def expected_telegram_webhook_url() -> str:
    return (PUBLIC_BASE_URL.rstrip("/") + TELEGRAM_WEBHOOK_PATH) if PUBLIC_BASE_URL else ""

def serialize_telegram_webhook_info(info, expected_url: str = "") -> dict:
    if not info:
        return {"ok": False, "reason": "not_available"}
    actual_url = getattr(info, "url", "") or ""
    return {
        "ok": True,
        "url": actual_url,
        "expected_url": expected_url or "",
        "matches_expected": bool(expected_url and actual_url == expected_url),
        "pending_update_count": int(getattr(info, "pending_update_count", 0) or 0),
        "last_error_date": str(getattr(info, "last_error_date", "") or ""),
        "last_error_message": getattr(info, "last_error_message", "") or "",
        "max_connections": getattr(info, "max_connections", None),
        "allowed_updates": getattr(info, "allowed_updates", None),
        "ip_address": getattr(info, "ip_address", "") or "",
    }

def telegram_update_ownership_diagnosis(info_payload: dict, active_update_mode: str = "") -> dict:
    actual_url = (info_payload or {}).get("url") or ""
    expected_url = (info_payload or {}).get("expected_url") or expected_telegram_webhook_url()
    mode = (active_update_mode or ACTIVE_TELEGRAM_UPDATE_MODE or TELEGRAM_UPDATE_MODE or "").lower()
    if mode == "webhook":
        if not expected_url:
            level = "SETUP_REQUIRED"
            message = "Thiếu PUBLIC_BASE_URL nên bot không có URL webhook để chiếm Telegram updates."
            next_action = "Set PUBLIC_BASE_URL=https://<railway-domain> và TELEGRAM_UPDATE_MODE=webhook trên Railway."
        elif not actual_url:
            level = "WEBHOOK_NOT_SET"
            message = "Telegram chưa có webhook. Nếu service cũ polling cùng token, nó vẫn có thể trả lời trước."
            next_action = "Redeploy Railway hoặc restart service để setWebhook; kiểm tra /runtime."
        elif actual_url != expected_url:
            level = "WEBHOOK_MISMATCH"
            message = "Telegram webhook đang trỏ sang URL khác, có thể deployment cũ/service khác đang giữ token."
            next_action = f"Restart đúng Railway service hoặc set webhook về {expected_url}; tắt service A_TOOLSX/cũ nếu còn chạy."
        else:
            level = "OWNED_BY_THIS_DEPLOY"
            message = "Telegram webhook đang trỏ đúng deployment TOAN AAS hiện tại."
            next_action = "/start hoặc /goal_audit"
    else:
        level = "POLLING_MODE"
        message = "Bot đang chạy polling; nếu có process cũ cùng token thì rất dễ tranh updates."
        next_action = "Ưu tiên set PUBLIC_BASE_URL và TELEGRAM_UPDATE_MODE=webhook trên Railway."
    return {
        "level": level,
        "message": message,
        "next_action": next_action,
        "mode": mode or "-",
        "actual_url": actual_url or "-",
        "expected_url": expected_url or "-",
        "pending_update_count": (info_payload or {}).get("pending_update_count", 0),
        "last_error_message": (info_payload or {}).get("last_error_message", ""),
    }

async def set_telegram_webhook_takeover(bot, drop_pending_updates: bool = True) -> dict:
    webhook_url = expected_telegram_webhook_url()
    if not webhook_url:
        return {
            "ok": False,
            "reason": "missing_public_base_url",
            "message": "Thiếu PUBLIC_BASE_URL hoặc fallback domain nên không thể setWebhook.",
            "expected_url": "",
        }
    webhook_kwargs = {
        "url": webhook_url,
        "allowed_updates": Update.ALL_TYPES,
        "drop_pending_updates": bool(drop_pending_updates),
    }
    if TELEGRAM_WEBHOOK_SECRET:
        webhook_kwargs["secret_token"] = TELEGRAM_WEBHOOK_SECRET
    await bot.set_webhook(**webhook_kwargs)
    info_payload = serialize_telegram_webhook_info(await bot.get_webhook_info(), webhook_url)
    ownership = telegram_update_ownership_diagnosis(info_payload, "webhook")
    return {
        "ok": bool(info_payload.get("matches_expected")),
        "webhook_url": webhook_url,
        "public_base_url_source": PUBLIC_BASE_URL_SOURCE or "",
        "drop_pending_updates": bool(drop_pending_updates),
        "telegram_webhook_info": info_payload,
        "telegram_ownership": ownership,
    }

async def telegram_webhook_watchdog():
    """Keep Telegram updates pinned to this Railway deployment if another process reclaims the token."""
    global ACTIVE_TELEGRAM_WEBHOOK_WATCHDOG, ACTIVE_TELEGRAM_WEBHOOK_URL
    if not tg_app or not PUBLIC_BASE_URL or TELEGRAM_TAKEOVER_INTERVAL_SECONDS <= 0:
        return
    ACTIVE_TELEGRAM_WEBHOOK_WATCHDOG = "running"
    notified_mismatch = False
    while True:
        try:
            await asyncio.sleep(TELEGRAM_TAKEOVER_INTERVAL_SECONDS)
            expected_url = expected_telegram_webhook_url()
            info_payload = serialize_telegram_webhook_info(await tg_app.bot.get_webhook_info(), expected_url)
            if info_payload.get("matches_expected"):
                ACTIVE_TELEGRAM_WEBHOOK_URL = expected_url
                notified_mismatch = False
                continue
            takeover = await set_telegram_webhook_takeover(tg_app.bot, drop_pending_updates=False)
            ACTIVE_TELEGRAM_WEBHOOK_URL = takeover.get("webhook_url") or expected_url
            logger.warning(
                "Telegram watchdog reclaimed webhook | old=%s | expected=%s | ok=%s",
                info_payload.get("url") or "-",
                expected_url or "-",
                takeover.get("ok"),
            )
            if ADMIN_ID and not notified_mismatch:
                notified_mismatch = True
                try:
                    await tg_app.bot.send_message(
                        chat_id=ADMIN_ID,
                        text=(
                            "🛡 <b>TOAN AAS WEBHOOK WATCHDOG</b>\n\n"
                            "Bot vừa tự kéo Telegram update về đúng Railway TOAN AAS.\n"
                            f"• Webhook cũ: <code>{html.escape(info_payload.get('url') or '-')}</code>\n"
                            f"• Webhook đúng: <code>{html.escape(expected_url or '-')}</code>\n"
                            f"• Kết quả: <code>{html.escape(str(takeover.get('ok')))}</code>\n"
                            "Nếu /start vẫn ra A_TOOLSX, còn một service khác đang dùng cùng TELEGRAM_TOKEN và liên tục giành lại."
                        ),
                        parse_mode="HTML",
                    )
                except Exception:
                    pass
        except asyncio.CancelledError:
            ACTIVE_TELEGRAM_WEBHOOK_WATCHDOG = "stopped"
            raise
        except Exception as e:
            ACTIVE_TELEGRAM_WEBHOOK_WATCHDOG = f"error: {e}"
            logger.warning(f"Telegram webhook watchdog error: {e}")

