def ai_memory_key(user_id, scope: str = "normal_chat") -> str:
    safe_scope = re.sub(r"[^A-Za-z0-9_.:-]+", "_", str(scope or "normal_chat"))[:48] or "normal_chat"
    return f"{safe_scope}:{str(user_id)}"

