def build_product_video_public_final_admission(
    project: dict,
    user_id: int,
    preflight: dict,
    scene_gate: dict,
) -> dict:
    project = dict(project or {})
    preflight = dict(preflight or {})
    scene_gate = dict(scene_gate or {})
    worker = product_video_worker_admission_status()
    asset_pack = _product_video_json_dict(project.get("asset_pack_json"))
    invoice = _product_video_json_dict(project.get("invoice_json"))
    route_contract = video_provider_router.product_video_route_contract(
        str(asset_pack.get("product_type") or invoice.get("product_type") or project.get("profile_id") or ""),
        str(asset_pack.get("engine_adapter") or invoice.get("engine_adapter") or ""),
        str(asset_pack.get("orchestration_mode") or invoice.get("orchestration_mode") or ""),
        explicit_local_renderer=bool(asset_pack.get("explicit_local_renderer") or invoice.get("explicit_local_renderer")),
    )
    candidates = [
        str(item or "").strip()
        for item in (
            scene_gate.get("eligible_provider_keys")
            or scene_gate.get("runtime_candidate_keys")
            or preflight.get("effective_provider_chain")
            or []
        )
        if str(item or "").strip()
    ]
    diagnostics = dict(PRODUCT_VIDEO_CONFIRM_HANDLER_DIAGNOSTICS or {})
    handler_ok = bool(
        diagnostics.get("product_video_confirm_handler_count") == 1
        and not diagnostics.get("duplicate_confirm_handler_detected")
        and not diagnostics.get("duplicate_callback_pattern_detected")
    )
    route_ok = bool(route_contract.get("route_requires_provider"))
    worker_ok = bool(worker.get("worker_version_compatible"))
    worker_connected = bool(worker.get("worker_connected"))
    worker_heartbeat_fresh = bool(worker.get("heartbeat_fresh"))
    worker_lease_valid = bool(worker.get("lease_valid"))
    worker_sha_match = bool(worker.get("sha_match"))
    worker_capability_match = bool(worker.get("capability_match"))
    worker_identity_conflict = bool(worker.get("worker_identity_conflict"))
    gate_ok = bool(preflight.get("ok") and scene_gate.get("ok"))
    freeze_truth = dict(
        scene_gate.get("freeze_truth")
        or preflight.get("freeze_truth")
        or {}
    )
    freeze_ok = bool(freeze_truth.get("public_final_confirm_allowed", True))
    admission_mode = str(
        scene_gate.get("admission_mode")
        or preflight.get("admission_mode")
        or "healthy"
    ).strip()
    probation_candidate_key = str(
        scene_gate.get("probation_candidate_selected")
        or preflight.get("probation_candidate_selected")
        or (candidates[0] if admission_mode == video_project_queue.PRODUCT_VIDEO_PROBATION_ADMISSION_MODE and candidates else "")
    ).strip()
    probation_reason = str(scene_gate.get("probation_reason") or preflight.get("probation_reason") or "").strip()
    probation_lock_clear = bool(scene_gate.get("probation_lock_clear", preflight.get("probation_lock_clear")))
    allowed = bool(
        candidates
        and gate_ok
        and worker_ok
        and worker_connected
        and worker_heartbeat_fresh
        and worker_lease_valid
        and worker_sha_match
        and worker_capability_match
        and not worker_identity_conflict
        and route_ok
        and handler_ok
        and freeze_ok
    )
    snapshot_id = f"pv-admission-{int(project.get('project_id') or 0)}-{uuid.uuid4().hex}"
    checked_at = now_text()
    quote_fingerprint = video_project_queue.product_video_admission_quote_fingerprint(project, int(user_id))
    if not freeze_ok:
        block_reason = str(
            freeze_truth.get("blocker_code")
            or freeze_truth.get("public_blocker_code")
            or "product_video_public_freeze_active"
        )
    elif not candidates:
        block_reason = "no_eligible_product_video_provider"
    elif not handler_ok:
        block_reason = "duplicate_product_video_confirm_handler"
    elif not worker_ok:
        block_reason = str(worker.get("worker_admission_block_reason") or "worker_version_incompatible")
    elif not route_ok:
        block_reason = "product_video_route_contract_mismatch"
    elif not gate_ok:
        block_reason = str(scene_gate.get("blocker") or preflight.get("blocker") or "product_video_admission_blocked")
    else:
        block_reason = ""
    snapshot = {
        **dict(scene_gate.get("provider_eligibility_snapshot") or {}),
        "provider_eligibility_snapshot_id": snapshot_id,
        "admission_snapshot_id": snapshot_id,
        "admission_checked_at": checked_at,
        "admission_user_id": int(user_id),
        "admission_project_id": int(project.get("project_id") or 0),
        "admission_quote_fingerprint": quote_fingerprint,
        "admission_callback_handler_id": video_project_queue.PRODUCT_VIDEO_PUBLIC_CONFIRM_HANDLER_ID,
        "admission_callback_data": video_project_queue.PRODUCT_VIDEO_PUBLIC_CONFIRM_CALLBACK,
        "eligible_provider_keys": candidates,
        "runtime_candidate_keys": candidates,
        "final_eligible_provider_count": len(candidates),
    }
    admission = {
        **preflight,
        **scene_gate,
        **route_contract,
        "ok": allowed,
        "provider_eligibility_snapshot": snapshot,
        "provider_eligibility_snapshot_id": snapshot_id,
        "admission_snapshot_id": snapshot_id,
        "admission_checked_at": checked_at,
        "admission_ttl_seconds": max(5, min(300, safe_int(os.getenv("PRODUCT_VIDEO_ADMISSION_TTL_SECONDS"), 60))),
        "admission_candidate_keys": candidates,
        "admission_candidate_count": len(candidates),
        "admission_result": "PASS" if allowed else "BLOCKED",
        "admission_block_reason": block_reason,
        "admission_user_id": int(user_id),
        "admission_project_id": int(project.get("project_id") or 0),
        "admission_quote_fingerprint": quote_fingerprint,
        "admission_callback_handler_id": video_project_queue.PRODUCT_VIDEO_PUBLIC_CONFIRM_HANDLER_ID,
        "admission_callback_data": video_project_queue.PRODUCT_VIDEO_PUBLIC_CONFIRM_CALLBACK,
        "admission_worker_runtime_sha": str(worker.get("runtime_sha") or ""),
        "admission_worker_sha": str(worker.get("worker_sha") or ""),
        "admission_worker_version_compatible": worker_ok,
        "admission_route_requires_provider": route_ok,
        "admission_provider_health_gate_pass": gate_ok,
        "product_video_freeze_truth": freeze_truth,
        "public_provider_freeze": bool(freeze_truth.get("public_provider_freeze")),
        "hidden_submit_freeze": bool(freeze_truth.get("hidden_submit_freeze")),
        "background_submit_freeze": bool(freeze_truth.get("background_submit_freeze")),
        "smoke_freeze": bool(freeze_truth.get("smoke_freeze")),
        "public_live_provider_allowed": bool(freeze_truth.get("public_live_allowed", True)),
        "freeze_blocker_code": str(freeze_truth.get("blocker_code") or ""),
        "freeze_blocker_source": str(freeze_truth.get("blocker_source") or ""),
        "admission_mode": admission_mode,
        "probation_candidate_key": probation_candidate_key,
        "probation_reason": probation_reason,
        "probation_lock_clear": probation_lock_clear,
        "submit_source": "public_user_final_confirm",
        "public_user_confirmed": True,
        "worker_generation_id": str(worker.get("generation_id") or worker.get("authoritative_worker_generation_id") or ""),
        "worker_git_sha": str(worker.get("git_sha") or worker.get("worker_sha") or ""),
        "runtime_sha": str(worker.get("runtime_sha") or ""),
        "worker_compatible": worker_ok,
        "worker_connected": worker_connected,
        "worker_heartbeat_fresh": worker_heartbeat_fresh,
        "worker_lease_valid": worker_lease_valid,
        "worker_sha_match": worker_sha_match,
        "worker_capability_match": worker_capability_match,
        "worker_identity_conflict": worker_identity_conflict,
        "route_requires_provider": route_ok,
        "handler_id": video_project_queue.PRODUCT_VIDEO_PUBLIC_CONFIRM_HANDLER_ID,
        "worker_heartbeat_age": worker.get("worker_heartbeat_age"),
        "worker_capability_version": str(worker.get("worker_capability_version") or ""),
        "worker_admission_block_reason": str(worker.get("worker_admission_block_reason") or ""),
        "duplicate_confirm_handler_detected": bool(diagnostics.get("duplicate_confirm_handler_detected")),
    }
    return video_project_queue.sign_product_video_final_admission_context(admission)


def confirm_video_project_invoice(
    project_id: int,
    user_id,
    *,
    balance_xu=None,
    use_wallet: bool = True,
    deduct_func=None,
    provider_admission: dict | None = None,
    require_provider_admission: bool = False,
    conn=None,
) -> dict:
    owned = conn is None
    db = conn or db_connect()
    try:
        def _deduct(uid: int, amount: int):
            if deduct_func is not None:
                return deduct_func(uid, amount)
            if not use_wallet:
                return {"ok": True, "final_cost": int(amount or 0)}
            return spend_fixed_credit_info(
                uid,
                int(amount or 0),
                "video_project_confirm",
                f"Video project #{int(project_id)} queued for worker",
                apply_member_discount_flag=False,
            )

        final_admission = dict(provider_admission or {})
        if require_provider_admission:
            if not final_admission:
                return {
                    "ok": False,
                    "reason": "admission_context_missing_or_invalid",
                    "public_message": "TOAN AAS chưa thể bắt đầu tạo video lúc này.\nHệ thống chưa trừ Xu.\nAnh/chị vui lòng thử lại sau.",
                    "job_created": False,
                    "scene_records_created": False,
                    "dispatch_outbox_created": False,
                    "charge": 0,
                    "charged_xu": 0,
                }
            return video_project_queue.confirm_public_product_video_invoice(
                db,
                project_id=int(project_id),
                user_id=int(user_id),
                balance_xu=balance_xu,
                provider_admission=final_admission,
            )
        return video_project_queue.confirm_video_project_invoice(
            db,
            project_id=int(project_id),
            user_id=int(user_id),
            balance_xu=balance_xu,
            deduct_func=_deduct,
            provider_admission=final_admission,
            require_provider_admission=bool(require_provider_admission),
        )
    finally:
        if owned:
            db.close()

def claim_video_project_job(worker_id: str, *, lease_seconds: int = 600, conn=None) -> dict:
    owned = conn is None
    db = conn or db_connect()
    try:
        job = video_project_queue.claim_next_video_job(db, worker_id=worker_id, lease_seconds=lease_seconds)
        return video_project_queue.hydrate_video_job_payload(db, job) if job else {}
    finally:
        if owned:
            db.close()

def update_video_project_job_result(job_id: int, status: str, *, final_video_path: str = "", final_video_file_id: str = "", error: str = "", result: dict | None = None, conn=None) -> dict:
    owned = conn is None
    db = conn or db_connect()
    try:
        clean_status = str(status or "").lower()
        if clean_status == "completed":
            return video_project_queue.complete_video_job(
                db,
                job_id=int(job_id),
                final_video_path=final_video_path,
                final_video_file_id=final_video_file_id,
                result=result,
            )
        if clean_status == "failed":
            return video_project_queue.fail_video_job(db, job_id=int(job_id), error=error or "video_worker_failed")
        raise ValueError("unsupported_video_job_status")
    finally:
        if owned:
            db.close()

SENSITIVE_AUDIT_KEYS = ("key", "token", "secret", "password", "authorization", "api")

def _safe_audit_value(value):
    if isinstance(value, dict):
        safe = {}
        for key, item in value.items():
            if any(marker in str(key).lower() for marker in SENSITIVE_AUDIT_KEYS):
                safe[key] = "***"
            else:
                safe[key] = _safe_audit_value(item)
        return safe
    if isinstance(value, list):
        return [_safe_audit_value(item) for item in value]
    return value

def _audit_json(value):
    if value is None:
        return ""
    try:
        return json.dumps(_safe_audit_value(value), ensure_ascii=False, default=str)
    except Exception:
        return str(value)

def record_audit(conn, actor_id, actor_type, action, object_type="", object_id="", before=None, after=None, note=""):
    try:
        c = conn.cursor()
        c.execute(
            """INSERT INTO audit_logs
            (actor_id, actor_type, action, object_type, object_id, before_json, after_json, note, created_at)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (
                str(actor_id or ""),
                str(actor_type or ""),
                str(action or ""),
                str(object_type or ""),
                str(object_id or ""),
                _audit_json(before),
                _audit_json(after),
                str(note or "")[:1200],
                now_text(),
            )
        )
    except Exception as e:
        logger.warning(f"Audit log write failed: {e}")

def record_audit_event(actor_id, actor_type, action, object_type="", object_id="", before=None, after=None, note=""):
    conn = None
    try:
        conn = db_connect()
        record_audit(conn, actor_id, actor_type, action, object_type, object_id, before, after, note)
        conn.commit()
    except Exception as e:
        logger.warning(f"Audit event write failed: {e}")
    finally:
        if conn:
            conn.close()

def get_system_setting(key, default=""):
    conn = None
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute("SELECT value FROM system_settings WHERE key=?", (str(key),))
        row = c.fetchone()
        return row[0] if row else default
    except sqlite3.OperationalError as e:
        if "no such table: system_settings" not in str(e).lower():
            logger.warning(f"System setting read failed: {e}")
        return default
    except Exception as e:
        logger.warning(f"System setting read failed: {e}")
        return default
    finally:
        if conn:
            conn.close()

def get_system_settings(keys: list[str]) -> dict:
    return {key: get_system_setting(key, "") for key in keys}

def set_system_setting(key, value, note="", updated_by=""):
    conn = None
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            """INSERT OR REPLACE INTO system_settings
            (key, value, note, updated_at, updated_by)
            VALUES (?,?,?,?,?)""",
            (str(key), str(value or ""), str(note or "")[:1200], now_text(), str(updated_by or "")),
        )
        conn.commit()
    except Exception as e:
        logger.warning(f"System setting write failed: {e}")
        raise
    finally:
        if conn:
            conn.close()


CSKH_SESSION_WINDOW_SETTING = "cskh_session_window_hours"
CSKH_TURN_RETENTION_SETTING = "cskh_turn_retention_days"
CSKH_RECENT_TURN_LIMIT_SETTING = "cskh_recent_turn_limit"
CSKH_CONTEXT_CHARACTER_BUDGET_SETTING = "cskh_context_character_budget"
CSKH_CLOSING_NOTICE_DELAY_SECONDS = 5 * 60
CSKH_TURN_PURGE_INTERVAL_SECONDS = 60 * 60
CSKH_CLOSING_NOTICE_TASKS: dict[str, asyncio.Task] = {}
CSKH_LAST_SESSION_PURGE_AT = 0.0
CSKH_ALLOWED_CONTEXT_EVENTS = {
    "product_video": "Khách đang xem dịch vụ tạo video",
    "image_ai": "Khách đang xem dịch vụ tạo ảnh",
    "subdub": "Khách đang xem phụ đề và lồng tiếng",
    "voice": "Khách đang xem dịch vụ giọng đọc",
    "music": "Khách đang xem dịch vụ nhạc",
}
CSKH_ALLOWED_CONTEXT_EVENT_TEXTS = frozenset(CSKH_ALLOWED_CONTEXT_EVENTS.values())


def cskh_runtime_setting_int(key, default, *, minimum=1, maximum=100_000):
    """Read a bounded CSKH runtime setting without writing configuration."""
    raw = get_system_setting(str(key), "")
    try:
        value = int(str(raw).strip())
    except (TypeError, ValueError):
        value = int(default)
    return max(int(minimum), min(int(maximum), value))


def cskh_session_settings() -> dict:
    return {
        "session_window_hours": cskh_runtime_setting_int(
            CSKH_SESSION_WINDOW_SETTING,
            cskh_session_memory.DEFAULT_SESSION_WINDOW_HOURS,
            minimum=1,
            maximum=24 * 31,
        ),
        "retention_days": cskh_runtime_setting_int(
            CSKH_TURN_RETENTION_SETTING,
            cskh_session_memory.DEFAULT_RETENTION_DAYS,
            minimum=1,
            maximum=3650,
        ),
        "recent_turn_limit": cskh_runtime_setting_int(
            CSKH_RECENT_TURN_LIMIT_SETTING,
            cskh_session_memory.DEFAULT_RECENT_TURN_LIMIT,
            minimum=1,
            maximum=100,
        ),
        "character_budget": cskh_runtime_setting_int(
            CSKH_CONTEXT_CHARACTER_BUDGET_SETTING,
            cskh_session_memory.DEFAULT_CHARACTER_BUDGET,
            minimum=200,
            maximum=40_000,
        ),
    }


def cskh_closing_notice_text(window_hours: int | None = None) -> str:
    hours = int(window_hours or cskh_session_settings()["session_window_hours"])
    return cskh_session_memory.closing_notice_text(hours)


def cskh_shared_context(owner_id, chat_id, *, now=None, conn=None) -> dict:
    """Read the active sanitized context, degrading safely on storage failure."""
    owned_conn = conn is None
    connection = conn
    try:
        connection = connection or db_connect()
        settings = cskh_session_settings()
        return cskh_session_memory.load_recent_session(
            connection,
            owner_id=str(owner_id or ""),
            chat_id=str(chat_id or ""),
            now=time.time() if now is None else now,
            session_window_hours=settings["session_window_hours"],
            recent_turn_limit=settings["recent_turn_limit"],
            character_budget=settings["character_budget"],
        )
    except Exception as exc:
        logger.warning("cskh shared context unavailable | error=%s", type(exc).__name__)
        return {"session_id": "", "turns": [], "history_text": "", "truncated": False, "active": False}
    finally:
        if owned_conn and connection:
            connection.close()


def cskh_maybe_purge_session_turns(*, now=None, conn=None) -> int:
    """Run the indexed retention purge at most once per process-hour."""
    global CSKH_LAST_SESSION_PURGE_AT
    timestamp = float(time.time() if now is None else now)
    if timestamp - CSKH_LAST_SESSION_PURGE_AT < CSKH_TURN_PURGE_INTERVAL_SECONDS:
        return 0
    owned_conn = conn is None
    connection = conn
    try:
        connection = connection or db_connect()
        count = cskh_session_memory.purge_expired_turns(
            connection,
            now=timestamp,
            retention_days=cskh_session_settings()["retention_days"],
        )
        connection.commit()
        CSKH_LAST_SESSION_PURGE_AT = timestamp
        return count
    except Exception as exc:
        logger.warning("cskh session purge skipped | error=%s", type(exc).__name__)
        return 0
    finally:
        if owned_conn and connection:
            connection.close()


def cskh_safe_customer_context_text(value) -> str:
    """Reject machine-only callback, route, and debug payloads from CSKH history."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    if re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]*(?:\|[A-Za-z0-9_:-]+){1,5}", raw):
        return ""
    machine_field = r"(?:callback_data|callback|route|provider|task_id|job_id|traceback|debug|raw_payload)"
    if re.search(rf"[\"']?{machine_field}[\"']?\s*[:=]", raw, flags=re.IGNORECASE):
        return ""
    return raw


def cskh_allowed_context_event(value) -> str:
    text = str(value or "").strip()
    return text if text in CSKH_ALLOWED_CONTEXT_EVENT_TEXTS else ""


def cskh_record_exchange(
    *,
    owner_id,
    chat_id,
    surface,
    user_content="",
    assistant_content="",
    assistant_delivery_confirmed=False,
    source_message_id="",
    context_event="",
    now=None,
    conn=None,
) -> dict:
    """Persist customer input and only an assistant reply confirmed as delivered.

    Callers record the customer message before classification.  They must call
    again with ``assistant_delivery_confirmed=True`` only after Telegram has
    acknowledged the actual reply; this helper never treats draft copy as a
    sent response.
    """
    timestamp = float(time.time() if now is None else now)
    source = str(source_message_id or "").strip()
    if not source:
        return {"session_id": "", "user_inserted": False, "assistant_inserted": False}
    owned_conn = conn is None
    connection = conn
    try:
        connection = connection or db_connect()
        settings = cskh_session_settings()
        user_turn = None
        assistant_turn = None
        safe_user_content = cskh_safe_customer_context_text(user_content)
        if safe_user_content:
            user_turn = cskh_session_memory.record_turn(
                connection,
                owner_id=owner_id,
                chat_id=chat_id,
                surface=surface,
                role="user",
                content=safe_user_content,
                source_message_id=source,
                now=timestamp,
                session_window_hours=settings["session_window_hours"],
            )
        session_id = str(user_turn.session_id if user_turn else cskh_shared_context(owner_id, chat_id, now=timestamp, conn=connection).get("session_id") or "")
        if str(assistant_content or "").strip() and assistant_delivery_confirmed is True and session_id:
            assistant_turn = cskh_session_memory.record_turn(
                connection,
                owner_id=owner_id,
                chat_id=chat_id,
                surface=surface,
                role="assistant",
                content=assistant_content,
                source_message_id=f"reply:{source}",
                now=timestamp,
                session_window_hours=settings["session_window_hours"],
                session_id=session_id,
            )
        safe_context_event = cskh_allowed_context_event(context_event)
        if safe_context_event and session_id:
            cskh_session_memory.record_turn(
                connection,
                owner_id=owner_id,
                chat_id=chat_id,
                surface=surface,
                role="context_event",
                content=safe_context_event,
                source_message_id=f"context:{source}",
                now=timestamp,
                session_window_hours=settings["session_window_hours"],
                session_id=session_id,
            )
        connection.commit()
        cskh_maybe_purge_session_turns(now=timestamp, conn=connection)
        return {
            "session_id": session_id,
            "user_inserted": bool(user_turn and user_turn.inserted),
            "assistant_inserted": bool(assistant_turn and assistant_turn.inserted),
        }
    except Exception as exc:
        logger.warning("cskh exchange persistence skipped | error=%s", type(exc).__name__)
        return {"session_id": "", "user_inserted": False, "assistant_inserted": False}
    finally:
        if owned_conn and connection:
            connection.close()


def cskh_record_customer_turn(
    *,
    owner_id,
    chat_id,
    surface,
    user_content,
    source_message_id,
    context_event="",
    now=None,
    conn=None,
) -> dict:
    """Persist only the inbound customer turn before any reply is attempted."""
    return cskh_record_exchange(
        owner_id=owner_id,
        chat_id=chat_id,
        surface=surface,
        user_content=user_content,
        source_message_id=source_message_id,
        context_event=context_event,
        now=now,
        conn=conn,
    )


def cskh_record_delivered_assistant_turn(
    *,
    owner_id,
    chat_id,
    surface,
    assistant_content,
    source_message_id,
    context_event="",
    now=None,
    conn=None,
) -> dict:
    """Persist an assistant turn only after its Telegram send has succeeded."""
    return cskh_record_exchange(
        owner_id=owner_id,
        chat_id=chat_id,
        surface=surface,
        assistant_content=assistant_content,
        assistant_delivery_confirmed=True,
        source_message_id=source_message_id,
        context_event=context_event,
        now=now,
        conn=conn,
    )


async def cskh_deliver_closing_notice_if_current(
    *,
    owner_id,
    chat_id,
    session_id,
    source_message_id,
    surface,
    send_notice,
    opt_out=False,
    conn=None,
    now=None,
) -> bool:
    """Send one closing note only after a durable cross-surface claim.

    The claim is committed before transport.  Known transport failures release
    it; once a transport is explicitly confirmed, a completion failure retains
    the claim rather than risking a duplicate customer-visible message.
    """
    timestamp = float(time.time() if now is None else now)
    owned_conn = conn is None
    connection = conn
    claimed = False
    delivery_confirmed = False
    try:
        connection = connection or db_connect()
        context = cskh_shared_context(owner_id, chat_id, now=timestamp, conn=connection)
        if str(context.get("session_id") or "") != str(session_id or ""):
            return False
        if not cskh_session_memory.closing_notice_needed(
            connection,
            owner_id=owner_id,
            chat_id=chat_id,
            session_id=session_id,
            source_message_id=source_message_id,
            now=timestamp,
            opt_out=opt_out,
        ):
            return False
        claimed = cskh_session_memory.claim_closing_notice(
            connection,
            owner_id=owner_id,
            chat_id=chat_id,
            session_id=session_id,
            source_message_id=source_message_id,
            surface=surface,
            now=timestamp,
            opt_out=opt_out,
        )
        if not claimed:
            return False
        connection.commit()
        notice = cskh_closing_notice_text(cskh_session_settings()["session_window_hours"])
        sent = send_notice(notice)
        if inspect.isawaitable(sent):
            sent = await sent
        delivery_confirmed = cskh_session_memory.notice_delivery_confirmed(sent)
        if not delivery_confirmed:
            cskh_session_memory.release_closing_notice_claim(
                connection,
                owner_id=owner_id,
                chat_id=chat_id,
                session_id=session_id,
            )
            connection.commit()
            return False
        completed = cskh_session_memory.complete_closing_notice_claim(
            connection,
            owner_id=owner_id,
            chat_id=chat_id,
            surface=surface,
            content=notice,
            confirmed_success=True,
            now=timestamp,
            session_id=session_id,
        )
        connection.commit()
        return bool(completed)
    except asyncio.CancelledError:
        if claimed and not delivery_confirmed and connection:
            cskh_session_memory.release_closing_notice_claim(
                connection,
                owner_id=owner_id,
                chat_id=chat_id,
                session_id=session_id,
            )
            connection.commit()
        raise
    except Exception as exc:
        if claimed and not delivery_confirmed and connection:
            try:
                cskh_session_memory.release_closing_notice_claim(
                    connection,
                    owner_id=owner_id,
                    chat_id=chat_id,
                    session_id=session_id,
                )
                connection.commit()
            except Exception:
                pass
        logger.warning("cskh closing notice skipped | error=%s", type(exc).__name__)
        return False
    finally:
        if owned_conn and connection:
            connection.close()


def cskh_schedule_closing_notice(
    *,
    owner_id,
    chat_id,
    session_id,
    source_message_id,
    surface,
    send_notice,
    opt_out=False,
    delay_seconds=CSKH_CLOSING_NOTICE_DELAY_SECONDS,
) -> None:
    """Replace an older idle timer for the same customer/chat with the latest one."""
    owner = str(owner_id or "").strip()
    chat = str(chat_id or "").strip()
    if not owner or not chat or not str(session_id or "").strip() or not str(source_message_id or "").strip():
        return
    key = f"{owner}:{chat}"
    previous = CSKH_CLOSING_NOTICE_TASKS.pop(key, None)
    if previous and not previous.done():
        previous.cancel()

    async def runner():
        try:
            await asyncio.sleep(max(0, float(delay_seconds)))
            await cskh_deliver_closing_notice_if_current(
                owner_id=owner,
                chat_id=chat,
                session_id=session_id,
                source_message_id=source_message_id,
                surface=surface,
                send_notice=send_notice,
                opt_out=opt_out,
            )
        except asyncio.CancelledError:
            raise
        finally:
            current = CSKH_CLOSING_NOTICE_TASKS.get(key)
            if current is asyncio.current_task():
                CSKH_CLOSING_NOTICE_TASKS.pop(key, None)

    try:
        CSKH_CLOSING_NOTICE_TASKS[key] = asyncio.create_task(runner())
    except RuntimeError:
        logger.warning("cskh closing notice schedule skipped: no running loop")


def cskh_safe_telegram_id(value, *, allow_negative=False) -> str:
    raw = str(value or "").strip()
    pattern = r"-?[1-9]\d{0,19}" if allow_negative else r"[1-9]\d{0,19}"
    return raw if re.fullmatch(pattern, raw) else ""


def cskh_safe_message_reference(value) -> str:
    return cskh_safe_telegram_id(value)


def cskh_transport_delivery_confirmed(value) -> bool:
    """Use the same strict acknowledgement rule for replies and idle notes."""
    return cskh_session_memory.notice_delivery_confirmed(value)


def cskh_context_event_for_classification(classification: dict | None) -> str:
    payload = classification or {}
    product = str(payload.get("primary_product") or payload.get("product") or "").strip()
    return CSKH_ALLOWED_CONTEXT_EVENTS.get(product, "")


def cskh_finalize_delivered_reply(
    *,
    owner_id,
    chat_id,
    surface,
    source_message_id,
    assistant_content,
    inbound_turn=None,
    classification=None,
    send_notice=None,
) -> dict:
    """Persist a real reply and arm the five-minute note only after delivery."""
    source = cskh_safe_message_reference(source_message_id)
    if not source:
        return {"session_id": "", "assistant_inserted": False}
    delivered = cskh_record_delivered_assistant_turn(
        owner_id=owner_id,
        chat_id=chat_id,
        surface=surface,
        assistant_content=assistant_content,
        source_message_id=source,
        context_event=cskh_context_event_for_classification(classification),
    )
    session_id = str((delivered or {}).get("session_id") or (inbound_turn or {}).get("session_id") or "")
    if session_id and callable(send_notice):
        cskh_schedule_closing_notice(
            owner_id=owner_id,
            chat_id=chat_id,
            session_id=session_id,
            source_message_id=source,
            surface=surface,
            send_notice=send_notice,
        )
    return delivered


