def _engine_async_job_key(internal_job_id: str) -> str:
    safe_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(internal_job_id or ""))[:80]
    return ENGINE_ASYNC_JOB_PREFIX + safe_id

def _engine_async_feature_key(feature: str) -> str:
    safe_feature = re.sub(r"[^A-Za-z0-9_.:-]", "", str(feature or ""))[:80]
    return f"{ENGINE_ASYNC_JOB_PREFIX}feature:{safe_feature}"

def _engine_async_user_key(user_id, feature: str = "") -> str:
    safe_user = re.sub(r"[^A-Za-z0-9_.:-]", "", str(user_id or ""))[:80]
    safe_feature = re.sub(r"[^A-Za-z0-9_.:-]", "", str(feature or ""))[:80]
    return f"{ENGINE_ASYNC_JOB_PREFIX}user:{safe_user}:{safe_feature}" if safe_feature else f"{ENGINE_ASYNC_JOB_PREFIX}user:{safe_user}"

def _engine_async_id_list_from_setting(key: str) -> list[str]:
    raw = get_system_setting(key, "")
    if not raw and key in ENGINE_ASYNC_MEMORY_INDEX:
        return list(ENGINE_ASYNC_MEMORY_INDEX.get(key) or [])
    try:
        value = json.loads(raw or "[]")
        ids = value if isinstance(value, list) else []
    except Exception:
        ids = []
    clean: list[str] = []
    seen = set()
    for item in ids:
        safe = re.sub(r"[^A-Za-z0-9_.:-]", "", str(item or ""))[:80]
        if safe and safe not in seen:
            clean.append(safe)
            seen.add(safe)
    return clean

def _engine_async_memory_save_id_list(key: str, internal_job_id: str) -> None:
    safe_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(internal_job_id or ""))[:80]
    if not safe_id:
        return
    ids = [safe_id]
    for item in ENGINE_ASYNC_MEMORY_INDEX.get(key, []):
        if item != safe_id:
            ids.append(item)
        if len(ids) >= ENGINE_ASYNC_JOB_MAX_INDEX:
            break
    ENGINE_ASYNC_MEMORY_INDEX[key] = ids

def _engine_async_save_id_list(key: str, internal_job_id: str, updated_by="") -> None:
    safe_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(internal_job_id or ""))[:80]
    if not safe_id:
        return
    ids = [safe_id]
    for item in _engine_async_id_list_from_setting(key):
        if item != safe_id:
            ids.append(item)
        if len(ids) >= ENGINE_ASYNC_JOB_MAX_INDEX:
            break
    set_system_setting(key, json.dumps(ids, separators=(",", ":")), "engine async job index", updated_by)

def mask_provider_task_id(value: str, visible: int = 4) -> str:
    text = str(value or "").strip()
    if not text:
        return "-"
    keep = max(2, int(visible or 4))
    if len(text) <= keep * 2:
        return text[:2] + "***" if len(text) > 2 else "***"
    return f"{text[:keep]}***{text[-keep:]}"

def sanitize_provider_status_text(value, provider_task_id: str = "", limit: int = 260) -> str:
    text = sanitize_log_text(str(value or ""))
    raw_task = str(provider_task_id or "").strip()
    if raw_task:
        text = text.replace(raw_task, mask_provider_task_id(raw_task))
    text = re.sub(r"https?://\S+", "[url]", text)
    text = re.sub(r"(?i)(bearer\s+)[A-Za-z0-9._:-]+", r"\1***", text)
    text = re.sub(r"(?i)(api[_-]?key|token|secret)=?[A-Za-z0-9._:-]+", r"\1=***", text)
    return text[: max(20, int(limit or 260))]

def canonical_music_job_id(raw: str = "") -> str:
    return product_progress_status.canonical_music_job_id(raw)


def legacy_music_job_id(raw: str = "") -> str:
    canonical = canonical_music_job_id(raw)
    if not canonical:
        return ""
    return f"MUS-{canonical[3:]}"


def normalized_music_job_input(raw: str = "") -> str:
    value = str(raw or "").strip().upper()
    if value.startswith("#"):
        value = value[1:].strip()
    return re.sub(r"[^A-Z0-9-]+", "", value)


def music_job_lookup_aliases(raw: str = "") -> list[str]:
    raw_clean = str(raw or "").strip()
    if raw_clean.startswith("#"):
        raw_clean = raw_clean[1:].strip()
    normalized = normalized_music_job_input(raw)
    canonical = canonical_music_job_id(normalized or raw)
    legacy = legacy_music_job_id(canonical or normalized or raw)
    aliases: list[str] = []
    for candidate in (raw_clean, normalized, legacy, canonical):
        if candidate and candidate not in aliases:
            aliases.append(candidate)
    return aliases


def music_job_lookup_identity(raw: str = "", resolved_job_id: str = "", lookup_found: bool = False) -> dict:
    input_job_id = str(raw or "").strip()
    normalized = normalized_music_job_input(input_job_id)
    canonical = canonical_music_job_id(normalized or input_job_id)
    legacy = legacy_music_job_id(canonical or normalized or input_job_id)
    return {
        "input_job_id": input_job_id,
        "normalized_no_hash": normalized,
        "canonical_job_id": canonical,
        "legacy_job_id": legacy,
        "resolved_job_id": str(resolved_job_id or ""),
        "lookup_found": bool(lookup_found),
    }


def music_public_display_job_id(raw: str = "") -> str:
    normalized = canonical_music_job_id(raw)
    return f"#{normalized}" if normalized else product_progress_status.product_progress_public_job_code(raw)


def engine_async_job_id(feature: str, user_id="") -> str:
    feature_key = str(feature or "").strip().lower()
    prefix = ENGINE_ASYNC_JOB_FEATURE_PREFIX.get(feature_key, "JOB")
    nonce = hashlib.sha256(f"{feature_key}:{user_id}:{time.time_ns()}:{random.random()}".encode("utf-8")).hexdigest()[:8].upper()
    if prefix == "MUS":
        return f"{prefix}{nonce}"
    return f"{prefix}-{nonce}"

def normalize_engine_async_job(job: dict) -> dict:
    current = dict(job or {})
    feature = str(current.get("feature") or "").strip().lower()
    current["feature"] = feature
    current["internal_job_id"] = str(current.get("internal_job_id") or engine_async_job_id(feature, current.get("user_id"))).strip()
    if feature == "music_suno":
        current["internal_job_id"] = canonical_music_job_id(current.get("internal_job_id")) or engine_async_job_id(feature, current.get("user_id"))
    provider_task_id = str(current.get("provider_task_id") or current.get("provider_job_id") or "").strip()
    output_bytes = int(current.get("output_bytes") or 0)
    status = str(current.get("status") or ("completed" if output_bytes > 0 else "submitted")).strip().lower()
    music_pending_submit_without_provider = (
        feature == "music_suno"
        and status in {"pending_submit", "submitting"}
        and str(current.get("confirm_submit_phase") or "").strip()
    )
    failed_terminal_without_provider = (
        status in {"failed", "failed_no_charge", "failed_refunded", "needs_admin_review"}
        or any(token in status for token in ("fail", "error", "cancel"))
    )
    if not provider_task_id and output_bytes <= 0 and not failed_terminal_without_provider and not music_pending_submit_without_provider:
        raise ValueError("engine async job requires provider_task_id or output_bytes")
    now = now_text()
    current.setdefault("created_at", now)
    current["updated_at"] = now
    current["provider_task_id"] = provider_task_id
    current["provider_job_id"] = provider_task_id
    current["status"] = status
    current["provider"] = str(current.get("provider") or "").strip()
    current["progress_text"] = sanitize_provider_status_text(current.get("progress_text") or "", provider_task_id, 360)
    current["last_provider_status"] = sanitize_provider_status_text(current.get("last_provider_status") or "", provider_task_id, 360)
    current["error_category"] = sanitize_provider_status_text(current.get("error_category") or "", provider_task_id, 120)
    current["output_path"] = str(current.get("output_path") or "")[:600]
    current["output_bytes"] = output_bytes
    current["poll_count"] = int(current.get("poll_count") or 0)
    current.setdefault("last_poll_at", "")
    current.setdefault("next_poll_after", "")
    current.setdefault("parsed_fields", {})
    current.setdefault("expire_at", "")
    if feature == "music_suno" and str(current.get("terminal_state") or current.get("music_terminal_state") or "").strip().lower() == "failed_no_charge":
        current = ensure_music_failed_no_charge_metadata(current)
    return current

def save_engine_async_job(job: dict) -> dict:
    current = normalize_engine_async_job(job)
    internal_id = str(current.get("internal_job_id") or "")
    updated_by = str(current.get("user_id") or "")
    try:
        set_system_setting(
            _engine_async_job_key(internal_id),
            json.dumps(current, ensure_ascii=False, separators=(",", ":")),
            f"engine async job {current.get('feature')} status={current.get('status')}",
            updated_by,
        )
        _engine_async_save_id_list(ENGINE_ASYNC_JOB_INDEX_KEY, internal_id, updated_by)
        _engine_async_save_id_list(_engine_async_feature_key(current.get("feature")), internal_id, updated_by)
        if current.get("user_id"):
            _engine_async_save_id_list(_engine_async_user_key(current.get("user_id")), internal_id, updated_by)
            _engine_async_save_id_list(_engine_async_user_key(current.get("user_id"), current.get("feature")), internal_id, updated_by)
    except sqlite3.OperationalError as exc:
        if "no such table: system_settings" not in str(exc).lower():
            raise
        ENGINE_ASYNC_MEMORY_JOBS[internal_id] = dict(current)
        _engine_async_memory_save_id_list(ENGINE_ASYNC_JOB_INDEX_KEY, internal_id)
        _engine_async_memory_save_id_list(_engine_async_feature_key(current.get("feature")), internal_id)
        if current.get("user_id"):
            _engine_async_memory_save_id_list(_engine_async_user_key(current.get("user_id")), internal_id)
            _engine_async_memory_save_id_list(_engine_async_user_key(current.get("user_id"), current.get("feature")), internal_id)
    return current


def save_music_engine_async_job_if_ready(job: dict) -> dict:
    try:
        return save_engine_async_job(job)
    except ValueError as exc:
        if "requires provider_task_id or output_bytes" not in str(exc):
            raise
        current = dict(job or {})
        current["persist_skipped_reason"] = "provider_task_id_or_output_bytes_missing"
        return current

def get_engine_async_job(internal_job_id: str) -> dict:
    raw_id = str(internal_job_id or "").strip()
    lookup_ids = music_job_lookup_aliases(raw_id) or [raw_id]
    for lookup_id in lookup_ids:
        raw = get_system_setting(_engine_async_job_key(lookup_id), "")
        if raw:
            try:
                value = json.loads(raw or "{}")
                return value if isinstance(value, dict) else {}
            except Exception:
                return {}
        memory = ENGINE_ASYNC_MEMORY_JOBS.get(str(lookup_id or "").strip())
        if memory:
            return dict(memory or {})
    return {}


def get_engine_async_job_lookup(internal_job_id: str) -> dict:
    raw_id = str(internal_job_id or "").strip()
    aliases = music_job_lookup_aliases(raw_id) or [raw_id]
    for lookup_id in aliases:
        job = get_engine_async_job(lookup_id)
        if job:
            resolved = str(job.get("internal_job_id") or job.get("job_id") or lookup_id or "").strip()
            return {
                "job": dict(job),
                "resolved_job_id": resolved,
                **music_job_lookup_identity(raw_id, resolved, True),
                "aliases": aliases,
            }
    return {
        "job": {},
        **music_job_lookup_identity(raw_id, "", False),
        "aliases": aliases,
    }

MUSIC_CONFIRM_SUBMIT_BLOCKERS = {
    "confirm_state_missing",
    "provider_submit_not_called",
    "provider_submit_failed",
    "provider_job_id_missing_after_submit",
    "job_persist_failed",
    "scheduler_start_failed",
    "auto_tick_exception",
}

def music_confirm_submit_public_failure_text(lang: str = "vi") -> str:
    if normalize_user_language(lang) != "vi":
        copy = public_hub_copy(lang)
        return f"⚠️ {copy['audio_failure']} {copy['common_no_charge']} {copy['common_retry']}"
    return "⚠️ Chưa gửi được yêu cầu tạo nhạc. TOAN AAS chưa xử lý. Hệ thống chưa trừ Xu. Vui lòng thử lại sau."

def music_confirm_submit_blocker_text(blocker: str = "") -> str:
    normalized = str(blocker or "").strip() or "provider_submit_failed"
    if normalized == "scheduler_start_failed":
        return "Đã nhận job nhạc nhưng chưa bật được tự cập nhật. TOAN AAS chưa trừ Xu cho tới khi file gửi thành công."
    if normalized == "auto_tick_exception":
        return "Tự cập nhật job nhạc gặp lỗi. TOAN AAS chưa trừ Xu cho tới khi file gửi thành công."
    return "Chưa gửi được yêu cầu tạo nhạc. TOAN AAS chưa xử lý và chưa trừ Xu."

def mark_music_confirm_submit_blocker(
    job: dict | None,
    blocker: str,
    detail: str = "",
    *,
    updated_by="",
    persist: bool = True,
) -> dict:
    current = dict(job or {})
    job_id = str(current.get("internal_job_id") or "").strip()
    if not job_id:
        job_id = engine_async_job_id("music_suno", current.get("user_id") or updated_by)
        current["internal_job_id"] = job_id
    normalized = str(blocker or "").strip() or "provider_submit_failed"
    if normalized not in MUSIC_CONFIRM_SUBMIT_BLOCKERS:
        normalized = "provider_submit_failed"
    safe_detail = sanitize_provider_status_text(detail or normalized, str(current.get("provider_task_id") or current.get("provider_job_id") or ""), 240)
    now = now_text()
    if normalized == "scheduler_start_failed":
        current.update({
            "feature": str(current.get("feature") or "music_suno"),
            "status": str(current.get("status") or ("completed" if int(current.get("output_bytes") or 0) > 0 else "submitted")),
            "terminal_state": "",
            "music_terminal_state": "",
            "confirm_submit_blocker": normalized,
            "confirm_submit_phase": str(current.get("confirm_submit_phase") or "submitted"),
            "auto_delivery_blocker": normalized,
            "scheduler_mode": "scheduler_failed",
            "scheduler_status": "start_failed",
            "task_started": False,
            "task_alive": False,
            "progress_percent": max(int(current.get("progress_percent") or 0), 12),
            "progress_text": music_confirm_submit_blocker_text(normalized),
            "last_provider_status": str(current.get("last_provider_status") or safe_detail),
            "scheduler_failed_at": now,
        })
        if str(current.get("error_category") or "") in {"", "scheduler_start_failed"}:
            current["error_category"] = ""
        if not persist:
            ENGINE_ASYNC_MEMORY_JOBS[job_id] = dict(current)
            return current
        try:
            return save_engine_async_job(current)
        except Exception as exc:
            current.update({
                "error_category": "job_persist_failed",
                "confirm_submit_blocker": "job_persist_failed",
                "auto_delivery_blocker": "job_persist_failed",
                "last_provider_status": sanitize_provider_status_text(str(exc), "", 240),
            })
            current = ensure_music_failed_no_charge_metadata(
                current,
                primary_blocker="job_persist_failed",
                fail_stage="persist",
                detail=str(exc),
                provider_submit_called=False,
            )
            ENGINE_ASYNC_MEMORY_JOBS[job_id] = dict(current)
            return current
    provider_submit_was_called = bool(
        normalized not in {"confirm_state_missing", "provider_submit_not_called", "job_persist_failed"}
        or current.get("provider_submit_called")
        or str(current.get("provider_task_id") or current.get("provider_job_id") or "").strip()
    )
    current.update({
        "feature": str(current.get("feature") or "music_suno"),
        "status": "failed",
        "terminal_state": "failed_no_charge",
        "music_terminal_state": "failed_no_charge",
        "error_category": normalized,
        "confirm_submit_blocker": normalized,
        "confirm_submit_phase": "submit_failed",
        "auto_delivery_blocker": normalized,
        "progress_percent": max(15, int(current.get("progress_percent") or 15)),
        "progress_text": music_confirm_submit_blocker_text(normalized),
        "last_provider_status": safe_detail,
        "pending_charge_xu": 0,
        "music_charged_xu": 0,
        "music_refunded": False,
        "submit_failed_at": now,
        "confirm_submit_failed_at": now,
    })
    current = ensure_music_failed_no_charge_metadata(
        current,
        primary_blocker=normalized,
        detail=safe_detail,
        provider_submit_called=provider_submit_was_called,
    )
    if not persist:
        ENGINE_ASYNC_MEMORY_JOBS[job_id] = dict(current)
        return current
    try:
        return save_engine_async_job(current)
    except Exception as exc:
        current.update({
            "error_category": "job_persist_failed",
            "confirm_submit_blocker": "job_persist_failed",
            "auto_delivery_blocker": "job_persist_failed",
            "last_provider_status": sanitize_provider_status_text(str(exc), "", 240),
            "submit_failed_at": now_text(),
            "confirm_submit_failed_at": now_text(),
        })
        current = ensure_music_failed_no_charge_metadata(
            current,
            primary_blocker="job_persist_failed",
            fail_stage="persist",
            detail=str(exc),
            provider_submit_called=provider_submit_was_called,
        )
        ENGINE_ASYNC_MEMORY_JOBS[job_id] = dict(current)
        return current

def music_confirm_submit_blocker_from_job(job: dict | None = None) -> str:
    current = dict(job or {})
    for key in ("confirm_submit_blocker", "auto_delivery_blocker", "error_category"):
        value = str(current.get(key) or "").strip()
        if value in MUSIC_CONFIRM_SUBMIT_BLOCKERS:
            return value
    return ""


