def music_failed_no_charge_primary_blocker(job: dict | None = None) -> str:
    current = dict(job or {})
    for key in (
        "primary_blocker",
        "artifact_blocker",
        "auto_delivery_blocker",
        "music_delivery_blocker",
        "confirm_submit_blocker",
        "error_category",
    ):
        value = sanitize_provider_status_text(current.get(key) or "", str(current.get("provider_task_id") or current.get("provider_job_id") or ""), 160).strip()
        if value and value not in {"failed", "failed_no_charge", "none", "-"}:
            return value
    terminal = str(current.get("terminal_state") or current.get("music_terminal_state") or "").strip().lower()
    status = str(current.get("status") or "").strip().lower()
    if terminal == "failed_no_charge" or status == "failed_no_charge":
        return MUSIC_FAILED_NO_CHARGE_COMPAT_BLOCKER
    return ""


def music_failed_no_charge_fail_stage(job: dict | None = None, primary_blocker: str = "") -> str:
    current = dict(job or {})
    explicit = str(current.get("fail_stage") or current.get("music_fail_stage") or "").strip()
    if explicit:
        return sanitize_provider_status_text(explicit, "", 80)
    blocker = str(primary_blocker or music_failed_no_charge_primary_blocker(current) or "").strip()
    if blocker in MUSIC_FAILED_STAGE_BY_BLOCKER:
        return MUSIC_FAILED_STAGE_BY_BLOCKER[blocker]
    if blocker.startswith("artifact_") or "artifact" in blocker or "result_url" in blocker:
        return "artifact"
    if "delivery" in blocker or "telegram" in blocker:
        return "delivery"
    if "provider" in blocker:
        return "provider_submit" if "submit" in blocker or "task_id" in blocker or "job_missing" in blocker else "provider_poll"
    return "unknown" if blocker else ""


def music_provider_submit_called_debug_value(job: dict | None = None) -> str:
    current = dict(job or {})
    provider_task_id = str(current.get("provider_task_id") or current.get("provider_job_id") or current.get("music_task_id") or "").strip()
    if provider_task_id:
        return "yes"
    if "provider_submit_called" in current:
        return "yes" if bool(current.get("provider_submit_called")) else "no"
    phase = str(current.get("confirm_submit_phase") or "").strip().lower()
    if phase in {"provider_submit_called", "provider_job_id_saved", "submitted"}:
        return "yes"
    blocker = music_failed_no_charge_primary_blocker(current)
    if blocker in {"confirm_state_missing", "provider_submit_not_called", "music_provider_submit_not_called", "job_persist_failed", "music_job_persist_failed", "music_confirm_callback_unbound"}:
        return "no"
    return "unknown"


def ensure_music_failed_no_charge_metadata(
    job: dict | None = None,
    *,
    primary_blocker: str = "",
    fail_stage: str = "",
    detail: str = "",
    provider_submit_called=None,
    callback_name: str = "",
    route_name: str = "",
) -> dict:
    current = dict(job or {})
    blocker = str(primary_blocker or music_failed_no_charge_primary_blocker(current) or MUSIC_FAILED_NO_CHARGE_COMPAT_BLOCKER).strip()
    stage = str(fail_stage or music_failed_no_charge_fail_stage(current, blocker) or "unknown").strip()
    provider_task_id = str(current.get("provider_task_id") or current.get("provider_job_id") or current.get("music_task_id") or "").strip()
    safe_detail = sanitize_provider_status_text(
        detail
        or current.get("fail_reason_safe")
        or current.get("last_provider_status")
        or current.get("provider_error")
        or current.get("last_send_error")
        or blocker,
        provider_task_id,
        240,
    )
    current["primary_blocker"] = blocker
    current.setdefault("error_category", blocker)
    current.setdefault("auto_delivery_blocker", blocker)
    current["fail_stage"] = stage
    current["fail_reason_safe"] = safe_detail or blocker
    current.setdefault("failed_at", now_text())
    current.setdefault("music_failed_at", current.get("failed_at") or now_text())
    if provider_submit_called is not None:
        current["provider_submit_called"] = bool(provider_submit_called)
    elif "provider_submit_called" not in current and music_provider_submit_called_debug_value(current) != "unknown":
        current["provider_submit_called"] = music_provider_submit_called_debug_value(current) == "yes"
    current["provider_task_id_present"] = bool(provider_task_id)
    current.setdefault("job_persisted", bool(current.get("persist_helper_called") or current.get("created_before_provider_submit") or current.get("internal_job_id")))
    current.setdefault("registry_saved", bool(current.get("progress_registry_saved") or current.get("progress_registry_key")))
    if callback_name:
        current.setdefault("callback_name", sanitize_provider_status_text(callback_name, "", 120))
    if route_name:
        current.setdefault("route_name", sanitize_provider_status_text(route_name, "", 120))
    return current

def list_engine_async_jobs(feature: str = "", user_id="", limit: int = 5, active_only: bool = False) -> list[dict]:
    if user_id and feature:
        ids = _engine_async_id_list_from_setting(_engine_async_user_key(user_id, feature))
    elif user_id:
        ids = _engine_async_id_list_from_setting(_engine_async_user_key(user_id))
    elif feature:
        ids = _engine_async_id_list_from_setting(_engine_async_feature_key(feature))
    else:
        ids = _engine_async_id_list_from_setting(ENGINE_ASYNC_JOB_INDEX_KEY)
    jobs: list[dict] = []
    for internal_id in ids:
        job = get_engine_async_job(internal_id)
        if not job:
            continue
        if active_only and str(job.get("status") or "").lower() not in ENGINE_ASYNC_ACTIVE_STATUSES:
            continue
        jobs.append(job)
        if len(jobs) >= max(1, int(limit or 5)):
            break
    return jobs

def music_vault_entry_key(vault_id: str) -> str:
    safe_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(vault_id or ""))[:80]
    return MUSIC_VAULT_PREFIX + safe_id

def music_vault_id_for_output(output_sha256: str = "", internal_job_id: str = "", provider: str = "", task_id: str = "") -> str:
    seed = output_sha256 or f"{internal_job_id}:{provider}:{task_id}:{time.time_ns()}"
    digest = hashlib.sha256(str(seed or "").encode("utf-8")).hexdigest()[:10].upper()
    return f"MV-{digest}"

def music_audio_sha256(audio_bytes: bytes | bytearray | None = None) -> str:
    data = bytes(audio_bytes or b"")
    return hashlib.sha256(data).hexdigest() if data else ""

def music_vault_category_for_result(result: dict | None = None) -> str:
    result = dict(result or {})
    kind = str(result.get("product_kind") or music_result_product_kind(result)).strip().lower()
    if kind in {"song_half", "song_full", "song_seconds"} or str(result.get("music_ai_kind") or "").lower() in {"lyrics", "song"}:
        return "vocal_ai"
    return "instrumental_ai"

def music_vault_status(value: str = "") -> str:
    status = str(value or "generated_unused").strip().lower()
    return status if status in MUSIC_VAULT_STATUSES else "generated_unused"

def music_vault_safe_prompt(result: dict | None = None) -> str:
    result = dict(result or {})
    prompt = str(result.get("selected_prompt") or result.get("description") or "").strip()
    return sanitize_provider_status_text(prompt, "", 900)

def music_vault_store_audio_bytes(vault_id: str, audio_bytes: bytes | bytearray | None = None) -> str:
    data = bytes(audio_bytes or b"")
    safe_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(vault_id or ""))[:80]
    if not data or not safe_id:
        return ""
    try:
        root = os.path.abspath(os.path.join(OPERATOR_UPLOAD_DIR or "operator_uploads", "music_vault"))
        os.makedirs(root, exist_ok=True)
        path = os.path.join(root, f"{safe_id}.mp3")
        if not os.path.exists(path) or os.path.getsize(path) <= 0:
            with open(path, "wb") as handle:
                handle.write(data)
        return path if os.path.exists(path) and os.path.getsize(path) > 0 else ""
    except Exception as exc:
        logger.warning("music vault file store failed | %s", sanitize_log_text(str(exc))[:180])
        return ""

def music_prompt_selection_summary(result: dict | None = None) -> str:
    result = dict(result or {})
    parts = []
    if result.get("song_product") or str(result.get("music_ai_kind") or "").lower() in {"lyrics", "song"}:
        parts.append("product=Bài hát có lời AI")
        parts.append(f"mode={music_result_product_kind(result)}")
        for key, label in [
            ("song_topic", "topic"),
            ("song_genre", "genre"),
            ("song_mood", "mood"),
            ("song_vocal", "vocal"),
        ]:
            value = str(result.get(key) or "").strip()
            if value:
                parts.append(f"{label}={value[:120]}")
    else:
        parts.append("product=Nhạc nền AI")
        for key, label in [
            ("guided_purpose", "purpose"),
            ("guided_style", "style"),
            ("guided_mood", "mood"),
            ("guided_duration", "duration"),
        ]:
            value = str(result.get(key) or "").strip()
            if value:
                parts.append(f"{label}={value[:120]}")
    parts.append(f"preview={music_preview_seconds()}s_from_{music_preview_start_seconds()}s")
    return sanitize_provider_status_text("; ".join(parts), "", 700)

def music_provider_prompt_for_result(result: dict | None = None, preview: bool = False) -> str:
    result = dict(result or {})
    if music_product_result_is_3tier(result):
        style_prompt = str(result.get("provider_style_prompt") or "").strip()
        lyrics = str(result.get("provider_lyrics") or "").strip()
        if style_prompt and lyrics:
            return f"Style: {style_prompt}\n\nLyrics:\n{lyrics}"
        if style_prompt:
            return style_prompt
    prompt = str(result.get("selected_prompt") or result.get("description") or "").strip()[:1200]
    full_duration = music_result_duration_seconds(result)
    product_kind = music_result_product_kind(result)
    selection = music_prompt_selection_summary(result)
    prompt = (
        f"{prompt}. Telegram selections: {selection}. "
        f"Target output duration: {full_duration} seconds."
    )
    if preview:
        prompt += (
            f" Create the full requested track; TOAN AAS will clip only the first {music_preview_seconds()} seconds "
            "locally for preview and keep the full file in the vault until confirmation."
        )
    if product_kind == "song_half" and music_short_mode_verified():
        prompt += " Create a verified short song/clip with complete original lyrics, clear hook/chorus, and no sentence cut off."
    elif product_kind == "song_full":
        prompt += " Create a complete original song with intro, verse, chorus, bridge and outro structure."
    else:
        prompt += " Create original instrumental background music, no famous melody, no artist imitation."
    return prompt

def _music_vault_index() -> list[str]:
    raw = get_system_setting(MUSIC_VAULT_INDEX_KEY, "")
    ids = []
    try:
        loaded = json.loads(raw or "[]")
        ids = loaded if isinstance(loaded, list) else []
    except Exception:
        ids = []
    if not ids:
        ids = list(MUSIC_VAULT_MEMORY_INDEX)
    clean = []
    seen = set()
    for item in ids:
        safe = re.sub(r"[^A-Za-z0-9_.:-]", "", str(item or ""))[:80]
        if safe and safe not in seen:
            clean.append(safe)
            seen.add(safe)
    return clean

def _music_vault_save_index(vault_id: str, updated_by="") -> None:
    safe_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(vault_id or ""))[:80]
    if not safe_id:
        return
    ids = [safe_id]
    for item in _music_vault_index():
        if item != safe_id:
            ids.append(item)
        if len(ids) >= ENGINE_ASYNC_JOB_MAX_INDEX:
            break
    try:
        set_system_setting(MUSIC_VAULT_INDEX_KEY, json.dumps(ids, separators=(",", ":")), "music vault index", updated_by)
    except Exception:
        pass
    MUSIC_VAULT_MEMORY_INDEX[:] = ids

def save_music_vault_entry(entry: dict, updated_by="") -> dict:
    current = dict(entry or {})
    output_sha = str(current.get("output_sha256") or "").strip()
    vault_id = str(current.get("vault_id") or music_vault_id_for_output(
        output_sha,
        current.get("internal_job_id") or "",
        current.get("provider") or "",
        current.get("provider_task_id") or "",
    )).strip()
    now = now_text()
    current.update({
        "vault_id": vault_id,
        "status": music_vault_status(current.get("status")),
        "category": "vocal_ai" if str(current.get("category") or "") == "vocal_ai" else "instrumental_ai",
        "output_sha256": output_sha,
        "output_bytes": int(current.get("output_bytes") or 0),
        "updated_at": now,
    })
    current.setdefault("created_at", now)
    current.setdefault("reserved_at", "")
    current.setdefault("used_at", "")
    current.setdefault("archived_at", "")
    current.setdefault("reuse_policy", "reusable_internal_stock")
    current.setdefault("prompt_summary", "")
    current.setdefault("last_send_error", "")
    try:
        set_system_setting(
            music_vault_entry_key(vault_id),
            json.dumps(current, ensure_ascii=False, separators=(",", ":")),
            f"music vault status={current.get('status')}",
            updated_by,
        )
        _music_vault_save_index(vault_id, updated_by)
    except Exception:
        MUSIC_VAULT_MEMORY[vault_id] = dict(current)
        _music_vault_save_index(vault_id, updated_by)
    return current

def get_music_vault_entry(vault_id: str) -> dict:
    raw = get_system_setting(music_vault_entry_key(vault_id), "")
    if not raw:
        return dict(MUSIC_VAULT_MEMORY.get(str(vault_id or "").strip()) or {})
    try:
        loaded = json.loads(raw or "{}")
        return loaded if isinstance(loaded, dict) else {}
    except Exception:
        return {}

def list_music_vault_entries(statuses: set[str] | list[str] | tuple[str, ...] | None = None, limit: int = 10) -> list[dict]:
    wanted = {music_vault_status(item) for item in (statuses or []) if str(item or "").strip()}
    entries = []
    for vault_id in _music_vault_index():
        entry = get_music_vault_entry(vault_id)
        if not entry:
            continue
        if wanted and str(entry.get("status") or "") not in wanted:
            continue
        entries.append(entry)
        if len(entries) >= max(1, int(limit or 10)):
            break
    return entries

def upsert_music_vault_from_output(
    *,
    audio_bytes: bytes | bytearray,
    result: dict | None = None,
    job: dict | None = None,
    status: str = "generated_unused",
    updated_by="",
) -> dict:
    data = bytes(audio_bytes or b"")
    if not data:
        return {}
    result = dict(result or {})
    job = dict(job or {})
    output_sha = music_audio_sha256(data)
    existing_id = str(job.get("vault_id") or result.get("music_vault_id") or "").strip()
    current = get_music_vault_entry(existing_id) if existing_id else {}
    vault_id = existing_id or current.get("vault_id") or music_vault_id_for_output(output_sha, job.get("internal_job_id") or "", job.get("provider") or "", job.get("provider_task_id") or "")
    storage_ref = str(current.get("storage_ref") or job.get("output_path") or "")[:600]
    if not storage_ref:
        storage_ref = music_vault_store_audio_bytes(vault_id, data)
    entry = {
        **current,
        "vault_id": vault_id,
        "category": music_vault_category_for_result(result or job),
        "status": status,
        "user_id": str(job.get("user_id") or result.get("user_id") or ""),
        "chat_id": str(job.get("chat_id") or result.get("chat_id") or ""),
        "internal_job_id": str(job.get("internal_job_id") or result.get("music_internal_job_id") or ""),
        "provider": str(job.get("provider") or result.get("music_provider") or ""),
        "provider_task_id_present": bool(job.get("provider_task_id") or result.get("music_task_id")),
        "product_kind": music_result_product_kind(result or job),
        "duration_seconds": music_result_duration_seconds(result or job),
        "preview_seconds": music_preview_seconds(),
        "preview_start_seconds": music_preview_start_seconds(),
        "output_bytes": len(data),
        "output_sha256": output_sha,
        "storage_ref": storage_ref,
        "prompt_summary": music_prompt_selection_summary(result or job),
        "safe_prompt": music_vault_safe_prompt(result or job),
        "reuse_policy": "reusable_internal_stock",
    }
    if status == "preview_sent":
        entry["sent_preview_at"] = now_text()
    return save_music_vault_entry(entry, updated_by=updated_by)

def find_music_vault_entry_for_job(job: dict | None = None) -> dict:
    current = dict(job or {})
    direct_id = str(current.get("vault_id") or current.get("music_vault_id") or "").strip()
    if direct_id:
        entry = get_music_vault_entry(direct_id)
        if entry:
            return entry
    internal_id = str(current.get("internal_job_id") or "").strip()
    output_sha = str(current.get("output_sha256") or "").strip()
    for vault_id in _music_vault_index():
        entry = get_music_vault_entry(vault_id)
        if not entry:
            continue
        if internal_id and str(entry.get("internal_job_id") or "") == internal_id:
            return entry
        if output_sha and str(entry.get("output_sha256") or "") == output_sha:
            return entry
    return {}

def music_vault_status_for_completed_job(job: dict | None = None) -> str:
    current = dict(job or {})
    if current.get("sent_full_at") or current.get("delivered_at") or current.get("claimed_at"):
        return "used"
    if current.get("sent_preview_at") or current.get("music_preview_seen"):
        return "preview_sent"
    return "generated_unused"

def upsert_music_vault_from_completed_job(job: dict | None = None, updated_by="") -> dict:
    current = dict(job or {})
    if str(current.get("status") or "").lower() != "completed":
        return {}
    if int(current.get("output_bytes") or 0) <= 0:
        return {}
    existing = find_music_vault_entry_for_job(current)
    output_sha = str(current.get("output_sha256") or "").strip()
    vault_id = str(existing.get("vault_id") or current.get("vault_id") or "").strip()
    if not vault_id:
        vault_id = music_vault_id_for_output(
            output_sha,
            current.get("internal_job_id") or "",
            current.get("provider") or "",
            current.get("provider_task_id") or "",
        )
    storage_ref = str(existing.get("storage_ref") or current.get("output_path") or "").strip()
    output_file_id = str(current.get("output_file_id") or "").strip()
    if not storage_ref and output_file_id:
        storage_ref = f"telegram_file_id:{output_file_id}"
    status = music_vault_status_for_completed_job(current)
    entry = {
        **existing,
        "vault_id": vault_id,
        "category": music_vault_category_for_result(current),
        "status": status,
        "user_id": str(current.get("user_id") or ""),
        "chat_id": str(current.get("chat_id") or ""),
        "internal_job_id": str(current.get("internal_job_id") or ""),
        "provider": str(current.get("provider") or ""),
        "provider_task_id_present": bool(current.get("provider_task_id")),
        "product_kind": music_result_product_kind(current),
        "duration_seconds": music_result_duration_seconds(current),
        "preview_seconds": int(current.get("preview_seconds") or music_preview_seconds()),
        "preview_start_seconds": int(current.get("preview_start_seconds") or music_preview_start_seconds()),
        "output_bytes": int(current.get("output_bytes") or 0),
        "output_sha256": output_sha,
        "storage_ref": storage_ref[:600],
        "prompt_summary": music_prompt_selection_summary(current),
        "safe_prompt": music_vault_safe_prompt(current),
        "reuse_policy": str(existing.get("reuse_policy") or "reusable_internal_stock"),
        "source": str(existing.get("source") or "backfill"),
    }
    if status == "preview_sent" and not entry.get("sent_preview_at"):
        entry["sent_preview_at"] = str(current.get("sent_preview_at") or current.get("completed_at") or now_text())
    if status == "used" and not entry.get("used_at"):
        entry["used_at"] = str(current.get("sent_full_at") or current.get("completed_at") or now_text())
    saved = save_music_vault_entry(entry, updated_by=updated_by)
    if str(current.get("internal_job_id") or "") and str(current.get("vault_id") or "") != str(saved.get("vault_id") or ""):
        current["vault_id"] = str(saved.get("vault_id") or "")
        save_engine_async_job(current)
    return saved

def backfill_completed_music_vault_entries(limit: int = 80, updated_by="") -> dict:
    created_or_updated = 0
    for job in list_engine_async_jobs("music_suno", limit=max(1, int(limit or 80))):
        before = find_music_vault_entry_for_job(job)
        entry = upsert_music_vault_from_completed_job(job, updated_by=updated_by)
        if entry and (not before or before != entry):
            created_or_updated += 1
    return {"checked": max(1, int(limit or 80)), "upserted": created_or_updated}

def mark_music_vault_status(vault_id: str, status: str, updated_by="") -> dict:
    entry = get_music_vault_entry(vault_id)
    if not entry:
        return {}
    next_status = music_vault_status(status)
    entry["status"] = next_status
    if next_status == "used":
        entry["used_at"] = now_text()
    elif next_status == "archived":
        entry["archived_at"] = now_text()
    elif next_status == "reserved":
        entry["reserved_at"] = now_text()
    return save_music_vault_entry(entry, updated_by=updated_by)

def latest_completed_music_suno_job_with_output() -> dict:
    for job in list_engine_async_jobs("music_suno", limit=20):
        if str(job.get("status") or "").lower() == "completed" and int(job.get("output_bytes") or 0) > 0:
            return job
