def music_result_url_expired_download(job: dict | None = None) -> bool:
    current = dict(job or {})
    category = str(current.get("artifact_download_error_category") or current.get("last_download_error_category") or "").strip().lower()
    if category in {"artifact_download_failed", "download_http_failed"}:
        return False
    if category in {
        "result_url_expired",
        "result_url_forbidden",
        "result_url_forbidden_access_denied",
        "result_url_forbidden_or_missing_auth",
        "result_url_signature_lost_or_invalid",
        "provider_auth_required",
        "provider_result_missing_or_expired",
    }:
        return True
    try:
        status = int(current.get("artifact_download_http_status") or current.get("last_download_http_status") or 0)
    except Exception:
        status = 0
    if status in {401, 403, 404, 410}:
        return True
    return False


async def refresh_music_expired_result_url_for_job(
    job: dict | None = None,
    *,
    updated_by="",
    source: str = "recovery_refresh",
) -> dict:
    current = dict(job or {})
    if not current:
        return {"ok": False, "status": "MISSING_JOB", "job": {}}
    provider_task_id = music_job_provider_task_id(current)
    if not provider_task_id:
        return {"ok": False, "status": "PROVIDER_TASK_ID_MISSING", "job": current}
    old_url = music_job_result_url(current)
    current.update({
        "refresh_url_attempted": True,
        "refresh_url_attempted_at": now_text(),
        "refresh_url_attempt_count": int(current.get("refresh_url_attempt_count") or 0) + 1,
        "refreshed_result_url": False,
        "lifecycle_status": str(current.get("lifecycle_status") or "refreshing_result_url"),
    })
    if current.get("internal_job_id"):
        save_engine_async_job(current)
    try:
        polled = await poll_music_generation_job(music_suno_poll_state_from_job(current), updated_by=updated_by)
    except Exception as exc:
        current.update({
            "refresh_url_status": "provider_repoll_failed",
            "refresh_url_error": sanitize_provider_status_text(str(exc), provider_task_id, 180),
            "primary_blocker": "result_url_expired",
            "artifact_blocker": "result_url_expired",
            "auto_delivery_blocker": "result_url_expired",
            "error_category": "result_url_expired",
            "terminal_state": "failed_no_charge",
            "music_terminal_state": "failed_no_charge",
            "progress_text": "Link kết quả nhạc đã hết hạn trước khi TOAN AAS tải được file. Hệ thống chưa trừ Xu.",
        })
        current = ensure_music_failed_no_charge_metadata(
            current,
            primary_blocker="result_url_expired",
            fail_stage="artifact",
            detail=str(exc),
            provider_submit_called=True,
        )
        if current.get("internal_job_id"):
            save_engine_async_job(current)
        return {"ok": False, "status": "RESULT_URL_EXPIRED", "job": current, "recovery_action": "refresh_url_failed"}
    provider_status = str(polled.get("status") or "")
    fresh_url = str(polled.get("output_url") or "").strip()
    current = apply_music_provider_result_metadata(current, polled, fresh_url or old_url)
    refreshed_candidates = list(polled.get("provider_result_candidates") or current.get("provider_result_candidates") or [])
    current.update({
        "provider_last_poll_at": now_text(),
        "last_poll_at": now_text(),
        "poll_count": int(current.get("poll_count") or 0) + 1,
        "provider_poll_count": int(current.get("provider_poll_count") or current.get("poll_count") or 0) + 1,
        "last_provider_status": sanitize_provider_status_text(provider_status or polled.get("detail") or "-", provider_task_id),
        "provider_status_raw": sanitize_provider_status_text(provider_status or polled.get("detail") or "-", provider_task_id),
        "provider_refresh_attempted": True,
        "refreshed_candidate_count": len(refreshed_candidates),
        "refreshed_url_changed": bool(fresh_url and fresh_url != old_url),
    })
    if polled.get("ok") and fresh_url and fresh_url != old_url:
        current.update({
            "status": "downloading",
            "provider_status": "completed",
            "provider_completed": True,
            "music_provider_completed": True,
            "provider_completed_at": str(current.get("provider_completed_at") or now_text()),
            "lifecycle_status": "result_url_refreshed",
            "materialization_status": "not_attempted",
            "refresh_url_status": "refreshed",
            "refreshed_result_url": True,
            "refreshed_candidate_count": len(refreshed_candidates),
            "refreshed_url_changed": True,
            "result_url_refreshed_at": now_text(),
            "result_url_first_seen_at": now_text(),
            "result_url_label": music_result_url_debug_label(fresh_url),
            "output_url": fresh_url,
            "music_output_url": fresh_url,
            "result_url": fresh_url,
            "download_url": fresh_url,
            "progress_text": "TOAN AAS đã tạo xong bài hát, đang tải file nhạc để gửi cho anh/chị.",
            "terminal_state": "",
            "music_terminal_state": "",
            "primary_blocker": "",
            "artifact_blocker": "",
            "auto_delivery_blocker": "",
            "error_category": "",
        })
        if current.get("internal_job_id"):
            save_engine_async_job(current)
        materialized = await materialize_music_artifact_for_job(current, updated_by=updated_by, source=source)
        materialized["recovery_action"] = "refresh_url_materialized" if materialized.get("ok") else "refresh_url_materialize_failed"
        return materialized
    if polled.get("ok") and fresh_url and fresh_url == old_url:
        current.update({
            "status": "downloading",
            "provider_status": "completed",
            "provider_completed": True,
            "music_provider_completed": True,
            "lifecycle_status": "result_url_same_retry_materialize",
            "materialization_status": "not_attempted",
            "refresh_url_status": "same_result_url_retry_materialize",
            "refreshed_result_url": False,
            "progress_text": "TOAN AAS đang thử tải lại file nhạc từ kết quả provider.",
            "terminal_state": "",
            "music_terminal_state": "",
        })
        if current.get("internal_job_id"):
            save_engine_async_job(current)
        materialized = await materialize_music_artifact_for_job(current, updated_by=updated_by, source=f"{source}_same_url")
        materialized["recovery_action"] = "same_url_materialized" if materialized.get("ok") else "same_url_materialize_failed"
        if materialized.get("ok"):
            return materialized
        current = dict(materialized.get("job") or current)
    current.update({
        "refresh_url_status": "same_or_missing_result_url",
        "refreshed_result_url": False,
        "primary_blocker": str(current.get("primary_blocker") or "result_url_forbidden_or_missing_auth"),
        "artifact_blocker": str(current.get("artifact_blocker") or current.get("primary_blocker") or "result_url_forbidden_or_missing_auth"),
        "auto_delivery_blocker": str(current.get("auto_delivery_blocker") or current.get("primary_blocker") or "result_url_forbidden_or_missing_auth"),
        "error_category": str(current.get("error_category") or current.get("primary_blocker") or "result_url_forbidden_or_missing_auth"),
        "terminal_state": "failed_no_charge",
        "music_terminal_state": "failed_no_charge",
        "lifecycle_status": "result_url_download_failed",
        "materialization_status": "failed",
        "progress_text": "TOAN AAS chưa tải được file nhạc hợp lệ từ kết quả provider. Hệ thống chưa trừ Xu.",
    })
    current = ensure_music_failed_no_charge_metadata(
        current,
        primary_blocker=str(current.get("primary_blocker") or "result_url_forbidden_or_missing_auth"),
        fail_stage="artifact",
        detail=current.get("refresh_url_status") or current.get("last_provider_status") or "",
        provider_submit_called=True,
    )
    if current.get("internal_job_id"):
        save_engine_async_job(current)
    final_status = "RESULT_URL_EXPIRED" if str(current.get("primary_blocker") or "").strip().lower() == "result_url_expired" else "RESULT_URL_DOWNLOAD_FAILED"
    return {"ok": False, "status": final_status, "job": current, "recovery_action": "refresh_url_unavailable"}


async def deliver_music_ready_artifact_once(
    job_id: str = "",
    *,
    context=None,
    message=None,
    chat_id=None,
    user_id=0,
    lang: str = "vi",
    product_context: str = "showroom",
    source: str = "recovery",
) -> dict:
    lookup = get_engine_async_job_lookup(job_id)
    current = dict(lookup.get("job") or {})
    if not current:
        return {"ok": False, "status": "MISSING_JOB", **lookup}
    resolved_job_id = str(lookup.get("resolved_job_id") or current.get("internal_job_id") or current.get("job_id") or job_id or "").strip()
    if music_job_delivered(current):
        return {"ok": True, "status": "ALREADY_DELIVERED", "duplicate": True, "job": current, **lookup}
    if music_job_terminal_failed(current) and not music_job_scheduler_artifact_recoverable(current) and not music_job_artifact_metadata_ready(current):
        return {"ok": False, "status": "TERMINAL_FAILED", "job": current, **lookup}
    materialized = {"recovery_action": "none", "job": current}
    if (
        not music_job_ready_artifact_validated(current)
        and not music_job_artifact_metadata_ready(current)
        and str(current.get("provider") or current.get("provider_name_internal") or "") == "key4u_suno"
        and music_job_provider_task_id(current)
    ):
        try:
            polled = await poll_music_generation_job(music_suno_poll_state_from_job(current), updated_by=user_id or current.get("user_id") or "")
            fresh_url = str(polled.get("output_url") or "").strip()
            current = apply_music_provider_result_metadata(current, polled, fresh_url or music_job_result_url(current))
            current.update({
                "provider_last_poll_at": now_text(),
                "last_poll_at": now_text(),
                "provider_refresh_attempted": True,
                "provider_completed": bool(polled.get("ok") or music_poll_status_is_success_without_url(polled.get("status")) or current.get("provider_completed")),
                "music_provider_completed": bool(polled.get("ok") or music_poll_status_is_success_without_url(polled.get("status")) or current.get("music_provider_completed")),
            })
            if fresh_url:
                current.update({
                    "status": "downloading",
                    "output_url": fresh_url,
                    "music_output_url": fresh_url,
                    "result_url": fresh_url,
                    "result_url_first_seen_at": str(current.get("result_url_first_seen_at") or now_text()),
                    "progress_text": "TOAN AAS đã tạo xong bài hát, đang tải file nhạc để gửi cho anh/chị.",
                })
            elif polled.get("primary_blocker"):
                current.update({
                    "primary_blocker": str(polled.get("primary_blocker") or ""),
                    "artifact_blocker": str(polled.get("primary_blocker") or ""),
                    "error_category": str(polled.get("error_category") or polled.get("primary_blocker") or ""),
                    "setup_required": str(polled.get("setup_required") or current.get("setup_required") or ""),
                    "recovery_action": str(polled.get("recovery_action") or current.get("recovery_action") or ""),
                })
            if resolved_job_id:
                save_engine_async_job(current)
        except Exception as exc:
            current["provider_refresh_error"] = sanitize_provider_status_text(str(exc), music_job_provider_task_id(current), 180)
    if not music_job_ready_artifact_validated(current):
        materialized = await materialize_music_artifact_for_job(current, updated_by=user_id or current.get("user_id") or "", source=source)
        current = dict(materialized.get("job") or current)
        if not materialized.get("ok") and music_result_url_expired_download(current) and not bool(current.get("refresh_url_attempted")):
            refreshed = await refresh_music_expired_result_url_for_job(
                current,
                updated_by=user_id or current.get("user_id") or "",
                source=f"{source}_url_refresh",
            )
            materialized = refreshed
            current = dict(refreshed.get("job") or current)
    if not music_job_ready_artifact_validated(current):
        if (
            str(materialized.get("status") or "").upper() == "ARTIFACT_WAITING"
            or str(current.get("artifact_materialization_status") or "").strip().lower() == "waiting_for_provider_audio"
            or bool(current.get("artifact_waiting") or current.get("music_artifact_waiting"))
        ):
            if resolved_job_id:
                save_engine_async_job(current)
            return {
                "ok": False,
                "status": "ARTIFACT_WAITING",
                **lookup,
                "job": current,
                "recovery_action": materialized.get("recovery_action") or "artifact_waiting_retry_later",
                "primary_blocker": MUSIC_ARTIFACT_NOT_READY_BLOCKER,
                "secondary_blocker": music_job_artifact_secondary_blocker(current),
            }
        primary = music_job_artifact_primary_blocker(current) or "artifact_materialization_failed"
        current = set_music_artifact_blocker(
            current,
            primary,
            secondary=music_job_artifact_secondary_blocker(current),
            status=music_job_artifact_state(current) if music_job_artifact_state(current) != "metadata_ready" else "invalid",
            detail=primary,
            updated_by=user_id or current.get("user_id") or "",
        )
        return {
            "ok": False,
            "status": primary.upper(),
            **lookup,
            "job": current,
            "recovery_action": materialized.get("recovery_action") or "delivery_skipped_invalid_audio",
            "primary_blocker": primary,
            "secondary_blocker": music_job_artifact_secondary_blocker(current),
        }
    if str(current.get("music_delivery_lock") or current.get("music_result_delivery_lock") or "").strip().lower() == "sending":
        updated = music_delivery_record_duplicate(current, source, "delivery_locked", current, updated_by=user_id or current.get("user_id") or "")
        return {"ok": True, "status": "DELIVERY_LOCKED", "duplicate": True, "job": updated or current, **lookup}
    delivery_chat_id = chat_id or current.get("chat_id") or current.get("user_id") or user_id
    delivery_user_id = current.get("user_id") or user_id or delivery_chat_id or 0
    if not delivery_chat_id:
        current["auto_delivery_blocker"] = "telegram_chat_id_missing"
        if resolved_job_id:
            save_engine_async_job(current)
        return {"ok": False, "status": "TELEGRAM_CHAT_ID_MISSING", "job": current, **lookup}
    audio_bytes = music_delivery_audio_bytes_from_job(current)
    delivery_message = music_progress_message_proxy(context, delivery_chat_id)
    if not getattr(context, "bot", None) and message is not None and str(getattr(message, "chat_id", "") or "") == str(delivery_chat_id):
        delivery_message = message
    result = music_result_for_job_delivery(delivery_user_id, current)
    delivered = await send_music_product_audio_result(
        delivery_message,
        context or SimpleNamespace(),
        user_id=delivery_user_id,
        lang=lang,
        product_context=product_context,
        result=result,
        audio_bytes=audio_bytes,
        job=current,
        updated_by=user_id or delivery_user_id,
        send_success_message=True,
        source=source,
    )
    updated_job = dict(delivered.get("job") or get_engine_async_job(resolved_job_id) or current)
    if delivered.get("ok") and str(delivered.get("delivery_message_id") or updated_job.get("delivery_message_id") or updated_job.get("music_delivery_message_id") or "").strip():
        updated_job.update({
            "terminal_state": "delivered",
            "music_terminal_state": "delivered",
            "delivery_state": "delivered",
            "auto_delivery_blocker": "",
            "confirm_submit_blocker": "",
            "music_delivery_blocker": "",
        })
        if str(updated_job.get("error_category") or "") in {"scheduler_start_failed", "telegram_delivery_failed", ""}:
            updated_job["error_category"] = ""
        if updated_job.get("internal_job_id"):
            save_engine_async_job(updated_job)
        delivered["job"] = updated_job
    recovery_action = str(materialized.get("recovery_action") or "none")
    if delivered.get("ok") and not delivered.get("duplicate"):
        recovery_action = "delivery_attempted" if recovery_action == "none" else recovery_action
    return {**delivered, **lookup, "resolved_job_id": resolved_job_id, "job": updated_job, "recovery_action": recovery_action}


async def music_auto_deliver_from_progress_record(context, record: dict, job: dict | None = None) -> dict:
    current = dict(job or {})
    if not bool(record.get("auto_delivery_enabled")) or not MUSIC_AUTO_DELIVERY_ENABLED:
        return current
    if not current or music_job_delivered(current):
        return current
    if music_job_ready_artifact_validated(current) or music_job_artifact_metadata_ready(current):
        recovered = await deliver_music_ready_artifact_once(
            str(current.get("internal_job_id") or record.get("job_id") or ""),
            context=context,
            chat_id=record.get("chat_id") or current.get("chat_id"),
            user_id=record.get("user_id") or current.get("user_id") or 0,
            lang=record.get("lang") or "vi",
            source="auto_tick",
        )
        return dict(recovered.get("job") or current)
    if music_job_terminal_failed(current):
        return current
    if not getattr(context, "bot", None):
        current["auto_delivery_blocker"] = "no_bot_context"
        return current
    if int(current.get("output_bytes") or 0) <= 0:
        return current
    if music_job_artifact_duration_seconds(current) <= 0:
        return current
    audio_bytes = music_delivery_audio_bytes_from_job(current)
    if not audio_bytes:
        current["auto_delivery_blocker"] = "artifact_bytes_missing"
        return current
    user_id = record.get("user_id") or current.get("user_id") or 0
    result = music_result_for_job_delivery(user_id, current)
    delivered = await send_music_product_audio_result(
        music_progress_message_proxy(context, record.get("chat_id") or current.get("chat_id") or user_id),
        context,
        user_id=user_id,
        lang=record.get("lang") or "vi",
        product_context=PRODUCT_CONTEXT_SHOWROOM,
        result=result,
        audio_bytes=audio_bytes,
        job=current,
        updated_by=user_id,
        send_success_message=True,
        source="auto_tick",
    )
    updated = dict(delivered.get("job") or get_engine_async_job(str(current.get("internal_job_id") or "")) or current)
    updated["auto_delivery_status"] = str(delivered.get("status") or "")
    return updated


async def progress_auto_refresh_status_for_tick(context, record: dict) -> dict:
    product_type = str(record.get("product_type") or "")
    job_id = str(record.get("job_id") or "")
    if product_type.strip().lower() == "video_edit":
        return progress_auto_refresh_read_status(
            product_type,
            job_id,
            record.get("user_id") or 0,
        )
    if progress_product_type_is_music(product_type, job_id):
        refreshed = await music_progress_refresh_job_status(
            job_id,
            user_id=record.get("user_id") or 0,
            allow_provider_poll=True,
            updated_by=record.get("user_id") or 0,
        )
        return await music_auto_deliver_from_progress_record(context, record, refreshed)
    return progress_auto_refresh_read_status(product_type, job_id, record.get("user_id") or 0)


def progress_auto_refresh_keyboard(product_type: str, job_id: str, lang: str = "vi"):
    if str(product_type or "").strip().lower() == "video_edit":
        normalized_job_id = safe_int(job_id, 0)
        return video_editor_status_keyboard(normalized_job_id, lang) if normalized_job_id > 0 else None
    canonical = product_progress_status.normalize_product_type(product_type)
    return product_progress_status_keyboard(canonical, job_id, lang)


async def progress_auto_refresh_tick(context, key: str) -> dict:
    record = dict(PROGRESS_AUTO_REFRESH_JOBS.get(str(key or "")) or {})
    if not record:
        return {"status": "missing"}
    if record.get("stopped"):
        return {"status": "stopped", "reason": record.get("stop_reason") or ""}
    if int(record.get("update_count") or 0) >= int(record.get("max_updates") or PROGRESS_AUTO_REFRESH_MAX_UPDATES):
        record["stopped"] = True
        record["stop_reason"] = "max_updates"
        record["task_alive"] = False
        PROGRESS_AUTO_REFRESH_JOBS[str(key or "")] = record
        return {"status": "stopped", "reason": "max_updates"}
    is_video_edit = str(record.get("product_type") or "").strip().lower() == "video_edit"
    if is_video_edit:
        expected_key = progress_auto_refresh_key("video_edit", str(record.get("job_id") or ""))
        binding_valid = bool(
            safe_int(record.get("job_id"), 0) > 0
            and safe_int(record.get("user_id"), 0) > 0
            and safe_int(record.get("chat_id"), 0) != 0
            and safe_int(record.get("message_id"), 0) > 0
            and str(key or "") == expected_key
            and str(record.get("key") or expected_key) == expected_key
        )
        if not binding_valid:
            record.update({
                "stopped": True,
                "task_alive": False,
                "stop_reason": "job_missing_or_owner_mismatch",
                "stopped_reason": "job_missing_or_owner_mismatch",
            })
            PROGRESS_AUTO_REFRESH_JOBS[str(key or "")] = record
            return {
                "status": "stopped",
                "reason": "job_missing_or_owner_mismatch",
                "record": dict(record),
                "snapshot": {},
            }
    record["last_tick_at"] = now_text()
    record["task_alive"] = True
    refreshed_job = await progress_auto_refresh_status_for_tick(context, record)
    if is_video_edit and not refreshed_job:
        record.update({
            "stopped": True,
            "task_alive": False,
            "stop_reason": "job_missing_or_owner_mismatch",
            "stopped_reason": "job_missing_or_owner_mismatch",
        })
        PROGRESS_AUTO_REFRESH_JOBS[str(key or "")] = record
        return {
            "status": "stopped",
            "reason": "job_missing_or_owner_mismatch",
            "record": dict(record),
            "snapshot": {},
        }
    snapshot = progress_auto_refresh_snapshot(
        record.get("product_type") or "",
        record.get("job_id") or "",
        job=refreshed_job,
        lang=record.get("lang") or "vi",
        user_id=record.get("user_id") or 0,
    )
    if is_video_edit and not snapshot:
        record.update({
            "stopped": True,
            "task_alive": False,
            "stop_reason": "job_missing_or_owner_mismatch",
            "stopped_reason": "job_missing_or_owner_mismatch",
        })
        PROGRESS_AUTO_REFRESH_JOBS[str(key or "")] = record
        return {
            "status": "stopped",
            "reason": "job_missing_or_owner_mismatch",
            "record": dict(record),
            "snapshot": {},
        }
    last_percent = int(record.get("last_percent") or 0)
    if int(snapshot.get("percent") or 0) < last_percent and not snapshot.get("terminal_state"):
        snapshot["percent"] = last_percent
        snapshot["text"] = re.sub(r"Tiến độ:\s*\d+%", f"Tiến độ: {last_percent}%", str(snapshot.get("text") or ""))
        snapshot["render_hash"] = hashlib.sha256(str(snapshot.get("text") or "").encode("utf-8")).hexdigest()
    record["update_count"] = int(record.get("update_count") or 0) + 1
    terminal = str(snapshot.get("terminal_state") or "")
    should_edit = progress_auto_refresh_should_edit(record, snapshot)

    def commit_panel_update() -> None:
        record["edit_success_count"] = int(record.get("edit_success_count") or 0) + 1
        record["last_update_at"] = now_text()
        record["last_edit_at"] = record["last_update_at"]
        record["last_stage"] = str(snapshot.get("stage") or "")
        record["last_percent"] = int(snapshot.get("percent") or 0)
        record["current_stage"] = str(snapshot.get("stage") or "")
        record["percent"] = int(snapshot.get("percent") or 0)
        record["terminal_state"] = terminal
        record["last_render_hash"] = str(snapshot.get("render_hash") or "")

    if should_edit:
        try:
            await context.bot.edit_message_text(
                chat_id=record.get("chat_id"),
                message_id=record.get("message_id"),
                text=str(snapshot.get("text") or ""),
                parse_mode="HTML",
                reply_markup=progress_auto_refresh_keyboard(record.get("product_type") or "", record.get("job_id") or "", record.get("lang") or "vi"),
            )
            commit_panel_update()
        except Exception as exc:
            not_modified = is_video_edit and video_edit_panel_not_modified(exc)
            if not_modified:
                commit_panel_update()
            else:
                record["edit_fail_count"] = int(record.get("edit_fail_count") or 0) + 1
                record["last_error"] = sanitize_log_text(str(exc))[:180]
            if not is_video_edit and not bool(record.get("edit_only")) and not record.get("fallback_used"):
                try:
                    sent = await context.bot.send_message(
                        chat_id=record.get("chat_id"),
                        text=str(snapshot.get("text") or ""),
                        parse_mode="HTML",
                        reply_markup=progress_auto_refresh_keyboard(record.get("product_type") or "", record.get("job_id") or "", record.get("lang") or "vi"),
                    )
                    record["message_id"] = getattr(sent, "message_id", record.get("message_id"))
                    record["fallback_used"] = True
                    record["last_update_at"] = now_text()
                    record["last_edit_at"] = record["last_update_at"]
                    record["last_stage"] = str(snapshot.get("stage") or "")
                    record["last_percent"] = int(snapshot.get("percent") or 0)
                    record["current_stage"] = str(snapshot.get("stage") or "")
                    record["percent"] = int(snapshot.get("percent") or 0)
                    record["terminal_state"] = terminal
                    record["last_render_hash"] = str(snapshot.get("render_hash") or "")
                except Exception as send_exc:
                    record["last_error"] = sanitize_log_text(str(send_exc))[:180]
            if is_video_edit and not not_modified:
                record["task_alive"] = True
                PROGRESS_AUTO_REFRESH_JOBS[str(key or "")] = record
                return {
                    "status": "retry_pending",
                    "record": dict(record),
                    "snapshot": snapshot,
                }
    else:
        record["last_checked_at"] = now_text()
        record["current_stage"] = str(snapshot.get("stage") or record.get("current_stage") or "")
        record["percent"] = int(snapshot.get("percent") or record.get("percent") or 0)
        record["terminal_state"] = terminal or str(record.get("terminal_state") or "")
        record["last_render_hash"] = str(snapshot.get("render_hash") or record.get("last_render_hash") or "")
    if terminal and bool(record.get("stop_on_terminal", PROGRESS_AUTO_REFRESH_STOP_ON_TERMINAL)):
        record["stopped"] = True
        record["stop_reason"] = terminal
        record["terminal_state"] = terminal
        record["task_alive"] = False
    elif int(record.get("update_count") or 0) >= int(record.get("max_updates") or PROGRESS_AUTO_REFRESH_MAX_UPDATES):
        record["stopped"] = True
        record["stop_reason"] = "max_updates"
        record["task_alive"] = False
    PROGRESS_AUTO_REFRESH_JOBS[str(key or "")] = record
    return {"status": "updated" if should_edit else "skipped", "record": dict(record), "snapshot": snapshot}


async def send_product_progress_message(
    message,
    context,
    *,
    product_type: str,
    job_id: str,
    current_stage: str = "",
    percent: int | None = None,
    terminal_state: str = "",
    public_note: str = "",
    lang: str = "vi",
    user_id=0,
    start_task: bool = True,
):
    canonical = product_progress_status.normalize_product_type(product_type)
    normalized_job_id = canonical_music_job_id(job_id) if progress_product_type_is_music(canonical, job_id) else str(job_id or "")
    panel_job_id = normalized_job_id or str(job_id or "")
    persisted_job = {}
    if progress_product_type_is_music(canonical, panel_job_id):
        persisted_job = get_engine_async_job(job_id) or get_engine_async_job(panel_job_id)
        if not music_progress_panel_job_is_real(panel_job_id, persisted_job):
            record_music_panel_creator_trace(
                job_id,
                product_type=canonical,
                source="send_product_progress_message",
                callback_data=product_progress_status.product_progress_update_callback(canonical, panel_job_id),
                real_job_created_before_panel=False,
                blocked=True,
                reason="missing_real_music_job_before_panel",
            )
            logger.warning("blocked fake music progress panel | product=%s | input_job=%s | normalized_job=%s", sanitize_log_text(canonical)[:40], sanitize_log_text(str(job_id or ""))[:80], sanitize_log_text(str(panel_job_id or ""))[:80])
            sent = await message.reply_text(
                music_panel_missing_job_public_text(lang),
                parse_mode="HTML",
            )
            try:
                setattr(sent, "music_panel_blocked", True)
                setattr(sent, "blocked_reason", "missing_real_music_job_before_panel")
            except Exception:
                pass
            return sent
    panel_text = product_progress_status_text(canonical, panel_job_id, current_stage, percent, terminal_state, public_note, lang)
    if progress_product_type_is_music(canonical, panel_job_id) and music_progress_job_lookup_found(panel_job_id, persisted_job):
        panel_text = product_progress_status_from_job_text(canonical, persisted_job, panel_job_id, lang)
    sent = await message.reply_text(
        panel_text,
        parse_mode="HTML",
        reply_markup=product_progress_status_keyboard(canonical, panel_job_id, lang),
    )
    if progress_product_type_is_music(canonical, panel_job_id):
        panel_chat_id = getattr(sent, "chat_id", None) or getattr(message, "chat_id", "")
        panel_message_id = getattr(sent, "message_id", "")
        trace = record_music_panel_creator_trace(
            panel_job_id,
            product_type=canonical,
            source="send_product_progress_message",
            route="send_product_progress_message",
            callback_data=product_progress_status.product_progress_update_callback(canonical, panel_job_id),
            chat_id=panel_chat_id,
            message_id=panel_message_id,
            real_job_created_before_panel=True,
            blocked=False,
        )
        try:
            persisted_job = get_engine_async_job(job_id) or get_engine_async_job(panel_job_id)
            if persisted_job:
                persisted_job.update({
                    "panel_created_by": str(persisted_job.get("panel_created_by") or "send_product_progress_message"),
                    "panel_created_at": str(persisted_job.get("panel_created_at") or trace.get("updated_at") or now_text()),
                    "panel_chat_id": str(panel_chat_id or ""),
                    "panel_message_id": str(panel_message_id or ""),
                    "panel_route": str(persisted_job.get("panel_route") or "send_product_progress_message"),
                    "panel_callback_data": str(product_progress_status.product_progress_update_callback(canonical, panel_job_id)),
                    "real_job_created_before_panel": True,
                })
                save_engine_async_job(persisted_job)
        except Exception as exc:
            logger.warning("music panel trace persist failed | job=%s | %s", sanitize_log_text(str(panel_job_id or ""))[:80], sanitize_log_text(str(exc))[:180])
    progress_auto_refresh_register_message(sent, context, product_type=canonical, job_id=panel_job_id, user_id=user_id, lang=lang, start_task=start_task)
    return sent


def progress_auto_refresh_status_text(job_id: str = "") -> str:
    input_job_id = str(job_id or "").strip()
    wanted = canonical_music_job_id(input_job_id) or input_job_id
    wanted_aliases = set(music_job_lookup_aliases(input_job_id) or [])
    if wanted:
        wanted_aliases.add(wanted)
    if input_job_id:
        wanted_aliases.add(input_job_id)
    records = [
        dict(record)
        for record in PROGRESS_AUTO_REFRESH_JOBS.values()
        if not wanted or bool(wanted_aliases.intersection(set(music_job_lookup_aliases(str(record.get("job_id") or "")) or []) | {str(record.get("job_id") or ""), str(record.get("key") or "")}))
    ]
    if not records and wanted and progress_job_id_is_music(wanted):
        job = get_engine_async_job(wanted)
        if job and str(job.get("progress_chat_id") or job.get("panel_chat_id") or "").strip() and str(job.get("progress_message_id") or job.get("panel_message_id") or "").strip():
            product_type = music_job_product_type(job, "music_bg")
            restored = progress_auto_refresh_register(
                product_type=product_type,
                job_id=wanted,
                chat_id=str(job.get("progress_chat_id") or job.get("panel_chat_id") or ""),
                message_id=str(job.get("progress_message_id") or job.get("panel_message_id") or ""),
                user_id=str(job.get("user_id") or ""),
                lang="vi",
                initial_snapshot=progress_auto_refresh_snapshot(product_type, wanted, job=job, lang="vi"),
                start_task=False,
            )
            if restored:
                restored["scheduler_mode"] = str(restored.get("scheduler_mode") or "restored_read_only")
                restored["restored_from_job"] = True
                PROGRESS_AUTO_REFRESH_JOBS[str(restored.get("key") or progress_auto_refresh_key(product_type, wanted))] = dict(restored)
                records = [dict(restored)]
    if not records:
        return "📊 <b>Auto refresh</b>\n\nKhông có bảng trạng thái auto-refresh đang được lưu.\n• reason: <code>no_registry_after_restart</code>"
    lines = ["📊 <b>Auto refresh</b>", ""]
    for record in records[:10]:
        lines.extend([
            f"• product_type: <code>{html.escape(str(record.get('product_type') or '-'))}</code>",
            f"• job_id: <code>{html.escape(str(record.get('job_id') or '-'))}</code>",
            f"• enabled: <code>{'true' if record.get('enabled') else 'false'}</code>",
            f"• scheduler_mode: <code>{html.escape(str(record.get('scheduler_mode') or '-'))}</code>",
            f"• scheduler_status: <code>{html.escape(str(record.get('scheduler_status') or '-'))}</code>",
            f"• registry_saved: <code>{'true' if record.get('registry_saved') else 'false'}</code>",
            f"• task_started: <code>{'true' if record.get('task_started') else 'false'}</code>",
            f"• task_alive: <code>{'true' if record.get('task_alive') else 'false'}</code>",
            f"• chat_id/message_id: <code>{html.escape(str(record.get('chat_id') or '-'))}/{html.escape(str(record.get('message_id') or '-'))}</code>",
            f"• task_started_at: <code>{html.escape(str(record.get('task_started_at') or '-'))}</code>",
            f"• last_tick_at: <code>{html.escape(str(record.get('last_tick_at') or '-'))}</code>",
            f"• last_update_at: <code>{html.escape(str(record.get('last_update_at') or '-'))}</code>",
            f"• last_edit_at: <code>{html.escape(str(record.get('last_edit_at') or '-'))}</code>",
            f"• update_count/max: <code>{int(record.get('update_count') or 0)}/{int(record.get('max_updates') or 0)}</code>",
            f"• terminal_state: <code>{html.escape(str(record.get('terminal_state') or '-'))}</code>",
            f"• last_percent/stage: <code>{int(record.get('last_percent') or 0)}% / {html.escape(str(record.get('last_stage') or '-'))}</code>",
            f"• current_percent/stage: <code>{int(record.get('percent') or 0)}% / {html.escape(str(record.get('current_stage') or '-'))}</code>",
            f"• edit_success/fail: <code>{int(record.get('edit_success_count') or 0)}/{int(record.get('edit_fail_count') or 0)}</code>",
            f"• fallback_used: <code>{'true' if record.get('fallback_used') else 'false'}</code>",
            f"• stopped_reason: <code>{html.escape(str(record.get('stopped_reason') or record.get('stop_reason') or '-'))}</code>",
            f"• stopped: <code>{'true' if record.get('stopped') else 'false'} {html.escape(str(record.get('stop_reason') or ''))}</code>",
            "",
        ])
    return "\n".join(lines).strip()


