UI_TEXT.update(public_ui_text_table())

_MISSING_UI_TEXT_KEYS: set[str] = set()

def ui_text(lang: str | None, key: str, **kwargs) -> str:
    selected = normalize_user_language(lang) or "en"
    value = (UI_TEXT.get(selected) or {}).get(key)
    if value is None and selected in USER_LANGUAGE_LABELS:
        copy = public_hub_copy(selected)
        common_keys = {
            "common.back": "common_back",
            "common.main_menu": "common_main_menu",
            "common.main_menu_back": "common_main_menu",
        }
        copy_key = common_keys.get(key)
        if copy_key:
            prefix = "🔙 " if key == "common.main_menu_back" else "🏠 " if key == "common.main_menu" else "🔙 "
            value = prefix + str(copy[copy_key])
    # Supported public locales must never silently fall back to English or
    # Vietnamese.  Every canonical UI_TEXT key is populated by the static
    # locale overlays above; an unknown key remains visibly identifiable for
    # copy review instead of leaking another language into the menu.
    if value is None and selected not in USER_LANGUAGE_LABELS:
        value = UI_TEXT["en"].get(key)
    if value is None:
        value = key
        marker = f"{selected}:{key}"
        if marker not in _MISSING_UI_TEXT_KEYS:
            _MISSING_UI_TEXT_KEYS.add(marker)
            logger.warning("Missing UI translation key %s for lang %s", key, selected)
    try:
        return str(value).format(**kwargs)
    except Exception:
        logger.warning("UI translation format failed for key %s", key)
        return str(value)

def user_ui_lang(user_id) -> str:
    return normalize_user_language(get_user_language(user_id)) or "vi"

def trial_bonus_hash_value(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    salt = TRIAL_BONUS_HASH_SALT or TELEGRAM_WEBHOOK_SECRET or OPERATOR_API_TOKEN or "toan-aas-trial-bonus-local-salt"
    return hmac.new(str(salt).encode("utf-8"), raw.encode("utf-8"), hashlib.sha256).hexdigest()

def record_trial_bonus_claim_conn(
    conn,
    telegram_user_id,
    amount: int,
    status: str,
    source: str = "telegram_start",
    reason: str = "",
    ip_hash: str = "",
    ip_prefix_hash: str = "",
    user_agent_hash: str = "",
    metadata: dict | None = None,
):
    try:
        conn.execute(
            """INSERT INTO trial_bonus_claims
               (telegram_user_id, ip_hash, ip_prefix_hash, user_agent_hash, claim_source, bonus_amount,
                status, reason, created_at, updated_at, metadata_json)
               VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
            (
                str(telegram_user_id or ""),
                str(ip_hash or ""),
                str(ip_prefix_hash or ""),
                str(user_agent_hash or ""),
                str(source or "unknown"),
                int(amount or 0),
                str(status or ""),
                str(reason or "")[:300],
                now_text(),
                now_text(),
                json.dumps(metadata or {}, ensure_ascii=False),
            ),
        )
    except Exception as e:
        logger.warning(f"trial bonus audit write failed: {type(e).__name__}")

def get_user(user_id, username="Unknown"):
    uid = str(user_id)
    clean_username = str(username or "Unknown")
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT credits, total_spent, is_vip FROM users WHERE user_id=?", (uid,))
    row = c.fetchone()
    if row:
        conn.close()
        return row[0], row[1], row[2]

    c.execute("SELECT granted_xu FROM trial_grants WHERE user_id=?", (uid,))
    trial_row = c.fetchone()
    if trial_row:
        initial_credits = 0
        note = "User recreated after missing users row; trial already granted before, no new trial credits."
        c.execute(
            "INSERT INTO users (user_id, username, credits, is_vip, join_date, total_spent) VALUES (?,?,?,?,?,?)",
            (uid, clean_username, initial_credits, 0, now_text(), 0)
        )
        record_credit_event(conn, uid, 0, "trial_already_granted_recreated", "", note)
        record_trial_bonus_claim_conn(
            conn,
            uid,
            0,
            "blocked_duplicate_user",
            "telegram_start",
            "trial_grants already has this Telegram user; no new free trial",
            metadata={"paid_topups_unaffected": True},
        )
        conn.commit()
        conn.close()
        return initial_credits, 0, 0

    initial_credits = TRIAL_BONUS_AMOUNT if TRIAL_BONUS_ENABLED else 0
    now = now_text()
    c.execute(
        "INSERT INTO users (user_id, username, credits, is_vip, join_date, total_spent) VALUES (?,?,?,?,?,?)",
        (uid, clean_username, initial_credits, 0, now, 0)
    )
    if TRIAL_BONUS_ENABLED and initial_credits > 0:
        c.execute(
            """INSERT OR IGNORE INTO trial_grants (user_id, granted_xu, granted_at, username, note)
            VALUES (?,?,?,?,?)""",
            (uid, initial_credits, now, clean_username, "First trial grant"),
        )
        record_trial_bonus_claim_conn(
            conn,
            uid,
            initial_credits,
            "granted",
            "telegram_start",
            "one_time_free_trial_by_telegram_user_id; no IP available from Telegram bot",
            metadata={
                "ip_available": False,
                "ip_check_applies_only_when_ip_available": bool(TRIAL_BONUS_IP_CHECK_ENABLED),
                "paid_topups_unaffected": True,
            },
        )
        record_credit_event(conn, uid, initial_credits, "trial_grant", "", f"Tặng {initial_credits} Xu trải nghiệm lần đầu")
    conn.commit()
    conn.close()
    return initial_credits, 0, 0

def get_trial_grant_status(user_id) -> dict:
    uid = str(user_id)
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute("SELECT granted_xu, granted_at, username, note FROM trial_grants WHERE user_id=?", (uid,))
        row = c.fetchone()
        return {
            "user_id": uid,
            "granted": row is not None,
            "granted_xu": int(row[0] or 0) if row else 0,
            "granted_at": row[1] if row else "",
            "username": row[2] if row else "",
            "note": row[3] if row else "",
        }
    finally:
        conn.close()

def add_credit(user_id, amount, event_type="manual_add", ref_id="", note=""):
    get_user(user_id)
    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute("BEGIN IMMEDIATE")
        if str(event_type or "") == "manual_deposit" and str(ref_id or "").strip() and int(amount or 0) > 0:
            duplicate = c.execute(
                """SELECT 1 FROM credit_events
                   WHERE user_id=? AND event_type=? AND ref_id=? AND delta>0
                   LIMIT 1""",
                (str(user_id), str(event_type), str(ref_id)),
            ).fetchone()
            if duplicate:
                conn.rollback()
                return False
        c.execute("UPDATE users SET credits = credits + ? WHERE user_id=?", (amount, str(user_id)))
        record_credit_event(conn, user_id, amount, event_type, ref_id, note)
        if event_type in {"admin_add", "manual_deposit"}:
            record_audit(
                conn,
                ADMIN_ID,
                "admin",
                "credit.added",
                "user",
                str(user_id),
                before=None,
                after={"delta": int(amount), "event_type": event_type, "ref_id": ref_id},
                note=note,
            )
        conn.commit()
        return True
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

def refund_charged_credit(user_id, amount, event_type="refund", ref_id="", note="", was_charged=True) -> bool:
    if not was_charged or is_admin_user(user_id) or int(amount or 0) <= 0:
        return False
    get_user(user_id)
    amount = int(amount)
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """UPDATE users
        SET credits = credits + ?,
            total_spent = CASE WHEN total_spent >= ? THEN total_spent - ? ELSE 0 END
        WHERE user_id=?""",
        (amount, amount, amount, str(user_id))
    )
    record_credit_event(conn, user_id, amount, event_type, ref_id, note)
    conn.commit()
    conn.close()
    return True

def spend_fixed_credit_info(user_id, amount, event_type, note="", apply_member_discount_flag=True) -> dict:
    base_amount = int(amount or 0)
    if is_admin_user(user_id):
        return {
            "ok": True,
            "base_cost": base_amount,
            "final_cost": 0,
            "discount_rate": 0,
            "discount_xu": 0,
            "tier": "admin",
            "badge": admin_display_badge(user_id) or "Admin",
            "note": "admin_free",
        }
    get_user(user_id)
    charge = (
        apply_member_service_discount(user_id, base_amount, event_type)
        if apply_member_discount_flag
        else {
            "base_cost": base_amount,
            "final_cost": base_amount,
            "discount_rate": 0,
            "discount_xu": 0,
            "tier": get_member_profile(user_id).get("tier") or "newbie",
            "badge": get_role_badge(user_id),
        }
    )
    final_amount = int(charge.get("final_cost") or 0)
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT credits FROM users WHERE user_id=?", (str(user_id),))
    row = c.fetchone()
    if not row or int(row[0] or 0) < final_amount:
        conn.close()
        charge["ok"] = False
        return charge
    c.execute(
        "UPDATE users SET credits = credits - ?, total_spent = total_spent + ? WHERE user_id=?",
        (final_amount, final_amount, str(user_id)),
    )
    discount_note = ""
    if int(charge.get("discount_xu") or 0) > 0:
        discount_note = (
            f" | member_discount tier={charge.get('tier')} "
            f"base={charge.get('base_cost')} rate={charge.get('discount_rate')} "
            f"discount={charge.get('discount_xu')} final={final_amount}"
        )
    record_credit_event(conn, user_id, -final_amount, event_type, "", f"{note}{discount_note}")
    conn.commit()
    conn.close()
    charge["ok"] = True
    return charge

def spend_fixed_credit(user_id, amount, event_type, note="") -> bool:
    return bool(spend_fixed_credit_info(user_id, amount, event_type, note).get("ok"))

def is_payos_order_processed(order_code: str) -> bool:
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT 1 FROM payos_processed WHERE order_code=?", (str(order_code),))
    exists = c.fetchone() is not None
    conn.close()
    return exists

def mark_payos_order_processed(order_code: str):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        "INSERT OR IGNORE INTO payos_processed (order_code, processed_at) VALUES (?,?)",
        (str(order_code), now_text())
    )
    conn.commit()
    conn.close()

PAYMENT_TYPES = {
    "topup_xu",
    "storage_addon",
    "combo_purchase",
    "monthly_package",
    "manual_topup",
}

def normalize_payment_type(value: str = "", order_type: str = "", metadata: dict | None = None) -> str:
    candidate = str(value or "").strip().lower()
    if candidate in PAYMENT_TYPES:
        return candidate
    order = str(order_type or "topup").strip().lower()
    meta = metadata if isinstance(metadata, dict) else {}
    if order in {"topup", "topup_xu", ""}:
        return "topup_xu"
    if order == "storage_addon":
        return "storage_addon"
    if order == "plan_purchase":
        return "monthly_package"
    if order == "package_purchase":
        return "monthly_package" if str(meta.get("package_type") or "").lower() == "monthly" else "combo_purchase"
    if order == "manual_topup":
        return "manual_topup"
    return candidate or order

def payment_package_id(order_type: str = "", plan_id: str = "", metadata: dict | None = None) -> str:
    meta = metadata if isinstance(metadata, dict) else {}
    return str(
        meta.get("package_id")
        or meta.get("package_code")
        or meta.get("item_id")
        or plan_id
        or order_type
        or ""
    ).strip()

def record_payos_processed_conn(
    conn,
    order_code: str,
    payment_type: str,
    apply_status: str = "success",
    payment_link_id: str = "",
    apply_error: str = "",
) -> None:
    conn.execute(
        """INSERT OR IGNORE INTO payos_processed
        (order_code, payment_link_id, payment_type, apply_status, apply_error, processed_at)
        VALUES (?,?,?,?,?,?)""",
        (
            str(order_code),
            str(payment_link_id or ""),
            normalize_payment_type(payment_type),
            str(apply_status or "success"),
            str(apply_error or "")[:300],
            now_text(),
        ),
    )

def normalize_payos_webhook_status(value: str = "") -> str:
    return str(value or "").strip().upper()

def payos_webhook_is_paid_status(value: str = "") -> bool:
    return normalize_payos_webhook_status(value) == PAYOS_STATUS_PAID

def payos_payload_text(data: dict, *keys: str) -> str:
    if not isinstance(data, dict):
        return ""
    for key in keys:
        value = data.get(key)
        if value is not None and str(value).strip():
            return str(value).strip()
    return ""

def payos_order_code_from_webhook_data(data: dict) -> str:
    return payos_payload_text(data, "orderCode", "order_code")

def payos_payment_link_id_from_webhook_data(data: dict) -> str:
    return payos_payload_text(data, "paymentLinkId", "payment_link_id", "paymentLinkID")

def payos_transaction_id_from_webhook_data(data: dict) -> str:
    return payos_payload_text(
        data,
        "transactionId",
        "transactionID",
        "transaction_id",
        "reference",
        "referenceId",
        "reference_id",
        "paymentId",
        "payment_id",
    )

def payos_idempotency_event_key(order_code: str, payment_link_id: str = "", transaction_id: str = "") -> str:
    tx = str(transaction_id or "").strip()
    if tx:
        return f"transaction:{tx}"
    link_id = str(payment_link_id or "").strip()
    if link_id:
        return f"payment_link:{link_id}"
    return f"order:{str(order_code or '').strip()}"

def _payos_processed_event_by_key_conn(conn, column: str, value: str):
    if column not in {"order_code", "payment_link_id", "transaction_id", "event_key"}:
        return None
    clean_value = str(value or "").strip()
    if not clean_value:
        return None
    return conn.execute(
        f"""SELECT order_code, payment_link_id, transaction_id, credited, event_key
            FROM payos_processed_events
            WHERE {column}=? AND credited=1
            ORDER BY id ASC LIMIT 1""",
        (clean_value,),
    ).fetchone()

def reserve_payos_idempotency_conn(
    conn,
    order_code: str,
    amount_vnd: int,
    user_id: str = "",
    payment_link_id: str = "",
    transaction_id: str = "",
    status: str = PAYOS_STATUS_PAID,
    raw_hash: str = "",
) -> dict:
    clean_order_code = str(order_code or "").strip()
    clean_payment_link_id = str(payment_link_id or "").strip()
    clean_transaction_id = str(transaction_id or "").strip()
    if not clean_order_code:
        return {"ok": False, "reason": "missing_order_code"}

    if conn.execute("SELECT 1 FROM payos_processed WHERE order_code=?", (clean_order_code,)).fetchone():
        return {"ok": False, "reason": "duplicate_order", "order_code": clean_order_code}

    checks = [
        ("order_code", clean_order_code, "duplicate_order", "order_conflict"),
        ("transaction_id", clean_transaction_id, "duplicate_transaction", "transaction_conflict"),
        ("payment_link_id", clean_payment_link_id, "duplicate_payment_link", "payment_link_conflict"),
    ]
    for column, value, duplicate_reason, conflict_reason in checks:
        existing = _payos_processed_event_by_key_conn(conn, column, value)
        if not existing:
            continue
        existing_order_code = str(existing[0] or "").strip()
        reason = duplicate_reason if existing_order_code == clean_order_code else conflict_reason
        return {
            "ok": False,
            "reason": reason,
            "order_code": clean_order_code,
            "existing_order_code": existing_order_code,
            "payment_link_id": clean_payment_link_id,
            "transaction_id": clean_transaction_id,
        }

    event_key = payos_idempotency_event_key(clean_order_code, clean_payment_link_id, clean_transaction_id)
    try:
        conn.execute(
            """INSERT INTO payos_processed_events
               (event_key, order_code, payment_link_id, transaction_id, user_id, amount, status, credited, created_at, raw_hash)
               VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (
                event_key,
                clean_order_code,
                clean_payment_link_id,
                clean_transaction_id,
                str(user_id or ""),
                int(amount_vnd or 0),
                normalize_payos_webhook_status(status),
                0,
                now_text(),
                str(raw_hash or "")[:128],
            ),
        )
    except sqlite3.IntegrityError:
        existing = conn.execute(
            """SELECT order_code, payment_link_id, transaction_id, credited
               FROM payos_processed_events WHERE event_key=? LIMIT 1""",
            (event_key,),
        ).fetchone()
        existing_order_code = str(existing[0] or "").strip() if existing else ""
        reason = "duplicate_idempotency_event" if existing_order_code == clean_order_code else "idempotency_conflict"
        return {
            "ok": False,
            "reason": reason,
            "order_code": clean_order_code,
            "existing_order_code": existing_order_code,
            "event_key": event_key,
        }

    return {
        "ok": True,
        "reason": "reserved",
        "event_key": event_key,
        "order_code": clean_order_code,
        "payment_link_id": clean_payment_link_id,
        "transaction_id": clean_transaction_id,
    }

def mark_payos_idempotency_credited_conn(conn, event_key: str) -> None:
    clean_event_key = str(event_key or "").strip()
    if not clean_event_key:
        return
    conn.execute(
        "UPDATE payos_processed_events SET credited=1, status=? WHERE event_key=?",
        (PAYOS_STATUS_PAID, clean_event_key),
    )

def create_order(
    order_code,
    user_id,
    amount,
    xu,
    base_xu=0,
    launch_bonus_xu=0,
    package_amount_vnd=None,
    order_type="topup",
    plan_id="",
    plan_name="",
    duration_days=0,
    plan_xu=0,
    metadata_json="",
):
    try:
        metadata = json.loads(metadata_json or "{}") if metadata_json else {}
        if not isinstance(metadata, dict):
            metadata = {}
    except Exception:
        metadata = {}
    payment_type = normalize_payment_type(metadata.get("payment_type"), order_type, metadata)
    package_id = payment_package_id(order_type, plan_id, metadata)
    conn = db_connect()
    if payment_type in TOPUP_PROMO_PAYMENT_TYPES:
        user_snapshot = canonical_user_market_snapshot_conn(conn, user_id)
        method = metadata.get("payment_method") or metadata.get("method") or "payos"
        currency = str(metadata.get("currency") or "VND").upper()
        metadata.update({
            "user_market_snapshot": user_snapshot.get("user_market") or "",
            "country_snapshot": user_snapshot.get("country_code") or "",
            "account_region_snapshot": user_snapshot.get("account_region") or "",
            "international_account": bool(user_snapshot.get("international_account")),
            "initial_user_language": user_snapshot.get("initial_user_language") or "",
            "payment_market": canonical_payment_market(method, currency, metadata.get("payment_market") or ""),
            "payment_channel": canonical_topup_method(method),
            "payment_currency": currency,
        })
    c = conn.cursor()
    created_at = datetime.now()
    expires_at = created_at + timedelta(minutes=ORDER_TTL_MINUTES)
    snapshot = build_finance_invoice_snapshot_conn(conn, order_code, user_id, amount, order_type, payment_type, metadata)
    metadata = invoice_metadata(snapshot, metadata)
    metadata_json = json.dumps(metadata, ensure_ascii=False)
    total_amount = int(snapshot.get("total_amount_vnd") or amount or 0)
    subtotal_amount = int(snapshot.get("subtotal_amount_vnd") or amount or 0)
    package_vnd = int(amount if package_amount_vnd is None else package_amount_vnd)
    c.execute(
        """INSERT INTO payos_orders
        (order_code, user_id, amount, xu, package_amount_vnd, base_xu, launch_bonus_xu,
         order_type, plan_id, plan_name, duration_days, plan_xu, metadata_json,
         payment_type, package_id, status, created_at, expires_at,
         invoice_type, payment_channel, currency, subtotal_amount_vnd, vat_rate, vat_amount_vnd,
         total_amount_vnd, fx_rate, original_amount, original_currency, vat_mode, tax_category)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (str(order_code), str(user_id), total_amount, xu, package_vnd, int(base_xu or 0), int(launch_bonus_xu or 0),
         str(order_type or "topup"), str(plan_id or ""), str(plan_name or ""), int(duration_days or 0), int(plan_xu or 0), str(metadata_json or ""),
         payment_type, package_id, PAYOS_STATUS_PENDING,
         created_at.strftime("%Y-%m-%d %H:%M:%S"), expires_at.strftime("%Y-%m-%d %H:%M:%S"))
         + (
             str(snapshot.get("invoice_type") or ""),
             str(snapshot.get("payment_channel") or ""),
             str(snapshot.get("currency") or "VND"),
             subtotal_amount,
             float(snapshot.get("vat_rate") or 0),
             int(snapshot.get("vat_amount_vnd") or 0),
             total_amount,
             float(snapshot.get("fx_rate") or 1),
             float(snapshot.get("original_amount") or amount or 0),
             str(snapshot.get("original_currency") or "VND"),
             str(snapshot.get("vat_mode") or VAT_DEFAULT_MODE),
             str(snapshot.get("tax_category") or "standard"),
         )
    )
    record_finance_invoice_conn(conn, snapshot, metadata)
    conn.commit()
    conn.close()

def get_order(order_code):
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT user_id, amount, xu, status, expires_at FROM payos_orders WHERE order_code=?", (str(order_code),))
    row = c.fetchone()
    conn.close()
    return row

