DOMESTIC_VND_METHOD_ALIASES = {
    "payos": "payos",
    "bank_qr": "bank_acb_vietqr",
    "vietqr": "bank_acb_vietqr",
    "manual_bank": "bank_acb_vietqr",
    "bank_acb": "bank_acb_vietqr",
    "bank_acb_vietqr": "bank_acb_vietqr",
    "manual_bank_acb_vnd": "bank_acb_vietqr",
    "manual_vietqr_vnd": "bank_acb_vietqr",
    "zalopay_personal": "manual_zalopay_personal_vnd",
    "manual_zalopay_personal_vnd": "manual_zalopay_personal_vnd",
    "zalopay_merchant": "manual_zalopay_merchant_vnd",
    "manual_zalopay_merchant_vnd": "manual_zalopay_merchant_vnd",
    "momo": "manual_momo_tuithantai_vnd",
    "momo_tuithantai": "manual_momo_tuithantai_vnd",
    "manual_momo_tuithantai_vnd": "manual_momo_tuithantai_vnd",
}

DOMESTIC_BONUS_METHODS = {
    "payos",
    "bank_acb_vietqr",
}

BONUS_BLOCKED_METHODS = {
    "manual_zalopay_personal_vnd",
    "manual_zalopay_merchant_vnd",
    "manual_momo_tuithantai_vnd",
    "usdt_trc20",
    "usdt",
    "crypto",
    "international_card",
    "paypal",
    "stripe",
    "foreign_transfer",
    "unknown_international",
}
TOPUP_PROMO_PAYMENT_TYPES = {"topup_xu", "manual_topup"}
TOPUP_PROMO_EXCLUDED_AMOUNTS_VND: set[int] = set()
TOPUP_PROMO_EXCLUDED_PACKAGE_KEYS: set[str] = set()

def payment_context_value(payment, key: str, default=None):
    if isinstance(payment, dict):
        return payment.get(key, default)
    return getattr(payment, key, default)

def payment_context_bool(payment, key: str, default=False) -> bool:
    value = payment_context_value(payment, key, default)
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "on"}
    return bool(value)

def canonical_topup_method(method: str) -> str:
    normalized = str(method or "").strip().lower()
    return DOMESTIC_VND_METHOD_ALIASES.get(normalized, normalized)

def configured_topup_method_allowed(method: str, configured_methods) -> bool:
    canonical = canonical_topup_method(method)
    return canonical in {canonical_topup_method(item) for item in configured_methods}

def is_vietnam_local_payment_method(payment_method) -> bool:
    method = canonical_topup_method(payment_method)
    return bool(method in DOMESTIC_BONUS_METHODS and method not in BONUS_BLOCKED_METHODS)

def is_international_payment_method(payment_method) -> bool:
    method = canonical_topup_method(payment_method)
    return bool(method in BONUS_BLOCKED_METHODS or method.startswith("foreign_"))

def canonical_payment_market(payment_method: str, currency: str = "VND", explicit_market: str = "") -> str:
    explicit = normalize_user_market(explicit_market)
    if explicit:
        return explicit
    normalized_currency = str(currency or "").strip().upper()
    if normalized_currency == "VND" and is_vietnam_local_payment_method(payment_method):
        return "VN"
    return "INTL"


def is_topup_promo_excluded_package(package_key: str = "", amount_vnd: int = 0) -> bool:
    key = str(package_key or "").strip().lower()
    try:
        amount = int(amount_vnd or 0)
    except Exception:
        amount = 0
    return bool(key in TOPUP_PROMO_EXCLUDED_PACKAGE_KEYS or amount in TOPUP_PROMO_EXCLUDED_AMOUNTS_VND)

def topup_promo_payment_eligibility(
    payment_type: str = "topup_xu",
    payment_method: str = "payos",
    currency: str = "VND",
    amount_vnd: int = 0,
    package_key: str = "",
    promo_min_amount: int = PROMOTION_MINIMUM_TOPUP_VND,
    foreign_manual: bool = False,
    user_market: str = "",
    payment_market: str = "",
    international_account: bool = False,
    is_test: bool = False,
) -> dict:
    payment_type = normalize_payment_type(payment_type)
    currency = str(currency or "VND").strip().upper()
    try:
        amount = int(amount_vnd or 0)
    except Exception:
        amount = 0
    method = canonical_topup_method(payment_method)
    normalized_user_market = normalize_user_market(user_market)
    normalized_payment_market = canonical_payment_market(method, currency, payment_market)
    if payment_type not in TOPUP_PROMO_PAYMENT_TYPES:
        return {"eligible": False, "reason": "not_topup_xu", "method": method}
    if is_test:
        return {"eligible": False, "reason": "test_payment", "method": method}
    if international_account or (normalized_user_market and normalized_user_market != "VN"):
        return {"eligible": False, "reason": "international_account", "method": method}
    if normalized_payment_market != "VN":
        return {"eligible": False, "reason": "payment_market_not_vn", "method": method}
    if foreign_manual or currency != "VND" or is_international_payment_method(method):
        return {"eligible": False, "reason": "international_or_non_vnd", "method": method}
    if not is_vietnam_local_payment_method(method):
        return {"eligible": False, "reason": "payment_method_not_eligible", "method": method}
    if is_topup_promo_excluded_package(package_key, amount):
        return {"eligible": False, "reason": "package_excluded", "method": method}
    if amount > 0 and amount < max(0, int(promo_min_amount or 0)):
        return {"eligible": False, "reason": "min_amount_not_met", "method": method}
    return {
        "eligible": True, "reason": "ok", "method": method,
        "user_market": normalized_user_market or "VN",
        "payment_market": normalized_payment_market,
    }

def should_apply_topup_promo(
    payment_type: str = "topup_xu",
    payment_method: str = "payos",
    currency: str = "VND",
    amount_vnd: int = 0,
    package_key: str = "",
    promo_min_amount: int = PROMOTION_MINIMUM_TOPUP_VND,
    foreign_manual: bool = False,
    user_market: str = "",
    payment_market: str = "",
    international_account: bool = False,
    is_test: bool = False,
) -> bool:
    return bool(topup_promo_payment_eligibility(
        payment_type,
        payment_method,
        currency,
        amount_vnd,
        package_key,
        promo_min_amount,
        foreign_manual,
        user_market,
        payment_market,
        international_account,
        is_test,
    ).get("eligible"))

def launch_bonus_eligible_for_payment(
    payment_type: str = "topup_xu",
    payment_method: str = "payos",
    currency: str = "VND",
    amount_vnd: int = 0,
    package_key: str = "",
    foreign_manual: bool = False,
) -> bool:
    return False

def membership_rank_volume_eligible(payment_type: str = "topup_xu", payment_method: str = "payos", currency: str = "VND") -> bool:
    payment_type = normalize_payment_type(payment_type)
    if payment_type not in TOPUP_PROMO_PAYMENT_TYPES:
        return False
    currency = str(currency or "VND").strip().upper()
    return bool(currency == "VND" or (currency in {"USD", "CNY"} and FOREIGN_MEMBER_POINTS_ENABLED))

def topup_promo_ineligibility_message(reason: str) -> str:
    reason = str(reason or "").strip().lower()
    if reason in {"international_account", "payment_market_not_vn", "international_or_non_vnd", "payment_method_not_eligible"}:
        return "Mã ưu đãi không áp dụng cho phương thức thanh toán này. Đơn của bạn vẫn được cộng Xu gốc."
    if reason == "test_payment":
        return "Giao dịch thử nghiệm không áp dụng ưu đãi."
    if reason == "not_topup_xu":
        return "Mã ưu đãi nạp Xu không áp dụng cho sản phẩm này. Thanh toán vẫn xử lý theo đúng sản phẩm đã chọn."
    return "Mã ưu đãi chưa đủ điều kiện. Đơn của bạn vẫn được cộng Xu gốc nếu thanh toán thành công."

def is_domestic_vnd_topup(payment) -> bool:
    currency = str(payment_context_value(payment, "currency", "VND") or "VND").strip().upper()
    method = canonical_topup_method(payment_context_value(payment, "method", ""))
    amount = int(payment_context_value(payment, "amount_vnd", 0) or 0)
    package_key = str(payment_context_value(payment, "pkg_key", "") or payment_context_value(payment, "package_key", "") or "")
    payment_type = str(payment_context_value(payment, "payment_type", "topup_xu") or "topup_xu")
    user_market = str(payment_context_value(payment, "user_market", "") or payment_context_value(payment, "user_market_snapshot", "") or "")
    payment_market = str(payment_context_value(payment, "payment_market", "") or "")
    international_account = payment_context_bool(payment, "international_account", False)
    return bool(
        DOMESTIC_TOPUP_BONUS_ENABLED
        and should_apply_topup_promo(
            payment_type,
            method,
            currency,
            amount_vnd=amount,
            package_key=package_key,
            promo_min_amount=0,
            foreign_manual=payment_context_bool(payment, "foreign_manual", False),
            user_market=user_market,
            payment_market=payment_market,
            international_account=international_account,
            is_test=payment_context_bool(payment, "is_test", False) or payment_context_bool(payment, "test_payment", False),
        )
    )

def is_foreign_topup(payment) -> bool:
    currency = str(payment_context_value(payment, "currency", "VND") or "VND").strip().upper()
    method = canonical_topup_method(payment_context_value(payment, "method", ""))
    return bool(currency in {"USD", "CNY"} or method == "usdt_trc20" or payment_context_bool(payment, "foreign_manual", False))

def is_topup_bonus_allowed(payment) -> bool:
    return bool(is_domestic_vnd_topup(payment) and not is_foreign_topup(payment))

def is_topup_bonus_blocked(payment) -> bool:
    currency = str(payment_context_value(payment, "currency", "VND") or "VND").strip().upper()
    method = canonical_topup_method(payment_context_value(payment, "method", ""))
    return bool(
        currency in {"USD", "CNY"}
        or payment_context_bool(payment, "foreign_manual", False)
        or method in BONUS_BLOCKED_METHODS
        or method not in DOMESTIC_BONUS_METHODS
    )

def is_first_topup_bonus_allowed(payment) -> bool:
    method = canonical_topup_method(payment_context_value(payment, "method", ""))
    currency = str(payment_context_value(payment, "currency", "VND") or "VND").strip().upper()
    return bool(is_topup_bonus_allowed(payment) and currency in PROMO_FIRST_TOPUP_ELIGIBLE_CURRENCIES and configured_topup_method_allowed(method, PROMO_FIRST_TOPUP_ELIGIBLE_METHODS))

def is_launch_bonus_allowed(payment) -> bool:
    method = canonical_topup_method(payment_context_value(payment, "method", ""))
    currency = str(payment_context_value(payment, "currency", "VND") or "VND").strip().upper()
    return bool(is_topup_bonus_allowed(payment) and currency in PROMO_LAUNCH_BONUS_ELIGIBLE_CURRENCIES and configured_topup_method_allowed(method, PROMO_LAUNCH_BONUS_ELIGIBLE_METHODS))

def is_rank_topup_reward_allowed(payment) -> bool:
    method = canonical_topup_method(payment_context_value(payment, "method", ""))
    currency = str(payment_context_value(payment, "currency", "VND") or "VND").strip().upper()
    return bool(is_topup_bonus_allowed(payment) and currency in PROMO_RANK_TOPUP_REWARD_ELIGIBLE_CURRENCIES and configured_topup_method_allowed(method, PROMO_RANK_TOPUP_REWARD_ELIGIBLE_METHODS))

def is_rank_discount_percent_allowed(user, payment_or_purchase=None) -> bool:
    payment = payment_or_purchase or {}
    currency = str(payment_context_value(payment, "currency", "VND") or "VND").strip().upper()
    method = canonical_topup_method(payment_context_value(payment, "method", ""))
    method_allowed = "all" in RANK_DISCOUNT_PERCENT_ELIGIBLE_METHODS or method in RANK_DISCOUNT_PERCENT_ELIGIBLE_METHODS
    if currency not in RANK_DISCOUNT_PERCENT_ELIGIBLE_CURRENCIES or not method_allowed:
        return False
    return bool(FOREIGN_RANK_DISCOUNT_PERCENT_ENABLED or currency == "VND")

def foreign_topup_rate_vnd(currency: str) -> int:
    return USD_FIXED_RATE_VND if str(currency or "").upper() == "USD" else CNY_FIXED_RATE_VND

def round_foreign_xu(value: int) -> int:
    value = max(0, int(value or 0))
    unit = max(1, int(FOREIGN_XU_ROUND_TO or 1))
    if FOREIGN_XU_ROUNDING_MODE == "ceil":
        return int(math.ceil(value / unit) * unit)
    if FOREIGN_XU_ROUNDING_MODE == "round":
        return int(round(value / unit) * unit)
    return int(math.floor(value / unit) * unit)

def foreign_topup_preview(currency: str, original_amount, method: str = "usdt_trc20") -> dict:
    currency = str(currency or "").strip().upper()
    if currency not in {"USD", "CNY"}:
        raise ValueError("unsupported_foreign_currency")
    amount = float(original_amount or 0)
    if amount <= 0:
        raise ValueError("invalid_foreign_amount")
    rate = foreign_topup_rate_vnd(currency)
    amount_vnd = int(math.floor(amount * rate))
    base_xu = round_foreign_xu(int(math.floor(amount_vnd / max(1, int(XU_TO_VND or 100)))))
    payment = {"currency": currency, "method": method, "foreign_manual": True}
    return {
        "currency": currency,
        "original_amount": int(amount) if amount.is_integer() else amount,
        "fixed_rate_vnd": rate,
        "amount_vnd": amount_vnd,
        "base_xu": base_xu,
        "bonus_xu": 0,
        "expected_xu": base_xu,
        "foreign_manual": True,
        "first_bonus_applied": False,
        "launch_bonus_applied": False,
        "rank_topup_reward_applied": False,
        "extra_xu_percent_bonus_applied": False,
        "rank_discount_percent_preserved": is_rank_discount_percent_allowed(None, payment),
        "member_points_eligible": bool(FOREIGN_MEMBER_POINTS_ENABLED),
        "method": str(method or "usdt_trc20"),
    }

