async def notify_manual_pending_deposit(context, deposit: dict) -> None:
    text = manual_pending_admin_text(deposit)
    keyboard = manual_pending_admin_keyboard(deposit)
    for admin_id in owner_and_admin_ids():
        try:
            if deposit.get("file_id"):
                await context.bot.send_photo(chat_id=admin_id, photo=deposit["file_id"], caption=text, parse_mode="HTML", reply_markup=keyboard)
            else:
                await context.bot.send_message(chat_id=admin_id, text=text, parse_mode="HTML", reply_markup=keyboard)
        except Exception as exc:
            logger.warning("Manual bill admin alert skipped: %s", type(exc).__name__)

async def _send_manual_payment_qr_to_chat(context, chat_id, method: str, caption: str, keyboard=None, lang: str = "vi") -> bool:
    asset_path = manual_method_asset_path(method)
    if asset_path and os.path.isfile(asset_path):
        try:
            with open(asset_path, "rb") as qr_file:
                await context.bot.send_photo(
                    chat_id=chat_id,
                    photo=qr_file,
                    caption=caption,
                    parse_mode="HTML",
                    reply_markup=keyboard,
                )
            return True
        except Exception as exc:
            await alert_admin(
                context,
                "Manual payment asset",
                f"manual payment QR send failed: method={method}; path={asset_path}; error={type(exc).__name__}",
            )
    else:
        await alert_admin(context, "Manual payment asset", f"missing manual payment QR asset: method={method}; expected_path={asset_path or '-'}")
    send_message = getattr(context.bot, "send_message", None)
    if callable(send_message):
        try:
            locale = public_copy_locale(lang)
            if locale == "vi":
                fallback_text = (
                    "QR phương thức này chưa được cấu hình. TOAN AAS chưa tạo yêu cầu nạp. "
                    "Vui lòng chọn phương thức khác hoặc liên hệ admin."
                )
            else:
                copy = public_hub_copy(locale)
                account_copy = public_account_flow_copy(locale)
                fallback_text = (
                    f"⚠️ {copy['common_failed']}\n\n"
                    f"{account_copy['payment_locked']}\n\n"
                    f"{copy['common_no_charge']}"
                )
            await send_message(
                chat_id=chat_id,
                text=fallback_text,
            )
        except Exception as exc:
            logger.warning("Manual payment QR fallback message skipped: %s", type(exc).__name__)
    return False

async def send_manual_payment_qr(update, context, method: str, caption: str, keyboard=None, lang: str = "vi") -> bool:
    chat = getattr(update, "effective_chat", None)
    chat_id = getattr(chat, "id", None)
    if chat_id is None:
        query = getattr(update, "callback_query", None)
        message = getattr(query, "message", None)
        chat_id = getattr(message, "chat_id", None)
    if chat_id is None:
        raise ValueError("manual_payment_chat_missing")
    return await _send_manual_payment_qr_to_chat(context, chat_id, method, caption, keyboard, lang)

async def send_manual_method_qr(context, chat_id, uid, method: str) -> bool:
    state = get_active_manual_bill_state(uid) or {}
    lang = get_user_language(uid) or "vi"
    return await _send_manual_payment_qr_to_chat(
        context,
        chat_id,
        method,
        manual_payment_method_text(uid, method, state, lang),
        manual_method_keyboard(uid, lang),
        lang,
    )

def manual_qr_url(uid: int, amount: int, order_code: int) -> str:
    params = {
        "amount": int(amount),
        "addInfo": f"AAS {uid} {order_code}",
        "accountName": PAYMENT_ACCOUNT_OWNER_LABEL,
    }
    bank_code = quote(MANUAL_BANK_CODE, safe="")
    account = quote(MANUAL_BANK_ACCOUNT, safe="")
    return f"https://img.vietqr.io/image/{bank_code}-{account}-compact2.png?{urlencode(params)}"

async def send_manual_payment(
    context: ContextTypes.DEFAULT_TYPE,
    chat_id: int,
    uid: int,
    amount: int,
    xu: int,
    order_code: int,
    reason: str = "",
):
    set_manual_bill_state(uid, order_code=order_code, amount=amount, xu=xu)
    text = manual_payment_text(uid, amount, xu, order_code, reason)
    try:
        await context.bot.send_photo(
            chat_id=chat_id,
            photo=manual_qr_url(uid, amount, order_code),
            caption=text,
            parse_mode="HTML"
        )
    except Exception as e:
        logger.error(f"Manual QR send error: {e}")
        await context.bot.send_message(chat_id=chat_id, text=text, parse_mode="HTML")

def expire_old_payos_orders():
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        "UPDATE payos_orders SET status=? WHERE status=? AND expires_at IS NOT NULL AND expires_at < ?",
        (PAYOS_STATUS_EXPIRED, PAYOS_STATUS_PENDING, now_text())
    )
    conn.commit()
    conn.close()

