def operator_next_run_data(owner_id, days=30, platform="tiktok", limit=8):
    base_url = (PUBLIC_BASE_URL or "https://<RAILWAY_DOMAIN>").rstrip("/")
    audit = operator_audit_data(owner_id)
    pipeline = operator_pipeline_pack_data(owner_id, job_id=0, days=days, platform=platform, limit=limit)
    director = operator_director_data(owner_id, days=days, platform=platform, limit=max(3, min(limit, 20)))
    publisher_caps = publisher_capability_pack_data(owner_id, platform=platform)
    money = operator_money_pack_data(owner_id, days=days, platform=platform, limit=max(3, min(limit, 20)))
    blockers = [item for item in audit.get("checks", []) if not item[1]]
    pipeline_state = pipeline.get("pipeline_state")
    pipeline_action = pipeline.get("next_action") or {}
    director_action = director.get("next_action") or {}
    queue = publisher_caps.get("open_queue") or []

    if blockers:
        key, _ok, detail, next_cmd = blockers[0]
        mode = "SETUP"
        title = f"Hoàn thiện cấu hình: {key}"
        telegram = next_cmd
        api = {"method": "GET", "url": "/api/operator/audit"}
        reason = detail
    elif pipeline_state and pipeline_state != "NO_ACTIVE_JOB":
        mode = pipeline_action.get("type") or pipeline_state
        title = f"Xử lý pipeline job #{pipeline.get('focus_job_id')}"
        telegram = pipeline_action.get("telegram") or "/pipeline_pack"
        api = pipeline_action.get("api") or {"method": "GET", "url": f"/api/operator/jobs/{pipeline.get('focus_job_id')}/pipeline-pack"}
        reason = f"Pipeline state: {pipeline_state}"
    elif queue:
        first = queue[0]
        mode = "PUBLISH"
        title = f"Đăng queue #{first.get('queue_id')} / job #{first.get('job_id')}"
        telegram = f"/publisher_handoff queue={first.get('queue_id')}"
        api = {"method": "GET", "url": f"/api/operator/publish/{first.get('queue_id')}/handoff"}
        reason = publisher_caps.get("overall") or "Có publish queue đang chờ."
    elif director_action:
        mode = director_action.get("action") or "DIRECTOR"
        title = director_action.get("title") or "Chạy next action từ director"
        telegram = director_action.get("telegram_command") or "/operator_director"
        api = director_action.get("api") or {"method": "GET", "url": "/api/operator/director"}
        reason = director_action.get("detail") or director.get("rule") or ""
    else:
        mode = "LAUNCH"
        title = "Tạo batch video affiliate mới"
        telegram = f"/operator_launch topic=công nghệ AI platform={platform} channel=all limit=3 build=1"
        api = {"method": "POST", "url": "/api/operator/launch"}
        reason = "Không có job/queue/task rõ ràng, bắt đầu batch test mới."

    return {
        "ok": True,
        "generated_at": now_text(),
        "mode": mode,
        "title": title,
        "reason": reason,
        "telegram_command": telegram,
        "api": api,
        "operator_card": {
            "admin_says": telegram,
            "claude_reads": f"{base_url}/api/operator/next-run?days={days}&platform={platform}&limit={limit}",
            "worker_starts": (api or {}).get("url", ""),
            "after_done": "/operator_next_run để lấy bước tiếp theo",
        },
        "state": {
            "audit_level": audit.get("level"),
            "pipeline_state": pipeline_state,
            "focus_job_id": pipeline.get("focus_job_id"),
            "publisher_overall": publisher_caps.get("overall"),
            "open_queue_count": len(queue),
            "money_summary": money.get("summary", {}),
        },
        "packs": {
            "pipeline": pipeline,
            "director": director,
            "publisher_capabilities": publisher_caps,
            "money_pack": money,
        },
        "rules": [
            "Luôn chạy theo run card hiện tại, xong một bước thì gọi lại next-run.",
            "Không bỏ qua review gate, approve publish hoặc consent gate.",
            "Auto publish chỉ dùng API chính thức; nếu manual_required thì trả handoff cho admin.",
            "Sau khi đăng phải complete queue và ghi performance để scale/fix/pause.",
        ],
    }

def operator_daily_execution_pack_data(owner_id, days=1, platform="tiktok", limit=8, topic=""):
    days = max(1, min(int(days or 1), 30))
    limit = max(3, min(int(limit or 8), 20))
    platform = (platform or "tiktok").lower()
    topic = (topic or "").strip()
    decision_days = max(7, min(days * 7, 60))
    base_url = (PUBLIC_BASE_URL or "https://<RAILWAY_DOMAIN>").rstrip("/")

    audit = operator_audit_data(owner_id)
    next_run = operator_next_run_data(owner_id, days=decision_days, platform=platform, limit=limit)
    command_center = operator_command_center_data(owner_id, days=decision_days, platform=platform, limit=limit)
    publisher = publisher_capability_pack_data(owner_id, platform=platform)
    money = operator_money_pack_data(owner_id, days=decision_days, platform=platform, limit=limit)
    scale = scale_plan_data(owner_id, days=decision_days, limit=limit, platform=platform)
    _since, affiliate_decisions, _jobs = affiliate_decision_data(
        owner_id,
        days=decision_days,
        limit=limit,
        platform=platform,
    )
    worker_next = operator_worker_next_summary(owner_id, limit=limit)

    open_queue_handoffs = []
    for row in list_publish_queue(owner_id, limit=limit):
        qid, job_id, row_platform, channel_name, mode, status, scheduled_at, publish_url, row_topic, updated_at = row
        if (status or "").lower() not in {"queued", "scheduled", "publishing", "blocked"}:
            continue
        payload = serialize_publish_queue_item(get_publish_queue_item(owner_id, qid))
        handoff = build_publisher_handoff(payload)
        comment_plan = handoff.get("comment_plan") or {}
        media = handoff.get("media") or {}
        open_queue_handoffs.append({
            "queue_id": qid,
            "job_id": job_id,
            "platform": row_platform,
            "channel": channel_name,
            "mode": mode,
            "status": status,
            "scheduled_at": scheduled_at,
            "topic": row_topic,
            "final_video_ready": bool(media.get("final_video_url") or media.get("telegram_file_id")),
            "comment_count": int(comment_plan.get("count") or 0),
            "telegram": f"/publisher_handoff queue={qid}",
            "api": f"/api/operator/publish/{qid}/handoff",
            "after_publish": f"/publish_queue_set id={qid} status=published url=https://...",
        })

    channel_niche = topic or ""
    if not channel_niche and affiliate_decisions:
        channel_niche = affiliate_decisions[0].get("niche") or affiliate_decisions[0].get("product") or ""
    channel_router = operator_channel_router_data(owner_id, platform=platform, niche=channel_niche or "công nghệ AI affiliate", limit=limit)

    def _ranked_action(lane, title, why, telegram, api, done_when, machine_action):
        return {
            "rank": len(execution_queue) + 1,
            "lane": lane,
            "title": title,
            "why": why,
            "telegram": telegram,
            "api": api,
            "done_when": done_when,
            "machine_action": machine_action,
        }

    execution_queue = []
    counts = audit.get("counts") or {}
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            "SELECT COUNT(*) FROM reference_videos WHERE owner_id=? AND COALESCE(status,'active')='active'",
            (str(owner_id),),
        )
        active_references = int(c.fetchone()[0] or 0)
        conn.close()
    except Exception:
        active_references = 0
    bootstrap_needs = {
        "channels": int(counts.get("active_channels") or 0) <= 0,
        "campaigns": int(counts.get("active_campaigns") or 0) <= 0,
        "affiliates": int(counts.get("active_affiliates") or 0) <= 0,
        "references": active_references <= 0,
    }
    if any(bootstrap_needs.values()):
        missing_labels = []
        if bootstrap_needs["channels"]:
            missing_labels.append("kênh")
        if bootstrap_needs["campaigns"]:
            missing_labels.append("campaign")
        if bootstrap_needs["affiliates"]:
            missing_labels.append("affiliate")
        if bootstrap_needs["references"]:
            missing_labels.append("reference video")
        execution_queue.append(_ranked_action(
            "setup_bootstrap",
            "Bootstrap dữ liệu nền còn thiếu",
            "Thiếu " + ", ".join(missing_labels) + ". Bot chỉ thêm dữ liệu mặc định còn thiếu, không xóa hoặc ghi đè dữ liệu cũ.",
            (
                "/operator_bootstrap "
                f"channels={int(bootstrap_needs['channels'])} "
                f"campaigns={int(bootstrap_needs['campaigns'])} "
                f"affiliates={int(bootstrap_needs['affiliates'])} "
                f"refs={int(bootstrap_needs['references'])}"
            ),
            "/api/operator/bootstrap",
            "Có đủ dữ liệu nền để tạo job, giao worker và chuẩn bị publish.",
            {
                "safe_to_execute": True,
                "requires_admin": False,
                "method": "POST",
                "url": "/api/operator/bootstrap",
                "body": {
                    "channels": bootstrap_needs["channels"],
                    "campaigns": bootstrap_needs["campaigns"],
                    "affiliates": bootstrap_needs["affiliates"],
                    "references": bootstrap_needs["references"],
                    "reference_limit": 200,
                    "notify_admin": True,
                },
                "reason": "Setup này chỉ tạo dữ liệu nền còn thiếu; secret/env vẫn phải do admin cấu hình.",
                "expected_output": "Seed channel/campaign/affiliate/reference nếu thiếu; dữ liệu cũ được giữ nguyên.",
                "after_success": "/api/operator/daily-pack",
            },
        ))
    hard_setup_keys = {"operator_api", "publish_readiness"}
    soft_runtime_keys = {
        "ai_provider",
        "payos",
        "affiliate_catalog",
        "channels",
        "campaigns",
        "production_pipeline",
        "performance_tracking",
    }
    setup_warnings = []
    for key, ok, detail, next_cmd in audit.get("checks", []):
        if not ok:
            if key in soft_runtime_keys:
                setup_warnings.append({"key": key, "detail": detail, "next": next_cmd})
                continue
            if key not in hard_setup_keys:
                setup_warnings.append({"key": key, "detail": detail, "next": next_cmd})
                continue
            execution_queue.append(_ranked_action(
                "setup",
                f"Sửa cấu hình: {key}",
                detail,
                next_cmd,
                "/api/operator/audit",
                "Audit không còn blocker này.",
                {
                    "safe_to_execute": False,
                    "requires_admin": True,
                    "method": "GET",
                    "url": "/api/operator/audit",
                    "body": {},
                    "reason": "Setup/env/secret/kênh/link có thể cần admin hoặc cấu hình ngoài bot.",
                    "after_success": "/operator_daily_pack",
                },
            ))
            break

    for item in worker_next[:limit]:
        task = item.get("next_task") or {}
        job_id = int(item.get("job_id") or task.get("job_id") or 0)
        if task:
            task_id = int(task.get("id") or 0)
            execution_queue.append(_ranked_action(
                "produce",
                f"Làm task {task.get('task_type') or '-'} cho job #{job_id or '-'}",
                task.get("title") or "Có task worker đang chờ.",
                f"/worker_pack job={job_id or '<JOB_ID>'}",
                f"/api/operator/jobs/{job_id or '<JOB_ID>'}/worker-pack",
                "Task complete/upload xong và job có asset/prompt/output thật.",
                {
                    "safe_to_execute": bool(job_id),
                    "requires_admin": False,
                    "method": "GET",
                    "url": f"/api/operator/tasks/claim?job_id={job_id}&include_context=1&include_prompt=1" if job_id else "/api/operator/worker-next",
                    "body": {},
                    "claim_task_id_hint": task_id,
                    "submit_ready_url": f"/api/operator/tasks/{task_id or '<TASK_ID>'}/complete",
                    "upload_url": f"/api/operator/tasks/{task_id or '<TASK_ID>'}/upload",
                    "expected_output": "output_url hoặc file upload thật; nếu tool lỗi/quota thì status=blocked và ghi tool event.",
                    "after_success": f"/api/operator/jobs/{job_id}/ready" if job_id else "/api/operator/daily-pack",
                },
            ))

    for item in open_queue_handoffs[:limit]:
        execution_queue.append(_ranked_action(
            "publish",
            f"Đăng queue #{item['queue_id']} / job #{item['job_id']}",
            f"Final video ready={item['final_video_ready']}, comments={item['comment_count']}.",
            item["telegram"],
            item["api"],
            item["after_publish"],
            {
                "safe_to_execute": False,
                "requires_admin": True,
                "method": "GET",
                "url": item["api"],
                "body": {},
                "complete_url": f"/api/operator/publish/{item['queue_id']}/complete",
                "complete_body_template": {"status": "published", "publish_url": "https://...", "views": 0, "clicks": 0, "note": "manual_or_official_publish"},
                "reason": "Publish cần review/consent/platform check; chỉ auto khi publisher_run quyết định api_ready.",
                "after_success": f"/api/operator/jobs/{item['job_id']}/post-publish",
            },
        ))

    for item in affiliate_decisions[:limit]:
        action = item.get("action") or ""
        if action not in {"SCALE", "TEST_MORE", "FIX_CTA", "FIX_OFFER"}:
            continue
        aid = item.get("id") or item.get("affiliate_id") or 0
        niche = item.get("niche") or item.get("product") or topic or "công nghệ AI"
        execution_queue.append(_ranked_action(
            "affiliate_growth",
            f"{action} affiliate #{aid} - {item.get('product') or '-'}",
            item.get("reason") or f"score={item.get('score')}",
            item.get("command") or f"/affiliate_scale aff={aid} platform={platform} channel=all limit=3 build=1",
            "/api/operator/affiliate-scale",
            "Tạo job mới, đăng, rồi ghi view/click/revenue theo source.",
            {
                "safe_to_execute": action in {"SCALE", "TEST_MORE"} and bool(aid),
                "requires_admin": action in {"FIX_CTA", "FIX_OFFER"},
                "method": "POST",
                "url": "/api/operator/affiliate-scale",
                "body": {
                    "affiliate_id": int(aid or 0),
                    "platform": platform,
                    "channel": "all",
                    "limit": 3,
                    "build": True,
                    "duration": 45,
                    "notify_admin": True,
                },
                "expected_output": "production_jobs/tasks mới cho affiliate, sau đó worker xử lý produce/review/publish.",
                "after_success": "/api/operator/daily-pack",
            },
        ))

    if not execution_queue:
        execution_queue.append(_ranked_action(
            "launch",
            "Tạo batch video affiliate mới",
            "Không có task/queue/action rõ ràng trong ngày.",
            f"/operator_launch topic={topic or 'công nghệ AI'} platform={platform} channel=all limit=3 build=1",
            "/api/operator/launch",
            "Có production_jobs + tasks để worker sản xuất.",
            {
                "safe_to_execute": True,
                "requires_admin": False,
                "method": "POST",
                "url": "/api/operator/launch",
                "body": {
                    "topic": topic or "công nghệ AI",
                    "platform": platform,
                    "channel": "all",
                    "limit": 3,
                    "build": True,
                    "bootstrap": True,
                    "duration": 45,
                    "notify_admin": True,
                },
                "expected_output": "production_jobs/tasks mới, chưa publish tự động.",
                "after_success": "/api/operator/daily-pack",
            },
        ))

    top_links = []
    for item in (money.get("top_affiliates") or [])[:limit]:
        top_links.append({
            "affiliate_id": item.get("id"),
            "product": item.get("product"),
            "network": item.get("network"),
            "score": item.get("score"),
            "views": item.get("views"),
            "clicks": item.get("clicks"),
            "revenue": item.get("revenue"),
            "next": item.get("next"),
        })

    return {
        "ok": True,
        "generated_at": now_text(),
        "base_url": base_url,
        "days": days,
        "decision_days": decision_days,
        "platform": platform,
        "topic": topic or "",
        "mission": "Daily execution pack cho công ty AI affiliate một người: chọn việc hôm nay, giao worker, publish, gắn comment link, đo hiệu quả và scale.",
        "state": {
            "audit_level": audit.get("level"),
            "audit_score": audit.get("score"),
            "next_mode": next_run.get("mode"),
            "next_title": next_run.get("title"),
            "publisher_overall": publisher.get("overall"),
            "open_queue_count": len(open_queue_handoffs),
            "worker_task_count": len([item for item in worker_next if item.get("next_task")]),
            "affiliate_revenue": (money.get("summary") or {}).get("affiliate_revenue", 0),
            "affiliate_clicks": (money.get("summary") or {}).get("affiliate_clicks", 0),
            "bot_payment_revenue": (money.get("summary") or {}).get("bot_payment_revenue", 0),
        },
        "execution_queue": execution_queue[:limit],
        "next_machine_action": (execution_queue[0].get("machine_action") if execution_queue else {}),
        "setup_warnings": setup_warnings,
        "open_queue_handoffs": open_queue_handoffs,
        "worker_next": worker_next[:limit],
        "affiliate_decisions": affiliate_decisions[:limit],
        "scale_summary": scale.get("summary", {}),
        "top_affiliate_links": top_links,
        "channel_router": {
            "recommended": channel_router.get("recommended", [])[:limit],
            "commands": channel_router.get("commands", {}),
        },
        "commander_prompt": (
            "Đọc execution_queue theo rank. Mỗi lần chỉ xử lý một lane: setup_bootstrap, setup, produce, publish, track hoặc affiliate_growth. "
            "Không tự publish nếu chưa có approve/review. Sau publish phải complete queue và ghi performance. "
            "Nếu tool trả phí lỗi/quota, fallback tool rẻ/miễn phí và báo admin."
        ),
        "commands": {
            "telegram": {
                "daily_pack": f"/operator_daily_pack days={days} platform={platform} limit={limit}",
                "daily_run_preview": "/operator_daily_run rank=1 execute=0",
                "daily_run_execute": "/operator_daily_run rank=1 execute=1",
                "daily_cycle_preview": "/operator_daily_cycle execute=0 max=3",
                "daily_cycle_execute": "/operator_daily_cycle execute=1 max=3",
                "next_run": f"/operator_next_run days={decision_days} platform={platform} limit={limit}",
                "director": f"/operator_director days={decision_days} platform={platform} limit={limit}",
                "publish_queue": "/publish_queue",
                "performance": "/performance",
                "affiliate_decisions": f"/affiliate_decisions days={decision_days} platform={platform} limit={limit}",
            },
            "api": {
                "daily_pack": f"/api/operator/daily-pack?days={days}&platform={platform}&limit={limit}",
                "daily_run": "/api/operator/daily-run",
                "daily_cycle": "/api/operator/daily-cycle",
                "next_run": f"/api/operator/next-run?days={decision_days}&platform={platform}&limit={limit}",
                "publisher_run": "/api/operator/publisher/run",
                "performance": "/api/operator/performance",
                "affiliate_decisions": f"/api/operator/affiliate-decisions?days={decision_days}&platform={platform}&limit={limit}",
            },
        },
        "rules": [
            "Admin Telegram là người duyệt cuối cùng khi publish manual/OnlyFans/adult/finance-sensitive.",
            "Publisher chỉ dùng API chính thức hoặc handoff manual; không bypass ToS nền tảng.",
            "Mỗi link/comment phải có tracking source riêng để biết link nào hiệu quả.",
            "Không scale dựa trên cảm tính; cần view/click/lead/order/revenue/cost trong performance_events.",
        ],
        "raw_packs": {
            "next_run": next_run,
            "command_center": command_center,
            "publisher": publisher,
            "money": money,
        },
    }

def _machine_action_job_id(action):
    body = action.get("body") or {}
    for key in ("job_id", "job"):
        if body.get(key):
            return safe_int(body.get(key), 0)
    url = action.get("url") or ""
    match = re.search(r"(?:[?&]job_id=|/jobs/)(\d+)", url)
    return safe_int(match.group(1), 0) if match else 0

async def execute_daily_machine_action(
    owner_id,
    days=1,
    platform="tiktok",
    limit=8,
    topic="",
    rank=1,
    execute=False,
    safe_mode=True,
    include_context=True,
    include_prompt=True,
):
    pack = operator_daily_execution_pack_data(owner_id, days=days, platform=platform, limit=limit, topic=topic)
    queue = pack.get("execution_queue") or []
    rank = max(1, min(safe_int(rank, 1), len(queue) or 1))
    item = next((row for row in queue if safe_int(row.get("rank"), 0) == rank), queue[rank - 1] if queue else {})
    action = item.get("machine_action") or {}
    lane = item.get("lane") or ""
    result = {
        "ok": True,
        "executed": False,
        "would_execute": bool(action.get("safe_to_execute")) and not bool(action.get("requires_admin")),
        "rank": rank,
        "lane": lane,
        "item": item,
        "machine_action": action,
        "pack_state": pack.get("state") or {},
        "after_done": action.get("after_success") or "/api/operator/daily-pack",
    }
    if not action:
        result.update({"ok": False, "reason": "no_machine_action"})
        return result
    if safe_mode and (not action.get("safe_to_execute") or action.get("requires_admin")):
        result.update({
            "blocked_by_safe_mode": True,
            "message": action.get("reason") or "Action này cần admin/gate riêng, không chạy tự động.",
        })
        return result
    if not execute:
        result.update({"message": "preview_only"})
        return result

    body = action.get("body") or {}
    if lane == "setup_bootstrap":
        bootstrap = operator_bootstrap_data(
            owner_id,
            include_channels=truthy_value(body.get("channels"), True),
            include_campaigns=truthy_value(body.get("campaigns"), True),
            include_affiliates=truthy_value(body.get("affiliates"), True),
            include_references=truthy_value(body.get("references"), True),
            reference_limit=max(1, min(safe_int(body.get("reference_limit"), 200), 500)),
        )
        result.update({
            "executed": True,
            "kind": "setup_bootstrap",
            "result": bootstrap,
        })
        return result

    if lane == "produce":
        job_id = _machine_action_job_id(action)
        claim = claim_operator_task_payload(
            job_id=job_id,
            tool="",
            include_context=bool(include_context),
            include_prompt=bool(include_prompt),
        )
        result.update({
            "executed": bool(claim.get("task")),
            "kind": "claim_task",
            "result": claim,
        })
        return result

    if lane == "affiliate_growth":
        affiliate_id = safe_int(body.get("affiliate_id"), 0)
        if not affiliate_id:
            result.update({"ok": False, "reason": "missing_affiliate_id"})
            return result
        affiliate = get_affiliate_link(affiliate_id, owner_id)
        if not affiliate:
            result.update({"ok": False, "reason": "affiliate_not_found"})
            return result
        (
            aid, network, product, affiliate_niche, url, note, status,
            price_vnd, commission_rate, audience, allowed_claims, blocked_claims, product_score
        ) = affiliate
        scale_niche = body.get("niche") or affiliate_niche or product or topic or "affiliate"
        campaign_id = safe_int(body.get("campaign_id"), 0)
        matched_campaign = None
        campaign_match_score = 0
        if not campaign_id:
            matched_campaign, campaign_match_score = find_matching_campaign(owner_id, scale_niche, body.get("platform") or platform)
            if matched_campaign:
                campaign_id = matched_campaign[0]
        created_jobs, error = await create_operator_auto_jobs(
            owner_id,
            scale_niche,
            (body.get("platform") or platform or "tiktok").lower(),
            body.get("channel") or "all",
            campaign_id,
            affiliate_id,
            max(1, min(safe_int(body.get("limit"), 3), 12)),
        )
        if error:
            result.update({"ok": False, "reason": error})
            return result
        built = []
        failed = []
        if truthy_value(body.get("build"), False):
            duration = max(15, min(safe_int(body.get("duration"), 45), 120))
            variants = max(3, min(safe_int(body.get("variants"), 5), 8))
            for job in created_jobs:
                ok, bundle = build_operator_job_bundle(owner_id, job["job_id"], count=variants, duration=duration)
                if ok:
                    readiness = bundle.get("readiness") or {}
                    built.append({
                        **job,
                        "manifest_id": bundle["manifest_id"],
                        "task_count": len(bundle["task_ids"]),
                        "variant_id": bundle["best_variant_id"],
                        "readiness": readiness.get("level", "UNKNOWN") if isinstance(readiness, dict) else "UNKNOWN",
                    })
                else:
                    failed.append({"job_id": job["job_id"], "error": bundle.get("error", "build lỗi")})
        result.update({
            "executed": True,
            "kind": "affiliate_scale",
            "result": {
                "affiliate": {"id": aid, "network": network, "product": product, "niche": affiliate_niche, "url": url},
                "scale_niche": scale_niche,
                "campaign": {
                    "id": campaign_id,
                    "auto_matched": bool(matched_campaign),
                    "match_score": campaign_match_score,
                    "name": matched_campaign[1] if matched_campaign else "",
                },
                "created_jobs": created_jobs,
                "built_jobs": built,
                "failed_builds": failed,
                "worker_next": operator_worker_next_summary(owner_id, [job["job_id"] for job in (built or created_jobs)], limit=5),
            },
        })
        return result

    if lane == "launch":
        ok, reason, launch = await operator_launch_pipeline(
            owner_id,
            body.get("topic") or topic or "công nghệ AI",
            platform=body.get("platform") or platform,
            channel=body.get("channel") or "all",
            affiliate_id=safe_int(body.get("affiliate_id"), 0),
            campaign_id=safe_int(body.get("campaign_id"), 0),
            limit=max(1, min(safe_int(body.get("limit"), 3), 8)),
            build=truthy_value(body.get("build"), True),
            duration=max(15, min(safe_int(body.get("duration"), 45), 120)),
            variants=max(3, min(safe_int(body.get("variants"), 5), 8)),
            bootstrap=truthy_value(body.get("bootstrap"), True),
        )
        result.update({"executed": bool(ok), "kind": "launch", "reason": reason, "result": launch})
        return result

    result.update({
        "blocked_by_policy": True,
        "message": f"Lane {lane or 'unknown'} chưa có executor tự động; dùng Telegram/API trong item.",
    })
    return result

async def operator_daily_cycle_data(
    owner_id,
    days=1,
    platform="tiktok",
    limit=8,
    topic="",
    max_steps=3,
    execute=False,
    safe_mode=True,
    include_context=True,
    include_prompt=True,
):
    days = max(1, min(safe_int(days, 1), 30))
    limit = max(3, min(safe_int(limit, 8), 20))
    max_steps = max(1, min(safe_int(max_steps, 3), 10))
    platform = (platform or "tiktok").lower()
    topic = (topic or "").strip()
    steps = []
    stop_reason = "max_steps_reached"
    for index in range(1, max_steps + 1):
        step = await execute_daily_machine_action(
            owner_id,
            days=days,
            platform=platform,
            limit=limit,
            topic=topic,
            rank=1,
            execute=execute,
            safe_mode=safe_mode,
            include_context=include_context,
            include_prompt=include_prompt,
        )
        step["cycle_step"] = index
        steps.append(step)
        if step.get("blocked_by_safe_mode"):
            stop_reason = f"gate:safe:{step.get('lane') or 'unknown'}"
            break
        if step.get("blocked_by_policy"):
            stop_reason = f"gate:policy:{step.get('lane') or 'unknown'}"
            break
        if not step.get("ok", True):
            stop_reason = f"error:{step.get('reason') or 'unknown'}"
            break
        if not execute:
            stop_reason = "preview_only"
            break
        if not step.get("executed"):
            stop_reason = f"not_executed:{step.get('lane') or 'unknown'}"
            break
        if step.get("lane") == "produce":
            stop_reason = "worker_claimed_task_waiting_output"
            break
    final_pack = operator_daily_execution_pack_data(owner_id, days=days, platform=platform, limit=limit, topic=topic)
    return {
        "ok": True,
        "generated_at": now_text(),
        "execute": bool(execute),
        "safe_mode": bool(safe_mode),
        "days": days,
        "platform": platform,
        "topic": topic,
        "limit": limit,
        "max_steps": max_steps,
        "steps": steps,
        "executed_count": len([item for item in steps if item.get("executed")]),
        "stop_reason": stop_reason,
        "final_state": final_pack.get("state") or {},
        "next_machine_action": final_pack.get("next_machine_action") or {},
        "next": {
            "daily_pack": "/api/operator/daily-pack",
            "daily_run": "/api/operator/daily-run",
            "daily_cycle": "/api/operator/daily-cycle",
            "telegram": "/operator_daily_pack",
        },
        "rule": "Daily cycle chỉ chạy safe actions. Setup/review/publish/consent gate luôn dừng chờ admin; produce chỉ claim task rồi dừng để worker tạo output thật.",
    }

