def build_manifest_prompt(job, variant=None, duration=45):
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    variant_text = "Chưa chọn creative variant."
    if variant:
        _, _, label, hook, angle, caption, cta, hashtags, score, v_status, v_note = variant
        variant_text = (
            f"Variant #{variant[0]} / {label or '-'} / score={score or 0}\n"
            f"Hook: {hook or '-'}\n"
            f"Angle: {angle or '-'}\n"
            f"Caption: {caption or '-'}\n"
            f"CTA: {cta or '-'}\n"
            f"Hashtags: {hashtags or '-'}"
        )
    pattern = select_video_pattern(job, duration)
    references = select_reference_examples_for_job(ADMIN_ID, job, limit=3)
    reference_lines = []
    for ref in references:
        reference_lines.append(
            f"- {ref.get('title') or '-'} | source={ref.get('path_or_url') or '-'} | "
            f"pattern={ref.get('pattern_hint') or '-'} | tags={ref.get('tags') or '-'}"
        )
    reference_text = "\n".join(reference_lines) if reference_lines else "Chưa có reference cụ thể; dùng video pattern bank."
    return (
        "Bạn là AI production director cho video ngắn affiliate. Hãy tạo PRODUCTION MANIFEST dạng JSON thuần, "
        "để Claude/Gemini/Runway/Kling/Fish/CapCut/FFmpeg có thể thực thi từng bước. "
        "Không spam, không mạo danh, không cam kết thu nhập phi thực tế. Với AI influencer/OnlyFans/người mẫu, "
        "chỉ dùng nhân vật tự tạo hoặc người thật có consent rõ ràng, đủ 18 tuổi.\n\n"
        f"Job ID: #{jid}\n"
        f"Nền tảng: {platform or '-'} | Tỷ lệ: 9:16 | Độ dài mục tiêu: {duration}s\n"
        f"Kênh/account: {channel_name or channel_id or '-'} / {account_label or 'main'}\n"
        f"Topic: {topic or '-'}\n"
        f"Affiliate: {network or '-'} - {product_name or '-'} - {affiliate_url or '-'}\n"
        f"Asset hiện có: {asset_url or 'chưa có'}\n"
        f"Operator note: {note or '-'}\n\n"
        f"Creative variant:\n{variant_text}\n\n"
        f"Video pattern bắt buộc áp dụng:\n{format_video_pattern_for_prompt(pattern)}\n\n"
        f"Reference videos được phép học format, không copy asset:\n{reference_text}\n\n"
        f"Brief:\n{brief or 'Chưa có brief'}\n\n"
        "JSON schema bắt buộc:\n"
        "{\n"
        '  "title": "...",\n'
        '  "duration_sec": 45,\n'
        '  "format": "9:16",\n'
        '  "video_pattern": {"id":"proof_first_demo","name":"...","hook_formula":"..."},\n'
        '  "reference_examples_used": [{"title":"...","source":"...","learned_structure":"...","rewrite_rule":"..."}],\n'
        '  "proof_assets_required": ["..."],\n'
        '  "selected_variant_id": 0,\n'
        '  "voice": {"provider_primary":"Fish Audio HD","provider_fallback":"Edge TTS","style":"...","script":"..."},\n'
        '  "scenes": [\n'
        '    {"scene":1,"start":0,"end":5,"goal":"hook","visual_prompt":"...","video_tool":"kling|runway","on_screen_text":"...","voice_line":"...","asset_needed":"..."}\n'
        "  ],\n"
        '  "edit_instructions": {"tool":"capcut|ffmpeg","music":"...","subtitle":"...","transitions":"...","cta_overlay":"..."},\n'
        '  "publish": {"caption":"...","hashtags":"...","affiliate_placement":"...","cta":"..."},\n'
        '  "compliance_checklist": ["..."],\n'
        '  "handoff_order": ["claude","kling","fish","capcut","review_gate"]\n'
        "}"
    )

def parse_job_brief_object(brief_text):
    try:
        parsed = json.loads(brief_text or "{}")
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}

def build_character_bible(topic, genre="", audience=""):
    topic = (topic or "AI film series").strip()
    genre = (genre or "drama cảm xúc").strip()
    audience = (audience or "người lớn").strip()
    base_negative = (
        "real person likeness, celebrity likeness, non-consensual face, deepfake, watermark, logo, "
        "brand asset, text, distorted anatomy, extra fingers, inconsistent face, underage, sexualized minor"
    )
    return {
        "lead": {
            "fixed_description": (
                f"Fictional Vietnamese lead character for topic '{topic}', {genre}, created from scratch, "
                "consistent face, age 25+, consistent outfit palette, cinematic realistic look, mobile-first framing"
            ),
            "wardrobe": "simple modern Vietnamese outfit, neutral colors, no visible brand logo",
            "personality": "empathetic, curious, resilient, credible for the target audience",
            "audience": audience,
            "negative_prompt": base_negative,
            "continuity_rules": [
                "Keep the same face, age, outfit style and body proportions across every scene.",
                "Do not imitate any real person, influencer, actor, customer, or competitor.",
                "No copyrighted logo, watermark, copied text, or recognizable third-party asset.",
            ],
        },
        "support": {
            "fixed_description": (
                "Fictional Vietnamese supporting character, age 25+, natural expression, consistent appearance, "
                "realistic cinematic style"
            ),
            "wardrobe": "plain outfit, no brand marks",
            "personality": "contrasting emotion that supports the story conflict",
            "negative_prompt": base_negative,
            "continuity_rules": [
                "Support character must remain visually distinct from the lead.",
                "Never clone a real person's face or voice without explicit consent.",
            ],
        },
    }

def build_scene_manifest(series_title, episode_no, scene_no, topic, character_bible, platform, duration):
    series_title = (series_title or topic or "AI Film Series").strip()
    topic = (topic or series_title).strip()
    platform = (platform or "tiktok").strip().lower()
    scene_no = max(1, int(scene_no or 1))
    duration_seconds = max(4, min(int(duration or 8), 20))
    bible = character_bible or build_character_bible(topic)
    lead = ((bible.get("lead") or {}).get("fixed_description") or "fictional Vietnamese lead character")
    negative = "; ".join(filter(None, [
        (bible.get("lead") or {}).get("negative_prompt"),
        (bible.get("support") or {}).get("negative_prompt"),
        "watermark, copied video, copied voice, copied text",
    ]))
    hook = scene_no == 1
    goal = "hook mở đầu tạo tò mò trong 1-3 giây" if hook else f"đẩy câu chuyện và cảm xúc cảnh {scene_no}"
    affiliate_cta = "Disclosure affiliate nhẹ ở caption/comment, không phá mạch phim." if scene_no >= 7 else ""
    visual_prompt = (
        f"Vertical 9:16 cinematic Vietnamese AI short film for {platform}. Series '{series_title}', "
        f"episode {episode_no}, scene {scene_no}. Topic: {topic}. Goal: {goal}. "
        f"Lead continuity: {lead}. Natural lighting, clear emotion, realistic action, no logo, no watermark. "
        f"Negative prompt: {negative}."
    )
    scene = {
        "scene": scene_no,
        "duration_seconds": duration_seconds,
        "hook": hook,
        "visual_prompt": visual_prompt,
        "image_prompt": visual_prompt + " Generate one clean storyboard keyframe.",
        "video_prompt": (
            f"Animate for {duration_seconds}s, slow push-in camera, realistic Vietnamese drama pacing. "
            f"Show {goal}. Keep all characters fictional and visually consistent."
        ),
        "voice_line": (
            f"Không ai ngờ câu chuyện này lại bắt đầu từ một chi tiết nhỏ."
            if hook else f"Cảnh {scene_no}: một lựa chọn mới làm câu chuyện đổi hướng."
        ),
        "caption": f"{series_title} - tập {episode_no}, cảnh {scene_no}. Nội dung AI có affiliate disclosure khi đăng.",
        "negative_prompt": negative,
        "camera": "slow push-in, subtle handheld, vertical close-up",
        "emotion": "curious, tense, emotional",
        "affiliate_cta_optional": affiliate_cta,
        "status": "draft",
    }
    scene["quality_score"] = score_video_prompt_quality(scene)
    return scene

def score_video_prompt_quality(scene_manifest):
    risk_blob = " ".join(str(scene_manifest.get(key) or "") for key in (
        "visual_prompt", "image_prompt", "video_prompt", "voice_line", "caption", "affiliate_cta_optional"
    )).lower()
    risk_blob = re.sub(r"negative prompt\s*:\s*[^.。]+[.。]?", "", risk_blob)
    risk_blob = re.sub(r"negative constraints\s*:\s*[^.。]+[.。]?", "", risk_blob)
    full_blob = json.dumps(scene_manifest or {}, ensure_ascii=False).lower()
    hook_score = 85 if scene_manifest.get("hook") or "hook" in full_blob or "tò mò" in full_blob else 65
    viral_score = 78 if any(word in full_blob for word in ["bí mật", "twist", "cảm xúc", "tò mò", "cliffhanger", "viral"]) else 62
    clarity_score = 85 if len((scene_manifest.get("video_prompt") or "")) >= 80 and len((scene_manifest.get("visual_prompt") or "")) >= 120 else 55
    affiliate_fit_score = 76 if "affiliate" in full_blob or "cta" in full_blob or "link" in full_blob else 58
    visual_feasibility_score = 82
    risky_terms = ["clone real person", "celebrity likeness", "deepfake", "underage", "mạo danh người thật", "impersonate"]
    copy_terms = ["copy nguyên", "reup", "download lại", "watermark thật", "brand asset thật"]
    copyright_risk_score = 85 if any(term in risk_blob for term in copy_terms) else 20
    policy_risk_score = 90 if any(term in risk_blob for term in risky_terms) else 25
    if policy_risk_score > 70 or copyright_risk_score > 70:
        decision = "block"
    elif hook_score < 60 or visual_feasibility_score < 60 or clarity_score < 60:
        decision = "rewrite"
    else:
        decision = "pass"
    return {
        "hook_score": hook_score,
        "viral_score": viral_score,
        "clarity_score": clarity_score,
        "affiliate_fit_score": affiliate_fit_score,
        "visual_feasibility_score": visual_feasibility_score,
        "copyright_risk_score": copyright_risk_score,
        "policy_risk_score": policy_risk_score,
        "decision": decision,
    }

def rewrite_low_score_scene(scene_manifest, reason):
    scene = dict(scene_manifest or {})
    reason = (reason or "score_low").strip()
    scene["hook"] = bool(scene.get("hook") or scene.get("scene") == 1)
    scene["video_prompt"] = (
        f"{scene.get('video_prompt') or ''} Rewrite for clarity and original execution. "
        "Use one clear action, one visible emotion, no copied asset, no real-person likeness, no watermark."
    ).strip()
    scene["visual_prompt"] = (
        f"{scene.get('visual_prompt') or ''} Original fictional characters only, stronger mobile framing, "
        "clean background, consistent face/outfit, no brand logo."
    ).strip()
    scene["caption"] = (scene.get("caption") or "") + " #AIvideo #affiliate"
    scene["rewrite_reason"] = reason
    scene["quality_score"] = score_video_prompt_quality(scene)
    return scene

def build_film_series_manifest(owner_id, topic, platform="tiktok", episodes=3, scenes_per_episode=8, duration=60, affiliate_id=0, campaign_id=0):
    topic = (topic or "").strip()
    if not topic:
        return {"ok": False, "reason": "missing_topic"}
    episodes = max(1, min(int(episodes or 3), 8))
    scenes_per_episode = max(3, min(int(scenes_per_episode or 8), 12))
    duration = max(30, min(int(duration or 60), 180))
    series_title = f"{topic[:80]} - TOAN AAS AI Series"
    character_bible = build_character_bible(topic)
    created = []
    for ep in range(1, episodes + 1):
        job_id = create_production_job(
            owner_id,
            0,
            int(campaign_id or 0),
            0,
            int(affiliate_id or 0),
            platform,
            f"Tập {ep}/{episodes}: {topic}",
            json.dumps({
                "type": "ai_film_series_episode",
                "series_title": series_title,
                "topic": topic,
                "episode_number": ep,
                "episode_count": episodes,
                "duration_seconds": duration,
                "scenes_per_episode": scenes_per_episode,
                "character_bible": character_bible,
            }, ensure_ascii=False),
            "build_film_series_manifest",
        )
        scene_duration = max(4, int(duration / scenes_per_episode))
        scenes = [
            build_scene_manifest(series_title, ep, scene_no, topic, character_bible, platform, scene_duration)
            for scene_no in range(1, scenes_per_episode + 1)
        ]
        for scene in scenes:
            score = scene.get("quality_score") or {}
            if score.get("decision") == "rewrite":
                scene.update(rewrite_low_score_scene(scene, "auto_rewrite_before_render"))
            elif score.get("decision") == "block":
                record_tool_event(owner_id, "prompt_gate", "policy_guard", "blocked", "critical", job_id, 0, "", "Prompt risk blocked before render")
        manifest = {
            "type": "film_series_episode",
            "series_title": series_title,
            "episode_number": ep,
            "platform": platform,
            "aspect_ratio": "9:16",
            "duration_seconds": duration,
            "character_bible": character_bible,
            "scenes": scenes,
            "review_gate": {
                "required": True,
                "status": "ready_for_review",
                "approve_command": f"/film_approve job={job_id}",
                "rewrite_command": f"/film_rewrite job={job_id} scene=<n>",
            },
            "compliance": [
                "Fictional characters only unless consent is documented.",
                "No copied reference video, voice, watermark, or brand asset.",
                "Affiliate disclosure required before publish.",
                "Admin approval required before publish_queue.",
            ],
        }
        ok, manifest_id = save_production_manifest(owner_id, job_id, 0, json.dumps(manifest, ensure_ascii=False), status="ready_for_review")
        task_ids = []
        if ok:
            task_ids = create_tasks_from_manifest(owner_id, get_production_manifest(owner_id, manifest_id))
        update_production_job(job_id, owner_id, stage="review", status="ready_for_review", note=f"film_series_manifest manifest={manifest_id}")
        created.append({"job_id": job_id, "episode": ep, "manifest_id": manifest_id, "task_ids": task_ids})
    return {
        "ok": True,
        "series_title": series_title,
        "topic": topic,
        "platform": platform,
        "episodes": episodes,
        "scenes_per_episode": scenes_per_episode,
        "duration_seconds": duration,
        "character_bible": character_bible,
        "created": created,
        "rule": "Chỉ tạo manifest/task và review gate; không render/publish tự động.",
    }

def analyze_reference_video_structure(owner_id, reference_text_or_url, platform="tiktok"):
    source = (reference_text_or_url or "").strip()
    platform = (platform or "tiktok").strip().lower()
    lower = source.lower()
    scene_count = 8 if any(word in lower for word in ["series", "storyboard", "10 cảnh", "10 canh"]) else 5
    hook_type = "curiosity_gap" if any(word in lower for word in ["đừng bấm", "dung bam", "bí mật", "bi mat", "cơ hội", "co hoi"]) else "problem_solution"
    return {
        "owner_id": str(owner_id),
        "source": source,
        "platform": platform,
        "hook_type": hook_type,
        "scene_count": scene_count,
        "pacing": "fast mobile cuts, 1-3s hook, short proof blocks, clear CTA",
        "emotion_curve": ["curiosity", "problem tension", "proof", "relief", "CTA"],
        "cta_style": "soft affiliate CTA with disclosure in caption/comment/status",
        "content_pattern": "learn structure only; create new characters, new setting, new wording, new assets",
        "do_not_copy": ["face", "voice", "watermark", "caption text", "brand/logo asset", "exact scene order"],
        "next": {
            "build_original": f"/reference_build niche=<niche> platform={platform}",
            "viral_remix": f"/viral_remix url={source} topic=<niche> platform={platform}" if source.startswith("http") else "/viral_remix topic=<niche>",
        },
    }

def build_original_variation_from_reference(owner_id, reference_analysis, niche, affiliate_id=0):
    analysis = reference_analysis or {}
    niche = (niche or "affiliate sản phẩm phù hợp").strip()
    character_bible = build_character_bible(niche, genre="affiliate short drama")
    scenes = []
    for scene_no in range(1, int(analysis.get("scene_count") or 5) + 1):
        scene = build_scene_manifest(
            f"{niche} - Original Variation",
            1,
            scene_no,
            niche,
            character_bible,
            analysis.get("platform") or "tiktok",
            8,
        )
        scene["learned_structure"] = analysis.get("hook_type") if scene_no == 1 else analysis.get("pacing")
        scenes.append(scene)
    return {
        "owner_id": str(owner_id),
        "niche": niche,
        "affiliate_id": int(affiliate_id or 0),
        "reference_learning": analysis,
        "character_bible": character_bible,
        "scenes": scenes,
        "caption": f"Nội dung AI gợi ý lựa chọn trong ngách {niche}. Có thể có affiliate disclosure khi đăng.",
        "rule": "Biến ý tưởng thành sản phẩm mới; không copy người/giọng/text/watermark/asset của video tham khảo.",
    }

def film_review_pack_data(owner_id, job_id):
    job = get_production_job(job_id, owner_id)
    if not job:
        return {"ok": False, "reason": "job_not_found"}
    manifests = list_production_manifests(owner_id, job_id, limit=1)
    tasks = list_production_tasks(owner_id, job_id=job_id, limit=120)
    manifest_obj = {}
    if manifests:
        try:
            manifest_obj = json.loads(manifests[0][3] or "{}")
        except Exception:
            manifest_obj = {"raw": manifests[0][3]}
    scene_scores = []
    for scene in manifest_obj.get("scenes", []) if isinstance(manifest_obj, dict) else []:
        scene_scores.append({
            "scene": scene.get("scene"),
            "score": scene.get("quality_score") or score_video_prompt_quality(scene),
            "caption": scene.get("caption"),
        })
    review = {
        "ok": True,
        "job_id": job_id,
        "job": serialize_production_job(job),
        "manifest_id": manifests[0][0] if manifests else 0,
        "manifest_status": manifests[0][2] if manifests else "missing",
        "scene_scores": scene_scores,
        "task_count": len(tasks),
        "tasks": [serialize_operator_task(get_production_task(owner_id, row[0])) for row in tasks[:20]],
        "risk_flags": [
            score for score in scene_scores
            if (score.get("score") or {}).get("decision") in {"rewrite", "block"}
        ],
        "commands": {
            "approve": f"/film_approve job={job_id}",
            "rewrite": f"/film_rewrite job={job_id} scene=<n>",
            "review_video": f"/review_video job={job_id} send=1",
            "approve_publish": f"/approve_publish job={job_id} queue=1 mode=manual",
        },
        "rule": "Admin review trước khi render/publish; publish vẫn qua approve gate.",
    }
    return review

def film_series_manifest_from_brief(job, variant=None, duration=80):
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    brief_obj = parse_job_brief_object(brief)
    if brief_obj.get("type") != "ai_film_series_episode":
        return None
    scene_count = max(3, min(int(brief_obj.get("scenes_per_episode") or 10), 12))
    duration = max(30, min(int(brief_obj.get("duration_seconds") or duration or 80), 180))
    segment = max(4, int(duration / scene_count))
    episode_no = int(brief_obj.get("episode_number") or 1)
    episode_total = int(brief_obj.get("episode_count") or 1)
    episode_title = brief_obj.get("episode_title") or topic or f"Tập {episode_no}"
    series_title = brief_obj.get("series_title") or topic or "AI Film Affiliate Series"
    genre = brief_obj.get("genre") or "drama cảm xúc"
    audience = brief_obj.get("target_audience") or "người lớn"
    character_bible = brief_obj.get("character_bible") or {}
    lead = ((character_bible.get("lead") or {}).get("fixed_description") or "Vietnamese main character, consistent face, cinematic realistic look")
    support = ((character_bible.get("support") or {}).get("fixed_description") or "Vietnamese supporting character, consistent look, cinematic realistic look")
    negative = "; ".join(filter(None, [
        (character_bible.get("lead") or {}).get("negative_prompt"),
        (character_bible.get("support") or {}).get("negative_prompt"),
        "text, watermark, distorted anatomy, extra fingers, inconsistent face",
    ]))
    affiliate = brief_obj.get("affiliate") or {}
    affiliate_name = affiliate.get("product") or product_name or "sản phẩm phù hợp"
    affiliate_link = affiliate.get("url") or affiliate_url or "tracking link trong publish pack"
    episode_arc = brief_obj.get("episode_arc") or [
        "Hook mạnh, tạo tò mò ngay 1-3 giây đầu.",
        "Giới thiệu bối cảnh và nhân vật chính.",
        "Đặt vấn đề hoặc hiểu lầm.",
        "Đẩy xung đột bằng hành động rõ.",
        "Cho thấy cảm xúc nhân vật.",
        "Tăng cao trào hoặc twist nhỏ.",
        "Hé lộ một phần sự thật.",
        "Gắn sản phẩm/link affiliate thật mềm theo ngữ cảnh.",
        "Payoff cảm xúc hoặc bài học.",
        "Cliffhanger kéo sang tập sau.",
    ]
    scenes = []
    for idx in range(1, scene_count + 1):
        goal = episode_arc[min(idx - 1, len(episode_arc) - 1)]
        if idx == 1:
            goal = "Hook mạnh: " + str(goal)
        elif idx == scene_count:
            goal = brief_obj.get("cliffhanger_rule") or "Cliffhanger kéo sang tập sau."
        start = 0 if idx == 1 else min(duration - 1, (idx - 1) * segment)
        end = duration if idx == scene_count else min(duration, idx * segment)
        on_screen = (
            f"Tập {episode_no}: chuyện gì xảy ra?"
            if idx == 1 else
            (f"Link gợi ý ở bình luận" if idx == scene_count else str(goal)[:48])
        )
        voice_line = (
            f"{episode_title}. Không ai ngờ một lựa chọn nhỏ lại mở ra bí mật thay đổi tất cả."
            if idx == 1 else
            (f"Nếu bạn muốn thử giải pháp liên quan, xem link affiliate minh bạch ở phần bình luận hoặc mô tả." if idx == scene_count else f"Cảnh {idx}: {goal}")
        )
        visual_prompt = (
            f"Vertical 9:16 Vietnamese cinematic {genre}, episode {episode_no}/{episode_total} of '{series_title}'. "
            f"Scene {idx}: {goal}. Characters must stay consistent: lead={lead}; support={support}. "
            f"Audience={audience}. Emotional realistic lighting, clear action, mobile-first framing, no copyrighted logo, no text in generated image/video. "
            f"Negative prompt: {negative}."
        )
        scenes.append({
            "scene": idx,
            "start": start,
            "end": end,
            "goal": str(goal),
            "visual_prompt": visual_prompt,
            "image_prompt": visual_prompt + " Produce one clean storyboard keyframe.",
            "video_prompt": (
                f"Animate scene {idx} for {max(4, end - start)} seconds. Camera movement: slow push-in or subtle handheld drama. "
                f"Action must match: {goal}. Keep same characters, same outfit, same face, realistic Vietnamese short film style."
            ),
            "video_tool": "kling",
            "on_screen_text": on_screen,
            "voice_line": voice_line,
            "asset_needed": f"episode_{episode_no:02d}_scene_{idx:02d}.mp4",
        })
    hook = scenes[0]["voice_line"] if scenes else episode_title
    caption = (
        f"{episode_title}\n"
        f"Đây là nội dung AI affiliate, link chỉ là gợi ý nếu phù hợp nhu cầu.\n"
        f"Link liên quan: {affiliate_link}"
    )
    return {
        "title": episode_title,
        "series_title": series_title,
        "episode_number": episode_no,
        "episode_count": episode_total,
        "duration_sec": duration,
        "format": "9:16",
        "video_pattern": {
            "id": "ai_film_series_episode",
            "name": "AI film series episode",
            "hook_formula": "bí mật/xung đột cảm xúc trong 1-3 giây đầu, cliffhanger cuối tập",
            "cta_style": "affiliate disclosure mềm, không phá mạch phim",
        },
        "character_bible": character_bible,
        "reference_examples_used": [],
        "proof_assets_required": [
            "affiliate link đúng sản phẩm/ngách",
            "caption có disclosure affiliate",
            "nhân vật AI nhất quán và không mạo danh người thật",
        ],
        "selected_variant_id": variant[0] if variant else 0,
        "voice": {
            "provider_primary": "Fish Audio HD",
            "provider_fallback": "Edge TTS",
            "style": "giọng kể phim ngắn Việt Nam, cảm xúc nhưng rõ chữ, nhịp nhanh vừa",
            "script": " ".join(scene["voice_line"] for scene in scenes),
        },
        "scenes": scenes,
        "edit_instructions": {
            "tool": "capcut|ffmpeg",
            "music": "nhạc nền cinematic hợp lệ, âm lượng thấp",
            "subtitle": "burn subtitle tiếng Việt, 2 dòng tối đa, không che mặt nhân vật",
            "transitions": "cut theo nhịp cảm xúc, không lạm dụng hiệu ứng",
            "cta_overlay": "Link gợi ý ở bình luận/mô tả - nội dung affiliate",
        },
        "publish": {
            "caption": caption,
            "hashtags": "#phimAI #AIvideo #affiliate #TOANAAS",
            "affiliate_placement": "caption/comment/status/bio theo distribution_pack",
            "cta": "Xem link gợi ý nếu phù hợp nhu cầu.",
        },
        "compliance_checklist": [
            "Không mạo danh người thật hoặc dùng ảnh/giọng người thật thiếu consent.",
            "Không copy nguyên nội dung/video/voice/reference của người khác.",
            "Không hứa kết quả tài chính/sức khỏe/chính sách chắc chắn.",
            "Có disclosure affiliate trong caption/comment/status.",
            "Final video phải được review trước khi approve publish.",
        ],
        "handoff_order": ["claude_storyboard", "kling_scene_video", "fish_voice", "capcut_edit", "review_gate", "publisher_handoff"],
        "source_brief": brief_obj,
    }

def fallback_production_manifest(job, variant=None, duration=45):
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    film_manifest = film_series_manifest_from_brief(job, variant, duration)
    if film_manifest:
        return film_manifest
    hook = topic or "video affiliate"
    caption = f"{topic or 'Nội dung mới'} - xem link gợi ý trong bio/mô tả."
    cta = "Xem link affiliate trong bio/mô tả nếu phù hợp nhu cầu."
    hashtags = "#AI #review #affiliate"
    selected_variant_id = 0
    if variant:
        selected_variant_id = variant[0]
        hook = variant[3] or hook
        caption = variant[5] or caption
        cta = variant[6] or cta
        hashtags = variant[7] or hashtags
    pattern = select_video_pattern(job, duration)
    references = select_reference_examples_for_job(ADMIN_ID, job, limit=3)
    goals = pattern.get("scene_goals") or ["hook", "problem", "demo", "benefit", "cta"]
    scene_count = max(3, min(6, len(goals)))
    scenes = []
    segment = max(3, int(duration / scene_count))
    for idx, goal in enumerate(goals[:scene_count], start=1):
        start = 0 if idx == 1 else min(duration - 1, (idx - 1) * segment)
        end = duration if idx == scene_count else min(duration, idx * segment)
        scenes.append({
            "scene": idx,
            "start": start,
            "end": end,
            "goal": goal,
            "visual_prompt": f"Vertical 9:16 {pattern.get('name')} scene about {topic or product_name or 'AI affiliate product'}, clean realistic creator style, proof-oriented, no impersonation, no copyrighted likeness.",
            "video_tool": "kling",
            "on_screen_text": hook if idx == 1 else (product_name or topic or "TOAN AAS"),
            "voice_line": hook if idx == 1 else f"Giải thích ngắn về {topic or product_name or 'sản phẩm'} theo góc {goal}.",
            "asset_needed": f"scene_{idx}_video.mp4",
        })
    return {
        "title": topic or "Affiliate short video",
        "duration_sec": duration,
        "format": "9:16",
        "video_pattern": {
            "id": pattern.get("id"),
            "name": pattern.get("name"),
            "hook_formula": pattern.get("hook_formula"),
            "cta_style": pattern.get("cta_style"),
        },
        "reference_examples_used": [
            {
                "title": ref.get("title"),
                "source": ref.get("path_or_url"),
                "pattern_hint": ref.get("pattern_hint"),
                "match_score": ref.get("match_score"),
                "rewrite_rule": ref.get("apply_rule"),
            }
            for ref in references
        ],
        "proof_assets_required": pattern.get("proof_assets_required") or [],
        "selected_variant_id": selected_variant_id,
        "voice": {
            "provider_primary": "Fish Audio HD",
            "provider_fallback": "Edge TTS",
            "style": "giọng Việt rõ, nhanh vừa, đáng tin",
            "script": " ".join(scene["voice_line"] for scene in scenes),
        },
        "scenes": scenes,
        "edit_instructions": {
            "tool": "capcut|ffmpeg",
            "music": "nhạc nền hợp lệ, âm lượng thấp",
            "subtitle": "burn subtitle tiếng Việt, chữ rõ trên mobile",
            "transitions": "cut nhanh, không rối",
            "cta_overlay": cta,
        },
        "publish": {
            "caption": caption,
            "hashtags": hashtags,
            "affiliate_placement": affiliate_url or "bio/mô tả",
            "cta": cta,
        },
        "compliance_checklist": [
            "Không mạo danh người thật/brand.",
            "Không cam kết thu nhập/kết quả phi thực tế.",
            "Affiliate CTA minh bạch.",
            "Asset hình/voice/nhạc có quyền dùng.",
        ],
        "handoff_order": ["claude", "kling", "fish", "capcut", "review_gate"],
    }

def parse_manifest_json(raw_text, job, variant=None, duration=45):
    pattern = select_video_pattern(job, duration)
    try:
        parsed = json.loads(raw_text)
        if isinstance(parsed, dict) and parsed.get("scenes"):
            parsed.setdefault("video_pattern", {
                "id": pattern.get("id"),
                "name": pattern.get("name"),
                "hook_formula": pattern.get("hook_formula"),
                "cta_style": pattern.get("cta_style"),
            })
            parsed.setdefault("reference_examples_used", select_reference_examples_for_job(ADMIN_ID, job, limit=3))
            parsed.setdefault("proof_assets_required", pattern.get("proof_assets_required") or [])
            return parsed
    except Exception:
        pass
    manifest = fallback_production_manifest(job, variant, duration)
    if raw_text:
        manifest["ai_raw_unparsed"] = truncate_text(raw_text, 1200)
    return manifest

def create_manifest_for_job(owner_id, job, variant=None, duration=45):
    job_id = job[0]
    if gemini_client or openai_client:
        raw = AgentGemini.chat(
            "Bạn là AI production director tạo production manifest JSON cho video affiliate.",
            build_manifest_prompt(job, variant, duration),
            owner_id,
            is_json=False
        )
        manifest = parse_manifest_json(raw, job, variant, duration)
    else:
        manifest = fallback_production_manifest(job, variant, duration)
    manifest["job_id"] = job_id
    manifest["generated_at"] = now_text()
    manifest["tool_policy"] = "premium_first_then_fallback"
    manifest_json = json.dumps(manifest, ensure_ascii=False, indent=2)
    ok, manifest_id = save_production_manifest(
        owner_id,
        job_id,
        variant[0] if variant else 0,
        manifest_json,
        "draft"
    )
    return ok, manifest_id, manifest

def build_manifest_handoff_prompt(job, manifest_row, target_tool):
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    manifest_id, _, variant_id, manifest_status, manifest_json, created_at, updated_at = manifest_row
    try:
        manifest = json.loads(manifest_json or "{}")
    except Exception:
        manifest = {}
    target_tool = (target_tool or "claude").lower()
    scenes = manifest.get("scenes") or []
    voice = manifest.get("voice") or {}
    edit = manifest.get("edit_instructions") or {}
    publish = manifest.get("publish") or {}
    compliance = manifest.get("compliance_checklist") or []
    video_pattern = manifest.get("video_pattern") or {}
    proof_assets = manifest.get("proof_assets_required") or []
    title = manifest.get("title") or topic or f"job #{jid}"
    common = (
        f"VAI TRÒ: Bạn là {target_tool.upper()} trong AI Operator TOAN AAS.\n"
        f"Manifest: #{manifest_id} | Job: #{jid} | Variant: {variant_id or '-'} | Platform: {platform or '-'} | Format: {manifest.get('format','9:16')}\n"
        f"Title: {title}\n"
        f"Affiliate: {network or '-'} / {product_name or '-'} / {affiliate_url or '-'}\n\n"
        f"VIDEO PATTERN: {video_pattern.get('id','-')} - {video_pattern.get('name','-')}\n"
        f"Hook formula: {video_pattern.get('hook_formula','-')}\n"
        "Proof cần có:\n" + "\n".join(f"- {item}" for item in proof_assets[:6]) + "\n\n"
        "QUY TẮC:\n"
        "- Ưu tiên công cụ tốt/có phí trước, nếu lỗi/quota/hết tiền thì ghi fallback và báo admin.\n"
        "- Không spam, không mạo danh, không dùng likeness/người thật nếu chưa có consent rõ ràng, đủ 18 tuổi.\n"
        "- Không cam kết thu nhập/kết quả phi thực tế; affiliate CTA phải minh bạch.\n"
        "- Output phải có file/link/asset cần lưu vào /asset_add hoặc trạng thái cần cập nhật bằng /pipeline_set.\n\n"
    )
    if target_tool in {"kling", "runway", "pika", "luma", "visuals"}:
        scene_lines = []
        for scene in scenes:
            scene_lines.append(
                f"SCENE {scene.get('scene')} ({scene.get('start')}-{scene.get('end')}s, {scene.get('goal')}):\n"
                f"Visual prompt: {scene.get('visual_prompt')}\n"
                f"On-screen text: {scene.get('on_screen_text')}\n"
                f"Voice line: {scene.get('voice_line')}\n"
                f"Asset cần xuất: {scene.get('asset_needed')}"
            )
        return (
            common +
            "NHIỆM VỤ VISUAL VIDEO:\n"
            "Tạo từng scene video 9:16 theo prompt. Giữ style nhất quán, không dùng logo/nhân vật bản quyền khi chưa có quyền.\n\n"
            + "\n\n".join(scene_lines) +
            "\n\nOUTPUT:\n"
            "1. Link/file từng scene.\n"
            "2. Scene nào lỗi và fallback đề xuất.\n"
            f"3. Lệnh cập nhật: /asset_add job={jid} type=raw_video url=<LINK> note=manifest:{manifest_id} scene=<N>"
        )
    if target_tool in {"fish", "edge", "tts", "voice"}:
        return (
            common +
            "NHIỆM VỤ VOICE:\n"
            f"Provider chính: {voice.get('provider_primary','Fish Audio HD')} | fallback: {voice.get('provider_fallback','Edge TTS')}\n"
            f"Style: {voice.get('style','giọng Việt rõ, đáng tin')}\n\n"
            f"SCRIPT:\n{voice.get('script') or ' '.join(str(s.get('voice_line','')) for s in scenes)}\n\n"
            "OUTPUT:\n"
            "1. File/link audio.\n"
            "2. Duration thực tế.\n"
            "3. Nếu Fish lỗi/quota, dùng Edge và báo admin.\n"
            f"4. Lệnh cập nhật: /asset_add job={jid} type=voice url=<LINK> note=manifest:{manifest_id}"
        )
    if target_tool in {"capcut", "ffmpeg", "edit"}:
        return (
            common +
            "NHIỆM VỤ EDIT:\n"
            f"Tool: {edit.get('tool','capcut|ffmpeg')}\n"
            f"Music: {edit.get('music','nhạc hợp lệ, âm lượng thấp')}\n"
            f"Subtitle: {edit.get('subtitle','burn subtitle tiếng Việt')}\n"
            f"Transitions: {edit.get('transitions','cut nhanh, sạch')}\n"
            f"CTA overlay: {edit.get('cta_overlay') or publish.get('cta') or '-'}\n\n"
            "INPUT CẦN DÙNG:\n"
            "- raw_video scenes từ /assets\n"
            "- voice audio từ /assets\n"
            "- caption/CTA từ manifest\n\n"
            "OUTPUT:\n"
            "1. final_video mp4 9:16.\n"
            "2. subtitle file nếu có.\n"
            "3. thumbnail nếu có.\n"
            f"4. Lệnh cập nhật: /asset_add job={jid} type=final_video url=<LINK> note=manifest:{manifest_id}"
        )
    if target_tool in {"publish", "caption", "social"}:
        return (
            common +
            "NHIỆM VỤ PUBLISH PACK:\n"
            f"Caption: {publish.get('caption','-')}\n"
            f"Hashtags: {publish.get('hashtags','-')}\n"
            f"Affiliate placement: {publish.get('affiliate_placement','-')}\n"
            f"CTA: {publish.get('cta','-')}\n\n"
            "OUTPUT:\n"
            "1. Caption cuối cùng theo nền tảng.\n"
            "2. Checklist trước khi đăng.\n"
            f"3. Queue đăng: /queue_publish job={jid} mode=manual note=manifest:{manifest_id}"
        )
    if target_tool in {"review", "review_gate", "compliance"}:
        return (
            common +
            "NHIỆM VỤ REVIEW GATE:\n"
            "Checklist manifest:\n" + "\n".join(f"- {item}" for item in compliance) + "\n\n"
            "Kiểm tra thêm: quyền hình ảnh/voice/nhạc, affiliate claim, nội dung người mẫu/OnlyFans nếu có, CTA, link, publish URL.\n"
            "OUTPUT: APPROVE/FIX/BLOCK, lý do, sửa gì trước khi đăng."
        )
    return (
        common +
        "NHIỆM VỤ ORCHESTRATION:\n"
        "Đọc manifest dưới đây và chia việc cho tool phù hợp theo handoff_order.\n\n"
        f"<MANIFEST_JSON>\n{manifest_json}\n</MANIFEST_JSON>\n\n"
        "OUTPUT: danh sách việc theo thứ tự, lệnh Telegram cần chạy tiếp, và điểm rủi ro cần xử lý."
    )

def create_production_task(owner_id, job_id, manifest_id, task_type, tool, scene_no=0, title="", prompt="", status="queued", output_url="", note=""):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO production_tasks
        (owner_id, job_id, manifest_id, task_type, tool, scene_no, title, prompt, status, output_url, note, created_at, updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            str(owner_id), job_id, int(manifest_id or 0), task_type, tool, int(scene_no or 0),
            title, prompt, status, output_url, note, now_text(), now_text()
        )
    )
    task_id = c.lastrowid
    conn.commit()
    conn.close()
    return task_id

def create_tasks_from_manifest(owner_id, manifest_row):
    manifest_id, job_id, variant_id, manifest_status, manifest_json, created_at, updated_at = manifest_row
    try:
        manifest = json.loads(manifest_json or "{}")
    except Exception:
        manifest = {}
    scenes = manifest.get("scenes") or []
    voice = manifest.get("voice") or {}
    edit = manifest.get("edit_instructions") or {}
    publish = manifest.get("publish") or {}
    proof_assets = manifest.get("proof_assets_required") or []
    created = []
    for idx, proof in enumerate(proof_assets[:4], start=1):
        created.append(create_production_task(
            owner_id, job_id, manifest_id, "proof_asset", "claude", idx,
            f"Proof asset {idx}", str(proof), "queued", "", "pattern_bank"
        ))
    for scene in scenes:
        scene_no = int(scene.get("scene") or 0)
        quality = scene.get("quality_score") or score_video_prompt_quality(scene)
        if quality.get("decision") == "block":
            created.append(create_production_task(
                owner_id, job_id, manifest_id, "review", "review_gate", scene_no,
                f"Blocked scene {scene_no}", json.dumps({
                    "scene": scene_no,
                    "quality_score": quality,
                    "reason": "Prompt gate blocked render task before paid tool execution.",
                    "scene_manifest": scene,
                }, ensure_ascii=False), "blocked", "", "prompt_quality_gate"
            ))
            record_tool_event(
                owner_id,
                "prompt_gate",
                "policy_guard",
                "blocked",
                "critical",
                job_id,
                0,
                "",
                f"Scene {scene_no} blocked before render: {json.dumps(quality, ensure_ascii=False)}",
            )
            continue
        tool = str(scene.get("video_tool") or "kling").split("|")[0].strip() or "kling"
        prompt = (
            f"Scene {scene_no} ({scene.get('start','?')}-{scene.get('end','?')}s, {scene.get('goal','-')})\n"
            f"Visual prompt: {scene.get('visual_prompt','')}\n"
            f"Image prompt: {scene.get('image_prompt','')}\n"
            f"Video prompt: {scene.get('video_prompt','')}\n"
            f"On-screen text: {scene.get('on_screen_text','')}\n"
            f"Voice line: {scene.get('voice_line','')}\n"
            f"Asset needed: {scene.get('asset_needed','')}"
        )
        created.append(create_production_task(
            owner_id, job_id, manifest_id, "visual_scene", tool, scene_no,
            f"Scene {scene_no}: {scene.get('goal','visual')}", prompt, "queued", "", f"asset_needed={scene.get('asset_needed','')}"
        ))
    voice_script = voice.get("script") or " ".join(str(scene.get("voice_line", "")) for scene in scenes)
    if voice_script:
        created.append(create_production_task(
            owner_id, job_id, manifest_id, "voice", "fish", 0,
            "Voice over", f"Style: {voice.get('style','giọng Việt rõ')}\nScript:\n{voice_script}", "queued", "",
            f"fallback={voice.get('provider_fallback','Edge TTS')}"
        ))
    created.append(create_production_task(
        owner_id, job_id, manifest_id, "edit", "capcut", 0,
        "Edit final video",
        "Dựng 9:16 từ raw scene + voice.\n"
        f"Music: {edit.get('music','nhạc hợp lệ')}\nSubtitle: {edit.get('subtitle','burn subtitle')}\n"
        f"Transitions: {edit.get('transitions','cut nhanh')}\nCTA overlay: {edit.get('cta_overlay') or publish.get('cta','')}",
        "queued", "", "fallback=ffmpeg"
    ))
    created.append(create_production_task(
        owner_id, job_id, manifest_id, "review", "review_gate", 0,
        "Compliance review", "\n".join(str(item) for item in (manifest.get("compliance_checklist") or [])), "queued", "", ""
    ))
    created.append(create_production_task(
        owner_id, job_id, manifest_id, "publish", "manual", 0,
        "Publish/queue",
        f"Caption: {publish.get('caption','')}\nHashtags: {publish.get('hashtags','')}\nCTA: {publish.get('cta','')}\nAffiliate: {publish.get('affiliate_placement','')}",
        "queued", "", "mode=manual_or_api"
    ))
    update_production_job(job_id, owner_id, stage="visuals", status="working", note=f"task_plan manifest:{manifest_id} tasks={len(created)}")
    return created

def build_operator_job_bundle(owner_id, job_id, count=5, duration=45):
    job = get_production_job(job_id, owner_id)
    if not job:
        return False, {"error": "Không tìm thấy production job."}
    created_variants = create_creative_variants_for_job(owner_id, job, count)
    if not created_variants:
        return False, {"error": "Không tạo được creative variants."}
    best_variant_id, best_variant = sorted(
        created_variants,
        key=lambda item: int(item[1].get("creative_score") or 0),
        reverse=True
    )[0]
    ok, selected_variant = select_creative_variant(owner_id, best_variant_id)
    if not ok:
        return False, {"error": "Không chọn được creative variant tốt nhất."}
    ok, manifest_id, manifest = create_manifest_for_job(owner_id, job, selected_variant, duration)
    if not ok:
        return False, {"error": "Không tạo được production manifest."}
    manifest_row = get_production_manifest(owner_id, manifest_id)
    task_ids = create_tasks_from_manifest(owner_id, manifest_row)
    readiness = production_readiness_data(owner_id, job_id)
    return True, {
        "job": job,
        "created_variants": created_variants,
        "best_variant_id": best_variant_id,
        "best_variant": best_variant,
        "selected_variant": selected_variant,
        "manifest_id": manifest_id,
        "manifest": manifest,
        "task_ids": task_ids,
        "readiness": readiness,
    }

def list_production_tasks(owner_id, job_id=None, manifest_id=None, limit=30):
    where = ["owner_id=?"]
    params = [str(owner_id)]
    if job_id:
        where.append("job_id=?")
        params.append(int(job_id))
    if manifest_id:
        where.append("manifest_id=?")
        params.append(int(manifest_id))
    params.append(limit)
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        f"""SELECT id, job_id, manifest_id, task_type, tool, scene_no, title, status, output_url, note, updated_at
        FROM production_tasks
        WHERE {' AND '.join(where)}
        ORDER BY
            CASE status
                WHEN 'blocked' THEN 0
                WHEN 'working' THEN 1
                WHEN 'queued' THEN 2
                WHEN 'ready' THEN 3
                ELSE 4
            END,
            id ASC
        LIMIT ?""",
        params
    )
    rows = c.fetchall()
    conn.close()
    return rows

def get_production_task(owner_id, task_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, job_id, manifest_id, task_type, tool, scene_no, title, prompt, status, output_url, note, updated_at
        FROM production_tasks WHERE owner_id=? AND id=?""",
        (str(owner_id), task_id)
    )
    row = c.fetchone()
    conn.close()
    return row

def next_production_task(owner_id, job_id=None):
    rows = list_production_tasks(owner_id, job_id=job_id, limit=100)
    if not rows:
        return None
    type_priority = {
        "proof_asset": 0,
        "visual_scene": 1,
        "voice": 2,
        "edit": 3,
        "review": 4,
        "publish": 5,
    }
    status_priority = {
        "blocked": 0,
        "working": 1,
        "queued": 2,
        "waiting": 3,
        "ready": 4,
        "done": 5,
        "cancelled": 6,
    }
    actionable = [row for row in rows if (row[7] or "queued") not in {"ready", "done", "cancelled"}]
    if not actionable:
        return None
    actionable.sort(key=lambda row: (status_priority.get(row[7] or "queued", 9), type_priority.get(row[3] or "", 9), row[5] or 0, row[0]))
    return actionable[0]

def next_worker_task(owner_id, job_id=None, tool=""):
    rows = list_production_tasks(owner_id, job_id=job_id, limit=200)
    allowed_status = {"queued", "waiting"}
    tool = (tool or "").strip().lower()
    candidates = []
    for row in rows:
        row_tool = (row[4] or "").lower()
        row_status = (row[7] or "queued").lower()
        if row_status not in allowed_status:
            continue
        if tool and tool not in {row_tool, (row[3] or "").lower()}:
            continue
        candidates.append(row)
    if not candidates:
        return None
    type_priority = {"proof_asset": 0, "visual_scene": 1, "voice": 2, "edit": 3, "review": 4, "publish": 5}
    candidates.sort(key=lambda row: (type_priority.get(row[3] or "", 9), row[5] or 0, row[0]))
    return get_production_task(owner_id, candidates[0][0])

def default_asset_type_for_task(task_type):
    return {
        "proof_asset": "proof_asset",
        "visual_scene": "raw_video",
        "voice": "voice",
        "edit": "final_video",
        "publish": "source",
    }.get((task_type or "").lower(), "source")

def update_production_task(owner_id, task_id, status=None, output_url=None, note=None, asset_type=None, record_asset=True):
    updates = []
    params = []
    if status:
        updates.append("status=?")
        params.append(status)
    if output_url is not None:
        updates.append("output_url=?")
        params.append(output_url)
    if note is not None:
        updates.append("note=?")
        params.append(note)
    if not updates:
        return False, None
    updates.append("updated_at=?")
    params.append(now_text())
    params.extend([str(owner_id), task_id])
    conn = db_connect()
    c = conn.cursor()
    c.execute(f"UPDATE production_tasks SET {', '.join(updates)} WHERE owner_id=? AND id=?", params)
    changed = c.rowcount
    c.execute("SELECT job_id, task_type, scene_no FROM production_tasks WHERE owner_id=? AND id=?", (str(owner_id), task_id))
    row = c.fetchone()
    conn.commit()
    conn.close()
    if changed and output_url and row and record_asset:
        resolved_asset_type = (asset_type or "").strip().lower() or default_asset_type_for_task(row[1])
        scene_note = f" scene={int(row[2] or 0)}" if int(row[2] or 0) else ""
        add_production_asset(owner_id, row[0], resolved_asset_type, output_url, "", f"task:{task_id}{scene_note} {note or ''}")
    return changed > 0, row

