async def create_operator_auto_jobs(owner_id, niche, platform_filter="", channel_filter="all", campaign_id=0, affiliate_id=0, limit=5):
    if campaign_id and not get_campaign(campaign_id, owner_id):
        return [], "Không tìm thấy campaign."
    if affiliate_id and not get_affiliate_link(affiliate_id, owner_id):
        return [], "Không tìm thấy affiliate."
    if channel_filter == "all":
        channels = list_social_channels(owner_id, limit=80)
        if platform_filter:
            channels = [ch for ch in channels if (ch[1] or "").lower() == platform_filter]
    else:
        try:
            one = get_social_channel(int(channel_filter), owner_id)
        except ValueError:
            one = None
        channels = [one] if one else []
    channels = [ch for ch in channels if ch and ch[7] == "active"]
    if not channels:
        return [], "Chưa có channel active phù hợp. Tạo bằng /channel_add."

    affiliate = get_affiliate_link(affiliate_id, owner_id) if affiliate_id else None
    search_platform = platform_filter or (channels[0][1] if channels else "tiktok")
    try:
        trends = await fetch_google_news_trends(niche, search_platform, limit=limit)
    except Exception as exc:
        logger.warning(f"Trend fetch failed, using fallback topics: niche={niche} platform={search_platform} error={exc}")
        trends = []
    if not trends:
        trends = fallback_operator_trends(niche, search_platform, affiliate=affiliate, limit=limit)

    related_affiliates = list_related_affiliate_links(owner_id, affiliate_id=affiliate_id, niche=niche, limit=8) if affiliate_id else []
    related_note = format_related_affiliate_links(related_affiliates, max_items=6)
    primary_channel = channels[0] if channels else None
    scored_trends = []
    for item in trends:
        scores = score_trend_candidate(niche, search_platform, item["title"], item.get("summary", ""), primary_channel, affiliate)
        scored_trends.append((scores["trend_score"], item, scores))
    scored_trends.sort(key=lambda row: row[0], reverse=True)

    created = []
    for _, item, base_scores in scored_trends:
        for channel in channels:
            if len(created) >= limit:
                break
            cid, channel_platform, channel_name, account_label, focus, audience, slots, status = channel
            scores = score_trend_candidate(niche, channel_platform or search_platform, item["title"], item.get("summary", ""), channel, affiliate) or base_scores
            trend_id = save_trend_candidate(
                owner_id,
                niche,
                channel_platform or search_platform,
                item["title"],
                item["url"],
                item.get("source", ""),
                item.get("summary", ""),
                cid,
                campaign_id,
                affiliate_id,
                scores["trend_score"],
                scores["affiliate_fit_score"],
                scores["competition_score"],
                scores["score_reason"]
            )
            topic = f"{item['title']} | {niche} | affiliate product placement"
            note = (
                f"operator_auto trend #{trend_id} | score={scores['trend_score']} "
                f"aff_fit={scores['affiliate_fit_score']} competition={scores['competition_score']} | "
                f"source={item.get('source','')} | {item['url']}"
                + (f" | related_affiliates={related_note}" if related_note else "")
            )
            slot_id = create_calendar_slot(
                owner_id,
                cid,
                campaign_id,
                affiliate_id,
                datetime.now().date().isoformat(),
                channel_platform or search_platform,
                topic,
                note
            )
            slot = get_calendar_slot(slot_id, owner_id)
            if gemini_client or openai_client:
                brief = AgentGemini.chat(
                    "Bạn là AI Operator trưởng, tạo brief video affiliate từ trend cho pipeline batch.",
                    build_production_prompt(slot)
                    + f"\n\nNguồn trend: {item['url']}\nTóm tắt trend: {item.get('summary','')}"
                    + (f"\n\nLink affiliate liên quan để chèn caption/comment/status:\n{related_note}" if related_note else ""),
                    owner_id,
                    is_json=False
                )
            else:
                brief = f"Trend: {item['title']}\nNguồn: {item['url']}\nTạo video affiliate theo trend này và kiểm duyệt trước khi đăng."
            job_id = create_production_job(
                owner_id,
                slot_id,
                campaign_id,
                cid,
                affiliate_id,
                channel_platform or search_platform,
                topic,
                brief,
                note
            )
            update_trend_status(trend_id, owner_id, f"job:{job_id}")
            created.append({
                "job_id": job_id,
                "slot_id": slot_id,
                "trend_id": trend_id,
                "platform": channel_platform or search_platform,
                "channel_name": channel_name,
                "title": item["title"],
                "score": scores["trend_score"],
                "reason": scores["score_reason"],
            })
    return created, ""

async def execute_scale_plan_actions(owner_id, days=30, platform="tiktok", limit=5, per_affiliate_limit=3, build=True, duration=45, notify_admin=False):
    plan = scale_plan_data(owner_id, days=days, limit=max(limit * 3, 10), platform=platform)
    executed = []
    skipped = []
    seen_affiliates = set()
    for item in plan["plans"]:
        if len(executed) >= limit:
            break
        aid = int(item.get("affiliate_id") or 0)
        if item.get("action") != "SCALE":
            skipped.append({**item, "skip_reason": "not_scale_action"})
            continue
        if not aid:
            skipped.append({**item, "skip_reason": "missing_affiliate_id"})
            continue
        if aid in seen_affiliates:
            skipped.append({**item, "skip_reason": "duplicate_affiliate_in_batch"})
            continue
        affiliate = get_affiliate_link(aid, owner_id)
        if not affiliate:
            skipped.append({**item, "skip_reason": "affiliate_not_found"})
            continue
        (
            _aid, network, product, affiliate_niche, url, note, status,
            price_vnd, commission_rate, audience, allowed_claims, blocked_claims, product_score
        ) = affiliate
        if (status or "active").lower() != "active":
            skipped.append({**item, "skip_reason": "affiliate_inactive"})
            continue
        scale_niche = affiliate_niche or product or item.get("topic") or "affiliate"
        matched_campaign, campaign_score = find_matching_campaign(owner_id, scale_niche, platform)
        campaign_id = matched_campaign[0] if matched_campaign else 0
        created_jobs, error = await create_operator_auto_jobs(
            owner_id,
            scale_niche,
            platform,
            "all",
            campaign_id,
            aid,
            per_affiliate_limit,
        )
        if error:
            skipped.append({**item, "skip_reason": error})
            continue
        built = []
        failed = []
        if build:
            for created in created_jobs:
                ok, bundle = build_operator_job_bundle(owner_id, created["job_id"], count=5, duration=duration)
                if ok:
                    built.append({
                        "job_id": created["job_id"],
                        "manifest_id": bundle.get("manifest_id"),
                        "task_count": len(bundle.get("task_ids") or []),
                        "variant_id": bundle.get("best_variant_id"),
                        "readiness": (bundle.get("readiness") or {}).get("level", "UNKNOWN"),
                    })
                else:
                    failed.append({"job_id": created["job_id"], "error": bundle.get("error", "build lỗi") if isinstance(bundle, dict) else "build lỗi"})
        seen_affiliates.add(aid)
        executed.append({
            **item,
            "affiliate": {"id": aid, "network": network, "product": product, "niche": affiliate_niche},
            "campaign": {
                "id": campaign_id,
                "name": matched_campaign[1] if matched_campaign else "",
                "match_score": campaign_score,
            },
            "created_jobs": created_jobs,
            "built_jobs": built,
            "failed_builds": failed,
        })
    if notify_admin and tg_app and ADMIN_ID:
        try:
            await tg_app.bot.send_message(
                chat_id=ADMIN_ID,
                text=(
                    "🎯 <b>SCALE PLAN EXECUTED</b>\n\n"
                    f"• Executed: <b>{len(executed)}</b>\n"
                    f"• Skipped: <b>{len(skipped)}</b>\n"
                    f"• Platform: <code>{html.escape(platform)}</code>\n"
                    f"• Next: <code>/tasks</code> hoặc <code>/operator_loop</code>"
                ),
                parse_mode="HTML"
            )
        except Exception as e:
            logger.error(f"Scale plan execute notify error: {e}")
    return {"plan": plan, "executed": executed, "skipped": skipped}

async def operator_growth_loop_data(
    owner_id,
    days=30,
    platform="tiktok",
    limit=5,
    execute=False,
    build=True,
    duration=45,
    per_affiliate_limit=2,
):
    days = max(1, min(int(days or 30), 180))
    limit = max(1, min(int(limit or 5), 20))
    platform = (platform or "tiktok").lower()
    duration = max(15, min(int(duration or 45), 120))
    per_affiliate_limit = max(1, min(int(per_affiliate_limit or 2), 5))
    scale = scale_plan_data(owner_id, days=days, limit=max(limit, 10), platform=platform)
    since, decisions, _job_rows = affiliate_decision_data(owner_id, days=days, limit=max(limit, 12), platform=platform)
    queue_rows = [
        serialize_publish_queue_item(row)
        for row in list_publish_queue(owner_id, limit=max(limit * 2, 10))
    ]
    open_queue = [
        item for item in queue_rows
        if item and (item.get("status") or "").lower() in {"queued", "scheduled", "publishing"}
    ]
    actions = []
    if open_queue:
        item = open_queue[0]
        actions.append({
            "kind": "publish_handoff",
            "safe_to_execute": False,
            "reason": "Có video đã qua queue, cần admin hoặc publisher đăng và ghi /publish_done.",
            "queue_id": item.get("id"),
            "job_id": item.get("job_id"),
            "platform": item.get("platform") or platform,
            "title": item.get("topic") or item.get("product_name") or "publish queue",
            "telegram": f"/publisher_handoff queue={item.get('id')}",
            "after_done": f"/publish_done queue={item.get('id')} url=https://... views=0 clicks=0 orders=0 revenue=0 cost=0",
        })

    for item in scale.get("plans") or []:
        action = item.get("action")
        aid = int(item.get("affiliate_id") or 0)
        job_id = int(item.get("job_id") or 0)
        if action == "SCALE" and aid:
            actions.append({
                "kind": "scale_affiliate",
                "safe_to_execute": True,
                "reason": item.get("reason") or "Affiliate/source có tín hiệu tốt.",
                "affiliate_id": aid,
                "job_id": job_id,
                "platform": item.get("platform") or platform,
                "title": item.get("product") or item.get("topic") or f"aff #{aid}",
                "score": item.get("score", 0),
                "telegram": f"/scale_execute days={days} platform={platform} limit=1 per={per_affiliate_limit} build={1 if build else 0} duration={duration}",
            })
        elif action == "FIX_CTA" and job_id:
            actions.append({
                "kind": "fix_cta",
                "safe_to_execute": True,
                "reason": item.get("reason") or "Có view nhưng thiếu click, cần test hook/caption/CTA.",
                "affiliate_id": aid,
                "job_id": job_id,
                "platform": item.get("platform") or platform,
                "title": item.get("topic") or item.get("product") or f"job #{job_id}",
                "score": item.get("score", 0),
                "telegram": f"/creative_test job={job_id} n=5",
            })
        elif action == "FIX_OFFER" and aid:
            actions.append({
                "kind": "fix_offer",
                "safe_to_execute": True,
                "reason": item.get("reason") or "Có click nhưng chưa có chuyển đổi, cần thêm sản phẩm/offer liên quan.",
                "affiliate_id": aid,
                "job_id": job_id,
                "platform": item.get("platform") or platform,
                "title": item.get("product") or f"aff #{aid}",
                "score": item.get("score", 0),
                "telegram": f"/affiliate_related aff={aid} limit=12",
            })
        elif action == "TEST_MORE" and aid:
            actions.append({
                "kind": "test_more",
                "safe_to_execute": True,
                "reason": item.get("reason") or "Dữ liệu còn mỏng, tạo thêm batch test nhỏ.",
                "affiliate_id": aid,
                "job_id": job_id,
                "platform": item.get("platform") or platform,
                "title": item.get("product") or item.get("topic") or f"aff #{aid}",
                "score": item.get("score", 0),
                "telegram": f"/affiliate_scale aff={aid} platform={platform} channel=all limit=1 build={1 if build else 0} duration={duration}",
            })

    if not actions and decisions:
        item = decisions[0]
        aid = int(item.get("id") or 0)
        actions.append({
            "kind": "decision_followup",
            "safe_to_execute": False,
            "reason": item.get("reason") or "Cần admin chọn bước tiếp theo từ affiliate decisions.",
            "affiliate_id": aid,
            "platform": platform,
            "title": item.get("product") or f"aff #{aid}",
            "score": item.get("score", 0),
            "telegram": item.get("command") or f"/affiliate_decisions days={days} platform={platform}",
        })

    selected = next((item for item in actions if item.get("safe_to_execute")), actions[0] if actions else None)
    result = {"executed": False, "reason": "preview_only", "details": {}}
    if execute and selected:
        kind = selected.get("kind")
        if not selected.get("safe_to_execute"):
            result = {"executed": False, "reason": "selected_action_requires_admin_gate", "details": selected}
        elif kind == "scale_affiliate":
            run = await execute_scale_plan_actions(
                owner_id,
                days=days,
                platform=platform,
                limit=1,
                per_affiliate_limit=per_affiliate_limit,
                build=build,
                duration=duration,
                notify_admin=False,
            )
            result = {"executed": bool(run.get("executed")), "reason": "scale_execute", "details": run}
        elif kind == "fix_cta":
            job_id = int(selected.get("job_id") or 0)
            job = get_production_job(job_id, owner_id)
            if not job:
                result = {"executed": False, "reason": "job_not_found", "details": selected}
            else:
                created = create_creative_variants_for_job(owner_id, job, count=5)
                if created:
                    update_production_job(job_id, owner_id, stage="script", status="working", note=f"growth_loop_fix_cta variants={len(created)}")
                result = {
                    "executed": bool(created),
                    "reason": "fix_cta_creative_variants",
                    "details": {
                        "job_id": job_id,
                        "created_variants": [
                            {"variant_id": variant_id, "label": item.get("variant_label"), "score": item.get("creative_score", 0)}
                            for variant_id, item in created
                        ],
                    },
                }
        elif kind == "fix_offer":
            aid = int(selected.get("affiliate_id") or 0)
            related = list_related_affiliate_links(owner_id, affiliate_id=aid, niche=selected.get("title") or "", limit=12)
            result = {
                "executed": False,
                "reason": "related_links_ready",
                "details": {
                    "affiliate_id": aid,
                    "related_links": [
                        {"id": row[0], "network": row[1], "product": row[2], "niche": row[3], "score": int(score or 0)}
                        for score, _reasons, row in related
                    ],
                },
            }
        elif kind == "test_more":
            aid = int(selected.get("affiliate_id") or 0)
            affiliate = get_affiliate_link(aid, owner_id)
            if not affiliate:
                result = {"executed": False, "reason": "affiliate_not_found", "details": selected}
            else:
                _aid, _network, product, niche, *_rest = affiliate
                scale_niche = niche or product or selected.get("title") or "affiliate"
                created_jobs, error = await create_operator_auto_jobs(owner_id, scale_niche, platform, "all", 0, aid, 1)
                built = []
                if not error and build:
                    for created in created_jobs:
                        ok, bundle = build_operator_job_bundle(owner_id, created["job_id"], count=5, duration=duration)
                        if ok:
                            built.append({
                                "job_id": created["job_id"],
                                "manifest_id": bundle.get("manifest_id"),
                                "task_count": len(bundle.get("task_ids") or []),
                            })
                result = {
                    "executed": bool(created_jobs) and not error,
                    "reason": error or "test_more_jobs_created",
                    "details": {"created_jobs": created_jobs, "built_jobs": built},
                }

    return {
        "ok": True,
        "generated_at": now_text(),
        "days": days,
        "since": since,
        "platform": platform,
        "execute": bool(execute),
        "selected_action": selected,
        "actions": actions[:limit],
        "scale_summary": scale.get("summary") or {},
        "affiliate_decisions": decisions[:limit],
        "open_publish_queue": open_queue[:limit],
        "result": result,
        "commands": {
            "telegram": {
                "preview": f"/growth_loop days={days} platform={platform} limit={limit}",
                "execute": f"/growth_loop days={days} platform={platform} limit={limit} execute=1 build={1 if build else 0}",
                "tracking": f"/tracking_report days={days} limit={limit}",
                "decisions": f"/affiliate_decisions days={days} platform={platform} limit={limit}",
            },
            "api": {
                "preview": f"/api/operator/growth-loop?days={days}&platform={platform}&limit={limit}",
                "execute": "/api/operator/growth-loop/run",
            },
        },
        "rule": "Growth loop chỉ chạy bước an toàn từ dữ liệu thật. Publish/handoff vẫn cần admin hoặc publisher adapter hợp lệ; sau đăng phải ghi /publish_done.",
    }

def is_multi_platform_request(platform):
    return (platform or "").strip().lower() in {"all", "*", "multi", "mxh", "social", "đa kênh", "da kenh"}

def active_platforms_for_launch(owner_id, platform=""):
    if not is_multi_platform_request(platform):
        value = (platform or "tiktok").strip().lower()
        return [value]
    rows = list_social_channels(owner_id, limit=100)
    preferred = ["tiktok", "facebook", "reels", "instagram", "youtube", "onlyfans"]
    active = []
    for _cid, row_platform, _name, _account, _focus, _audience, _slots, status in rows:
        value = (row_platform or "").strip().lower()
        if value and (status or "").lower() == "active" and value not in active:
            active.append(value)
    active.sort(key=lambda item: preferred.index(item) if item in preferred else len(preferred))
    return active or ["tiktok", "facebook", "onlyfans"]

async def make_video_pipeline(
    owner_id,
    topic,
    platform="tiktok",
    channel="all",
    affiliate_id=0,
    campaign_id=0,
    limit=3,
    build=True,
    duration=45,
    variants=5,
    autorun=False,
    autorun_max_tasks=24,
):
    topic = (topic or "").strip()
    if not topic:
        return False, "missing_topic", {}
    requested_platform = (platform or "tiktok").lower()
    multi_platform = is_multi_platform_request(requested_platform)
    platform_filter = "" if multi_platform else requested_platform
    channel = (channel or "all").lower()
    target_platforms = active_platforms_for_launch(owner_id, requested_platform)

    selected_affiliate = get_affiliate_link(affiliate_id, owner_id) if affiliate_id else None
    affiliate_score = 0
    affiliate_hits = 0
    if affiliate_id and not selected_affiliate:
        return False, "affiliate_not_found", {}
    if not selected_affiliate:
        matches = list_affiliate_matches(owner_id, niche=topic, trend_text=topic, platform=(platform_filter or "multi"), limit=5)
        if matches:
            affiliate_score, affiliate_hits, _blocked, selected_affiliate = matches[0]
            affiliate_id = selected_affiliate[0]

    selected_campaign = get_campaign(campaign_id, owner_id) if campaign_id else None
    campaign_score = 0
    if campaign_id and not selected_campaign:
        return False, "campaign_not_found", {}
    if not selected_campaign:
        selected_campaign, campaign_score = find_matching_campaign(owner_id, topic, platform_filter or (target_platforms[0] if target_platforms else "tiktok"))
        campaign_id = selected_campaign[0] if selected_campaign else 0

    created_jobs, error = await create_operator_auto_jobs(
        owner_id,
        topic,
        platform_filter,
        channel,
        campaign_id,
        affiliate_id,
        limit,
    )
    if error:
        return False, error, {
            "affiliate_id": affiliate_id,
            "campaign_id": campaign_id,
            "topic": topic,
            "platform": requested_platform,
            "target_platforms": target_platforms,
            "channel": channel,
        }

    built = []
    failed = []
    publish_packs = []
    distribution_packs = []
    if build:
        for item in created_jobs:
            ok, bundle = build_operator_job_bundle(owner_id, item["job_id"], count=variants, duration=duration)
            if ok:
                readiness = bundle.get("readiness") or {}
                built_item = {
                    **item,
                    "manifest_id": bundle.get("manifest_id"),
                    "task_count": len(bundle.get("task_ids") or []),
                    "variant_id": bundle.get("best_variant_id"),
                    "readiness": readiness.get("level", "UNKNOWN") if isinstance(readiness, dict) else "UNKNOWN",
                }
                built.append(built_item)
                job = get_production_job(item["job_id"], owner_id)
                if job:
                    pack = build_static_publish_pack(job, owner_id)
                    publish_packs.append({
                        "job_id": item["job_id"],
                        "caption": pack.get("caption", ""),
                        "tracking_url": (pack.get("primary_affiliate") or {}).get("tracking_url", ""),
                        "related_links": pack.get("related_links", [])[:6],
                        "affiliate_bundle": pack.get("affiliate_bundle", {}),
                        "placement_plan": pack.get("placement_plan", {}),
                        "disclosure": pack.get("disclosure", ""),
                    })
                    distribution = build_distribution_pack(owner_id, item["job_id"])
                    if distribution:
                        distribution_packs.append({
                            "job_id": item["job_id"],
                            "channel": distribution.get("channel"),
                            "placement_map": distribution.get("placement_map"),
                            "review_gate": distribution.get("review_gate"),
                            "tracking_plan": distribution.get("tracking_plan"),
                            "commands": distribution.get("commands"),
                        })
            else:
                failed.append({"job_id": item["job_id"], "error": bundle.get("error", "build lỗi") if isinstance(bundle, dict) else "build lỗi"})
    job_ids_for_work = [item["job_id"] for item in (built or created_jobs)]
    autorun_result = None
    if build and autorun and job_ids_for_work:
        autorun_result = await operator_worker_autorun_data(
            owner_id,
            job_ids=job_ids_for_work,
            limit=min(len(job_ids_for_work), 8),
            max_tasks=autorun_max_tasks,
            execute=True,
        )
    worker_next = operator_worker_next_summary(
        owner_id,
        job_ids_for_work,
        limit=min(len(job_ids_for_work), 5),
    )
    video_work_orders = operator_video_work_orders_data(
        owner_id,
        job_ids_for_work,
        limit=min(len(job_ids_for_work), 8) or 1,
    )

    affiliate_payload = None
    if selected_affiliate:
        aid, network, product, niche, url, note, status, *_rest = selected_affiliate
        affiliate_payload = {
            "id": aid,
            "network": network,
            "product": product,
            "niche": niche,
            "url": url,
            "match_score": affiliate_score,
            "match_hits": affiliate_hits,
        }

    campaign_payload = None
    if selected_campaign:
        if len(selected_campaign) >= 8:
            campaign_name = selected_campaign[2]
            campaign_niche = selected_campaign[3]
            campaign_platforms = selected_campaign[4]
        else:
            campaign_name = selected_campaign[1]
            campaign_niche = selected_campaign[2]
            campaign_platforms = selected_campaign[3]
        campaign_payload = {
            "id": selected_campaign[0],
            "name": campaign_name,
            "niche": campaign_niche,
            "platforms": campaign_platforms,
            "match_score": campaign_score,
        }

    return True, "ok", {
        "topic": topic,
        "platform": requested_platform,
        "platform_filter": platform_filter,
        "multi_platform": multi_platform,
        "target_platforms": target_platforms,
        "created_platforms": sorted({(item.get("platform") or "") for item in created_jobs if item.get("platform")}),
        "channel": channel,
        "affiliate": affiliate_payload,
        "campaign": campaign_payload,
        "created_jobs": created_jobs,
        "built_jobs": built,
        "failed_builds": failed,
        "publish_packs": publish_packs,
        "distribution_packs": distribution_packs,
        "autorun": autorun_result,
        "worker_next": worker_next,
        "video_work_orders": video_work_orders,
        "automation_next": {
            "worker_autorun": (
                "/worker_autorun jobs="
                + ",".join(str(job_id) for job_id in job_ids_for_work[:8])
                + " execute=1"
            ) if job_ids_for_work else "/worker_autorun execute=1",
            "review": "/review_video job=<JOB_ID> send=1",
            "approve": "/approve_publish job=<JOB_ID> queue=1 mode=manual",
        },
    }

async def operator_launch_pipeline(
    owner_id,
    topic,
    platform="tiktok",
    channel="all",
    affiliate_id=0,
    campaign_id=0,
    limit=3,
    build=True,
    duration=45,
    variants=5,
    bootstrap=True,
    autorun=False,
    autorun_max_tasks=24,
):
    topic = (topic or "").strip()
    if not topic:
        return False, "missing_topic", {}
    before = operator_audit_data(owner_id)
    bootstrap_result = None
    if bootstrap:
        counts = before.get("counts") or {}
        needs_bootstrap = (
            int(counts.get("active_channels") or 0) <= 0
            or int(counts.get("active_affiliates") or 0) <= 0
            or int(counts.get("active_campaigns") or 0) <= 0
        )
        if needs_bootstrap:
            bootstrap_result = operator_bootstrap_data(
                owner_id,
                include_channels=True,
                include_campaigns=True,
                include_affiliates=True,
                include_references=True,
                reference_limit=200,
            )
    ok, reason, result = await make_video_pipeline(
        owner_id,
        topic,
        platform=platform,
        channel=channel,
        affiliate_id=affiliate_id,
        campaign_id=campaign_id,
        limit=limit,
        build=build,
        duration=duration,
        variants=variants,
        autorun=autorun,
        autorun_max_tasks=autorun_max_tasks,
    )
    after = operator_audit_data(owner_id)
    if not ok:
        return False, reason, {
            "topic": topic,
            "platform": platform,
            "channel": channel,
            "bootstrap": bootstrap_result,
            "audit_before": {"level": before.get("level"), "score": before.get("score"), "next_command": before.get("next_command")},
            "audit_after": {"level": after.get("level"), "score": after.get("score"), "next_command": after.get("next_command")},
        }
    created_jobs = result.get("created_jobs") or []
    first_job_id = created_jobs[0]["job_id"] if created_jobs else 0
    first_job = get_production_job(first_job_id, owner_id) if first_job_id else None
    readiness = production_readiness_data(owner_id, first_job_id) if first_job_id else {}
    review_video = build_video_review_summary(owner_id, first_job_id) if first_job_id else {}
    post_publish = build_post_publish_handoff(owner_id, first_job_id, days=30) if first_job_id else {}
    distribution_pack = build_distribution_pack(owner_id, first_job_id) if first_job_id else {}
    return True, "ok", {
        **result,
        "bootstrap": bootstrap_result,
        "audit_before": {"level": before.get("level"), "score": before.get("score"), "next_command": before.get("next_command")},
        "audit_after": {"level": after.get("level"), "score": after.get("score"), "next_command": after.get("next_command")},
        "launch_next": {
            "first_job_id": first_job_id,
            "readiness": readiness,
            "review_video": review_video,
            "post_publish": post_publish,
            "distribution_pack": distribution_pack,
            "telegram": {
                "worker_next": f"/worker_next job={first_job_id}" if first_job_id else "/worker_next",
                "tasks": f"/tasks job={first_job_id}" if first_job_id else "/tasks",
                "video_brief": f"/video_brief job={first_job_id}" if first_job_id else "/video_brief job=<JOB_ID>",
                "distribution": f"/distribution_pack job={first_job_id}" if first_job_id else "/distribution_pack job=<JOB_ID>",
                "review": f"/review_video job={first_job_id} send=1" if first_job_id else "/review_video job=<JOB_ID> send=1",
                "approve": f"/approve_publish job={first_job_id} queue=1 mode=manual" if first_job_id else "/approve_publish job=<JOB_ID> queue=1 mode=manual",
                "post_publish": f"/post_publish job={first_job_id}" if first_job_id else "/post_publish job=<JOB_ID>",
            },
            "api": {
                "worker_next": "/api/operator/worker-next",
                "claim_task": "/api/operator/tasks/claim?include_context=1&include_prompt=1",
                "video_brief": f"/api/operator/jobs/{first_job_id}/video-brief" if first_job_id else "/api/operator/jobs/<JOB_ID>/video-brief",
                "video_work_orders": (
                    "/api/operator/video-work-orders?job_ids="
                    + ",".join(str(item.get("job_id")) for item in created_jobs[:8])
                ) if created_jobs else "/api/operator/video-work-orders",
                "distribution_pack": f"/api/operator/jobs/{first_job_id}/distribution-pack" if first_job_id else "/api/operator/jobs/<JOB_ID>/distribution-pack",
                "review_video": f"/api/operator/jobs/{first_job_id}/review-video" if first_job_id else "/api/operator/jobs/<JOB_ID>/review-video",
                "approve": f"/api/operator/jobs/{first_job_id}/approve" if first_job_id else "/api/operator/jobs/<JOB_ID>/approve",
                "publisher_run": "/api/operator/publisher/run",
                "post_publish": f"/api/operator/jobs/{first_job_id}/post-publish" if first_job_id else "/api/operator/jobs/<JOB_ID>/post-publish",
            },
        },
    }

async def operator_film_series_pipeline(
    owner_id,
    topic,
    platform="tiktok",
    channel="all",
    affiliate_id=0,
    campaign_id=0,
    episodes=5,
    scenes_per_episode=10,
    duration=80,
    genre="drama cảm xúc",
    audience="người lớn",
    template="dao_ly_trieu_views",
    build=True,
    bootstrap=True,
    autorun=False,
    autorun_max_tasks=24,
):
    topic = (topic or "").strip()
    if not topic:
        return False, "missing_topic", {}
    platform = (platform or "tiktok").strip().lower()
    channel = (channel or "all").strip().lower()
    episodes = max(1, min(int(episodes or 5), 8))
    scenes_per_episode = max(3, min(int(scenes_per_episode or 10), 12))
    duration = max(30, min(int(duration or 80), 180))
    genre = (genre or "drama cảm xúc").strip()
    audience = (audience or "người lớn").strip()
    template = (template or "dao_ly_trieu_views").strip()

    if bootstrap:
        counts = (operator_audit_data(owner_id).get("counts") or {})
        if int(counts.get("active_channels") or 0) <= 0 or int(counts.get("active_affiliates") or 0) <= 0 or int(counts.get("active_campaigns") or 0) <= 0:
            operator_bootstrap_data(
                owner_id,
                include_channels=True,
                include_campaigns=True,
                include_affiliates=True,
                include_references=True,
                reference_limit=200,
            )

    if channel == "all":
        channels = list_social_channels(owner_id, limit=80)
        if platform:
            channels = [ch for ch in channels if (ch[1] or "").lower() == platform]
    else:
        try:
            one_channel = get_social_channel(int(channel), owner_id)
        except (TypeError, ValueError):
            one_channel = None
        channels = [one_channel] if one_channel else []
    channels = [ch for ch in channels if ch and ch[7] == "active"]
    if not channels:
        return False, "no_active_channel", {"message": "Chưa có channel active phù hợp. Dùng /operator_bootstrap hoặc /channel_add."}
    selected_channel = channels[0]

    selected_affiliate = get_affiliate_link(affiliate_id, owner_id) if affiliate_id else None
    affiliate_score = 0
    affiliate_hits = 0
    if affiliate_id and not selected_affiliate:
        return False, "affiliate_not_found", {}
    if not selected_affiliate:
        matches = list_affiliate_matches(owner_id, niche=f"{topic} {genre} {template}", trend_text=topic, platform=platform, limit=5)
        if matches:
            affiliate_score, affiliate_hits, _blocked_hits, selected_affiliate = matches[0]
            affiliate_id = selected_affiliate[0]

    selected_campaign = get_campaign(campaign_id, owner_id) if campaign_id else None
    campaign_score = 0
    if campaign_id and not selected_campaign:
        return False, "campaign_not_found", {}
    if not selected_campaign:
        selected_campaign, campaign_score = find_matching_campaign(owner_id, f"{topic} {genre} {template}", platform)
        campaign_id = selected_campaign[0] if selected_campaign else 0

    blueprint = ai_film_series_blueprint_data()
    template_item = next((item for item in blueprint.get("template_library", []) if item.get("id") == template), None)
    series_title = f"{topic[:80]} - Series AI Affiliate"
    character_bible = {
        "lead": {
            "fixed_description": "Vietnamese main character, consistent face and outfit style across all episodes, realistic cinematic look",
            "negative_prompt": "different face, different age, cartoon, distorted body, extra fingers, text, watermark",
        },
        "support": {
            "fixed_description": "Vietnamese supporting character, consistent appearance, natural expression, realistic cinematic look",
            "negative_prompt": "different face, inconsistent outfit, text, watermark, low quality",
        },
    }
    if selected_affiliate:
        (
            aid, network, product, aff_niche, url, note, status,
            price_vnd, commission_rate, target_audience, allowed_claims, blocked_claims, product_score
        ) = selected_affiliate
        affiliate_payload = {
            "id": aid,
            "network": network,
            "product": product,
            "niche": aff_niche,
            "url": url,
            "match_score": affiliate_score,
            "match_hits": affiliate_hits,
            "allowed_claims": allowed_claims,
            "blocked_claims": blocked_claims,
        }
    else:
        affiliate_payload = None

    created_jobs = []
    built_jobs = []
    failed_builds = []
    for ep in range(1, episodes + 1):
        episode_title = f"Tập {ep}/{episodes}: {topic}"
        cliffhanger = "Mở nút một phần và để lại câu hỏi cho tập sau." if ep < episodes else "Kết thúc bằng bài học/CTA mềm và gợi ý sản phẩm liên quan."
        brief_obj = {
            "type": "ai_film_series_episode",
            "series_title": series_title,
            "topic": topic,
            "episode_number": ep,
            "episode_count": episodes,
            "episode_title": episode_title,
            "genre": genre,
            "target_audience": audience,
            "template": template,
            "template_hint": template_item,
            "duration_seconds": duration,
            "scenes_per_episode": scenes_per_episode,
            "aspect_ratio": "9:16",
            "character_bible": character_bible,
            "episode_arc": (blueprint.get("series_structure") or {}).get("episode_arc"),
            "cliffhanger_rule": cliffhanger,
            "affiliate": affiliate_payload,
            "voice_profile": (blueprint.get("voice_profile_contract") or {}).get("schema"),
            "guardrails": (blueprint.get("viral_remix_modes") or {}).get("copyright_guard"),
            "affiliate_comment_manager": blueprint.get("affiliate_comment_manager"),
            "worker_prompt": (blueprint.get("worker_prompt_template") or "").format(
                episodes=episodes,
                scenes_per_episode=scenes_per_episode,
            ),
        }
        cid, channel_platform, channel_name, account_label, focus, channel_audience, slots, status = selected_channel
        slot_id = create_calendar_slot(
            owner_id,
            cid,
            campaign_id,
            affiliate_id,
            (datetime.now().date() + timedelta(days=ep - 1)).isoformat(),
            channel_platform or platform,
            episode_title,
            f"film_series template={template} episode={ep}/{episodes}",
        )
        job_id = create_production_job(
            owner_id,
            slot_id,
            campaign_id,
            cid,
            affiliate_id,
            channel_platform or platform,
            episode_title,
            json.dumps(brief_obj, ensure_ascii=False),
            f"film_series | series={series_title} | template={template} | episode={ep}/{episodes}",
        )
        created_jobs.append({
            "job_id": job_id,
            "slot_id": slot_id,
            "episode": ep,
            "episode_title": episode_title,
            "platform": channel_platform or platform,
            "channel_name": channel_name,
        })
        if build:
            ok, bundle = build_operator_job_bundle(owner_id, job_id, count=5, duration=duration)
            if ok:
                built_jobs.append({
                    "job_id": job_id,
                    "episode": ep,
                    "manifest_id": bundle.get("manifest_id"),
                    "task_count": len(bundle.get("task_ids") or []),
                    "variant_id": bundle.get("best_variant_id"),
                    "readiness": (bundle.get("readiness") or {}).get("level", "UNKNOWN"),
                })
            else:
                failed_builds.append({"job_id": job_id, "episode": ep, "error": bundle.get("error", "build lỗi") if isinstance(bundle, dict) else "build lỗi"})

    created_job_ids = [item["job_id"] for item in created_jobs]
    autorun_result = None
    if build and autorun and created_job_ids:
        autorun_result = await operator_worker_autorun_data(
            owner_id,
            job_ids=created_job_ids,
            limit=min(len(created_job_ids), 8),
            max_tasks=autorun_max_tasks,
            execute=True,
        )

    worker_next = operator_worker_next_summary(owner_id, created_job_ids, limit=min(len(created_jobs), 8))
    work_orders = operator_mission_work_orders_data(
        owner_id,
        result_payload={"created_jobs": created_jobs, "built_jobs": built_jobs},
        limit=min(len(created_jobs), 8),
        include_prompt=True,
    )
    video_work_orders = operator_video_work_orders_data(
        owner_id,
        [item["job_id"] for item in created_jobs],
        limit=min(len(created_jobs), 8) or 1,
    )
    campaign_name = ""
    if selected_campaign:
        campaign_name = selected_campaign[2] if len(selected_campaign) >= 8 else selected_campaign[1]
    return True, "ok", {
        "series": {
            "title": series_title,
            "topic": topic,
            "genre": genre,
            "audience": audience,
            "template": template,
            "episodes": episodes,
            "scenes_per_episode": scenes_per_episode,
            "duration_seconds": duration,
            "character_bible": character_bible,
        },
        "affiliate": affiliate_payload,
        "campaign": {
            "id": campaign_id,
            "match_score": campaign_score,
            "name": campaign_name,
        },
        "created_jobs": created_jobs,
        "built_jobs": built_jobs,
        "failed_builds": failed_builds,
        "worker_next": worker_next,
        "work_orders": work_orders,
        "video_work_orders": video_work_orders,
        "autorun": autorun_result,
        "next": {
            "worker_intake": "/api/operator/worker-intake?claim=0&include_prompt=1",
            "claim_worker": "/api/operator/worker-intake?claim=1&include_prompt=1",
            "worker_autorun": (
                "/worker_autorun jobs="
                + ",".join(str(item["job_id"]) for item in created_jobs[:8])
                + " execute=1"
            ) if created_jobs else "/worker_autorun execute=1",
            "review": "/review_video job=<JOB_ID> send=1",
            "approve": "/approve_publish job=<JOB_ID> queue=1 mode=manual",
        },
        "rule": "Film series tạo một job cho mỗi tập; worker tạo scene assets rồi dừng ở review/publish gate.",
    }

async def operator_campaign_preset_data(
    owner_id,
    preset_key="tech",
    topic="",
    platform="",
    channel="all",
    limit=3,
    build=True,
    execute=False,
    duration=45,
    variants=5,
    bootstrap=True,
):
    preset = get_campaign_preset(preset_key)
    topic = (topic or preset.get("topic") or preset.get("niche") or "công nghệ AI").strip()
    requested_platform = (platform or "").strip().lower()
    if requested_platform and requested_platform not in {"all", "*"}:
        platforms = [requested_platform]
    else:
        platforms = list(preset.get("platforms") or ["tiktok"])
    platforms = platforms[:4]
    limit = max(1, min(int(limit or 3), 8))
    duration = max(15, min(int(duration or 45), 120))
    variants = max(3, min(int(variants or 5), 8))

    bootstrap_result = None
    if bootstrap and execute:
        bootstrap_result = operator_bootstrap_data(
            owner_id,
            include_channels=True,
            include_campaigns=True,
            include_affiliates=True,
            include_references=False,
        )
    if execute:
        campaign, campaign_created = ensure_campaign_for_preset(owner_id, preset)
    else:
        campaign = find_campaign_by_name(owner_id, preset.get("campaign_name") or preset.get("name") or "")
        campaign_created = False
    campaign_id = campaign[0] if campaign else 0
    campaign_name = (
        campaign[2] if campaign and len(campaign) >= 8
        else (campaign[1] if campaign else (preset.get("campaign_name") or preset.get("name") or ""))
    )

    plan = []
    executions = []
    errors = []
    for plat in platforms:
        router = operator_channel_router_data(owner_id, platform=plat, niche=preset.get("niche", ""), limit=limit)
        matches = list_affiliate_matches(
            owner_id,
            niche=preset.get("niche", ""),
            trend_text=f"{topic} {preset.get('affiliate_query', '')}",
            platform=plat,
            limit=8,
        )
        affiliate_cards = []
        for score, hits, blocked_hits, row in matches[:8]:
            aid, network, product, niche, url, note, status, *_rest = row
            affiliate_cards.append({
                "id": aid,
                "network": network,
                "product": product,
                "niche": niche,
                "url": url,
                "score": score,
                "hits": hits,
                "blocked_hits": blocked_hits,
            })
        selected_affiliate_id = affiliate_cards[0]["id"] if affiliate_cards else 0
        recommended_channel = (router.get("recommended") or [{}])[0]
        channel_arg = channel or "all"
        launch_command = (
            f"/operator_launch topic={topic} platform={plat} channel={channel_arg} "
            f"aff={selected_affiliate_id or 0} camp={campaign_id or 0} limit={limit} "
            f"build={1 if build else 0} duration={duration} variants={variants}"
        )
        plan_item = {
            "platform": plat,
            "topic": topic,
            "campaign_id": campaign_id,
            "campaign_created": campaign_created,
            "selected_affiliate_id": selected_affiliate_id,
            "top_affiliates": affiliate_cards,
            "recommended_channel": recommended_channel,
            "router_counts": router.get("counts") or {},
            "launch_command": launch_command,
            "content_angle": preset.get("angle", ""),
            "compliance": preset.get("compliance", ""),
            "tracking_rule": "Mỗi publish phải dùng tracking_url /r/<affiliate_id>, ghi views/click/order/revenue qua /performance_add hoặc postback.",
        }
        plan.append(plan_item)
        if execute:
            try:
                ok, reason, result = await operator_launch_pipeline(
                    owner_id,
                    topic,
                    platform=plat,
                    channel=channel_arg,
                    affiliate_id=selected_affiliate_id,
                    campaign_id=campaign_id,
                    limit=limit,
                    build=build,
                    duration=duration,
                    variants=variants,
                    bootstrap=False,
                )
                if ok:
                    executions.append({
                        "platform": plat,
                        "created_jobs": result.get("created_jobs") or [],
                        "built_jobs": result.get("built_jobs") or [],
                        "first_job_id": ((result.get("launch_next") or {}).get("first_job_id") or 0),
                        "launch_next": result.get("launch_next") or {},
                    })
                else:
                    errors.append({"platform": plat, "reason": reason, "detail": result})
            except Exception as e:
                errors.append({"platform": plat, "reason": str(e)})

    return {
        "ok": True,
        "generated_at": now_text(),
        "execute": bool(execute),
        "preset": {
            "key": preset.get("key"),
            "name": preset.get("name"),
            "niche": preset.get("niche"),
            "topic": topic,
            "platforms": platforms,
            "angle": preset.get("angle"),
            "affiliate_query": preset.get("affiliate_query"),
            "compliance": preset.get("compliance"),
        },
        "campaign": {
            "id": campaign_id,
            "created": campaign_created,
            "name": campaign_name,
        },
        "bootstrap": bootstrap_result,
        "plan": plan,
        "executions": executions,
        "errors": errors,
        "commands": {
            "preview": f"/campaign_preset preset={preset.get('key')} platform={requested_platform or 'all'} limit={limit}",
            "execute": f"/campaign_preset preset={preset.get('key')} platform={requested_platform or 'all'} limit={limit} execute=1 build={1 if build else 0}",
            "money": "/money_pack",
            "scale": "/scale_plan",
        },
        "rule": "Preset chỉ dành cho admin. Finance phải minh bạch điều kiện; OnlyFans manual-only và chỉ dùng nhân vật/consent hợp pháp 18+; mọi job vẫn qua review gate trước publish.",
    }

