def build_review_gate_prompt(job):
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    return (
        "Bạn là AI compliance reviewer cho TOAN AAS. Hãy kiểm duyệt production job trước khi đăng. "
        "Không cần trích dẫn luật; hãy kiểm tra thực dụng theo rủi ro nền tảng và rủi ro kinh doanh.\n\n"
        f"Job ID: #{jid}\n"
        f"Platform: {platform or '-'}\n"
        f"Channel/account: {channel_name or channel_id or '-'} / {account_label or 'main'}\n"
        f"Topic: {topic or '-'}\n"
        f"Stage/status: {stage or '-'} / {status or '-'}\n"
        f"Affiliate: {network or '-'} - {product_name or '-'} - {affiliate_url or '-'}\n"
        f"Asset URL: {asset_url or 'chưa có'}\n"
        f"Publish URL: {publish_url or 'chưa có'}\n"
        f"Operator note: {note or '-'}\n\n"
        f"Brief/publish context:\n{brief or 'Chưa có brief'}\n\n"
        "Trả về tiếng Việt theo format:\n"
        "DECISION: APPROVE hoặc FIX hoặc BLOCK\n"
        "RISK_LEVEL: LOW/MEDIUM/HIGH\n"
        "CHECKLIST:\n"
        "- Quyền hình ảnh/nhân vật/consent 18+ nếu có người mẫu hoặc OnlyFans\n"
        "- Quyền âm thanh/voice/music\n"
        "- Affiliate claim có minh bạch, không cam kết thu nhập phi thực tế\n"
        "- Không spam, không mạo danh, không né kiểm duyệt\n"
        "- Caption/CTA không gây hiểu nhầm\n"
        "- Có link affiliate và tracking cần thiết\n"
        "FIX_REQUIRED: các điểm phải sửa trước khi đăng\n"
        "APPROVAL_NOTE: câu ngắn để lưu vào pipeline"
    )

def slots_per_day(posting_slots: str) -> int:
    digits = "".join(ch for ch in (posting_slots or "") if ch.isdigit())
    if not digits:
        return 2
    return max(1, min(int(digits), 5))

def content_topic_for_slot(niche, channel_focus, platform, day_index, slot_index):
    focus = channel_focus or niche or "công nghệ"
    templates = [
        "Review nhanh {focus}: vấn đề thật và cách TOAN AAS xử lý",
        "Top công cụ {focus} đáng dùng trong ngày",
        "Case study kiếm tiền với {focus} và link affiliate phù hợp",
        "So sánh sản phẩm {focus}: nên mua loại nào",
        "Checklist tạo nội dung {focus} để bán hàng bền vững",
        "Lỗi thường gặp khi làm {focus} và cách sửa",
    ]
    template = templates[(day_index + slot_index) % len(templates)]
    return f"{template.format(focus=focus)} ({platform})"

def safe_positive_int(value, default=1):
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return default
    return parsed if parsed > 0 else default

def ceil_mb(size_bytes: int) -> int:
    size = safe_positive_int(size_bytes, 1)
    return max(1, math.ceil(size / (1024 * 1024)))

def calculate_mb_cost(size_bytes: int, base_cost: int, cost_per_mb: int, min_cost: int) -> int:
    mb = ceil_mb(size_bytes)
    return max(int(min_cost), int(base_cost) + mb * int(cost_per_mb))

def calculate_audio_cost(size_bytes: int) -> int:
    return calculate_mb_cost(size_bytes, AUDIO_BASE_COST, AUDIO_COST_PER_MB, AUDIO_MIN_COST)

def calculate_video_download_cost(size_bytes: int) -> int:
    return calculate_mb_cost(size_bytes, VIDEO_DOWNLOAD_BASE_COST, VIDEO_DOWNLOAD_COST_PER_MB, VIDEO_DOWNLOAD_MIN_COST)

def calculate_voice_cost(text: str) -> int:
    chars = len(text or "")
    blocks = max(1, math.ceil(chars / VOICE_BLOCK_CHARS))
    return VOICE_BASE_COST + blocks * VOICE_COST_PER_BLOCK

def calculate_voice_cost_by_length(chars) -> int:
    length = safe_positive_int(chars, 1)
    blocks = max(1, math.ceil(length / VOICE_BLOCK_CHARS))
    return VOICE_BASE_COST + blocks * VOICE_COST_PER_BLOCK

def calculate_chat_cost(size_or_length) -> int:
    length = safe_positive_int(size_or_length, 1)
    if length <= 500:
        return CHAT_SHORT_COST
    if length <= 2000:
        return CHAT_LONG_COST
    return CHAT_HEAVY_COST

def normalize_chat_tier(value: str) -> str:
    tier = str(value or CHAT_TIER_PRO).strip().lower()
    if tier == CHAT_TIER_DEEP:
        return CHAT_TIER_PRO
    return tier if tier in {CHAT_TIER_NORMAL, CHAT_TIER_PRO} else CHAT_TIER_PRO

def normalize_chat_model(value: str) -> str:
    model = str(value or "auto").strip().lower().replace("-", "_")
    aliases = {
        "gpt": "openai",
        "chatgpt": "openai",
        "chatgpt_pro": "gpt_pro",
        "gemini": "gemini",
        "gemini_advanced": "gemini_pro",
        "claude_sonnet": "sonnet",
        "claude_opus": "opus",
    }
    return aliases.get(model, model or "auto")

def estimate_text_mb(text: str) -> int:
    chars = len(text or "")
    if chars <= 0:
        return 1
    return max(1, math.ceil(chars / CHAT_TEXT_MB_CHARS))

def calculate_chat_pro_cost(text: str, tier: str = CHAT_TIER_PRO, model_level: str = "standard") -> int:
    units = estimate_text_mb(text)
    tier_norm = normalize_chat_tier(tier)
    model_norm = normalize_chat_model(model_level)
    if tier_norm == CHAT_TIER_DEEP or model_norm in CHAT_ADVANCED_MODEL_LEVELS:
        base = CHAT_PRO_DEEP_COST
    elif tier_norm == CHAT_TIER_PRO:
        base = CHAT_PRO_STANDARD_COST
    else:
        base = CHAT_PRO_BASE_COST
    cost = base + max(0, units - 1) * CHAT_PRO_MB_UNIT_COST
    return min(max(CHAT_PRO_MIN_COST, cost), CHAT_PRO_MAX_COST)

def choose_chat_provider(tier=CHAT_TIER_NORMAL, requested_model="auto") -> dict:
    tier_norm = normalize_chat_tier(tier)
    model_norm = normalize_chat_model(requested_model)

    if model_norm in {"sonnet", "opus", "claude"}:
        return {
            "provider": "claude",
            "model_label": "Claude Sonnet/Opus",
            "ready": False,
            "reason": "Claude Pro chưa được cấu hình trong bản hiện tại.",
            "tier": tier_norm,
            "model": model_norm,
        }
    if model_norm == "grok":
        return {
            "provider": "grok",
            "model_label": "Grok cao cấp",
            "ready": False,
            "reason": "Grok chưa được cấu hình trong bản hiện tại.",
            "tier": tier_norm,
            "model": model_norm,
        }
    if model_norm in {"openai", "gpt_pro"}:
        return {
            "provider": "openai",
            "model_label": "OpenAI Pro" if model_norm == "gpt_pro" else "OpenAI",
            "ready": bool(openai_client),
            "reason": "" if openai_client else "OpenAI chưa được cấu hình.",
            "tier": tier_norm,
            "model": model_norm,
        }
    if model_norm in {"gemini", "gemini_pro"}:
        return {
            "provider": "gemini",
            "model_label": "Gemini Pro" if model_norm == "gemini_pro" or tier_norm == CHAT_TIER_DEEP else "Gemini Flash",
            "ready": bool(gemini_client),
            "reason": "" if gemini_client else "Gemini chưa được cấu hình.",
            "tier": tier_norm,
            "model": model_norm,
        }

    if gemini_client:
        return {
            "provider": "gemini",
            "model_label": "Gemini Pro" if tier_norm in {CHAT_TIER_PRO, CHAT_TIER_DEEP} else "Gemini Flash",
            "ready": True,
            "reason": "",
            "tier": tier_norm,
            "model": "auto",
        }
    if openai_client:
        return {
            "provider": "openai",
            "model_label": "OpenAI Pro" if tier_norm in {CHAT_TIER_PRO, CHAT_TIER_DEEP} else "OpenAI Fast",
            "ready": True,
            "reason": "",
            "tier": tier_norm,
            "model": "auto",
        }
    return {
        "provider": "none",
        "model_label": "No AI provider",
        "ready": False,
        "reason": "Thiếu GEMINI_API_KEY hoặc OPENAI_API_KEY.",
        "tier": tier_norm,
        "model": model_norm,
    }

def calculate_film_cost(episodes=1, scenes=5, tier="basic") -> int:
    tier_norm = str(tier or "basic").strip().lower()
    if tier_norm == "pro":
        return VIDEO_PRO_COST
    if tier_norm == "series":
        return VIDEO_SERIES_COST
    episode_count = safe_positive_int(episodes, 1)
    scene_count = safe_positive_int(scenes, 5)
    extra_episode_cost = max(0, episode_count - 1) * 100
    extra_scene_cost = max(0, scene_count - 5) * 20
    return max(VIDEO_BASIC_COST, VIDEO_BASIC_COST + extra_episode_cost + extra_scene_cost)

def calculate_dynamic_cost(action_type, size_or_length):
    if action_type == "chat":
        return calculate_chat_cost(size_or_length)
    elif action_type == "whisper":
        return calculate_audio_cost(size_or_length)
    elif action_type == "image":
        return IMAGE_REMOVE_BG_PREMIUM_COST
    elif action_type == "voice":
        return calculate_voice_cost_by_length(size_or_length)
    elif action_type == "download":
        return calculate_video_download_cost(size_or_length)
    return CHAT_SHORT_COST

def apply_discount(total_spent, raw_cost):
    # Legacy helper kept for compatibility with older tests/helpers.
    # New service charges must use apply_member_service_discount().
    if total_spent >= 20000:
        discount = 0.20
    elif total_spent >= 5000:
        discount = 0.10
    else:
        discount = 0.0
    return math.ceil(int(raw_cost or 0) * (1 - discount)), discount

def deduct_dynamic_credit(user_id, action_type, size_or_length) -> tuple:
    if str(user_id) == ADMIN_ID:
        return True, 0, 1.0
    credits, total_spent, is_vip = get_user(user_id)
    raw_cost  = calculate_dynamic_cost(action_type, size_or_length)
    charge = apply_member_service_discount(user_id, raw_cost, action_type)
    final_cost = int(charge.get("final_cost") or 0)
    discount_rate = int(charge.get("discount_rate") or 0) / 100
    if credits >= final_cost:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            "UPDATE users SET credits = credits - ?, total_spent = total_spent + ? WHERE user_id=?",
            (final_cost, final_cost, str(user_id))
        )
        c.execute(
            "INSERT INTO transactions (user_id, action, cost, discount_rate, created_at) VALUES (?,?,?,?,?)",
            (str(user_id), action_type, final_cost, discount_rate, now_text())
        )
        note = f"Trừ xu cho {action_type}"
        if int(charge.get("discount_xu") or 0) > 0:
            note += (
                f" | member_discount tier={charge.get('tier')} base={charge.get('base_cost')} "
                f"rate={charge.get('discount_rate')} discount={charge.get('discount_xu')} final={final_cost}"
            )
        record_credit_event(conn, user_id, -final_cost, f"spend_{action_type}", "", note)
        conn.commit()
        conn.close()
        return True, final_cost, discount_rate
    return False, final_cost, discount_rate

def process_payos_paid_order(
    order_code: str,
    amount_vnd: int,
    webhook_payment_link_id: str = "",
    transaction_id: str = "",
    webhook_status: str = "",
    webhook_currency: str = "",
    raw_hash: str = "",
) -> tuple[bool, str, dict]:
    """
    Cộng xu cho đơn PayOS trong một transaction để tránh cộng trùng.
    Trả về (processed, desc, info).
    """
    if not order_code:
        return False, "missing_order_code", {}
    if flag_on("emergency_lock") or flag_on("payment_freeze"):
        return False, "payment_frozen", {"order_code": str(order_code), "amount": int(amount_vnd or 0)}

    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute("BEGIN IMMEDIATE")
        c.execute(
            """SELECT user_id, amount, xu, status, expires_at,
                      COALESCE(order_type,'topup'), COALESCE(plan_id,''), COALESCE(plan_name,''),
                      COALESCE(duration_days,0), COALESCE(plan_xu,0), COALESCE(metadata_json,''),
                      COALESCE(payment_type,''), COALESCE(package_id,''), COALESCE(payment_link_id,'')
               FROM payos_orders WHERE order_code=?""",
            (str(order_code),)
        )
        order = c.fetchone()
        if not order:
            conn.rollback()
            return False, "order_not_found", {}

        target_id, expected_amount, xu, status, expires_at, order_type, plan_id, plan_name, duration_days, plan_xu, metadata_json, payment_type, package_id, payment_link_id = order
        order_type = str(order_type or "topup")
        stored_payment_link_id = str(payment_link_id or "").strip()
        incoming_payment_link_id = str(webhook_payment_link_id or "").strip()
        effective_payment_link_id = incoming_payment_link_id or stored_payment_link_id
        clean_transaction_id = str(transaction_id or "").strip()
        try:
            metadata = json.loads(metadata_json or "{}") if metadata_json else {}
            if not isinstance(metadata, dict):
                metadata = {}
        except Exception:
            metadata = {}
        payment_type = normalize_payment_type(payment_type, order_type, metadata)
        package_id = str(package_id or payment_package_id(order_type, plan_id, metadata))
        expected_currency = str(metadata.get("currency") or "VND").strip().upper()
        incoming_currency = str(webhook_currency or "").strip().upper()
        stored_xu = int(xu or 0)
        invoice_subtotal_vnd = finance_order_subtotal_from_metadata(metadata, expected_amount)
        invoice_vat_vnd = int(metadata.get("vat_amount_vnd") or max(0, int(expected_amount or 0) - int(invoice_subtotal_vnd or 0)))
        calculated_base_xu = package_base_xu(invoice_subtotal_vnd)
        base_xu = calculated_base_xu if calculated_base_xu > 0 else stored_xu
        account_market = canonical_user_market_snapshot_conn(conn, target_id)
        payment_method = metadata.get("payment_method") or metadata.get("method") or "payos"
        payment_currency = str(metadata.get("currency") or "VND").strip().upper()
        user_market_value = (
            account_market.get("user_market")
            or normalize_user_market(metadata.get("user_market_snapshot"))
        )
        payment_market_value = canonical_payment_market(payment_method, payment_currency, metadata.get("payment_market") or "")
        topup_payment_context = {
            "payment_type": payment_type,
            "method": metadata.get("payment_method") or metadata.get("method") or "payos",
            "currency": metadata.get("currency") or "VND",
            "amount_vnd": int(invoice_subtotal_vnd or 0),
            "package_key": package_id or metadata.get("pkg_key") or "",
            "foreign_manual": bool(metadata.get("foreign_manual") or False),
            "user_market": user_market_value,
            "user_market_snapshot": user_market_value,
            "payment_market": payment_market_value,
            "international_account": bool(
                account_market.get("international_account")
                or metadata.get("international_account")
            ),
            "transaction_id": clean_transaction_id,
            "payment_status": webhook_status or PAYOS_STATUS_PAID,
            "amount_valid": int(expected_amount or 0) == int(amount_vnd or 0),
            "base_credit_success": base_xu > 0,
            "is_test": bool(metadata.get("is_test") or metadata.get("test_payment")),
            "is_refund": bool(metadata.get("is_refund") or metadata.get("refunded")),
        }
        info = {
            "target_id": target_id,
            "expected_amount": expected_amount,
            "xu": base_xu,
            "status": status,
            "order_type": order_type,
            "plan_id": plan_id or "",
            "plan_name": plan_name or "",
            "plan_xu": int(plan_xu or 0),
            "metadata": metadata,
            "payment_type": payment_type,
            "package_id": package_id,
            "payment_link_id": effective_payment_link_id or "",
            "transaction_id": clean_transaction_id,
            "currency": expected_currency,
            "webhook_currency": incoming_currency,
            "subtotal_amount_vnd": int(invoice_subtotal_vnd or 0),
            "vat_amount_vnd": int(invoice_vat_vnd or 0),
            "total_amount_vnd": int(expected_amount or 0),
        }

        if status == PAYOS_STATUS_PAID:
            flag_finance_anomaly_conn(
                conn,
                str(order_code),
                str(target_id),
                "duplicate_callback",
                expected_amount_vnd=int(expected_amount or 0),
                actual_amount_vnd=int(amount_vnd or 0),
                reason="PayOS callback received after order was already paid; no double credit/grant.",
                metadata=metadata,
                severity="info",
                mark_order_review=False,
            )
            conn.commit()
            if order_type == "package_purchase":
                info.update({"flagged": True, "flag_reason": "duplicate_callback"})
                return False, "duplicate_callback", info
            return False, "already_paid", info
        if status == PAYOS_STATUS_PENDING_ADMIN_REVIEW:
            conn.rollback()
            return False, "pending_admin_review", info
        if status in (PAYOS_STATUS_EXPIRED, PAYOS_STATUS_CANCELLED):
            conn.rollback()
            return False, status.lower(), info
        if expires_at and expires_at < now_text():
            c.execute("UPDATE payos_orders SET status=? WHERE order_code=?", (PAYOS_STATUS_EXPIRED, str(order_code)))
            conn.commit()
            return False, "expired", info
        if int(expected_amount) != int(amount_vnd):
            flag_finance_anomaly_conn(
                conn,
                str(order_code),
                str(target_id),
                "amount_mismatch",
                expected_amount_vnd=int(expected_amount or 0),
                actual_amount_vnd=int(amount_vnd or 0),
                reason="Paid amount does not match expected invoice total.",
                metadata=metadata,
            )
            if order_type == "package_purchase":
                flag = flag_package_order_for_admin_conn(
                    conn,
                    str(order_code),
                    metadata,
                    "amount_mismatch",
                    paid_amount_vnd=int(amount_vnd or 0),
                    note=f"expected={int(expected_amount or 0)} paid={int(amount_vnd or 0)}",
                )
                info.update(flag)
                conn.commit()
                return False, "package_order_flagged", info
            conn.commit()
            return False, "amount_mismatch", info
        if incoming_currency and expected_currency and incoming_currency != expected_currency:
            flag_finance_anomaly_conn(
                conn,
                str(order_code),
                str(target_id),
                "currency_mismatch",
                expected_amount_vnd=int(expected_amount or 0),
                actual_amount_vnd=int(amount_vnd or 0),
                reason=f"Webhook currency {incoming_currency} does not match invoice currency {expected_currency}.",
                metadata=metadata,
            )
            if order_type == "package_purchase":
                flag = flag_package_order_for_admin_conn(
                    conn,
                    str(order_code),
                    metadata,
                    "currency_mismatch",
                    paid_amount_vnd=int(amount_vnd or 0),
                    note=f"expected={expected_currency} incoming={incoming_currency}",
                )
                info.update(flag)
                conn.commit()
                return False, "package_order_flagged", info
            conn.commit()
            return False, "currency_mismatch", info

        if webhook_status and not payos_webhook_is_paid_status(webhook_status):
            conn.rollback()
            return False, "status_not_paid", info
        if incoming_payment_link_id and stored_payment_link_id and incoming_payment_link_id != stored_payment_link_id:
            flag_finance_anomaly_conn(
                conn,
                str(order_code),
                str(target_id),
                "payment_link_mismatch",
                expected_amount_vnd=int(expected_amount or 0),
                actual_amount_vnd=int(amount_vnd or 0),
                reason="Webhook paymentLinkId does not match the stored PayOS paymentLinkId.",
                metadata=metadata,
            )
            if order_type == "package_purchase":
                flag = flag_package_order_for_admin_conn(
                    conn,
                    str(order_code),
                    metadata,
                    "payment_link_mismatch",
                    paid_amount_vnd=int(amount_vnd or 0),
                    note=f"stored={stored_payment_link_id} incoming={incoming_payment_link_id}",
                )
                info.update(flag)
                conn.commit()
                return False, "package_order_flagged", info
            conn.commit()
            return False, "payment_link_mismatch", info

        idempotency = reserve_payos_idempotency_conn(
            conn,
            order_code=str(order_code),
            amount_vnd=int(amount_vnd or 0),
            user_id=str(target_id or ""),
            payment_link_id=effective_payment_link_id,
            transaction_id=clean_transaction_id,
            status=webhook_status or PAYOS_STATUS_PAID,
            raw_hash=raw_hash,
        )
        info["idempotency"] = idempotency
        if not idempotency.get("ok"):
            conn.rollback()
            return False, str(idempotency.get("reason") or "duplicate"), info
        idempotency_event_key = str(idempotency.get("event_key") or "")

        if order_type == "package_purchase":
            package_type = "monthly" if str(metadata.get("package_type") or "").lower() in {"monthly", "month", "plan", "task", "package"} else "combo"
            package_code = str(metadata.get("package_code") or plan_id or "").strip().lower()
            entry = package_catalog_entry(package_code, package_type)
            if not entry:
                flag = flag_package_order_for_admin_conn(conn, str(order_code), metadata, "invalid_package_order", paid_amount_vnd=int(amount_vnd or 0))
                info.update(flag)
                conn.commit()
                return False, "package_order_flagged", info
            if not package_entry_auto_checkout_enabled(entry):
                flag = flag_package_order_for_admin_conn(conn, str(order_code), metadata, "quota_handler_not_ready", paid_amount_vnd=int(amount_vnd or 0))
                info.update(flag)
                conn.commit()
                return False, "package_order_flagged", info
            if user_bought_package_this_month(target_id, package_code, package_type, conn=conn, exclude_order_code=str(order_code)):
                flag = flag_package_order_for_admin_conn(conn, str(order_code), metadata, "same_package_month", paid_amount_vnd=int(amount_vnd or 0))
                info.update(flag)
                conn.commit()
                return False, "package_order_flagged", info
            user_row = c.execute("SELECT 1 FROM users WHERE user_id=?", (str(target_id),)).fetchone()
            if not user_row:
                c.execute(
                    "INSERT INTO users (user_id, username, credits, is_vip, join_date, total_spent, has_deposited) VALUES (?,?,?,?,?,?,?)",
                    (str(target_id), "PayOS package user", 0, 0, now_text(), 0, 0),
                )
            package_result = grant_user_package_conn(
                conn,
                target_id,
                package_code,
                package_type,
                "payos",
                days=int(duration_days or entry.get("default_days") or 0),
                note=f"PayOS order {order_code}",
                source=f"payos_{package_type}",
            )
            if not package_result.get("ok"):
                flag = flag_package_order_for_admin_conn(
                    conn,
                    str(order_code),
                    metadata,
                    package_result.get("reason") or "package_grant_failed",
                    paid_amount_vnd=int(amount_vnd or 0),
                )
                info.update(flag)
                conn.commit()
                return False, "package_order_flagged", info
            c.execute(
                "UPDATE payos_orders SET status=?, paid_at=? WHERE order_code=?",
                (PAYOS_STATUS_PAID, now_text(), str(order_code)),
            )
            update_finance_invoice_status_conn(conn, str(order_code), "granted", paid_at=now_text(), granted_at=now_text())
            record_payos_processed_conn(conn, order_code, payment_type, "success", effective_payment_link_id)
            mark_payos_idempotency_credited_conn(conn, idempotency_event_key)
            item_summary = package_items_summary(entry.get("items") or {})
            record_usage_event_conn(
                conn,
                target_id,
                event_type="payment_payos_package_success",
                tool_name="package_wallet",
                command="/webhook/payos",
                status="paid",
                xu_delta=0,
                amount_vnd=int(invoice_subtotal_vnd or 0),
                provider="payos",
                detail=f"order={order_code}; package_type={package_type}; package_code={package_code}; counts_for_member_tier=false",
            )
            record_finance_revenue_event_conn(
                conn,
                target_id,
                "monthly_plan" if package_type == "monthly" else "combo_purchase",
                str(order_code),
                int(invoice_subtotal_vnd or 0),
                0,
                "payos",
                "success",
                f"PayOS package purchase {package_type}:{package_code}",
            )
            record_audit(
                conn,
                "payos",
                "system",
                "package.paid",
                "payos_order",
                str(order_code),
                before={"status": status, "amount": expected_amount, "order_type": order_type},
                after={"status": PAYOS_STATUS_PAID, "user_id": target_id, "package_type": package_type, "package_code": package_code, "subtotal": invoice_subtotal_vnd, "vat": invoice_vat_vnd, "total": amount_vnd},
                note="PayOS package paid; saved to package wallet; not counted as top-up",
            )
            emit_event(
                conn,
                "package.paid",
                "payos",
                {"order_code": str(order_code), "user_id": str(target_id), "amount": int(invoice_subtotal_vnd), "vat": int(invoice_vat_vnd), "total": int(amount_vnd), "package_type": package_type, "package_code": package_code},
                status="processed",
            )
            info.update({
                "xu": 0,
                "package_type": package_type,
                "package_code": package_code,
                "package_label": entry.get("label") or package_code,
                "package_items": item_summary,
                "package_id": int(package_result.get("package_id") or 0),
                "expires_at": package_result.get("expires_at") or "",
            })
            conn.commit()
            return True, "package_success", info

        if order_type == "plan_purchase":
            if not normalize_plan_id(plan_id):
                conn.rollback()
                return False, "invalid_plan_order", info
            user_row = c.execute("SELECT 1 FROM users WHERE user_id=?", (str(target_id),)).fetchone()
            if not user_row:
                c.execute(
                    "INSERT INTO users (user_id, username, credits, is_vip, join_date, total_spent, has_deposited) VALUES (?,?,?,?,?,?,?)",
                    (str(target_id), "PayOS plan user", 0, 0, now_text(), 0, 0),
                )
            activation = activate_user_plan_conn(
                conn,
                target_id,
                plan_id,
                days=int(duration_days or PLAN_CATALOG[plan_id]["duration_days"]),
                order_code=str(order_code),
                source="payos",
            )
            c.execute(
                "UPDATE payos_orders SET status=?, paid_at=? WHERE order_code=?",
                (PAYOS_STATUS_PAID, now_text(), str(order_code)),
            )
            update_finance_invoice_status_conn(conn, str(order_code), "granted", paid_at=now_text(), granted_at=now_text())
            record_payos_processed_conn(conn, order_code, payment_type, "success", effective_payment_link_id)
            mark_payos_idempotency_credited_conn(conn, idempotency_event_key)
            record_usage_event_conn(
                conn,
                target_id,
                event_type="payment_payos_plan_success",
                tool_name="subscription",
                command="/webhook/payos",
                status="paid",
                xu_delta=0,
                amount_vnd=int(invoice_subtotal_vnd or 0),
                provider="payos",
                detail=f"order={order_code}; plan={plan_id}; plan_xu={int(plan_xu or 0)}; counts_for_member_tier=false",
            )
            record_finance_revenue_event_conn(
                conn,
                target_id,
                "monthly_plan",
                str(order_code),
                int(invoice_subtotal_vnd or 0),
                0,
                "payos",
                "success",
                f"PayOS monthly plan {plan_id}",
            )
            record_audit(
                conn,
                "payos",
                "system",
                "plan.paid",
                "payos_order",
                str(order_code),
                before={"status": status, "amount": expected_amount, "order_type": order_type},
                after={"status": PAYOS_STATUS_PAID, "user_id": target_id, "plan": plan_id, "amount": amount_vnd},
                note="PayOS monthly plan paid; not counted as top-up",
            )
            emit_event(
                conn,
                "plan.paid",
                "payos",
                {"order_code": str(order_code), "user_id": str(target_id), "amount": int(amount_vnd), "plan": plan_id},
                status="processed",
            )
            info.update(activation)
            info["xu"] = 0
            conn.commit()
            return True, "plan_success", info

        if order_type == "storage_addon":
            addon_mb = int(metadata.get("addon_mb") or 0)
            months = max(1, int(metadata.get("months") or max(1, int(duration_days or 30) // 30) or 1))
            if addon_mb <= 0:
                conn.rollback()
                return False, "invalid_storage_addon_order", info
            user_row = c.execute("SELECT 1 FROM users WHERE user_id=?", (str(target_id),)).fetchone()
            if not user_row:
                c.execute(
                    "INSERT INTO users (user_id, username, credits, is_vip, join_date, total_spent, has_deposited) VALUES (?,?,?,?,?,?,?)",
                    (str(target_id), "PayOS storage user", 0, 0, now_text(), 0, 0),
                )
            grant_result = grant_memory_storage_addon_conn(
                conn,
                target_id,
                addon_mb,
                amount_vnd=int(invoice_subtotal_vnd or 0),
                months=months,
                order_code=str(order_code),
                source="payos",
                granted_by="payos",
                note="PayOS storage add-on",
            )
            if not grant_result.get("ok"):
                conn.rollback()
                return False, grant_result.get("reason") or "storage_addon_grant_failed", info
            c.execute(
                "UPDATE payos_orders SET status=?, paid_at=? WHERE order_code=?",
                (PAYOS_STATUS_PAID, now_text(), str(order_code)),
            )
            update_finance_invoice_status_conn(conn, str(order_code), "granted", paid_at=now_text(), granted_at=now_text())
            record_payos_processed_conn(conn, order_code, payment_type, "success", effective_payment_link_id)
            mark_payos_idempotency_credited_conn(conn, idempotency_event_key)
            record_usage_event_conn(
                conn,
                target_id,
                event_type="payment_payos_storage_addon_success",
                tool_name="memory_storage",
                command="/webhook/payos",
                status="paid",
                xu_delta=0,
                amount_vnd=int(invoice_subtotal_vnd or 0),
                provider="payos",
                detail=f"order={order_code}; addon_mb={addon_mb}; months={months}; counts_for_member_tier=false; no_xu=true",
            )
            record_finance_revenue_event_conn(
                conn,
                target_id,
                "storage_addon",
                str(order_code),
                int(invoice_subtotal_vnd or 0),
                0,
                "payos",
                "success",
                f"PayOS storage add-on +{addon_mb}MB/{months} month(s)",
            )
            record_audit(
                conn,
                "payos",
                "system",
                "storage_addon.paid",
                "payos_order",
                str(order_code),
                before={"status": status, "amount": expected_amount, "order_type": order_type},
                after={"status": PAYOS_STATUS_PAID, "user_id": target_id, "addon_mb": addon_mb, "months": months, "subtotal": invoice_subtotal_vnd, "vat": invoice_vat_vnd, "total": amount_vnd},
                note="PayOS storage add-on paid; extends notes/docs quota; not counted as top-up",
            )
            emit_event(
                conn,
                "storage_addon.paid",
                "payos",
                {"order_code": str(order_code), "user_id": str(target_id), "amount": int(invoice_subtotal_vnd), "vat": int(invoice_vat_vnd), "total": int(amount_vnd), "addon_mb": addon_mb, "months": months},
                status="processed",
            )
            info.update({
                "xu": 0,
                "addon_mb": addon_mb,
                "months": months,
                "active_addon_mb": int(grant_result.get("active_addon_mb") or 0),
                "total_limit_mb": int(grant_result.get("total_limit_mb") or 0),
                "expires_at": grant_result.get("expires_at") or "",
            })
            conn.commit()
            return True, "storage_addon_success", info

        c.execute("SELECT COALESCE(has_deposited,0) FROM users WHERE user_id=?", (str(target_id),))
        user_deposit_row = c.fetchone()
        is_first_deposit = not (user_deposit_row and int(user_deposit_row[0] or 0) > 0)
        if not user_deposit_row:
            c.execute(
                """INSERT OR IGNORE INTO trial_grants (user_id, granted_xu, granted_at, username, note)
                VALUES (?,?,?,?,?)""",
                (str(target_id), TRIAL_CREDITS, now_text(), "PayOS user", "Backfilled before PayOS paid credit; no extra trial grant"),
            )
            c.execute(
                "INSERT INTO users (user_id, username, credits, is_vip, join_date, total_spent, has_deposited) VALUES (?,?,?,?,?,?,?)",
                (str(target_id), "PayOS user", 0, 0, now_text(), 0, 0)
            )

        old_total_paid = member_total_paid_vnd(target_id, conn=conn)
        old_tier = member_tier_by_total_paid(old_total_paid)
        auto_promotion = apply_automatic_topup_promotion_conn(
            conn,
            target_id,
            str(order_code),
            {**topup_payment_context, "base_xu": int(base_xu or 0)},
        )
        auto_bonus = int(auto_promotion.get("bonus_xu") or 0)
        launch_bonus = 0
        total_credit = int(base_xu or 0) + auto_bonus
        c.execute(
            "UPDATE users SET credits = credits + ?, has_deposited=1, total_paid_vnd = COALESCE(total_paid_vnd,0) + ? WHERE user_id=?",
            (int(total_credit), int(invoice_subtotal_vnd or 0), str(target_id))
        )
        new_total_paid = int(old_total_paid or 0) + int(invoice_subtotal_vnd or 0)
        new_tier = member_tier_by_total_paid(new_total_paid)
        c.execute(
            """UPDATE payos_orders
               SET status=?,paid_at=?,user_market_snapshot=?,payment_market=?,
                   payment_transaction_id=?,domestic_eligibility=?,
                   successful_topup_ordinal=?,base_credit_applied=1
               WHERE order_code=?""",
            (
                PAYOS_STATUS_PAID, now_text(), str(user_market_value or ""),
                str(payment_market_value or ""), clean_transaction_id,
                int(bool(auto_promotion.get("domestic_eligibility"))),
                int(auto_promotion.get("successful_topup_ordinal") or 0),
                str(order_code),
            ),
        )
        update_finance_invoice_status_conn(conn, str(order_code), "paid", paid_at=now_text())
        record_payos_processed_conn(conn, order_code, payment_type, "success", effective_payment_link_id)
        mark_payos_idempotency_credited_conn(conn, idempotency_event_key)
        record_credit_event(conn, target_id, base_xu, "payos_deposit", order_code, f"Nạp PayOS {invoice_subtotal_vnd}đ trước thuế; VAT {invoice_vat_vnd}đ")
        if auto_bonus > 0:
            auto_event_type = (
                "auto_first_topup_bonus"
                if auto_promotion.get("promotion_id") == AUTO_FIRST_TOPUP_PROMOTION_ID
                else "auto_second_topup_bonus"
            )
            record_credit_event(
                conn, target_id, auto_bonus, auto_event_type, str(order_code),
                f"{auto_promotion.get('promotion_id')} +{auto_bonus} Xu; ordinal={auto_promotion.get('successful_topup_ordinal')}",
            )
            defer_pending_code_promo_for_auto_conn(conn, target_id, str(order_code), str(auto_promotion.get("promotion_id") or ""))
            promo_result = {"bonus_xu": 0, "code": "", "status": "deferred_for_auto_promotion"}
        else:
            promo_result = redeem_promo_for_order(conn, target_id, order_code, invoice_subtotal_vnd, base_xu, payment_context=topup_payment_context)
        promo_bonus = int(promo_result.get("bonus_xu") or 0)
        update_usage_event_amount_for_ref_conn(conn, target_id, order_code, invoice_subtotal_vnd, "xu_credit")
        record_usage_event_conn(
            conn,
            target_id,
            event_type="payment_payos_success",
            tool_name="payment",
            command="/webhook/payos",
            status="paid",
            xu_delta=int(base_xu or 0) + auto_bonus + int(promo_bonus or 0),
            amount_vnd=int(invoice_subtotal_vnd or 0),
            provider="payos",
            detail=f"order={order_code}; promo={promo_result.get('code') or ''}",
        )
        record_finance_revenue_event_conn(
            conn,
            target_id,
            "payos_topup",
            str(order_code),
            int(invoice_subtotal_vnd or 0),
            int(base_xu or 0) + auto_bonus + int(promo_bonus or 0),
            "payos",
            "success",
            f"PayOS topup; promo={promo_result.get('code') or ''}",
        )
        referral_result = award_referral_bonus_if_needed(
            conn,
            target_id,
            order_code=str(order_code),
            amount_vnd=int(invoice_subtotal_vnd or 0),
            base_xu=int(base_xu or 0),
            is_first_deposit=is_first_deposit,
        )
        tier_up_result = handle_member_tier_up(
            conn,
            target_id,
            old_tier,
            new_tier,
            new_total_paid,
            source="payos",
        )
        info["promo_bonus"] = promo_bonus
        info["promo_code"] = promo_result.get("code") or ""
        info["promo_status"] = promo_result.get("status") or ""
        info["launch_bonus"] = launch_bonus
        info["auto_bonus"] = auto_bonus
        info["auto_promotion_id"] = auto_promotion.get("promotion_id") or ""
        info["auto_bonus_percent"] = int(auto_promotion.get("bonus_percent") or 0)
        info["auto_promotion_label"] = auto_promotion.get("label") or ""
        info["successful_topup_ordinal"] = int(auto_promotion.get("successful_topup_ordinal") or 0)
        info["domestic_eligibility"] = bool(auto_promotion.get("domestic_eligibility"))
        info["base_xu"] = base_xu
        info["total_credit_without_promo"] = total_credit
        info["referral_bonus"] = int(referral_result.get("reward_xu") or 0)
        info["referral_result"] = referral_result
        info["tier_up_result"] = tier_up_result
        record_audit(
            conn,
            "payos",
            "system",
            "payment.paid",
            "payos_order",
            str(order_code),
            before={"status": status, "amount": expected_amount},
            after={"status": PAYOS_STATUS_PAID, "user_id": target_id, "subtotal": invoice_subtotal_vnd, "vat": invoice_vat_vnd, "total": amount_vnd, "base_xu": base_xu, "auto_bonus": auto_bonus, "auto_promotion_id": auto_promotion.get("promotion_id") or "", "promo_bonus": promo_bonus},
            note="PayOS paid order credited",
        )
        emit_event(
            conn,
            "payment.paid",
            "payos",
            {"order_code": str(order_code), "user_id": str(target_id), "amount": int(invoice_subtotal_vnd), "vat": int(invoice_vat_vnd), "total": int(amount_vnd), "base_xu": int(base_xu), "auto_bonus": auto_bonus, "auto_promotion_id": auto_promotion.get("promotion_id") or "", "promo_bonus": int(promo_bonus or 0)},
            status="processed",
        )
        conn.commit()
        if (
            clean_transaction_id
            and int(auto_promotion.get("successful_topup_ordinal") or 0) == 1
        ):
            enqueue_broadcast_after_first_topup_safe(target_id)
        return True, "success", info
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

# ─── ADMIN ALERT ─────────────────────────────────────────────────────────────
async def alert_admin(context: ContextTypes.DEFAULT_TYPE, service_name: str, error_msg: str):
    try:
        safe_service = html.escape(str(service_name))
        safe_error = html.escape(str(error_msg))
        await context.bot.send_message(
            chat_id=ADMIN_ID,
            text=f"🚨 <b>BÁO ĐỘNG TOAN AAS</b>\n\n{safe_service} lỗi:\n<code>{safe_error}</code>",
            parse_mode="HTML"
        )
    except Exception:
        pass

