def message_media_candidate(message) -> tuple[object | None, str]:
    if not message:
        return None, ""
    for attr, file_type in (
        ("voice", "voice"),
        ("audio", "audio"),
        ("video", "video"),
    ):
        media = getattr(message, attr, None)
        if media:
            return media, file_type
    doc = getattr(message, "document", None)
    if doc:
        mime = str(getattr(doc, "mime_type", "") or "")
        file_name = str(getattr(doc, "file_name", "") or "")
        guessed = mimetypes.guess_type(file_name)[0] or ""
        if mime.startswith(("audio/", "video/")) or guessed.startswith(("audio/", "video/")):
            return doc, "document"
    return None, ""

def media_content_type(media, file_type: str = "") -> str:
    content_type = str(getattr(media, "mime_type", "") or "")
    file_name = str(getattr(media, "file_name", "") or "")
    if not content_type and file_name:
        content_type = mimetypes.guess_type(file_name)[0] or ""
    if not content_type:
        content_type = "audio/ogg" if file_type == "voice" else "application/octet-stream"
    return content_type

def cache_recent_media_state(update: Update) -> str:
    try:
        message = update.message
        user_id = int(update.effective_user.id) if update.effective_user else 0
        if not message or not user_id:
            return ""
        created = {"created_at": time.time(), "created_at_text": now_text()}
        if getattr(message, "photo", None):
            photo = message.photo[-1]
            LAST_USER_IMAGE[user_id] = {
                **created,
                "file_id": str(photo.file_id or ""),
                "file_size": int(photo.file_size or 0),
                "mime_type": "image/jpeg",
                "file_name": "telegram_photo.jpg",
            }
            return "image"
        media, file_type = message_media_candidate(message)
        if not media:
            return ""
        info = {
            **created,
            "file_id": str(getattr(media, "file_id", "") or ""),
            "file_unique_id": str(getattr(media, "file_unique_id", "") or ""),
            "file_type": file_type,
            "mime_type": media_content_type(media, file_type),
            "file_name": str(getattr(media, "file_name", "") or ""),
            "file_size": int(getattr(media, "file_size", 0) or 0),
            "duration": int(getattr(media, "duration", 0) or 0),
        }
        mime = info.get("mime_type") or ""
        if file_type == "video" or mime.startswith("video/"):
            LAST_USER_VIDEO[user_id] = info
            return "video"
        if file_type in {"voice", "audio"} or mime.startswith("audio/"):
            LAST_USER_AUDIO[user_id] = info
            return "audio"
    except Exception as e:
        logger.warning(f"media factory state cache failed: {e}")
    return ""

def get_recent_media_state(store: dict[int, dict], user_id) -> dict:
    item = store.get(int(user_id or 0)) or {}
    if not item:
        return {}
    if time.time() - float(item.get("created_at") or 0) > MEDIA_FACTORY_STATE_TTL_SECONDS:
        store.pop(int(user_id or 0), None)
        return {}
    return dict(item)

def get_selected_media_state(store: dict[int, dict], user_id) -> dict:
    item = store.get(int(user_id or 0)) or {}
    if not item:
        return {}
    if time.time() - float(item.get("created_at") or 0) > MEDIA_PREVIEW_TTL_SECONDS:
        store.pop(int(user_id or 0), None)
        return {}
    return dict(item)

def remember_last_media(update: Update):
    try:
        message = update.message
        if not message or not update.effective_user:
            return
        media, file_type = message_media_candidate(message)
        if not media:
            return
        LAST_MEDIA_BY_USER[str(update.effective_user.id)] = {
            "file_id": str(getattr(media, "file_id", "") or ""),
            "file_unique_id": str(getattr(media, "file_unique_id", "") or ""),
            "file_type": file_type,
            "mime_type": media_content_type(media, file_type),
            "file_name": str(getattr(media, "file_name", "") or ""),
            "file_size": int(getattr(media, "file_size", 0) or 0),
            "created_at_ts": time.time(),
            "created_at": now_text(),
        }
    except Exception as e:
        logger.warning(f"last media cache write failed: {e}")

def set_pending_admin_tool_test(user_id, tool: str, command: str = "", *, mode: str = "") -> dict:
    uid = int(user_id or 0)
    state = {
        "tool": str(tool or "").strip().lower(),
        "command": str(command or "").strip()[:80],
        "confirm_paid": True,
        "created_at": time.time(),
        "expires_at": time.time() + ADMIN_TOOL_TEST_PENDING_TTL_SECONDS,
    }
    normalized_mode = normalize_video_translate_mode(mode) if str(mode or "").strip() else ""
    if normalized_mode:
        state["mode"] = normalized_mode
    if uid:
        PENDING_ADMIN_TOOL_TEST[uid] = state
    return state

def get_pending_admin_tool_test(user_id) -> dict:
    uid = int(user_id or 0)
    state = dict(PENDING_ADMIN_TOOL_TEST.get(uid) or {})
    if not state:
        return {}
    if float(state.get("expires_at") or 0) < time.time():
        PENDING_ADMIN_TOOL_TEST.pop(uid, None)
        return {}
    return state

def clear_pending_admin_tool_test(user_id) -> bool:
    return PENDING_ADMIN_TOOL_TEST.pop(int(user_id or 0), None) is not None

