def list_local_worker_jobs(limit: int = 10) -> list[dict]:
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute(
            """SELECT id,user_id,command,job_type,status,provider,input_file_id,output_file_id,output_url,
                      error_short,created_at,started_at,finished_at,xu_cost,admin_only,worker_id,updated_at
               FROM local_worker_jobs
               ORDER BY id DESC
               LIMIT ?""",
            (max(1, min(int(limit or 10), 50)),),
        )
        return [local_worker_job_from_row(row) for row in c.fetchall()]
    finally:
        conn.close()

def count_local_worker_jobs() -> dict:
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute("SELECT status, COUNT(*) FROM local_worker_jobs GROUP BY status")
        counts = {str(status or "unknown"): int(count or 0) for status, count in c.fetchall()}
        return {
            "queued": counts.get("queued", 0),
            "running": counts.get("running", 0),
            "succeeded": counts.get("succeeded", 0),
            "failed": counts.get("failed", 0),
            "cancelled": counts.get("cancelled", 0),
            "total": sum(counts.values()),
        }
    except sqlite3.OperationalError:
        return {"queued": 0, "running": 0, "succeeded": 0, "failed": 0, "cancelled": 0, "total": 0}
    finally:
        conn.close()

def update_local_worker_job(
    job_id,
    status: str,
    worker_id: str = "",
    error_short: str = "",
    output_file_id: str = "",
    output_url: str = "",
    *,
    conn=None,
) -> dict:
    status = str(status or "").strip().lower()
    if status not in LOCAL_WORKER_JOB_STATUSES:
        raise ValueError("invalid local worker job status")
    job = (
        get_local_worker_job(job_id, conn=conn)
        if conn is not None
        else get_local_worker_job(job_id)
    )
    if not job:
        raise ValueError("local worker job not found")
    frame_transition_blocker = frame_video_public_seam.frame_video_worker_transition_blocker(
        job,
        status,
        worker_id,
    )
    if frame_transition_blocker:
        raise ValueError(frame_transition_blocker)
    frame_receipt_replay_blocker = (
        frame_video_public_seam.frame_video_terminal_receipt_replay_blocker(
            job,
            status,
            output_url=output_url,
            output_file_id=output_file_id,
        )
    )
    if frame_receipt_replay_blocker:
        raise ValueError(frame_receipt_replay_blocker)
    now = now_text()
    job_type = str(job.get("job_type") or "")
    detail_limit = 128 * 1024 if job_type == "video_local_edit" else 4000 if job_type == "video_ai_edit" else 500
    output_limit = 128 * 1024 if job_type == "video_local_edit" else 16 * 1024 if job_type == "frame_video_render" else 1000
    started_at = job.get("started_at") or (now if status == "running" else "")
    finished_at = job.get("finished_at") or (now if status in {"succeeded", "failed", "cancelled"} else "")
    frame_cas = job_type == "frame_video_render"
    updated_rows = 0
    owns_connection = conn is None
    conn = conn or db_connect()
    try:
        params = (
            status,
            str(worker_id or job.get("worker_id") or "")[:120],
            str(error_short or "")[:detail_limit],
            str(output_file_id or job.get("output_file_id") or "")[:500],
            str(output_url or job.get("output_url") or "")[:output_limit],
            started_at,
            finished_at,
            now,
            str(job_id),
        )
        if frame_cas:
            cursor = conn.execute(
                """UPDATE local_worker_jobs
                   SET status=?, worker_id=?, error_short=?, output_file_id=?, output_url=?,
                       started_at=?, finished_at=?, updated_at=?
                   WHERE id=? AND status=? AND worker_id=?""",
                params
                + (
                    str(job.get("status") or ""),
                    str(job.get("worker_id") or "")[:120],
                ),
            )
        else:
            cursor = conn.execute(
                """UPDATE local_worker_jobs
                   SET status=?, worker_id=?, error_short=?, output_file_id=?, output_url=?,
                       started_at=?, finished_at=?, updated_at=?
                   WHERE id=?""",
                params,
            )
        updated_rows = int(cursor.rowcount or 0)
        if owns_connection:
            conn.commit()
    finally:
        if owns_connection:
            conn.close()
    if frame_cas and updated_rows != 1:
        latest = (
            get_local_worker_job(job_id)
            if owns_connection
            else get_local_worker_job(job_id, conn=conn)
        )
        if not latest:
            raise ValueError("local worker job not found")
        latest_transition_blocker = (
            frame_video_public_seam.frame_video_worker_transition_blocker(
                latest,
                status,
                worker_id,
            )
        )
        if latest_transition_blocker:
            raise ValueError(latest_transition_blocker)
        latest_receipt_blocker = (
            frame_video_public_seam.frame_video_terminal_receipt_replay_blocker(
                latest,
                status,
                output_url=output_url,
                output_file_id=output_file_id,
            )
        )
        if latest_receipt_blocker:
            raise ValueError(latest_receipt_blocker)
        return latest
    updated = (
        get_local_worker_job(job_id)
        if owns_connection
        else get_local_worker_job(job_id, conn=conn)
    )
    if updated.get("job_type") == "ffmpeg_health":
        save_tool_test_result(
            "ffmpeg_local",
            "PASS" if status == "succeeded" else ("FAIL" if status == "failed" else "RUNNING"),
            updated.get("error_short") or "local ffmpeg health queued/running",
            updated.get("worker_id") or "local_worker",
        )
    if updated.get("job_type") == "worker_ping":
        save_tool_test_result(
            "local_worker",
            "PASS" if status == "succeeded" else ("FAIL" if status == "failed" else "RUNNING"),
            updated.get("error_short") or "local worker ping queued/running",
            updated.get("worker_id") or "local_worker",
        )
    return updated

def handle_frame_video_worker_job_update(previous_job: dict, updated_job: dict) -> None:
    if not updated_job or str(updated_job.get("job_type") or "") != "frame_video_render":
        return
    previous_status = str((previous_job or {}).get("status") or "").lower()
    status = str(updated_job.get("status") or "").lower()
    if previous_status in {"succeeded", "failed", "cancelled"}:
        return
    payload = {}
    try:
        raw = str(updated_job.get("input_file_id") or "")
        payload = json.loads(raw) if raw else {}
    except Exception:
        payload = {}
    frame_job_id = str(payload.get("frame_job_id") or "")
    user_id = str(payload.get("user_id") or updated_job.get("user_id") or "")
    if status == "running" and frame_job_id:
        update_frame_video_job(
            frame_job_id,
            status="rendering",
            owner="local_worker",
            progress_percent=45,
            lease_owner=str(updated_job.get("worker_id") or "local_worker"),
            heartbeat_updated_at=now_text(),
            started_at=now_text(),
        )
        update_frame_video_job_config(
            frame_job_id,
            claim_attempted=True,
            claim_result="running",
            execution_owner="local_worker",
            ffmpeg_command_created=True,
        )
        return
    if status == "succeeded":
        receipt = {}
        try:
            receipt = json.loads(str(updated_job.get("output_url") or "") or "{}")
        except Exception:
            receipt = {}
        if frame_video_public_seam.frame_video_public_seam_applies_to_worker_job(payload):
            attestation = frame_video_public_seam.validate_frame_video_worker_terminal(
                payload,
                receipt,
                admitted_worker_id=str((previous_job or {}).get("worker_id") or ""),
                reported_worker_id=str(updated_job.get("worker_id") or ""),
                expected_local_worker_job_id=(previous_job or {}).get("id")
                or (updated_job or {}).get("id"),
            )
            if not attestation.get("ok"):
                blocker = str(attestation.get("blocker") or "worker_terminal_attestation_failed")
                if frame_job_id:
                    update_frame_video_job(
                        frame_job_id,
                        status="failed_no_charge",
                        blocker="worker_terminal_attestation_failed",
                        error_code=blocker,
                        charge_state="not_charged",
                        wallet_charge_amount_xu=0,
                        lease_owner="",
                        lease_expires_at="",
                        finished_at=now_text(),
                    )
                set_frame_video_last_error(f"worker_terminal_attestation:{blocker}")
                save_tool_test_result(
                    "frame_video",
                    "FAIL",
                    f"local worker terminal attestation failed:{blocker}",
                    user_id,
                )
                return
            receipt = dict(attestation.get("receipt") or {})
        delivery_message_id = str(receipt.get("delivery_message_id") or "")
        delivery_file_id = str(receipt.get("delivery_file_id") or "")
        delivery_blocker = (
            frame_video_public_seam.frame_video_delivery_receipt_blocker(
                delivery_message_id,
                delivery_file_id,
            )
            if frame_video_public_seam.frame_video_public_seam_applies_to_worker_job(payload)
            else ""
        )
        if not frame_job_id or delivery_blocker or (not delivery_message_id and not delivery_blocker):
            if frame_job_id:
                update_frame_video_job(
                    frame_job_id,
                    status="failed_no_charge",
                    blocker="delivery_receipt_missing",
                    error_code=delivery_blocker or "worker_succeeded_without_delivery_message_id",
                    charge_state="not_charged",
                    wallet_charge_amount_xu=0,
                    lease_owner="",
                    lease_expires_at="",
                    finished_at=now_text(),
                )
            save_tool_test_result("frame_video", "FAIL", f"local worker job {updated_job.get('id')} missing delivery receipt", user_id)
            return
        current_frame_job = frame_video_job_for_user(frame_job_id, user_id, allow_any=True)
        current_delivery_id = str((current_frame_job or {}).get("delivery_message_id") or "")
        if current_delivery_id:
            if current_delivery_id != delivery_message_id:
                save_tool_test_result(
                    "frame_video",
                    "DELIVERY_RECEIPT_CONFLICT",
                    f"job={frame_job_id}; kept={current_delivery_id}; ignored={delivery_message_id}",
                    user_id,
                )
                return
            if str((current_frame_job or {}).get("charge_state") or "") != "charged":
                charge_result = frame_video_charge_after_delivery(frame_job_id, user_id, dict(payload.get("state") or {}))
                if charge_result.get("ok"):
                    update_frame_video_job(frame_job_id, status="completed", progress_percent=100, finished_at=now_text())
            return
        update_frame_video_job(
            frame_job_id,
            status="delivered_charge_pending",
            progress_percent=95,
            output_path="",
            output_size_bytes=int(receipt.get("output_size_bytes") or 0),
            output_sha256=str(receipt.get("output_sha256") or ""),
            ffprobe_json=json.dumps(
                frame_video_public_seam.compact_frame_video_probe(
                    receipt.get("ffprobe") or {}
                ),
                ensure_ascii=False,
                separators=(",", ":"),
            ),
            delivery_status="sent",
            delivery_message_id=delivery_message_id,
            delivery_file_id=delivery_file_id,
            receipt_recorded=1,
            lease_owner="",
            lease_expires_at="",
            delivered_at=now_text(),
        )
        charge_result = frame_video_charge_after_delivery(frame_job_id, user_id, dict(payload.get("state") or {}))
        if charge_result.get("ok"):
            update_frame_video_job(frame_job_id, status="completed", progress_percent=100, finished_at=now_text())
            save_tool_test_result(
                "frame_video",
                "PASS",
                f"local worker render job {updated_job.get('id')} delivered; charged={int(charge_result.get('charged') or 0)}",
                user_id,
            )
        else:
            update_frame_video_job(frame_job_id, status="delivered_charge_pending", progress_percent=95)
            save_tool_test_result("frame_video", "DELIVERED_CHARGE_PENDING", f"local worker job {updated_job.get('id')}", user_id)
        clear_frame_video_state(user_id)
        return
    if status == "failed":
        reason = sanitize_log_text(str(updated_job.get("error_short") or "worker_failed"))[:240]
        delivery_detail = {}
        try:
            parsed_detail = json.loads(str(updated_job.get("error_short") or "") or "{}")
            delivery_detail = parsed_detail if isinstance(parsed_detail, dict) else {}
        except (TypeError, ValueError):
            delivery_detail = {}
        delivery_reason = str(delivery_detail.get("reason") or reason)
        delivery_unknown = bool(
            str(delivery_detail.get("stage") or "").lower() == "delivery_unknown"
            or frame_video_public_seam.frame_video_delivery_outcome_uncertain(
                RuntimeError(delivery_reason)
            )
            or "telegram_delivery_outcome_uncertain" in delivery_reason
        )
        if delivery_unknown:
            if frame_job_id:
                update_frame_video_job(
                    frame_job_id,
                    status="delivery_unknown",
                    blocker="telegram_delivery_outcome_uncertain",
                    error_code="telegram_delivery_outcome_uncertain",
                    delivery_status="unverified",
                    charge_state="not_charged",
                    wallet_charge_amount_xu=0,
                    lease_owner="",
                    lease_expires_at="",
                    finished_at=now_text(),
                )
            save_tool_test_result(
                "frame_video",
                "DELIVERY_UNKNOWN",
                "local worker delivery needs verification; no charge or retry",
                user_id,
            )
            return
        if frame_job_id:
            update_frame_video_job(
                frame_job_id,
                status="failed_no_charge",
                blocker="worker_render_failed",
                error_code=f"worker_failed:{reason}",
                charge_state="not_charged",
                wallet_charge_amount_xu=0,
                lease_owner="",
                lease_expires_at="",
                finished_at=now_text(),
            )
        set_frame_video_last_error(f"worker_failed:{reason}")
        save_tool_test_result("frame_video", "FAIL", f"local worker render failed:{reason}", user_id)

def handle_paid_video_preview_worker_job_update(previous_job: dict, updated_job: dict) -> None:
    if not updated_job or str(updated_job.get("job_type") or "") != "paid_video_preview":
        return
    previous_status = str((previous_job or {}).get("status") or "").lower()
    status = str(updated_job.get("status") or "").lower()
    if previous_status in {"succeeded", "failed", "cancelled"}:
        return
    try:
        payload = json.loads(str(updated_job.get("input_file_id") or "") or "{}")
    except Exception:
        payload = {}
    user_id = str(payload.get("user_id") or updated_job.get("user_id") or "")
    token = str(payload.get("confirm_token") or "")
    if not user_id:
        return
    state = get_video_addon_state(user_id) or {}
    active_token = str(state.get("pending_confirm_token") or "")
    if token and active_token and token != active_token:
        return
    if token and token not in SHOPAIKEY_PENDING_CONFIRMATIONS and token != active_token:
        return
    pending_payload = dict(state.get("pending_payload") or SHOPAIKEY_PENDING_CONFIRMATIONS.get(token) or {})
    if status == "succeeded" and str(updated_job.get("output_file_id") or ""):
        state, pending_payload = apply_video_paid_preview_job_result(state, pending_payload, updated_job)
        if token and token in SHOPAIKEY_PENDING_CONFIRMATIONS:
            SHOPAIKEY_PENDING_CONFIRMATIONS[token].update(pending_payload)
        if state:
            state["pending_confirm_token"] = token or state.get("pending_confirm_token") or ""
            set_video_addon_state(user_id, state)
        return
    if status in {"failed", "cancelled"} and state:
        state["paid_preview_seen"] = False
        state["pending_payload"] = {**pending_payload, "paid_preview_seen": False}
        set_video_addon_state(user_id, state)


def handle_social_link_import_worker_job_update(previous_job: dict, updated_job: dict) -> None:
    if not updated_job or str(updated_job.get("job_type") or "") != "social_link_import":
        return
    previous_status = str((previous_job or {}).get("status") or "").lower()
    status = str(updated_job.get("status") or "").lower()
    if previous_status in {"succeeded", "failed", "cancelled"}:
        return
    try:
        payload = json.loads(str(updated_job.get("input_file_id") or "") or "{}")
    except Exception:
        payload = {}
    user_id = str(payload.get("user_id") or updated_job.get("user_id") or "")
    if not user_id:
        return
    state = get_video_dubbing_pending(user_id) or {}
    job_id = str(updated_job.get("id") or "")
    if state and str(state.get("link_import_job_id") or "") not in {"", job_id}:
        return
    if status == "succeeded":
        output_file_id = str(updated_job.get("output_file_id") or "")
        charged = 0
        if output_file_id and not state.get("link_import_charged_xu"):
            charge = spend_fixed_credit_info(
                user_id,
                int(LINK_IMPORT_PRICE_XU or 0),
                "social_link_import_success",
                f"successful social link import job={job_id}",
                apply_member_discount_flag=False,
            )
            charged = int(charge.get("final_cost") or 0) if charge.get("ok") else 0
        set_video_dubbing_pending(
            user_id,
            "link_ready",
            video_file_id=output_file_id,
            source_file_id=output_file_id,
            source_kind="social_link",
            source_url=str(payload.get("source_url") or ""),
            source_platform=str(payload.get("source_platform") or ""),
            link_import_job_id=job_id,
            link_import_status="succeeded",
            link_import_charged_xu=charged or int(state.get("link_import_charged_xu") or 0),
        )
        return
    if status in {"failed", "cancelled"}:
        set_video_dubbing_pending(
            user_id,
            "link_failed",
            link_import_job_id=job_id,
            link_import_status=status,
        )


def local_worker_status_payload() -> dict:
    heartbeat = local_worker_last_heartbeat()
    counts = count_local_worker_jobs()
    ffmpeg_test = get_tool_test_result("ffmpeg_local")
    worker_test = get_tool_test_result("local_worker")
    worker_sha = frame_video_public_seam.sanitize_frame_video_worker_sha(
        get_system_setting("local_worker:worker_sha", "")
    )
    try:
        worker_flags_raw = json.loads(
            get_system_setting("local_worker:frame_video_engine_flags_json", "{}")
            or "{}"
        )
    except (TypeError, ValueError, json.JSONDecodeError):
        worker_flags_raw = {}
    worker_flags = frame_video_public_seam.normalize_frame_video_worker_flags(worker_flags_raw)
    return {
        "enabled": LOCAL_WORKER_ENABLED,
        "poll_enabled": LOCAL_WORKER_POLL_ENABLED,
        "token_configured": bool(LOCAL_WORKER_TOKEN),
        "connected": bool(heartbeat.get("connected")),
        "worker_id": heartbeat.get("worker_id") or "",
        "worker_sha": worker_sha,
        "frame_video_engine_flags": worker_flags,
        "last_heartbeat": heartbeat.get("last_heartbeat") or "",
        "heartbeat_age_seconds": heartbeat.get("age_seconds"),
        "job_counts": counts,
        "ffmpeg_path_configured": bool(LOCAL_FFMPEG_PATH),
        "ffmpeg_path": LOCAL_FFMPEG_PATH,
        "ffprobe_path_configured": get_system_setting("local_worker:ffprobe_configured", "0") == "1",
        "ffmpeg_seen": bool(get_system_setting("local_worker:ffmpeg_path_seen", "")),
        "delivery_configured": bool(TELEGRAM_TOKEN),
        "ffmpeg_test_status": ffmpeg_test.get("status") or "NOT_TESTED",
        "ffmpeg_test_at": ffmpeg_test.get("tested_at") or "",
        "worker_test_status": worker_test.get("status") or "NOT_TESTED",
        "comfy_url_configured": bool(LOCAL_COMFY_URL),
        "comfy_enabled": LOCAL_COMFY_ENABLED,
        "comfy_status": "installed_but_not_ready/planned" if not LOCAL_COMFY_ENABLED else "admin_only/not_tested",
        "comfy_render": "admin-only/planned",
        "render_queue": "admin-only",
    }


VIDEO_EDIT_FILTER_SNAPSHOT_MAX_ITEMS = 1024


def video_edit_worker_status_payload() -> dict:
    """Return only the fresh heartbeat owned by the local Video Edit adapter."""

    received_at = get_system_setting("local_worker:video_edit_received_at_utc", "")
    received_dt = parse_utc_text(received_at)
    age_seconds = None
    if received_dt:
        age_seconds = max(
            0,
            int((datetime.now(timezone.utc) - received_dt).total_seconds()),
        )
    capabilities_raw = get_system_setting(
        "local_worker:video_edit_capabilities_json",
        "[]",
    )
    try:
        capabilities = json.loads(capabilities_raw or "[]")
    except (TypeError, ValueError, json.JSONDecodeError):
        capabilities = []
    if not isinstance(capabilities, list):
        capabilities = []
    filters_raw = get_system_setting("local_worker:video_edit_filters_json", "[]")
    try:
        video_edit_filters = json.loads(filters_raw or "[]")
    except (TypeError, ValueError, json.JSONDecodeError):
        video_edit_filters = []
    if not isinstance(video_edit_filters, list):
        video_edit_filters = []
    video_edit_filters = [
        str(item)
        for item in video_edit_filters
        if re.fullmatch(r"[a-z0-9_]{1,64}", str(item))
    ][:VIDEO_EDIT_FILTER_SNAPSHOT_MAX_ITEMS]
    contract_version = safe_int(
        get_system_setting(
            "local_worker:video_edit_heartbeat_contract_version",
            "0",
        ),
        0,
    )
    job_scope = get_system_setting("local_worker:video_edit_job_scope", "")
    fresh = bool(
        contract_version >= 1
        and job_scope == "video_edit_only"
        and age_seconds is not None
        and age_seconds <= video_editengine1.HEARTBEAT_TTL_SECONDS
    )
    worker_status = "healthy" if fresh else "stale"
    reported_ffmpeg_path = get_system_setting(
        "local_worker:video_edit_ffmpeg_path_seen",
        "",
    )
    workspace_free_bytes = max(
        0,
        min(
            safe_int(
                get_system_setting(
                    "local_worker:video_edit_workspace_free_bytes",
                    "0",
                ),
                0,
            ),
            (1 << 63) - 1,
        ),
    )
    max_deadline_seconds = max(
        0,
        min(
            safe_int(
                get_system_setting(
                    "local_worker:video_edit_max_deadline_seconds",
                    "0",
                ),
                0,
            ),
            6 * 60 * 60,
        ),
    )
    return {
        "enabled": LOCAL_WORKER_ENABLED,
        "poll_enabled": LOCAL_WORKER_POLL_ENABLED,
        "delivery_configured": bool(TELEGRAM_TOKEN),
        "worker_sha": get_system_setting(
            "local_worker:video_edit_worker_sha",
            "",
        ),
        "last_heartbeat": received_at,
        "ffmpeg_path": reported_ffmpeg_path,
        "ffmpeg_path_configured": bool(reported_ffmpeg_path),
        "ffmpeg_seen": bool(reported_ffmpeg_path),
        "ffprobe_path_configured": get_system_setting(
            "local_worker:video_edit_ffprobe_configured",
            "0",
        ) == "1",
        "token_configured": bool(VIDEO_EDIT_WORKER_TOKEN),
        "connected": fresh,
        "heartbeat_contract_version": contract_version,
        "job_scope": job_scope,
        "worker_id": get_system_setting("local_worker:video_edit_worker_id", ""),
        "worker_owner": get_system_setting(
            "local_worker:video_edit_worker_owner",
            "",
        ),
        "engine_route": get_system_setting(
            "local_worker:video_edit_engine_route",
            "",
        ),
        "capabilities": [str(item) for item in capabilities if str(item).strip()],
        "video_edit_filters": video_edit_filters,
        "video_edit_filters_known": get_system_setting("local_worker:video_edit_filters_known", "0") == "1",
        "video_edit_filter_worker_id": get_system_setting("local_worker:video_edit_filter_worker_id", ""),
        "video_edit_filter_ffmpeg_path": get_system_setting("local_worker:video_edit_filter_ffmpeg_path", ""),
        "instance_id": get_system_setting("local_worker:video_edit_instance_id", ""),
        "worker_instance_id": get_system_setting("local_worker:video_edit_instance_id", ""),
        "process_id": safe_int(
            get_system_setting("local_worker:video_edit_process_id", "0"),
            0,
        ),
        "started_at_utc": get_system_setting("local_worker:video_edit_started_at_utc", ""),
        "timestamp_utc": get_system_setting("local_worker:video_edit_timestamp_utc", ""),
        "heartbeat_timestamp": get_system_setting("local_worker:video_edit_timestamp_utc", ""),
        "received_at_utc": received_at,
        "heartbeat_age_seconds": age_seconds,
        "heartbeat_ttl_seconds": video_editengine1.HEARTBEAT_TTL_SECONDS,
        "worker_status": worker_status,
        "queue_depth": safe_int(
            get_system_setting("local_worker:video_edit_queue_depth", "0"),
            0,
        ),
        "last_error": get_system_setting("local_worker:video_edit_last_error", ""),
        "workspace_ready": get_system_setting(
            "local_worker:video_edit_workspace_ready",
            "0",
        ) == "1",
        "workspace_free_bytes": workspace_free_bytes,
        "video_edit_max_deadline_seconds": max_deadline_seconds,
        "worker_token_ready": get_system_setting(
            "local_worker:video_edit_worker_token_ready",
            "0",
        ) == "1",
        "local_bot_api_ready": get_system_setting(
            "local_worker:video_edit_local_bot_api_ready",
            "0",
        ) == "1",
    }


def video_edit_runtime_capability_admission(
    feature_key: str,
    state: dict | None = None,
    *,
    runtime: dict | None = None,
) -> dict:
    worker = dict(runtime if runtime is not None else video_edit_worker_status_payload())
    metadata = dict((state or {}).get("source_metadata") or {})

    def blocked(reason: str) -> dict:
        return {
            "ready": False,
            "reason": reason,
            "required_filters": [],
            "missing_filters": [],
        }

    if not worker.get("enabled"):
        return blocked("local_worker_disabled")
    if not worker.get("poll_enabled"):
        return blocked("local_worker_poll_disabled")
    if not worker.get("token_configured"):
        return blocked("local_worker_token_missing")
    if str(worker.get("job_scope") or "") != "video_edit_only":
        return blocked("local_worker_job_scope_mismatch")
    if not worker.get("connected"):
        return blocked("local_worker_heartbeat_stale")
    try:
        contract_version = int(worker.get("heartbeat_contract_version") or 0)
    except (TypeError, ValueError, OverflowError):
        contract_version = 0
    if contract_version < 1:
        return blocked("local_worker_contract_missing")
    try:
        heartbeat_age = int(worker.get("heartbeat_age_seconds"))
    except (TypeError, ValueError, OverflowError):
        heartbeat_age = -1
    if heartbeat_age < 0 or heartbeat_age > video_editengine1.HEARTBEAT_TTL_SECONDS:
        return blocked("local_worker_heartbeat_stale")
    if str(worker.get("worker_owner") or "") != video_editengine1.OUTBOX_OWNER:
        return blocked("local_worker_owner_mismatch")
    if str(worker.get("engine_route") or "") != video_editengine1.ENGINE_ROUTE:
        return blocked("local_worker_route_mismatch")
    capabilities = worker.get("capabilities") or []
    if isinstance(capabilities, str):
        capabilities = [item.strip() for item in capabilities.split(",") if item.strip()]
    if video_editengine1.WORKER_CAPABILITY not in {str(item) for item in capabilities}:
        return blocked("local_worker_capability_missing")
    worker_id = str(worker.get("worker_id") or "").strip()
    filter_worker_id = str(worker.get("video_edit_filter_worker_id") or "").strip()
    if not worker_id or not filter_worker_id or worker_id != filter_worker_id:
        return blocked("local_worker_filter_snapshot_owner_mismatch")

    def path_identity(value) -> str:
        return str(value or "").strip().replace("\\", "/").rstrip("/").lower()

    worker_ffmpeg_path = path_identity(worker.get("ffmpeg_path"))
    filter_ffmpeg_path = path_identity(worker.get("video_edit_filter_ffmpeg_path"))
    if not worker_ffmpeg_path or not filter_ffmpeg_path or worker_ffmpeg_path != filter_ffmpeg_path:
        return blocked("local_worker_filter_snapshot_path_mismatch")
    if not worker.get("ffprobe_path_configured"):
        return blocked("ffprobe_missing")
    return video_edit_capabilities.runtime_capability_admission(
        feature_key,
        available_filters=set(worker.get("video_edit_filters") or []),
        filters_known=bool(worker.get("video_edit_filters_known")),
        has_audio=bool(metadata.get("has_audio")),
        worker_id=worker_id,
        filter_worker_id=filter_worker_id,
        ffmpeg_path=worker_ffmpeg_path,
        filter_ffmpeg_path=filter_ffmpeg_path,
        source_width=int(metadata.get("width") or 0),
        source_height=int(metadata.get("height") or 0),
        snapshot_age_seconds=heartbeat_age,
        snapshot_ttl_seconds=video_editengine1.HEARTBEAT_TTL_SECONDS,
    )


def video_edit_runtime_capability_ready(
    feature_key: str,
    state: dict | None = None,
    *,
    runtime: dict | None = None,
) -> bool:
    return bool(
        video_edit_runtime_capability_admission(
            feature_key,
            state,
            runtime=runtime,
        ).get("ready")
    )

