def normalize_video_tier(value: str = "") -> str:
    tier = str(value or "").strip().lower()
    tier = tier.replace("-", "_").replace(" ", "_")
    if tier in {"200", "200xu", "video_beta_200"}:
        return "low"
    if tier in {"300", "300xu", "video_beta_300"}:
        return "basic"
    if tier in {"400", "400xu", "video_beta_400"}:
        return "common"
    if tier in {"500", "500xu", "advanced", "plus", "nang_cao", "nangcao"}:
        return "advanced"
    if tier in {"600", "600xu", "business", "sales", "ban_hang", "banhang"}:
        return "standard"
    if tier in {"700", "700xu", "long", "long_scene", "canh_dai", "canhdai"}:
        return "long"
    if tier in {"800", "800xu", "high", "pro"}:
        return "high"
    if tier in {"1000", "1000xu", "future_1000", "pro_1000", "professional"}:
        return "future_1000"
    if tier in {"1200", "1200xu", "future_1200", "pro_1200", "pro_plus"}:
        return "future_1200"
    if tier in {"1500", "1500xu", "future_1500", "premium_future"}:
        return "future_1500"
    if tier in {"standard", "std", "normal", "medium", "tieu_chuan"}:
        return "standard"
    if tier in {"premium", "vip", "admin"}:
        return "future_1500"
    if tier in {"common", "regular", "popular", "pho_thong", "phothong"}:
        return "common"
    if tier in {"basic", "starter", "co_ban", "coban"}:
        return "basic"
    if tier in {"low", "experience", "cheap", "eco", "economy", "trial", "trai_nghiem", "trainghiem"}:
        return "low"
    fallback = str(SHOPAIKEY_VIDEO_DEFAULT_TIER or "low").strip().lower()
    fallback = fallback.replace("-", "_").replace(" ", "_")
    return fallback if fallback in set(VIDEO_TIER_ORDER) else "low"

def video_tier_payload(tier: str = "") -> dict:
    tier_norm = normalize_video_tier(tier)
    pricing = video_tier_pricing_payload()
    payload = dict(pricing.get(tier_norm) or pricing["low"])
    payload["tier"] = tier_norm
    payload["enabled"] = bool(video_tier_enabled_map().get(tier_norm, False))
    payload["admin_only"] = bool(tier_norm == "premium" and VIDEO_PREMIUM_ADMIN_ONLY)
    payload["model"] = payload.get("model") or SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast"
    return payload

