def _video_debug_json(value, fallback=None):
    if isinstance(value, (dict, list)):
        return value
    if value in (None, ""):
        return {} if fallback is None else fallback
    try:
        return json.loads(str(value))
    except Exception:
        return {} if fallback is None else fallback


def _video_debug_file_info(path: str) -> dict:
    clean = str(path or "").strip()
    if not clean:
        return {"path": "", "exists": False, "size": 0}
    try:
        return {"path": clean, "exists": os.path.exists(clean), "size": os.path.getsize(clean) if os.path.exists(clean) else 0}
    except OSError:
        return {"path": clean, "exists": False, "size": 0}


def _video_provider_attempt_summary_lines(result: dict | None = None, *, limit: int = 6) -> list[str]:
    current = dict(result or {})
    attempts = current.get("provider_attempts") or []
    if not isinstance(attempts, list):
        attempts = []
    if not attempts:
        attempts = current.get("provider_fallback_attempts") or current.get("fallback_provider_attempts") or []
    rows = [dict(item) for item in attempts if isinstance(item, dict)][: max(1, int(limit or 6))]
    lines = ["", "Provider attempts:"]
    if not rows:
        lines.append("• <code>-</code>")
        return lines
    for item in rows:
        provider = html.escape(str(item.get("provider") or "-"))
        phase = html.escape(str(item.get("phase") or ("submit" if item.get("submit_failure") else "-")))
        blocker = html.escape(str(item.get("blocker") or item.get("reason") or "-")[:180])
        safe_error = html.escape(str(item.get("safe_error") or item.get("provider_error_message_safe") or "-")[:180])
        task_source = html.escape(str(item.get("task_id_source") or "-")[:80])
        content_type = html.escape(str(item.get("download_content_type") or "-")[:80])
        lines.append(
            "• "
            f"<code>{provider}</code> "
            f"phase=<code>{phase}</code> "
            f"submit=<code>{'yes' if item.get('submit_called') else 'no'}</code>/<code>{safe_int(item.get('submit_http_status'), 0)}</code> "
            f"accepted=<code>{'yes' if item.get('submit_accepted') else 'no'}</code> "
            f"task=<code>{'yes' if item.get('task_id_present') else 'no'}</code> source=<code>{task_source}</code> "
            f"poll=<code>{'yes' if item.get('poll_called') else 'no'}</code>/<code>{safe_int(item.get('poll_http_status'), 0)}</code> "
            f"raw=<code>{html.escape(str(item.get('poll_raw_status') or '-')[:80])}</code> "
            f"norm=<code>{html.escape(str(item.get('normalized_status') or '-')[:80])}</code> "
            f"continue=<code>{'yes' if item.get('continue_polling') else 'no'}</code> "
            f"url=<code>{'yes' if item.get('result_url_present') else 'no'}</code> "
            f"download=<code>{'yes' if item.get('download_called') else 'no'}</code>/<code>{safe_int(item.get('download_http_status'), 0)}</code> "
            f"type=<code>{content_type}</code> "
            f"bytes=<code>{safe_int(item.get('downloaded_file_size'), 0)}</code> "
            f"valid=<code>{'yes' if item.get('validation_passed') else 'no'}</code> "
            f"blocker=<code>{blocker}</code> "
            f"safe=<code>{safe_error}</code>"
        )
    return lines


VIDEO_DEBUG_REPLY_LIMIT = 3900


def _video_debug_safe_value(value, limit: int = 180) -> str:
    safe_limit = max(1, int(limit or 180))
    try:
        text = sanitize_provider_status_text(str(value if value not in (None, "") else "-"), "", safe_limit)
    except Exception:
        text = str(value if value not in (None, "") else "-")
        text = re.sub(r"(?i)(bearer\s+)[A-Za-z0-9._:-]+", r"\1***", text)
        text = re.sub(r"(?i)(authorization|api[_-]?key|token|secret)=?[A-Za-z0-9._:-]+", r"\1=***", text)
        text = re.sub(r"https?://\S+", "[url]", text)
        text = text[:safe_limit]
    return html.escape(text[:safe_limit])


def _video_debug_compact_attempt_lines(result: dict | None = None, *, limit: int = 4) -> list[str]:
    current = dict(result or {})
    attempts = current.get("provider_attempts") or current.get("provider_fallback_attempts") or current.get("fallback_provider_attempts") or []
    if not isinstance(attempts, list):
        attempts = []
    rows = [dict(item) for item in attempts if isinstance(item, dict)][: max(1, int(limit or 4))]
    lines = ["Provider attempts:"]
    if not rows:
        return [*lines, "• <code>-</code>"]
    for item in rows:
        safe_error = (
            item.get("safe_error")
            or item.get("provider_error_message_safe")
            or item.get("exception_message_safe")
            or "-"
        )
        lines.append(
            "• "
            f"<code>{_video_debug_safe_value(item.get('provider'), 80)}</code> "
            f"phase=<code>{_video_debug_safe_value(item.get('phase') or ('submit' if item.get('submit_failure') else '-'), 40)}</code> "
            f"submit=<code>{'yes' if item.get('submit_called') else 'no'}</code>/<code>{safe_int(item.get('submit_http_status'), 0)}</code> "
            f"accepted=<code>{'yes' if item.get('submit_accepted') else 'no'}</code> "
            f"task=<code>{'yes' if item.get('task_id_present') else 'no'}</code> "
            f"blocker=<code>{_video_debug_safe_value(item.get('blocker') or item.get('reason'), 120)}</code> "
            f"safe=<code>{_video_debug_safe_value(safe_error, 180)}</code>"
        )
    return lines


def _video_scene_ledger_debug_lines(result: dict | None = None) -> list[str]:
    current = dict(result or {})
    task_map = current.get("scene_task_map") if isinstance(current.get("scene_task_map"), dict) else {}
    masked_task_map = {
        str(index): [mask_provider_task_id(task_id) for task_id in (task_ids if isinstance(task_ids, list) else [task_ids]) if str(task_id or "").strip()]
        for index, task_ids in task_map.items()
    }
    active_map = current.get("scene_active_task_by_index") if isinstance(current.get("scene_active_task_by_index"), dict) else {}
    winner_map = current.get("scene_winner_task_by_index") if isinstance(current.get("scene_winner_task_by_index"), dict) else {}
    return [
        "Scene ledger:",
        f"• aggregate status: <code>{_video_debug_safe_value(current.get('aggregate_job_status'), 100)}</code> reason=<code>{_video_debug_safe_value(current.get('aggregate_status_reason'), 140)}</code>",
        f"• required/completed/unresolved/failed: <code>{safe_int(current.get('required_scene_count'), 0)}/{safe_int(current.get('completed_scene_count'), 0)}/{safe_int(current.get('unresolved_scene_count'), 0)}/{safe_int(current.get('failed_scene_count'), 0)}</code>",
        f"• scene task map: <code>{_video_debug_safe_value(masked_task_map, 320)}</code>",
        f"• scene status by index: <code>{_video_debug_safe_value(current.get('scene_status_by_index') or current.get('scene_status_by_scene'), 260)}</code>",
        f"• scene active task by index: <code>{_video_debug_safe_value({key: mask_provider_task_id(value) for key, value in active_map.items()}, 260)}</code>",
        f"• scene winner task by index: <code>{_video_debug_safe_value({key: mask_provider_task_id(value) for key, value in winner_map.items()}, 260)}</code>",
        f"• scene provider progress: <code>{_video_debug_safe_value(current.get('scene_provider_progress_by_index'), 220)}</code>",
        f"• scene result available: <code>{_video_debug_safe_value(current.get('scene_result_available_by_index'), 220)}</code>",
        f"• scene clip valid: <code>{_video_debug_safe_value(current.get('scene_clip_valid_by_index'), 220)}</code>",
        f"• unresolved scene indexes: <code>{_video_debug_safe_value(current.get('unresolved_scene_indexes'), 160)}</code>",
        f"• next scene poll at: <code>{_video_debug_safe_value(current.get('next_scene_poll_at'), 100)}</code>",
        f"• canonical scope: <code>{_video_debug_safe_value(current.get('canonical_scope'), 80)}</code> does_not_imply_job_success=<code>{'yes' if current.get('canonical_does_not_imply_job_success') else 'no'}</code>",
        f"• progress cap correction: <code>{'yes' if current.get('progress_cap_correction') else 'no'}</code> <code>{safe_int(current.get('progress_cap_correction_from'), 0)}→{safe_int(current.get('progress_cap_correction_to'), 0)}</code>",
    ]


def _video_debug_plain_compact_text(text: str, *, reason: str = "message_too_long") -> str:
    raw = str(text or "")
    raw = re.sub(r"</?(?:b|code)>", "", raw)
    raw = re.sub(r"<[^>]+>", "", raw)
    raw = html.unescape(raw)
    safe_lines = []
    for line in raw.splitlines():
        clean = sanitize_provider_status_text(line, "", 260)
        if len(clean) > 260:
            clean = clean[:257] + "..."
        safe_lines.append(clean)
        if len("\n".join(safe_lines)) > VIDEO_DEBUG_REPLY_LIMIT - 220:
            break
    safe_lines.append(f"debug_truncated=yes reason={reason}")
    safe_lines.append("Bot chưa trừ Xu.")
    compact = "\n".join(safe_lines)
    if len(compact) > VIDEO_DEBUG_REPLY_LIMIT:
        compact = compact[: VIDEO_DEBUG_REPLY_LIMIT - 80] + "\ndebug_truncated=yes"
    return compact


