def _video_provider_recover_values(result: dict, keys: tuple[str, ...]) -> list[str]:
    values: list[str] = []

    def add(value) -> None:
        if isinstance(value, (list, tuple, set)):
            for item in value:
                add(item)
            return
        text = str(value or "").strip()
        if text and text not in values:
            values.append(text)

    for key in keys:
        add(result.get(key))
    for event in result.get("provider_events") or []:
        if not isinstance(event, dict):
            continue
        for key in keys:
            add(event.get(key))
    for attempt in result.get("provider_attempts") or []:
        if not isinstance(attempt, dict):
            continue
        for key in keys:
            add(attempt.get(key))
    return values


def _video_provider_recover_identity(result: dict) -> dict:
    provider_values = _video_provider_recover_values(
        result,
        (
            "provider_pending_provider",
            "selected_provider_before_submit",
            "initial_selected_provider",
            "selected_provider",
            "provider",
        ),
    )
    task_ids = _video_provider_recover_values(
        result,
        (
            "provider_pending_task_id",
            "provider_task_id",
            "task_id",
            "id_base",
            "provider_task_ids",
        ),
    )
    video_ids = _video_provider_recover_values(
        result,
        (
            "provider_pending_video_id",
            "provider_video_id",
            "video_id",
            "videoId",
            "provider_video_ids",
        ),
    )
    provider = next((item for item in provider_values if item and item != "-"), "")
    if provider in {"shopai", "shopaikey"}:
        provider = "shopaikey_video"
    elif provider in {"key4u", "k4u"}:
        provider = "key4u_video"
    task_id = next((item for item in task_ids if item and item != "-"), "")
    if not task_id:
        task_id = next((item for item in video_ids if item and item != "-"), "")
    if not provider and task_id:
        provider = "shopaikey_video"
    return {
        "provider": provider,
        "task_id": task_id,
        "task_id_source": "provider_task_ids/provider_pending_task_id" if task_ids else ("provider_video_ids" if video_ids else ""),
        "task_id_masked": mask_provider_task_id(task_id),
    }


def _video_provider_recover_adapter(provider: str):
    target = str(provider or "").strip().lower()
    adapters = video_provider_router.load_video_provider_adapters(os.environ)
    for adapter in adapters:
        if str(getattr(adapter, "provider_name", "") or "").strip().lower() == target:
            return adapter
    if target in {"shopaikey_video", "key4u_video", "toanaas_video", "generic_http"}:
        factory = getattr(video_provider_router, "_generic_adapter_for", None)
        if callable(factory):
            return factory(target, dict(os.environ))
    return None


def _video_provider_normalize_name(value: str) -> str:
    target = str(value or "").strip().lower()
    return {
        "shopai": "shopaikey_video",
        "shopaikey": "shopaikey_video",
        "key4u": "key4u_video",
        "k4u": "key4u_video",
        "toanaas": "toanaas_video",
    }.get(target, target)


def _video_provider_task_candidates(result: dict, project: dict | None = None) -> list[dict]:
    payload = dict(result or {})
    durable_ownership = video_project_queue.product_video_durable_task_scene_owners(payload)
    durable_scene_by_task = dict(durable_ownership.get("task_to_scene_index") or {})
    conflicting_task_ids = set((durable_ownership.get("task_scene_mapping_conflicts") or {}).keys())
    candidates: list[dict] = []
    order = 0

    def add(mapping: dict, source: str, *, provider_hint: str = "", task_value="") -> None:
        nonlocal order
        if not isinstance(mapping, dict):
            return
        provider = _video_provider_normalize_name(
            mapping.get("provider")
            or mapping.get("provider_name")
            or mapping.get("selected_provider")
            or provider_hint
            or payload.get("selected_provider")
            or payload.get("provider_pending_provider")
        )
        task_id = str(
            task_value
            or mapping.get("provider_task_id")
            or mapping.get("task_id")
            or mapping.get("id_base")
            or mapping.get("provider_video_id")
            or mapping.get("video_id")
            or mapping.get("videoId")
            or ""
        ).strip()
        if not task_id or task_id == "-":
            return
        explicit_scene_index = safe_int(
            mapping.get("scene_index")
            or mapping.get("scene_id")
            or mapping.get("clip_index"),
            0,
        )
        durable_scene_index = safe_int(durable_scene_by_task.get(task_id), 0)
        canonical_scene_index = safe_int(payload.get("canonical_scene_index"), 0)
        ownership_conflict = task_id in conflicting_task_ids
        if ownership_conflict:
            scene_index = 0
            scene_index_source = "durable_task_scene_conflict"
        elif explicit_scene_index:
            scene_index = explicit_scene_index
            scene_index_source = "candidate"
        elif durable_scene_index:
            scene_index = durable_scene_index
            scene_index_source = "durable_task_scene_map"
        else:
            scene_index = canonical_scene_index
            scene_index_source = "canonical_scene_fallback" if canonical_scene_index else "missing"
        order += 1
        mapping_direct_task_id = str(
            mapping.get("provider_task_id")
            or mapping.get("task_id")
            or mapping.get("id_base")
            or mapping.get("provider_video_id")
            or mapping.get("video_id")
            or mapping.get("videoId")
            or ""
        ).strip()
        status = str(
            mapping.get("shopaikey_raw_status")
            or mapping.get("provider_status_raw")
            or mapping.get("poll_raw_status")
            or mapping.get("raw_status")
            or mapping.get("normalized_provider_status")
            or mapping.get("provider_status")
            or mapping.get("normalized_status")
            or mapping.get("status")
            or ""
        ).strip()
        result_url = str(
            mapping.get("result_url")
            or mapping.get("provider_result_url")
            or mapping.get("file_url")
            or mapping.get("download_url")
            or mapping.get("output_url")
            or ""
        ).strip()
        if task_value and mapping_direct_task_id and mapping_direct_task_id != task_id:
            result_url = ""
        candidates.append(
            {
                "provider": provider or "shopaikey_video",
                "task_id": task_id,
                "scene_index": scene_index,
                "scene_index_explicit": bool(
                    not ownership_conflict
                    and (explicit_scene_index or durable_scene_index)
                ),
                "scene_index_source": scene_index_source,
                "source": source,
                "status": status,
                "result_url": result_url,
                "timestamp": str(
                    mapping.get("polled_at")
                    or mapping.get("updated_at")
                    or mapping.get("submitted_at")
                    or mapping.get("created_at")
                    or ""
                ),
                "order": order,
                "primary": source in {
                    "persisted_job.provider_pending_task_id",
                    "persisted_job.provider_task_id",
                    "persisted_job.provider_task_ids",
                },
            }
        )

    provider_hint = _video_provider_normalize_name(
        payload.get("provider_pending_provider")
        or payload.get("selected_provider")
        or payload.get("provider")
    )
    for key in ("provider_pending_task_id", "provider_task_id", "task_id", "id_base"):
        add(payload, f"persisted_job.{key}", provider_hint=provider_hint, task_value=payload.get(key))
    for key in ("provider_task_ids", "provider_video_ids"):
        values = payload.get(key) or []
        if not isinstance(values, (list, tuple, set)):
            values = [values]
        for value in values:
            add(payload, f"persisted_job.{key}", provider_hint=provider_hint, task_value=value)
    for group_name in (
        "provider_attempts",
        "provider_pending_attempts",
        "provider_fallback_attempts",
        "fallback_provider_attempts",
        "provider_events",
    ):
        for item in payload.get(group_name) or []:
            if isinstance(item, dict):
                add(item, group_name, provider_hint=provider_hint)
    for group_name in ("scene_ledger", "scene_tasks", "provider_scene_tasks", "product_video_scene_tasks"):
        values = payload.get(group_name) or []
        if isinstance(values, dict):
            values = [
                ({**dict(item or {}), "scene_index": dict(item or {}).get("scene_index") or key} if isinstance(item, dict) else {"scene_index": key, "status": item})
                for key, item in values.items()
            ]
        scene_values = values if isinstance(values, (list, tuple)) else []
        for item in scene_values:
            if not isinstance(item, dict):
                continue
            direct_ids = [
                item.get("active_task_id"),
                item.get("provider_task_id"),
                item.get("task_id"),
                item.get("provider_video_id"),
                item.get("video_id"),
                item.get("winning_task_id"),
                item.get("scene_winner_task"),
                item.get("canonical_task_selected"),
            ]
            direct_ids.extend(item.get("fallback_task_ids") or [])
            seen_scene_ids: set[str] = set()
            for task_value in direct_ids:
                task_text = str(task_value or "").strip()
                if not task_text or task_text in seen_scene_ids:
                    continue
                seen_scene_ids.add(task_text)
                add(item, group_name, provider_hint=provider_hint, task_value=task_text)

    project = dict(project or {})
    for field_name in ("asset_pack_json", "story_bible_json", "addon_plan_json", "invoice_json"):
        metadata = _video_debug_json(project.get(field_name), {})
        if not isinstance(metadata, dict):
            continue
        for key in ("provider_pending_task_id", "provider_task_id", "task_id", "id_base"):
            add(metadata, f"project.{field_name}.{key}", provider_hint=provider_hint, task_value=metadata.get(key))
        for item in metadata.get("provider_attempts") or []:
            if isinstance(item, dict):
                add(item, f"project.{field_name}.provider_attempts", provider_hint=provider_hint)

    merged: dict[tuple[str, str], dict] = {}
    for candidate in candidates:
        key = (candidate["provider"], candidate["task_id"])
        existing = merged.get(key)
        if not existing:
            merged[key] = candidate
            continue
        existing["primary"] = bool(existing.get("primary") or candidate.get("primary"))
        existing["order"] = max(safe_int(existing.get("order"), 0), safe_int(candidate.get("order"), 0))
        if candidate.get("status"):
            existing["status"] = candidate["status"]
        if candidate.get("result_url"):
            existing["result_url"] = candidate["result_url"]
        if candidate.get("timestamp"):
            existing["timestamp"] = candidate["timestamp"]
        if candidate.get("scene_index") and (
            not existing.get("scene_index")
            or (candidate.get("scene_index_explicit") and not existing.get("scene_index_explicit"))
        ):
            existing["scene_index"] = candidate["scene_index"]
        existing["scene_index_explicit"] = bool(existing.get("scene_index_explicit") or candidate.get("scene_index_explicit"))
        sources = [item for item in str(existing.get("source") or "").split(",") if item]
        if candidate["source"] not in sources:
            sources.append(candidate["source"])
        existing["source"] = ",".join(sources)
    return list(merged.values())


def video_b14_result_url_validation(result_url: str = "") -> dict:
    raw_url = str(result_url or "").strip()
    if not raw_url:
        return {
            "result_url_present_raw": False,
            "result_url_valid": False,
            "result_url_invalid_reason": "empty",
            "result_url_host": "",
            "result_url_scheme": "",
            "result_url_ext": "",
            "result_url_query_present": False,
        }
    if raw_url[:1] in {"{", "["} or raw_url.lower() in {"none", "null", "false", "error"}:
        return {
            "result_url_present_raw": True,
            "result_url_valid": False,
            "result_url_invalid_reason": "provider_error_object",
            "result_url_host": "",
            "result_url_scheme": "",
            "result_url_ext": "",
            "result_url_query_present": False,
        }
    parsed = urlparse(raw_url)
    scheme = str(parsed.scheme or "").lower()
    host = str(parsed.netloc or "").strip()
    extension = os.path.splitext(parsed.path or "")[1].lower()
    if scheme not in {"http", "https"} or not host:
        return {
            "result_url_present_raw": True,
            "result_url_valid": False,
            "result_url_invalid_reason": "missing_scheme_or_host",
            "result_url_host": str(parsed.hostname or ""),
            "result_url_scheme": scheme,
            "result_url_ext": extension,
            "result_url_query_present": bool(parsed.query),
        }
    return {
        "result_url_present_raw": True,
        "result_url_valid": True,
        "result_url_invalid_reason": "",
        "result_url_host": str(parsed.hostname or host),
        "result_url_scheme": scheme,
        "result_url_ext": extension,
        "result_url_query_present": bool(parsed.query),
    }


PRODUCT_VIDEO_FALLBACK_BLOCKERS = {
    "provider_failed_result_url_invalid",
    "provider_result_url_missing",
    "provider_download_failed",
    "download_failed",
    "raw_provider_video_download_failed",
    "provider_poll_failed",
    "provider_timeout",
    "duration_short",
    "final_duration_short_scene_coverage_missing",
}


def video_b14_product_video_fallback_policy(
    result: dict | None = None,
    project: dict | None = None,
    blocker: str = "",
    *,
    source: str = "",
) -> dict:
    result = dict(result or {})
    project = dict(project or {})
    policy_metadata = {
        **project,
        **result,
        "is_confirmed": project.get("is_confirmed") or result.get("is_confirmed"),
        "project_is_confirmed": project.get("is_confirmed") or result.get("project_is_confirmed"),
    }
    if source:
        policy_metadata["submit_source"] = source
        policy_metadata["provider_submit_source"] = source
    elif not policy_metadata.get("original_submit_source"):
        policy_metadata["original_submit_source"] = (
            result.get("original_submit_source")
            or result.get("public_confirm_submit_source")
            or project.get("original_submit_source")
            or project.get("public_confirm_submit_source")
            or result.get("submit_source")
            or project.get("submit_source")
            or ""
        )
    fallback_policy = video_provider_router.product_video_controlled_fallback_policy(blocker or result.get("provider_result_blocker") or result.get("blocker") or "", policy_metadata)
    normalized_source = str(fallback_policy.get("current_source") or "")
    blocker = str(blocker or result.get("provider_result_blocker") or result.get("blocker") or "").strip()
    public_confirmed = bool(fallback_policy.get("public_user_confirmed"))
    invoice_confirmed = bool(fallback_policy.get("invoice_confirmed"))
    provider_submit_accepted_before = bool(fallback_policy.get("provider_submit_accepted_before"))
    delivered = bool(
        result.get("delivery_succeeded")
        or result.get("video_delivered")
        or result.get("delivered")
        or project.get("video_delivered_at")
        or project.get("final_video_file_id")
    )
    charged = safe_int(
        result.get("charged_xu")
        or result.get("charged_amount_xu")
        or project.get("charged_xu")
        or project.get("total_xu_charged"),
        0,
    )
    fallback_count = safe_int(result.get("fallback_count") or result.get("provider_fallback_count"), 0)
    status = {}
    try:
        status = video_provider_router.provider_status_payload()
    except Exception:
        status = {}
    chain = [str(item) for item in (result.get("effective_provider_chain") or status.get("effective_provider_chain") or status.get("provider_chain") or []) if str(item or "").strip()]
    primary = str(result.get("canonical_provider") or result.get("selected_provider") or result.get("provider_pending_provider") or (chain[0] if chain else "") or "").strip()
    fallback_provider = ""
    for provider_name in chain:
        if provider_name and provider_name != primary:
            fallback_provider = provider_name
            break
    fallback_public_enabled = bool(fallback_provider)
    if fallback_provider:
        provider_rows = {
            str(item.get("provider") or ""): item
            for item in (status.get("providers") or [])
            if isinstance(item, dict)
        }
        row = provider_rows.get(fallback_provider, {})
        fallback_public_enabled = bool(row.get("public_enabled", True) and row.get("configured", True))
    block_reason = ""
    eligible = True
    if not fallback_policy.get("fallback_allowed"):
        eligible = False
        block_reason = str(fallback_policy.get("fallback_blocked_reason") or "source_not_public_confirmed_fallback")
    elif not public_confirmed:
        eligible = False
        block_reason = "public_confirm_missing"
    elif not invoice_confirmed:
        eligible = False
        block_reason = "invoice_confirm_missing"
    elif not provider_submit_accepted_before:
        eligible = False
        block_reason = "provider_submit_not_accepted_before"
    elif blocker not in PRODUCT_VIDEO_FALLBACK_BLOCKERS:
        eligible = False
        block_reason = "blocker_not_fallbackable"
    elif delivered:
        eligible = False
        block_reason = "already_delivered"
    elif charged > 0:
        eligible = False
        block_reason = "already_charged"
    elif fallback_count >= 1:
        eligible = False
        block_reason = "fallback_limit_reached"
    elif not fallback_provider:
        eligible = False
        block_reason = "fallback_provider_missing"
    elif not fallback_public_enabled:
        eligible = False
        block_reason = "fallback_provider_public_disabled"
    return {
        "fallback_eligible": bool(eligible),
        "fallback_reason": blocker if eligible else "",
        "fallback_block_reason": block_reason,
        "fallback_blocked_reason": block_reason,
        "primary_provider": primary,
        "fallback_provider": fallback_provider,
        "fallback_attempted": False,
        "fallback_count": fallback_count,
        "current_source": normalized_source,
        "original_submit_source": str(fallback_policy.get("original_submit_source") or ""),
        "public_user_confirmed": public_confirmed,
        "invoice_confirmed": invoice_confirmed,
        "provider_submit_accepted_before": provider_submit_accepted_before,
        "fallback_eligibility_source": str(fallback_policy.get("fallback_eligibility_source") or ""),
        "fallback_submit_source": "public_confirmed_scene_fallback_once" if eligible else "",
        "final_decision": "fallback_provider_once" if eligible else "failed_no_charge",
    }


def video_b14_product_video_fallback_eligible(result: dict | None = None, project: dict | None = None, blocker: str = "", *, source: str = "") -> bool:
    return bool(video_b14_product_video_fallback_policy(result, project, blocker, source=source).get("fallback_eligible"))


def _video_provider_status_class(value: str, *, result_url: str = "") -> str:
    normalized = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    result_url_valid = bool(video_b14_result_url_validation(result_url).get("result_url_valid"))
    if normalized in {"success", "succeeded", "completed", "complete", "done", "finished"} or (
        result_url_valid and normalized not in {"failed", "failure", "cancelled", "canceled", "error"}
    ):
        return "succeeded"
    if normalized in {"not_start", "not_started", "provider_not_start", "media_generation_status_not_start"}:
        return "not_start"
    if normalized in {"running", "processing", "in_progress", "pending", "queued", "submitted", "created"}:
        return "running"
    if normalized in {"failed", "failure", "cancelled", "canceled", "error"}:
        return "failed"
    return normalized or "unknown"


def _video_provider_canonical_parser_fields(poll_result) -> dict:
    if poll_result is None:
        return {}
    raw = dict(getattr(poll_result, "raw", {}) or {})
    progress_raw = raw.get("shopaikey_data_progress_raw")
    if progress_raw in (None, ""):
        progress_raw = raw.get("provider_progress_raw")
    progress_number = getattr(poll_result, "progress_percent", None)
    if progress_number in (None, ""):
        progress_number = raw.get("provider_progress_raw_number")
    result_url = str(getattr(poll_result, "result_url", "") or getattr(poll_result, "file_url", "") or "")
    url_check = video_b14_result_url_validation(result_url)
    return {
        "shopaikey_status_endpoint_exact": bool(raw.get("shopaikey_status_endpoint_exact")),
        "shopaikey_status_http_code": safe_int(raw.get("shopaikey_status_http_code") or raw.get("poll_http_status"), 0),
        "shopaikey_raw_status": str(raw.get("shopaikey_raw_status") or getattr(poll_result, "raw_status", "") or ""),
        "shopaikey_normalized_status": str(raw.get("shopaikey_normalized_status") or getattr(poll_result, "status", "") or ""),
        "shopaikey_data_progress_raw": progress_raw if progress_raw not in (None, "") else "",
        "shopaikey_progress_source": "data.progress" if progress_raw not in (None, "") else "none",
        "shopaikey_result_url_from_data": bool(raw.get("shopaikey_result_url_from_data")),
        "shopaikey_data_result_url_present": bool(url_check.get("result_url_valid")),
        "provider_progress_raw": progress_raw if progress_raw not in (None, "") else "",
        "provider_progress_raw_number": progress_number if progress_number not in (None, "") else "",
        "provider_progress_source": "data.progress" if progress_raw not in (None, "") else "none",
        "http_200_not_used_as_progress": True,
        "result_url_source_path": str(raw.get("result_url_source_path") or raw.get("result_field_path") or "none"),
        "result_url_primary_path_checked": bool(raw.get("result_url_primary_path_checked")),
        "result_url_found": bool(url_check.get("result_url_valid")),
        "result_url_present": bool(url_check.get("result_url_valid")),
        "provider_result_url_present": bool(url_check.get("result_url_valid")),
        **url_check,
        "normalized_provider_status": str(getattr(poll_result, "status", "") or ""),
        "provider_status": str(getattr(poll_result, "status", "") or ""),
    }


def resolve_canonical_video_provider_task(
    job_id: int,
    *,
    conn=None,
    job: dict | None = None,
    project: dict | None = None,
    result: dict | None = None,
    poll_candidates: bool = True,
) -> dict:
    """Resolve one stable Product Video task without submitting or falling back."""
    jid = safe_int(job_id, 0)
    owns_conn = conn is None and (job is None or project is None or result is None)
    if owns_conn:
        conn = db_connect()
    try:
        if job is None and conn is not None:
            job = video_project_queue.get_video_render_job(conn, jid)
        if project is None and conn is not None and job:
            project = video_project_queue.get_video_project(conn, safe_int((job or {}).get("project_id"), 0))
        if result is None:
            result = _video_debug_json((job or {}).get("result_json"), {})
        candidates = _video_provider_task_candidates(dict(result or {}), project)
        adapter_cache: dict[str, object] = {}
        for candidate in candidates:
            candidate.update(video_b14_result_url_validation(str(candidate.get("result_url") or "")))
            candidate["status_class"] = _video_provider_status_class(
                candidate.get("status"),
                result_url=str(candidate.get("result_url") or ""),
            )
            if not poll_candidates:
                continue
            provider = str(candidate.get("provider") or "")
            adapter = adapter_cache.get(provider)
            if provider not in adapter_cache:
                adapter = _video_provider_recover_adapter(provider)
                adapter_cache[provider] = adapter
            if adapter is None:
                candidate["poll_error"] = "provider_adapter_missing"
                continue
            try:
                polled = adapter.poll_video_job(str(candidate.get("task_id") or ""))
                candidate["poll_result"] = polled
                candidate["status"] = str(getattr(polled, "raw_status", "") or getattr(polled, "status", "") or "")
                candidate["result_url"] = str(getattr(polled, "result_url", "") or getattr(polled, "file_url", "") or "")
                candidate.update(video_b14_result_url_validation(candidate["result_url"]))
                candidate["status_class"] = _video_provider_status_class(
                    str(getattr(polled, "status", "") or candidate.get("status") or ""),
                    result_url=candidate["result_url"],
                )
                candidate["parser_fields"] = _video_provider_canonical_parser_fields(polled)
            except Exception as exc:
                candidate["poll_error"] = type(exc).__name__

        successful = [
            item for item in candidates
            if item.get("status_class") == "succeeded" and bool(item.get("result_url_valid"))
        ]
        active = [item for item in candidates if item.get("status_class") == "running"]
        not_started = [item for item in candidates if item.get("status_class") == "not_start"]
        primary_not_started = [item for item in not_started if item.get("primary")]
        failed = [item for item in candidates if item.get("status_class") == "failed"]
        selected = None
        selected_reason = "provider_task_id_missing"
        if primary_not_started:
            selected = max(
                primary_not_started,
                key=lambda item: (1 if item.get("primary") else 0, str(item.get("timestamp") or ""), safe_int(item.get("order"), 0)),
            )
            selected_reason = "primary_not_start_task"
        elif successful:
            selected = max(successful, key=lambda item: (str(item.get("timestamp") or ""), safe_int(item.get("order"), 0)))
            selected_reason = "success_result_url_wins"
        elif active:
            selected = max(
                active,
                key=lambda item: (1 if item.get("primary") else 0, str(item.get("timestamp") or ""), safe_int(item.get("order"), 0)),
            )
            selected_reason = "active_primary_task"
        elif failed:
            selected = max(failed, key=lambda item: (str(item.get("timestamp") or ""), safe_int(item.get("order"), 0)))
            selected_reason = "terminal_failed_task"
        elif candidates:
            selected = max(candidates, key=lambda item: (1 if item.get("primary") else 0, safe_int(item.get("order"), 0)))
            selected_reason = "best_persisted_candidate"

        selected = dict(selected or {})
        all_masked = [mask_provider_task_id(item.get("task_id")) for item in candidates if item.get("task_id")]
        parser_fields = dict(selected.get("parser_fields") or {})
        return {
            "job_id": jid,
            "canonical_task_id": str(selected.get("task_id") or ""),
            "canonical_task_id_masked": mask_provider_task_id(selected.get("task_id")),
            "canonical_provider": str(selected.get("provider") or ""),
            "canonical_source": str(selected.get("source") or ""),
            "canonical_status": str(selected.get("status_class") or "unknown"),
            "canonical_result_url": str(selected.get("result_url") or ""),
            "canonical_poll_result": selected.get("poll_result"),
            "all_task_ids_masked": all_masked,
            "task_count": len(candidates),
            "selected_reason": selected_reason,
            "canonical_task_ambiguity": len(candidates) > 1,
            "candidate_summaries": [
                {
                    "provider": str(item.get("provider") or ""),
                    "task_id_masked": mask_provider_task_id(item.get("task_id")),
                    "source": str(item.get("source") or ""),
                    "status": str(item.get("status_class") or "unknown"),
                    "scene_index": safe_int(item.get("scene_index"), 0),
                    "scene_index_explicit": bool(item.get("scene_index_explicit")),
                    "result_url_present": bool(item.get("result_url_valid")),
                    "result_url_present_raw": bool(item.get("result_url_present_raw")),
                    "result_url_valid": bool(item.get("result_url_valid")),
                    "result_url_invalid_reason": str(item.get("result_url_invalid_reason") or ""),
                    "poll_error": str(item.get("poll_error") or ""),
                }
                for item in candidates
            ],
            **parser_fields,
        }
    finally:
        if owns_conn and conn is not None:
            conn.close()


def _video_provider_merge_canonical_task_debug(data: dict, canonical: dict | None = None) -> dict:
    current = dict(data or {})
    canonical = dict(canonical or {})
    task_id = str(canonical.get("canonical_task_id") or "").strip()
    provider = str(canonical.get("canonical_provider") or "").strip()
    result_url = str(canonical.get("canonical_result_url") or "").strip()
    url_check = video_b14_result_url_validation(result_url)
    canonical_status = str(canonical.get("canonical_status") or "").strip().lower()
    candidate_summaries = list(canonical.get("candidate_summaries") or [])
    selected_masked = str(canonical.get("canonical_task_id_masked") or "").strip()
    stale_result_url_ignored = bool(
        canonical
        and canonical_status != "succeeded"
        and any(
            isinstance(item, dict)
            and bool(item.get("result_url_valid") or item.get("result_url_present"))
            and str(item.get("task_id_masked") or "").strip() != selected_masked
            for item in candidate_summaries
        )
    )
    result_url_task_matches_canonical = bool(canonical_status == "succeeded" and url_check.get("result_url_valid"))
    parser_keys = {
        "shopaikey_status_endpoint_exact",
        "shopaikey_status_http_code",
        "shopaikey_raw_status",
        "shopaikey_normalized_status",
        "shopaikey_data_progress_raw",
        "shopaikey_progress_source",
        "shopaikey_result_url_from_data",
        "shopaikey_data_result_url_present",
        "provider_progress_raw",
        "provider_progress_raw_number",
        "provider_progress_source",
        "http_200_not_used_as_progress",
        "result_url_source_path",
        "result_url_primary_path_checked",
        "result_url_found",
        "result_url_present",
        "provider_result_url_present",
        "result_url_present_raw",
        "result_url_valid",
        "result_url_invalid_reason",
        "result_url_host",
        "result_url_scheme",
        "result_url_ext",
        "result_url_query_present",
        "normalized_provider_status",
        "provider_status",
    }
    if canonical:
        current.update(
            {
                "r8d_canonical_parser_active": True,
                "canonical_task_id_masked": canonical.get("canonical_task_id_masked") or "-",
                "canonical_provider": provider or "-",
                "canonical_task_source": canonical.get("canonical_source") or "-",
                "canonical_task_selected_reason": canonical.get("selected_reason") or "-",
                "canonical_task_count": safe_int(canonical.get("task_count"), 0),
                "canonical_all_task_ids_masked": list(canonical.get("all_task_ids_masked") or []),
                "canonical_task_ambiguity": bool(canonical.get("canonical_task_ambiguity")),
                "canonical_candidate_summaries": candidate_summaries,
                "canonical_status": canonical.get("canonical_status") or "-",
                "canonical_result_url_present": bool(result_url_task_matches_canonical),
                "finance_result_task_id": selected_masked if result_url_task_matches_canonical else "-",
                "result_url_task_matches_canonical": bool(result_url_task_matches_canonical),
                "stale_result_url_ignored": bool(stale_result_url_ignored),
                "final_artifact_source": "canonical_result_url" if result_url_task_matches_canonical else "",
                **url_check,
            }
        )
    if task_id:
        current["provider_pending_task_id"] = task_id
        current["provider_task_id_saved"] = True
        task_ids = [str(item) for item in (current.get("provider_task_ids") or []) if str(item or "").strip()]
        if task_id not in task_ids:
            task_ids.insert(0, task_id)
        current["provider_task_ids"] = task_ids
    if provider:
        current["provider_pending_provider"] = provider
        current.setdefault("selected_provider", provider)
    if bool(result_url_task_matches_canonical):
        current["provider_result_url_present"] = True
        current["result_url_present"] = True
        current["result_url_found"] = True
        current["result_url"] = result_url
        current["provider_result_blocker"] = ""
    elif stale_result_url_ignored:
        current["provider_result_url_present"] = False
        current["result_url_present"] = False
        current["result_url_found"] = False
        current["canonical_result_url_present"] = False
        current["result_url_valid"] = False
        current["result_url"] = ""
        current["provider_result_blocker"] = "stale_result_url_ignored"
    elif bool(url_check.get("result_url_present_raw")):
        current["provider_result_url_present"] = False
        current["result_url_present"] = False
        current["result_url_found"] = False
        current["result_url_present_raw"] = True
        current["result_url_valid"] = False
        current["result_url_invalid_reason"] = str(url_check.get("result_url_invalid_reason") or "invalid_result_url")
        current["provider_result_blocker"] = "provider_failed_result_url_invalid"
    for key in parser_keys:
        value = canonical.get(key)
        if value not in (None, "") and (
            key.startswith("shopaikey_")
            or key in {
                "provider_progress_source",
                "http_200_not_used_as_progress",
                "result_url_source_path",
                "result_url_primary_path_checked",
                "result_url_found",
                "result_url_present",
                "provider_result_url_present",
            }
            or current.get(key) in (None, "", 0, 200, "200")
        ):
            current[key] = value
    if canonical.get("http_200_not_used_as_progress"):
        if current.get("provider_progress_raw") in (200, "200"):
            current["provider_progress_raw"] = ""
        if current.get("provider_progress_raw_number") in (200, "200"):
            current["provider_progress_raw_number"] = ""
    if canonical_status == "succeeded":
        current["provider_poll_called"] = True
        current["continue_polling"] = False
        current["normalized_provider_status"] = "succeeded"
        current["provider_status"] = "succeeded"
    elif canonical_status == "not_start":
        current["provider_poll_called"] = True
        current["continue_polling"] = True
        current["normalized_provider_status"] = "not_start"
        current["provider_status"] = "not_start"
        current["provider_error"] = "provider_not_start"
        current["blocker"] = "provider_not_start"
    elif canonical_status == "running":
        current["provider_poll_called"] = True
        current["continue_polling"] = True
        current["normalized_provider_status"] = "running"
        current["provider_status"] = "running"
    return current


def _video_provider_recover_debug_from_poll(poll_result) -> dict:
    raw = dict(getattr(poll_result, "raw", {}) or {})
    result_url = str(getattr(poll_result, "result_url", "") or getattr(poll_result, "file_url", "") or "")
    url_check = video_b14_result_url_validation(result_url)
    return {
        "recovery_poll_called": True,
        "recovery_poll_endpoint_exact": bool(raw.get("shopaikey_status_endpoint_exact")),
        "recovery_poll_http_status": safe_int(raw.get("shopaikey_status_http_code") or raw.get("poll_http_status"), 0),
        "recovery_raw_status": str(raw.get("shopaikey_raw_status") or getattr(poll_result, "raw_status", "") or getattr(poll_result, "status", "") or ""),
        "recovery_normalized_status": str(raw.get("shopaikey_normalized_status") or getattr(poll_result, "status", "") or ""),
        "recovery_data_progress_raw": str(raw.get("shopaikey_data_progress_raw") or raw.get("provider_progress_raw") or ""),
        "recovery_progress_source": str(raw.get("shopaikey_progress_source") or raw.get("provider_progress_source") or "none"),
        "recovery_http_200_not_used_as_progress": bool(raw.get("http_200_not_used_as_progress")),
        "recovery_result_url_found": bool(url_check.get("result_url_valid")),
        "recovery_result_url_source_path": str(raw.get("result_url_source_path") or raw.get("result_field_path") or "none"),
        "recovery_result_url_from_data": bool(raw.get("shopaikey_result_url_from_data") and url_check.get("result_url_valid")),
        "recovery_result_url_present": bool(url_check.get("result_url_valid")),
        "recovery_result_url_present_raw": bool(url_check.get("result_url_present_raw")),
        "recovery_result_url_valid": bool(url_check.get("result_url_valid")),
        "recovery_result_url_invalid_reason": str(url_check.get("result_url_invalid_reason") or ""),
        **url_check,
    }


def _video_provider_update_job_result(conn, job_id: int, updates: dict) -> dict:
    for attempt in range(3):
        job = video_project_queue.get_video_render_job(conn, int(job_id))
        if not job:
            return {}
        original_result_json = str((job or {}).get("result_json") or "")
        current = _video_debug_json(original_result_json, {})
        if not isinstance(current, dict):
            current = {}
        current.update(updates)
        cursor = conn.execute(
            """UPDATE video_jobs
                  SET result_json=?, updated_at=?
                WHERE id=? AND COALESCE(result_json,'')=?""",
            (
                json.dumps(current, ensure_ascii=False),
                now_text_safe(),
                int(job_id),
                original_result_json,
            ),
        )
        if cursor.rowcount == 1:
            conn.commit()
            current["metadata_cas_retries"] = attempt
            current["metadata_cas_conflict"] = bool(attempt)
            return current
        conn.rollback()
    return {
        "metadata_cas_conflict": True,
        "metadata_cas_exhausted": True,
    }


def video_b14_persist_auto_refresh_metadata(job_id: int | str, updates: dict | None = None, conn=None) -> dict:
    jid = safe_int(job_id, 0)
    if jid <= 0:
        return {}
    payload = dict(updates or {})
    if not payload:
        return {}
    owns_conn = conn is None
    if conn is None:
        conn = db_connect()
    try:
        job = video_project_queue.get_video_render_job(conn, jid)
        if not job:
            return {}
        progress = safe_int(
            payload.get("final_progress_after_reconcile")
            or payload.get("final_progress")
            or payload.get("progress_percent"),
            0,
        )
        merged = _video_provider_update_job_result(conn, jid, payload)
        latest_job = video_project_queue.get_video_render_job(conn, jid)
        current_progress = safe_int((latest_job or {}).get("progress_percent"), 0)
        if progress > current_progress:
            cursor = conn.execute(
                """UPDATE video_jobs
                      SET progress_percent=?, updated_at=?
                    WHERE id=? AND COALESCE(progress_percent,0)<?""",
                (
                    min(100, max(0, progress)),
                    now_text_safe(),
                    jid,
                    min(100, max(0, progress)),
                ),
            )
            conn.commit()
            merged["persisted_progress_updated"] = cursor.rowcount == 1
        else:
            merged["persisted_progress_updated"] = False
        return merged
    finally:
        if owns_conn:
            conn.close()


def video_b14_autonomous_db_poll_metadata(
    job_id: int | str,
    *,
    job: dict | None = None,
    project: dict | None = None,
    result: dict | None = None,
    registry_present: bool = False,
    refresh_source: str = "autonomous_db_poll",
    persist: bool = False,
    conn=None,
) -> dict:
    """Describe the DB-backed Product Video poll state without submitting new provider work."""
    jid = safe_int(job_id or (job or {}).get("id") or (job or {}).get("job_id"), 0)
    current_job = dict(job or (video_b14_render_job_by_id(jid) if jid else {}) or {})
    current_project = dict(project or {})
    if current_job and not current_project:
        try:
            current_project = get_video_project(safe_int(current_job.get("project_id"), 0))
        except Exception:
            current_project = {}
    payload = dict(result or video_b14_job_result_payload(current_job) or {})
    telemetry = (
        video_b14_reconciled_provider_debug(
            current_job,
            current_project,
            payload,
            refresh_source=refresh_source,
            poll_candidates=False,
        )
        if current_job
        else dict(payload)
    )
    provider_alive = bool(
        telemetry.get("provider_task_alive")
        or telemetry.get("primary_provider_task_alive")
        or telemetry.get("continue_polling")
    )
    delivered = bool(
        current_project.get("video_delivered_at")
        or current_project.get("video_delivery_message_id")
        or current_project.get("final_video_file_id")
        or current_job.get("final_video_file_id")
    )
    result_url_present = bool(
        telemetry.get("provider_result_url_present")
        or telemetry.get("result_url_present")
        or telemetry.get("shopaikey_result_url_from_data")
        or telemetry.get("canonical_result_url_present")
    )
    interval = max(5, safe_int(
        telemetry.get("panel_refresh_interval_seconds")
        or os.getenv("VIDEO_PROVIDER_EXISTING_TASK_POLL_SECONDS", "")
        or VIDEO_STATUS_AUTO_REFRESH_INTERVAL_SECONDS,
        VIDEO_STATUS_AUTO_REFRESH_INTERVAL_SECONDS,
    ))
    next_dt = datetime.now() + timedelta(seconds=interval)
    next_poll_at = next_dt.isoformat(timespec="seconds")
    terminal_before = str(
        current_project.get("video_terminal_state")
        or payload.get("terminal_state")
        or current_job.get("status")
        or ""
    ).strip()
    candidate = bool(provider_alive and not delivered and not result_url_present)
    metadata = {
        "autonomous_db_poller_enabled": True,
        "autonomous_poll_enabled": True,
        "db_poll_candidate": bool(candidate),
        "registry_required_for_poll": False,
        "registry_missing_is_blocker": False,
        "product_video_registry_present": bool(registry_present),
        "status_registry_missing_after_restart": bool(jid and not registry_present),
        "provider_task_alive": bool(provider_alive),
        "provider_result_url_present": bool(result_url_present),
        "result_url_present": bool(result_url_present),
        "next_poll_at": next_poll_at if candidate else str(telemetry.get("next_poll_scheduled_at") or ""),
        "next_poll_scheduled": bool(candidate or telemetry.get("next_poll_scheduled")),
        "next_poll_scheduled_at": next_poll_at if candidate else str(telemetry.get("next_poll_scheduled_at") or ""),
        "next_refresh_expected_at": next_poll_at if candidate else str(telemetry.get("next_poll_scheduled_at") or ""),
        "auto_refresh_enabled": bool(candidate or provider_alive),
        "auto_refresh_interval_seconds": interval,
        "auto_refresh_recovered_from_db": bool(jid and not registry_present),
        "auto_refresh_next_tick_at": next_poll_at if candidate else str(telemetry.get("next_poll_scheduled_at") or ""),
        "auto_refresh_next_update_at": next_poll_at if candidate else str(telemetry.get("next_poll_scheduled_at") or ""),
        "auto_refresh_last_update_at": now_text_safe(),
        "auto_refresh_skip_reason": "" if candidate or provider_alive else "not_processing",
        "status_panel_message_id_source": "result_json" if payload.get("status_panel_message_id") or payload.get("latest_status_message_id") else "missing",
        "status_panel_message_id": safe_int(payload.get("status_panel_message_id") or payload.get("latest_status_message_id") or payload.get("progress_message_id"), 0),
        "latest_status_message_id": safe_int(payload.get("latest_status_message_id") or payload.get("status_panel_message_id") or payload.get("progress_message_id"), 0),
        "job_id": jid,
        "project_id": safe_int(current_job.get("project_id") or current_project.get("project_id") or current_project.get("id"), 0),
        "poll_interval_seconds": interval,
        "terminal_before_reconcile": terminal_before,
        "terminal_after_reconcile": "final_rendering" if provider_alive else terminal_before,
        "terminal_override_reason": "provider_running_overrides_failed_no_charge" if provider_alive and terminal_before == "failed_no_charge" else "",
        "final_status_after_reconcile": "processing" if provider_alive else str(telemetry.get("final_status_after_reconcile") or current_job.get("status") or ""),
        "final_progress_after_reconcile": safe_int(telemetry.get("final_progress_after_reconcile") or telemetry.get("final_progress") or current_job.get("progress_percent"), 0),
        "no_new_paid_submit": True,
        "paid_fallback_not_used": True,
        "debug_status_read_only_no_submit": True,
        "refresh_source": refresh_source,
    }
    metadata.update({key: telemetry.get(key) for key in (
        "provider_started_at",
        "provider_started_at_source",
        "provider_wait_elapsed_seconds",
        "provider_wait_max_seconds",
        "provider_poll_count",
        "provider_poll_count_source",
        "provider_progress_raw",
        "provider_progress_raw_number",
        "provider_progress_source",
        "render_video_progress_percent",
        "render_video_progress_percent_public",
        "render_progress_public_mode",
        "status_source_priority_used",
        "provider_state_overrode_registry",
        "provider_state_overrode_persisted_status",
            "persisted_status_before_reconcile",
            "persisted_progress_before_reconcile",
            "elapsed_estimate_progress",
            "public_progress_source",
            "public_progress_mode",
            "public_progress_percent_visible",
            "public_progress_cap",
            "persisted_progress_updated",
            "elapsed_live_tick_enabled",
            "elapsed_source",
            "panel_rendered_at",
            "no_fake_success_guard",
            "in_progress_stall_elapsed",
            "in_progress_stall_threshold",
            "provider_progress_last_changed_at",
            "provider_progress_stuck",
            "in_progress_stall_decision",
            "fallback_due_to_in_progress_stall",
        ) if telemetry.get(key) not in (None, "")})
    if persist and jid and (candidate or provider_alive or result_url_present):
        video_b14_persist_auto_refresh_metadata(jid, metadata, conn=conn)
    return metadata


def video_b14_recovery_cancellation_state(
    job_id: int | str,
    *,
    conn=None,
    job: dict | None = None,
    project: dict | None = None,
) -> dict:
    jid = safe_int(job_id, 0)
    if jid <= 0:
        return {"cancelled": False, "blocker": "job_id_required"}
    owns_conn = conn is None
    if conn is None:
        conn = db_connect()
    try:
        job = dict(job or video_project_queue.get_video_render_job(conn, jid) or {})
        if not job:
            return {"cancelled": False, "blocker": "job_not_found"}
        project = dict(
            project
            or video_project_queue.get_video_project(
                conn,
                safe_int(job.get("project_id"), 0),
            )
            or {}
        )
        outbox = (
            video_project_queue.get_product_video_dispatch_outbox(
                conn,
                job_id=jid,
            )
            if callable(getattr(conn, "execute", None))
            else {}
        )
        return {
            **video_project_queue.product_video_recovery_cancellation_state(
                project,
                outbox,
            ),
            "job_id": jid,
        }
    finally:
        if owns_conn:
            conn.close()


async def video_b14_autonomous_materialize_and_deliver(
    context,
    chat_id,
    job_id: int | str,
    *,
    lang: str = "vi",
    source: str = "autonomous_db_poll",
) -> dict:
    """Poll an existing provider task, download a ready result_url, finalize, and deliver once."""
    jid = safe_int(job_id, 0)
    if jid <= 0:
        return {"ok": False, "sent": False, "reason": "job_id_required", "no_new_paid_submit": True, "charge": 0}
    cancellation = video_b14_recovery_cancellation_state(jid)
    if cancellation.get("cancelled"):
        return {
            "ok": False,
            "sent": False,
            "reason": str(cancellation.get("blocker") or "product_video_cancelled"),
            "terminal": True,
            "no_new_paid_submit": True,
            "charge": 0,
        }
    watchdog = run_product_video_bot_side_zero_task_watchdog(
        jid,
        reconciliation_source="worker_claim_recovery",
    )
    if safe_int(watchdog.get("terminal_failed"), 0) > 0:
        detail = next(
            (
                dict(item)
                for item in (watchdog.get("details") or [])
                if isinstance(item, dict) and safe_int(item.get("job_id"), 0) == jid
            ),
            {},
        )
        return {
            "ok": False,
            "sent": False,
            "terminal": True,
            "reason": str(detail.get("zero_task_terminal_reason") or "failed_no_charge"),
            "public_message": "TOAN AAS chưa thể bắt đầu tạo video. Hệ thống chưa trừ Xu.",
            "bot_side_zero_task_watchdog": watchdog,
            "no_new_paid_submit": True,
            "charge": 0,
        }
    already = video_b14_delivered_video_artifact(jid)
    if already.get("ok"):
        charge_after_delivery = product_video_charge_after_final_delivery(
            jid,
            source=f"{source}:already_delivered",
        )
        return {
            "ok": True,
            "sent": False,
            "already_delivered": True,
            "download_button_visible": True,
            **already,
            "charge": safe_int(charge_after_delivery.get("charged_xu"), 0),
            "charge_after_delivery": charge_after_delivery,
        }
    recovery = video_provider_recover_existing_task(jid, download=True, source=source)
    if recovery.get("waiting"):
        conn = db_connect()
        try:
            job = video_project_queue.get_video_render_job(conn, jid)
            project = video_project_queue.get_video_project(conn, safe_int((job or {}).get("project_id"), 0)) if job else {}
            metadata = video_b14_autonomous_db_poll_metadata(
                jid,
                job=job,
                project=project,
                result=dict((recovery.get("debug") or {})),
                registry_present=bool(VIDEO_STATUS_AUTO_REFRESH_JOBS.get(video_b14_auto_refresh_key(jid))),
                refresh_source=source,
                persist=True,
                conn=conn,
            )
        finally:
            conn.close()
        return {
            "ok": False,
            "waiting": True,
            "reason": "provider_in_progress",
            "provider_running": True,
            "autonomous_db_poll": metadata,
            "no_new_paid_submit": True,
            "charge": 0,
        }
    artifact = recovery.get("artifact")
    artifact_path = str(getattr(artifact, "local_path", "") or "").strip()
    if not recovery.get("ok") or not artifact_path:
        return {
            "ok": False,
            "sent": False,
            "reason": str(recovery.get("blocker") or "result_url_not_ready"),
            "recovery": recovery,
            "no_new_paid_submit": True,
            "charge": 0,
        }
    conn = db_connect()
    try:
        job = video_project_queue.get_video_render_job(conn, jid)
        project = video_project_queue.get_video_project(conn, safe_int((job or {}).get("project_id"), 0)) if job else {}
        from services.video_real_render_connector import finalize_recovered_product_video_artifact

        recovery_finalization = finalize_recovered_product_video_artifact(
            job,
            project,
            artifact_path,
            workspace=str(Path(artifact_path).parent),
        )
        if not recovery_finalization.get("ok"):
            _video_provider_update_job_result(
                conn,
                jid,
                {
                    "recovery_finalization": recovery_finalization,
                    "autonomous_finalizer_invoked": True,
                    "autonomous_finalizer_ok": False,
                    "autonomous_finalizer_reason": str(recovery_finalization.get("reason") or "finalizer_failed"),
                    "download_button_visible": False,
                    "no_charge": True,
                    "charge": 0,
                },
            )
            return {
                "ok": False,
                "sent": False,
                "reason": str(recovery_finalization.get("reason") or "finalizer_failed"),
                "recovery": recovery,
                "recovery_finalization": recovery_finalization,
                "charge": 0,
            }
        artifact_path = str(recovery_finalization.get("final_video_path") or artifact_path)
        result_payload = {
            **dict(recovery.get("debug") or {}),
            "ok": True,
            "result_url_auto_materialized": True,
            "autonomous_db_poller_enabled": True,
            "autonomous_materialize_source": source,
            "final_video_path": artifact_path,
            "bytes": safe_int(recovery_finalization.get("output_bytes"), safe_int(getattr(artifact, "bytes", 0), 0)),
            "output_bytes": safe_int(recovery_finalization.get("output_bytes"), safe_int(getattr(artifact, "bytes", 0), 0)),
            "output_duration": float(recovery_finalization.get("final_duration_seconds") or getattr(artifact, "duration", 0.0) or 0.0),
            "recovery_finalization": recovery_finalization,
            "autonomous_finalizer_invoked": True,
            "autonomous_finalizer_ok": True,
            "download_button_visible": False,
            "no_new_paid_submit": True,
            "paid_fallback_not_used": True,
            "charge_policy": "after_valid_mp4_delivery",
        }
        complete = video_project_queue.complete_video_job(
            conn,
            job_id=jid,
            final_video_path=artifact_path,
            result=result_payload,
        )
        if not complete.get("ok"):
            _video_provider_update_job_result(
                conn,
                jid,
                {
                    **result_payload,
                    "autonomous_finalizer_invoked": True,
                    "autonomous_finalizer_ok": False,
                    "autonomous_finalizer_reason": str(complete.get("reason") or "finalizer_failed"),
                    "download_button_visible": False,
                    "charge": 0,
                },
            )
            return {"ok": False, "sent": False, "reason": str(complete.get("reason") or "finalizer_failed"), "recovery": recovery, "charge": 0}
    finally:
        conn.close()
    delivery = await maybe_send_remote_worker_final_video(complete)
    conn = db_connect()
    try:
        noted = video_project_queue.note_video_delivery_result(
            conn,
            job_id=jid,
            sent=bool(delivery.get("sent")),
            delivery_message_id=str(delivery.get("telegram_message_id") or ""),
            success_message_id=str(delivery.get("success_message_id") or delivery.get("telegram_message_id") or ""),
            reason=str(delivery.get("reason") or delivery.get("delivery_reason") or "telegram_delivery_failed"),
        )
        _video_provider_update_job_result(
            conn,
            jid,
            {
                "autonomous_delivery_attempted": True,
                "autonomous_delivery_source": source,
                "autonomous_delivery_sent": bool(delivery.get("sent")),
                "delivery_succeeded": bool(delivery.get("sent")),
                "video_delivered": bool(delivery.get("sent")),
                "download_button_visible": bool(delivery.get("sent")),
                "download_source": "telegram_file_id_or_final_path" if delivery.get("sent") else "",
                "result_url_auto_materialized": True,
                "charge_policy": "after_valid_mp4_delivery",
                "charge_after_delivery_gate": "valid_mp4_delivered" if delivery.get("sent") else "delivery_failed_no_charge",
                "charge": 0,
            },
        )
        charge_after_delivery = (
            product_video_charge_after_final_delivery(
                jid,
                conn=conn,
                source=source,
            )
            if delivery.get("sent")
            else {"ok": False, "charged_xu": 0, "charge_skip_reason": "delivery_failed_no_charge"}
        )
    finally:
        conn.close()
    return {
        "ok": bool(delivery.get("sent")),
        "sent": bool(delivery.get("sent")),
        "delivery": delivery,
        "note_delivery": noted,
        "recovery": recovery,
        "download_button_visible": bool(delivery.get("sent")),
        "charge": safe_int(charge_after_delivery.get("charged_xu"), 0),
        "charge_after_delivery": charge_after_delivery,
    }


def video_provider_recover_existing_task(job_id: int, *, download: bool = False, conn=None, source: str = "recover") -> dict:
    jid = safe_int(job_id, 0)
    if jid <= 0:
        return {"ok": False, "blocker": "job_id_required", "charge": 0}
    owns_conn = conn is None
    if conn is None:
        conn = db_connect()
    try:
        job = video_project_queue.get_video_render_job(conn, jid)
        if not job:
            return {"ok": False, "blocker": "job_not_found", "job_id": jid, "charge": 0}
        result = _video_debug_json((job or {}).get("result_json"), {})
        project = video_project_queue.get_video_project(conn, safe_int((job or {}).get("project_id"), 0))
        cancellation = video_b14_recovery_cancellation_state(
            jid,
            conn=conn,
            job=job,
            project=project,
        )
        if cancellation.get("cancelled"):
            blocker = str(cancellation.get("blocker") or "product_video_cancelled")
            return {
                "ok": False,
                "blocker": blocker,
                "reason": blocker,
                "job_id": jid,
                "no_new_paid_submit": True,
                "charge": 0,
            }
        canonical = resolve_canonical_video_provider_task(
            jid,
            conn=conn,
            job=job,
            project=project,
            result=result if isinstance(result, dict) else {},
            poll_candidates=True,
        )
        provider = str(canonical.get("canonical_provider") or "").strip()
        task_id = str(canonical.get("canonical_task_id") or "").strip()
        identity = {
            "task_id_masked": canonical.get("canonical_task_id_masked"),
            "task_id_source": canonical.get("canonical_source"),
        }
        if not task_id:
            _video_provider_update_job_result(
                conn,
                jid,
                {
                    "video_provider_recover_called": True,
                    "video_provider_recover_download_requested": bool(download),
                    "no_new_paid_submit": True,
                    "recovery_charge_xu": 0,
                    "recovery_blocker": "provider_task_id_missing",
                },
            )
            return {"ok": False, "blocker": "provider_task_id_missing", "job_id": jid, "provider": provider or "-", "charge": 0}
        if download and bool((result or {}).get("raw_provider_video_delivered")):
            return {
                "ok": True,
                "already_delivered": True,
                "blocker": "",
                "job_id": jid,
                "provider": provider,
                "task_id_masked": identity.get("task_id_masked"),
                "debug": {
                    "recovery_raw_video_sent": True,
                    "raw_provider_video_delivered": True,
                    "duplicate_delivery_prevented": True,
                    "no_new_paid_submit": True,
                    "paid_fallback_not_used": True,
                    "recovery_charge_xu": 0,
                    "canonical_task_id_masked": canonical.get("canonical_task_id_masked"),
                    "canonical_task_source": canonical.get("canonical_source"),
                    "canonical_task_selected_reason": canonical.get("selected_reason"),
                },
                "charge": 0,
            }
        adapter = _video_provider_recover_adapter(provider)
        if adapter is None:
            _video_provider_update_job_result(
                conn,
                jid,
                {
                    "video_provider_recover_called": True,
                    "video_provider_recover_download_requested": bool(download),
                    "existing_provider_task_id_found": True,
                    "provider_task_id_masked": identity.get("task_id_masked"),
                    "no_new_paid_submit": True,
                    "recovery_charge_xu": 0,
                    "recovery_blocker": "provider_adapter_missing",
                },
            )
            return {"ok": False, "blocker": "provider_adapter_missing", "job_id": jid, "provider": provider or "-", "task_id_masked": identity.get("task_id_masked"), "charge": 0}

        poll_result = canonical.get("canonical_poll_result")
        if poll_result is None:
            poll_result = adapter.poll_video_job(task_id)
        poll_debug = _video_provider_recover_debug_from_poll(poll_result)
        result_url_validation = video_b14_result_url_validation(
            str(getattr(poll_result, "result_url", "") or getattr(poll_result, "file_url", "") or "")
        )
        normalized = _video_provider_status_class(
            str(getattr(poll_result, "status", "") or poll_debug.get("recovery_normalized_status") or ""),
            result_url=str(getattr(poll_result, "result_url", "") or getattr(poll_result, "file_url", "") or ""),
        )
        all_task_ids = [
            str(item.get("task_id") or "")
            for item in _video_provider_task_candidates(result if isinstance(result, dict) else {}, project)
            if str(item.get("task_id") or "").strip()
        ]
        updates = {
            "video_provider_recover_called": True,
            "video_provider_recover_download_requested": bool(download),
            "existing_provider_task_id_found": True,
            "provider_pending_provider": provider,
            "provider_pending_task_id": task_id,
            "provider_task_ids": list(dict.fromkeys(all_task_ids or [task_id])),
            "provider_task_id_masked": identity.get("task_id_masked"),
            "canonical_task_id_masked": canonical.get("canonical_task_id_masked"),
            "canonical_task_source": canonical.get("canonical_source"),
            "canonical_task_selected_reason": canonical.get("selected_reason"),
            "canonical_task_count": safe_int(canonical.get("task_count"), 0),
            "canonical_all_task_ids_masked": list(canonical.get("all_task_ids_masked") or []),
            "canonical_task_ambiguity": bool(canonical.get("canonical_task_ambiguity")),
            "canonical_candidate_summaries": list(canonical.get("candidate_summaries") or []),
            "no_new_paid_submit": True,
            "paid_fallback_not_used": True,
            "recovery_charge_xu": 0,
            "postprocess_required_for_recovery": True,
            "delivery_type": "raw_provider_video_pending_finalization",
            **poll_debug,
            **result_url_validation,
        }
        if normalized == "running":
            poll_metadata = video_b14_autonomous_db_poll_metadata(
                jid,
                job=job,
                project=project,
                result={**result, **updates, **poll_debug},
                registry_present=bool(VIDEO_STATUS_AUTO_REFRESH_JOBS.get(video_b14_auto_refresh_key(jid))),
                refresh_source="provider_recover_running",
            )
            updates.update(
                {
                    "recovery_status": "waiting_provider_result",
                    "recovery_blocker": "provider_in_progress",
                    "continue_polling": True,
                    **poll_metadata,
                }
            )
            _video_provider_update_job_result(conn, jid, updates)
            return {
                "ok": False,
                "waiting": True,
                "blocker": "provider_in_progress",
                "job_id": jid,
                "provider": provider,
                "task_id_masked": identity.get("task_id_masked"),
                "poll": poll_result,
                "debug": updates,
                "charge": 0,
            }
        if normalized == "failed":
            failed_blocker = str(getattr(poll_result, "error_code", "") or normalized)
            fallback_policy = video_b14_product_video_fallback_policy(result, project, failed_blocker, source=source)
            updates.update(
                {
                    "recovery_status": "provider_failed",
                    "recovery_blocker": failed_blocker,
                    "continue_polling": False,
                    **fallback_policy,
                }
            )
            _video_provider_update_job_result(conn, jid, updates)
            return {
                "ok": False,
                "blocker": updates["recovery_blocker"],
                "job_id": jid,
                "provider": provider,
                "task_id_masked": identity.get("task_id_masked"),
                "poll": poll_result,
                "debug": updates,
                "charge": 0,
            }
        if normalized == "succeeded" and poll_debug.get("recovery_result_url_present_raw") and not poll_debug.get("recovery_result_url_valid"):
            fallback_policy = video_b14_product_video_fallback_policy(
                result,
                project,
                "provider_failed_result_url_invalid",
                source=source,
            )
            updates.update(
                {
                    "recovery_status": "completed_invalid_result_url",
                    "recovery_blocker": "provider_failed_result_url_invalid",
                    "provider_result_blocker": "provider_failed_result_url_invalid",
                    "continue_polling": False,
                    **fallback_policy,
                }
            )
            _video_provider_update_job_result(conn, jid, updates)
            return {
                "ok": False,
                "blocker": "provider_failed_result_url_invalid",
                "job_id": jid,
                "provider": provider,
                "task_id_masked": identity.get("task_id_masked"),
                "poll": poll_result,
                "debug": updates,
                "charge": 0,
            }
        if normalized == "succeeded" and not poll_debug.get("recovery_result_url_present"):
            fallback_policy = video_b14_product_video_fallback_policy(
                result,
                project,
                "provider_result_url_missing",
                source=source,
            )
            updates.update(
                {
                    "recovery_status": "completed_missing_result_url",
                    "recovery_blocker": "provider_result_url_missing",
                    "continue_polling": False,
                    **fallback_policy,
                }
            )
            _video_provider_update_job_result(conn, jid, updates)
            return {
                "ok": False,
                "blocker": "provider_result_url_missing",
                "job_id": jid,
                "provider": provider,
                "task_id_masked": identity.get("task_id_masked"),
                "poll": poll_result,
                "debug": updates,
                "charge": 0,
            }
        if normalized == "succeeded" and not download:
            updates.update({"recovery_status": "result_url_available", "recovery_blocker": "", "continue_polling": False})
            _video_provider_update_job_result(conn, jid, updates)
            return {
                "ok": True,
                "result_url_available": True,
                "job_id": jid,
                "provider": provider,
                "task_id_masked": identity.get("task_id_masked"),
                "poll": poll_result,
                "debug": updates,
                "charge": 0,
            }

        artifact = adapter.materialize_result(poll_result, f"recovery_job_{jid}")
        download_debug = dict(getattr(artifact, "diagnostics", {}) or {})
        download_blocker = "" if artifact.ok else (artifact.error_code or "provider_download_failed")
        fallback_policy = video_b14_product_video_fallback_policy(
            result,
            project,
            download_blocker or "provider_download_failed",
            source=source,
        )
        updates.update(
            {
                "recovery_status": "raw_provider_video_downloaded" if artifact.ok else "raw_provider_video_download_failed",
                "recovery_download_attempted": True,
                "recovery_download_success": bool(artifact.ok),
                "raw_provider_video_artifact_path": str(artifact.local_path or ""),
                "raw_provider_video_valid": bool(artifact.ok and artifact.has_video_stream and artifact.bytes > 0),
                "raw_provider_video_bytes": int(artifact.bytes or 0),
                "raw_provider_video_duration": float(artifact.duration or 0.0),
                "recovery_blocker": download_blocker,
                "continue_polling": False,
                "terminal_state": "recover_ready_for_delivery" if artifact.ok else "recover_failed",
                "no_charge": True,
                **({} if artifact.ok else fallback_policy),
                **download_debug,
            }
        )
        _video_provider_update_job_result(conn, jid, updates)
        return {
            "ok": bool(artifact.ok),
            "blocker": "" if artifact.ok else updates["recovery_blocker"],
            "job_id": jid,
            "provider": provider,
            "task_id_masked": identity.get("task_id_masked"),
            "poll": poll_result,
            "artifact": artifact,
            "debug": updates,
            "charge": 0,
        }
    finally:
        if owns_conn:
            conn.close()


def video_provider_recover_text(payload: dict) -> str:
    jid = safe_int(payload.get("job_id"), 0)
    provider = html.escape(str(payload.get("provider") or "-"))
    task_masked = html.escape(str(payload.get("task_id_masked") or "-"))
    blocker = html.escape(str(payload.get("blocker") or (payload.get("debug") or {}).get("recovery_blocker") or "-")[:180])
    debug = dict(payload.get("debug") or {})
    status = html.escape(str(debug.get("recovery_raw_status") or debug.get("recovery_normalized_status") or "-")[:120])
    progress = html.escape(str(debug.get("recovery_data_progress_raw") or "-")[:80])
