async def cmd_video_provider_recover(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id if update.effective_user else 0
    if not is_admin_user(uid):
        return await update.message.reply_text("⛔ Lệnh này chỉ dành cho admin.")
    args = _diagnostic_message_args(update, context)
    job_id = safe_int(args[0] if args else 0, 0)
    if job_id <= 0:
        return await update.message.reply_text("⚠️ Dùng: <code>/video_provider_recover JOB_ID</code>", parse_mode="HTML")
    payload = video_provider_recover_existing_task(job_id, download=True)
    artifact = payload.get("artifact")
    artifact_path = str(getattr(artifact, "local_path", "") or "")
    if payload.get("ok") and artifact_path:
        delivery = await send_generated_video_artifact_for_delivery(
            context.bot,
            update.effective_chat.id,
            artifact_path,
            filename=f"toan_aas_raw_provider_video_{job_id}.mp4",
            caption="TOAN AAS đã lấy được video thô từ hệ thống dựng. Đây là bản gốc để kiểm tra trước khi xử lý hậu kỳ.",
            lang="vi",
        )
        conn = db_connect()
        try:
            _video_provider_update_job_result(
                conn,
                job_id,
                {
                    "recovery_raw_video_sent": bool(delivery.get("sent")),
                    "raw_provider_video_delivered": bool(delivery.get("sent")),
                    "recovery_delivery_method": str(delivery.get("method") or ""),
                    "recovery_delivery_message_id": str(delivery.get("telegram_message_id") or ""),
                    "recovery_charge_xu": 0,
                    "no_new_paid_submit": True,
                    "paid_fallback_not_used": True,
                },
            )
        finally:
            conn.close()
        if delivery.get("sent"):
            return await video_debug_safe_reply_text(update.message, video_provider_recover_text(payload))
        payload = {
            **payload,
            "blocker": "telegram_raw_video_delivery_failed",
            "debug": {**dict(payload.get("debug") or {}), "recovery_blocker": "telegram_raw_video_delivery_failed"},
        }
    return await video_debug_safe_reply_text(update.message, video_provider_recover_text(payload))


def multiscene_job_status_text(job: dict, *, admin: bool = True) -> str:
    if not job:
        return "⚠️ Không tìm thấy video multiscene job. TOAN AAS chưa gọi provider mới."
    parent_id = str(job.get("parent_task_id") or "-")
    scene_jobs = list(job.get("scene_jobs") or [])
    completed = sum(1 for child in scene_jobs if str(child.get("status") or "").upper() == "COMPLETED")
    submitted = sum(1 for child in scene_jobs if str(child.get("provider_task_id") or "").strip())
    lines = [
        f"🎞 <b>VIDEO MULTISCENE JOB {html.escape(parent_id)}</b>",
        "",
        f"• Status: <code>{html.escape(str(job.get('status') or '-'))}</code>",
        f"• Scenes: <code>{completed}/{len(scene_jobs)} completed</code>",
        f"• Provider accepted scenes: <code>{submitted}/{len(scene_jobs)}</code>",
        f"• Stitching: <code>{'completed' if job.get('final_output') else ('failed' if job.get('stitching_error') else ('waiting_all_scenes' if completed < len(scene_jobs) else 'ready_or_running'))}</code>",
        f"• Final bytes: <code>{os.path.getsize(job.get('final_output')) if job.get('final_output') and os.path.exists(str(job.get('final_output'))) else 0}</code>",
        f"• Error: <code>{html.escape(str(job.get('error') or job.get('stitching_error') or '-')[:180])}</code>",
        f"• Updated: <code>{html.escape(str(job.get('updated_at') or '-'))}</code>",
        "",
        "Scene progress:",
    ]
    for child in sorted(scene_jobs, key=lambda item: int(item.get("scene_index") or 0)):
        scene_idx = int(child.get("scene_index") or 0)
        provider_task = str(child.get("provider_task_id") or "")
        provider_note = f" task=<code>{html.escape(mask_provider_task_id(provider_task))}</code>" if admin and provider_task else ""
        lines.append(
            f"• Scene {scene_idx}: <code>{html.escape(str(child.get('status') or 'QUEUED'))}</code>"
            f" provider=<code>{html.escape(str(child.get('provider') or '-'))}</code>"
            f" polls=<code>{int(child.get('poll_count') or 0)}</code>"
            f" output=<code>{'yes' if child.get('output_url') or child.get('local_file') else 'no'}</code>"
            f"{provider_note}"
            f" error=<code>{html.escape(str(child.get('error') or '-')[:120])}</code>"
        )
    lines.append("")
    lines.append("Provider task id thô không hiển thị; chỉ dùng masked diagnostics cho admin.")
    if admin and multiscene_job_has_overloaded_failure(job):
        lines.extend(["", multiscene_overloaded_admin_copy()])
    return "\n".join(lines)

def multiscene_failed_scene_indexes(job: dict) -> list[int]:
    indexes: list[int] = []
    for child in list((job or {}).get("scene_jobs") or []):
        if str(child.get("status") or "").upper() == "FAILED":
            indexes.append(int(child.get("scene_index") or 0))
    return [idx for idx in indexes if idx > 0]

def multiscene_successful_scene_indexes(job: dict) -> list[int]:
    indexes: list[int] = []
    for child in list((job or {}).get("scene_jobs") or []):
        if str(child.get("status") or "").upper() == "COMPLETED":
            indexes.append(int(child.get("scene_index") or 0))
    return [idx for idx in indexes if idx > 0]

def multiscene_job_has_overloaded_failure(job: dict) -> bool:
    haystack = " ".join(
        str(value or "")
        for child in list((job or {}).get("scene_jobs") or [])
        for value in (child.get("error"), child.get("fail_reason"), child.get("provider_message"))
    ).lower()
    return any(term in haystack for term in ("overloaded", "overload", "quá tải", "rate limit", "capacity"))

def multiscene_overloaded_admin_copy() -> str:
    return (
        "Provider video đang quá tải. Job đã thất bại ở cảnh này. TOAN AAS chưa trừ Xu. "
        "Admin có thể retry cảnh lỗi hoặc freeze provider video tạm thời."
    )

def multiscene_retry_plan(job: dict, *, confirmed: bool = False, fallback_verified: bool = False) -> dict:
    failed = multiscene_failed_scene_indexes(job)
    completed = multiscene_successful_scene_indexes(job)
    return {
        "requires_confirm": bool(failed and not confirmed),
        "retry_scene_indexes": failed,
        "skip_scene_indexes": completed,
        "fallback_available": bool(fallback_verified),
        "will_create_jobs": bool(failed and confirmed),
    }

def multiscene_retry_help_text(job: dict, *, confirmed: bool = False, fallback_verified: bool = False) -> str:
    if not job:
        return "⚠️ Không tìm thấy video multiscene job. Chưa tạo retry."
    plan = multiscene_retry_plan(job, confirmed=confirmed, fallback_verified=fallback_verified)
    failed = ", ".join(str(idx) for idx in plan["retry_scene_indexes"]) or "-"
    skipped = ", ".join(str(idx) for idx in plan["skip_scene_indexes"]) or "-"
    fallback_line = (
        "• Fallback: <code>có route đã xác minh</code>"
        if plan["fallback_available"]
        else "• Fallback: <code>chưa có route fallback đã xác minh</code>"
    )
    action_line = (
        "• Xác nhận: <code>đã nhận</code>. Màn này không tự tạo job mới; admin chạy lệnh retry riêng khi sẵn sàng."
        if confirmed
        else "• Xác nhận: <code>cần xác nhận trước khi retry thật</code>."
    )
    return "\n".join([
        "🔁 <b>Retry cảnh lỗi multiscene</b>",
        "",
        multiscene_overloaded_admin_copy() if multiscene_job_has_overloaded_failure(job) else "Chỉ retry các cảnh lỗi, không đụng cảnh đã thành công.",
        "",
        f"• Parent: <code>{html.escape(str(job.get('parent_task_id') or '-'))}</code>",
        f"• Retry scenes: <code>{html.escape(failed)}</code>",
        f"• Skip successful scenes: <code>{html.escape(skipped)}</code>",
        fallback_line,
        action_line,
        "",
        "Không duplicate cảnh đã thành công. Không fake output. Không chạy provider từ màn hướng dẫn này.",
    ])

def multiscene_retry_help_keyboard(parent_task_id: str, *, confirmed: bool = False) -> InlineKeyboardMarkup:
    safe_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(parent_task_id or ""))[:40]
    rows = []
    if safe_id and not confirmed:
        confirm_callback = f"enginejob|multiscene_retry_confirm|{safe_id}"
        if len(confirm_callback.encode("utf-8")) <= 64:
            rows.append([InlineKeyboardButton("✅ Xác nhận retry cảnh lỗi", callback_data=confirm_callback)])
    if safe_id:
        rows.append([InlineKeyboardButton("🔄 Làm mới", callback_data=f"enginejob|multiscene|{safe_id}")])
    rows.append([InlineKeyboardButton("🟡 Freeze", callback_data="menu|admin_confirm_provider_freeze_video"), InlineKeyboardButton("📊 Provider Status", callback_data="menu|admin_provider_status")])
    rows.append([InlineKeyboardButton("⚙️ Admin", callback_data="menu|admin"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")])
    return InlineKeyboardMarkup(rows)

async def poll_multiscene_job_once(parent_task_id: str, *, poller=None, updated_by="") -> dict:
    job = get_multiscene_job_record(parent_task_id)
    if not job:
        return {"ok": False, "status": "JOB_NOT_FOUND", "job": {}}
    changed = False
    for child in list(job.get("scene_jobs") or []):
        status = str(child.get("status") or "").upper()
        task_id = str(child.get("provider_task_id") or "").strip()
        if status in {"COMPLETED", "FAILED"} or not task_id:
            continue
        try:
            if poller:
                last = await poller(child)
            elif str(child.get("provider") or "").lower() == "key4u":
                last = await key4u_provider_instance().poll_video_task(task_id)
            else:
                last = await shopaikey_video_job_status(task_id)
        except Exception as exc:
            last = {"status": "IN_PROGRESS", "error_class": type(exc).__name__, "detail": "poll temporarily unavailable"}
        provider_status = _multiscene_provider_status(last)
        output_url = str(last.get("result_url") or last.get("output_url") or "").strip()
        poll_count = int(child.get("poll_count") or 0) + 1
        if provider_status == "COMPLETED" and output_url:
            _multiscene_update_child(
                job,
                int(child.get("scene_index") or 0),
                status="COMPLETED",
                output_url=output_url,
                poll_count=poll_count,
                completed_at=now_text(),
                error="",
            )
        elif provider_status == "FAILED":
            reason = shopaikey_sanitize_error(str(last.get("fail_reason") or last.get("detail") or last.get("error_class") or "scene failed"))
            _multiscene_update_child(
                job,
                int(child.get("scene_index") or 0),
                status="FAILED",
                poll_count=poll_count,
                error=reason,
                completed_at=now_text(),
            )
        else:
            _multiscene_update_child(
                job,
                int(child.get("scene_index") or 0),
                status="IN_PROGRESS",
                poll_count=poll_count,
                error="",
            )
        changed = True
        job = get_multiscene_job_record(parent_task_id) or job
    if changed:
        job["last_poll_at"] = now_text()
        save_multiscene_job_record(job)
    return {"ok": True, "status": str(job.get("status") or "UNKNOWN"), "job": job}

def list_recent_shopaikey_video_jobs(limit: int = 8) -> list[dict]:
    conn = None
    try:
        conn = db_connect()
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            """SELECT * FROM shopaikey_jobs
               WHERE job_type IN ('video','video_scene')
               ORDER BY id DESC LIMIT ?""",
            (max(1, int(limit or 8)),),
        ).fetchall()
        return [dict(row) for row in rows]
    except Exception:
        return []
    finally:
        if conn:
            conn.close()

