async def handle_video_export_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE, session_id: str = ""):
    """Bridge Task 3D final export to the old stable ShopAIKey video core."""
    query = update.callback_query
    uid = query.from_user.id
    lang = user_ui_lang(uid)
    token = str(session_id or "").strip()
    state = get_video_addon_state(uid)
    if not state:
        await query.answer()
        return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
    pending_payload = dict(state.get("pending_payload") or {})
    if token and token in SHOPAIKEY_PENDING_CONFIRMATIONS:
        pending_payload.update(dict(SHOPAIKEY_PENDING_CONFIRMATIONS[token] or {}))
        state["pending_payload"] = pending_payload
        set_video_addon_state(uid, state)
    token = token or str(state.get("pending_confirm_token") or "")
    tier = normalize_video_tier(state.get("video_tier") or pending_payload.get("video_tier"))
    quote = calculate_video_quote(state)
    if state.get("source") != "frame" and tier == "low" and not quote.get("is_package_200_valid"):
        await query.answer()
        return await safe_edit_or_send(
            query,
            video_experience_tier_lock_text(lang, video_package_200_lock_reasons(quote)),
            parse_mode=None,
            reply_markup=video_experience_tier_lock_keyboard(lang),
        )
    if state.get("source") != "frame" and int(quote.get("scene_count") or 1) > 1 and not video_multiscene_public_ready(quote.get("scene_count")):
        await query.answer()
        if is_admin_user(uid):
            decision = can_user_access_product_engine(
                uid,
                "video_multiscene",
                str(int(quote.get("scene_count") or 1)),
                is_provider_call=True,
                is_paid_job=True,
                admin_interactive_confirm=True,
                state={"scene_count": int(quote.get("scene_count") or 1)},
            )
            if not decision.get("allowed"):
                return await safe_edit_or_send(
                    query,
                    decision.get("message") or admin_product_engine_missing_text("video_multiscene", decision.get("readiness")),
                    parse_mode="HTML",
                    reply_markup=video_export_maintenance_keyboard(lang),
                )
        else:
            return await safe_edit_or_send(
                query,
                VIDEO_MULTISCENE_PUBLIC_GUARD_TEXT,
                parse_mode=None,
                reply_markup=video_export_maintenance_keyboard(lang),
            )
    classification = classify_video_addons_for_package(state)

    voice_mux_guard = video_voice_mux_export_guard(state)
    if not voice_mux_guard.get("ok"):
        await query.answer()
        return await safe_edit_or_send(
            query,
            PUBLIC_PRODUCT_MAINTENANCE_VI
            if normalize_user_language(lang) == "vi" else
            PUBLIC_PRODUCT_MAINTENANCE_EN,
            parse_mode=None,
            reply_markup=video_export_maintenance_keyboard(lang),
        )

    # Public readiness is checked here so a missing/closed provider gives a clean
    # no-charge guard while preserving the invoice token and video session.
    export_enabled, _export_message = shopaikey_public_generation_guard("video")
    key4u_ready = key4u_public_video_route_ready() if tier in {"future_1000", "future_1200", "future_1500"} else key4u_public_video_fallback_ready()
    if not export_enabled and not key4u_ready:
        await query.answer()
        if is_admin_user(uid):
            decision = can_user_access_product_engine(
                uid,
                "video",
                "export",
                is_provider_call=True,
                is_paid_job=True,
                admin_interactive_confirm=True,
            )
            if not decision.get("allowed"):
                return await safe_edit_or_send(
                    query,
                    decision.get("message") or admin_product_engine_missing_text("video_single", decision.get("readiness")),
                    parse_mode="HTML",
                    reply_markup=video_export_maintenance_keyboard(lang),
                )
        else:
            return await safe_edit_or_send(
                query,
                PUBLIC_PRODUCT_MAINTENANCE_VI
                if normalize_user_language(lang) == "vi" else
                PUBLIC_PRODUCT_MAINTENANCE_EN,
                parse_mode=None,
                reply_markup=video_export_maintenance_keyboard(lang),
            )

    state = normalize_video_export_payload_for_classifier(state, classification)
    if state.get("source") != "frame" and int(quote.get("scene_count") or 1) > 1:
        active_multiscene = shopaikey_active_job_for_user(uid, "video")
        if active_multiscene:
            await query.answer()
            return await safe_edit_or_send(
                query,
                "Video nhiều cảnh của bạn đang được xử lý. TOAN AAS sẽ chỉ gửi một video hoàn chỉnh sau khi đủ cảnh và ghép xong.",
                parse_mode=None,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]]),
            )
        multiscene_session = video_multiscene_session_snapshot(uid, state)
        multiscene_session.update({
            "selected_scene_count": int(quote.get("scene_count") or 1),
            "scene_count": int(quote.get("scene_count") or 1),
            "estimated_scene_seconds": int(state.get("estimated_scene_seconds") or TASK3D_SCENE_SECONDS or 6),
            "estimated_total_seconds": int(quote.get("estimated_seconds") or int(quote.get("scene_count") or 1) * 6),
            "current_video_price_preview": dict(quote),
            "video_tier": tier,
            "selected_video_tier": tier,
            "language": lang,
        })
        await query.answer()
        await safe_edit_or_send(
            query,
            f"TOAN AAS đang tạo {int(quote.get('scene_count') or 1)} cảnh, kiểm tra đủ đầu ra rồi ghép thành một video hoàn chỉnh. Thời lượng ước tính khoảng {int(quote.get('estimated_seconds') or 0)} giây.",
            parse_mode=None,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]]),
        )
        engine_result = await execute_engine(
            "video_multiscene",
            {
                "wait_for_completion": False,
                "scene_count": int(quote.get("scene_count") or 1),
                "order": {
                    "session": multiscene_session,
                    "user_id": uid,
                    "chat_id": query.message.chat_id,
                    "video_tier": tier,
                    "total_xu": int(quote.get("total_xu") or 0),
                    "final_invoice_confirmed": True,
                    "charge_xu": True,
                    "bot_client": context.bot,
                },
            },
            {
                "user_id": uid,
                "entry_source": ENGINE_ENTRY_SOURCE_PRODUCT,
                "confirm_paid": True,
                "admin_interactive_confirm": True,
                "is_paid_job": True,
            },
        )
        started = dict(engine_result.get("provider_result") or {})
        if not engine_result.get("ok"):
            return await safe_edit_or_send(
                query,
                engine_result.get("message")
                or (admin_product_engine_missing_text("video_multiscene", (engine_result.get("gate") or {}).get("readiness")) if is_admin_user(uid) else VIDEO_MULTISCENE_PUBLIC_GUARD_TEXT),
                parse_mode="HTML" if is_admin_user(uid) else None,
                reply_markup=video_export_maintenance_keyboard(lang),
            )
        state["multiscene_parent_task_id"] = str(started.get("parent_task_id") or "")
        state["multiscene_started_at"] = now_text()
        set_video_addon_state(uid, state)
        return started
    legacy_order = build_legacy_shopaikey_video_order_from_task3d_session(get_video_session(uid), uid, state)
    token = token or shopaikey_confirmation_token()
    restore_shopaikey_pending_confirmation(token, uid, legacy_order)
    state["pending_confirm_token"] = token
    state["pending_payload"] = legacy_order
    set_video_addon_state(uid, state)
    canonical_callback = f"shopai|confirm|{token}"
    try:
        async def _run_single_video_export():
            return await handle_shopaikey_public_callback(update, context, canonical_callback)
        _single_export_params = {"runner": _run_single_video_export, "action": "export", "state": state}
        _single_export_context = {
            "user_id": uid,
            "entry_source": ENGINE_ENTRY_SOURCE_PRODUCT,
            "confirm_paid": True,
            "admin_interactive_confirm": True,
            "is_paid_job": True,
        }
        # This handler owns the export decision: it has already resolved the
        # confirmation token and rebuilt the order. It hands the engine a real
        # decision object rather than a bare flag, so the engine can tell this
        # apart from any future caller that merely claims to have checked.
        _single_export_context["gate_precheck_result"] = engine_gate_precheck_allow(
            "video_single",
            _single_export_params,
            _single_export_context,
            reason="video export confirm handler owns this decision",
        )
        engine_result = await execute_engine(
            "video_single",
            _single_export_params,
            _single_export_context,
        )
        if not engine_result.get("ok") and not engine_result.get("runner_result"):
            return await safe_edit_or_send(
                query,
                engine_result.get("message")
                or (admin_product_engine_missing_text("video_single", (engine_result.get("gate") or {}).get("readiness")) if is_admin_user(uid) else PUBLIC_PRODUCT_MAINTENANCE_VI),
                parse_mode="HTML" if is_admin_user(uid) else None,
                reply_markup=video_export_maintenance_keyboard(lang),
            )
        return engine_result.get("runner_result")
    except Exception as exc:
        restore_shopaikey_pending_confirmation(token, uid, legacy_order)
        state["pending_confirm_token"] = token
        state["pending_payload"] = legacy_order
        set_video_addon_state(uid, state)
        record_video_last_export_error(exc, uid, str(query.data or ""), state, legacy_order)
        logger.exception("Task3D video export bridge failed | package=%s | product=%s", legacy_order.get("task3d_package_id"), legacy_order.get("product_id"))
        return await safe_edit_or_send(
            query,
            PUBLIC_PRODUCT_MAINTENANCE_VI
            if normalize_user_language(lang) == "vi" else
            PUBLIC_PRODUCT_MAINTENANCE_EN,
            parse_mode=None,
            reply_markup=video_export_maintenance_keyboard(lang),
        )

