def image_menu_pending_key(user_id) -> str:
    return f"image_menu:{user_id}"

def set_image_menu_pending(user_id, action: str, **fields) -> None:
    action = str(action or "").strip()
    if action not in IMAGE_MENU_PENDING_ACTIONS:
        return
    payload = {
        "pending_action": action,
        "created_at_ts": time.time(),
    }
    if fields:
        for key, value in fields.items():
            if key in {"file_id", "file_unique_id"}:
                payload[key] = str(value or "")[:240]
            elif key in {
                "note", "goal", "goal_code", "subject", "style", "style_code", "ratio",
                "edit_type", "edit_request", "resize_task", "resize_ratio", "resize_method",
                "manual_action",
                "upscale_mode",
                "pixel_size", "source_name", "prompt", "current_prompt", "short_prompt",
                "detail_prompt", "negative_prompt", "selected_variant", "ratio_change",
                "prompt_source", "back_to", "last_step", "editor_mode", "editor_preset",
                "editor_text", "editor_source", "editor_overlay_position",
                "editor_overlay_text", "editor_logo_text",
                "image_prompt_current_prompt", "image_prompt_short_prompt",
                "image_prompt_detail_prompt", "image_prompt_negative_prompt",
                "image_prompt_selected_ratio", "image_prompt_selected_purpose",
                "image_prompt_selected_style", "image_prompt_subject",
                "image_prompt_selected_variant",
            }:
                payload[key] = re.sub(r"\s+", " ", str(value or "").strip())[:900]
            elif key in {"variants", "image_prompt_variants"} and isinstance(value, list):
                payload[key] = [re.sub(r"\s+", " ", str(item or "").strip())[:1200] for item in value[:3]]
            elif key == "brightness_percent":
                payload[key] = max(20, min(200, safe_int(value, 100)))
    USER_PENDING[image_menu_pending_key(user_id)] = payload

def get_image_menu_pending(user_id) -> dict | None:
    key = image_menu_pending_key(user_id)
    pending = USER_PENDING.get(key) or {}
    if pending.get("pending_action") not in IMAGE_MENU_PENDING_ACTIONS:
        return None
    age = time.time() - float(pending.get("created_at_ts") or 0)
    if age > QUICK_MEDIA_PENDING_TTL_SECONDS:
        USER_PENDING.pop(key, None)
        return None
    return pending

def clear_image_menu_pending(user_id) -> bool:
    return USER_PENDING.pop(image_menu_pending_key(user_id), None) is not None

