def prepare_telegram_image_delivery(
    image_bytes: bytes,
    *,
    max_bytes: int = 4 * 1024 * 1024,
    max_side: int = 4096,
) -> tuple[bytes, str]:
    """Return an image that satisfies Telegram's sendPhoto size/dimension limits."""
    if not image_bytes:
        raise ValueError("empty_image_output")
    if Image is None:
        return image_bytes, "png"
    with Image.open(io.BytesIO(image_bytes)) as source:
        source.load()
        image = ImageOps.exif_transpose(source) if ImageOps is not None else source.copy()
        image = image.convert("RGB")
        longest = max(image.size)
        if longest > max_side or sum(image.size) > 9000:
            scale = min(max_side / max(1, longest), 9000 / max(1, sum(image.size)))
            image = image.resize(
                (max(1, int(image.width * scale)), max(1, int(image.height * scale))),
                Image.Resampling.LANCZOS,
            )
        for quality in (92, 86, 80, 74, 68):
            output = io.BytesIO()
            image.save(output, format="JPEG", quality=quality, optimize=True, progressive=True)
            payload = output.getvalue()
            if len(payload) <= max_bytes:
                return payload, "jpg"
        image.thumbnail((2560, 2560), Image.Resampling.LANCZOS)
        output = io.BytesIO()
        image.save(output, format="JPEG", quality=72, optimize=True, progressive=True)
        payload = output.getvalue()
        if len(payload) > max_bytes:
            raise ValueError("telegram_image_output_too_large")
        return payload, "jpg"


async def send_local_edited_image(
    update_or_query,
    context: ContextTypes.DEFAULT_TYPE,
    state: dict,
    preset: str = "photo_clear_detail",
    settings: dict | None = None,
    overlay_text: str = "",
    logo_file_id: str = "",
    overlay_position: str = "",
    overlay_kind: str = "",
    upscale: bool = False,
) -> bool:
    message = getattr(update_or_query, "message", None) or getattr(getattr(update_or_query, "callback_query", None), "message", None)
    query = getattr(update_or_query, "callback_query", None)
    user = getattr(update_or_query, "effective_user", None) or getattr(query, "from_user", None)
    uid = getattr(user, "id", 0)
    lang = get_user_language(uid) or "vi"
    _image_copy = public_image_deep_copy(lang)
    file_id = str((state or {}).get("file_id") or "")
    chat_id = message.chat_id if message else query.message.chat_id
    if not file_id:
        await context.bot.send_message(chat_id=chat_id, text=f"⚠️ {_image_copy['no_image']} {public_hub_copy(lang)['common_no_charge']}", reply_markup=image_editor_start_keyboard(lang))
        return True
    overlay_position = normalize_image_editor_overlay_position(
        overlay_position,
        "bottom_right" if logo_file_id else "bottom_center",
    )
    settings_signature = json.dumps(dict(settings or {}), ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    source_id = f"{file_id}:{preset}:{settings_signature}:{overlay_text[:80]}:{logo_file_id}:{overlay_position}:{int(bool(upscale))}"
    if not acquire_image_action_lock(uid, "local_image_editor", source_id, 180):
        await context.bot.send_message(chat_id=chat_id, text=image_action_locked_text(lang))
        return True
    try:
        if query:
            await safe_edit_query_message(query, image_action_waiting_text(lang), parse_mode=None)
        else:
            await message.reply_text(image_action_waiting_text(lang))
        try:
            image_bytes = await telegram_photo_file_bytes(context, file_id)
            logo_bytes = await telegram_photo_file_bytes(context, logo_file_id) if logo_file_id else b""
            ok, output_bytes, size_text, preset_used = await asyncio.to_thread(
                process_image_local_editor_bytes,
                image_bytes,
                preset,
                settings,
                overlay_text,
                logo_bytes,
                overlay_position,
                upscale,
            )
            if not ok:
                raise RuntimeError(size_text)
            delivery_bytes, delivery_extension = await asyncio.to_thread(
                prepare_telegram_image_delivery,
                output_bytes,
            )
        except Exception as exc:
            logger.warning("local image editor processing failed | %s", sanitize_log_text(str(exc))[:220])
            await context.bot.send_message(
                chat_id=chat_id,
                text=f"⚠️ {_image_copy['resize_error']} {public_hub_copy(lang)['common_no_charge']}",
                reply_markup=image_editor_start_keyboard(lang),
            )
            return True
        brightness_percent = max(20, min(200, int(round(float((settings or {}).get("brightness", 1.0)) * 100))))
        brightness_line = f"{_image_copy['brightness_title']}: <b>{brightness_percent}%</b>\n" if settings and "brightness" in settings else ""
        caption = (
            f"✅ <b>{_image_copy['image_received']}</b>\n\n"
            f"{_image_copy['style']}: <b>{html.escape(image_editor_preset_label('upscale_basic' if upscale else ('logo_overlay' if logo_file_id or str(overlay_kind or '').lower() == 'logo' else ('text_overlay' if overlay_text else preset_used)), lang))}</b>\n"
            f"{brightness_line}"
            f"{_image_copy['ratio']}: <code>{html.escape(size_text)}</code>\n\n"
            f"{public_hub_copy(lang)['common_no_charge']}"
        )
        sent = None
        try:
            photo = io.BytesIO(delivery_bytes)
            photo.name = f"toan_aas_editor_{uid}_{int(time.time())}.{delivery_extension}"
            sent = await context.bot.send_photo(
                chat_id=chat_id,
                photo=photo,
                caption=caption,
                parse_mode="HTML",
                reply_markup=image_editor_result_keyboard(lang),
                read_timeout=60,
                write_timeout=60,
                connect_timeout=30,
                pool_timeout=30,
            )
        except Exception as photo_exc:
            logger.warning("local image preview send_photo failed; trying document | %s", sanitize_log_text(str(photo_exc))[:220])
            try:
                document = io.BytesIO(delivery_bytes)
                document.name = f"toan_aas_editor_{uid}_{int(time.time())}.{delivery_extension}"
                sent = await context.bot.send_document(
                    chat_id=chat_id,
                    document=document,
                    caption=caption,
                    parse_mode="HTML",
                    reply_markup=image_editor_result_keyboard(lang),
                    read_timeout=60,
                    write_timeout=60,
                    connect_timeout=30,
                    pool_timeout=30,
                )
            except Exception as document_exc:
                logger.warning("local image preview delivery failed | %s", sanitize_log_text(str(document_exc))[:220])
                await context.bot.send_message(
                    chat_id=chat_id,
                    text=f"⚠️ {_image_copy['resize_error']} {public_hub_copy(lang)['common_no_charge']}",
                    reply_markup=image_editor_result_keyboard(lang),
                )
                return True
        output_file_id = (
            sent.photo[-1].file_id
            if getattr(sent, "photo", None)
            else getattr(getattr(sent, "document", None), "file_id", "") or file_id
        )
        try:
            save_image_tool_result(uid, "editor", {
                "file_id": output_file_id,
                "source_file_id": file_id,
                "preset": preset_used,
                "size": size_text,
                "overlay_text": overlay_text[:260],
                "overlay_position": overlay_position,
                "brightness_percent": brightness_percent,
            })
            set_image_menu_pending(
                uid,
                "image_editor_menu",
                file_id=output_file_id,
                source_name=f"edited_image.{delivery_extension}",
                editor_mode="preset",
                editor_preset=preset_used,
                brightness_percent=brightness_percent,
            )
        except Exception as state_exc:
            logger.warning("local image editor result state save failed after delivery | %s", sanitize_log_text(str(state_exc))[:220])
        return True
    finally:
        release_image_action_lock(uid, "local_image_editor", source_id, cooldown_seconds=5)

