async def telegram_photo_file_bytes(context: ContextTypes.DEFAULT_TYPE, file_id: str) -> bytes:
    tg_file = await context.bot.get_file(file_id)
    payload = b""
    download_as_bytearray = getattr(tg_file, "download_as_bytearray", None)
    if callable(download_as_bytearray):
        payload = bytes(await download_as_bytearray())
    else:
        buffer = io.BytesIO()
        await tg_file.download_to_memory(out=buffer)
        payload = buffer.getvalue()
    if not payload:
        raise ValueError("telegram_image_download_empty")
    if len(payload) > 25 * 1024 * 1024:
        raise ValueError("telegram_image_download_too_large")
    return payload

async def send_local_resized_image(update_or_query, context: ContextTypes.DEFAULT_TYPE, state: dict, ratio: str = "", method: str = "pad", pixel_size: str = "") -> bool:
    message = getattr(update_or_query, "message", None) or getattr(getattr(update_or_query, "callback_query", None), "message", None) or getattr(update_or_query, "message", None)
    query = getattr(update_or_query, "callback_query", None)
    user = getattr(update_or_query, "effective_user", None) or getattr(query, "from_user", None)
    uid = getattr(user, "id", 0)
    lang = get_user_language(uid) or "vi"
    _image_copy = public_image_deep_copy(lang)
    file_id = str((state or {}).get("file_id") or "")
    if not file_id:
        text = f"⚠️ {_image_copy['no_image']} {_image_copy['send_prompt_hint']} {public_hub_copy(lang)['common_no_charge']}"
        if query:
            await safe_edit_query_message(query, text, parse_mode=None, reply_markup=image_resize_start_keyboard(lang))
        elif message:
            await message.reply_text(text, reply_markup=image_resize_start_keyboard(lang))
        return True
    if Image is None:
        text = f"⚠️ {_image_copy['resize_error']} {public_hub_copy(lang)['common_no_charge']}"
        if query:
            await safe_edit_query_message(query, text, parse_mode=None, reply_markup=image_menu_child_keyboard(lang))
        elif message:
            await message.reply_text(text, reply_markup=image_menu_child_keyboard(lang))
        return True
    action_name = "resize_pixels" if pixel_size else "resize_ratio"
    source_id = f"{file_id}:{pixel_size or ratio}:{method}"
    if not acquire_image_action_lock(uid, action_name, source_id, 180):
        await context.bot.send_message(
            chat_id=message.chat_id if message else query.message.chat_id,
            text=image_action_locked_text(lang),
        )
        return True
    try:
        if query:
            await safe_edit_query_message(query, image_action_waiting_text(lang), parse_mode=None)
        elif message:
            await message.reply_text(image_action_waiting_text(lang))
        img_bytes = await telegram_photo_file_bytes(context, file_id)
        ok, out_bytes, size_text, method_used = await asyncio.to_thread(process_image_local_resize_bytes, img_bytes, ratio, method, pixel_size)
        if not ok:
            raise RuntimeError(size_text)
        photo = io.BytesIO(out_bytes)
        photo.name = f"toan_aas_{uid}_{int(time.time())}_{random.getrandbits(24):06x}.png"
        method_label = image_resize_method_label("pixels" if pixel_size else method_used, lang)
        task_label = _image_copy["resize_pixel"] if pixel_size else _image_copy["resize_ratio_title"]
        caption = (
            f"✅ <b>{_image_copy['image_received']}</b>\n\n"
            f"{_image_copy['processing']}: <b>{html.escape(task_label)}</b>\n"
            f"{_image_copy['ratio']}: <code>{html.escape(size_text)}</code>\n"
            f"{_image_copy['choose']}: <b>{html.escape(method_label)}</b>\n\n"
            f"{public_hub_copy(lang)['common_no_charge']}"
        )
        sent_message = await context.bot.send_photo(
            chat_id=message.chat_id if message else query.message.chat_id,
            photo=photo,
            caption=caption,
            parse_mode="HTML",
            reply_markup=image_resize_result_keyboard(lang),
        )
        output_file_id = ""
        if getattr(sent_message, "photo", None):
            output_file_id = sent_message.photo[-1].file_id
        save_image_tool_result(uid, "resize", {
            "file_id": output_file_id or file_id,
            "source_file_id": file_id,
            "ratio": normalize_image_tool_ratio(ratio, "1:1") if not pixel_size else "",
            "pixel_size": size_text if pixel_size else "",
            "method": method_used,
        })
        clear_image_menu_pending(uid)
        return True
    except Exception as e:
        logger.warning("local image resize failed | %s", sanitize_log_text(str(e))[:220])
        text = f"⚠️ {_image_copy['resize_error']}\n{public_hub_copy(lang)['common_no_charge']}"
        if query:
            await safe_edit_query_message(query, text, parse_mode=None, reply_markup=image_menu_child_keyboard(lang))
        elif message:
            await message.reply_text(text, reply_markup=image_menu_child_keyboard(lang))
        return True
    finally:
        release_image_action_lock(uid, action_name, source_id, cooldown_seconds=5)

