def direct_minimax_tts_url() -> str:
    endpoint = str(MINIMAX_DIRECT_TTS_ENDPOINT or MINIMAX_TTS_ENDPOINT or "/t2a_v2").strip()
    if endpoint.startswith("/tts/minimax/"):
        endpoint = "/" + endpoint.rstrip("/").rsplit("/", 1)[-1]
    url = join_shopaikey_url(MINIMAX_DIRECT_BASE_URL, endpoint)
    if "GroupId=" not in url and "group_id=" not in url:
        separator = "&" if "?" in url else "?"
        url = f"{url}{separator}GroupId={quote(str(MINIMAX_GROUP_ID or ''), safe='')}"
    return url

VOICE_TTS_DEFAULT_SPEED = "1.0"
VOICE_TTS_MIN_SPEED = 0.1
VOICE_TTS_MAX_SPEED = 2.0
VOICE_TTS_DEFAULT_VOLUME_PERCENT = 100
VOICE_TTS_MIN_VOLUME_PERCENT = 0
VOICE_TTS_MAX_VOLUME_PERCENT = 200
VOICE_TTS_PRODUCT_MIN_WORDS = 20
VOICE_TTS_PRODUCT_PRICE_PER_WORD_XU = 0.10
VOICE_TTS_PRODUCT_MIN_CHARGE_XU = 1


def parse_voice_tts_speed_input(value: str | int | float) -> str:
    raw = str(value if value is not None else "").strip().lower().replace(",", ".")
    aliases = {
        "": VOICE_TTS_DEFAULT_SPEED,
        "default": VOICE_TTS_DEFAULT_SPEED,
        "normal": VOICE_TTS_DEFAULT_SPEED,
        "slow": "0.85",
        "fast": "1.2",
    }
    raw = aliases.get(raw, raw)
    if raw.endswith("x"):
        raw = raw[:-1].strip()
    try:
        number = float(raw)
    except Exception as exc:
        raise ValueError("invalid_speed") from exc
    if number < VOICE_TTS_MIN_SPEED or number > VOICE_TTS_MAX_SPEED:
        raise ValueError("speed_out_of_range")
    normalized = f"{number:.2f}".rstrip("0").rstrip(".")
    return "1.0" if normalized == "1" else normalized


def parse_voice_tts_volume_input(value: str | int | float) -> int:
    if isinstance(value, float) and not value.is_integer():
        raise ValueError("volume_integer_required")
    raw = str(value if value is not None else "").strip().lower().replace(" ", "")
    if raw.endswith("%"):
        raw = raw[:-1].strip()
    if "." in raw or "," in raw:
        raise ValueError("volume_integer_required")
    if not re.fullmatch(r"\d+", raw or ""):
        raise ValueError("invalid_volume")
    percent = int(raw)
    if percent < VOICE_TTS_MIN_VOLUME_PERCENT or percent > VOICE_TTS_MAX_VOLUME_PERCENT:
        raise ValueError("volume_out_of_range")
    return percent


def voice_tts_speed_value(value: str | int | float | None = None) -> str:
    try:
        return parse_voice_tts_speed_input(VOICE_TTS_DEFAULT_SPEED if value is None else value)
    except Exception:
        return VOICE_TTS_DEFAULT_SPEED


def voice_tts_volume_percent(value: str | int | float | None = None) -> int:
    try:
        return parse_voice_tts_volume_input(VOICE_TTS_DEFAULT_VOLUME_PERCENT if value is None else value)
    except Exception:
        return VOICE_TTS_DEFAULT_VOLUME_PERCENT


def voice_tts_effective_volume_factor(volume_percent: str | int | float | None = None) -> float:
    percent = voice_tts_volume_percent(volume_percent)
    return round(2.0 * float(percent) / 100.0, 3)


def voice_tts_provider_speed(value: str | int | float | None = None) -> float:
    return float(parse_voice_tts_speed_input(VOICE_TTS_DEFAULT_SPEED if value is None else value))


def voice_tts_edge_rate(value: str | int | float | None = None) -> str:
    speed = voice_tts_provider_speed(value)
    percent = int(round((speed - 1.0) * 100))
    return f"{percent:+d}%"


def voice_tts_word_count(text: str) -> int:
    return len(re.findall(r"[0-9A-Za-zÀ-ỹĐđ]+", str(text or ""), flags=re.UNICODE))


def voice_tts_product_quote(text: str) -> dict:
    words = voice_tts_word_count(text)
    price_per_word = float(canonical_price_xu("voice_tts_basic") or VOICE_TTS_PRODUCT_PRICE_PER_WORD_XU or 0.10)
    raw_price = round(float(words) * price_per_word, 3)
    discount_percent = finance_volume_discount_percent(words)
    discount_xu = raw_price * discount_percent / 100.0
    discounted_price = raw_price - discount_xu
    total = 0
    if words > 0:
        total = max(int(VOICE_TTS_PRODUCT_MIN_CHARGE_XU or 1), int(math.ceil(discounted_price)))
    return {
        "word_count": words,
        "price_per_word_xu": price_per_word,
        "raw_price_xu": raw_price,
        "discount_percent": finance_discount_cap_percent(discount_percent),
        "discount_xu": discount_xu,
        "discount_cap_percent": int(VOLUME_DISCOUNT_CAP_PERCENT),
        "total_xu": total,
        "rounded": bool(total != discounted_price),
        "min_words": int(VOICE_TTS_PRODUCT_MIN_WORDS),
    }


def voice_tts_product_quote_for_source(text: str, source: str = "") -> dict:
    quote = dict(voice_tts_product_quote(text))
    if str(source or "").strip().lower() == "default":
        quote.update({
            "price_per_word_xu": 0.0,
            "raw_price_xu": 0.0,
            "total_xu": 0,
            "rounded": False,
            "free_default": True,
        })
    return quote


def voice_tts_product_text_too_short(text: str) -> bool:
    return voice_tts_word_count(text) < int(VOICE_TTS_PRODUCT_MIN_WORDS)


def voice_tts_min_words_text(lang: str = "vi") -> str:
    if music_ui_lang(lang=lang) != "vi":
        return "Content needs at least 20 words to create audio. Please add more content and try again."
    return "Nội dung cần ít nhất 20 từ để tạo audio. Anh/chị hãy nhập thêm nội dung rồi thử lại."


def voice_tts_format_xu(value: int | float) -> str:
    number = float(value or 0)
    return f"{number:.2f}".rstrip("0").rstrip(".")


