def extract_shopaikey_suno_task_id(payload) -> str:
    if isinstance(payload, str):
        return payload.strip()
    if not isinstance(payload, dict):
        return ""
    data = payload.get("data")
    if isinstance(data, str):
        return data.strip()
    candidates: list[str] = []

    def visit(value):
        if isinstance(value, dict):
            for key in ("task_id", "taskId", "taskID", "id"):
                raw = value.get(key)
                if isinstance(raw, (str, int)) and str(raw).strip():
                    candidates.append(str(raw).strip())
            for child in ("data", "result", "task", "job"):
                if child in value:
                    visit(value.get(child))
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    return candidates[0] if candidates else ""

def _shopaikey_suno_status_raw(payload) -> str:
    values: list[str] = []

    def visit(value):
        if isinstance(value, dict):
            for key in ("status", "state", "task_status", "taskStatus"):
                raw = value.get(key)
                if isinstance(raw, str) and raw.strip():
                    values.append(raw.strip())
            for child in ("data", "result", "task", "job"):
                if child in value:
                    visit(value.get(child))
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    if values:
        return values[0]
    if isinstance(payload, dict):
        code = str(payload.get("code") or "").strip()
        if code:
            return code
    return ""

SUNO_AUDIO_EXTENSIONS = (".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac")
MUSIC_RESULT_SIGNATURE_QUERY_KEYS = {
    "token", "signature", "sig", "expires", "expires_in", "expiresat",
    "x-amz-algorithm", "x-amz-credential", "x-amz-date", "x-amz-expires",
    "x-amz-signature", "x-amz-security-token", "policy", "key-pair-id",
}
MUSIC_PROVIDER_AUDIO_URL_KEYS = {
    "audio_url", "audiourl", "source_audio_url", "sourceaudiourl",
    "stream_audio_url", "streamaudiourl", "download_url", "downloadurl",
    "stream_url", "streamurl", "file_url", "fileurl", "result_url", "resulturl", "url",
    "signed_url", "signedurl",
    "mp3_url", "mp3url", "song_url", "songurl", "cdn_url", "cdnurl",
    "media_url", "mediaurl", "proxy_url", "proxyurl",
    "provider_download_url", "providerdownloadurl", "output_url", "outputurl",
    "play_url", "playurl", "preview_url", "previewurl", "audio",
}

def music_url_query_metadata(url: str = "") -> dict:
    raw = str(url or "").strip()
    try:
        parsed = urlparse(raw)
        query = str(parsed.query or "")
        parts = parse_qsl(query, keep_blank_values=True)
    except Exception:
        query = raw.split("?", 1)[1].split("#", 1)[0] if "?" in raw else ""
        parts = []
    lowered_keys = {str(key or "").strip().lower() for key, _value in parts}
    signature_present = any(
        key in MUSIC_RESULT_SIGNATURE_QUERY_KEYS or key.startswith("x-amz-")
        for key in lowered_keys
    )
    return {
        "query_present": bool(query),
        "query_param_count": len(parts) if parts else (query.count("&") + 1 if query else 0),
        "signature_param_present": bool(signature_present),
    }

def music_url_host_extension(url: str = "") -> tuple[str, str]:
    try:
        parsed = urlparse(str(url or "").strip())
        host = str(parsed.netloc or "").lower()
        extension = os.path.splitext(str(parsed.path or "").lower())[1]
        return host, extension
    except Exception:
        clean = str(url or "").split("?", 1)[0].lower()
        return "", os.path.splitext(clean)[1]

def music_url_is_bare_suno_cdn(url: str = "") -> bool:
    raw = str(url or "").strip()
    if not raw.startswith(("http://", "https://")):
        return False
    try:
        parsed = urlparse(raw)
        host = str(parsed.netloc or "").lower()
        path = str(parsed.path or "").lower()
        return bool(
            (host == "suno.ai" or host.endswith(".suno.ai"))
            and path.endswith(SUNO_AUDIO_EXTENSIONS)
            and not str(parsed.query or "").strip()
        )
    except Exception:
        lowered = raw.lower()
        return bool("suno.ai" in lowered and lowered.split("?", 1)[0].endswith(SUNO_AUDIO_EXTENSIONS) and "?" not in raw)

def music_provider_candidate_selected_reason(candidate: dict | None = None) -> str:
    item = dict(candidate or {})
    path = str(item.get("field_path") or item.get("source") or "").lower().replace(".", "_")
    if item.get("rejected"):
        return f"rejected:{item.get('reject_reason') or 'not_downloadable'}"
    if item.get("signature_param_present"):
        return "signed_url_candidate"
    if item.get("has_query"):
        return "query_url_candidate"
    if "cld2audiourl" in path:
        return "cld2_audio_url_candidate"
    if music_url_is_bare_suno_cdn(str(item.get("url") or "")):
        return "direct_suno_cdn_candidate"
    if "provider_download_url" in path:
        return "provider_download_url_candidate"
    if "download_url" in path:
        return "download_url_candidate"
    if "signed_url" in path:
        return "signed_url_candidate"
    if "file_url" in path:
        return "file_url_candidate"
    if "source_audio_url" in path:
        return "source_audio_url_candidate"
    if "stream_audio_url" in path or "stream_url" in path:
        return "stream_audio_url_candidate"
    if "audio_url" in path or path.endswith("_audio") or path == "audio":
        return "audio_url_candidate"
    if "music_output_url" in path:
        return "music_output_url_candidate"
    return "ranked_provider_candidate"

def music_provider_url_reject_reason(field_path: str = "", url: str = "") -> str:
    path = str(field_path or "").lower()
    raw = str(url or "").strip()
    if not raw.startswith(("http://", "https://")):
        return "invalid_url"
    _host, extension = music_url_host_extension(raw)
    clean_url = raw.lower().split("?", 1)[0]
    if extension in {".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp", ".svg"}:
        return "image_url"
    if any(token in path for token in ("thumbnail", "thumb", "image", "cover", "artwork", "poster")):
        return "image_url"
    if extension in {".json", ".xml", ".txt", ".srt", ".vtt", ".lrc"}:
        return "metadata_url"
    if any(token in path for token in ("lyrics", "lyric", "caption", "subtitle", "transcript", "metadata", "json")):
        if not clean_url.endswith(SUNO_AUDIO_EXTENSIONS):
            return "metadata_url"
    return ""

def music_rejected_candidate_reason_label(reason: str = "") -> str:
    value = str(reason or "").strip()
    if value == "bare_suno_cdn_no_query":
        return "rejected_bare_suno_cdn_no_query"
    return value

def music_provider_candidate_priority(candidate: dict | None = None) -> int:
    item = dict(candidate or {})
    if item.get("rejected"):
        return -10000
    path = str(item.get("field_path") or item.get("source") or "").lower().replace(".", "_")
    url = str(item.get("url") or "")
    _host, extension = music_url_host_extension(url)
    score = 0
    if "provider_download_url" in path:
        score += 1200
    if "cld2audiourl" in path or (music_url_is_bare_suno_cdn(url) and extension in SUNO_AUDIO_EXTENSIONS):
        score += 1450
    if "download_url" in path and "provider_download_url" not in path:
        score += 1100
    if "signed_url" in path:
        score += 1080
    if "file_url" in path:
        score += 1050
    if "source_audio_url" in path:
        score += 950
    if "stream_audio_url" in path or "stream_url" in path:
        score += 920
    if "audio_url" in path or path.endswith("_audio") or path == "audio":
        score += 900
    if "result_url" in path:
        score += 800
    if "proxy_url" in path:
        score += 760
    if "cdn_url" in path or "mp3_url" in path or "media_url" in path or "song_url" in path:
        score += 650
    if extension in SUNO_AUDIO_EXTENSIONS:
        score += 120
    if item.get("signature_param_present"):
        score += 500
    elif item.get("has_query"):
        score += 220
    if item.get("likely_stream_only"):
        score -= 260
    if "preview" in path:
        score -= 500
    if "play_url" in path or path.endswith("_play"):
        score -= 220
    return score

def extract_shopaikey_suno_audio_candidates(payload, *, provider_name: str = "") -> list[dict]:
    candidates: list[dict] = []
    seen: set[tuple[str, str]] = set()

    def add_candidate(field_path: str, raw):
        if not isinstance(raw, str):
            return
        url = raw.strip()
        if not url.startswith(("http://", "https://")):
            return
        compact_key = re.sub(r"[^a-z0-9]", "", str(field_path or "").split(".")[-1].lower())
        clean_url = url.lower().split("?", 1)[0]
        key_supports_audio = compact_key in MUSIC_PROVIDER_AUDIO_URL_KEYS or "audio" in compact_key
        url_supports_audio = clean_url.endswith(SUNO_AUDIO_EXTENSIONS) or "/audio" in clean_url or "suno" in clean_url
        if not (key_supports_audio or url_supports_audio):
            return
        dedupe = (field_path, url)
        if dedupe in seen:
            return
        seen.add(dedupe)
        host, extension = music_url_host_extension(url)
        meta = music_url_query_metadata(url)
        lowered_path = str(field_path or "").lower()
        reject_reason = music_provider_url_reject_reason(field_path, url)
        likely_stream = any(token in lowered_path for token in ("preview", "stream", "play"))
        requires_auth = any(token in host for token in ("shopaikey", "key4u")) or "proxy" in lowered_path
        item = {
            "field_path": field_path,
            "source": field_path,
            "role": "provider_result_metadata",
            "url": url,
            "url_host": host,
            "extension": extension,
            "has_query": bool(meta.get("query_present")),
            "query_param_count": int(meta.get("query_param_count") or 0),
            "signature_param_present": bool(meta.get("signature_param_present")),
            "likely_direct_download": bool(extension in SUNO_AUDIO_EXTENSIONS and not likely_stream),
            "likely_stream_only": bool(likely_stream),
            "requires_auth": bool(requires_auth),
            "provider_name": str(provider_name or ""),
            "last_http_status": 0,
            "rejected": bool(reject_reason),
            "reject_reason": reject_reason,
            "rejected_reason": reject_reason,
            "safe_label": music_result_url_debug_label(url),
        }
        item["rank"] = music_provider_candidate_priority(item)
        item["selected_reason"] = music_provider_candidate_selected_reason(item)
        candidates.append(item)

    def visit(value, path: str = ""):
        if isinstance(value, dict):
            for key, child in value.items():
                key_text = str(key or "")
                child_path = f"{path}.{key_text}" if path else key_text
                add_candidate(child_path, child)
                visit(child, child_path)
        elif isinstance(value, list):
            for index, item in enumerate(value):
                visit(item, f"{path}[{index}]" if path else f"[{index}]")

    visit(payload)
    return sorted(candidates, key=music_provider_candidate_priority, reverse=True)

def music_provider_audio_candidate_records(candidates: list[dict] | None = None) -> list[dict]:
    records: list[dict] = []
    for item in candidates or []:
        current = dict(item or {})
        records.append({
            "field_path": str(current.get("field_path") or ""),
            "source": str(current.get("source") or current.get("field_path") or ""),
            "role": str(current.get("role") or "provider_result_metadata"),
            "url": str(current.get("url") or ""),
            "url_label": str(current.get("safe_label") or music_result_url_debug_label(current.get("url") or "")),
            "url_host": str(current.get("url_host") or ""),
            "extension": str(current.get("extension") or ""),
            "has_query": bool(current.get("has_query")),
            "query_param_count": int(current.get("query_param_count") or 0),
            "signature_param_present": bool(current.get("signature_param_present")),
            "likely_direct_download": bool(current.get("likely_direct_download")),
            "likely_stream_only": bool(current.get("likely_stream_only")),
            "requires_auth": bool(current.get("requires_auth")),
            "provider_name": str(current.get("provider_name") or ""),
            "last_http_status": int(current.get("last_http_status") or 0),
            "rejected": bool(current.get("rejected")),
            "reject_reason": str(current.get("reject_reason") or ""),
            "rejected_reason": str(current.get("rejected_reason") or current.get("reject_reason") or ""),
            "rejected_candidate_reason": music_rejected_candidate_reason_label(current.get("reject_reason") or current.get("rejected_reason") or ""),
            "selected_reason": str(current.get("selected_reason") or music_provider_candidate_selected_reason(current)),
            "rank": int(current.get("rank") or music_provider_candidate_priority(current)),
        })
    return records

def music_result_field_path_value(payload, field_path: str = ""):
    path = str(field_path or "").strip()
    if not path:
        return None
    current = payload
    tokens = re.findall(r"([^\.\[\]]+)|\[(\d+)\]", path)
    for key, index in tokens:
        if key:
            if not isinstance(current, dict):
                return None
            current = current.get(key)
        else:
            if not isinstance(current, list):
                return None
            idx = int(index or 0)
            if idx < 0 or idx >= len(current):
                return None
            current = current[idx]
    return current

def music_provider_candidate_from_url(field_path: str, url: str, *, provider_name: str = "", source: str = "") -> dict:
    raw = str(url or "").strip()
    host, extension = music_url_host_extension(raw)
    meta = music_url_query_metadata(raw)
    reject_reason = music_provider_url_reject_reason(field_path, raw)
    item = {
        "field_path": str(field_path or source or "provider_result_override"),
        "source": str(source or field_path or "provider_result_override"),
        "role": "provider_result_metadata",
        "url": raw,
        "url_host": host,
        "extension": extension,
        "has_query": bool(meta.get("query_present")),
        "query_param_count": int(meta.get("query_param_count") or 0),
        "signature_param_present": bool(meta.get("signature_param_present")),
        "likely_direct_download": bool(extension in SUNO_AUDIO_EXTENSIONS),
        "likely_stream_only": bool("stream" in str(field_path or "").lower() or "preview" in str(field_path or "").lower()),
        "requires_auth": bool(any(token in host for token in ("shopaikey", "key4u")) or "proxy" in str(field_path or "").lower()),
        "provider_name": str(provider_name or ""),
        "last_http_status": 0,
        "rejected": bool(reject_reason),
        "reject_reason": reject_reason,
        "rejected_reason": reject_reason,
        "safe_label": music_result_url_debug_label(raw),
    }
    item["rank"] = music_provider_candidate_priority(item)
    item["selected_reason"] = music_provider_candidate_selected_reason(item)
    return item

def music_provider_candidate_paths_safe(candidates: list[dict] | None = None, *, limit: int = 12) -> list[str]:
    rows: list[str] = []
    for item in candidates or []:
        current = dict(item or {})
        field_path = str(current.get("field_path") or current.get("source") or "-")
        label = str(current.get("safe_label") or current.get("url_label") or music_result_url_debug_label(current.get("url") or ""))
        host = str(current.get("url_host") or music_url_host_extension(current.get("url") or "")[0] or "-")
        extension = str(current.get("extension") or music_url_host_extension(current.get("url") or "")[1] or "-")
        query = "query" if current.get("has_query") else "no-query"
        reason = str(current.get("reject_reason") or current.get("selected_reason") or "")
        safe_reason = music_rejected_candidate_reason_label(reason) if current.get("rejected") else reason
        rows.append(f"{field_path}|{label}|{host}|{extension}|{query}|{safe_reason or 'ranked'}")
        if len(rows) >= max(1, int(limit or 12)):
            break
    return rows

def music_provider_candidate_paths_text(candidates: list[dict] | None = None, *, limit: int = 8) -> str:
    return "; ".join(music_provider_candidate_paths_safe(candidates, limit=limit))

def music_provider_rejected_candidate_reasons(candidates: list[dict] | None = None) -> list[str]:
    reasons: list[str] = []
    for item in candidates or []:
        current = dict(item or {})
        if not current.get("rejected"):
            continue
        field_path = str(current.get("field_path") or current.get("source") or "candidate")
        reason = music_rejected_candidate_reason_label(current.get("reject_reason") or current.get("rejected_reason") or "rejected")
        label = str(current.get("safe_label") or current.get("url_label") or music_result_url_debug_label(current.get("url") or ""))
        text = f"{field_path}:{reason}:{label}"
        if text not in reasons:
            reasons.append(text)
    return reasons

def music_bare_suno_output_reject_reason(candidates: list[dict] | None = None) -> str:
    for item in candidates or []:
        current = dict(item or {})
        if str(current.get("reject_reason") or "") == "bare_suno_cdn_no_query":
            return "rejected_bare_suno_cdn_no_query"
    return ""

def music_provider_downloadable_candidates(candidates: list[dict] | None = None) -> list[dict]:
    return [dict(item or {}) for item in (candidates or []) if not dict(item or {}).get("rejected")]

def music_key4u_suno_download_candidate(provider_task_id: str = "", *, raw_url: str = "") -> dict:
    task_id = str(provider_task_id or "").strip()
    endpoint = key4u_suno_provider_download_final_url(task_id, raw_url=raw_url)
    if not task_id or not endpoint:
        return {}
    candidate = music_provider_candidate_from_url(
        "provider_download_url",
        endpoint,
        provider_name="key4u_suno",
        source="KEY4U_SUNO_DOWNLOAD_URL",
    )
    candidate.update({
        "requires_auth": True,
        "provider_download_endpoint_candidate": True,
        "provider_download_endpoint_configured": True,
        "raw_result_url": str(raw_url or "").strip(),
        "selected_reason": "provider_download_url_candidate",
        "rank": max(int(candidate.get("rank") or 0), 1400),
    })
    return candidate

def music_first_bare_suno_cdn_url(candidates: list[dict] | None = None) -> str:
    for item in candidates or []:
        current = dict(item or {})
        url = str(current.get("url") or "").strip()
        if url and music_url_is_bare_suno_cdn(url):
            return url
    return ""

def music_key4u_candidates_with_download_endpoint(candidates: list[dict] | None = None, provider_task_id: str = "") -> list[dict]:
    items = [dict(item or {}) for item in (candidates or [])]
    if select_music_provider_audio_candidate(items):
        return items
    bare_url = music_first_bare_suno_cdn_url(items)
    endpoint_candidate = music_key4u_suno_download_candidate(provider_task_id, raw_url=bare_url)
    if endpoint_candidate:
        items.append(endpoint_candidate)
        return sorted(items, key=music_provider_candidate_priority, reverse=True)
    return items

def select_music_provider_audio_candidate(candidates: list[dict] | None = None) -> dict:
    valid = music_provider_downloadable_candidates(candidates)
    if not valid:
        return {}
    return max(valid, key=music_provider_candidate_priority)

def extract_shopaikey_suno_audio_urls(payload) -> list[str]:
    urls: list[str] = []
    for item in extract_shopaikey_suno_audio_candidates(payload):
        if item.get("rejected"):
            continue
        url = str(item.get("url") or "").strip()
        if url and url not in urls:
            urls.append(url)
    return urls

SUNO_RESULT_FIELD_KEYS = (
    "status", "state", "result", "output",
    "audio_url", "url", "file_url", "download_url", "stream_url",
    "stream_audio_url", "source_audio_url", "signed_url", "music_output_url",
)
def suno_response_parsed_fields(payload) -> dict:
    fields = {key: False for key in SUNO_RESULT_FIELD_KEYS}

    def visit(value):
        if isinstance(value, dict):
            for key, child in value.items():
                lowered = str(key or "").strip().lower()
                for field in fields:
                    if lowered == field:
                        fields[field] = True
                visit(child)
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    return fields

def suno_result_parsed_fields(result: dict | None) -> dict:
    current = dict(result or {})
    fields = current.get("parsed_fields")
    if isinstance(fields, dict):
        return {key: bool(fields.get(key)) for key in SUNO_RESULT_FIELD_KEYS}
    debug = current.get("raw_debug_admin_only")
    if isinstance(debug, dict):
        nested = debug.get("parsed_fields")
        if isinstance(nested, dict):
            return {key: bool(nested.get(key)) for key in SUNO_RESULT_FIELD_KEYS}
    return {key: False for key in SUNO_RESULT_FIELD_KEYS}

def suno_parsed_fields_text(fields: dict | None) -> str:
    current = {key: bool((fields or {}).get(key)) for key in SUNO_RESULT_FIELD_KEYS}
    return ", ".join(f"{key}={'yes' if current.get(key) else 'no'}" for key in SUNO_RESULT_FIELD_KEYS)

def music_audio_url_has_acceptable_extension(url: str) -> bool:
    try:
        path = urlparse(str(url or "")).path.lower()
    except Exception:
        path = str(url or "").split("?", 1)[0].lower()
    return path.endswith(SUNO_AUDIO_EXTENSIONS) or "/audio" in path

def music_audio_payload_looks_like_error_page(audio_bytes: bytes | bytearray | None = None) -> str:
    head = bytes(audio_bytes or b"")[:256].lstrip().lower()
    if not head:
        return "empty"
    if head.startswith((b"<!doctype html", b"<html", b"<head", b"<body")) or b"<html" in head[:120]:
        return "html_error_page"
    if head.startswith((b"{", b"[")) and any(token in head[:160] for token in (b"error", b"message", b"status", b"code")):
        return "json_error_page"
    return ""

def music_download_detail_field(detail: str = "", field: str = "") -> str:
    wanted = re.escape(str(field or "").strip())
    if not wanted:
        return ""
    match = re.search(rf"(?:^|;\s*){wanted}=([^;]*)", str(detail or ""), flags=re.IGNORECASE)
    return str(match.group(1) if match else "").strip()

def music_download_error_body_class(body_text: str = "", content_type: str = "") -> str:
    text = str(body_text or "").strip()
    lowered = text.lower()
    ctype = str(content_type or "").lower()
    if not text:
        return ""
    if "signaturedoesnotmatch" in lowered or "signature does not match" in lowered:
        return "SignatureDoesNotMatch"
    if "expiredtoken" in lowered or "requestexpired" in lowered or "request has expired" in lowered:
        return "ExpiredToken"
    if "accessdenied" in lowered or "access denied" in lowered:
        return "AccessDenied"
    if "nosuchkey" in lowered or "no such key" in lowered:
        return "NoSuchKey"
    if "login" in lowered or "captcha" in lowered or "challenge" in lowered:
        return "HtmlLoginOrChallenge"
    if ctype.startswith("application/json") or lowered.startswith(("{", "[")):
        return "JsonError"
    if ctype.startswith(("text/html", "application/xhtml")) or lowered.startswith(("<!doctype html", "<html")):
        return "HtmlError"
    if ctype.startswith(("application/xml", "text/xml")) or lowered.startswith("<?xml"):
        return "XmlError"
    return ""

def music_download_error_category(detail: str = "", http_status: int = 0) -> str:
    status = int(http_status or 0)
    lowered = str(detail or "").strip().lower()
    body_class = music_download_detail_field(detail, "error_body_class").lower()
    if music_key4u_suno_wav_pending_detail(detail):
        return MUSIC_ARTIFACT_NOT_READY_BLOCKER
    if KEY4U_SUNO_BARE_CDN_SETUP_BLOCKER in lowered:
        return KEY4U_SUNO_BARE_CDN_SETUP_BLOCKER
    if KEY4U_SUNO_WAV_RESULT_BLOCKER in lowered:
        return KEY4U_SUNO_WAV_RESULT_BLOCKER
    if KEY4U_SUNO_CLIP_ID_MISSING_BLOCKER in lowered:
        return KEY4U_SUNO_CLIP_ID_MISSING_BLOCKER
    if KEY4U_SUNO_WAV_CLIP_ID_REJECTED_BLOCKER in lowered:
        return KEY4U_SUNO_WAV_CLIP_ID_REJECTED_BLOCKER
    if KEY4U_SUNO_WAV_JSON_OBJECT_BLOCKER in lowered:
        return KEY4U_SUNO_WAV_JSON_OBJECT_BLOCKER
    if status == 401:
        return "provider_auth_required"
    if status == 403:
        if body_class == "signaturedoesnotmatch":
            return "result_url_signature_lost_or_invalid"
        if body_class in {"expiredtoken", "requestexpired"}:
            return "result_url_expired"
        if body_class == "accessdenied":
            return "result_url_forbidden_access_denied"
        if "accessdenied" in lowered or "access denied" in lowered:
            return "result_url_forbidden_access_denied"
        if "signaturedoesnotmatch" in lowered or "signature does not match" in lowered:
            return "result_url_signature_lost_or_invalid"
        if "expiredtoken" in lowered or "requestexpired" in lowered:
            return "result_url_expired"
        if "bearer" in lowered or "token=" in lowered:
            return "download_http_failed"
        return "result_url_expired"
    if status in {404, 410}:
        return "provider_result_missing_or_expired" if status == 404 else "result_url_expired"
    if body_class == "nosuchkey":
        return "result_url_missing"
    if body_class == "htmlloginorchallenge":
        return "provider_download_blocked"
    if body_class == "jsonerror":
        return "provider_download_error"
    if "html_error_page" in lowered:
        return "html_error_page"
    if "json_error_page" in lowered:
        return "json_error_page"
    if "invalid_content_type" in lowered or "audio_mime_or_extension_missing" in lowered:
        return "invalid_content_type"
    if "zero" in lowered or "empty" in lowered:
        return "artifact_zero_bytes"
    if status >= 400:
        return "download_http_failed"
    return "download_failed" if lowered else ""

async def _download_music_audio_url_bytes(url: str, timeout_seconds: float = 60.0, headers: dict | None = None) -> tuple[bytes, str, int]:
    if headers:
        audio_bytes, detail, http_status = await _download_audio_url_bytes(url, timeout_seconds=timeout_seconds, headers=headers)
    else:
        audio_bytes, detail, http_status = await _download_audio_url_bytes(url, timeout_seconds=timeout_seconds)
    if not audio_bytes:
        return b"", detail, http_status
    detail_text = str(detail or "")
    content_type = music_download_detail_field(detail_text, "content_type").lower()
    payload_error = music_audio_payload_looks_like_error_page(audio_bytes)
    if payload_error:
        return b"", f"{payload_error}; downloaded_bytes={len(audio_bytes)}; {sanitize_provider_status_text(detail_text, '', 180)}", http_status
    if content_type.startswith(("text/html", "application/json", "text/plain")):
        return b"", f"invalid_content_type; downloaded_bytes={len(audio_bytes)}; {sanitize_provider_status_text(detail_text, '', 180)}", http_status
    if (
        content_type.startswith("audio/")
        or content_type in {"application/octet-stream", "binary/octet-stream", "application/x-mpegurl", ""}
        or music_audio_url_has_acceptable_extension(url)
        or "content_type=audio/" in detail_text.lower()
    ):
        return audio_bytes, detail, http_status
    return b"", f"audio_mime_or_extension_missing; downloaded_bytes={len(audio_bytes)}; {sanitize_provider_status_text(detail_text, '', 180)}", http_status

def tool_test_result_audio_bytes_positive(result: dict | None) -> bool:
    current = dict(result or {})
    try:
        if int(current.get("output_bytes") or 0) > 0:
            return True
    except Exception:
        pass
    detail = str(current.get("detail") or current.get("message") or "")
    matches = re.findall(r"\bbytes=(\d+)\b", detail)
    return any(int(item or 0) > 0 for item in matches)

def extract_shopaikey_suno_media_presence(payload) -> dict:
    presence = {"audio": False, "video": False, "image": False}

    def visit(value):
        if isinstance(value, dict):
            for key, child in value.items():
                lowered_key = str(key or "").lower()
                raw = str(child or "").strip() if isinstance(child, str) else ""
                if raw.startswith(("http://", "https://")):
                    lowered_url = raw.lower().split("?", 1)[0]
                    if "audio" in lowered_key or lowered_url.endswith((".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac")):
                        presence["audio"] = True
                    if "video" in lowered_key or lowered_url.endswith((".mp4", ".mov", ".webm", ".mkv")):
                        presence["video"] = True
                    if "image" in lowered_key or lowered_url.endswith((".jpg", ".jpeg", ".png", ".webp")):
                        presence["image"] = True
                visit(child)
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    if extract_shopaikey_suno_audio_urls(payload):
        presence["audio"] = True
    return presence

def normalize_shopaikey_suno_fetch_status(payload, http_status: int = 0) -> str:
    raw = _shopaikey_suno_status_raw(payload).strip()
    lowered = raw.lower()
    has_audio = bool(extract_shopaikey_suno_audio_urls(payload))
    if has_audio and lowered in {"", "success", "ok", "complete", "completed", "succeeded", "done", "finish", "finished"}:
        return "SUCCESS"
    if lowered in {"success", "ok", "complete", "completed", "succeeded", "done", "finish", "finished"}:
        return "COMPLETED_NO_AUDIO"
    if lowered in {"submitted", "queued", "queue", "pending", "processing", "running", "in_progress", "generating"}:
        return "PROCESSING"
    if lowered in {"fail", "failed", "error", "cancelled", "canceled", "timeout"}:
        return "FAILED"
    if http_status and int(http_status or 0) >= 400:
        return classify_provider_error(http_status, "FAIL_PROVIDER_ERROR", raw)
    return raw.upper() if raw else ("SUCCESS" if has_audio else "PROCESSING")

async def resolve_shopaikey_tts_audio_bytes(payload) -> tuple[bytes, str, int]:
    for candidate in _minimax_audio_candidates(payload):
        if candidate.startswith(("http://", "https://")):
            audio_bytes, detail, http_status = await _download_audio_url_bytes(candidate, timeout_seconds=float(SHOPAIKEY_TTS_TIMEOUT_SECONDS or 60))
            if audio_bytes:
                return audio_bytes, f"audio_url=yes; {detail}", int(http_status or 0)
            continue
        audio_bytes, encoding = _decode_minimax_audio_string(candidate)
        if audio_bytes:
            return audio_bytes, f"bytes={len(audio_bytes)}; encoding={encoding}", 0
    return b"", "no_audio", 0

async def _download_audio_url_bytes(url: str, timeout_seconds: float = 60.0, headers: dict | None = None) -> tuple[bytes, str, int]:
    target = str(url or "").strip()
    if not target.startswith(("http://", "https://")):
        return b"", "invalid_url", 0
    res = None
    attempts = max(1, int(MUSIC_RESULT_DOWNLOAD_MAX_RETRIES or 1))
    attempted = 0
    request_headers = {
        "User-Agent": str(MUSIC_RESULT_DOWNLOAD_USER_AGENT or "TOAN-AAS-MusicDownloader/1.0"),
        "Accept": "audio/mpeg,audio/*,*/*",
        "Referer": "https://suno.com/",
    }
    request_headers.update(dict(headers or {}))
    async with httpx.AsyncClient(timeout=timeout_seconds, follow_redirects=True, headers=request_headers) as client:
        for attempt in range(attempts):
            attempted = attempt + 1
            res = await client.get(target)
            status_code = int(getattr(res, "status_code", 0) or 0)
            if status_code in {429} or status_code >= 500:
                if attempt + 1 < attempts:
                    await asyncio.sleep(float(MUSIC_RESULT_DOWNLOAD_RETRY_SLEEP_SECONDS or 0))
                    continue
            break
    if res is None:
        return b"", "download_failed", 0
    content_type = str(res.headers.get("content-type") or "")
    if res.status_code < 400 and res.content and (content_type.startswith("audio/") or len(res.content) > 1024):
        return bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}; content_type={content_type or '-'}; attempts={attempted}", int(res.status_code)
    downloaded = len(getattr(res, "content", b"") or b"")
    body_text = str(getattr(res, "text", "") or "")
    body_class = music_download_error_body_class(body_text[:800], content_type)
    safe_error = shopaikey_sanitize_error(body_text[:220] if body_text else f"HTTP {res.status_code}")
    class_part = f"; error_body_class={body_class}" if body_class else ""
    return b"", f"http={res.status_code}; downloaded_bytes={downloaded}; content_type={content_type or '-'}{class_part}; error={safe_error}; attempts={attempted}", int(res.status_code)

async def minimax_audio_reference_to_bytes(value) -> tuple[bytes, str]:
    candidates = _minimax_audio_candidates(value if isinstance(value, (dict, list)) else {"audio": value})
    for candidate in candidates:
        if str(candidate).startswith(("http://", "https://")):
            audio_bytes, detail, _http_status = await _download_audio_url_bytes(str(candidate))
            if audio_bytes:
                return audio_bytes, f"url:{detail}"
            continue
        audio_bytes, encoding = _decode_minimax_audio_string(str(candidate))
        if audio_bytes:
            return audio_bytes, encoding
    return b"", "empty_demo_audio"

async def key4u_minimax_tts_bytes(
    text: str,
    voice_id: str = "",
    voice_style: str = "",
    voice_speed: str = VOICE_TTS_DEFAULT_SPEED,
    allow_admin: bool = False,
    allow_confirmed_product: bool = False,
    tts_language_boost: str = "auto",
) -> tuple[str, bytes, str, int]:
    if not key4u_minimax_tts_configured(require_public=not (allow_admin or allow_confirmed_product)):
        return "MISSING", b"", "KEY4U_ENABLED/KEY4U_API_KEY/KEY4U_TTS_ENDPOINT/KEY4U_TTS_MODEL missing", 0
    provider = key4u_provider_instance()
    selected_voice_id = str(voice_id or default_tts_voice_id("male"))
    selected_speed = voice_tts_provider_speed(voice_speed or VOICE_TTS_DEFAULT_SPEED)
    result = await provider.tts(
        str(text or "")[:3500],
        model=KEY4U_TTS_MODEL,
        voice_id=str(voice_id or default_tts_voice_id("male")),
        speed=selected_speed,
        timeout_seconds=float(SHOPAIKEY_TTS_TIMEOUT_SECONDS or 60),
        language_boost=str(tts_language_boost or "auto"),
    )
    status = str(result.get("status") or ("PASS" if result.get("ok") else "FAIL"))
    http_status = int(result.get("http_status") or 0)
    audio_bytes = bytes(result.get("output_bytes") or b"")
    if result.get("ok") and audio_bytes:
        return "PASS", audio_bytes, f"http={http_status}; bytes={len(audio_bytes)}; route=key4u_minimax", http_status
    output_url = str(result.get("output_url") or "").strip()
    if result.get("ok") and output_url:
        downloaded, detail, download_http = await _download_audio_url_bytes(output_url)
        if downloaded:
            return "PASS", downloaded, f"http={http_status}; {detail}; route=key4u_minimax", int(download_http or http_status)
    detail = sanitize_provider_error(result.get("error_message_safe") or status)[:240]
    return status or "FAIL", b"", detail, http_status

async def shopaikey_minimax_tts_bytes(
    text: str,
    voice_id: str = "",
    voice_style: str = "",
    voice_speed: str = VOICE_TTS_DEFAULT_SPEED,
    tts_language_boost: str = "auto",
) -> tuple[str, bytes, str, int]:
    if not shopaikey_minimax_tts_configured():
        return "MISSING", b"", "SHOPAIKEY_API_KEY/SHOPAIKEY_TTS_BASE_URL/SHOPAIKEY_TTS_ENDPOINT/SHOPAIKEY_TTS_MODEL missing", 0
    endpoint = shopaikey_tts_final_url(SHOPAIKEY_TTS_ENDPOINT)
    selected_voice = shopaikey_minimax_voice_id(voice_id)
    text_value = str(text or "").strip()[:3500]
    if not text_value:
        return "FAIL_BAD_REQUEST", b"", "empty_text", 0
    if not selected_voice:
        return "FAIL_BAD_REQUEST", b"", "shopaikey_voice_not_configured", 0
    payload = shopaikey_official_tts_payload(
        text_value,
        voice_id=selected_voice,
        speed=voice_speed,
        tts_language_boost=tts_language_boost,
    )
    try:
        async with httpx.AsyncClient(timeout=float(SHOPAIKEY_TTS_TIMEOUT_SECONDS or 60), follow_redirects=True) as client:
            res = await client.post(
                endpoint,
                headers={"Authorization": f"Bearer {SHOPAIKEY_API_KEY}", "Content-Type": "application/json"},
                json=payload,
            )
        content_type = str(res.headers.get("content-type") or "")
        if res.status_code < 400 and res.content and content_type.startswith("audio/"):
            return "PASS", bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}; model={SHOPAIKEY_TTS_MODEL}; voice={selected_voice}", int(res.status_code)
        try:
            data = res.json()
        except Exception:
            data = {}
        if res.status_code < 400 and isinstance(data, dict):
            audio_bytes, detail, http_status = await resolve_shopaikey_tts_audio_bytes(data)
            if audio_bytes:
                return "PASS", audio_bytes, f"http={res.status_code}; {detail}; model={SHOPAIKEY_TTS_MODEL}; voice={selected_voice}", int(http_status or res.status_code)
        elif res.status_code < 400 and res.content and len(res.content) > 512:
            return "PASS", bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}; content_type={content_type or '-'}; model={SHOPAIKEY_TTS_MODEL}; voice={selected_voice}", int(res.status_code)
        detail = shopaikey_sanitize_error(res.text[:320] if getattr(res, "text", "") else f"HTTP {res.status_code}; no_audio")
        return shopaikey_classify_error(res.status_code, detail), b"", detail, int(res.status_code)
    except httpx.TimeoutException as exc:
        return "FAIL_TIMEOUT", b"", shopaikey_sanitize_error(str(exc)), 0
    except Exception as exc:
        return "FAIL_PROVIDER_ERROR", b"", shopaikey_sanitize_error(str(exc)), 0

