def make_minimax_voice_id(user_id, profile_id: int | str = "", timestamp_text: str = "") -> str:
    uid = re.sub(r"[^0-9A-Za-z]+", "", str(user_id or ""))[-18:] or "user"
    stamp = re.sub(r"[^0-9A-Za-z]+", "", str(timestamp_text or datetime.now().strftime("%Y%m%d%H%M%S")))[:18]
    profile = re.sub(r"[^0-9A-Za-z-]+", "-", str(profile_id or "").strip()).strip("-")
    parts = ["toanaas", "voice", uid, stamp]
    if profile:
        parts.append(profile)
    voice_id = "-".join(part for part in parts if part)
    voice_id = re.sub(r"[^A-Za-z0-9-]+", "-", voice_id).strip("-")[:128].rstrip("-")
    if not re.match(r"^[A-Za-z]", voice_id or ""):
        voice_id = f"v{voice_id}"[:128].rstrip("-")
    if len(voice_id) < 8:
        voice_id = (voice_id + "-toanaas")[:8].rstrip("-")
    return voice_id

def extract_minimax_returned_voice_id(payload, fallback: str = "") -> str:
    fallback_text = str(fallback or "").strip()
    candidates: list[str] = []

    def visit(value):
        if isinstance(value, dict):
            for key, child in value.items():
                lowered = str(key or "").lower()
                if lowered in {"voice_id", "voiceid", "voice"} and isinstance(child, (str, int)) and str(child).strip():
                    candidates.append(str(child).strip())
                elif lowered in {"data", "result", "voice", "output", "clone"}:
                    visit(child)
                elif isinstance(child, (dict, list)):
                    visit(child)
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    return candidates[0] if candidates else fallback_text

def shopaikey_minimax_base_resp_ok(payload) -> bool:
    if not isinstance(payload, dict):
        return False
    base_resp = payload.get("base_resp")
    if isinstance(base_resp, dict):
        status_code = str(base_resp.get("status_code") if base_resp.get("status_code") is not None else "").strip()
        return status_code == "0"
    if payload.get("status_code") is not None:
        status = str(payload.get("status_code")).strip().lower()
    else:
        status = str(payload.get("status") or "").strip().lower()
    return status in {"ok", "success", "pass", "0"}

async def shopaikey_minimax_upload_voice_sample(audio_bytes: bytes, filename: str = "voice_sample.mp3", content_type: str = "audio/mpeg") -> tuple[str, str, str, int]:
    if not SHOPAIKEY_API_KEY or not MINIMAX_VOICE_UPLOAD_ENDPOINT:
        return "MISSING", "", "SHOPAIKEY_API_KEY/MINIMAX_VOICE_UPLOAD_ENDPOINT missing", 0
    if not audio_bytes:
        return "NEED_AUDIO_INPUT", "", "missing_audio_sample", 0
    endpoint = join_shopaikey_url(SHOPAIKEY_TTS_BASE_URL, MINIMAX_VOICE_UPLOAD_ENDPOINT)
    if "?" not in endpoint:
        endpoint = f"{endpoint}?purpose=voice_clone"
    safe_name = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(filename or "voice_sample.mp3"))[:80] or "voice_sample.mp3"
    media_type = str(content_type or "audio/mpeg").split(";", 1)[0].strip() or "audio/mpeg"
    files = {"file": (safe_name, audio_bytes, media_type)}
    data = {"purpose": "voice_clone"}
    try:
        async with httpx.AsyncClient(timeout=60.0) as client:
            res = await client.post(endpoint, headers={"Authorization": f"Bearer {SHOPAIKEY_API_KEY}"}, data=data, files=files)
        try:
            payload = res.json()
        except Exception:
            payload = {}
        file_obj = (payload or {}).get("file") if isinstance(payload, dict) else {}
        file_id = str(
            (payload or {}).get("file_id")
            or (file_obj or {}).get("file_id")
            or (payload or {}).get("id")
            or ""
        ).strip()
        if res.status_code < 400 and file_id and shopaikey_minimax_base_resp_ok(payload):
            return "PASS", file_id, f"http={res.status_code}; file_id=yes; bytes={len(audio_bytes)}", int(res.status_code)
        detail = shopaikey_sanitize_error(res.text[:320] if getattr(res, "text", "") else f"HTTP {res.status_code}")
        return shopaikey_classify_error(res.status_code, detail), "", detail, int(res.status_code)
    except httpx.TimeoutException as exc:
        return "FAIL_TIMEOUT", "", shopaikey_sanitize_error(str(exc)), 0
    except Exception as exc:
        return "FAIL_PROVIDER_ERROR", "", shopaikey_sanitize_error(str(exc)), 0

async def shopaikey_minimax_voice_clone(file_id: str, voice_id: str) -> tuple[str, dict, str, int]:
    if not SHOPAIKEY_API_KEY or not MINIMAX_VOICE_CLONE_ENDPOINT:
        return "MISSING", {}, "SHOPAIKEY_API_KEY/MINIMAX_VOICE_CLONE_ENDPOINT missing", 0
    file_id_text = str(file_id or "").strip()
    raw_voice_id_text = str(voice_id or "").strip()
    if re.search(r"[^A-Za-z0-9_.-]+", raw_voice_id_text):
        return "FAIL_BAD_REQUEST", {}, "invalid_requested_voice_id", 0
    voice_id_text = minimax_voice_adapter.normalize_voice_id(raw_voice_id_text)
    if not file_id_text or not voice_id_text:
        return "FAIL_BAD_REQUEST", {}, "missing_file_id_or_voice_id", 0
    if not minimax_voice_adapter.validate_provider_voice_id(voice_id_text):
        return "FAIL_BAD_REQUEST", {}, "invalid_requested_voice_id", 0
    endpoint = join_shopaikey_url(SHOPAIKEY_TTS_BASE_URL, MINIMAX_VOICE_CLONE_ENDPOINT)
    payload = {
        "file_id": int(file_id_text) if file_id_text.isdigit() else file_id_text,
        "voice_id": voice_id_text,
        "model": MINIMAX_TTS_MODEL or "speech-02-hd",
        "text": VOICE_CLONE_CONFIRMATION_SAMPLE_TEXT,
        "need_noise_reduction": True,
        "need_volume_normalization": True,
        "language_boost": "auto",
        "aigc_watermark": False,
    }
    try:
        async with httpx.AsyncClient(timeout=60.0, follow_redirects=True) as client:
            res = await client.post(endpoint, headers={"Authorization": f"Bearer {SHOPAIKEY_API_KEY}", "Content-Type": "application/json"}, json=payload)
        try:
            data = res.json()
        except Exception:
            data = {}
        if res.status_code < 400 and shopaikey_minimax_base_resp_ok(data):
            returned_voice_id = minimax_voice_adapter.normalize_voice_id(extract_minimax_returned_voice_id(data, ""))
            provider_voice_id = returned_voice_id if minimax_voice_adapter.validate_provider_voice_id(returned_voice_id) else voice_id_text
            return "PASS", {
                "voice_id": provider_voice_id,
                "provider_voice_id": provider_voice_id,
                "requested_voice_id": voice_id_text,
                "demo_audio": str((data or {}).get("demo_audio") or ""),
            }, f"http={res.status_code}; voice_id={provider_voice_id}", int(res.status_code)
        detail = shopaikey_sanitize_error(res.text[:320] if getattr(res, "text", "") else f"HTTP {res.status_code}")
        return shopaikey_classify_error(res.status_code, detail), {}, detail, int(res.status_code)
    except httpx.TimeoutException as exc:
        return "FAIL_TIMEOUT", {}, shopaikey_sanitize_error(str(exc)), 0
    except Exception as exc:
        return "FAIL_PROVIDER_ERROR", {}, shopaikey_sanitize_error(str(exc)), 0

async def key4u_minimax_upload_voice_sample(audio_bytes: bytes, filename: str = "voice-sample.mp3", content_type: str = "audio/mpeg") -> tuple[str, str, str, int]:
    if not (KEY4U_ENABLED and KEY4U_API_KEY and KEY4U_MINIMAX_UPLOAD_ENDPOINT):
        return "MISSING", "", "KEY4U_ENABLED/KEY4U_API_KEY/KEY4U_MINIMAX_UPLOAD_ENDPOINT missing", 0
    result = await key4u_provider_instance().upload_voice_sample(audio_bytes, filename, content_type)
    status = str(result.get("status") or ("PASS" if result.get("ok") else "FAIL"))
    file_id = str(result.get("file_id") or "")
    return status, file_id, sanitize_provider_error(result.get("error_message_safe") or status)[:240], int(result.get("http_status") or 0)

async def key4u_minimax_voice_clone(file_id: str, voice_id: str) -> tuple[str, dict, str, int]:
    if not (KEY4U_ENABLED and KEY4U_API_KEY and KEY4U_MINIMAX_CLONE_ENDPOINT):
        return "MISSING", {}, "KEY4U_ENABLED/KEY4U_API_KEY/KEY4U_MINIMAX_CLONE_ENDPOINT missing", 0
    result = await key4u_provider_instance().clone_voice(file_id, voice_id, VOICE_CLONE_CONFIRMATION_SAMPLE_TEXT)
