def extract_command_name(update: Update) -> str:
    message = update.effective_message
    text = (getattr(message, "text", "") or getattr(message, "caption", "") or "").strip()
    if not text.startswith("/"):
        return ""
    command = text.split()[0][1:]
    command = command.split("@", 1)[0]
    return command.lower()

def safe_mode_command_block_reason(command: str, user_id, state: dict) -> str:
    command = (command or "").lower()
    if not command:
        return ""
    if state.get("emergency_lock"):
        if command in EMERGENCY_ALLOWED_PUBLIC_COMMANDS:
            return ""
        if command in EMERGENCY_ALLOWED_ADMIN_COMMANDS and is_admin_user(user_id):
            return ""
        return "emergency"
    if state.get("maintenance_mode") and command in TOOL_FREEZE_COMMANDS:
        return "maintenance"
    if state.get("payment_freeze") and command in PAYMENT_FREEZE_COMMANDS and not is_owner_user(user_id):
        return "payment_freeze"
    if state.get("tool_freeze") and command in TOOL_FREEZE_COMMANDS:
        return "tool_freeze"
    if state.get("provider_freeze") and command in PROVIDER_FREEZE_COMMANDS:
        return "provider_freeze"
    return ""

def freeze_block_message(reason: str, state: dict) -> str:
    if reason == "emergency":
        return emergency_user_message()
    if reason == "payment_freeze":
        return (
            "💳 <b>Thanh toán đang được khóa an toàn.</b>\n\n"
            "Hệ thống đang kiểm tra vận hành thanh toán. Số dư và lịch sử nạp của bạn không bị xóa.\n"
            "Vui lòng liên hệ hỗ trợ nếu cần xử lý bill gấp."
        )
    if reason == "maintenance":
        return (
            "🚧 <b>TOAN AAS đang bảo trì nhẹ.</b>\n\n"
            "Các tác vụ tốn phí/công cụ đang tạm dừng để kiểm tra. Bạn vẫn có thể xem /profile, /pricing, /legal."
        )
    if reason in {"tool_freeze", "provider_freeze"}:
        return (
            "🧰 <b>Công cụ AI đang tạm khóa an toàn.</b>\n\n"
            "TOAN AAS đang kiểm tra công cụ. Bot không trừ Xu cho tác vụ bị khóa. Vui lòng quay lại sau."
        )
    return emergency_user_message()

async def notify_ops_alert(context: ContextTypes.DEFAULT_TYPE, title: str, lines: list[str], exclude_user_id=None):
    if not context or not getattr(context, "bot", None):
        return
    body = "\n".join([title, "", *lines])[:3800]
    excluded = str(exclude_user_id) if exclude_user_id is not None else ""
    for chat_id in owner_and_admin_ids():
        if excluded and str(chat_id) == excluded:
            continue
        try:
            await context.bot.send_message(chat_id=str(chat_id), text=body, parse_mode="HTML")
        except Exception as e:
            logger.warning(f"Ops alert send failed chat_id={chat_id}: {e}")

# ── Per-user dispatch throttle ───────────────────────────────────────────────
# Job locks already stop one account from running two renders at once, but
# nothing limited how fast a single account could push updates into the
# handlers. This is a token bucket applied before any handler runs: generous
# enough that a real person never meets it, tight enough that an automated
# flood stops here instead of reaching job creation or the wallet.
DISPATCH_THROTTLE_ENABLED = env_flag("DISPATCH_THROTTLE_ENABLED", "true")
DISPATCH_THROTTLE_BURST = max(1, env_int("DISPATCH_THROTTLE_BURST", 30))
DISPATCH_THROTTLE_PER_MINUTE = max(1, env_int("DISPATCH_THROTTLE_PER_MINUTE", 60))
DISPATCH_THROTTLE_NOTICE_SECONDS = max(1, env_int("DISPATCH_THROTTLE_NOTICE_SECONDS", 20))
DISPATCH_THROTTLE_MAX_TRACKED = max(100, env_int("DISPATCH_THROTTLE_MAX_TRACKED", 5000))
DISPATCH_THROTTLE_BUCKETS: dict[str, tuple[float, float]] = {}
DISPATCH_THROTTLE_NOTICE_AT: dict[str, float] = {}
DISPATCH_THROTTLE_TEXT_VI = "⏳ Anh/chị thao tác hơi nhanh. Vui lòng chờ vài giây rồi thử lại."


def dispatch_throttle_reset_state() -> None:
    DISPATCH_THROTTLE_BUCKETS.clear()
    DISPATCH_THROTTLE_NOTICE_AT.clear()


def dispatch_throttle_prune(now: float) -> None:
    # Keep the in-memory maps bounded; idle callers are forgotten.
    if len(DISPATCH_THROTTLE_BUCKETS) <= DISPATCH_THROTTLE_MAX_TRACKED:
        return
    cutoff = now - 300.0
    for key in [key for key, value in DISPATCH_THROTTLE_BUCKETS.items() if value[1] < cutoff]:
        DISPATCH_THROTTLE_BUCKETS.pop(key, None)
        DISPATCH_THROTTLE_NOTICE_AT.pop(key, None)


def dispatch_throttle_allow(user_id, now: float | None = None) -> bool:
    """Token bucket per caller. True when this update may reach the handlers."""
    if not DISPATCH_THROTTLE_ENABLED:
        return True
    uid = str(user_id or "").strip()
    if not uid:
        return True
    if is_admin_user(uid):
        return True
    moment = time.time() if now is None else float(now)
    dispatch_throttle_prune(moment)
    refill_per_second = float(DISPATCH_THROTTLE_PER_MINUTE) / 60.0
    tokens, last_seen = DISPATCH_THROTTLE_BUCKETS.get(
        uid, (float(DISPATCH_THROTTLE_BURST), moment)
    )
    tokens = min(
        float(DISPATCH_THROTTLE_BURST),
        tokens + max(0.0, moment - last_seen) * refill_per_second,
    )
    if tokens < 1.0:
        DISPATCH_THROTTLE_BUCKETS[uid] = (tokens, moment)
        return False
    DISPATCH_THROTTLE_BUCKETS[uid] = (tokens - 1.0, moment)
    return True


def dispatch_throttle_should_notify(user_id, now: float | None = None) -> bool:
    """Answer a throttled caller once per window, not on every dropped update."""
    uid = str(user_id or "").strip()
    if not uid:
        return False
    moment = time.time() if now is None else float(now)
    if moment - DISPATCH_THROTTLE_NOTICE_AT.get(uid, 0.0) < DISPATCH_THROTTLE_NOTICE_SECONDS:
        return False
    DISPATCH_THROTTLE_NOTICE_AT[uid] = moment
    return True


async def dispatch_throttle_message_guard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    message = update.effective_message
    if not message or not update.effective_user:
        return
    if dispatch_throttle_allow(update.effective_user.id):
        return
    if dispatch_throttle_should_notify(update.effective_user.id):
        try:
            await message.reply_text(DISPATCH_THROTTLE_TEXT_VI)
        except Exception as exc:
            logger.warning("dispatch throttle notice skipped: %s", type(exc).__name__)
    raise ApplicationHandlerStop


async def dispatch_throttle_callback_guard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query or not query.from_user:
        return
    if dispatch_throttle_allow(query.from_user.id):
        return
    try:
        await query.answer(DISPATCH_THROTTLE_TEXT_VI)
    except Exception as exc:
        logger.warning("dispatch throttle answer skipped: %s", type(exc).__name__)
    raise ApplicationHandlerStop


async def safe_mode_message_guard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    message = update.effective_message
    if not message:
        return
    uid = update.effective_user.id if update.effective_user else ""
    command = extract_command_name(update)
    if command:
        deactivate_video_uiflow3_pending_input(context)
    state = current_system_mode()
    if not any([state.get("emergency_lock"), state.get("maintenance_mode"), state.get("payment_freeze"), state.get("tool_freeze"), state.get("provider_freeze")]):
        return
    if command:
        reason = safe_mode_command_block_reason(command, uid, state)
        if reason:
            await message.reply_text(freeze_block_message(reason, state), parse_mode="HTML")
            raise ApplicationHandlerStop
        return
    if state.get("emergency_lock"):
        await message.reply_text(emergency_user_message(), parse_mode="HTML")
        raise ApplicationHandlerStop
    if state.get("maintenance_mode") or state.get("tool_freeze") or state.get("provider_freeze"):
        await message.reply_text(freeze_block_message("maintenance" if state.get("maintenance_mode") else "tool_freeze", state), parse_mode="HTML")
        raise ApplicationHandlerStop

async def safe_mode_callback_guard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    callback_data = str(getattr(query, "data", "") or "")
    quick_image_state = (
        get_quick_image_flow(getattr(getattr(query, "from_user", None), "id", 0))
        if callback_data.startswith(("create_media|", "shopai|"))
        else None
    )
    preserve_uiflow3_handoff = bool(
        isinstance(quick_image_state, dict)
        and str(quick_image_state.get("source_flow") or "") == "video_uiflow3"
    )
    preserve_uiflow3_tail = bool(
        callback_data.startswith(("video_tail|", "vt9|"))
        and isinstance(getattr(context, "user_data", None), dict)
        and isinstance(context.user_data.get(VIDEO_UIFLOW3_ACTIVE_TAIL_KEY), dict)
    )
    if (
        not callback_data.startswith("vid3|")
        and not preserve_uiflow3_handoff
        and not preserve_uiflow3_tail
    ):
        deactivate_video_uiflow3_pending_input(context)
    state = current_system_mode()
    if not any([state.get("emergency_lock"), state.get("payment_freeze"), state.get("tool_freeze"), state.get("provider_freeze"), state.get("maintenance_mode")]):
        return
    data = query.data or ""
    reason = ""
    if state.get("emergency_lock"):
        reason = "emergency"
    elif state.get("payment_freeze") and data.startswith(("pkg|", "payos_pkg|", "manual|")):
        reason = ""
    elif (state.get("tool_freeze") or state.get("provider_freeze") or state.get("maintenance_mode")) and data.startswith(("prov|", "job|", "pipe|", "trend|", "creative|", "task|")):
        reason = "tool_freeze"
    if reason:
        await query.answer("TOAN AAS đang khóa an toàn để bảo vệ dữ liệu.", show_alert=True)
        try:
            await query.edit_message_text(freeze_block_message(reason, state), parse_mode="HTML")
        except Exception:
            pass
        raise ApplicationHandlerStop


