_VIDEO_PUBLIC_MEDIA_CLAIMS: dict[str, float] = {}


def _claim_video_public_event(cache: dict[str, float], event_id: str, now_ts: float | None = None) -> bool:
    """Atomically claim a Telegram event and keep the bounded cache short-lived."""

    clean_id = str(event_id or "").strip()
    if not clean_id:
        return True
    now_value = float(now_ts if now_ts is not None else time.time())
    cutoff = now_value - VIDEO_PUBLIC_CALLBACK_DEDUPE_TTL_SECONDS
    if len(cache) > 4096:
        for key, claimed_at in list(cache.items()):
            if float(claimed_at or 0) < cutoff:
                cache.pop(key, None)
        overflow = len(cache) - 4096
        if overflow > 0:
            for key in list(cache)[:overflow]:
                cache.pop(key, None)
    claimed_at = float(cache.get(clean_id) or 0)
    if claimed_at >= cutoff:
        return False
    cache[clean_id] = now_value
    return True


def _is_video_public_callback(data: str, context) -> bool:
    callback = str(data or "")
    if callback in {"menu|main_video", "menu|guide_video_ai"}:
        return True
    if callback.startswith(VIDEO_PUBLIC_CALLBACK_PREFIXES):
        return True
    if callback.startswith("create_media|qi_") or callback == "create_media|cancel":
        user_data = getattr(context, "user_data", None)
        return bool(isinstance(user_data, dict) and user_data.get("video_scene3_image_handoff_active"))
    return False


async def video_public_callback_dedupe_guard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query or not _is_video_public_callback(str(query.data or ""), context):
        return
    if _claim_video_public_event(_VIDEO_PUBLIC_CALLBACK_CLAIMS, str(getattr(query, "id", "") or "")):
        return
    try:
        await query.answer("TOAN AAS đã nhận thao tác này.")
    except Exception:
        pass
    raise ApplicationHandlerStop


def video_public_callback_failure_guard(callback_handler):
    """Contain an unexpected public Video callback failure inside its current screen.

    The individual route keeps ownership of state and Back.  This wrapper only
    prevents an exception from escaping into the global generic-X error handler.
    """

    async def guarded(update: Update, context: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        try:
            return await callback_handler(update, context, *args, **kwargs)
        except ApplicationHandlerStop:
            raise
        except Exception:
            query = getattr(update, "callback_query", None)
            callback_data = str(getattr(query, "data", "") or "")
            # Some shared handlers also serve non-Video features.  Preserve
            # their existing error ownership unless this is an active public
            # Product Video route.
            if not _is_video_public_callback(callback_data, context):
                raise
            logger.exception(
                "product_video_callback_failed callback=%s handler=%s",
                callback_data,
                getattr(callback_handler, "__name__", "unknown"),
            )
            if query:
                try:
                    await query.answer(
                        "Không thể cập nhật lựa chọn này. Màn hiện tại và kế hoạch vẫn được giữ.",
                        show_alert=True,
                    )
                except Exception:
                    pass
            return True

    guarded.__name__ = getattr(callback_handler, "__name__", "video_public_callback")
    guarded.__wrapped__ = callback_handler
    return guarded


def video_editor_callback_state_guard(callback_handler):
    """Rollback only this callback's exact write when Telegram rendering fails."""

    async def guarded(update: Update, context: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        query = getattr(update, "callback_query", None)
        user_id = safe_int(getattr(getattr(query, "from_user", None), "id", 0), 0)
        state_key = video_editor_pending_key(user_id) if user_id else ""
        try:
            restored_state = dict(get_video_editor_pending(user_id) or {}) if user_id else {}
        except VideoEditorStateUnavailableError:
            await notify_video_editor_state_unavailable(query)
            return True
        had_state = bool(restored_state)
        snapshot = video_editor_state_snapshot(restored_state)
        guard_snapshot_token = _VIDEO_EDITOR_GUARD_SNAPSHOT.set(snapshot)
        write_token = _VIDEO_EDITOR_STATE_WRITE.set(None)
        submission_token = _VIDEO_EDITOR_SUBMISSION_COMMITTED.set(False)
        answered_token = _VIDEO_EDIT_CALLBACK_ANSWERED.set(False)
        callback_data_override = str(kwargs.get("callback_data_override") or "")
        transactional_token = _VIDEO_EDIT_CALLBACK_TRANSACTIONAL.set(
            callback_data_override.startswith("videoedit|")
        )
        try:
            return await callback_handler(update, context, *args, **kwargs)
        except VideoEditorStateUnavailableError:
            await notify_video_editor_state_unavailable(query)
            return True
        except VideoEditorStateCommitError as exc:
            winner = video_editor_state_snapshot(exc.winner)
            if query is not None and winner:
                await rerender_video_editor_after_stale_commit(
                    query,
                    winner,
                    get_user_language(user_id) or "vi",
                )
            elif query is not None:
                try:
                    await query.answer(
                        "Không thể lưu phiên Chỉnh sửa video lúc này. Vui lòng thử lại.",
                        show_alert=True,
                    )
                except Exception:
                    pass
            return True
        except ApplicationHandlerStop:
            raise
        except Exception:
            if _VIDEO_EDITOR_SUBMISSION_COMMITTED.get():
                raise
            write_record = _VIDEO_EDITOR_STATE_WRITE.get()
            if state_key and write_record:
                restored, winner = rollback_video_editor_guard_state(
                    user_id,
                    write_record,
                    snapshot,
                    snapshot_exists=had_state,
                )
                if not restored and winner and query is not None:
                    try:
                        await rerender_video_editor_after_stale_commit(
                            query,
                            winner,
                            get_user_language(user_id) or "vi",
                        )
                    except Exception:
                        pass
            raise
        finally:
            _VIDEO_EDIT_CALLBACK_TRANSACTIONAL.reset(transactional_token)
            _VIDEO_EDIT_CALLBACK_ANSWERED.reset(answered_token)
            _VIDEO_EDITOR_SUBMISSION_COMMITTED.reset(submission_token)
            _VIDEO_EDITOR_STATE_WRITE.reset(write_token)
            _VIDEO_EDITOR_GUARD_SNAPSHOT.reset(guard_snapshot_token)

    guarded.__name__ = getattr(callback_handler, "__name__", "video_editor_callback")
    guarded.__wrapped__ = callback_handler
    return guarded


async def video_public_media_dedupe_guard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    message = getattr(update, "message", None)
    if not message:
        return
    chat_id = safe_int(getattr(getattr(message, "chat", None), "id", 0), 0)
    message_id = safe_int(getattr(message, "message_id", 0), 0)
    event_id = f"{chat_id}:{message_id}" if chat_id and message_id else ""
    if event_id and event_id in _VIDEO_PUBLIC_MEDIA_CLAIMS:
        if not _claim_video_public_event(_VIDEO_PUBLIC_MEDIA_CLAIMS, event_id):
            raise ApplicationHandlerStop
    user_data = getattr(context, "user_data", None)
    raw_state = dict(user_data.get(VIDEO_PROFILE_STUDIO_SESSION_KEY) or {}) if isinstance(user_data, dict) else {}
    profile_step = str(raw_state.get("step") or "")
    active_step = profile_step
    active_product = ""
    if chat_id:
        try:
            active_session = get_video_session(chat_id)
        except Exception:
            active_session = {}
        active_step = str(active_session.get("current_step") or active_step)
        active_product = str(active_session.get("product_id") or "")
    if active_step == "awaiting_video_tail9_logo":
        if active_product not in VIDEO_PRODUCT_REGISTRY:
            return
    elif active_step in {"awaiting_selfshot2_video", "awaiting_selfshot2_logo", "awaiting_selfshot3_video"}:
        expected_product = (
            video_selfshot2.PRODUCT_ID
            if active_step in {"awaiting_selfshot2_video", "awaiting_selfshot2_logo"}
            else video_selfshot3.PRODUCT_ID
        )
        if active_product != expected_product:
            return
    elif active_step not in {
        "await_material_upload",
        "await_post_asset_upload",
        "await_flow6_asset_upload",
    }:
        return
    if not _claim_video_public_event(_VIDEO_PUBLIC_MEDIA_CLAIMS, event_id):
        raise ApplicationHandlerStop

def admin_internal_command(handler):
    async def wrapped(update: Update, context: ContextTypes.DEFAULT_TYPE):
        if not is_admin_user(update.effective_user.id):
            record_anomaly(
                "unauthorized_admin_command",
                "medium",
                f"command={extract_command_name(update) or '-'}",
                user_id=update.effective_user.id,
                username=update.effective_user.username or update.effective_user.first_name or "",
                auto_lock=False,
            )
            return await reply_internal_customer_feature(update)
        return await handler(update, context)
    return wrapped

