def video_editor_callback_arity_valid(parts: list[str] | tuple[str, ...]) -> bool:
    """Reject malformed Video Edit callback shapes before state or UI work."""

    values = list(parts or [])
    if len(values) < 2 or str(values[0] or "").strip().lower() != "videoedit":
        return False
    action = str(values[1] or "").strip().lower()
    parameters = [str(value or "").strip() for value in values[2:]]
    if action in {"a650_upload", "a650_source", "a650_catalog", "a650_selected", "a650_summary"}:
        return (
            len(parameters) == 2
            and bool(re.fullmatch(r"[0-9a-f]{8}", parameters[0]))
            and bool(re.fullmatch(r"[1-9][0-9]*", parameters[1]))
        )
    if action in {"a650_cat", "a650_item", "a650_detail"}:
        return (
            len(parameters) == 3
            and bool(parameters[0])
            and bool(re.fullmatch(r"[0-9a-f]{8}", parameters[1]))
            and bool(re.fullmatch(r"[1-9][0-9]*", parameters[2]))
        )
    if action in {"status", "ai_status", "status_hub", "status_menu"}:
        return len(parameters) == 1 and bool(re.fullmatch(r"[1-9][0-9]*", parameters[0]))
    if action == "guide":
        return not parameters or (
            len(parameters) == 1 and parameters[0] in VIDEO_EDITOR_GUIDE_CALLERS
        )
    if action in _VIDEO_EDITOR_CALLBACK_NO_VALUE_ACTIONS:
        return not parameters
    if action in _VIDEO_EDITOR_CALLBACK_ONE_VALUE_ACTIONS:
        return len(parameters) == 1 and bool(parameters[0])
    if action in _VIDEO_EDITOR_CALLBACK_OPTIONAL_ONE_VALUE_ACTIONS:
        return len(parameters) <= 1 and (not parameters or bool(parameters[0]))
    if action == "set":
        return len(parameters) == 2 and all(parameters)
    if action.startswith("ai_set_"):
        return len(parameters) == 1 and bool(parameters[0])
    return False


def video_editor_pending_key(user_id) -> str:
    return f"video_editor:{user_id}"


def video_editor_durable_state_enabled() -> bool:
    """Persist live editor ownership, while ordinary pytest fixtures stay isolated."""

    disabled = str(os.getenv("VIDEO_EDITOR_DURABLE_STATE_DISABLED") or "").strip().lower()
    if disabled in {"1", "true", "yes", "on"}:
        return False
    if os.getenv("PYTEST_CURRENT_TEST") and str(
        os.getenv("VIDEO_EDITOR_DURABLE_STATE_TEST") or ""
    ).strip().lower() not in {"1", "true", "yes", "on"}:
        return False
    return True


def persist_video_editor_state(user_id, state: dict | None, *, exists: bool) -> None:
    """Best-effort durability; public routing still fails closed in memory."""

    if not video_editor_durable_state_enabled():
        return
    try:
        if exists and state:
            video_edit_state_store.save_state(
                user_id,
                video_editor_state_snapshot(state),
                ttl_seconds=VIDEO_EDITOR_TTL_SECONDS,
            )
        else:
            video_edit_state_store.delete_state(user_id)
    except (OSError, TypeError, ValueError) as exc:
        logger.warning(
            "videoedit durable state skipped | error_type=%s",
            type(exc).__name__,
        )


def record_video_editor_state_write(
    user_id,
    state: dict | None,
    *,
    exists: bool,
) -> None:
    """Remember this coroutine's exact last Video Edit state mutation."""

    _VIDEO_EDITOR_STATE_WRITE.set(
        {
            "user_id": str(user_id or ""),
            "exists": bool(exists),
            "state": video_editor_state_snapshot(state),
        }
    )


def _video_editor_guard_expected_state(user_id) -> tuple[dict, bool] | None:
    """Return the optimistic state captured by this guarded transition."""

    snapshot = _VIDEO_EDITOR_GUARD_SNAPSHOT.get()
    if snapshot is None:
        return None
    write_record = _VIDEO_EDITOR_STATE_WRITE.get()
    if isinstance(write_record, dict) and str(write_record.get("user_id") or "") == str(user_id or ""):
        return (
            video_editor_state_snapshot(write_record.get("state") or {}),
            bool(write_record.get("exists")),
        )
    clean = video_editor_state_snapshot(snapshot)
    return clean, bool(clean)


def build_video_editor_pending_state(step: str, **fields) -> dict:
    """Build the one sanitized state shape used by memory and durable CAS."""

    payload = {"step": str(step or "menu"), "created_at_ts": time.time()}
    for key, value in fields.items():
        if key == "source_file_id" and value is None:
            payload[key] = None
        elif key in VIDEO_EDITOR_TEXT_FIELDS:
            payload[key] = re.sub(r"\s+", " ", str(value or "").strip())[:800]
        elif key in VIDEO_EDITOR_NUMBER_FIELDS:
            payload[key] = safe_int(value, 0)
        elif key == "sharpen":
            payload[key] = bool(value)
        elif key in {
            "allow_gaps", "coverage_required", "inspection_complete",
            "public_user_confirmed", "preserve_source_audio", "provider_call",
            "awaiting_media", "intake_in_progress", "source_has_audio",
        }:
            payload[key] = bool(value)
        elif key in VIDEO_EDITOR_STRUCTURED_FIELDS:
            try:
                payload[key] = json.loads(json.dumps(value, ensure_ascii=False))
            except (TypeError, ValueError):
                payload[key] = {} if key not in {"concat_sources", "split_ranges"} else []
    return payload


def set_video_editor_pending(user_id, step: str, **fields) -> dict:
    payload = build_video_editor_pending_state(step, **fields)
    expected = _video_editor_guard_expected_state(user_id)
    current = (
        expected[0]
        if expected is not None
        else video_editor_state_snapshot(get_video_editor_pending(user_id))
    )
    _committed, winner = compare_and_replace_video_editor_pending(
        user_id,
        current,
        payload,
        expected_exists=bool(current),
        raise_on_failure=True,
    )
    return winner


def update_video_editor_pending(user_id, step: str = "", **fields) -> dict:
    current = dict(get_video_editor_pending(user_id) or {})
    current.pop("step", None)
    current.pop("created_at_ts", None)
    current.update(fields)
    return set_video_editor_pending(user_id, step or str((get_video_editor_pending(user_id) or {}).get("step") or "menu"), **current)


def update_video_editor_screen(
    user_id,
    screen_id: str,
    *,
    parent_callback: str,
    state_step: str = "",
    **fields,
) -> dict:
    """Persist one allow-listed Video Edit screen and its exact parent."""

    screen = str(screen_id or "workspace").strip().lower()
    parent = video_edit_state_machine.safe_parent_callback(parent_callback)
    return update_video_editor_pending(
        user_id,
        str(state_step or screen),
        screen_id=screen,
        current_screen=screen,
        parent_callback=parent,
        **fields,
    )


def get_video_editor_pending(user_id) -> dict:
    key = video_editor_pending_key(user_id)
    durable_enabled = video_editor_durable_state_enabled()
    state: dict = {}
    for _attempt in range(3):
        memory_state = video_editor_state_snapshot(USER_PENDING.get(key) or {})
        state = memory_state
        if durable_enabled:
            try:
                durable_state = video_edit_state_store.load_state(user_id)
            except (OSError, TypeError, ValueError) as exc:
                logger.warning(
                    "videoedit durable state unavailable | error_type=%s",
                    type(exc).__name__,
                )
                raise VideoEditorStateUnavailableError() from exc
            # SQLite/file-backed state is the cross-process source of truth.
            # Reconcile it on every enabled read so a replacement or deletion
            # in another bot process cannot leave a stale in-memory owner.
            state = video_editor_state_snapshot(durable_state or {})
            if state:
                USER_PENDING[key] = video_editor_state_snapshot(state)
            elif memory_state:
                USER_PENDING.pop(key, None)
        if not state:
            return {}
        try:
            created_at_ts = float(state.get("created_at_ts") or 0)
        except (TypeError, ValueError, OverflowError):
            created_at_ts = 0.0
        expired = bool(
            not math.isfinite(created_at_ts)
            or created_at_ts <= 0
            or time.time() - created_at_ts > VIDEO_EDITOR_TTL_SECONDS
        )
        if not expired:
            return state
        if not durable_enabled:
            USER_PENDING.pop(key, None)
            return {}
        try:
            removed, durable_winner = video_edit_state_store.compare_and_swap_state(
                user_id,
                expected_state=state,
                replacement_state=None,
                expected_exists=True,
                replacement_exists=False,
                ttl_seconds=VIDEO_EDITOR_TTL_SECONDS,
            )
        except (OSError, TypeError, ValueError) as exc:
            logger.warning(
                "videoedit expired state CAS unavailable | error_type=%s",
                type(exc).__name__,
            )
            raise VideoEditorStateUnavailableError(state) from exc
        if removed or not durable_winner:
            USER_PENDING.pop(key, None)
            return {}
        USER_PENDING[key] = video_editor_state_snapshot(durable_winner)
    raise VideoEditorStateUnavailableError(state)


def video_editor_state_snapshot(state: dict | None) -> dict:
    """Return a detached value for exact Video Edit compare-and-set checks."""

    try:
        return json.loads(json.dumps(dict(state or {}), ensure_ascii=False))
    except (TypeError, ValueError):
        return dict(state or {})


def video_editor_split_reset_token(state: dict | None) -> str:
    """Bind one destructive Split reset to the exact warned edit state."""

    current = dict(state or {})
    identity = {
        "edit_session_id": str(
            current.get("edit_session_id") or current.get("session_id") or ""
        ),
        "state_revision": safe_int(current.get("state_revision"), 0),
        "revision": safe_int(current.get("revision"), 0),
        "source_file_id": str(current.get("source_file_id") or ""),
        "source_video_hash": str(current.get("source_video_hash") or ""),
        "manual_edit_plan": current.get("manual_edit_plan") or {},
        "concat_sources": current.get("concat_sources") or [],
        "logo_source": current.get("logo_source") or {},
        "watermark_config": current.get("watermark_config") or {},
        "subtitle_source": current.get("subtitle_source") or {},
        "audio_sources": current.get("audio_sources") or [],
    }
    canonical = json.dumps(
        video_editor_state_snapshot(identity),
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()[:16]


def compare_and_set_video_editor_pending(
    user_id,
    expected_state: dict,
    step: str = "",
    **fields,
) -> tuple[bool, dict]:
    """Commit only while the complete pending state is still unchanged."""

    current = video_editor_state_snapshot(get_video_editor_pending(user_id))
    if current != video_editor_state_snapshot(expected_state):
        return False, current
    replacement_fields = dict(current)
    current_step = str(replacement_fields.pop("step", "") or "menu")
    replacement_fields.pop("created_at_ts", None)
    replacement_fields.update(fields)
    replacement = build_video_editor_pending_state(
        step or current_step,
        **replacement_fields,
    )
    return compare_and_replace_video_editor_pending(
        user_id,
        current,
        replacement,
    )


def compare_and_replace_video_editor_pending(
    user_id,
    expected_state: dict,
    replacement_state: dict,
    *,
    replacement_exists: bool = True,
    expected_exists: bool | None = None,
    raise_on_failure: bool = False,
) -> tuple[bool, dict]:
    """Replace an exact pending value only if no concurrent state won."""

    expected = video_editor_state_snapshot(expected_state)
    current = video_editor_state_snapshot(get_video_editor_pending(user_id))
    current_exists = bool(current)
    require_existing = bool(expected) if expected_exists is None else bool(expected_exists)
    if current_exists != require_existing or current != expected:
        if raise_on_failure:
            raise VideoEditorStateCommitError(
                "video_editor_state_commit_conflict",
                current,
            )
        return False, current
    key = video_editor_pending_key(user_id)
    replacement = video_editor_state_snapshot(replacement_state)
    if video_editor_durable_state_enabled():
        try:
            replaced, durable_winner = video_edit_state_store.compare_and_swap_state(
                user_id,
                expected_state=expected,
                replacement_state=replacement,
                expected_exists=require_existing,
                replacement_exists=bool(replacement_exists),
                ttl_seconds=VIDEO_EDITOR_TTL_SECONDS,
            )
        except (OSError, TypeError, ValueError) as exc:
            logger.warning(
                "videoedit durable CAS skipped | error_type=%s",
                type(exc).__name__,
            )
            if raise_on_failure:
                raise VideoEditorStateCommitError(
                    "video_editor_state_commit_failed",
                    current,
                ) from exc
            return False, current
        if not replaced:
            if durable_winner:
                USER_PENDING[key] = durable_winner
            else:
                USER_PENDING.pop(key, None)
            if raise_on_failure:
                raise VideoEditorStateCommitError(
                    "video_editor_state_commit_conflict",
                    durable_winner,
                )
            return False, video_editor_state_snapshot(durable_winner)
    if replacement_exists:
        USER_PENDING[key] = replacement
        if not video_editor_durable_state_enabled():
            persist_video_editor_state(user_id, replacement, exists=True)
        record_video_editor_state_write(user_id, replacement, exists=True)
        return True, replacement
    USER_PENDING.pop(key, None)
    if not video_editor_durable_state_enabled():
        persist_video_editor_state(user_id, {}, exists=False)
    record_video_editor_state_write(user_id, {}, exists=False)
    return True, {}


def rollback_video_editor_guard_state(
    user_id,
    write_record: dict | None,
    snapshot: dict | None,
    *,
    snapshot_exists: bool,
) -> tuple[bool, dict]:
    """Rollback only this coroutine's exact write, never a concurrent winner."""

    record = dict(write_record or {})
    if str(record.get("user_id") or "") != str(user_id or ""):
        return False, video_editor_state_snapshot(get_video_editor_pending(user_id))
    expected = video_editor_state_snapshot(record.get("state") or {})
    key = video_editor_pending_key(user_id)
    expected_exists = bool(record.get("exists"))
    current_exists = key in USER_PENDING
    current = video_editor_state_snapshot(get_video_editor_pending(user_id))
    if current_exists != expected_exists or current != expected:
        return False, current
    return compare_and_replace_video_editor_pending(
        user_id,
        expected,
        video_editor_state_snapshot(snapshot),
        replacement_exists=bool(snapshot_exists),
    )


def clear_video_editor_pending(user_id) -> bool:
    expected = _video_editor_guard_expected_state(user_id)
    current = (
        expected[0]
        if expected is not None
        else video_editor_state_snapshot(get_video_editor_pending(user_id))
    )
    if not current:
        return False
    committed, _winner = compare_and_replace_video_editor_pending(
        user_id,
        current,
        {},
        replacement_exists=False,
        expected_exists=True,
        raise_on_failure=True,
    )
    return committed


def build_video_edit_lane_state(edit_mode: str, **carry) -> dict:
    """Build one complete fresh lane without mutating pending ownership."""

    canonical = video_edit_state_machine.start_lane(edit_mode)
    session_id = str(carry.get("edit_session_id") or carry.get("session_id") or uuid.uuid4().hex)
    mode_defaults = {
        "manual_edit": {"selected_tool": "manual", "entry_context": "manual", "last_section": "manual", "entry_parent_callback": "videoedit|manual"},
        "ai_edit": {"selected_tool": "ai_edit", "entry_context": "ai", "last_section": "ai", "entry_parent_callback": "videoedit|ai"},
        "quality_enhance": {"selected_tool": "ai_edit", "entry_context": "quality_enhance", "last_section": "restore", "entry_parent_callback": "videoedit|restore"},
    }
    fields = {
        **mode_defaults[canonical["edit_mode"]],
        **canonical,
        "product_type": video_editengine1.PRODUCT_TYPE,
        "flow_owner": "video_edit",
        "engine_route": video_editengine1.ENGINE_ROUTE,
        "worker_owner": video_editengine1.OUTBOX_OWNER,
        "state_revision": 1,
        "revision": 1,
        "ratio": "keep",
        "audio_policy": "preserve_if_present",
        "status": "awaiting_source",
        "source_has_audio": False,
        "source_video_id": "",
        "source_video_hash": "",
        "edit_operations": [],
        "addon_config": {},
        "logo_config": {},
        "pricing_snapshot": {},
        "receipt_state": "not_created",
        "charge_state": "not_charged",
        "edit_session_id": session_id,
        "session_id": session_id,
        **carry,
    }
    step = str(fields.pop("step"))
    return build_video_editor_pending_state(step, **fields)


def replace_video_edit_lane_state(
    user_id,
    expected_state: dict,
    edit_mode: str,
    **carry,
) -> dict:
    """Replace one exact lane state in a single durable compare-and-set."""

    expected = video_editor_state_snapshot(expected_state)
    replacement = build_video_edit_lane_state(edit_mode, **carry)
    _committed, winner = compare_and_replace_video_editor_pending(
        user_id,
        expected,
        replacement,
        expected_exists=bool(expected),
        replacement_exists=True,
        raise_on_failure=True,
    )
    return winner


def begin_video_editor_submission(
    user_id,
    expected_state: dict,
    *,
    lane: str,
) -> dict:
    """Reserve one exact confirmation state before creating a job."""

    expected = video_editor_state_snapshot(expected_state)
    if not expected:
        raise VideoEditorStateCommitError(
            "video_editor_submit_state_missing",
            video_editor_state_snapshot(get_video_editor_pending(user_id)),
        )
    current = video_editor_state_snapshot(get_video_editor_pending(user_id))
    if current != expected:
        raise VideoEditorStateCommitError(
            "video_editor_submit_state_conflict",
            current,
        )
    reserved = video_editor_state_snapshot(expected)
    reserved.update(
        {
            "step": "submitting",
            "current_screen": "submitting",
            "status": "submitting",
            "pending_field": "",
            "awaiting_media": False,
            "submission_lane": str(lane or "local")[:40],
        }
    )
    committed, winner = compare_and_replace_video_editor_pending(
        user_id,
        expected,
        reserved,
        expected_exists=True,
        replacement_exists=True,
        raise_on_failure=False,
    )
    if not committed:
        raise VideoEditorStateCommitError(
            "video_editor_submit_state_conflict",
            winner,
        )
    return reserved


def finish_video_editor_submission(
    user_id,
    expected_reserved_state: dict,
    replacement_state: dict | None = None,
    *,
    replacement_exists: bool = True,
) -> tuple[bool, dict]:
    """Commit or clear a job result only if this submit still owns the lane."""

    expected = video_editor_state_snapshot(expected_reserved_state)
    replacement = video_editor_state_snapshot(replacement_state or {})
    return compare_and_replace_video_editor_pending(
        user_id,
        expected,
        replacement,
        expected_exists=True,
        replacement_exists=bool(replacement_exists),
        raise_on_failure=False,
    )


def start_video_edit_lane_state(user_id, edit_mode: str, **carry) -> dict:
    current = video_editor_state_snapshot(get_video_editor_pending(user_id))
    return replace_video_edit_lane_state(
        user_id,
        current,
        edit_mode,
        **carry,
    )


def return_video_editor_workspace(user_id, *, selected_tool: str = "", **fields) -> dict:
    """Clear one completed input and restore its exact canonical editor parent."""

    state = dict(get_video_editor_pending(user_id) or {})
    tool = str(selected_tool or state.get("selected_tool") or "manual")
    if tool not in {"manual", "split"}:
        tool = "manual"
    edit_mode = video_edit_state_machine.normalize_edit_mode(
        fields.pop("edit_mode", state.get("edit_mode"))
    ) or "manual_edit"
    entry_parent = video_edit_state_machine.safe_parent_callback(
        fields.pop("entry_parent_callback", state.get("entry_parent_callback"))
        or video_edit_state_machine.lane_callback(edit_mode)
    )
    review_return_to_hint = (
        fields.pop("review_return_to", None)
        or state.get("return_to")
        or state.get("parent_callback")
    )
    review_state = {**state, **fields}
    if review_return_to_hint:
        review_state["return_to"] = review_return_to_hint
    review_return_to = video_edit_review_return_action(review_state)
    for transient_key in (
        "step", "created_at_ts", "screen_id", "current_screen",
        "parent_callback", "pending_field", "return_to",
    ):
        fields.pop(transient_key, None)
    screen_id = "split" if tool == "split" else "workspace"
    parent_callback = "videoedit|cut" if tool == "split" else entry_parent
    return update_video_editor_screen(
        user_id,
        screen_id,
        parent_callback=parent_callback,
        state_step="options",
        pending_field="",
        return_to=review_return_to,
        selected_tool=tool,
        edit_mode=edit_mode,
        entry_parent_callback=entry_parent,
        **fields,
    )


def return_video_editor_review_after_plan_change(
    user_id,
    state: dict,
    **fields,
) -> dict:
    """Render a changed branding plan back on Review with a fresh token."""

    current = dict(state or {})
    candidate = {**current, **fields}
    source_duration_ms = safe_int(
        (candidate.get("source_metadata") or {}).get("duration_ms")
        or candidate.get("source_duration_ms"),
        0,
    )
    if not video_local_editing.plan_has_effective_operation(
        candidate.get("manual_edit_plan") or {},
        source_duration_ms=source_duration_ms,
    ):
        return return_video_editor_workspace(
            user_id,
            review_return_to="workspace",
            **fields,
        )
    review_return_to = video_edit_review_return_action(
        {"return_to": current.get("return_action") or "workspace"}
    )
    revision = max(
        1,
        safe_int(current.get("state_revision"), 1),
        safe_int(current.get("review_revision"), 0),
    ) + 1
    return update_video_editor_pending(
        user_id,
        "review",
        screen_id="review",
        current_screen="review",
        parent_callback="videoedit|workspace",
        pending_field="",
        return_to=review_return_to,
        return_action="",
        status="review_ready",
        state_revision=revision,
        review_revision=revision,
        **fields,
    )


def save_video_edit_canonical_state(user_id, state: dict) -> dict:
    fields = dict(state or {})
    step = str(fields.pop("step", "await_edit_video"))
    fields.pop("created_at_ts", None)
    return set_video_editor_pending(user_id, step, **fields)


def recent_video_editor_source(user_id) -> dict:
    source = get_recent_media_state(LAST_USER_VIDEO, safe_int(user_id, 0)) or {}
    if not source.get("file_id"):
        return {}
    return {
        "source_file_id": str(source.get("file_id") or "")[:240],
        "source_file_name": str(source.get("file_name") or "video.mp4")[:180],
        "source_mime_type": str(source.get("mime_type") or "video/mp4")[:120],
        "source_file_size": safe_int(source.get("file_size"), 0),
        "source_duration": safe_int(source.get("duration"), 0),
    }


