def video_ai_real_profile_idea_category(profile_key: str) -> str:
    key = str(profile_key or "").strip()
    for category, profile_keys in video_profile_catalog.IDEA_GROUP_PROFILE_MAP.items():
        if key in profile_keys:
            return str(category)
    content_profile = video_profile_catalog.content_type_for_profile(key)
    return VIDEO_AI_REAL_CATEGORY_BY_CONTENT_PROFILE.get(content_profile, "story")


def video_ai_real_profile_context_prompts(raw_state: dict) -> list[dict]:
    """Build public suggestions from the selected 32-content profile."""

    state = _video_ai_real_pilot_state(raw_state)
    profile_key = str((state.get("content") or {}).get("profile_id") or "").strip()
    profile = dict(video_profile_catalog.PROFILE_BY_KEY.get(profile_key) or {})
    pattern = [
        str(item or "").strip()
        for item in profile.get("default_scene_pattern") or []
        if str(item or "").strip()
    ]
    if not pattern:
        return [
            {
                "key": key,
                "label": label,
                "guidance": guidance,
                "profile_key": "legacy",
                "profile_name": "Nội dung tự nhập",
                "pattern": "",
            }
            for key, (label, guidance) in VIDEO_AI_REAL_CONTEXT_PROMPTS.items()
        ]
    profile_name = str(
        profile.get("public_name")
        or (state.get("content") or {}).get("approved_brief", {}).get("title")
        or "Nội dung tự nhập"
    ).strip()
    description = str(profile.get("description") or "").strip()
    sequence = " -> ".join(pattern)
    questions = [
        str(item or "").strip()
        for item in profile.get("clarification_questions") or []
        if str(item or "").strip()
    ] or [f"Người xem cần nhớ điều gì sau video {profile_name}?"]
    category = video_ai_real_profile_idea_category(profile_key)
    beats = tuple(
        video_idea_catalog.CATEGORY_BEAT_IDEAS.get(category)
        or video_idea_catalog.CATEGORY_BEAT_IDEAS["story"]
    )
    content_profile = video_profile_catalog.content_type_for_profile(profile_key)
    post_guidance = dict(
        VIDEO_AI_REAL_PROFILE_POST_GUIDANCE_VI.get(content_profile)
        or VIDEO_AI_REAL_PROFILE_POST_GUIDANCE_VI["storytelling"]
    )
    technical_profile = video_profile_catalog.technical_profile_for_profile(profile_key)
    creative = dict(video_scene3_flow.PROFILE_CREATIVE_GUIDANCE.get(technical_profile) or {})
    visual_style = str(
        creative.get("visual")
        or f"Hình ảnh chân thật, nhất quán và phục vụ đúng {profile_name.lower()}."
    )
    camera = str(
        creative.get("camera")
        or "Khung hình rõ chủ thể, camera có điểm bắt đầu và điểm dừng tự nhiên."
    )
    motion = str(
        creative.get("motion")
        or "Mỗi cảnh có một chuyển động chính và hoàn tất trước khi cắt."
    )
    constraints = str(
        creative.get("avoid")
        or "Không đổi nhận diện, không bịa chi tiết và không cắt giữa hành động."
    )
    suggestions = []
    for index, beat in enumerate(beats, 1):
        question = questions[(index - 1) % len(questions)]
        character_direction = (
            f"Giữ nhân vật hoặc chủ thể phù hợp {profile_name.lower()} nhất quán về tên, vai trò, "
            "nhận diện và trang phục; chỉ dùng những người thật sự cần cho tình tiết."
        )
        location_direction = (
            f"Chọn bối cảnh trực tiếp phục vụ tình tiết “{beat}”; nếu đã có ảnh bối cảnh thì dùng ảnh "
            "làm chuẩn và không hỏi mô tả trùng."
        )
        blueprint = {
            "profile_key": profile_key,
            "profile_name": profile_name,
            "category": category,
            "content_goal": description,
            "hook": str(beat),
            "story_formula": list(pattern),
            "clarification": question,
            "character_direction": character_direction,
            "location_direction": location_direction,
            "visual_style": visual_style,
            "camera": camera,
            "motion": motion,
            "transition": post_guidance["transition"],
            "voice": post_guidance["voice"],
            "music": post_guidance["music"],
            "subtitle": post_guidance["subtitle"],
            "pacing": post_guidance["pacing"],
            "constraints": constraints,
        }
        visual_prompt = "\n".join([
            f"Loại nội dung: {profile_name}",
            f"Mục tiêu nội dung: {description}",
            f"Tình tiết chính: {beat}",
            f"Mạch kể: {sequence}",
            f"Điểm cần chốt: {question}",
            f"Nhân vật/chủ thể: {character_direction}",
            f"Bối cảnh: {location_direction}",
            f"Phong cách hình ảnh: {visual_style}",
            f"Máy quay: {camera}",
            f"Chuyển động: {motion}",
            f"Chuyển cảnh: {post_guidance['transition']}",
            f"Nhịp dựng: {post_guidance['pacing']}",
            f"Giới hạn: {constraints}",
        ])
        prompt = "\n".join([
            visual_prompt,
            f"Giọng: {post_guidance['voice']}",
            f"Nhạc: {post_guidance['music']}",
            f"Phụ đề: {post_guidance['subtitle']}",
        ])
        suggestions.append({
            "key": f"idea_{index:02d}",
            "label": str(beat),
            "guidance": (
                f"{profile_name}: {beat}. "
                f"Mục tiêu nội dung: {description} "
                f"Mạch kể: {sequence}. "
                f"Máy quay: {camera}. "
                f"Chuyển động: {motion}. "
                f"Gợi ý hậu kỳ: {post_guidance['voice']} {post_guidance['music']} {post_guidance['subtitle']} "
                f"Điểm cần chốt: {question}"
            ).strip(),
            "profile_key": profile_key,
            "profile_name": profile_name,
            "pattern": sequence,
            "category": category,
            "visual_prompt": visual_prompt,
            "prompt": prompt,
            "prompt_blueprint": blueprint,
        })
    return suggestions


def video_uiflow3_profile_context_prompts(raw_state: dict) -> list[dict]:
    """Build five product-aware content suggestions for non-pilot lanes."""

    state = video_uiflow3.normalize_state(raw_state)
    product = str(state.get("parent_product") or "")
    if product == "video_ai_real":
        # Keep the locked Video AI chân thật pilot output unchanged.
        return video_ai_real_profile_context_prompts(state)
    product_guidance = dict(VIDEO_UIFLOW3_PRODUCT_CONTEXT_GUIDANCE.get(product) or {})
    if not product_guidance:
        return []
    content = dict(state.get("content") or {})
    profile_key = str(content.get("profile_id") or "").strip()
    profile = dict(video_profile_catalog.PROFILE_BY_KEY.get(profile_key) or {})
    profile_name = str(
        profile.get("public_name")
        or (content.get("approved_brief") or {}).get("title")
        or "Nội dung tự nhập"
    ).strip()
    description = str(profile.get("description") or content.get("original_intent") or "").strip()
    pattern = [
        str(item or "").strip()
        for item in profile.get("default_scene_pattern") or []
        if str(item or "").strip()
    ]
    category = video_ai_real_profile_idea_category(profile_key)
    fallback_beats = list(video_idea_catalog.CATEGORY_BEAT_IDEAS.get(category) or [])
    beats: list[str] = []
    for beat in [*pattern, *fallback_beats, "Mở đầu rõ chủ thể", "Kết thúc có điểm nhớ"]:
        value = str(beat or "").strip()
        if value and value not in beats:
            beats.append(value)
        if len(beats) >= 5:
            break
    while len(beats) < 5:
        beats.append(f"Tình tiết {len(beats) + 1}")
    sequence = " → ".join(pattern or beats[:4])
    technical_profile = video_profile_catalog.technical_profile_for_profile(profile_key)
    creative = dict(video_scene3_flow.PROFILE_CREATIVE_GUIDANCE.get(technical_profile) or {})
    visual = str(creative.get("visual") or "Hình ảnh rõ chủ thể, nhất quán và phù hợp nội dung.")
    camera = str(creative.get("camera") or "Khung hình có điểm bắt đầu và điểm dừng tự nhiên.")
    motion = str(creative.get("motion") or "Mỗi cảnh có một chuyển động chính, hoàn tất trước khi chuyển cảnh.")
    avoid = str(creative.get("avoid") or "Không tự ý đổi nhận diện, vật thể hoặc ý nghĩa nội dung đã chọn.")
    suggestions: list[dict] = []
    for index, beat in enumerate(beats[:5], 1):
        full_prompt = "\n".join([
            f"Sản phẩm: {product_guidance['name']}",
            f"Loại nội dung: {profile_name}",
            f"Mục tiêu: {description}",
            f"Tình tiết số {index}: {beat}",
            f"Mạch nội dung: {sequence}",
            f"Quy tắc nguồn: {product_guidance['rule']}",
            f"Trọng tâm cảnh: {product_guidance['focus']}",
            f"Phong cách hình ảnh: {visual}",
            f"Máy quay: {camera}",
            f"Chuyển động: {motion}",
            f"Giới hạn: {avoid}",
            "Giọng đọc, nhạc, phụ đề, lồng tiếng và logo/watermark được chọn ở phần hậu kỳ riêng.",
        ])
        suggestions.append({
            "key": f"product_context_{index:02d}",
            "label": beat,
            "guidance": f"{profile_name}: {beat}. {product_guidance['focus']} {product_guidance['rule']}",
            "profile_key": profile_key,
            "profile_name": profile_name,
            "pattern": sequence,
            "category": category,
            "visual_prompt": full_prompt,
            "prompt": full_prompt,
            "prompt_blueprint": {
                "product": product,
                "profile_key": profile_key,
                "profile_name": profile_name,
                "beat": beat,
                "sequence": sequence,
                "source_rule": product_guidance["rule"],
                "focus": product_guidance["focus"],
                "visual": visual,
                "camera": camera,
                "motion": motion,
                "avoid": avoid,
            },
        })
    return suggestions


def video_uiflow3_apply_context_prompt(raw_state: dict, context_key: str) -> dict:
    """Save a product suggestion without replacing the original source."""

    state = video_uiflow3.normalize_state(raw_state)
    if str(state.get("parent_product") or "") == "video_ai_real":
        return video_ai_real_apply_context_prompt(state, context_key)
    selected = next(
        (
            item for item in video_uiflow3_profile_context_prompts(state)
            if str(item.get("key") or "") == str(context_key or "")
        ),
        None,
    )
    if not selected:
        raise ValueError("video_uiflow3_context_invalid")
    content = dict(state.get("content") or {})
    brief = dict(content.get("approved_brief") or {})
    brief.update({
        "context_suggestion_key": str(selected.get("key") or ""),
        "context_suggestion_label": str(selected.get("label") or ""),
        "context_guidance": str(selected.get("guidance") or ""),
        "visual_prompt": str(selected.get("visual_prompt") or ""),
        "prompt": str(selected.get("prompt") or ""),
        "prompt_blueprint": deepcopy(selected.get("prompt_blueprint") or {}),
    })
    return video_uiflow3.set_content_candidate(
        state,
        source=str(content.get("source") or "content_catalog"),
        original_intent=str(content.get("original_intent") or ""),
        profile_id=str(content.get("profile_id") or ""),
        idea_id=str(content.get("idea_id") or ""),
        approved_brief=brief,
    )


def video_ai_real_round_sale_xu(value) -> int:
    return video_ai_real_pricing.round_sale_xu(value)


def video_ai_real_prompt_model_catalog() -> list[dict]:
    return video_ai_real_pricing.model_catalog()


VIDEO_AI_REAL_QUALITY_MODEL_KEYS = dict(video_ai_real_pricing.QUALITY_TIER_MODEL_KEYS)


def video_public_quality_product(tier_id: int) -> dict:
    selected_id = safe_int(tier_id, 0)
    model_key = VIDEO_AI_REAL_QUALITY_MODEL_KEYS.get(selected_id)
    if not model_key:
        raise ValueError("video_quality_invalid")
    internal_model = video_ai_real_pricing.model_by_key(model_key)
    public_product = video_ai_real_pricing.public_quality_by_tier(selected_id)
    return {
        **public_product,
        "model_key": model_key,
        "internal_model": deepcopy(internal_model),
    }


def video_ai_real_quality_products(raw_state: dict) -> list[dict]:
    """Return public quality packages without exposing internal routing."""

    state = video_uiflow3.normalize_state(raw_state)
    if str(state.get("parent_product") or "") != "video_ai_real":
        raise ValueError("video_ai_real_quality_required")
    scene_count = max(
        1,
        len(state.get("scenes") or []),
        safe_int((state.get("format") or {}).get("scene_count"), 0),
    )
    required_capability = (
        "image_to_video"
        if str(state.get("entry_mode") or "") == "image_video"
        else "text_to_video"
    )
    compatible_offers = video_uifreeze1.compatible_quality_tiers(
        "video_ai_real",
        scene_count=scene_count,
        ratio=str((state.get("format") or {}).get("ratio") or "9:16"),
        required_capability=required_capability,
    )
    offers_by_tier = {
        safe_int(item.get("tier_id"), 0): dict(item)
        for item in compatible_offers
    }
    products: list[dict] = []
    for tier_id in VIDEO_AI_REAL_QUALITY_MODEL_KEYS:
        if tier_id not in offers_by_tier:
            continue
        product = video_public_quality_product(tier_id)
        product.pop("internal_model", None)
        products.append(product)
    return sorted(
        products,
        key=lambda item: (
            safe_int(item.get("unit_xu"), 0),
            safe_int(item.get("seconds"), 0),
            safe_int(item.get("tier_id"), 0),
        ),
    )


def video_ai_real_apply_quality_product(raw_state: dict, tier_id: int) -> dict:
    state = video_uiflow3.normalize_state(raw_state)
    selected_id = safe_int(tier_id, 0)
    quality = next(
        (item for item in video_ai_real_quality_products(state) if item["tier_id"] == selected_id),
        None,
    )
    if not quality:
        raise ValueError("video_ai_real_quality_invalid")
    model = video_ai_real_pricing.model_by_key(
        VIDEO_AI_REAL_QUALITY_MODEL_KEYS[selected_id]
    )
    seconds = max(1, safe_int(quality.get("seconds"), 1))
    scene_count = max(
        1,
        len(state.get("scenes") or []),
        safe_int((state.get("format") or {}).get("scene_count"), 0),
    )
    state["format"]["seconds_per_scene"] = seconds
    state["format"]["target_duration_seconds"] = scene_count * seconds
    for scene in state.get("scenes") or []:
        scene["duration_target"] = seconds
    _legacy, commercial = _video_ai_real_commercial_state(state)
    commercial["quality"] = deepcopy(quality)
    commercial["model"] = {
        **deepcopy(model),
        "unit_xu": safe_int(quality.get("unit_xu"), model.get("unit_xu")),
        "seconds": seconds,
    }
    dirty = list((state.get("navigation") or {}).get("dirty_sections") or [])
    state["navigation"]["dirty_sections"] = list(dict.fromkeys([
        *dirty,
        "prompts",
        "summary",
    ]))
    if state.get("render_contract") and video_ai_real_is_prompt_pilot(state):
        return video_ai_real_compile_state(state)
    return video_uiflow3.normalize_state(state)


def _video_ai_real_pilot_state(raw_state: dict) -> dict:
    state = video_uiflow3.normalize_state(raw_state)
    if (
        str(state.get("parent_product") or "") != "video_ai_real"
        or str(state.get("entry_mode") or "")
        not in video_uiflow3.VIDEO_AI_REAL_PRODUCT_FIRST_MODES
    ):
        raise ValueError("video_ai_real_creation_flow_required")
    return state


def _video_ai_real_commercial_state(state: dict) -> tuple[dict, dict]:
    legacy = dict(state.get("legacy_compat") or {})
    commercial = dict(legacy.get("pilot_commercial") or {})
    legacy["pilot_commercial"] = commercial
    state["legacy_compat"] = legacy
    return legacy, commercial


def _video_ai_real_visual_contract_is_current(state: dict) -> bool:
    existing_hash = str(
        ((state.get("render_contract") or {}).get("visual") or {}).get("visual_hash")
        or ""
    )
    if not existing_hash:
        return False
    try:
        current = video_ai_real_prompt_compiler.compile_render_contract(state)
    except (KeyError, TypeError, ValueError):
        return False
    current_hash = str((current.get("visual") or {}).get("visual_hash") or "")
    return bool(current_hash and current_hash == existing_hash)


def video_ai_real_mark_post_only_change(raw_state: dict) -> dict:
    state = video_uiflow3.normalize_state(raw_state)
    if not video_ai_real_is_prompt_pilot(state):
        return state
    dirty = list((state.get("navigation") or {}).get("dirty_sections") or [])
    if "prompts" in dirty and _video_ai_real_visual_contract_is_current(state):
        dirty = [item for item in dirty if item != "prompts"]
    state["navigation"]["dirty_sections"] = list(dict.fromkeys([
        *dirty,
        "audio",
        "summary",
    ]))
    return video_uiflow3.normalize_state(state)


def video_ai_real_apply_context_prompt(raw_state: dict, context_key: str) -> dict:
    state = _video_ai_real_pilot_state(raw_state)
    key = str(context_key or "").strip()
    profile_prompt = next(
        (
            item
            for item in video_ai_real_profile_context_prompts(state)
            if str(item.get("key") or "") == key
        ),
        {},
    )
    if profile_prompt:
        label = str(profile_prompt.get("label") or "")
        guidance = str(profile_prompt.get("guidance") or "")
        visual_prompt = str(profile_prompt.get("visual_prompt") or guidance)
        full_prompt = str(profile_prompt.get("prompt") or visual_prompt)
        prompt_blueprint = deepcopy(dict(profile_prompt.get("prompt_blueprint") or {}))
        context_profile_id = str(profile_prompt.get("profile_key") or "")
    else:
        label, guidance = VIDEO_AI_REAL_CONTEXT_PROMPTS.get(key, ("", ""))
        visual_prompt = guidance
        full_prompt = guidance
        prompt_blueprint = {}
        context_profile_id = "legacy"
    if not visual_prompt:
        raise ValueError("video_ai_real_context_invalid")
    _legacy, commercial = _video_ai_real_commercial_state(state)
    current_intent = str((state.get("content") or {}).get("original_intent") or "").strip()
    previous_applied = str(commercial.get("context_applied_intent") or "").strip()
    stored_base = str(commercial.get("context_base_intent") or "").strip()
    base_intent = stored_base if current_intent == previous_applied and stored_base else current_intent
    if not base_intent:
        raise ValueError("content_candidate_required")
    contextual_intent = f"{base_intent}\n\nGợi ý triển khai đã chọn:\n{visual_prompt}"
    commercial.update({
        "context_key": key,
        "context_label": label,
        "context_profile_id": context_profile_id,
        "context_prompt": full_prompt,
        "context_visual_prompt": visual_prompt,
        "context_prompt_blueprint": prompt_blueprint,
        "context_base_intent": base_intent,
        "context_applied_intent": contextual_intent,
    })
    brief = dict((state.get("content") or {}).get("approved_brief") or {})
    brief.update({
        "selected_context_key": key,
        "selected_context_label": label,
        "selected_context_prompt": full_prompt,
        "profile_prompt_blueprint": prompt_blueprint,
    })
    state["content"]["approved_brief"] = brief
    if bool((state.get("content") or {}).get("locked")):
        state = video_uiflow3.revise_content(state, original_intent=contextual_intent)
    else:
        state["content"]["original_intent"] = contextual_intent
    return video_uiflow3.normalize_state(state)


def video_ai_real_confirm_preselected_scene_count(raw_state: dict) -> dict:
    """Materialize the scene count selected at product intake without asking twice."""

    state = video_uiflow3.normalize_state(raw_state)
    if (
        not video_ai_real_is_creation_flow(state)
        or not bool((state.get("content") or {}).get("locked"))
        or bool(state.get("scenes"))
    ):
        return state
    scene_count = safe_int((state.get("format") or {}).get("scene_count"), 0)
    if scene_count <= 0:
        return state
    previous_step = str((state.get("navigation") or {}).get("current_step") or "content_lock")
    previous_stack = list((state.get("navigation") or {}).get("visible_step_stack") or [])
    seconds = max(1, safe_int((state.get("format") or {}).get("seconds_per_scene"), 8))
    state["format"]["target_duration_seconds"] = scene_count * seconds
    state = video_uiflow3.confirm_scene_count(state, scene_count)
    state["navigation"]["current_step"] = previous_step
    state["navigation"]["visible_step_stack"] = previous_stack
    return video_uiflow3.normalize_state(state)


def video_ai_real_apply_prompt_model(raw_state: dict, model_key: str) -> dict:
    state = _video_ai_real_pilot_state(raw_state)
    model = video_ai_real_pricing.model_by_key(model_key)
    seconds = max(1, safe_int(model.get("seconds"), 1))
    scene_count = max(
        len(state.get("scenes") or []),
        safe_int((state.get("format") or {}).get("scene_count"), 0),
    )
    state["format"]["seconds_per_scene"] = seconds
    state["format"]["target_duration_seconds"] = scene_count * seconds
    for scene in state.get("scenes") or []:
        scene["duration_target"] = seconds
    _legacy, commercial = _video_ai_real_commercial_state(state)
    commercial["model"] = deepcopy(model)
    dirty = list((state.get("navigation") or {}).get("dirty_sections") or [])
    state["navigation"]["dirty_sections"] = list(dict.fromkeys([
        *dirty,
        "prompts",
        "summary",
    ]))
    if state.get("render_contract"):
        return video_ai_real_compile_state(state)
    return video_uiflow3.normalize_state(state)


def video_ai_real_apply_default_voice_plan(
    raw_state: dict,
    *,
    enable_dubbing: bool = True,
) -> dict:
    """Bind dialogue owners to the same verified default voices used by B14."""

    state = _video_ai_real_pilot_state(raw_state)
    bible = dict(state.get("bible") or {})
    characters = list(bible.get("characters") or [])
    narrator = dict(bible.get("narrator") or {})
    dialogue_rows = [
        dict(item)
        for item in (state.get("audio") or {}).get("dialogue_segments") or []
        if isinstance(item, dict) and str(item.get("text") or "").strip()
    ]
    owner_ids = list(dict.fromkeys(
        str(item.get("speaker_id") or "")
        for item in dialogue_rows
        if str(item.get("speaker_id") or "")
    ))
    if str((state.get("needs") or {}).get("voice") or "") == "REQUIRED":
        owner_ids = list(dict.fromkeys([
            *owner_ids,
            *[
                str(item.get("character_id") or "")
                for item in characters
                if str(item.get("character_id") or "")
            ],
            str(narrator.get("narrator_id") or ""),
        ]))
        owner_ids = [item for item in owner_ids if item]

    character_map = {
        str(item.get("character_id") or ""): item
        for item in characters
        if str(item.get("character_id") or "")
    }
    voice_cast = dict((state.get("audio") or {}).get("voice_cast") or {})
    for owner_id in owner_ids:
        owner = character_map.get(owner_id) or (
            narrator if str(narrator.get("narrator_id") or "") == owner_id else {}
        )
        gender = str(owner.get("gender") or "unspecified")
        voice_id = default_tts_voice_id(gender)
        if owner:
            owner["voice_id"] = voice_id
        voice_cast[owner_id] = {
            "voice_id": voice_id,
            "gender": gender,
            "server_renderable": True,
            "source": "default_tts_voice",
        }

    state["bible"]["characters"] = characters
    if narrator:
        state["bible"]["narrator"] = narrator
    state["audio"]["voice_cast"] = voice_cast
    state["audio"]["dubbing_mode"] = "default_ai" if enable_dubbing else "none"
    return video_ai_real_mark_post_only_change(state)


def video_ai_real_apply_audio_option(raw_state: dict, option: str, value: str) -> dict:
    state = _video_ai_real_pilot_state(raw_state)
    key = str(option or "").strip()
    selected = str(value or "").strip()
    allowed = {
        "music": {"none", "library_whole", "library_scene", "ai_whole", "ai_scene"},
        "subtitle": {"none", "script", "auto"},
        "dubbing": {"none", "browser", "default_ai"},
        "sfx": {"none", "library", "ai"},
    }
    if selected not in allowed.get(key, set()):
        raise ValueError("video_ai_real_audio_option_invalid")
    audio = state["audio"]
    if key == "music":
        if selected == "none":
            scope, source = "none", "none"
        else:
            scope = "per_scene" if selected.endswith("_scene") else "whole_video"
            source = "ai" if selected.startswith("ai_") else "library"
        audio.update({"music_scope": scope, "music_source": source, "music_plan": {}})
        for scene in state.get("scenes") or []:
            scene["music_policy"] = "off" if scope == "none" else "inherit"
    elif key == "dubbing" and selected == "default_ai":
        if not any(
            isinstance(item, dict) and str(item.get("text") or "").strip()
            for item in audio.get("dialogue_segments") or []
        ):
            raise ValueError("dialogue_required")
        return video_ai_real_apply_default_voice_plan(state)
    else:
        field = {
            "subtitle": "subtitle_mode",
            "dubbing": "dubbing_mode",
            "sfx": "sfx_mode",
        }[key]
        audio[field] = selected
    return video_ai_real_mark_post_only_change(state)


def video_ai_real_scene_music_return_callback(state: dict, scene_id: str) -> str:
    if str(state.get("ui_view") or "") == "audio_music_scenes":
        return "vid3|view|audio_music_scenes"
    pending = dict(state.get("pending_input") or {})
    return str(
        state.get("ui_return_callback")
        or pending.get("ui_return_callback")
        or f"vid3|scene|{scene_id}"
    )


def video_ai_real_prompt_quote(raw_state: dict) -> dict:
    state = _video_ai_real_pilot_state(raw_state)
    commercial = dict((state.get("legacy_compat") or {}).get("pilot_commercial") or {})
    model = dict(commercial.get("model") or {})
    quality = dict(commercial.get("quality") or {})
    if not model:
        raise ValueError("video_ai_real_model_required")
    scenes = list(state.get("scenes") or [])
    scene_count = len(scenes) or safe_int((state.get("format") or {}).get("scene_count"), 0)
    if scene_count <= 0:
        raise ValueError("scene_count_out_of_range")
    seconds = max(1, safe_int(quality.get("seconds") or model.get("seconds"), 1))
    total_duration = scene_count * seconds
    unit_xu = max(0, safe_int(quality.get("unit_xu") or model.get("unit_xu"), 0))
    scene_price = video_ai_real_pricing.video_multiscene_price(unit_xu, scene_count)
    base_xu = int(scene_price["total_xu"])
    audio = dict(state.get("audio") or {})
    addons: list[dict] = []

    def add(key: str, label: str, price_xu: int) -> None:
        price = max(0, safe_int(price_xu, 0))
        if price:
            addons.append({"key": key, "label": label, "price_xu": price})

    music_scope = str(audio.get("music_scope") or "none")
    if str(audio.get("music_source") or "") == "ai" and music_scope != "none":
        if music_scope == "per_scene" and scenes:
            music_plan = dict(audio.get("music_plan") or {})
            tracks = sum(
                1
                for scene in scenes
                if str(
                    (music_plan.get(str(scene.get("scene_id") or "")) or {}).get("policy")
                    or scene.get("music_policy")
                    or "inherit"
                ) != "off"
            )
        else:
            tracks = scene_count if music_scope == "per_scene" else 1
        per_track = video_ai_real_pricing.music_model_catalog()[0]["unit_xu"]
        music_label = "Nhạc AI theo từng cảnh" if music_scope == "per_scene" else "Nhạc AI toàn video"
        add("music_ai", music_label, tracks * safe_int(per_track, 0))
    if str(audio.get("subtitle_mode") or "none") == "auto":
        add("subtitle_auto", "Phụ đề tự động", calculate_named_addon_quote("subtitle_auto", total_duration).get("total_xu") or 0)
    if str(audio.get("dubbing_mode") or "none") == "default_ai":
        add("dubbing_default", "Lồng tiếng AI mặc định", calculate_named_addon_quote("dubbing_default", total_duration).get("total_xu") or 0)
    if str(audio.get("sfx_mode") or "none") == "ai":
        add("sfx_ai", "Hiệu ứng âm thanh AI", calculate_named_addon_quote("sfx_ai", total_duration).get("total_xu") or 0)

    addons_xu = sum(int(item["price_xu"]) for item in addons)
    total_xu = base_xu + addons_xu
    return {
        "model": model,
        "quality": quality,
        "scene_count": scene_count,
        "seconds_per_scene": seconds,
        "total_duration_seconds": total_duration,
        "unit_xu": unit_xu,
        "subtotal_xu": int(scene_price["subtotal_xu"]),
        "discount_percent": int(scene_price["discount_percent"]),
        "discount_xu": int(scene_price["discount_xu"]),
        "base_xu": base_xu,
        "addons": addons,
        "addons_xu": addons_xu,
        "total_xu": total_xu,
        "estimated_vnd": total_xu * 100,
        "provider_priority": list(model.get("provider_priority") or []),
        "pricing_provider": str(model.get("pricing_provider") or ""),
        "quote_only": True,
    }


def video_tail9_addon_quote(raw_tail: dict | None = None) -> dict:
    """Price only the explicit post-production choices carried by Tail9."""

    tail = video_tail9.normalize_state(dict(raw_tail or {}))
    audio = dict(tail.get("audio_config") or {})
    addon_config = dict(tail.get("addon_config") or {})
    entries = {
        str(key): dict(value)
        for key, value in dict(addon_config.get("postprocessing") or {}).items()
        if isinstance(value, dict)
    }
    duration = max(1, safe_int(tail.get("estimated_duration"), 8))
    items: list[dict] = []

    def value_for(key: str) -> dict:
        entry = dict(entries.get(key) or {})
        return dict(entry.get("value") or {}) if isinstance(entry.get("value"), dict) else {}

    def selected(key: str) -> bool:
        entry = dict(entries.get(key) or {})
        return bool(entry.get("enabled", audio.get(key)))

    def add_item(key: str, label: str, price_xu: int = 0) -> None:
        if any(str(item.get("key") or "") == key for item in items):
            return
        items.append({
            "key": key,
            "label": label,
            "price_xu": max(0, safe_int(price_xu, 0)),
        })

    if selected("source_audio"):
        add_item("source_audio", "Giữ âm thanh gốc", 0)

    if selected("dubbing"):
        dubbing_price = calculate_named_addon_quote(
            "dubbing_default", duration
        ).get("total_xu") or 0
        add_item("dubbing_default", "Lồng tiếng", dubbing_price)

    if selected("subtitles"):
        subtitle_value = value_for("subtitles")
        translated = bool(
            subtitle_value.get("translation")
            or str(subtitle_value.get("source") or "").lower()
            in {"translated", "auto_translate", "translation"}
        )
        quote_key = "subtitle_translate" if translated else "subtitle_auto"
        subtitle_quote = calculate_named_addon_quote(quote_key, duration)
        add_item(
            quote_key,
            "Dịch phụ đề" if translated else "Tạo phụ đề tự động",
            subtitle_quote.get("total_xu") or 0,
        )

    if selected("music"):
        music_value = value_for("music")
        music_source = str(
            music_value.get("source")
            or music_value.get("music_source")
            or music_value.get("music_source_choice")
            or ""
        ).strip().lower()
        paid_music = bool(
            music_value.get("paid_generation")
            or music_source
            in {"ai", "create_new", "planned_generation", "generated", "music_ai"}
        )
        if paid_music:
            music_price = safe_int(
                video_ai_real_pricing.music_model_catalog()[0].get("unit_xu"),
                0,
            )
            add_item("music_ai", "Tạo nhạc bằng AI", music_price)
        else:
            add_item("music_existing", "Nhạc nền từ kho hoặc tệp đã gửi", 0)

    if selected("sfx"):
        sfx_value = value_for("sfx")
        sfx_source = str(
            sfx_value.get("source") or sfx_value.get("sfx_source") or ""
        ).strip().lower()
        paid_sfx = bool(
            sfx_value.get("paid_generation")
            or sfx_source in {"ai", "planned_generation", "generated", "sfx_ai"}
        )
        if paid_sfx:
            sfx_quote = calculate_named_addon_quote("sfx_ai", duration)
            add_item(
                "sfx_ai",
                "Tạo hiệu ứng âm thanh bằng AI",
                sfx_quote.get("total_xu") or 0,
            )
        else:
            add_item("sfx_library", "Hiệu ứng âm thanh từ kho", 0)

    total_xu = sum(max(0, safe_int(item.get("price_xu"), 0)) for item in items)
    return {
        "items": items,
        "total_xu": total_xu,
        "duration_seconds": duration,
    }


def video_ai_real_is_creation_flow(raw_state: dict) -> bool:
    return bool(
        str((raw_state or {}).get("parent_product") or "") == "video_ai_real"
        and str((raw_state or {}).get("entry_mode") or "")
        in video_uiflow3.VIDEO_AI_REAL_PRODUCT_FIRST_MODES
    )


VIDEO_UIFLOW3_SHARED_TAIL_PRODUCTS = frozenset({
    "video_ai_real",
    "video_trend",
    "script_image_video",
    "storyboard_prompt",
    "multi_scene_film",
})

VIDEO_TAIL9_SHARED_UI_PRODUCTS = frozenset({
    *VIDEO_UIFLOW3_SHARED_TAIL_PRODUCTS,
    "self_shot_scene_change",
    "self_shot_cinematic_transform",
})

VIDEO_UIFLOW3_DEFERRED_RUNTIME_PRODUCTS = frozenset({
    "video_ai_real",
    "video_trend",
    "script_image_video",
    "storyboard_prompt",
    "multi_scene_film",
})

VIDEO_TAIL9_DEFERRED_RUNTIME_PRODUCTS = frozenset({
    *VIDEO_UIFLOW3_DEFERRED_RUNTIME_PRODUCTS,
    "self_shot_scene_change",
    "self_shot_cinematic_transform",
    "video_long",
})


def video_uiflow3_execution_adapter(raw_state: dict) -> dict:
    """Resolve one UIFLOW3 product to its real, product-specific executor."""

    state = video_uiflow3.normalize_state(raw_state)
    product = str(state.get("parent_product") or "")
    commercial = video_tail9.commercial_contract(product)
    kind = {
        "frame_video_local": "frame_video",
        "self_shot_scene_change": "selfshot2",
    }.get(product, "product_tail" if product in VIDEO_UIFLOW3_SHARED_TAIL_PRODUCTS else "planning_only")
    if (
        not bool(commercial.get("execution_enabled", True))
        and product not in VIDEO_UIFLOW3_DEFERRED_RUNTIME_PRODUCTS
    ):
        kind = "planning_only"
    return {
        "kind": kind,
        "product_type": product,
        "engine_route": str(commercial.get("engine_route") or ""),
        "executor_product_type": str(commercial.get("executor_product_type") or product),
        "required_capability": str(commercial.get("required_capability") or ""),
        "input_type": str(commercial.get("input_type") or ""),
        "worker_owner": str(commercial.get("worker_owner") or ""),
        "execution_enabled": bool(commercial.get("execution_enabled", True)),
        "execution_blocker": str(commercial.get("execution_blocker") or ""),
    }


def video_uiflow3_snapshot_revision(snapshot: dict) -> int:
    token = str((snapshot or {}).get("config_hash") or "")[:12]
    try:
        return max(1, int(token, 16))
    except (TypeError, ValueError):
        return 1


def video_uiflow3_snapshot_assets(snapshot: dict) -> list[dict]:
    seen: set[str] = set()
    rows: list[dict] = []
    for raw in [
        *list(((snapshot or {}).get("source") or {}).get("assets") or []),
        *list((snapshot or {}).get("references") or []),
    ]:
        item = dict(raw or {})
        file_id = str(item.get("telegram_file_id") or item.get("file_id") or "").strip()
        if not file_id or file_id in seen:
            continue
        seen.add(file_id)
        metadata = dict(item.get("metadata") or {})
        rows.append({
            **metadata,
            **item,
            "file_id": file_id,
            "file_unique_id": str(item.get("file_unique_id") or metadata.get("file_unique_id") or ""),
            "file_size": safe_int(item.get("file_size") or metadata.get("file_size"), 0),
            "mime_type": str(item.get("mime_type") or metadata.get("mime_type") or ""),
        })
    return rows


def claim_video_uiflow3_tail_owner(context, raw_state: dict) -> dict:
    state = video_uiflow3.normalize_state(raw_state)
    claim = {
        "owner": "uiflow3",
        "draft_id": str(state.get("draft_id") or ""),
        "product_type": str(state.get("parent_product") or ""),
    }
    if isinstance(getattr(context, "user_data", None), dict):
        context.user_data[VIDEO_UIFLOW3_ACTIVE_TAIL_KEY] = claim
    return claim


def video_uiflow3_build_tail_state(raw_state: dict) -> dict:
    state = video_uiflow3.normalize_state(raw_state)
    route = video_uiflow3_execution_adapter(state)
    if route["kind"] != "product_tail":
        raise ValueError("video_uiflow3_shared_tail_not_supported")
    snapshot = video_uiflow3.approved_snapshot(state)
    scenes = [dict(item or {}) for item in snapshot.get("scenes") or []]
    content = dict(snapshot.get("content") or {})
    fmt = dict(snapshot.get("format") or {})
    assets = video_uiflow3_snapshot_assets(snapshot)
    scene_seconds = max(1, safe_int(fmt.get("seconds_per_scene"), 8))
    duration = sum(
        max(1, safe_int(item.get("duration_target"), scene_seconds))
        for item in scenes
    ) or scene_seconds
    revision = video_uiflow3_snapshot_revision(snapshot)
    existing = dict(state.get(VIDEO_TAIL9_STATE_KEY) or {})
    same_draft_existing = bool(
        str(existing.get("video_product_type") or "") == str(route["product_type"])
        and str(existing.get("video_session_id") or "")
        == str(snapshot.get("draft_id") or "")
    )
    same_scope_existing = video_tail9.scope_matches(
        existing,
        product_type=route["product_type"],
        session_id=str(snapshot.get("draft_id") or ""),
        plan_revision=revision,
    )
    if same_scope_existing:
        tail = video_tail9.normalize_state(existing)
    else:
        tail = video_tail9.new_state(
            product_type=route["product_type"],
            session_id=str(snapshot.get("draft_id") or ""),
            plan_revision=revision,
            scene_count=max(1, len(scenes)),
            ratio=str(fmt.get("ratio") or "9:16"),
            estimated_duration=duration,
            source_asset_ids=[str(item.get("file_id") or "") for item in assets],
            return_to="vid3|resume",
        )
        if same_draft_existing:
            for field in (
                "audio_config",
                "audio_status",
                "addon_config",
                "logo_config",
                "logo_status",
                "watermark_config",
                "watermark_status",
            ):
                if field in existing:
                    tail[field] = deepcopy(existing[field])
    tail["video_flow_owner"] = "uiflow3"
    tail["return_to"] = "vid3|resume"
    scene_contract = []
    approved_brief = dict(content.get("approved_brief") or {})
    detailed_prompt = str(approved_brief.get("prompt") or approved_brief.get("visual_prompt") or "").strip()
    fallback_prompt = detailed_prompt or str(content.get("original_intent") or "").strip()
    for item in scenes:
        scene = dict(item)
        scene_prompt = str(
            scene.get("provider_prompt")
            or scene.get("prompt_override")
            or scene.get("visual_prompt")
            or scene.get("semantic_beat")
            or scene.get("main_action")
            or fallback_prompt
        ).strip()
        if detailed_prompt and scene_prompt and scene_prompt not in detailed_prompt:
            scene_prompt = f"{detailed_prompt}\nCảnh {scene.get('scene_index') or len(scene_contract) + 1}: {scene_prompt}"
        scene["provider_prompt"] = scene_prompt
        scene_contract.append(scene)
    tail = video_tail9.apply_content_contract(tail, {
        "content_source": str(content.get("source") or "manual"),
        "canonical_content_mode": str(state.get("entry_mode") or (snapshot.get("source") or {}).get("kind") or ""),
        "selected_prompt": fallback_prompt,
        "scene_drafts": scene_contract,
        "content_revision": safe_int(content.get("revision"), 1),
        "plan_revision": revision,
        "plan_status": "approved",
        "plan_approved": True,
    })
    audio_source = dict(snapshot.get("audio") or {})
    audio = dict(tail.get("audio_config") or {})
    audio.update({
        "source_audio": False,
        "dubbing": str(audio_source.get("dubbing_mode") or "none") != "none",
        "music": str(audio_source.get("music_scope") or "none") != "none",
        "sfx": str(audio_source.get("sfx_mode") or "none") != "none",
        "subtitles": str(audio_source.get("subtitle_mode") or "none") != "none",
    })
    tail["audio_config"] = audio
    music_source = str(audio_source.get("music_source") or "none").strip().lower()
    sfx_mode = str(audio_source.get("sfx_mode") or "none").strip().lower()
    subtitle_mode = str(audio_source.get("subtitle_mode") or "none").strip().lower()
    dubbing_mode = str(audio_source.get("dubbing_mode") or "none").strip().lower()
    addon_config = dict(tail.get("addon_config") or {})
    addon_config["technical_profile"] = video_profile_catalog.technical_profile_for_profile(
        str(content.get("profile_id") or "")
    )
    addon_config["postprocessing"] = {
        "dubbing": {
            "enabled": dubbing_mode != "none",
            "value": {
                "dubbing_mode": dubbing_mode,
                "voice_source": dubbing_mode,
            },
        },
        "subtitles": {
            "enabled": subtitle_mode != "none",
            "value": {
                "source": subtitle_mode,
                "translation": subtitle_mode in {"translated", "auto_translate"},
            },
        },
        "music": {
            "enabled": str(audio_source.get("music_scope") or "none") != "none",
            "value": {
                "source": "planned_generation" if music_source == "ai" else music_source,
                "paid_generation": music_source == "ai",
                "music_scope": str(audio_source.get("music_scope") or "none"),
            },
        },
        "sfx": {
            "enabled": sfx_mode != "none",
            "value": {
                "source": "ai" if sfx_mode == "ai" else "library_only",
                "paid_generation": sfx_mode == "ai",
            },
        },
    }
    tail["addon_config"] = addon_config
    tail["audio_status"] = "configured" if any(
        bool(audio.get(key)) for key in ("dubbing", "music", "sfx", "subtitles")
    ) else "skipped"
    if not same_scope_existing:
        branding = dict(snapshot.get("branding") or {})
        logo = dict(branding.get("logo") or {})
        watermark = dict(branding.get("watermark") or {})
        logo_file_id = str(logo.get("telegram_file_id") or logo.get("file_id") or "")
        watermark_text = str(watermark.get("text") or "").strip()
        tail["logo_config"] = {
            "enabled": bool(logo_file_id),
            "asset_file_id": logo_file_id,
            "file_size": safe_int(logo.get("file_size"), 0),
            "position": str(logo.get("position") or "") if logo_file_id else "",
        }
        tail["watermark_config"] = {
            "enabled": bool(watermark_text),
            "text": watermark_text,
            "position": str(watermark.get("position") or "") if watermark_text else "",
            "opacity_percent": max(0, min(100, safe_int(watermark.get("opacity_percent"), 45))),
        }
        tail["logo_status"] = (
            "configured"
            if logo_file_id and tail["logo_config"]["position"]
            else "not_configured"
            if logo_file_id
            else "skipped"
        )
        tail["watermark_status"] = (
            "configured"
            if watermark_text and tail["watermark_config"]["position"]
            else "not_configured"
            if watermark_text
            else "skipped"
        )
    return video_tail9.prepare_summary(tail)


def video_uiflow3_build_frame_state(raw_state: dict) -> dict:
    state = video_uiflow3.normalize_state(raw_state)
    if video_uiflow3_execution_adapter(state)["kind"] != "frame_video":
        raise ValueError("video_uiflow3_frame_handoff_not_supported")
    snapshot = video_uiflow3.approved_snapshot(state)
    source_rows = [
        item for item in video_uiflow3_snapshot_assets(snapshot)
        if str(item.get("asset_type") or "").lower() in {"frame", "image", "photo"}
        or str(item.get("mime_type") or "").lower().startswith("image/")
    ]
    if len(source_rows) < frame_video_runtime.FRAME_VIDEO_MIN_IMAGES:
        raise ValueError("frame_video_minimum_images_required")
    fmt = dict(snapshot.get("format") or {})
    branding = dict(snapshot.get("branding") or {})
    logo = dict(branding.get("logo") or {})
    watermark = dict(branding.get("watermark") or {})
    frame = frame_video3_new_state("uploaded")
    frame.update({
        "step": "quality",
        "photos": source_rows[:frame_video_runtime.FRAME_VIDEO_MAX_IMAGES],
        "image_count": min(len(source_rows), frame_video_runtime.FRAME_VIDEO_MAX_IMAGES),
        "ratio": str(fmt.get("ratio") or "9:16").replace(":", "x"),
        "seconds_per_image": float(max(1, safe_int(fmt.get("seconds_per_scene"), 3))),
        "duration_confirmed": True,
        "logo_enabled": bool(logo.get("telegram_file_id") or logo.get("file_id")),
        "logo_file_id": str(logo.get("telegram_file_id") or logo.get("file_id") or ""),
        "logo_position": str(logo.get("position") or "top_right"),
        "watermark_enabled": bool(str(watermark.get("text") or "").strip()),
        "watermark_text": str(watermark.get("text") or "").strip(),
        "watermark_position": str(watermark.get("position") or "bottom_right"),
        "uiflow3_draft_id": str(snapshot.get("draft_id") or ""),
        "uiflow3_config_hash": str(snapshot.get("config_hash") or ""),
        "uiflow3_return_to": "vid3|resume",
        "uiflow3_approved_snapshot": snapshot,
    })
    return normalize_frame_video_state(frame)


def video_uiflow3_build_selfshot2_handoff(raw_state: dict) -> dict:
    state = video_uiflow3.normalize_state(raw_state)
    if video_uiflow3_execution_adapter(state)["kind"] != "selfshot2":
        raise ValueError("video_uiflow3_selfshot_handoff_not_supported")
    snapshot = video_uiflow3.approved_snapshot(state)
    source_rows = [
        item for item in video_uiflow3_snapshot_assets(snapshot)
        if str(item.get("asset_type") or "").lower() in {"source_video", "video"}
        or str(item.get("mime_type") or "").lower().startswith("video/")
    ]
    source = dict(source_rows[-1] if source_rows else {})
    metadata = dict(source.get("metadata") or {})
    source_video = {
        **metadata,
        **source,
        "file_id": str(source.get("file_id") or source.get("telegram_file_id") or ""),
        "file_unique_id": str(source.get("file_unique_id") or metadata.get("file_unique_id") or ""),
        "duration_seconds": float(source.get("duration_seconds") or metadata.get("duration_seconds") or 0),
        "width": safe_int(source.get("width") or metadata.get("width"), 0),
        "height": safe_int(source.get("height") or metadata.get("height"), 0),
    }
    analysis = video_selfshot2.analyze_source(source_video)
    gate = video_selfshot2.source_gate(source_video, analysis)
    if not gate.get("ok"):
        return {"ok": False, "blocker": str(gate.get("blocker") or "source_video_probe_missing"), "draft": {}}
    content = dict(snapshot.get("content") or {})
    branding = dict(snapshot.get("branding") or {})
    logo = dict(branding.get("logo") or {})
    watermark = dict(branding.get("watermark") or {})
    draft = video_selfshot2.initial_draft()
    draft.update({
        "session_id": str(snapshot.get("draft_id") or ""),
        "revision": video_uiflow3_snapshot_revision(snapshot),
        "source_video": source_video,
        "source_analysis": analysis,
        "scene_count": max(1, len(snapshot.get("scenes") or [])),
        "aspect_ratio": str((snapshot.get("format") or {}).get("ratio") or analysis.get("aspect_ratio") or "9:16"),
        "content_source": str(content.get("source") or "manual"),
        "selected_content": {
            **dict(content.get("approved_brief") or {}),
            "summary": str(content.get("original_intent") or ""),
        },
        "scene_plan": [dict(item or {}) for item in snapshot.get("scenes") or []],
        "uiflow3_draft_id": str(snapshot.get("draft_id") or ""),
        "uiflow3_config_hash": str(snapshot.get("config_hash") or ""),
        "uiflow3_return_to": "vid3|resume",
        "uiflow3_approved_snapshot": snapshot,
    })
    draft["visual_addons"] = {
        "logo": {
            "enabled": bool(logo.get("telegram_file_id") or logo.get("file_id")),
            "file_id": str(logo.get("telegram_file_id") or logo.get("file_id") or ""),
            "file_unique_id": str(logo.get("file_unique_id") or ""),
            "position": str(logo.get("position") or "top_right"),
        },
        "watermark": {
            "enabled": bool(str(watermark.get("text") or "").strip()),
            "text": str(watermark.get("text") or "").strip(),
            "position": str(watermark.get("position") or "bottom_right"),
        },
    }
    return {"ok": True, "blocker": "", "draft": draft}


def video_uiflow3_b14_storyboard_payload(raw_state: dict) -> dict:
    """Translate the approved UI plan into the existing real Product Video seam."""

    state = video_uiflow3.normalize_state(raw_state)
    snapshot = video_uiflow3.approved_snapshot(state)
    content = dict(snapshot.get("content") or {})
    brief = dict(content.get("approved_brief") or {})
    bible = dict(snapshot.get("production_bible") or {})
    audio = dict(snapshot.get("audio") or {})
    fmt = dict(snapshot.get("format") or {})
    product_route = video_uiflow3_execution_adapter(state)
    is_video_ai_real = video_ai_real_is_creation_flow(state)
    profile_key = str(content.get("profile_id") or "")
    profile_id = video_profile_scene1_b14_profile_id(profile_key)
    profile = video_profiles.get_video_profile(profile_id)
    characters = {
        str(item.get("character_id") or ""): str(item.get("display_name") or "")
        for item in bible.get("characters") or []
    }
    locations = {
        str(item.get("location_id") or ""): dict(item)
        for item in bible.get("locations") or []
    }
    dialogue_by_scene: dict[str, list[str]] = {}
    for item in audio.get("dialogue_segments") or []:
        scene_id = str(item.get("scene_id") or "")
        speaker = characters.get(str(item.get("speaker_id") or ""), "")
        text = str(item.get("text") or "").strip()
        if scene_id and text:
            dialogue_by_scene.setdefault(scene_id, []).append(
                f"{speaker}: {text}" if speaker else text
            )

    asset_items: list[dict] = []
    seen_file_ids: set[str] = set()
    for raw in [
        *list(snapshot.get("references") or []),
        *list((snapshot.get("source") or {}).get("assets") or []),
    ]:
        item = dict(raw or {})
        file_id = str(item.get("telegram_file_id") or item.get("file_id") or "").strip()
        if not file_id or file_id in seen_file_ids:
            continue
        seen_file_ids.add(file_id)
        asset_items.append({
            "asset_id": str(item.get("asset_id") or f"asset_{len(asset_items) + 1:02d}"),
            "file_id": file_id,
            "file_unique_id": str(item.get("file_unique_id") or ""),
            "type": str(item.get("asset_type") or "image"),
            "owner_type": str(item.get("owner_type") or "source"),
            "owner_id": str(item.get("owner_id") or ""),
            "role": str(item.get("role") or "reference"),
            "fingerprint": str(item.get("fingerprint") or f"telegram:{file_id}"),
            "allowed_scene_ids": [str(value) for value in item.get("allowed_scene_ids") or []],
        })
    ordered_source_assets = [
        item for item in asset_items
        if str(item.get("owner_type") or "") in {"raw_source", "source"}
        and not list(item.get("allowed_scene_ids") or [])
    ]
    if is_video_ai_real:
        ordered_source_assets = []
        for index, raw_source in enumerate(
            (snapshot.get("source") or {}).get("assets") or [],
            1,
        ):
            source_item = dict(raw_source or {})
            source_file_id = str(
                source_item.get("telegram_file_id")
                or source_item.get("file_id")
                or ""
            ).strip()
            if not source_file_id:
                continue
            ordered_source_assets.append({
                "asset_id": str(source_item.get("asset_id") or f"source_{index:02d}"),
                "file_id": source_file_id,
                "file_unique_id": str(source_item.get("file_unique_id") or ""),
                "type": str(source_item.get("asset_type") or "image"),
                "owner_type": "raw_source",
                "owner_id": "",
                "role": "source",
                "fingerprint": str(
                    source_item.get("fingerprint")
                    or f"telegram:{source_file_id}"
                ),
                "allowed_scene_ids": [],
            })
    ordered_storyboard_assets = [
        item for item in asset_items
        if is_video_ai_real
        and str(item.get("owner_type") or "") == "storyboard_panel"
        and str(item.get("role") or "") == "storyboard_frames"
        and not list(item.get("allowed_scene_ids") or [])
    ]

    cards = []
    scenes = list(snapshot.get("scenes") or [])
    for fallback_index, raw_scene in enumerate(scenes, 1):
        scene = dict(raw_scene or {})
        scene_id = str(scene.get("scene_id") or f"scene_{fallback_index:02d}")
        scene_index = max(1, safe_int(scene.get("scene_index"), fallback_index))
        character_ids = [str(value) for value in scene.get("character_ids") or []]
        location_id = str(scene.get("location_id") or "")
        location = locations.get(location_id, {})
        scene_assets = []
        ordered_source = (
            ordered_source_assets[min(fallback_index - 1, len(ordered_source_assets) - 1)]
            if ordered_source_assets
            else {}
        )
        ordered_storyboard = (
            ordered_storyboard_assets[
                min(fallback_index - 1, len(ordered_storyboard_assets) - 1)
            ]
            if ordered_storyboard_assets
            else {}
        )
        for item in asset_items:
            allowed = set(item.get("allowed_scene_ids") or [])
            owner_type = str(item.get("owner_type") or "")
            owner_id = str(item.get("owner_id") or "")
            role = str(item.get("role") or "")
            if allowed:
                applies = scene_id in allowed
            elif owner_type == "character":
                applies = bool(owner_id and owner_id in character_ids)
            elif owner_type == "location":
                applies = bool(owner_id and owner_id == location_id)
            elif owner_type == "product":
                applies = bool(owner_id and owner_id in set(scene.get("product_ids") or []))
            elif owner_type == "prop":
                applies = bool(owner_id and owner_id in set(scene.get("prop_ids") or []))
            elif owner_type in {"raw_source", "source"}:
                applies = bool(
                    ordered_source
                    and str(item.get("file_id") or "")
                    == str(ordered_source.get("file_id") or "")
                )
            elif (
                is_video_ai_real
                and owner_type == "frame"
                and role == "visual_style_reference"
            ):
                applies = True
            elif (
                is_video_ai_real
                and owner_type == "storyboard_panel"
                and role == "storyboard_frames"
            ):
                applies = bool(
                    ordered_storyboard
                    and str(item.get("file_id") or "")
                    == str(ordered_storyboard.get("file_id") or "")
                )
            else:
                applies = owner_type == "source_video"
            if applies:
                scene_assets.append(dict(item))
        preferred_start_assets = ([dict(ordered_source)] if ordered_source else []) + [
            item for item in scene_assets
            if str(item.get("owner_type") or "")
            in {"raw_source", "source", "source_video"}
        ]
        if is_video_ai_real:
            preferred_start_assets.extend([
                item for item in scene_assets
                if str(item.get("role") or "") == "storyboard_frames"
            ])
            preferred_start_assets.extend([
                item for item in scene_assets
                if str(item.get("role") or "") != "visual_style_reference"
            ])
        start_asset = dict(
            preferred_start_assets[0]
            if preferred_start_assets
            else (scene_assets[0] if scene_assets and not is_video_ai_real else {})
        )
        subject_names = [characters.get(value, "") for value in character_ids]
        subject = ", ".join(value for value in subject_names if value)
        visual_goal = str(
            scene.get("semantic_beat")
            or scene.get("goal")
            or brief.get("main_message")
            or content.get("original_intent")
            or ""
        ).strip()
        action = str(scene.get("main_action") or visual_goal).strip()
        provider_prompt = str(
            scene.get("prompt_override")
            or scene.get("visual_prompt")
            or f"{visual_goal}. {action}"
        ).strip()
        narration = "\n".join(dialogue_by_scene.get(scene_id) or [])
        cards.append({
            "scene_index": scene_index,
            "role": str(scene.get("scene_role") or "scene"),
            "duration_seconds": float(
                scene.get("duration_target")
                or fmt.get("seconds_per_scene")
                or 8
            ),
            "narration_line": narration,
            "subtitle_line": narration,
            "visual_goal": visual_goal,
            "subject_action": action,
            "camera_motion": str(scene.get("movement") or scene.get("camera") or ""),
            "composition": str(scene.get("framing") or scene.get("camera") or ""),
            "background": str(location.get("description") or location.get("name") or ""),
            "reference_asset_ids": [str(item.get("file_id") or "") for item in scene_assets],
            "scene_assets": scene_assets,
            "start_image_file_id": str(start_asset.get("file_id") or ""),
            "end_image_file_id": "",
            "input_mode": "image_to_video" if start_asset else "text_to_video",
            "transition_from_previous": str(scene.get("transition_in") or ""),
            "transition_to_next": str(scene.get("transition_out") or ""),
            "music_cue": str(scene.get("music_policy") or ""),
            "exact_subject": subject or str(brief.get("title") or ""),
            "exact_product_or_object": ", ".join(str(value) for value in scene.get("product_ids") or []),
            "exact_location": str(location.get("name") or location.get("description") or ""),
            "camera_angle": str(scene.get("camera") or scene.get("framing") or ""),
            "lighting": str(scene.get("lighting") or location.get("lighting") or ""),
            "entry_state": str(scene.get("start_state") or ""),
            "exit_state": str(scene.get("completion_state") or ""),
            "continuity_lock": "; ".join(
                key for key, value in dict(bible.get("continuity") or {}).items() if value
            ),
            "provider_prompt": provider_prompt,
            "negative_prompt": str(scene.get("negative_prompt") or ""),
        })

    title = str(brief.get("title") or content.get("original_intent") or "TOAN AAS Video")
    required_capability = str(product_route.get("required_capability") or "text_to_video")
    if str(state.get("entry_mode") or "") == "image_video":
        required_capability = "image_to_video"
    continuity = dict(bible.get("continuity") or {})
    return {
        "profile": profile.to_public_dict(),
        "story_bible": {
            "profile_id": profile_id,
            "title": title,
            "core_message": str(brief.get("main_message") or content.get("original_intent") or title),
            "main_subject": title,
            "visual_style": str(brief.get("visual_intent") or brief.get("tone") or ""),
            "color_palette": str(brief.get("palette") or ""),
            "brand_tone": str(brief.get("tone") or ""),
            "creative_controls": {},
            "negative_prompt": "",
        },
        "scene_cards": cards,
        "asset_pack": {"items": asset_items, "planning_notes": []},
        "preview_text": "Kế hoạch video theo cảnh đã được duyệt",
        "prompt_context": {
            "profile_id": profile_id,
            "job_type": str(product_route.get("executor_product_type") or "video_ai_prompt"),
            "execution_owner": "owner_product_video",
            "required_capability": required_capability,
            "public_product_type": str(product_route.get("product_type") or ""),
            "engine_route": str(product_route.get("engine_route") or ""),
            "selected_voice_music_subtitle_cues": deepcopy(audio),
        },
        "continuity_ledger": continuity,
        "uiflow3_approved_snapshot": snapshot,
        "provider_called": False,
        "xu_charged": 0,
    }


def video_uiflow3_b14_execution_blockers(raw_state: dict) -> list[str]:
    state = video_uiflow3.normalize_state(raw_state)
    blockers = list(video_uiflow3.render_readiness_errors(state))
    audio = dict(state.get("audio") or {})
    dialogue_rows = [
        dict(item) for item in audio.get("dialogue_segments") or []
        if isinstance(item, dict) and str(item.get("text") or "").strip()
    ]
    speakers = list(dict.fromkeys(
        str(item.get("speaker_id") or "")
        for item in dialogue_rows
        if str(item.get("speaker_id") or "")
    ))
    dubbing_mode = str(audio.get("dubbing_mode") or "none")
    if dialogue_rows and dubbing_mode == "browser":
        blockers.append("browser_voice_not_server_renderable")
    if dialogue_rows and dubbing_mode == "default_ai" and len(speakers) > 1:
        blockers.append("multi_voice_renderer_missing")
    return list(dict.fromkeys(str(item or "") for item in blockers if str(item or "")))


def video_uiflow3_new_invoice_attestation(
    state: dict,
    *,
    user_id: int,
    chat_id: int = 0,
    message_id: int = 0,
) -> dict:
    snapshot = video_uiflow3.approved_snapshot(state)
    product_id = str(snapshot.get("parent_product") or state.get("parent_product") or "").strip()
    return {
        "token": uuid.uuid4().hex[:12],
        "draft_id": str(snapshot.get("draft_id") or ""),
        "config_hash": str(snapshot.get("config_hash") or ""),
        "owner_user_id": int(user_id or 0),
        "owner_chat_id": int(chat_id or user_id or 0),
        "message_id": int(message_id or 0),
        "product_id": product_id,
    }


def video_uiflow3_validate_invoice_confirmation(
    session: dict,
    *,
    user_id: int,
    chat_id: int,
    message_id: int,
    token: str,
) -> dict:
    draft = dict((session or {}).get("draft") or {})
    if not draft.get("uiflow3_invoice_attestation_required"):
        return {"ok": True, "reason": ""}
    if str((session or {}).get("current_step") or "") != "b14_invoice":
        return {"ok": False, "reason": "invoice_step_changed"}
    attestation = dict(draft.get("uiflow3_invoice_attestation") or {})
    if not attestation:
        return {"ok": False, "reason": "invoice_attestation_missing"}
    attested_product = str(attestation.get("product_id") or "").strip()
    if not attested_product or str((session or {}).get("product_id") or "") != attested_product:
        return {"ok": False, "reason": "invoice_product_mismatch"}
    if (
        safe_int(attestation.get("owner_user_id"), 0) != int(user_id or 0)
        or safe_int(attestation.get("owner_chat_id"), 0) != int(chat_id or 0)
    ):
        return {"ok": False, "reason": "invoice_owner_mismatch"}
    expected_token = str(attestation.get("token") or "")
    expected_message_id = safe_int(attestation.get("message_id"), 0)
    if (
        not expected_token
        or not hmac.compare_digest(expected_token, str(token or ""))
        or expected_message_id <= 0
        or expected_message_id != int(message_id or 0)
    ):
        return {"ok": False, "reason": "invoice_attestation_mismatch"}
    snapshot = dict(draft.get("uiflow3_approved_snapshot") or {})
    if (
        str(snapshot.get("draft_id") or "") != str(attestation.get("draft_id") or "")
        or str(snapshot.get("config_hash") or "") != str(attestation.get("config_hash") or "")
    ):
        return {"ok": False, "reason": "invoice_snapshot_replaced"}
    return {"ok": True, "reason": ""}


def video_uiflow3_update_invoice_message_id(user_id: int, session: dict, message_id: int) -> dict:
    rendered_message_id = safe_int(message_id, 0)
    if rendered_message_id <= 0:
        return session
    expected = dict(((session or {}).get("draft") or {}).get("uiflow3_invoice_attestation") or {})
    current = get_video_session(user_id)
    draft = dict(current.get("draft") or {})
    attestation = dict(draft.get("uiflow3_invoice_attestation") or {})
    if (
        str(current.get("current_step") or "") != "b14_invoice"
        or not expected.get("token")
        or not hmac.compare_digest(
            str(expected.get("token") or ""),
            str(attestation.get("token") or ""),
        )
    ):
        return current
    attestation["message_id"] = rendered_message_id
    draft["uiflow3_invoice_attestation"] = attestation
    current["draft"] = draft
    return save_video_session(user_id, current)


def video_uiflow3_prepare_no_job_status(
    user_id: int,
    session: dict,
    *,
    blocker_code: str,
    public_message: str,
) -> dict:
    """Persist a truthful failed submit attempt without inventing a task."""

    current = dict(session or get_video_session(user_id) or {})
    draft = dict(current.get("draft") or {})
    existing_job_id = safe_int(
        draft.get("b14_queue_job_id")
        or (draft.get("b14_queue_job") or {}).get("id"),
        0,
    )
    if existing_job_id > 0:
        current["current_step"] = "b14_queue_status"
        return save_video_session(user_id, current)

    preflight = {
        "allowed": False,
        "blocker_code": str(blocker_code or "job_not_created")[:160],
        "public_message": str(
            public_message
            or "TOAN AAS chưa thể bắt đầu tạo video lúc này."
        )[:1200],
    }
    draft.pop("b14_preflight_ui_context", None)
    draft.update({
        "b14_submit_attempted": True,
        "b14_submit_preflight_snapshot": preflight,
        "b14_queue_job": {},
        "b14_queue_job_id": 0,
        "provider_called": False,
        "job_created": False,
        "outbox_created": False,
        "xu_charged": 0,
    })
    current["draft"] = draft
    current["current_step"] = "b14_queue_status"
    return save_video_session(user_id, current)


def video_uiflow3_prepare_b14_session(
    user_id: int,
    raw_state: dict,
    *,
    owner_chat_id: int = 0,
    invoice_message_id: int = 0,
    tail_state: dict | None = None,
    require_attestation: bool = True,
) -> tuple[dict, dict]:
    """Persist a real B14 invoice handoff without submitting or charging yet."""

    state = video_ai_real_maybe_compile_state(raw_state)
    routeengine_handoff = dict(
        (state.get("legacy_compat") or {}).get("routeengine_handoff") or {}
    )
    state["navigation"]["current_step"] = "invoice"
    product_id = str(state.get("parent_product") or "").strip()
    product_route = video_uiflow3_execution_adapter(state)
    if not product_id or not str(product_route.get("product_type") or "").strip():
        raise ValueError("video_uiflow3_product_owner_required")
    if product_id not in VIDEO_UIFLOW3_DEFERRED_RUNTIME_PRODUCTS:
        blockers = video_uiflow3_b14_execution_blockers(state)
        if blockers:
            raise ValueError("video_uiflow3_render_capability_unavailable:" + ",".join(blockers))
    approved_snapshot = video_uiflow3.approved_snapshot(state)
    existing_session = get_video_session(user_id)
    existing_draft = dict(existing_session.get("draft") or {})
    existing_snapshot = dict(existing_draft.get("uiflow3_approved_snapshot") or {})
    same_durable_scope = bool(
        str(existing_session.get("product_id") or existing_draft.get("product_id") or "")
        == str(state.get("parent_product") or "")
        and str(existing_snapshot.get("draft_id") or "")
        == str(approved_snapshot.get("draft_id") or "")
        and str(existing_snapshot.get("config_hash") or "")
        == str(approved_snapshot.get("config_hash") or "")
    )
    durable_submit_fields = {
        key: deepcopy(existing_draft[key])
        for key in (
            "b14_project_id",
            "b14_queue_job_id",
            "b14_queue_job",
            "b14_duplicate_prevented",
            "b14_submit_attempted",
            "b14_submit_preflight_snapshot",
            "submitted_at",
            "video_tail_submit_session_id",
            "video_tail_submit_product_type",
            "video_tail_submit_owner",
            "video_tail_submit_user_id",
        )
        if same_durable_scope and key in existing_draft
    }
    storyboard = video_uiflow3_b14_storyboard_payload(state)
    content = dict(state.get("content") or {})
    brief = dict(content.get("approved_brief") or {})
    selected_prompt = str(
        brief.get("prompt")
        or brief.get("visual_prompt")
        or content.get("original_intent")
        or ""
    ).strip()
    fmt = dict(state.get("format") or {})
    audio = dict(state.get("audio") or {})
    branding = dict(state.get("branding") or {})
    commercial = dict((state.get("legacy_compat") or {}).get("pilot_commercial") or {})
    tail = video_tail9.normalize_state(tail_state) if tail_state else {}
    if tail:
        selected_quality = safe_int(tail.get("quality_tier_id"), 0)
        quality = {
            "tier_id": selected_quality,
            "seconds": safe_int(fmt.get("seconds_per_scene"), TASK3D_SCENE_SECONDS),
            "unit_xu": selected_quality,
        }
        model = dict(tail.get("capability_snapshot") or {})
    else:
        quality = dict(commercial.get("quality") or {})
        model = dict(commercial.get("model") or {})
    if not quality or not safe_int(quality.get("tier_id"), 0) or (not model and not tail):
        raise ValueError("video_ai_real_model_required")
    scene_count = max(1, len(state.get("scenes") or []), safe_int(fmt.get("scene_count"), 0))
    profile_id = str((storyboard.get("profile") or {}).get("profile_id") or "storytelling")
    addon_plan = video_b14_default_addon_plan(profile_id)
    dialogue_rows = [
        dict(item) for item in audio.get("dialogue_segments") or []
        if isinstance(item, dict) and str(item.get("text") or "").strip()
    ]
    dialogues = [str(item.get("text") or "").strip() for item in dialogue_rows]
    dialogue_speakers = list(dict.fromkeys(
        str(item.get("speaker_id") or "")
        for item in dialogue_rows
        if str(item.get("speaker_id") or "")
    ))
    gender_by_speaker = {
        str(item.get("character_id") or ""): str(item.get("gender") or "unspecified")
        for item in (state.get("bible") or {}).get("characters") or []
    }
    narrator = dict((state.get("bible") or {}).get("narrator") or {})
    if narrator.get("narrator_id"):
        gender_by_speaker[str(narrator.get("narrator_id"))] = str(narrator.get("gender") or "unspecified")
    dubbing_mode = str(audio.get("dubbing_mode") or "none")
    dialogue_gender = gender_by_speaker.get(dialogue_speakers[0], "unspecified") if len(dialogue_speakers) == 1 else "unspecified"
    default_voice_source = "default_female" if dialogue_gender == "female" else "default_male"
    music_scope = str(audio.get("music_scope") or "none")
    music_source = str(audio.get("music_source") or "none")
    logo = dict(branding.get("logo") or {})
    watermark = dict(branding.get("watermark") or {})
    logo_file_id = str(logo.get("telegram_file_id") or logo.get("file_id") or "")
    watermark_text = str(watermark.get("text") or "")
    logo_material = (
        product_video_logo_material_config(
            logo_file_id=logo_file_id,
            logo_position=str(logo.get("position") or "top_right"),
            logo_enabled=True,
        )
        if logo_file_id
        else {}
    )
    asset_pack = deepcopy(storyboard.get("asset_pack") or {})
    if logo_material:
        asset_pack["logo_material"] = deepcopy(logo_material)
    if model:
        provider_costs = [
            dict(item) for item in model.get("provider_costs") or [] if isinstance(item, dict)
        ]
        runtime_provider_keys = {
            "shopaikey": "shopaikey_video",
            "key4u": "key4u_video",
        }
        provider_model_map = {
            runtime_provider_keys.get(
                str(item.get("provider") or ""),
                str(item.get("provider") or ""),
            ): str(item.get("model") or "")
            for item in provider_costs
            if str(item.get("provider") or "") and str(item.get("model") or "")
        }
        provider_chain = [
            runtime_provider_keys.get(str(item or ""), str(item or ""))
            for item in model.get("provider_priority") or []
            if str(item or "")
        ]
        asset_pack.update({
            "provider_model_metadata": deepcopy(model),
            "provider_model_map": provider_model_map,
            "provider_chain": provider_chain,
            "provider_order": ",".join(provider_chain),
            "selected_clip_seconds": max(1, safe_int(model.get("seconds"), TASK3D_SCENE_SECONDS)),
            "selected_quality": str(model.get("quality") or ""),
        })
    addon_plan.update({
        "voice_enabled": dubbing_mode == "default_ai" and bool(dialogues),
        "voice_source": default_voice_source if dubbing_mode == "default_ai" and dialogues else "none",
        "voice_provider_voice_id": default_tts_voice_id(dialogue_gender) if dubbing_mode == "default_ai" and dialogues else "",
        "voice_label": ("Nữ mặc định" if dialogue_gender == "female" else "Nam mặc định") if dubbing_mode == "default_ai" and dialogues else "",
        "dub_enabled": dubbing_mode == "default_ai" and bool(dialogues),
        "dub_source": "same_as_voice" if dubbing_mode == "default_ai" and dialogues else "none",
        "music_enabled": music_scope != "none" and music_source in {"library", "ai"},
        "music_source": "default" if music_scope != "none" else "none",
        "subtitle_enabled": str(audio.get("subtitle_mode") or "none") != "none",
        "subtitle_source": "from_narration" if str(audio.get("subtitle_mode") or "none") != "none" else "none",
        "sfx_enabled": str(audio.get("sfx_mode") or "none") != "none",
        "logo_enabled": bool(logo_file_id or watermark_text),
        "logo_source": "text" if watermark_text else "none",
        "logo_text": watermark_text,
        "logo_file_id": logo_file_id,
        "narration_text": "\n".join(dialogues),
        "music_note": f"{music_source}:{music_scope}" if music_scope != "none" else "",
    })
    source_refs = [
        str(item.get("file_id") or "")
        for item in (storyboard.get("asset_pack") or {}).get("items") or []
        if str(item.get("file_id") or "")
    ]
    topic = str(
        brief.get("title")
        or content.get("original_intent")
        or VIDEO_UIFLOW3_PRODUCT_LABELS.get(product_id)
        or "Video"
    )
    scene_seconds = max(1, safe_int(fmt.get("seconds_per_scene") or quality.get("seconds") or model.get("seconds"), TASK3D_SCENE_SECONDS))
    commercial_quote = video_ai_real_prompt_quote(state) if not tail else {}
    attestation = (
        video_uiflow3_new_invoice_attestation(
            state,
            user_id=user_id,
            chat_id=owner_chat_id or safe_int(state.get("owner_chat_id"), 0),
            message_id=invoice_message_id,
        )
        if require_attestation
        else {}
    )
    session = default_video_session(user_id)
    session.update({
        "product_id": product_id,
        "current_step": "b14_invoice",
        "topic": topic,
        "original_user_prompt": str(content.get("original_intent") or topic),
        "aspect_ratio": str(fmt.get("ratio") or "9:16"),
        "entry_flow": "video_uiflow3",
        "current_flow": "product_video",
    })
    session["draft"] = {
        "topic": topic,
        "product_id": product_id,
        "content_mode": str(content.get("source") or "manual"),
        "content_source": str(content.get("source") or "manual"),
        "content_choice": deepcopy(brief),
        "selected_suggestion": deepcopy(brief),
        "selected_prompt": selected_prompt or topic,
        "selected_prompt_text": selected_prompt or topic,
        "b14_profile_id": profile_id,
        "b14_scene_count": scene_count,
        "b14_scene_count_selected": True,
        "b14_scene_seconds": scene_seconds,
        "b14_quality_xu": safe_int(quality.get("tier_id"), 0),
        "b14_pricing_mode": "video_ai_real_model" if commercial_quote else "canonical",
        "b14_billing_unit_xu": safe_int(commercial_quote.get("unit_xu"), quality.get("unit_xu")),
        "b14_addon_quote_items": deepcopy(list(commercial_quote.get("addons") or [])),
        "b14_addon_quote_xu": safe_int(commercial_quote.get("addons_xu"), 0),
        "b14_quote_total_xu": safe_int(commercial_quote.get("total_xu"), 0),
        "b14_package_label_override": (
            f"{str(model.get('label') or quality.get('name') or 'Video AI')} · "
            f"{scene_seconds} giây · {str(model.get('quality') or quality.get('public_level') or 'Chất lượng đã chọn')}"
            if commercial_quote
            else ""
        ),
        "b14_aspect_ratio": str(fmt.get("ratio") or "9:16"),
        "b14_addon_plan": addon_plan,
        "b14_storyboard_plan": storyboard,
        "prompt_bundle": video_b14_prompt_bundle_from_plan_payload(storyboard),
        "asset_pack": asset_pack,
        "provider_model_metadata": model,
        "video_tail_engine_route": str(product_route.get("engine_route") or ""),
        "video_tail_executor_product_type": str(product_route.get("executor_product_type") or ""),
        "video_tail_required_capability": str(product_route.get("required_capability") or ""),
        "video_tail_worker_owner": str(product_route.get("worker_owner") or ""),
        "entry_choice": "ai_image_menu" if str(state.get("entry_mode") or "") == "image_video" else "prompt_video",
        "input_origin_step": "awaiting_source_image" if str(state.get("entry_mode") or "") == "image_video" else "prompt_video",
        "source_media_ref": source_refs[0] if source_refs else "",
        "source_media_refs": source_refs,
        "media_type": "image" if str(state.get("entry_mode") or "") == "image_video" else "text",
        "uiflow3_approved_snapshot": approved_snapshot,
        "uiflow3_invoice_attestation_required": bool(require_attestation),
        "uiflow3_invoice_attestation": attestation,
        "charge_policy": "after_valid_mp4_delivery",
        "provider_called": False,
        "job_created": False,
        "outbox_created": False,
        "xu_charged": 0,
    }
    if routeengine_handoff:
        session["draft"].update({
            "uiflow3_routeengine_handoff": deepcopy(routeengine_handoff),
            "uiflow3_handoff_sha256": str(routeengine_handoff.get("handoff_sha256") or ""),
            "uiflow3_snapshot_config_hash": str(
                routeengine_handoff.get("snapshot_config_hash") or ""
            ),
            "uiflow3_summary_token": video_uiflow3.draft_token(state),
        })
    session["draft"].update(durable_submit_fields)
    if logo_material:
        session["draft"]["product_video_logo_material"] = deepcopy(logo_material)
    if tail:
        session["draft"][VIDEO_TAIL9_STATE_KEY] = tail
    saved = save_video_session(user_id, session)
    confirmation_invoice = video_b14_invoice_for_session(saved, user_id)
    commercial["b14_handoff_ready"] = True
    commercial["b14_quality_xu"] = safe_int(quality.get("tier_id"), 0)
    commercial["confirmation"] = {
        "token": str(attestation.get("token") or ""),
        "product_label": "Ảnh → Video" if str(state.get("entry_mode") or "") == "image_video" else "Prompt → Video",
        "package_label": str(confirmation_invoice.get("package_label") or quality.get("name") or "Gói đã chọn"),
        "scene_count": safe_int(confirmation_invoice.get("scene_count"), scene_count),
        "seconds_per_scene": scene_seconds,
        "duration_seconds": safe_int(
            confirmation_invoice.get("duration_seconds"),
            scene_count * scene_seconds,
        ),
        "unit_xu": safe_int(confirmation_invoice.get("quality_xu"), quality.get("tier_id")),
        "total_xu": safe_int(confirmation_invoice.get("total_xu"), 0),
    }
    state["legacy_compat"]["pilot_commercial"] = commercial
    return video_uiflow3.normalize_state(state), saved


def video_uiflow3_real_invoice_keyboard(state: dict, session: dict) -> InlineKeyboardMarkup:
    back_callback = video_uiflow3.scope_callback(state, "vid3|invoice_back")
    confirm_callback = video_uiflow3.scope_callback(state, "vid3|invoice_confirm")
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("✅ Tiếp tục xác nhận tạo video", callback_data=confirm_callback),
            InlineKeyboardButton("✏️ Sửa lựa chọn", callback_data=back_callback),
        ],
        [InlineKeyboardButton("🎬 Menu Video", callback_data="menu|main_video")],
    ])


def video_uiflow3_matching_b14_session(user_id: int, raw_state: dict) -> dict:
    state = video_uiflow3.normalize_state(raw_state)
    session = get_video_session(user_id)
    draft = dict(session.get("draft") or {})
    snapshot = dict(draft.get("uiflow3_approved_snapshot") or {})
    current_snapshot = video_uiflow3.approved_snapshot(state)
    if (
        str(session.get("product_id") or "") != "video_ai_real"
        or str(snapshot.get("draft_id") or "") != str(state.get("draft_id") or "")
        or str(snapshot.get("config_hash") or "") != str(current_snapshot.get("config_hash") or "")
    ):
        return {}
    return session


def video_uiflow3_real_invoice_text(session: dict, user_id: int, lang: str = "vi") -> str:
    """Render the canonical invoice plus an explicit balance shortfall."""

    text = video_b14_invoice_text(session, user_id, lang)
    invoice = video_b14_invoice_for_session(session, user_id)
    try:
        credits, _, _ = get_user(user_id)
        missing_xu = max(0, safe_int(invoice.get("total_xu"), 0) - safe_int(credits, 0))
    except Exception:
        missing_xu = 0
    if not missing_xu:
        return text
    missing_line = f"• Còn thiếu: <b>{xu_number(missing_xu)} Xu</b>"
    marker = "\n\nBấm xác nhận"
    if marker in text:
        return text.replace(marker, f"\n{missing_line}{marker}", 1)
    return f"{text}\n{missing_line}"


async def video_uiflow3_render_real_invoice(
    query,
    context,
    user_id: int,
    state: dict,
    *,
    reuse_saved: bool = False,
):
    if reuse_saved:
        prepared = video_uiflow3.normalize_state(state)
        session = video_uiflow3_matching_b14_session(user_id, prepared)
        if str(session.get("current_step") or "") != "b14_invoice":
            raise ValueError("video_uiflow3_saved_invoice_unavailable")
    else:
        prepared, session = video_uiflow3_prepare_b14_session(
            user_id,
            state,
            owner_chat_id=safe_int(getattr(getattr(query, "message", None), "chat_id", 0), 0),
            invoice_message_id=safe_int(getattr(getattr(query, "message", None), "message_id", 0), 0),
        )
    save_video_uiflow3_state(context, prepared)
    rendered = await safe_edit_or_send_long_html(
        query,
        video_uiflow3_real_invoice_text(
            session,
            user_id,
            get_user_language(user_id) or "vi",
        ),
        reply_markup=video_uiflow3_real_invoice_keyboard(prepared, session),
    )
    rendered_message_id = safe_int(
        getattr(rendered, "message_id", 0)
        or getattr(getattr(query, "message", None), "message_id", 0),
        0,
    )
    video_uiflow3_update_invoice_message_id(user_id, session, rendered_message_id)
    return rendered


def video_ai_real_is_prompt_pilot(raw_state: dict) -> bool:
    """Compatibility name for both supported Video AI creation products."""

    return video_ai_real_is_creation_flow(raw_state)


def video_ai_real_pilot_can_plan_capability(state: dict, capability: str) -> bool:
    """Keep the prompt pilot editable while the future renderer is still gated."""

    return video_ai_real_is_prompt_pilot(state) or bool(
        (state.get("capabilities") or {}).get(str(capability or ""))
    )


def video_ai_real_maybe_compile_state(raw_state: dict) -> dict:
    if not video_ai_real_is_prompt_pilot(raw_state):
        return video_uiflow3.normalize_state(raw_state)
    return video_ai_real_compile_state(raw_state)


def video_ai_real_compile_state(raw_state: dict) -> dict:
    """Persist one deterministic visual/post-production handoff contract."""

    state = _video_ai_real_pilot_state(raw_state)
    contract = video_ai_real_prompt_compiler.compile_render_contract(state)
    scene_prompts = {
        str(item.get("scene_id") or ""): item
        for item in (contract.get("visual") or {}).get("scenes") or []
    }
    for scene in state.get("scenes") or []:
        compiled = scene_prompts.get(str(scene.get("scene_id") or ""))
        if not compiled:
            continue
        scene["visual_prompt"] = str(compiled.get("visual_prompt") or "")
        scene["negative_prompt"] = str(compiled.get("negative_prompt") or "")
        scene["visual_prompt_hash"] = str(compiled.get("visual_prompt_hash") or "")
        scene["compiled_prompt_status"] = (
            "user_override" if compiled.get("user_override_applied") else "compiled"
        )
        scene["compiled_prompt_version"] = str(
            (contract.get("visual") or {}).get("schema_version") or ""
        )
    state["render_contract"] = contract
    dirty = list((state.get("navigation") or {}).get("dirty_sections") or [])
    state["navigation"]["dirty_sections"] = [item for item in dirty if item != "prompts"]
    return video_uiflow3.normalize_state(state)


def video_ai_real_default_character_description(
    raw_state: dict,
    character_id: str,
) -> str:
    state = _video_ai_real_pilot_state(raw_state)
    characters = list((state.get("bible") or {}).get("characters") or [])
    character = next(
        (item for item in characters if str(item.get("character_id") or "") == str(character_id or "")),
        None,
    )
    if not character:
        raise ValueError("character_not_found")
    index = next(
        (
            offset
            for offset, item in enumerate(characters, 1)
            if str(item.get("character_id") or "") == str(character_id or "")
        ),
        1,
    )
    content = dict(state.get("content") or {})
    brief = dict(content.get("approved_brief") or {})
    topic = str(brief.get("title") or content.get("original_intent") or "Nội dung đã chọn").strip()
    folded = "".join(
        char
        for char in unicodedata.normalize("NFD", topic.lower())
        if unicodedata.category(char) != "Mn"
    )
    if "gioi thieu san pham" in folded:
        topic = "Giới thiệu sản phẩm"
    gender = {
        "female": "nữ",
        "male": "nam",
    }.get(str(character.get("gender") or ""), "phù hợp nội dung")
    name = video_ai_real_pilot_visible_entity_name(
        character.get("display_name"),
        entity="character",
        index=index,
    ) or f"Nhân vật {index}"
    return (
        f"{topic}. {name} là nhân vật {gender}, ngoại hình đời thường và dễ nhận diện; "
        "trang phục, màu sắc, biểu cảm và cách tương tác nhất quán giữa các cảnh; "
        "hành động tự nhiên, đúng mục tiêu nội dung, không phô diễn máy móc."
    )


