def video_ai_real_build_quick_plan(
    raw_state: dict,
    *,
    bible_only: bool = False,
) -> dict:
    """Fill content-based defaults and optionally build the complete quick plan."""

    state = _video_ai_real_pilot_state(raw_state)
    if not bool((state.get("content") or {}).get("locked")):
        raise ValueError("content_not_locked")
    fmt = dict(state.get("format") or {})
    scene_count = safe_int(fmt.get("scene_count"), 0)
    if scene_count <= 0:
        raise ValueError("scene_count_out_of_range")
    if not str(fmt.get("ratio") or ""):
        raise ValueError("aspect_ratio_unsupported")
    needs = dict(state.get("needs") or {})
    if needs.get("reference_assets") == "REQUIRED" and not state.get("references"):
        raise ValueError("reference_assets_required")

    seed_source = "|".join([
        str(state.get("draft_id") or ""),
        str((state.get("content") or {}).get("revision") or 0),
        str((state.get("content") or {}).get("profile_id") or "general"),
        str(scene_count),
        str(fmt.get("ratio") or ""),
    ])
    seed = hashlib.sha256(seed_source.encode("utf-8")).hexdigest()[:16]
    seed_number = int(seed[:8], 16)
    content = dict(state.get("content") or {})
    brief = dict(content.get("approved_brief") or {})
    topic = str(brief.get("title") or content.get("original_intent") or "Nội dung đã chọn").strip()

    bible = dict(state.get("bible") or {})
    wants_characters = needs.get("characters") not in {"SKIP", "UNSUPPORTED"}
    has_required_source_image = bool(
        str(state.get("entry_mode") or "") == "image_video"
        and (state.get("source") or {}).get("assets")
    )
    wants_locations = bool(
        needs.get("locations") not in {"SKIP", "UNSUPPORTED"}
        and (
            not has_required_source_image
            or needs.get("locations") == "REQUIRED"
        )
    )
    if not bool(bible.get("character_count_confirmed")):
        state = video_uiflow3.set_character_count(state, 1 if wants_characters else 0)
    if not bool((state.get("bible") or {}).get("location_count_confirmed")):
        state = video_uiflow3.set_location_count(state, 1 if wants_locations else 0)

    for index, character in enumerate((state.get("bible") or {}).get("characters") or [], 1):
        was_locked_by_user = bool(character.get("locked_by_user"))
        changes = {}
        if str(character.get("gender") or "unspecified") == "unspecified":
            changes["gender"] = "female" if (seed_number + index) % 2 else "male"
        if not str(character.get("description") or "").strip():
            provisional = video_uiflow3.update_character(state, str(character.get("character_id") or ""), **changes) if changes else state
            changes["description"] = video_ai_real_default_character_description(
                provisional,
                str(character.get("character_id") or ""),
            )
        if changes:
            state = video_uiflow3.update_character(
                state,
                str(character.get("character_id") or ""),
                **changes,
            )
            if not was_locked_by_user:
                character_id = str(character.get("character_id") or "")
                updated_character = next(
                    (
                        item
                        for item in (state.get("bible") or {}).get("characters") or []
                        if str(item.get("character_id") or "") == character_id
                    ),
                    None,
                )
                if updated_character is not None:
                    updated_character.update({
                        "locked_by_user": False,
                        "suggestion_source": "content_needs",
                        "suggestion_confidence": 0.65,
                    })

    location_presets = list(VIDEO_AI_REAL_PILOT_LOCATION_PRESETS.values())
    for index, location in enumerate((state.get("bible") or {}).get("locations") or [], 1):
        if str(location.get("description") or "").strip():
            continue
        was_locked_by_user = bool(location.get("locked_by_user"))
        preset = location_presets[(seed_number + index - 1) % len(location_presets)]
        state = video_uiflow3.update_location(
            state,
            str(location.get("location_id") or ""),
            name=str(preset.get("name") or f"Bối cảnh {index}"),
            description=f"{preset.get('description')} Phù hợp nội dung: {topic}.",
            indoor_outdoor=str(preset.get("indoor_outdoor") or ""),
            lighting=str(preset.get("lighting") or ""),
            mood=str(preset.get("mood") or ""),
        )
        if not was_locked_by_user:
            location_id = str(location.get("location_id") or "")
            updated_location = next(
                (
                    item
                    for item in (state.get("bible") or {}).get("locations") or []
                    if str(item.get("location_id") or "") == location_id
                ),
                None,
            )
            if updated_location is not None:
                updated_location.update({
                    "locked_by_user": False,
                    "suggestion_source": "content_needs",
                    "suggestion_confidence": 0.65,
                })

    if has_required_source_image and needs.get("locations") == "REQUIRED":
        first_source = next(
            (
                item
                for item in (state.get("source") or {}).get("assets") or []
                if str(item.get("asset_id") or "")
            ),
            {},
        )
        first_location = next(
            (
                item
                for item in (state.get("bible") or {}).get("locations") or []
                if str(item.get("location_id") or "")
            ),
            {},
        )
        if (
            first_source
            and first_location
            and not first_location.get("reference_asset_ids")
        ):
            state = video_uiflow3.map_source_asset_to_reference(
                state,
                source_asset_id=str(first_source.get("asset_id") or ""),
                owner_type="location",
                owner_id=str(first_location.get("location_id") or ""),
                role="primary_location",
            )

    if needs.get("product") == "REQUIRED" and not (state.get("bible") or {}).get("products"):
        state = video_uiflow3.add_product(
            state,
            name=str(brief.get("product_name") or topic)[:120],
            category=str(brief.get("category") or "Sản phẩm trong nội dung"),
            description=f"Sản phẩm trung tâm của {topic}; giữ nguyên hình dáng, màu sắc và nhãn giữa các cảnh.",
        )
    if needs.get("narrator") == "REQUIRED" and not (state.get("bible") or {}).get("narrator"):
        state = video_uiflow3.set_narrator(
            state,
            display_name="Người dẫn",
            style="Tự nhiên, rõ ý và vừa thời lượng cảnh",
            gender="unspecified",
        )

    if bible_only:
        state = video_uiflow3_clear_transient(state)
        state["navigation"]["current_step"] = "production_bible"
        return video_uiflow3.normalize_state(state)

    if not bool((state.get("format") or {}).get("scene_count_confirmed")):
        state = video_uiflow3.confirm_scene_count(state, scene_count)
    state = video_uiflow3.suggest_scene_plan(state)
    state = video_uiflow3.auto_assign_scenes(state)

    product_ids = [
        str(item.get("product_id") or "")
        for item in (state.get("bible") or {}).get("products") or []
        if str(item.get("product_id") or "")
    ]
    narrator_required = needs.get("narrator") == "REQUIRED"
    for index, scene in enumerate(list(state.get("scenes") or []), 1):
        direction = VIDEO_AI_REAL_QUICK_DIRECTIONS[(seed_number + index - 1) % len(VIDEO_AI_REAL_QUICK_DIRECTIONS)]
        state = video_uiflow3.assign_scene(
            state,
            str(scene.get("scene_id") or ""),
            product_ids=product_ids if needs.get("product") == "REQUIRED" else scene.get("product_ids") or [],
            narrator_enabled=narrator_required,
            sfx_ids=["auto_library_by_action"] if needs.get("sfx") == "REQUIRED" else scene.get("sfx_ids") or [],
            ambient_id="auto_library_by_location" if needs.get("ambient") == "REQUIRED" else str(scene.get("ambient_id") or ""),
        )
        state = video_uiflow3.update_scene_direction(
            state,
            str(scene.get("scene_id") or ""),
            framing=direction[0],
            movement=direction[1],
            lighting=direction[2],
            mood=direction[3],
        )

    if needs.get("dialogue") == "REQUIRED" and not (state.get("audio") or {}).get("dialogue_segments"):
        narrator_id = str(((state.get("bible") or {}).get("narrator") or {}).get("narrator_id") or "")
        for scene in state.get("scenes") or []:
            speaker_id = str((scene.get("character_ids") or [narrator_id])[0] or narrator_id)
            if speaker_id:
                state = video_uiflow3.set_dialogue(
                    state,
                    str(scene.get("scene_id") or ""),
                    speaker_id=speaker_id,
                    text=f"{topic}: trình bày ngắn gọn ý chính của cảnh {scene.get('scene_index')}.",
                )
    if needs.get("voice") == "REQUIRED":
        state = video_ai_real_apply_default_voice_plan(
            state,
            enable_dubbing=bool((state.get("audio") or {}).get("dialogue_segments")),
        )
        state["audio"]["subtitle_mode"] = "script" if state["audio"].get("dialogue_segments") else "none"
    if needs.get("music") == "REQUIRED":
        state["audio"].update({
            "music_scope": "whole_video",
            "music_source": "library",
            "music_plan": {"track_id": "auto_library_by_story_mood"},
        })
    if needs.get("sfx") == "REQUIRED":
        state["audio"].update({
            "sfx_mode": "library",
            "sfx_plan": [{"policy": "auto_by_scene_action"}],
        })
    if needs.get("ambient") == "REQUIRED":
        state["audio"]["ambient_plan"] = [{"policy": "auto_by_scene_location"}]

    state = video_uiflow3.mark_sections_complete(
        state,
        "production_bible",
        "references",
        "continuity",
        "scene_plan",
        "scene_assignment",
    )
    legacy = dict(state.get("legacy_compat") or {})
    legacy["pilot_quick_build"] = {
        "version": "quick-v1",
        "seed": seed,
        "profile_id": str(content.get("profile_id") or "general"),
    }
    state["legacy_compat"] = legacy
    state = video_ai_real_compile_state(state)
    state = video_uiflow3_go(state, "prompts")
    return video_uiflow3.normalize_state(state)


def video_ai_real_pilot_nav_rows(*, back: str) -> list[list[tuple[str, str]]]:
    target = str(back or "vid3|back")
    if target == "menu|main_video":
        return [[("⬅️ Quay lại Menu Video", "menu|main_video")]]
    return [[("⬅️ Quay lại", target), ("🎬 Menu Video", "menu|main_video")]]


def video_ai_real_pilot_selected(label: str, selected: bool) -> str:
    return f"✅ {label}" if selected else str(label or "")


def video_ai_real_pilot_visible_entity_name(value: object, *, entity: str, index: int) -> str:
    """Hide generated placeholders so a numbered item is not shown twice."""

    name = str(value or "").strip()
    if not name:
        return ""
    defaults = {
        "character": ("Nhân vật", "Nhan vat"),
        "location": ("Bối cảnh", "Boi canh"),
        "product": ("Sản phẩm", "San pham"),
        "prop": ("Đạo cụ", "Dao cu"),
    }.get(str(entity or ""), ())
    if name in {f"{prefix} {index}" for prefix in defaults}:
        return ""
    return name


def video_ai_real_pilot_character_label(item: dict, index: int) -> str:
    name = video_ai_real_pilot_visible_entity_name(
        item.get("display_name"),
        entity="character",
        index=index,
    )
    return f"👤 Nhân vật {index}" + (f" · {name}" if name else "")


def video_ai_real_pilot_location_label(item: dict, index: int) -> str:
    name = video_ai_real_pilot_visible_entity_name(
        item.get("name"),
        entity="location",
        index=index,
    )
    return f"🏞 Bối cảnh {index}" + (f" · {name}" if name else "")


def video_ai_real_pilot_entity_label(state: dict, owner_type: str, owner_id: str) -> str:
    material_label = {
        ("frame", "style"): "Phong cách hình ảnh",
        ("storyboard_panel", "board"): "Storyboard",
    }.get((str(owner_type or ""), str(owner_id or "")))
    if material_label:
        return material_label
    bible = dict(state.get("bible") or {})
    config = {
        "character": ("characters", "character_id", "display_name", "Nhân vật"),
        "location": ("locations", "location_id", "name", "Bối cảnh"),
        "product": ("products", "product_id", "name", "Sản phẩm"),
        "prop": ("props", "prop_id", "name", "Đạo cụ"),
    }.get(str(owner_type or ""))
    if not config:
        return "Nguồn video"
    field, id_field, name_field, label = config
    for index, item in enumerate(bible.get(field) or [], 1):
        if str(item.get(id_field) or "") == str(owner_id or ""):
            name = video_ai_real_pilot_visible_entity_name(
                item.get(name_field),
                entity=owner_type,
                index=index,
            )
            return f"{label} {index}" + (f" · {name}" if name else "")
    return "Đối tượng không còn tồn tại"


def video_ai_real_pilot_scene_label(state: dict, scene: dict) -> str:
    characters = {
        str(item.get("character_id") or ""): video_ai_real_pilot_visible_entity_name(
            item.get("display_name"),
            entity="character",
            index=index,
        )
        for index, item in enumerate((state.get("bible") or {}).get("characters") or [], 1)
    }
    names = [
        characters.get(str(character_id), "")
        for character_id in scene.get("character_ids") or []
    ]
    cast = ", ".join(name for name in names if name) or "Tự động theo thứ tự"
    scene_index = safe_int(scene.get("scene_index"), 0)
    beat = str(scene.get("semantic_beat") or scene.get("main_action") or "").strip()
    return f"🎬 Cảnh {scene_index} · {beat or cast}"


VIDEO_AI_REAL_PROMPT_PAGE_BODY_LIMIT = 3600


def video_ai_real_compiled_scene_prompt(state: dict, scene_id: str) -> dict:
    """Return exactly the prompt fields sent to the renderer for one scene."""

    contract = video_ai_real_prompt_compiler.compile_render_contract(state)
    return dict(next(
        (
            item
            for item in (contract.get("visual") or {}).get("scenes") or []
            if str(item.get("scene_id") or "") == str(scene_id or "")
        ),
        {},
    ))


def video_ai_real_prompt_review_pages(raw_state: dict) -> list[dict]:
    """Split complete prompts only for Telegram transport; never summarize them."""

    state = video_uiflow3.normalize_state(raw_state)
    contract = video_ai_real_prompt_compiler.compile_render_contract(state)
    compiled_by_id = {
        str(item.get("scene_id") or ""): dict(item)
        for item in (contract.get("visual") or {}).get("scenes") or []
    }
    pages: list[dict] = []
    for fallback_index, scene in enumerate(state.get("scenes") or [], 1):
        scene_id = str(scene.get("scene_id") or "")
        compiled = compiled_by_id.get(scene_id, {})
        scene_index = max(1, safe_int(scene.get("scene_index"), fallback_index))
        for part, label, value in (
            ("visual", "Câu lệnh hình ảnh", str(compiled.get("visual_prompt") or "")),
            ("negative", "Điều cần tránh", str(compiled.get("negative_prompt") or "")),
        ):
            chunks = [
                value[offset:offset + VIDEO_AI_REAL_PROMPT_PAGE_BODY_LIMIT]
                for offset in range(0, len(value), VIDEO_AI_REAL_PROMPT_PAGE_BODY_LIMIT)
            ] or [""]
            for chunk_index, body in enumerate(chunks, 1):
                pages.append({
                    "scene_id": scene_id,
                    "scene_index": scene_index,
                    "part": part,
                    "part_label": label,
                    "chunk_index": chunk_index,
                    "chunk_count": len(chunks),
                    "body": body,
                })
    return pages


def video_ai_real_prompt_page_payload(
    raw_state: dict,
    page_number: int = 1,
) -> tuple[str, InlineKeyboardMarkup]:
    """Render one complete prompt page without truncating the stored text."""

    state = video_uiflow3.normalize_state(raw_state)
    pages = video_ai_real_prompt_review_pages(state)
    if not pages:
        return (
            "🧠 Rà soát câu lệnh\n\nChưa có câu lệnh để hiển thị.",
            video_uiflow3_keyboard([
                [("⬅️ Quay lại", "vid3|back"), ("🎬 Menu Video", "menu|main_video")],
            ]),
        )
    page_index = max(1, min(len(pages), safe_int(page_number, 1)))
    page = dict(pages[page_index - 1])
    scene_id = str(page.get("scene_id") or "")
    scene_index = safe_int(page.get("scene_index"), 1)
    part_label = str(page.get("part_label") or "Câu lệnh")
    lines = [
        "🧠 Rà soát câu lệnh",
        "Toàn bộ câu lệnh hiện tại",
        f"CẢNH {scene_index} · {part_label} · Trang {page_index}/{len(pages)}",
        "",
        str(page.get("body") or ""),
        "",
        "Nội dung được hiển thị nguyên văn. Mở chi tiết cảnh để sửa trực tiếp; mọi ký tự đều được giữ nguyên.",
    ]
    rows: list[list[tuple[str, str]]] = []
    page_navigation: list[tuple[str, str]] = []
    if page_index > 1:
        page_navigation.append(("⬅️ Trang trước", f"vid3|prompt_page|{page_index - 1}"))
    if page_index < len(pages):
        page_navigation.append(("Trang sau ➡️", f"vid3|prompt_page|{page_index + 1}"))
    if page_navigation:
        rows.append(page_navigation)
    rows.append([
        ("📝 Câu lệnh từng cảnh", "vid3|prompt_scenes"),
        ("✏️ Mở chi tiết cảnh", f"vid3|prompt_scene|{scene_id}" if scene_id else "vid3|prompt_scenes"),
    ])
    rows.append([
        ("🎥 Tùy chỉnh nâng cao", "vid3|prompt_advanced"),
        ("✅ Hoàn tất rà soát câu lệnh", "vid3|prompts_done"),
    ])
    rows.extend(video_ai_real_pilot_nav_rows(back="vid3|back"))
    return "\n".join(lines), video_uiflow3_keyboard(rows)


def video_ai_real_pilot_scene_prompt_text(state: dict, scene: dict) -> str:
    compiled = video_ai_real_compiled_scene_prompt(
        state,
        str(scene.get("scene_id") or ""),
    )
    return (
        "Câu lệnh hình ảnh hiện tại:\n"
        f"{str(compiled.get('visual_prompt') or '')}\n\n"
        "Điều cần tránh hiện tại:\n"
        f"{str(compiled.get('negative_prompt') or '')}"
    )


