def storyboard2_package_resolutions(state: dict) -> list[dict]:
    """Return catalog-compatible packages for the current asset mode.

    Runtime route readiness is checked later by preflight. Keeping that check
    separate prevents a temporarily unavailable provider from erasing valid
    public packages while still blocking invoice creation when no engine can
    execute the selected plan.
    """

    current = video_scene3_flow.normalize_state(state)
    capability = video_flow6_required_capability("storyboard", current)
    scene_count = max(1, safe_int(current.get("scene_count"), 1))
    catalog = video_uifreeze1.catalog_report(
        "storyboard_prompt",
        scene_count=scene_count,
        ratio=str(current.get("ratio") or "9:16"),
        required_capability=capability,
    )
    return [
        {
            "price": safe_int(offer.get("tier_id"), 0),
            "resolution": {
                "ok": True,
                "catalog_only": True,
                "required_capability": capability,
                "supports_concat": scene_count > 1,
            },
            "tier": dict(offer),
        }
        for offer in catalog.get("offers") or []
    ]


def storyboard2_quality_text(state: dict, lang: str = "vi") -> str:
    current = video_scene3_flow.normalize_state(state)
    capability = video_flow6_required_capability("storyboard", current)
    packages = storyboard2_package_resolutions(current)
    count = max(1, safe_int(current.get("scene_count"), 1))
    mode_label = "ảnh đầu + ảnh cuối" if capability == "first_last_frame_video" else "một ảnh đầu mỗi cảnh"
    lines = [
        "⭐ <b>Hoàn thiện video Storyboard</b>",
        "",
        f"• Số cảnh: <b>{count}</b> · khoảng <b>{count * 8} giây</b>",
        f"• Chế độ ảnh: <b>{mode_label}</b>",
        "",
    ]
    if not packages:
        lines.extend([
            "Hiện chưa có gói nào đáp ứng đúng chế độ ảnh đã chọn.",
            "Hệ thống chưa tạo tác vụ, chưa xử lý video và chưa trừ Xu.",
        ])
        if capability == "first_last_frame_video":
            lines.append("Có thể chuyển về một ảnh đầu mỗi cảnh hoặc quay lại quản lý ảnh.")
        return "\n".join(lines)
    lines.append("Các gói phù hợp với ảnh đầu/ảnh cuối, tỉ lệ và số cảnh đã chọn:")
    for item in packages:
        price = safe_int(item.get("price"), 0)
        tier = dict(item.get("tier") or video_uifreeze1.tier_spec(price))
        icon = str(tier.get("icon") or "⭐")
        name = str(tier.get("name") or "Chất lượng")
        level = str(tier.get("public_level") or "Chất lượng phù hợp")
        detail = str(tier.get("public_detail") or "Tạo và ghép cảnh theo kế hoạch đã duyệt.")
        lines.append(
            f"{icon} <b>{price} Xu — {html.escape(name)}</b>: "
            f"{html.escape(level)} · {html.escape(detail)}"
        )
    lines.extend([
        "",
        "Chọn một gói để kiểm tra điều kiện xử lý và mở hóa đơn. Màn này chưa tạo video và chưa trừ Xu.",
    ])
    return "\n".join(lines)


def storyboard2_quality_keyboard(state: dict, lang: str = "vi") -> InlineKeyboardMarkup:
    current = video_scene3_flow.normalize_state(state)
    capability = video_flow6_required_capability("storyboard", current)
    prices = [safe_int(item.get("price"), 0) for item in storyboard2_package_resolutions(current)]
    rows: list[list[tuple[str, str]]] = []
    for offset in range(0, len(prices), 2):
        row = [
            (video_b14_package_button_label(price), f"vprofile|tier|{price}")
            for price in prices[offset:offset + 2]
        ]
        if len(row) == 1:
            row.append(("🖼️ Quản lý ảnh", "vstory|assets_screen"))
        rows.append(row)
    if not rows:
        second = (
            ("🖼️ Dùng một ảnh/cảnh", "vstory|one_image_mode")
            if capability == "first_last_frame_video"
            else ("📋 Xem Storyboard", "vstory|review_from_quality")
        )
        rows.append([("🖼️ Quản lý ảnh", "vstory|assets_screen"), second])
    rows.append([("⬅️ Quay lại", "vstory|review_from_quality"), ("🏠 Menu chính", "menu|main")])
    return storyboard2_keyboard(rows)


def storyboard2_entry_text() -> str:
    return (
        "🎞️ <b>Storyboard</b>\n\n"
        "Lập bảng phân cảnh có ảnh đầu bắt buộc và ảnh cuối tùy chọn cho từng cảnh. "
        "Mỗi cảnh có câu lệnh chuyển động riêng và được ghép thành một video hoàn chỉnh.\n\n"
        "Bước này chỉ mở kế hoạch. Hệ thống chưa tạo ảnh/video, chưa tạo tác vụ và chưa trừ Xu."
    )


def storyboard2_screen_payload(board: dict) -> tuple[str, InlineKeyboardMarkup]:
    board = video_storyboard2.normalize_state(board)
    screen = str(board.get("screen") or "entry")
    count = int(board.get("scene_count") or 0)
    ratio = str(board.get("aspect_ratio") or "Chưa chọn")
    index = max(1, min(max(1, count), int(board.get("active_scene_index") or 1)))
    scene = board.get("scenes", [video_storyboard2.default_state()])[index - 1] if count else {}
    if screen == "entry":
        return storyboard2_entry_text(), storyboard2_entry_keyboard()
    if screen == "await_storyboard_upload":
        return (
            "📎 <b>Gửi storyboard có sẵn</b>\n\n"
            "Gửi ảnh, tài liệu hoặc PDF storyboard. Có thể gửi nhiều ảnh liên tiếp; hệ thống giữ nguyên phiên và "
            "đếm panel đã nhận để anh/chị xác nhận trước khi chọn tỉ lệ.\n\n"
            "Bước này chỉ lưu tư liệu trong phiên, chưa tạo tác vụ, chưa xử lý video và chưa trừ Xu.",
            storyboard2_upload_wait_keyboard(),
        )
    if screen in {"upload_review", "await_upload_count"}:
        files = list(board.get("uploaded_storyboard_files") or [])
        detected = int(board.get("detected_panel_count") or 0)
        suffix = "\n\nHãy gửi số cảnh từ 2 đến 20." if screen == "await_upload_count" else ""
        return (
            "📎 <b>Đã nhận storyboard</b>\n\n"
            f"• Tệp/ảnh đã nhận: <b>{len(files)}</b>\n"
            f"• Số panel/cảnh phát hiện: <b>{detected or 'Chưa xác định'}</b>\n\n"
            "Xác nhận số cảnh phát hiện hoặc sửa lại trước khi chọn tỉ lệ. Các panel chưa tạo video và chưa trừ Xu."
            + suffix,
            storyboard2_upload_review_keyboard(),
        )
    if screen == "upload_panels":
        files = list(board.get("uploaded_storyboard_files") or [])
        panel_index = max(1, min(max(1, len(files)), int(board.get("upload_panel_index") or 1)))
        item = dict(files[panel_index - 1]) if files else {}
        return (
            f"👁️ <b>Panel/tệp {panel_index}/{max(1, len(files))}</b>\n\n"
            f"• Tên: <b>{html.escape(str(item.get('file_name') or 'Ảnh storyboard'))}</b>\n"
            f"• Loại: <b>{html.escape(str(item.get('mime_type') or 'image'))}</b>\n"
            f"• Ghi chú: {html.escape(str(item.get('caption') or 'Không có'))}\n\n"
            "Đây là bản xem thông tin, chưa tạo tệp đầu ra và chưa trừ Xu.",
            storyboard2_upload_panels_keyboard(),
        )
    if screen == "help":
        return (
            "ℹ️ <b>Storyboard hoạt động thế nào?</b>\n\n"
            "Chọn số cảnh và tỉ lệ → viết nội dung → chuẩn bị ảnh đầu/ảnh cuối theo cảnh → "
            "duyệt câu lệnh chuyển động → chọn chuyển cảnh và phần bổ sung → chọn gói, xem hóa đơn rồi xác nhận.\n\n"
            "Ảnh AI có hóa đơn và xác nhận riêng. Video chỉ trừ Xu sau khi video hợp lệ đã được gửi thành công.",
            storyboard2_keyboard(storyboard2_nav("vstory|entry")),
        )
    if screen in {"count", "await_count"}:
        suffix = "\n\nHãy gửi một số từ 2 đến 20." if screen == "await_count" else ""
        return (
            "🔢 <b>Chọn số cảnh Storyboard</b>\n\n"
            "Mỗi cảnh là một ý hoặc hành động trọn vẹn. Thời lượng mỗi cảnh và tổng giá được tính theo gói Chất lượng ở bước cuối; "
            "hãy chọn vừa đủ nội dung, hệ thống không tự tăng số cảnh."
            + suffix,
            storyboard2_count_keyboard(),
        )
    if screen == "ratio":
        return (
            "📐 <b>Chọn tỉ lệ Storyboard</b>\n\n"
            f"• Số cảnh: <b>{count}</b>\n"
            "Tỉ lệ này được giữ cho câu lệnh ảnh, ảnh tạo AI và video của toàn bộ cảnh. Bước này chưa xử lý dữ liệu.",
            storyboard2_ratio_keyboard(board),
        )
    if screen == "content_source":
        return (
            "🎯 <b>Chọn nguồn nội dung Storyboard</b>\n\n"
            f"• Số cảnh: <b>{count}</b> · Tỉ lệ: <b>{html.escape(ratio)}</b>\n\n"
            "Chọn đúng một nguồn. 32 loại nội dung, Kho Ý tưởng video và Tự nhập là ba nhánh riêng; "
            "không trộn preset vào màn profile.",
            storyboard2_content_source_keyboard(),
        )
    if screen == "profiles":
        profile_rows, selected_page, page_count = storyboard2_profile_rows(safe_int(board.get("profile_page"), 1))
        labels = "\n".join(
            f"• {html.escape(str(item.get('icon') or '🎬'))} {html.escape(str(item.get('public_name') or ''))}"
            for item in profile_rows
        )
        return (
            "🎯 <b>Chọn loại nội dung Storyboard</b>\n\n"
            f"• Số cảnh: <b>{count}</b> · Tỉ lệ: <b>{html.escape(ratio)}</b>\n\n"
            f"Trang {selected_page}/{page_count} trong 32 loại nội dung. Chỉ chọn một loại để nhận 20 gợi ý liên quan, mỗi lần hiện 5 gợi ý.\n\n"
            f"{labels}",
            storyboard2_profiles_keyboard(board),
        )
    if screen == "content_choice":
        # Read-only compatibility for sessions created by the old duplicate
        # content-choice screen. The canonical destination is the source menu.
        board = video_storyboard2.move(board, "content_source", push=False, awaiting_input="")
        return storyboard2_screen_payload(board)
    if screen == "await_content":
        entry_mode = str(board.get("entry_mode") or "guided")
        title = "Gửi storyboard có sẵn" if entry_mode == "existing" else "Nhập nội dung Storyboard"
        back_callback = "vstory|upload_review" if entry_mode == "existing" else "vstory|content_screen"
        return (
            f"✍️ <b>{title}</b>\n\n"
            "Mô tả chủ thể, mục tiêu, diễn biến và điều người xem cần ghi nhớ. Hệ thống sẽ chia đúng số cảnh đã chọn, "
            "mỗi cảnh trọn một ý và không cắt giữa hành động.",
            storyboard2_keyboard(storyboard2_nav(back_callback)),
        )
    if screen == "suggestions":
        suggestions = video_storyboard2.suggestion_page(board)
        profile = dict(board.get("profile") or {})
        lines = [
            "💡 <b>5 gợi ý Storyboard</b>",
            "",
            f"• Loại nội dung: <b>{html.escape(str(profile.get('label') or 'Đã chọn'))}</b>",
            f"• Bộ gợi ý: <b>{int(board.get('suggestion_offset') or 0) // 5 + 1}/4</b>",
            f"Mỗi gợi ý sẽ được chia thành đúng <b>{count}</b> cảnh ở tỉ lệ <b>{html.escape(ratio)}</b>.",
            "",
        ]
        for item in suggestions:
            lines.append(f"{item['index']}. <b>{html.escape(item['title'])}</b>: {html.escape(item['content'])}")
        lines.extend(["", "Chọn một số hoặc đổi sang 5 gợi ý tiếp theo. Chưa tạo tác vụ và chưa trừ Xu."])
        return "\n".join(lines), storyboard2_suggestion_keyboard(board)
    if screen in {"scene_review", "await_scene_edit"}:
        if screen == "await_scene_edit":
            return (
                f"✍️ <b>Sửa nội dung cảnh {index}/{count}</b>\n\n"
                f"Hiện tại: {html.escape(str(scene.get('content') or ''))}\n\n"
                "Gửi lại một ý/hành động hoàn chỉnh cho riêng cảnh này.",
                storyboard2_keyboard(storyboard2_nav("vstory|scene_screen")),
            )
        return (
            f"🎞️ <b>Nội dung cảnh {index}/{count}</b>\n\n"
            f"• Ý cảnh: {html.escape(str(scene.get('content') or ''))}\n"
            f"• Bắt đầu: {html.escape(str(scene.get('start_state') or ''))}\n"
            f"• Hành động: {html.escape(str(scene.get('main_action') or ''))}\n"
            f"• Kết thúc: {html.escape(str(scene.get('end_state') or ''))}\n\n"
            "Mỗi cảnh phải kết thúc hành động và chuyển động camera trước khi nối cảnh sau.",
            storyboard2_scene_review_keyboard(board),
        )
    if screen == "asset_overview":
        summary = video_storyboard2.asset_summary(board)
        active_scene_index = max(1, min(count, int(board.get("active_scene_index") or 1)))
        active_slot = str(board.get("active_slot") or "start")
        if active_slot == "end" and board.get("asset_mode") != "start_end":
            active_slot = "start"
        selected_scene = dict((board.get("scenes") or [])[active_scene_index - 1])
        selected_image = dict(selected_scene.get(f"{active_slot}_image") or {})
        selected_label = "ảnh đầu" if active_slot == "start" else "ảnh cuối"
        lines = [
            "🗂️ <b>Sắp xếp / thay ảnh Storyboard</b>",
            "",
            f"• Đang chọn: <b>{selected_label} cảnh {active_scene_index}</b> · "
            f"<b>{'Đã có' if selected_image.get('status') == 'ready' else 'Chưa có'}</b>",
            "",
        ]
        for scene_item in board.get("scenes") or []:
            scene_number = int(scene_item.get("scene_index") or 0)
            start_image = dict(scene_item.get("start_image") or {})
            end_image = dict(scene_item.get("end_image") or {})
            end_status = (
                "Đã có"
                if end_image.get("status") == "ready"
                else ("Không dùng" if end_image.get("status") == "not_used" else "Chưa có")
            )
            lines.append(
                f"• Cảnh {scene_number}: ảnh đầu "
                f"<b>{'Đã có' if start_image.get('status') == 'ready' else 'Chưa có'}</b> · "
                f"ảnh cuối <b>{end_status}</b>"
            )
        lines.extend([
            "",
            f"Tổng: <b>{summary['ready_images']}/{summary['required_images']}</b> ảnh cần dùng · "
            f"đủ ảnh đầu <b>{summary['ready_start']}/{count}</b> cảnh.",
            "Chọn Ảnh trước/Ảnh sau để đổi mục đang thao tác. Thay, xóa hoặc đổi vị trí chỉ áp dụng cho ảnh đang chọn.",
        ])
        return "\n".join(lines), storyboard2_asset_overview_keyboard(board)
    if screen in {"assets", "await_image"}:
        summary = video_storyboard2.asset_summary(board)
        target = video_storyboard2.next_missing_image_target(board)
        mode_label = "hai ảnh/cảnh (ảnh đầu rồi ảnh cuối)" if board.get("asset_mode") == "start_end" else "một ảnh đầu/cảnh"
        wait_copy = ""
        if screen == "await_image":
            pending_image_action = str(board.get("awaiting_input") or "")
            if pending_image_action == "image_upload_replace":
                replace_slot = str(board.get("active_slot") or "start")
                replace_label = "ảnh đầu" if replace_slot == "start" else "ảnh cuối"
                wait_copy = (
                    f"\n\n📎 Hãy gửi ảnh mới để thay <b>{replace_label} cảnh {index}</b>. "
                    "Ảnh mới chỉ thay đúng mục này."
                )
            elif target:
                slot_label = "ảnh đầu" if target.get("slot") == "start" else "ảnh cuối"
                wait_copy = (
                    f"\n\n📎 Đang nhận theo thứ tự: <b>{slot_label} cảnh {int(target.get('scene_index') or 1)}</b>. "
                    "Gửi tiếp ảnh PNG/JPG/WEBP vào cùng màn này; hệ thống tự gắn đúng cảnh."
                )
            else:
                wait_copy = "\n\n✅ Đã nhận đủ ảnh theo chế độ đã chọn."
        scene_lines = []
        for scene_item in board.get("scenes") or []:
            scene_index = int(scene_item.get("scene_index") or 0)
            start_ready = dict(scene_item.get("start_image") or {}).get("status") == "ready"
            end_ready = dict(scene_item.get("end_image") or {}).get("status") == "ready"
            if board.get("asset_mode") == "start_end":
                scene_lines.append(
                    f"• Cảnh {scene_index}: ảnh đầu <b>{'Đã có' if start_ready else 'Chưa có'}</b> · "
                    f"ảnh cuối <b>{'Đã có' if end_ready else 'Chưa có'}</b>"
                )
            else:
                scene_lines.append(f"• Cảnh {scene_index}: ảnh đầu <b>{'Đã có' if start_ready else 'Chưa có'}</b>")
        await_keyboard = (
            storyboard2_keyboard(storyboard2_nav("vstory|asset_view"))
            if screen == "await_image" and str(board.get("awaiting_input") or "") == "image_upload_replace"
            else storyboard2_asset_keyboard(board)
        )
        return (
            "🖼️ <b>Ảnh Storyboard</b>\n\n"
            f"• Chế độ: <b>{mode_label}</b>\n"
            f"• Đã có: <b>{summary['ready_images']}/{summary['required_images']}</b> ảnh cần dùng\n\n"
            + "\n".join(scene_lines)
            + "\n\nMột nút nhận toàn bộ ảnh; ảnh được gắn lần lượt cho các cảnh, ảnh đầu trước rồi ảnh cuối. "
            "Tạo ảnh AI dùng thẳng nội dung và câu lệnh Storyboard đã chọn, không mở thêm bộ gợi ý chung."
            + wait_copy,
            await_keyboard,
        )
    if screen in {"image_prompt", "await_image_prompt", "await_image_negative"}:
        slot = str(board.get("active_slot") or "start")
        slot_label = "ảnh đầu" if slot == "start" else "ảnh cuối"
        if screen == "await_image_prompt":
            return (
                f"✍️ <b>Nhập prompt {slot_label} · cảnh {index}/{count}</b>\n\n"
                "Câu lệnh phải giữ đúng nội dung cảnh, tỉ lệ, nhận diện và trạng thái đầu/cuối đã chọn.",
                storyboard2_keyboard(storyboard2_nav("vstory|image_prompt_screen")),
            )
        if screen == "await_image_negative":
            return (
                f"🚫 <b>Sửa yêu cầu loại trừ · {slot_label} cảnh {index}</b>\n\n"
                "Gửi những chi tiết không được xuất hiện trong ảnh.",
                storyboard2_keyboard(storyboard2_nav("vstory|image_prompt_screen")),
            )
        offset = int(board.get("image_prompt_offset") or 0)
        lines = [
            f"✨ <b>Câu lệnh {slot_label} · cảnh {index}/{count}</b>",
            "",
            "Chọn một biến thể bố cục. Cả năm đều kế thừa đúng ý tưởng, nội dung cảnh, tỉ lệ, nhận diện và mạch cảnh.",
            "",
        ]
        for choice in range(1, 6):
            prompt = video_storyboard2.image_prompt(board, index, slot, offset + choice - 1)
            lines.append(f"{choice}. {html.escape(prompt['prompt'][:220])}…")
        lines.extend(["", "Sau khi chọn, hệ thống mở gói ảnh và hóa đơn riêng; chưa tạo ảnh ở màn này."])
        return "\n".join(lines), storyboard2_image_prompt_keyboard()
    if screen in {"video_prompts", "await_video_prompt", "await_video_negative"}:
        if screen == "await_video_prompt":
            return (
                f"✍️ <b>Sửa câu lệnh video · cảnh {index}/{count}</b>\n\nGửi câu lệnh chuyển động hoàn chỉnh cho riêng cảnh này.",
                storyboard2_keyboard(storyboard2_nav("vstory|video_screen")),
            )
        if screen == "await_video_negative":
            return (
                f"🚫 <b>Sửa yêu cầu loại trừ · cảnh {index}/{count}</b>\n\nGửi những lỗi/chuyển động không được xuất hiện.",
                storyboard2_keyboard(storyboard2_nav("vstory|video_screen")),
            )
        return (
            f"🎬 <b>Câu lệnh video · cảnh {index}/{count}</b>\n\n"
            f"{html.escape(str(scene.get('video_prompt') or 'Chưa có câu lệnh'))}\n\n"
            f"Loại trừ: {html.escape(str(scene.get('video_negative_prompt') or scene.get('negative_constraints') or ''))}\n\n"
            "Câu lệnh dùng đúng ảnh đầu, ảnh cuối nếu có và hoàn tất hành động trong 8 giây.",
            storyboard2_video_prompt_keyboard(),
        )
    if screen == "transitions":
        transitions = list(board.get("transitions") or [])
        if not transitions:
            return (
                "🔗 <b>Chuyển cảnh</b>\n\nStoryboard một cảnh không cần điểm nối. Bấm Xong chuyển cảnh để tiếp tục.",
                storyboard2_keyboard([
                    [("✅ Tiếp tục Add-on", "vstory|transition_done"), ("🎬 Xem câu lệnh", "vstory|video_screen")],
                    *storyboard2_nav("vstory|video_screen"),
                ]),
            )
        transition_index = max(1, min(len(transitions), int(board.get("transition_index") or 1)))
        item = transitions[transition_index - 1]
        return (
            f"🔗 <b>Chuyển cảnh {transition_index}/{len(transitions)}</b>\n\n"
            f"• Cảnh {transition_index} → {transition_index + 1}: <b>{html.escape(str(item.get('transition') or 'Cắt theo hành động'))}</b>\n\n"
            "Chọn kiểu nối phù hợp với trạng thái cuối cảnh trước và trạng thái đầu cảnh sau.",
            storyboard2_transition_keyboard(),
        )
    if screen == "addons":
        return (
            "🎚️ <b>Add-on Storyboard</b>\n\n"
            "Chỉ bật mục thực sự cần. Các mục âm thanh, phụ đề, logo và watermark dùng cùng cấu hình hậu kỳ canonical; "
            "chưa tạo file và chưa trừ Xu.",
            storyboard2_addon_keyboard(board),
        )
    if screen == "review":
        summary = video_storyboard2.asset_summary(board)
        capability = video_storyboard2.required_capability(board)
        addons = [key for key, enabled in dict(board.get("addons") or {}).items() if enabled]
        return (
            "📋 <b>Xem lại bảng phân cảnh</b>\n\n"
            f"• Nội dung: {html.escape(str(board.get('content') or ''))}\n"
            f"• Số cảnh: <b>{count}</b> · khoảng <b>{count * 8} giây</b>\n"
            f"• Tỉ lệ: <b>{html.escape(ratio)}</b>\n"
            f"• Ảnh đầu: <b>{summary['ready_start']}/{count}</b> · Ảnh cuối: <b>{summary['ready_end']}/{count}</b>\n"
            f"• Chế độ ảnh: <b>{'Ảnh đầu + ảnh cuối' if capability == 'first_last_frame_video' else 'Một ảnh đầu mỗi cảnh'}</b>\n"
            f"• Điểm nối: <b>{len(board.get('transitions') or [])}/{max(0, count - 1)}</b>\n"
            f"• Add-on: <b>{html.escape(', '.join(addons) if addons else 'Không thêm')}</b>\n\n"
            "Bấm Hoàn thiện video để kiểm tra package/công nghệ phù hợp rồi mới mở hóa đơn.",
            storyboard2_review_keyboard(),
        )
    return storyboard2_entry_text(), storyboard2_entry_keyboard()


async def storyboard2_render(query, context, board: dict | None = None):
    current = video_storyboard2.normalize_state(board or storyboard2_state(context))
    text, keyboard = storyboard2_screen_payload(current)
    return await safe_edit_or_send(query, text, parse_mode="HTML", reply_markup=keyboard)


def storyboard2_scene3_handoff(context, board: dict) -> dict:
    board = video_storyboard2.normalize_state(board)
    pure_preflight = video_storyboard2.preflight(board)
    if not pure_preflight.get("ok"):
        raise ValueError(str(pure_preflight.get("block_reason") or "storyboard_preflight_failed"))
    outer = video_profile_studio_state(context)
    manifest = dict(pure_preflight.get("manifest") or {})
    asset_items = []
    image_prompt_versions = {}
    video_prompt_versions = {}
    image_strategy_per_scene = {}
    plan_scenes = []
    for scene in board.get("scenes") or []:
        scene_index = int(scene.get("scene_index") or 0)
        for slot in ("start", "end"):
            image = dict(scene.get(f"{slot}_image") or {})
            if image.get("status") != "ready":
                continue
            asset_items.append({
                "type": "storyboard_start_image" if slot == "start" else "storyboard_end_image",
                "slot": slot,
                "scene_id": str(scene.get("scene_id") or f"scene_{scene_index}"),
                "scene_index": scene_index,
                "media_kind": "image",
                "file_id": str(image.get("file_id") or ""),
                "result_url": str(image.get("result_url") or ""),
                "image_id": str(image.get("image_id") or ""),
                "source_type": str(image.get("source_type") or ""),
                "artifact_receipt": dict(image.get("artifact_receipt") or {}),
                "prompt_version": int(image.get("prompt_version") or 0),
            })
        start_prompt = dict(scene.get("start_image") or {})
        start_source = str(start_prompt.get("source_type") or "").strip().lower()
        image_strategy_per_scene[str(scene_index)] = {
            "strategy": "create" if start_source == "quick_image_paid_delivery" else "uploaded",
            "approved": True,
        }
        image_prompt_versions[str(scene_index)] = {
            "active_version": max(1, int(start_prompt.get("prompt_version") or 1)),
            "versions": [{
                "version": max(1, int(start_prompt.get("prompt_version") or 1)),
                "prompt": str(start_prompt.get("prompt") or ""),
                "negative_prompt": str(start_prompt.get("negative_prompt") or ""),
            }],
        }
        video_version = max(1, int(scene.get("video_prompt_version") or 1))
        video_prompt_versions[str(scene_index)] = {
            "active_version": video_version,
            "versions": [{
                "version": video_version,
                "prompt": str(scene.get("video_prompt") or ""),
                "provider_prompt": str(scene.get("video_prompt") or ""),
                "negative_prompt": str(scene.get("video_negative_prompt") or ""),
                "provider_negative_prompt": str(scene.get("video_negative_prompt") or ""),
            }],
        }
        plan_scenes.append({
            "scene_index": scene_index,
            "scene_id": str(scene.get("scene_id") or f"scene_{scene_index}"),
            "scene_role": "storyboard_panel",
            "duration_seconds": 8,
            "main_idea": str(scene.get("content") or ""),
            "subject": str(board.get("content") or ""),
            "start_state": str(scene.get("start_state") or ""),
            "primary_action": str(scene.get("main_action") or ""),
            "completion_state": str(scene.get("end_state") or ""),
            "camera": str(scene.get("camera_motion") or ""),
            "visual_style": "Storyboard nhất quán theo ảnh đã chọn",
            "environment": "Giữ đúng bối cảnh trong ảnh Storyboard",
            "lighting": "Giữ ánh sáng và màu nhận diện nhất quán",
            "audio_intent": "Theo add-on đã chọn",
            "dialogue_or_voiceover": "",
            "preserve_constraints": [str(scene.get("negative_constraints") or "")],
            "provider_prompt": str(scene.get("video_prompt") or ""),
            "negative_prompt": str(scene.get("video_negative_prompt") or ""),
            "start_image_id": str((scene.get("start_image") or {}).get("image_id") or ""),
            "end_image_id": str((scene.get("end_image") or {}).get("image_id") or ""),
        })
    post_entries = dict(outer.get("postproduction_addons") or {})
    selected_addons = dict(board.get("addons") or {})
    addon_map = {
        "dubbing": "dubbing",
        "subtitles": "subtitles",
        "music": "music",
        "sfx": "sfx",
        "logo": "logo_image",
        "source_audio": "source_audio",
    }
    for source_key, target_key in addon_map.items():
        entry = dict(post_entries.get(target_key) or {})
        entry["enabled"] = bool(selected_addons.get(source_key))
        post_entries[target_key] = entry
    runtime_post = {
        "dubbing_mix": bool(selected_addons.get("dubbing")),
        "subtitle_rendering": bool(selected_addons.get("subtitles")),
        "source_audio": bool(selected_addons.get("source_audio")),
        "music_mix": bool(selected_addons.get("music")),
        "sfx_mix": bool(selected_addons.get("sfx")),
        "logo_burn_in": bool(selected_addons.get("logo")),
    }
    plan = {
        "profile_id": "storytelling",
        "scenes": plan_scenes,
        "continuity_contract": dict(board.get("continuity") or {}),
        "addon_plan": {
            "content_affecting": {"aspect_ratio": str(board.get("aspect_ratio") or "9:16")},
            "post_production": runtime_post,
        },
        "quality_gate": {"ok": True, "blockers": []},
    }
    outer.update({
        "storyboard2": board,
        "step": "quality",
        "source_product_id": "storyboard_prompt",
        "product_type": "storyboard_prompt",
        "flow_kind": "storyboard",
        "content_mode": "manual",
        "subject": str(board.get("content") or ""),
        "scene_count": int(board.get("scene_count") or 0),
        "aspect_ratio": str(board.get("aspect_ratio") or ""),
        "asset_requirement": "images_required",
        "image_source_mode": "uploaded",
        "image_strategy_per_scene": image_strategy_per_scene,
        "primary_profile": "storytelling",
        "technical_profile": "storytelling",
        "plan": plan,
        "scene_plan": plan,
        "continuity_contract": dict(board.get("continuity") or {}),
        "reference_assets": {
            "items": asset_items,
            "source_media_refs": [str(item.get("file_id") or item.get("result_url") or "") for item in asset_items],
            "storyboard_manifest": manifest,
        },
        "assets": {
            "items": asset_items,
            "source_media_refs": [str(item.get("file_id") or item.get("result_url") or "") for item in asset_items],
            "storyboard_manifest": manifest,
        },
        "image_prompt_versions": image_prompt_versions,
        "video_prompt_versions": video_prompt_versions,
        "transition_plan": list(board.get("transitions") or []),
        "postproduction_addons": post_entries,
        "storyboard_selected_addons": selected_addons,
        "required_capability": str(pure_preflight.get("required_capability") or "image_to_video"),
        "storyboard_manifest": manifest,
        "quality_xu": 0,
        "quality_tier": 0,
        "provider_called": False,
        "image_provider_called": False,
        "job_created": False,
        "outbox_created": False,
        "files_generated": 0,
        "wallet_mutations": 0,
        "xu_charged": 0,
    })
    outer = video_flow6.sync_scene_state(outer)
    route = video_flow6.execution_route_for(video_flow6.context_from_scene_state(outer))
    route.update({
        "job_type": "storyboard_to_video",
        "execution_owner": "owner_product_video",
        "route": "storyboard_to_video",
    })
    outer["execution_route"] = route
    return save_video_profile_studio_state(context, outer)


def video_profile_studio_pop_step(context, state: dict) -> dict:
    history = list(state.get("history") or [])
    step = history.pop() if history else "menu"
    return save_video_profile_studio_state(context, {**state, "step": step, "history": history})


def video_scene3_return_to_parent(handler_context, state: dict, parent: str, **fields) -> dict:
    history = list(state.get("history") or [])
    if history and history[-1] == parent:
        history.pop()
    return save_video_profile_studio_state(
        handler_context,
        {**state, **fields, "step": str(parent), "history": history},
    )


def video_scene2_action_allowed(state: dict, action: str) -> bool:
    expected = VIDEO_SCENE2_ACTION_EXPECTED_STEPS.get(str(action or ""))
    return expected is None or str((state or {}).get("step") or "") in expected


def video_scene2_reconcile_state(context, state: dict) -> dict:
    state = video_flow6.sync_scene_state(dict(state or {}))
    flow_context = video_flow6.context_from_scene_state(state)
    flow_kind = str(flow_context.get("flow_kind") or "ai_real")
    step = str(state.get("step") or "")
    early_source_steps = {
        "content_mode", "scene_count", "await_count_custom", "aspect_ratio",
        "await_ratio_custom", "ai_input_type", "content_source",
    }
    pre_asset_steps = early_source_steps - {"content_source"}
    if (
        str(state.get("content_mode") or "") not in video_flow6.CONTENT_MODES
        and step not in early_source_steps
    ):
        return video_profile_studio_step(context, state, "content_mode", push=False)
    scene_count = safe_int(state.get("scene_count"), 0)
    if scene_count < 1 or scene_count > 20:
        return video_profile_studio_step(context, state, "scene_count", push=False, scene_count=0)
    if str(state.get("aspect_ratio") or "") not in video_flow6.SUPPORTED_RATIOS:
        return video_profile_studio_step(context, state, "aspect_ratio", push=False, aspect_ratio="")
    valid_steps = set(VIDEO_SCENE1_CANONICAL_STEPS) | {
        "menu", "content_type", "subject", "await_subject", "await_count_custom", "await_ratio_custom", "ai_input_type", "content_source", "await_suggestion", "await_flow6_asset_upload",
        "await_profile_custom", "await_character_description", "await_automatic_text", "await_automatic_text_coordinates", "await_automatic_text_timestamp", "await_post_volume",
        "await_requirement", "await_creative", "await_content_addon", "await_material_upload", "await_material_caption",
        "await_scene_edit", "await_scene_regen", "await_reorder",
        "await_image_prompt", "await_image_negative", "await_video_prompt", "await_video_negative",
        "await_post_config", "await_post_text", "await_post_asset_upload",
        "requirement_detail", "materials_manage", "creative_detail", "creative_suggestions", "content_detail", "content_suggestions", "content_position",
        "profile_links", "profile_suggestions",
        "scene_detail", "transitions", "transition_picker", "logo_position", "post_detail", "post_position", "post_volume", "quality_guide", "image_quote",
        "automatic_text_review", "automatic_text_position", "automatic_text_scope", "automatic_text_timing", "automatic_text_target", "automatic_text_duration", "automatic_text_animation", "automatic_text_style",
    }
    if step not in valid_steps or step in {"menu", "subject", "await_subject"}:
        return video_profile_studio_step(context, state, "scene_count", push=False)
    if not str(state.get("content_type") or ""):
        state["content_type"] = video_scene3_flow.suggested_content_type(state)
    if flow_kind == "ai_real" and step in {"content_type", "profile_links"}:
        return video_profile_studio_step(context, state, "technical_profile", push=False)
    content_source = str(state.get("content_source") or "")
    gate = video_flow6.asset_gate_status(flow_context)
    if (
        gate["requirement"] != "optional"
        and step not in pre_asset_steps | {"asset_gate", "await_flow6_asset_upload"}
        and not gate["ok"]
    ):
        return video_profile_studio_step(context, state, "asset_gate", push=False)
    if (
        flow_kind == "ai_real"
        and content_source == "profiles"
        and step not in early_source_steps | {"asset_gate", "await_flow6_asset_upload", "technical_profile", "profile_suggestions"}
        and not str(state.get("primary_profile") or state.get("technical_profile") or "")
    ):
        return video_profile_studio_step(context, state, "technical_profile", push=False)
    if (
        flow_kind == "ai_real"
        and content_source == "profiles"
        and step not in {
            *early_source_steps, "asset_gate", "await_flow6_asset_upload",
            "technical_profile", "profile_suggestions", "content_choice", "await_suggestion",
        }
        and not dict(state.get("content_choice") or state.get("selected_suggestion") or {})
    ):
        return video_profile_studio_step(context, state, "content_choice", push=False)
    return save_video_profile_studio_state(context, state)


def video_profile_studio_option(selection_id: str) -> dict:
    selection_id = str(selection_id or "").strip()
    for item in profile_router.STUDIO_PROFILE_OPTIONS:
        if str(item.get("selection_id") or "") == selection_id:
            return dict(item)
    return {}


