def video_scene3_scene_plan_text(state: dict) -> str:
    plan = dict(state.get("plan") or {})
    scenes = [dict(item) for item in plan.get("scenes") or []]
    lines = [
        "🎞 <b>Kế hoạch cảnh hoàn chỉnh</b>", "",
        f"• Chủ đề: {html.escape(str(state.get('subject') or '')[:220])}",
        f"• Video Profile: <b>{html.escape(video_profile_public_label(state))}</b>",
        f"• Số cảnh: <b>{len(scenes)}/{safe_int(state.get('scene_count'), 1)}</b> · khoảng <b>{len(scenes) * 8}s</b>", "",
    ]
    for scene in scenes[:20]:
        lines.append(
            f"• <b>Cảnh {safe_int(scene.get('scene_index'), 0)}</b>: "
            f"{html.escape(video_scene3_flow.public_planning_text(scene.get('main_idea'))[:150])} "
            f"→ {html.escape(video_scene3_flow.public_planning_text(scene.get('completion_state'))[:110])}"
        )
    lines.extend([
        "",
        "Mỗi cảnh là một ý/hành động trọn vẹn; không cắt giữa câu nói, hành động hoặc chuyển động camera.",
        "Chuyển cảnh sẽ được chọn ở bước riêng sau khi câu lệnh từng cảnh đã hoàn chỉnh.",
    ])
    return "\n".join(lines)


