def video_scene3_image_strategy_text(state: dict) -> str:
    if bool((state or {}).get("storyboard_image_required")):
        return video_scene3_image_source_text(state)
    return video_scene3_image_source_text(state)


def video_scene3_image_strategy_keyboard(state: dict | None = None) -> InlineKeyboardMarkup:
    return video_scene3_image_source_keyboard(state)


def video_scene3_storyboard_image_sources_ready(state: dict) -> bool:
    if not bool((state or {}).get("storyboard_image_required")):
        return True
    allowed = {"uploaded_image", "ai_image"}
    strategies = dict((state or {}).get("image_strategy_per_scene") or {})
    scene_count = max(1, safe_int((state or {}).get("scene_count"), 1))
    return all(
        str((strategies.get(str(index)) or {}).get("strategy") or "") in allowed
        for index in range(1, scene_count + 1)
    )


def video_scene3_prompt_text(state: dict, kind: str) -> str:
    index = video_scene3_active_scene(state)
    collection = state.get("image_prompt_versions" if kind == "image" else "video_prompt_versions") or {}
    entry = dict(collection.get(str(index)) or {})
    prompt = video_scene3_flow.active_prompt(entry)
    title = "Câu lệnh ảnh" if kind == "image" else "Câu lệnh video"
    explanation = (
        "Câu lệnh AI mô tả khung hình cần tạo. Yêu cầu loại trừ là những lỗi/hình ảnh không được xuất hiện."
        if kind == "image" else
        "Câu lệnh video mô tả trọn trạng thái đầu, hành động, diễn biến và trạng thái kết thúc của riêng cảnh này."
    )
    transition_line = ""
    structure = ""
    if kind == "video":
        outgoing = dict(prompt.get("transition_out") or {})
        transition_line = f"\n• Chuyển tiếp: {html.escape(str(outgoing.get('label') or 'Kết thúc trọn vẹn'))} — {html.escape(str(outgoing.get('description') or ''))}"
        structure = (
            "\n\n<b>Cấu trúc cảnh</b>\n"
            f"• Ý chính: {html.escape(str(prompt.get('main_idea') or prompt.get('goal') or '')[:220])}\n"
            f"• Bắt đầu: {html.escape(str(prompt.get('start_state') or '')[:220])}\n"
            f"• Hành động: {html.escape(str(prompt.get('action') or '')[:220])}\n"
            f"• Kết thúc: {html.escape(str(prompt.get('end_state') or '')[:220])}"
        )
    return (
        f"{'🖼' if kind == 'image' else '🎥'} <b>{title} · cảnh {index}/{safe_int(state.get('scene_count'), 1)}</b>\n\n"
        f"• Phiên bản: <b>{safe_int(entry.get('active_version'), 1)}</b>\n"
        f"• Đã duyệt: <b>{'Có' if entry.get('approved') else 'Chưa'}</b>{transition_line}{structure}\n\n"
        f"<b>Nội dung đầy đủ</b>\n{html.escape(str(prompt.get('prompt') or ''))}\n\n"
        f"<b>Yêu cầu loại trừ đầy đủ</b>\n{html.escape(str(prompt.get('negative_prompt') or ''))}\n\n"
        f"{explanation} Chưa gọi dịch vụ tạo ảnh/video."
    )


def video_scene3_prompt_copy_text(state: dict, kind: str) -> str:
    index = video_scene3_active_scene(state)
    collection = state.get("image_prompt_versions" if kind == "image" else "video_prompt_versions") or {}
    entry = dict(collection.get(str(index)) or {})
    prompt = video_scene3_flow.active_prompt(entry)
    title = "ảnh" if kind == "image" else "video"
    return (
        f"📋 <b>Bản sao câu lệnh {title} · cảnh {index}/{safe_int(state.get('scene_count'), 1)}</b>\n\n"
        f"<pre>{html.escape(str(prompt.get('prompt') or ''))}</pre>\n\n"
        f"<b>Yêu cầu loại trừ</b>\n<pre>{html.escape(str(prompt.get('negative_prompt') or ''))}</pre>\n\n"
        "Chạm giữ phần câu lệnh để sao chép. Đây chỉ là bản kế hoạch; hệ thống chưa gọi dịch vụ tạo ảnh/video."
    )


def video_scene3_prompt_keyboard(kind: str, state: dict | None = None) -> InlineKeyboardMarkup:
    prefix = "image" if kind == "image" else "video"
    state = state or {}
    if str(state.get("origin") or "").startswith("video_idea"):
        nav_rows = [[
            ("⬅️ Quay lại ý tưởng", str(state.get("idea_return_callback") or "videoidea|catalog_result")),
            ("🏠 Menu chính", "menu|main"),
        ]]
    else:
        nav_rows = video_scene3_nav_rows()
    return video_scene3_keyboard([
        [("💡 Gợi ý lại", f"vprofile|{prefix}_prompt_regen"), ("✍️ Sửa câu lệnh", f"vprofile|{prefix}_prompt_edit")],
        [("🚫 Sửa loại trừ", f"vprofile|{prefix}_negative_edit"), ("👁️ Xem đầy đủ", f"vprofile|{prefix}_prompt_view")],
        [("📋 Sao chép", f"vprofile|{prefix}_prompt_copy"), ("↩️ Khôi phục", f"vprofile|{prefix}_prompt_restore")],
        [("⬅️ Cảnh trước", f"vprofile|{prefix}_prompt_prev"), ("➡️ Cảnh sau", f"vprofile|{prefix}_prompt_next")],
        [("✅ Duyệt tất cả", f"vprofile|{prefix}_prompt_approve_all"), ("➡️ Xong phần này", f"vprofile|{prefix}_prompt_done")],
        *nav_rows,
    ])


def video_scene3_full_review_text(state: dict) -> str:
    counts = video_scene3_flow.scene_contract_counts(state)
    continuity = dict(state.get("continuity_contract") or {})
    plan = dict(state.get("plan") or {})
    scenes = [dict(item) for item in plan.get("scenes") or [] if isinstance(item, dict)]
    requirements = video_scene3_summary(
        state.get("preservation_requirements") or {},
        video_scene3_flow.PUBLIC_REQUIREMENT_CATEGORIES,
    )
    creative = video_scene3_summary(
        state.get("creative_controls") or {},
        video_scene3_flow.CREATIVE_CONTROLS,
    )
    post_without_text = tuple(
        item for item in video_scene3_flow.PUBLIC_POST_ADDONS
        if item[0] != "automatic_text"
    )
    lines = [
        "📋 <b>Xem lại toàn bộ kế hoạch</b>", "",
        f"• Chủ đề: {html.escape(str(state.get('subject') or '')[:220])}",
        f"• Video Profile: {html.escape(video_profile_public_label(state))}",
        f"• Tỉ lệ video: <b>{html.escape(str(state.get('aspect_ratio') or '9:16'))}</b>",
        f"• Hướng nội dung: {html.escape(str((state.get('selected_suggestion') or {}).get('title') or 'Theo yêu cầu riêng')[:180])}",
        f"• Ngữ cảnh: {html.escape(str(state.get('context') or state.get('profile_context') or 'Theo chủ đề đã chọn')[:320])}",
        f"• Cảnh: <b>{counts['scenes']}/{counts['expected']}</b> · khoảng <b>{counts['expected'] * 8}s</b>",
        f"• Nguồn hình: <b>{html.escape(dict(video_scene3_flow.IMAGE_SOURCE_MODES).get(str(state.get('image_source_mode') or ''), 'Chưa chọn'))}</b>",
        f"• Câu lệnh ảnh: <b>{counts['image_prompts']}/{counts['image_prompts_expected']}</b>",
        f"• Câu lệnh video: <b>{counts['video_prompts']}/{counts['expected']}</b>",
        f"• Tính nhất quán: <b>{len(continuity.get('must_remain_constant') or [])} ràng buộc</b>",
        f"• Tư liệu: <b>{len(((state.get('reference_assets') or {}).get('items') or []))} tệp</b>",
        f"• Yêu cầu giữ nguyên: {html.escape(requirements[:420])}",
        f"• Phong cách sáng tạo: {html.escape(creative[:420])}",
        f"• Lời thoại/âm thanh: {html.escape(video_scene3_summary(state.get('postproduction_addons') or {}, video_scene3_flow.AUDIO_PLANNING_ADDONS)[:500])}",
        f"• Chữ trên video: <b>{len(state.get('automatic_text_items') or [])} mục</b>",
        f"• Hậu kỳ: {html.escape(video_scene3_summary(state.get('postproduction_addons') or {}, post_without_text)[:500])}",
        "", "<b>Mạch cảnh</b>",
    ]
    image_versions = dict(state.get("image_prompt_versions") or {})
    video_versions = dict(state.get("video_prompt_versions") or {})
    for scene in scenes[:20]:
        scene_index = safe_int(scene.get("scene_index"), 0)
        outgoing = video_scene3_flow.transition_public(str(scene.get("transition_out") or ""))
        image_entry = dict(image_versions.get(str(scene_index)) or {})
        video_entry = dict(video_versions.get(str(scene_index)) or {})
        lines.append(
            f"• <b>Cảnh {scene_index}</b>: {html.escape(video_scene3_flow.public_planning_text(scene.get('main_idea'))[:115])} "
            f"· Ảnh bản {safe_int(image_entry.get('active_version'), 1)} "
            f"· Video bản {safe_int(video_entry.get('active_version'), 1)} "
            f"· {html.escape(outgoing['label'])}"
        )
    lines.extend([
        "",
        "Mỗi cảnh phải hoàn tất một ý hoặc hành động trước khi nối sang cảnh tiếp theo.",
        "Logo/Watermark và bản tổng hợp đã được giữ. Khi mọi phần đã đúng, tiếp tục sang Âm thanh & Add-on rồi chọn gói phù hợp.",
    ])
    return "\n".join(lines)[:4050]


def video_scene3_full_review_keyboard(state: dict) -> InlineKeyboardMarkup:
    return video_scene3_keyboard([
        [("👁️ Xem cảnh", "vprofile|scene_view|1"), ("✍️ Sửa cảnh", "vprofile|edit_scene")],
        [("🎬 Prompt video", "vprofile|review_video_prompts"), ("🔗 Chuyển cảnh", "vprofile|review_transitions")],
        [("📝 Chữ", "vprofile|review_text"), ("🎚️ Âm thanh", "vprofile|review_audio")],
        [("🖼️ Logo/Watermark", "vprofile|review_post"), ("⭐ Hoàn thiện video", "vprofile|review_continue")],
        *video_scene3_nav_rows(),
    ])


def video_scene3_post_text(state: dict) -> str:
    return (
        "🏷️ <b>Logo và watermark</b>\n\n"
        "Logo dùng ảnh; watermark dùng chữ. Hai mục được cấu hình riêng để dễ gửi đúng tư liệu, chọn đúng vị trí và không che mặt, sản phẩm hoặc phụ đề.\n\n"
        "Mỗi mục mặc định tắt và chỉ là kế hoạch cho đến khi hậu kỳ thật cùng video cuối được kiểm tra.\n\n"
        f"• Đang bật: {html.escape(video_scene3_summary(state.get('postproduction_addons') or {}, video_scene3_flow.PUBLIC_POST_ADDONS))}"
    )


def video_scene3_post_keyboard(state: dict) -> InlineKeyboardMarkup:
    entries = dict(state.get("postproduction_addons") or {})
    def _label(key: str, label: str, *, enabled: bool | None = None) -> str:
        active = (entries.get(key) or {}).get("enabled") if enabled is None else enabled
        return f"{'✅' if active else '☐'} {label}"

    return video_scene3_keyboard([
        [(_label("logo_image", "Logo hình"), "vprofile|post_toggle|logo_image"), (_label("watermark_text", "Watermark chữ"), "vprofile|post_toggle|watermark_text")],
        [("✅ Xong logo / watermark", "vprofile|post_done"), ("⏭️ Bỏ qua", "vprofile|post_skip")],
        [("⬅️ Quay lại", "vprofile|back"), ("🏠 Menu chính", "menu|main")],
    ])


def video_scene3_post_detail_text(state: dict) -> str:
    key = str(state.get("active_post_addon") or "")
    labels = dict(video_scene3_flow.POST_ADDONS)
    entry = dict((state.get("postproduction_addons") or {}).get(key) or {})
    value = dict(entry.get("value") or {}) if isinstance(entry.get("value"), dict) else {}
    lines = [
        f"🎛 <b>{html.escape(labels.get(key, 'Cấu hình hậu kỳ'))}</b>", "",
        f"• Trạng thái: <b>{'Đã thêm vào kế hoạch' if entry.get('enabled') else 'Đang tắt'}</b>",
    ]
    if key == "logo_image":
        lines.extend([
            f"• Ảnh logo: <b>{'Đã nhận' if value.get('asset_file_id') else 'Chưa gửi'}</b>",
            f"• Vị trí: <b>{html.escape(video_scene3_flow.logo_position_label(str(value.get('position') or '')))}</b>",
            "• Kích thước: <b>nhỏ, rộng 12% chiều ngang</b>",
            "• Giữ đúng tỉ lệ ảnh: <b>Có</b>",
            "",
            "Gửi ảnh logo trước, sau đó chọn vị trí. Logo không được kéo méo hoặc che chủ thể chính.",
        ])
    elif key == "watermark_text":
        lines.extend([
            f"• Nội dung: <b>{html.escape(str(value.get('text') or 'Chưa nhập')[:300])}</b>",
            f"• Vị trí: <b>{html.escape(video_scene3_flow.logo_position_label(str(value.get('position') or '')))}</b>",
            f"• Độ trong: <b>{safe_int(value.get('opacity_percent'), 45)}%</b>",
            "",
            "Nhập một dòng chữ bản quyền ngắn rồi chọn vị trí. Mục này không yêu cầu gửi ảnh.",
        ])
    elif key == "dubbing":
        voice_choice = str(value.get("voice_choice") or "")
        voice_label = video_scene3_public_config_value(
            "voice_choice",
            voice_choice or value.get("voice_type") or "not_selected",
        )
        lines.extend([
            f"• Giọng: <b>{html.escape(voice_label)}</b>",
            f"• Âm lượng: <b>{safe_int(value.get('volume_percent'), 100)}%</b>",
            f"• Lời thoại: <b>{html.escape(str(value.get('dialogue_text') or 'Chưa nhập')[:500])}</b>",
            "",
            "Chọn giọng nam, nữ, theo nhân vật đã xác định hoặc giọng riêng có quyền sử dụng. "
            "Nếu nhân vật chưa rõ giới tính, hệ thống yêu cầu chọn lại thay vì tự đoán.",
        ])
    elif key == "music":
        source_label = video_scene3_public_config_value(
            "music_source_choice",
            value.get("music_source_choice") or value.get("source") or "not_selected",
        )
        mode_label = video_scene3_public_config_value("vocal_mode", value.get("vocal_mode") or "instrumental")
        lines.extend([
            f"• Cách lấy nhạc: <b>{html.escape(source_label)}</b>",
            f"• Kiểu nhạc: <b>{html.escape(mode_label)}</b>",
            f"• Âm lượng: <b>{safe_int(value.get('volume_percent'), 20)}%</b>",
            f"• Yêu cầu/lời nhạc: <b>{html.escape(str(value.get('music_request') or 'Chưa nhập')[:500])}</b>",
            "",
            "Chọn nhạc có sẵn hoặc lập kế hoạch tạo nhạc mới, sau đó chọn có lời hay không lời. "
            "Bước này chưa tạo nhạc và chưa phát sinh chi phí.",
        ])
    else:
        lines.append(f"• Mẫu: <b>{html.escape(video_scene3_flow.post_addon_preset_label(key, value))}</b>")
        if key in {"subtitles", "text_overlay"}:
            lines.append(
                f"• Vị trí: <b>{html.escape(video_scene3_flow.logo_position_label(str(value.get('position') or 'bottom_center')))}</b>"
            )
        for field, label in VIDEO_SCENE3_CONFIG_FIELD_LABELS.items():
            if field not in value or value.get(field) in {None, ""} or field in {"applied_to_mp4", "completed"}:
                continue
            lines.append(f"• {html.escape(label.capitalize())}: {html.escape(video_scene3_public_config_value(field, value.get(field)))}")
    lines.extend(["", "Đây là cấu hình kế hoạch. Hệ thống chỉ báo đã áp dụng sau khi hậu kỳ thật và kiểm tra video cuối."])
    return "\n".join(lines)[:3900]


def video_scene3_post_detail_keyboard(state: dict) -> InlineKeyboardMarkup:
    key = str(state.get("active_post_addon") or "")
    entry = dict((state.get("postproduction_addons") or {}).get(key) or {})
    enabled_label = "🚫 Tắt mục này" if entry.get("enabled") else "✅ Bật mục này"
    value = dict(entry.get("value") or {}) if isinstance(entry.get("value"), dict) else {}
    if key == "logo_image":
        upload_label = "🔄 Đổi ảnh logo" if value.get("asset_file_id") else "📎 Gửi ảnh logo"
        return video_scene3_keyboard([
            [(upload_label, "vprofile|post_asset"), ("📍 Chọn vị trí", "vprofile|post_position")],
            [("🚫 Không dùng logo", "vprofile|post_remove"), ("↩️ Khôi phục", "vprofile|post_restore")],
            [("⬅️ Danh sách hậu kỳ", "vprofile|post_detail_done"), ("🏠 Menu chính", "menu|main")],
        ])
    if key == "watermark_text":
        text_label = "✍️ Sửa chữ bản quyền" if str(value.get("text") or "").strip() else "✍️ Nhập chữ bản quyền"
        return video_scene3_keyboard([
            [(text_label, "vprofile|post_text"), ("📍 Chọn vị trí", "vprofile|post_position")],
            [("🚫 Không dùng dấu bản quyền", "vprofile|post_remove"), ("↩️ Khôi phục", "vprofile|post_restore")],
            [("⬅️ Danh sách hậu kỳ", "vprofile|post_detail_done"), ("🏠 Menu chính", "menu|main")],
        ])
    if key == "dubbing":
        return video_scene3_keyboard([
            [("👨 Giọng nam", "vprofile|post_voice_choice|default_male"), ("👩 Giọng nữ", "vprofile|post_voice_choice|default_female")],
            [("🧑 Theo nhân vật", "vprofile|post_voice_choice|follow_character"), ("🎤 Giọng riêng", "vprofile|post_voice_choice|custom_voice")],
            [("📎 Gửi mẫu giọng", "vprofile|post_voice_upload"), ("✍️ Sửa lời thoại", "vprofile|post_edit")],
            [("🔉 Âm lượng", "vprofile|post_volume"), ("👁 Xem cấu hình", "vprofile|post_view")],
            [("↩️ Khôi phục", "vprofile|post_restore"), ("🚫 Tắt lồng tiếng", "vprofile|post_remove")],
            [("⬅️ Quay lại", "vprofile|post_detail_done"), ("🏠 Menu chính", "menu|main")],
        ])
    if key == "music":
        return video_scene3_keyboard([
            [("🎼 Chọn nhạc có sẵn", "vprofile|post_music_source|choose_existing"), ("✨ Tạo nhạc mới", "vprofile|post_music_source|create_new")],
            [("🎹 Không lời", "vprofile|post_music_mode|instrumental"), ("🎤 Có lời", "vprofile|post_music_mode|with_lyrics")],
            [("🔊 Chỉnh âm lượng", "vprofile|post_volume"), ("✍️ Yêu cầu/lời nhạc", "vprofile|post_edit")],
            [("↩️ Khôi phục", "vprofile|post_restore"), ("🗑 Không dùng nhạc", "vprofile|post_remove")],
            [("⬅️ Quay lại", "vprofile|post_detail_done"), ("🏠 Menu chính", "menu|main")],
        ])
    edit_label = {
        "subtitles": "✍️ Sửa nội dung phụ đề",
        "dubbing": "✍️ Sửa lời thoại",
        "music": "✂️ Sửa cắt/ghép nhạc",
        "source_audio": "✍️ Sửa cách giữ âm thanh",
    }.get(key, "✍️ Chỉnh nội dung")
    preset_label = {
        "subtitles": "🎨 Chọn kiểu phụ đề",
        "dubbing": "🌐 Chọn ngôn ngữ",
        "text_overlay": "🎨 Chọn kiểu chữ",
        "sfx": "🎧 Chọn hiệu ứng",
    }.get(key, "🎛 Chọn thiết lập")
    rows = [[(enabled_label, "vprofile|post_enable"), (preset_label, "vprofile|post_preset")]]
    if key in video_scene3_flow.AUDIO_POST_ADDONS:
        rows.append([("🔊 Chỉnh âm lượng", "vprofile|post_volume"), (edit_label, "vprofile|post_edit")])
        rows.append([("↩️ Khôi phục", "vprofile|post_restore"), ("🗑 Xóa khỏi kế hoạch", "vprofile|post_remove")])
    else:
        if key in {"subtitles", "text_overlay"}:
            rows.append([(edit_label, "vprofile|post_edit"), ("📍 Chọn vị trí", "vprofile|post_position")])
            rows.append([("↩️ Khôi phục", "vprofile|post_restore"), ("🗑 Xóa khỏi kế hoạch", "vprofile|post_remove")])
        else:
            rows.append([(edit_label, "vprofile|post_edit"), ("👁 Xem cấu hình", "vprofile|post_view")])
            rows.append([("↩️ Khôi phục", "vprofile|post_restore"), ("🗑 Xóa khỏi kế hoạch", "vprofile|post_remove")])
        rows.append([("⬅️ Danh sách hậu kỳ", "vprofile|post_detail_done"), ("🏠 Menu chính", "menu|main")])
    if key in video_scene3_flow.AUDIO_POST_ADDONS:
        rows.append([("⬅️ Quay lại", "vprofile|post_detail_done"), ("🏠 Menu chính", "menu|main")])
    return video_scene3_keyboard(rows)


def video_scene3_post_volume_text(state: dict) -> str:
    key = str(state.get("active_post_addon") or "")
    label = dict(video_scene3_flow.PUBLIC_CONFIGURABLE_POST_ADDONS).get(key, "Âm thanh")
    entry = dict((state.get("postproduction_addons") or {}).get(key) or {})
    value = dict(entry.get("value") or {}) if isinstance(entry.get("value"), dict) else {}
    default_volume = safe_int(video_scene3_flow.post_addon_default(key).get("volume_percent"), 100)
    volume = safe_int(value.get("volume_percent"), default_volume)
    return (
        f"🔊 <b>Âm lượng: {html.escape(label)}</b>\n\n"
        f"• Đang chọn: <b>{volume}%</b>\n\n"
        "Chọn mức nghe phù hợp. Khi có lời nói, nhạc nền nên để thấp hơn để nội dung vẫn rõ. "
        "Đây chỉ là cấu hình hậu kỳ, chưa tạo hoặc chỉnh sửa tệp âm thanh."
    )


def video_scene3_post_volume_keyboard() -> InlineKeyboardMarkup:
    values = list(video_scene3_flow.AUDIO_VOLUME_LEVELS)
    rows = []
    for index in range(0, len(values) - 1, 2):
        rows.append([(f"{value}%", f"vprofile|post_volume_set|{value}") for value in values[index:index + 2]])
    rows.append([(f"{values[-1]}%", f"vprofile|post_volume_set|{values[-1]}"), ("✍️ Tự nhập", "vprofile|post_volume_custom")])
    rows.append([("⬅️ Quay lại", "vprofile|post_volume_done"), ("🏠 Menu chính", "menu|main")])
    return video_scene3_keyboard(rows)


