def video_profile_scene1_b14_profile_id(profile_id: str) -> str:
    value = str(profile_id or "").lower()
    if "fashion" in value:
        return "fashion_lookbook"
    if "real_estate" in value or "architecture" in value or "interior" in value:
        return "real_estate_fpv"
    if "product" in value:
        return "product_review"
    if "tutorial" in value or "saas" in value:
        return "educational"
    if "vfx" in value:
        return "cinematic_trailer"
    return "storytelling"


def video_profile_scene1_storyboard_payload(state: dict) -> dict:
    plan = dict(state.get("plan") or {})
    content_type_id = str(state.get("content_type") or "")
    profile_id = (
        content_type_id
        if video_scene3_flow.content_type(content_type_id)
        else video_profile_scene1_b14_profile_id(str(plan.get("profile_id") or ""))
    )
    profile = video_profiles.get_video_profile(profile_id)
    continuity = dict(plan.get("continuity_contract") or {})
    reference_pack = dict(state.get("reference_assets") or {})
    reference_assets = [
        dict(item)
        for item in (reference_pack.get("items") or [])
        if isinstance(item, dict)
    ]
    storyboard_manifest = dict(
        state.get("storyboard_manifest")
        or reference_pack.get("storyboard_manifest")
        or {}
    )
    manifest_scenes = {
        int(item.get("scene_index") or 0): dict(item)
        for item in storyboard_manifest.get("scenes") or []
        if isinstance(item, dict) and int(item.get("scene_index") or 0) > 0
    }
    assets_by_scene: dict[int, list[dict]] = {}
    for item in reference_assets:
        scene_index = int(item.get("scene_index") or 0)
        if scene_index > 0:
            assets_by_scene.setdefault(scene_index, []).append(item)
    required_capability = str(
        state.get("required_capability")
        or storyboard_manifest.get("required_capability")
        or "image_to_video"
    )
    cards = []
    for scene in plan.get("scenes") or []:
        scene_index = int(scene.get("scene_index") or 0)
        scene_assets = list(assets_by_scene.get(scene_index) or [])
        manifest_scene = dict(manifest_scenes.get(scene_index) or {})
        start_asset = next(
            (item for item in scene_assets if str(item.get("slot") or "start") == "start"),
            {},
        )
        end_asset = next(
            (item for item in scene_assets if str(item.get("slot") or "") == "end"),
            {},
        )
        scene_asset_ids = [
            str(item.get("file_id") or item.get("result_url") or "")
            for item in scene_assets
            if str(item.get("file_id") or item.get("result_url") or "")
        ]
        image_prompt = video_scene3_flow.active_prompt(
            (state.get("image_prompt_versions") or {}).get(str(scene_index))
        )
        video_prompt = video_scene3_flow.active_prompt(
            (state.get("video_prompt_versions") or {}).get(str(scene_index))
        )
        cards.append({
            "scene_index": scene_index,
            "role": str(scene.get("scene_role") or "scene"),
            "duration_seconds": float(scene.get("duration_seconds") or 8),
            "narration_line": str(scene.get("dialogue_or_voiceover") or ""),
            "subtitle_line": str(scene.get("dialogue_or_voiceover") or ""),
            "visual_goal": str(scene.get("main_idea") or ""),
            "subject_action": str(scene.get("primary_action") or ""),
            "camera_motion": str(scene.get("camera") or ""),
            "composition": str(scene.get("visual_style") or ""),
            "background": str(scene.get("environment") or ""),
            "reference_asset_ids": scene_asset_ids,
            "scene_assets": scene_assets,
            "start_image_id": str(start_asset.get("image_id") or manifest_scene.get("start_image_id") or ""),
            "start_image_file_id": str(start_asset.get("file_id") or manifest_scene.get("start_image_file_id") or ""),
            "start_image_url": str(start_asset.get("result_url") or manifest_scene.get("start_image_url") or ""),
            "end_image_id": str(end_asset.get("image_id") or manifest_scene.get("end_image_id") or ""),
            "end_image_file_id": str(end_asset.get("file_id") or manifest_scene.get("end_image_file_id") or ""),
            "end_image_url": str(end_asset.get("result_url") or manifest_scene.get("end_image_url") or ""),
            "end_image_mode": str(scene.get("end_image_mode") or manifest_scene.get("end_image_mode") or "optional"),
            "input_mode": "first_last_frame_video" if end_asset or manifest_scene.get("end_image_id") else "image_to_video",
            "transition_from_previous": str(scene.get("transition_in") or ""),
            "transition_to_next": str(scene.get("transition_out") or ""),
            "music_cue": str(scene.get("audio_intent") or ""),
            "logo_cue": str(((plan.get("addon_plan") or {}).get("composition_constraints") or {}).get("logo_safe_area") or "none"),
            "exact_subject": str(scene.get("subject") or ""),
            "exact_product_or_object": str(scene.get("subject") or ""),
            "exact_location": str(scene.get("environment") or ""),
            "camera_angle": str(scene.get("camera") or ""),
            "lighting": str(scene.get("lighting") or ""),
            "color_tone": "; ".join(continuity.get("color_palette") or []),
            "entry_state": str(scene.get("start_state") or ""),
            "exit_state": str(scene.get("completion_state") or ""),
            "continuity_lock": "; ".join(scene.get("preserve_constraints") or []),
            "image_prompt": str(image_prompt.get("prompt") or ""),
            "image_negative_prompt": str(image_prompt.get("negative_prompt") or ""),
            "image_strategy": str(
                ((state.get("image_strategy_per_scene") or {}).get(str(scene_index)) or {}).get("strategy")
                or "direct_description"
            ),
            "provider_prompt": str(video_prompt.get("provider_prompt") or video_prompt.get("prompt") or scene.get("provider_prompt") or ""),
            "negative_prompt": str(video_prompt.get("provider_negative_prompt") or video_prompt.get("negative_prompt") or scene.get("negative_prompt") or ""),
        })
    return {
        "profile": profile.to_public_dict(),
        "story_bible": {
            "profile_id": profile_id,
            "primary_profile": str(state.get("primary_profile") or ""),
            "linked_profiles": [str(item) for item in state.get("linked_profiles") or []][:2],
            "content_type": content_type_id,
            "technical_profile": str(state.get("technical_profile") or ""),
            "title": str(state.get("subject") or "TOAN AAS Video"),
            "core_message": str(state.get("profile_context") or state.get("subject") or ""),
            "main_subject": str(state.get("subject") or ""),
            "visual_style": str((cards[0] if cards else {}).get("composition") or ""),
            "color_palette": "; ".join(continuity.get("color_palette") or []),
            "brand_tone": str(continuity.get("audio_style") or ""),
            "creative_controls": dict(state.get("creative_controls") or {}),
            "negative_prompt": str((cards[0] if cards else {}).get("negative_prompt") or ""),
        },
        "scene_cards": cards,
        "asset_pack": {
            "items": reference_assets,
            "storyboard_manifest": storyboard_manifest,
            "ordered_scene_assets": {
                str(index): list(items)
                for index, items in sorted(assets_by_scene.items())
            },
            "planning_notes": list(reference_pack.get("planning_notes") or []),
        },
        "preview_text": "Kế hoạch video theo cảnh đã được duyệt",
        "prompt_context": {
            "profile_id": profile_id,
            "primary_profile": str(state.get("primary_profile") or ""),
            "linked_profiles": [str(item) for item in state.get("linked_profiles") or []][:2],
            "technical_profile": str(state.get("technical_profile") or ""),
            "job_type": "storyboard_to_video",
            "execution_owner": "owner_product_video",
            "required_capability": required_capability,
            "storyboard_manifest": storyboard_manifest,
            "selected_transition_style": str(((plan.get("addon_plan") or {}).get("content_affecting") or {}).get("transition_style") or "tự nhiên"),
            "selected_voice_music_subtitle_cues": dict((plan.get("addon_plan") or {}).get("post_production") or {}),
        },
        "continuity_ledger": continuity,
        "provider_called": False,
        "xu_charged": 0,
    }


def video_flow6_product_id(state: dict | None = None) -> str:
    current = dict(state or {})
    return str(current.get("source_product_id") or current.get("product_type") or "")


def video_flow6_required_capability(flow_kind: str, state: dict | None = None) -> str:
    if str(flow_kind or "") == "storyboard":
        current = dict(state or {})
        manifest = dict(current.get("storyboard_manifest") or {})
        return str(
            current.get("required_capability")
            or manifest.get("required_capability")
            or "image_to_video"
        )
    return {
        "self_shot": "video_to_video",
    }.get(str(flow_kind or ""), "text_to_video_or_scene_video")


def video_flow6_worker_is_ready(worker: dict | None = None) -> bool:
    current = dict(worker or {})
    return bool(
        current.get("worker_version_compatible")
        and current.get("worker_connected")
        and current.get("heartbeat_fresh")
        and current.get("lease_valid")
        and current.get("sha_match")
        and current.get("capability_match")
        and not current.get("worker_identity_conflict")
    )


def video_flow6_frame_state_from_scene3(state: dict | None = None) -> dict:
    current = video_scene3_flow.normalize_state(state)
    context_state = video_flow6.context_from_scene_state(current)
    manifest = dict(context_state.get("asset_manifest") or {})
    photos = []
    for ordinal, raw in enumerate(manifest.get("items") or [], 1):
        item = dict(raw or {})
        if str(item.get("media_kind") or "image").lower() not in {"image", "photo", "storyboard"}:
            continue
        file_id = str(item.get("file_id") or "")
        if not file_id:
            continue
        photos.append({
            "image_id": str(item.get("image_id") or f"flow6_scene_{safe_int(item.get('scene_index'), ordinal)}"),
            "file_id": file_id,
            "file_unique_id": str(item.get("file_unique_id") or ""),
            "file_size": safe_int(item.get("file_size"), 0),
            "mime_type": str(item.get("mime_type") or "image/jpeg"),
            "scene_index": safe_int(item.get("scene_index"), ordinal),
        })
    photos.sort(key=lambda item: (safe_int(item.get("scene_index"), 0), str(item.get("image_id") or "")))
    ratio = str(current.get("aspect_ratio") or "9:16").replace(":", "x")
    quality_xu = safe_int(current.get("quality_xu"), 0)
    explicit_quality = str(current.get("frame_video_quality") or "")
    quality = (
        explicit_quality
        if explicit_quality in {"fast", "balanced", "beautiful"}
        else "fast" if quality_xu and quality_xu <= 300
        else "beautiful" if quality_xu >= 1000
        else "balanced"
    )
    addons = dict(current.get("postproduction_addons") or {})
    logo_entry = dict(addons.get("logo_image") or {})
    logo_value = dict(logo_entry.get("value") or {}) if isinstance(logo_entry.get("value"), dict) else {}
    watermark_entry = dict(addons.get("watermark_text") or {})
    watermark_value = dict(watermark_entry.get("value") or {}) if isinstance(watermark_entry.get("value"), dict) else {}
    subtitle_entry = dict(addons.get("subtitles") or {})
    subtitle_value = dict(subtitle_entry.get("value") or {}) if isinstance(subtitle_entry.get("value"), dict) else {}
    music_entry = dict(addons.get("music") or {})
    music_value = dict(music_entry.get("value") or {}) if isinstance(music_entry.get("value"), dict) else {}
    dubbing_entry = dict(addons.get("dubbing") or {})
    dubbing_value = dict(dubbing_entry.get("value") or {}) if isinstance(dubbing_entry.get("value"), dict) else {}
    text_overlays = []
    for ordinal, raw in enumerate(current.get("automatic_text_items") or [], 1):
        item = dict(raw or {})
        content = str(item.get("content") or item.get("text") or "").strip()
        if not content:
            continue
        text_overlays.append({
            "text_id": str(item.get("id") or item.get("text_id") or f"flow6_text_{ordinal}"),
            "content": content,
            "start_seconds": float(item.get("start_seconds") or 0),
            "end_seconds": float(item.get("end_seconds") or max(1, len(photos) * 3)),
            "position": str(item.get("position") or "top_center"),
            "animation": str(item.get("animation") or "fade"),
            "style": str(item.get("style") or "readable"),
        })
    frame_state = normalize_frame_video_state({
        "source": "flow6_scene3",
        "mode": "existing_images",
        "img2vid_lock1": True,
        "step": "confirm",
        "photos": photos,
        "ratio": ratio,
        "seconds_per_image": 3.0,
        "transition": "fade",
        "effect": "fade",
        "quality": quality,
        "logo_enabled": bool(logo_entry.get("enabled") and logo_value.get("asset_file_id")),
        "logo_file_id": str(logo_value.get("asset_file_id") or ""),
        "logo_position": str(logo_value.get("position") or "top_right"),
        "watermark_enabled": bool(watermark_entry.get("enabled") and str(watermark_value.get("text") or "").strip()),
        "watermark_text": str(watermark_value.get("text") or ""),
        "watermark_position": str(watermark_value.get("position") or "top_right"),
        "subtitle_enabled": bool(subtitle_entry.get("enabled")),
        "subtitle_text": str(subtitle_value.get("text") or subtitle_value.get("content") or ""),
        "subtitle_position": str(subtitle_value.get("position") or "bottom_center"),
        "music_enabled": bool(music_entry.get("enabled") and music_value.get("asset_file_id")),
        "music_file_id": str(music_value.get("asset_file_id") or ""),
        "music_volume_percent": safe_int(music_value.get("volume_percent"), 35),
        "voice_enabled": bool(dubbing_entry.get("enabled") and dubbing_value.get("asset_file_id")),
        "voice_file_id": str(dubbing_value.get("asset_file_id") or ""),
        "voice_volume_percent": safe_int(dubbing_value.get("volume_percent"), 100),
        "text_overlays": text_overlays,
        "flow6_context": context_state,
    })
    addon_blockers = []
    if music_entry.get("enabled") and not frame_state.get("music_file_id"):
        addon_blockers.append("frame_music_asset_missing")
    if dubbing_entry.get("enabled") and not frame_state.get("voice_file_id"):
        addon_blockers.append("frame_dubbing_asset_missing")
    if logo_entry.get("enabled") and not frame_state.get("logo_file_id"):
        addon_blockers.append("frame_logo_asset_missing")
    if dict(addons.get("sfx") or {}).get("enabled"):
        addon_blockers.append("frame_sfx_runtime_unavailable")
    frame_state["flow6_addon_blockers"] = addon_blockers
    return frame_state


def video_flow6_preflight_for_state(user_id: int, state: dict, quality: int) -> dict:
    current = video_scene3_flow.normalize_state(state)
    context_state = video_flow6.context_from_scene_state(current)
    flow_kind = str(context_state.get("flow_kind") or "ai_real")
    if flow_kind == "frame_video":
        frame_state = video_flow6_frame_state_from_scene3({**current, "quality_xu": quality})
        runtime_guard = frame_video_runtime_guard(frame_state, user_id)
        addon_blockers = list(frame_state.get("flow6_addon_blockers") or [])
        result = video_flow6.preflight(
            context_state,
            package_available=True,
            engine_ready=bool(runtime_guard.get("ok")),
            worker_ready=bool(runtime_guard.get("ok")),
            capability_ready=not addon_blockers,
            duration_seconds=max(1, int(math.ceil(frame_video_estimated_output_seconds(frame_state)))),
        )
        blockers = list(result.get("blockers") or [])
        if not runtime_guard.get("ok"):
            blockers.append(str(runtime_guard.get("reason") or "frame_video_runtime_unavailable"))
        blockers.extend(addon_blockers)
        result.update({
            "ok": not blockers,
            "blockers": list(dict.fromkeys(blockers)),
            "blocker": next(iter(dict.fromkeys(blockers)), ""),
            "frame_state": frame_state,
            "runtime_guard": dict(runtime_guard),
            "route_selection": {"ok": True, "selected_provider": "local_ffmpeg", "selected_model": "ffmpeg"},
            "worker": {"worker_connected": bool(runtime_guard.get("worker_connected"))},
            "required_capability": "local_ffmpeg",
        })
        return result
    required_capability = video_flow6_required_capability(flow_kind, context_state)
    route_selection = video_provider_catalog.resolve_product_video_model(
        tier=quality,
        scene_count=max(1, safe_int(current.get("scene_count"), 1)),
        required_capability=required_capability,
        requires_concat=True,
    )
    worker = product_video_worker_admission_status()
    worker_ready = video_flow6_worker_is_ready(worker)
    public_preflight = product_video_public_preflight_evaluation(
        max(1, safe_int(current.get("scene_count"), 1)),
        explicit_public_final_confirm=True,
    )
    result = video_flow6.preflight(
        context_state,
        package_available=bool(route_selection.get("ok")),
        engine_ready=bool(public_preflight.get("ready")),
        worker_ready=worker_ready,
        capability_ready=bool(route_selection.get("ok")),
    )
    result.update({
        "route_selection": dict(route_selection),
        "worker": dict(worker),
        "public_preflight": dict(public_preflight),
        "required_capability": required_capability,
    })
    return result


