def video_local_job_progress_payload(job: dict) -> dict:
    raw = str((job or {}).get("error_short") or "").strip()
    try:
        parsed = json.loads(raw) if raw.startswith("{") else {}
    except (TypeError, ValueError, json.JSONDecodeError):
        parsed = {}
    return parsed if isinstance(parsed, dict) and parsed.get("local1") else {}


def video_editengine1_job_for_worker(worker_job_id, *, conn=None) -> dict:
    owns_connection = conn is None
    conn = conn or db_connect_readonly()
    try:
        return video_editengine1.get_job_by_worker_id_readonly(conn, worker_job_id)
    finally:
        if owns_connection:
            conn.close()


def video_edit_delivery_receipt_is_complete(
    canonical: dict | None,
    progress: dict | None = None,
) -> bool:
    """Require one internally consistent, fully decoded Telegram receipt."""

    current = dict(canonical or {})
    worker_progress = dict(progress or {}) if isinstance(progress, dict) else {}

    def _strict_nonnegative_integer(value) -> int | None:
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            return value if value >= 0 else None
        if isinstance(value, str):
            token = value.strip()
            if not token or not token.isdigit():
                return None
            parsed = int(token)
            return parsed if parsed >= 0 else None
        return None

    output_sha256 = current.get("output_sha256")
    output_size_bytes = _strict_nonnegative_integer(current.get("output_size_bytes"))
    delivery_message_id, delivery_file_id = video_editengine1.telegram_delivery_identity({
        "sent": True,
        "message_id": current.get("delivery_message_id"),
        "file_id": current.get("delivery_file_id"),
    })
    output_file_id = current.get("output_file_id")
    if not (
        str(current.get("status") or "").strip().lower() in {"delivered", "charged"}
        and current.get("receipt_state") == "created"
        and delivery_message_id
        and delivery_file_id
        and isinstance(output_file_id, str)
        and output_file_id == output_file_id.strip() == delivery_file_id
        and isinstance(output_sha256, str)
        and output_sha256 == output_sha256.strip()
        and re.fullmatch(r"[0-9A-Fa-f]{64}", output_sha256)
        and output_size_bytes is not None
        and output_size_bytes > 0
        and video_editengine1.valid_mp4_delivery_probe(current.get("ffprobe"))
    ):
        return False

    raw_artifacts = current.get("artifact_receipts", [])
    if not isinstance(raw_artifacts, list) or not video_editengine1._artifact_receipts_valid(raw_artifacts):
        return False
    artifacts = video_editengine1._artifact_receipts(raw_artifacts)
    scalar_cursor = _strict_nonnegative_integer(current.get("delivery_cursor", 0))
    if scalar_cursor is None:
        return False
    tail = current.get("tail", {})
    if not isinstance(tail, dict):
        return False
    has_strict_cursor = "delivery_cursor" in tail
    strict_cursor = None
    if has_strict_cursor:
        try:
            strict_cursor = video_editengine1.video_edit_long_media.DeliveryCursor.from_mapping(
                tail.get("delivery_cursor")
            )
            video_editengine1._validate_delivery_cursor_receipt_prefix(
                strict_cursor,
                artifacts,
            )
        except (TypeError, ValueError):
            return False

    if artifacts:
        if (
            scalar_cursor != len(artifacts)
            or output_size_bytes != sum(int(item.get("size") or 0) for item in artifacts)
            or not video_editengine1._valid_mp4_path_list(
                current.get("output_path"),
                output_count=len(artifacts),
            )
            or any(
                not video_editengine1.valid_mp4_delivery_probe(item.get("ffprobe"))
                for item in artifacts
            )
            or (strict_cursor is not None and strict_cursor.state != "delivered")
        ):
            return False
        bound_artifact = artifacts[-1] if strict_cursor is not None else artifacts[0]
        if (
            delivery_message_id != str(bound_artifact.get("message_id") or "")
            or delivery_file_id != str(bound_artifact.get("file_id") or "")
        ):
            return False
        expected_output_count = len(artifacts)
    else:
        if (
            scalar_cursor != 0
            or has_strict_cursor
            or not video_editengine1._valid_mp4_path_list(
                current.get("output_path"),
                output_count=1,
            )
        ):
            return False
        expected_output_count = 1

    worker_status = str(worker_progress.get("worker_status") or "").strip().lower()
    worker_stage = str(worker_progress.get("stage") or "").strip().lower()
    if worker_status not in {"completed", "succeeded"}:
        return False
    if worker_stage != "delivered":
        return False
    for field in ("processed", "total", "delivered"):
        parsed = _strict_nonnegative_integer(worker_progress.get(field))
        if parsed is None or parsed != expected_output_count:
            return False
    return True


def video_editor_job_status_text(job: dict, lang: str = "vi") -> str:
    copy = public_video_deep_copy(normalize_user_language(lang))
    status = str((job or {}).get("status") or "unknown").lower()
    progress = video_local_job_progress_payload(job)

    def strict_nonnegative_integer(value) -> int | None:
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            return value if value >= 0 else None
        if isinstance(value, str):
            token = value.strip()
            if token and token.isdigit():
                return int(token)
        return None

    canonical = dict((job or {}).get("_video_edit_canonical") or {})
    if not canonical:
        canonical = video_editengine1_job_for_worker((job or {}).get("id"))
    canonical_status = str(canonical.get("status") or "").lower()
    stage = str(progress.get("stage") or ("received" if status == "queued" else ""))
    failed_stage = str(progress.get("failed_stage") or "").strip().lower()
    processed = max(0, safe_int(progress.get("processed"), 0))
    total = max(1, safe_int(progress.get("total"), 1))
    delivered = max(0, safe_int(progress.get("delivered"), 0))
    stage_labels = {
        "received": copy["receive"],
        "inspecting_input": copy["check"],
        "preparing_plan": copy["prepare"],
        "processing_video": copy["edit"],
        "validating_output": copy["validate"],
        "delivering": copy["deliver"],
        "delivered": copy["completed"],
        "delivery_unknown": copy["delivery_unknown"],
        "failed_no_charge": copy["failed"],
    }
    receipt_progress = {**progress, "worker_status": status}
    delivered_truth = video_edit_delivery_receipt_is_complete(
        canonical,
        receipt_progress,
    )
    artifact_receipts = video_editengine1._artifact_receipts(
        canonical.get("artifact_receipts") or []
    )
    receipt_count = len(artifact_receipts)
    worker_terminal_success = status in {"completed", "succeeded"}
    delivery_uncertain = bool(
        canonical_status == "delivery_unknown"
        or stage == "delivery_unknown"
        or (stage == "delivered" and not delivered_truth)
        or (
            canonical_status in {"delivered", "charged"}
            and not delivered_truth
        )
        or (worker_terminal_success and not delivered_truth)
    )
    if delivered_truth:
        public_status = copy["completed"]
    elif delivery_uncertain:
        public_status = copy["delivery_unknown"]
    elif canonical_status == "failed_no_charge" or status in {"failed", "cancelled"} or stage == "failed_no_charge":
        public_status = copy["failed"]
    else:
        public_status = stage_labels.get(stage, copy["waiting"])
    confirmed_price_xu = strict_nonnegative_integer(canonical.get("price_xu"))
    if delivered_truth:
        heading = f"✅ <b>{copy['completed']}</b>"
    elif not delivery_uncertain and (
        canonical_status == "failed_no_charge"
        or status in {"failed", "cancelled"}
        or stage == "failed_no_charge"
    ):
        heading = f"❌ <b>{copy['failed']}</b>"
    else:
        heading = f"🎞 <b>{copy['status_heading']}</b>"
    lines = [
        heading,
        "",
        f"• {copy['task_id']}: <code>#{html.escape(str((job or {}).get('id') or '-'))}</code>",
    ]
    if not delivered_truth:
        lines.append(f"• {copy['status_label']}: <b>{html.escape(public_status)}</b>")
    if confirmed_price_xu is not None:
        lines.append(f"• {copy['price']}: <b>{confirmed_price_xu} Xu</b>")
    failed = bool(
        canonical_status == "failed_no_charge"
        or delivery_uncertain
        or status in {"failed", "cancelled"}
        or stage == "failed_no_charge"
    )
    board_stage = failed_stage if failed and failed_stage else stage
    completed_count = {
        "received": 1,
        "inspecting_input": 1,
        "preparing_plan": 2,
        "processing_video": 3,
        "validating_output": 4,
        "delivering": 5,
        "delivered": 6,
    }.get(board_stage, 1 if status in {"queued", "running"} else 0)
    if delivered_truth:
        completed_count = 6
    elif delivery_uncertain:
        completed_count = 5
    canonical_stages = (
        copy["receive"],
        copy["check"],
        copy["prepare"],
        copy["edit"],
        copy["validate"],
        copy["deliver"],
    )
    lines.extend(["", f"<b>{copy['progress']}</b>"])
    for index, label in enumerate(canonical_stages):
        if index < completed_count:
            icon = "✅"
        elif failed and index == completed_count:
            icon = "⚠️"
        elif not failed and index == completed_count:
            icon = "⏳"
        else:
            icon = "⬜"
        lines.append(f"{icon} {label}")
    if delivered_truth:
        lines.append(f"• {copy['result']}: <b>{copy['completed']}</b>")
    raw_operation_summary = progress.get("operation_summary")
    if delivered_truth and isinstance(raw_operation_summary, list):
        operation_summary = [
            item.strip()
            for item in raw_operation_summary
            if isinstance(item, str) and item.strip()
        ]
        if operation_summary and len(operation_summary) == len(raw_operation_summary):
            operation = str(progress.get("operation") or "").strip().lower()
            public_operation = (
                copy["operation_split"]
                if operation == "split"
                else copy["operation_manual"]
            )
            lines.append(f"• {copy['operations']}: <b>{html.escape(public_operation)}</b>")
    failure_stage_labels = {
        "received": canonical_stages[0],
        "inspecting_input": canonical_stages[1],
        "preparing_plan": canonical_stages[2],
        "processing_video": canonical_stages[3],
        "validating_output": canonical_stages[4],
        "delivering": canonical_stages[5],
    }
    if total > 1 and stage in {"processing_video", "validating_output", "delivering", "delivered", "delivery_unknown"}:
        if stage == "delivering":
            lines.append(f"• {copy['delivered_count']}: <b>{min(delivered, total)}/{total}</b> {copy['parts']}")
        elif stage == "delivered":
            if delivered_truth:
                lines.append(f"• {copy['delivered_count']}: <b>{total}/{total}</b> {copy['parts']}")
            else:
                lines.append(f"• {copy['receipts_count']}: <b>{min(receipt_count, total)}/{total}</b> {copy['parts']}")
        elif stage == "delivery_unknown":
            lines.append(f"• {copy['receipts_count']}: <b>{min(receipt_count, total)}/{total}</b> {copy['parts']}")
        else:
            action = copy["validated_count"] if stage == "validating_output" else copy["processed_count"]
            lines.append(f"• {action}: <b>{min(processed, total)}/{total}</b> {copy['parts']}")
    if delivered_truth:
        canonical_probe = dict(canonical.get("ffprobe") or {})
        if artifact_receipts:
            artifact_durations = [
                strict_nonnegative_integer(
                    dict(item.get("ffprobe") or {}).get("duration_ms")
                )
                for item in artifact_receipts
            ]
            duration_ms = (
                sum(artifact_durations)
                if all(value is not None and value > 0 for value in artifact_durations)
                else 0
            )
        else:
            duration_ms = strict_nonnegative_integer(
                canonical_probe.get("duration_ms")
            ) or 0
        if duration_ms > 0:
            duration_seconds = duration_ms / 1000.0
            duration_text = (
                str(int(duration_seconds))
                if duration_seconds.is_integer()
                else f"{duration_seconds:.1f}".rstrip("0").rstrip(".")
            )
            lines.append(f"• {copy['video_duration']}: <b>{duration_text} {copy['seconds']}</b>")
        output_count = len(artifact_receipts) if artifact_receipts else 1
        output_size_bytes = strict_nonnegative_integer(
            canonical.get("output_size_bytes")
        )
        common_resolution: tuple[int, int] | None = None
        if artifact_receipts:
            resolutions: list[tuple[int, int]] = []
            for item in artifact_receipts:
                probe = dict(item.get("ffprobe") or {})
                width = strict_nonnegative_integer(probe.get("width"))
                height = strict_nonnegative_integer(probe.get("height"))
                if width is None or height is None or width <= 0 or height <= 0:
                    resolutions = []
                    break
                resolutions.append((width, height))
            if resolutions and len(set(resolutions)) == 1:
                common_resolution = resolutions[0]
        else:
            output_width = strict_nonnegative_integer(canonical_probe.get("width"))
            output_height = strict_nonnegative_integer(canonical_probe.get("height"))
            if (
                output_width is not None
                and output_width > 0
                and output_height is not None
                and output_height > 0
            ):
                common_resolution = (output_width, output_height)
        if output_size_bytes is not None and output_size_bytes > 0:
            output_size_mb = output_size_bytes / (1024 * 1024)
            output_size_text = f"{output_size_mb:.1f} MB"
            output_parts = [f"{output_count} MP4" if output_count > 1 else "MP4"]
            if common_resolution is not None:
                output_parts.append(f"{common_resolution[0]}×{common_resolution[1]}")
            output_parts.append(output_size_text)
            output_summary = " · ".join(output_parts)
            lines.append(f"• {copy['output']}: <b>{output_summary}</b>")
        raw_started_at = str((job or {}).get("started_at") or "")
        raw_finished_at = str((job or {}).get("finished_at") or "")
        if raw_started_at and raw_finished_at:
            try:
                started_at = parse_datetime_text(raw_started_at)
                finished_at = parse_datetime_text(raw_finished_at)
            except (TypeError, ValueError, OverflowError):
                started_at = None
                finished_at = None
            if (
                started_at is not None
                and finished_at is not None
                and finished_at >= started_at
            ):
                elapsed_seconds = int(
                    round((finished_at - started_at).total_seconds())
                )
                lines.append(f"• {copy['processing_time']}: <b>{elapsed_seconds} {copy['seconds']}</b>")
        charge_state = str(canonical.get("charge_state") or "")
        charged_xu = strict_nonnegative_integer(canonical.get("charged_xu"))
        if confirmed_price_xu == 0 and charge_state == "not_charged":
            lines.append(f"• {copy['charged']}: <b>0 Xu</b>")
        elif (
            confirmed_price_xu is not None
            and charge_state == "charged"
            and charged_xu == confirmed_price_xu
        ):
            lines.append(f"• {copy['charged']}: <b>{charged_xu} Xu</b>")
        elif confirmed_price_xu is not None and charge_state == "charge_failed":
            lines.append(f"• {copy['delivery_charge_failed']}")
        elif confirmed_price_xu is not None and charge_state in {
            "not_charged",
            "charging",
        }:
            lines.append(f"• {copy['fee_recording']}")
        lines.append(f"• {copy['delivery_status']}: <b>{copy['video_delivered']}</b>")
        authoritative_balance = strict_nonnegative_integer(
            canonical.get("account_balance_xu")
        )
        if authoritative_balance is not None:
            lines.append(f"• {copy['account_balance']}: <b>{authoritative_balance} Xu</b>")
    elif delivery_uncertain:
        lines.append(f"• {copy['delivery_uncertain']} {copy['no_resend']}.")
        charge_state = str(canonical.get("charge_state") or "not_charged")
        charged_xu = strict_nonnegative_integer(canonical.get("charged_xu"))
        if charge_state == "charged" and charged_xu is not None and charged_xu > 0:
            lines.append(f"• {copy['recorded_charge']}: <b>{charged_xu} Xu</b>. {copy['charge_reconcile']}")
        elif charge_state == "charged":
            lines.append(f"• {copy['marked_charge']}")
        elif confirmed_price_xu == 0:
            lines.append(f"• {copy['free_task']}")
        elif charge_state == "charge_failed":
            lines.append(f"• {copy['charge_failed']}")
        else:
            lines.append(f"• {copy['no_new_charge']}")
    elif failed:
        failed_stage_label = failure_stage_labels.get(failed_stage)
        if failed_stage_label:
            lines.append(f"• {copy['failed_step']}: <b>{html.escape(failed_stage_label)}</b>")
        public_reason = (
            copy["invalid_output"]
            if str(progress.get("reason") or "").endswith("output_validation_failed")
            else copy["processing_failed"]
        )
        lines.append(f"• {copy['reason']}: <b>{public_reason}</b>")
        lines.append(f"• {copy['charged']}: <b>0 Xu</b>")
    else:
        lines.append(f"• {copy['pending_delivery']}")
    return "\n".join(lines)


async def show_video_editor_job_status_panel(
    update,
    context,
    job_id,
    lang: str = "vi",
    *,
    user_id=0,
):
    """Render and register one exact owner-bound Video Edit progress panel."""

    query = getattr(update, "callback_query", None)
    source_message = getattr(update, "message", None) or getattr(query, "message", None)
    normalized_job_id = safe_int(job_id, 0)
    normalized_user_id = safe_int(
        user_id or getattr(getattr(update, "effective_user", None), "id", 0),
        0,
    )
    current = dict(
        video_edit_progress_read_status(
            normalized_job_id,
            user_id=normalized_user_id,
        )
        or {}
    )
    if not current:
        if query:
            await query.answer(
                "Không tìm thấy bảng tiến độ Video Edit thuộc tài khoản này.",
                show_alert=True,
            )
        return None

    registry = globals().setdefault("PROGRESS_AUTO_REFRESH_JOBS", {})
    key = f"video_edit:{normalized_job_id}"
    existing = dict(registry.get(key) or {}) if isinstance(registry, dict) else {}
    if existing:
        if query:
            await query.answer(
                "Bảng tiến độ của tác vụ này đang hoạt động. Hãy dùng đúng bảng đã mở.",
                show_alert=True,
            )
        return None
    tasks = globals().setdefault("PROGRESS_AUTO_REFRESH_TASKS", {})
    orphan_task = tasks.get(key) if isinstance(tasks, dict) else None
    if orphan_task is not None:
        task_done = getattr(orphan_task, "done", None)
        if not callable(task_done) or not task_done():
            if query:
                await query.answer(
                    "Bảng tiến độ của tác vụ này đang được khôi phục. Hãy thử lại sau.",
                    show_alert=True,
                )
            return None
        tasks.pop(key, None)

    snapshot = video_edit_progress_snapshot(
        str(normalized_job_id),
        user_id=normalized_user_id,
        job=current,
        lang=lang,
    )
    if not snapshot:
        if query:
            await query.answer(
                "Chưa đọc được tiến độ Video Edit an toàn.",
                show_alert=True,
            )
        return None

    text = str(snapshot.get("text") or video_editor_job_status_text(current, lang))
    if not isinstance(registry, dict):
        raise RuntimeError("videoedit_progress_registry_unavailable")
    binding_attempt = object()
    binding_task = None
    registry[key] = {
        "key": key,
        "product_type": "video_edit",
        "job_id": str(normalized_job_id),
        "user_id": normalized_user_id,
        "binding_attempt": binding_attempt,
        "binding_state": "reserved",
        "task_started": False,
        "task_alive": False,
    }

    def rollback_binding() -> None:
        owned = dict(registry.get(key) or {})
        if owned.get("binding_attempt") is not binding_attempt:
            return
        if isinstance(tasks, dict) and binding_task is not None:
            task = tasks.get(key)
            if task is binding_task:
                tasks.pop(key, None)
                task_done = getattr(task, "done", None)
                task_cancel = getattr(task, "cancel", None)
                if callable(task_cancel) and (
                    not callable(task_done) or not task_done()
                ):
                    task_cancel()
        registry.pop(key, None)

    if query:
        if source_message is None:
            rollback_binding()
            return None
        try:
            rendered = await query.edit_message_text(text, parse_mode="HTML")
        except Exception as exc:
            if video_edit_panel_not_modified(exc):
                rendered = None
            elif any(
                fragment in str(exc or "").lower()
                for fragment in (
                    "there is no text in the message to edit",
                    "query is too old",
                    "message to edit not found",
                    "message can't be edited",
                    "message is not editable",
                )
            ):
                try:
                    rendered = await source_message.reply_text(
                        text,
                        parse_mode="HTML",
                    )
                except Exception:
                    rollback_binding()
                    raise
            else:
                rollback_binding()
                raise
        panel_message = rendered or source_message
    elif source_message:
        try:
            panel_message = await source_message.reply_text(
                text,
                parse_mode="HTML",
            )
        except Exception:
            rollback_binding()
            raise
    else:
        rollback_binding()
        return None

    if panel_message is None:
        rollback_binding()
        return None
    try:
        registration = dict(progress_auto_refresh_register_message(
            panel_message,
            context,
            product_type="video_edit",
            job_id=str(normalized_job_id),
            user_id=normalized_user_id,
            lang=lang,
            initial_snapshot=snapshot,
            start_task=False,
        ) or {})
    except Exception:
        rollback_binding()
        raise
    panel_chat_id = safe_int(
        getattr(panel_message, "chat_id", 0)
        or getattr(getattr(panel_message, "chat", None), "id", 0),
        0,
    )
    panel_message_id = safe_int(getattr(panel_message, "message_id", 0), 0)
    if not (
        str(registration.get("key") or "") == f"video_edit:{normalized_job_id}"
        and str(registration.get("product_type") or "").strip().lower() == "video_edit"
        and safe_int(registration.get("job_id"), 0) == normalized_job_id
        and safe_int(registration.get("user_id"), 0) == normalized_user_id
        and safe_int(registration.get("chat_id"), 0) == panel_chat_id
        and safe_int(registration.get("message_id"), 0) == panel_message_id
        and panel_chat_id != 0
        and panel_message_id > 0
    ):
        rollback_binding()
        raise RuntimeError("videoedit_progress_panel_registration_failed")
    registry[key] = {
        **dict(registry.get(key) or {}),
        **registration,
        "binding_attempt": binding_attempt,
        "binding_state": "registered",
    }
    terminal_snapshot = bool(str(snapshot.get("terminal_state") or "").strip())
    if not terminal_snapshot:
        try:
            scheduler_started = bool(progress_auto_refresh_start_task(context, key))
        except Exception:
            rollback_binding()
            raise
        if not scheduler_started:
            rollback_binding()
            raise RuntimeError("videoedit_progress_panel_scheduler_start_failed")
        binding_task = tasks.get(key) if isinstance(tasks, dict) else None
    try:
        if query and panel_message is source_message:
            await query.edit_message_text(
                text,
                parse_mode="HTML",
                reply_markup=video_editor_status_keyboard(normalized_job_id, lang),
            )
        else:
            await panel_message.edit_text(
                text,
                parse_mode="HTML",
                reply_markup=video_editor_status_keyboard(normalized_job_id, lang),
            )
    except Exception as exc:
        if not video_edit_panel_not_modified(exc):
            rollback_binding()
            raise
    active = dict(registry.get(key) or {})
    if active.get("binding_attempt") is not binding_attempt:
        rollback_binding()
        raise RuntimeError("videoedit_progress_panel_binding_lost")
    active["binding_state"] = "active"
    registry[key] = active
    return panel_message


