def video_flow_first_step(tool_id: str) -> str:
    route = video_public_route_for_tool(tool_id)
    return str(route.get("first_step") or ("profile_select" if str(tool_id or "") in VIDEO_PROFILE_FIRST_PRODUCTS else "tool_home"))


def video_flow_requires_intro_profile(product_id: str) -> bool:
    return str(product_id or "") in VIDEO_INTRO_THEN_PROFILE_PRODUCTS


def video_flow_requires_shared_profile(product_id: str) -> bool:
    return str(product_id or "") in VIDEO_PROFILE_FIRST_PRODUCTS or video_flow_requires_intro_profile(product_id)


def video_profile_origin_step(session: dict | None = None) -> str:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    origin = str(draft.get("profile_origin_step") or session.get("profile_origin_step") or "").strip()
    return origin


def video_session_flow_id(session: dict | None = None) -> str:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    return str(session.get("video_flow") or session.get("video_tool") or session.get("product_id") or draft.get("video_flow") or draft.get("product_id") or "")


def video_context_ready_for_assets(session: dict | None = None) -> bool:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    return bool(
        str(session.get("topic") or draft.get("topic") or "").strip()
        or draft.get("selected_trend_source")
        or draft.get("prepared_prompt_bundle")
        or draft.get("prompt_bundle")
        or draft.get("b14_storyboard_plan")
        or draft.get("input_collected")
        or draft.get("suggestion_used")
        or draft.get("sample_used")
        or draft.get("media_description")
    )


def video_asset_context_missing(session: dict | None = None) -> bool:
    product_id = video_session_flow_id(session)
    return product_id in {
        "video_trend",
        "video_idea",
        "script_image_video",
        "storyboard_prompt",
        "multi_scene_film",
    } and not video_context_ready_for_assets(session)


def video_back_matrix_target(session: dict | None = None) -> str:
    session = dict(session or {})
    current = str(session.get("current_step") or "")
    flow = video_session_flow_id(session)
    draft = dict(session.get("draft") or {})
    if not current:
        return VIDEO_BACK_MENU_TARGET
    if current == "profile_select":
        origin = video_profile_origin_step(session)
        if origin:
            return origin
        if not draft and not session.get("step_history"):
            return VIDEO_BACK_MENU_TARGET
        target = str((VIDEO_STEP_BACK_MATRIX.get(flow) or {}).get(current) or "")
        return target or VIDEO_BACK_MENU_TARGET
    if current == "b14_invoice":
        invoice_origin = str(draft.get("b14_invoice_return_step") or "").strip()
        if invoice_origin and invoice_origin != current:
            return invoice_origin
    if current == "tool_home":
        return VIDEO_BACK_MENU_TARGET
    if current == "intro" and draft.get("profile_next_screen"):
        return "profile_select"
    if current == "collect_input":
        input_origin = str(draft.get("input_origin_step") or session.get("input_origin_step") or "").strip()
        if input_origin:
            return input_origin
    if current.startswith("asset_") and current != "asset_intake":
        return "asset_intake"
    if flow == "video_trend" and current == "asset_intake" and draft.get("suggestion_used"):
        return "idea_suggestions"
    if flow == "video_trend" and current == "asset_intake" and (draft.get("selected_trend_source") or draft.get("trend_ideas")):
        return "trend_ideas"
    target = str((VIDEO_STEP_BACK_MATRIX.get(flow) or {}).get(current) or "")
    if target:
        return target
    if current == "asset_intake":
        history = [str(item) for item in (session.get("step_history") or []) if str(item or "")]
        for candidate in reversed(history):
            if candidate and candidate not in {"asset_intake", current}:
                return candidate
    history = [str(item) for item in (session.get("step_history") or []) if str(item or "")]
    for candidate in reversed(history):
        if candidate and candidate != current:
            return candidate
    return VIDEO_BACK_MENU_TARGET


def video_back_audit_rows_detailed() -> list[dict]:
    rows: list[dict] = []
    for tool_id, route in VIDEO_PUBLIC_ROUTE_MATRIX.items():
        if tool_id == "main_menu":
            continue
        initial_contract = _video_uiflow3_initial_route_contract(tool_id)
        if initial_contract:
            expected = str(route.get("back_target") or "")
            actual = str(initial_contract.get("back_target") or "")
            rows.append({
                "video_tool": tool_id,
                "flow": tool_id,
                "step": str(initial_contract.get("first_step") or ""),
                "expected": expected,
                "actual": actual,
                "ok": bool(
                    expected == actual == "menu|main_video"
                    and str(route.get("first_step") or "") == initial_contract.get("first_step")
                ),
            })
            continue
        first_step = video_flow_first_step(tool_id)
        flow_id = str(route.get("product_id") or tool_id)
        step_map = VIDEO_STEP_BACK_MATRIX.get(flow_id) or {}
        if not step_map and first_step:
            expected = str(route.get("back_target") or "")
            rows.append({
                "video_tool": tool_id,
                "flow": flow_id,
                "step": first_step,
                "expected": expected,
                "actual": expected,
                "ok": bool(expected),
            })
            continue
        for step, expected in step_map.items():
            if not step:
                continue
            sample = {
                "product_id": flow_id,
                "video_tool": tool_id,
                "video_flow": flow_id,
                "current_step": step,
                "step_history": ["profile_select", "intro", "collect_input", "idea_suggestions", "asset_intake"],
                "draft": {
                    "product_id": flow_id,
                    "video_tool": tool_id,
                    "video_flow": flow_id,
                    "topic": "demo",
                    "b14_profile_id": "storytelling",
                    "input_collected": True,
                },
            }
            actual = video_back_matrix_target(sample)
            rows.append({
                "video_tool": tool_id,
                "flow": flow_id,
                "step": step,
                "expected": expected,
                "actual": actual,
                "ok": actual == expected,
            })
    return rows


def video_public_route_for_callback(callback: str) -> dict:
    callback = str(callback or "")
    for tool_id, route in VIDEO_PUBLIC_ROUTE_MATRIX.items():
        if str(route.get("entry_callback") or "") == callback:
            item = dict(route)
            item["video_tool"] = tool_id
            return item
    return {}


def video_public_menu_label(tool_id: str, lang: str = "vi") -> str:
    route = video_public_route_for_tool(tool_id)
    lang = normalize_user_language(lang) or "vi"
    native_label = public_video_menu_label(tool_id, lang)
    if native_label:
        return native_label
    if lang == "zh":
        return str(route.get("label_zh") or route.get("label_vi") or tool_id)
    if lang != "vi":
        return str(route.get("label_en") or route.get("label_vi") or tool_id)
    return str(route.get("label_vi") or tool_id)


