def video_route_expected_handler(callback: str) -> str:
    callback_value = str(callback or "")
    if callback_value == "vproduct|b14_confirm":
        return "handle_product_video_public_confirm_callback"
    if re.fullmatch(r"vproduct\|b14_confirm\|[a-f0-9]{12}", callback_value):
        return "handle_product_video_public_confirm_callback"
    if callback_value.startswith("vproduct|b14_confirm"):
        return ""
    for prefix, owner in VIDEO_PUBLIC_CALLBACK_OWNER_PREFIXES[1:]:
        if callback_value.startswith(prefix):
            return owner
    return ""


def video_public_text_forbidden_words(text: str) -> list[str]:
    lower = str(text or "").lower()
    search_lower = re.sub(r"</?code>", " ", lower)
    found = []
    for term in VIDEO_PUBLIC_ROUTE_FORBIDDEN_WORDS:
        normalized = str(term or "").lower()
        if not normalized:
            continue
        if normalized in {"api", "admin", "test", "code"}:
            if re.search(rf"\b{re.escape(normalized)}\b", search_lower):
                found.append(term)
        elif normalized in search_lower:
            found.append(term)
    return found


def video_route_session_fields(tool_id: str, step: str = "tool_home") -> dict:
    route = video_public_route_for_tool(tool_id)
    flow_id = str(route.get("product_id") or tool_id or "")
    step = str(step or video_flow_first_step(tool_id) or "tool_home")
    return {
        "product_area": "video",
        "video_tool": str(tool_id or ""),
        "video_flow": flow_id,
        "source_button": str(route.get("entry_callback") or ""),
        "parent_menu": "video_main",
        "parent_menu_callback": str(route.get("parent_menu") or "menu|main_video"),
        "entry_callback": str(route.get("entry_callback") or ""),
        "back_target": str(route.get("back_target") or "menu|main_video"),
        "first_step": str(route.get("first_step") or video_flow_first_step(tool_id)),
        "flow_stack": ["video_main", str(tool_id or ""), step],
    }


def set_video_route_session(user_id, tool_id: str, step: str = "tool_home", **fields) -> dict:
    route_fields = video_route_session_fields(tool_id, step)
    route_fields.update(fields)
    session = go_video_screen(user_id, f"{tool_id}:{step}", str(tool_id or ""), **route_fields)
    session.update(route_fields)
    current_step = str(session.get("current_step") or "")
    if current_step != str(step or "tool_home"):
        session["previous_step"] = current_step
        session["current_step"] = str(step or "tool_home")
    product_id = str(route_fields.get("product_id") or video_public_route_for_tool(tool_id).get("product_id") or "")
    if product_id:
        session["product_id"] = product_id
    session["return_to"] = str(route_fields.get("parent_menu_callback") or "menu|main_video")
    draft = dict(session.get("draft") or {})
    draft.update(route_fields)
    session["draft"] = draft
    return save_video_session(user_id, session)


def start_shared_video_profile_step(user_id, product_id: str, *, origin_step: str = "intro", **fields) -> dict:
    product_id = str(product_id or "")
    route_fields = video_route_session_fields(product_id, "profile_select") if product_id in VIDEO_PUBLIC_ROUTE_MATRIX else {}
    route_fields.update(fields)
    route_fields["profile_origin_step"] = str(origin_step or "intro")
    route_fields["provider_called"] = False
    route_fields["xu_charged"] = 0
    session = task3d_session_step(
        user_id,
        "profile_select",
        product_id=product_id,
        return_to=str(route_fields.get("parent_menu_callback") or "menu|main_video"),
        **route_fields,
    )
    session = go_video_screen(user_id, f"{product_id}:profile_select", product_id, **route_fields)
    session.update(route_fields)
    session["product_id"] = product_id
    session["return_to"] = str(route_fields.get("parent_menu_callback") or "menu|main_video")
    draft = dict(session.get("draft") or {})
    draft.update(route_fields)
    session["draft"] = draft
    return save_video_session(user_id, session)


def video_scene2_clear_legacy_price_state(session: dict) -> dict:
    clean = dict(session or {})
    clean["package_id"] = ""
    clean["invoice_id"] = ""
    draft = dict(clean.get("draft") or {})
    for key in VIDEO_SCENE2_LEGACY_PRICE_KEYS:
        draft.pop(key, None)
    draft["provider_called"] = False
    draft["job_created"] = False
    draft["outbox_created"] = False
    draft["xu_charged"] = 0
    clean["draft"] = draft
    return clean


def start_public_video_scene2_state(
    context,
    user_id: int,
    product_id: str,
    *,
    origin_step: str = "intro",
    **fields,
) -> dict:
    product_id = str(product_id or "")
    start_at_scene_count = bool(fields.pop("start_at_scene_count", False))
    content_mode = str(fields.get("content_mode") or "").strip()
    if content_mode not in video_flow6.CONTENT_MODES:
        content_mode = ""
    topic = str(fields.get("topic") or fields.get("subject") or "").strip()[:1600]
    filtered_fields = {
        key: value
        for key, value in fields.items()
        if key not in VIDEO_SCENE2_LEGACY_PRICE_KEYS and key not in {"subject", "quality_xu"}
    }
    route_fields = video_route_session_fields(product_id, "scene_count") if product_id in VIDEO_PUBLIC_ROUTE_MATRIX else {}
    route_fields.update(filtered_fields)
    route_fields.update({
        "topic": topic,
        "scene2_origin_step": str(origin_step or "intro"),
        "scene2_canonical_entry": True,
        "content_mode": content_mode,
        "flow8_direct_entry": start_at_scene_count,
        "provider_called": False,
        "job_created": False,
        "outbox_created": False,
        "xu_charged": 0,
    })

    session = default_video_session(user_id)
    session.update({
        "product_id": product_id,
        "current_step": "scene2_scene_count" if (content_mode or start_at_scene_count) else "scene2_content_mode",
        "previous_step": "scene2_content_mode" if content_mode else ("menu_video" if start_at_scene_count else ""),
        "topic": topic,
        "return_to": str(route_fields.get("parent_menu_callback") or "menu|main_video"),
        "entry_flow": "scene2_public_planner",
        "current_flow": "scene2_public_planner",
        "package_id": "",
        "invoice_id": "",
    })
    session["draft"] = dict(route_fields)
    session = video_scene2_clear_legacy_price_state(session)
    save_video_session(user_id, session)

    assets = {
        "source_product_id": product_id,
        "origin_step": str(origin_step or "intro"),
        "source_media_ref": str(filtered_fields.get("source_media_ref") or ""),
        "source_media_refs": list(filtered_fields.get("source_media_refs") or []),
        "media_type": str(filtered_fields.get("media_type") or ""),
        "media_description": str(filtered_fields.get("media_description") or ""),
        "storyboard_image_scenes": list(filtered_fields.get("storyboard_image_scenes") or []),
        "final_video_scenes": list(filtered_fields.get("final_video_scenes") or []),
        "architecture_reference_assets": list(filtered_fields.get("architecture_reference_assets") or []),
        "items": [
            dict(item)
            for item in filtered_fields.get("source_asset_items") or []
            if isinstance(item, dict)
        ][:20],
    }
    state = video_scene3_flow.default_state(
        product_type=product_id,
        subject=topic,
        aspect_ratio="",
    )
    state.update({
        "step": "scene_count" if (content_mode or start_at_scene_count) else "content_mode",
        "history": ["content_mode"] if content_mode else (["menu_video"] if start_at_scene_count else ["menu"]),
        "content_mode": content_mode,
        "flow8_direct_entry": start_at_scene_count,
        "assets": assets,
        "reference_assets": assets,
        "source_product_id": product_id,
        "origin_step": str(origin_step or "intro"),
        "source_fields": dict(filtered_fields),
    })
    state = video_flow6.sync_scene_state(state)
    return save_video_profile_studio_state(context, state)


