def video_flow_audit_rows() -> list[dict]:
    placeholder_by_tool = {row["flow_id"]: row for row in video_placeholder_audit_rows()}
    rows = []
    for row in video_route_matrix_rows():
        tool_id = str(row.get("video_tool") or "")
        route = video_public_route_for_tool(tool_id)
        initial_contract = _video_uiflow3_initial_route_contract(tool_id)
        first_step = str(route.get("first_step") or row.get("first_step") or "")
        is_uiflow3_route = bool(initial_contract)
        placeholder = placeholder_by_tool.get(tool_id) or {}
        if tool_id == "video_trend":
            placeholder = placeholder_by_tool.get("video_trend") or placeholder
        rows.append({
            "button": row.get("label"),
            "handler": row.get("expected_handler"),
            "semantic_category": VIDEO_PRODUCT_SEMANTICS.get(tool_id, ""),
            "flow_type": str(route.get("flow_type") or row.get("category") or ""),
            "intro_step_exists": bool(
                first_step in VIDEO_UIFLOW3_RENDERED_STEPS
                if is_uiflow3_route
                else first_step == "intro" or tool_id == "video_trend"
            ),
            "first_step": first_step,
            "profile_required": False if is_uiflow3_route else bool(video_flow_requires_shared_profile(tool_id)),
            "profile_step_position": (
                "content_hub_after_source" if is_uiflow3_route
                else "step_1" if tool_id in VIDEO_PROFILE_FIRST_PRODUCTS
                else "after_product_intro_input" if video_flow_requires_intro_profile(tool_id)
                else "not_required"
            ),
            "next_step_after_profile": (
                "content_lock" if is_uiflow3_route
                else video_post_profile_step(tool_id) if video_flow_requires_intro_profile(tool_id)
                else "profile_next" if tool_id in VIDEO_PROFILE_FIRST_PRODUCTS
                else ""
            ),
            "is_placeholder": bool(placeholder.get("is_placeholder")),
            "requires_provider": bool(tool_id in {"video_ai_real", "script_image_video", "video_trend", "storyboard_prompt"}),
            "requires_worker": bool(tool_id in {"frame_video_local", "video_local_edit", "script_image_video", "video_trend"}),
            "readiness": "route_connected" if row.get("ok") and not placeholder.get("is_placeholder") else "needs_review",
            "last_blocker": ", ".join(placeholder.get("matches") or placeholder.get("forbidden_public_words") or []),
            "public_label": row.get("label"),
            "back_target": row.get("back_target"),
            "canonical": bool(route.get("canonical")),
        })
    return rows


def video_semantics_audit_payload() -> dict:
    creation_products = set(video_uiflow3.ENTRY_ADAPTERS)
    routes = {product: video_public_route_for_tool(product) for product in creation_products}
    contracts = {
        product: _video_uiflow3_initial_route_contract(product)
        for product in creation_products
    }
    visible_steps = tuple(video_uiflow3.CANONICAL_VISIBLE_STEPS)
    content_first_steps = (
        "content_hub", "content_lock", "production_bible", "scene_count",
        "scene_plan", "scene_assignment", "prompts", "branding", "summary",
    )
    content_first_positions = [
        visible_steps.index(step)
        for step in content_first_steps
        if step in visible_steps
    ]
    expected_route_owners = {
        "video_trend": ("vproduct|open|video_trend", "handle_video_product_callback"),
        "video_ai_real": ("vid3|entry|video_ai_real", "handle_video_uiflow3_callback"),
        "script_image_video": ("vproduct|open|script_image_video", "handle_video_product_callback"),
        "frame_video_local": ("vproduct|open|frame_video_local", "handle_video_product_callback"),
        "self_shot_scene_change": ("vproduct|open|self_shot_scene_change", "handle_video_product_callback"),
        "storyboard_prompt": ("vproduct|open|storyboard_prompt", "handle_video_product_callback"),
        "multi_scene_film": ("longvideo|public_guard", "handle_long_video_callback"),
    }
    checks = [
        {
            "name": "creation_products_keep_proven_selective_owners",
            "ok": set(expected_route_owners) == creation_products and all(
                (
                    str(routes[product].get("entry_callback") or ""),
                    str(routes[product].get("handler") or ""),
                ) == expected_route_owners[product]
                for product in expected_route_owners
            ),
            "detail": "Video AI chân thật dùng UIFLOW3; Kịch bản, Video tự quay và các sản phẩm khác giữ owner riêng đã chứng minh.",
        },
        {
            "name": "content_first_order_is_canonical",
            "ok": len(content_first_positions) == len(content_first_steps)
            and content_first_positions == sorted(content_first_positions),
            "detail": "Content Lock và Production Bible luôn đứng trước Scene Plan/Audio/Prompt/Summary.",
        },
        {
            "name": "route_metadata_matches_rendered_entry",
            "ok": all(
                (
                    bool(contracts[product])
                    and str(routes[product].get("first_step") or "") == contracts[product].get("first_step")
                    and tuple(routes[product].get("expected_children") or ()) == tuple(contracts[product].get("children") or ())
                    and str(routes[product].get("back_target") or "") == contracts[product].get("back_target")
                    and str(routes[product].get("flow_type") or "") == "content_first_canonical"
                    and routes[product].get("canonical") is True
                )
                if product in VIDEO_UIFLOW3_SYNCED_PRODUCTS
                else (
                    not contracts[product]
                    and video_route_expected_handler(str(routes[product].get("entry_callback") or ""))
                    == str(routes[product].get("handler") or "")
                    and all(
                        video_route_expected_handler(str(callback or ""))
                        for callback in routes[product].get("expected_children") or ()
                    )
                    and str(routes[product].get("back_target") or "") == "menu|main_video"
                    and bool(str(routes[product].get("first_step") or ""))
                )
                for product in creation_products
            ),
            "detail": "Metadata, owner, nút con và Back khớp đúng entry riêng của từng sản phẩm.",
        },
        {
            "name": "video_idea_remains_read_only_catalog",
            "ok": "video_idea" not in creation_products
            and str(video_public_route_for_tool("video_idea").get("entry_callback") or "") == "videoidea|start"
            and str(video_public_route_for_tool("video_idea").get("handler") or "") == "handle_video_idea_callback",
            "detail": "Kho Ý tưởng không sở hữu draft UIFLOW3 hay commercial tail mới.",
        },
        {
            "name": "frame_render_family_is_preserved",
            "ok": str(video_uiflow3.ENTRY_ADAPTERS["frame_video_local"].get("render_family") or "") == "frame_video",
            "detail": "Ghép ảnh chỉ dùng orchestration chung; render family Frame vẫn riêng.",
        },
        {
            "name": "long_video_submit_lock_is_preserved",
            "ok": video_uiflow3.ENTRY_ADAPTERS["multi_scene_film"].get("public_submit_enabled") is False
            and routes["multi_scene_film"].get("job_reachable") is False,
            "detail": "Video dài tập được lập kế hoạch nhưng submit công khai vẫn khóa.",
        },
    ]
    return {"ok": all(item.get("ok") for item in checks), "checks": checks, "semantics": dict(VIDEO_PRODUCT_SEMANTICS)}


def video_callback_audit_payload() -> dict:
    rows = []
    for tool_id in VIDEO_PUBLIC_ROUTE_MATRIX:
        if tool_id in {"prompt_library", "video_downloader"}:
            continue
        product_id = str(video_public_route_for_tool(tool_id).get("product_id") or tool_id)
        if product_id not in VIDEO_PRODUCT_REGISTRY:
            continue
        route = video_public_route_for_tool(tool_id)
        callbacks = [
            *tuple(route.get("expected_children") or ()),
            str(route.get("back_target") or ""),
        ]
        callbacks = [str(callback) for callback in callbacks if str(callback or "")]
        owners = {callback: video_route_expected_handler(callback) for callback in callbacks}
        missing = [callback for callback, owner in owners.items() if not owner]
        rows.append({
            "product_id": product_id,
            "callbacks": callbacks,
            "owners": owners,
            "missing": missing,
            "ok": not missing,
        })
    return {"ok": all(row.get("ok") for row in rows), "rows": rows}


def video_microflow_audit_payload() -> dict:
    sample_option_rows = [
        ("prompt", video_microflow_build_options("prompt", "demo", "video_ai_real", 5)),
        ("image_prompts", video_microflow_build_options("image_prompts", "demo", "frame_video_local", 4)),
        ("video", video_microflow_build_options("video", "demo", "video_ai_real", 5)),
        ("script", video_microflow_build_options("script", "demo", "script_image_video", 5)),
        ("storyboard", video_microflow_build_options("storyboard", "demo", "storyboard_prompt", 4)),
        ("selfshot", video_microflow_build_options("selfshot", "demo", "self_shot_scene_change", 5)),
        ("video_idea", video_microflow_build_options("video_idea", "demo", "video_idea", 5)),
    ]
    sample_keyboards = [
        task3d_product_intro_keyboard(product_id, "vi")
        for product_id in ("video_ai_real", "video_idea", "storyboard_prompt", "frame_video_local", "script_image_video", "self_shot_scene_change")
    ] + [
        video_microflow_options_keyboard(product_id, "vi", options, kind)
        for kind, options in sample_option_rows
        for product_id in ("video_ai_real",)
    ]
    labels = [
        button.text
        for markup in sample_keyboards
        for row in markup.inline_keyboard
        for button in row
    ]
    callbacks = [
        button.callback_data
        for markup in sample_keyboards
        for row in markup.inline_keyboard
        for button in row
        if button.callback_data
    ]
    checks = [
        {
            "name": "text_steps_registered",
            "ok": VIDEO_MICROFLOW_TEXT_INPUT_STEPS.issubset(set().union(*[set(steps) for steps in [VIDEO_MICROFLOW_TEXT_INPUT_STEPS]])),
            "detail": ", ".join(sorted(VIDEO_MICROFLOW_TEXT_INPUT_STEPS)),
        },
        {
            "name": "media_steps_registered",
            "ok": VIDEO_MICROFLOW_MEDIA_INPUT_STEPS == {
                "awaiting_source_image",
                "awaiting_multiple_images",
                "awaiting_reference_video",
                "awaiting_self_shot_video",
                "awaiting_selfshot2_video",
                "awaiting_selfshot2_logo",
                "awaiting_selfshot3_video",
                "awaiting_video_tail9_logo",
                "storyboard_upload_images",
            },
            "detail": ", ".join(sorted(VIDEO_MICROFLOW_MEDIA_INPUT_STEPS)),
        },
        {
            "name": "required_back_targets_exist",
            "ok": all(
                step in (VIDEO_STEP_BACK_MATRIX.get(product_id) or {}) or step == "intro"
                for product_id, steps in VIDEO_MICROFLOW_REQUIRED_STEPS.items()
                for step in steps
            ),
            "detail": "Mỗi microflow có đường quay lại theo product cha.",
        },
        {
            "name": "image_to_video_after_image",
            "ok": video_back_matrix_target({"product_id": "frame_video_local", "current_step": "profile_select", "draft": {"profile_origin_step": "awaiting_multiple_images"}}) == "awaiting_multiple_images",
            "detail": "Ghép ảnh không vào profile trước khi có ảnh/prompt ảnh.",
        },
        {
            "name": "self_shot_requires_source_video",
            "ok": video_back_matrix_target({"product_id": "self_shot_scene_change", "current_step": "profile_select", "draft": {"profile_origin_step": "awaiting_self_shot_video"}}) == "awaiting_self_shot_video",
            "detail": "Self-shot quay lại đúng bước gửi video nguồn.",
        },
        {
            "name": "no_inner_prompt_vault_buttons",
            "ok": "📚 Dùng prompt từ kho" not in labels and "vpromptlib|start" not in callbacks,
            "detail": "Flow con không lặp Kho mẫu ý tưởng và câu lệnh.",
        },
        {
            "name": "suggestions_have_multiple_selectable_options",
            "ok": all(len(options) >= (5 if kind == "video_idea" else 3) for kind, options in sample_option_rows),
            "detail": "Mỗi gợi ý có 3-5 lựa chọn thật, không chỉ một nút Dùng hướng này.",
        },
        {
            "name": "option_keyboard_not_single_use_direction",
            "ok": all("✅ Dùng hướng này" not in label for label in labels),
            "detail": "Kết quả gợi ý có nút chọn từng lựa chọn riêng.",
        },
        {
            "name": "suggestion_buttons_show_options_before_count",
            "ok": video_back_matrix_target({"product_id": "storyboard_prompt", "current_step": "storyboard_suggestion_scene_count", "draft": {"product_id": "storyboard_prompt"}}) == "storyboard_idea"
            and video_back_matrix_target({"product_id": "frame_video_local", "current_step": "image_to_video_image_suggestion_scene_count", "draft": {"product_id": "frame_video_local"}}) == "frame_suggest_image",
            "detail": "Gợi ý ra danh sách chọn trước; chọn xong mới hỏi số khung/cảnh và Quay lại về màn gợi ý.",
        },
        {
            "name": "storyboard_separates_image_and_video_scenes",
            "ok": bool(video_microflow_build_image_scenes("demo", 4, "cinematic"))
            and bool(video_microflow_build_final_video_scenes(video_microflow_build_image_scenes("demo", 4, "cinematic"), 5)),
            "detail": "Code/state phân biệt storyboard_image_scenes và final_video_scenes.",
        },
    ]
    return {"ok": all(check.get("ok") for check in checks) and video_callback_audit_payload().get("ok") is True, "checks": checks, "callbacks": video_callback_audit_payload()}


