def video_image_prompt_set_text(session: dict | None = None, lang: str = "vi") -> str:
    draft = dict((session or {}).get("draft") or {})
    selected = dict(draft.get("selected_image_prompt_set") or video_microflow_selected_option(session))
    images = list(selected.get("images") or [])
    lines = [
        "🎨 <b>Bộ ảnh/câu lệnh ảnh đã chọn</b>",
        "",
        f"<b>{html.escape(str(selected.get('title') or 'Bộ ảnh'))}</b>",
        html.escape(str(selected.get("description") or "")),
        "",
    ]
    for item in images[:12]:
        lines.append(f"{safe_int(item.get('index'), 0)}. {html.escape(str(item.get('image_prompt') or ''))}")
    lines.extend(["", "Bước này chỉ lập kế hoạch ảnh đầu vào, chưa tạo ảnh/video thật và chưa trừ Xu."])
    return "\n".join(lines)


def video_image_prompt_set_keyboard(lang: str = "vi") -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ Dùng bộ ảnh này", callback_data="vproduct|image_prompt_set_use"), InlineKeyboardButton("🖼 Tạo ảnh", callback_data="vproduct|image_prompt_set_create")],
        [InlineKeyboardButton("🔄 Gợi ý lại", callback_data="vproduct|microflow_regenerate"), InlineKeyboardButton("✍️ Sửa ý tưởng", callback_data="vproduct|microflow_edit")],
        [InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vproduct|back"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
    ])


def task3d_product_intro_text(product_id: str, lang: str = "vi") -> str:
    product = VIDEO_PRODUCT_REGISTRY.get(str(product_id or "")) or {}
    if not product:
        return "⚠️ Sản phẩm video không tồn tại. Bot chưa trừ Xu."
    if str(product_id or "") == "script_image_video":
        return video_script_hub_text(lang)
    if normalize_user_language(lang) != "vi":
        copy = public_hub_copy(lang)
        video_copy = public_video_deep_copy(lang)
        return (
            f"🎬 <b>{copy['video_label']}</b>\n\n"
            f"{copy['freehub_input_title'].format(item=video_copy['video_prompt'])}\n\n"
            f"{video_copy['no_charge']}"
        )
    return task3d_public_copy(product_id, lang)


def video_scene3_canonical_entry_keyboard(
    product_id: str,
    lang: str = "vi",
    *,
    parent_callback: str = "menu|main_video",
) -> InlineKeyboardMarkup:
    """Shared public entry for every canonical short-video product."""

    is_vi = normalize_user_language(lang) == "vi"
    copy = public_hub_copy(lang)
    video_copy = public_video_deep_copy(lang)
    protected = str(product_id or "") in {
        "frame_video_local", "image_to_video", "video_edit", "video_local_edit",
    }
    secondary_label = ui_text(lang, "common.main_menu") if protected else "🎬 Menu Video"
    secondary_callback = "menu|main" if protected else "menu|main_video"
    return video_scene3_keyboard([
        [
            (
                "✍️ Tự nhập nội dung" if is_vi else f"✍️ {copy['freehub_custom_input']}",
                f"vproduct|scene3_mode|{product_id}|manual",
            ),
            (
                "💡 Gợi ý nội dung" if is_vi else f"💡 {copy['freehub_more_suggestions']}",
                f"vproduct|scene3_mode|{product_id}|suggestions",
            ),
        ],
        [
            (f"⬅️ {video_copy['back_video']}", parent_callback),
            (secondary_label, secondary_callback),
        ],
    ])


def task3d_product_intro_keyboard(
    product_id: str,
    lang: str = "vi",
    *,
    parent_callback_override: str = "",
) -> InlineKeyboardMarkup:
    product = VIDEO_PRODUCT_REGISTRY.get(str(product_id or "")) or {}
    if str(product_id or "") == "video_local_edit":
        return video_edit_hub_keyboard(lang)
    if str(product_id or "") == "frame_video_local":
        return ivf.frame_video_unified_menu_keyboard(lang)
    if str(product_id or "") == "script_image_video":
        return video_script_hub_keyboard(lang)
    is_vi = normalize_user_language(lang) == "vi"
    copy = public_hub_copy(lang)
    video_copy = public_video_deep_copy(lang)
    parent_callback = str(parent_callback_override or product.get("parent_menu_callback") or "menu|main_video")
    menu_label = f"⬅️ {video_copy['back_video']}"
    protected = str(product_id or "") in {
        "frame_video_local", "image_to_video", "video_edit", "video_local_edit",
    }
    secondary_menu = (
        (ui_text(lang, "common.main_menu"), "menu|main")
        if protected
        else ("🎬 Menu Video", "menu|main_video")
    )
    if (
        str(product_id or "") in video_flow7.ENTRY_ROWS
        and str(product_id or "") != "script_image_video"
    ):
        rows = video_flow7.entry_rows(str(product_id))
        rows.append([(menu_label, parent_callback), secondary_menu])
        return video_scene3_keyboard(rows)
    rows_by_product = {
        "video_trend": [
            [("🔥 Gợi ý trend hot", "vproduct|trend_today"), ("🗂 Ý tưởng video có sẵn", "vproduct|idea_library|video_trend")],
            [("✍️ Tự nhập trend", "vproduct|trend_custom"), ("📖 Xem hướng dẫn", "menu|guide_video_ai")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "video_idea": [
            [("🔎 Khám phá ý tưởng", "videa|page|1"), ("📖 Xem hướng dẫn video", "menu|guide_video_ai")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "storyboard_prompt": [
            [("🖼 Gửi bảng phân cảnh sẵn", "vproduct|storyboard_upload|storyboard_prompt"), ("💡 Gợi ý bảng phân cảnh", "vproduct|storyboard_suggest|storyboard_prompt")],
            [("🗂 Ý tưởng video có sẵn", "vproduct|idea_library|storyboard_prompt"), ("📖 Xem hướng dẫn video", "menu|guide_video_ai")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "motion_prompt": [
            [("✍️ Mô tả cảnh", "vproduct|input_text|motion_prompt"), ("📷 Gửi ảnh", "vproduct|input_media|motion_prompt")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "image_to_video": [
            [("📷 Gửi ảnh", "vproduct|input_media|image_to_video"), ("✍️ Mô tả cảnh", "vproduct|input_text|image_to_video")],
            [(menu_label, parent_callback), (ui_text(lang, "common.main_menu"), "menu|main")],
        ],
        "frame_video_local": [
            [("📎 Gửi ảnh", "vproduct|frame_send_images|frame_video_local"), ("🖼 Dùng ảnh gần nhất", "vproduct|frame_recent|frame_video_local")],
            [("📚 Dùng ảnh từ storyboard", "vproduct|asset_storyboard_prompt"), ("🎨 Gợi ý tạo ảnh trước", "vproduct|frame_suggest_image|frame_video_local")],
            [(menu_label, parent_callback), (ui_text(lang, "common.main_menu"), "menu|main")],
        ],
        "video_ai_real": [
            [("✨ Prompt → Video", "vproduct|ai_prompt_menu|video_ai_real"), ("🖼 Ảnh → Video", "vproduct|ai_image_menu|video_ai_real")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "script_image_video": [],
        "self_shot_scene_change": [
            [("🎥 Gửi video tự quay", "vproduct|selfshot_source|upload"), ("📖 Xem hướng dẫn video", "menu|guide_video_ai")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "multi_scene_film": [
            [("✍️ Nhập ý tưởng phim", "vproduct|film_manual|multi_scene_film"), ("💡 Gợi ý cốt truyện", "vproduct|film_story|multi_scene_film")],
            [("📄 Gửi kịch bản phim", "vproduct|film_script|multi_scene_film"), ("📖 Xem hướng dẫn video", "menu|guide_video_ai")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "video_reference": [
            [("📎 Gửi video mẫu", "vproduct|legacy|video_reference"), ("🔗 Gửi link mẫu", "vproduct|input_text|video_reference")],
            [("✍️ Mô tả phong cách", "vproduct|input_detail|video_reference"), ("📖 Xem hướng dẫn video", "menu|guide_video_ai")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "audio_addons": [
            [("🎵 Không thêm", "vproduct|addon_skip"), ("🎙 Chọn giọng đọc", "vfinal|voice")],
            [("📂 Chọn nhạc từ kho", "vfinal|music_library"), ("📖 Xem hướng dẫn video", "menu|guide_video_ai")],
            [(menu_label, parent_callback), secondary_menu],
        ],
        "video_local_edit": [
            [("📎 Gửi video", "videoedit|upload"), ("✂️ Cắt video", "videoedit|cut")],
            [("📐 Đổi tỉ lệ", "videoedit|resize"), ("🗜 Nén video", "videoedit|compress")],
            [(menu_label, parent_callback), (ui_text(lang, "common.main_menu"), "menu|main")],
        ],
    }
    rows = rows_by_product.get(product_id, [
        [("✍️ Nhập nội dung" if is_vi else f"✍️ {copy['freehub_custom_input']}", f"vproduct|input_text|{product_id}"), ("📖 Xem hướng dẫn video" if is_vi else f"📖 {video_copy['video_edit_guide']}", "menu|guide_video_ai")],
        [(menu_label, parent_callback), secondary_menu],
    ])
    if not is_vi:
        rows = [[
            (f"✍️ {copy['freehub_custom_input']}", f"vproduct|input_text|{product_id}"),
            (f"📖 {video_copy['video_edit_guide']}", "menu|guide_video_ai"),
        ], [(menu_label, parent_callback), secondary_menu]]
    return video_scene3_keyboard(rows)


