def video_b14_fake_asset_pack(admin: bool = True):
    pack = video_assets.new_asset_pack(["fake admin asset pack; no provider call"])
    video_assets.add_asset(pack, asset_type="character_reference", file_id="fake-character", admin=admin)
    video_assets.add_asset(pack, asset_type="product_reference", file_id="fake-product", admin=admin)
    video_assets.add_asset(pack, asset_type="scene_background", file_id="fake-background", admin=admin)
    video_assets.add_asset(pack, asset_type="storyboard_frame", file_id="fake-frame-1", scene_index=1, admin=admin)
    video_assets.add_asset(pack, asset_type="logo", file_id="fake-logo", admin=admin)
    video_assets.add_asset(pack, asset_type="voice_audio", file_id="fake-voice", admin=admin)
    video_assets.add_asset(pack, asset_type="music_audio", file_id="fake-music", admin=admin)
    return pack


def video_b14_storyboard_plan(profile_id: str = "product_review", scenes: int = 3, *, idea_text: str = ""):
    pack = video_b14_fake_asset_pack(admin=True)
    plan = video_storyboard.create_storyboard_plan(
        profile_id=profile_id,
        idea_text=idea_text or "Review sản phẩm TOAN AAS bằng video ngắn, rõ lợi ích và CTA.",
        asset_pack=pack,
        scene_count=scenes,
    )
    video_continuity.build_continuity_prompts(plan.story_bible, plan.scene_cards)
    return plan


def video_b14_storyboard_preview_text(plan) -> str:
    asset_summary = video_assets.asset_reference_summary(plan.asset_pack)
    scene_count = len(plan.scene_cards)
    context = dict(getattr(plan, "prompt_context", {}) or {})
    ledger = dict(getattr(plan, "continuity_ledger", {}) or {})
    lines = [
        "🧠 <b>Xem trước Storyboard và câu lệnh</b>",
        "<b>Bản kế hoạch video</b>",
        "",
        "TOAN AAS đã chọn ngữ cảnh phù hợp và ghép ý tưởng, loại video, tư liệu thành một hướng dựng liền mạch:",
        f"• Loại video: <b>{html.escape(str(plan.profile.menu_label))}</b>",
        f"• Ngữ cảnh sản phẩm / nhóm nội dung: <b>{html.escape(str(context.get('product_domain') or 'tổng quát'))}</b>",
        f"• Phong cách: {html.escape(str(context.get('selected_visual_style') or plan.story_bible.visual_style))}",
        f"• Màu sắc: {html.escape(str(context.get('selected_color_tone') or plan.story_bible.color_palette))}",
        f"• Cảm xúc: {html.escape(str(context.get('selected_emotional_tone') or plan.story_bible.brand_tone or 'theo mạch câu chuyện'))}",
        f"• Chuyển động: {html.escape(str(context.get('selected_motion_language') or plan.story_bible.motion_style))}",
        f"• Chuyển cảnh: {html.escape(str(context.get('selected_transition_style') or 'match cut'))}",
        f"• Nhịp dựng: {html.escape(str(plan.story_bible.motion_style))}",
        f"• Tư liệu đã có: <b>{html.escape(asset_summary)}</b>",
        f"• Nhân vật/sản phẩm chính: {html.escape(str(plan.story_bible.main_subject))}",
        f"• Bối cảnh: {html.escape(str(plan.story_bible.setting))}",
        f"• Số cảnh gợi ý: <b>{scene_count}</b>",
        f"• Mạch cảm xúc: {html.escape(str(ledger.get('emotional_arc') or 'liền mạch từ mở đầu tới kết'))}",
        f"• Giọng đọc mặc định: {html.escape(str(plan.story_bible.voice_policy))}",
        f"• Nhạc mặc định: {html.escape(str(plan.story_bible.music_policy))}",
        f"• Phụ đề mặc định: {html.escape(str(plan.story_bible.subtitle_policy))}",
        f"• Logo mặc định: {html.escape(str(plan.story_bible.logo_policy))}",
        "",
        "<b>Một vài cảnh đầu</b>",
    ]
    for card in plan.scene_cards[:5]:
        lines.append(
            f"{card.scene_index}. <b>{html.escape(card.role)}</b> — {html.escape(card.visual_goal)}\n"
            f"   {html.escape(card.subject_action)}\n"
            f"   Góc quay: {html.escape(card.camera_motion)}"
        )
    lines.extend(["", "Màn này chỉ là kế hoạch dạng văn bản. Chưa tạo tệp thật, chưa trừ Xu."])
    return "\n".join(lines)


def video_b14_prompt_bundle_from_plan(plan) -> dict:
    context = dict(getattr(plan, "prompt_context", {}) or {})
    ledger = dict(getattr(plan, "continuity_ledger", {}) or {})
    cards = list(getattr(plan, "scene_cards", []) or [])
    shot_table = []
    image_prompts = []
    video_prompts = []
    for card in cards:
        image_prompt = (
            f"Cảnh {card.scene_index}: {card.visual_goal}. "
            f"Keyframe subject: {card.exact_subject or card.subject_action}. "
            f"Reference/consistency: {card.continuity_lock}. "
            f"Style/color/camera: {card.color_tone}; {card.camera_angle}; {card.composition}. "
            f"Negative: {card.negative_prompt}."
        )
        video_prompt = str(card.provider_prompt or "")
        image_prompts.append(image_prompt)
        video_prompts.append(video_prompt)
        shot_table.append({
            "shot_number": int(card.scene_index),
            "duration_seconds": float(card.duration_seconds),
            "camera_angle": str(card.composition),
            "camera_movement": str(card.camera_motion),
            "scene_purpose": str(card.visual_goal),
            "image_prompt": image_prompt,
            "video_prompt": video_prompt,
            "entry_state": str(card.entry_state),
            "exit_state": str(card.exit_state),
            "transition_bridge": str(card.transition_to_next),
            "match_cut_hint": str(card.match_cut_hint),
        })
    return {
        "bundle_id": f"b14_{getattr(plan.profile, 'profile_id', 'video')}_{len(cards)}",
        "title": getattr(plan.story_bible, "title", "TOAN AAS Video"),
        "short_summary": getattr(plan.story_bible, "core_message", ""),
        "hook": cards[0].subtitle_line if cards else "",
        "caption": "",
        "image_prompts": image_prompts,
        "video_prompts": video_prompts,
        "shot_table": shot_table,
        "provider_payload": {
            "profile_id": getattr(plan.profile, "profile_id", ""),
            "creative_controls": dict(getattr(plan.story_bible, "creative_controls", {}) or {}),
            "prompt_context": context,
            "continuity_ledger": ledger,
        },
        "continuity_ledger": ledger,
        "postprocess_cues": dict(context.get("selected_voice_music_subtitle_cues") or {}),
        "negative_prompt": str(context.get("selected_negative_prompt") or ""),
    }


def video_b14_prompt_bundle_from_plan_payload(plan: dict) -> dict:
    plan = dict(plan or {})
    context = dict(plan.get("prompt_context") or {})
    ledger = dict(plan.get("continuity_ledger") or {})
    story_bible = dict(plan.get("story_bible") or {})
    profile = dict(plan.get("profile") or {})
    cards = list(plan.get("scene_cards") or [])
    shot_table = []
    image_prompts = []
    video_prompts = []
    for fallback_index, card in enumerate(cards, 1):
        card = dict(card or {})
        scene_index = safe_int(card.get("scene_index"), fallback_index)
        visual_goal = str(card.get("visual_goal") or "")
        subject_action = str(card.get("subject_action") or "")
        composition = str(card.get("composition") or card.get("camera_angle") or "")
        color_tone = str(card.get("color_tone") or story_bible.get("color_palette") or "")
        negative = str(card.get("negative_prompt") or story_bible.get("negative_prompt") or context.get("selected_negative_prompt") or "")
        image_prompt = (
            f"Cảnh {scene_index}: {visual_goal}. "
            f"Keyframe subject: {str(card.get('exact_subject') or subject_action)}. "
            f"Reference/consistency: {str(card.get('continuity_lock') or ledger.get('main_subject') or '')}. "
            f"Style/color/camera: {color_tone}; {str(card.get('camera_angle') or '')}; {composition}. "
            f"Negative: {negative}."
        )
        video_prompt = str(card.get("provider_prompt") or card.get("video_prompt") or visual_goal or "")
        image_prompts.append(image_prompt)
        video_prompts.append(video_prompt)
        shot_table.append({
            "shot_number": scene_index,
            "duration_seconds": float(card.get("duration_seconds") or TASK3D_SCENE_SECONDS),
            "camera_angle": composition,
            "camera_movement": str(card.get("camera_motion") or ""),
            "scene_purpose": visual_goal,
            "image_prompt": image_prompt,
            "video_prompt": video_prompt,
            "entry_state": str(card.get("entry_state") or ""),
            "exit_state": str(card.get("exit_state") or ""),
            "transition_bridge": str(card.get("transition_to_next") or card.get("transition_bridge") or ""),
            "match_cut_hint": str(card.get("match_cut_hint") or ""),
        })
    return {
        "bundle_id": f"b14_{profile.get('profile_id') or story_bible.get('profile_id') or 'video'}_{len(cards)}",
        "title": story_bible.get("title") or "TOAN AAS Video",
        "short_summary": story_bible.get("core_message") or "",
        "hook": str((cards[0] or {}).get("subtitle_line") or "") if cards else "",
        "caption": "",
        "image_prompts": image_prompts,
        "video_prompts": video_prompts,
        "shot_table": shot_table,
        "provider_payload": {
            "profile_id": profile.get("profile_id") or story_bible.get("profile_id") or "",
            "creative_controls": dict(story_bible.get("creative_controls") or {}),
            "prompt_context": context,
            "continuity_ledger": ledger,
        },
        "continuity_ledger": ledger,
        "postprocess_cues": dict(context.get("selected_voice_music_subtitle_cues") or {}),
        "negative_prompt": str(context.get("selected_negative_prompt") or story_bible.get("negative_prompt") or ""),
    }


def video_b14_prompt_text_from_session(session: dict, kind: str = "video") -> str:
    draft = dict((session or {}).get("draft") or {})
    plan = dict(draft.get("b14_storyboard_plan") or {})
    cards = list(plan.get("scene_cards") or [])
    if not cards:
        return "⚠️ Bộ câu lệnh chưa sẵn sàng. TOAN AAS chưa xử lý video và chưa trừ Xu."
    title = "🖼 Câu lệnh tạo ảnh" if kind == "image" else "🎥 Câu lệnh tạo video"
    lines = [
        title,
        "",
        "Toàn bộ câu lệnh hiện tại được hiển thị nguyên văn bên dưới. Chưa tạo tệp và chưa trừ Xu.",
        "",
    ]
    for index, card in enumerate(cards, 1):
        if kind == "image":
            prompt = (
                f"{card.get('visual_goal') or ''}. "
                f"{card.get('subject_action') or ''}. "
                f"{card.get('composition') or ''}. "
                f"{card.get('background') or ''}."
            )
        else:
            prompt = str(card.get("provider_prompt") or card.get("video_prompt") or card.get("visual_goal") or "")
        lines.append(f"Cảnh {index}\n{prompt}")
    return "\n\n".join(lines)


def video_b14_prompt_video_text_from_session(session: dict, lang: str = "vi") -> str:
    draft = dict((session or {}).get("draft") or {})
    plan = dict(draft.get("b14_storyboard_plan") or {})
    cards = list(plan.get("scene_cards") or [])
    if not cards:
        return "⚠️ Phiên tạo video bị thiếu dữ liệu. TOAN AAS chưa xử lý video và chưa trừ Xu."
    story_bible = dict(plan.get("story_bible") or {})
    context = dict(plan.get("prompt_context") or {})
    emotion = str(context.get("selected_emotional_tone") or story_bible.get("brand_tone") or "theo mạch câu chuyện")
    visual_style = str(context.get("selected_visual_style") or story_bible.get("visual_style") or "theo profile")
    negative = str(context.get("selected_negative_prompt") or story_bible.get("negative_prompt") or "không méo chữ/logo, không đổi nhân vật chính")
    lines = [
        "🎥 Câu lệnh tạo video",
        "",
        "Toàn bộ câu lệnh hiện tại được hiển thị nguyên văn bên dưới. Chưa tạo tệp và chưa trừ Xu.",
        "",
    ]
    for index, card in enumerate(cards, 1):
        card = dict(card or {})
        camera = str(card.get("camera_motion") or card.get("camera_angle") or card.get("composition") or "camera mượt theo cảnh")
        subject = str(card.get("subject_action") or card.get("exact_subject") or card.get("visual_goal") or "chủ thể chính")
        card_style = str(card.get("color_tone") or visual_style)
        card_emotion = str(card.get("emotional_beat") or emotion)
        card_negative = str(card.get("negative_prompt") or negative)
        duration = safe_int(card.get("duration_seconds"), TASK3D_SCENE_SECONDS)
        prompt = str(card.get("provider_prompt") or card.get("video_prompt") or card.get("visual_goal") or "")
        lines.extend([
            f"Cảnh {index}",
            f"• Máy quay và chuyển động: {camera}",
            f"• Chủ thể: {subject}",
            f"• Phong cách hình ảnh: {card_style}",
            f"• Cảm xúc: {card_emotion}",
            f"• Điều cần tránh: {card_negative}",
            f"• Thời lượng dự kiến: {duration} giây",
        ])
        if prompt:
            lines.extend(["• Câu lệnh nguyên văn:", prompt])
        lines.append("")
    return "\n".join(lines).strip()


