def product_video_requested_duration_seconds(text: str = "") -> int:
    raw = str(text or "").lower()
    if not raw:
        return 0
    patterns = (
        (r"(\d{1,3})\s*(?:giây|giay|sec|secs|second|seconds|s)\b", 1),
        (r"(\d{1,2})\s*(?:phút|phut|minute|minutes|min|m)\b", 60),
    )
    for pattern, multiplier in patterns:
        match = re.search(pattern, raw)
        if match:
            return max(1, min(180, safe_int(match.group(1), 0) * multiplier))
    if any(word in raw for word in ("1 phút", "mot phut", "một phút")):
        return 60
    return 0


def product_video_predict_intent(text: str = "") -> str:
    lower = str(text or "").lower()
    if any(token in lower for token in ("before after", "trước sau", "truoc sau", "biến đổi", "bien doi")):
        return "before_after"
    if any(token in lower for token in ("demo", "hướng dẫn", "huong dan", "cách dùng", "cach dung", "sử dụng", "su dung")):
        return "demo_usage"
    if any(token in lower for token in ("cinematic", "điện ảnh", "dien anh", "sang trọng", "sang trong", "luxury", "phố đêm", "pho dem")):
        return "cinematic_showcase"
    if any(token in lower for token in ("thương hiệu", "thuong hieu", "brand", "logo", "giới thiệu", "gioi thieu")):
        return "brand_intro"
    if any(token in lower for token in ("bán hàng", "ban hang", "mỹ phẩm", "my pham", "sản phẩm", "san pham", "cta", "chốt đơn", "chot don")):
        return "product_ad"
    if any(token in lower for token in ("trend", "viral", "tiktok", "reels", "shorts")):
        return "trend_short"
    if any(token in lower for token in ("câu chuyện", "cau chuyen", "hành trình", "hanh trinh", "trailer", "phim ngắn", "phim ngan")):
        return "story_video"
    return "unknown"


def product_video_scene_breakdown(intent: str, count: int, prompt: str = "") -> list[str]:
    count = max(1, min(20, safe_int(count, 1)))
    templates = {
        "product_ad": ["hook gây chú ý", "giới thiệu sản phẩm", "công dụng/lợi ích", "CTA/chốt cảm xúc"],
        "brand_intro": ["mở đầu nhận diện thương hiệu", "giá trị/câu chuyện", "sản phẩm hoặc dịch vụ chính", "kết thúc bằng logo/thông điệp"],
        "cinematic_showcase": ["hook hình ảnh mạnh", "chuyển động/bối cảnh chính", "cận chi tiết sang trọng", "kết thúc cảm xúc"],
        "demo_usage": ["vấn đề ban đầu", "cách dùng", "kết quả sau khi dùng", "CTA nhẹ"],
        "before_after": ["trạng thái trước", "quá trình chuyển đổi", "kết quả sau", "nhấn lợi ích"],
        "trend_short": ["hook trend", "cao trào/chuyển động chính", "điểm nhớ cuối", "CTA ngắn"],
        "story_video": ["mở chuyện", "xung đột/chuyển động", "cao trào", "kết thúc"],
        "unknown": ["mở đầu rõ chủ thể", "diễn biến chính", "chi tiết nổi bật", "kết thúc"],
    }
    base = templates.get(intent) or templates["unknown"]
    lines: list[str] = []
    for index in range(count):
        label = base[index] if index < len(base) else f"mở rộng ý {index + 1}"
        lines.append(f"Cảnh {index + 1}: {label}")
    return lines


def product_video_duration_predictor(session: dict | None = None, user_id=0) -> dict:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    prompt = str(session.get("topic") or draft.get("topic") or draft.get("idea") or draft.get("prompt") or "").strip()
    quality = video_b14_quality_for_session(session) or PRODUCT_VIDEO_TRIAL_QUALITY_XU
    requested_seconds = product_video_requested_duration_seconds(prompt)
    intent = product_video_predict_intent(prompt)
    addon_plan = dict(draft.get("b14_addon_plan") or video_b14_addon_plan_from_session(session))
    trial = video_b14_is_trial_quality(quality)
    lower = prompt.lower()
    long_prompt_signals = sum(
        1
        for token in ("hook", "công dụng", "cong dung", "cta", "logo", "nội thất", "noi that", "hành trình", "hanh trinh", "chuyển cảnh", "chuyen canh")
        if token in lower
    )
    if requested_seconds:
        recommended = int(math.ceil(requested_seconds / max(1, TASK3D_SCENE_SECONDS)))
    elif intent in {"product_ad", "demo_usage", "story_video", "before_after"} or long_prompt_signals >= 2:
        recommended = 3 if long_prompt_signals >= 2 else 2
    elif intent in {"cinematic_showcase", "brand_intro"}:
        recommended = 2
    else:
        recommended = 1
    recommended = max(1, min(20, recommended))
    min_scene = 1
    max_scene = 1 if trial else 20
    upgrade_hint = ""
    if trial:
        if recommended > 1 or requested_seconds > PRODUCT_VIDEO_TRIAL_DURATION_SECONDS:
            upgrade_hint = "Nội dung này phù hợp hơn với 2–3 cảnh nếu muốn thể hiện đầy đủ."
        recommended = PRODUCT_VIDEO_TRIAL_FIXED_SCENE_COUNT
    breakdown = product_video_scene_breakdown(intent, recommended, prompt)
    pricing = video_b14_invoice_breakdown(quality, recommended)
    trial_addons = video_b14_trial_addon_policy(addon_plan, quality_xu=quality)
    add_on_impact = []
    if product_video_logo_material_invoice_line(session):
        add_on_impact.append("logo miễn phí vì anh/chị đã gửi logo")
    if addon_plan.get("voice_enabled") and str(addon_plan.get("voice_source") or "").lower() in {"uploaded", "media", "user", "sent"}:
        add_on_impact.append("voice/audio tự gửi không tính phí tạo mới")
    if addon_plan.get("music_enabled") and str(addon_plan.get("music_source") or "").lower() in {"uploaded", "media", "user", "sent", "saved"}:
        add_on_impact.append("nhạc tự gửi/đã lưu không tính phí tạo mới")
    if trial_addons.get("paid_blocked"):
        add_on_impact.append("một số phần bổ sung chưa được tính trong dự đoán")
    if not add_on_impact:
        add_on_impact.append("chưa có add-on tính vào dự đoán")
    confidence = "high" if prompt and (requested_seconds or intent != "unknown") else ("medium" if prompt else "low")
    next_action = f"Chọn {recommended} cảnh / {recommended * TASK3D_SCENE_SECONDS}s"
    return {
        "predicted_intent": intent,
        "recommended_scene_count": recommended,
        "recommended_duration_seconds": recommended * TASK3D_SCENE_SECONDS,
        "min_scene_count": min_scene,
        "max_scene_count": max_scene,
        "scene_breakdown": breakdown,
        "add_on_impact": add_on_impact,
        "price_estimate": {
            "unit_price_xu": quality,
            "scene_count": recommended,
            "subtotal_xu": pricing["subtotal_xu"],
            "discount_xu": pricing["discount_xu"],
            "total_xu": pricing["total_xu"],
        },
        "confidence": confidence,
        "next_action": next_action,
        "requested_duration_seconds": requested_seconds,
        "trial_upgrade_hint": upgrade_hint,
        "trial_limits": {
            "day": PRODUCT_VIDEO_TRIAL_LIMIT_DAY,
            "week": PRODUCT_VIDEO_TRIAL_LIMIT_WEEK,
            "month": PRODUCT_VIDEO_TRIAL_LIMIT_MONTH,
        } if trial else {},
    }


def product_video_duration_predictor_text(session: dict | None = None, user_id=0, lang: str = "vi") -> str:
    prediction = product_video_duration_predictor(session, user_id)
    price = dict(prediction.get("price_estimate") or {})
    lines = [
        "🧭 <b>Gợi ý thời lượng</b>",
        f"TOAN AAS đề xuất <b>{prediction['recommended_scene_count']} cảnh</b> khoảng <b>{prediction['recommended_duration_seconds']} giây</b> cho prompt hiện tại.",
    ]
    breakdown = list(prediction.get("scene_breakdown") or [])[:4]
    if breakdown:
        lines.append("")
        lines.extend(f"• {html.escape(item)}" for item in breakdown)
    hint = str(prediction.get("trial_upgrade_hint") or "").strip()
    if hint:
        lines.extend(["", html.escape(hint), "Giới hạn: 1 lần/ngày · 3 lần/tuần · 10 lần/tháng."])
    lines.extend([
        "",
        f"Ước tính: <b>{xu_number(safe_int(price.get('unit_price_xu'), 0))} Xu/cảnh</b> · tổng <b>{xu_number(safe_int(price.get('total_xu'), 0))} Xu</b>.",
        f"Bước tiếp theo: <b>{html.escape(str(prediction.get('next_action') or 'Chọn số cảnh'))}</b>.",
        "Gợi ý này chỉ để lập kế hoạch, chưa dựng video và chưa trừ Xu.",
    ])
    return "\n".join(lines)


def video_b14_build_storyboard_for_session(user_id, session: dict, *, scene_count: int | None = None):
    draft = dict((session or {}).get("draft") or {})
    product_id = str(session.get("product_id") or "")
    idea = str(session.get("topic") or draft.get("topic") or TASK3D_SAMPLE_TOPICS.get(product_id) or "video ngắn rõ chủ thể").strip()
    pack = video_b14_asset_pack_from_session(session)
    profile = video_profiles.get_video_profile(video_b14_profile_id_for_session(session))
    creative_controls = video_b14_creative_controls_to_storyboard(session)
    plan = video_storyboard.create_storyboard_plan(
        profile_id=profile.profile_id,
        idea_text=idea,
        asset_pack=pack,
        scene_count=scene_count or video_b14_scene_count_for_session(session, 3),
        creative_controls=creative_controls,
    )
    video_continuity.build_continuity_prompts(plan.story_bible, plan.scene_cards)
    prompt_bundle = video_b14_prompt_bundle_from_plan(plan)
    draft.update({
        "b14_storyboard_plan": plan.to_dict(),
        "prompt_bundle": prompt_bundle,
        "prompt_bundle_id": prompt_bundle.get("bundle_id"),
        "b14_profile_id": profile.profile_id,
        "creative_control_json": creative_controls,
        "b14_creative_controls": creative_controls,
        "b14_scene_count": len(plan.scene_cards),
        "topic": idea,
        "provider_called": False,
        "xu_charged": 0,
    })
    session["draft"] = draft
    save_video_session(user_id, session)
    return plan


def video_b14_resize_storyboard_for_session(user_id, session: dict, scene_count: int) -> tuple[dict, str]:
    count = max(1, min(20, safe_int(scene_count, 3)))
    draft = dict((session or {}).get("draft") or {})
    old_plan = dict(draft.get("b14_storyboard_plan") or {})
    old_cards = [dict(item or {}) for item in list(old_plan.get("scene_cards") or [])]
    if old_cards and len(old_cards) == count:
        draft["b14_scene_count"] = count
        draft["b14_scene_resize_note"] = ""
        session["draft"] = draft
        save_video_session(user_id, session)
        return session, ""
    note = ""
    if old_cards and len(old_cards) > count:
        new_plan = dict(old_plan)
        merged_cards = []
        for idx, card in enumerate(old_cards[:count], 1):
            card = dict(card)
            card["scene_index"] = idx
            merged_cards.append(card)
        new_plan["scene_cards"] = merged_cards
        note = f"TOAN AAS sẽ rút gọn storyboard còn {count} cảnh."
    else:
        generated = video_b14_build_storyboard_for_session(user_id, session, scene_count=count)
        session = get_video_session(user_id)
        generated_plan = generated.to_dict()
        generated_cards = [dict(item or {}) for item in list(generated_plan.get("scene_cards") or [])]
        merged_cards = []
        for idx in range(count):
            if idx < len(old_cards):
                card = dict(old_cards[idx])
                card["scene_index"] = idx + 1
                merged_cards.append(card)
            elif idx < len(generated_cards):
                card = dict(generated_cards[idx])
                card["scene_index"] = idx + 1
                merged_cards.append(card)
        new_plan = dict(generated_plan)
        new_plan["scene_cards"] = merged_cards
        if old_cards and count > len(old_cards):
            note = f"TOAN AAS đã giữ {len(old_cards)} cảnh cũ và mở rộng storyboard lên {count} cảnh."
    draft = dict((get_video_session(user_id).get("draft") if old_cards and len(old_cards) <= count else session.get("draft")) or {})
    draft.update({
        "b14_storyboard_plan": new_plan,
        "prompt_bundle": video_b14_prompt_bundle_from_plan_payload(new_plan),
        "b14_scene_count": count,
        "b14_scene_resize_note": note,
        "provider_called": False,
        "xu_charged": 0,
    })
    session["draft"] = draft
    save_video_session(user_id, session)
    return session, note


def video_b14_default_addon_plan(profile_id: str = "storytelling") -> dict:
    profile = video_profiles.get_video_profile(profile_id)
    defaults = dict(profile.postprocess_defaults or {})
    voice_volume = int(round(float(defaults.get("voice_volume", 1.0) or 0.0) * 100))
    music_volume = int(round(float(defaults.get("music_volume", 0.0) or 0.0) * 100))
    voice_enabled = voice_volume > 0 and "usually no voice" not in str(profile.voice_style).lower()
    music_enabled = music_volume > 0
    default_voice_source = "default_male" if voice_enabled else "none"
    default_voice_id = default_tts_voice_id("male") if voice_enabled else ""
    return {
        "voice_enabled": bool(voice_enabled),
        "voice_source": default_voice_source,
        "voice_id": "",
        "voice_provider_voice_id": default_voice_id,
        "voice_profile_id": 0,
        "voice_label": "Nam mặc định" if voice_enabled else "",
        "video_voice_speed": VIDEO_AUDIO_DEFAULT_VOICE_SPEED,
        "voice_speed": VIDEO_AUDIO_DEFAULT_VOICE_SPEED,
        "voice_volume_percent": max(70, min(120, voice_volume or 100)),
        "voice_speed_percent": 100,
        "source_audio_enabled": False,
        "source_audio_volume_percent": 100,
        "music_enabled": bool(music_enabled),
        "music_source": "default" if music_enabled else "none",
        "music_id": "",
        "video_music_speed": VIDEO_AUDIO_DEFAULT_MUSIC_SPEED,
        "music_speed": VIDEO_AUDIO_DEFAULT_MUSIC_SPEED,
        "music_volume_percent": min(VIDEO_B14_2_MUSIC_VOLUME_OPTIONS, key=lambda item: abs(item - (music_volume or 10))),
        "sfx_enabled": bool(profile.sfx_policy),
        "sfx_volume_percent": 35,
        "subtitle_enabled": bool(defaults.get("burn_subtitles", True)),
        "subtitle_source": "from_narration" if defaults.get("burn_subtitles", True) else "none",
        "subtitle_target_language": "",
        "dub_enabled": False,
        "dub_source": "none",
        "dub_volume_percent": 100,
        "dub_target_language": "",
        "dub_voice_source": "same_as_voice",
        "environment_audio_volume_percent": 100,
        "audio_ducking": True,
        "audio_clipping_guard": True,
        "logo_enabled": False,
        "logo_source": "none",
        "logo_text": "",
        "logo_file_id": "",
        "logo_position": str(defaults.get("logo_position") or "bottom_right"),
        "logo_opacity_percent": int(round(float(defaults.get("logo_opacity", 0.82) or 0.82) * 100)),
    }


def video_b14_addon_plan_from_session(session: dict | None = None) -> dict:
    draft = dict((session or {}).get("draft") or {})
    plan = dict(draft.get("b14_addon_plan") or {})
    defaults = video_b14_default_addon_plan(str(draft.get("b14_profile_id") or video_b14_profile_id_for_session(session)))
    defaults.update({key: value for key, value in plan.items() if key in defaults})
    logo_source = str(defaults.get("logo_source") or "none")
    if logo_source not in {"none", "text"}:
        logo_text_value = logo_watermark_clean_text(defaults.get("logo_text") or "")
        defaults["logo_file_id"] = ""
        if logo_text_value:
            defaults["logo_source"] = "text"
            defaults["logo_text"] = logo_text_value
        else:
            defaults["logo_enabled"] = False
            defaults["logo_source"] = "none"
    for extra_key in ("narration_text", "music_note", "sfx_note", "subtitle_note", "dub_note", "logo_note"):
        if extra_key in plan:
            defaults[extra_key] = str(plan.get(extra_key) or "")
    return defaults


def video_b14_set_addon_plan(user_id, session: dict, **fields) -> dict:
    draft = dict((session or {}).get("draft") or {})
    plan = video_b14_addon_plan_from_session(session)
    plan.update({key: value for key, value in fields.items() if key in plan})
    for extra_key in ("narration_text", "music_note", "sfx_note", "subtitle_note", "dub_note", "logo_note"):
        if extra_key in fields:
            plan[extra_key] = str(fields.get(extra_key) or "")[:4000]
    draft["b14_addon_plan"] = plan
    session["draft"] = draft
    return save_video_session(user_id, session)


def video_b14_lock_product_video_addons(plan: dict | None = None) -> dict:
    locked = dict(plan or {})
    locked.update({
        "voice_enabled": False,
        "voice_source": "none",
        "voice_provider_voice_id": "",
        "dub_enabled": False,
        "dub_source": "none",
        "music_enabled": False,
        "music_source": "none",
        "sfx_enabled": False,
        "subtitle_enabled": False,
        "subtitle_source": "none",
        "logo_enabled": False,
        "logo_source": "none",
        "logo_text": "",
        "logo_file_id": "",
    })
    return locked


def video_b14_clear_runtime_selection_for_package(
    session: dict | None = None,
    *,
    preserve_addons: bool = False,
) -> dict:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    planned_addons = deepcopy(dict(draft.get("b14_addon_plan") or {}))
    for key in (
        "b14_scene_count",
        "b14_scene_count_selected",
        "b14_invoice",
        "b14_invoice_return_step",
        "b14_project_id",
        "b14_queue_job",
        "b14_queue_job_id",
        "b14_duplicate_prevented",
        "b14_provider_preflight",
        "uiflow3_invoice_confirmation",
        "provider_called",
        "xu_charged",
    ):
        draft.pop(key, None)
    draft["b14_addon_plan"] = (
        planned_addons
        if preserve_addons
        else video_b14_lock_product_video_addons(planned_addons)
    )
    session["draft"] = draft
    return session


