def video_b14_narration_from_storyboard(session: dict | None = None) -> str:
    draft = dict((session or {}).get("draft") or {})
    addon_plan = dict(draft.get("b14_addon_plan") or {})
    saved = str(addon_plan.get("narration_text") or "").strip()
    if saved:
        return saved[:3500]
    plan = dict(draft.get("b14_storyboard_plan") or {})
    lines = []
    for card in list(plan.get("scene_cards") or [])[:20]:
        line = str(card.get("narration_line") or card.get("subtitle_line") or card.get("visual_goal") or "").strip()
        if line:
            lines.append(f"Cảnh {safe_int(card.get('scene_index'), len(lines) + 1)}: {line}")
    if lines:
        return "\n".join(lines)[:3500]
    topic = str((session or {}).get("topic") or draft.get("topic") or "video của anh/chị").strip()
    return f"Cảnh 1: {topic}\nCảnh 2: nhấn lợi ích chính.\nCảnh 3: kết thúc bằng lời kêu gọi hành động."


def video_b14_narration_source(session: dict | None = None) -> dict:
    draft = dict((session or {}).get("draft") or {})
    addon_plan = dict(draft.get("b14_addon_plan") or {})
    manual = str(addon_plan.get("narration_text") or "").strip()
    if manual:
        return {"ok": True, "source": "manual", "text": manual[:3500]}
    plan = dict(draft.get("b14_storyboard_plan") or {})
    lines = []
    for card in list(plan.get("scene_cards") or [])[:20]:
        line = str(card.get("narration_line") or card.get("subtitle_line") or "").strip()
        if line:
            lines.append(f"Cảnh {safe_int(card.get('scene_index'), len(lines) + 1)}: {line}")
    if lines:
        return {"ok": True, "source": "storyboard", "text": "\n".join(lines)[:3500]}
    generated = video_b14_narration_from_storyboard(session)
    if generated.strip():
        return {"ok": True, "source": "generated", "text": generated[:3500]}
    return {
        "ok": False,
        "source": "missing",
        "text": "",
        "public_message": "TOAN AAS cần lời đọc trước khi bật giọng đọc. Anh/chị bấm Sửa lời đọc rồi gửi kịch bản muốn đọc.",
    }


def video_b14_saved_voice_profiles(user_id, limit: int = 5) -> list[dict]:
    try:
        rows = user_voice_profile_rows(user_id, max(1, int(limit or 5)), 0, include_inactive=False)
    except Exception:
        rows = []
    return [dict(row) for row in rows if voice_profile_can_generate_tts(row)]


def voice_core_vault_lookup(user_id, *, source: str = "saved", limit: int = 5, include_inactive: bool = False) -> list[dict]:
    source = str(source or "saved").strip().lower()
    try:
        rows = user_voice_profile_rows(user_id, max(1, int(limit or 5)), 0, include_inactive=include_inactive)
    except Exception:
        rows = []
    if source in {"uploaded", "uploaded_voice"}:
        rows = [row for row in rows if str(row.get("source_file_id") or row.get("source_file_ref") or "").strip()]
    entries = []
    for row in rows:
        entry = minimax_voice_adapter.voice_vault_entry(row, source="uploaded" if source in {"uploaded", "uploaded_voice"} else "saved")
        if not entry.ok:
            continue
        entries.append({
            "id": entry.profile_id,
            "display_name": entry.display_name,
            "provider_voice_id": entry.provider_voice_id,
            "source": entry.source,
            "status": str(row.get("status") or ""),
        })
    return entries


def video_b14_uploaded_voice_profiles(user_id, limit: int = 5) -> list[dict]:
    try:
        rows = user_voice_profile_rows(user_id, max(1, int(limit or 5)), 0, include_inactive=False)
    except Exception:
        rows = []
    return [
        dict(row)
        for row in rows
        if voice_profile_can_generate_tts(row)
        and str(row.get("source_file_id") or row.get("source_file_ref") or "").strip()
    ]


def video_b14_voice_select_keyboard(user_id, lang: str = "vi") -> InlineKeyboardMarkup:
    buttons = []
    for profile in video_b14_saved_voice_profiles(user_id, 5):
        label = minimax_voice_adapter.friendly_voice_name(profile, f"Giọng #{profile.get('id') or ''}")[:32] or "Giọng đã lưu"
        buttons.append(InlineKeyboardButton(f"📚 {label}", callback_data=f"vproduct|b14_voice_saved_pick|{int(profile.get('id') or 0)}"))
    rows = [buttons[index:index + 2] for index in range(0, len(buttons), 2)]
    if rows and len(rows[-1]) == 1:
        rows[-1].append(InlineKeyboardButton("📖 Xem hướng dẫn", callback_data="menu|guide_video_ai"))
    rows.append([InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vproduct|b14_addon_voice"), InlineKeyboardButton("🎬 Menu Video", callback_data="menu|main_video")])
    return InlineKeyboardMarkup(rows)


def video_b14_voice_resolution(source: str, profile: dict | None = None) -> minimax_voice_adapter.VoiceIdResolution:
    return minimax_voice_adapter.resolve_provider_voice_id(
        voice_source=source,
        profile=profile,
        uploaded_profile=profile,
        default_male_voice_id=default_tts_voice_id("male"),
        default_female_voice_id=default_tts_voice_id("female"),
    )


def voice_core_preview_policy(*, explicit: bool = False, max_seconds: int | None = None) -> minimax_voice_adapter.VoicePreviewPolicy:
    return minimax_voice_adapter.voice_preview_policy(
        explicit=bool(explicit),
        no_charge=True,
        max_seconds=max_seconds or voice_preview_seconds(),
    )


def custom_voice_core_state(readiness: dict | None = None, *, public: bool = True) -> minimax_voice_adapter.CustomVoiceFlowState:
    data = dict(readiness or get_minimax_voice_clone_readiness())
    provider_blocked = bool(data.get("provider_permission_blocked"))
    configured_ready = bool(data.get("ready")) and not provider_blocked
    public_ready = bool(data.get("public_enabled")) and configured_ready
    ready = public_ready if public else configured_ready
    reason = (
        str(data.get("provider_permission_blocker") or "").strip()
        or str(data.get("reason") or "").strip()
        or ("public_custom_voice_locked" if configured_ready and not public_ready and public else "custom_voice_locked")
    )
    return minimax_voice_adapter.custom_voice_flow_state(ready=ready, locked_reason=reason)


def video_b14_apply_voice_choice(user_id, session: dict, source: str, profile: dict | None = None) -> tuple[dict, dict]:
    source = str(source or "none").strip()
    if source == "none":
        next_session = video_b14_set_addon_plan(
            user_id,
            session,
            voice_enabled=False,
            voice_source="none",
            voice_id="",
            voice_provider_voice_id="",
            voice_profile_id=0,
            voice_label="",
        )
        return next_session, {"ok": True, "source": "none"}
    narration = video_b14_narration_source(session)
    if not narration.get("ok"):
        return session, narration
    resolved = video_b14_voice_resolution(source, profile)
    if not resolved.ok:
        return session, {
            "ok": False,
            "source": source,
            "reason": resolved.reason,
            "public_message": resolved.public_message or minimax_voice_adapter.PUBLIC_SAFE_VOICE_NOT_READY,
        }
    next_session = video_b14_set_addon_plan(
        user_id,
        session,
        voice_enabled=True,
        voice_source=source,
        voice_id=str(resolved.provider_voice_id or ""),
        voice_provider_voice_id=str(resolved.provider_voice_id or ""),
        voice_profile_id=int(resolved.profile_id or (profile or {}).get("id") or 0),
        voice_label=str(resolved.voice_label or video_b14_addon_label("voice", source)),
        narration_text=str(narration.get("text") or "")[:3500],
    )
    return next_session, {"ok": True, "source": source, "provider_voice_id": resolved.provider_voice_id, "narration_source": narration.get("source")}


