def audit_product_video_confirm_handler_registration(application) -> dict:
    callback_value = video_project_queue.PRODUCT_VIDEO_PUBLIC_CONFIRM_CALLBACK
    owners: list[dict] = []
    relevant_callbacks = {
        "handle_product_video_public_confirm_callback",
        "handle_video_product_callback",
    }
    for group, handlers in dict(getattr(application, "handlers", {}) or {}).items():
        for handler in handlers or []:
            if not isinstance(handler, CallbackQueryHandler):
                continue
            callback_name = str(getattr(getattr(handler, "callback", None), "__name__", "") or "")
            if callback_name not in relevant_callbacks:
                continue
            pattern_obj = getattr(handler, "pattern", None)
            pattern_text = str(getattr(pattern_obj, "pattern", pattern_obj) or "")
            try:
                matches = bool(re.match(pattern_text, callback_value)) if pattern_text else True
            except Exception:
                matches = False
            if matches:
                owners.append({"handler": callback_name, "pattern": pattern_text, "group": group})
    authoritative = [item for item in owners if item["handler"] == "handle_product_video_public_confirm_callback"]
    handler_ids = [video_project_queue.PRODUCT_VIDEO_PUBLIC_CONFIRM_HANDLER_ID for _item in authoritative]
    return {
        "product_video_confirm_handler_count": len(authoritative),
        "product_video_confirm_handler_ids": handler_ids,
        "matching_product_video_confirm_handlers": owners,
        "duplicate_confirm_handler_detected": len(authoritative) != 1,
        "duplicate_callback_pattern_detected": len(owners) != 1,
    }
try:
    VIDEO_PROVIDER_PREFLIGHT_TTL_SECONDS = max(30, int(os.getenv("VIDEO_PROVIDER_PREFLIGHT_TTL_SECONDS", "900") or 900))
except Exception:
    VIDEO_PROVIDER_PREFLIGHT_TTL_SECONDS = 900


def _video_provider_unavailable_reason_from_attempt(attempt: dict | None = None) -> str:
    item = dict(attempt or {})
    text = " ".join(
        str(item.get(key) or "")
        for key in (
            "blocker",
            "reason",
            "provider_submit_blocker",
            "provider_error",
            "provider_error_message_safe",
            "safe_error",
            "exception_message_safe",
        )
    ).lower()
    status = safe_int(item.get("submit_http_status") or item.get("provider_submit_http_status"), 0)
    if any(marker in text for marker in ("provider_capacity_unavailable", "get_channel_failed", "no available channel", "no channel")):
        return "provider_capacity_unavailable"
    if "provider_temporarily_unavailable" in text or status == 503:
        return "provider_temporarily_unavailable"
    if 500 <= status <= 599 or "provider_submit_http_5xx" in text:
        return "provider_submit_http_5xx"
    return ""


def _video_provider_preflight_recent_failure(conn, *, ttl_seconds: int = VIDEO_PROVIDER_PREFLIGHT_TTL_SECONDS) -> dict:
    try:
        rows = conn.execute(
            """SELECT j.id,j.result_json,j.updated_at,p.project_id,p.video_terminal_state,p.error_log
               FROM video_jobs j
               JOIN video_projects p ON p.project_id=j.project_id
               WHERE j.job_type=? AND j.status IN ('failed','completed')
               ORDER BY j.id DESC LIMIT 20""",
            (video_project_queue.VIDEO_RENDER_JOB_TYPE,),
        ).fetchall()
    except Exception as exc:
        return {"ok": True, "source": "skip", "reason": f"preflight_db_unavailable:{type(exc).__name__}"}
    now_dt = datetime.now()
    for row in rows:
        try:
            result = json.loads(str(row[1] or "{}"))
        except Exception:
            result = {}
        if not isinstance(result, dict):
            continue
        if not (
            str(result.get("blocker") or result.get("provider_error") or "").strip()
            in {"all_video_providers_submit_failed", "all_video_providers_submit_unavailable"}
            or bool(result.get("provider_fallback_attempted"))
        ):
            continue
        updated_raw = str(row[2] or "")
        if updated_raw:
            try:
                updated_dt = datetime.fromisoformat(updated_raw.replace("Z", "+00:00")[:19])
                if (now_dt - updated_dt.replace(tzinfo=None)).total_seconds() > max(30, int(ttl_seconds or 900)):
                    continue
            except Exception:
                pass
        chain = [
            str(item or "").strip()
            for item in (
                result.get("configured_provider_chain")
                or result.get("effective_provider_chain")
                or result.get("provider_chain")
                or []
            )
            if str(item or "").strip()
        ]
        attempts = result.get("provider_attempts") or result.get("provider_fallback_attempts") or result.get("fallback_provider_attempts") or []
        if not isinstance(attempts, list):
            attempts = []
        reason_by_provider: dict[str, str] = {}
        for attempt in attempts:
            if not isinstance(attempt, dict):
                continue
            provider = str(attempt.get("provider") or "").strip()
            reason = _video_provider_unavailable_reason_from_attempt(attempt)
            if provider and reason in {"provider_capacity_unavailable", "provider_temporarily_unavailable"}:
                reason_by_provider[provider] = reason
        if not chain:
            chain = list(reason_by_provider.keys())
        configured_chain = [provider for provider in chain if provider in reason_by_provider]
        if chain and configured_chain and len(configured_chain) >= len(chain):
            return {
                "ok": False,
                "provider_preflight_checked": True,
                "provider_preflight_source": "cache",
                "provider_preflight_result": "all_providers_unavailable",
                "unavailable_providers": configured_chain,
                "unavailable_reason_by_provider": reason_by_provider,
                "preflight_ttl_seconds": max(30, int(ttl_seconds or 900)),
                "job_creation_blocked_by_provider_availability": True,
                "no_charge_reason": "provider_preflight_all_unavailable",
                "source_job_id": safe_int(row[0], 0),
                "source_project_id": safe_int(row[3], 0),
            }
    return {
        "ok": True,
        "provider_preflight_checked": True,
        "provider_preflight_source": "cache",
        "provider_preflight_result": "no_recent_all_unavailable",
        "job_creation_blocked_by_provider_availability": False,
        "preflight_ttl_seconds": max(30, int(ttl_seconds or 900)),
    }


def _product_video_json_dict(value) -> dict:
    if isinstance(value, dict):
        return dict(value)
    try:
        parsed = json.loads(value or "{}")
        return dict(parsed) if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _product_video_provider_attempt_like(value: dict) -> bool:
    keys = {
        "provider",
        "selected_provider",
        "selected_provider_before_submit",
        "provider_pending_provider",
        "submit_provider_key",
        "provider_status",
        "provider_status_raw",
        "normalized_provider_status",
        "raw_status",
        "result_url",
        "provider_result_url",
        "download_url",
        "artifact_size",
        "artifact_bytes",
        "raw_video_bytes",
    }
    return bool(keys.intersection(value.keys()))


def _product_video_collect_provider_attempts_from_payload(payload: dict) -> list[dict]:
    attempts: list[dict] = []

    def visit(item, context: dict | None = None):
        context = dict(context or {})
        if isinstance(item, dict):
            next_context = dict(context)
            for key in (
                "job_id",
                "project_id",
                "updated_at",
                "created_at",
                "admission_mode",
                "probation_result",
                "final_delivered",
                "delivery_succeeded",
                "video_delivered",
                "delivery_message_id",
                "telegram_delivery_message_id",
                "video_delivery_message_id",
                "success_message_id",
                "scene_coverage_expected",
                "scene_coverage_count",
                "scene_clip_coverage_complete",
                "scenes_total",
                "scenes_done",
                "final_mp4_valid",
                "final_mp4_validated",
                "artifact_valid_for_charge",
                "output_bytes",
            ):
                if item.get(key) not in (None, ""):
                    next_context[key] = item.get(key)
            if _product_video_provider_attempt_like(item):
                attempt = dict(item)
                for key in (
                    "job_id",
                    "project_id",
                    "updated_at",
                    "created_at",
                    "admission_mode",
                    "probation_result",
                    "final_delivered",
                    "delivery_succeeded",
                    "video_delivered",
                    "delivery_message_id",
                    "telegram_delivery_message_id",
                    "video_delivery_message_id",
                    "success_message_id",
                    "scene_coverage_expected",
                    "scene_coverage_count",
                    "scene_clip_coverage_complete",
                    "scenes_total",
                    "scenes_done",
                    "final_mp4_valid",
                    "final_mp4_validated",
                    "artifact_valid_for_charge",
                    "output_bytes",
                ):
                    if attempt.get(key) in (None, "") and next_context.get(key) not in (None, ""):
                        attempt[key] = next_context.get(key)
                attempts.append(attempt)
            for child in item.values():
                if isinstance(child, (dict, list, tuple)):
                    visit(child, next_context)
        elif isinstance(item, (list, tuple)):
            for child in item:
                visit(child, context)

    visit(dict(payload or {}))
    return attempts


def _product_video_recent_provider_attempt_evidence(conn, *, limit: int = 24) -> list[dict]:
    attempts: list[dict] = []
    try:
        rows = conn.execute(
            """
            SELECT j.id, j.project_id, j.status, j.progress_percent, j.result_json, j.updated_at,
                   p.asset_pack_json, p.invoice_json
              FROM video_jobs j
              LEFT JOIN video_projects p ON p.project_id = j.project_id
             WHERE j.job_type='video_render'
             ORDER BY COALESCE(j.updated_at, j.created_at) DESC, j.id DESC
             LIMIT ?
            """,
            (max(1, int(limit or 24)),),
        ).fetchall()
    except Exception:
        return attempts
    for row in rows:
        job_id, project_id, status, progress, result_json, updated_at, asset_json, invoice_json = row
        result_payload = _product_video_json_dict(result_json)
        asset_pack = _product_video_json_dict(asset_json)
        invoice = _product_video_json_dict(invoice_json)
        product_source = str(
            result_payload.get("source")
            or asset_pack.get("source")
            or invoice.get("source")
            or ""
        ).strip()
        if product_source and product_source != "product_video":
            continue
        root = {
            **result_payload,
            "job_id": safe_int(job_id, 0),
            "project_id": safe_int(project_id, 0),
            "job_status": str(status or ""),
            "progress_percent": safe_int(progress, 0),
            "updated_at": str(updated_at or ""),
        }
        attempts.extend(_product_video_collect_provider_attempts_from_payload(root))
    return attempts


