def _product_video_contract_valid_provider_chain(
    chain: list[str] | tuple[str, ...],
    *,
    scene_count: int = 1,
) -> tuple[list[str], list[dict]]:
    valid: list[str] = []
    invalid: list[dict] = []
    for provider in [str(item or "").strip() for item in (chain or []) if str(item or "").strip()]:
        try:
            resolution = video_provider_catalog.resolve_product_video_model(
                tier=300,
                provider_chain=[provider],
                scene_count=max(1, safe_int(scene_count, 1)),
                required_capability="text_to_video_or_scene_video",
                requires_concat=True,
            )
        except Exception as exc:
            invalid.append({"provider": provider, "reason": f"model_contract_check_error:{type(exc).__name__}"})
            continue
        if resolution.get("ok"):
            valid.append(provider)
        else:
            invalid.append(
                {
                    "provider": provider,
                    "reason": str(
                        resolution.get("blocker")
                        or resolution.get("model_routing_blocker")
                        or resolution.get("contract_validation_status")
                        or "provider_contract_invalid"
                    ),
                }
            )
    return valid, invalid


def product_video_provider_freeze_admission_snapshot(
    chain,
    *,
    explicit_public_final_confirm: bool = False,
    source: str = "public_preflight",
    job_context: dict | None = None,
) -> dict:
    """Collect runtime inputs once and delegate Product Video freeze truth."""
    configured_chain = [
        str(provider or "").strip()
        for provider in (chain or [])
        if str(provider or "").strip()
    ]
    ops = current_system_mode()
    public_maintenance = bool(
        product_video_public_maintenance_enabled()
        or ops.get("maintenance_mode")
    )
    provider_displays: dict[str, dict] = {}
    for provider in configured_chain:
        freeze_key = "key4u" if provider == "key4u_video" else provider
        provider_displays[provider] = provider_freeze_display(freeze_key)
    runtime_public_provider_freeze = bool(
        flag_on("public_provider_freeze")
        or flag_on("product_video_public_provider_freeze")
    )
    truth_context = dict(job_context or {})
    truth_context.update(
        {
            "explicit_public_provider_freeze": runtime_public_provider_freeze,
            "runtime_public_provider_freeze": runtime_public_provider_freeze,
            "public_provider_freeze_source": (
                "runtime:public_provider_freeze"
                if runtime_public_provider_freeze
                else ""
            ),
            "provider_freeze": bool(
                PROVIDER_FREEZE
                or PROVIDER_FREEZE_ENABLED
                or ops.get("provider_freeze")
            ),
            "provider_freeze_enabled": bool(PROVIDER_FREEZE_ENABLED),
            "provider_spend_freeze": bool(PROVIDER_SPEND_FREEZE),
            "hidden_video_freeze": any(
                bool(item.get("frozen")) for item in provider_displays.values()
            ),
            "public_maintenance": public_maintenance,
            "product_video_public_maintenance": public_maintenance,
            "payment_freeze": bool(ops.get("payment_freeze")),
            "tool_freeze": bool(ops.get("tool_freeze")),
            "security_block": bool(ops.get("emergency_lock")),
        }
    )
    freeze_truth = video_provider_router.product_video_freeze_truth(
        source=(
            video_provider_router.PRODUCT_VIDEO_SUBMIT_SOURCE_PUBLIC_FINAL_CONFIRM
            if explicit_public_final_confirm
            else source
        ),
        job_context=truth_context,
    )
    policies: dict[str, dict] = {}
    hard_blocks: dict[str, str] = {}
    for provider in configured_chain:
        display = provider_displays.get(provider) or {}
        policy = video_provider_router.product_video_provider_freeze_probation_policy(
            provider=provider,
            provider_frozen=bool(display.get("frozen")),
            provider_freeze_reason=str(display.get("reason") or ""),
            explicit_public_final_confirm=explicit_public_final_confirm,
            public_provider_freeze=bool(freeze_truth.get("public_provider_freeze")),
            public_maintenance=bool(freeze_truth.get("public_maintenance")),
            payment_freeze=bool(freeze_truth.get("payment_freeze")),
            tool_freeze=bool(freeze_truth.get("tool_freeze")),
            security_block=bool(freeze_truth.get("security_block")),
            cost_lock=bool(freeze_truth.get("hard_public_cost_block")),
        )
        policies[provider] = policy
        if policy.get("hard_block_reason"):
            hard_blocks[provider] = str(policy["hard_block_reason"])
    global_hard_block_reason = str(freeze_truth.get("public_blocker_code") or "")
    return {
        **freeze_truth,
        "freeze_truth": dict(freeze_truth),
        "public_provider_freeze": bool(freeze_truth.get("public_provider_freeze")),
        "hidden_submit_freeze": bool(freeze_truth.get("hidden_submit_freeze")),
        "hidden_video_freeze": bool(freeze_truth.get("hidden_video_freeze")),
        "operational_health_state": {
            provider: str(item.get("operational_health_state") or "normal")
            for provider, item in policies.items()
        },
        "provider_freeze_display_by_provider": provider_displays,
        "provider_freeze_policy_by_provider": policies,
        "hard_block_reason_by_provider": hard_blocks,
        "global_hard_block_reason": global_hard_block_reason,
    }


def product_video_provider_public_route_preflight(
    conn=None,
    *,
    scene_count: int = 1,
    allow_public_confirmed_probation: bool = False,
    admission_source: str = "",
    public_user_confirmed: bool = False,
    current_probation_job_id: int = 0,
    recent_failure: dict | None = None,
) -> dict:
    owned_conn = None
    if conn is None:
        try:
            owned_conn = db_connect()
            conn = owned_conn
        except Exception:
            conn = None
    attempts = _product_video_recent_provider_attempt_evidence(conn)
    status = _product_video_provider_status_for_preflight()
    chain = status.get("effective_provider_chain") or status.get("provider_chain") or []
    provider_items = {
        str(item.get("provider") or "").strip(): dict(item)
        for item in (status.get("providers") or [])
        if isinstance(item, dict) and str(item.get("provider") or "").strip()
    }
    degraded_providers = {
        str(provider): video_provider_router.product_video_provider_public_degradation(
            str(provider),
            attempts,
            route_ready=bool(
                provider_items.get(str(provider), {}).get("configured")
                and provider_items.get(str(provider), {}).get("credit_ok", True)
            ),
        )
        for provider in chain
        if str(provider or "").strip()
    }
    shopaikey_degradation = degraded_providers.get("shopaikey_video") or video_provider_router.product_video_provider_public_degradation(
        "shopaikey_video", attempts
    )
    key4u_degradation = degraded_providers.get("key4u_video") or video_provider_router.product_video_provider_public_degradation(
        "key4u_video", attempts
    )
    decision = video_provider_router.product_video_public_provider_route_decision(
        status=status,
        chain=chain,
        degraded_providers=degraded_providers,
    )
    count = max(1, safe_int(scene_count, 1))
    explicit_public_final_confirm = bool(
        allow_public_confirmed_probation
        and public_user_confirmed
        and video_provider_router.normalize_product_video_submit_source(admission_source)
        == video_provider_router.PRODUCT_VIDEO_SUBMIT_SOURCE_PUBLIC_FINAL_CONFIRM
    )
    contract_valid_chain, contract_invalid_providers = _product_video_contract_valid_provider_chain(chain, scene_count=count)
    submit_switch = video_provider_router.product_video_submit_switch_detail()
    public_submit_enabled = bool(submit_switch.get("resolved"))
    public_submit_switch_blocker = (
        "" if public_submit_enabled else "public_provider_submit_disabled"
    )
    public_maintenance = product_video_public_maintenance_enabled()
    worker = product_video_worker_admission_status()
    worker_compatible = bool(
        worker.get("worker_version_compatible")
        and worker.get("worker_connected")
        and worker.get("heartbeat_fresh")
        and worker.get("lease_valid")
        and worker.get("sha_match")
        and worker.get("capability_match")
        and not worker.get("worker_identity_conflict")
    )
    worker_incompatible_blocker = (
        ""
        if worker_compatible
        else str(worker.get("worker_admission_block_reason") or "worker_incompatible")
    )
    worker_available = bool(
        worker.get("worker_connected")
        and worker.get("heartbeat_fresh")
        and worker.get("lease_valid")
    )
    provider_configured = bool(
        contract_valid_chain
        and (
            not provider_items
            or any(
                provider in contract_valid_chain
                and bool(provider_items.get(provider, {}).get("configured"))
                for provider in chain
            )
        )
    )
    freeze_admission = product_video_provider_freeze_admission_snapshot(
        chain,
        explicit_public_final_confirm=explicit_public_final_confirm,
        source=(
            video_provider_router.PRODUCT_VIDEO_SUBMIT_SOURCE_PUBLIC_FINAL_CONFIRM
            if explicit_public_final_confirm
            else "public_preflight"
        ),
        job_context={
            "public_submit_enabled": public_submit_enabled,
            "provider_configured": provider_configured,
            "worker_available": worker_available,
            "worker_compatible": worker_compatible,
        },
    )
    try:
        probation_lock = video_project_queue.product_video_probation_lock_state(conn) if conn is not None else {
            "probation_lock_clear": False,
            "probation_lock_status": "unknown",
        }
    except Exception as exc:
        probation_lock = {
            "probation_lock_clear": False,
            "probation_lock_status": "unknown",
            "probation_lock_error": type(exc).__name__,
        }
    active_probation_job_id = safe_int(probation_lock.get("active_probation_job_id"), 0)
    probation_lock_owned_by_current_job = bool(
        safe_int(current_probation_job_id, 0) > 0
        and active_probation_job_id == safe_int(current_probation_job_id, 0)
    )
    probation_lock_clear_for_request = bool(
        probation_lock.get("probation_lock_clear")
        or probation_lock_owned_by_current_job
    )
    recent_failure = dict(recent_failure or {})
    stale_cooldown_ignored_for_public_preflight = bool(
        recent_failure and not explicit_public_final_confirm
    )
    hard_block_reason = str(freeze_admission.get("global_hard_block_reason") or "")
    provider_hard_blocks = dict(freeze_admission.get("hard_block_reason_by_provider") or {})
    eligibility_snapshot = video_provider_router.product_video_provider_eligibility_snapshot(
        status=status,
        chain=chain,
        provider_health=degraded_providers,
        contract_valid_provider_chain=contract_valid_chain,
        scene_count=count,
        require_live_health=True,
        allow_public_confirmed_probation=allow_public_confirmed_probation,
        allow_operational_degradation_probation=True,
        admission_source=admission_source,
        public_user_confirmed=public_user_confirmed,
        public_submit_enabled=bool(
            public_submit_enabled
            and freeze_admission.get("public_live_allowed")
        ),
        worker_compatible=worker_compatible,
        probation_lock_clear=probation_lock_clear_for_request,
        hard_block_reason_by_provider=provider_hard_blocks,
        global_hard_block_reason=hard_block_reason,
    )
    selected_chain = list(eligibility_snapshot.get("eligible_provider_keys") or [])
    final_ok = bool(selected_chain)
    final_selected_provider = selected_chain[0] if selected_chain else ""
    eligibility_state = str(eligibility_snapshot.get("eligibility_state") or "blocked")
    preflight_ready_for_final_confirm = bool(
        final_ok
        or (
            eligibility_state == "probation"
            and eligibility_snapshot.get("probation_candidate_keys")
            and public_submit_enabled
            and not public_maintenance
            and worker_compatible
            and probation_lock_clear_for_request
            and not hard_block_reason
            and freeze_admission.get("public_final_confirm_allowed")
        )
    )
    if not final_ok and contract_invalid_providers:
        decision = {
            **decision,
            "ok": False,
            "selected_provider": "",
            "blocker": "no_healthy_video_provider_no_charge",
            "contract_invalid_providers": contract_invalid_providers,
        }
    result = {
        **decision,
        **eligibility_snapshot,
        "provider_preflight_checked": True,
        "stale_cooldown_ignored_for_public_preflight": stale_cooldown_ignored_for_public_preflight,
        "provider_preflight_source": "provider_status_and_recent_jobs",
        "provider_preflight_result": (
            "provider_route_ready"
            if final_ok
            else ("provider_probation_ready" if preflight_ready_for_final_confirm else "no_real_mp4_provider_available")
        ),
        "provider_status_checked": True,
        "shopaikey_public_degradation": shopaikey_degradation,
        "key4u_public_degradation": key4u_degradation,
        "provider_health_summary": degraded_providers,
        "provider_health_at_submit": degraded_providers,
        "provider_status_snapshot": status,
        "provider_eligibility_snapshot": eligibility_snapshot,
        "provider_degraded_reason": ";".join(
            str(item.get("degrade_reason") or "")
            for item in degraded_providers.values()
            if item.get("provider_degraded_for_product_video_public") and str(item.get("degrade_reason") or "")
        ),
        "primary_selected_due_to_health": str(decision.get("primary_selected_due_to_health") or ""),
        "effective_primary_for_low_basic": str(decision.get("effective_primary_for_low_basic") or decision.get("selected_provider") or ""),
        "configured_provider_chain": list(decision.get("provider_chain") or chain or []),
        "contract_valid_provider_chain": contract_valid_chain,
        "contract_invalid_providers": contract_invalid_providers,
        "effective_provider_chain": selected_chain,
        "route_ready_provider_chain": list(decision.get("route_ready_provider_order") or []),
        "live_healthy_provider_chain": list(decision.get("live_healthy_provider_order") or []),
        "selected_provider": final_selected_provider,
        "scene_count": count,
        "preflight_ready_for_final_confirm": preflight_ready_for_final_confirm,
        "public_submit_enabled": public_submit_enabled,
        "public_submit_switch_blocker": public_submit_switch_blocker,
        "public_maintenance": bool(freeze_admission.get("public_maintenance")),
        "worker_compatible": worker_compatible,
        "worker_incompatible_blocker": worker_incompatible_blocker,
        "worker_admission_block_reason": str(worker.get("worker_admission_block_reason") or ""),
        "provider_hard_block_reason": str(eligibility_snapshot.get("hard_block_reason") or hard_block_reason),
        "global_hard_block_reason": hard_block_reason,
        "provider_hard_block_reason_by_provider": provider_hard_blocks,
        "freeze_truth": dict(freeze_admission.get("freeze_truth") or freeze_admission),
        "provider_freeze": bool(freeze_admission.get("provider_freeze")),
        "public_provider_freeze": bool(freeze_admission.get("public_provider_freeze")),
        "hidden_submit_freeze": bool(freeze_admission.get("hidden_submit_freeze")),
        "hidden_video_freeze": bool(freeze_admission.get("hidden_video_freeze")),
        "background_submit_freeze": bool(freeze_admission.get("background_submit_freeze")),
        "smoke_freeze": bool(freeze_admission.get("smoke_freeze")),
        "public_live_provider_allowed": bool(freeze_admission.get("public_live_allowed")),
        "public_preflight_allowed": bool(freeze_admission.get("public_preflight_allowed")),
        "public_final_confirm_allowed": bool(freeze_admission.get("public_final_confirm_allowed")),
        "freeze_blocker_code": str(freeze_admission.get("blocker_code") or ""),
        "freeze_blocker_source": str(freeze_admission.get("blocker_source") or ""),
        "operational_health_state": dict(freeze_admission.get("operational_health_state") or {}),
        "provider_freeze_policy_by_provider": dict(freeze_admission.get("provider_freeze_policy_by_provider") or {}),
        "probation_lock": probation_lock,
        **probation_lock,
        "probation_lock_clear": probation_lock_clear_for_request,
        "probation_lock_owned_by_current_job": probation_lock_owned_by_current_job,
        "probation_current_job_id": safe_int(current_probation_job_id, 0),
        "probation_eligible": bool(eligibility_snapshot.get("probation_candidate_keys")),
        "probation_reject_reason": str(
            eligibility_snapshot.get("probation_reject_reason")
            or eligibility_snapshot.get("hard_block_reason")
            or ""
        ),
        "probation_candidate": str(eligibility_snapshot.get("probation_candidate_selected") or ""),
        "router_called": False,
        "router_skip_reason": "" if final_ok else str(eligibility_snapshot.get("blocker") or hard_block_reason or "no_eligible_product_video_provider"),
        "submit_allowed": final_ok,
        "submit_block_reason": "" if final_ok else str(eligibility_snapshot.get("blocker") or hard_block_reason or "no_eligible_product_video_provider"),
        "job_creation_blocked_by_provider_availability": not final_ok,
        "no_charge_reason": "" if final_ok else "no_healthy_video_provider_no_charge",
        "legacy_no_charge_reason": "" if final_ok else "product_video_no_public_mp4_provider",
        "preflight_ttl_seconds": max(30, safe_int(os.getenv("PRODUCT_VIDEO_PROVIDER_PREFLIGHT_TTL_SECONDS"), 900)),
        "public_message": "" if final_ok else PRODUCT_VIDEO_PROVIDER_BUSY_COPY_VI,
    }
    if owned_conn is not None:
        owned_conn.close()
    return result


def product_video_multi_scene_health_gate(
    scene_count: int,
    preflight: dict | None = None,
    *,
    allow_public_confirmed_probation: bool = False,
    admission_source: str = "",
    public_user_confirmed: bool = False,
) -> dict:
    preflight = dict(preflight or {})
    count = max(1, safe_int(scene_count, 1))
    configured = [
        str(item or "").strip()
        for item in (preflight.get("configured_provider_chain") or preflight.get("effective_provider_chain") or [])
        if str(item or "").strip()
    ]
    contract_valid, contract_invalid = _product_video_contract_valid_provider_chain(
        configured,
        scene_count=count,
    )
    eligibility_snapshot = dict(preflight.get("provider_eligibility_snapshot") or {})
    explicit_public_final_confirm = bool(
        allow_public_confirmed_probation
        and public_user_confirmed
        and video_provider_router.normalize_product_video_submit_source(admission_source)
        == video_provider_router.PRODUCT_VIDEO_SUBMIT_SOURCE_PUBLIC_FINAL_CONFIRM
    )
    if safe_int(eligibility_snapshot.get("scene_count"), 0) != count or explicit_public_final_confirm:
        freeze_admission = dict(preflight.get("freeze_truth") or {})
        if not freeze_admission:
            freeze_admission = product_video_provider_freeze_admission_snapshot(
                configured,
                explicit_public_final_confirm=explicit_public_final_confirm,
                source=(
                    video_provider_router.PRODUCT_VIDEO_SUBMIT_SOURCE_PUBLIC_FINAL_CONFIRM
                    if explicit_public_final_confirm
                    else "public_preflight"
                ),
                job_context={
                    "public_submit_enabled": bool(preflight.get("public_submit_enabled")),
                    "provider_configured": bool(configured),
                    "worker_available": bool(preflight.get("worker_compatible")),
                    "worker_compatible": bool(preflight.get("worker_compatible")),
                },
            )
        eligibility_snapshot = video_provider_router.product_video_provider_eligibility_snapshot(
            status=preflight.get("provider_status_snapshot") if isinstance(preflight.get("provider_status_snapshot"), dict) else {},
            chain=configured,
            provider_health=preflight.get("provider_health_summary") if isinstance(preflight.get("provider_health_summary"), dict) else {},
            contract_valid_provider_chain=contract_valid,
            scene_count=count,
            require_live_health=True,
            allow_public_confirmed_probation=allow_public_confirmed_probation,
            allow_operational_degradation_probation=True,
            admission_source=admission_source,
            public_user_confirmed=public_user_confirmed,
            public_submit_enabled=bool(
                preflight.get("public_submit_enabled")
                and freeze_admission.get("public_live_allowed", True)
            ),
            worker_compatible=bool(preflight.get("worker_compatible")),
            probation_lock_clear=bool(preflight.get("probation_lock_clear")),
            hard_block_reason_by_provider=dict(freeze_admission.get("hard_block_reason_by_provider") or {}),
            global_hard_block_reason=str(
                freeze_admission.get("global_hard_block_reason")
                or preflight.get("global_hard_block_reason")
                or ""
            ),
        )
    effective = list(eligibility_snapshot.get("eligible_provider_keys") or [])
    result = video_provider_router.product_video_multi_scene_public_gate(
        count,
        preflight.get("provider_health_summary") if isinstance(preflight.get("provider_health_summary"), dict) else {},
        effective_provider_chain=effective,
        contract_valid_provider_chain=contract_valid,
        eligibility_snapshot=eligibility_snapshot,
        public_user_final_confirm=explicit_public_final_confirm,
    )
    ready_for_confirm = bool(
        result.get("ok")
        or (
            eligibility_snapshot.get("eligibility_state") == "probation"
            and eligibility_snapshot.get("probation_candidate_keys")
            and not (count > 1 and result.get("blocker") == "product_video_multi_scene_public_disabled")
            and preflight.get("probation_lock_clear")
            and preflight.get("worker_compatible")
            and preflight.get("public_submit_enabled")
            and not preflight.get("public_maintenance")
            and preflight.get("public_final_confirm_allowed", True)
        )
    )
    return {
        **eligibility_snapshot,
        **result,
        "provider_eligibility_snapshot": eligibility_snapshot,
        "contract_invalid_providers": contract_invalid,
        "preflight_ready_for_final_confirm": ready_for_confirm,
        "public_message": "" if result.get("ok") else PRODUCT_VIDEO_MULTI_SCENE_PROVIDER_BUSY_COPY_VI,
    }


def product_video_provider_availability_preflight(
    conn=None,
    *,
    scene_count: int = 1,
    allow_public_confirmed_probation: bool = False,
    admission_source: str = "",
    public_user_confirmed: bool = False,
    current_probation_job_id: int = 0,
) -> dict:
    owned = conn is None
    db = conn or db_connect()
    try:
        result = _video_provider_preflight_recent_failure(db)
        route_result = product_video_provider_public_route_preflight(
            db,
            scene_count=scene_count,
            allow_public_confirmed_probation=allow_public_confirmed_probation,
            admission_source=admission_source,
            public_user_confirmed=public_user_confirmed,
            current_probation_job_id=current_probation_job_id,
            recent_failure=result,
        )
        return {
            **result,
            **route_result,
            "provider_preflight_result": route_result.get("provider_preflight_result") or result.get("provider_preflight_result"),
            "job_creation_blocked_by_provider_availability": not bool(route_result.get("ok")),
        }
    finally:
        if owned:
            db.close()


PRODUCT_VIDEO_PREFLIGHT_UI_TTL_SECONDS = 900


def product_video_public_preflight_evaluation(
    scene_count: int,
    *,
    explicit_public_final_confirm: bool = False,
    preflight_snapshot: dict | None = None,
) -> dict:
    """Read admission truth only; this function never creates or submits a job."""
    count = max(1, safe_int(scene_count, 1))
    source = "public_user_final_confirm" if explicit_public_final_confirm else ""
    try:
        preflight = (
            dict(preflight_snapshot)
            if preflight_snapshot is not None
            else product_video_provider_availability_preflight(
                scene_count=count,
                allow_public_confirmed_probation=explicit_public_final_confirm,
                admission_source=source,
                public_user_confirmed=explicit_public_final_confirm,
            )
        )
        scene_gate = product_video_multi_scene_health_gate(
            count,
            preflight,
            allow_public_confirmed_probation=explicit_public_final_confirm,
            admission_source=source,
            public_user_confirmed=explicit_public_final_confirm,
        )
        resolution = video_provider_router.resolve_product_video_public_preflight_state(
            preflight,
            scene_gate,
        )
    except Exception as exc:
        preflight = {}
        scene_gate = {}
        resolution = video_provider_router.resolve_product_video_public_preflight_state(
            {},
            {},
            internal_error=f"preflight_evaluation_error:{type(exc).__name__}",
        )
    ready = bool(resolution.get("final_confirm_enabled"))
    return {
        "ready": ready,
        "scene_count": count,
        "preflight": preflight,
        "scene_gate": scene_gate,
        "admission_mode": str(resolution.get("selected_admission_mode") or "blocked"),
        **resolution,
    }


def product_video_public_preflight_public_kind(resolved_state: str) -> str:
    return {
        "ready_healthy": "ready",
        "ready_probation": "ready_try",
        "expired_context": "expired",
        "internal_error": "error",
    }.get(str(resolved_state or "").strip().lower(), "blocked")


def product_video_public_preflight_default_state(ready) -> str:
    return "ready_healthy" if bool(ready) else "blocked_provider"


def product_video_public_preflight_panel_text(
    scene_count: int,
    *,
    resolved_state: str = "",
    ready=None,
    total_xu: int = 0,
) -> str:
    count = max(1, safe_int(scene_count, 1))
    if not resolved_state:
        resolved_state = product_video_public_preflight_default_state(ready)
    panel_kind = product_video_public_preflight_public_kind(resolved_state)
    if panel_kind == "ready":
        return (
            "🎬 <b>Trạng thái tạo video</b>\n\n"
            "✅ <b>Hệ thống đã sẵn sàng</b>\n\n"
            f"• Số cảnh đã chọn: <b>{count}</b>\n"
            "• Hệ thống dựng video: Sẵn sàng\n"
            "• Khả năng tạo nhiều cảnh: Sẵn sàng\n"
            "• Hệ thống chỉ bắt đầu sau khi anh/chị xác nhận."
        )
    if panel_kind == "ready_try":
        return (
            "🎬 <b>Trạng thái tạo video</b>\n\n"
            "✅ <b>Có thể bắt đầu thử tạo</b>\n\n"
            f"• Số cảnh đã chọn: <b>{count}</b>\n"
            "• Hệ thống dựng video: Sẵn sàng thử\n"
            "• Hệ thống chỉ bắt đầu sau khi anh/chị xác nhận.\n"
            "• Hệ thống chưa trừ Xu."
        )
    if panel_kind == "expired":
        return (
            "🎬 <b>Trạng thái tạo video</b>\n\n"
            "⚠️ <b>Phiên kiểm tra đã hết hạn</b>\n\n"
            f"• Số cảnh đã chọn: <b>{count}</b>\n"
            "• Hệ thống chưa trừ Xu.\n\n"
            "Anh/chị vui lòng quay lại chọn số cảnh."
        )
    if panel_kind == "error":
        return (
            "🎬 <b>Trạng thái tạo video</b>\n\n"
            "⚠️ <b>Chưa thể đọc trạng thái lúc này</b>\n\n"
            f"• Số cảnh đã chọn: <b>{count}</b>\n"
            "• Hệ thống chưa trừ Xu.\n\n"
            "Anh/chị có thể kiểm tra lại sau."
        )
    return (
        "🎬 <b>Trạng thái tạo video</b>\n\n"
        "⚠️ <b>Chưa thể bắt đầu</b>\n\n"
        f"• Số cảnh đã chọn: <b>{count}</b>\n"
        "• Hệ thống dựng video: Tạm thời chưa sẵn sàng\n"
        "• Hệ thống chưa trừ Xu.\n\n"
        "Anh/chị có thể kiểm tra lại sau."
    )


def product_video_public_preflight_panel_keyboard(
    lang: str = "vi",
    *,
    resolved_state: str = "",
    ready=None,
    back_callback: str = "vproduct|b14_scene_count_screen",
) -> InlineKeyboardMarkup:
    if not resolved_state:
        resolved_state = "ready_healthy" if bool(ready) else "blocked_provider"
    panel_kind = product_video_public_preflight_public_kind(resolved_state)
    rows = []
    if panel_kind == "ready":
        rows.append([InlineKeyboardButton("✅ Xác nhận tạo video", callback_data="vproduct|b14_confirm"), InlineKeyboardButton("🧾 Xem lại hóa đơn", callback_data="vproduct|b14_invoice_screen")])
    elif panel_kind == "ready_try":
        rows.append([InlineKeyboardButton("✅ Xác nhận tạo video", callback_data="vproduct|b14_confirm"), InlineKeyboardButton("🔄 Kiểm tra lại", callback_data="vproduct|b14_preflight_refresh")])
    elif panel_kind in {"blocked", "error"}:
        rows.append([InlineKeyboardButton("🔄 Kiểm tra lại", callback_data="vproduct|b14_preflight_refresh"), InlineKeyboardButton("📖 Xem hướng dẫn", callback_data="menu|guide_video_ai")])
    rows.append([
        InlineKeyboardButton(ui_text(lang, "common.back"), callback_data=back_callback),
        InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"),
    ])
    return InlineKeyboardMarkup(rows)


def product_video_store_public_preflight_context(user_id: int, session: dict, query, scene_count: int) -> dict:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    now_ts = time.time()
    message = getattr(query, "message", None) or query
    message_id = safe_int(getattr(message, "message_id", 0), 0)
    previous = draft.get("b14_preflight_ui_context") if isinstance(draft.get("b14_preflight_ui_context"), dict) else {}
    created_at = float(previous.get("created_at") or now_ts)
    draft.pop("b14_provider_preflight", None)
    draft["b14_preflight_ui_context"] = {
        "user_id": int(user_id),
        "project_draft_reference": safe_int(draft.get("b14_project_id"), 0),
        "selected_scene_count": max(1, safe_int(scene_count, 1)),
        "preflight_message_id": message_id,
        "created_at": created_at,
        "expires_at": now_ts + PRODUCT_VIDEO_PREFLIGHT_UI_TTL_SECONDS,
    }
    draft["provider_called"] = False
    draft["xu_charged"] = 0
    session["draft"] = draft
    return save_video_session(user_id, session)


async def product_video_show_public_preflight_panel(
    query,
    user_id: int,
    session: dict,
    lang: str,
    scene_count: int,
    *,
    evaluation: dict | None = None,
):
    evaluation = dict(evaluation or product_video_public_preflight_evaluation(scene_count))
    resolved_state = str(evaluation.get("preflight_resolved_state") or "internal_error")
    draft = dict((session or {}).get("draft") or {})
    back_callback = (
        "vproduct|b14_invoice_screen"
        if safe_int(draft.get("b14_project_id"), 0) > 0
        else "vproduct|b14_scene_count_screen"
    )
    product_video_store_public_preflight_context(user_id, session, query, scene_count)
    return await safe_edit_or_send(
        query,
        product_video_public_preflight_panel_text(
            scene_count,
            resolved_state=resolved_state,
        ),
        parse_mode="HTML",
        reply_markup=product_video_public_preflight_panel_keyboard(
            lang,
            resolved_state=resolved_state,
            back_callback=back_callback,
        ),
    )


def product_video_bot_watchdog_eligibility(job: dict, result: dict, project: dict) -> dict:
    result = dict(result or {})
    project = dict(project or {})
    submit_switch = video_provider_router.product_video_submit_switch_detail()
    submit_policy = video_provider_router.product_video_provider_submit_source_policy(
        result,
        public_submit_enabled=bool(submit_switch.get("resolved")),
        poll_existing_task=False,
    )
    explicit_public_final_confirm = bool(
        submit_policy.get("provider_submit_allowed")
        and submit_policy.get("public_user_confirmed")
        and submit_policy.get("submit_source")
        == video_provider_router.PRODUCT_VIDEO_SUBMIT_SOURCE_PUBLIC_FINAL_CONFIRM
    )
    explicit_zero_at_creation = bool(
        ("admission_candidate_count" in result and safe_int(result.get("admission_candidate_count"), 0) <= 0)
        or (
            "provider_candidates_count" in result
            and safe_int(result.get("provider_candidates_count"), 0) <= 0
            and not result.get("provider_router_called")
        )
    )
    runtime_sha_at_creation = str(
        result.get("admission_worker_runtime_sha") or result.get("runtime_sha_at_creation") or ""
    ).strip()
    worker_sha_at_creation = str(
        result.get("admission_worker_sha") or result.get("worker_sha_at_creation") or ""
    ).strip()
    worker_mismatch_at_creation = bool(
        runtime_sha_at_creation
        and worker_sha_at_creation
        and not (
            runtime_sha_at_creation.startswith(worker_sha_at_creation)
            or worker_sha_at_creation.startswith(runtime_sha_at_creation)
        )
    )
    if worker_mismatch_at_creation or (
        explicit_zero_at_creation and not explicit_public_final_confirm
    ):
        reason = (
            "worker_version_mismatch_before_dispatch"
            if worker_mismatch_at_creation
            else "admission_bypassed_no_eligible_provider"
        )
        return {
            "eligible_provider_keys": [],
            "runtime_candidate_keys": [],
            "final_eligible_provider_count": 0,
            "reconciliation_reason": reason,
            "worker_admission_block_reason": reason,
            "admission_block_reason": reason,
            "no_provider_call_verified": True,
            "no_charge_verified": safe_int(result.get("charged_xu") or result.get("charge"), 0) == 0,
        }
    scene_count = max(1, safe_int(project.get("scene_count") or result.get("scene_count"), 1))
    preflight = product_video_provider_availability_preflight(
        scene_count=scene_count,
        allow_public_confirmed_probation=explicit_public_final_confirm,
        admission_source=str(submit_policy.get("submit_source") or ""),
        public_user_confirmed=bool(submit_policy.get("public_user_confirmed")),
        current_probation_job_id=safe_int(job.get("id"), 0),
    )
    scene_gate = product_video_multi_scene_health_gate(
        scene_count,
        preflight,
        allow_public_confirmed_probation=explicit_public_final_confirm,
        admission_source=str(submit_policy.get("submit_source") or ""),
        public_user_confirmed=bool(submit_policy.get("public_user_confirmed")),
    )
    worker = product_video_worker_admission_status()
    candidates = [
        str(item or "").strip()
        for item in (scene_gate.get("eligible_provider_keys") or scene_gate.get("runtime_candidate_keys") or [])
        if str(item or "").strip()
    ]
    if not worker.get("worker_version_compatible"):
        candidates = []
    reason = "" if candidates else str(
        worker.get("worker_admission_block_reason")
        or scene_gate.get("blocker")
        or preflight.get("blocker")
        or "no_eligible_provider_before_scene_dispatch"
    )
    return {
        **scene_gate,
        "eligible_provider_keys": candidates,
        "runtime_candidate_keys": candidates,
        "final_eligible_provider_count": len(candidates),
        "reconciliation_reason": reason,
        "worker_admission_block_reason": str(worker.get("worker_admission_block_reason") or ""),
        "admission_block_reason": reason,
        "candidate_resolver_source": str(submit_policy.get("submit_source") or ""),
        "candidate_resolver_public_user_confirmed": bool(submit_policy.get("public_user_confirmed")),
        "provider_submit_allowed": bool(candidates and submit_policy.get("provider_submit_allowed")),
        "provider_submit_block_reason": "" if candidates else str(
            submit_policy.get("provider_submit_block_reason")
            or reason
            or "no_eligible_provider_before_scene_dispatch"
        ),
        "router_skip_reason": "" if candidates else str(
            reason or "no_eligible_provider_before_scene_dispatch"
        ),
    }


def run_product_video_bot_side_zero_task_watchdog(
    job_id: int | str,
    *,
    reconciliation_source: str = "manual_admin_reconcile",
) -> dict:
    wanted = safe_int(job_id, 0)
    if wanted <= 0:
        return {"checked": 0, "terminal_failed": 0, "details": []}
    conn = db_connect()
    try:
        return video_project_queue.sweep_product_video_zero_task_watchdog(
            conn,
            job_id=wanted,
            eligibility_evaluator=product_video_bot_watchdog_eligibility,
            reconciliation_source=reconciliation_source,
        )
    finally:
        conn.close()


def product_video_watchdog_scheduler_interval_seconds() -> int:
    configured = os.getenv("PRODUCT_VIDEO_ZERO_TASK_WATCHDOG_INTERVAL_SECONDS")
    return safe_int(
        video_project_queue.product_video_watchdog_interval_config(configured).get("effective_interval_seconds"),
        video_project_queue.PRODUCT_VIDEO_WATCHDOG_INTERVAL_SECONDS_DEFAULT,
    )


def run_product_video_watchdog_scheduler_tick() -> dict:
    conn = db_connect()
    try:
        return video_project_queue.run_product_video_watchdog_scheduler_tick(
            conn,
            eligibility_evaluator=product_video_bot_watchdog_eligibility,
        )
    finally:
        conn.close()


async def product_video_watchdog_scheduler_loop() -> None:
    configured = os.getenv("PRODUCT_VIDEO_ZERO_TASK_WATCHDOG_INTERVAL_SECONDS")

    async def _tick() -> dict:
        return await asyncio.to_thread(run_product_video_watchdog_scheduler_tick)

    await video_project_queue.run_product_video_watchdog_scheduler_loop(
        _tick,
        sleep=asyncio.sleep,
        configured_interval_seconds=configured,
        generation_id=PRODUCT_VIDEO_WATCHDOG_GENERATION_ID,
    )


def product_video_apply_provider_preflight_to_session(user_id, session: dict, preflight: dict) -> dict:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    draft["b14_provider_preflight"] = dict(preflight or {})
    multi_scene_gate = preflight.get("multi_scene_health_gate") if isinstance(preflight.get("multi_scene_health_gate"), dict) else {}
    eligibility_snapshot = (
        multi_scene_gate.get("provider_eligibility_snapshot")
        if isinstance(multi_scene_gate.get("provider_eligibility_snapshot"), dict)
        else preflight.get("provider_eligibility_snapshot")
    )
    eligibility_snapshot = dict(eligibility_snapshot or {})
    chain = [
        str(item or "").strip()
        for item in (
            eligibility_snapshot.get("eligible_provider_keys")
            or (preflight or {}).get("effective_provider_chain", [])
        )
        if str(item or "").strip()
    ]
    draft["provider_eligibility_snapshot"] = eligibility_snapshot
    draft["provider_eligibility_snapshot_id"] = str(eligibility_snapshot.get("provider_eligibility_snapshot_id") or "")
    draft["preconfirm_candidate_keys"] = list(eligibility_snapshot.get("eligible_provider_keys") or [])
    if chain:
        draft["b14_provider_chain"] = chain
        draft["provider_chain"] = chain
        draft["provider_order"] = ",".join(chain)
        asset_pack = dict(draft.get("asset_pack") or {})
        asset_pack["provider_chain"] = chain
        asset_pack["provider_order"] = ",".join(chain)
        asset_pack["selected_provider"] = chain[0]
        asset_pack["provider_preflight_result"] = str(preflight.get("provider_preflight_result") or "")
        asset_pack["provider_degraded_for_product_video_public"] = bool(preflight.get("provider_degraded_for_product_video_public"))
        asset_pack["provider_health_at_submit"] = dict(preflight.get("provider_health_summary") or preflight.get("provider_health_at_submit") or {})
        asset_pack["provider_route_ready_chain"] = list(preflight.get("route_ready_provider_chain") or [])
        asset_pack["provider_live_healthy_chain"] = list(preflight.get("live_healthy_provider_chain") or [])
        asset_pack["multi_scene_health_gate"] = dict(preflight.get("multi_scene_health_gate") or {})
        asset_pack["primary_selected_due_to_health"] = str(preflight.get("primary_selected_due_to_health") or "")
        asset_pack["provider_degraded_reason"] = str(preflight.get("provider_degraded_reason") or "")
        asset_pack["effective_primary_for_low_basic"] = str(preflight.get("effective_primary_for_low_basic") or chain[0])
        asset_pack["provider_eligibility_snapshot"] = eligibility_snapshot
        asset_pack["provider_eligibility_snapshot_id"] = str(eligibility_snapshot.get("provider_eligibility_snapshot_id") or "")
        asset_pack["preconfirm_candidate_keys"] = list(eligibility_snapshot.get("eligible_provider_keys") or [])
        asset_pack["candidate_rejection_reason_by_provider"] = dict(eligibility_snapshot.get("candidate_rejection_reason_by_provider") or {})
        asset_pack["final_eligible_provider_count"] = safe_int(eligibility_snapshot.get("final_eligible_provider_count"), 0)
        asset_pack["product_video_freeze_truth"] = dict(preflight.get("freeze_truth") or {})
        for key in (
            "provider_freeze",
            "public_provider_freeze",
            "hidden_video_freeze",
            "hidden_submit_freeze",
            "background_submit_freeze",
            "smoke_freeze",
            "public_live_provider_allowed",
            "public_preflight_allowed",
            "public_final_confirm_allowed",
            "freeze_blocker_code",
            "freeze_blocker_source",
            "operational_health_state",
            "provider_freeze_policy_by_provider",
            "provider_hard_block_reason_by_provider",
            "probation_eligible",
            "probation_reject_reason",
            "probation_candidate",
            "candidates_before_filter",
            "candidates_after_route_filter",
            "candidates_after_freeze_filter",
            "candidates_after_health_filter",
            "candidates_after_hard_block_filter",
            "candidate_count_before_filters",
            "candidate_count_after_route_filter",
            "candidate_count_after_freeze_filter",
            "candidate_count_after_health_filter",
            "candidate_count_after_hard_block_filter",
            "submit_allowed",
            "submit_block_reason",
        ):
            if key in preflight:
                asset_pack[key] = preflight.get(key)
        draft["asset_pack"] = asset_pack
    session["draft"] = draft
    return save_video_session(user_id, session)


def video_engine_product_type_for_session(session: dict | None = None) -> str:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    product_id = str(session.get("product_id") or draft.get("product_id") or "").strip()
    entry = str(draft.get("entry_choice") or draft.get("input_origin_step") or draft.get("selected_microflow_kind") or "").strip()
    if product_id == "video_trend":
        return "video_trend"
    if product_id == "script_image_video":
        return "script_to_video"
    if product_id == "storyboard_prompt":
        return "storyboard_prompt"
    if product_id == "frame_video_local":
        return "image_to_video"
    if product_id == "self_shot_scene_change":
        return "self_shot_scene_change"
    if product_id == video_selfshot3.PRODUCT_ID:
        return video_selfshot3.JOB_TYPE
    if product_id == "multi_scene_film":
        return "multi_scene_film"
    if product_id == "video_idea":
        return "video_idea_to_product"
    if product_id == "video_ai_real":
        if entry in {"ai_image_menu", "awaiting_source_image", "image_prompts"} or draft.get("source_media_ref") or draft.get("source_media_refs"):
            media_type = str(draft.get("media_type") or "").strip().lower()
            if media_type == "video" or entry in {"ai_video_menu", "awaiting_reference_video"}:
                return "video_ai_video_reference"
            return "video_ai_image"
        if entry in {"ai_video_menu", "awaiting_reference_video", "video", "reference_video"}:
            return "video_ai_video_reference"
        return "video_ai_prompt"
    return video_final_output.normalize_video_product_type(product_id or "video_ai_prompt")


def video_uiflow3_commercial_quote(session: dict, user_id: int) -> dict:
    invoice = video_b14_invoice_for_session(session, user_id)
    quality = safe_int(invoice.get("quality_xu"), 0)
    routing_quality = safe_int(invoice.get("routing_quality_tier"), 0)
    scene_count = max(1, safe_int(invoice.get("scene_count"), 1))
    if quality <= 0 or routing_quality not in VIDEO_TIER_ID_TO_NAME:
        return {}
    tier = VIDEO_TIER_ID_TO_NAME[routing_quality]
    total = max(1, safe_int(invoice.get("total_xu"), quality * scene_count))
    return {
        "tier": tier,
        "package_xu": total,
        "quality_tier": routing_quality,
        "scene_count": scene_count,
        "total_xu": total,
        "user_visible_price_xu": total,
        "persisted_quoted_price_xu": total,
        "customer_charge_planned_xu": total,
        "wallet_charge_amount_xu": total,
        "list_price_xu": max(total, safe_int(invoice.get("subtotal_xu"), total)),
        "provider_budget_xu": total,
        "addons_disabled_by_package": bool(invoice.get("addons_disabled_by_package")),
        "provider_chain": video_project_queue.resolve_product_video_provider_chain(),
    }


def video_uiflow3_prepare_project_for_invoice(user_id: int, session: dict) -> dict:
    """Persist the V3 draft through RouteEngine after package selection."""

    handoff = video_uiflow3_handoff_from_session(session)
    if not handoff:
        return {}
    quote = video_uiflow3_commercial_quote(session, int(user_id))
    if not quote:
        return {}
    db = db_connect()
    try:
        prepared = video_uiflow3_routeengine.prepare_commercial_project(
            db,
            handoff,
            quote=quote,
        )
    finally:
        db.close()
    if not prepared.get("ok"):
        current = get_video_session(user_id)
        draft = dict(current.get("draft") or {})
        draft["uiflow3_prepare_error"] = dict(prepared)
        current["draft"] = draft
        save_video_session(user_id, current)
        return {}
    project = dict(prepared.get("project") or {})
    current = get_video_session(user_id)
    draft = dict(current.get("draft") or {})
    draft.update(
        {
            "b14_project_id": safe_int(project.get("project_id"), 0),
            "b14_invoice": video_b14_invoice_for_session(current, user_id),
            "uiflow3_prepare_error": {},
        }
    )
    current["draft"] = draft
    save_video_session(user_id, current)
    return project


def video_b14_prepare_project_for_invoice(user_id, session: dict) -> dict:
    if video_uiflow3_handoff_from_session(session):
        return video_uiflow3_prepare_project_for_invoice(user_id, session)
    draft = dict((session or {}).get("draft") or {})
    plan = dict(draft.get("b14_storyboard_plan") or {})
    if not plan:
        plan_obj = video_b14_build_storyboard_for_session(user_id, session)
        plan = plan_obj.to_dict()
        draft = dict((get_video_session(user_id).get("draft") or {}))
    invoice = video_b14_invoice_for_session(session, user_id)
    profile_id = str(draft.get("b14_profile_id") or video_b14_profile_id_for_session(session))
    topic = str((session or {}).get("topic") or draft.get("topic") or "")
    ratio = str(draft.get("b14_aspect_ratio") or (session or {}).get("aspect_ratio") or "9:16")
    is_internal = video_b14_is_admin_or_owner(user_id)
    product_type = video_engine_product_type_for_session(session)
    route = video_final_output.route_for_product_type(product_type)
    asset_pack_payload = dict(draft.get("asset_pack") or {})
    logo_material = product_video_logo_material_from_session(session)
    if logo_material.get("logo_enabled"):
        asset_pack_payload["logo_material"] = logo_material
    else:
        asset_pack_payload.pop("logo_material", None)
    original_user_prompt = str((session or {}).get("original_user_prompt") or topic or draft.get("topic") or "").strip()
    cleaned_user_prompt = re.sub(r"\s+", " ", original_user_prompt).strip()
    raw_provider_chain = (
        draft.get("b14_provider_chain")
        or draft.get("provider_chain")
        or asset_pack_payload.get("provider_chain")
        or asset_pack_payload.get("provider_order")
        or draft.get("provider_order")
    )
    if isinstance(raw_provider_chain, str):
        provider_chain = [item.strip() for item in raw_provider_chain.replace("|", ",").replace(">", ",").split(",") if item.strip()]
    else:
        try:
            provider_chain = [str(item or "").strip() for item in raw_provider_chain if str(item or "").strip()]
        except Exception:
            provider_chain = []
    provider_order_csv = ",".join(provider_chain) if provider_chain else (asset_pack_payload.get("provider_order") or os.getenv("VIDEO_PROVIDER_ORDER") or "shopaikey,key4u")
    asset_pack_payload.update({
        "original_user_prompt": original_user_prompt,
        "cleaned_user_prompt": cleaned_user_prompt,
        "provider_order": provider_order_csv,
        "provider_chain": provider_chain or [item.strip() for item in str(provider_order_csv or "").split(",") if item.strip()],
        "product_type": product_type,
        "engine_adapter": route.get("adapter") or "",
        "engine_family": route.get("engine_family") or "",
        "input_requirements": list(route.get("input_requirements") or []),
        "profile_id": profile_id,
        "aspect_ratio": ratio,
        "source": "product_video",
        "render_mode": "real",
        "test_pattern": False,
        "admin_video_delivery": False,
        "owner_admin_test_mode": False,
        "safe_output_delivery_test": False,
        "fake_renderer_allowed": False,
        "real_renderer_required": True,
        "provider_call": True,
        "selected_provider": (provider_chain[0] if provider_chain else ""),
        "submit_source": str(draft.get("submit_source") or draft.get("provider_submit_source") or "public_user_final_confirm"),
        "provider_submit_source": str(draft.get("provider_submit_source") or draft.get("submit_source") or "public_user_final_confirm"),
        "public_user_confirmed": bool(draft.get("public_user_confirmed") or draft.get("b14_public_user_confirmed")),
        "charge_policy": "after_valid_mp4_delivery",
    })
    if product_type == video_selfshot2.JOB_TYPE:
        source_video = dict(draft.get("source_video") or draft.get("source_asset") or {})
        source_analysis = dict(draft.get("source_analysis") or {})
        subject_manifest = dict(draft.get("subject_manifest") or {})
        preserve_constraints = dict(draft.get("preserve_constraints") or {})
        scene_plan = list(draft.get("scene_plan") or [])
        video_prompts = list(draft.get("video_prompts") or [])
        preflight_snapshot = dict(draft.get("selfshot2_preflight") or {})
        scene_count = max(1, safe_int(draft.get("scene_count"), len(scene_plan) or 1))
        asset_pack_payload.update({
            "source_video": source_video,
            "source_file_id": str(source_video.get("file_id") or draft.get("source_file_id") or ""),
            "source_video_id": str(source_video.get("file_id") or draft.get("source_file_id") or ""),
            "source_materialization_required": True,
            "source_probe_policy": str(draft.get("source_probe_policy") or "telegram_metadata_then_worker_ffprobe"),
            "source_hash": str(source_analysis.get("source_hash") or ""),
            "source_analysis": source_analysis,
            "shot_manifest": list(source_analysis.get("shot_manifest") or []),
            "person_tracks": list(source_analysis.get("person_tracks") or []),
            "face_tracks": list(source_analysis.get("face_tracks") or []),
            "object_tracks": list(source_analysis.get("object_tracks") or []),
            "logo_text_candidates": list(source_analysis.get("logo_text_candidates") or []),
            "interaction_graph": list(source_analysis.get("interaction_graph") or []),
            "audio_manifest": dict(source_analysis.get("audio_manifest") or {}),
            "analysis_version": str(source_analysis.get("analysis_version") or ""),
            "subject_manifest": subject_manifest,
            "preserve_constraints": preserve_constraints,
            "selected_content": dict(draft.get("selected_content") or {}),
            "selected_profile": str(draft.get("selected_profile") or ""),
            "transformation_direction": dict(draft.get("direction_contract") or {}),
            "scene_plan": scene_plan,
            "scene_source_segments": [
                {
                    "scene_index": safe_int(item.get("scene_index"), index),
                    "start_seconds": float(item.get("source_segment_start") or 0),
                    "end_seconds": float(item.get("source_segment_end") or 0),
                }
                for index, item in enumerate(scene_plan, 1)
            ],
            "video_prompts": video_prompts,
            "audio_plan": dict(draft.get("audio_plan") or {}),
            "visual_addons": dict(draft.get("visual_addons") or {}),
            "capability_snapshot": dict(preflight_snapshot.get("engine_route") or {}),
            "route_selection": dict(preflight_snapshot.get("route_selection") or {}),
            "scene_count": scene_count,
            "duration_seconds": scene_count * video_selfshot2.SCENE_SECONDS,
            "source_bound_per_scene": True,
            "text_only_fallback_allowed": False,
            "continuity_validation_required": True,
            "identity_continuity_required": bool(subject_manifest.get("person_subject_ids")),
            "object_continuity_required": bool(subject_manifest.get("object_subject_ids")),
            "relationship_continuity_required": bool(
                subject_manifest.get("person_subject_ids") and subject_manifest.get("object_subject_ids")
            ),
            "receipt_once": True,
        })
        invoice.update({
            "job_type": video_selfshot2.JOB_TYPE,
            "source_hash": str(source_analysis.get("source_hash") or ""),
            "scene_count": scene_count,
            "duration_seconds": scene_count * video_selfshot2.SCENE_SECONDS,
            "engine_route": str((preflight_snapshot.get("engine_route") or {}).get("route") or ""),
            "continuity_validation_required": True,
            "text_only_fallback_allowed": False,
        })
    if product_type == video_selfshot3.JOB_TYPE:
        source_video = dict(draft.get("source_video") or draft.get("source_asset") or {})
        source_analysis = dict(draft.get("source_analysis") or {})
        source_segment = dict(draft.get("source_segment") or {})
        subject_manifest = dict(draft.get("subject_manifest") or {})
        relationship_locks = list(draft.get("relationship_locks") or [])
        transformation_stages = list(draft.get("transformation_stages") or [])
        prompt_bundle = dict(draft.get("prompt_bundle") or {})
        audio_plan = dict(draft.get("audio_plan") or {})
        preflight_snapshot = dict(draft.get("selfshot3_preflight") or {})
        asset_pack_payload.update({
            "source_video": source_video,
            "source_file_id": str(source_video.get("file_id") or draft.get("source_file_id") or ""),
            "source_video_id": str(source_video.get("file_id") or draft.get("source_file_id") or ""),
            "source_materialization_required": True,
            "source_probe_policy": str(draft.get("source_probe_policy") or "telegram_metadata_until_worker_probe"),
            "source_hash": str(source_analysis.get("source_hash") or ""),
            "source_analysis": source_analysis,
            "shot_manifest": list(source_analysis.get("shot_manifest") or []),
            "person_tracks": list(source_analysis.get("person_tracks") or []),
            "face_tracks": list(source_analysis.get("face_tracks") or []),
            "pet_tracks": list(source_analysis.get("pet_tracks") or []),
            "object_tracks": list(source_analysis.get("object_tracks") or []),
            "product_tracks": list(source_analysis.get("product_tracks") or []),
            "interaction_graph": list(source_analysis.get("interaction_graph") or []),
            "camera_motion": str(source_analysis.get("camera_motion") or ""),
            "audio_manifest": dict(source_analysis.get("audio_manifest") or {}),
            "analysis_version": str(source_analysis.get("analysis_version") or ""),
            "source_segment": source_segment,
            "subject_manifest": subject_manifest,
            "interaction_locks": relationship_locks,
            "layer_rules": dict(draft.get("layer_rules") or {}),
            "transformation_group_id": str(draft.get("selected_group_id") or ""),
            "transformation_preset": dict(draft.get("selected_preset") or {}),
            "transformation_content": str(draft.get("transformation_content") or ""),
            "transformation_stages": transformation_stages,
            "wardrobe_plan": str(draft.get("wardrobe") or ""),
            "environment_plan": str(draft.get("world") or ""),
            "effect_layers": list(draft.get("selected_effects") or []),
            "prompt_bundle": prompt_bundle,
            "audio_plan": audio_plan,
            "capability_snapshot": dict(preflight_snapshot.get("engine_route") or {}),
            "route_selection": dict(preflight_snapshot.get("route_selection") or {}),
            "one_take": True,
            "scene_count": 1,
            "duration_seconds": max(1, int((source_segment.get("duration_ms") or 0) / 1000)),
            "continuity_validation_required": True,
            "identity_continuity_required": True,
            "object_continuity_required": bool(relationship_locks or subject_manifest.get("selection_type") in {"object", "person_object"}),
            "receipt_once": True,
        })
        invoice.update({
            "job_type": video_selfshot3.JOB_TYPE,
            "source_hash": str(source_analysis.get("source_hash") or ""),
            "one_take": True,
            "scene_count": 1,
            "duration_seconds": max(1, int((source_segment.get("duration_ms") or 0) / 1000)),
            "engine_route": str((preflight_snapshot.get("engine_route") or {}).get("route") or ""),
            "continuity_validation_required": True,
        })
    invoice.update({
        "product_type": product_type,
        "engine_adapter": route.get("adapter") or "",
        "source": "product_video",
        "render_mode": "real",
        "test_pattern": False,
        "admin_video_delivery": False,
        "owner_admin_test_mode": False,
        "safe_output_delivery_test": False,
        "fake_renderer_allowed": False,
        "real_renderer_required": True,
        "provider_call": True,
        "provider_order": provider_order_csv,
        "provider_chain": provider_chain or [item.strip() for item in str(provider_order_csv or "").split(",") if item.strip()],
        "selected_provider": (provider_chain[0] if provider_chain else ""),
        "submit_source": str(draft.get("submit_source") or draft.get("provider_submit_source") or "public_user_final_confirm"),
        "provider_submit_source": str(draft.get("provider_submit_source") or draft.get("submit_source") or "public_user_final_confirm"),
        "public_user_confirmed": bool(draft.get("public_user_confirmed") or draft.get("b14_public_user_confirmed")),
        "charge_policy": "after_valid_mp4_delivery",
    })
    if is_internal:
        asset_pack_payload.update({
            "created_by_admin": True,
            "admin_only": True,
            "admin_no_charge": True,
            "no_charge": True,
            "public_user": False,
            "scene_count": invoice["scene_count"],
            "duration_seconds": invoice["duration_seconds"],
        })
        invoice.update({
            "created_by_admin": True,
            "admin_only": True,
            "admin_no_charge": True,
            "no_charge": True,
            "public_user": False,
            "source": asset_pack_payload.get("source"),
        })
    else:
        asset_pack_payload.update({"public_user": True, "admin_only": False, "no_charge": False})
        invoice.update({"public_user": True, "admin_only": False, "no_charge": False})
    project_id = safe_int(draft.get("b14_project_id"), 0)
    if project_id:
        project = get_video_project(project_id)
    else:
        project = create_video_project(
            user_id,
            profile_id=profile_id,
            topic=topic,
            ratio=ratio,
            asset_pack=asset_pack_payload,
        )
        project_id = safe_int(project.get("project_id"), 0)
    save_video_project_storyboard(project_id, plan)
    creative_controls = video_b14_creative_controls_to_storyboard(session)
    addon_plan = video_b14_addon_plan_from_session(session)
    if invoice["addons_disabled_by_package"]:
        addon_plan = video_b14_sanitize_trial_addons(addon_plan, quality_xu=invoice["quality_xu"])
    update = update_video_project(
        project_id,
        status="draft_invoice",
        profile_id=profile_id,
        topic=topic,
        ratio=ratio,
        asset_pack_json=asset_pack_payload,
        prompt_text=str(original_user_prompt or plan.get("preview_text") or topic or "")[:8000],
        addon_plan_json=addon_plan,
        creative_control_json=creative_controls,
        quality_tier=safe_int(
            invoice.get("routing_quality_tier"),
            invoice["quality_xu"],
        ),
        scene_count=invoice["scene_count"],
        addons_disabled_by_package=1 if invoice["addons_disabled_by_package"] else 0,
        invoice_json=invoice,
        total_xu_estimated=invoice["total_xu"],
    )
    draft["b14_project_id"] = project_id
    draft["b14_invoice"] = invoice
    draft["b14_addon_plan"] = addon_plan
    draft["asset_pack"] = asset_pack_payload
    session["draft"] = draft
    save_video_session(user_id, session)
    return update


def task3d_idea_suggestions(product_id: str, lang: str = "vi", offset: int = 0) -> list[str]:
    suggestions = list(TASK3D_GUIDED_IDEAS.get(str(product_id or "")) or [])
    if suggestions:
        offset = safe_int(offset, 0)
        if offset > 0:
            product = VIDEO_PRODUCT_REGISTRY.get(str(product_id or "")) or {}
            public_label = str(product.get("public_label") or "video")
            round_no = offset // max(len(suggestions), 1) + 1
            suggestions = suggestions + [
                f"Phiên bản khác {round_no}: mở đầu bằng câu hỏi đau điểm rồi chốt lợi ích rõ cho {public_label}.",
                f"Phiên bản khác {round_no}: kể chuyện trước/sau, thêm cảnh demo ngắn và CTA lưu lại.",
                f"Phiên bản khác {round_no}: góc quay đời thường, chuyển động nhẹ, nội dung tự nhiên như UGC.",
                f"Phiên bản khác {round_no}: phong cách quảng cáo nhanh, 1 hook mạnh, 1 bằng chứng, 1 lời kêu gọi hành động.",
                f"Phiên bản khác {round_no}: cinematic sạch, nhấn vào cảm xúc và kết quả cuối.",
            ]
        if suggestions:
            start = offset % len(suggestions)
            rotated = suggestions[start:] + suggestions[:start]
            return rotated[:5]
    sample = TASK3D_SAMPLE_TOPICS.get(str(product_id or "")) or "ý tưởng video ngắn dễ xem"
    return [
        f"Video hook 8 giây cho {sample}",
        f"Storyboard before/after cho {sample}",
        f"Video UGC chân thật xoay quanh {sample}",
        f"Prompt cinematic ngắn cho {sample}",
    ]

def task3d_idea_suggestions_text(session: dict, lang: str = "vi") -> str:
    product_id = str(session.get("product_id") or "")
    product = VIDEO_PRODUCT_REGISTRY.get(product_id) or {}
    ideas = task3d_idea_suggestions(product_id, lang, safe_int((session.get("draft") or {}).get("idea_offset"), 0))
    lines = [
        f"💡 <b>Gợi ý nhanh cho {html.escape(str(product.get('public_label') or 'video'))}</b>",
        "",
        "Chọn một ý tưởng để TOAN AAS đi tiếp qua các bước gợi ý phù hợp và tạo prompt miễn phí.",
        "",
    ]
    for idx, idea in enumerate(ideas[:5], 1):
        lines.append(f"{idx}. {html.escape(idea)}")
    lines.append("\nBạn cũng có thể quay lại để nhập thủ công. Bước này chưa xử lý video và chưa trừ Xu.")
    return "\n".join(lines)

