def task3d_session_step(user_id, step: str, **fields) -> dict:
    session = get_video_session(user_id)
    current = str(session.get("current_step") or "")
    step = str(step or "")
    history = [str(item) for item in (session.get("step_history") or []) if str(item or "")]
    if current and current != step and current != VIDEO_BACK_MENU_TARGET and (not history or history[-1] != current):
        history.append(current)
    session["previous_step"] = current
    session["current_step"] = step
    session["step_history"] = history[-12:]
    draft = dict(session.get("draft") or {})
    product_id_before = str(session.get("product_id") or draft.get("product_id") or fields.get("product_id") or "")
    for key, value in fields.items():
        if key in {"product_id", "topic", "platform", "aspect_ratio", "style", "package_id", "prompt_bundle_id", "source_media_ref", "return_to", "selected_scene_count", "estimated_scene_seconds", "estimated_duration_seconds", "duration_mode", "duration_note", "video_flow", "video_tool", "source_button", "parent_menu", "parent_menu_callback", "back_target", "entry_callback", "first_step"}:
            session[key] = value
        draft[key] = value
    product_id = str(session.get("product_id") or draft.get("product_id") or product_id_before or "")
    route_tool = str(session.get("video_tool") or draft.get("video_tool") or product_id or "")
    if product_id:
        session.setdefault("video_flow", product_id)
        draft.setdefault("video_flow", product_id)
    if route_tool:
        session.setdefault("video_tool", route_tool)
        draft.setdefault("video_tool", route_tool)
    if product_id or route_tool:
        session.setdefault("parent_menu_callback", "menu|main_video")
        session.setdefault("back_target", "menu|main_video")
        session.setdefault("return_to", "menu|main_video")
        session["flow_stack"] = ["video_main", route_tool or product_id, step or video_flow_first_step(route_tool or product_id)]
    session["draft"] = draft
    return save_video_session(user_id, session)


def task3d_back_step(user_id) -> tuple[str, dict]:
    session = get_video_session(user_id)
    history = [str(item) for item in (session.get("step_history") or []) if str(item or "")]
    current = str(session.get("current_step") or "")
    target = video_back_matrix_target(session)
    if target == VIDEO_BACK_MENU_TARGET:
        history = []
    elif history and history[-1] == target:
        history.pop()
    else:
        try:
            index = len(history) - 1 - list(reversed(history)).index(target)
            history = history[:index]
        except ValueError:
            history = [item for item in history if item != current]
    session["previous_step"] = current
    session["current_step"] = target
    session["step_history"] = history
    flow_id = video_session_flow_id(session)
    tool_id = str(session.get("video_tool") or flow_id or "")
    session["flow_stack"] = ["video_main", tool_id, target]
    return target, save_video_session(user_id, session)


def task3d_build_bundle_from_session(session: dict) -> dict:
    draft = dict(session.get("draft") or {})
    product_id = str(session.get("product_id") or draft.get("product_id") or "")
    count = safe_int(draft.get("panel_count") or draft.get("scene_count") or (1 if product_id in {"video_ai_real", "image_to_video", "motion_prompt"} else 6), 6)
    reference_parts = [
        str(draft.get("selected_motion") or ""),
        str(draft.get("camera_choice") or ""),
        str(draft.get("film_pace") or ""),
        str(draft.get("suggested_scene") or ""),
        str(draft.get("reference_format") or ""),
        str(draft.get("reference_style") or ""),
    ]
    request = VideoPromptRequest(
        product_id=product_id,
        user_topic=str(session.get("topic") or draft.get("topic") or draft.get("media_description") or "Ảnh/video người dùng cung cấp"),
        platform=str(session.get("platform") or draft.get("platform") or "TikTok/Reels"),
        aspect_ratio=str(session.get("aspect_ratio") or draft.get("aspect_ratio") or "9:16"),
        duration=max(6, count * 4),
        package_id=str(session.get("package_id") or ""),
        objective=str(draft.get("objective") or "engagement"),
        style=str(session.get("style") or draft.get("style") or "realistic cinematic"),
        tone=str(draft.get("color_mood") or "clear, original and audience-appropriate"),
        language="vi",
        character_description=str(draft.get("main_subject") or ""),
        scene_count=count,
        shot_count=count,
        reference_style=", ".join(item for item in reference_parts if item and item not in {"mặc định", "bỏ qua"}),
        source_media_ref=str(session.get("source_media_ref") or draft.get("source_media_ref") or ""),
        user_constraints=([str(draft.get("image_plan"))] if draft.get("image_plan") and draft.get("image_plan") != "bỏ qua" else []),
        provider_target="configured_shopAIKey_or_Key4U_route",
        safety_flags=["no_artist_imitation", "no_copyrighted_character_without_rights", "no_watermark"],
    )
    return TASK3D_PROMPT_ENGINE.build(request).to_dict()


def task3d_result_text(session: dict, lang: str = "vi") -> str:
    bundle = dict((session.get("draft") or {}).get("prompt_bundle") or {})
    shots = list(bundle.get("shot_table") or [])
    batches = list((bundle.get("render_plan") or {}).get("batches") or [])
    lines = [
        "🎞 <b>Bộ ý tưởng và prompt đã sẵn sàng</b>", "",
        f"<b>{html.escape(str(bundle.get('title') or 'TOAN AAS Video'))}</b>",
        html.escape(str(bundle.get("short_summary") or "")), "",
        f"<b>Hook:</b> {html.escape(str(bundle.get('hook') or ''))}", "",
        "<b>Storyboard / các cảnh chính</b>",
    ]
    trend_hooks = list(bundle.get("trend_hooks") or [])
    if trend_hooks:
        lines.extend(["", "<b>3 hook gợi ý</b>"])
        for hook in trend_hooks[:3]:
            lines.append(f"• {html.escape(str(hook))}")
    caption = str(bundle.get("caption") or "").strip()
    if caption:
        lines.extend(["", f"<b>Caption:</b> {html.escape(caption)}"])
    for shot in shots[:6]:
        lines.append(
            f"• Cảnh {shot.get('shot_number')} · {shot.get('duration_seconds')}s · "
            f"{html.escape(str(shot.get('camera_angle') or ''))} · {html.escape(str(shot.get('camera_movement') or ''))}\n"
            f"  {html.escape(str(shot.get('scene_purpose') or ''))}"
        )
    if len(shots) > 6:
        lines.append(f"• … còn {len(shots) - 6} cảnh trong file xuất.")
    if batches:
        batch_text = ", ".join(f"B{item.get('batch_number')}: {','.join(map(str, item.get('shot_numbers') or []))}" for item in batches)
        lines.extend(["", f"<b>Gợi ý chia cảnh:</b> <code>{html.escape(batch_text)}</code>"])
    lines.extend(["", "Bước này miễn phí: chưa xử lý video AI, chưa tạo lệnh xử lý trả phí và chưa trừ Xu."])
    return "\n".join(lines)


