@video_public_callback_failure_guard
async def handle_video_prompt_library_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    await query.answer()
    if action in {"start", "menu", "back"}:
        set_video_route_session(uid, "prompt_library", "tool_home")
        return await safe_edit_or_send(
            query,
            video_prompt_library_text(lang),
            parse_mode="HTML",
            reply_markup=video_prompt_library_keyboard(lang),
        )
    if action in VIDEO_PROMPT_LIBRARY_CATEGORY_KEYWORDS:
        set_video_route_session(uid, "prompt_library", f"category:{action}")
        items = video_prompt_library_search(action, limit=5)
        return await safe_edit_or_send(
            query,
            video_prompt_library_category_text(action, items, lang),
            parse_mode="HTML",
            reply_markup=video_prompt_library_category_keyboard(action, items, lang),
        )
    if action == "use":
        category = parts[2] if len(parts) > 2 else "idea"
        index = max(1, min(5, safe_int(parts[3] if len(parts) > 3 else 1, 1)))
        items = video_prompt_library_search(category, limit=5)
        item = items[index - 1] if index <= len(items) else {}
        if not item:
            return await safe_edit_or_send(
                query,
                video_prompt_library_guard_text(lang),
                reply_markup=video_prompt_library_keyboard(lang),
            )
        product_id = str(item.get("product_id") or "storyboard_prompt")
        if product_id not in VIDEO_PRODUCT_REGISTRY:
            product_id = "storyboard_prompt"
        prompt_text = str(item.get("prompt_text") or "").strip()
        route_fields = video_route_session_fields("prompt_library", "use_prompt")
        session = task3d_session_step(
            uid,
            "result",
            product_id=product_id,
            topic=prompt_text[:320] or video_prompt_library_category_label(category, lang),
            input_collected=True,
            prompt_library_prompt_id=str(item.get("prompt_id") or ""),
            provider_called=False,
            xu_charged=0,
            return_to="menu|main_video",
            **route_fields,
        )
        session.update(route_fields)
        session["product_id"] = product_id
        session["return_to"] = "menu|main_video"
        save_video_session(uid, session)
        bundle = task3d_build_bundle_from_session(session)
        session = task3d_session_step(
            uid,
            "result",
            prompt_bundle=bundle,
            prompt_bundle_id=bundle.get("bundle_id"),
            free_generation=True,
            provider_called=False,
            xu_charged=0,
        )
        return await safe_edit_or_send(
            query,
            "✅ <b>Đã dùng câu lệnh từ Kho mẫu ý tưởng</b>\n\n" + task3d_result_text(session, lang),
            parse_mode="HTML",
            reply_markup=task3d_result_keyboard(product_id, lang),
        )
    return await safe_edit_or_send(query, video_prompt_library_text(lang), parse_mode="HTML", reply_markup=video_prompt_library_keyboard(lang))


@video_public_callback_failure_guard
async def handle_product_video_public_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    callback_data = str(
        getattr(context, "_product_video_callback_data_override", "")
        or getattr(query, "data", "")
        or ""
    )
    if not query or not re.fullmatch(
        rf"{re.escape(video_project_queue.PRODUCT_VIDEO_PUBLIC_CONFIRM_CALLBACK)}(?:\|[a-f0-9]{{12}})?",
        callback_data,
    ):
        return
    diagnostics = dict(PRODUCT_VIDEO_CONFIRM_HANDLER_DIAGNOSTICS or {})
    if (
        diagnostics.get("product_video_confirm_handler_count") != 1
        or diagnostics.get("duplicate_confirm_handler_detected")
        or diagnostics.get("duplicate_callback_pattern_detected")
    ):
        await query.answer()
        logger.error("product_video_public_confirm_fail_closed | %s", json.dumps(diagnostics, ensure_ascii=True, sort_keys=True))
        return await safe_edit_or_send(
            query,
            "Hệ thống tạo video nhiều cảnh đang được cập nhật. TOAN AAS chưa trừ Xu. Anh/chị vui lòng thử lại sau.",
        )
    setattr(context, "_product_video_authoritative_confirm", True)
    try:
        return await handle_video_product_callback(update, context)
    finally:
        try:
            delattr(context, "_product_video_authoritative_confirm")
        except Exception:
            pass


VIDEO_TREND2_STATE_KEY = "video_trend2_state"
VIDEO_TREND2_PARENT = {
    "catalog": "entry",
    "historical": "entry",
    "categories": "entry",
    "help": "entry",
    "scene_count": "catalog",
    "aspect_ratio": "scene_count",
    "content_source": "aspect_ratio",
    "profiles": "content_source",
    "suggestions": "profiles",
    "preview": "suggestions",
}


def video_trend2_state(context) -> dict:
    state = dict((getattr(context, "user_data", {}) or {}).get(VIDEO_TREND2_STATE_KEY) or {})
    state.setdefault("screen", "entry")
    state.setdefault("catalog_offset", 0)
    state.setdefault("catalog_mode", "latest")
    state.setdefault("profile_page", 1)
    state.setdefault("suggestion_offset", 0)
    state.setdefault("selected_trend", {})
    state.setdefault("scene_count", 0)
    state.setdefault("aspect_ratio", "")
    state.setdefault("profile_key", "")
    state.setdefault("suggestions", [])
    state.setdefault("content_choice", {})
    state.update({
        "provider_called": False,
        "image_provider_called": False,
        "job_created": False,
        "outbox_created": False,
        "files_generated": 0,
        "wallet_mutations": 0,
        "xu_charged": 0,
    })
    return state


def save_video_trend2_state(context, state: dict) -> dict:
    clean = video_trend2_state(context)
    clean.update(dict(state or {}))
    clean.update({
        "provider_called": False,
        "image_provider_called": False,
        "job_created": False,
        "outbox_created": False,
        "files_generated": 0,
        "wallet_mutations": 0,
        "xu_charged": 0,
    })
    context.user_data[VIDEO_TREND2_STATE_KEY] = clean
    return clean


def video_trend2_open_screen(state: dict, screen: str, *, parent: str = "") -> dict:
    """Open one Trend screen while retaining the exact screen that launched it."""

    updated = dict(state or {})
    current = str(updated.get("screen") or "entry")
    target = str(screen or "entry")
    parents = dict(updated.get("screen_parents") or {})
    parent_screen = str(parent or (current if current != target else ""))
    if parent_screen and parent_screen != target:
        parents[target] = parent_screen
    updated.update({"screen": target, "screen_parents": parents})
    return updated


def video_trend2_db(read_fn):
    conn = db_connect()
    try:
        video_trend_catalog.ensure_schema(conn)
        video_trend_catalog.seed_media_catalog(conn)
        return read_fn(conn)
    finally:
        conn.close()


