def video_trend2_canonical_state(context, state: dict) -> dict:
    content = dict(state.get("content_choice") or {})
    subject = str(content.get("content") or content.get("title") or (state.get("selected_trend") or {}).get("title") or "Video theo trend")
    profile_key = str(state.get("profile_key") or "social_creator_trend")
    canonical = video_scene3_flow.default_state(
        product_type="video_trend",
        subject=subject,
        aspect_ratio=str(state.get("aspect_ratio") or "9:16"),
    )
    canonical.update({
        "source_product_id": "video_trend",
        "scene_count": max(1, min(20, safe_int(state.get("scene_count"), 1))),
        "aspect_ratio": str(state.get("aspect_ratio") or "9:16"),
        "content_mode": "manual" if str(content.get("id") or "").startswith("manual") else "suggestions",
        "subject": subject,
        "trend_source": video_trend2_source_snapshot(state),
        "trend_content_choice": content,
        "provider_called": False,
        "image_provider_called": False,
        "job_created": False,
        "outbox_created": False,
        "files_generated": 0,
        "wallet_mutations": 0,
        "xu_charged": 0,
    })
    canonical = video_scene3_flow.select_primary_profile(canonical, profile_key)
    canonical.update({
        "content_choice": content,
        "selected_suggestion": content,
        "step": "character",
        "history": ["content_mode", "scene_count", "aspect_ratio", "profile_select", "suggestions"],
    })
    return save_video_profile_studio_state(context, video_flow6.sync_scene_state(canonical))


async def video_trend2_render(target, context, state: dict, lang: str = "vi"):
    screen = str(state.get("screen") or "entry")
    if screen == "entry":
        return await safe_edit_or_send(
            target,
            task3d_product_intro_text("video_trend", lang),
            parse_mode="HTML",
            reply_markup=video_trend2_entry_keyboard(),
        )
    if screen == "catalog":
        rows = video_trend2_catalog_rows(state)
        return await safe_edit_or_send_long_html(target, video_trend2_catalog_text(state, rows), reply_markup=video_trend2_catalog_keyboard(state, rows))
    if screen == "categories":
        historical = str(state.get("catalog_mode") or "latest") == "historical"
        categories = video_trend2_db(
            lambda conn: video_trend_catalog.list_media_categories(conn, historical=historical)
        )
        rows = [
            [InlineKeyboardButton(category, callback_data=f"vtrend|category|{index}") for index, category in enumerate(categories[start:start + 2], start=start)]
            for start in range(0, len(categories), 2)
        ]
        if not rows:
            rows = [[InlineKeyboardButton("✍️ Tự nhập trend", callback_data="vtrend|manual_trend"), InlineKeyboardButton("🔥 Trend mới nhất", callback_data="vtrend|catalog|latest")]]
        rows.append(video_trend2_nav("vtrend|back"))
        return await safe_edit_or_send(
            target,
            "🔎 <b>Lọc media trend</b>\n\nChọn một dạng nội dung truyền thông. Chưa tạo video và chưa trừ Xu.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(rows),
        )
    if screen == "help":
        return await safe_edit_or_send(
            target,
            "📖 <b>Video theo trend</b>\n\n"
            "1. Chọn một media trend mới hoặc tự nhập.\n"
            "2. Chọn số cảnh và tỉ lệ.\n"
            "3. Chọn loại nội dung, Kho Ý tưởng video hoặc tự nhập nội dung.\n"
            "4. Xem, sửa prompt rồi hoàn thiện video.\n\n"
            "Chỉ sau hóa đơn và xác nhận cuối hệ thống mới được tạo tác vụ. Xu chỉ trừ sau khi video cuối hợp lệ đã được gửi.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([video_trend2_nav("vtrend|back")]),
        )
    if screen == "scene_count":
        return await safe_edit_or_send(target, video_trend2_scene_count_text(state), parse_mode="HTML", reply_markup=video_trend2_scene_count_keyboard())
    if screen == "aspect_ratio":
        return await safe_edit_or_send(
            target,
            f"📐 <b>Chọn tỉ lệ video</b>\n\nSố cảnh: {safe_int(state.get('scene_count'), 0)}. Tỉ lệ được khóa sớm để viết bố cục từng cảnh đúng ngay từ đầu.",
            parse_mode="HTML",
            reply_markup=video_trend2_ratio_keyboard(),
        )
    if screen == "content_source":
        return await safe_edit_or_send(
            target,
            "🧭 <b>Chọn cách xây nội dung</b>\n\nChọn loại nội dung để mở đúng một trong 32 profile rồi nhận gợi ý bám trend. Kho Ý tưởng video dùng preset có sẵn; tự nhập giữ nguyên nội dung của anh/chị.",
            parse_mode="HTML",
            reply_markup=video_trend2_content_source_keyboard(),
        )
    if screen == "profiles":
        page = safe_int(state.get("profile_page"), 1)
        return await safe_edit_or_send_long_html(target, video_trend2_profiles_text(state, page), reply_markup=video_trend2_profiles_keyboard(page))
    if screen == "suggestions":
        return await safe_edit_or_send_long_html(target, video_trend2_suggestions_text(state), reply_markup=video_trend2_suggestions_keyboard(state))
    if screen == "preview":
        return await safe_edit_or_send_long_html(target, video_trend2_preview_text(state), reply_markup=video_trend2_preview_keyboard())
    state["screen"] = "entry"
    save_video_trend2_state(context, state)
    return await video_trend2_render(target, context, state, lang)


async def _handle_video_trend2_callback_impl(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|", 2)
    action = parts[1] if len(parts) > 1 else "entry"
    value = parts[2] if len(parts) > 2 else ""
    state = video_trend2_state(context)
    callback_query_id = str(getattr(query, "id", "") or "")
    if callback_query_id and str(state.get("last_callback_query_id") or "") == callback_query_id:
        return None
    if callback_query_id:
        state["last_callback_query_id"] = callback_query_id
        state = save_video_trend2_state(context, state)

    if action == "entry":
        state = save_video_trend2_state(context, {
            "screen": "entry",
            "screen_parents": {},
            "category": "",
            "catalog_mode": "latest",
            "catalog_offset": 0,
            "last_callback_query_id": callback_query_id,
        })
        return await video_trend2_render(query, context, state, lang)
    if action == "catalog":
        state = video_trend2_open_screen(state, "catalog")
        state.update({"category": "", "catalog_mode": "latest", "catalog_offset": 0, "pending_input": ""})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "historical":
        # Read-only compatibility for old Telegram messages. The public flow
        # now has one twenty-item media catalog shown five at a time.
        readonly = dict(state)
        readonly.update({"screen": "catalog", "category": "", "catalog_mode": "latest", "catalog_offset": 0})
        return await video_trend2_render(query, context, readonly, lang)
    if action == "categories":
        readonly = dict(state)
        readonly.update({"screen": "catalog", "category": "", "catalog_mode": "latest"})
        return await video_trend2_render(query, context, readonly, lang)
    if action == "category":
        readonly = dict(state)
        readonly.update({"screen": "catalog", "category": "", "catalog_mode": "latest"})
        return await video_trend2_render(query, context, readonly, lang)
    if action == "more":
        rows = video_trend2_catalog_rows(state)
        offset = safe_int(state.get("catalog_offset"), 0) + 5
        state["catalog_offset"] = 0 if offset >= len(rows) else offset
        state["screen"] = "catalog"
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "help":
        state = video_trend2_open_screen(state, "help", parent="entry")
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action in {"freshness", "sources", "ratio_suggest"}:
        readonly = dict(state)
        if str(readonly.get("screen") or "") not in VIDEO_TREND2_PARENT:
            readonly["screen"] = "entry"
        return await video_trend2_render(query, context, readonly, lang)
    if action == "pick":
        trend = video_trend2_db(lambda conn: video_trend_catalog.get_item(conn, value))
        if not trend or not video_trend_catalog.is_media_trend(trend):
            state["screen"] = "catalog"
            state = save_video_trend2_state(context, state)
            return await video_trend2_render(query, context, state, lang)
        state = video_trend2_open_screen(state, "scene_count", parent="catalog")
        state.update({"selected_trend": trend, "pending_input": ""})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "manual_trend":
        state.update({
            "pending_input": "manual_trend",
            "input_return_screen": str(state.get("screen") or "entry"),
        })
        save_video_trend2_state(context, state)
        return await safe_edit_or_send(
            query,
            "✍️ <b>Tự nhập trend</b>\n\nGửi tên trend hoặc chủ đề đang được quan tâm. Đây sẽ được ghi rõ là nội dung do anh/chị cung cấp, không giả thành nguồn thị trường.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([video_trend2_nav("vtrend|resume")]),
        )
    if action == "scenes":
        count = safe_int(value, 0)
        if count not in {1, 2, 3, 5, 10, 20}:
            return await video_trend2_render(query, context, state, lang)
        state = video_trend2_open_screen(state, "aspect_ratio", parent="scene_count")
        state.update({"scene_count": count, "pending_input": ""})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "scenes_custom":
        state["pending_input"] = "scene_count"
        save_video_trend2_state(context, state)
        return await safe_edit_or_send(
            query,
            "✍️ <b>Nhập số cảnh</b>\n\nGửi một số từ 1 đến 20. Thời lượng mỗi cảnh được xác định theo gói Chất lượng.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([video_trend2_nav("vtrend|resume")]),
        )
    if action == "scene_note":
        return await safe_edit_or_send(
            query,
            "ℹ️ <b>Lưu ý số cảnh</b>\n\nMỗi cảnh phải trọn một ý, hành động hoặc phong cảnh. Nhiều cảnh hơn tạo video dài hơn và có thể tăng tổng chi phí; chất lượng và giá được chọn gần cuối.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([video_trend2_nav("vtrend|resume")]),
        )
    if action == "ratio":
        if value not in {"9:16", "16:9", "1:1", "4:5"}:
            return await video_trend2_render(query, context, state, lang)
        state = video_trend2_open_screen(state, "content_source", parent="aspect_ratio")
        state.update({"aspect_ratio": value, "pending_input": ""})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "ratio_custom":
        state["screen"] = "aspect_ratio"
        state["pending_input"] = ""
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "profiles":
        state = video_trend2_open_screen(state, "profiles")
        state.update({"profile_page": max(1, safe_int(value, 1)), "pending_input": ""})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "profile":
        profile = video_trend2_profile_record(value)
        if not profile:
            state["screen"] = "profiles"
            return await video_trend2_render(query, context, save_video_trend2_state(context, state), lang)
        suggestions = video_trend_catalog.build_content_suggestions(
            dict(state.get("selected_trend") or {}),
            profile,
            scene_count=safe_int(state.get("scene_count"), 1),
            aspect_ratio=str(state.get("aspect_ratio") or "9:16"),
        )
        state = video_trend2_open_screen(state, "suggestions", parent="profiles")
        state.update({"profile_key": value, "suggestions": suggestions, "suggestion_offset": 0})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "suggestions_more":
        suggestions = list(state.get("suggestions") or [])
        offset = safe_int(state.get("suggestion_offset"), 0) + 5
        state.update({"suggestion_offset": 0 if offset >= len(suggestions) else offset, "screen": "suggestions"})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "suggestion":
        page = video_trend_catalog.suggestion_page(list(state.get("suggestions") or []), safe_int(state.get("suggestion_offset"), 0))
        index = safe_int(value, -1)
        if index < 0 or index >= len(page):
            return await video_trend2_render(query, context, state, lang)
        history = list(state.get("content_choice_history") or [])
        if state.get("content_choice"):
            history.append(dict(state.get("content_choice") or {}))
        state = video_trend2_open_screen(state, "preview", parent="suggestions")
        state.update({
            "content_choice": dict(page[index]),
            "content_choice_history": history[-10:],
            "preview_parent": "suggestions",
            "pending_input": "",
        })
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "restore_content":
        history = list(state.get("content_choice_history") or [])
        if history:
            restored = dict(history.pop())
            state.update({
                "content_choice": restored,
                "content_choice_history": history,
                "screen": "preview",
                "preview_parent": "suggestions",
            })
        else:
            state["screen"] = "suggestions"
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action in {"manual_content", "edit_content"}:
        input_return_screen = (
            str(state.get("preview_parent") or "suggestions")
            if action == "edit_content"
            else str(state.get("screen") or "content_source")
        )
        state.update({
            "pending_input": "edit_content" if action == "edit_content" else "manual_content",
            "input_return_screen": input_return_screen,
        })
        save_video_trend2_state(context, state)
        return await safe_edit_or_send(
            query,
            "✍️ <b>Nhập nội dung video</b>\n\nMô tả mạch nội dung cần giữ. Hệ thống sẽ phân bổ đúng số cảnh đã chọn, không cắt cụt ý cuối.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([video_trend2_nav("vtrend|resume")]),
        )
    if action == "idea_catalog":
        interim = video_scene3_flow.default_state(
            product_type="video_trend",
            subject=str((state.get("selected_trend") or {}).get("title") or "Video theo trend"),
            aspect_ratio=str(state.get("aspect_ratio") or "9:16"),
        )
        interim.update({
            "source_product_id": "video_trend",
            "scene_count": max(1, min(20, safe_int(state.get("scene_count"), 1))),
            "aspect_ratio": str(state.get("aspect_ratio") or "9:16"),
            "trend_source": video_trend2_source_snapshot(state),
        })
        save_video_profile_studio_state(context, interim)
        return await video_flow7_open_idea_catalog_from_state(
            query,
            context,
            uid,
            interim,
            lang,
            back_callback="vtrend|idea_return",
        )
    if action == "idea_return":
        clear_developing_video_pending(uid)
        for key in (
            "video_idea_origin_product",
            "video_idea_source_media_refs",
            "video_idea_flow7_intake",
            "video_idea_return_callback",
        ):
            context.user_data.pop(key, None)
        state = video_trend2_open_screen(state, "content_source", parent="aspect_ratio")
        state.update({"pending_input": "", "screen": "content_source"})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "continue":
        canonical = video_trend2_canonical_state(context, state)
        context.user_data.pop(VIDEO_TREND2_STATE_KEY, None)
        return await video_profile_scene1_render(query, canonical, lang)
    if action == "resume":
        state["pending_input"] = ""
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    if action == "back":
        screen = str(state.get("screen") or "")
        screen_parents = dict(state.get("screen_parents") or {})
        if screen == "preview":
            parent = str(state.get("preview_parent") or "suggestions")
        else:
            parent = str(screen_parents.get(screen) or VIDEO_TREND2_PARENT.get(screen, "entry"))
        state.update({"screen": parent, "pending_input": ""})
        state = save_video_trend2_state(context, state)
        return await video_trend2_render(query, context, state, lang)
    return await video_trend2_render(query, context, state, lang)


@video_public_callback_failure_guard
async def handle_video_trend2_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        return await _handle_video_trend2_callback_impl(update, context)
    except Exception as exc:
        query = update.callback_query
        uid = query.from_user.id if query and query.from_user else 0
        state = video_trend2_state(context)
        logger.exception(
            "video_trend2_callback_failed | callback=%s screen=%s handler=handle_video_trend2_callback exception=%s user=%s keys=%s",
            sanitize_log_text(str(getattr(query, "data", "") or ""))[:120],
            sanitize_log_text(str(state.get("screen") or "entry"))[:80],
            type(exc).__name__,
            uid,
            sorted(str(key) for key in state.keys())[:40],
        )
        state["pending_input"] = ""
        state = save_video_trend2_state(context, state)
        try:
            return await video_trend2_render(query, context, state, get_user_language(uid) or "vi")
        except Exception:
            return await context.bot.send_message(
                chat_id=query.message.chat_id,
                text=(
                    "⚠️ Kho trend chưa đọc được dữ liệu ở lần này. Phiên lựa chọn vẫn được giữ; "
                    "anh/chị có thể quay lại Video theo trend hoặc tự nhập trend. Bot chưa tạo tác vụ và chưa trừ Xu."
                ),
                reply_markup=video_trend2_entry_keyboard(),
            )


def storyboard2_prepare_quick_image(user_id: int, board: dict, prompt: str, negative_prompt: str) -> dict:
    board = video_storyboard2.normalize_state(board)
    scene_index = int(board.get("active_scene_index") or 1)
    slot = str(board.get("active_slot") or "start")
    targets = video_storyboard2.image_targets(board)
    target_keys = [
        (int(item.get("scene_index") or 1), str(item.get("slot") or "start"))
        for item in targets
    ]
    try:
        target_index = target_keys.index((scene_index, slot)) + 1
    except ValueError:
        target_index = 1
    slot_label = "ảnh đầu" if slot == "start" else "ảnh cuối"
    scene = (board.get("scenes") or [])[scene_index - 1] if board.get("scenes") else {}
    image = dict(scene.get(f"{slot}_image") or {})
    return set_quick_image_flow(
        user_id,
        "prepared_prompt",
        prompt=prompt,
        negative_prompt=negative_prompt,
        prompt_source="storyboard2_scene_prompt",
        selected_topic=f"Storyboard cảnh {scene_index} · {slot_label}",
        original_request=str(board.get("content") or "Storyboard"),
        image_purpose="storyboard_scene",
        purpose_label=f"Storyboard cảnh {scene_index} · {slot_label}",
        style="storyboard continuity",
        suggested_ratio=str(board.get("aspect_ratio") or "9:16"),
        aspect_ratio=str(board.get("aspect_ratio") or "9:16"),
        ratio_back_target="vstory|assets_screen",
        source_flow="video_scene3",
        flow="storyboard",
        product="storyboard_prompt",
        owner="storyboard_image",
        session_id=str(board.get("storyboard_session_id") or ""),
        return_step="storyboard_asset_board",
        generation_state="planning",
        idea_id=str(image.get("idea_id") or board.get("selected_suggestion") or ""),
        revision=max(1, int(board.get("revision") or 1)),
        return_to="vstory|image_return",
        return_label="⬅️ Ảnh Storyboard",
        storyboard_scene_id=f"scene_{scene_index}",
        storyboard_scene_index=scene_index,
        storyboard_slot=slot,
        storyboard_prompt_version=max(1, int(image.get("prompt_version") or 1)),
        storyboard_target_index=target_index,
        storyboard_target_count=len(targets),
    )


def storyboard2_select_ai_image_target(user_id: int, board: dict, target_number: int | None = None) -> tuple[dict, dict]:
    board = video_storyboard2.normalize_state(board)
    targets = video_storyboard2.image_targets(board)
    if not targets:
        raise ValueError("storyboard_image_target_missing")
    if target_number is None:
        target = video_storyboard2.next_missing_image_target(board) or targets[0]
    else:
        index = max(1, min(len(targets), int(target_number)))
        target = targets[index - 1]
    scene_index = int(target.get("scene_index") or 1)
    slot = str(target.get("slot") or "start")
    board["active_scene_index"] = scene_index
    board["active_slot"] = slot
    prompt = video_storyboard2.image_prompt(board, scene_index, slot, 0)
    scene = dict(board["scenes"][scene_index - 1])
    image = dict(scene.get(f"{slot}_image") or {})
    image.update({
        "prompt": prompt["prompt"],
        "negative_prompt": prompt["negative_prompt"],
        "prompt_version": max(1, int(image.get("prompt_version") or 0) + 1),
    })
    scene[f"{slot}_image"] = image
    board["scenes"][scene_index - 1] = scene
    board = video_storyboard2.normalize_state(board)
    flow = storyboard2_prepare_quick_image(user_id, board, prompt["prompt"], prompt["negative_prompt"])
    return board, flow


async def _handle_storyboard2_callback_impl(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    uid = int(getattr(getattr(query, "from_user", None), "id", 0) or 0)
    callback_id = str(getattr(query, "id", "") or "")
    parts = str(getattr(query, "data", "") or "").split("|")
    action = str(parts[1] if len(parts) > 1 else "entry")
    value = str(parts[2] if len(parts) > 2 else "")
    if action not in STORYBOARD2_CALLBACK_ACTIONS:
        await query.answer(
            "Nút Storyboard này đã hết phiên. Hãy mở lại màn hiện tại.",
            show_alert=True,
        )
        return True
    outer = video_profile_studio_state(context)
    board = video_storyboard2.normalize_state(dict(outer.get("storyboard2") or {}))
    if callback_id and callback_id in set(board.get("processed_callback_ids") or []):
        try:
            await query.answer("Đã nhận lựa chọn này.")
        except Exception:
            pass
        return True
    if action == "entry" or not dict(outer.get("storyboard2") or {}):
        outer = storyboard2_new_outer_state(context)
        board = storyboard2_state(context)
    if callback_id:
        board["processed_callback_ids"] = (list(board.get("processed_callback_ids") or []) + [callback_id])[-100:]
        save_storyboard2_state(context, board, outer)

    # Actions below that can legitimately show an alert must not be answered
    # here first. Telegram accepts one answer per callback query; answering
    # twice is the source of repeated generic-X reports on stale/invalid taps.
    deferred_answer_actions = {
        "count_help", "count", "ratio", "profile_help", "profile_pick", "suggest_pick", "content_approve",
        "assets_done", "asset_ai_missing", "video_full", "video_done",
        "transition_pick", "addon", "finish", "content_config", "upload_use",
    }
    if action not in deferred_answer_actions:
        await query.answer()

    def persist(next_board: dict) -> dict:
        save_storyboard2_state(context, next_board)
        return video_storyboard2.normalize_state(next_board)

    if action == "entry":
        board = video_storyboard2.move(board, "entry", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action in {"start", "ai"}:
        fresh = storyboard2_fresh_board(entry_mode="ai")
        board = video_storyboard2.move(fresh, "count", push=True)
        return await storyboard2_render(query, context, persist(board))
    if action == "upload":
        fresh = storyboard2_fresh_board(entry_mode="existing")
        board = video_storyboard2.move(
            fresh,
            "await_storyboard_upload",
            push=True,
            awaiting_input="storyboard_upload",
        )
        return await storyboard2_render(query, context, persist(board))
    if action == "upload_review":
        board = video_storyboard2.move(board, "upload_review", push=False, awaiting_input="storyboard_upload")
        return await storyboard2_render(query, context, persist(board))
    if action == "upload_again":
        board = video_storyboard2.clear_uploaded_storyboard(board)
        board = video_storyboard2.move(
            board,
            "await_storyboard_upload",
            push=False,
            awaiting_input="storyboard_upload",
        )
        return await storyboard2_render(query, context, persist(board))
    if action == "upload_cancel":
        board = video_storyboard2.clear_uploaded_storyboard(board)
        board = video_storyboard2.move(board, "entry", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "upload_count":
        board = video_storyboard2.move(board, "await_upload_count", awaiting_input="upload_count")
        return await storyboard2_render(query, context, persist(board))
    if action == "upload_use":
        try:
            detected = safe_int(board.get("scene_count"), 0) or safe_int(board.get("detected_panel_count"), 0)
            board = video_storyboard2.set_detected_panel_count(board, detected)
        except ValueError:
            return await query.answer("Storyboard cần từ 2 đến 20 cảnh. Hãy sửa số cảnh trước.", show_alert=True)
        await query.answer()
        board = video_storyboard2.move(board, "ratio", awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "upload_panels":
        board = video_storyboard2.move(board, "upload_panels", awaiting_input="storyboard_upload")
        return await storyboard2_render(query, context, persist(board))
    if action in {"upload_panel_prev", "upload_panel_next"}:
        total = max(1, len(board.get("uploaded_storyboard_files") or []))
        current = max(1, safe_int(board.get("upload_panel_index"), 1))
        delta = -1 if action.endswith("prev") else 1
        board["upload_panel_index"] = ((current - 1 + delta) % total) + 1
        board = video_storyboard2.move(board, "upload_panels", push=False, awaiting_input="storyboard_upload")
        return await storyboard2_render(query, context, persist(board))
    if action == "help":
        board = video_storyboard2.move(board, "help")
        return await storyboard2_render(query, context, persist(board))
    if action == "count_screen":
        board = video_storyboard2.move(board, "count", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "count_help":
        return await query.answer(
            "Storyboard cần 2–20 cảnh. Thời lượng và giá mỗi cảnh được chọn ở bước Chất lượng gần cuối.",
            show_alert=True,
        )
    if action == "count":
        try:
            selected_count = int(value)
            if selected_count < video_storyboard2.MIN_PUBLIC_SCENES:
                raise ValueError("storyboard_public_scene_count_too_small")
            board = video_storyboard2.set_scene_count(board, selected_count)
        except (TypeError, ValueError):
            return await query.answer("Số cảnh cần từ 2 đến 20.", show_alert=True)
        await query.answer()
        board = video_storyboard2.move(board, "ratio")
        return await storyboard2_render(query, context, persist(board))
    if action == "count_custom":
        board = video_storyboard2.move(board, "await_count", awaiting_input="count")
        return await storyboard2_render(query, context, persist(board))
    if action == "ratio_screen":
        board = video_storyboard2.move(board, "ratio", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "ratio":
        ratio = value.replace("x", ":")
        try:
            board = video_storyboard2.set_ratio(board, ratio)
        except ValueError:
            return await query.answer("Tỉ lệ này chưa được hỗ trợ.", show_alert=True)
        entry_mode = str(board.get("entry_mode") or "guided")
        if entry_mode == "existing":
            try:
                board = video_storyboard2.apply_uploaded_storyboard(board)
            except ValueError as exc:
                return await query.answer(f"Chưa thể dùng storyboard: {str(exc)}", show_alert=True)
            board = video_storyboard2.move(board, "scene_review", awaiting_input="")
        else:
            board = video_storyboard2.move(board, "content_source", awaiting_input="")
        await query.answer()
        return await storyboard2_render(query, context, persist(board))
    if action == "idea_source":
        interim = video_scene3_flow.default_state(
            product_type="storyboard_prompt",
            subject=str(board.get("content") or "Storyboard từ Kho Ý tưởng video"),
            aspect_ratio=str(board.get("aspect_ratio") or "9:16"),
        )
        interim.update({
            "source_product_id": "storyboard_prompt",
            "scene_count": max(1, min(20, safe_int(board.get("scene_count"), 1))),
            "aspect_ratio": str(board.get("aspect_ratio") or "9:16"),
            "content_source": "idea_catalog",
            "content_mode": "suggestions",
            "storyboard2": board,
            "provider_called": False,
            "image_provider_called": False,
            "job_created": False,
            "outbox_created": False,
            "files_generated": 0,
            "wallet_mutations": 0,
            "xu_charged": 0,
        })
        interim = save_video_profile_studio_state(context, video_flow6.sync_scene_state(interim))
        return await video_flow7_open_idea_catalog_from_state(
            query,
            context,
            uid,
            interim,
            get_user_language(uid) or "vi",
            back_callback="vstory|idea_return",
        )
    if action == "idea_return":
        clear_developing_video_pending(uid)
        for key in (
            "video_idea_origin_product",
            "video_idea_source_media_refs",
            "video_idea_flow7_intake",
            "video_idea_return_callback",
        ):
            context.user_data.pop(key, None)
        board["content_source"] = ""
        board = video_storyboard2.move(board, "content_source", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "profiles_screen":
        board["content_source"] = "profiles"
        board = video_storyboard2.move(board, "profiles", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "profile_page":
        board["profile_page"] = max(1, safe_int(value, 1))
        board = video_storyboard2.move(board, "profiles", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "profile_help":
        return await query.answer(
            "Có 32 loại nội dung, chia thành nhiều trang. Chọn đúng một loại để nhận 20 gợi ý liên quan; loại đã chọn không tự ghi đè nội dung anh/chị sửa.",
            show_alert=True,
        )
    if action == "profile_pick":
        profile = next(
            (
                dict(item)
                for item in video_profile_catalog.PROFILE_SEEDS
                if bool(item.get("is_active", 1)) and str(item.get("profile_key") or "") == value
            ),
            {},
        )
        if not profile:
            return await query.answer("Loại nội dung này không còn khả dụng.", show_alert=True)
        await query.answer()
        board = video_storyboard2.set_profile(board, profile)
        board = video_storyboard2.move(board, "suggestions", awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "content_screen":
        board = video_storyboard2.move(board, "content_source", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "content_config":
        return await query.answer(
            f"Storyboard: {int(board.get('scene_count') or 0)} cảnh · tỉ lệ {str(board.get('aspect_ratio') or 'chưa chọn')}. Chưa tạo tác vụ và chưa trừ Xu.",
            show_alert=True,
        )
    if action == "content_manual":
        board["content_source"] = "manual"
        board = video_storyboard2.move(board, "await_content", awaiting_input="content")
        return await storyboard2_render(query, context, persist(board))
    if action == "content_suggest":
        target = "suggestions" if dict(board.get("profile") or {}) else "profiles"
        board = video_storyboard2.move(board, target, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "suggestions_screen":
        target = "suggestions" if dict(board.get("profile") or {}) else "profiles"
        board = video_storyboard2.move(board, target, push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "suggest_more":
        board = video_storyboard2.rotate_suggestions(board)
        board = video_storyboard2.move(board, "suggestions", push=False)
        return await storyboard2_render(query, context, persist(board))
    if action == "suggest_pick":
        suggestions = video_storyboard2.suggestion_page(board)
        choice = safe_int(value, 0)
        if choice < 1 or choice > len(suggestions):
            return await query.answer("Gợi ý này không còn hợp lệ.", show_alert=True)
        await query.answer()
        item = suggestions[choice - 1]
        board = video_storyboard2.apply_content(
            board,
            f"{item['title']}: {item['content']}",
            mode="suggestion",
        )
        board = video_storyboard2.move(board, "scene_review", awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "scene_screen":
        board = video_storyboard2.move(board, "scene_review", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action in {"scene_prev", "scene_next", "video_prev", "video_next"}:
        count = max(1, int(board.get("scene_count") or 1))
        current = int(board.get("active_scene_index") or 1)
        delta = -1 if action.endswith("prev") else 1
        board["active_scene_index"] = ((current - 1 + delta) % count) + 1
        screen = (
            "scene_review"
            if action.startswith("scene")
            else "video_prompts"
        )
        board = video_storyboard2.move(board, screen, push=False)
        return await storyboard2_render(query, context, persist(board))
    if action == "scene_edit":
        board = video_storyboard2.move(board, "await_scene_edit", awaiting_input="scene_content")
        return await storyboard2_render(query, context, persist(board))
    if action == "content_approve":
        try:
            board = video_storyboard2.approve_content(board)
        except ValueError:
            return await query.answer("Hãy bổ sung đủ nội dung cho mọi cảnh trước.", show_alert=True)
        await query.answer()
        board = video_storyboard2.move(board, "assets", awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "assets_screen" or action == "image_return":
        board = video_storyboard2.move(board, "assets", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "asset_view":
        targets = video_storyboard2.image_targets(board)
        active_target = (
            int(board.get("active_scene_index") or 1),
            str(board.get("active_slot") or "start"),
        )
        if targets and active_target not in {
            (int(item.get("scene_index") or 1), str(item.get("slot") or "start"))
            for item in targets
        }:
            board["active_scene_index"] = int(targets[0]["scene_index"])
            board["active_slot"] = str(targets[0]["slot"])
        board = video_storyboard2.move(board, "asset_overview", awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "asset_mode":
        try:
            board = video_storyboard2.set_asset_mode(board, value)
        except ValueError:
            board = video_storyboard2.move(board, "assets", push=False, awaiting_input="")
            return await storyboard2_render(query, context, persist(board))
        board = video_storyboard2.move(board, "assets", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "asset_upload_all":
        board = video_storyboard2.move(board, "await_image", awaiting_input="image_upload_batch")
        return await storyboard2_render(query, context, persist(board))
    if action in {"asset_prev", "asset_next"}:
        targets = video_storyboard2.image_targets(board)
        if targets:
            active_target = (
                int(board.get("active_scene_index") or 1),
                str(board.get("active_slot") or "start"),
            )
            target_keys = [
                (int(item.get("scene_index") or 1), str(item.get("slot") or "start"))
                for item in targets
            ]
            try:
                current_target_index = target_keys.index(active_target)
            except ValueError:
                current_target_index = 0
            delta = -1 if action == "asset_prev" else 1
            selected_target = targets[(current_target_index + delta) % len(targets)]
            board["active_scene_index"] = int(selected_target["scene_index"])
            board["active_slot"] = str(selected_target["slot"])
        board = video_storyboard2.move(board, "asset_overview", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "asset_replace":
        board = video_storyboard2.move(board, "await_image", awaiting_input="image_upload_replace")
        return await storyboard2_render(query, context, persist(board))
    if action == "asset_remove":
        board = video_storyboard2.remove_image(
            board,
            int(board.get("active_scene_index") or 1),
            str(board.get("active_slot") or "start"),
        )
        board = video_storyboard2.move(board, "asset_overview", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action in {"asset_move_prev", "asset_move_next"}:
        source_index = int(board.get("active_scene_index") or 1)
        target_index = source_index + (-1 if action == "asset_move_prev" else 1)
        if 1 <= target_index <= int(board.get("scene_count") or 0):
            board = video_storyboard2.move_image_to_scene(
                board,
                source_index,
                target_index,
                str(board.get("active_slot") or "start"),
            )
        board = video_storyboard2.move(board, "asset_overview", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "asset_ai_missing":
        if not video_storyboard2.next_missing_image_target(board):
            return await query.answer("Đã đủ ảnh theo chế độ Storyboard đang chọn.", show_alert=True)
        await query.answer()
        board, flow = storyboard2_select_ai_image_target(uid, board)
        persist(board)
        return await safe_edit_or_send(
            query,
            quick_image_prepared_prompt_text(flow, get_user_language(uid) or "vi"),
            parse_mode="HTML",
            reply_markup=quick_image_prepared_prompt_keyboard(
                get_user_language(uid) or "vi",
                state=flow,
                back_callback="vstoryimg|cancel",
            ),
        )
    if action in {
        "asset_upload", "asset_ai", "asset_no_end", "image_prompt_screen", "image_more", "image_custom",
        "image_negative", "image_full", "image_pick",
    }:
        # Public per-scene/per-slot controls were retired. Old Telegram
        # messages only return to the batch manager and never mutate assets.
        board = video_storyboard2.move(board, "assets", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "assets_done":
        summary = video_storyboard2.asset_summary(board)
        if not summary.get("ok"):
            missing = summary.get("missing_start") or summary.get("missing_required_end") or []
            return await query.answer(
                "Chưa đủ ảnh bắt buộc cho cảnh: " + ", ".join(str(item) for item in missing),
                show_alert=True,
            )
        await query.answer()
        board = video_storyboard2.compile_video_prompts(board)
        board = video_storyboard2.move(board, "video_prompts", awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "video_screen":
        board = video_storyboard2.move(board, "video_prompts", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "video_regenerate":
        board = video_storyboard2.compile_video_prompts(board)
        board = video_storyboard2.move(board, "video_prompts", push=False)
        return await storyboard2_render(query, context, persist(board))
    if action == "video_edit":
        board = video_storyboard2.move(board, "await_video_prompt", awaiting_input="video_prompt")
        return await storyboard2_render(query, context, persist(board))
    if action == "video_negative":
        board = video_storyboard2.move(board, "await_video_negative", awaiting_input="video_negative")
        return await storyboard2_render(query, context, persist(board))
    if action == "video_full":
        scene_index = int(board.get("active_scene_index") or 1)
        scene = board["scenes"][scene_index - 1]
        return await query.answer(str(scene.get("video_prompt") or "")[:1800], show_alert=True)
    if action == "video_done":
        if any(not str(scene.get("video_prompt") or "").strip() for scene in board.get("scenes") or []):
            return await query.answer("Còn cảnh chưa có câu lệnh video.", show_alert=True)
        await query.answer()
        board = video_storyboard2.build_transitions(board)
        board = video_storyboard2.move(board, "transitions", awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "transitions_screen":
        if not list(board.get("transitions") or []) and int(board.get("scene_count") or 0) > 1:
            board = video_storyboard2.build_transitions(board)
        board = video_storyboard2.move(board, "transitions", push=False)
        return await storyboard2_render(query, context, persist(board))
    if action in {"transition_prev", "transition_next"}:
        total = max(1, len(board.get("transitions") or []))
        current = int(board.get("transition_index") or 1)
        delta = -1 if action.endswith("prev") else 1
        board["transition_index"] = ((current - 1 + delta) % total) + 1
        return await storyboard2_render(query, context, persist(board))
    if action == "transition_pick":
        choice = safe_int(value, 0)
        if choice < 1 or choice > len(STORYBOARD2_TRANSITION_CHOICES):
            return await query.answer("Kiểu chuyển cảnh không hợp lệ.", show_alert=True)
        await query.answer()
        if board.get("transitions"):
            board = video_storyboard2.set_transition(
                board,
                int(board.get("transition_index") or 1),
                STORYBOARD2_TRANSITION_CHOICES[choice - 1],
            )
        return await storyboard2_render(query, context, persist(board))
    if action in {"transition_natural", "transition_done"}:
        if action == "transition_natural":
            board = video_storyboard2.build_transitions(board, "Cắt tự nhiên")
        # Shared Tail9 now owns Add-on and Review. Mark only the retired
        # Storyboard-specific Add-on screen complete so preflight can hand off.
        board["addons_ready"] = True
        board = persist(board)
        try:
            storyboard2_scene3_handoff(context, board)
        except ValueError as exc:
            return await query.answer(f"Chưa thể tiếp tục: {str(exc)}", show_alert=True)
        await query.answer()
        return await video_tail9_render(query, uid, context, "addon")
    if action == "addons_screen":
        board = video_storyboard2.move(board, "addons", push=False)
        return await storyboard2_render(query, context, persist(board))
    if action == "review_from_quality":
        board = video_storyboard2.move(board, "review", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "one_image_mode":
        board = video_storyboard2.set_asset_mode(board, "start_only")
        board = video_storyboard2.move(board, "assets", push=False, awaiting_input="")
        return await storyboard2_render(query, context, persist(board))
    if action == "addon":
        key = value
        if key not in {"dubbing", "subtitles", "source_audio", "music", "sfx", "logo"}:
            return await query.answer("Add-on này không hợp lệ.", show_alert=True)
        await query.answer()
        addons = dict(board.get("addons") or {})
        addons[key] = not bool(addons.get(key))
        board["addons"] = addons
        return await storyboard2_render(query, context, persist(board))
    if action in {"addon_done", "addon_skip"}:
        if action == "addon_skip":
            board["addons"] = {}
        board["addons_ready"] = True
        board = video_storyboard2.move(board, "review")
        return await storyboard2_render(query, context, persist(board))
    if action == "finish":
        try:
            storyboard2_scene3_handoff(context, board)
        except ValueError as exc:
            return await query.answer(f"Chưa thể hoàn thiện: {str(exc)}", show_alert=True)
        await query.answer()
        tail, owner, host = video_tail9_context(uid, context)
        tail = video_tail9.mark_addon_complete(tail)
        tail = video_tail9.mark_review_complete(tail)
        save_video_tail9_state(uid, context, tail, owner, host)
        return await video_tail9_render(query, uid, context, "quality")
    if action in deferred_answer_actions:
        return await query.answer("Nút Storyboard này đã hết phiên. Hãy mở lại màn hiện tại.", show_alert=True)
    return True


@video_public_callback_failure_guard
async def handle_storyboard2_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single guarded owner for every canonical Storyboard callback.

    A stale Telegram button must never fall through to the generic error
    handler and must not create a second error message.  The implementation
    records callback ids before mutating the board; this outer guard only
    acknowledges an unexpected route failure in-place.
    """
    query = update.callback_query
    try:
        return await _handle_storyboard2_callback_impl(update, context)
    except Exception as exc:
        logger.warning(
            "storyboard2_callback_failed | callback=%s exception=%s",
            sanitize_log_text(str(getattr(query, "data", "") or ""))[:160],
            type(exc).__name__,
        )
        try:
            await query.answer(
                "Nút này không còn phù hợp với phiên hiện tại. Dữ liệu Storyboard vẫn được giữ.",
                show_alert=True,
            )
        except Exception:
            pass
        return True


async def handle_storyboard2_legacy_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Old Storyboard buttons are read-only redirects to the canonical entry."""
    query = update.callback_query
    await query.answer("Đã mở Storyboard hiện tại.")
    # Legacy callbacks are read-only redirects.  Do not reset or mutate an
    # active Storyboard session just because an old Telegram message was
    # pressed.
    outer = video_profile_studio_state(context)
    if dict(outer.get("storyboard2") or {}):
        board = storyboard2_state(context)
    else:
        storyboard2_new_outer_state(context)
        board = storyboard2_state(context)
    return await storyboard2_render(query, context, board)


@video_public_callback_failure_guard
async def handle_video_trend2_legacy_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Redirect old Trend buttons without restoring or mutating their legacy state."""

    query = update.callback_query
    await query.answer("Đã mở luồng Video theo trend hiện tại.")
    readonly_state = video_trend2_state(context)
    readonly_state["screen"] = "entry"
    try:
        return await video_trend2_render(
            query,
            context,
            readonly_state,
            get_user_language(query.from_user.id) or "vi",
        )
    except Exception as exc:
        logger.warning(
            "video_trend2_legacy_redirect_failed | callback=%s exception=%s",
            sanitize_log_text(str(getattr(query, "data", "") or ""))[:120],
            type(exc).__name__,
        )
        return await context.bot.send_message(
            chat_id=query.message.chat_id,
            text=(
                "⚠️ Nút trend trong tin nhắn cũ đã hết phiên. Hãy mở lại Video theo trend từ Menu Video. "
                "Bot chưa tạo tác vụ và chưa trừ Xu."
            ),
            reply_markup=video_trend2_entry_keyboard(),
        )


