def video_ai_realistic_restore_legacy_content_mode(state: dict | None) -> dict:
    """Materialize only the completed pre-FLOW6 Video AI trạng thái content mode.

    FLOW6 made ``content_mode`` a required preflight field. Older Video AI chân
    thật sessions had already persisted the selected profile/content but not that
    new field, so the commercial tail rejected an otherwise complete plan. This
    compatibility shim deliberately refuses to infer a choice from a bare topic:
    it only repairs a state that contains proof of a completed content branch.
    """

    current = dict(state or {})
    raw_product = str(current.get("source_product_id") or current.get("product_type") or "").strip()
    if raw_product != "video_ai_real":
        return current

    flow_context = dict(current.get("video_flow_context") or {})
    existing_mode = str(current.get("content_mode") or flow_context.get("content_mode") or "").strip()
    if existing_mode in video_flow6.CONTENT_MODES:
        return video_flow6.sync_scene_state(current)

    source_fields = dict(current.get("source_fields") or flow_context.get("source_fields") or {})
    source = str(
        current.get("content_source")
        or source_fields.get("content_source")
        or flow_context.get("content_source")
        or ""
    ).strip()
    selection = dict(
        current.get("content_choice")
        or current.get("selected_suggestion")
        or flow_context.get("content_choice")
        or {}
    )
    profile = str(
        current.get("primary_profile_key")
        or current.get("primary_profile")
        or current.get("technical_profile")
        or flow_context.get("primary_profile_key")
        or ""
    ).strip()
    idea_id = str(current.get("idea_preset_id") or flow_context.get("idea_preset_id") or "").strip()
    manual_content = str(
        current.get("manual_content")
        or current.get("manual_script_raw")
        or current.get("script_text")
        or source_fields.get("manual_content")
        or ""
    ).strip()

    raw_plan = current.get("plan") or current.get("scene_plan") or {}
    plan = dict(raw_plan) if isinstance(raw_plan, dict) else {}
    planned_scenes = [item for item in plan.get("scenes") or [] if isinstance(item, dict)]
    completed_profile_plan = bool(planned_scenes and profile)

    if source in {"manual", "custom", "manual_content"} and manual_content:
        current["content_mode"] = "manual"
        current["content_source"] = "manual"
    elif source in {"profiles", "profile", "suggestions", "idea", "idea_catalog"} and (selection or idea_id):
        current["content_mode"] = "suggestions"
    elif selection and profile:
        current["content_mode"] = "suggestions"
        current["content_source"] = source or "profiles"
    elif idea_id:
        current["content_mode"] = "suggestions"
        current["content_source"] = source or "idea_catalog"
    elif completed_profile_plan:
        # A saved multi-scene plan plus its selected profile is sufficient proof
        # that this older Video AI session already passed content selection.
        # Do not use this branch for a bare topic or an incomplete plan.
        first_scene = dict(planned_scenes[0] or {})
        current["content_mode"] = "suggestions"
        current["content_source"] = source or "profiles"
        current["primary_profile_key"] = profile
        if not selection:
            current["content_choice"] = {
                "id": str(current.get("selected_suggestion_id") or profile or "completed_profile_plan"),
                "title": str(first_scene.get("title") or first_scene.get("goal") or current.get("subject") or profile),
                "concept": str(first_scene.get("summary") or first_scene.get("goal") or current.get("subject") or ""),
            }
    else:
        return current

    return video_flow6.sync_scene_state(current)


def video_tail12_compile_content_contract(state: dict | None, *, product_type: str = "") -> dict:
    """Persist one explicit, provider-free content contract before the shared tail.

    The commercial tail must never guess a completed content choice from a
    button label or a chat message.  Older product lanes persisted different
    structured fields, however, so this adapter consolidates only those fields
    into the FLOW6-compatible ``content_mode`` plus the richer public-tail
    contract used by review, invoice and exact Back routing.
    """

    current = dict(state or {})
    flow_context = dict(current.get("video_flow_context") or {})
    source_fields = dict(current.get("source_fields") or flow_context.get("source_fields") or {})
    requested_product = str(
        product_type
        or current.get("product_type")
        or current.get("source_product_id")
        or flow_context.get("product_id")
        or ""
    ).strip()
    requested_product = str(video_tail9.adapter_for(requested_product).get("adapter_key") or "").strip()
    if not requested_product:
        return current
    source = str(
        current.get("content_source")
        or source_fields.get("content_source")
        or flow_context.get("content_source")
        or ""
    ).strip()
    raw_plan = current.get("plan") or current.get("scene_plan") or flow_context.get("scene_plan") or {}
    plan = dict(raw_plan) if isinstance(raw_plan, dict) else {}
    scene_content = []
    for candidate in (
        current.get("per_scene_content"),
        current.get("idea_scene_contents"),
        current.get("idea_scene_content"),
        current.get("scene_drafts"),
        plan.get("scenes"),
    ):
        values = [dict(item) for item in list(candidate or []) if isinstance(item, dict)]
        if values:
            scene_content = values
            break
    selection = dict(
        current.get("content_choice")
        or current.get("selected_suggestion")
        or flow_context.get("content_choice")
        or {}
    )
    profile = str(
        current.get("primary_profile_key")
        or current.get("primary_profile")
        or current.get("technical_profile")
        or current.get("selected_profile")
        or flow_context.get("primary_profile_key")
        or ""
    ).strip()
    idea_id = str(
        current.get("idea_id")
        or current.get("idea_preset_id")
        or current.get("catalog_idea_id")
        or flow_context.get("idea_preset_id")
        or ""
    ).strip()
    selected_prompt = str(
        current.get("selected_prompt_text")
        or current.get("idea_selected_prompt")
        or current.get("selected_prompt")
        or flow_context.get("selected_prompt_text")
        or ""
    ).strip()
    if not selected_prompt:
        restored_prompts = []
        prompt_versions = dict(current.get("video_prompt_versions") or {})
        for scene_key in sorted(prompt_versions, key=lambda item: safe_int(item, 0)):
            entry = dict(prompt_versions.get(scene_key) or {})
            versions = [dict(item) for item in entry.get("versions") or [] if isinstance(item, dict)]
            active_version = safe_int(entry.get("active_version"), 0)
            active = next(
                (item for item in versions if safe_int(item.get("version"), 0) == active_version),
                versions[-1] if versions else {},
            )
            prompt_text = str(active.get("prompt") or active.get("provider_prompt") or "").strip()
            if prompt_text:
                restored_prompts.append(prompt_text)
        if not restored_prompts:
            for scene in scene_content:
                prompt_text = str(
                    scene.get("prompt")
                    or scene.get("video_prompt")
                    or scene.get("provider_prompt")
                    or ""
                ).strip()
                if prompt_text:
                    restored_prompts.append(prompt_text)
        selected_prompt = "\n\n".join(restored_prompts)
    manual_text = str(
        current.get("manual_content")
        or current.get("manual_script_raw")
        or current.get("script_text")
        or source_fields.get("manual_content")
        or ""
    ).strip()
    source_video_id = str(
        current.get("source_video_id")
        or current.get("source_file_id")
        or (current.get("source_video") or {}).get("file_id")
        or source_fields.get("source_video_id")
        or ""
    ).strip()
    storyboard_session_id = str(
        current.get("storyboard_session_id")
        or (current.get("storyboard2") or {}).get("session_id")
        or ""
    ).strip()
    scene_count = max(1, safe_int(current.get("scene_count") or flow_context.get("scene_count"), 1))
    ratio = str(current.get("aspect_ratio") or current.get("ratio") or flow_context.get("aspect_ratio") or "").strip()
    existing_mode = str(current.get("content_mode") or flow_context.get("content_mode") or "").strip()
    semantic_mode = ""
    flow_mode = existing_mode if existing_mode in video_flow6.CONTENT_MODES else ""

    if requested_product == "script_image_video" and manual_text:
        source = "manual"
        flow_mode = "manual"
        semantic_mode = "long_script"
        current["script_session_id"] = str(current.get("script_session_id") or current.get("video_session_id") or "")
        current["scene_count_confirmed"] = True
    elif requested_product == "storyboard_prompt" and (storyboard_session_id or scene_content or plan):
        source = "storyboard_plan"
        flow_mode = "manual"
        semantic_mode = "storyboard_plan"
        current["storyboard_session_id"] = storyboard_session_id or str(current.get("video_session_id") or "")
    elif requested_product == video_selfshot2.PRODUCT_ID and source_video_id:
        source = source or "manual"
        flow_mode = "manual"
        semantic_mode = "self_shot_scene_change"
        current["source_video_id"] = source_video_id
    elif requested_product == video_selfshot3.PRODUCT_ID and source_video_id:
        source = source or "manual"
        flow_mode = "manual"
        semantic_mode = "self_shot_cinematic_transform"
        current["source_video_id"] = source_video_id
    elif requested_product == "multi_scene_film" and (manual_text or scene_content or plan):
        source = source or "manual"
        flow_mode = "manual"
        semantic_mode = "long_video_plan"
    elif (idea_id or source == "idea_catalog") and (selected_prompt or scene_content or plan):
        source = "idea_catalog"
        flow_mode = "suggestions"
        semantic_mode = "idea_catalog"
    elif source in {"manual", "custom", "manual_content"} and manual_text:
        source = "manual"
        flow_mode = "manual"
        semantic_mode = "manual"
    elif source in {"content_profiles", "profiles", "profile", "suggestions"} and (selection or profile or scene_content):
        source = "content_profiles"
        flow_mode = "suggestions"
        semantic_mode = "content_profiles"
    elif selection and profile:
        source = "content_profiles"
        flow_mode = "suggestions"
        semantic_mode = "content_profiles"
    elif requested_product == "video_ai_real" and scene_content and (selected_prompt or plan):
        # Some last-green Video AI sessions persisted a complete scene plan and
        # selected prompt but predated FLOW6's explicit content fields.  This is
        # a compatibility repair for a completed plan, never an inference from
        # a bare topic or an unfinished entry screen.
        first_scene = dict(scene_content[0] or {})
        source = "content_profiles"
        flow_mode = "suggestions"
        semantic_mode = "content_profiles"
        profile = profile or "storytelling_life"
        if not selection:
            selection = {
                "id": str(current.get("selected_suggestion_id") or "restored_completed_plan"),
                "title": str(first_scene.get("title") or first_scene.get("goal") or current.get("subject") or "Nội dung đã chọn"),
                "concept": str(first_scene.get("summary") or first_scene.get("goal") or current.get("subject") or ""),
            }
        current["primary_profile"] = str(current.get("primary_profile") or profile)
        current["primary_profile_key"] = profile
    elif scene_content and (selected_prompt or plan):
        # Completed legacy plans from Trend/Script and the other Scene3
        # products did not always persist FLOW6's explicit content mode.  A
        # real scene plan plus a selected prompt is sufficient evidence to
        # restore its contract; never infer this from a bare topic.
        source = source or "content_profiles"
        flow_mode = "manual" if source in {"manual", "custom", "manual_content"} else "suggestions"
        semantic_mode = "manual" if flow_mode == "manual" else "content_profiles"
        if flow_mode == "suggestions":
            profile = profile or "storytelling_life"
            current["primary_profile"] = str(current.get("primary_profile") or profile)
            current["primary_profile_key"] = profile
            if not selection:
                first_scene = dict(scene_content[0] or {})
                selection = {
                    "id": str(current.get("selected_suggestion_id") or "restored_completed_plan"),
                    "title": str(first_scene.get("title") or first_scene.get("goal") or current.get("subject") or "Nội dung đã chọn"),
                    "concept": str(first_scene.get("summary") or first_scene.get("goal") or current.get("subject") or ""),
                }

    if not flow_mode:
        return current

    if not selection and idea_id:
        selection = {
            "id": idea_id,
            "title": str(current.get("idea_title") or current.get("subject") or "").strip(),
        }

    current.update({
        "product_type": requested_product,
        "flow_owner": str(
            current.get("idea_parent_flow_owner")
            or current.get("flow_owner")
            or video_tail9.adapter_for(requested_product).get("flow_owner")
            or "scene3"
        ),
        "parent_session_id": str(
            current.get("idea_parent_session_id")
            or current.get("parent_session_id")
            or current.get("video_session_id")
            or current.get("flow_session_id")
            or ""
        ),
        "scene_count": scene_count,
        "aspect_ratio": ratio or "9:16",
        "content_source": source,
        "content_mode": flow_mode,
        "canonical_content_mode": semantic_mode or flow_mode,
        "content_choice": selection,
        "content_revision": max(1, safe_int(current.get("content_revision") or current.get("plan_revision") or current.get("suggestion_version"), 1)),
        "per_scene_content": scene_content,
        "selected_prompt": selected_prompt,
        "selected_prompt_revision": max(
            1 if selected_prompt else 0,
            safe_int(current.get("selected_prompt_revision"), 0),
        ),
        "plan_status": "ready",
    })
    return video_flow6.sync_scene_state(current)


def video_tail9_hydrate_scene3_host(host: dict | None, session: dict | None) -> dict:
    """Restore the completed content contract before the shared commercial tail.

    Scene3 keeps its interactive screen state in ``context.user_data`` while
    the B14 handoff persists the final content contract in ``session.draft``.
    A tail re-render can therefore see an older screen state even though the
    user already chose content and a prompt.  Copy only missing fields from
    that persisted contract; a newer value on the current screen always wins.
    """

    current = dict(host or {})
    draft = dict((session or {}).get("draft") or {})
    contract = dict(draft.get("scene3_data_contract") or {})
    sources = (contract, draft)
    fields = (
        "product_type",
        "source_product_id",
        "flow_owner",
        "parent_session_id",
        "content_mode",
        "canonical_content_mode",
        "content_source",
        "content_choice",
        "selected_suggestion",
        "idea_preset_id",
        "idea_id",
        "idea_title",
        "selected_prompt",
        "selected_prompt_text",
        "idea_selected_prompt",
        "per_scene_content",
        "scene_drafts",
        "content_revision",
        "scene_count",
        "aspect_ratio",
        "selected_profile",
        "primary_profile",
        "primary_profile_key",
        "technical_profile",
        "manual_content",
        "manual_script_raw",
        "script_text",
        "parsed_script_scenes",
        "parsed_script_ranges",
        "script_coverage",
        "scene_count_confirmed",
        "script_source",
        "script_metadata",
        "script_sha256",
        "script_exact_match",
        "video_prompt_versions",
        "plan",
        "scene_plan",
        "source_video_id",
        "storyboard_session_id",
    )
    persisted_script = str(
        contract.get("manual_script_raw")
        or contract.get("script_text")
        or draft.get("manual_script_raw")
        or draft.get("script_text")
        or ""
    )
    current_script = str(current.get("manual_script_raw") or current.get("script_text") or "")
    script_identity_matches = bool(
        persisted_script and (not current_script or current_script == persisted_script)
    )
    script_identity_fields = {
        "script_text",
        "manual_script_raw",
        "parsed_script_scenes",
        "parsed_script_ranges",
        "script_coverage",
        "scene_count_confirmed",
        "script_source",
        "script_metadata",
        "script_sha256",
        "script_exact_match",
        "video_prompt_versions",
        "plan",
        "scene_plan",
    }
    for field in fields:
        if field in script_identity_fields and not script_identity_matches:
            continue
        existing = current.get(field)
        missing = existing in (None, "", [], {})
        if field in {"scene_count_confirmed", "script_exact_match"}:
            missing = not bool(existing)
        if not missing:
            continue
        for source in sources:
            value = source.get(field)
            if value not in (None, "", [], {}):
                current[field] = value
                break
    return current


def video_tail9_context(user_id: int, context) -> tuple[dict, str, dict]:
    """Return one scoped tail state and the canonical host that owns it."""

    uid = int(user_id or 0)
    edit_host = dict(get_video_editor_pending(uid) or {})
    edit_ready = bool(
        edit_host.get("edit_mode")
        and edit_host.get("source_file_id")
        and edit_host.get("inspection_complete")
    )
    session = get_video_session(uid)
    draft = dict(session.get("draft") or {})
    session_product = str(session.get("product_id") or draft.get("product_id") or "").strip()
    persisted_tail = dict(draft.get(VIDEO_TAIL9_STATE_KEY) or {})
    uiflow3_host = video_uiflow3_state(context)
    uiflow3_product = str(uiflow3_host.get("parent_product") or "")
    uiflow3_snapshot = dict(
        (uiflow3_host.get("legacy_compat") or {}).get("approved_snapshot") or {}
    )
    user_data = getattr(context, "user_data", None)
    uiflow3_tail_claim = dict(
        user_data.get(VIDEO_UIFLOW3_ACTIVE_TAIL_KEY) or {}
    ) if isinstance(user_data, dict) else {}
    uiflow3_tail_ready = bool(
        str(uiflow3_tail_claim.get("owner") or "") == "uiflow3"
        and str(uiflow3_tail_claim.get("draft_id") or "")
        == str(uiflow3_host.get("draft_id") or "")
        and str(uiflow3_tail_claim.get("product_type") or "") == uiflow3_product
        and uiflow3_product in VIDEO_UIFLOW3_SHARED_TAIL_PRODUCTS
        and str(uiflow3_snapshot.get("draft_id") or "")
        == str(uiflow3_host.get("draft_id") or "")
        and str(uiflow3_snapshot.get("parent_product") or "") == uiflow3_product
    )
    edit_route_marker = bool(
        session_product in {
            "video_edit", "video_ai_edit", "video_local_edit",
            video_editengine1.PRODUCT_TYPE,
        }
        or str(edit_host.get("flow_owner") or "") == "video_edit"
        or str(edit_host.get("product_type") or "") == video_editengine1.PRODUCT_TYPE
        or str(draft.get("flow_owner") or "") == "video_edit"
        or str(persisted_tail.get("video_product_type") or "") == video_editengine1.PRODUCT_TYPE
        or str(persisted_tail.get("video_flow_owner") or "") == "video_edit"
    )
    selfshot_products = {video_selfshot2.PRODUCT_ID, video_selfshot3.PRODUCT_ID}
    source_audio_available = None
    if uiflow3_tail_ready:
        owner = "uiflow3"
        host = uiflow3_host
        product_type = uiflow3_product
        session_id = str(uiflow3_snapshot.get("draft_id") or host.get("draft_id") or f"{uid}:{product_type}")
        revision = video_uiflow3_snapshot_revision(uiflow3_snapshot)
        scene_count = max(1, len(uiflow3_snapshot.get("scenes") or []))
        ratio = str((uiflow3_snapshot.get("format") or {}).get("ratio") or "9:16")
        estimated_duration = sum(
            max(1, safe_int(item.get("duration_target"), 8))
            for item in uiflow3_snapshot.get("scenes") or []
            if isinstance(item, dict)
        ) or scene_count * 8
        source_asset_ids = [
            str(item.get("file_id") or "")
            for item in video_uiflow3_snapshot_assets(uiflow3_snapshot)
            if str(item.get("file_id") or "")
        ]
    elif edit_ready or edit_route_marker:
        owner = "video_edit"
        host = edit_host
        product_type = video_editengine1.PRODUCT_TYPE
        session_id = str(host.get("edit_session_id") or f"{uid}:{product_type}")
        revision = max(1, safe_int(host.get("state_revision"), 1))
        scene_count = 1
        metadata = dict(host.get("source_metadata") or {})
        ratio = "keep"
        duration_ms = safe_int(host.get("source_duration_ms") or metadata.get("duration_ms"), 0)
        estimated_duration = max(
            1,
            safe_int(
                host.get("source_duration")
                or metadata.get("duration")
                or (duration_ms / 1000 if duration_ms else 0),
                1,
            ),
        )
        source_asset_ids = [str(host.get("source_file_id") or "")]
        source_audio_available = bool(metadata.get("has_audio") or safe_int(metadata.get("audio_streams"), 0) > 0)
    elif session_product in selfshot_products:
        owner = "session"
        host = draft
        product_type = session_product
        session_id = str(draft.get("session_id") or session.get("flow_session_id") or f"{uid}:{product_type}")
        revision = max(1, safe_int(draft.get("revision"), 1))
        scene_count = max(1, safe_int(draft.get("scene_count"), 1))
        ratio = str(draft.get("aspect_ratio") or (draft.get("source_analysis") or {}).get("aspect_ratio") or "9:16")
        estimated_duration = max(
            1,
            safe_int(
                draft.get("estimated_duration")
                or (draft.get("source_segment") or {}).get("duration_seconds")
                or (draft.get("source_analysis") or {}).get("duration_seconds"),
                scene_count * 8,
            ),
        )
        source_asset_ids = [
            str(value)
            for value in (
                (draft.get("source_video") or {}).get("file_id"),
                draft.get("source_file_id"),
            )
            if str(value or "").strip()
        ]
        source_analysis = dict(draft.get("source_analysis") or {})
        audio_manifest = dict(source_analysis.get("audio_manifest") or {})
        source_audio_available = safe_int(
            audio_manifest.get("stream_count") or source_analysis.get("audio_streams"),
            0,
        ) > 0
    else:
        owner = "scene3"
        host = video_profile_studio_state(context)
        host = video_tail9_hydrate_scene3_host(host, session)
        restored_host = video_ai_realistic_restore_legacy_content_mode(host)
        host = save_video_profile_studio_state(context, restored_host)
        requested = str(host.get("product_type") or host.get("source_product_id") or session_product or "")
        if not requested:
            return {}, "missing", host
        product_type = str(video_tail9.adapter_for(requested).get("adapter_key") or "")
        if not product_type:
            return {}, "missing", host
        compiled_host = video_tail12_compile_content_contract(host, product_type=product_type)
        if compiled_host != host:
            host = save_video_profile_studio_state(context, compiled_host)
        else:
            host = compiled_host
        session_id = str(host.get("video_session_id") or host.get("flow_session_id") or f"{uid}:{product_type}")
        revision = max(1, safe_int(host.get("plan_revision") or host.get("suggestion_version"), 1))
        scene_count = max(1, safe_int(host.get("scene_count"), 1))
        ratio = str(host.get("aspect_ratio") or "9:16")
        estimated_duration = scene_count * int(video_tail9.adapter_for(product_type).get("scene_duration_seconds") or 8)
        source_asset_ids = [
            str(item.get("file_id") or "")
            for item in list(((host.get("reference_assets") or {}).get("items") or []))
            if str(item.get("file_id") or "").strip()
        ]

    existing = (
        video_uiflow3_build_tail_state(host)
        if owner == "uiflow3"
        else dict(host.get(VIDEO_TAIL9_STATE_KEY) or draft.get(VIDEO_TAIL9_STATE_KEY) or {})
    )
    if video_tail9.scope_matches(
        existing,
        product_type=product_type,
        session_id=session_id,
        plan_revision=revision,
    ):
        tail = video_tail9.normalize_state(existing)
    else:
        tail = video_tail9.new_state(
            product_type=product_type,
            session_id=session_id,
            plan_revision=revision,
            scene_count=scene_count,
            ratio=ratio,
            estimated_duration=estimated_duration,
            source_asset_ids=source_asset_ids,
        )
        audio_plan = dict(host.get("audio_plan") or {})
        if audio_plan:
            audio = dict(tail.get("audio_config") or {})
            source_map = {
                "source_audio": "source",
                "dubbing": "voice",
                "music": "music",
                "sfx": "sfx",
                "subtitles": "subtitle",
            }
            volumes = dict(audio.get("volumes") or {})
            for tail_key, old_key in source_map.items():
                old = dict(audio_plan.get(old_key) or {})
                if old:
                    audio[tail_key] = bool(old.get("enabled"))
                    if tail_key in volumes:
                        volumes[tail_key] = max(0, min(200, safe_int(old.get("volume"), volumes[tail_key])))
            audio["volumes"] = volumes
            tail["audio_config"] = audio
        post = dict(host.get("postproduction_addons") or {})
        if post:
            audio = dict(tail.get("audio_config") or {})
            volumes = dict(audio.get("volumes") or {})
            for key in ("source_audio", "dubbing", "music", "sfx", "subtitles"):
                entry = dict(post.get(key) or {})
                if entry:
                    audio[key] = bool(entry.get("enabled"))
                    value = dict(entry.get("value") or {})
                    if key in volumes:
                        volumes[key] = max(0, min(200, safe_int(value.get("volume"), volumes[key])))
            audio["volumes"] = volumes
            tail["audio_config"] = audio
            logo_entry = dict(post.get("logo_image") or {})
            logo_value = dict(logo_entry.get("value") or {})
            tail["logo_config"] = {
                "enabled": bool(logo_entry.get("enabled") and logo_value.get("asset_file_id")),
                "asset_file_id": str(logo_value.get("asset_file_id") or ""),
                "position": str(logo_value.get("position") or ""),
            }
            watermark_entry = dict(post.get("watermark_text") or {})
            watermark_value = dict(watermark_entry.get("value") or {})
            tail["watermark_config"] = {
                "enabled": bool(watermark_entry.get("enabled") and watermark_value.get("text")),
                "text": str(watermark_value.get("text") or ""),
                "position": str(watermark_value.get("position") or ""),
                "opacity_percent": max(0, min(100, safe_int(watermark_value.get("opacity_percent"), 45))),
            }
        tail = video_tail9.normalize_state(tail)
    tail = video_tail9.apply_content_contract(tail, host)
    if owner == "scene3":
        tail = video_tail9.apply_planning_audio_contract(
            tail,
            dict(host.get("postproduction_addons") or {}),
            planning_complete=bool(host.get("scene_plan") or host.get("plan")),
        )
    if owner == "video_edit":
        persisted_job_id = safe_int(host.get("job_id"), 0)
        if persisted_job_id > 0:
            pricing = dict(tail.get("pricing_snapshot") or {})
            tail = video_tail9.recover_submission(tail, {
                "user_id": uid,
                "job_id": persisted_job_id,
                "status": str(host.get("status") or "queued"),
                "submitted_at": str(host.get("submitted_at") or ""),
                "invoice_id": str(tail.get("invoice_id") or ""),
                "quality_tier_id": str(tail.get("quality_tier_id") or ""),
                "package_id": str(tail.get("package_id") or ""),
                "scene_count": safe_int(tail.get("scene_count"), 1),
                "total_xu": safe_int(pricing.get("total_xu") or pricing.get("price_xu"), 0),
            })
    else:
        persisted_session = get_video_session(uid)
        persisted_draft = dict(persisted_session.get("draft") or {})
        persisted_job = dict(persisted_draft.get("b14_queue_job") or {})
        persisted_job_id = safe_int(
            persisted_draft.get("b14_queue_job_id") or persisted_job.get("id"),
            0,
        )
        persisted_tail_state = dict(persisted_draft.get(VIDEO_TAIL9_STATE_KEY) or {})
        recovery_session_id = str(
            persisted_draft.get("video_tail_submit_session_id")
            or persisted_tail_state.get("video_session_id")
            or persisted_session.get("flow_session_id")
            or ""
        ).strip()
        recovery_product = str(
            persisted_draft.get("video_tail_submit_product_type")
            or persisted_tail_state.get("video_product_type")
            or persisted_session.get("product_id")
            or ""
        ).strip()
        recovery_owner = str(
            persisted_draft.get("video_tail_submit_owner")
            or persisted_tail_state.get("video_flow_owner")
            or ""
        ).strip()
        same_recovery_scope = bool(
            recovery_session_id
            and recovery_session_id == str(tail.get("video_session_id") or "")
            and video_tail9.adapter_for(recovery_product).get("adapter_key")
            == video_tail9.adapter_for(str(tail.get("video_product_type") or "")).get("adapter_key")
            and (not recovery_owner or recovery_owner == str(tail.get("video_flow_owner") or ""))
        )
        if persisted_job_id > 0 and same_recovery_scope:
            persisted_invoice = dict(persisted_draft.get("b14_invoice") or {})
            tail = video_tail9.recover_submission(tail, {
                "user_id": uid,
                "job_id": persisted_job_id,
                "status": str(persisted_job.get("status") or "queued"),
                "submitted_at": str(persisted_job.get("created_at") or persisted_draft.get("submitted_at") or ""),
                "invoice_id": str(tail.get("invoice_id") or persisted_invoice.get("invoice_id") or ""),
                "quality_tier_id": str(
                    tail.get("quality_tier_id")
                    or persisted_invoice.get("quality_xu")
                    or persisted_draft.get("b14_quality_xu")
                    or ""
                ),
                "package_id": str(tail.get("package_id") or persisted_invoice.get("package_id") or ""),
                "scene_count": safe_int(
                    persisted_invoice.get("scene_count")
                    or persisted_draft.get("b14_scene_count")
                    or tail.get("scene_count"),
                    1,
                ),
                "total_xu": safe_int(
                    persisted_invoice.get("total_xu")
                    or persisted_invoice.get("price_xu")
                    or (tail.get("pricing_snapshot") or {}).get("total_xu"),
                    0,
                ),
                "invoice": persisted_invoice,
                "job": persisted_job,
            })
    if source_audio_available is not None:
        audio = dict(tail.get("audio_config") or {})
        audio["source_audio_available"] = bool(source_audio_available)
        if not source_audio_available:
            audio["source_audio"] = False
        tail["audio_config"] = audio
        tail = video_tail9.normalize_state(tail)
    return tail, owner, host


def save_video_tail9_state(user_id: int, context, tail: dict, owner: str, host: dict) -> dict:
    uid = int(user_id or 0)
    clean = video_tail9.normalize_state(tail)
    current = dict(host or {})
    current[VIDEO_TAIL9_STATE_KEY] = clean
    audio = dict(clean.get("audio_config") or {})
    volumes = dict(audio.get("volumes") or {})
    if owner == "video_edit":
        plan = dict(current.get("manual_edit_plan") or {})
        if audio.get("source_audio_available"):
            plan["volume"] = (
                max(0, min(200, safe_int(volumes.get("source_audio"), 100))) / 100.0
                if audio.get("source_audio")
                else 0.0
            )
        current["manual_edit_plan"] = plan
        current.update({
            "product_type": video_editengine1.PRODUCT_TYPE,
            "flow_owner": "video_edit",
            "engine_route": video_editengine1.ENGINE_ROUTE,
            "worker_owner": video_editengine1.OUTBOX_OWNER,
            "session_id": str(current.get("session_id") or current.get("edit_session_id") or ""),
            "revision": max(1, safe_int(current.get("revision") or current.get("state_revision"), 1)),
            "ratio": "keep",
            "audio_policy": str(current.get("audio_policy") or "preserve_if_present"),
            "source_has_audio": bool(audio.get("source_audio_available")),
            "addon_config": audio,
            "logo_config": {
                "logo": dict(clean.get("logo_config") or {}),
                "watermark": dict(clean.get("watermark_config") or {}),
            },
            "quality_tier_id": str(clean.get("quality_tier_id") or ""),
            "package_id": str(clean.get("package_id") or ""),
            "pricing_snapshot": dict(clean.get("pricing_snapshot") or {}),
        })
        save_video_edit_canonical_state(uid, current)
    elif owner == "uiflow3":
        branding = dict(current.get("branding") or {})
        logo = dict(clean.get("logo_config") or {})
        watermark = dict(clean.get("watermark_config") or {})
        if str(logo.get("asset_file_id") or "").strip():
            branding["logo"] = {
                **dict(branding.get("logo") or {}),
                "telegram_file_id": str(logo.get("asset_file_id") or ""),
                "file_id": str(logo.get("asset_file_id") or ""),
                "file_size": safe_int(logo.get("file_size"), 0),
                "position": str(logo.get("position") or ""),
            }
        else:
            branding.pop("logo", None)
        if str(watermark.get("text") or "").strip():
            branding["watermark"] = {
                **dict(branding.get("watermark") or {}),
                "text": str(watermark.get("text") or ""),
                "position": str(watermark.get("position") or ""),
                "opacity_percent": max(
                    0,
                    min(100, safe_int(watermark.get("opacity_percent"), 45)),
                ),
            }
        else:
            branding.pop("watermark", None)
        current["branding"] = branding
        save_video_uiflow3_state(context, current)
    elif owner == "scene3":
        save_video_profile_studio_state(context, current)
    elif clean.get("video_product_type") == video_selfshot2.PRODUCT_ID:
        plan = dict(current.get("audio_plan") or video_selfshot2.initial_draft()["audio_plan"])
        for old_key, tail_key in (("source", "source_audio"), ("voice", "dubbing"), ("music", "music"), ("sfx", "sfx"), ("subtitle", "subtitles")):
            item = dict(plan.get(old_key) or {})
            item["enabled"] = bool(audio.get(tail_key))
            if tail_key in volumes:
                item["volume"] = safe_int(volumes.get(tail_key), 100)
            plan[old_key] = item
        current["audio_plan"] = plan
        visuals = dict(current.get("visual_addons") or video_selfshot2.initial_draft()["visual_addons"])
        visuals["logo"] = {
            **dict(visuals.get("logo") or {}),
            "enabled": bool(clean.get("logo_config", {}).get("enabled")),
            "file_id": str(clean.get("logo_config", {}).get("asset_file_id") or ""),
            "position": str(clean.get("logo_config", {}).get("position") or ""),
        }
        visuals["watermark"] = {
            **dict(visuals.get("watermark") or {}),
            "enabled": bool(clean.get("watermark_config", {}).get("enabled")),
            "text": str(clean.get("watermark_config", {}).get("text") or ""),
            "position": str(clean.get("watermark_config", {}).get("position") or ""),
        }
        current["visual_addons"] = visuals
        save_video_selfshot2_draft(uid, current, step="selfshot2:tail")
    else:
        plan = dict(current.get("audio_plan") or video_selfshot3.initial_draft()["audio_plan"])
        for old_key, tail_key in (("source", "source_audio"), ("voice", "dubbing"), ("music", "music"), ("sfx", "sfx"), ("subtitle", "subtitles")):
            item = dict(plan.get(old_key) or {})
            item["enabled"] = bool(audio.get(tail_key))
            if tail_key in volumes:
                item["volume"] = safe_int(volumes.get(tail_key), 100)
            plan[old_key] = item
        current["audio_plan"] = plan
        save_video_selfshot3_draft(uid, current, step="selfshot3:tail")
    return clean


def video_tail9_apply_to_session(user_id: int, context, tail: dict, owner: str, host: dict) -> dict:
    uid = int(user_id or 0)
    clean = video_tail9.normalize_state(tail)
    if owner == "video_edit":
        audio = dict(clean.get("audio_config") or {})
        volumes = dict(audio.get("volumes") or {})
        addon_plan = video_b14_default_addon_plan("storytelling")
        addon_plan.update({
            "source_audio_enabled": bool(audio.get("source_audio")),
            "source_audio_volume_percent": safe_int(volumes.get("source_audio"), 100),
            "dub_enabled": bool(audio.get("dubbing")),
            "music_enabled": bool(audio.get("music")),
            "sfx_enabled": bool(audio.get("sfx")),
            "subtitle_enabled": bool(audio.get("subtitles")),
            "audio_ducking": bool(audio.get("ducking", True)),
            "audio_clipping_guard": True,
            "logo_enabled": bool((clean.get("watermark_config") or {}).get("enabled")),
            "logo_source": "text" if (clean.get("watermark_config") or {}).get("enabled") else "none",
            "logo_text": str((clean.get("watermark_config") or {}).get("text") or ""),
            "logo_position": str((clean.get("watermark_config") or {}).get("position") or ""),
        })
        draft = {
            VIDEO_TAIL9_STATE_KEY: clean,
            "b14_scene_count": 1,
            "b14_scene_count_selected": True,
            "b14_aspect_ratio": "keep",
            "b14_quality_xu": safe_int(clean.get("quality_tier_id"), 0),
            "b14_profile_id": "storytelling",
            "b14_addon_plan": addon_plan,
            "product_type": video_editengine1.PRODUCT_TYPE,
            "charge_policy": "after_valid_mp4_delivery",
            "provider_called": False,
            "job_created": False,
            "outbox_created": False,
            "xu_charged": 0,
        }
        return {
            "draft": draft,
            "product_id": video_editengine1.PRODUCT_TYPE,
            "topic": "Chỉnh sửa / Nâng cấp video",
            "aspect_ratio": "keep",
            "scene_count": 1,
        }
    if owner == "uiflow3":
        _prepared, session = video_uiflow3_prepare_b14_session(
            uid,
            host,
            owner_chat_id=safe_int(host.get("owner_chat_id"), 0),
            tail_state=clean,
            require_attestation=False,
        )
    elif owner == "scene3":
        session = video_profile_scene1_handoff(uid, host)
    else:
        session = get_video_session(uid)
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    audio = dict(clean.get("audio_config") or {})
    volumes = dict(audio.get("volumes") or {})
    draft.update({
        VIDEO_TAIL9_STATE_KEY: clean,
        "b14_scene_count": int(clean.get("scene_count") or 1),
        "b14_scene_count_selected": True,
        "b14_aspect_ratio": str(clean.get("ratio") or "9:16"),
        "b14_quality_xu": safe_int(clean.get("quality_tier_id"), 0),
        "video_tail_engine_route": str(clean.get("engine_route") or ""),
        "video_tail_executor_product_type": str(
            video_tail9.adapter_for(str(clean.get("video_product_type") or "")).get("executor_product_type") or ""
        ),
        "charge_policy": "after_valid_mp4_delivery",
        "provider_called": False,
        "job_created": False,
        "outbox_created": False,
        "xu_charged": 0,
    })
    postprocessing = dict(
        (clean.get("addon_config") or {}).get("postprocessing") or {}
    )

    def post_value(key: str) -> dict:
        entry = dict(postprocessing.get(key) or {})
        return dict(entry.get("value") or {}) if isinstance(entry.get("value"), dict) else {}

    dubbing_value = post_value("dubbing")
    music_value = post_value("music")
    sfx_value = post_value("sfx")
    subtitle_value = post_value("subtitles")
    music_source_value = str(
        music_value.get("source")
        or music_value.get("music_source")
        or music_value.get("music_source_choice")
        or ""
    ).strip().lower()
    music_is_ai = bool(
        music_value.get("paid_generation")
        or music_source_value
        in {"ai", "create_new", "planned_generation", "generated", "music_ai"}
    )
    sfx_source_value = str(
        sfx_value.get("source") or sfx_value.get("sfx_source") or ""
    ).strip().lower()
    subtitle_source_value = str(subtitle_value.get("source") or "").strip().lower()
    addon_plan = video_b14_default_addon_plan(str(draft.get("b14_profile_id") or "storytelling"))
    addon_plan.update({
        "voice_enabled": False,
        "voice_source": "none",
        "voice_volume_percent": safe_int(volumes.get("dubbing"), 100),
        "source_audio_enabled": bool(audio.get("source_audio")),
        "source_audio_volume_percent": safe_int(volumes.get("source_audio"), 100),
        "dub_enabled": bool(audio.get("dubbing")),
        "dub_source": str(
            dubbing_value.get("voice_source")
            or dubbing_value.get("dubbing_mode")
            or ("same_as_voice" if audio.get("dubbing") else "none")
        ),
        "dub_volume_percent": safe_int(volumes.get("dubbing"), 100),
        "music_enabled": bool(audio.get("music")),
        "music_source": (
            "ai"
            if audio.get("music") and music_is_ai
            else "uploaded"
            if audio.get("music") and music_source_value in {"user_asset", "uploaded", "media"}
            else "default"
            if audio.get("music")
            else "none"
        ),
        "music_volume_percent": safe_int(volumes.get("music"), 20),
        "sfx_enabled": bool(audio.get("sfx")),
        "sfx_source": (
            "ai"
            if sfx_value.get("paid_generation") or sfx_source_value in {"ai", "planned_generation", "generated", "sfx_ai"}
            else "library"
        ),
        "sfx_volume_percent": safe_int(volumes.get("sfx"), 35),
        "environment_audio_volume_percent": safe_int(volumes.get("environment"), 100),
        "audio_ducking": bool(audio.get("ducking", True)),
        "audio_clipping_guard": True,
        "subtitle_enabled": bool(audio.get("subtitles")),
        "subtitle_source": (
            "translated"
            if audio.get("subtitles") and (
                subtitle_value.get("translation")
                or subtitle_source_value in {"translated", "auto_translate", "translation"}
            )
            else "auto"
            if audio.get("subtitles")
            else "none"
        ),
        "logo_enabled": bool(clean.get("watermark_config", {}).get("enabled")),
        "logo_source": "text" if clean.get("watermark_config", {}).get("enabled") else "none",
        "logo_text": str(clean.get("watermark_config", {}).get("text") or ""),
        "logo_position": str(clean.get("watermark_config", {}).get("position") or ""),
    })
    draft["b14_addon_plan"] = addon_plan
    addon_quote = video_tail9_addon_quote(clean)
    draft["b14_addon_quote_items"] = deepcopy(addon_quote.get("items") or [])
    draft["b14_addon_quote_xu"] = safe_int(addon_quote.get("total_xu"), 0)
    logo = dict(clean.get("logo_config") or {})
    if logo.get("enabled") and logo.get("asset_file_id"):
        draft["product_video_logo_material"] = product_video_logo_material_config(
            logo_file_id=str(logo.get("asset_file_id") or ""),
            logo_position=str(logo.get("position") or ""),
            logo_enabled=True,
        )
    else:
        draft.pop("product_video_logo_material", None)
    session["draft"] = draft
    clean_product = str(clean.get("video_product_type") or "").strip()
    if clean_product:
        session["product_id"] = clean_product
    session["aspect_ratio"] = str(clean.get("ratio") or "9:16")
    session["scene_count"] = int(clean.get("scene_count") or 1)
    save_video_session(uid, session)
    return get_video_session(uid)


def video_tail9_prepare_submit_status(
    user_id: int,
    context,
    tail: dict,
    owner: str,
    host: dict,
    snapshot: dict | None = None,
) -> dict:
    """Persist a truthful no-job submit attempt for the canonical status panel."""

    uid = int(user_id or 0)
    clean = video_tail9.normalize_state(tail)
    preflight = dict(snapshot or {})
    preflight.setdefault("allowed", False)
    preflight.setdefault("blocker_code", "submit_not_started")
    preflight.setdefault("public_message", (
        "TOAN AAS chưa thể bắt đầu tạo video lúc này. Anh/chị vui lòng kiểm tra lại sau."
    ))
    clean.update(
        {
            "submit_attempted": True,
            "submit_preflight_snapshot": preflight,
            "status_stage": "invoice",
        }
    )
    clean = save_video_tail9_state(uid, context, clean, owner, host)
    if owner != "video_edit":
        session = video_tail9_apply_to_session(uid, context, clean, owner, host)
        draft = dict(session.get("draft") or {})
        draft.update(
            {
                VIDEO_TAIL9_STATE_KEY: video_tail9.normalize_state(clean),
                "b14_submit_attempted": True,
                "b14_submit_preflight_snapshot": preflight,
                "provider_called": False,
                "job_created": False,
                "outbox_created": False,
                "xu_charged": 0,
            }
        )
        session["draft"] = draft
        session["current_step"] = "b14_queue_status"
        save_video_session(uid, session)
    return clean


def video_tail9_preflight(user_id: int, context, tail: dict, owner: str, host: dict, quality: int = 300) -> dict:
    product = str(tail.get("video_product_type") or "")
    if product in {video_editengine1.PRODUCT_TYPE, video_editengine1.WORKER_JOB_TYPE}:
        runtime = dict(video_edit_worker_status_payload())
        report = dict(video_editengine1.preflight({**dict(host or {}), VIDEO_TAIL9_STATE_KEY: dict(tail or {})}, runtime))
    elif product == video_selfshot2.PRODUCT_ID:
        report = dict(video_selfshot2_preflight(host))
    elif product == video_selfshot3.PRODUCT_ID:
        report = dict(video_selfshot3_preflight(host))
    else:
        report = dict(video_flow6_preflight_for_state(int(user_id or 0), host, int(quality or 300)))
    ok = bool(report.get("ok") or report.get("ready"))
    reason = str(report.get("reason") or report.get("blocker") or ("" if ok else "engine_route_unavailable"))
    return {**report, "ok": ok, "reason": reason, "engine_route": str(tail.get("engine_route") or "")}


def video_tail9_runtime_only_blocker(value: str) -> bool:
    blocker = str(value or "").strip().lower()
    if blocker in {
        "package_unavailable",
        "execution_owner_unavailable",
        "worker_runtime_unavailable",
        "required_capability_unavailable",
        "long_series_public_not_ready",
        "long_form_video_in_development",
        "long_video_under_upgrade",
    }:
        return True
    return any(token in blocker for token in (
        "provider_unavailable",
        "provider_not_ready",
        "provider_freeze",
        "worker_unavailable",
        "worker_not_ready",
        "engine_unavailable",
        "engine_not_ready",
        "route_unavailable",
        "owner_unavailable",
        "owner_not_ready",
        "executor_unavailable",
        "capability_unavailable",
        "capability_missing",
    ))


def video_tail9_deferred_runtime_blocker(value: str) -> bool:
    blocker = str(value or "").strip().lower()
    return bool(
        video_tail9_runtime_only_blocker(blocker)
        or any(token in blocker for token in (
            "runtime_unavailable",
            "not_server_renderable",
            "renderer_missing",
        ))
    )


def video_tail9_commercial_preflight(
    user_id: int,
    context,
    tail: dict,
    owner: str,
    host: dict,
    quality: int = 300,
) -> dict:
    """Validate planning/package compatibility without binding UI to runtime health."""

    product_type = str(tail.get("video_product_type") or "")
    deferred_runtime_product = product_type in VIDEO_TAIL9_DEFERRED_RUNTIME_PRODUCTS
    skip_runtime_probe = bool(
        owner == "uiflow3"
        and product_type in VIDEO_UIFLOW3_DEFERRED_RUNTIME_PRODUCTS
    )
    if skip_runtime_probe:
        runtime = {
            "ok": False,
            "reason": "not_checked_before_final_confirmation",
            "blockers": [],
        }
    else:
        runtime = video_tail9_preflight(user_id, context, tail, owner, host, quality)
    compatibility = video_tail9.package_compatibility(
        product_type,
        scene_count=safe_int(tail.get("scene_count"), 1),
        ratio=str(tail.get("ratio") or "9:16"),
        quality_tier_id=safe_int(quality, 0),
    )
    runtime_blockers = [str(item) for item in runtime.get("blockers") or [] if str(item)]
    runtime_reason = str(runtime.get("reason") or runtime.get("blocker") or "")
    if runtime_reason and not runtime.get("ok") and runtime_reason not in runtime_blockers:
        runtime_blockers.append(runtime_reason)
    structural_blockers = [] if skip_runtime_probe else [
        item
        for item in runtime_blockers
        if not (
            video_tail9_runtime_only_blocker(item)
            or (
                deferred_runtime_product
                and video_tail9_deferred_runtime_blocker(item)
            )
        )
    ]
    if not compatibility.get("ok"):
        structural_blockers.extend(str(item) for item in compatibility.get("blockers") or [])
    structural_blockers = list(dict.fromkeys(item for item in structural_blockers if item))
    return {
        "ok": not structural_blockers,
        "reason": structural_blockers[0] if structural_blockers else "",
        "blocker": structural_blockers[0] if structural_blockers else "",
        "blockers": structural_blockers,
        "required_capability": str(compatibility.get("required_capability") or ""),
        "engine_route": str(tail.get("engine_route") or compatibility.get("engine_route") or ""),
        "runtime_ready": bool(runtime.get("ok")),
        "runtime_reason": runtime_reason,
        "runtime_blockers": runtime_blockers,
        "execution_enabled": bool(compatibility.get("execution_enabled")),
        "execution_blocker": str(compatibility.get("execution_blocker") or ""),
        "commercial_contract": compatibility,
        "side_effects": {
            "job": 0,
            "outbox": 0,
            "provider_calls": 0,
            "generated_files": 0,
            "wallet_mutations": 0,
            "xu_charged": 0,
        },
    }


def video_tail9_addon_text(tail: dict) -> str:
    audio = dict(tail.get("audio_config") or {})
    product_type = str(tail.get("video_product_type") or "")
    scenes = [dict(item) for item in tail.get("scene_content") or [] if isinstance(item, dict)]
    text_items = [
        dict(item)
        for item in (tail.get("addon_config") or {}).get("automatic_text") or []
        if isinstance(item, dict) and str(item.get("text") or "").strip()
    ]
    transition_count = sum(
        1
        for index, scene in enumerate(scenes[:-1])
        if str(scene.get("transition_out") or scenes[index + 1].get("transition_in") or "").strip()
    )
    selected_audio = [
        VIDEO_TAIL9_AUDIO_LABELS[key]
        for key in ("source_audio", "dubbing", "music", "sfx", "subtitles")
        if audio.get(key)
    ]
    quote = video_tail9_addon_quote(tail)
    quote_items = list(quote.get("items") or [])
    lines = [
        "🧰 <b>Add-on video</b>",
        "",
        f"• Sản phẩm: <b>{html.escape(VIDEO_TAIL9_PRODUCT_LABELS.get(str(tail.get('video_product_type') or ''), 'Video AI'))}</b>",
        f"• Âm thanh, giọng và phụ đề: <b>{html.escape(', '.join(selected_audio) or 'Không thêm')}</b>",
        f"• Logo/Watermark: <b>{html.escape(video_tail9_branding_public_summary(tail))}</b>",
    ]
    if product_type == "video_ai_real":
        lines.extend([
            f"• Chuyển cảnh: <b>{transition_count}/{max(0, len(scenes) - 1)} ranh giới đã chọn</b>",
            f"• Chữ trên video: <b>{len(text_items)} mục</b>",
        ])
    if quote_items:
        lines.extend(["", "<b>Chi phí Add-on đang chọn</b>"])
        for item in quote_items:
            lines.append(
                f"• {html.escape(str(item.get('label') or 'Add-on'))}: "
                f"<b>{xu_number(safe_int(item.get('price_xu'), 0))} Xu</b>"
            )
        lines.append(f"• Tổng Add-on: <b>{xu_number(safe_int(quote.get('total_xu'), 0))} Xu</b>")
    else:
        lines.extend(["", "• Tổng Add-on: <b>0 Xu</b>"])
    lines.extend([
        "",
        "Chọn từng mục cần bổ sung. Logo và watermark chỉ được lưu sau khi đã chọn vị trí.",
        "Khi đã đúng, bấm Hoàn tất Add-on để chuyển sang rà soát toàn bộ video.",
    ])
    return "\n".join(lines)


