def video_tail9_idea_prompt_state(tail: dict, host: dict) -> dict:
    """Recover the embedded Idea prompt owner from its exact parent draft."""

    current = dict(host or {})
    if not video_tail9_uses_idea_catalog(tail, current):
        return {}
    parent_handoff = video_idea_handoff.normalize_parent_handoff(
        current.get("idea_parent_handoff")
    )
    expected_product = str(tail.get("video_product_type") or "")
    if not parent_handoff or str(parent_handoff.get("origin_product") or "") != expected_product:
        return {}
    candidates = [
        dict(item)
        for item in current.get("idea_prompt_candidates") or []
        if isinstance(item, dict)
    ]
    if len(candidates) != 5:
        return {}
    current.update({
        "idea2": True,
        "flow": "videoidea",
        "step": "idea2_prompt",
        "idea_parent_handoff": parent_handoff,
        "idea_parent_product": str(parent_handoff.get("idea_parent_product") or expected_product),
        "idea_prompt_candidates": candidates,
        "idea_selected_prompt": str(
            current.get("idea_selected_prompt")
            or current.get("selected_prompt_text")
            or tail.get("selected_prompt")
            or ""
        ),
    })
    return current


def video_tail9_status_recovery_text(tail: dict) -> str:
    public_code = str(
        tail.get("public_processing_code")
        or (f"#{tail.get('job_id')}" if tail.get("job_id") else "-")
    )
    submit_preflight = dict(tail.get("submit_preflight_snapshot") or {})
    submit_failed = bool(
        tail.get("submit_attempted")
        and not str(tail.get("job_id") or "").strip()
    )
    if submit_failed:
        detail = str(submit_preflight.get("public_message") or "").strip()
        return (
            "🎬 <b>Trạng thái tạo video</b>\n\n"
            "❌ <b>FAIL - Chưa tạo được tác vụ</b>\n\n"
            f"• Mã xử lý: <code>{html.escape(public_code)}</code>\n"
            f"• Mã hóa đơn: <code>{html.escape(str(tail.get('invoice_id') or '-'))}</code>\n"
            "• Tiến độ: <b>0%</b>\n"
            "• Trạng thái: <b>Đã dừng - chưa tạo video</b>\n\n"
            f"{detail + chr(10) + chr(10) if detail else ''}"
            "Hóa đơn và toàn bộ cấu hình vẫn được giữ nguyên. Tài khoản chưa bị trừ Xu."
        )
    return (
        "🎬 <b>Trạng thái tạo video</b>\n\n"
        "ℹ️ <b>Chưa có tác vụ tạo video</b>\n"
        f"• Mã xử lý: <code>{html.escape(public_code)}</code>\n"
        f"• Mã hóa đơn: <code>{html.escape(str(tail.get('invoice_id') or '-'))}</code>\n"
        "• Trạng thái: <b>Chưa bắt đầu</b>\n\n"
        "Quay lại hóa đơn để xác nhận tạo video. Hệ thống chưa tạo tác vụ và chưa trừ Xu."
    )


def video_tail9_status_recovery_keyboard(tail: dict | None = None) -> InlineKeyboardMarkup:
    current = dict(tail or {})
    is_video_edit = str(current.get("video_product_type") or "") == video_editengine1.PRODUCT_TYPE
    menu_button = (
        ("🏠 Menu chính", "menu|main")
        if is_video_edit
        else ("🎬 Menu Video", "menu|main_video")
    )
    retry_callback = (
        "video_tail|confirm|submit"
        if current.get("submit_attempted") and not str(current.get("job_id") or "").strip()
        else "video_tail|confirm|status"
    )
    return video_scene3_keyboard([
        [("🔄 Kiểm tra trạng thái", retry_callback), ("🎬 Gửi video khác", "menu|main_video")],
        [("⬅️ Quay lại hóa đơn", "video_tail|confirm|back"), menu_button],
    ])


async def video_tail9_render_confirmed_status(query, context, uid: int, tail: dict, owner: str, host: dict):
    if owner == "video_edit":
        job_id = safe_int(tail.get("job_id") or host.get("job_id"), 0)
        job = get_local_worker_job(job_id) if job_id else {}
        if job:
            return await safe_edit_or_send(
                query,
                video_editor_job_status_text(job, get_user_language(uid) or "vi"),
                parse_mode="HTML",
                reply_markup=video_editor_status_keyboard(job_id, get_user_language(uid) or "vi"),
            )
        return await safe_edit_or_send(
            query,
            video_tail9_status_recovery_text(tail),
            parse_mode="HTML",
            reply_markup=video_tail9_status_recovery_keyboard(tail),
        )
    session = get_video_session(uid)
    persisted_job_id = safe_int(tail.get("job_id"), 0)
    if persisted_job_id > 0:
        draft = dict(session.get("draft") or {})
        if safe_int(draft.get("b14_queue_job_id"), 0) <= 0:
            draft["b14_queue_job_id"] = persisted_job_id
            draft[VIDEO_TAIL9_STATE_KEY] = video_tail9.normalize_state(tail)
            session["draft"] = draft
            session = save_video_session(uid, session)
    return await video_b14_send_or_edit_status_panel(
        query,
        context,
        session,
        None,
        uid,
        get_user_language(uid) or "vi",
    )


async def video_tail9_open_planning_audio(query, context, uid: int, tail: dict, owner: str, host: dict):
    """Open the product's existing audio owner without creating a tail duplicate."""

    lang = get_user_language(uid) or "vi"
    if owner == "uiflow3":
        current = video_uiflow3.normalize_state(host)
        current = video_uiflow3_go(current, "scene_assignment")
        current = video_uiflow3_open_view(current, "audio_options")
        legacy_compat = dict(current.get("legacy_compat") or {})
        legacy_compat["video_tail_return_to"] = "addon"
        current["legacy_compat"] = legacy_compat
        save_video_uiflow3_state(context, current)
        return await video_uiflow3_render(query, context, current)
    if owner == "scene3":
        state = video_profile_studio_step(
            context,
            host,
            "audio_plan",
            push=False,
            audio_plan_return_step="addon",
            video_tail_return_to="addon",
        )
        state = save_video_profile_studio_state(context, state)
        return await video_profile_scene1_render(query, state, lang)
    if owner == "video_edit":
        current = dict(get_video_editor_pending(uid) or host)
        update_video_editor_pending(
            uid,
            "audio",
            return_to="video_tail|summary|open",
            video_tail9=tail,
        )
        return await safe_edit_or_send(
            query,
            video_edit_audio_text(current, lang),
            parse_mode="HTML",
            reply_markup=video_edit_audio_keyboard(current, lang),
        )
    product_type = str(tail.get("video_product_type") or "")
    if product_type == video_selfshot2.PRODUCT_ID:
        current = {**dict(host or {}), "video_tail_return_to": "addon"}
        save_video_selfshot2_draft(uid, current, step="selfshot2:audio")
        return await video_selfshot2_render(query, uid, "audio", draft=current)
    if product_type == video_selfshot3.PRODUCT_ID:
        current = {**dict(host or {}), "video_tail_return_to": "addon"}
        save_video_selfshot3_draft(uid, current, step="selfshot3:audio")
        return await video_selfshot3_render(query, uid, "audio", draft=current)
    return await video_tail9_render(query, uid, context, "addon")


async def video_tail9_render(query, user_id: int, context, screen: str):
    tail, owner, host = video_tail9_context(user_id, context)
    if owner == "missing" or not str(tail.get("video_product_type") or ""):
        return await safe_edit_or_send(
            query,
            "⏰ Phiên video không còn đúng ngữ cảnh. Hãy mở lại đúng sản phẩm từ Menu Video; bot chưa tạo tác vụ và chưa trừ Xu.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("🎬 Menu Video", callback_data="menu|main_video"),
            ]]),
        )
    if screen == "addon":
        if owner == "video_edit":
            return await video_tail9_render(query, user_id, context, "review")
        if str(tail.get("video_product_type") or "") not in VIDEO_TAIL9_SHARED_UI_PRODUCTS:
            return await video_tail9_render(query, user_id, context, "review")
        tail["status_stage"] = "audio_addons"
        tail["branding_return_to"] = "addon"
        tail["branding_back_to"] = "addon"
        save_video_tail9_state(user_id, context, tail, owner, host)
        return await safe_edit_or_send_long_html(
            query,
            video_tail9_addon_text(tail),
            reply_markup=video_tail9_addon_keyboard(tail),
        )
    if screen == "review":
        if owner == "video_edit":
            tail["status_stage"] = "review"
            save_video_tail9_state(user_id, context, tail, owner, host)
            return await safe_edit_or_send(
                query,
                video_tail9_video_edit_review_text(tail, host),
                parse_mode="HTML",
                reply_markup=video_tail9_video_edit_review_keyboard(),
            )
        if (
            str(tail.get("video_product_type") or "") in VIDEO_TAIL9_SHARED_UI_PRODUCTS
            and not video_tail9.addon_complete(tail)
        ):
            return await video_tail9_render(query, user_id, context, "addon")
        tail = video_tail9.prepare_review(tail)
        save_video_tail9_state(user_id, context, tail, owner, host)
        return await safe_edit_or_send_long_html(
            query,
            video_tail9_review_text(tail),
            reply_markup=video_tail9_review_keyboard(tail),
        )
    if screen == "audio":
        return await video_tail9_open_planning_audio(
            query,
            context,
            int(user_id),
            tail,
            owner,
            host,
        )
    if screen == "logo":
        if not video_tail9.content_contract_ready(tail):
            return await video_tail9_render(query, user_id, context, "review")
        tail["status_stage"] = "logo_watermark"
        save_video_tail9_state(user_id, context, tail, owner, host)
        return await safe_edit_or_send(query, video_tail9_logo_text(tail), parse_mode="HTML", reply_markup=video_tail9_logo_keyboard(tail))
    if screen == "logo_confirm":
        target = video_tail9_pending_brand_target(tail)
        if not target:
            return await video_tail9_render(query, user_id, context, "logo")
        tail["status_stage"] = "logo_watermark"
        save_video_tail9_state(user_id, context, tail, owner, host)
        return await safe_edit_or_send(
            query,
            video_tail9_brand_confirm_text(tail),
            parse_mode="HTML",
            reply_markup=video_tail9_brand_confirm_keyboard(target, tail),
        )
    if screen == "summary":
        if owner == "video_edit":
            tail = video_tail9.prepare_summary(tail)
            tail["status_stage"] = "summary"
            save_video_tail9_state(user_id, context, tail, owner, host)
            return await safe_edit_or_send(
                query,
                video_tail9_summary_text(tail),
                parse_mode="HTML",
                reply_markup=video_tail9_summary_keyboard(tail),
            )
        if str(tail.get("video_product_type") or "") in VIDEO_TAIL9_SHARED_UI_PRODUCTS:
            return await video_tail9_render(query, user_id, context, "review")
        tail = video_tail9.prepare_summary(tail)
        tail["status_stage"] = "summary"
        save_video_tail9_state(user_id, context, tail, owner, host)
        return await safe_edit_or_send_long_html(
            query,
            video_tail9_summary_text(tail),
            reply_markup=video_tail9_summary_keyboard(tail),
        )
    if screen == "quality":
        required_screen = video_tail9.next_required_screen(tail)
        if required_screen:
            return await video_tail9_render(query, user_id, context, required_screen)
        capability = video_tail9_commercial_preflight(user_id, context, tail, owner, host)
        catalog = video_tail9_catalog_report(tail, capability)
        selection_ready = bool(
            capability.get("ok")
            and (owner != "video_edit" or capability.get("runtime_ready"))
        )
        tail = video_tail9.set_capability(tail, capability)
        tail["status_stage"] = "quality"
        save_video_tail9_state(user_id, context, tail, owner, host)
        if not selection_ready or not catalog.get("ok"):
            return await safe_edit_or_send(
                query,
                video_tail9_public_blocker_text(),
                parse_mode="HTML",
                reply_markup=video_tail9_public_blocker_keyboard(),
            )
        quality_text = video_tail9_quality_text(tail, capability, catalog)
        quality_keyboard = video_tail9_quality_keyboard(tail, catalog, selectable=selection_ready)
        if owner == "video_edit":
            return await safe_edit_or_send(
                query,
                quality_text,
                parse_mode="HTML",
                reply_markup=quality_keyboard,
            )
        return await safe_edit_or_send_long_html(
            query,
            quality_text,
            reply_markup=quality_keyboard,
        )
    if screen == "invoice":
        session = video_tail9_apply_to_session(user_id, context, tail, owner, host)
        invoice_text = video_tail9_invoice_text(tail, session, user_id, get_user_language(user_id) or "vi")
        invoice_keyboard = video_tail9_invoice_keyboard()
        if owner == "video_edit":
            return await safe_edit_or_send(
                query,
                invoice_text,
                parse_mode="HTML",
                reply_markup=invoice_keyboard,
            )
        return await safe_edit_or_send_long_html(
            query,
            invoice_text,
            reply_markup=invoice_keyboard,
        )
    if screen == "confirm":
        return await safe_edit_or_send(
            query,
            video_tail9_confirm_text(tail, user_id),
            parse_mode="HTML",
            reply_markup=video_tail9_confirm_keyboard(),
        )
    return await video_tail9_render(query, user_id, context, "review")


def video_tail9_callback_guard(callback_handler):
    """Keep pre-confirm tail callback failures inside their exact product route."""

    async def guarded(update: Update, context: ContextTypes.DEFAULT_TYPE):
        try:
            return await callback_handler(update, context)
        except ApplicationHandlerStop:
            raise
        except Exception:
            query = getattr(update, "callback_query", None)
            callback_data = str(getattr(query, "data", "") or "")
            logger.exception("video_tail_callback_failed callback=%s", callback_data)
            if not query:
                return True

            try:
                # The recovery renderer below keeps the user inside the same
                # product route.  Do not add a second generic error alert.
                await query.answer()
            except Exception:
                pass

            if callback_data == "video_tail|confirm|submit":
                try:
                    uid = int(query.from_user.id)
                    tail, owner, host = video_tail9_context(uid, context)
                    if str(tail.get("job_id") or "").strip():
                        return await video_tail9_render_confirmed_status(
                            query,
                            context,
                            uid,
                            tail,
                            owner,
                            host,
                        )
                except Exception:
                    logger.exception(
                        "video_tail_submit_status_recovery_failed callback=%s",
                        callback_data,
                    )
                try:
                    tail, owner, host = video_tail9_context(
                        int(query.from_user.id), context
                    )
                    tail = video_tail9_prepare_submit_status(
                        int(query.from_user.id),
                        context,
                        tail,
                        owner,
                        host,
                        snapshot={
                            "allowed": False,
                            "blocker_code": "submit_callback_failed",
                            "public_message": "TOAN AAS chưa thể bắt đầu tạo video lúc này.",
                        },
                    )
                    return await video_tail9_render_confirmed_status(
                        query,
                        context,
                        int(query.from_user.id),
                        tail,
                        owner,
                        host,
                    )
                except Exception:
                    return True

            section = callback_data.split("|")[1] if callback_data.count("|") >= 1 else "review"
            screen = {
                "audio": "audio",
                "logo": "logo",
                "quality": "quality",
                "summary": "summary",
                "confirm": "invoice",
            }.get(section, "review")
            try:
                return await video_tail9_render(query, int(query.from_user.id), context, screen)
            except Exception:
                logger.exception("video_tail_callback_recovery_failed callback=%s", callback_data)
                back_callback = {
                    "audio": "video_tail|audio|open",
                    "logo": "video_tail|logo|open",
                    "quality": "video_tail|quality|open",
                    "summary": "video_tail|summary|open",
                    "confirm": "video_tail|confirm|back",
                }.get(section, "video_tail|review|open")
                try:
                    return await safe_edit_or_send(
                        query,
                        video_tail9_public_blocker_text(),
                        parse_mode="HTML",
                        reply_markup=video_scene3_keyboard([[("⬅️ Quay lại", back_callback), ("🏠 Menu chính", "menu|main")]]),
                    )
                except Exception:
                    return True

    guarded.__name__ = getattr(callback_handler, "__name__", "handle_video_tail_callback")
    return guarded


async def video_edit_legacy_tail_compatibility(query, uid: int, tail: dict, host: dict):
    """Move an old Video Edit commercial-tail button into the local-free flow."""

    lang = get_user_language(uid) or "vi"
    persisted_state = dict(get_video_editor_pending(uid) or {})
    expected_state = video_editor_state_snapshot(persisted_state)
    state = dict(persisted_state or host or {})
    job_id = safe_int(state.get("job_id") or (tail or {}).get("job_id"), 0)
    if job_id > 0:
        job = get_local_worker_job(job_id)
        if (
            job
            and str(job.get("job_type") or "") == video_editengine1.WORKER_JOB_TYPE
            and str(job.get("user_id") or "") == str(uid)
        ):
            return await safe_edit_or_send(
                query,
                video_editor_job_status_text(job, lang),
                parse_mode="HTML",
                reply_markup=video_editor_status_keyboard(job_id, lang),
            )
    if not state.get("source_file_id") or not state.get("inspection_complete"):
        return await safe_edit_or_send(
            query,
            "ℹ️ Quy trình xác nhận cũ đã được thay bằng chỉnh sửa local miễn phí. "
            "Hãy mở lại công cụ và gửi video nguồn; hệ thống chưa tạo tác vụ và chưa trừ Xu.",
            reply_markup=video_edit_lane_upload_keyboard("manual_edit", lang),
        )

    edit_mode = video_edit_state_machine.normalize_edit_mode(state.get("edit_mode")) or "manual_edit"
    entry_parent = video_edit_state_machine.safe_parent_callback(
        state.get("entry_parent_callback")
        or video_edit_state_machine.lane_callback(edit_mode)
    )
    tool = "split" if str(state.get("selected_tool") or "") == "split" and state.get("split_ranges") else "manual"
    review_revision = max(
        1,
        safe_int(state.get("state_revision"), 0),
        safe_int(state.get("review_revision"), 0),
    ) + 1
    candidate = dict(state)
    candidate.pop("step", None)
    candidate.pop("created_at_ts", None)
    candidate.update({
        "screen_id": "review",
        "current_screen": "review",
        "status": "review_ready",
        "selected_tool": tool,
        "edit_mode": edit_mode,
        "entry_parent_callback": entry_parent,
        "return_to": video_edit_review_return_action(state),
        "provider_call": False,
        "state_revision": review_revision,
        "review_revision": review_revision,
    })
    current = {"step": "review", **candidate}

    async def commit_review():
        committed, current_state = compare_and_set_video_editor_pending(
            uid,
            expected_state,
            "review",
            **candidate,
        )
        if not committed:
            await rerender_video_editor_after_stale_commit(
                query,
                current_state,
                lang,
            )
        return current_state

    return await safe_edit_or_send(
        query,
        video_local_confirmation_text(current, lang, stage="review"),
        parse_mode="HTML",
        reply_markup=video_local_review_keyboard(tool, lang, current),
        post_render=commit_review,
    )


@video_tail9_callback_guard
async def handle_video_tail_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    uid = int(query.from_user.id)
    parts = str(query.data or "").split("|")
    section = parts[1] if len(parts) > 1 else "review"
    action = parts[2] if len(parts) > 2 else "open"
    argument = parts[3] if len(parts) > 3 else ""
    extra = parts[4] if len(parts) > 4 else ""
    tail, owner, host = video_tail9_context(uid, context)
    if owner == "missing":
        lang = get_user_language(uid) or "vi"
        await query.answer(
            "Phiên video cũ đã hết hạn. Vui lòng chọn lại sản phẩm.",
            show_alert=True,
        )
        return await safe_edit_or_send(
            query,
            menu_text_main_video_i18n(lang),
            parse_mode="HTML",
            reply_markup=main_video_keyboard(lang),
        )
    tail, claimed = video_tail9.claim_callback(tail, str(getattr(query, "id", "") or ""))
    if not claimed:
        return
    if owner == "video_edit":
        transactional_token = _VIDEO_EDIT_CALLBACK_TRANSACTIONAL.set(True)
        answered_token = _VIDEO_EDIT_CALLBACK_ANSWERED.set(False)
        try:
            expected_host = video_editor_state_snapshot(host)
            claimed_fields = dict(expected_host)
            claimed_step = str(claimed_fields.pop("step", "") or "review")
            claimed_fields.pop("created_at_ts", None)
            claimed_fields[VIDEO_TAIL9_STATE_KEY] = tail
            committed, claimed_host = compare_and_set_video_editor_pending(
                uid,
                expected_host,
                claimed_step,
                **claimed_fields,
            )
            if not committed:
                await rerender_video_editor_after_stale_commit(
                    query,
                    claimed_host,
                    get_user_language(uid) or "vi",
                )
                return True
            try:
                return await video_edit_legacy_tail_compatibility(
                    query, uid, tail, claimed_host
                )
            except Exception:
                logger.exception("video_edit_legacy_tail_compatibility_failed uid=%s", uid)
                # The old shared callback is owned by Video Edit.  Never let its
                # recovery failure continue into the commercial Product Video tail.
                if not _VIDEO_EDIT_CALLBACK_ANSWERED.get():
                    try:
                        await query.answer(
                            "Không thể cập nhật màn chỉnh sửa lúc này. Kế hoạch cũ vẫn được giữ.",
                            show_alert=True,
                        )
                        _VIDEO_EDIT_CALLBACK_ANSWERED.set(True)
                    except Exception:
                        pass
                return True
        finally:
            _VIDEO_EDIT_CALLBACK_ANSWERED.reset(answered_token)
            _VIDEO_EDIT_CALLBACK_TRANSACTIONAL.reset(transactional_token)
    save_video_tail9_state(uid, context, tail, owner, host)
    if isinstance(getattr(context, "user_data", None), dict):
        context.user_data.pop(VIDEO_TAIL9_TEXT_INPUT_KEY, None)
    if section != "confirm":
        await query.answer()
    if tail.get("final_confirmed") and section != "confirm":
        return await video_tail9_render_confirmed_status(query, context, uid, tail, owner, host)
    if section == "addon":
        if action == "back" and owner == "uiflow3":
            current = video_uiflow3.normalize_state(host)
            current[VIDEO_TAIL9_STATE_KEY] = tail
            current = video_uiflow3_clear_transient(current, keep_return=False)
            current["navigation"]["current_step"] = "summary"
            current["navigation"]["return_to"] = None
            current = video_uiflow3.begin_summary_edit(current, "prompts")
            legacy_compat = dict(current.get("legacy_compat") or {})
            legacy_compat["video_tail_return_to"] = "addon"
            current["legacy_compat"] = legacy_compat
            if isinstance(getattr(context, "user_data", None), dict):
                context.user_data.pop(VIDEO_UIFLOW3_ACTIVE_TAIL_KEY, None)
            save_video_uiflow3_state(context, current)
            return await video_uiflow3_render(query, context, current)
        if action in {"scenes", "edit_scenes", "prompts"} and owner == "uiflow3":
            target_step = "prompts" if action == "prompts" else "scene_plan"
            current = video_uiflow3.normalize_state(host)
            current[VIDEO_TAIL9_STATE_KEY] = tail
            current = video_uiflow3_clear_transient(current, keep_return=False)
            current["navigation"]["current_step"] = "summary"
            current["navigation"]["return_to"] = None
            current = video_uiflow3.begin_summary_edit(current, target_step)
            if action == "edit_scenes":
                current = video_uiflow3_open_view(current, "scene_plan_list")
            legacy_compat = dict(current.get("legacy_compat") or {})
            legacy_compat["video_tail_return_to"] = "addon"
            current["legacy_compat"] = legacy_compat
