def translation_auto_translate_enabled(user_id=None) -> bool:
    if user_id is None:
        return False
    try:
        modes = ensure_user_modes(user_id)
    except Exception:
        modes = {}
    return bool(str((modes or {}).get("translate_mode_target") or "").strip())

