DEVELOPING_VIDEO_FLOWS = {"selfscene", "longvideo", "storypack", "videoidea", "promptvideo", "imagevideo", "videoref"}

VIDEO_SESSION_TTL_SECONDS = 45 * 60
VIDEO_SESSION_STACK_LIMIT = 16

def video_value_present(value) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, tuple, set, dict)):
        return bool(value)
    return True

def video_session_key(user_id) -> str:
    return f"video_session:{user_id}"

def default_video_session(user_id) -> dict:
    now_ts = time.time()
    return {
        "pending_action": "video_session",
        "video_session_id": hashlib.sha256(f"{user_id}:{now_ts}".encode()).hexdigest()[:32],
        "user_id": str(user_id),
        "product_id": "",
        "current_step": "",
        "previous_step": "",
        "source_media_ref": "",
        "topic": "",
        "platform": "",
        "aspect_ratio": "",
        "style": "",
        "package_id": "",
        "prompt_bundle_id": "",
        "selected_addons": [],
        "provider_job_id": "",
        "invoice_id": "",
        "return_to": "",
        "entry_flow": "",
        "current_flow": "",
        "current_screen": "",
        "screen_stack": [],
        "draft": {},
        "order": {},
        "created_at_ts": now_ts,
        "updated_at_ts": now_ts,
        "expires_at_ts": now_ts + VIDEO_SESSION_TTL_SECONDS,
    }

def get_video_session(user_id) -> dict:
    key = video_session_key(user_id)
    session = USER_PENDING.get(key) or {}
    if session.get("pending_action") != "video_session":
        if session:
            USER_PENDING.pop(key, None)
        return default_video_session(user_id)
    if float(session.get("expires_at_ts") or 0) < time.time():
        USER_PENDING.pop(key, None)
        return default_video_session(user_id)
    base = default_video_session(user_id)
    base.update(session)
    base["draft"] = dict(base.get("draft") or {})
    base["order"] = dict(base.get("order") or {})
    base["screen_stack"] = [str(item) for item in (base.get("screen_stack") or []) if str(item or "").strip()][-VIDEO_SESSION_STACK_LIMIT:]
    return base

def save_video_session(user_id, session: dict) -> dict:
    now_ts = time.time()
    clean = default_video_session(user_id)
    clean.update(dict(session or {}))
    clean["pending_action"] = "video_session"
    clean["user_id"] = str(user_id)
    clean["draft"] = dict(clean.get("draft") or {})
    clean["order"] = dict(clean.get("order") or {})
    clean["screen_stack"] = [str(item) for item in (clean.get("screen_stack") or []) if str(item or "").strip()][-VIDEO_SESSION_STACK_LIMIT:]
    clean.setdefault("created_at_ts", now_ts)
    clean["updated_at_ts"] = now_ts
    clean["expires_at_ts"] = now_ts + VIDEO_SESSION_TTL_SECONDS
    USER_PENDING[video_session_key(user_id)] = clean
    return clean

def clear_video_session(user_id) -> bool:
    return USER_PENDING.pop(video_session_key(user_id), None) is not None

def push_video_screen(user_id, screen_id: str, flow: str | None = None) -> dict:
    session = get_video_session(user_id)
    screen = str(screen_id or "").strip()[:120]
    if not screen:
        return save_video_session(user_id, session)
    if flow is not None:
        flow_name = str(flow or "").strip()[:80]
        if flow_name:
            session.setdefault("entry_flow", flow_name)
            if not session.get("entry_flow"):
                session["entry_flow"] = flow_name
            session["current_flow"] = flow_name
    stack = [str(item) for item in (session.get("screen_stack") or []) if str(item or "").strip()]
    current = str(session.get("current_screen") or "").strip()
    if current and (not stack or stack[-1] != current):
        stack.append(current)
    if not stack or stack[-1] != screen:
        stack.append(screen)
    session["current_screen"] = screen
    session["screen_stack"] = stack[-VIDEO_SESSION_STACK_LIMIT:]
    return save_video_session(user_id, session)

def go_video_screen(user_id, screen_id: str, flow: str | None = None, **draft_fields) -> dict:
    session = push_video_screen(user_id, screen_id, flow)
    if draft_fields:
        draft = dict(session.get("draft") or {})
        for key, value in draft_fields.items():
            draft[str(key)[:80]] = value
        session["draft"] = draft
        session = save_video_session(user_id, session)
    return session

def pop_video_screen(user_id, fallback: str = "video_main") -> str:
    session = get_video_session(user_id)
    stack = [str(item) for item in (session.get("screen_stack") or []) if str(item or "").strip()]
    current = str(session.get("current_screen") or "").strip()
    if stack and current and stack[-1] == current:
        stack.pop()
    target = stack[-1] if stack else str(fallback or "video_main")
    session["current_screen"] = target
    session["screen_stack"] = stack or [target]
    save_video_session(user_id, session)
    return target

def preserve_video_session_on_back(user_id) -> dict:
    return get_video_session(user_id)

def validate_video_flow_state(user_id, required_fields) -> dict:
    session = get_video_session(user_id)
    draft = dict(session.get("draft") or {})
    missing = []
    for field in required_fields or []:
        parts = str(field or "").split(".")
        cursor = draft if parts and parts[0] != "session" else session
        if parts and parts[0] == "draft":
            cursor = draft
            parts = parts[1:]
        elif parts and parts[0] == "session":
            parts = parts[1:]
        ok = True
        for part in parts:
            if isinstance(cursor, dict) and part in cursor and video_value_present(cursor.get(part)):
                cursor = cursor.get(part)
            else:
                ok = False
                break
        if not ok:
            missing.append(str(field))
    return {"ok": not missing, "missing": missing, "session": session}

def sync_self_scene_source_video(user_id, source: dict | None, lang: str = "vi") -> dict:
    source = dict(source or {})
    file_id = str(source.get("file_id") or source.get("source_file_id") or "").strip()
    duration = _safe_int(source.get("duration") or source.get("source_duration") or 0, 0)
    return go_video_screen(
        user_id,
        "selfscene:object",
        "selfscene",
        input_video_file_id=file_id,
        input_video_duration_seconds=duration,
        input_video_duration_status="detected" if duration > 0 else "unknown",
        input_video_file_name=str(source.get("file_name") or source.get("source_file_name") or "")[:220],
        input_video_mime_type=str(source.get("mime_type") or source.get("source_mime_type") or "video/mp4")[:120],
        input_video_file_size=_safe_int(source.get("file_size") or source.get("source_file_size") or 0, 0),
        input_video_label=self_scene_input_label("video", lang),
    )

def developing_video_pending_key(user_id) -> str:
    return f"developing_video:{user_id}"

def developing_video_latest_key(user_id, flow: str = "") -> str:
    return f"{user_id}:{normalize_developing_video_flow(flow)}"

def normalize_developing_video_flow(flow: str = "") -> str:
    value = str(flow or "").strip().lower()
    return value if value in DEVELOPING_VIDEO_FLOWS else ""

def _short_pending_text(value: str, limit: int = 700) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip())[:limit]

def _safe_int(value, default: int = 0) -> int:
    try:
        return int(value)
    except Exception:
        return default

def _safe_float(value, default: float = 0.0) -> float:
    try:
        return float(value)
    except Exception:
        return default

def video_v6_keyboard(items: list, lang: str = "vi", back: tuple[str, str] | None = None, main: bool = True) -> InlineKeyboardMarkup:
    return build_2col_keyboard(items, nav_back=back, nav_main=main, lang=lang)


VIDEO_NUMBER_BUTTON_LABELS = ("1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣")


def video_numbered_choice_row_size(count: int) -> int:
    count = max(0, int(count or 0))
    if count <= 5:
        return max(count, 1)
    if count == 6:
        return 3
    if count <= 8:
        return 4
    return 4


def video_numbered_choice_keyboard(
    number_items: list,
    lang: str = "vi",
    action_items: list | None = None,
    back: tuple[str, str] | None = None,
    main: bool = True,
) -> InlineKeyboardMarkup:
    rows = []
    size = video_numbered_choice_row_size(len(number_items or []))
    for start in range(0, len(number_items or []), size):
        chunk = list((number_items or [])[start:start + size])
        row = []
        for idx, item in enumerate(chunk, start + 1):
            label = VIDEO_NUMBER_BUTTON_LABELS[idx - 1] if idx <= len(VIDEO_NUMBER_BUTTON_LABELS) else str(idx)
            callback_data = item.callback_data if isinstance(item, InlineKeyboardButton) else str(item[1])
            row.append(InlineKeyboardButton(label, callback_data=callback_data))
        rows.append(row)
    if action_items:
        rows.extend(build_2col_keyboard(action_items, nav_back=None, nav_main=False, lang=lang).inline_keyboard)
    nav = []
    if back:
        nav.append(InlineKeyboardButton(str(back[0]), callback_data=str(back[1])))
    if main:
        nav.append(InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"))
    if nav:
        rows.append(nav)
    return InlineKeyboardMarkup(rows)

def video_v6_rotating_items(items: list[str], offset: int = 0, limit: int = 3) -> list[str]:
    clean = [str(item or "").strip() for item in items if str(item or "").strip()]
    if not clean:
        return []
    start = _safe_int(offset, 0) % len(clean)
    return [clean[(start + idx) % len(clean)] for idx in range(min(limit, len(clean)))]

