async def cmd_video_idea_admin(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user or not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    context.user_data.pop("video_idea_admin_input", None)
    context.user_data.pop("video_idea_admin_candidate", None)
    return await update.message.reply_text(
        video_idea_admin_main_text(),
        parse_mode="HTML",
        reply_markup=video_idea_admin_main_keyboard(),
    )


async def handle_video_idea_admin_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query.from_user or not is_admin_user(query.from_user.id):
        return await query.answer("Bạn không có quyền dùng chức năng này.", show_alert=True)
    await query.answer()
    uid = query.from_user.id
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "main"
    value = parts[2] if len(parts) > 2 else ""

    if action == "main":
        context.user_data.pop("video_idea_admin_input", None)
        context.user_data.pop("video_idea_admin_candidate", None)
        return await safe_edit_or_send(query, video_idea_admin_main_text(), parse_mode="HTML", reply_markup=video_idea_admin_main_keyboard())

    if action == "cats":
        all_rows = video_idea_dynamic_categories(active_only=False)
        page_size = 8
        total_pages = max(1, (len(all_rows) + page_size - 1) // page_size)
        page = max(1, min(safe_int(value, 1), total_pages))
        rows = all_rows[(page - 1) * page_size:page * page_size]
        return await safe_edit_or_send(
            query,
            video_idea_admin_categories_text(rows, page, total_pages),
            parse_mode="HTML",
            reply_markup=video_idea_admin_categories_keyboard(rows, page, total_pages),
        )

    if action == "pres":
        all_rows = _video_idea_dynamic_db(lambda conn: video_idea_store.list_presets(conn, active_only=False, limit=2000))
        page_size = 10
        total_pages = max(1, (len(all_rows) + page_size - 1) // page_size)
        page = max(1, min(safe_int(value, 1), total_pages))
        rows = all_rows[(page - 1) * page_size:page * page_size]
        return await safe_edit_or_send_long_html(
            query,
            video_idea_admin_presets_text(rows, page, total_pages),
            reply_markup=video_idea_admin_presets_keyboard(rows, page, total_pages),
        )

    if action == "cat":
        row = video_idea_dynamic_category(safe_int(value, 0))
        if not row:
            return await safe_edit_or_send(query, video_idea_admin_main_text(), parse_mode="HTML", reply_markup=video_idea_admin_main_keyboard())
        return await safe_edit_or_send(query, video_idea_admin_category_detail_text(row), parse_mode="HTML", reply_markup=video_idea_admin_category_detail_keyboard(row))

    if action == "pre":
        row = video_idea_dynamic_preset(safe_int(value, 0))
        if not row:
            return await safe_edit_or_send(query, video_idea_admin_main_text(), parse_mode="HTML", reply_markup=video_idea_admin_main_keyboard())
        return await safe_edit_or_send_long_html(query, video_idea_admin_preset_detail_text(row), reply_markup=video_idea_admin_preset_detail_keyboard(row))

    if action == "preview":
        row = video_idea_dynamic_preset(safe_int(value, 0))
        return await safe_edit_or_send(
            query,
            video_idea_dynamic_preset_text(row),
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Preset", callback_data=f"viadm|pre|{safe_int(value, 0)}")]]),
        )

    if action == "newc":
        context.user_data["video_idea_admin_input"] = {"action": "create_category"}
        return await safe_edit_or_send(
            query,
            "➕ <b>Thêm danh mục</b>\n\nGửi JSON gồm: category_key, public_name, short_button_name, description, icon, sort_order.\n\nVí dụ: <code>{\"category_key\":\"new_group\",\"public_name\":\"Nhóm mới\",\"short_button_name\":\"Nhóm mới\",\"description\":\"Mô tả\",\"icon\":\"💡\",\"sort_order\":17}</code>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Hủy", callback_data="viadm|cancel|1")]]),
        )

    if action == "pickc":
        categories = video_idea_dynamic_categories(active_only=False)
        rows = [[InlineKeyboardButton(
            f"{row.get('icon') or '💡'} {str(row.get('short_button_name') or row.get('public_name'))[:30]}",
            callback_data=f"viadm|newp|{int(row.get('id') or 0)}",
        )] for row in categories]
        rows.append([InlineKeyboardButton("❌ Hủy", callback_data="viadm|cancel|1")])
        return await safe_edit_or_send(query, "➕ <b>Chọn danh mục cho preset mới</b>", parse_mode="HTML", reply_markup=InlineKeyboardMarkup(rows))

    if action == "newp":
        category = video_idea_dynamic_category(safe_int(value, 0))
        context.user_data["video_idea_admin_input"] = {"action": "create_preset", "category": category}
        return await safe_edit_or_send(
            query,
            "➕ <b>Thêm preset</b>\n\nGửi một JSON object. Bắt buộc: preset_key, title, description, system_guidance, user_prompt_template, recommended_scene_count, music_plan, voice_plan, visual_plan. scene_duration_sec phải là 8. Có thể thêm recommended_aspect_ratio (9:16, 16:9, 1:1 hoặc 4:5), audio_plan, content_safety_note, routing và prompt seed.\n\nHệ thống sẽ kiểm tra rồi hiện preview trước khi lưu.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Hủy", callback_data="viadm|cancel|1")]]),
        )

    if action in {"editc", "editp", "ordc", "ordp", "clone"}:
        context.user_data["video_idea_admin_input"] = {"action": action, "entity_id": safe_int(value, 0)}
        instructions = {
            "editc": "Gửi JSON chứa các trường danh mục cần sửa.",
            "editp": "Gửi JSON chứa các trường preset cần sửa.",
            "ordc": "Gửi số thứ tự mới cho danh mục.",
            "ordp": "Gửi số thứ tự mới cho preset.",
            "clone": "Gửi: preset_key_mới | Tên preset mới. Bản nhân sẽ mặc định tắt.",
        }
        return await safe_edit_or_send(
            query,
            f"✍️ <b>Chuẩn bị thay đổi</b>\n\n{instructions[action]}\n\nSẽ có preview trước khi ghi DB.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Hủy", callback_data="viadm|cancel|1")]]),
        )

    if action in {"togc", "togp"}:
        entity_id = safe_int(value, 0)
        if action == "togc":
            before = video_idea_dynamic_category(entity_id)
            if not before:
                return await safe_edit_or_send(
                    query,
                    video_idea_admin_error_text(ValueError("category_not_found")),
                    reply_markup=video_idea_admin_main_keyboard(),
                )
            payload = {"is_active": 0 if bool(before.get("is_active")) else 1}
            candidate = {"action": "toggle_category", "entity_id": entity_id, "payload": payload}
        else:
            before = video_idea_dynamic_preset(entity_id)
            if not before:
                return await safe_edit_or_send(
                    query,
                    video_idea_admin_error_text(ValueError("preset_not_found")),
                    reply_markup=video_idea_admin_main_keyboard(),
                )
            payload = {"is_active": 0 if bool(before.get("is_active")) else 1}
            candidate = {"action": "toggle_preset", "entity_id": entity_id, "payload": payload}
        context.user_data["video_idea_admin_candidate"] = candidate
        return await safe_edit_or_send(query, video_idea_admin_candidate_text(candidate), parse_mode="HTML", reply_markup=video_idea_admin_confirm_keyboard())

    if action == "export":
        payload = _video_idea_dynamic_db(video_idea_store.export_catalog)
        document = io.BytesIO(json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8"))
        document.name = f"video_idea_catalog_v{video_idea_store.SCHEMA_VERSION}.json"
        await query.message.reply_document(document=document, caption="📤 Export kho ý tưởng video · không chứa khóa provider.")
        return await safe_edit_or_send(query, video_idea_admin_main_text(), parse_mode="HTML", reply_markup=video_idea_admin_main_keyboard())

    if action == "import":
        context.user_data["video_idea_admin_input"] = {"action": "import"}
        return await safe_edit_or_send(
            query,
            "📥 <b>Import JSON</b>\n\nDán object JSON schema_version=1. Hệ thống sẽ kiểm tra khóa trùng, giới hạn trường, category tham chiếu và bí mật provider rồi mới hiện preview.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Hủy", callback_data="viadm|cancel|1")]]),
        )

    if action == "audit":
        rows = _video_idea_dynamic_db(lambda conn: video_idea_store.list_audit(conn, limit=20))
        lines = ["🧾 <b>Audit gần nhất</b>", ""]
        for row in rows:
            lines.append(
                f"• {html.escape(str(row.get('action') or ''))} · {html.escape(str(row.get('entity_key') or ''))} · "
                f"{html.escape(str(row.get('actor_id') or ''))} · {html.escape(str(row.get('created_at') or ''))}"
            )
        if not rows:
            lines.append("Chưa có thay đổi admin.")
        return await safe_edit_or_send_long_html(query, "\n".join(lines), reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Quản lý", callback_data="viadm|main|1")]]))

    if action == "cancel":
        context.user_data.pop("video_idea_admin_input", None)
        context.user_data.pop("video_idea_admin_candidate", None)
        return await safe_edit_or_send(query, video_idea_admin_main_text(), parse_mode="HTML", reply_markup=video_idea_admin_main_keyboard())

    if action == "save":
        candidate = dict(context.user_data.get("video_idea_admin_candidate") or {})
        actor_id = str(uid)
        try:
            def _apply(conn):
                operation = str(candidate.get("action") or "")
                payload = dict(candidate.get("payload") or {})
                entity_id = safe_int(candidate.get("entity_id"), 0)
                if operation == "create_category":
                    return video_idea_store.create_category(conn, payload, actor_id=actor_id)
                if operation in {"update_category", "toggle_category"}:
                    return video_idea_store.update_category(conn, entity_id, payload, actor_id=actor_id)
                if operation == "create_preset":
                    return video_idea_store.create_preset(conn, payload, actor_id=actor_id)
                if operation in {"update_preset", "toggle_preset"}:
                    return video_idea_store.update_preset(conn, entity_id, payload, actor_id=actor_id)
                if operation == "clone_preset":
                    return video_idea_store.clone_preset(conn, entity_id, payload["preset_key"], payload["title"], actor_id=actor_id)
                if operation == "import":
                    return video_idea_store.apply_import(conn, payload["validated"], actor_id=actor_id)
                raise ValueError("unknown_admin_operation")
            result = _video_idea_dynamic_db(_apply)
        except Exception as error:
            logger.warning("video idea admin save rejected: %s", type(error).__name__)
            return await safe_edit_or_send(query, video_idea_admin_error_text(error), reply_markup=video_idea_admin_confirm_keyboard())
        context.user_data.pop("video_idea_admin_input", None)
        context.user_data.pop("video_idea_admin_candidate", None)
        summary = html.escape(json.dumps(result, ensure_ascii=False, default=str)[:1200])
        return await safe_edit_or_send(
            query,
            f"✅ <b>Đã lưu thay đổi</b>\n\n<code>{summary}</code>",
            parse_mode="HTML",
            reply_markup=video_idea_admin_main_keyboard(),
        )

    return await safe_edit_or_send(query, video_idea_admin_main_text(), parse_mode="HTML", reply_markup=video_idea_admin_main_keyboard())


@video_public_callback_failure_guard
async def handle_video_idea_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    value = parts[2] if len(parts) > 2 else ""
    uiflow3_parent: dict = {}
    uiflow3_session_id = ""
    uiflow3_marker = _video_uiflow3_idea_parent_marker(context)
    if uiflow3_marker:
        uiflow3_state = video_uiflow3_state(context)
        uiflow3_parent = (
            uiflow3_marker
            if uiflow3_state and _video_uiflow3_idea_handoff_matches(
                uiflow3_state,
                uiflow3_marker,
                user_id=uid,
                chat_id=_video_uiflow3_query_chat_id(query),
            )
            else {}
        )
        if not uiflow3_parent:
            clear_developing_video_pending(uid)
            _video_uiflow3_clear_idea_handoff(context)
            return await safe_edit_or_send(
                query,
                "Kho y tuong khong con thuoc ban nhap hien tai.\n\n" + video_idea_menu_text(lang),
                reply_markup=video_idea_menu_keyboard(lang),
            )
        uiflow3_session_id = str(uiflow3_parent.get("uiflow3_catalog_session_id") or "")
        if action in {"start", "uiflow3_back"}:
            clear_developing_video_pending(uid)
            _video_uiflow3_clear_idea_handoff(context)
            return await video_uiflow3_render(query, context, uiflow3_state)
        if action in {"continue", "handoff"}:
            plan = dict(
                get_latest_developing_video_plan(uid, "videoidea")
                or {}
            )
            if (
                not plan
                or str(plan.get("uiflow3_catalog_session_id") or "")
                != str(uiflow3_parent.get("uiflow3_catalog_session_id") or "")
            ):
                return await video_uiflow3_render(query, context, uiflow3_state)
            return await video_uiflow3_accept_idea_candidate(
                query,
                context,
                uid,
                uiflow3_parent,
                plan,
            )
        session_bound_actions = {
            "catalog_refresh", "catalog_choose", "catalog_back_options",
            "catalog_back_detail", "catalog_scene_count", "catalog_duration",
            "catalog_source", "catalog_back_source", "catalog_result",
            "catalog_edit", "catalog_image_prompt", "catalog_video_prompt",
            "routes", "save",
        }
        if action in session_bound_actions:
            catalog_state = dict(
                get_developing_video_pending(uid)
                or get_latest_developing_video_plan(uid, "videoidea")
                or {}
            )
            if (
                str(catalog_state.get("uiflow3_catalog_session_id") or "")
                != str(uiflow3_parent.get("uiflow3_catalog_session_id") or "")
            ):
                clear_developing_video_pending(uid)
                return await safe_edit_or_send_long_html(
                    query,
                    video_idea_catalog_categories_text(lang),
                    reply_markup=video_idea_catalog_categories_keyboard(
                        lang,
                        back_callback="videoidea|uiflow3_back",
                    ),
                )
    legacy_state = dict(get_latest_developing_video_plan(uid, "videoidea") or get_developing_video_pending(uid) or {})
    legacy_target = video_idea_catalog.legacy_callback_target(action, value, legacy_state)
    if legacy_target:
        target_screen = str(legacy_target.get("screen") or "categories")
        target_category = str(legacy_target.get("category") or "")
        if target_screen == "categories":
            clear_developing_video_pending(uid)
            return await safe_edit_or_send(
                query,
                video_idea_catalog_categories_text(lang),
                parse_mode="HTML",
                reply_markup=video_idea_catalog_categories_keyboard(
                    lang,
                    back_callback="videoidea|uiflow3_back" if uiflow3_parent else "videoidea|start",
                ),
            )
        if target_screen == "result":
            idea_id = str(legacy_state.get("catalog_idea_id") or legacy_state.get("idea_id") or "")
            idea = video_idea_catalog.idea_by_id(idea_id)
            if idea:
                scene_count = safe_int(legacy_state.get("scene_count"), 0)
                if scene_count not in video_idea_catalog.SCENE_COUNT_OPTIONS:
                    scene_count = video_idea_catalog.scene_count_for_duration(
                        safe_int(legacy_state.get("duration_seconds"), 16)
                    )
                plan = video_idea_catalog.build_plan(
                    idea,
                    scene_count=scene_count,
                    source_mode="text_prompt",
                    custom_note=str(legacy_state.get("custom_note") or ""),
                )
                plan.update({
                    "catalog_category": target_category or str(idea.get("category") or "sales"),
                    "catalog_offset": safe_int(legacy_state.get("catalog_offset"), 0),
                    "catalog_idea_id": idea_id,
                })
                clear_developing_video_pending(uid)
                plan = save_developing_video_plan(uid, "videoidea", plan)
                return await safe_edit_or_send_long_html(
                    query,
                    video_idea_catalog_result_text(plan, lang),
                    reply_markup=video_uiflow3_idea_catalog_result_keyboard(context, query, uid, plan, lang),
                )
        state = {
            "catalog_category": target_category or "sales",
            "catalog_offset": 0,
            "provider_called": False,
            "image_provider_called": False,
            "job_created": False,
            "outbox_created": False,
            "wallet_mutations": 0,
            "xu_charged": 0,
        }
        if uiflow3_session_id:
            state["uiflow3_catalog_session_id"] = uiflow3_session_id
        restore_developing_video_pending(uid, "videoidea", state, "catalog_options")
        return await safe_edit_or_send(
            query,
            video_idea_catalog_options_text(state, lang),
            parse_mode="HTML",
            reply_markup=video_idea_catalog_options_keyboard(lang),
        )
    if action == "start":
        clear_developing_video_pending(uid)
        clear_video_idea_parent_context(context)
        set_video_route_session(uid, "video_idea", "tool_home", product_id="video_idea")
        return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
    if action == "explore":
        clear_developing_video_pending(uid)
        clear_video_idea_parent_context(context)
        return await safe_edit_or_send_long_html(
            query,
            video_idea_catalog_categories_text(lang),
            reply_markup=video_idea_catalog_categories_keyboard(
                lang,
                back_callback="videoidea|uiflow3_back" if uiflow3_parent else "videoidea|start",
            ),
        )
    if action == "catalog":
        clear_video_idea_parent_context(context)
        state = {
            "catalog_category": value if value in video_idea_catalog.CATEGORY_LABELS else "sales",
            "catalog_offset": 0,
            "provider_called": False,
            "image_provider_called": False,
            "job_created": False,
            "outbox_created": False,
            "wallet_mutations": 0,
            "xu_charged": 0,
        }
        if uiflow3_session_id:
            state["uiflow3_catalog_session_id"] = uiflow3_session_id
        restore_developing_video_pending(uid, "videoidea", state, "catalog_options")
        return await safe_edit_or_send(
            query,
            video_idea_catalog_options_text(state, lang),
            parse_mode="HTML",
            reply_markup=video_idea_catalog_options_keyboard(lang),
        )
    if action == "catalog_refresh":
        state = dict(get_developing_video_pending(uid) or {})
        if not state.get("catalog_category"):
            return await safe_edit_or_send(
                query,
                video_idea_catalog_categories_text(lang),
                parse_mode="HTML",
                reply_markup=video_idea_catalog_categories_keyboard(
                    lang,
                    back_callback="videoidea|uiflow3_back" if uiflow3_parent else "videoidea|start",
                ),
            )
        state["catalog_offset"] = safe_int(state.get("catalog_offset"), 0) + 5
        restore_developing_video_pending(uid, "videoidea", state, "catalog_options")
        return await safe_edit_or_send(
            query,
            video_idea_catalog_options_text(state, lang),
            parse_mode="HTML",
            reply_markup=video_idea_catalog_options_keyboard(lang),
        )
    if action == "catalog_choose":
        state = dict(get_developing_video_pending(uid) or {})
        options = video_idea_catalog_options(state)
        index = max(1, min(5, safe_int(value, 1)))
        idea = options[index - 1] if index <= len(options) else {}
        if not idea:
            return await safe_edit_or_send(
                query,
                video_idea_catalog_options_text(state, lang),
                parse_mode="HTML",
                reply_markup=video_idea_catalog_options_keyboard(lang),
            )
        state.update(idea)
        state["catalog_idea_id"] = str(idea.get("idea_id") or "")
        restore_developing_video_pending(uid, "videoidea", state, "catalog_detail")
        return await safe_edit_or_send(
            query,
            video_idea_catalog_detail_text(state, lang),
            parse_mode="HTML",
            reply_markup=video_idea_catalog_duration_keyboard(lang),
        )
    if action == "catalog_back_options":
        state = dict(get_developing_video_pending(uid) or get_latest_developing_video_plan(uid, "videoidea") or {})
        restore_developing_video_pending(uid, "videoidea", state, "catalog_options")
        return await safe_edit_or_send(
            query,
            video_idea_catalog_options_text(state, lang),
            parse_mode="HTML",
            reply_markup=video_idea_catalog_options_keyboard(lang),
        )
    if action == "catalog_back_detail":
        state = dict(get_developing_video_pending(uid) or get_latest_developing_video_plan(uid, "videoidea") or {})
        restore_developing_video_pending(uid, "videoidea", state, "catalog_detail")
        return await safe_edit_or_send(
            query,
            video_idea_catalog_detail_text(state, lang),
            parse_mode="HTML",
            reply_markup=video_idea_catalog_duration_keyboard(lang),
        )
    if action in {"catalog_scene_count", "catalog_duration"}:
        state = dict(get_developing_video_pending(uid) or {})
        if action == "catalog_duration":
            scene_count = video_idea_catalog.scene_count_for_duration(safe_int(value, 16))
        else:
            scene_count = safe_int(value, 2)
            if scene_count not in video_idea_catalog.SCENE_COUNT_OPTIONS:
                scene_count = 2
        idea = video_idea_catalog.idea_by_id(str(state.get("catalog_idea_id") or "")) or state
        plan = video_idea_catalog.build_plan(
            idea,
            scene_count=scene_count,
            source_mode="text_prompt",
            custom_note=str(state.get("custom_note") or ""),
        )
        plan.update({
            "catalog_category": state.get("catalog_category") or idea.get("category") or "",
            "catalog_offset": safe_int(state.get("catalog_offset"), 0),
            "catalog_idea_id": state.get("catalog_idea_id") or idea.get("idea_id") or "",
        })
        if state.get("uiflow3_catalog_session_id"):
            plan["uiflow3_catalog_session_id"] = str(state["uiflow3_catalog_session_id"])
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "videoidea", plan)
        return await safe_edit_or_send_long_html(
            query,
            video_idea_catalog_result_text(plan, lang),
            reply_markup=(
                video_uiflow3_idea_catalog_result_keyboard(context, query, uid, plan, lang)
                if uiflow3_parent
                else video_idea_catalog_result_keyboard(plan, lang)
            ),
        )
    if action == "source_start":
        clear_developing_video_pending(uid)
        state = {
            "title": "Ý tưởng từ tư liệu của anh/chị",
            "selected_topic": "Ý tưởng từ tư liệu của anh/chị",
            "provider_called": False,
            "image_provider_called": False,
            "job_created": False,
            "outbox_created": False,
            "wallet_mutations": 0,
            "xu_charged": 0,
        }
        if uiflow3_session_id:
            state["uiflow3_catalog_session_id"] = uiflow3_session_id
        restore_developing_video_pending(uid, "videoidea", state, "catalog_source_first")
        return await safe_edit_or_send(
            query,
            video_idea_source_text(state, lang),
            parse_mode="HTML",
            reply_markup=video_idea_source_keyboard(lang, back_callback="videoidea|start"),
        )
    if action == "catalog_source":
        state = dict(get_developing_video_pending(uid) or get_latest_developing_video_plan(uid, "videoidea") or {})
        source_mode = value if value in VIDEO_IDEA_SOURCE_LABELS else "text_prompt"
        if not state.get("catalog_idea_id") and str(state.get("idea_kind") or "") != "catalog":
            state["source_mode"] = source_mode
            restore_developing_video_pending(uid, "videoidea", state, "catalog_source_topic")
            return await safe_edit_or_send(
                query,
                "✍️ <b>Mô tả video anh/chị muốn làm</b>\n\nHãy gửi một câu ngắn về chủ thể, mục tiêu hoặc nội dung trong ảnh/video. TOAN AAS sẽ dựng bản kế hoạch để anh/chị chọn thời lượng và sửa tiếp.\n\nChưa tải file, chưa tạo tác vụ và chưa trừ Xu.",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("⬅️ Chọn nguồn", callback_data="videoidea|source_start"),
                    InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"),
                ]]),
            )
        idea = video_idea_catalog.idea_by_id(str(state.get("catalog_idea_id") or "")) or state
        plan = video_idea_catalog.build_plan(
            idea,
            duration_seconds=safe_int(state.get("duration_seconds"), 16),
            source_mode=source_mode,
            custom_note=str(state.get("custom_note") or ""),
        )
        plan.update({
            "catalog_category": state.get("catalog_category") or idea.get("category") or "",
            "catalog_offset": safe_int(state.get("catalog_offset"), 0),
            "catalog_idea_id": state.get("catalog_idea_id") or idea.get("idea_id") or "",
        })
        if state.get("uiflow3_catalog_session_id"):
            plan["uiflow3_catalog_session_id"] = str(state["uiflow3_catalog_session_id"])
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "videoidea", plan)
        return await safe_edit_or_send_long_html(
            query,
            video_idea_catalog_result_text(plan, lang),
            reply_markup=video_uiflow3_idea_catalog_result_keyboard(context, query, uid, plan, lang),
        )
    if action == "catalog_back_source":
        plan = dict(get_latest_developing_video_plan(uid, "videoidea") or get_developing_video_pending(uid) or {})
        restore_developing_video_pending(uid, "videoidea", plan, "catalog_source")
        return await safe_edit_or_send(
            query,
            video_idea_source_text(plan, lang),
            parse_mode="HTML",
            reply_markup=video_idea_source_keyboard(lang),
        )
    if action == "catalog_result":
        plan = dict(get_latest_developing_video_plan(uid, "videoidea") or {})
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        return await safe_edit_or_send_long_html(
            query,
            video_idea_catalog_result_text(plan, lang),
            reply_markup=video_uiflow3_idea_catalog_result_keyboard(context, query, uid, plan, lang),
        )
    if action == "catalog_edit":
        plan = dict(get_latest_developing_video_plan(uid, "videoidea") or {})
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        restore_developing_video_pending(uid, "videoidea", plan, "catalog_edit")
        return await safe_edit_or_send(
            query,
            "✍️ <b>Chỉnh nhanh ý tưởng</b>\n\nGửi yêu cầu muốn thêm, bớt hoặc thay đổi. Ví dụ: đổi sang buổi tối, nhấn mạnh sản phẩm, giữ gương mặt nhân vật, kết bằng lời mời nhẹ.\n\nHệ thống chỉ cập nhật kế hoạch, chưa tạo file và chưa trừ Xu.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⬅️ Kế hoạch", callback_data="videoidea|catalog_result"),
                InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"),
            ]]),
        )
    if action in {"catalog_image_prompt", "catalog_video_prompt"}:
        plan = dict(get_latest_developing_video_plan(uid, "videoidea") or {})
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        field = "image_prompt_final" if action == "catalog_image_prompt" else "video_prompt_final"
        fallback_field = "image_prompt_seed" if action == "catalog_image_prompt" else "video_prompt_seed"
        title = "Câu lệnh ảnh gợi ý" if action == "catalog_image_prompt" else "Câu lệnh video gợi ý"
        return await safe_edit_or_send(
            query,
            f"{'🖼' if action == 'catalog_image_prompt' else '🎬'} <b>{title}</b>\n\n<code>{html.escape(str(plan.get(field) or plan.get(fallback_field) or 'Chưa có câu lệnh.'))}</code>\n\nĐây là bản nháp có thể sửa trong flow sản phẩm. Chưa tạo file và chưa trừ Xu.",
            parse_mode="HTML",
            reply_markup=video_uiflow3_idea_catalog_result_keyboard(context, query, uid, plan, lang),
        )
    if action == "routes":
        plan = dict(get_latest_developing_video_plan(uid, "videoidea") or {})
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        return await safe_edit_or_send(
            query,
            video_idea_route_choice_text(plan, lang),
            parse_mode="HTML",
            reply_markup=video_idea_route_choice_keyboard(lang),
        )
    if action == "handoff":
        plan = dict(get_latest_developing_video_plan(uid, "videoidea") or {})
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        state = video_idea_catalog.build_scene3_handoff_state(plan)
        state = save_video_profile_studio_state(context, state)
        return await video_profile_scene1_render(query, state, lang)
    if action == "kind":
        kind = value if value in {"ad", "cinema", "custom"} else "custom"
        if kind == "ad":
            set_developing_video_pending(uid, "videoidea", "product_type", idea_kind=kind)
            return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
        if kind == "cinema":
            set_developing_video_pending(uid, "videoidea", "cinema_suggestions", idea_kind=kind, suggest_offset=0)
            current = get_developing_video_pending(uid) or {}
            return await safe_edit_or_send(query, video_idea_cinema_suggestions_text(current, lang), parse_mode="HTML", reply_markup=video_idea_cinema_suggestions_keyboard(lang))
        set_developing_video_pending(uid, "videoidea", "topic", idea_kind=kind)
        return await safe_edit_or_send(
            query,
            video_idea_topic_text(kind, lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("🔙 Quay lại Ý tưởng video" if normalize_user_language(lang) == "vi" else "🔙 Back to video ideas", "videoidea|start"),
            ),
        )
    pending = get_developing_video_pending(uid)
    plan = get_latest_developing_video_plan(uid, "videoidea")
    state = pending or plan or {}
    if action == "cinema_refresh":
        offset = _safe_int(state.get("suggest_offset"), 0) + 3
        set_developing_video_pending(uid, "videoidea", "cinema_suggestions", idea_kind="cinema", suggest_offset=offset)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_idea_cinema_suggestions_text(current, lang), parse_mode="HTML", reply_markup=video_idea_cinema_suggestions_keyboard(lang))
    if action == "cinema_custom":
        set_developing_video_pending(uid, "videoidea", "cinema_custom", idea_kind="cinema")
        return await safe_edit_or_send(
            query,
            video_idea_topic_text("cinema", lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại 3 gợi ý" if normalize_user_language(lang) == "vi" else "⬅️ Back to ideas", "videoidea|kind|cinema"),
            ),
        )
    if action == "cinema_choice":
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        suggestions = video_idea_cinema_suggestions(_safe_int(state.get("suggest_offset"), 0), lang)
        topic = suggestions[idx - 1] if idx <= len(suggestions) else (suggestions[0] if suggestions else "")
        base = dict(state or {})
        base.update({"idea_kind": "cinema", "selected_topic": topic, "product": topic, "context": "điện ảnh/kể chuyện" if normalize_user_language(lang) == "vi" else "cinematic/story", "prompt_variant_offset": 0})
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "videoidea", base)
        return await safe_edit_or_send(query, video_idea_choices_text(plan, lang), parse_mode="HTML", reply_markup=video_idea_choice_keyboard(lang, plan.get("idea_kind")))
    if action == "product_type":
        if value == "custom":
            set_developing_video_pending(uid, "videoidea", "product_type_custom", idea_kind="ad")
            return await safe_edit_or_send(
                query,
                "✍️ Hãy nhập loại sản phẩm/dịch vụ." if normalize_user_language(lang) == "vi" else "✍️ Enter the product/service category.",
                reply_markup=video_idea_product_description_keyboard(lang),
            )
        set_developing_video_pending(uid, "videoidea", "product_suggestions", idea_kind="ad", product_type=value, suggest_offset=0)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_idea_product_suggestions_text(current, lang), parse_mode="HTML", reply_markup=video_idea_product_suggestions_keyboard(lang))
    if action == "product_refresh":
        if not state.get("product_type"):
            return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
        offset = _safe_int(state.get("suggest_offset"), 0) + 3
        restore_developing_video_pending(uid, "videoidea", state, "product_suggestions")
        set_developing_video_pending(uid, "videoidea", "product_suggestions", suggest_offset=offset)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_idea_product_suggestions_text(current, lang), parse_mode="HTML", reply_markup=video_idea_product_suggestions_keyboard(lang))
    if action == "product_custom":
        if not state.get("product_type"):
            return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
        restore_developing_video_pending(uid, "videoidea", state, "topic")
        return await safe_edit_or_send(query, video_idea_product_description_text(state.get("product_type"), lang), parse_mode="HTML", reply_markup=video_idea_product_description_keyboard(lang))
    if action == "product_choice":
        if not state.get("product_type"):
            return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        options = video_idea_product_suggestions(state.get("product_type"), _safe_int(state.get("suggest_offset"), 0), lang)
        product = options[idx - 1] if idx <= len(options) else (options[0] if options else "")
        set_developing_video_pending(uid, "videoidea", "goal", idea_kind="ad", product=product, selected_topic=product)
        return await safe_edit_or_send(query, video_idea_goal_text(lang), parse_mode="HTML", reply_markup=video_idea_goal_keyboard(lang))
    if action == "back_product_type":
        restore_developing_video_pending(uid, "videoidea", state, "product_type")
        return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
    if action == "back_description":
        if state.get("product_type"):
            restore_developing_video_pending(uid, "videoidea", state, "product_suggestions")
            return await safe_edit_or_send(query, video_idea_product_suggestions_text(state, lang), parse_mode="HTML", reply_markup=video_idea_product_suggestions_keyboard(lang))
        restore_developing_video_pending(uid, "videoidea", state, "topic")
        return await safe_edit_or_send(query, video_idea_product_description_text(state.get("product_type"), lang), parse_mode="HTML", reply_markup=video_idea_product_description_keyboard(lang))
    if action == "back_goal":
        restore_developing_video_pending(uid, "videoidea", state, "goal")
        return await safe_edit_or_send(query, video_idea_goal_text(lang), parse_mode="HTML", reply_markup=video_idea_goal_keyboard(lang))
    if action == "back_context":
        restore_developing_video_pending(uid, "videoidea", state, "context")
        return await safe_edit_or_send(query, video_idea_context_text(state, lang), parse_mode="HTML", reply_markup=video_idea_context_keyboard(lang))
    if action == "back_choices":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        return await safe_edit_or_send(query, video_idea_choices_text(plan, lang), parse_mode="HTML", reply_markup=video_idea_choice_keyboard(lang, plan.get("idea_kind")))
    if action == "idea_refresh":
        base = dict(plan or state or {})
        if not base.get("selected_topic") and not base.get("product"):
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        base["prompt_variant_offset"] = str(_safe_int(base.get("prompt_variant_offset"), 0) + 3)
        refreshed = save_developing_video_plan(uid, "videoidea", base)
        return await safe_edit_or_send(query, video_idea_choices_text(refreshed, lang), parse_mode="HTML", reply_markup=video_idea_choice_keyboard(lang, refreshed.get("idea_kind")))
    if action == "goal_custom":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        set_developing_video_pending(uid, "videoidea", "goal_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Nhập mục tiêu quảng cáo của bạn." if normalize_user_language(lang) == "vi" else "✍️ Enter your advertising goal.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Quay lại" if normalize_user_language(lang) == "vi" else "🔙 Back", callback_data="videoidea|back_goal"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]]),
        )
    if action == "goal":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        goal_labels = {
            "sales": "bán hàng trực tiếp",
            "brand": "nhận diện thương hiệu",
            "viral": "viral TikTok/Reels",
        }
        set_developing_video_pending(uid, "videoidea", "context", goal=goal_labels.get(value, value))
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(
            query,
            video_idea_context_text(current, lang),
            parse_mode="HTML",
            reply_markup=video_idea_context_keyboard(lang),
        )
    if action == "context_custom":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        set_developing_video_pending(uid, "videoidea", "context_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Nhập ngữ cảnh/bối cảnh quảng cáo." if normalize_user_language(lang) == "vi" else "✍️ Enter the advertising context.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Quay lại" if normalize_user_language(lang) == "vi" else "🔙 Back", callback_data="videoidea|back_context"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]]),
        )
    if action == "context":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        options = video_idea_context_options(pending.get("product_type"), lang)
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        state = dict(pending)
        state["context"] = options[idx - 1]
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "videoidea", state)
        return await safe_edit_or_send(query, video_idea_choices_text(plan, lang), reply_markup=video_idea_choice_keyboard(lang, plan.get("idea_kind")))
    if action == "genre":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        genre_labels = {"scifi": "khoa học viễn tưởng/công nghệ", "fantasy": "fantasy/điện ảnh", "drama": "drama/cảm xúc"}
        set_developing_video_pending(uid, "videoidea", "context", goal=genre_labels.get(value, value))
        return await safe_edit_or_send(
            query,
            "🌍 Chọn bối cảnh kể chuyện." if normalize_user_language(lang) == "vi" else "🌍 Choose the story context.",
            reply_markup=video_idea_context_keyboard(lang),
        )
    if action == "choose":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        try:
            choice = max(1, min(3, int(value or "1")))
        except Exception:
            choice = 1
        plan["idea_choice"] = str(choice)
        plan = save_developing_video_plan(uid, "videoidea", plan)
        return await safe_edit_or_send_long_html(query, video_idea_result_text(plan, choice, lang), reply_markup=video_idea_result_keyboard(lang))
    if action == "choice_custom":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        restore_developing_video_pending(uid, "videoidea", plan, "choice_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Hãy nhập ý tưởng quảng cáo riêng của bạn." if normalize_user_language(lang) == "vi" else "✍️ Enter your custom advertising idea.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Quay lại 3 ý tưởng" if normalize_user_language(lang) == "vi" else "🔙 Back to ideas", callback_data="videoidea|back_choices"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]]),
        )
    if action == "finalization":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        package = developing_video_public_package(plan, "videoidea", lang)
        return await open_video_finalization(query, uid, "videoidea", plan, lang, "videoidea|back_choices", package)
    if action == "frame_video":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        photos = developing_video_frame_photos(plan)
        if len(photos) >= 2:
            return await open_existing_images_in_frame_video(query, uid, photos, "videoidea_plan", lang=lang)
        text = (
            "⚠️ Ý tưởng này chưa có bộ ảnh từng cảnh. Hãy tạo/lưu ít nhất 2 ảnh trước khi ghép video. Bot chưa render và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "⚠️ This idea has no scene image set yet. Create/save at least two images before assembling video. No render and no Xu charged."
        )
        return await safe_edit_or_send(query, text, reply_markup=video_idea_result_keyboard(lang))
    if action == "render_ai":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        active = shopaikey_active_job_for_user(uid, "video")
        if active:
            return await safe_edit_or_send(query, public_video_active_job_text(lang), reply_markup=public_video_active_job_keyboard(active, lang))
        return await open_video_finalization(
            query,
            uid,
            "videoidea",
            plan,
            lang,
            "videoidea|back_choices",
            developing_video_public_package(plan, "videoidea", lang),
        )
    if action in {"storyboard", "image_prompts", "video_prompts", "music"}:
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        return await safe_edit_or_send_long_html(query, video_idea_followup_text(action, plan, lang), reply_markup=video_idea_result_keyboard(lang))
    if action == "save":
        if plan and (str(plan.get("idea_kind") or "") == "catalog" or plan.get("catalog_idea_id")):
            return await safe_edit_or_send(
                query,
                "💾 TOAN AAS đã lưu kế hoạch ý tưởng trong phiên hiện tại. Hệ thống chưa tạo tác vụ, chưa gọi dịch vụ dựng và chưa trừ Xu.",
                reply_markup=video_uiflow3_idea_catalog_result_keyboard(context, query, uid, plan, lang),
            )
        return await safe_edit_or_send(
            query,
            "💾 TOAN AAS đã lưu ý tưởng trong phiên hiện tại. Hệ thống chưa tạo tác vụ và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "💾 Idea saved in this session. No API call and no Xu deducted.",
            reply_markup=video_idea_result_keyboard(lang),
        )
    return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))

