def localized_menu_content(action: str, is_admin: bool, lang: str, user_id=None) -> tuple[str, InlineKeyboardMarkup]:
    lang = normalize_user_language(lang) or "vi"
    if action in {"main", "back"}:
        return localized_start_menu_text(user_id or "__customer__", lang), localized_main_menu_keyboard(is_admin, lang)
    if action == "main_video":
        if user_id is not None:
            go_video_screen(user_id, "video_main", "main_video")
        return menu_text_main_video_i18n(lang), main_video_keyboard(lang)
    if action == "main_ai":
        return menu_text_main_ai_i18n(lang), main_ai_keyboard(lang)
    if action == "main_memory":
        return menu_text_main_memory_i18n(lang), main_memory_keyboard(lang, user_id)
    if action == "memory_storage_status":
        return memory_status_text(user_id or "__customer__", lang), memory_storage_nav_keyboard(lang)
    if action == "memory_storage_addon":
        return memory_storage_addon_text(lang), memory_storage_addon_keyboard(lang)
    if action == "memory_storage_cleanup":
        return memory_storage_cleanup_text(lang), memory_storage_nav_keyboard(lang)
    if action == "main_docs":
        return menu_text_main_docs_i18n(lang), main_docs_keyboard(lang)
    if action == "main_image":
        return menu_text_main_image_i18n(lang), main_image_keyboard(lang)
    if action == "main_music":
        if user_id is not None:
            set_music_nav_origin(user_id, "menu|main")
            enter_product_context(user_id, PRODUCT_CONTEXT_SHOWROOM, origin_screen="menu|main", product_area="voice_music")
        return menu_text_main_music_i18n(lang), music_tools_keyboard(lang)
    if action == "main_music_video":
        if user_id is not None:
            set_music_nav_origin(user_id, "menu|main_video")
            go_video_screen(user_id, "video_music_hub", "main_video")
            enter_product_context(user_id, PRODUCT_CONTEXT_VIDEO_ADDON, origin_screen="menu|main_video", product_area="voice_music")
        return menu_text_main_music_i18n(lang), music_tools_keyboard(lang, back_callback="menu|main_video")
    if action == "main_audio":
        return menu_text_main_audio_i18n(lang), main_audio_keyboard(lang)
    if action == "translate":
        if user_id is not None:
            enter_product_context(user_id, PRODUCT_CONTEXT_SHOWROOM, origin_screen="menu|main", product_area="translation")
        return translation_menu_text(lang), translation_menu_keyboard(lang)
    if action == "translation_video_factory":
        if user_id is not None:
            set_video_dubbing_pending(user_id, "menu", origin="translation", translation_context="media_center")
        return video_dubbing_menu_text(lang, "translation"), video_dubbing_menu_keyboard(lang, "translation")
    if action == "translation_media_file":
        if user_id is not None:
            clear_video_dubbing_pending(user_id)
            set_translation_menu_pending(user_id, "media_file", translation_context="translate_file")
        copy = public_hub_copy(normalize_user_language(lang) or "vi")
        text = (
            f"<b>{copy['translation_file_entry_title']}</b>\n\n"
            f"{copy['translation_file_entry_body']}\n\n"
            f"{copy['translation_picker_no_charge']}"
        )
        return text, translation_input_keyboard(lang, parent="language")
    if action == "translation_media_audio":
        if user_id is not None:
            clear_video_dubbing_pending(user_id)
            set_translation_menu_pending(user_id, "media_audio", translation_context="translate_audio")
        return translation_voice_menu_text(lang), translation_voice_menu_keyboard(lang, parent="language")
    if action == "translation_subtitle_file":
        state = {
            "mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "process_type": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "video_processing_mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "requested_mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "active_flow": VIDEO_DUBBING_FLOW_SUBTITLE_FILE_TRANSLATE,
            "flow_type": VIDEO_DUBBING_FLOW_HAS_SUBTITLE,
            "origin": "translation",
            "product_context": PRODUCT_CONTEXT_SHOWROOM,
        }
        if user_id is not None:
            state = set_video_dubbing_pending(user_id, "source", **state)
        return video_dubbing_source_text(state, lang), video_dubbing_source_keyboard(lang, state)
    if action == "translation_language_hub":
        return translation_language_hub_text(lang), translation_language_hub_keyboard(lang, user_id)
    if action == "translation_auto_target":
        return menu_text_translate_i18n(False, lang), translate_language_keyboard(False, lang)
    if action == "translate_more":
        return menu_text_translate_i18n(True, lang), translate_language_keyboard(True, lang)
    if action == "main_quick":
        return menu_text_main_quick_i18n(lang), main_quick_keyboard(lang)
    if action == "main_topup":
        return menu_text_main_topup_i18n(lang, user_id), main_topup_keyboard(lang, user_id)
    if action == "main_profile":
        return menu_text_main_profile_i18n(user_id or "__customer__", lang), main_profile_keyboard(lang)
    if action == "profile_packages":
        return user_package_summary_text(user_id or "__customer__", lang=lang), profile_child_keyboard(lang)
    if action == "profile_ref_link":
        return referral_account_link_text(user_id or "__customer__", BOT_USERNAME, lang), profile_child_keyboard(lang)
    if action == "profile_ref_policy":
        return referral_account_policy_text(user_id or "__customer__", lang), profile_child_keyboard(lang)
    if action == "profile_ref_stats":
        return referral_account_stats_text(user_id or "__customer__", lang), profile_child_keyboard(lang)
    if action == "main_guide":
        return menu_text_main_guide_i18n(lang), main_guide_keyboard(lang)
    if action == "guide":
        return guide_index_text_i18n(lang), guide_keyboard("", lang)
    if action == "guide_video_ai":
        return video_uiflow3_guide_text(lang), video_uiflow3_guide_keyboard(lang)
    if action.startswith("guide_"):
        section = action.replace("guide_", "", 1)
        return guide_section_text_i18n(section, lang), guide_keyboard(section, lang)
    if action == "admin_broadcast_lite" and is_admin:
        return broadcast_lite_admin_menu_text(), broadcast_lite_admin_menu_keyboard()
    if action in ADMIN_MENU_PAGE_HANDLERS:
        return ADMIN_MENU_PAGE_HANDLERS[action]()
    if action == "doc_tools":
        return doc_tools_menu_text_i18n(lang), doc_tools_keyboard(lang)
    if action.startswith("hint_"):
        section, hint = menu_hint_text_i18n(action, lang)
        return hint, menu_nav_keyboard_i18n(section, is_admin, lang)
    return localized_start_menu_text(user_id or "__customer__", lang), localized_main_menu_keyboard(is_admin, lang)

