async def cmd_huongdan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id if update.effective_user else 0
    clear_media_creator_pending_states(uid)
    lang = get_user_language(uid) or "vi"
    section = context.args[0] if context.args else ""
    await update.message.reply_text(
        guide_section_text_i18n(section, lang),
        parse_mode="HTML",
        reply_markup=guide_keyboard(section, lang),
    )
    if section or PUBLIC_BASE_URL:
        return
    sent_any = False
    filename = GUIDE_DOCX_FILE
    path = find_guide_docx_path()
    if os.path.exists(path):
        try:
            with open(path, "rb") as f:
                await context.bot.send_document(
                    chat_id=update.effective_chat.id,
                    document=f,
                    filename=filename,
                    caption=f"📘 {filename}",
                )
            sent_any = True
        except Exception as e:
            logger.warning(f"Cannot send guide document {filename}: {e}")
    if not sent_any:
        await update.message.reply_text(
            "⚠️ Chưa có file Word hướng dẫn. Admin cần set PUBLIC_BASE_URL hoặc kiểm tra file hướng dẫn trong repo."
        )

async def cmd_guide_debug(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    found = find_guide_docx_path()
    candidates = guide_docx_candidates()
    lines = [
        "📘 <b>Guide Debug</b>",
        f"• Found: <code>{'YES' if found else 'NO'}</code>",
        f"• File: <code>{html.escape(GUIDE_DOCX_FILE)}</code>",
        f"• CWD: <code>{html.escape(os.getcwd())}</code>",
        "",
        "<b>Candidates</b>",
    ]
    for idx, path in enumerate(candidates, 1):
        lines.append(f"{idx}. <code>{html.escape(os.path.basename(path))}</code> — <code>{'exists' if os.path.exists(path) else 'missing'}</code>")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

def terms_keyboard() -> InlineKeyboardMarkup:
    rows = []
    url = terms_pdf_download_url()
    if url:
        rows.append([InlineKeyboardButton("📄 Tải điều khoản PDF", url=url)])
    rows.append([InlineKeyboardButton("💬 Nhắn admin/hỗ trợ", url=SUPPORT_TELEGRAM_URL or "https://t.me/toanaas")])
    return InlineKeyboardMarkup(rows)

def terms_text() -> str:
    return (
        "📜 <b>ĐIỀU KHOẢN SỬ DỤNG TOAN AAS</b>\n\n"
        "Tài liệu này áp dụng cho người dùng sử dụng bot Telegram, website, công cụ AI, "
        "công cụ xử lý ảnh/video/audio, Xu dịch vụ và các module thử nghiệm của TOAN AAS.\n\n"
        "<b>Tóm tắt nhanh:</b>\n"
        "• TOAN AAS là trung tâm công cụ AI/automation hỗ trợ tạo nội dung và xử lý media.\n"
        "• Xu dịch vụ chỉ dùng nội bộ trong TOAN AAS, không phải tiền/coin/token, không rút tiền và không chuyển nhượng.\n"
        "• Người dùng chịu trách nhiệm kiểm tra nội dung AI trước khi đăng.\n"
        "• Không dùng hệ thống để lừa đảo, giả mạo, vi phạm bản quyền, deepfake gây hại, spam hoặc quảng cáo sai sự thật.\n"
        "• TOAN AAS giữ quyền với logo, tài liệu, prompt, workflow, source code, database, cấu hình hệ thống và tài liệu vận hành nội bộ.\n"
        "• Người dùng không được sao chép, reverse engineer, bán lại hoặc dùng tài liệu/quy trình nội bộ để tạo dịch vụ cạnh tranh nếu chưa được TOAN AAS cho phép.\n"
        "• Nội dung người dùng gửi vào bot cần thuộc quyền sử dụng hợp pháp của người gửi; user chịu trách nhiệm với file, ảnh, audio, video và prompt đã gửi.\n"
        "• Kết quả AI là nội dung hỗ trợ, có thể sai/thiếu; user phải kiểm tra lại pháp lý, bản quyền, số liệu, tuyên bố quảng cáo và tính phù hợp trước khi dùng công khai.\n"
        f"• Khiếu nại bản quyền/giả mạo: gửi thông tin và bằng chứng qua {support_link_html()} để admin kiểm tra thủ công.\n"
        "• Chức năng tự đăng bài/chạy quảng cáo cho khách chưa được mở công khai.\n"
        f"• Khi cần hỗ trợ, liên hệ admin: {support_link_html()}\n\n"
        "Bấm nút bên dưới để xem/tải bản PDF đầy đủ nếu file đã được triển khai."
    )

