async def handle_aichat_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    action = (query.data or "").split("|", 1)[1] if "|" in (query.data or "") else "status"
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    state = aichat_state()
    if action == "back_freehub":
        return await safe_edit_or_send(query, free_hub_main_text(lang), parse_mode="HTML", reply_markup=free_hub_main_keyboard(lang))
    if action == "back_active":
        payload = ai_chatbot_copilot.status_payload(state, uid)
        if payload.get("enabled"):
            return await safe_edit_or_send(query, aichat_status_text(payload), parse_mode="HTML", reply_markup=aichat_control_keyboard(payload))
        return await safe_edit_or_send(query, free_hub_main_text(lang), parse_mode="HTML", reply_markup=free_hub_main_keyboard(lang))
    if action == "on":
        state, result = ai_chatbot_copilot.request_enable(state, uid)
        save_aichat_state(state)
        return await safe_edit_or_send(query, "🤖 <b>AAS ONE AI Chatbot</b>\n\n" + result["reply"], parse_mode="HTML", reply_markup=aichat_consent_keyboard())
    if action == "consent_on":
        state, result = ai_chatbot_copilot.enable_with_consent(state, uid)
        save_aichat_state(state)
        payload = ai_chatbot_copilot.status_payload(state, uid)
        return await safe_edit_or_send(query, result["reply"], reply_markup=aichat_control_keyboard(payload))
    if action == "off":
        state, result = ai_chatbot_copilot.disable_user(state, uid)
        save_aichat_state(state)
        return await safe_edit_or_send(query, result["reply"], reply_markup=aichat_control_keyboard({"enabled": False}))
    if action in {"assist_on", "assist_off"}:
        state, result = ai_chatbot_copilot.set_action_permission(state, uid, action == "assist_on")
        save_aichat_state(state)
        payload = ai_chatbot_copilot.status_payload(state, uid)
        if result.get("consent_required"):
            return await safe_edit_or_send(query, result["reply"], reply_markup=aichat_consent_keyboard())
        return await safe_edit_or_send(query, result["reply"], reply_markup=aichat_control_keyboard(payload))
    payload = ai_chatbot_copilot.status_payload(state, uid)
    if action == "open_image_prefill":
        flow_state = aichat_prepare_image_prefill_flow(uid, payload=payload, lang=lang)
        state = ai_chatbot_copilot.mark_action_execution(
            state,
            uid,
            selected_action="open_image_ai_flow_with_prefill",
            executed=True,
            router_called=True,
            action_result="quick_image_prefill_opened_by_button",
            requested_action="open_image_ai_flow_with_prefill",
            flow_access_allowed=True,
            flow_block_reason="",
            provider_submit_allowed=False,
            provider_submit_block_reason="awaiting_user_final_confirm",
            opened_flow=True,
            prefill_saved=True,
        )
        save_aichat_state(state)
        return await safe_edit_or_send(
            query,
            quick_image_prepared_prompt_text(flow_state, lang),
            parse_mode="HTML",
            reply_markup=aichat_image_flow_keyboard(lang),
        )
    if action == "trace":
        return await safe_edit_or_send(query, aichat_trace_text(payload), parse_mode="HTML", reply_markup=aichat_trace_keyboard(payload))
    return await safe_edit_or_send(query, aichat_status_text(payload), parse_mode="HTML", reply_markup=aichat_trace_keyboard(payload))

async def handle_aichat_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    chat_type = str(getattr(getattr(update, "effective_chat", None), "type", "") or "").lower()
    if chat_type and chat_type != "private":
        return False
    text = update.message.text.strip()
    if not text or text.startswith("/"):
        return False
    state = aichat_state()
    user_id = update.effective_user.id
    lang = get_user_language(user_id) or "vi"
    owner_id = cskh_safe_telegram_id(user_id)
    chat_id = cskh_safe_telegram_id(
        getattr(getattr(update, "effective_chat", None), "id", None) or getattr(update.message, "chat_id", None),
        allow_negative=True,
    )
    source_message_id = cskh_safe_message_reference(getattr(update.message, "message_id", None))
    inbound_turn = {"session_id": ""}
    shared_context = None
    runtime_facts = None
    if ai_chatbot_copilot.is_enabled(state, user_id):
        runtime_facts = cskh_live_pricing_snapshot()
        if owner_id and chat_id:
            if source_message_id:
                inbound_turn = cskh_record_customer_turn(
                    owner_id=owner_id,
                    chat_id=chat_id,
                    surface="aichat",
                    user_content=text,
                    source_message_id=source_message_id,
                )
            shared_context = cskh_shared_context(owner_id, chat_id)
    state, result = ai_chatbot_copilot.process_message(
        state,
        user_id,
        text,
        conversation_memory=shared_context,
        runtime_facts=runtime_facts,
    )
    save_aichat_state(state)
    if result.get("action_guard") == "disabled_no_reply":
        return ai_chatbot_copilot.was_explicitly_disabled(state, user_id)
    if not result.get("replied"):
        return False

    async def send_closing_notice(notice):
        return await update.message.reply_text(
            notice,
            disable_web_page_preview=True,
        )

    if result.get("action_should_execute") and result.get("selected_action") == "open_image_ai_flow_with_prefill":
        payload = ai_chatbot_copilot.status_payload(state, user_id)
        flow_state = aichat_prepare_image_prefill_flow(user_id, result=result, payload=payload, lang=lang)
        state = ai_chatbot_copilot.mark_action_execution(
            state,
            user_id,
            selected_action="open_image_ai_flow_with_prefill",
            executed=True,
            router_called=True,
            action_result="quick_image_prefill_opened_live",
            requested_action="open_image_ai_flow_with_prefill",
            flow_access_allowed=True,
            flow_block_reason="",
            provider_submit_allowed=False,
            provider_submit_block_reason="awaiting_user_final_confirm",
            opened_flow=True,
            prefill_saved=True,
        )
        save_aichat_state(state)
        delivered_text = f"{result.get('reply') or ''}\n\n{quick_image_prepared_prompt_text(flow_state, lang)}"
        sent = await update.message.reply_text(
            delivered_text,
            parse_mode="HTML",
            reply_markup=aichat_image_flow_keyboard(lang),
            disable_web_page_preview=True,
        )
        confirmed = cskh_transport_delivery_confirmed(sent)
        if confirmed and owner_id and chat_id:
            cskh_finalize_delivered_reply(
                owner_id=owner_id,
                chat_id=chat_id,
                surface="aichat",
                source_message_id=source_message_id,
                assistant_content=delivered_text,
                inbound_turn=inbound_turn,
                classification=result,
                send_notice=send_closing_notice,
            )
        return True
    delivered_text = str(result.get("reply") or "")
    sent = await update.message.reply_text(
        delivered_text,
        parse_mode="HTML",
        reply_markup=aichat_result_keyboard(result, ai_chatbot_copilot.status_payload(state, user_id)),
        disable_web_page_preview=True,
    )
    confirmed = cskh_transport_delivery_confirmed(sent)
    if confirmed and owner_id and chat_id:
        cskh_finalize_delivered_reply(
            owner_id=owner_id,
            chat_id=chat_id,
            surface="aichat",
            source_message_id=source_message_id,
            assistant_content=delivered_text,
            inbound_turn=inbound_turn,
            classification=result,
            send_notice=send_closing_notice,
        )
    return True

