def video_public_bool_label(value) -> str:
    return "ON" if bool(value) else "OFF"

def bool_from_runtime_value(value, default: bool = False) -> bool:
    text = str(value if value is not None else "").strip().lower()
    if text in {"1", "true", "yes", "on", "enabled", "open"}:
        return True
    if text in {"0", "false", "no", "off", "disabled", "closed"}:
        return False
    return bool(default)

def video_runtime_bool(key: str, default: bool = False) -> bool:
    value = get_system_setting(str(key), "")
    if str(value or "").strip() == "":
        return bool(default)
    return bool_from_runtime_value(value, default)

def set_video_runtime_bool(key: str, value: bool, updated_by="", note: str = "") -> None:
    set_system_setting(str(key), "true" if value else "false", note or "video public runtime flag", updated_by)

def video_public_beta_enabled_runtime() -> bool:
    return video_runtime_bool("video_public_beta_enabled", VIDEO_PUBLIC_BETA_ENABLED)

def video_ai_public_enabled_runtime() -> bool:
    return video_runtime_bool("video_ai_public_enabled", VIDEO_AI_PUBLIC_ENABLED)

def video_ai_master_enabled_runtime() -> bool:
    return video_runtime_bool("video_ai_master_enabled", VIDEO_AI_MASTER_ENABLED)

def video_text_to_video_public_enabled_runtime() -> bool:
    return video_runtime_bool("video_text_to_video_public_enabled", VIDEO_TEXT_TO_VIDEO_PUBLIC_ENABLED)

def shopaikey_public_video_enabled_runtime() -> bool:
    return video_runtime_bool("shopaikey_public_video_enabled", SHOPAIKEY_PUBLIC_VIDEO_ENABLED)

def video_beta_200_marketing_loss_enabled_runtime() -> bool:
    # The 200 Xu tier is an intentional starter/marketing tier, not a margin-gated
    # product. A stale runtime "false" must not silently block it once beta is open.
    raw = get_system_setting("video_beta_200_marketing_loss_enabled", "")
    runtime_enabled = bool_from_runtime_value(raw, VIDEO_BETA_200_MARKETING_LOSS_ENABLED) if str(raw or "").strip() else bool(VIDEO_BETA_200_MARKETING_LOSS_ENABLED)
    beta_low_allowed = bool(video_public_beta_enabled_runtime() and "low" in video_public_allowed_tiers())
    return bool(VIDEO_BETA_200_MARKETING_LOSS_ENABLED or runtime_enabled or beta_low_allowed)

def video_public_allowed_tiers_runtime() -> str:
    return get_system_setting("video_public_allowed_tiers", "") or str(VIDEO_PUBLIC_ALLOWED_TIERS or "200,300,400,500,600,700,800,1000,1200,1500")

def video_public_allowed_tiers() -> list[str]:
    allowed = []
    for tier in str(video_public_allowed_tiers_runtime() or "200,300,400,500,600,700,800,1000,1200,1500").split(","):
        tier = normalize_video_tier(tier.strip())
        if tier and tier not in allowed:
            allowed.append(tier)
    current_public = list(video_public_current_tiers())
    for tier in current_public:
        # Older Railway/system settings may still contain only 200/300/400.
        # The current launch decision is to keep all ten canonical public tiers
        # available whenever public video beta is open.
        if tier not in allowed:
            allowed.append(tier)
    allowed = allowed or current_public
    allowed = [tier for tier in allowed if tier in set(video_public_launch_tiers())] or current_public
    if video_public_beta_enabled_runtime():
        if "low" in allowed:
            allowed = ["low", *[tier for tier in allowed if tier != "low"]]
        else:
            allowed.insert(0, "low")
    return allowed

def video_public_blocked_tiers() -> set[str]:
    blocked = set()
    for tier in str(VIDEO_PUBLIC_BLOCK_TIERS or "").split(","):
        tier_norm = normalize_video_tier(tier.strip())
        if tier_norm:
            blocked.add(tier_norm)
    blocked.discard("future_1000")
    blocked.discard("future_1200")
    blocked.discard("future_1500")
    blocked.discard("long")
    return blocked

def video_public_beta_tiers() -> tuple[str, ...]:
    return ("low", "basic", "common")

def video_public_launch_tiers() -> tuple[str, ...]:
    return VIDEO_TIER_ORDER

def video_public_current_tiers() -> tuple[str, ...]:
    return VIDEO_TIER_ORDER

def video_high_tiers() -> tuple[str, ...]:
    return ("advanced", "standard", "high", "future_1000", "future_1200", "future_1500")

def video_tier_base_public_flag(tier: str = "") -> bool:
    tier_norm = normalize_video_tier(tier)
    defaults = {
        "low": bool(VIDEO_TIER_LOW_ENABLED),
        "basic": bool(VIDEO_TIER_BASIC_ENABLED),
        "common": bool(VIDEO_TIER_COMMON_ENABLED),
        "advanced": bool(VIDEO_TIER_500_PUBLIC_ENABLED and VIDEO_TIER_COMMON_ENABLED),
        "standard": bool(VIDEO_TIER_600_PUBLIC_ENABLED and VIDEO_TIER_STANDARD_ENABLED),
        "long": bool(VIDEO_TIER_700_PUBLIC_ENABLED and VIDEO_TIER_STANDARD_ENABLED),
        "high": bool(VIDEO_TIER_800_PUBLIC_ENABLED and VIDEO_TIER_HIGH_ENABLED),
        "future_1000": bool(VIDEO_TIER_1000_PUBLIC_ENABLED and VIDEO_TIER_HIGH_ENABLED),
        "future_1200": bool(VIDEO_TIER_1200_PUBLIC_ENABLED and VIDEO_TIER_HIGH_ENABLED),
        "future_1500": bool(VIDEO_TIER_1500_PUBLIC_ENABLED and VIDEO_TIER_HIGH_ENABLED),
    }
    return bool(defaults.get(tier_norm, False))

def video_tier_public_flag(tier: str = "") -> bool:
    tier_norm = normalize_video_tier(tier)
    runtime_keys = {
        "low": "video_beta_tier_200_enabled",
        "basic": "video_beta_tier_300_enabled",
        "common": "video_beta_tier_400_enabled",
        "advanced": "video_beta_tier_500_enabled",
        "standard": "video_beta_tier_600_enabled",
        "long": "video_beta_tier_700_enabled",
        "high": "video_beta_tier_800_enabled",
        "future_1000": "video_beta_tier_1000_enabled",
        "future_1200": "video_beta_tier_1200_enabled",
        "future_1500": "video_beta_tier_1500_enabled",
    }
    key = runtime_keys.get(tier_norm)
    if not key:
        return video_tier_base_public_flag(tier_norm)
    if tier_norm in video_public_current_tiers() and video_public_beta_enabled_runtime():
        return bool(video_tier_base_public_flag(tier_norm))
    return video_runtime_bool(key, video_tier_base_public_flag(tier_norm))

def video_tier_limit_config(tier: str = "") -> dict:
    tier_norm = normalize_video_tier(tier)
    if tier_norm == "advanced":
        return {"user_day": int(VIDEO_TIER_500_DAILY_USER_LIMIT), "global_day": int(VIDEO_TIER_500_DAILY_GLOBAL_LIMIT)}
    if tier_norm == "standard":
        return {"user_day": int(VIDEO_TIER_600_DAILY_USER_LIMIT), "global_day": int(VIDEO_TIER_600_DAILY_GLOBAL_LIMIT)}
    if tier_norm == "long":
        return {"user_day": int(VIDEO_TIER_600_DAILY_USER_LIMIT), "global_day": int(VIDEO_TIER_600_DAILY_GLOBAL_LIMIT)}
    if tier_norm == "high":
        return {"user_day": int(VIDEO_TIER_800_DAILY_USER_LIMIT), "global_day": int(VIDEO_TIER_800_DAILY_GLOBAL_LIMIT)}
    return {"user_day": int(VIDEO_PUBLIC_MAX_JOBS_PER_USER_PER_DAY or 1), "global_day": 0}

def video_public_tier_token_to_name(token: str = "") -> str:
    raw = str(token or "").strip().lower()
    mapping = {
        "200": "low",
        "200xu": "low",
        "video_beta_200": "low",
        "300": "basic",
        "300xu": "basic",
        "video_beta_300": "basic",
        "400": "common",
        "400xu": "common",
        "video_beta_400": "common",
        "500": "advanced",
        "500xu": "advanced",
        "video_beta_500": "advanced",
        "600": "standard",
        "600xu": "standard",
        "video_beta_600": "standard",
        "700": "long",
        "700xu": "long",
        "video_beta_700": "long",
        "800": "high",
        "800xu": "high",
        "video_beta_800": "high",
        "1000": "future_1000",
        "1000xu": "future_1000",
        "video_beta_1000": "future_1000",
        "1200": "future_1200",
        "1200xu": "future_1200",
        "video_beta_1200": "future_1200",
        "1500": "future_1500",
        "1500xu": "future_1500",
        "video_beta_1500": "future_1500",
    }
    return mapping.get(raw, normalize_video_tier(raw))

def video_beta_open_parse_args(args: list[str] | tuple[str, ...] | None = None) -> dict:
    raw = " ".join(str(item) for item in (args or [])).strip()
    allow_key = r"(?:allow_loss_200|allow_loss|marketing_loss_200|loss_200)"
    allow_loss_200 = bool(
        re.search(rf"\b{allow_key}\s*=\s*(?:1|true|yes|on)\b", raw, re.I)
        or re.search(rf"\b{allow_key}\b(?!\s*=)", raw, re.I)
    )
    clean = re.sub(
        rf"\b{allow_key}\s*(?:=\s*(?:1|true|yes|on|0|false|no|off))?\b",
        "",
        raw,
        flags=re.I,
    )
    return {"raw": raw, "tier_text": clean.strip(), "allow_loss_200": allow_loss_200}

def video_public_tier_enabled(tier: str = "") -> bool:
    tier_norm = normalize_video_tier(tier)
    if tier_norm not in video_public_launch_tiers():
        return False
    if video_public_beta_enabled_runtime():
        return True
    marketing_loss = bool(tier_norm == "low" and video_beta_200_marketing_loss_enabled_runtime())
    if tier_norm == "low":
        return marketing_loss
    base_enabled = {
        "low": bool(VIDEO_TIER_LOW_ENABLED),
        "basic": bool(VIDEO_TIER_BASIC_ENABLED),
        "common": bool(VIDEO_TIER_COMMON_ENABLED),
        "advanced": video_tier_public_flag("advanced"),
        "standard": video_tier_public_flag("standard"),
        "long": video_tier_public_flag("long"),
        "high": video_tier_public_flag("high"),
        "future_1000": video_tier_public_flag("future_1000"),
        "future_1200": video_tier_public_flag("future_1200"),
        "future_1500": video_tier_public_flag("future_1500"),
    }.get(tier_norm, False)
    return bool(base_enabled and video_public_beta_enabled_runtime())

def video_public_tier_revenue_vnd(tier: str = "") -> int:
    return int(video_tier_cost_xu(tier) * XU_TO_VND)

def check_video_margin(tier: str = "") -> dict:
    tier_norm = normalize_video_tier(tier)
    payload = video_tier_pricing_payload().get(tier_norm) or {}
    price_xu = int(payload.get("cost") or 0)
    provider_cost_xu = int(payload.get("provider_cost") or 0)
    revenue_vnd = int(price_xu * XU_TO_VND)
    ratio = (provider_cost_xu / price_xu) if price_xu > 0 and provider_cost_xu > 0 else None
    blocked = []
    marketing_loss = bool(tier_norm == "low" and video_beta_200_marketing_loss_enabled_runtime())
    if tier_norm not in video_public_launch_tiers():
        blocked.append("tier is not in the canonical ten-package public launch")
    if tier_norm in video_public_blocked_tiers() and not marketing_loss:
        blocked.append("tier is blocked for public beta")
    if price_xu <= 0:
        blocked.append("price_xu missing")
    if provider_cost_xu <= 0:
        blocked.append("provider_cost_unknown")
    if ratio is not None and ratio > float(VIDEO_PUBLIC_WARN_COST_RATIO) and not marketing_loss:
        blocked.append(f"provider_cost_ratio {ratio:.2f} exceeds hard limit {VIDEO_PUBLIC_WARN_COST_RATIO:.2f}")
    high_controlled = bool(
        tier_norm in video_high_tiers()
        and VIDEO_COST_GATE_ALLOW_HIGH_TIERS_AFTER_SMOKE
        and video_tier_public_flag(tier_norm)
    )
    if high_controlled:
        blocked = [
            item for item in blocked
            if str(item) not in {"provider_cost_unknown"}
            and "provider_cost_ratio" not in str(item)
        ]
    cost_review_only = False
    if tier_norm in video_public_launch_tiers():
        config_blockers = []
        cost_warnings = []
        for item in blocked:
            item_text = str(item)
            if item_text == "provider_cost_unknown" or "provider_cost_ratio" in item_text:
                cost_warnings.append(item)
            else:
                config_blockers.append(item)
        if cost_warnings and not config_blockers:
            # Current ten launch tiers are sold by product
            # policy. Provider cost is still reported to admin, but it must not
            # block customer confirmation/output paths.
            cost_review_only = True
            blocked = []
    status = "PASS"
    if marketing_loss:
        status = "MARKETING_LOSS_ON"
        # Starter tier is allowed to run at a loss. Keep only impossible config
        # blockers such as a missing customer price.
        blocked = [item for item in blocked if "price_xu missing" in str(item)]
    elif cost_review_only:
        status = "COST_REVIEW_ONLY"
    elif blocked:
        status = "BLOCKED"
    elif high_controlled:
        status = "COST_REVIEW_ONLY"
    elif ratio is not None and ratio > float(VIDEO_PUBLIC_MAX_COST_RATIO):
        status = "WARN_MARGIN"
    return {
        "tier": tier_norm,
        "price_xu": price_xu,
        "provider_cost_xu": provider_cost_xu,
        "revenue_vnd": revenue_vnd,
        "cost_ratio": ratio,
        "status": status,
        "can_open": status in {"PASS", "WARN_MARGIN", "MARKETING_LOSS_ON", "COST_REVIEW_ONLY"},
        "blockers": blocked,
        "safe_ratio": float(VIDEO_PUBLIC_MAX_COST_RATIO),
        "hard_ratio": float(VIDEO_PUBLIC_WARN_COST_RATIO),
        "marketing_loss": marketing_loss,
        "controlled": high_controlled,
    }

def video_beta_200_today_counts(user_id=None) -> dict:
    today = datetime.now().strftime("%Y-%m-%d")
    week_start = (datetime.now() - timedelta(days=6)).strftime("%Y-%m-%d 00:00:00")
    month_start = datetime.now().strftime("%Y-%m-01 00:00:00")
    params: list = [today + "%"]
    user_clause = ""
    if user_id is not None:
        user_clause = "AND e.user_id=?"
        params.append(str(user_id or ""))
    conn = db_connect()
    try:
        row = conn.execute(
            f"""
            SELECT COUNT(DISTINCT e.job_id)
            FROM shopaikey_billing_events e
            JOIN shopaikey_jobs j ON j.id=e.job_id
            WHERE e.created_at LIKE ?
              {user_clause}
              AND e.event_type IN ('video_deducted_after_provider_accept','video_package_use_after_provider_accept')
              AND e.reason LIKE '%tier=low%'
              AND LOWER(j.job_type)='video'
              AND UPPER(j.status) IN ('IN_PROGRESS','SUCCESS','SUCCEEDED','COMPLETED','DONE')
            """,
            tuple(params),
        ).fetchone()
        scoped = int((row or [0])[0] or 0)
        scoped_week = 0
        scoped_month = 0
        if user_id is not None:
            week_row = conn.execute(
                """
                SELECT COUNT(DISTINCT e.job_id)
                FROM shopaikey_billing_events e
                JOIN shopaikey_jobs j ON j.id=e.job_id
                WHERE e.created_at >= ?
                  AND e.user_id=?
                  AND e.event_type IN ('video_deducted_after_provider_accept','video_package_use_after_provider_accept')
                  AND e.reason LIKE '%tier=low%'
                  AND LOWER(j.job_type)='video'
                  AND UPPER(j.status) IN ('IN_PROGRESS','SUCCESS','SUCCEEDED','COMPLETED','DONE')
                """,
                (week_start, str(user_id or "")),
            ).fetchone()
            scoped_week = int((week_row or [0])[0] or 0)
            month_row = conn.execute(
                """
                SELECT COUNT(DISTINCT e.job_id)
                FROM shopaikey_billing_events e
                JOIN shopaikey_jobs j ON j.id=e.job_id
                WHERE e.created_at >= ?
                  AND e.user_id=?
                  AND e.event_type IN ('video_deducted_after_provider_accept','video_package_use_after_provider_accept')
                  AND e.reason LIKE '%tier=low%'
                  AND LOWER(j.job_type)='video'
                  AND UPPER(j.status) IN ('IN_PROGRESS','SUCCESS','SUCCEEDED','COMPLETED','DONE')
                """,
                (month_start, str(user_id or "")),
            ).fetchone()
            scoped_month = int((month_row or [0])[0] or 0)
        global_row = conn.execute(
            """
            SELECT COUNT(DISTINCT e.job_id)
            FROM shopaikey_billing_events e
            JOIN shopaikey_jobs j ON j.id=e.job_id
            WHERE e.created_at LIKE ?
              AND e.event_type IN ('video_deducted_after_provider_accept','video_package_use_after_provider_accept')
              AND e.reason LIKE '%tier=low%'
              AND LOWER(j.job_type)='video'
              AND UPPER(j.status) IN ('IN_PROGRESS','SUCCESS','SUCCEEDED','COMPLETED','DONE')
            """,
            (today + "%",),
        ).fetchone()
        global_count = int((global_row or [0])[0] or 0)
        return {
            "user_count": scoped,
            "user_week_count": scoped_week,
            "user_month_count": scoped_month,
            "global_count": global_count,
            "date": today,
            "week_start": week_start[:10],
            "month_start": month_start[:10],
        }
    except Exception:
        return {"user_count": 0, "global_count": 0, "date": today}
    finally:
        conn.close()

def check_video_beta_200_limit(user_id=None) -> dict:
    counts = video_beta_200_today_counts(user_id)
    user_count = int(counts.get("user_count") or 0)
    user_week_count = int(counts.get("user_week_count") or 0)
    user_month_count = int(counts.get("user_month_count") or 0)
    global_count = int(counts.get("global_count") or 0)
    user_limit = max(1, int(VIDEO_BETA_200_MAX_USER_DAY or 1))
    week_limit = max(1, int(VIDEO_BETA_200_MAX_USER_WEEK or 1))
    month_limit = max(1, int(VIDEO_BETA_200_MAX_USER_MONTH or 1))
    global_limit = max(1, int(VIDEO_BETA_200_MAX_TOTAL_DAY or 10))
    if user_count >= user_limit:
        return {"ok": False, **counts, "reason": "user_daily_limit", "user_limit": user_limit, "week_limit": week_limit, "month_limit": month_limit, "global_limit": global_limit}
    if user_week_count >= week_limit:
        return {"ok": False, **counts, "reason": "user_weekly_limit", "user_limit": user_limit, "week_limit": week_limit, "month_limit": month_limit, "global_limit": global_limit}
    if user_month_count >= month_limit:
        return {"ok": False, **counts, "reason": "user_monthly_limit", "user_limit": user_limit, "week_limit": week_limit, "month_limit": month_limit, "global_limit": global_limit}
    if global_count >= global_limit:
        return {"ok": False, **counts, "reason": "global_daily_limit", "user_limit": user_limit, "week_limit": week_limit, "month_limit": month_limit, "global_limit": global_limit}
    return {"ok": True, **counts, "reason": "ok", "user_limit": user_limit, "week_limit": week_limit, "month_limit": month_limit, "global_limit": global_limit}

def video_tier_today_counts(tier: str = "", user_id=None) -> dict:
    tier_norm = normalize_video_tier(tier)
    today = datetime.now().strftime("%Y-%m-%d")
    conn = db_connect()
    try:
        user_row = conn.execute(
            """
            SELECT COUNT(DISTINCT job_id)
            FROM shopaikey_billing_events
            WHERE created_at LIKE ?
              AND user_id=?
              AND event_type IN ('video_confirmed','video_deducted','video_package_use')
              AND reason LIKE ?
            """,
            (today + "%", str(user_id or ""), f"%tier={tier_norm}%"),
        ).fetchone()
        global_row = conn.execute(
            """
            SELECT COUNT(DISTINCT job_id)
            FROM shopaikey_billing_events
            WHERE created_at LIKE ?
              AND event_type IN ('video_confirmed','video_deducted','video_package_use')
              AND reason LIKE ?
            """,
            (today + "%", f"%tier={tier_norm}%"),
        ).fetchone()
        return {
            "tier": tier_norm,
            "user_count": int((user_row or [0])[0] or 0),
            "global_count": int((global_row or [0])[0] or 0),
            "date": today,
        }
    except Exception:
        return {"tier": tier_norm, "user_count": 0, "global_count": 0, "date": today}
    finally:
        conn.close()

def check_video_high_tier_limit(user_id=None, tier: str = "") -> dict:
    tier_norm = normalize_video_tier(tier)
    if tier_norm not in video_high_tiers():
        return {"ok": True, "tier": tier_norm, "reason": "not_high_tier"}
    limits = video_tier_limit_config(tier_norm)
    counts = video_tier_today_counts(tier_norm, user_id)
    user_limit = max(1, int(limits.get("user_day") or 1))
    global_limit = max(1, int(limits.get("global_day") or 1))
    if int(counts.get("user_count") or 0) >= user_limit:
        return {"ok": False, **counts, "reason": "user_daily_limit", "user_limit": user_limit, "global_limit": global_limit}
    if int(counts.get("global_count") or 0) >= global_limit:
        return {"ok": False, **counts, "reason": "global_daily_limit", "user_limit": user_limit, "global_limit": global_limit}
    return {"ok": True, **counts, "reason": "ok", "user_limit": user_limit, "global_limit": global_limit}

