def _media_readiness_snapshot(tool_name: str, *fallback_tool_names: str) -> dict:
    return preferred_tool_test_result(tool_name, *fallback_tool_names) if fallback_tool_names else get_tool_test_result(tool_name)

def _media_readiness_payload(
    *,
    name: str,
    provider: str,
    model: str = "",
    endpoint: str = "",
    api_key_configured: bool = False,
    endpoint_configured: bool = False,
    admin_smoke_tool: str = "",
    public_enabled: bool = False,
    ready: bool = False,
    reason: str = "",
    missing_env: list[str] | None = None,
    safe_user_message: str = "",
) -> dict:
    snapshot = _media_readiness_snapshot(admin_smoke_tool) if admin_smoke_tool else {}
    smoke_status = str(snapshot.get("status") or "NOT_TESTED")
    return {
        "name": name,
        "ready": bool(ready),
        "provider": provider,
        "model": model or "auto/NEED_DOCS",
        "endpoint_configured": bool(endpoint_configured),
        "endpoint": "configured" if endpoint_configured else "NEED_DOCS/NOT_CONFIGURED",
        "api_key_configured": bool(api_key_configured),
        "public_enabled": bool(public_enabled),
        "admin_smoke_status": smoke_status,
        "last_smoke_at": snapshot.get("tested_at") or "",
        "reason": reason or ("ready" if ready else "not_ready"),
        "missing_env": list(dict.fromkeys(missing_env or [])),
        "safe_user_message": safe_user_message or "⚙️ Tính năng đang được kiểm tra tài nguyên xử lý. TOAN AAS chưa xử lý và chưa trừ Xu.",
        "admin_debug_reason": reason or ("ready" if ready else "not_ready"),
    }

def get_suno_music_readiness() -> dict:
    key4u_missing = []
    for name, ok in [
        ("KEY4U_ENABLED", KEY4U_ENABLED),
        ("KEY4U_API_KEY", bool(KEY4U_API_KEY)),
        ("KEY4U_ADMIN_SMOKE_ENABLED", KEY4U_ADMIN_SMOKE_ENABLED),
        ("KEY4U_SUNO_CREATE_ENDPOINT", bool(KEY4U_SUNO_CREATE_ENDPOINT)),
        ("KEY4U_DEFAULT_MUSIC_MODEL/KEY4U_SUNO_MODEL", bool(KEY4U_SUNO_MODEL)),
    ]:
        if not ok:
            key4u_missing.append(name)
    shopaikey_missing = []
    for name, ok in [
        ("MUSIC_AI_ENABLED", MUSIC_AI_ENABLED),
        ("SHOPAIKEY_ENABLED", SHOPAIKEY_ENABLED),
        ("SHOPAIKEY_API_KEY", bool(SHOPAIKEY_API_KEY)),
        ("SHOPAIKEY_MUSIC_ENABLED", SHOPAIKEY_MUSIC_ENABLED),
        ("SHOPAIKEY_MUSIC_ENDPOINT", bool(SHOPAIKEY_MUSIC_ENDPOINT)),
        ("SHOPAIKEY_MUSIC_STATUS_ENDPOINT", bool(SHOPAIKEY_MUSIC_STATUS_ENDPOINT)),
    ]:
        if not ok:
            shopaikey_missing.append(name)
    key4u_smoke = preferred_tool_test_status_text("key4u_suno", "key4u_suno_job")
    shopaikey_smoke = preferred_tool_test_status_text("shopaikey_music", "shopaikey_music_job")
    submit_smoke = preferred_tool_test_result("key4u_suno", "shopaikey_music")
    fetch_smoke = preferred_tool_test_result("key4u_suno_job", "shopaikey_music_job")
    download_smoke = preferred_tool_test_result("music_ai_download", "music_ai_preview_download")
    key4u_configured = not key4u_missing
    shopaikey_configured = not shopaikey_missing
    configured = bool(key4u_configured or shopaikey_configured)
    fetch_status = str(fetch_smoke.get("status") or "").upper()
    submit_ready = provider_status_is_pass(str(submit_smoke.get("status") or ""))
    fetch_ready = bool((KEY4U_SUNO_QUERY_ENDPOINT if key4u_configured else SHOPAIKEY_MUSIC_STATUS_ENDPOINT) and fetch_status not in {"", "NOT_TESTED", "MISSING", "NEED_DOCS"})
    latest_completed_job = latest_completed_music_suno_job_with_output()
    latest_completed_ready = bool(latest_completed_job)
    download_ready = bool(
        (provider_status_is_pass(str(download_smoke.get("status") or "")) and tool_test_result_audio_bytes_positive(download_smoke))
        or latest_completed_ready
    )
    full_result_ok = bool((fetch_status == "PASS_FULL_RESULT" and download_ready) or latest_completed_ready)
    smoke_ok = bool(provider_status_is_pass(str(submit_smoke.get("status") or "")) and full_result_ok)
    preferred_provider = "key4u_suno" if key4u_configured else ("shopaikey_music" if shopaikey_configured else "none")
    preferred_model = KEY4U_SUNO_MODEL if key4u_configured else (SHOPAIKEY_MUSIC_MODEL or "auto")
    preferred_endpoint = KEY4U_SUNO_CREATE_ENDPOINT if key4u_configured else (SHOPAIKEY_MUSIC_ENDPOINT or "")
    status_endpoint_ready = bool((KEY4U_SUNO_QUERY_ENDPOINT if key4u_configured else SHOPAIKEY_MUSIC_STATUS_ENDPOINT) if configured else False)
    public_ready = bool(configured and SUNO_PUBLIC_ENABLED and full_result_ok and music_pricing_configured())
    product_public_enabled = bool(configured and music_product_public_enabled_for_feature("music") and music_pricing_configured() and status_endpoint_ready)
    if configured:
        if public_ready:
            reason = "ready"
        elif product_public_enabled:
            reason = "ready_for_public_submit; final audio validates before charge"
        else:
            reason = "configured_for_admin_smoke; public gate remains closed until config/cost pass"
        missing = []
    else:
        reason = "Missing Key4U Suno or ShopAIKey Music configuration"
        missing = ["KEY4U_SUNO_* or SHOPAIKEY_MUSIC_*"]
    payload = _media_readiness_payload(
        name="suno_music",
        provider=preferred_provider,
        model=preferred_model,
        endpoint=preferred_endpoint,
        api_key_configured=bool((key4u_configured and KEY4U_API_KEY) or (shopaikey_configured and SHOPAIKEY_API_KEY)),
        endpoint_configured=bool(preferred_endpoint),
        admin_smoke_tool="key4u_suno" if key4u_configured else "shopaikey_music",
        public_enabled=public_ready,
        ready=configured,
        reason=reason,
        missing_env=missing,
        safe_user_message="Nhạc AI đang chờ kiểm tra tài nguyên xử lý. TOAN AAS chưa xử lý và chưa trừ Xu.",
    )
    payload.update({
        "providers": {
            "key4u_suno": {
                "configured": key4u_configured,
                "model": KEY4U_SUNO_MODEL or "",
                "endpoint_configured": bool(KEY4U_SUNO_CREATE_ENDPOINT),
                "submit_final_url": key4u_suno_final_url(KEY4U_SUNO_CREATE_ENDPOINT) if KEY4U_SUNO_CREATE_ENDPOINT else "",
                "fetch_final_url": key4u_suno_fetch_final_url() if KEY4U_SUNO_QUERY_ENDPOINT else "",
                "lyrics_final_url": key4u_suno_final_url(KEY4U_SUNO_LYRICS_ENDPOINT) if KEY4U_SUNO_LYRICS_ENDPOINT else "",
                "smoke": key4u_smoke,
                "missing_env": key4u_missing,
            },
            "shopaikey_music": {
                "configured": shopaikey_configured,
                "model": SHOPAIKEY_MUSIC_MODEL or "",
                "endpoint_configured": bool(SHOPAIKEY_MUSIC_ENDPOINT),
                "submit_final_url": shopaikey_suno_final_url(SHOPAIKEY_MUSIC_ENDPOINT) if SHOPAIKEY_MUSIC_ENDPOINT else "",
                "fetch_final_url": shopaikey_suno_fetch_final_url() if SHOPAIKEY_MUSIC_STATUS_ENDPOINT else "",
                "smoke": shopaikey_smoke,
                "missing_env": shopaikey_missing,
            },
        },
        "admin_smoke_status": f"key4u={key4u_smoke}; shopaikey={shopaikey_smoke}",
        "preferred_provider": preferred_provider,
        "submit_ready": submit_ready,
        "fetch_ready": fetch_ready,
        "download_ready": download_ready,
        "full_result_ready": full_result_ok,
        "full_result_smoke": fetch_status,
        "full_result_ok": full_result_ok,
        "product_public_enabled": product_public_enabled,
        "music_public_enabled": bool(MUSIC_PUBLIC_ENABLED and SUNO_PUBLIC_ENABLED),
        "instrumental_public_enabled": bool(MUSIC_PUBLIC_ENABLED and MUSIC_INSTRUMENTAL_PUBLIC_ENABLED and SUNO_PUBLIC_ENABLED),
        "song_public_enabled": bool(MUSIC_PUBLIC_ENABLED and MUSIC_SONG_PUBLIC_ENABLED and SUNO_PUBLIC_ENABLED),
        "status_endpoint_ready": status_endpoint_ready,
        "latest_completed_job_id": str(latest_completed_job.get("internal_job_id") or ""),
        "latest_completed_output_bytes": int(latest_completed_job.get("output_bytes") or 0),
        "processing_gate_allowed": False,
        "processing_gate_requested": bool(SUNO_ALLOW_PROCESSING_GATE),
        "cost_gate_ok": music_pricing_configured(),
    })
    return payload

def music_ai_public_processing_ready(readiness: dict | None = None) -> bool:
    readiness = dict(readiness or get_suno_music_readiness())
    return bool(
        readiness.get("ready")
        and readiness.get("public_enabled")
        and readiness.get("full_result_ok")
        and readiness.get("cost_gate_ok")
    )

def music_product_public_enabled_for_feature(feature: str = "music") -> bool:
    feature_key = normalize_engine_feature(feature)
    if feature_key in {"music_song", "suno_song", "song"}:
        return bool(MUSIC_PUBLIC_ENABLED and MUSIC_SONG_PUBLIC_ENABLED and SUNO_PUBLIC_ENABLED)
    if feature_key in {"music_background", "music_bg", "instrumental", "instrumental_ai", "background"}:
        return bool(MUSIC_PUBLIC_ENABLED and MUSIC_INSTRUMENTAL_PUBLIC_ENABLED and SUNO_PUBLIC_ENABLED)
    return bool(MUSIC_PUBLIC_ENABLED and SUNO_PUBLIC_ENABLED and (MUSIC_INSTRUMENTAL_PUBLIC_ENABLED or MUSIC_SONG_PUBLIC_ENABLED))

def music_product_submit_public_ready(readiness: dict | None = None, feature: str = "music") -> bool:
    item = dict(readiness or get_suno_music_readiness())
    if "product_public_enabled" in item:
        public_enabled = bool(item.get("product_public_enabled"))
    else:
        public_enabled = bool(item.get("public_enabled"))
    return bool(
        item.get("ready")
        and public_enabled
        and item.get("cost_gate_ok", music_pricing_configured())
        and item.get("status_endpoint_ready", item.get("fetch_ready", True))
    )

def music_product_public_ready_flags(readiness: dict | None = None) -> dict:
    item = dict(readiness or get_suno_music_readiness())
    stable = bool(music_ai_public_processing_ready(item))
    return {
        "Music": stable,
        "AI Music": stable,
        "AI Song": stable,
        "Music Vault": True,
        "Video": "unchanged",
        "Subtitle/dub": "unchanged",
        "Voice": "ON locked",
    }

def music_provider_result_task_id(payload: dict | None = None) -> str:
    return engine_provider_task_id(dict(payload or {}))

def music_provider_result_has_real_output(payload: dict | None = None) -> bool:
    payload = dict(payload or {})
    return bool(music_provider_result_task_id(payload) or engine_output_bytes(payload))

def latest_saved_minimax_voice_profile(user_id=None) -> dict:
    clauses = ["deleted_at IS NULL", "COALESCE(provider_voice_id,'')<>''", "status IN ('ready','active','saved','completed')"]
    params: list[str] = []
    if user_id is not None:
        clauses.append("user_id=?")
        params.append(str(user_id))
    try:
        with db_connect() as conn:
            cur = conn.cursor()
            cur.execute(
                f"""
                SELECT id, user_id, display_name, provider_voice_id, status
                FROM voice_profiles
                WHERE {' AND '.join(clauses)}
                ORDER BY is_default DESC, updated_at DESC, id DESC
                LIMIT 1
                """,
                params,
            )
            row = cur.fetchone()
            if not row:
                return {}
            return {
                "id": row[0],
                "user_id": row[1],
                "display_name": row[2],
                "provider_voice_id": row[3],
                "status": row[4],
            }
    except Exception as exc:
        logger.warning("latest_saved_minimax_voice_profile failed | %s", sanitize_log_text(str(exc))[:220])
    return {}

def get_minimax_voice_readiness() -> dict:
    missing = []
    shopaikey_voice_ready = bool(SHOPAIKEY_API_KEY and MINIMAX_TTS_ENDPOINT and MINIMAX_TTS_MODEL)
    key4u_voice_ready = bool(KEY4U_ENABLED and KEY4U_API_KEY and KEY4U_TTS_ENDPOINT and KEY4U_TTS_MODEL)
    direct_voice_ready = bool(MINIMAX_API_KEY and MINIMAX_GROUP_ID and (MINIMAX_DIRECT_TTS_ENDPOINT or MINIMAX_TTS_ENDPOINT) and MINIMAX_TTS_MODEL)
    for name, ok in [
        ("SHOPAIKEY_API_KEY or KEY4U_API_KEY or MINIMAX_API_KEY+MINIMAX_GROUP_ID", bool(shopaikey_voice_ready or key4u_voice_ready or direct_voice_ready)),
        ("MINIMAX_TTS_ENDPOINT or KEY4U_TTS_ENDPOINT or MINIMAX_DIRECT_TTS_ENDPOINT", bool(MINIMAX_TTS_ENDPOINT or KEY4U_TTS_ENDPOINT or MINIMAX_DIRECT_TTS_ENDPOINT)),
        ("MINIMAX_TTS_MODEL", bool(MINIMAX_TTS_MODEL)),
    ]:
        if not ok:
            missing.append(name)
    tts_snapshot = preferred_tool_test_result("minimax_tts", "minimax_tts_key4u", "minimax_tts_shopaikey", "minimax_voice_job")
    clone_snapshot = preferred_tool_test_result("minimax_voice_clone")
    smoke = str(tts_snapshot.get("status") or "NOT_TESTED")
    configured = not missing
    provider_public = bool(
        (shopaikey_voice_ready and SHOPAIKEY_ENABLED and SHOPAIKEY_TTS_ENABLED)
        or direct_voice_ready
        or (key4u_voice_ready and KEY4U_PUBLIC_ENABLED)
    )
    product_public_enabled = bool(configured and provider_public and voice_tts_product_public_enabled() and voice_pricing_configured())
    public_ready = bool(product_public_enabled and (provider_status_is_pass(smoke) or not MINIMAX_REQUIRE_SMOKE_PASS))
    reason = "ready" if configured else "Missing " + ", ".join(missing)
    if configured and not public_ready:
        reason = "configured_for_admin_smoke; public voice gate remains closed until smoke/cost pass"
    saved_profile = latest_saved_minimax_voice_profile()
    payload = _media_readiness_payload(
        name="minimax_voice",
        provider="shopaikey_minimax" if shopaikey_voice_ready else ("key4u_minimax" if key4u_voice_ready else "minimax"),
        model=MINIMAX_TTS_MODEL,
        endpoint=MINIMAX_TTS_ENDPOINT or MINIMAX_DIRECT_TTS_ENDPOINT,
        api_key_configured=bool(shopaikey_voice_ready or key4u_voice_ready or direct_voice_ready),
        endpoint_configured=bool(MINIMAX_TTS_ENDPOINT or KEY4U_TTS_ENDPOINT or MINIMAX_DIRECT_TTS_ENDPOINT),
        admin_smoke_tool="minimax_tts",
        public_enabled=public_ready,
        ready=configured,
        reason=reason,
        missing_env=missing,
        safe_user_message="⚙️ Dịch vụ giọng đọc đang kiểm tra tài nguyên xử lý. TOAN AAS chưa tạo audio và chưa trừ Xu.",
    )
    last_error = str(tts_snapshot.get("detail") or clone_snapshot.get("detail") or reason or "")
    payload.update({
        "base_url_present": bool(MINIMAX_DIRECT_BASE_URL or SHOPAIKEY_BASE_URL),
        "minimax_api_key_present": bool(MINIMAX_API_KEY or SHOPAIKEY_API_KEY or KEY4U_API_KEY),
        "group_or_project_id_present": bool(MINIMAX_GROUP_ID),
        "tts_endpoint_ready": bool((MINIMAX_TTS_ENDPOINT and SHOPAIKEY_API_KEY) or (KEY4U_TTS_ENDPOINT and KEY4U_API_KEY) or (MINIMAX_DIRECT_TTS_ENDPOINT and MINIMAX_API_KEY and MINIMAX_GROUP_ID)),
        "clone_endpoint_ready": bool((MINIMAX_VOICE_CLONE_ENDPOINT and SHOPAIKEY_API_KEY) or (KEY4U_MINIMAX_CLONE_ENDPOINT and KEY4U_API_KEY)),
        "product_public_enabled": product_public_enabled,
        "voice_public_enabled": bool(VOICE_PUBLIC_ENABLED),
        "voice_tts_public_enabled": bool(VOICE_TTS_PUBLIC_ENABLED and MINIMAX_VOICE_PUBLIC_ENABLED),
        "minimax_tts_final_url": key4u_minimax_final_url(KEY4U_TTS_ENDPOINT) if KEY4U_TTS_ENDPOINT else "",
        "minimax_clone_upload_final_url": key4u_minimax_final_url(KEY4U_MINIMAX_UPLOAD_ENDPOINT) if KEY4U_MINIMAX_UPLOAD_ENDPOINT else "",
        "minimax_clone_final_url": key4u_minimax_final_url(KEY4U_MINIMAX_CLONE_ENDPOINT) if KEY4U_MINIMAX_CLONE_ENDPOINT else "",
        "saved_voice_id_available": bool(saved_profile.get("provider_voice_id")),
        "saved_voice_id": str(saved_profile.get("provider_voice_id") or "")[:180],
        "last_tts_smoke": preferred_tool_test_status_text("minimax_tts", "minimax_tts_key4u", "minimax_tts_shopaikey", "minimax_voice_job"),
        "last_clone_smoke": preferred_tool_test_status_text("minimax_voice_clone"),
        "last_error_sanitized": shopaikey_sanitize_error(sanitize_log_text(last_error)[:260]) if last_error else "",
    })
    return payload

def voice_clone_optional_adapter_available(names: list[str]) -> bool:
    return any(callable(globals().get(name)) for name in names)

def voice_clone_last_forbidden_provider() -> str:
    attempt = load_provider_attempt("voice_clone")
    marker = " ".join(str(attempt.get(key) or "") for key in ("status", "error", "clone_status", "route")).lower()
    if not ("clone_permission_forbidden" in marker or "voice clone user forbidden" in marker or "forbidden" in marker):
        return ""
    provider = str(attempt.get("provider") or "").strip().lower()
    return provider if provider in {"shopaikey_minimax", "key4u_minimax"} else ""

def voice_clone_route_readiness_statuses(readiness: dict | None = None) -> dict:
    readiness = dict(readiness or get_minimax_voice_clone_readiness())
    blocked_provider = voice_clone_last_forbidden_provider()
    statuses = {}
    for provider, configured_key in (
        ("shopaikey_minimax", "shopaikey_configured"),
        ("key4u_minimax", "key4u_configured"),
    ):
        configured = bool(readiness.get(configured_key))
        if not configured:
            statuses[provider] = "MISSING"
        elif blocked_provider == provider:
            statuses[provider] = "BLOCKED"
        elif provider_status_is_pass(str(readiness.get("clone_smoke") or "")):
            statuses[provider] = "PASS"
        else:
            statuses[provider] = "UNKNOWN"
    return statuses

def voice_clone_active_custom_voice_route(readiness: dict | None = None) -> str:
    readability = dict(readiness or get_minimax_voice_clone_readiness())
    statuses = voice_clone_route_readiness_statuses(readability)
    for provider in ("shopaikey_minimax", "key4u_minimax"):
        if bool(readability.get("shopaikey_configured" if provider == "shopaikey_minimax" else "key4u_configured")) and statuses.get(provider) != "BLOCKED":
            return provider
    return "blocked"

def get_minimax_voice_clone_readiness() -> dict:
    shopaikey_configured = bool(
        SHOPAIKEY_API_KEY
        and MINIMAX_VOICE_UPLOAD_ENDPOINT
        and MINIMAX_VOICE_CLONE_ENDPOINT
        and MINIMAX_TTS_ENDPOINT
        and MINIMAX_TTS_MODEL
    )
    key4u_configured = bool(
        KEY4U_ENABLED
        and KEY4U_API_KEY
        and KEY4U_MINIMAX_UPLOAD_ENDPOINT
        and KEY4U_MINIMAX_CLONE_ENDPOINT
        and KEY4U_TTS_ENDPOINT
        and KEY4U_TTS_MODEL
    )
    fish_upload_ready = voice_clone_optional_adapter_available(["fish_audio_upload_voice_sample", "upload_fish_audio_voice_sample", "fish_audio_upload_sample"])
    fish_clone_ready = voice_clone_optional_adapter_available(["fish_audio_clone_voice", "clone_fish_audio_voice", "fish_audio_voice_clone"])
    elevenlabs_upload_ready = voice_clone_optional_adapter_available(["elevenlabs_upload_voice_sample", "upload_elevenlabs_voice_sample"])
    elevenlabs_clone_ready = voice_clone_optional_adapter_available(["elevenlabs_clone_voice", "clone_elevenlabs_voice", "elevenlabs_voice_clone"])
    fish_key_configured = bool(FISH_AUDIO_KEY)
    elevenlabs_key_configured = bool(ELEVENLABS_API_KEY)
    fish_configured = bool(fish_key_configured and fish_upload_ready and fish_clone_ready)
    elevenlabs_configured = bool(elevenlabs_key_configured and elevenlabs_upload_ready and elevenlabs_clone_ready)
    optional_missing = []
    if fish_key_configured and not fish_upload_ready:
        optional_missing.append("fish_audio_upload_adapter_missing")
    if fish_key_configured and not fish_clone_ready:
        optional_missing.append("fish_audio_clone_adapter_missing")
    if elevenlabs_key_configured and not elevenlabs_upload_ready:
        optional_missing.append("elevenlabs_upload_adapter_missing")
    if elevenlabs_key_configured and not elevenlabs_clone_ready:
        optional_missing.append("elevenlabs_clone_adapter_missing")
    missing = [] if (shopaikey_configured or key4u_configured or fish_configured or elevenlabs_configured) else [
        "ShopAIKey MiniMax, Key4U MiniMax, Fish Audio, or ElevenLabs clone+TTS"
    ]
    if not (shopaikey_configured or key4u_configured or fish_configured or elevenlabs_configured):
        missing.extend(optional_missing)
    tts_smoke = preferred_tool_test_status_text("minimax_tts", "minimax_tts_key4u", "minimax_tts_shopaikey", "minimax_voice_job")
    clone_smoke = preferred_tool_test_status_text("minimax_voice_clone")
    smoke_ok = provider_status_is_pass(tts_smoke) and provider_status_is_pass(clone_smoke)
    configured = bool(shopaikey_configured or key4u_configured or fish_configured or elevenlabs_configured)
    minimax_configured_routes = [
        provider
        for provider, enabled in (
            ("shopaikey_minimax", shopaikey_configured),
            ("key4u_minimax", key4u_configured),
        )
        if enabled
    ]
    blocked_provider = voice_clone_last_forbidden_provider()
    alternate_minimax_ready = bool(
        blocked_provider
        and any(provider != blocked_provider for provider in minimax_configured_routes)
    )
    provider_public = bool(
        (shopaikey_configured and SHOPAIKEY_ENABLED and SHOPAIKEY_TTS_ENABLED)
        or (key4u_configured and KEY4U_PUBLIC_ENABLED)
    )
    public_ready = bool(
        configured
        and provider_public
        and voice_tts_product_public_enabled()
        and voice_clone_product_public_enabled()
        and (smoke_ok or not MINIMAX_REQUIRE_SMOKE_PASS)
    )
    alternate_clone_ready = bool(fish_configured or elevenlabs_configured)
    permission_blocked = bool(
        voice_clone_last_forbidden_attempt()
        and not provider_status_is_pass(clone_smoke)
        and not alternate_clone_ready
        and not alternate_minimax_ready
    )
    if not configured:
        reason = "Missing " + ", ".join(missing)
    elif permission_blocked:
        reason = "clone_permission_forbidden"
    elif not public_ready:
        reason = "configured_for_admin_smoke; clone public gate remains closed until smoke/cost pass"
    else:
        reason = "ready"
    payload = {
        "ready": configured,
        "public_enabled": public_ready,
        "missing_env": missing,
        "reason": reason,
        "tts_smoke": tts_smoke,
        "clone_smoke": clone_smoke,
        "shopaikey_configured": shopaikey_configured,
        "key4u_configured": key4u_configured,
        "fish_audio_configured": fish_configured,
        "elevenlabs_configured": elevenlabs_configured,
        "fish_audio_key_configured": fish_key_configured,
        "elevenlabs_key_configured": elevenlabs_key_configured,
        "fish_audio_upload_adapter_ready": fish_upload_ready,
        "fish_audio_clone_adapter_ready": fish_clone_ready,
        "elevenlabs_upload_adapter_ready": elevenlabs_upload_ready,
        "elevenlabs_clone_adapter_ready": elevenlabs_clone_ready,
        "alternate_clone_ready": alternate_clone_ready,
        "provider_permission_blocked": permission_blocked,
        "provider_permission_blocker": "clone_permission_forbidden" if (permission_blocked or blocked_provider) else "",
        "upload_adapter_missing": optional_missing,
        "routes": [
            name
            for name, enabled in (
                ("shopaikey_minimax", shopaikey_configured),
                ("key4u_minimax", key4u_configured),
                ("fish_audio", fish_configured),
                ("elevenlabs", elevenlabs_configured),
            )
            if enabled
        ],
    }
    payload["shopaikey_clone_readiness"] = voice_clone_route_readiness_statuses(payload).get("shopaikey_minimax", "MISSING")
    payload["key4u_clone_readiness"] = voice_clone_route_readiness_statuses(payload).get("key4u_minimax", "MISSING")
    payload["active_custom_voice_route"] = voice_clone_active_custom_voice_route(payload)
    payload["blocked_provider"] = blocked_provider
    return payload

def get_asr_readiness() -> dict:
    adapter = get_asr_adapter_readiness(public=True)
    missing = []
    if not VIDEO_ASR_ENABLED:
        missing.append("VIDEO_ASR_ENABLED")
    if str(ASR_PROVIDER or "auto").strip().lower() not in {"deepgram", "auto", "shopaikey", "shopai", "key4u"}:
        missing.append("ASR_PROVIDER=auto/key4u/deepgram/shopaikey")
    if not adapter.get("ready"):
        missing.append("asr_adapter_missing")
    configured = not missing
    provider_label = str(adapter.get("adapter") or "none")
    payload = _media_readiness_payload(
        name="asr",
        provider=provider_label,
        model=ASR_PROVIDER,
        endpoint="Deepgram / Key4U STT / ShopAIKey audio transcription",
        api_key_configured=bool(adapter.get("configured")),
        endpoint_configured=bool(adapter.get("configured")),
        admin_smoke_tool="asr",
        public_enabled=bool(configured and (VIDEO_SUBTITLE_PUBLIC_ENABLED or VIDEO_TRANSLATE_SUBTITLE_PUBLIC_ENABLED or VIDEO_DUB_PUBLIC_ENABLED or VIDEO_SUBTITLE_PLUS_DUB_PUBLIC_ENABLED)),
        ready=configured,
        reason="ready" if configured else str(adapter.get("reason") or "Missing " + ", ".join(missing)),
        missing_env=missing,
        safe_user_message="⚙️ Công cụ lấy lời thoại/phụ đề đang được kiểm tra. TOAN AAS chưa xử lý video và chưa trừ Xu.",
    )
    payload.update({
        "adapter_readiness": adapter,
        "supports_audio": bool(adapter.get("supports_audio")),
        "supports_video": bool(adapter.get("supports_video")),
        "needs_audio_extract": bool(adapter.get("needs_audio_extract")),
    })
    return payload

def get_subtitle_dub_readiness() -> dict:
    pipeline = video_pipeline_status_payload()
    asr = get_asr_readiness()
    modes = {}
    for mode in (VIDEO_SUBTITLE_MODE_CREATE, VIDEO_SUBTITLE_MODE_TRANSLATE, VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB):
        cap = video_dubbing_capability(mode, public=True)
        public_ready = video_dubbing_public_processing_ready(mode)
        modes[mode] = {
            "ready": bool(public_ready),
            "reason": cap.get("reason") or "not_ready",
            "missing": cap.get("missing") or [],
            "public_enabled": bool(public_ready),
            "smoke_status": preferred_tool_test_status_text(_subtitle_dub_required_smoke(mode)),
        }
    ready = any(item.get("ready") for item in modes.values())
    missing = []
    for item in modes.values():
        missing.extend(item.get("missing") or [])
    return {
        **_media_readiness_payload(
            name="subtitle_dub_pipeline",
            provider="deepgram+translation+tts+worker",
            model=f"asr={pipeline.get('asr_provider')}; tts={pipeline.get('tts_provider')}",
            endpoint="pipeline",
            api_key_configured=bool(asr.get("api_key_configured")),
            endpoint_configured=bool(asr.get("endpoint_configured")),
            admin_smoke_tool="subtitle_plus_dub",
            public_enabled=any(item.get("public_enabled") for item in modes.values()),
            ready=ready,
            reason="ready" if ready else "No subtitle/dub public mode is ready",
            missing_env=list(dict.fromkeys(missing)),
            safe_user_message="⚙️ Phụ đề/lồng tiếng đang được kiểm tra theo từng bước. TOAN AAS chưa xử lý video và chưa trừ Xu.",
        ),
        "pipeline": pipeline,
        "modes": modes,
    }

def get_media_ai_public_status() -> dict:
    image = get_image_edit_provider_readiness()
    suno = get_suno_music_readiness()
    minimax = get_minimax_voice_readiness()
