def video_beta_requested_tiers(args: list[str] | tuple[str, ...] | None = None) -> list[str]:
    parsed = video_beta_open_parse_args(args)
    raw = str(parsed.get("tier_text") or "").strip()
    if not raw:
        return list(video_public_beta_tiers())
    raw = raw.replace("tiers=", "").replace("tier=", "").replace(" ", ",")
    requested = []
    for part in re.split(r"[,/;]+", raw):
        tier = video_public_tier_token_to_name(part)
        if tier in video_public_launch_tiers() and tier not in requested:
            requested.append(tier)
    return requested or list(video_public_beta_tiers())

def video_beta_open_result(admin_id, args: list[str] | tuple[str, ...] | None = None) -> dict:
    global VIDEO_PUBLIC_BETA_ENABLED, VIDEO_PUBLIC_ALLOWED_TIERS
    global VIDEO_AI_PUBLIC_ENABLED, VIDEO_AI_MASTER_ENABLED, SHOPAIKEY_PUBLIC_VIDEO_ENABLED, VIDEO_TEXT_TO_VIDEO_PUBLIC_ENABLED
    global VIDEO_PREMIUM_PUBLIC_ENABLED, VIDEO_IMAGE_TO_VIDEO_ENABLED, VIDEO_VIDEO_TO_VIDEO_ENABLED, VIDEO_LONG_RENDER_ENABLED, VIDEO_TREND_RENDER_ENABLED

    parsed = video_beta_open_parse_args(args)
    requested = video_beta_requested_tiers(args)
    ai_gate = video_ai_provider_smoke_gate()
    ops = current_system_mode()
    core_blockers = []
    tier_blockers = []
    if ops.get("maintenance_mode") or ops.get("tool_freeze") or ops.get("provider_freeze"):
        core_blockers.append("System maintenance/tool/provider freeze is active")
    if not ai_gate.get("ready"):
        core_blockers.extend(ai_gate.get("blockers") or ["Video AI provider smoke gate is not ready"])
    if "low" in requested and not core_blockers:
        set_video_runtime_bool("video_beta_200_marketing_loss_enabled", True, admin_id, "200 Xu starter video beta enabled")
    billing_gate = video_billing_public_gate()
    if not billing_gate.get("ready"):
        core_blockers.extend(billing_gate.get("blockers") or [])
    opened_tiers = []
    for tier in requested:
        if tier in video_public_launch_tiers() and video_tier_base_public_flag(tier):
            opened_tiers.append(tier)
        else:
            tier_blockers.append(f"{tier} is not enabled in launch tier config")
    if core_blockers or not opened_tiers:
        blockers = list(dict.fromkeys(str(item) for item in [*core_blockers, *tier_blockers] if item))
        set_system_setting("video_beta_open_last_result", "BLOCKED", "; ".join(blockers)[:1000], admin_id)
        return {
            "status": "BLOCKED",
            "opened_tiers": [],
            "requested_tiers": requested,
            "blockers": blockers,
        }
    VIDEO_PUBLIC_ALLOWED_TIERS = ",".join(opened_tiers)
    VIDEO_PUBLIC_BETA_ENABLED = True
    SHOPAIKEY_PUBLIC_VIDEO_ENABLED = True
    VIDEO_AI_PUBLIC_ENABLED = True
    VIDEO_AI_MASTER_ENABLED = True
    VIDEO_TEXT_TO_VIDEO_PUBLIC_ENABLED = True
    VIDEO_PREMIUM_PUBLIC_ENABLED = False
    VIDEO_IMAGE_TO_VIDEO_ENABLED = False
    VIDEO_VIDEO_TO_VIDEO_ENABLED = False
    VIDEO_LONG_RENDER_ENABLED = False
    VIDEO_TREND_RENDER_ENABLED = False
    set_system_setting("video_public_allowed_tiers", VIDEO_PUBLIC_ALLOWED_TIERS, "video beta open tiers", admin_id)
    set_video_runtime_bool("video_public_beta_enabled", True, admin_id, "video beta open")
    set_video_runtime_bool("shopaikey_public_video_enabled", True, admin_id, "video beta open")
    set_video_runtime_bool("video_ai_public_enabled", True, admin_id, "video beta open")
    set_video_runtime_bool("video_ai_master_enabled", True, admin_id, "video beta open")
    set_video_runtime_bool("video_text_to_video_public_enabled", True, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_200_enabled", "low" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_300_enabled", "basic" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_400_enabled", "common" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_500_enabled", "advanced" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_600_enabled", "standard" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_700_enabled", "long" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_800_enabled", "high" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_1000_enabled", "future_1000" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_1200_enabled", "future_1200" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_beta_tier_1500_enabled", "future_1500" in opened_tiers, admin_id, "video beta open")
    set_video_runtime_bool("video_public_600_plus_enabled", any(tier in opened_tiers for tier in {"advanced", "standard", "long", "high", "future_1000", "future_1200", "future_1500"}), admin_id, "video beta open")
    set_video_runtime_bool("video_premium_public_enabled", False, admin_id, "keep premium off")
    set_video_runtime_bool("video_image_to_video_enabled", False, admin_id, "keep image-to-video off")
    set_video_runtime_bool("video_video_to_video_enabled", False, admin_id, "keep video-to-video off")
    set_video_runtime_bool("video_long_render_enabled", False, admin_id, "keep long render off")
    note = f"opened={','.join(opened_tiers)}; requested={','.join(requested)}; allow_loss_200={bool(parsed.get('allow_loss_200'))}"
    set_system_setting("video_beta_open_last_result", "OPENED", note, admin_id)
    record_audit_event(admin_id, "admin", "video.beta_open", "video_public_gate", "beta_open", before={"requested": requested}, after={"opened": opened_tiers}, note=note)
    return {
        "status": "OPENED",
        "opened_tiers": opened_tiers,
        "requested_tiers": requested,
        "allow_loss_200": bool(parsed.get("allow_loss_200")),
        "blockers": list(dict.fromkeys(str(item) for item in tier_blockers if item)),
    }

def video_beta_open_text(result: dict) -> str:
    opened = result.get("opened_tiers") or []
    blockers = result.get("blockers") or []
    lines = ["🎬 <b>VIDEO BETA OPEN</b>", ""]
    opened_set = set(opened)
    if opened:
        lines.append("Đã mở public beta:")
        for _tier_id, tier in VIDEO_TIER_ID_TO_NAME.items():
            payload = video_tier_pricing_payload().get(tier) or {}
            price = int(payload.get("cost") or video_tier_cost_xu(tier))
            label = str(payload.get("label") or video_tier_short_label(tier, "vi"))
            suffix = (
                f" — MARKETING_LOSS / giới hạn {int(VIDEO_BETA_200_MAX_USER_DAY or 1)}/ngày, {int(VIDEO_BETA_200_MAX_USER_WEEK or 1)}/tuần, {int(VIDEO_BETA_200_MAX_USER_MONTH or 1)}/tháng"
                if tier == "low" and video_beta_200_marketing_loss_enabled_runtime()
                else ""
            )
            status = f"ON{suffix}" if tier in opened_set else "OFF"
            lines.append(
                f"• {VIDEO_TIER_ICONS.get(tier, '🎬')} {html.escape(label)} · "
                f"<code>{price} Xu/cảnh</code>: <code>{html.escape(status)}</code>"
            )
    else:
        lines.append("Chưa mở public beta.")
    if blockers:
        lines.extend(["", "<b>Blockers</b>"])
        lines.extend(f"• <code>{html.escape(str(item))}</code>" for item in blockers[:12])
    if "low" in opened and video_beta_200_marketing_loss_enabled_runtime():
        row = check_video_margin("low")
        ratio = row.get("cost_ratio")
        ratio_text = "-" if ratio is None else f"{float(ratio):.2f}"
        lines.extend([
            "",
            "<b>Cảnh báo</b>",
            f"• <code>200 Xu</code> có cost ratio <code>{html.escape(ratio_text)}</code>, vượt ngưỡng lời. Đây là gói mồi có kiểm soát.",
        ])
    lines.extend([
        "",
        "Giữ OFF: long render, image-to-video và video-to-video.",
        "Không gọi provider trong lệnh này. Không trừ Xu.",
    ])
    return "\n".join(lines)

