def subdub_long_video_audit_payload() -> dict:
    full_limit = int(subdub_full_duration_limit_seconds(False))
    duration_unbounded = full_limit <= 0
    preview_limit = int(subdub_preview_duration_seconds())
    source = "\n".join([
        inspect.getsource(subdub_duration_gate_payload),
        inspect.getsource(subdub_duration_gate_payload_for_saved_input),
        inspect.getsource(_execute_video_dubbing_pipeline_core),
        inspect.getsource(subdub_send_progress_update),
        inspect.getsource(subdub_progress_job_for_user),
    ])
    full_job_30_patterns = (
        r"min\s*\(\s*30",
        r"max_seconds\s*=\s*30",
        r"duration\s*[<>]=?\s*30",
    )
    hardcoded_30_full_job = any(re.search(pattern, source) for pattern in full_job_30_patterns)
    accepted_31 = subdub_duration_gate_payload({"duration": 31}, {}, is_admin=False)
    accepted_60 = subdub_duration_gate_payload({"duration": 60}, {}, is_admin=False)
    accepted_299 = subdub_duration_gate_payload({"duration": 299}, {}, is_admin=False)
    over_limit = (
        subdub_duration_gate_payload({"duration": full_limit + 1}, {}, is_admin=False)
        if not duration_unbounded
        else {}
    )
    long_stage_percent = subdub_progress_percent_for_lifecycle("extracting_audio")
    sample_public_text = subdub_progress_text("extracting_audio", "AUDITJOB", "vi")
    return {
        "preview_limit_seconds": preview_limit,
        "full_duration_limit_seconds": full_limit,
        "preview_limit_separate_from_full_job": bool(
            preview_limit == 30 and (duration_unbounded or full_limit > preview_limit)
        ),
        "supports_31s": bool(accepted_31.get("duration_gate_result") == "pass_long" and accepted_31.get("long_media_allowed")),
        "supports_60s": bool(accepted_60.get("duration_gate_result") == "pass_long" and accepted_60.get("long_media_allowed")),
        "supports_299s": bool(accepted_299.get("duration_gate_result") in {"pass_long", "pass"} and not str(accepted_299.get("duration_gate_result")).startswith("fail")),
        "over_limit_fails_clean_no_charge": bool(
            duration_unbounded or over_limit.get("duration_gate_result") == "fail_over_limit"
        ),
        "accepted_long_progress_beyond_5": bool(long_stage_percent > 5),
        "progress_registry_available": "SUBTITLE_DUB_PIPELINE_JOBS" in globals() and callable(subdub_progress_job_for_user),
        "status_refresh_uses_existing_job": "subdub_progress_job_for_user" in inspect.getsource(handle_video_dubbing_callback),
        "worker_claim_fields_present": all(key in inspect.getsource(acquire_subtitle_dub_pipeline_job) for key in ("worker_claim_required", "worker_claimed")),
        "full_job_hardcoded_30_gate_absent": not hardcoded_30_full_job,
        "public_long_status_no_debug_terms": not product_progress_status.public_copy_has_technical_words(sample_public_text),
    }

def subdub_audit_text(title: str, payload: dict) -> str:
    lines = [f"🧾 <b>{html.escape(title)}</b>", ""]
    for key, value in payload.items():
        if isinstance(value, (dict, list, tuple)):
            value = json.dumps(value, ensure_ascii=False, sort_keys=True)
        lines.append(f"• {html.escape(str(key))}: <code>{html.escape(str(value))}</code>")
    return "\n".join(lines)

def subdub_normalize_lookup_id(value: str = "") -> str:
    text = str(value or "").strip()
    if text.startswith("#"):
        text = text[1:]
    return re.sub(r"[^A-Za-z0-9_.:-]+", "", text).strip().lower()

def subdub_lookup_variants(value: str = "") -> set[str]:
    raw = str(value or "").strip()
    variants = {subdub_normalize_lookup_id(raw)}
    if raw:
        variants.add(subdub_normalize_lookup_id(product_progress_status.product_progress_public_job_code(raw)))
        variants.add(subdub_normalize_lookup_id(subdub_public_job_code(raw)))
    return {item for item in variants if item}

def subdub_job_identifier_variants(job: dict | None = None) -> set[str]:
    current = dict(job or {})
    ids: set[str] = set()
    for key in (
        "internal_job_id", "job_id", "public_job_id", "public_code",
        "job_key", "provider_task_id", "pipeline_job_id", "registry_job_id",
        "subdub_public_job_id", "terminal_public_outcome_message_id",
    ):
        value = str(current.get(key) or "").strip()
        if value:
            ids.update(subdub_lookup_variants(value))
    return {item for item in ids if item}

def subdub_classify_bad_request(reason: str = "", *, stage: str = "", job: dict | None = None) -> str:
    current = dict(job or {})
    text = " ".join(
        str(item or "")
        for item in (
            reason,
            stage,
            current.get("last_error_stage"),
            current.get("pipeline_blocker"),
            current.get("last_technical_error"),
            current.get("delivery_reason"),
            current.get("render_detail"),
            current.get("mux_status"),
        )
    ).lower()
    if "badrequest" not in text and "bad request" not in text:
        return ""
    if any(token in text for token in ("subdub_delivery_debug", "debug_render", "render_debug", "debug command", "debug_read_failed")):
        return "debug_render_bad_request"
    if any(token in text for token in ("edit", "panel", "message is not modified", "message to edit", "status_panel")):
        return "panel_edit_bad_request"
    if "audio" in text:
        return "audio_delivery_bad_request"
    if any(token in text for token in ("video", "document", "mp4", "mux", "ffmpeg", "render", "file")):
        return "video_delivery_bad_request"
    if any(token in text for token in ("send", "reply", "delivery", "telegram")):
        return "telegram_send_bad_request"
    return "unknown_bad_request"

def subdub_merge_debug_job(job: dict | None = None, *, lookup_store_hit: str = "") -> dict:
    current = dict(job or {})
    # Nested debug snapshots are historical context. Canonical persisted root
    # fields must win so a stale in-memory stage cannot overwrite DB truth.
    merged = {**dict(current.get("debug_job") or {}), **current}
    # Older successful jobs persisted the authoritative input-save receipt only
    # in the nested object while leaving root defaults false. Promote a proven
    # successful receipt so historical production diagnostics remain truthful.
    nested_input_save = dict(merged.get("input_save") or {})
    if nested_input_save:
        input_save_fields = subdub_input_save_debug_fields(nested_input_save, merged)
        explicit_input_failure = bool(
            str(merged.get("input_save_blocker") or "").strip()
            or str(merged.get("no_charge_reason") or "").strip()
            or merged.get("telegram_download_limit_hit")
        )
        if input_save_fields.get("input_save_success") and not explicit_input_failure:
            merged.update(input_save_fields)
        elif not input_save_fields.get("input_save_success"):
            for key, value in input_save_fields.items():
                merged.setdefault(key, value)
    video_delivery_message_id = str(
        merged.get("video_delivery_message_id")
        or merged.get("final_video_message_id")
        or merged.get("subdub_final_video_message_id")
        or ""
    ).strip()
    delivered_video_receipt = bool(
        video_delivery_message_id
        and (
            merged.get("final_mp4_delivered")
            or str(merged.get("terminal_state") or "").strip().lower() == "delivered"
        )
    )
    if delivered_video_receipt:
        # This is historical receipt truth (the MP4 existed and was validated at
        # delivery), not a claim that the temporary workspace still exists.
        merged["final_mp4_exists"] = True
        merged["final_mp4_validated"] = True
        merged["final_mp4_delivered"] = True
    merged = subdub_enrich_job_identity(merged, job_key=str(current.get("job_key") or ""))
    if lookup_store_hit and not merged.get("lookup_store_hit"):
        merged["lookup_store_hit"] = lookup_store_hit
    checked = list(merged.get("lookup_stores_checked") or [])
    if lookup_store_hit and lookup_store_hit not in checked:
        checked.append(lookup_store_hit)
        merged["lookup_stores_checked"] = checked
    public_code = subdub_existing_public_code(merged) or subdub_public_code_value(merged.get("job_id") or merged.get("internal_job_id") or "")
    if public_code:
        merged["public_code"] = public_code
        merged["public_job_id"] = public_code
        merged["subdub_public_job_id"] = public_code
        merged["progress_public_code"] = f"#{public_code}"
    voice_config = subdub_default_voice_config_payload()
    for key, value in voice_config.items():
        if key not in merged or merged.get(key) in (None, ""):
            merged[key] = value
    merged.setdefault("tts_backend", str(TTS_PROVIDER or voice_tts_backend_choice() or "auto"))
    merged.setdefault("persisted_job_status", str(merged.get("status") or ""))
    merged["bad_request_classification"] = subdub_classify_bad_request(
        merged.get("pipeline_blocker")
        or merged.get("last_technical_error")
        or merged.get("last_error_safe")
        or merged.get("status")
        or "",
        stage=merged.get("last_error_stage") or merged.get("stage") or "",
        job=merged,
    )
    return merged

def subdub_engine_async_persisted_scan(limit: int = 240) -> list[dict]:
    jobs: list[dict] = []
    conn = None
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            "SELECT value FROM system_settings WHERE key LIKE ? ORDER BY updated_at DESC LIMIT ?",
            (ENGINE_ASYNC_JOB_PREFIX + "%", max(1, int(limit or 240))),
        )
        for row in c.fetchall() or []:
            raw = row[0] if row else ""
            try:
                value = json.loads(raw or "{}")
            except Exception:
                continue
            if isinstance(value, dict) and str(value.get("feature") or "").strip().lower() == "subtitle_dub":
                jobs.append(value)
    except sqlite3.OperationalError as exc:
        if "no such table: system_settings" not in str(exc).lower():
            logger.warning("subtitle/dub persisted scan failed | %s", sanitize_log_text(str(exc))[:160])
    except Exception as exc:
        logger.warning("subtitle/dub persisted scan failed | %s", sanitize_log_text(str(exc))[:160])
    finally:
        if conn:
            conn.close()
    return jobs

def subdub_debug_missing_payload(arg: str = "", command: str = "") -> dict:
    return {
        "_lookup_missing": True,
        "lookup_input": str(arg or "").strip(),
        "command": str(command or "").strip(),
        "searched": sorted(subdub_lookup_variants(arg)),
        "lookup_store_hit": "",
        "lookup_stores_checked": ["engine_async_direct", "subtitle_dub_memory", "engine_async_feature_index", "engine_async_persisted_scan"],
        "public_code": product_progress_status.product_progress_public_job_code(arg),
        "internal_job_id": "",
        "persisted_job_status": "",
        "terminal_public_outcome_sent": False,
        "success_sent_count": 0,
        "public_error_sent_count": 0,
        "success_after_error_prevented": False,
        "late_fail_suppressed": False,
        "status_panel_edit_failed": False,
        "result_delivery_failed": False,
        "persistence_backend": "memory_engine_async_and_persisted_scan",
        "pipeline_blocker": "job_lookup_missing",
        "status": "missing",
    }

def subtitle_dub_debug_lookup_job(arg: str = "") -> dict:
    wanted = str(arg or "").strip()
    if wanted:
        wanted_variants = subdub_lookup_variants(wanted)
        direct_ids = [wanted, wanted.lstrip("#"), *sorted(wanted_variants)]
        for lookup_id in direct_ids:
            job = get_engine_async_job(lookup_id)
            if job:
                return subdub_merge_debug_job(job, lookup_store_hit="engine_async_direct")
        for candidate in SUBTITLE_DUB_PIPELINE_JOBS.values():
            merged = subdub_merge_debug_job(candidate, lookup_store_hit="subtitle_dub_memory")
            if wanted_variants & subdub_job_identifier_variants(merged):
                return merged
        for candidate in list_engine_async_jobs("subtitle_dub", limit=80):
            merged = subdub_merge_debug_job(candidate, lookup_store_hit="engine_async_feature_index")
            if wanted_variants & subdub_job_identifier_variants(merged):
                return merged
        for candidate in subdub_engine_async_persisted_scan(limit=240):
            merged = subdub_merge_debug_job(candidate, lookup_store_hit="engine_async_persisted_scan")
            if wanted_variants & subdub_job_identifier_variants(merged):
                return merged
        return {}
    candidates = [subdub_merge_debug_job(item, lookup_store_hit="engine_async_feature_index") for item in list_engine_async_jobs("subtitle_dub", limit=12)]
    candidates.extend(
        subdub_merge_debug_job(item, lookup_store_hit="subtitle_dub_memory")
        for item in SUBTITLE_DUB_PIPELINE_JOBS.values()
    )
    if not candidates:
        candidates.extend(
            subdub_merge_debug_job(item, lookup_store_hit="engine_async_persisted_scan")
            for item in subdub_engine_async_persisted_scan(limit=12)
        )
    if not candidates:
        return {}
    def _sort_time(item: dict) -> float:
        return subdub_job_timestamp(item.get("updated_at") or item.get("started_at") or item.get("created_at") or 0)
    return max(candidates, key=_sort_time)

