def music_pricing_configured() -> bool:
    return bool(
        int(MUSIC_AI_15S_PRICE_XU or 0) > 0
        and int(MUSIC_AI_30S_PRICE_XU or 0) > 0
        and int(MUSIC_AI_EXTRA_30S_PRICE_XU or 0) >= 0
        and int(MUSIC_AI_PRICE_ROUND_TO_XU or 0) > 0
    )

