def key4u_extract_balance_usd(result: dict) -> float | None:
    if not result or not result.get("ok"):
        return None
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    candidates = []
    for key in ("balance", "remaining", "credit", "credits", "available", "amount"):
        value = data.get(key)
        if isinstance(value, (int, float, str)):
            candidates.append(value)
    nested = data.get("data")
    if isinstance(nested, dict):
        for key in ("balance", "remaining", "credit", "credits", "available", "amount", "usd"):
            value = nested.get(key)
            if isinstance(value, (int, float, str)):
                candidates.append(value)
        wallet = nested.get("wallet")
        if isinstance(wallet, dict):
            value = wallet.get("balance")
            if isinstance(value, (int, float, str)):
                candidates.append(value)
    for value in candidates:
        try:
            return float(str(value).replace("$", "").strip())
        except Exception:
            continue
    return None

def key4u_configured_usage_url() -> str:
    return (
        str(KEY4U_USAGE_ENDPOINT or "").strip()
        or str(KEY4U_USAGE_URL or "").strip()
        or str(KEY4U_USAGE_CHECK_URL or "").strip()
        or str(KEY4U_BALANCE_ENDPOINT or "").strip()
        or str(KEY4U_BALANCE_URL or "").strip()
        or str(KEY4U_WALLET_BALANCE_URL or "").strip()
    )

def key4u_usage_auth_configured() -> bool:
    return bool(
        str(KEY4U_USAGE_AUTH_HEADER_VALUE or "").strip()
        or str(KEY4U_SYSTEM_API_KEY or "").strip()
        or str(KEY4U_API_KEY or "").strip()
        or str(KEY4U_VIDEO_AUTH_HEADER_VALUE or "").strip()
    )

def key4u_usage_auth_source_info() -> dict:
    candidates = (
        ("usage_auth_header_value", KEY4U_USAGE_AUTH_HEADER_VALUE),
        ("system_api_key", KEY4U_SYSTEM_API_KEY),
        ("api_key", KEY4U_API_KEY),
        ("video_auth_header_value", KEY4U_VIDEO_AUTH_HEADER_VALUE),
    )
    source = "missing"
    raw_value = ""
    for candidate_source, candidate_value in candidates:
        value = str(candidate_value or "").strip()
        if value:
            source = candidate_source
            raw_value = value
            break
    header_name = str(KEY4U_USAGE_AUTH_HEADER_NAME or "Authorization").strip() or "Authorization"
    configured_mode = str(KEY4U_USAGE_AUTH_MODE or "").strip().lower().replace("-", "_")
    if configured_mode in {"x_api_key", "xapikey", "x_api"}:
        header_name = "x-api-key"
    elif configured_mode in {"api_key", "apikey"}:
        header_name = "api-key"
    elif configured_mode in {"authorization_raw", "raw", "authorization"}:
        header_name = "Authorization"
    header_value = raw_value
    auth_mode = configured_mode or ("x_api_key" if header_name.lower() == "x-api-key" else "api_key" if header_name.lower() == "api-key" else "authorization_bearer")
    if auth_mode == "authorization_bearer" and header_name.lower() == "authorization" and header_value and not header_value.lower().startswith(("bearer ", "apikey ", "key ", "basic ")):
        header_value = f"Bearer {header_value}"
    scheme_prefix = "missing"
    if header_value:
        scheme_prefix = header_value.split(" ", 1)[0] if " " in header_value else "raw"
    return {"source": source, "header_name": header_name, "scheme_prefix": scheme_prefix, "auth_mode": auth_mode}

def key4u_usage_endpoint_debug() -> dict:
    raw_url = key4u_configured_usage_url()
    parsed = urlparse(raw_url) if raw_url else None
    return {
        "usage_endpoint_host": parsed.netloc if parsed else "",
        "usage_endpoint_path": parsed.path if parsed else "",
    }

def key4u_credit_diagnostic_from_results(remote_usage: dict | None = None, remote_balance_result: dict | None = None) -> dict:
    remote_usage = remote_usage or {}
    remote_balance_result = remote_balance_result or {}
    balance = key4u_extract_balance_usd(remote_balance_result)
    source = "balance_endpoint"
    if balance is None:
        balance = key4u_extract_balance_usd(remote_usage)
        source = "usage_endpoint" if balance is not None else "unknown"
    endpoint_configured = bool(key4u_configured_usage_url())
    reason = ""
    if balance is not None:
        reason = "key4u_usage_balance_ok"
    elif not endpoint_configured:
        reason = "key4u_usage_url_missing"
    elif not key4u_usage_auth_configured():
        reason = "key4u_usage_auth_missing"
    elif balance is None:
        reason = str(
            (remote_balance_result or {}).get("error_class")
            or (remote_usage or {}).get("error_class")
            or (remote_balance_result or {}).get("status")
            or (remote_usage or {}).get("status")
            or "key4u_usage_balance_unknown"
        )
    usage_debug_source = remote_balance_result if (remote_balance_result or {}).get("raw_debug_admin_only") else remote_usage
    usage_debug = dict((usage_debug_source or {}).get("raw_debug_admin_only") or {})
    auth_info = key4u_usage_auth_source_info()
    endpoint_debug = key4u_usage_endpoint_debug()
    usage_http_status = int(
        usage_debug.get("usage_http_status")
        or (usage_debug_source or {}).get("http_status")
        or 0
    )
    safe_reason = str(usage_debug.get("usage_reason") or reason)
    if usage_debug.get("usage_endpoint_candidates_tried") and not balance and safe_reason in {"FAIL_AUTH", "NOT_FOUND", "FAIL", "FAIL_HTTP"}:
        safe_reason = "KEY4U_USERAPIKEY_ENDPOINT_NOT_FOUND_OR_FORBIDDEN"
    connectivity_status = str(usage_debug.get("usage_connectivity_status") or "UNKNOWN")
    balance_status = str(usage_debug.get("usage_balance_status") or ("PASS" if balance is not None else "UNKNOWN"))
    health_status = str(usage_debug.get("usage_health_status") or "UNKNOWN")
    if balance is None and connectivity_status == "PASS" and balance_status != "PASS" and health_status == "PASS":
        safe_reason = "KEY4U_HEALTH_OK_BALANCE_ENDPOINT_NOT_FOUND"
    return {
        "provider": "key4u",
        "endpoint_configured": endpoint_configured,
        "auth_configured": key4u_usage_auth_configured(),
        "credit": f"{key4u_format_usd_amount(balance)} USD" if balance is not None else "unknown",
        "balance_usd": balance,
        "source": source,
        "reason": safe_reason,
        "usage_auth_source": usage_debug.get("usage_auth_source") or auth_info["source"],
        "usage_auth_header_name": usage_debug.get("usage_auth_header_name") or auth_info["header_name"],
        "usage_auth_scheme_prefix": usage_debug.get("usage_auth_scheme_prefix") or auth_info["scheme_prefix"],
        "usage_auth_mode": usage_debug.get("usage_auth_mode") or auth_info["auth_mode"],
        "usage_endpoint_host": usage_debug.get("usage_endpoint_host") or endpoint_debug["usage_endpoint_host"],
        "usage_endpoint_path": usage_debug.get("usage_endpoint_path") or endpoint_debug["usage_endpoint_path"],
        "usage_http_status": usage_http_status,
        "usage_endpoint_candidates_tried": usage_debug.get("usage_endpoint_candidates_tried") or [],
        "usage_auth_modes_tried": usage_debug.get("usage_auth_modes_tried") or [],
        "usage_last_http_status": int(usage_debug.get("usage_last_http_status") or usage_http_status or 0),
        "usage_last_error_message_safe": usage_debug.get("usage_last_error_message_safe") or "",
        "usage_success_endpoint_host_path": usage_debug.get("usage_success_endpoint_host_path") or "",
        "usage_success_auth_mode": usage_debug.get("usage_success_auth_mode") or "",
        "usage_connectivity_status": connectivity_status,
        "usage_balance_status": balance_status,
        "usage_balance_value": usage_debug.get("usage_balance_value") or (key4u_format_usd_amount(balance) if balance is not None else ""),
        "usage_success_endpoint_type": usage_debug.get("usage_success_endpoint_type") or "",
        "usage_health_status": health_status,
        "usage_health_http": int(usage_debug.get("usage_health_http") or 0),
        "usage_health_endpoint_host_path": usage_debug.get("usage_health_endpoint_host_path") or "",
        "usage_balance_http": int(usage_debug.get("usage_balance_http") or 0),
        "usage_balance_parse_endpoint_host_path": usage_debug.get("usage_balance_parse_endpoint_host_path") or "",
        "usage_balance_parse_fields": usage_debug.get("usage_balance_parse_fields") or "",
        "usage_log_status": usage_debug.get("usage_log_status") or "UNKNOWN",
        "usage_log_endpoint_host_path": usage_debug.get("usage_log_endpoint_host_path") or "",
        "usage_groups_status": usage_debug.get("usage_groups_status") or "UNKNOWN",
        "usage_groups_endpoint_host_path": usage_debug.get("usage_groups_endpoint_host_path") or "",
        "usage_connectivity_endpoint_host_path": usage_debug.get("usage_connectivity_endpoint_host_path") or "",
        "usage_response_shape": usage_debug.get("usage_response_shape") or "",
        "usage_reason": safe_reason,
        "usage_status": str((remote_usage or {}).get("status") or ("UNKNOWN" if not endpoint_configured else "-")),
        "balance_status": str((remote_balance_result or {}).get("status") or ("UNKNOWN" if not endpoint_configured else "-")),
    }

async def key4u_credit_diagnostic(refresh_remote: bool = False) -> dict:
    if not key4u_configured_usage_url():
        return key4u_credit_diagnostic_from_results(
            {"status": "UNKNOWN", "error_class": "key4u_usage_url_missing"},
            {"status": "UNKNOWN", "error_class": "key4u_usage_url_missing"},
        )
    if not key4u_usage_auth_configured():
        return key4u_credit_diagnostic_from_results(
            {"status": "UNKNOWN", "error_class": "key4u_usage_auth_missing"},
            {"status": "UNKNOWN", "error_class": "key4u_usage_auth_missing"},
        )
    if not refresh_remote:
        return key4u_credit_diagnostic_from_results({"status": "CONFIGURED"}, {"status": "CONFIGURED"})
    provider = key4u_provider_instance()
    remote_usage = await provider.get_usage() if KEY4U_USAGE_ENDPOINT else {"status": "UNKNOWN", "error_class": "key4u_usage_url_missing"}
    remote_balance = await provider.get_balance() if KEY4U_BALANCE_ENDPOINT else {"status": "UNKNOWN", "error_class": "key4u_usage_url_missing"}
    return key4u_credit_diagnostic_from_results(remote_usage, remote_balance)

def key4u_warning_text(remote_balance: float | None, manual_balance: float | None, estimated_used: float = 0.0) -> str:
    balance = remote_balance
    source = "remote"
    if balance is None and manual_balance is not None:
        balance = max(0.0, float(manual_balance) - float(estimated_used or 0))
        source = "manual_estimated"
    if balance is None:
        return "BALANCE_REMOTE_UNKNOWN"
    if balance <= float(KEY4U_LOW_BALANCE_FREEZE_USD or 2):
        return f"CREDIT_CRITICAL_{source}"
    if balance <= float(KEY4U_LOW_BALANCE_WARN_USD or 5):
        return f"CREDIT_LOW_{source}"
    return "OK"

