async def cmd_key4u_suno_download_probe(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    if not has_admin_paid_confirmation(context):
        return await update.message.reply_text(admin_paid_confirm_required_text("/key4u_suno_download_probe <MUS-job-id>"), parse_mode="HTML")
    args = args_without_admin_paid_confirmation(context.args or [])
    job_id = str((args or [""])[0] or "").strip()
    if not job_id:
        return await update.message.reply_text("Cú pháp: /key4u_suno_download_probe <MUS-job-id> --confirm-paid")
    if not job_id.upper().startswith("MUS-"):
        return await update.message.reply_text("Vui lòng dùng MUS-id nội bộ. Lệnh này không cần raw provider task id.")
    polled = await poll_music_suno_async_job(job_id, updated_by=update.effective_user.id, download=True)
    job = dict(polled.get("job") or get_engine_async_job(job_id) or {})
    if polled.get("ok") and polled.get("audio_bytes"):
        if music_job_full_already_sent(job, polled.get("audio_bytes")):
            return await update.message.reply_text("✅ Đã gửi bản nhạc phía trên.\n\n" + engine_async_status_text(job, admin=True), parse_mode="HTML")
        audio = video_dubbing_output_file(bytes(polled.get("audio_bytes") or b""), "toan_aas_suno_download_probe.mp3")
        sent_message = await context.bot.send_audio(
            chat_id=update.effective_chat.id,
            audio=audio,
            filename="toan_aas_suno_download_probe.mp3",
            caption=f"✅ Download probe PASS: bytes={len(polled.get('audio_bytes') or b'')}.",
        )
        job = record_music_job_full_send(job, sent_message, bytes(polled.get("audio_bytes") or b""), result=job, updated_by=update.effective_user.id)
    return await update.message.reply_text(engine_async_status_text(job, admin=True), parse_mode="HTML")

async def handle_engine_async_job_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    await query.answer()
    uid = query.from_user.id if query.from_user else 0
    parts = str(query.data or "").split("|")
    kind = parts[1] if len(parts) > 1 else ""
    job_id = parts[2] if len(parts) > 2 else ""
    if not job_id:
        return await safe_edit_or_send(query, "⚠️ Thiếu internal job id. TOAN AAS chưa gọi provider mới.")
    if kind == "music":
        job = get_engine_async_job(job_id)
        if not job:
            return await safe_edit_or_send(query, "⚠️ Không tìm thấy job nhạc nội bộ.")
        if not is_admin_user(uid) and str(job.get("user_id") or "") != str(uid):
            return await safe_edit_or_send(query, "⚠️ Không tìm thấy job của bạn. TOAN AAS chưa gọi provider mới.")
        if str(job.get("status") or "").lower() == "completed" and int(job.get("output_bytes") or 0) > 0:
            upsert_music_vault_from_completed_job(job, updated_by=uid)
            job = get_engine_async_job(job_id) or job
        else:
            polled = await poll_music_suno_async_job(job_id, updated_by=uid, download=True)
            job = dict(polled.get("job") or get_engine_async_job(job_id) or {})
            if polled.get("ok") and polled.get("audio_bytes"):
                vault_entry = upsert_music_vault_from_output(
                    audio_bytes=bytes(polled.get("audio_bytes") or b""),
                    result=job,
                    job=job,
                    status=music_vault_status_for_completed_job(job),
                    updated_by=uid,
                )
                job["vault_id"] = str(vault_entry.get("vault_id") or job.get("vault_id") or "")
                save_engine_async_job(job)
            else:
                upsert_music_vault_from_completed_job(job, updated_by=uid)
                job = get_engine_async_job(job_id) or job
        return await safe_edit_or_send(
            query,
            "\n".join(_music_suno_job_lines(job, admin=bool(is_admin_user(uid)))),
            reply_markup=engine_async_status_keyboard(job_id, "music"),
            parse_mode="HTML",
        )
    if kind == "multiscene":
        if not is_admin_user(uid):
            return await safe_edit_or_send(query, ENGINE_ASYNC_PUBLIC_CHECKING_VI)
        polled = await poll_multiscene_job_once(job_id, updated_by=uid)
        job = dict(polled.get("job") or get_multiscene_job_record(job_id) or {})
        return await safe_edit_or_send(
            query,
            multiscene_job_status_text(job, admin=True),
            reply_markup=engine_async_status_keyboard(job_id, "multiscene") if job else None,
            parse_mode="HTML",
        )
    if kind in {"multiscene_retry", "multiscene_retry_confirm"}:
        if not is_admin_user(uid):
            return await safe_edit_or_send(query, ENGINE_ASYNC_PUBLIC_CHECKING_VI)
        job = get_multiscene_job_record(job_id)
        confirmed = kind == "multiscene_retry_confirm"
        return await safe_edit_or_send(
            query,
            multiscene_retry_help_text(job, confirmed=confirmed, fallback_verified=key4u_public_video_fallback_ready()),
            reply_markup=multiscene_retry_help_keyboard(job_id, confirmed=confirmed),
            parse_mode="HTML",
        )
    return await safe_edit_or_send(query, "⚠️ Loại job chưa được hỗ trợ. TOAN AAS chưa gọi provider mới.")

async def cmd_tool_test_key4u_rerank(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    provider = key4u_provider_instance()
    query = " ".join(context.args or []).strip() or "video quảng cáo nước hoa nam"
    candidates = [
        "Prompt quảng cáo sản phẩm 9:16",
        "Storyboard cinematic thương hiệu",
        "Caption bán hàng TikTok",
    ]
    result = await provider.rerank(query=query, candidates=candidates)
    detail = key4u_smoke_detail(result)
    save_tool_test_result("key4u_rerank", result.get("status") or "FAIL", detail, update.effective_user.id)
    record_api_debug("key4u", "tool_test_key4u_rerank", result.get("status") or "FAIL", int(result.get("http_status") or 0), detail)
    record_key4u_smoke_usage(update.effective_user.id, result, "key4u_rerank_smoke")
    await reply_html_lines(update, key4u_result_lines("Key4U Rerank Smoke", result))

