def music_product_text_looks_like_lyrics(text: str = "") -> bool:
    raw = str(text or "").strip()
    if not raw:
        return False
    lowered = raw.lower()
    section_pattern = r"(?im)^\s*[\[\(（]?\s*(verse|chorus|hook|bridge|intro|outro|pre[- ]?chorus|điệp khúc|diep khuc|đoạn|doan|lời|loi)\s*[\]\)）:]?"
    if re.search(section_pattern, raw):
        return True
    lines = [line.strip() for line in raw.splitlines() if line.strip()]
    if len(lines) >= 4 and not any(token in lowered for token in ("genre:", "style:", "mood:", "thể loại:", "phong cách:", "cảm xúc:")):
        return True
    return False

def music_product_parse_details(text: str = "", mode: str = "background", tier: str = "", vocal_mode: str = "auto") -> dict:
    raw_text = str(text or "").strip()
    parsed: dict[str, str] = {}
    current_key = ""
    key_map = {
        "mô tả": "description",
        "mo ta": "description",
        "description": "description",
        "chủ đề": "theme",
        "chu de": "theme",
        "theme": "theme",
        "tiêu đề": "title",
        "tieu de": "title",
        "title": "title",
        "thể loại": "genre",
        "the loai": "genre",
        "genre": "genre",
        "style": "style",
        "phong cách": "style",
        "phong cach": "style",
        "style nhạc": "style_prompt",
        "style nhac": "style_prompt",
        "gợi ý âm nhạc": "style_prompt",
        "goi y am nhac": "style_prompt",
        "music prompt": "style_prompt",
        "music style": "style_prompt",
        "style prompt": "style_prompt",
        "cảm xúc": "mood",
        "cam xuc": "mood",
        "mood": "mood",
        "ngôn ngữ": "language",
        "ngon ngu": "language",
        "language": "language",
        "thời lượng": "duration",
        "thoi luong": "duration",
        "duration": "duration",
        "lời": "lyrics",
        "loi": "lyrics",
        "lời hát": "lyrics",
        "loi hat": "lyrics",
        "lyrics": "lyrics",
    }
    for line in raw_text.splitlines():
        match = re.match(r"^\s*([^:：-]{2,64})\s*[:：-]\s*(.*)$", line)
        if match:
            label = match.group(1).strip().lower()
            normalized = unicodedata.normalize("NFC", label)
            current_key = key_map.get(normalized, key_map.get(unicodedata.normalize("NFD", label).encode("ascii", "ignore").decode("ascii"), ""))
            if current_key:
                parsed[current_key] = match.group(2).strip()
                continue
        if current_key:
            parsed[current_key] = (parsed.get(current_key, "") + "\n" + line).strip()
    mode_key = normalize_music_product_mode(mode)
    if not parsed:
        if mode_key == "song":
            parsed["theme"] = raw_text
            parsed["lyrics"] = raw_text if music_product_text_looks_like_lyrics(raw_text) else ""
        else:
            parsed["description"] = raw_text
    duration_default = MUSIC_PRODUCT_DEFAULT_SONG_SECONDS if mode_key == "song" else MUSIC_PRODUCT_DEFAULT_BACKGROUND_SECONDS
    duration_match = re.search(r"\d+", parsed.get("duration", "") or raw_text)
    seconds = normalize_music_duration_seconds(duration_match.group(0), duration_default) if duration_match else duration_default
    parsed.update({
        "music_product_mode": mode_key,
        "music_product_tier": normalize_music_product_tier_for_mode(tier, mode_key),
        "duration_seconds": seconds,
        "vocal_mode": normalize_song_vocal_mode(vocal_mode),
    })
    if mode_key == "song" and not str(parsed.get("lyrics") or "").strip():
        parsed["lyrics"] = ""
    return parsed

