def music_product_idea_keyboard(
    mode: str = "background",
    lang: str = "vi",
    product_context: str = PRODUCT_CONTEXT_SHOWROOM,
) -> InlineKeyboardMarkup:
    ctx = normalize_product_context(product_context)
    cb = lambda action: product_context_callback("music_quick", ctx, action)
    mode_key = normalize_music_product_mode(mode)
    back_action = "music_product_change_vocal" if mode_key == "song" else "music_product_change_tier"
    sample_label = f"✨ {_audio_copy(lang, 'sample')}"
    manual_label = f"✍️ {_audio_copy(lang, 'lyrics')}"
    rows = []
    if mode_key == "song":
        rows.append([
            InlineKeyboardButton(sample_label, callback_data=cb("music_product_sample_idea")),
            InlineKeyboardButton(manual_label, callback_data=cb("music_product_manual")),
        ])
    else:
        rows.append([InlineKeyboardButton(sample_label, callback_data=cb("music_product_sample_idea"))])
    rows.append(
        [
            InlineKeyboardButton(f"⬅️ {_audio_label(lang, 'back')}", callback_data=cb(back_action)),
            InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"),
        ],
    )
    return InlineKeyboardMarkup(rows)

def music_product_clean_idea(value: str = "") -> str:
    text = re.sub(r"\s+", " ", str(value or "").strip())
    return text[:420].strip(" ,.;:") or music_product_sample_idea("background")

def music_product_suggestion_offset(result: dict | None = None) -> int:
    return max(0, _safe_int((result or {}).get("music_suggestion_offset"), 0))

def music_product_public_style_from_parts(*parts: str) -> str:
    text = ", ".join(str(item or "").strip(" ,.;") for item in parts if str(item or "").strip(" ,.;"))
    text = re.sub(r"\s*,\s*", ", ", text)
    return re.sub(r"\s{2,}", " ", text).strip(" ;,")[:900]

def build_music_product_suggestions(
    *,
    mode: str = "background",
    tier: str = "",
    vocal_mode: str = "auto",
    idea: str = "",
    offset: int = 0,
    lang: str = "vi",
) -> list[dict]:
    mode_key = normalize_music_product_mode(mode)
    tier_key = normalize_music_product_tier_for_mode(tier, mode_key)
    clean_idea = music_product_clean_idea(idea or music_product_sample_idea(mode_key))
    tier_label = music_product_tier_label(tier_key, lang)
    seed = int(music_product_hash_text(f"{mode_key}:{tier_key}:{vocal_mode}:{clean_idea}")[:6] or "0", 16)
    start = (seed + max(0, int(offset or 0))) % 9
    background_bank = [
        ("Future Pop", "bright, uplifting", "110 BPM", "TikTok advertisement video", "clean studio production, modern synth, clear rhythm"),
        ("Cinematic Tech", "inspirational, premium", "92 BPM", "brand video", "wide cinematic synth, elegant build, moderate climax"),
        ("Tropical House", "sunny, feel-good", "118 BPM", "sales reels", "warm pluck synth, catchy hook, smooth transition"),
        ("Lo-fi Corporate", "trustworthy, calm", "86 BPM", "service introduction video", "soft beat, clean background, speech friendly"),
        ("Electro Pop", "energetic, bright", "124 BPM", "product launch short video", "bouncy bass, bright synth, short hook"),
        ("Acoustic Pop", "warm, friendly", "96 BPM", "review video", "acoustic guitar, bright piano, intimate feel"),
        ("Modern R&B", "luxury, smooth", "100 BPM", "product lookbook", "soft groove, clean bass, vocal-friendly space"),
        ("Epic Hybrid", "breakthrough, powerful", "104 BPM", "campaign video", "big drums, wide synth, strong ending"),
        ("Minimal Tech", "focused, precise", "108 BPM", "software demo", "steady pulse, clean texture, uncluttered background"),
    ]
    song_bank = [
        ("Brand Pop", "upbeat, feel-good", "112 BPM", "verse - pre-chorus - chorus - outro", "bright melody, catchy hook, clean studio production"),
        ("Dance Pop", "high energy, uplifting", "124 BPM", "verse - chorus - bridge - final chorus", "driving rhythm, open chorus, bouncy bass"),
        ("Acoustic Pop", "warm, healing", "92 BPM", "verse - chorus - verse - chorus", "acoustic guitar, bright piano, clear lyrics"),
        ("Future Pop", "modern, inspirational", "116 BPM", "intro - verse - chorus - outro", "bright synth, tech vibe, clean studio production"),
        ("R&B Pop", "smooth, luxury", "98 BPM", "verse - pre-chorus - chorus", "soft groove, warm bass, vocal-forward mix"),
        ("Rock Pop", "determined, energetic", "132 BPM", "verse - chorus - bridge - chorus", "clear electric guitar, driving drums, high energy"),
        ("Ballad Pop", "emotional, hopeful", "78 BPM", "verse - chorus - bridge - outro", "soft piano, gentle strings, emotional climax"),
        ("Tropical Pop", "optimistic, refreshing", "120 BPM", "verse - chorus - dance break - chorus", "tropical house elements, sunny vibe, catchy melody"),
        ("Indie Pop", "natural, bright", "104 BPM", "verse - chorus - verse - chorus", "acoustic guitar, indie drums, fresh vocal tone"),
    ]
    title_prefix = ["Bứt Phá", "Nhịp Sáng", "Dấu Ấn", "Vươn Xa", "Tỏa Sáng", "Khởi Động", "Niềm Tin", "Chạm Tới", "Lên Sóng"]
    title_tail = ["TOAN AAS", "Ngày Mới", "AI Việt", "Thương Hiệu", "Tương Lai", "Khách Hàng", "Hành Trình", "Công Nghệ", "Chiến Dịch"]
    suggestions: list[dict] = []
    for i in range(3):
        idx = (start + i) % 9
        if mode_key == "song":
            genre, mood, tempo, structure, production = song_bank[idx]
            vocal = normalize_song_vocal_mode(vocal_mode)
            vocal_direction = {
                "male": "Male vocal, male lead vocal, emotional vocal, Vietnamese lyrics in Lyrics field",
                "female": "Female vocal, female lead vocal, emotional vocal, Vietnamese lyrics in Lyrics field",
                "duet": "Male and female duet vocal, alternating male and female vocals, duet chorus, Vietnamese lyrics in Lyrics field",
                "auto": "Natural vocal, emotional vocal, Vietnamese lyrics in Lyrics field",
            }.get(vocal, "Natural vocal, emotional vocal, Vietnamese lyrics in Lyrics field")
            title = f"{title_prefix[idx]} {title_tail[(idx + i) % 9]}"
            lyric_seed = clean_idea[:110].strip(" .")
            lyrics = (
                f"[Verse]\n{lyric_seed} mở ra một ngày mới\n"
                "Từng nhịp bước đưa niềm tin đi xa\n"
                f"[Chorus]\n{title}, cùng nhau tỏa sáng\n"
                "TOAN AAS nâng giấc mơ bay qua giới hạn\n"
                "[Outro]\nGiữ nhịp tim luôn bứt phá hôm nay"
            )
            style_prompt = music_product_public_style_from_parts(
                genre,
                "acoustic guitar, bright piano, bouncy bass",
                mood,
                tempo,
                production,
                vocal_direction,
                f"Vietnamese original song for: {clean_idea}",
            )
            suggestions.append({
                "id": i + 1,
                "title": title,
                "theme": clean_idea,
                "genre": genre,
                "style": genre,
                "mood": mood,
                "tempo": tempo,
                "vocal_mode": vocal,
                "song_vocal": vocal,
                "requested_vocal_mode": vocal,
                "selected_vocal_mode": vocal,
                "vocal_mode_source": "suggestion_builder",
                "vocal_mode_persisted": "yes",
                "vocal_direction": vocal_direction,
                "lyrics_structure": structure,
                "duet_enabled": vocal == "duet",
                "duet_prompt_applied": vocal == "duet",
                "duet_lyrics_structure": "natural" if vocal == "duet" else "none",
                "lyrics": lyrics,
                "lyrics_prompt": lyrics,
                "style_prompt": style_prompt,
                "description": f"{tier_label}: {production}. Chủ đề giữ đúng ý tưởng anh/chị đã nhập.",
                "language": "Vietnamese",
                "provider_tags": genre,
            })
        else:
            genre, mood, tempo, use_case, production = background_bank[idx]
            title = f"{title_prefix[idx]} {title_tail[(idx + i + 2) % 9]}"
            style_prompt = music_product_public_style_from_parts(
                "instrumental, no vocals, no lyrics, background music",
                genre,
                mood,
                tempo,
                production,
                f"use case: {use_case}",
                f"theme: {clean_idea}",
            )
            suggestions.append({
                "id": i + 1,
                "title": title,
                "theme": clean_idea,
                "genre": genre,
                "style": genre,
                "mood": mood,
                "tempo": tempo,
                "use_case": use_case,
                "style_prompt": style_prompt,
                "description": f"{tier_label}: {production}. Không lời, dùng làm nhạc nền.",
                "lyrics": "",
                "lyrics_prompt": "",
                "language": "",
                "provider_tags": genre,
        })
    return suggestions

def music_product_prompt_preset_audit(
    *,
    mode: str = "song",
    tier: str = MUSIC_PRODUCT_TIER_BASIC,
    vocal_mode: str = "female",
    idea: str = "Bài hát quảng cáo thương hiệu TOAN AAS",
    lang: str = "vi",
) -> list[dict]:
    mode_key = normalize_music_product_mode(mode)
    tier_key = normalize_music_product_tier_for_mode(tier, mode_key)
    price = music_product_tier_price_xu(tier_key, mode_key)
    rows: list[dict] = []
    for offset in (0, 3, 6):
        for item in build_music_product_suggestions(
            mode=mode_key,
            tier=tier_key,
            vocal_mode=vocal_mode,
            idea=idea,
            offset=offset,
            lang=lang,
        ):
            preset_id = str(item.get("id") or len(rows) + 1)
            style_prompt = str(item.get("style_prompt") or "").strip()
            lyrics = str(item.get("lyrics") or item.get("lyrics_prompt") or "").strip()
            rows.append({
                "preset_id": f"{tier_key}:{mode_key}:{offset}:{preset_id}",
                "label": str(item.get("title") or item.get("genre") or f"Gợi ý {preset_id}"),
                "package": music_product_tier_label(tier_key, lang),
                "price_xu": price,
                "requested_vocal_mode": normalize_song_vocal_mode(vocal_mode),
                "selected_vocal_mode": normalize_song_vocal_mode(item.get("vocal_mode") or vocal_mode),
                "vocal_mode_source": str(item.get("vocal_mode_source") or "suggestion_builder"),
                "provider_prompt_contains_voice_hint": music_product_prompt_contains_vocal_hint(style_prompt, item.get("vocal_mode") or vocal_mode),
                "has_lyrics_required": mode_key == "song",
                "lyrics_present": bool(lyrics) if mode_key == "song" else True,
                "style_prompt_present": bool(style_prompt),
                "expected_route": "music_product_song_details -> invoice -> music_ai_confirm" if mode_key == "song" else "music_product_background_details -> invoice -> music_ai_confirm",
                "fixed": bool(style_prompt and (lyrics or mode_key != "song")),
            })
    unique: dict[str, dict] = {}
    for row in rows:
        unique[str(row["preset_id"])] = row
    return list(unique.values())

def music_product_prepare_suggestions_result(
    result: dict | None = None,
    *,
    idea: str = "",
    offset: int | None = None,
    lang: str = "vi",
) -> dict:
    current = dict(result or {})
    mode = music_product_mode_from_result(current)
    tier = normalize_music_product_tier_for_mode(current.get("music_product_tier"), mode)
    vocal_mode = normalize_song_vocal_mode(current.get("song_vocal") or current.get("vocal_mode") or "auto")
    clean_idea = music_product_clean_idea(idea or current.get("music_user_idea") or music_product_sample_idea(mode))
    next_offset = music_product_suggestion_offset(current) if offset is None else max(0, int(offset or 0))
    suggestions = build_music_product_suggestions(
        mode=mode,
        tier=tier,
        vocal_mode=vocal_mode,
        idea=clean_idea,
        offset=next_offset,
        lang=lang,
    )
    current.update({
        "music_product_flow": "p0_20b1_suggestions",
        "music_product_mode": mode,
        "music_product_tier": tier,
        "music_product_price_xu": music_product_tier_price_xu(tier, mode),
        "music_user_idea": clean_idea,
        "music_suggestion_offset": next_offset,
        "music_suggestions": suggestions,
        "music_selected_suggestion_id": "",
        "music_selected_title": "",
        "music_selected_style_prompt": "",
        "music_selected_lyrics_prompt": "",
        "music_confirmed": False,
    })
    if mode == "song":
        current.update(music_product_vocal_state_fields(
            current,
            requested_vocal_mode=vocal_mode,
            selected_vocal_mode=vocal_mode,
            vocal_mode_source="prepare_suggestions",
            prompt_after_preset=" ".join(str(item.get("style_prompt") or "") for item in suggestions[:3]),
        ))
    return current

def music_product_suggestion_by_index(result: dict | None = None, index: int = 1) -> dict:
    suggestions = list((result or {}).get("music_suggestions") or [])
    idx = max(1, min(3, _safe_int(index, 1)))
    if 0 <= idx - 1 < len(suggestions) and isinstance(suggestions[idx - 1], dict):
        return dict(suggestions[idx - 1])
    return {}

def music_product_result_from_suggestion(result: dict | None = None, suggestion: dict | None = None) -> dict:
    current = dict(result or {})
    item = dict(suggestion or {})
    mode = music_product_mode_from_result(current)
    tier = normalize_music_product_tier_for_mode(current.get("music_product_tier"), mode)
    raw_current_vocal = str(current.get("song_vocal") or current.get("vocal_mode") or "").strip()
    raw_item_vocal = str(item.get("vocal_mode") or item.get("song_vocal") or "").strip()
    vocal_mode = normalize_song_vocal_mode(raw_current_vocal) if raw_current_vocal else normalize_song_vocal_mode(raw_item_vocal or "auto")
    payload = {
        **current,
        **item,
        "music_product_mode": mode,
        "music_product_tier": tier,
        "vocal_mode": vocal_mode,
        "song_vocal": vocal_mode,
        "title": str(item.get("title") or current.get("title") or "").strip(),
        "theme": str(item.get("theme") or current.get("music_user_idea") or "").strip(),
        "description": str(item.get("description") or item.get("theme") or current.get("music_user_idea") or "").strip(),
        "lyrics": str(item.get("lyrics") or item.get("lyrics_prompt") or "").strip() if mode == "song" else "",
        "style_prompt": str(item.get("style_prompt") or "").strip(),
        "provider_tags": str(item.get("provider_tags") or item.get("genre") or "").strip(),
    }
    product_result = music_product_result_from_input(payload)
    selected_id = str(item.get("id") or current.get("music_selected_suggestion_id") or "")
    style_preset_id = f"{tier}:{mode}:{music_product_suggestion_offset(current)}:{selected_id}" if selected_id else ""
    product_result.update({
        "music_product_flow": "p0_20b1_suggestions",
        "music_user_idea": str(current.get("music_user_idea") or item.get("theme") or "").strip(),
        "music_suggestions": list(current.get("music_suggestions") or []),
        "music_suggestion_offset": music_product_suggestion_offset(current),
        "music_selected_suggestion_id": selected_id,
        "music_selected_title": str(item.get("title") or product_result.get("title") or "").strip(),
        "music_selected_style_prompt": str(item.get("style_prompt") or product_result.get("provider_style_prompt") or "").strip(),
        "music_selected_lyrics_prompt": str(item.get("lyrics_prompt") or item.get("lyrics") or product_result.get("provider_lyrics") or "").strip(),
        "style_preset_id": style_preset_id,
        "music_invoice_id": music_product_hash_text(f"{time.time_ns()}:{selected_id}:{product_result.get('provider_style_prompt')}"),
        "music_confirmed": False,
    })
    product_result.update(music_product_vocal_state_fields(
        product_result,
        requested_vocal_mode=current.get("requested_vocal_mode") or current.get("song_vocal") or current.get("vocal_mode") or vocal_mode,
        selected_vocal_mode=vocal_mode,
        vocal_mode_source="selected_suggestion",
        style_preset_id=style_preset_id,
        prompt_after_preset=music_provider_prompt_for_result(product_result),
    ))
    product_result["duet_lyrics_structure"] = music_product_duet_lyrics_structure(product_result.get("provider_lyrics") or product_result.get("lyrics") or "")
    return product_result

def music_product_suggestions_text(result: dict | None = None, lang: str = "vi") -> str:
    current = dict(result or {})
    mode = music_product_mode_from_result(current)
    suggestions = list(current.get("music_suggestions") or [])
    product_label = music_product_type_label(current, lang)
    tier_label = music_product_tier_label(current.get("music_product_tier"), lang)
    lines = [f"✨ <b>3 {_audio_copy(lang, 'direction').lower()} — {html.escape(product_label)}</b>"]
    for idx, item in enumerate(suggestions[:3], start=1):
        tempo = str(item.get("tempo") or "-")[:80]
        if mode == "song":
            lines.extend([
                "",
                f"{idx}️⃣ <b>{_audio_label(lang, f'choose_{idx}')}</b>",
                f"• {_audio_copy(lang, 'package')}: {html.escape(tier_label)}",
                f"• {_audio_label(lang, 'voice')}: {html.escape(music_product_vocal_label(current.get('song_vocal') or 'auto', lang))}",
                f"• {_audio_copy(lang, 'tempo')}: {html.escape(tempo)}",
            ])
        else:
            lines.extend([
                "",
                f"{idx}️⃣ <b>{_audio_label(lang, f'choose_{idx}')}</b>",
                f"• {_audio_copy(lang, 'package')}: {html.escape(tier_label)}",
                f"• {_audio_copy(lang, 'tempo')}: {html.escape(tempo)}",
            ])
    lines.extend(["", music_no_xu_text(lang)])
    return "\n".join(lines)

