def update_music_submit_job_provider_accepted(
    job: dict | None,
    submitted: dict | None = None,
    *,
    updated_by="",
) -> dict:
    current = dict(job or {})
    payload = dict(submitted or {})
    task_id = str(payload.get("task_id") or payload.get("provider_task_id") or payload.get("provider_job_id") or "").strip()
    provider = str(payload.get("provider") or current.get("provider") or "").strip()
    if not task_id:
        return mark_music_confirm_submit_blocker(current, "provider_job_id_missing_after_submit", payload.get("detail") or payload.get("status") or "", updated_by=updated_by)
    is_song = music_job_product_type(current, "music_bg") == "music_song"
    generation_stage = "generating_song" if is_song else "generating_music"
    current.update({
        "provider": provider,
        "provider_task_id": task_id,
        "provider_job_id": task_id,
        "status": "submitted",
        "create_song_started": True,
        "last_provider_status": sanitize_provider_status_text(payload.get("status") or "PASS_SUBMITTED", task_id, 180),
        "provider_status": "submitted",
        "scheduler_status": str(current.get("scheduler_status") or "not_started"),
        "lifecycle_status": "provider_submitted",
        "progress_text": "Đã gửi yêu cầu tạo nhạc tới provider.",
        "current_stage": generation_stage,
        "stage": generation_stage,
        "progress_percent": 35,
        "percent": 35,
        "public_percent_reason": "provider_job_accepted",
        "confirm_submit_phase": "submitted",
        "confirm_submit_blocker": "",
        "auto_delivery_blocker": "",
        "provider_submit_ok_at": now_text(),
        "submitted_to_provider_at": now_text(),
        "provider_job_id_saved_at": now_text(),
        "selected_model_key": str(payload.get("selected_model_key") or current.get("selected_model_key") or ""),
        "final_provider_vocal_mode": str(payload.get("final_provider_vocal_mode") or current.get("final_provider_vocal_mode") or ""),
        "final_provider_voice_field": str(payload.get("final_provider_voice_field") or current.get("final_provider_voice_field") or ""),
        "final_provider_style_prompt_contains_female": bool(payload.get("final_provider_style_prompt_contains_female") or current.get("final_provider_style_prompt_contains_female")),
        "final_provider_lyrics_prompt_contains_female": bool(payload.get("final_provider_lyrics_prompt_contains_female") or current.get("final_provider_lyrics_prompt_contains_female")),
        "final_provider_prompt_contains_male": bool(payload.get("final_provider_prompt_contains_male") or current.get("final_provider_prompt_contains_male")),
        "female_vocal_payload_lock": str(payload.get("female_vocal_payload_lock") or current.get("female_vocal_payload_lock") or "no"),
        "male_hint_removed_for_female": str(payload.get("male_hint_removed_for_female") or current.get("male_hint_removed_for_female") or "no"),
        "pending_charge_xu": int(current.get("pending_charge_xu") or 0),
    })
    return save_engine_async_job(current)

def music_suno_poll_state_from_job(job: dict) -> dict:
    return {
        "music_provider": str((job or {}).get("provider") or ""),
        "music_task_id": str((job or {}).get("provider_task_id") or ""),
    }

def music_poll_status_is_processing(status: str) -> bool:
    normalized = str(status or "").strip().lower()
    return normalized in {
        "submitted", "queued", "queue", "pending", "processing", "running",
        "in_progress", "generating", "process", "pass_submitted",
    }

def music_poll_status_is_success_without_url(status: str) -> bool:
    normalized = str(status or "").strip().upper()
    return normalized in {"SUCCESS", "SUCCEEDED", "COMPLETED", "COMPLETE", "DONE", "FINISHED", "PASS", "PASS_FULL_RESULT", "COMPLETED_NO_AUDIO", "COMPLETED_NO_DOWNLOADABLE_AUDIO"}

def suno_verified_fallback_provider(primary_provider: str = "key4u_suno") -> str:
    primary = str(primary_provider or "").strip()
    readiness = get_suno_music_readiness()
    providers = dict(readiness.get("providers") or {})
    download_smoke = preferred_tool_test_result("music_ai_download", "music_ai_preview_download")
    if not tool_test_result_audio_bytes_positive(download_smoke):
        return ""
    candidates = [
        ("shopaikey_music", "shopaikey_music_job"),
        ("key4u_suno", "key4u_suno_job"),
    ]
    for provider_name, fetch_tool in candidates:
        if provider_name == primary:
            continue
        if not dict(providers.get(provider_name) or {}).get("configured"):
            continue
        fetch_status = str(get_tool_test_result(fetch_tool).get("status") or "").upper()
        if fetch_status == "PASS_FULL_RESULT":
            return provider_name
    return ""

def suno_fallback_status_text(primary_provider: str = "key4u_suno") -> str:
    fallback = suno_verified_fallback_provider(primary_provider)
    if fallback:
        return f"Fallback đã xác minh: {fallback}. Chỉ chạy khi admin xác nhận rõ; không auto-run."
    return "Chưa có provider nhạc AI fallback đã xác minh."

async def poll_music_suno_async_job(internal_job_id: str, *, updated_by="", download: bool = True) -> dict:
    job = get_engine_async_job(internal_job_id)
    if not job:
        return {"ok": False, "status": "JOB_NOT_FOUND", "job": {}, "audio_bytes": b""}
    if music_job_delivered(job):
        return {"ok": True, "status": "ALREADY_DELIVERED", "job": job, "audio_bytes": b""}
    if music_job_terminal_failed(job):
        return {"ok": False, "status": "TERMINAL_FAILED", "job": job, "audio_bytes": b""}
    if str(job.get("status") or "").strip().lower() in {"pending_submit", "submitting"}:
        return {"ok": False, "status": "PROVIDER_SUBMIT_NOT_READY", "job": job, "audio_bytes": b""}
    if not str(job.get("provider_task_id") or "").strip():
        job.update({
            "status": "failed",
            "terminal_state": "failed_no_charge",
            "music_terminal_state": "failed_no_charge",
            "error_category": music_confirm_submit_blocker_from_job(job) or "provider_job_missing",
            "confirm_submit_blocker": music_confirm_submit_blocker_from_job(job) or str(job.get("confirm_submit_blocker") or ""),
            "progress_text": "Không có provider task id thật; không tạo fake processing.",
        })
        save_engine_async_job(job)
        return {"ok": False, "status": "MISSING_TASK", "job": job, "audio_bytes": b""}
    polled = await poll_music_generation_job(music_suno_poll_state_from_job(job), updated_by=updated_by)
    provider_task_id = str(job.get("provider_task_id") or "")
    provider_status = str(polled.get("status") or "")
    output_url = str(polled.get("output_url") or "").strip()
    job["poll_count"] = int(job.get("poll_count") or 0) + 1
    job["provider_poll_count"] = int(job["poll_count"] or 0)
    job["last_poll_at"] = now_text()
    job["provider_last_poll_at"] = str(job.get("last_poll_at") or "")
    job["next_poll_after"] = engine_async_next_poll_after_text()
    job["parsed_fields"] = suno_result_parsed_fields(polled)
    raw_provider_status = sanitize_provider_status_text(provider_status or polled.get("detail") or "-", provider_task_id)
    job["last_provider_status"] = raw_provider_status
    job["provider_status_raw"] = raw_provider_status
    job["provider_status"] = "completed" if polled.get("ok") and output_url else ("running" if music_poll_status_is_processing(provider_status) else raw_provider_status)
    job["provider_error"] = sanitize_provider_status_text(polled.get("detail") or polled.get("error") or "", provider_task_id, 180)
    if output_url or polled.get("provider_result_candidates") or polled.get("raw_provider_result_saved"):
        job = apply_music_provider_result_metadata(job, polled, output_url)
    if polled.get("ok") and output_url:
        if not download:
            job["status"] = "downloading"
            job["progress_text"] = "Đã có kết quả, TOAN AAS đang tải file nhạc."
            job["provider_completed"] = True
            job["music_provider_completed"] = True
            job["provider_status"] = "completed"
            job["lifecycle_status"] = "provider_completed"
            job["materialization_status"] = "not_attempted"
            job["provider_completed_at"] = str(job.get("provider_completed_at") or now_text())
            job["artifact_ready"] = False
            job["music_artifact_ready"] = False
            job["artifact_validated"] = False
            job["audio_validated"] = False
            job["music_audio_validated"] = False
            job["artifact_state"] = "metadata_ready"
            job["music_artifact_state"] = "metadata_ready"
            job["artifact_metadata_ready_at"] = str(job.get("artifact_metadata_ready_at") or now_text())
            job["output_url"] = output_url
            job["music_output_url"] = output_url
            job["result_url"] = output_url
            job["result_url_first_seen_at"] = str(job.get("result_url_first_seen_at") or now_text())
            job["result_url_label"] = music_result_url_debug_label(output_url)
            save_engine_async_job(job)
            return {"ok": True, "status": "OUTPUT_URL_READY", "job": job, "output_url": output_url, "audio_bytes": b""}
        job["status"] = "downloading"
        job["progress_text"] = "Đã có kết quả, TOAN AAS đang tải file nhạc."
        job["provider_completed"] = True
        job["music_provider_completed"] = True
        job["provider_status"] = "completed"
        job["lifecycle_status"] = "provider_completed"
        job["materialization_status"] = "not_attempted"
        job["provider_completed_at"] = str(job.get("provider_completed_at") or now_text())
        job["artifact_ready"] = False
        job["music_artifact_ready"] = False
        job["artifact_validated"] = False
        job["audio_validated"] = False
        job["music_audio_validated"] = False
        job["artifact_state"] = "metadata_ready"
        job["music_artifact_state"] = "metadata_ready"
        job["artifact_metadata_ready_at"] = str(job.get("artifact_metadata_ready_at") or now_text())
        job["output_url"] = output_url
        job["music_output_url"] = output_url
        job["result_url"] = output_url
        job["result_url_first_seen_at"] = str(job.get("result_url_first_seen_at") or now_text())
        job["result_url_label"] = music_result_url_debug_label(output_url)
        save_engine_async_job(job)
        materialized = await materialize_music_artifact_for_job(job, updated_by=updated_by, source="provider_poll_completed")
        materialized_job = dict(materialized.get("job") or job)
        audio_bytes = bytes(materialized.get("audio_bytes") or b"")
        record_music_provider_attempt(
            provider=str(job.get("provider") or ""),
            task_id=provider_task_id,
            fetch_status=provider_status,
            download_status="PASS" if materialized.get("ok") else str(materialized.get("status") or "FAIL_DOWNLOAD"),
            error=str((materialized.get("artifact") or {}).get("download_detail") or materialized.get("status") or ""),
            updated_by=updated_by,
        )
        if materialized.get("ok") and audio_bytes:
            return {"ok": True, "status": "COMPLETED", "job": materialized_job, "output_url": output_url, "audio_bytes": audio_bytes}
        if str(materialized.get("status") or "").upper() == "ARTIFACT_WAITING" or music_job_artifact_materialization_waiting(materialized_job):
            materialized_job.update({
                "status": "processing",
                "terminal_state": "",
                "music_terminal_state": "",
                "provider_status": "completed",
                "provider_completed": True,
                "music_provider_completed": True,
                "lifecycle_status": "artifact_waiting",
                "artifact_ready": False,
                "music_artifact_ready": False,
                "artifact_validated": False,
                "audio_validated": False,
                "music_audio_validated": False,
                "primary_blocker": MUSIC_ARTIFACT_NOT_READY_BLOCKER,
                "artifact_blocker": MUSIC_ARTIFACT_NOT_READY_BLOCKER,
                "auto_delivery_blocker": MUSIC_ARTIFACT_NOT_READY_BLOCKER,
                "error_category": MUSIC_ARTIFACT_NOT_READY_BLOCKER,
                "progress_percent": max(85, min(90, int(materialized_job.get("progress_percent") or job.get("progress_percent") or 85))),
                "progress_text": "Bài hát đã tạo xong, TOAN AAS đang chuẩn bị file nhạc để gửi tự động. Hệ thống chưa trừ Xu.",
                "pr173_artifact_engine_restored": True,
                "terminal_after_wait_exhausted": False,
                "recovery_action": materialized.get("recovery_action") or "artifact_waiting_retry_later",
            })
            save_engine_async_job(materialized_job)
            return {"ok": False, "status": "ARTIFACT_WAITING", "job": materialized_job, "output_url": output_url, "audio_bytes": b""}
        if music_result_url_expired_download(materialized_job) and not bool(materialized_job.get("refresh_url_attempted")):
            refreshed = await refresh_music_expired_result_url_for_job(
                materialized_job,
                updated_by=updated_by,
                source="provider_poll_completed_url_refresh",
            )
            refreshed_job = dict(refreshed.get("job") or materialized_job)
            refreshed_audio = bytes(refreshed.get("audio_bytes") or b"")
            if refreshed.get("ok") and refreshed_audio:
                record_music_provider_attempt(
                    provider=str(job.get("provider") or ""),
                    task_id=provider_task_id,
                    fetch_status=provider_status,
                    download_status="PASS_REFRESHED_URL",
                    error="refreshed_result_url",
                    updated_by=updated_by,
                )
                return {"ok": True, "status": "COMPLETED", "job": refreshed_job, "output_url": music_job_result_url(refreshed_job), "audio_bytes": refreshed_audio}
            materialized = refreshed
            materialized_job = refreshed_job
        blocker = music_job_artifact_primary_blocker(materialized_job) or "artifact_materialization_failed"
        clean_provider_file_message = KEY4U_SUNO_DOWNLOAD_PUBLIC_NO_CHARGE
        materialized_job.update({
            "status": "failed",
            "terminal_state": "failed_no_charge",
            "music_terminal_state": "failed_no_charge",
            "progress_text": clean_provider_file_message if blocker in {"result_url_forbidden_access_denied", "result_url_forbidden", "result_url_forbidden_or_missing_auth", "result_url_expired", "artifact_download_failed", KEY4U_SUNO_BARE_CDN_SETUP_BLOCKER} else "Có kết quả nhưng chưa tải được file nhạc hợp lệ. TOAN AAS chưa trừ Xu.",
            "provider_status": "completed",
            "lifecycle_status": "artifact_failed",
            "artifact_ready": False,
            "music_artifact_ready": False,
            "artifact_validated": False,
            "audio_validated": False,
            "music_audio_validated": False,
            "primary_blocker": blocker,
            "artifact_blocker": blocker,
            "secondary_blocker": music_job_artifact_secondary_blocker(materialized_job),
            "error_category": blocker,
            "auto_delivery_blocker": blocker,
            "last_provider_status": raw_provider_status,
            "last_artifact_error": sanitize_provider_status_text(str((materialized.get("artifact") or {}).get("download_detail") or materialized.get("status") or ""), provider_task_id),
        })
        save_engine_async_job(materialized_job)
        return {"ok": False, "status": str(materialized.get("status") or "ARTIFACT_MATERIALIZATION_FAILED"), "job": materialized_job, "output_url": output_url, "audio_bytes": b""}
    if music_poll_status_is_processing(provider_status):
        if engine_async_provider_processing_timed_out(job):
            job.update({
                "status": "timeout_provider_processing",
                "terminal_state": "failed_no_charge",
                "music_terminal_state": "failed_no_charge",
                "progress_text": "Provider xử lý quá lâu, chưa có file nhạc. TOAN AAS chưa trừ Xu.",
                "error_category": "timeout_provider_processing",
            })
            job = ensure_music_failed_no_charge_metadata(
                job,
                primary_blocker="timeout_provider_processing",
                fail_stage="provider_poll",
                detail="timeout_provider_processing",
                provider_submit_called=True,
            )
            save_engine_async_job(job)
            return {"ok": False, "status": "TIMEOUT_PROVIDER_PROCESSING", "job": job, "audio_bytes": b""}
        progress_text = "Provider đang tạo nhạc. Thường mất vài phút."
        if engine_async_provider_processing_soft_timed_out(job):
            progress_text = "Provider xử lý lâu hơn 5 phút, chưa có file nhạc. TOAN AAS chưa trừ Xu."
        job.update({
            "status": "processing",
            "progress_text": progress_text,
            "error_category": "",
            "provider_processing_started_at": str(job.get("provider_processing_started_at") or now_text()),
            "provider_completed": False,
            "music_provider_completed": False,
        })
        save_engine_async_job(job)
        return {"ok": False, "status": "PROCESSING", "job": job, "audio_bytes": b""}
    if music_poll_status_is_success_without_url(provider_status):
        blocker = str(polled.get("primary_blocker") or polled.get("error_category") or "result_url_missing")
        recovery_action = str(polled.get("recovery_action") or ("setup_required_key4u_suno_download_url" if blocker == KEY4U_SUNO_BARE_CDN_SETUP_BLOCKER else "need_key4u_signed_download_field_or_proxy" if blocker == "result_url_forbidden_access_denied" else "need_provider_download_endpoint"))
        job.update({
            "status": "failed",
            "terminal_state": "failed_no_charge",
            "music_terminal_state": "failed_no_charge",
            "progress_text": KEY4U_SUNO_DOWNLOAD_PUBLIC_NO_CHARGE,
            "provider_completed": True,
            "music_provider_completed": True,
            "provider_status": "completed",
            "lifecycle_status": "artifact_failed",
            "artifact_ready": False,
            "music_artifact_ready": False,
            "artifact_validated": False,
            "audio_validated": False,
            "music_audio_validated": False,
            "primary_blocker": blocker,
            "artifact_blocker": blocker,
            "auto_delivery_blocker": blocker,
            "error_category": blocker,
            "recovery_action": recovery_action,
            "provider_download_endpoint_configured": bool(polled.get("provider_download_endpoint_configured")),
            "provider_download_endpoint_attempted": bool(polled.get("provider_download_endpoint_attempted")),
            "setup_required": str(polled.get("setup_required") or (KEY4U_SUNO_DOWNLOAD_SETUP_REQUIRED if blocker == KEY4U_SUNO_BARE_CDN_SETUP_BLOCKER else "")),
            "rejected_candidate_reasons": list(polled.get("rejected_candidate_reasons") or job.get("rejected_candidate_reasons") or [])[-8:],
        })
        job = ensure_music_failed_no_charge_metadata(
            job,
            primary_blocker=blocker,
            fail_stage="artifact",
            detail=recovery_action,
            provider_submit_called=True,
        )
        save_engine_async_job(job)
        status_name = "KEY4U_SUNO_DOWNLOAD_ENDPOINT_MISSING_FOR_BARE_CDN" if blocker == KEY4U_SUNO_BARE_CDN_SETUP_BLOCKER else "RESULT_URL_FORBIDDEN_ACCESS_DENIED" if blocker == "result_url_forbidden_access_denied" else "RESULT_URL_MISSING"
        return {"ok": False, "status": status_name, "job": job, "audio_bytes": b""}
    if str(provider_status or "").upper() in {"FAIL", "FAILED", "ERROR", "CANCELLED", "CANCELED"} or str(polled.get("status") or "").upper().startswith("FAIL"):
        job.update({
            "status": "failed",
            "terminal_state": "failed_no_charge",
            "music_terminal_state": "failed_no_charge",
            "progress_text": "Provider trả lỗi khi xử lý nhạc.",
            "error_category": "provider_failed",
            "last_provider_status": sanitize_provider_status_text(polled.get("detail") or provider_status, provider_task_id),
        })
        job = ensure_music_failed_no_charge_metadata(
            job,
            primary_blocker="provider_failed",
            fail_stage="provider_poll",
            detail=polled.get("detail") or provider_status,
            provider_submit_called=True,
        )
        save_engine_async_job(job)
        return {"ok": False, "status": "PROVIDER_FAILED", "job": job, "audio_bytes": b""}
    job.update({
        "status": "processing",
        "progress_text": "Provider chưa trả file tải về; tiếp tục chờ/poll.",
        "last_provider_status": sanitize_provider_status_text(provider_status or polled.get("detail") or "unknown", provider_task_id),
        "provider_processing_started_at": str(job.get("provider_processing_started_at") or now_text()),
        "provider_completed": False,
        "music_provider_completed": False,
    })
    save_engine_async_job(job)
    return {"ok": False, "status": "PROCESSING", "job": job, "audio_bytes": b""}

async def poll_music_preview_job(result: dict, updated_by="") -> dict:
    preview_state = dict(result or {})
    preview_state["music_provider"] = str(result.get("music_preview_provider") or "")
    preview_state["music_task_id"] = str(result.get("music_preview_task_id") or "")
    return await poll_music_generation_job(preview_state, updated_by=updated_by)

async def send_music_preview_output(query, context, result: dict, lang: str = "vi", updated_by="") -> tuple[bool, dict]:
    polled = await poll_music_preview_job(result, updated_by=updated_by)
    output_url = str(polled.get("output_url") or "").strip()
    if not polled.get("ok") or not output_url:
        return False, polled
    try:
        audio_bytes, _detail, _status = await _download_music_audio_url_bytes(output_url, timeout_seconds=60.0)
        record_music_provider_attempt(
            provider=str(result.get("music_preview_provider") or ""),
            task_id=str(result.get("music_preview_task_id") or ""),
            fetch_status=str(polled.get("status") or ""),
            download_status="PASS" if audio_bytes else "FAIL_DOWNLOAD",
            error=_detail,
            updated_by=updated_by,
        )
        vault_entry = upsert_music_vault_from_output(
            audio_bytes=audio_bytes,
            result=result,
            job={
                "provider": str(result.get("music_preview_provider") or ""),
                "provider_task_id": str(result.get("music_preview_task_id") or ""),
                "user_id": str(result.get("user_id") or ""),
                "chat_id": str(getattr(query.message, "chat_id", "") or ""),
            },
            status="preview_sent",
            updated_by=updated_by,
        )
        preview_seconds = music_preview_seconds()
        capped_bytes, _cap_detail = await cap_voice_preview_audio_bytes(audio_bytes, preview_seconds)
        if not capped_bytes:
            return False, {**polled, "status": "PREVIEW_CAP_FAILED"}
        audio_file = io.BytesIO(capped_bytes)
        audio_file.name = "toan_aas_music_preview.mp3"
        sent = await context.bot.send_audio(
            chat_id=query.message.chat_id,
            audio=audio_file,
            title="TOAN AAS Music Preview",
            caption=(
                f"▶️ Nghe thử {preview_seconds} giây. Bản đầy đủ đã được lưu trong kho, chưa giao và chưa trừ Xu final."
                if music_ui_lang(lang=lang) == "vi" else
                f"▶️ {preview_seconds}-second preview. The full output is stored in the vault and not delivered before confirmation."
            ),
        )
        preview_ref = str(getattr(getattr(sent, "audio", None), "file_id", "") or "")
        return True, {**polled, "preview_audio_ref": preview_ref, "preview_seconds": preview_seconds, "music_vault_id": str(vault_entry.get("vault_id") or "")}
    except Exception as exc:
        logger.warning("music preview send failed | %s", sanitize_log_text(str(exc))[:180])
        return False, {**polled, "status": "PREVIEW_SEND_FAILED"}

def music_product_delivery_lock_key(user_id, result: dict | None = None, job: dict | None = None, audio_bytes: bytes | bytearray | None = None) -> str:
    result = dict(result or {})
    job = dict(job or {})
    for key in ("internal_job_id", "music_job_id", "music_internal_job_id", "provider_task_id", "music_task_id"):
        value = str(job.get(key) or result.get(key) or "").strip()
        if value:
            return f"music-delivery:{value}"
    sha = music_audio_sha256(audio_bytes)
    return f"music-delivery:{user_id}:{sha or music_product_hash_text(str(result)[:500])}"

def music_delivery_identity_values(result: dict | None = None, job: dict | None = None, audio_bytes: bytes | bytearray | None = None) -> set[str]:
    data = {**dict(job or {}), **dict(result or {})}
    values: set[str] = set()
    for key in (
        "internal_job_id", "job_id", "music_job_id", "music_internal_job_id",
        "provider_task_id", "task_id", "music_task_id",
        "selected_artifact_id", "music_artifact_id", "artifact_id",
        "vault_id", "music_vault_id",
        "output_sha256", "music_output_sha256", "selected_artifact_hash",
        "music_artifact_hash", "delivered_artifact_hash",
    ):
        value = str(data.get(key) or "").strip()
        if value:
            values.add(f"{key}:{value}")
    for key in ("output_url", "music_output_url", "result_url", "music_artifact_url"):
        value = music_normalized_artifact_url(str(data.get(key) or "").strip())
        if value:
            values.add(f"url:{value}")
    for key in ("local_artifact_path", "music_result_path", "output_path", "storage_ref", "delivered_artifact_path"):
        value = str(data.get(key) or "").strip()
        if value:
            values.add(f"path:{os.path.normcase(os.path.abspath(value)) if not value.startswith('telegram_file_id:') else value}")
    sha = music_audio_sha256(audio_bytes)
    if sha:
        values.add(f"sha:{sha}")
        values.add(f"output_sha256:{sha}")
        values.add(f"music_output_sha256:{sha}")
        values.add(f"selected_artifact_hash:{sha}")
        values.add(f"music_artifact_hash:{sha}")
        values.add(f"delivered_artifact_hash:{sha}")
    return values

def music_delivery_core_identity_values(result: dict | None = None, job: dict | None = None) -> set[str]:
    data = {**dict(job or {}), **dict(result or {})}
    values: set[str] = set()
    for key in ("internal_job_id", "job_id", "music_job_id", "music_internal_job_id", "provider_task_id", "task_id", "music_task_id"):
        value = str(data.get(key) or "").strip()
        if value:
            values.add(f"{key}:{value}")
            values.add(f"core:{value}")
    return values

