def music_delivery_same_identity(
    delivered_result: dict | None = None,
    candidate_result: dict | None = None,
    candidate_job: dict | None = None,
    audio_bytes: bytes | bytearray | None = None,
) -> bool:
    delivered_job_ids = music_delivery_job_identity_values(delivered_result, None)
    candidate_job_ids = music_delivery_job_identity_values(candidate_result, candidate_job)
    if delivered_job_ids and candidate_job_ids:
        return bool(delivered_job_ids.intersection(candidate_job_ids))
    delivered_provider_ids = music_delivery_provider_identity_values(delivered_result, None)
    candidate_provider_ids = music_delivery_provider_identity_values(candidate_result, candidate_job)
    if delivered_provider_ids and candidate_provider_ids:
        return bool(delivered_provider_ids.intersection(candidate_provider_ids))
    delivered_core = music_delivery_core_identity_values(delivered_result, None)
    candidate_core = music_delivery_core_identity_values(candidate_result, candidate_job)
    if delivered_core and candidate_core:
        return bool(delivered_core.intersection(candidate_core))
    delivered_values = music_delivery_identity_values(delivered_result, None, None)
    candidate_values = music_delivery_identity_values(candidate_result, candidate_job, audio_bytes)
    return bool(delivered_values and candidate_values and delivered_values.intersection(candidate_values))

def music_existing_delivered_result_for_attempt(user_id, result: dict | None = None, job: dict | None = None, audio_bytes: bytes | bytearray | None = None) -> dict:
    if not user_id:
        return {}
    if not (
        music_delivery_job_identity_values(result, job)
        or music_delivery_provider_identity_values(result, job)
        or music_delivery_explicit_artifact_identity_values(result, job)
    ):
        return {}
    try:
        saved = get_music_guided_result(user_id) or {}
    except Exception:
        saved = {}
    if not saved or not music_delivery_should_suppress_public_fail(saved, job):
        return {}
    if music_delivery_same_identity(saved, result, job, audio_bytes):
        return dict(saved)
    return {}

def music_product_audio_has_partial_marker(result: dict | None = None, job: dict | None = None) -> bool:
    data = {**dict(job or {}), **dict(result or {})}
    for key in ("is_preview", "preview", "is_partial", "partial", "temporary", "is_temp", "temp_output"):
        if bool(data.get(key)):
            return True
    output_path = os.path.basename(str(data.get("output_path") or data.get("music_result_path") or data.get("local_path") or "")).lower()
    if output_path and any(token in output_path for token in ("preview", "partial", "tmp", "temp")) and str(data.get("status") or "").lower() != "completed":
        return True
    return False

def music_delivery_source_token(source: str = "") -> str:
    token = re.sub(r"[^a-z0-9_:-]+", "_", str(source or "").strip().lower())
    return token[:60] or "unknown"

def music_normalized_artifact_url(url: str = "") -> str:
    raw = str(url or "").strip()
    if not raw:
        return ""
    try:
        parsed = urlparse(raw)
        path = re.sub(r"/+", "/", parsed.path or "")
        return f"{parsed.scheme.lower()}://{parsed.netloc.lower()}{path}"
    except Exception:
        return raw.split("?", 1)[0].strip()

def music_result_url_debug_label(url: str = "") -> str:
    raw = str(url or "").strip()
    if not raw:
        return "-"
    try:
        parsed = urlparse(raw)
        host = str(parsed.netloc or "").strip()
        suffix = os.path.splitext(str(parsed.path or "").split("?", 1)[0])[1].lower()
        return f"{host or 'url'}{suffix or ''}"
    except Exception:
        return "url"

def music_provider_result_metadata(payload: dict | None = None, *, provider_name: str = "") -> dict:
    data = dict(payload or {})
    raw_payload = data.get("raw_provider_result") or data.get("raw_provider_result_internal")
    candidate_payload = raw_payload if isinstance(raw_payload, (dict, list)) else data
    candidates = extract_shopaikey_suno_audio_candidates(candidate_payload, provider_name=provider_name)
    override_path = str(KEY4U_SUNO_RESULT_FIELD or "").strip() if str(provider_name or "").strip() == "key4u_suno" else ""
    if override_path and isinstance(candidate_payload, (dict, list)):
        override_value = music_result_field_path_value(candidate_payload, override_path)
        if isinstance(override_value, str) and override_value.strip().startswith(("http://", "https://")):
            candidates.append(music_provider_candidate_from_url(override_path, override_value, provider_name=provider_name, source="KEY4U_SUNO_RESULT_FIELD"))
            candidates = sorted(candidates, key=music_provider_candidate_priority, reverse=True)
    if not candidates and data:
        candidates = extract_shopaikey_suno_audio_candidates(data, provider_name=provider_name)
    selected = select_music_provider_audio_candidate(candidates)
    selected_url = str(selected.get("url") or data.get("output_url") or data.get("result_url") or "").strip()
    query_meta = music_url_query_metadata(selected_url)
    candidate_records = music_provider_audio_candidate_records(candidates)
    valid_count = len([item for item in candidates if not item.get("rejected")])
    rejected_reasons = music_provider_rejected_candidate_reasons(candidates)
    bare_reject = music_bare_suno_output_reject_reason(candidates)
    is_key4u = str(provider_name or data.get("provider") or "").strip() == "key4u_suno"
    task_id = str(data.get("music_task_id") or data.get("provider_task_id") or data.get("task_id") or "").strip()
    endpoint_configured = bool(key4u_suno_provider_download_final_url(task_id or "{taskId}", raw_url=music_first_bare_suno_cdn_url(candidates))) if is_key4u else False
    return {
        "raw_provider_result_saved": bool(isinstance(raw_payload, (dict, list))),
        "provider_result_candidates": candidate_records,
        "provider_result_candidate_count": valid_count,
        "provider_result_candidate_total_count": len(candidates),
        "artifact_candidates_count": valid_count,
        "provider_result_candidate_paths": music_provider_candidate_paths_safe(candidates),
        "provider_result_candidate_paths_text": music_provider_candidate_paths_text(candidates),
        "selected_artifact_field_path": str(selected.get("field_path") or data.get("selected_artifact_field_path") or ""),
        "selected_artifact_url_label": music_result_url_debug_label(selected_url),
        "selected_artifact_has_query": bool(query_meta.get("query_present")),
        "selected_artifact_selected_reason": str(selected.get("selected_reason") or ("fallback_output_url" if selected_url else "")),
        "music_output_url_reject_reason": bare_reject,
        "rejected_candidate_reasons": rejected_reasons,
        "provider_download_endpoint_configured": endpoint_configured,
        "setup_required": KEY4U_SUNO_DOWNLOAD_SETUP_REQUIRED if is_key4u and bare_reject and not endpoint_configured else "",
        "result_url_query_present": bool(query_meta.get("query_present")),
        "result_url_query_param_count": int(query_meta.get("query_param_count") or 0),
        "result_url_signature_param_present": bool(query_meta.get("signature_param_present")),
        "signature_param_present": bool(query_meta.get("signature_param_present")),
        "result_url_label_safe": music_result_url_debug_label(selected_url),
        "provider_name_internal": str(provider_name or data.get("provider") or ""),
    }

def apply_music_provider_result_metadata(target: dict | None = None, polled: dict | None = None, output_url: str = "") -> dict:
    current = dict(target or {})
    payload = dict(polled or {})
    provider_name = str(current.get("provider") or payload.get("provider_name_internal") or payload.get("provider") or "")
    metadata = music_provider_result_metadata(payload, provider_name=provider_name)
    raw_provider_result = payload.get("raw_provider_result") or payload.get("raw_provider_result_internal")
    if isinstance(raw_provider_result, (dict, list)):
        current["raw_provider_result_internal"] = raw_provider_result
        current["raw_provider_result_saved"] = True
    elif payload.get("raw_provider_result_saved"):
        current["raw_provider_result_saved"] = True
    current.update({key: value for key, value in metadata.items() if value not in ("", [], None)})
    for key in (
        "key4u_suno_fetch_attempted",
        "key4u_suno_fetch_http_status",
        "key4u_suno_fetch_status_raw",
        "key4u_suno_fetch_retried",
        "key4u_suno_fetch_candidate_paths",
        "key4u_suno_fetch_candidate_paths_text",
        "provider_download_endpoint_configured",
        "provider_download_endpoint_attempted",
        "provider_download_endpoint_status",
        "provider_download_http_status",
        "provider_download_content_type",
        "provider_download_bytes",
        "wav_endpoint_configured",
        "wav_request_http_status",
        "wav_response_shape",
        "wav_task_id_present",
        "provider_result_item_count",
        "provider_result_item0_keys",
        "provider_result_item1_keys",
        "clip_id_candidates_found",
        "selected_clip_id_source_path",
        "selected_clip_id_present",
        "wav_request_clip_id_source",
        "wav_request_used_provider_task_id_fallback",
        "clip_id_candidate_statuses",
        "final_audio_download_status",
        "wav_response_top_level_keys",
        "wav_response_data_keys",
        "wav_response_result_keys",
        "wav_response_status",
        "wav_response_message_safe",
        "wav_json_audio_url_found",
        "wav_json_task_id_found",
        "wav_json_audio_url_field_path",
        "wav_json_task_id_field_path",
        "wav_followup_attempted",
        "wav_followup_http_status",
        "final_audio_content_type",
        "final_audio_bytes",
        "rejected_candidate_reasons",
        "setup_required",
        "recovery_action",
        "music_output_url_reject_reason",
    ):
        value = payload.get(key)
        if value not in ("", [], None):
            current[key] = value
    raw_url = str(output_url or payload.get("output_url") or music_job_result_url(current) or "").strip()
    if raw_url:
        query_meta = music_url_query_metadata(raw_url)
        current.update({
            "result_url_raw_encrypted_or_internal": raw_url,
            "result_url_label": music_result_url_debug_label(raw_url),
            "result_url_label_safe": music_result_url_debug_label(raw_url),
            "result_url_query_present": bool(query_meta.get("query_present")),
            "result_url_query_param_count": int(query_meta.get("query_param_count") or 0),
            "result_url_signature_param_present": bool(query_meta.get("signature_param_present")),
            "signature_param_present": bool(query_meta.get("signature_param_present")),
        })
    return current

def music_artifact_candidate_bytes(value) -> bytes:
    if isinstance(value, (bytes, bytearray)):
        return bytes(value)
    if hasattr(value, "getvalue"):
        try:
            payload = value.getvalue()
            if isinstance(payload, (bytes, bytearray)):
                return bytes(payload)
        except Exception:
            return b""
    return b""

def music_provider_auth_download_headers(provider_name: str = "") -> dict:
    provider = str(provider_name or "").strip().lower()
    token = ""
    if provider == "key4u_suno" and KEY4U_API_KEY:
        token = KEY4U_API_KEY
    elif provider in {"shopaikey_music", "shopaikey_suno", "shopaikey"} and SHOPAIKEY_API_KEY:
        token = SHOPAIKEY_API_KEY
    if not token:
        return {}
    return {"Authorization": f"Bearer {token}"}

def music_key4u_suno_safe_id(value: str = "") -> str:
    text = re.sub(r"[^A-Za-z0-9_-]+", "", str(value or "").strip())
    if len(text) < 6:
        return ""
    return text[:160]

KEY4U_SUNO_TRACK_ITEM_PATHS = (
    "data.data",
    "data",
    "result.data",
    "result",
    "clips",
    "songs",
    "items",
)
KEY4U_SUNO_CLIP_ID_FIELD_PATHS = (
    "clipId",
    "clip_id",
    "audio_id",
    "audioId",
    "song_id",
    "songId",
    "id",
    "task_id",
    "taskId",
    "data.clipId",
    "data.clip_id",
    "data.id",
)

def music_key4u_suno_provider_result_track_items(payload=None) -> list[dict]:
    rows: list[dict] = []
    seen: set[int] = set()

    def add_item(path: str, item):
        if not isinstance(item, dict):
            return
        marker = id(item)
        if marker in seen:
            return
        seen.add(marker)
        rows.append({
            "path": str(path or "result"),
            "item": item,
            "keys": music_key4u_suno_json_keys_text(item),
        })

    if isinstance(payload, list):
        for index, item in enumerate(payload):
            add_item(f"data[{index}]", item)
    if not isinstance(payload, dict):
        return rows
    for path in KEY4U_SUNO_TRACK_ITEM_PATHS:
        value = music_result_field_path_value(payload, path)
        if isinstance(value, list):
            for index, item in enumerate(value):
                add_item(f"{path}[{index}]", item)
        elif isinstance(value, dict) and any(music_result_field_path_value(value, key) is not None for key in KEY4U_SUNO_CLIP_ID_FIELD_PATHS):
            add_item(path, value)
    return rows

def music_key4u_suno_clip_id_candidates_from_payload(payload=None, *, raw_url: str = "", provider_task_id: str = "") -> list[dict]:
    task = music_key4u_suno_safe_id(str(provider_task_id or ""))
    rows = music_key4u_suno_provider_result_track_items(payload)
    candidates: list[dict] = []
    seen: set[str] = set()

    def add_candidate(value, source_path: str, *, item_keys: str = "", provider_task_fallback: bool = False):
        candidate = music_key4u_suno_safe_id(str(value or ""))
        if not candidate or candidate in seen:
            return
        seen.add(candidate)
        candidates.append({
            "clip_id": candidate,
            "source_path": str(source_path or "-"),
            "item_keys": str(item_keys or "-"),
            "provider_task_fallback": bool(provider_task_fallback or (task and candidate == task and "provider_task_id" in str(source_path or ""))),
        })

    for row in rows:
        item = row.get("item") or {}
        for field_path in KEY4U_SUNO_CLIP_ID_FIELD_PATHS:
            value = music_result_field_path_value(item, field_path)
            if isinstance(value, (str, int)):
                add_candidate(
                    value,
                    f"{row.get('path')}.{field_path}",
                    item_keys=str(row.get("keys") or "-"),
                    provider_task_fallback=bool(task and music_key4u_suno_safe_id(str(value)) == task),
                )
    url_clip = key4u_suno_clip_id_from_url(raw_url)
    if url_clip and not rows:
        add_candidate(url_clip, "raw_url", item_keys="-")
    if task and not candidates and not rows:
        add_candidate(task, "provider_task_id_fallback", item_keys="-", provider_task_fallback=True)
    return candidates

def music_key4u_suno_clip_debug_metadata(payload=None, candidates: list[dict] | None = None, *, selected: dict | None = None) -> dict:
    rows = music_key4u_suno_provider_result_track_items(payload)
    selected_item = dict(selected or {})
    selected_source = str(selected_item.get("source_path") or "")
    return {
        "provider_result_item_count": len(rows),
        "provider_result_item0_keys": str((rows[0] or {}).get("keys") if len(rows) > 0 else "-"),
        "provider_result_item1_keys": str((rows[1] or {}).get("keys") if len(rows) > 1 else "-"),
        "clip_id_candidates_found": len(candidates or []),
        "selected_clip_id_source_path": selected_source,
        "selected_clip_id_present": bool(selected_item.get("clip_id")),
        "wav_request_clip_id_source": selected_source,
        "wav_request_used_provider_task_id_fallback": bool(selected_item.get("provider_task_fallback")),
    }

def music_key4u_suno_clip_debug_detail(metadata: dict | None = None) -> str:
    data = dict(metadata or {})
    return (
        f"provider_result_item_count={int(data.get('provider_result_item_count') or 0)}; "
        f"provider_result_item0_keys={data.get('provider_result_item0_keys') or '-'}; "
        f"provider_result_item1_keys={data.get('provider_result_item1_keys') or '-'}; "
        f"clip_id_candidates_found={int(data.get('clip_id_candidates_found') or 0)}; "
        f"selected_clip_id_source_path={data.get('selected_clip_id_source_path') or '-'}; "
        f"selected_clip_id_present={'yes' if data.get('selected_clip_id_present') else 'no'}; "
        f"wav_request_clip_id_source={data.get('wav_request_clip_id_source') or '-'}; "
        f"wav_request_used_provider_task_id_fallback={'yes' if data.get('wav_request_used_provider_task_id_fallback') else 'no'}"
    )

def music_key4u_suno_clip_candidate_status_text(rows: list[dict] | None = None, *, limit: int = 6) -> str:
    values: list[str] = []
    for row in rows or []:
        current = dict(row or {})
        source = re.sub(r"[^A-Za-z0-9_.\[\]-]+", "_", str(current.get("clip_id_source_path") or "-"))[:90]
        shape = re.sub(r"[^A-Za-z0-9_-]+", "_", str(current.get("wav_response_shape") or "-"))[:40]
        status = re.sub(r"[^A-Za-z0-9_-]+", "_", str(current.get("wav_response_status") or "-"))[:40]
        message = re.sub(r"[|;]+", ",", str(current.get("wav_response_message_safe") or "-"))[:80]
        try:
            http_status = int(current.get("wav_http_status") or 0)
        except Exception:
            http_status = 0
        try:
            final_bytes = int(current.get("final_audio_bytes") or 0)
        except Exception:
            final_bytes = 0
        values.append(f"{source}|http={http_status}|shape={shape}|status={status}|msg={message}|bytes={final_bytes}")
        if len(values) >= max(1, int(limit or 6)):
            break
    return " || ".join(values) if values else "-"

def music_key4u_suno_wav_clip_id_rejected(detail: str = "") -> bool:
    lowered = str(detail or "").lower()
    return bool(
        "wav_response_status=1010" in lowered
        or "no found clipid" in lowered
        or "no_found_clipid" in lowered
        or "nofoundclipid" in lowered
    )

def music_key4u_suno_wav_pending_info(info: dict | None = None) -> bool:
    current = dict(info or {})
    status = str(current.get("status") or "").strip().lower()
    message = str(current.get("message_safe") or "").strip().lower()
    pending_status = status in {"1102", "pending", "processing", "running", "creating"}
    pending_message = any(
        token in message
        for token in (
            "please wait",
            "creation to finish",
            "not ready",
            "not finished",
            "still processing",
            "processing",
        )
    )
    return bool(pending_status or pending_message)

def music_key4u_suno_wav_pending_detail(detail: str = "") -> bool:
    text = str(detail or "")
    lowered = text.lower()
    status = music_download_detail_field(text, "wav_response_status").strip().lower()
    message = music_download_detail_field(text, "wav_response_message_safe").strip().lower()
    final_status = music_download_detail_field(text, "final_audio_download_status").strip().lower()
    return bool(
        MUSIC_ARTIFACT_NOT_READY_BLOCKER in lowered
        or "wav_1102_treated_as_pending=yes" in lowered
        or final_status == "pending"
        or status == "1102"
        or "please wait" in message
        or "creation to finish" in message
        or "not ready" in message
    )

def music_key4u_suno_clip_id_from_payload(payload=None, *, raw_url: str = "", provider_task_id: str = "") -> str:
    candidates = music_key4u_suno_clip_id_candidates_from_payload(payload, raw_url=raw_url, provider_task_id=provider_task_id)
    return str((candidates[0] or {}).get("clip_id") or "") if candidates else ""

def music_key4u_suno_wav_task_id_from_json(payload=None) -> str:
    if isinstance(payload, dict):
        info = music_key4u_suno_wav_json_object_info(payload)
        if info.get("task_id"):
            return str(info.get("task_id") or "")
    data = payload
    if isinstance(payload, dict) and "data" in payload:
        data = payload.get("data")
    if isinstance(data, (str, int)):
        return music_key4u_suno_safe_id(str(data))
    if isinstance(data, dict):
        for key in ("task_id", "taskId", "id", "uuid", "clip_id", "clipId", "audio_id", "audioId"):
            value = data.get(key)
            if isinstance(value, (str, int)):
                candidate = music_key4u_suno_safe_id(str(value))
                if candidate:
                    return candidate
    return ""

def music_key4u_suno_json_response_shape(payload=None) -> str:
    if not isinstance(payload, dict):
        return "json_other"
    data = payload.get("data")
    if isinstance(data, str):
        return "json_data_uuid"
    if isinstance(data, dict):
        return "json_data_object"
    if isinstance(data, list):
        return "json_data_array"
    if data is None:
        return "json_no_data"
    return "json_data_other"

def music_key4u_suno_json_keys_text(value=None, *, limit: int = 12) -> str:
    if not isinstance(value, dict):
        return "-"
    keys: list[str] = []
    for key in sorted(str(item or "") for item in value.keys()):
        safe = re.sub(r"[^A-Za-z0-9_-]+", "_", key).strip("_")[:60]
        if safe:
            keys.append(safe)
        if len(keys) >= max(1, int(limit or 12)):
            break
    return ",".join(keys) if keys else "-"

def music_key4u_suno_safe_json_message(value=None) -> str:
    text = sanitize_provider_status_text(str(value or ""), "", 140).replace(";", ",")
    return text or "-"

def music_key4u_suno_wav_json_object_info(payload=None) -> dict:
    current = payload if isinstance(payload, dict) else {}
    data_obj = current.get("data") if isinstance(current.get("data"), dict) else {}
    result_obj = current.get("result") if isinstance(current.get("result"), dict) else {}
    audio_paths = (
        "url", "audio_url", "audioUrl", "wav_url", "wavUrl", "download_url", "downloadUrl", "file_url", "fileUrl",
        "data.url", "data.audio_url", "data.audioUrl", "data.wav_url", "data.wavUrl", "data.download_url", "data.downloadUrl", "data.file_url", "data.fileUrl",
        "result.url", "result.audio_url", "result.audioUrl", "result.wav_url", "result.wavUrl", "result.download_url", "result.downloadUrl", "result.file_url", "result.fileUrl",
    )
    task_paths = (
        "id", "task_id", "taskId",
        "data.id", "data.task_id", "data.taskId", "data.wav_task_id", "data.wavTaskId", "data.clip_id", "data.clipId", "data.audio_id", "data.audioId",
        "result.id", "result.task_id", "result.taskId", "result.wav_task_id", "result.wavTaskId", "result.clip_id", "result.clipId", "result.audio_id", "result.audioId",
    )
    status_paths = ("status", "code", "data.status", "data.code", "result.status", "result.code")
    message_paths = ("message", "msg", "error", "data.message", "data.msg", "data.error", "result.message", "result.msg", "result.error")
    audio_url = ""
    audio_path = ""
    for path in audio_paths:
        value = music_result_field_path_value(current, path)
        if isinstance(value, str) and value.strip().startswith(("http://", "https://")):
            audio_url = value.strip()
            audio_path = path
            break
    task_id = ""
    task_path = ""
    for path in task_paths:
        value = music_result_field_path_value(current, path)
        if isinstance(value, (str, int)):
            candidate = music_key4u_suno_safe_id(str(value))
            if candidate:
                task_id = candidate
                task_path = path
                break
    status = ""
    status_path = ""
    for path in status_paths:
        value = music_result_field_path_value(current, path)
        if isinstance(value, (str, int)):
            status = music_key4u_suno_safe_json_message(value)
            status_path = path
            break
    message = ""
    for path in message_paths:
        value = music_result_field_path_value(current, path)
        if isinstance(value, (str, int)):
            message = music_key4u_suno_safe_json_message(value)
            break
    return {
        "audio_url": audio_url,
        "audio_url_field_path": audio_path,
        "task_id": task_id,
        "task_id_field_path": task_path,
        "status": status,
        "status_field_path": status_path,
        "message_safe": message or "-",
        "top_level_keys": music_key4u_suno_json_keys_text(current),
        "data_keys": music_key4u_suno_json_keys_text(data_obj),
        "result_keys": music_key4u_suno_json_keys_text(result_obj),
    }

def music_key4u_suno_wav_detail_fields(detail: str = "", *, payload_bytes: int = 0) -> dict:
    text = str(detail or "")
    wav_status = 0
    followup_status = 0
    for raw_status in re.findall(r"(?:^|;\s*)wav_request_http_status=([^;]*)", text, flags=re.IGNORECASE):
        try:
            current_status = int(str(raw_status or "0").strip() or 0)
        except Exception:
            current_status = 0
        if current_status:
            wav_status = current_status
    for raw_status in re.findall(r"(?:^|;\s*)wav_followup_http_status=([^;]*)", text, flags=re.IGNORECASE):
        try:
            current_status = int(str(raw_status or "0").strip() or 0)
        except Exception:
            current_status = 0
        if current_status:
            followup_status = current_status
    shapes = [str(item or "").strip() for item in re.findall(r"(?:^|;\s*)wav_response_shape=([^;]*)", text, flags=re.IGNORECASE)]
    task_flags = [str(item or "").strip().lower() for item in re.findall(r"(?:^|;\s*)wav_task_id_present=([^;]*)", text, flags=re.IGNORECASE)]
    final_statuses = [str(item or "").strip() for item in re.findall(r"(?:^|;\s*)final_audio_download_status=([^;]*)", text, flags=re.IGNORECASE)]
    audio_bytes_values = []
    for raw_bytes in re.findall(r"(?:^|;\s*)final_audio_bytes=([^;]*)", text, flags=re.IGNORECASE):
        try:
            audio_bytes_values.append(int(str(raw_bytes or "0").strip() or 0))
        except Exception:
            pass
    return {
        "wav_endpoint_configured": music_download_detail_field(text, "wav_endpoint_configured") == "yes",
        "wav_request_http_status": wav_status,
        "wav_response_shape": next((item for item in reversed(shapes) if item), ""),
        "wav_task_id_present": "yes" in task_flags,
        "provider_result_item_count": int(music_download_detail_field(text, "provider_result_item_count") or 0),
        "provider_result_item0_keys": music_download_detail_field(text, "provider_result_item0_keys"),
        "provider_result_item1_keys": music_download_detail_field(text, "provider_result_item1_keys"),
        "clip_id_candidates_found": int(music_download_detail_field(text, "clip_id_candidates_found") or 0),
        "selected_clip_id_source_path": music_download_detail_field(text, "selected_clip_id_source_path"),
        "selected_clip_id_present": music_download_detail_field(text, "selected_clip_id_present") == "yes",
        "wav_request_clip_id_source": music_download_detail_field(text, "wav_request_clip_id_source"),
        "wav_request_used_provider_task_id_fallback": music_download_detail_field(text, "wav_request_used_provider_task_id_fallback") == "yes",
        "clip_id_candidate_statuses": music_download_detail_field(text, "clip_id_candidate_statuses"),
        "wav_response_top_level_keys": music_download_detail_field(text, "wav_response_top_level_keys"),
        "wav_response_data_keys": music_download_detail_field(text, "wav_response_data_keys"),
        "wav_response_result_keys": music_download_detail_field(text, "wav_response_result_keys"),
        "wav_response_status": music_download_detail_field(text, "wav_response_status"),
        "wav_response_message_safe": music_download_detail_field(text, "wav_response_message_safe"),
        "wav_json_audio_url_found": music_download_detail_field(text, "wav_json_audio_url_found") == "yes",
        "wav_json_task_id_found": music_download_detail_field(text, "wav_json_task_id_found") == "yes",
        "wav_1102_treated_as_pending": music_download_detail_field(text, "wav_1102_treated_as_pending") == "yes",
        "wav_json_audio_url_field_path": music_download_detail_field(text, "audio_url_field_path"),
        "wav_json_task_id_field_path": music_download_detail_field(text, "task_id_field_path"),
        "wav_followup_attempted": music_download_detail_field(text, "wav_followup_attempted") == "yes",
        "wav_followup_http_status": followup_status,
        "final_audio_content_type": music_download_detail_field(text, "final_audio_content_type"),
        "final_audio_bytes": next((item for item in reversed(audio_bytes_values) if item), int(payload_bytes or 0)),
        "final_audio_download_status": next((item for item in final_statuses if item), ("PASS" if int(payload_bytes or 0) > 0 else "")),
    }

async def music_key4u_suno_audio_from_endpoint(
    endpoint: str,
    *,
    headers: dict,
    timeout_seconds: float = 60.0,
    role: str = "provider_download",
    task_id: str = "",
    clip_id: str = "",
    allow_wav_task_followup: bool = True,
) -> tuple[bytes, str, int]:
    endpoint = str(endpoint or "").strip()
    if not endpoint:
        return b"", "provider_download_endpoint_configured=no", 0
    role_name = re.sub(r"[^a-z0-9_]+", "_", str(role or "provider_download").lower()).strip("_") or "provider_download"
    try:
        async with httpx.AsyncClient(timeout=timeout_seconds, follow_redirects=True) as client:
            response = await client.get(endpoint, headers=headers)
        content_type = str(response.headers.get("content-type") or "").split(";", 1)[0].strip().lower()
        payload = bytes(response.content or b"")
        status = int(response.status_code or 0)
        wav_request_status = status if role_name == "wav_request" else 0
        prefix = (
            f"http={status}; downloaded_bytes={len(payload)}; content_type={content_type}; "
            "provider_download_endpoint_attempted=yes; "
            f"wav_request_http_status={wav_request_status}; "
        )
        if 200 <= status < 300 and payload and (
            content_type.startswith("audio/")
            or content_type in {"application/octet-stream", "binary/octet-stream"}
            or music_audio_url_has_acceptable_extension(endpoint)
        ):
            return payload, (
                f"{prefix}bytes={len(payload)}; wav_response_shape=audio_bytes; "
                f"wav_task_id_present=no; final_audio_download_status=PASS; final_audio_content_type={content_type}; final_audio_bytes={len(payload)}"
            ), status
        if content_type.startswith("application/json") or payload[:1] in {b"{", b"["}:
            try:
                data = response.json()
            except Exception:
                data = {}
            response_shape = music_key4u_suno_json_response_shape(data)
            object_info = music_key4u_suno_wav_json_object_info(data) if isinstance(data, dict) else {}
            object_detail = (
                f"wav_response_top_level_keys={object_info.get('top_level_keys') or '-'}; "
                f"wav_response_data_keys={object_info.get('data_keys') or '-'}; "
                f"wav_response_result_keys={object_info.get('result_keys') or '-'}; "
                f"wav_response_status={object_info.get('status') or '-'}; "
                f"wav_response_message_safe={object_info.get('message_safe') or '-'}; "
                f"wav_json_audio_url_found={'yes' if object_info.get('audio_url') else 'no'}; "
                f"wav_json_task_id_found={'yes' if object_info.get('task_id') else 'no'}; "
                f"audio_url_field_path={object_info.get('audio_url_field_path') or '-'}; "
                f"task_id_field_path={object_info.get('task_id_field_path') or '-'}; "
                f"status_field_path={object_info.get('status_field_path') or '-'}"
            )
            candidates = extract_shopaikey_suno_audio_candidates(data, provider_name="key4u_suno")
            if object_info.get("audio_url"):
                object_candidate = music_provider_candidate_from_url(
                    str(object_info.get("audio_url_field_path") or "wav_json_audio_url"),
                    str(object_info.get("audio_url") or ""),
                    provider_name="key4u_suno",
                    source="KEY4U_SUNO_WAV_JSON_OBJECT",
                )
                object_candidate["selected_reason"] = "wav_json_audio_url_candidate"
                object_candidate["rank"] = max(int(object_candidate.get("rank") or 0), 1600)
                candidates.append(object_candidate)
                candidates = sorted(candidates, key=music_provider_candidate_priority, reverse=True)
            override_path = str(KEY4U_SUNO_RESULT_FIELD or "").strip()
            if override_path:
                override_value = music_result_field_path_value(data, override_path)
                if isinstance(override_value, str) and override_value.strip().startswith(("http://", "https://")):
                    candidates.append(music_provider_candidate_from_url(override_path, override_value, provider_name="key4u_suno", source="KEY4U_SUNO_RESULT_FIELD"))
                    candidates = sorted(candidates, key=music_provider_candidate_priority, reverse=True)
            selected = select_music_provider_audio_candidate(candidates)
            selected_url = str(selected.get("url") or "").strip()
            if selected_url:
                selected_headers = music_provider_auth_download_headers("key4u_suno") if selected.get("requires_auth") else None
                audio_bytes, detail, http_status = await _download_music_audio_url_bytes(
                    selected_url,
                    timeout_seconds=timeout_seconds,
                    headers=selected_headers,
                )
                if audio_bytes:
                    return audio_bytes, (
                        f"{sanitize_provider_status_text(detail, '', 160)}; provider_download_endpoint_attempted=yes; "
                        f"provider_download_json_field={selected.get('field_path')}; wav_response_shape={response_shape}; {object_detail}; "
                        f"wav_task_id_present=no; final_audio_download_status=PASS; "
                        f"final_audio_content_type={music_download_detail_field(detail, 'content_type') or '-'}; final_audio_bytes={len(audio_bytes)}"
                    ), http_status
                category = music_download_error_category(detail, http_status)
                return b"", (
                    f"{sanitize_provider_status_text(detail, '', 160)}; provider_download_endpoint_attempted=yes; "
                    f"provider_download_json_field={selected.get('field_path')}; candidate_paths={music_provider_candidate_paths_text(candidates)}; "
                    f"wav_response_shape={response_shape}; {object_detail}; wav_task_id_present=no; "
                    f"final_audio_download_status=FAIL; final_audio_content_type={music_download_detail_field(detail, 'content_type') or '-'}; "
                    f"final_audio_bytes={music_download_detail_field(detail, 'downloaded_bytes') or 0}; category={category}"
                ), http_status
            if music_key4u_suno_wav_pending_info(object_info):
                return b"", (
                    f"{prefix}wav_response_shape={response_shape}; {object_detail}; wav_task_id_present=no; "
                    "wav_followup_attempted=no; final_audio_download_status=PENDING; "
                    f"wav_1102_treated_as_pending=yes; category={MUSIC_ARTIFACT_NOT_READY_BLOCKER}"
                ), status
            wav_task_id = music_key4u_suno_wav_task_id_from_json(data)
            if wav_task_id and allow_wav_task_followup:
                followup = key4u_suno_wav_result_final_url(wav_task_id, clip_id=clip_id, task_id=task_id)
                if not followup:
                    return b"", (
                        f"{prefix}wav_response_shape={response_shape}; {object_detail}; wav_task_id_present=yes; wav_followup_attempted=no; "
                        "final_audio_download_status=SETUP_REQUIRED; "
                        f"setup_required={KEY4U_SUNO_WAV_SETUP_REQUIRED}; category={KEY4U_SUNO_WAV_RESULT_BLOCKER}"
                    ), status
                audio_bytes, follow_detail, follow_status = await music_key4u_suno_audio_from_endpoint(
                    followup,
                    headers=headers,
                    timeout_seconds=timeout_seconds,
                    role="wav_result",
                    task_id=wav_task_id,
                    clip_id=clip_id,
                    allow_wav_task_followup=False,
                )
                if audio_bytes:
                    return audio_bytes, (
                        f"{sanitize_provider_status_text(follow_detail, wav_task_id, 180)}; "
                        f"{prefix}wav_response_shape={response_shape}; {object_detail}; wav_task_id_present=yes; "
                        f"wav_task_id_safe={mask_provider_task_id(wav_task_id)}; wav_followup_attempted=yes; "
                        f"wav_followup_http_status={int(follow_status or 0)}; final_audio_download_status=PASS; "
                        f"final_audio_content_type={music_download_detail_field(follow_detail, 'final_audio_content_type') or music_download_detail_field(follow_detail, 'content_type') or '-'}; "
                        f"final_audio_bytes={len(audio_bytes)}"
                    ), follow_status
                category = music_download_error_category(follow_detail, follow_status)
                return b"", (
                    f"{prefix}wav_response_shape={response_shape}; {object_detail}; wav_task_id_present=yes; "
                    f"wav_task_id_safe={mask_provider_task_id(wav_task_id)}; wav_followup_attempted=yes; "
                    f"wav_followup_http_status={int(follow_status or 0)}; final_audio_download_status=FAIL; "
                    f"{sanitize_provider_status_text(follow_detail, wav_task_id, 180)}; category={category or 'wav_result_download_failed'}"
                ), follow_status or status
            if response_shape == "json_data_object":
                return b"", (
                    f"{prefix}wav_response_shape={response_shape}; {object_detail}; wav_task_id_present=no; "
                    "wav_followup_attempted=no; final_audio_download_status=FAIL; "
                    f"category={KEY4U_SUNO_WAV_JSON_OBJECT_BLOCKER}"
                ), status
            return b"", (
                f"{prefix}wav_response_shape={response_shape}; {object_detail}; wav_task_id_present={'yes' if wav_task_id else 'no'}; "
                f"candidate_paths={music_provider_candidate_paths_text(candidates)}; final_audio_download_status=FAIL; downloadable_candidate_missing"
            ), status
        body_class = music_download_error_body_class(payload[:512].decode("utf-8", errors="ignore"), content_type)
        return b"", (
            f"{prefix}wav_response_shape=non_json; wav_task_id_present=no; final_audio_download_status=FAIL; "
            f"error_body_class={body_class or '-'}"
        ), status
    except Exception as exc:
        return b"", (
            "provider_download_endpoint_attempted=yes; final_audio_download_status=FAIL; "
            f"provider_proxy_exception={sanitize_provider_status_text(str(exc), '', 160)}"
        ), 0

async def music_provider_proxy_download_audio(
    *,
    provider_name: str = "",
    provider_task_id: str = "",
    raw_url: str = "",
    raw_provider_result=None,
    timeout_seconds: float = 60.0,
) -> tuple[bytes, str, int]:
    provider = str(provider_name or "").strip().lower()
    task_id = str(provider_task_id or "").strip()
    if provider != "key4u_suno":
        return b"", "provider_proxy_unavailable", 0
    clip_candidates = music_key4u_suno_clip_id_candidates_from_payload(raw_provider_result, raw_url=raw_url, provider_task_id=task_id)
    download_template = str(KEY4U_SUNO_DOWNLOAD_URL or "").strip()
    download_needs_clip_id = bool(
        "/act/wav" in download_template.lower()
        or any(token in download_template for token in ("{clip_id}", "{clipId}", "{audio_id}", "{audioId}", "{id}"))
    )
    wav_endpoint_configured = bool(key4u_suno_wav_final_url("{clip_id}", task_id=task_id or "{taskId}", raw_url=raw_url))
    provider_download_without_clip = key4u_suno_download_final_url(task_id, audio_id="", raw_url=raw_url)
    candidate_statuses: list[dict] = []
    headers = music_provider_auth_download_headers("key4u_suno")
    headers = {
        **headers,
        "Accept": "audio/wav,audio/mpeg,audio/*,application/json,*/*",
        "User-Agent": "TOAN-AAS/1.0",
        "Referer": "https://api.key4u.shop/",
    }

    def debug_detail(selected: dict | None = None) -> str:
        metadata = music_key4u_suno_clip_debug_metadata(raw_provider_result, clip_candidates, selected=selected)
        detail = music_key4u_suno_clip_debug_detail(metadata)
        return f"{detail}; clip_id_candidate_statuses={music_key4u_suno_clip_candidate_status_text(candidate_statuses)}"

    if not clip_candidates and provider_download_without_clip and not download_needs_clip_id:
        audio_bytes, detail, status = await music_key4u_suno_audio_from_endpoint(
            provider_download_without_clip,
            headers=headers,
            timeout_seconds=timeout_seconds,
            role="provider_download",
            task_id=task_id,
            clip_id="",
            allow_wav_task_followup=True,
        )
        if "wav_endpoint_configured=" not in detail:
            detail = f"{detail}; wav_endpoint_configured={'yes' if wav_endpoint_configured else 'no'}"
        return audio_bytes, f"{detail}; {debug_detail({})}", status

    if not clip_candidates:
        return b"", (
            "provider_download_endpoint_attempted=no; final_audio_download_status=FAIL; "
            f"wav_endpoint_configured={'yes' if wav_endpoint_configured else 'no'}; "
            f"{debug_detail({})}; category={KEY4U_SUNO_CLIP_ID_MISSING_BLOCKER}"
        ), 0

    if not (
        key4u_suno_download_final_url(task_id, audio_id="{clip_id}", raw_url=raw_url)
        or key4u_suno_wav_final_url("{clip_id}", task_id=task_id or "{taskId}", raw_url=raw_url)
    ):
        return b"", (
            "provider_proxy_unavailable; provider_download_endpoint_configured=no; "
            f"wav_endpoint_configured={'yes' if wav_endpoint_configured else 'no'}; {debug_detail({})}"
        ), 0

    last_detail = ""
    last_status = 0
    last_selected: dict = {}
    for candidate in clip_candidates:
        current = dict(candidate or {})
        clip_id = str(current.get("clip_id") or "").strip()
        if not clip_id:
            continue
        last_selected = current
        endpoint = (
            key4u_suno_download_final_url(task_id, audio_id=clip_id, raw_url=raw_url)
            or key4u_suno_wav_final_url(clip_id, task_id=task_id, raw_url=raw_url)
        )
        if not endpoint:
            continue
        role = "wav_request" if "/act/wav" in urlparse(endpoint).path.lower() or bool(KEY4U_SUNO_WAV_URL) else "provider_download"
        audio_bytes, detail, status = await music_key4u_suno_audio_from_endpoint(
            endpoint,
            headers=headers,
            timeout_seconds=timeout_seconds,
            role=role,
            task_id=task_id,
            clip_id=clip_id,
            allow_wav_task_followup=True,
        )
        last_detail = detail
        last_status = status
        try:
            final_bytes = int(music_download_detail_field(detail, "final_audio_bytes") or len(audio_bytes) or 0)
        except Exception:
            final_bytes = len(audio_bytes or b"")
        clip_rejected = music_key4u_suno_wav_clip_id_rejected(detail)
        candidate_statuses.append({
            "clip_id_source_path": str(current.get("source_path") or "-"),
            "wav_http_status": int(status or 0),
            "wav_response_shape": music_download_detail_field(detail, "wav_response_shape") or "-",
            "wav_response_status": music_download_detail_field(detail, "wav_response_status") or "-",
            "wav_response_message_safe": music_download_detail_field(detail, "wav_response_message_safe") or "-",
            "final_audio_bytes": final_bytes,
            "clip_rejected": clip_rejected,
        })
        if audio_bytes:
            if "wav_endpoint_configured=" not in detail:
                detail = f"{detail}; wav_endpoint_configured={'yes' if wav_endpoint_configured else 'no'}"
            return audio_bytes, f"{detail}; {debug_detail(current)}", status
        if not clip_rejected:
            break

    all_rejected = bool(candidate_statuses) and all(bool(item.get("clip_rejected")) for item in candidate_statuses)
    category = KEY4U_SUNO_WAV_CLIP_ID_REJECTED_BLOCKER if all_rejected else (music_download_error_category(last_detail, last_status) or "provider_download_error")
    detail = last_detail or "provider_download_endpoint_attempted=yes; final_audio_download_status=FAIL"
    if "wav_endpoint_configured=" not in detail:
        detail = f"{detail}; wav_endpoint_configured={'yes' if wav_endpoint_configured else 'no'}"
    return b"", f"{detail}; {debug_detail(last_selected)}; category={category}", last_status

async def music_download_artifact_candidate(
    candidate: dict | None = None,
    job: dict | None = None,
    *,
    timeout_seconds: float = 60.0,
) -> dict:
    item = dict(candidate or {})
    current = dict(job or {})
    url = str(item.get("url") or item.get("artifact_url") or item.get("output_url") or item.get("download_url") or "").strip()
    provider_name = str(item.get("provider_name") or current.get("provider") or current.get("provider_name_internal") or "")
    provider_task_id = music_job_provider_task_id(current)
    raw_provider_result = current.get("raw_provider_result_internal") or current.get("raw_provider_result") or {}
    attempts: list[dict] = []
    raw_audio_prefetch: dict = {}

    async def run_strategy(strategy: str, extra_headers: dict | None = None, target_url: str = ""):
        request_url = str(target_url or url)
        if extra_headers:
            payload, detail, status = await _download_music_audio_url_bytes(request_url, timeout_seconds=timeout_seconds, headers=extra_headers)
        else:
            payload, detail, status = await _download_music_audio_url_bytes(request_url, timeout_seconds=timeout_seconds)
        content_type = music_download_detail_field(detail, "content_type")
        downloaded = len(payload)
        if not payload:
            try:
                downloaded = int(music_download_detail_field(detail, "downloaded_bytes") or 0)
            except Exception:
                downloaded = 0
        category = music_download_error_category(detail, status)
        attempts.append({
            "strategy": strategy,
            "http_status": int(status or 0),
            "detail": sanitize_provider_status_text(detail, "", 180),
            "content_type": content_type,
            "downloaded_bytes": int(downloaded or 0),
            "category": category,
        })
        return payload, detail, status, content_type, downloaded, category

    clip_id = music_key4u_suno_clip_id_from_payload(raw_provider_result, raw_url=url, provider_task_id=provider_task_id) if provider_name == "key4u_suno" else ""
    provider_download_endpoint_configured = bool(
        key4u_suno_download_final_url(provider_task_id, audio_id=clip_id, raw_url=url)
        or key4u_suno_wav_final_url(clip_id or "{clip_id}", task_id=provider_task_id or "{taskId}", raw_url=url)
    ) if provider_name == "key4u_suno" else False

    if not url:
        return {"ok": False, "status": "MISSING_URL", "download_strategy_used": "", "provider_auth_header_used": False, "provider_proxy_attempted": False, "provider_download_endpoint_configured": provider_download_endpoint_configured, "provider_download_endpoint_attempted": False}

    is_key4u_bare_suno_cdn = bool(provider_name == "key4u_suno" and music_url_is_bare_suno_cdn(url))
    force_direct_suno_cdn = bool(provider_name == "key4u_suno" and music_artifact_candidate_is_direct_suno_audio(item))

    if force_direct_suno_cdn:
        payload, detail, status, content_type, downloaded, category = await run_strategy("direct_cdn")
        common = {
            "download_detail": detail,
            "download_http_status": int(status or 0),
            "download_content_type": content_type,
            "downloaded_bytes": int(downloaded or len(payload) or 0),
            "download_strategy_used": "direct_cdn",
            "provider_auth_header_used": False,
            "provider_proxy_attempted": False,
            "provider_download_endpoint_configured": provider_download_endpoint_configured,
            "provider_download_endpoint_attempted": False,
            "provider_download_http_status": 0,
            "provider_download_content_type": "",
            "provider_download_bytes": 0,
            "provider_auth_bypassed_for_direct_cdn": True,
            "provider_auth_bypassed_for_direct_suno_cdn": True,
            "direct_cdn_download_attempted": True,
            "direct_cdn_download_http_status": int(status or 0),
            "direct_cdn_download_content_type": content_type,
            "direct_cdn_download_bytes": int(downloaded or len(payload) or 0),
            "candidate_attempted": True,
            "candidate_field_path": str(item.get("field_path") or item.get("source") or ""),
            "candidate_host": urlparse(url).netloc,
            "candidate_bare_url_allowed_for_validation": True,
            "candidate_http_status": int(status or 0),
            "candidate_content_type": content_type,
            "candidate_bytes": int(downloaded or len(payload) or 0),
            "download_attempts": attempts,
        }
        if payload:
            return {
                "ok": True,
                "audio_bytes": payload,
                "download_error_category": "",
                "pr173_artifact_engine_restored": True,
                "old_working_candidate_path_used": str(item.get("field_path") or item.get("source") or ""),
                "direct_audio_url_get_attempted": True,
                "provider_download_endpoint_bypassed_for_raw_audio": True,
                "candidate_validation_passed": True,
                "direct_cdn_validation_passed": True,
                "audio_validation_passed": True,
                "artifact_ready": True,
                "final_audio_download_status": "PASS",
                "final_audio_content_type": content_type,
                "final_audio_bytes": len(payload),
                **common,
            }
        return {
            "ok": False,
            "status": "ARTIFACT_DOWNLOAD_FAILED",
            "audio_bytes": b"",
            "download_error_category": category or "download_failed",
            "pr173_artifact_engine_restored": True,
            "old_working_candidate_path_used": str(item.get("field_path") or item.get("source") or ""),
            "direct_audio_url_get_attempted": True,
            "provider_download_endpoint_bypassed_for_raw_audio": True,
            "candidate_validation_passed": False,
            "direct_cdn_validation_passed": False,
            "audio_validation_passed": False,
            "artifact_ready": False,
            "final_audio_download_status": "FAIL",
            "final_audio_content_type": content_type,
            "final_audio_bytes": 0,
            "setup_required": "",
            **common,
        }

    raw_result_url = str(item.get("raw_result_url") or "").strip()
    raw_result_field_path = str(item.get("raw_result_field_path") or item.get("field_path") or item.get("source") or "")
    if (
        provider_name == "key4u_suno"
        and item.get("provider_download_endpoint_candidate")
        and not item.get("skip_raw_audio_prefetch")
        and bool(item.get("prefer_direct_raw_audio") or item.get("force_direct_raw_audio") or item.get("pr173_direct_raw_audio_first"))
        and raw_result_url
        and music_artifact_candidate_is_direct_suno_audio({
            **item,
            "url": raw_result_url,
            "field_path": raw_result_field_path,
            "source": raw_result_field_path,
            "provider_download_endpoint_candidate": False,
        })
    ):
        payload, detail, status, content_type, downloaded, category = await run_strategy("direct_raw_url", target_url=raw_result_url)
        common = {
            "download_detail": detail,
            "download_http_status": int(status or 0),
            "download_content_type": content_type,
            "downloaded_bytes": int(downloaded or len(payload) or 0),
            "download_strategy_used": "direct_raw_url",
            "provider_auth_header_used": False,
            "provider_proxy_attempted": False,
            "provider_download_endpoint_configured": provider_download_endpoint_configured,
            "provider_download_endpoint_attempted": False,
            "provider_download_http_status": 0,
            "provider_download_content_type": "",
            "provider_download_bytes": 0,
            "provider_auth_bypassed_for_direct_cdn": True,
            "provider_auth_bypassed_for_direct_suno_cdn": True,
            "direct_audio_url_get_attempted": True,
            "direct_audio_url_http_status": int(status or 0),
            "direct_audio_url_content_type": content_type,
            "direct_audio_url_bytes": int(downloaded or len(payload) or 0),
            "direct_audio_url_validation_passed": bool(payload),
            "direct_cdn_download_attempted": True,
            "direct_cdn_download_http_status": int(status or 0),
            "direct_cdn_download_content_type": content_type,
            "direct_cdn_download_bytes": int(downloaded or len(payload) or 0),
            "provider_download_endpoint_bypassed_for_raw_audio": True,
            "provider_download_json_83_bytes_ignored": True,
            "wav_json_no_data_ignored_when_raw_url_present": True,
            "selected_artifact_strategy": "direct_raw_url",
            "candidate_attempted": True,
            "candidate_field_path": raw_result_field_path,
            "candidate_host": urlparse(raw_result_url).netloc,
            "candidate_bare_url_allowed_for_validation": True,
            "candidate_http_status": int(status or 0),
            "candidate_content_type": content_type,
            "candidate_bytes": int(downloaded or len(payload) or 0),
            "download_attempts": attempts,
        }
        if payload:
            return {
                "ok": True,
                "audio_bytes": payload,
                "download_error_category": "",
                "pr173_artifact_engine_restored": True,
                "old_working_candidate_path_used": raw_result_field_path,
                "candidate_validation_passed": True,
                "direct_cdn_validation_passed": True,
                "audio_validation_passed": True,
                "artifact_ready": True,
                "final_audio_download_status": "PASS",
                "final_audio_content_type": content_type,
                "final_audio_bytes": len(payload),
                **common,
            }
        raw_audio_prefetch = {
            "direct_audio_url_error_category": category or "download_failed",
            "direct_audio_url_prefetch_failed": True,
            "direct_audio_url_prefetch_detail": sanitize_provider_status_text(detail, "", 180),
            **common,
        }

    if provider_name == "key4u_suno" and item.get("provider_download_endpoint_candidate"):
        proxy_payload, proxy_detail, proxy_status = await music_provider_proxy_download_audio(
            provider_name=provider_name,
            provider_task_id=provider_task_id,
            raw_url=str(item.get("raw_result_url") or url),
            raw_provider_result=raw_provider_result,
            timeout_seconds=timeout_seconds,
        )
        proxy_content_type = music_download_detail_field(proxy_detail, "content_type")
        if proxy_payload:
            wav_fields = music_key4u_suno_wav_detail_fields(proxy_detail, payload_bytes=len(proxy_payload))
            return {
                "ok": True,
                "audio_bytes": proxy_payload,
                "download_detail": proxy_detail,
                "download_http_status": int(proxy_status or 0),
                "download_content_type": proxy_content_type,
                "downloaded_bytes": len(proxy_payload),
                "download_error_category": "",
                "download_strategy_used": "provider_proxy",
                "provider_auth_header_used": bool(music_provider_auth_download_headers(provider_name)),
                "provider_proxy_attempted": True,
                "provider_download_endpoint_configured": provider_download_endpoint_configured,
                "provider_download_endpoint_attempted": True,
                "provider_download_http_status": int(proxy_status or 0),
                "provider_download_content_type": proxy_content_type,
                "provider_download_bytes": len(proxy_payload),
                "direct_audio_url_get_attempted": bool(raw_audio_prefetch.get("direct_audio_url_get_attempted")),
                "direct_audio_url_http_status": int(raw_audio_prefetch.get("direct_audio_url_http_status") or 0),
                "direct_audio_url_content_type": str(raw_audio_prefetch.get("direct_audio_url_content_type") or ""),
                "direct_audio_url_bytes": int(raw_audio_prefetch.get("direct_audio_url_bytes") or 0),
                "direct_audio_url_validation_passed": False,
                "direct_audio_url_error_category": str(raw_audio_prefetch.get("direct_audio_url_error_category") or ""),
                **wav_fields,
                "setup_required": "",
                "download_attempts": [{
                    "strategy": "provider_proxy",
                    "http_status": int(proxy_status or 0),
                    "detail": sanitize_provider_status_text(proxy_detail, "", 180),
                    "content_type": proxy_content_type,
                    "downloaded_bytes": len(proxy_payload),
                    "category": "",
                }],
            }
        proxy_category = music_download_error_category(proxy_detail, proxy_status) or "provider_download_error"
        try:
            proxy_downloaded = int(music_download_detail_field(proxy_detail, "downloaded_bytes") or music_download_detail_field(proxy_detail, "bytes") or 0)
        except Exception:
            proxy_downloaded = 0
        direct_attempt = {}
        proxy_selected_clip_present = music_download_detail_field(proxy_detail, "selected_clip_id_present") == "yes"
        proxy_allows_direct_bare_suno_validation = proxy_category in {
            KEY4U_SUNO_WAV_JSON_OBJECT_BLOCKER,
            MUSIC_ARTIFACT_NOT_READY_BLOCKER,
        }
        proxy_json_no_audio = bool(
            music_download_detail_field(proxy_detail, "wav_response_shape").lower().startswith("json")
            and str(music_download_detail_field(proxy_detail, "final_audio_download_status") or "").strip().upper() in {"", "FAIL", "PENDING"}
        )
        if proxy_json_no_audio and proxy_category not in {KEY4U_SUNO_CLIP_ID_MISSING_BLOCKER, KEY4U_SUNO_WAV_CLIP_ID_REJECTED_BLOCKER}:
            proxy_allows_direct_bare_suno_validation = True
        if proxy_selected_clip_present and proxy_allows_direct_bare_suno_validation and music_url_is_bare_suno_cdn(raw_result_url):
            direct_payload, direct_detail, direct_status = await _download_music_audio_url_bytes(raw_result_url, timeout_seconds=timeout_seconds)
            direct_content_type = music_download_detail_field(direct_detail, "content_type")
            try:
                direct_downloaded = int(music_download_detail_field(direct_detail, "downloaded_bytes") or len(direct_payload) or 0)
            except Exception:
                direct_downloaded = len(direct_payload or b"")
            direct_category = music_download_error_category(direct_detail, direct_status)
            direct_attempt = {
                "strategy": "direct_bare_suno_validation",
                "http_status": int(direct_status or 0),
                "detail": sanitize_provider_status_text(direct_detail, "", 180),
                "content_type": direct_content_type,
                "downloaded_bytes": int(direct_downloaded or 0),
                "category": direct_category,
            }
            if direct_payload:
                wav_fields = music_key4u_suno_wav_detail_fields(proxy_detail, payload_bytes=len(direct_payload))
                return {
                    "ok": True,
                    "audio_bytes": direct_payload,
                    "download_detail": f"{sanitize_provider_status_text(proxy_detail, '', 180)}; direct_bare_suno_validation=PASS; {sanitize_provider_status_text(direct_detail, '', 180)}",
                    "download_http_status": int(direct_status or 0),
                    "download_content_type": direct_content_type,
                    "downloaded_bytes": int(direct_downloaded or len(direct_payload) or 0),
                    "download_error_category": "",
                    "download_strategy_used": "provider_proxy_then_direct_bare_suno_validation",
                    "provider_auth_header_used": bool(music_provider_auth_download_headers(provider_name)),
                    "provider_proxy_attempted": True,
                    "provider_download_endpoint_configured": provider_download_endpoint_configured,
                    "provider_download_endpoint_attempted": True,
                    "provider_download_http_status": int(proxy_status or 0),
                    "provider_download_content_type": proxy_content_type,
                    "provider_download_bytes": int(proxy_downloaded or 0),
                    **wav_fields,
                    "final_audio_download_status": "PASS",
                    "final_audio_content_type": direct_content_type,
                    "final_audio_bytes": len(direct_payload),
                    "candidate_attempted": True,
                    "candidate_field_path": raw_result_field_path,
                    "candidate_host": urlparse(raw_result_url).netloc,
                    "candidate_bare_url_allowed_for_validation": True,
                    "candidate_http_status": int(direct_status or 0),
                    "candidate_content_type": direct_content_type,
                    "candidate_bytes": int(direct_downloaded or len(direct_payload) or 0),
                    "candidate_validation_passed": True,
                    "setup_required": "",
                    "download_attempts": [{
                        "strategy": "provider_proxy",
                        "http_status": int(proxy_status or 0),
                        "detail": sanitize_provider_status_text(proxy_detail, "", 180),
                        "content_type": proxy_content_type,
                        "downloaded_bytes": int(proxy_downloaded or 0),
                        "category": proxy_category,
                    }, direct_attempt],
                }
        wav_fields = music_key4u_suno_wav_detail_fields(proxy_detail, payload_bytes=0)
        download_attempts = [{
            "strategy": "provider_proxy",
            "http_status": int(proxy_status or 0),
            "detail": sanitize_provider_status_text(proxy_detail, "", 180),
            "content_type": proxy_content_type,
            "downloaded_bytes": int(proxy_downloaded or 0),
            "category": proxy_category,
        }]
        if direct_attempt:
            download_attempts.append(direct_attempt)
        return {
            "ok": False,
            "status": "ARTIFACT_DOWNLOAD_FAILED",
            "download_detail": sanitize_provider_status_text(proxy_detail, "", 180),
            "download_http_status": int(proxy_status or 0),
            "download_content_type": proxy_content_type,
            "downloaded_bytes": int(proxy_downloaded or 0),
            "download_error_category": proxy_category,
            "download_strategy_used": "provider_proxy",
            "provider_auth_header_used": bool(music_provider_auth_download_headers(provider_name)),
            "provider_proxy_attempted": True,
            "provider_download_endpoint_configured": provider_download_endpoint_configured,
            "provider_download_endpoint_attempted": True,
            "provider_download_http_status": int(proxy_status or 0),
            "provider_download_content_type": proxy_content_type,
            "provider_download_bytes": int(proxy_downloaded or 0),
            "direct_audio_url_get_attempted": bool(raw_audio_prefetch.get("direct_audio_url_get_attempted")),
            "direct_audio_url_http_status": int(raw_audio_prefetch.get("direct_audio_url_http_status") or 0),
            "direct_audio_url_content_type": str(raw_audio_prefetch.get("direct_audio_url_content_type") or ""),
            "direct_audio_url_bytes": int(raw_audio_prefetch.get("direct_audio_url_bytes") or 0),
            "direct_audio_url_validation_passed": False,
            "direct_audio_url_error_category": str(raw_audio_prefetch.get("direct_audio_url_error_category") or ""),
            "direct_audio_url_prefetch_failed": bool(raw_audio_prefetch.get("direct_audio_url_prefetch_failed")),
            **wav_fields,
            "candidate_attempted": bool(direct_attempt),
            "candidate_field_path": raw_result_field_path,
            "candidate_host": urlparse(raw_result_url).netloc if raw_result_url else "",
            "candidate_bare_url_allowed_for_validation": bool(direct_attempt and music_url_is_bare_suno_cdn(raw_result_url)),
            "candidate_http_status": int((direct_attempt or {}).get("http_status") or 0),
            "candidate_content_type": str((direct_attempt or {}).get("content_type") or ""),
            "candidate_bytes": int((direct_attempt or {}).get("downloaded_bytes") or 0),
            "candidate_validation_passed": False,
            "setup_required": str(music_download_detail_field(proxy_detail, "setup_required") or ("" if provider_download_endpoint_configured else KEY4U_SUNO_DOWNLOAD_SETUP_REQUIRED)),
            "download_attempts": download_attempts,
        }

    payload, detail, status, content_type, downloaded, category = await run_strategy("direct_raw_url")
    if payload:
        return {
            "ok": True,
            "audio_bytes": payload,
            "download_detail": detail,
            "download_http_status": int(status or 0),
            "download_content_type": content_type,
            "downloaded_bytes": int(downloaded or len(payload) or 0),
            "download_error_category": "",
            "download_strategy_used": "direct_raw_url",
            "pr173_artifact_engine_restored": True,
            "old_working_candidate_path_used": str(item.get("field_path") or item.get("source") or ""),
            "direct_audio_url_get_attempted": True,
            "provider_download_endpoint_bypassed_for_raw_audio": bool(provider_name == "key4u_suno"),
            "audio_validation_passed": True,
            "artifact_ready": True,
            "provider_auth_header_used": False,
            "provider_proxy_attempted": False,
            "provider_download_endpoint_configured": provider_download_endpoint_configured,
            "provider_download_endpoint_attempted": False,
            "candidate_attempted": True,
            "candidate_field_path": str(item.get("field_path") or item.get("source") or ""),
            "candidate_host": urlparse(url).netloc,
            "candidate_bare_url_allowed_for_validation": bool(is_key4u_bare_suno_cdn),
            "candidate_http_status": int(status or 0),
            "candidate_content_type": content_type,
            "candidate_bytes": int(downloaded or len(payload) or 0),
            "candidate_validation_passed": True,
            "download_attempts": attempts,
        }

    auth_headers = music_provider_auth_download_headers(provider_name)
    auth_needed = int(status or 0) in {401, 403} or bool(item.get("requires_auth")) or category in {"provider_auth_required", "result_url_forbidden", "result_url_forbidden_access_denied", "result_url_forbidden_or_missing_auth"}
    auth_used = False
    if auth_headers and auth_needed:
        auth_used = True
        payload, detail, status, content_type, downloaded, category = await run_strategy("provider_auth", auth_headers)
        if payload:
            return {
                "ok": True,
                "audio_bytes": payload,
                "download_detail": detail,
                "download_http_status": int(status or 0),
                "download_content_type": content_type,
                "downloaded_bytes": int(downloaded or len(payload) or 0),
                "download_error_category": "",
                "download_strategy_used": "provider_auth",
                "provider_auth_header_used": True,
                "provider_proxy_attempted": False,
                "provider_download_endpoint_configured": provider_download_endpoint_configured,
                "provider_download_endpoint_attempted": False,
                "candidate_attempted": True,
                "candidate_field_path": str(item.get("field_path") or item.get("source") or ""),
                "candidate_host": urlparse(url).netloc,
                "candidate_bare_url_allowed_for_validation": bool(is_key4u_bare_suno_cdn),
                "candidate_http_status": int(status or 0),
                "candidate_content_type": content_type,
                "candidate_bytes": int(downloaded or len(payload) or 0),
                "candidate_validation_passed": True,
                "download_attempts": attempts,
            }

    allow_proxy_fallback = bool(
        provider_name != "key4u_suno"
        or key4u_suno_download_final_url(provider_task_id, audio_id=clip_id, raw_url=url)
    )
    proxy_payload, proxy_detail, proxy_status = (b"", "", 0)
    proxy_attempted = False
    if allow_proxy_fallback:
        proxy_payload, proxy_detail, proxy_status = await music_provider_proxy_download_audio(
            provider_name=provider_name,
            provider_task_id=provider_task_id,
            raw_url=url,
            raw_provider_result=raw_provider_result,
            timeout_seconds=timeout_seconds,
        )
        proxy_attempted = True
    if proxy_payload:
        proxy_content_type = music_download_detail_field(proxy_detail, "content_type")
        wav_fields = music_key4u_suno_wav_detail_fields(proxy_detail, payload_bytes=len(proxy_payload))
        return {
            "ok": True,
            "audio_bytes": proxy_payload,
            "download_detail": proxy_detail,
            "download_http_status": int(proxy_status or 0),
            "download_content_type": proxy_content_type,
            "downloaded_bytes": len(proxy_payload),
            "download_error_category": "",
            "download_strategy_used": "provider_proxy",
            "provider_auth_header_used": auth_used,
            "provider_proxy_attempted": True,
            "provider_download_endpoint_configured": provider_download_endpoint_configured,
            "provider_download_endpoint_attempted": True,
            "provider_download_http_status": int(proxy_status or 0),
            "provider_download_content_type": proxy_content_type,
            "provider_download_bytes": len(proxy_payload),
            **wav_fields,
            "download_attempts": attempts + [{
                "strategy": "provider_proxy",
                "http_status": int(proxy_status or 0),
                "detail": sanitize_provider_status_text(proxy_detail, "", 180),
                "content_type": proxy_content_type,
                "downloaded_bytes": len(proxy_payload),
                "category": "",
            }],
        }
    proxy_category = music_download_error_category(proxy_detail, proxy_status) if proxy_status else ""
    if proxy_category:
        category = proxy_category
        detail = proxy_detail
        status = proxy_status
        content_type = music_download_detail_field(proxy_detail, "content_type")
        try:
            downloaded = int(music_download_detail_field(proxy_detail, "downloaded_bytes") or 0)
        except Exception:
            downloaded = 0
    wav_fields = music_key4u_suno_wav_detail_fields(proxy_detail, payload_bytes=0)
    return {
        "ok": False,
        "status": "ARTIFACT_DOWNLOAD_FAILED",
        "download_detail": detail,
        "download_http_status": int(status or 0),
        "download_content_type": content_type,
        "downloaded_bytes": int(downloaded or 0),
        "download_error_category": category or "download_failed",
        "download_strategy_used": str((attempts[-1] or {}).get("strategy") if attempts else "direct_raw_url"),
        "provider_auth_header_used": auth_used,
        "provider_proxy_attempted": proxy_attempted,
        "provider_download_endpoint_configured": provider_download_endpoint_configured,
        "provider_download_endpoint_attempted": proxy_attempted and provider_name == "key4u_suno",
        "provider_download_http_status": int(proxy_status or status or 0),
        "provider_download_content_type": content_type,
        "provider_download_bytes": int(downloaded or 0),
        **wav_fields,
        "candidate_attempted": bool(attempts),
        "candidate_field_path": str(item.get("field_path") or item.get("source") or ""),
        "candidate_host": urlparse(url).netloc,
        "candidate_bare_url_allowed_for_validation": bool(is_key4u_bare_suno_cdn),
        "candidate_http_status": int(status or 0),
        "candidate_content_type": content_type,
        "candidate_bytes": int(downloaded or 0),
        "candidate_validation_passed": False,
        "setup_required": str(music_download_detail_field(proxy_detail, "setup_required") or ""),
        "download_attempts": attempts,
    }

def music_delivery_artifact_candidates(result: dict | None = None, job: dict | None = None, audio_bytes: bytes | bytearray | None = None) -> list[dict]:
    data = {**dict(job or {}), **dict(result or {})}
    candidates: list[dict] = []
    provider_name = str(data.get("provider") or data.get("provider_name_internal") or "")
    provider_task_id = music_job_provider_task_id(data)
    first_bare_suno_url = ""
    first_bare_suno_field_path = ""
    rejected_reasons: list[str] = []
    for key in ("provider_result_candidates", "music_artifact_candidates", "artifact_candidates", "output_candidates", "music_output_candidates"):
        value = data.get(key)
        if isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    current = dict(item)
                    if current.get("rejected"):
                        rejected_reasons.extend(music_provider_rejected_candidate_reasons([current]))
                        rejected_url = str(current.get("url") or "").strip()
                        if not first_bare_suno_url and rejected_url and music_url_is_bare_suno_cdn(rejected_url):
                            first_bare_suno_url = rejected_url
                            first_bare_suno_field_path = str(current.get("field_path") or current.get("source") or "")
                        continue
                    if current.get("url") and not current.get("safe_label"):
                        current["safe_label"] = music_result_url_debug_label(current.get("url") or "")
                    candidates.append(current)
                    current_url = str(current.get("url") or "").strip()
                    if not first_bare_suno_url and current_url and music_url_is_bare_suno_cdn(current_url):
                        first_bare_suno_url = current_url
                        first_bare_suno_field_path = str(current.get("field_path") or current.get("source") or "")
    raw_provider_payload = data.get("raw_provider_result_internal") or data.get("raw_provider_result")
    if provider_name == "key4u_suno" and isinstance(raw_provider_payload, (dict, list)):
        existing = {
            (str(item.get("field_path") or item.get("source") or ""), str(item.get("url") or ""))
            for item in candidates
            if isinstance(item, dict)
        }
        raw_candidates = music_provider_audio_candidate_records(
            extract_shopaikey_suno_audio_candidates(raw_provider_payload, provider_name="key4u_suno")
        )
        for item in raw_candidates:
            if not isinstance(item, dict):
                continue
            current = dict(item)
            marker = (str(current.get("field_path") or current.get("source") or ""), str(current.get("url") or ""))
            if marker in existing:
                continue
            existing.add(marker)
            if current.get("rejected"):
                rejected_reasons.extend(music_provider_rejected_candidate_reasons([current]))
                rejected_url = str(current.get("url") or "").strip()
                if not first_bare_suno_url and rejected_url and music_url_is_bare_suno_cdn(rejected_url):
                    first_bare_suno_url = rejected_url
                    first_bare_suno_field_path = str(current.get("field_path") or current.get("source") or "")
                continue
            if current.get("url") and not current.get("safe_label"):
                current["safe_label"] = music_result_url_debug_label(current.get("url") or "")
            candidates.append(current)
            current_url = str(current.get("url") or "").strip()
            if not first_bare_suno_url and current_url and music_url_is_bare_suno_cdn(current_url):
                first_bare_suno_url = current_url
                first_bare_suno_field_path = str(current.get("field_path") or current.get("source") or "")
    if provider_name == "key4u_suno":
        if not first_bare_suno_url:
            first_bare_suno_url = music_first_bare_suno_cdn_url(data.get("provider_result_candidates") or [])
        endpoint_candidate = music_key4u_suno_download_candidate(provider_task_id, raw_url=first_bare_suno_url)
        if endpoint_candidate:
            if first_bare_suno_field_path:
                endpoint_candidate["raw_result_field_path"] = first_bare_suno_field_path
            candidates.append(endpoint_candidate)
        elif first_bare_suno_url:
            candidates.append({
                "source": "bare_suno_cdn_requires_provider_download",
                "field_path": "bare_suno_cdn_requires_provider_download",
                "role": "provider_result_metadata",
                "url": first_bare_suno_url,
                "url_label": music_result_url_debug_label(first_bare_suno_url),
                "safe_label": music_result_url_debug_label(first_bare_suno_url),
                "provider_name": "key4u_suno",
                "rank": 10,
                "selected_reason": "provider_download_endpoint_required",
                "reject_reason": "bare_suno_cdn_no_query",
                "rejected_candidate_reason": "rejected_bare_suno_cdn_no_query",
                "rejected_candidates": rejected_reasons[-8:],
                "setup_required": KEY4U_SUNO_DOWNLOAD_SETUP_REQUIRED,
            })
    direct_payload = music_artifact_candidate_bytes(audio_bytes)
    if direct_payload:
        candidates.append({
            "source": "downloaded_validated_mp3",
            "role": "downloaded_validated",
            "audio_bytes": direct_payload,
            "url": data.get("music_output_url") or data.get("output_url") or data.get("result_url") or "",
            "artifact_id": data.get("music_artifact_id") or data.get("provider_artifact_id") or "",
            "duration_seconds": data.get("artifact_duration_seconds") or data.get("music_result_duration_seconds") or data.get("duration_seconds") or 0,
        })
    auto_payload = music_artifact_candidate_bytes(data.get("_auto_delivery_audio_bytes"))
    if auto_payload:
        candidates.append({
            "source": "auto_delivery_audio_bytes",
            "role": "downloaded_validated",
            "audio_bytes": auto_payload,
            "url": data.get("music_output_url") or data.get("output_url") or data.get("result_url") or "",
            "artifact_id": data.get("music_artifact_id") or data.get("provider_artifact_id") or "",
            "duration_seconds": data.get("artifact_duration_seconds") or data.get("music_result_duration_seconds") or data.get("duration_seconds") or 0,
        })
    url_seen: set[str] = set()
    for url_key in ("music_output_url", "output_url", "result_url", "download_url", "file_url", "audio_url", "music_result_url", "result_url_raw_encrypted_or_internal", "music_artifact_url", "selected_artifact_url"):
        url = str(data.get(url_key) or "").strip()
        if url and url not in url_seen:
            url_seen.add(url)
            query_meta = music_url_query_metadata(url)
            candidates.append({
                "source": url_key,
                "field_path": url_key,
                "role": "provider_result_metadata",
                "url": url,
                "url_label": music_result_url_debug_label(url),
                "safe_label": music_result_url_debug_label(url),
                "has_query": bool(query_meta.get("query_present")),
                "query_param_count": int(query_meta.get("query_param_count") or 0),
                "signature_param_present": bool(query_meta.get("signature_param_present")),
                "artifact_id": data.get("music_artifact_id") or data.get("provider_artifact_id") or "",
                "duration_seconds": data.get("artifact_duration_seconds") or data.get("music_result_duration_seconds") or data.get("duration_seconds") or 0,
                "provider_name": data.get("provider") or data.get("provider_name_internal") or "",
            })
    for path_key in ("local_artifact_path", "music_result_path", "output_path", "local_path", "storage_ref"):
        local_path = str(data.get(path_key) or "").strip()
        if local_path and os.path.exists(local_path) and os.path.getsize(local_path) > 0:
            candidates.append({
                "source": path_key,
                "role": "downloaded_validated",
                "local_path": local_path,
                "artifact_id": data.get("music_artifact_id") or data.get("provider_artifact_id") or "",
                "duration_seconds": data.get("artifact_duration_seconds") or data.get("music_result_duration_seconds") or data.get("duration_seconds") or 0,
            })
            break
    return candidates

def music_artifact_candidate_is_preview(candidate: dict | None = None) -> bool:
    item = dict(candidate or {})
    text = " ".join(str(item.get(key) or "") for key in ("role", "kind", "type", "source", "status", "name", "local_path", "url")).lower()
    return any(token in text for token in ("preview", "partial", "temp", "tmp", "sample"))

def music_artifact_candidate_is_direct_suno_audio(candidate: dict | None = None) -> bool:
    item = dict(candidate or {})
    if item.get("provider_download_endpoint_candidate"):
        return False
    url = str(item.get("url") or item.get("artifact_url") or item.get("output_url") or item.get("download_url") or "").strip()
    host, extension = music_url_host_extension(url)
    path = str(item.get("field_path") or item.get("source") or "").lower().replace(".", "_")
    if not (host == "suno.ai" or host.endswith(".suno.ai")):
        return False
    if extension not in SUNO_AUDIO_EXTENSIONS:
        return False
    return bool(
        music_url_is_bare_suno_cdn(url)
        or "cld2audiourl" in path
        or "music_output_url" in path
        or "output_url" in path
        or "result_url" in path
        or "audio_url" in path
    )

def music_artifact_candidate_priority(candidate: dict | None = None) -> int:
    item = dict(candidate or {})
    if music_artifact_candidate_is_preview(item):
        return -10000
    try:
        explicit_rank = int(item.get("rank") or 0)
    except Exception:
        explicit_rank = 0
    text = " ".join(str(item.get(key) or "") for key in ("role", "kind", "type", "source", "status")).lower()
    score = explicit_rank
    if music_artifact_candidate_is_direct_suno_audio(item):
        score += 2400
    if item.get("provider_download_endpoint_candidate"):
        score -= 250
    if any(token in text for token in ("final", "master", "full")):
        score += 1000
    if any(token in text for token in ("completed", "complete", "success", "downloaded_validated")):
        score += 500
    if item.get("provider_artifact_id") or item.get("artifact_id") or item.get("id"):
        score += 50
    if item.get("audio_bytes") or item.get("bytes"):
        score += 40
    if item.get("local_path"):
        score += 30
    if item.get("url") or item.get("artifact_url") or item.get("output_url"):
        score += 20
    try:
        score += min(10, int(item.get("duration_seconds") or item.get("duration") or 0) // 60)
    except Exception:
        pass
    return score

async def select_music_delivery_artifact(
    result: dict | None = None,
    job: dict | None = None,
    audio_bytes: bytes | bytearray | None = None,
) -> dict:
    candidates = music_delivery_artifact_candidates(result, job, audio_bytes)
    final_candidates = sorted(
        [dict(item) for item in candidates if music_artifact_candidate_priority(item) >= 0],
        key=music_artifact_candidate_priority,
        reverse=True,
    )
    if not final_candidates:
        return {
            "ok": False,
            "status": "FINAL_ARTIFACT_NOT_READY",
            "artifact_candidates_count": len(candidates),
        }
    last_failure: dict = {}
    rejected_reasons: list[str] = []
    direct_cdn_any_attempted = False
    direct_cdn_any_validation_passed = False
    direct_cdn_last_http_status = 0
    direct_cdn_last_content_type = ""
    direct_cdn_last_bytes = 0
    provider_auth_any_bypassed_for_direct_cdn = False
    direct_raw_attempted_urls = set()
    for candidate_order, selected in enumerate(final_candidates, start=1):
        payload = music_artifact_candidate_bytes(selected.get("audio_bytes") or selected.get("bytes"))
        local_path = str(selected.get("local_path") or selected.get("path") or "").strip()
        if not payload and local_path and os.path.exists(local_path) and os.path.getsize(local_path) > 0:
            try:
                with open(local_path, "rb") as handle:
                    payload = handle.read()
            except Exception:
                payload = b""
        url = str(selected.get("url") or selected.get("artifact_url") or selected.get("output_url") or selected.get("download_url") or "").strip()
        download_detail = ""
        download_status = 0
        download_content_type = ""
        download_error_category = ""
        downloaded_bytes = len(payload)
        download_strategy_used = ""
        provider_auth_header_used = False
        provider_proxy_attempted = False
        provider_download_endpoint_configured = False
        provider_download_endpoint_attempted = False
        provider_download_http_status = 0
        provider_download_content_type = ""
        provider_download_bytes = 0
        wav_endpoint_configured = False
        wav_request_http_status = 0
        wav_response_shape = ""
        wav_task_id_present = False
        provider_result_item_count = 0
        provider_result_item0_keys = ""
        provider_result_item1_keys = ""
        clip_id_candidates_found = 0
        selected_clip_id_source_path = ""
        selected_clip_id_present = False
        wav_request_clip_id_source = ""
        wav_request_used_provider_task_id_fallback = False
        clip_id_candidate_statuses = ""
        final_audio_download_status = ""
        wav_response_top_level_keys = ""
        wav_response_data_keys = ""
        wav_response_result_keys = ""
        wav_response_status = ""
        wav_response_message_safe = ""
        wav_json_audio_url_found = False
        wav_json_task_id_found = False
        wav_1102_treated_as_pending = False
        wav_json_audio_url_field_path = ""
        wav_json_task_id_field_path = ""
        wav_followup_attempted = False
        wav_followup_http_status = 0
        final_audio_content_type = ""
        final_audio_bytes = 0
        candidate_attempted = False
        candidate_field_path = str(selected.get("field_path") or selected.get("source") or "")
        candidate_host = urlparse(url).netloc if url else ""
        candidate_bare_url_allowed_for_validation = False
        candidate_http_status = 0
        candidate_content_type = ""
        candidate_bytes = 0
        candidate_validation_passed = False
        setup_required = ""
        provider_auth_bypassed_for_direct_cdn = False
        provider_auth_bypassed_for_direct_suno_cdn = False
        direct_cdn_download_attempted = False
        direct_cdn_download_http_status = 0
        direct_cdn_download_content_type = ""
        direct_cdn_download_bytes = 0
        direct_cdn_validation_passed = False
        if not payload and url:
            download_candidate = dict(selected)
            raw_result_url = str(download_candidate.get("raw_result_url") or "").strip()
            if raw_result_url and raw_result_url in direct_raw_attempted_urls:
                download_candidate["skip_raw_audio_prefetch"] = True
            downloaded = await music_download_artifact_candidate(download_candidate, {**dict(job or {}), **dict(result or {})}, timeout_seconds=60.0)
            payload = bytes(downloaded.get("audio_bytes") or b"")
