def media_asset_summary_line(kind: str, row: dict) -> str:
    if not row:
        return "-"
    label = normalize_media_asset_kind(kind) or "media"
    return (
        f"<code>{html.escape(str(row.get('asset_id') or row.get('id') or '-'))}</code> "
        f"| kind <code>{html.escape(label)}</code> "
        f"| user <code>{html.escape(str(row.get('user_id') or '-'))}</code> "
        f"| output <code>{html.escape(str(row.get('output_type') or '-'))}</code> "
        f"| status <code>{html.escape(str(row.get('status') or '-'))}</code> "
        f"| bytes <code>{int(row.get('output_bytes') or 0)}</code>"
    )

def media_asset_tables_ready() -> bool:
    try:
        with db_connect() as conn:
            rows = conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name IN ('subtitle_assets','translation_assets','dub_assets')"
            ).fetchall()
            return {str(row[0]) for row in rows} == set(MEDIA_ASSET_TABLES.values())
    except Exception:
        return False

def voice_profile_policy_label(lang: str = "vi") -> str:
    price = int(VOICE_PROFILE_PRICE_XU or 0)
    if VOICE_PROFILE_FIRST_FREE and int(VOICE_PROFILE_MAX_FREE_PER_USER or 0) > 0:
        if music_ui_lang(lang=lang) == "vi":
            return f"miễn phí lượt đầu, sau đó +{price} Xu/profile"
        return f"first profile free, then +{price} Xu/profile"
    return (f"+{price} Xu/profile" if music_ui_lang(lang=lang) != "vi" else f"+{price} Xu/profile")

def default_tts_voice_map() -> dict:
    female = str(DEFAULT_TTS_FEMALE_VOICE or MINIMAX_DEFAULT_FEMALE_VOICE_ID or "").strip()
    male = str(DEFAULT_TTS_MALE_VOICE or MINIMAX_DEFAULT_MALE_VOICE_ID or "").strip()
    neutral = str(MINIMAX_DEFAULT_VOICE_ID or male or female or "male-qn-qingse").strip()
    return {
        "female": female,
        "male": male,
        "neutral": neutral,
        "distinct": bool(female and male and female != male),
    }

def default_tts_voices_distinct() -> bool:
    return bool(default_tts_voice_map().get("distinct"))

def default_tts_voice_id(choice: str = "") -> str:
    value = str(choice or "").strip().lower()
    mapping = default_tts_voice_map()
    if "female" in value or "nữ" in value or "nu" in value:
        return str(mapping.get("female") or mapping.get("neutral") or "female-shaonv")
    if "male" in value or "nam" in value:
        return str(mapping.get("male") or mapping.get("neutral") or "male-qn-qingse")
    return str(mapping.get("neutral") or mapping.get("male") or mapping.get("female") or "male-qn-qingse")

def get_tts_voice_id(kind: str, profile: dict | None = None) -> str:
    normalized = str(kind or "").strip().lower()
    if normalized in {"default_female", "female", "nữ", "nu"}:
        return default_tts_voice_id("female")
    if normalized in {"default_male", "male", "nam"}:
        return default_tts_voice_id("male")
    if normalized in {"default_neutral", "neutral", "default"}:
        return default_tts_voice_id("neutral")
    if normalized in {"saved_voice", "saved", "voice_profile", "cloned_voice", "clone"}:
        return str((profile or {}).get("provider_voice_id") or "").strip()
    return str((profile or {}).get("provider_voice_id") or kind or "").strip()

def subdub_voice_not_ready_text(lang: str = "vi") -> str:
    if normalize_user_language(lang) != "vi":
        return "TOAN AAS could not create the selected dubbing voice. No Xu was charged. Please choose another voice or try again."
    return "TOAN AAS chưa tạo được giọng lồng tiếng đã chọn. Hệ thống chưa trừ Xu. Anh/chị vui lòng chọn giọng khác hoặc thử lại."

def subdub_voice_text_normalized(value: str = "") -> str:
    text = str(value or "").strip().lower()
    return "".join(
        char for char in unicodedata.normalize("NFD", text)
        if unicodedata.category(char) != "Mn"
    )

def subdub_voice_gender_from_state(state: dict | None = None) -> str:
    state = dict(state or {})
    values = [
        state.get("selected_voice_gender"),
        state.get("requested_voice_gender"),
        state.get("dub_voice_gender"),
        state.get("tts_voice_gender"),
        state.get("voice_gender"),
        state.get("gender"),
        state.get("selected_voice_kind"),
        state.get("voice_kind"),
        state.get("voice_choice"),
        state.get("selected_voice"),
        state.get("voice_style"),
        state.get("selected_voice_label"),
        state.get("voice_label"),
    ]
    text = subdub_voice_text_normalized(" ".join(str(item or "") for item in values))
    if "default_female" in text or "female" in text or "giong nu" in text or re.search(r"\bnu\b", text):
        return "female"
    if "default_male" in text or re.search(r"\bmale\b", text) or "giong nam" in text or re.search(r"\bnam\b", text):
        return "male"
    return ""

def subdub_voice_id_gender_hint(voice_id: str = "") -> str:
    text = subdub_voice_text_normalized(voice_id)
    if "female" in text or "shaonv" in text or "woman" in text or "girl" in text or re.search(r"\bnu\b", text):
        return "female"
    if "male" in text and "female" not in text:
        return "male"
    if "qingse" in text or re.search(r"\bnam\b", text):
        return "male"
    return ""

def subdub_voice_gender_conflict(voice_id: str = "", gender: str = "") -> bool:
    gender = str(gender or "").strip().lower()
    if gender not in {"female", "male"}:
        return False
    selected = str(voice_id or "").strip().lower()
    if not selected:
        return True
    opposite_default = default_tts_voice_id("male" if gender == "female" else "female").strip().lower()
    if opposite_default and selected == opposite_default:
        return True
    hint = subdub_voice_id_gender_hint(selected)
    return bool(hint and hint != gender)

def subdub_default_tts_voice_for_gender(gender: str = "") -> str:
    safe_gender = str(gender or "").strip().lower()
    mapping = default_tts_voice_map()
    if safe_gender == "female":
        return str(mapping.get("female") or "").strip()
    if safe_gender == "male":
        return str(mapping.get("male") or "").strip()
    return str(mapping.get("neutral") or "").strip()

def subdub_default_voice_config_payload() -> dict:
    female = str(subdub_default_tts_voice_for_gender("female") or "").strip()
    male = str(subdub_default_tts_voice_for_gender("male") or "").strip()
    female_valid = bool(
        female
        and minimax_voice_adapter.validate_provider_voice_id(female)
        and not subdub_voice_gender_conflict(female, "female")
    )
    male_valid = bool(
        male
        and minimax_voice_adapter.validate_provider_voice_id(male)
        and not subdub_voice_gender_conflict(male, "male")
    )
    payload = {
        "default_female_voice_id_present": bool(female),
        "default_male_voice_id_present": bool(male),
        "default_female_configured": female_valid,
        "default_male_configured": male_valid,
        "default_voices_distinct": bool(female and male and female != male),
        "voice_config_source": "subdub_runtime_default_voice_config",
    }
    payload["voice_config_blocker"] = "" if (
        payload["default_female_configured"]
        and payload["default_male_configured"]
        and payload["default_voices_distinct"]
    ) else "subdub_default_voice_config_missing"
    return payload


def subdub_voice_resolution_payload(
    *,
    ok: bool,
    selected_voice_label: str = "",
    selected_voice_gender: str = "",
    requested_voice_gender: str = "",
    selected_voice_id: str = "",
    provider_voice_id: str = "",
    voice_provider: str = "",
    tts_payload_voice_id: str = "",
    resolved_voice_id: str = "",
    resolved_gender: str = "",
    auto_detected_gender: str = "",
    confidence: float = 0.0,
    blocker: str = "",
    fallback_used: bool = False,
    fallback_reason: str = "",
    reason: str = "",
) -> dict:
    selected_gender = str(selected_voice_gender or "").strip().lower()
    requested_gender = str(requested_voice_gender or selected_gender or "").strip().lower()
    provider_id = str(provider_voice_id or "").strip()
    resolved_id = str(resolved_voice_id or provider_id).strip()
    resolved_gender_value = str(resolved_gender or selected_gender or subdub_voice_id_gender_hint(resolved_id)).strip().lower()
    auto_gender = str(auto_detected_gender or ("" if selected_gender else resolved_gender_value)).strip().lower()
    try:
        safe_confidence = float(confidence or (1.0 if selected_gender in {"female", "male"} else 0.0))
    except Exception:
        safe_confidence = 0.0
    return {
        "ok": bool(ok),
        "selected_voice_label": str(selected_voice_label or "")[:160],
        "selected_voice_gender": selected_gender[:40],
        "requested_voice_gender": requested_gender[:40],
        "selected_voice_id": str(selected_voice_id or "")[:180],
        "provider_voice_id": provider_id[:180],
        "voice_provider": str(voice_provider or TTS_PROVIDER or "tts")[:80],
        "tts_payload_voice_id": str(tts_payload_voice_id or provider_id or "")[:180],
        "resolved_voice_id": resolved_id[:180],
        "resolved_gender": resolved_gender_value[:40],
        "auto_detected_gender": auto_gender[:40],
        "confidence": max(0.0, min(1.0, safe_confidence)),
        "blocker": str(blocker or reason or "")[:180],
        "fallback_used": bool(fallback_used),
        "fallback_reason": str(fallback_reason or "")[:180],
        "reason": str(reason or "")[:180],
    }

def subdub_apply_voice_resolution_to_state(state: dict | None, resolution: dict) -> None:
    if not isinstance(state, dict):
        return
    state["_subdub_voice_resolution"] = dict(resolution or {})
    state["selected_voice_label"] = str(resolution.get("selected_voice_label") or state.get("voice_style") or "")[:160]
    state["selected_voice_gender"] = str(resolution.get("selected_voice_gender") or "")[:40]
    state["requested_voice_gender"] = str(resolution.get("requested_voice_gender") or resolution.get("selected_voice_gender") or "")[:40]
    state["selected_voice_id"] = str(resolution.get("selected_voice_id") or state.get("voice_id") or "")[:180]
    state["provider_voice_id"] = str(resolution.get("provider_voice_id") or "")[:180]
    state["voice_provider"] = str(resolution.get("voice_provider") or state.get("voice_provider") or TTS_PROVIDER or "")[:80]
    state["tts_payload_voice_id"] = str(resolution.get("tts_payload_voice_id") or "")[:180]
    state["resolved_voice_id"] = str(resolution.get("resolved_voice_id") or resolution.get("provider_voice_id") or "")[:180]
    state["resolved_gender"] = str(resolution.get("resolved_gender") or "")[:40]
    state["auto_detected_gender"] = str(resolution.get("auto_detected_gender") or "")[:40]
    state["voice_confidence"] = str(resolution.get("confidence") or "")[:20]
    state["voice_fallback_used"] = bool(resolution.get("fallback_used"))
    state["voice_fallback_reason"] = str(resolution.get("fallback_reason") or resolution.get("reason") or "")[:180]
    if resolution.get("ok"):
        state["selected_tts_voice_id"] = str(resolution.get("provider_voice_id") or "")[:180]

def resolve_video_dub_tts_voice(state_user_id, state: dict | None = None) -> dict:
    state = state if isinstance(state, dict) else dict(state or {})
    requested = str(
        state.get("voice_id")
        or state.get("selected_voice_id")
        or state.get("provider_voice_id")
        or state.get("tts_voice_id")
        or state.get("selected_tts_voice_id")
        or ""
    ).strip()
    kind = subdub_voice_text_normalized(str(state.get("voice_kind") or state.get("selected_voice_kind") or ""))
    label = str(state.get("voice_style") or state.get("selected_voice_label") or state.get("voice_label") or "").strip()
    gender = subdub_voice_gender_from_state(state)
    profile_id = _safe_int(state.get("voice_profile_id") or state.get("selected_voice_profile_id"), 0)
    provider_voice_id = ""
    reason = ""
    fallback_used = False
    fallback_reason = ""
    custom_kind = kind in {"saved_voice", "saved", "voice_profile", "cloned_voice", "clone", "custom_clone", "custom_prompt", "custom"}

    if profile_id and not requested:
        profile = get_user_voice_profile(state_user_id, profile_id)
        requested = str((profile or {}).get("provider_voice_id") or "").strip()
        label = label or str((profile or {}).get("display_name") or "")
        custom_kind = True
    exact_requested = bool(
        requested
        and requested.lower() not in {"saved_voice", "saved", "voice_profile", "cloned_voice", "clone"}
        and minimax_voice_adapter.validate_provider_voice_id(requested)
    )
    default_gender_requested = bool(
        not custom_kind
        and gender in {"female", "male"}
        and (
            kind in {"default_female", "female", "default_male", "male", "nu", "nam", "nu tu nhien", "nam tu nhien"}
            or not exact_requested
            or subdub_voice_gender_conflict(requested, gender)
        )
    )
    if default_gender_requested:
        candidate = subdub_default_tts_voice_for_gender(gender)
        if candidate and minimax_voice_adapter.validate_provider_voice_id(candidate) and not subdub_voice_gender_conflict(candidate, gender):
            resolution = subdub_voice_resolution_payload(
                ok=True,
                selected_voice_label=label,
                selected_voice_gender=gender,
                requested_voice_gender=gender,
                selected_voice_id=requested or f"default_{gender}",
                provider_voice_id=candidate,
                voice_provider=TTS_PROVIDER or "tts",
                tts_payload_voice_id=candidate,
                resolved_gender=gender,
                confidence=1.0,
                fallback_used=False,
                fallback_reason="",
            )
            subdub_apply_voice_resolution_to_state(state, resolution)
            return resolution
    if exact_requested and not custom_kind:
        provider_voice_id = requested
        if gender in {"female", "male"} and subdub_voice_gender_conflict(provider_voice_id, gender):
            candidate = subdub_default_tts_voice_for_gender(gender)
            if candidate and minimax_voice_adapter.validate_provider_voice_id(candidate) and not subdub_voice_gender_conflict(candidate, gender):
                provider_voice_id = candidate
                fallback_used = True
                fallback_reason = "corrected_stale_voice_gender"
            else:
                reason = "selected_voice_gender_unavailable"
                resolution = subdub_voice_resolution_payload(
                    ok=False,
                    selected_voice_label=label,
                    selected_voice_gender=gender,
                    requested_voice_gender=gender,
                    selected_voice_id=requested,
                    provider_voice_id=requested,
                    voice_provider=TTS_PROVIDER or "tts",
                    fallback_used=False,
                    fallback_reason=reason,
                    reason=reason,
                )
                subdub_apply_voice_resolution_to_state(state, resolution)
                return resolution
        hint = subdub_voice_id_gender_hint(provider_voice_id)
        resolution = subdub_voice_resolution_payload(
            ok=True,
            selected_voice_label=label,
            selected_voice_gender=gender,
            requested_voice_gender=gender,
            selected_voice_id=requested,
            provider_voice_id=provider_voice_id,
            voice_provider=TTS_PROVIDER or "tts",
            tts_payload_voice_id=provider_voice_id,
            resolved_gender=hint or gender,
            confidence=1.0 if (hint or gender) else 0.0,
            fallback_used=fallback_used,
            fallback_reason=fallback_reason,
        )
        subdub_apply_voice_resolution_to_state(state, resolution)
        return resolution
    if custom_kind:
        if minimax_voice_adapter.validate_provider_voice_id(requested):
            provider_voice_id = requested
        else:
            reason = "missing_provider_voice_id"
    elif gender == "female" or kind in {"default_female", "female", "nu", "nu tu nhien"}:
        provider_voice_id = subdub_default_tts_voice_for_gender("female")
        kind = "default_female"
        gender = "female"
    elif gender == "male" or kind in {"default_male", "male", "nam", "nam tu nhien"}:
        provider_voice_id = subdub_default_tts_voice_for_gender("male")
        kind = "default_male"
        gender = "male"
    elif requested and requested.lower() not in {"saved_voice", "saved", "voice_profile", "cloned_voice", "clone"}:
        provider_voice_id = get_tts_voice_id(requested)
    else:
        provider_voice_id = get_tts_voice_id("default_female")
        kind = "default_female"
        gender = "female"

    if not provider_voice_id or not minimax_voice_adapter.validate_provider_voice_id(provider_voice_id):
        reason = reason or "missing_provider_voice_id"
        resolution = subdub_voice_resolution_payload(
            ok=False,
            selected_voice_label=label,
            selected_voice_gender=gender,
            requested_voice_gender=gender,
            selected_voice_id=requested,
            reason=reason,
        )
        subdub_apply_voice_resolution_to_state(state, resolution)
        return resolution

    if subdub_voice_gender_conflict(provider_voice_id, gender):
        reason = "selected_voice_gender_unavailable"
        if SUBDUB_ALLOW_SILENT_VOICE_FALLBACK:
            candidate = subdub_default_tts_voice_for_gender(gender)
            if candidate and minimax_voice_adapter.validate_provider_voice_id(candidate) and not subdub_voice_gender_conflict(candidate, gender):
                fallback_used = True
                fallback_reason = reason
                provider_voice_id = candidate
                reason = ""
        if reason:
            resolution = subdub_voice_resolution_payload(
                ok=False,
                selected_voice_label=label,
                selected_voice_gender=gender,
                requested_voice_gender=gender,
                selected_voice_id=requested,
                provider_voice_id=provider_voice_id,
                voice_provider=TTS_PROVIDER or "tts",
                fallback_used=False,
                fallback_reason=reason,
                reason=reason,
            )
            subdub_apply_voice_resolution_to_state(state, resolution)
            return resolution

    resolution = subdub_voice_resolution_payload(
        ok=True,
        selected_voice_label=label,
        selected_voice_gender=gender,
        requested_voice_gender=gender,
        selected_voice_id=requested or kind,
        provider_voice_id=provider_voice_id,
        voice_provider=TTS_PROVIDER or "tts",
        tts_payload_voice_id=provider_voice_id,
        fallback_used=fallback_used,
        fallback_reason=fallback_reason,
    )
    subdub_apply_voice_resolution_to_state(state, resolution)
    return resolution

def resolve_video_dub_tts_voice_id(user_id, state: dict | None = None) -> str:
    resolution = resolve_video_dub_tts_voice(user_id, state)
    return str(resolution.get("provider_voice_id") or "") if resolution.get("ok") else ""

def default_edge_tts_voice_id(kind: str) -> str:
    normalized = str(kind or "").strip().lower()
    if normalized in {"default_female", "female", "nữ", "nu"}:
        return "vi-VN-HoaiMyNeural"
    return "vi-VN-NamMinhNeural"

def default_tts_single_voice_notice(lang: str = "vi") -> str:
    return f"⚠️ {_audio_copy(lang, 'guard')} {_audio_label(lang, 'voice_default')}"

VOICE_PROFILE_FINAL_READY_STATUSES = {"active", "ready", "saved"}
VOICE_PROFILE_PREVIEW_STATUSES = VOICE_PROFILE_FINAL_READY_STATUSES | {"preview_ready"}

def voice_profile_can_generate_tts(profile: dict | None) -> bool:
    profile = dict(profile or {})
    status = str(profile.get("status") or "").strip().lower()
    provider_voice_id = minimax_voice_adapter.normalize_voice_id(profile.get("provider_voice_id"))
    return bool(
        status in VOICE_PROFILE_FINAL_READY_STATUSES
        and minimax_voice_adapter.validate_provider_voice_id(provider_voice_id)
        and str(profile.get("id") or "").strip() != provider_voice_id
    )

def voice_profile_can_preview(profile: dict | None) -> bool:
    profile = dict(profile or {})
    status = str(profile.get("status") or "").strip().lower()
    return bool(status in VOICE_PROFILE_PREVIEW_STATUSES and (profile.get("preview_audio_ref") or profile.get("provider_voice_id")))

def voice_profile_clone_permission_forbidden(profile: dict | None) -> bool:
    profile = dict(profile or {})
    status = str(profile.get("status") or "").strip().lower()
    metadata = voice_profile_metadata(profile)
    marker = " ".join([
        status,
        str(metadata.get("activation_status") or ""),
        str(metadata.get("activation_admin_error") or ""),
    ]).lower()
    return bool(status in VOICE_CLONE_PERMISSION_FORBIDDEN_PROFILE_STATUSES or "clone_permission_forbidden" in marker)

def voice_profile_not_ready_text(profile: dict | None = None, lang: str = "vi") -> str:
    name = str((profile or {}).get("display_name") or _audio_label(lang, "voice"))
    status = str((profile or {}).get("status") or "-")
    if voice_profile_clone_permission_forbidden(profile):
        return "⚠️ " + voice_clone_permission_forbidden_public_text(lang) + (
            f"\n\n{_audio_label(lang, 'voice')}: <b>{html.escape(name)}</b>\n{_audio_label(lang, 'status')}: <b>{html.escape(status)}</b>"
        )
    return f"⚠️ {_audio_copy(lang, 'guard')}\n\n{_audio_label(lang, 'voice')}: <b>{html.escape(name)}</b>\n{_audio_label(lang, 'status')}: <b>{html.escape(status)}</b>"

def estimate_voice_duration_seconds(text: str, speed: str = "normal") -> int:
    clean = re.sub(r"\s+", " ", str(text or "")).strip()
    if not clean:
        return 0
    words = len(clean.split())
    words_per_second = {
        "slow": 2.35,
        "normal": 2.85,
        "fast": 3.35,
    }.get(str(speed or "normal").strip().lower(), 2.85)
    return max(1, int(math.ceil(words / words_per_second)))

def voice_tts_billable_chars(text: str) -> int:
    return len(re.sub(r"\s+", " ", str(text or "")).strip())

def custom_voice_usage_billable_chars(text: str) -> int:
    return voice_tts_billable_chars(text)

def custom_voice_usage_price_breakdown(text: str) -> dict:
    chars = custom_voice_usage_billable_chars(text)
    rate = float(canonical_price_xu("voice_clone_custom") or CUSTOM_VOICE_USAGE_PRICE_PER_CHAR_XU or 0.0)
    if chars <= 0:
        return {
            "chars": 0,
            "rate_xu": rate,
            "raw_xu": 0.0,
            "discount_percent": 0,
            "discount_xu": 0.0,
            "discount_cap_percent": int(VOLUME_DISCOUNT_CAP_PERCENT),
            "total_xu": 0,
        }
    raw = chars * rate
    discount_percent = finance_volume_discount_percent(chars)
    discount_xu = raw * discount_percent / 100.0
    total = int(math.ceil(raw - discount_xu))
    return {
        "chars": chars,
        "rate_xu": rate,
        "raw_xu": raw,
        "discount_percent": finance_discount_cap_percent(discount_percent),
        "discount_xu": discount_xu,
        "discount_cap_percent": int(VOLUME_DISCOUNT_CAP_PERCENT),
        "total_xu": total,
    }

def custom_voice_usage_price_xu(text: str) -> int:
    return int(custom_voice_usage_price_breakdown(text).get("total_xu") or 0)

def custom_voice_usage_text_too_short(text: str) -> bool:
    return custom_voice_usage_billable_chars(text) <= int(CUSTOM_VOICE_USAGE_MIN_CHARS or 10)

def custom_voice_usage_duration_seconds(text: str, speed: str = "normal") -> int:
    return estimate_voice_duration_seconds(text, speed)

def custom_voice_usage_output_too_short(text: str, speed: str = "normal", audio_bytes: bytes | bytearray | None = None) -> bool:
    if not audio_bytes:
        return True
    return custom_voice_usage_duration_seconds(text, speed) <= int(CUSTOM_VOICE_USAGE_MIN_DURATION_SECONDS or 3)

def voice_tts_credit_estimate(text: str) -> dict:
    chars = voice_tts_billable_chars(text)
    if chars <= 0:
        return {"chars": 0, "billable_blocks": 0, "base_chars": int(VOICE_TTS_BASE_CHARS or 1000), "price_xu": 0}
    base_chars = max(1, int(VOICE_TTS_BASE_CHARS or 1000))
    extra_chars = max(0, chars - base_chars)
    extra_blocks = int(math.ceil(extra_chars / 1000.0)) if extra_chars else 0
    price = int(VOICE_TTS_BASE_PRICE_XU or 0) + extra_blocks * int(VOICE_TTS_EXTRA_1000_CHARS_PRICE_XU or 0)
    return {
        "chars": chars,
        "billable_blocks": 1 + extra_blocks,
        "base_chars": base_chars,
        "extra_blocks": extra_blocks,
        "price_xu": max(0, int(price or 0)),
    }

def tts_full_price_xu(text: str, speed: str = "normal") -> int:
    return int(voice_tts_credit_estimate(text).get("price_xu") or 0)

def voice_vault_page_size(limit: int = 5) -> int:
    return max(1, min(20, int(limit or 5)))

def voice_profile_display_code(page: int = 0, index_on_page: int = 0, page_size: int = 5) -> int:
    return max(1, int(page or 0) * voice_vault_page_size(page_size) + int(index_on_page or 0) + 1)

def user_voice_profile_by_display_code(user_id, display_code: int, page_size: int = 5) -> dict | None:
    raw_code = _safe_int(display_code, 0)
    if raw_code < 1 or raw_code > 999:
        return None
    code = raw_code
    rows = user_voice_profile_rows(user_id, 1, code - 1)
    return dict(rows[0]) if rows else None

def voice_profile_status_label(status: str, lang: str = "vi") -> str:
    value = str(status or "").strip().lower()
    if value in VOICE_PROFILE_FINAL_READY_STATUSES:
        return _audio_copy(lang, "ready")
    if value in {"failed_provider_not_ready", "waiting_provider", "waiting_admin_smoke"}:
        return _audio_copy(lang, "preparing")
    if value.startswith("failed") or value in {"error", "rejected"}:
        return _audio_copy(lang, "failed")
    if value in {"pending_confirm", "pending_name", "processing", "preview_generating"}:
        return _audio_copy(lang, "waiting")
    return value or _audio_copy(lang, "draft")

def user_voice_profiles_summary(user_id, lang: str = "vi", limit: int = 5, product_context: str = PRODUCT_CONTEXT_SHOWROOM, page: int = 0) -> str:
    ctx = normalize_product_context(product_context)
    rows = []
    total = user_voice_profile_count(user_id)
    page = max(0, int(page or 0))
    page_size = voice_vault_page_size(limit)
    offset = page * page_size
    try:
        with db_connect() as conn:
            cur = conn.cursor()
            cur.execute(
                """
                SELECT id, display_name, consent_status, status, created_at, is_default
                FROM voice_profiles
                WHERE user_id=? AND deleted_at IS NULL AND status NOT IN ('deleted')
                ORDER BY is_default DESC, id DESC
                LIMIT ? OFFSET ?
                """,
                (str(user_id), page_size, offset),
            )
            rows = cur.fetchall()
    except Exception as exc:
        logger.warning("user_voice_profiles_summary failed | %s", sanitize_log_text(str(exc))[:220])
    if not rows:
        return f"📁 <b>{_audio_copy(lang, 'saved_voices')}</b>\n\n{_audio_copy(lang, 'no_saved_voice')} {_audio_copy(lang, 'no_charge')}"
    lines = [f"📁 <b>{_audio_copy(lang, 'saved_voices')}</b>", f"{_audio_copy(lang, 'page')} <b>{page + 1}</b> / <b>{max(1, int(math.ceil(max(1, total) / page_size)))}</b>", ""]
    for index_on_page, row in enumerate(rows):
        profile_id, name, consent, status, created, is_default = row
        default_text = f" — ⭐ {_audio_copy(lang, 'default_name')}" if int(is_default or 0) else ""
        display_code = voice_profile_display_code(page, index_on_page, page_size)
        status_label = voice_profile_status_label(str(status or ""), lang)
        lines.append(f"• <b>{display_code}</b>. <code>#{profile_id}</code> {html.escape(str(name or _audio_copy(lang, 'unnamed')))} — {html.escape(status_label)}{default_text}")
    lines.append("")
    if ctx == PRODUCT_CONTEXT_VIDEO_ADDON:
        lines.append(f"{_audio_label(lang, 'choose')}: 1–999 · {_audio_label(lang, 'use_for_video')}")
    else:
        lines.append(f"{_audio_label(lang, 'choose')}: 1–999 · {_audio_copy(lang, 'preview')} / {_audio_label(lang, 'create_audio')} / {_audio_copy(lang, 'download')}")
    return "\n".join(lines)

def voice_vault_keyboard(user_id, lang: str = "vi", product_context: str = PRODUCT_CONTEXT_SHOWROOM, page: int = 0) -> InlineKeyboardMarkup:
    ctx = normalize_product_context(product_context)
    cb = lambda action: product_context_callback("music_quick", ctx, action)
    buttons = []
    page = max(0, int(page or 0))
    page_size = voice_vault_page_size(5)
    total = user_voice_profile_count(user_id)
    profiles = user_voice_profile_rows(user_id, page_size, page * page_size)
    for index_on_page, profile in enumerate(profiles):
        display_code = voice_profile_display_code(page, index_on_page, page_size)
        marker = f"{display_code}"
        buttons.append((marker, cb(f"voice_profile_select_code:{display_code}")))
    nav_buttons = []
    if page > 0:
        nav_buttons.append((f"⬅️ {_audio_copy(lang, 'previous')}", cb(f"voice_profiles_page:{page - 1}")))
    if (page + 1) * page_size < total:
        nav_buttons.append((f"➡️ {_audio_copy(lang, 'next')}", cb(f"voice_profiles_page:{page + 1}")))
    buttons.extend(nav_buttons)
    if ctx == PRODUCT_CONTEXT_VIDEO_ADDON:
        if default_tts_voices_distinct():
            buttons.extend([
                (f"👩 {_audio_label(lang, 'voice_female')} - {_audio_copy(lang, 'free')}", "vfinal|voice_default|female"),
                (f"👨 {_audio_label(lang, 'voice_male')} - {_audio_copy(lang, 'free')}", "vfinal|voice_default|male"),
            ])
        else:
            buttons.append((f"🎙 {_audio_label(lang, 'voice_default')} - {_audio_copy(lang, 'free')}", "vfinal|voice_default|neutral"))
        return build_2col_keyboard(buttons, nav_back=(f"⬅️ {_audio_label(lang, 'back_video')}", "vfinal|voice"), nav_main=True, lang=lang)
    if default_tts_voices_distinct():
        buttons.extend([
            (f"👨 {_audio_label(lang, 'voice_male')}", cb("voice_default_male")),
            (f"👩 {_audio_label(lang, 'voice_female')}", cb("voice_default_female")),
        ])
    else:
        buttons.append((f"🎙 {_audio_label(lang, 'voice_default')}", cb("voice_default_neutral")))
    buttons.extend([
        (f"🧬 {_audio_label(lang, 'voice_custom')}", cb("voice_clone")),
    ])
    return build_2col_keyboard(buttons, nav_back=(f"⬅️ {_audio_label(lang, 'voice')}", cb("voice_hub")), nav_main=True, lang=lang)

def voice_profile_actions_keyboard(profile_id: int, lang: str = "vi", product_context: str = PRODUCT_CONTEXT_SHOWROOM, profile: dict | None = None) -> InlineKeyboardMarkup:
    pid = int(profile_id or 0)
    ctx = normalize_product_context(product_context)
    cb = lambda action: product_context_callback("music_quick", ctx, action)
    final_ready = True if profile is None else voice_profile_can_generate_tts(profile)
    preview_ready = True if profile is None else voice_profile_can_preview(profile)
    has_demo = bool((profile or {}).get("preview_audio_ref"))
    profile_status = str((profile or {}).get("status") or "").strip().lower()
    if profile_status in {"error", "rejected", "deleted"}:
        final_ready = False
        preview_ready = False
    if not final_ready:
        return InlineKeyboardMarkup([
            [
                InlineKeyboardButton(f"🔁 {_audio_label(lang, 'retry')}", callback_data=cb(f"voice_clone_retry:{pid}")),
                InlineKeyboardButton(f"✏️ {_audio_copy(lang, 'rename')}", callback_data=cb(f"voice_profile_rename:{pid}")),
            ],
            [
                InlineKeyboardButton(f"🗑 {_audio_copy(lang, 'delete')}", callback_data=cb(f"voice_profile_delete:{pid}")),
                InlineKeyboardButton(f"⬅️ {_audio_label(lang, 'voice_vault')}", callback_data=cb("voice_profiles")),
            ],
            [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
        ])
    video_callback = cb(f"voice_profile_use:{pid}") if ctx == PRODUCT_CONTEXT_VIDEO_ADDON else cb(f"voice_profile_video_hint:{pid}")
    buttons = [
        (f"▶️ {_audio_copy(lang, 'preview')}", cb(f"voice_profile_listen:{pid}")),
        (f"🎧 {_audio_label(lang, 'create_audio')}", cb(f"voice_profile_read:{pid}")),
        (f"⭐ {_audio_copy(lang, 'set_default')}", cb(f"voice_profile_default:{pid}")),
        (f"🎬 {_audio_copy(lang, 'use_for_video')}", video_callback),
    ]
    if has_demo:
        buttons.append((f"⬇️ {_audio_copy(lang, 'download')}", cb(f"voice_profile_download:{pid}")))
    buttons.extend([
        (f"✏️ {_audio_copy(lang, 'rename')}", cb(f"voice_profile_rename:{pid}")),
        (f"🗑 {_audio_copy(lang, 'delete')}", cb(f"voice_profile_delete:{pid}")),
    ])
    return build_2col_keyboard(buttons, nav_back=(f"⬅️ {_audio_label(lang, 'voice_vault')}", cb("voice_profiles")), nav_main=ctx == PRODUCT_CONTEXT_VIDEO_ADDON, lang=lang)

