def voice_profile_metadata(profile: dict) -> dict:
    try:
        value = json.loads(str((profile or {}).get("metadata_json") or "{}"))
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def capped_voice_preview_text(text: str) -> str:
    clean = re.sub(r"\s+", " ", str(text or "")).strip()
    if not clean:
        clean = str(VOICE_PROFILE_PREVIEW_TEXT or "Xin chào từ TOAN AAS.").strip()
    sentences = [part.strip() for part in re.split(r"(?<=[.!?])\s+", clean) if part.strip()]
    candidate = " ".join(sentences[:2]) if sentences else clean
    words = candidate.split()
    if len(words) > VOICE_PREVIEW_MAX_WORDS:
        candidate = " ".join(words[:VOICE_PREVIEW_MAX_WORDS])
    candidate = candidate[:VOICE_PREVIEW_MAX_CHARACTERS].rstrip()
    return candidate or "Xin chào từ TOAN AAS."


def voice_preview_idempotency_key(user_id, profile: dict, preview_text: str, preview_mode: str = "clone_preview") -> str:
    source_ref = str((profile or {}).get("source_file_id") or (profile or {}).get("source_file_ref") or "")
    raw = "|".join([
        str(user_id),
        str((profile or {}).get("id") or ""),
        source_ref,
        capped_voice_preview_text(preview_text),
        str(preview_mode or "clone_preview"),
    ])
    return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest()


def voice_preview_usage_snapshot(user_id, now: datetime | None = None) -> dict:
    now = now or datetime.now()
    day_key = now.strftime("%Y-%m-%d")
    attempts = 0
    latest_at = None
    available = True
    try:
        with db_connect() as conn:
            rows = conn.execute(
                "SELECT metadata_json FROM voice_profiles WHERE user_id=?",
                (str(user_id),),
            ).fetchall()
        for row in rows:
            try:
                metadata = json.loads(str(row[0] or "{}"))
            except Exception:
                metadata = {}
            if str(metadata.get("preview_attempt_day") or "") == day_key:
                attempts += max(0, int(metadata.get("preview_attempts_today") or 0))
            attempted_at = parse_now_text(str(metadata.get("preview_attempt_at") or ""))
            if attempted_at and (latest_at is None or attempted_at > latest_at):
                latest_at = attempted_at
    except Exception as exc:
        available = False
        logger.warning("voice preview usage read failed | %s", sanitize_log_text(str(exc))[:180])
    return {"day": day_key, "attempts": attempts, "latest_at": latest_at, "available": available}


def voice_preview_guard(user_id, profile_id: int, preview_text: str, preview_mode: str = "clone_preview", now: datetime | None = None, bypass_limits: bool = False) -> dict:
    now = now or datetime.now()
    profile = get_user_voice_profile(user_id, profile_id)
    if not profile or str(profile.get("consent_status") or "") != "confirmed":
        return {"ok": False, "reason": "invalid", "profile": profile}
    capped_text = capped_voice_preview_text(preview_text)
    preview_key = voice_preview_idempotency_key(user_id, profile, capped_text, preview_mode)
    metadata = voice_profile_metadata(profile)
    cached_ref = str(profile.get("preview_audio_ref") or "")
    if cached_ref and str(metadata.get("preview_key") or "") == preview_key:
        return {
            "ok": True,
            "cached": True,
            "profile": profile,
            "metadata": metadata,
            "preview_key": preview_key,
            "preview_text": capped_text,
            "preview_audio_ref": cached_ref,
        }
    stale_inflight = False
    if str(profile.get("status") or "") in {"preview_generating", "processing"}:
        attempted_at = parse_now_text(str(metadata.get("preview_attempt_at") or ""))
        stale_after = max(300, int(VOICE_PREVIEW_COOLDOWN_SECONDS or 0) * 4)
        if not attempted_at or (now - attempted_at).total_seconds() < stale_after:
            return {"ok": False, "reason": "inflight", "profile": profile, "metadata": metadata}
        stale_inflight = True
    usage = {"bypassed": True} if bypass_limits else voice_preview_usage_snapshot(user_id, now)
    if not bypass_limits:
        if not usage.get("available", True):
            return {"ok": False, "reason": "usage_unavailable", "profile": profile, "metadata": metadata}
        if int(usage.get("attempts") or 0) >= int(VOICE_PREVIEW_FREE_PER_DAY or 0):
            return {"ok": False, "reason": "quota", "profile": profile, "metadata": metadata, "usage": usage}
        latest_at = usage.get("latest_at")
        if latest_at and VOICE_PREVIEW_COOLDOWN_SECONDS > 0:
            elapsed = max(0, int((now - latest_at).total_seconds()))
            if elapsed < VOICE_PREVIEW_COOLDOWN_SECONDS:
                return {
                    "ok": False,
                    "reason": "cooldown",
                    "retry_after": VOICE_PREVIEW_COOLDOWN_SECONDS - elapsed,
                    "profile": profile,
                    "metadata": metadata,
                    "usage": usage,
                }
    if not frame_video_ffmpeg_path():
        return {"ok": False, "reason": "preview_cap_unavailable", "profile": profile, "metadata": metadata}
    return {
        "ok": True,
        "cached": False,
        "profile": profile,
        "metadata": metadata,
        "preview_key": preview_key,
        "preview_text": capped_text,
        "usage": usage,
        "stale_inflight": stale_inflight,
    }


def voice_preview_guard_message(reason: str, retry_after: int = 0) -> str:
    if reason == "inflight":
        return "TOAN AAS đang tạo bản nghe thử, bạn chờ một chút nhé."
    if reason == "cooldown":
        return f"Bạn chờ khoảng {max(1, int(retry_after or 1))} giây rồi nghe thử lại nhé. TOAN AAS chưa trừ Xu final."
    if reason == "quota":
        return "Bạn đã hết lượt nghe thử miễn phí hôm nay. Bạn vẫn có thể tạo bản đầy đủ sau khi xác nhận."
    if reason == "preview_cap_unavailable":
        return "Máy tạo bản nghe thử ngắn đang tạm bận. TOAN AAS chưa xử lý bản đầy đủ và chưa trừ Xu final."
    if reason == "usage_unavailable":
        return "TOAN AAS chưa kiểm tra được lượt nghe thử lúc này. Bạn vui lòng thử lại sau; hệ thống chưa gọi xử lý và chưa trừ Xu final."
    return "Yêu cầu tạo bản nghe thử không còn hợp lệ hoặc chưa xác nhận quyền sử dụng."


def acquire_voice_preview_generation(user_id, profile_id: int, guard: dict, now: datetime | None = None) -> tuple[bool, dict]:
    now = now or datetime.now()
    fresh = get_user_voice_profile(user_id, profile_id)
    if not fresh or (str(fresh.get("status") or "") in {"preview_generating", "processing"} and not guard.get("stale_inflight")):
        return False, fresh
    metadata = voice_profile_metadata(fresh)
    day_key = now.strftime("%Y-%m-%d")
    attempts_today = int(metadata.get("preview_attempts_today") or 0) if metadata.get("preview_attempt_day") == day_key else 0
    metadata.update({
        "preview_key_pending": str(guard.get("preview_key") or ""),
        "preview_mode": "clone_preview",
        "preview_attempt_day": day_key,
        "preview_attempts_today": attempts_today + 1,
        "preview_attempt_at": datetime_text(now),
        "preview_charged_xu": 0,
        "preview_limits_bypassed": bool((guard.get("usage") or {}).get("bypassed")),
    })
    ok = update_user_voice_profile(
        user_id,
        profile_id,
        status="processing",
        metadata_json=json.dumps(metadata, ensure_ascii=False),
    )
    fresh.update({"status": "processing", "metadata_json": json.dumps(metadata, ensure_ascii=False)})
    return bool(ok), fresh


async def cap_voice_preview_audio_bytes(audio_bytes: bytes, max_seconds: int = VOICE_PREVIEW_MAX_SECONDS) -> tuple[bytes, str]:
    ffmpeg = frame_video_ffmpeg_path()
    seconds = max(2, min(6, int(max_seconds or VOICE_PREVIEW_MAX_SECONDS)))
    if not ffmpeg or not audio_bytes:
        return b"", "preview_cap_unavailable"
    with tempfile.TemporaryDirectory() as tmpdir:
        input_path = os.path.join(tmpdir, "voice_preview_input.mp3")
        output_path = os.path.join(tmpdir, "voice_preview_capped.mp3")
        with open(input_path, "wb") as handle:
            handle.write(audio_bytes)
        ok, detail = await run_ffmpeg_command([
            ffmpeg,
            "-y",
            "-i", input_path,
            "-t", str(seconds),
            "-vn",
            "-c:a", "libmp3lame",
            "-b:a", "96k",
            output_path,
        ], timeout=30)
        if not ok or not os.path.exists(output_path) or os.path.getsize(output_path) <= 0:
            return b"", str(detail or "preview_cap_failed")
        with open(output_path, "rb") as handle:
            return handle.read(), "ok"

def voice_clone_admin_blocker(readiness: dict | None = None) -> str:
    readiness = dict(readiness or get_minimax_voice_clone_readiness())
    blockers = []
    blockers.extend(readiness.get("missing_env") or [])
    if not readiness.get("ready"):
        blockers.append(readiness.get("reason") or "voice clone route not configured")
    if not readiness.get("public_enabled"):
        blockers.append(readiness.get("reason") or "voice clone public gate closed")
    if MINIMAX_REQUIRE_SMOKE_PASS:
        tts_smoke = str(readiness.get("tts_smoke") or "NOT_TESTED")
        clone_smoke = str(readiness.get("clone_smoke") or "NOT_TESTED")
        if tts_smoke != "PASS":
            blockers.append(f"minimax_tts smoke={tts_smoke}")
        if clone_smoke != "PASS":
            blockers.append(f"minimax_voice_clone smoke={clone_smoke}")
    routes = ",".join(readiness.get("routes") or [])
    if routes:
        blockers.append(f"configured_routes={routes}")
    return sanitize_log_text("; ".join(str(item) for item in blockers if str(item or "").strip()))[:700] or "voice clone provider not ready"

def voice_clone_route_error(
    adapter: str,
    operation: str,
    route: str,
    status: str,
    detail: str = "",
    *,
    http_status: int = 0,
    provider_status: str = "",
    output_bytes: int = 0,
    payload_fields: list[str] | None = None,
) -> dict:
    safe_fields = []
    for field in payload_fields or []:
        value = re.sub(r"[^0-9A-Za-z_.-]+", "", str(field or "").strip())
        if value and value not in safe_fields:
            safe_fields.append(value)
    return {
        "adapter": sanitize_log_text(str(adapter or ""))[:80],
        "operation": sanitize_log_text(str(operation or ""))[:40],
        "route": sanitize_log_text(str(route or ""))[:120],
        "http_status": int(http_status or 0),
        "provider_status": sanitize_log_text(str(provider_status or status or ""))[:80],
        "error_code": sanitize_log_text(str(status or ""))[:80],
        "error_message": shopaikey_sanitize_error(sanitize_log_text(str(detail or "")))[:220],
        "output_bytes": int(output_bytes or 0),
        "payload_fields": safe_fields[:16],
    }

def voice_clone_route_error_summary(error, limit: int = 260) -> str:
    if not isinstance(error, dict):
        return _engine_safe(str(error or ""), limit)
    fields = ",".join(str(item) for item in (error.get("payload_fields") or [])) or "-"
    text = (
        f"adapter={error.get('adapter') or '-'}; "
        f"operation={error.get('operation') or '-'}; "
        f"route={error.get('route') or '-'}; "
        f"http_status={int(error.get('http_status') or 0)}; "
        f"provider_status={error.get('provider_status') or '-'}; "
        f"error_code={error.get('error_code') or '-'}; "
        f"error_message={error.get('error_message') or '-'}; "
        f"output_bytes={int(error.get('output_bytes') or 0)}; "
        f"payload_fields={fields}"
    )
    return _engine_safe(text, limit)

def voice_clone_route_error_markers(route_errors: list[dict | str] | None = None) -> str:
    parts = []
    for item in route_errors or []:
        if isinstance(item, dict):
            parts.extend([
                str(item.get("error_code") or ""),
                str(item.get("error_message") or ""),
                str(item.get("provider_status") or ""),
                str(item.get("operation") or ""),
            ])
        else:
            parts.append(str(item or ""))
    return " ".join(parts).lower()

def voice_clone_not_ready_status(route_errors: list[dict | str] | None = None, error: Exception | str = "") -> str:
    marker = f"{str(error or '').lower()} {voice_clone_route_error_markers(route_errors)}"
    if "voice clone user forbidden" in marker or "clone_permission_forbidden" in marker or "forbidden" in marker:
        return "CLONE_PERMISSION_FORBIDDEN"
    if "adapter_missing" in marker or "upload_adapter_missing" in marker:
        return "CLONE_ADAPTER_MISSING"
    return "CLONE_NOT_READY"

def voice_clone_permission_error(error: Exception | str = "") -> bool:
    marker = str(error or "").lower()
    return bool(
        "clone_permission_forbidden" in marker
        or "clone_permis" in marker
        or "voice clone user forbidden" in marker
        or "forbidden" in marker
    )

def voice_clone_last_forbidden_attempt() -> bool:
    attempt = load_provider_attempt("voice_clone")
    marker = " ".join(str(attempt.get(key) or "") for key in ("status", "error", "clone_status", "route")).lower()
    return bool("clone_permission_forbidden" in marker or "voice clone user forbidden" in marker)

async def _call_optional_voice_adapter(names: list[str], *args, **kwargs):
    for name in names:
        func = globals().get(name)
        if not callable(func):
            continue
        result = func(*args, **kwargs)
        if asyncio.iscoroutine(result) or hasattr(result, "__await__"):
            result = await result
        return result, name
    return None, ""

def _voice_upload_result(result, provider: str, called_name: str = "") -> tuple[str, str, str, int]:
    if isinstance(result, dict):
        status = str(result.get("status") or ("PASS" if result.get("ok") else "FAIL"))
        file_id = str(result.get("file_id") or result.get("voice_id") or result.get("id") or "")
        detail = str(result.get("detail") or result.get("error_message_safe") or result.get("error") or called_name or "")
        return status, file_id, detail[:240], int(result.get("http_status") or 0)
    if isinstance(result, (tuple, list)):
        status = str(result[0] if len(result) > 0 else "")
        file_id = str(result[1] if len(result) > 1 else "")
        detail = str(result[2] if len(result) > 2 else "")
        http_status = int(result[3] if len(result) > 3 and str(result[3]).isdigit() else 0)
        return status, file_id, detail[:240], http_status
    return "ADAPTER_MISSING", "", f"{provider}_upload_adapter_missing", 0

def _voice_clone_result(result, provider: str, voice_id: str, called_name: str = "") -> tuple[str, dict, str, int]:
    if isinstance(result, dict):
        status = str(result.get("status") or ("PASS" if result.get("ok") else "FAIL"))
        provider_voice_id = str(result.get("voice_id") or result.get("provider_voice_id") or voice_id or "")
        payload = dict(result)
        if provider_voice_id:
            payload["voice_id"] = provider_voice_id
        detail = str(result.get("detail") or result.get("error_message_safe") or result.get("error") or called_name or "")
        return status, payload, detail[:240], int(result.get("http_status") or 0)
    if isinstance(result, (tuple, list)):
        status = str(result[0] if len(result) > 0 else "")
        payload = result[1] if len(result) > 1 and isinstance(result[1], dict) else {"voice_id": str(result[1] if len(result) > 1 else voice_id or "")}
        detail = str(result[2] if len(result) > 2 else "")
        http_status = int(result[3] if len(result) > 3 and str(result[3]).isdigit() else 0)
        return status, dict(payload), detail[:240], http_status
    return "ADAPTER_MISSING", {}, f"{provider}_clone_adapter_missing", 0

