async def handle_music_guided_pending_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.effective_user:
        return False
    uid = update.effective_user.id
    state = get_music_guided_pending(uid)
    if not state:
        return False
    pending_action = str(state.get("pending_action") or "")
    ctx = normalize_product_context(state.get("product_context"), PRODUCT_CONTEXT_SHOWROOM)
    if pending_action in {"music_merge_video", "voice_merge_video", "music_merge_audio", "voice_merge_audio"}:
        target = "video" if pending_action.endswith("_video") else "audio"
        kind = "voice" if pending_action.startswith("voice_") else "music"
        media_kind = cache_recent_media_state(update)
        lang = music_ui_lang(uid)
        if target == "video" and media_kind != "video":
            await update.message.reply_text(
                "⚠️ Hãy gửi file video để ghép. Bot chưa render và chưa trừ Xu.",
                reply_markup=music_merge_keyboard(kind, lang, ctx),
            )
            return True
        if target == "audio" and media_kind != "audio":
            await update.message.reply_text(
                "⚠️ Hãy gửi file audio/voice/nhạc hợp lệ. Bot chưa render và chưa trừ Xu.",
                reply_markup=music_merge_keyboard(kind, lang, ctx),
            )
            return True
        clear_music_guided_pending(uid)
        await update.message.reply_text(
            ("✅ Đã lưu video vào phiên này.\n\n" if target == "video" else "✅ Đã lưu audio/nhạc/giọng đọc vào phiên này.\n\n")
            + music_merge_menu_text(kind, uid, lang),
            parse_mode="HTML",
            reply_markup=music_merge_keyboard(kind, lang, ctx),
        )
        return True
    if pending_action == "speech_to_text_upload":
        lang = music_ui_lang(uid)
        media, file_type = message_media_candidate(update.message)
        mime = media_content_type(media, file_type) if media else ""
        if not media or not (file_type in {"voice", "audio", "video", "document"} or str(mime).startswith(("audio/", "video/"))):
            await update.message.reply_text(
                "⚠️ Hãy gửi voice/audio/video hợp lệ để chuyển thành văn bản. TOAN AAS chưa xử lý và chưa trừ Xu.",
                reply_markup=music_guided_back_keyboard(lang, ctx, "voice_hub"),
            )
            return True
        clear_music_guided_pending(uid)
        ok, transcript, detail = await transcribe_standalone_audio_message(update, context)
        if ok and transcript:
            await update.message.reply_text(
                "📝 <b>Bản chuyển văn bản</b>\n\n"
                f"{html.escape(transcript[:3500])}\n\n"
                "TOAN AAS chưa trừ Xu final.",
                parse_mode="HTML",
                reply_markup=voice_hub_keyboard(lang, PRODUCT_CONTEXT_SHOWROOM),
            )
            return True
        logger.info("standalone stt not ready | user=%s | detail=%s", uid, sanitize_log_text(detail)[:160])
        await update.message.reply_text(
            "⚙️ Chuyển giọng nói thành văn bản đang được kiểm tra tài nguyên xử lý. TOAN AAS chưa trừ Xu. Bạn có thể thử lại với file ngắn/rõ hơn.",
            reply_markup=voice_hub_keyboard(lang, PRODUCT_CONTEXT_SHOWROOM),
        )
        return True
    if pending_action != "voice_clone_upload":
        return False
    media, file_type = message_media_candidate(update.message)
    mime = media_content_type(media, file_type) if media else ""
    if not media or not (file_type in {"voice", "audio", "document"} or str(mime).startswith("audio/")):
        await update.message.reply_text(
            "⚠️ Hãy gửi file voice/audio hợp lệ để lưu voice profile. TOAN AAS chưa bắt đầu xử lý và chưa trừ Xu.",
            reply_markup=voice_clone_keyboard(music_ui_lang(uid), ctx),
        )
        return True
    file_id = str(getattr(media, "file_id", "") or "")
    profile_id = _safe_int(state.get("profile_id"), 0)
    existing_profile = get_user_voice_profile(uid, profile_id) if profile_id else {}
    if existing_profile:
        metadata = voice_profile_metadata(existing_profile)
        metadata.update({"file_type": str(file_type or "audio")[:40], "source": "telegram_upload"})
        updated = update_user_voice_profile(
            uid,
            profile_id,
            source_file_id=file_id,
            source_file_ref=file_id,
            status="pending_name",
            metadata_json=json.dumps(metadata, ensure_ascii=False),
        )
        if not updated:
            profile_id = 0
    else:
        profile_id = save_user_voice_profile(
            uid,
            file_id,
            file_type=file_type or "audio",
            consent_at=str(state.get("consent_at") or now_text()),
        )
    lang = music_ui_lang(uid)
    if profile_id:
        set_voice_flow_pending(
            uid,
            "voice_clone_sample_confirm",
            profile_id=profile_id,
            product_context=ctx,
            origin=VOICE_FLOW_ROOT_SCREEN,
            current_screen="voice_clone_sample_confirm",
            previous_screen="voice_clone_upload",
            return_to="voice_clone_upload",
            back_stack=["voice_hub", "voice_clone_intro", "voice_clone_upload"],
            voice_flow_step="voice_clone_sample_confirm",
            voice_sample_file_id=file_id,
        )
        await update.message.reply_text(
            voice_clone_sample_confirmation_text(lang),
            parse_mode="HTML",
            reply_markup=voice_clone_step_back_keyboard(f"voice_clone_back_upload:{profile_id}", lang, ctx),
        )
    else:
        clear_music_guided_pending(uid)
        await update.message.reply_text(
            "⚠️ Không lưu được file giọng lúc này. TOAN AAS chưa trừ Xu.",
            reply_markup=voice_hub_keyboard(lang, ctx),
        )
    return True

def music_ai_provider_summary() -> str:
    providers = []
    try:
        readiness = get_suno_music_readiness()
        configured = dict(readiness.get("providers") or {})
        if (configured.get("key4u_suno") or {}).get("configured"):
            providers.append("Key4U Suno")
        if (configured.get("shopaikey_music") or {}).get("configured"):
            providers.append("ShopAIKey Music/Suno")
    except Exception:
        pass
    if MUSICFUL_API_KEY:
        providers.append("Musicful")
    if MINIMAX_API_KEY and MINIMAX_GROUP_ID:
        providers.append("MiniMax")
    elif MINIMAX_API_KEY:
        providers.append("MiniMax thiếu group_id")
    if STABILITY_API_KEY:
        providers.append("Stability/Stable Audio")
    if MUBERT_API_KEY:
        providers.append("Mubert")
    if BEATOVEN_API_KEY:
        providers.append("Beatoven")
    if SOUNDRAW_API_KEY:
        providers.append("Soundraw")
    return ", ".join(providers) or "missing"

