def reply_media_candidate(message, wanted: set[str]) -> dict:
    if not message:
        return {}
    if "image" in wanted and getattr(message, "photo", None):
        photo = message.photo[-1]
        return {"file_id": str(photo.file_id or ""), "mime_type": "image/jpeg", "file_name": "telegram_photo.jpg", "file_size": int(photo.file_size or 0), "file_type": "image"}
    media, file_type = message_media_candidate(message)
    if not media:
        return {}
    mime = media_content_type(media, file_type)
    category = "video" if file_type == "video" or mime.startswith("video/") else "audio"
    if category not in wanted:
        return {}
    return {
        "file_id": str(getattr(media, "file_id", "") or ""),
        "mime_type": mime,
        "file_name": str(getattr(media, "file_name", "") or ""),
        "file_size": int(getattr(media, "file_size", 0) or 0),
        "file_type": category,
        "duration": int(getattr(media, "duration", 0) or 0),
    }

async def telegram_file_to_path(context: ContextTypes.DEFAULT_TYPE, file_id: str, path: str):
    tg_file = await context.bot.get_file(file_id)
    data = bytes(await tg_file.download_as_bytearray())
    with open(path, "wb") as f:
        f.write(data)
    return path

async def url_to_path(url: str, path: str, max_bytes: int = MEDIA_PREVIEW_MAX_BYTES):
    async with httpx.AsyncClient(timeout=25.0, follow_redirects=True) as client:
        res = await client.get(url)
    if res.status_code >= 400:
        raise RuntimeError(f"media_url_http_{res.status_code}")
    data = bytes(res.content or b"")
    if not data:
        raise RuntimeError("media_url_empty")
    if len(data) > max_bytes:
        raise RuntimeError("media_url_too_large")
    with open(path, "wb") as f:
        f.write(data)
    return path

async def send_generated_image_result(
    context: ContextTypes.DEFAULT_TYPE,
    chat_id,
    image_url: str,
    caption: str,
    reply_markup=None,
    lang: str = "vi",
    b64_json: str = "",
) -> tuple[bool, str]:
    output_file_id = ""

    async def try_photo(photo_value, retries: int = 2):
        nonlocal output_file_id
        last_error = ""
        for attempt in range(max(1, int(retries or 1))):
            try:
                sent = await context.bot.send_photo(
                    chat_id=chat_id,
                    photo=photo_value() if callable(photo_value) else photo_value,
                    caption=caption,
                    reply_markup=reply_markup,
                )
                photos = getattr(sent, "photo", None) or []
                if photos:
                    output_file_id = str(getattr(photos[-1], "file_id", "") or "")
                return True, ""
            except Exception as e:
                last_error = sanitize_log_text(str(e))[:220]
                if attempt == 0 and is_timeout_exception(e):
                    await asyncio.sleep(0.8)
                    continue
                break
        return False, last_error

    async def try_document(document_value, filename: str = "toan_aas_image.png"):
        try:
            await context.bot.send_document(
                chat_id=chat_id,
                document=document_value() if callable(document_value) else document_value,
                filename=filename,
                caption=caption,
                reply_markup=reply_markup,
            )
            return True
        except Exception as e:
            logger.warning("generated image document fallback failed | %s", sanitize_log_text(str(e))[:220])
            return False

    image_url = str(image_url or "").strip()
    b64_json = str(b64_json or "").strip()
    if image_url:
        sent, error = await try_photo(image_url)
        if sent:
            return True, output_file_id
        try:
            sent_document = await try_document(image_url, "toan_aas_image.png")
            if sent_document:
                return True, output_file_id
        except Exception:
            pass
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=ui_text(lang, "image.success_link", url=html.escape(image_url, quote=True)),
                parse_mode="HTML",
                disable_web_page_preview=False,
                reply_markup=reply_markup,
            )
            return True, output_file_id
        except Exception as e:
            logger.warning("generated image link fallback failed | photo_error=%s | %s", error, sanitize_log_text(str(e))[:220])

    if b64_json:
        try:
            image_bytes = base64.b64decode(b64_json, validate=False)
        except Exception as e:
            logger.warning("generated image b64 decode failed | %s", sanitize_log_text(str(e))[:220])
            image_bytes = b""
        if image_bytes:
            def make_photo():
                photo = io.BytesIO(image_bytes)
                photo.name = "toan_aas_image.png"
                return photo
            sent, _error = await try_photo(make_photo)
            if sent:
                return True, output_file_id
            if await try_document(make_photo, "toan_aas_image.png"):
                return True, output_file_id
    return False, output_file_id


async def send_frame_video_generated_image(
    context: ContextTypes.DEFAULT_TYPE,
    chat_id,
    *,
    image_url: str,
    b64_json: str,
    caption: str,
) -> dict:
    """Deliver one generated image and return the Telegram delivery receipt."""

    async def receipt(sent, artifact_fallback: str = "") -> dict:
        message_id = int(getattr(sent, "message_id", 0) or 0)
        photos = getattr(sent, "photo", None) or []
        document = getattr(sent, "document", None)
        file_id = str(
            (getattr(photos[-1], "file_id", "") if photos else "")
            or getattr(document, "file_id", "")
            or ""
        )
        artifact = file_id or str(artifact_fallback or "").strip()
        return {
            "sent": bool(message_id and artifact),
            "message_id": message_id,
            "file_id": file_id,
            "artifact": artifact,
        }

    image_url = str(image_url or "").strip()
    b64_json = str(b64_json or "").strip()
    if image_url:
        try:
            sent = await context.bot.send_photo(chat_id=chat_id, photo=image_url, caption=caption)
            return await receipt(sent, image_url)
        except Exception as photo_exc:
            logger.warning(
                "frame video generated image photo delivery failed | %s",
                sanitize_log_text(str(photo_exc))[:220],
            )
        try:
            sent = await context.bot.send_document(
                chat_id=chat_id,
                document=image_url,
                filename="toan_aas_frame_image.png",
                caption=caption,
            )
            return await receipt(sent, image_url)
        except Exception as document_exc:
            logger.warning(
                "frame video generated image document delivery failed | %s",
                sanitize_log_text(str(document_exc))[:220],
            )
    if b64_json:
        try:
            image_bytes = base64.b64decode(b64_json, validate=False)
        except Exception:
            image_bytes = b""
        if image_bytes:
            def image_file():
                value = io.BytesIO(image_bytes)
                value.name = "toan_aas_frame_image.png"
                return value

            try:
                sent = await context.bot.send_photo(chat_id=chat_id, photo=image_file(), caption=caption)
                return await receipt(sent, hashlib.sha256(image_bytes).hexdigest())
            except Exception as photo_exc:
                logger.warning(
                    "frame video generated b64 photo delivery failed | %s",
                    sanitize_log_text(str(photo_exc))[:220],
                )
            try:
                sent = await context.bot.send_document(
                    chat_id=chat_id,
                    document=image_file(),
                    filename="toan_aas_frame_image.png",
                    caption=caption,
                )
                return await receipt(sent, hashlib.sha256(image_bytes).hexdigest())
            except Exception as document_exc:
                logger.warning(
                    "frame video generated b64 document delivery failed | %s",
                    sanitize_log_text(str(document_exc))[:220],
                )
    return {"sent": False, "message_id": 0, "file_id": "", "artifact": ""}


