    for row in prompts:
        preview = str(row.get("prompt") or "")[:90]
        lines.append(f"• Ảnh {int(row.get('index') or 0)}: {html.escape(preview)}{'…' if len(str(row.get('prompt') or '')) > 90 else ''}")
