def frame_video_quality_keyboard(state: dict | None = None) -> InlineKeyboardMarkup:
    is_framevideo3 = is_frame_video3_state(state)
    done_callback = "framevideo|continue" if is_framevideo3 else "framevideo|panel"
    done_label = "✅ Hoàn tất chọn chất lượng" if is_framevideo3 else "✅ Hoàn thiện video"
    back_callback = (
        "vid3|resume"
        if str((state or {}).get("uiflow3_return_to") or "") == "vid3|resume"
        else "framevideo|review" if is_framevideo3 else "framevideo|panel"
    )
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("⚡ Nhanh · 50 Xu", callback_data="framevideo|quality_set|fast"), InlineKeyboardButton("⭐ Cân bằng · 100 Xu", callback_data="framevideo|quality_set|balanced")],
        [InlineKeyboardButton("💎 Đẹp · 200 Xu", callback_data="framevideo|quality_set|beautiful"), InlineKeyboardButton(done_label, callback_data=done_callback)],
        [InlineKeyboardButton("⬅️ Quay lại rà soát kế hoạch", callback_data=back_callback), InlineKeyboardButton("🎬 Menu Video", callback_data="menu|main_video")],
    ])


def frame_video_quality_text(state: dict) -> str:
    clean = normalize_frame_video_state(state)
    current = str(clean.get("quality") or "balanced")
    if clean.get("uiflow3_draft_id"):
        lines = [
            "⭐ <b>Chọn chất lượng video</b>",
            "",
            f"Đang chọn: <b>{html.escape(FRAME_VIDEO_QUALITY_LABELS.get(current, current))}</b>",
            "",
            "Chọn mức phù hợp với tốc độ, độ nét và kích thước video mong muốn:",
        ]
        for token in ("fast", "balanced", "beautiful"):
            detail = frame_video_commercial.QUALITY_DETAILS[token]
            preset = frame_video_runtime.quality_payload(
                token,
                str(clean.get("ratio") or "9x16"),
                clean.get("custom_width"),
                clean.get("custom_height"),
            )
            price = frame_video_price_breakdown({**clean, "quality": token})
            marker = "✅" if token == current else "•"
            lines.append(
                f"{marker} <b>{html.escape(str(detail['label']))}</b> · "
                f"{int(preset['width'])}×{int(preset['height'])} · "
                f"{xu_number(int(price.get('total') or 0))} Xu"
            )
            lines.append(f"  {html.escape(str(detail['strength']))}. {html.escape(str(detail['limit']))}.")
        lines.extend([
            "",
            "Giá đầy đủ sẽ được hiển thị ở bước báo giá trước khi xác nhận dựng video.",
        ])
        return "\n".join(lines)
    preflight = frame_video_commercial_preflight(clean)
    route = str(preflight.get("execution_owner") or "")
    route_label = {
        "local_ffmpeg": "Dựng trực tiếp bằng FFmpeg local",
        frame_video_commercial.EXECUTION_OWNER: "Local Worker dựng bằng FFmpeg",
    }.get(route, "Chưa có tuyến dựng sẵn sàng")
    availability = "Sẵn sàng" if preflight.get("ok") else f"Chưa sẵn sàng ({preflight.get('blocker') or 'preflight_failed'})"
    lines = [
        "⭐ <b>Hoàn thiện video</b>",
        "",
        f"Đang chọn: <b>{html.escape(FRAME_VIDEO_QUALITY_LABELS.get(current, current))}</b>",
        f"Tuyến dựng: <b>{html.escape(route_label)}</b>",
        f"Trạng thái: <b>{html.escape(availability)}</b>",
        "",
    ]
    for token in ("fast", "balanced", "beautiful"):
        detail = frame_video_commercial.QUALITY_DETAILS[token]
        preset = frame_video_runtime.quality_payload(
            token,
            str(clean.get("ratio") or "9x16"),
            clean.get("custom_width"),
            clean.get("custom_height"),
        )
        tier_state = {**clean, "quality": token}
        tier_price = frame_video_price_breakdown(tier_state)
        marker = "✅" if token == current else "•"
        lines.extend(
            [
                f"{marker} <b>{html.escape(str(detail['label']))}</b> · {int(preset['width'])}×{int(preset['height'])} · {int(preset['fps'])} FPS",
                f"  Codec: H.264 ({html.escape(str(preset['codec']))}) · Giá dự kiến: {xu_number(int(tier_price.get('total') or 0))} Xu.",
                f"  Thời gian: {html.escape(str(detail['eta']))}.",
                f"  Mạnh: {html.escape(str(detail['strength']))}.",
                f"  Lưu ý: {html.escape(str(detail['limit']))}.",
            ]
        )
    lines.extend([
        "",
        "Giá gói dựng là giá khuyến mãi cố định, không đổi theo độ dài video. "
        "Dịch vụ tạo thêm nếu có được ghi riêng ở hóa đơn. Preflight chạy lại "
        "ngay trước hóa đơn và không tạo job khi chưa đạt.",
    ])
    return "\n".join(lines)


def frame_video_review_text(state: dict, user_id=0, invoice: bool = False) -> str:
    summary = frame_video_flow.plan_summary(state)
    clean = summary["state"]
    price = frame_video_price_breakdown(clean)
    cost = shopaikey_preview_final_cost(user_id, int(price.get("total") or 0), f"frame_video_{clean.get('quality') or 'balanced'}")
    title = "🧾 <b>Báo giá và xác nhận</b>" if invoice else "👁️ <b>Kế hoạch video</b>"
    lines = [
        title, "",
        f"• {summary['image_count']} ảnh · {summary['duration_seconds']:.1f} giây · {html.escape(summary['ratio'])}",
        f"• {html.escape(FRAME_VIDEO_FIT_LABELS.get(summary['fit_mode'], summary['fit_mode']))}",
        f"• Chuyển cảnh: {html.escape(FRAME_VIDEO_TRANSITION_LABELS.get(summary['transition'], summary['transition']))}",
        f"• Chuyển động: {html.escape(FRAME_VIDEO_MOTION_LABELS.get(summary['motion'], summary['motion']))}",
        f"• Chất lượng: {html.escape(FRAME_VIDEO_QUALITY_LABELS.get(summary['quality'], summary['quality']))}",
        f"• Nhạc: {'Có' if summary['has_music'] else 'Không'} · Lồng tiếng: {'Có' if summary['has_voice'] else 'Không'}",
        f"• Logo: {'Có' if summary['has_logo'] else 'Không'} · Watermark: {'Có' if summary['has_watermark'] else 'Không'}",
        f"• Chữ/phụ đề: {summary['text_count']} mục",
    ]
    receipts = [row for row in list(clean.get("generated_image_receipts") or []) if isinstance(row, dict)]
    generated_count = sum(1 for row in list(clean.get("photos") or []) if str(row.get("source") or "") == "generated")
    uploaded_count = max(0, int(summary["image_count"]) - generated_count)
    image_charge = int(clean.get("image_generation_charged_amount") or 0)
    image_receipts_paid = bool(receipts) and all(bool(row.get("charge_recorded")) for row in receipts)
    lines.extend(["", "<b>Ảnh đầu vào</b>"])
    if generated_count:
        lines.append(
            f"• Ảnh AI: <b>{generated_count}</b> ảnh · "
            f"biên nhận <b>{len(receipts)}</b> · "
            f"{'đã ghi ' + xu_number(image_charge) + ' Xu' if image_receipts_paid else 'chưa hoàn tất đối soát'}"
        )
    if uploaded_count:
        lines.append(f"• Ảnh anh/chị gửi: <b>{uploaded_count}</b> ảnh · không có phí tạo ảnh AI")
    if invoice:
        lines.extend(
            [
                "",
                "<b>Hóa đơn dựng MP4</b>",
                f"• Thời lượng video: <b>{int(price.get('duration_seconds') or 0)} giây</b>",
                f"• Gói dựng cố định: <b>{xu_number(int(price.get('base') or 0))} Xu</b>",
                f"• Tùy chọn bổ sung: <b>{xu_number(int(price.get('addon_xu') or 0))} Xu</b>",
                f"• Nhạc: <b>{xu_number(int(price.get('music_xu') or 0))} Xu</b>",
                f"• Tổng video dự kiến: <b>{xu_number(cost)} Xu</b>",
                "• Giá gói dựng không đổi theo thời lượng video.",
                "• Mức giá gồm đúng phần dựng và các dịch vụ tạo thêm đã chọn.",
                "• Phí ảnh AI đã giao được đối soát riêng và không cộng lại vào hóa đơn video.",
                "Xu video chỉ được ghi sau khi MP4 hợp lệ đã gửi thành công.",
            ]
        )
    else:
        lines.extend(["", "Màn này chỉ xem kế hoạch, chưa tạo file và chưa trừ Xu."])
    return "\n".join(lines)


