def storyboard_ai_motion_prompt(scene: dict, motion_index: int = 1) -> str:
    title = str((scene or {}).get("scene_title") or f"Cảnh {int((scene or {}).get('scene_index') or 1)}").strip()
    description = str((scene or {}).get("scene_description") or "").strip()
    image_prompt = str((scene or {}).get("image_prompt") or "").strip()
    motions = {
        1: "Camera zoom nhẹ vào sản phẩm, slow push-in, parallax tinh tế, ánh sáng sạch, chuyển động ổn định.",
        2: "Sản phẩm nổi bật/chuyển động nhẹ, background sống động vừa phải, cảm giác quảng cáo chuyên nghiệp.",
        3: "Lifestyle motion tự nhiên, chuyển động đời thường, camera mềm, cảm xúc thân thiện, thương mại nhẹ.",
    }
    motion = motions.get(int(motion_index or 1), motions[1])
    return re.sub(
        r"\s+",
        " ",
        f"{title}. {description}. {image_prompt}. {motion} No watermark, no extra text, no distorted subject.",
    ).strip()[:1200]

def storyboard_video_package_from_scene(user_id, project_id: int, scene_index: int, motion_index: int = 1, lang: str = "vi") -> dict:
    rows = storyboard_scenes_for_project(project_id)
    scene = next((row for row in rows if int(row.get("scene_index") or 0) == int(scene_index or 0)), rows[0] if rows else {})
    source_job_id = str(scene.get("image_job_id") or "").strip()
    return {
        "source": "storyboard_image_to_video",
        "source_job_id": source_job_id,
        "image_job_id": source_job_id,
        "telegram_file_id": str(scene.get("image_file_id") or "")[:220],
        "generated_image_url": str(scene.get("image_url") or "")[:1000],
        "image_url": str(scene.get("image_url") or "")[:1000],
        "image_prompt": str(scene.get("image_prompt") or "")[:1200],
        "source_flow": "storyboard",
        "project_id": str(int(project_id or 0)),
        "scene_index": str(int(scene_index or 0)),
        "video_prompt": storyboard_ai_motion_prompt(scene, motion_index),
        "video_prompt_choice": max(1, min(3, int(motion_index or 1))),
        "music_choice": {"type": "not_selected", "label": "music_not_selected"},
        "no_music": False,
    }

def create_storyboard_project(user_id, source_type: str, title: str, selected_script: str, scenes: list[dict]) -> int:
    now = now_text()
    conn = db_connect()
    try:
        cur = conn.cursor()
        cur.execute(
            """INSERT INTO storyboard_projects
               (user_id, source_type, title, selected_script, scene_count, status, created_at, updated_at)
               VALUES (?,?,?,?,?,?,?,?)""",
            (str(user_id), source_type, title[:300], selected_script[:1800], len(scenes or []), "storyboard_ready", now, now),
        )
        project_id = int(cur.lastrowid)
        for scene in scenes or []:
            cur.execute(
                """INSERT INTO storyboard_scenes
                   (project_id, scene_index, scene_title, scene_description, image_prompt, status, created_at, updated_at)
                   VALUES (?,?,?,?,?,?,?,?)""",
                (
                    project_id,
                    int(scene.get("scene_index") or 0),
                    str(scene.get("scene_title") or "")[:300],
                    str(scene.get("scene_description") or "")[:900],
                    str(scene.get("image_prompt") or "")[:1400],
                    "prompt_ready",
                    now,
                    now,
                ),
            )
        conn.commit()
        return project_id
    finally:
        conn.close()

def storyboard_scenes_for_project(project_id: int) -> list[dict]:
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(
            "SELECT * FROM storyboard_scenes WHERE project_id=? ORDER BY scene_index ASC",
            (int(project_id or 0),),
        ).fetchall()
        return [dict(row) for row in rows]
    finally:
        conn.close()

def storyboard_project_for_user(project_id: int, user_id) -> dict:
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            "SELECT * FROM storyboard_projects WHERE id=? AND user_id=? LIMIT 1",
            (int(project_id or 0), str(user_id or "")),
        ).fetchone()
        return dict(row) if row else {}
    finally:
        conn.close()

def developing_video_frame_photos(state: dict | None) -> list[dict]:
    state = state or {}
    photos = []
    for item in list(state.get("photos") or []):
        if isinstance(item, dict):
            file_id = str(item.get("file_id") or item.get("image_file_id") or "").strip()
            image_url = str(item.get("image_url") or item.get("url") or "").strip()
        else:
            file_id = str(item or "").strip()
            image_url = ""
        if file_id or image_url:
            photos.append({"file_id": file_id, "image_url": image_url})
    return photos[:FRAME_VIDEO_MAX_IMAGES]

async def open_existing_images_in_frame_video(query, uid, photos: list[dict], source: str, lang: str = "vi", **metadata):
    clean_photos = developing_video_frame_photos({"photos": photos})
    if len(clean_photos) < 2:
        return await safe_edit_or_send(
            query,
            "⚠️ Chưa có bộ ảnh để ghép video. Vui lòng tạo storyboard/ảnh trước. Bot chưa render và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "⚠️ There is no image set to assemble yet. Create or upload at least two images first. No video was rendered and no Xu was charged.",
            parse_mode=None,
        )
    state = {
        "step": "planning",
        "photos": clean_photos,
        "source": str(source or "existing_images")[:80],
        "motion_mode": "frame",
        **metadata,
    }
    set_frame_video_state(uid, state)
    return await safe_edit_or_send(
        query,
        frame_video_planning_text(state, lang),
        parse_mode="HTML",
        reply_markup=frame_video_planning_keyboard(lang),
    )

def update_storyboard_scene_asset(project_id: int, scene_index: int, image_job_id: int = 0, image_file_id: str = "", image_url: str = "", tier: str = "", price_xu: int = 0, status: str = "image_ready") -> None:
    conn = db_connect()
    try:
        conn.execute(
            """UPDATE storyboard_scenes
               SET image_job_id=?, image_file_id=?, image_url=?, image_tier=?, image_price_xu=?, status=?, updated_at=?
               WHERE project_id=? AND scene_index=?""",
            (int(image_job_id or 0), str(image_file_id or ""), str(image_url or ""), normalize_image_tier(tier), int(price_xu or 0), status, now_text(), int(project_id or 0), int(scene_index or 0)),
        )
        conn.commit()
    finally:
        conn.close()

def create_storyboard_video_record(project_id: int, render_type: str, price_xu: int, status: str = "handoff_to_frame_video") -> int:
    conn = db_connect()
    try:
        cur = conn.cursor()
        cur.execute(
            """INSERT INTO storyboard_videos (project_id, render_type, price_xu, status, created_at, updated_at)
               VALUES (?,?,?,?,?,?)""",
            (int(project_id or 0), str(render_type or "basic"), int(price_xu or 0), status, now_text(), now_text()),
        )
        conn.commit()
        return int(cur.lastrowid)
    finally:
        conn.close()

