def frame_video_ffmpeg_filter(width: int, height: int, seconds_per_image: float, effect: str) -> str:
    base = f"scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},setsar=1"
    effect = frame_video_effect_payload(effect).get("token") or "none"
    if effect == "fade":
        fade_out_start = max(0.0, float(seconds_per_image or 0) - 0.25)
        return f"{base},fade=t=in:st=0:d=0.25,fade=t=out:st={fade_out_start:.2f}:d=0.25,format=yuv420p"
    if effect == "zoom":
        frames = max(1, int(float(seconds_per_image or 0) * 30))
        zoom_w = width * 2
        zoom_h = height * 2
        return (
            f"scale={zoom_w}:{zoom_h}:force_original_aspect_ratio=increase,crop={zoom_w}:{zoom_h},"
            f"zoompan=z='min(zoom+0.0015,1.08)':d={frames}:"
            f"x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s={width}x{height}:fps=30,"
            "setsar=1,format=yuv420p"
        )
    if effect == "pan":
        frames = max(1, int(float(seconds_per_image or 0) * 30))
        pan_w = max(width + 2, int(width * 1.12))
        return (
            f"scale={pan_w}:{height}:force_original_aspect_ratio=increase,crop={pan_w}:{height},"
            f"zoompan=z=1:d={frames}:x='(iw-ow)*on/{max(frames - 1, 1)}':y='(ih-oh)/2':s={width}x{height}:fps=30,"
            "setsar=1,format=yuv420p"
        )
    if effect == "slide":
        frames = max(1, int(float(seconds_per_image or 0) * 30))
        slide_w = max(width + 2, int(width * 1.18))
        return (
            f"scale={slide_w}:{height}:force_original_aspect_ratio=increase,crop={slide_w}:{height},"
            f"zoompan=z=1:d={frames}:x='(iw-ow)*(1-on/{max(frames - 1, 1)})':y='(ih-oh)/2':s={width}x{height}:fps=30,"
            "setsar=1,format=yuv420p"
        )
    return f"{base},format=yuv420p"

def frame_video_concat_path(path: str) -> str:
    return str(path or "").replace("\\", "/").replace("'", "'\\''")

async def render_frame_video_paths(
    image_paths: list[str],
    output_path: str,
    width: int,
    height: int,
    seconds_per_image: float,
    effect: str,
    ffmpeg_path: str = "",
) -> tuple[bool, str]:
    ffmpeg = ffmpeg_path or frame_video_ffmpeg_path()
    if not ffmpeg:
        return False, "ffmpeg_missing"
    if len(image_paths or []) < 1:
        return False, "not_enough_images"
    clips: list[str] = []
    directory = os.path.dirname(output_path) or tempfile.gettempdir()
    effect_token = frame_video_effect_payload(effect).get("token") or "fade"
    random_cycle = ["fade", "zoom", "pan", "slide"]
    for idx, image_path in enumerate(image_paths[:FRAME_VIDEO_MAX_IMAGES], start=1):
        clip_path = os.path.join(directory, f"frame_video_clip_{idx}.mp4")
        clip_effect = random_cycle[(idx - 1) % len(random_cycle)] if effect_token == "random" else effect_token
        vf = frame_video_ffmpeg_filter(width, height, seconds_per_image, clip_effect)
        cmd = [
            ffmpeg, "-y",
            "-loop", "1",
            "-t", f"{float(seconds_per_image):.2f}",
            "-i", image_path,
            "-vf", vf,
            "-r", "30",
            "-an",
            "-c:v", "libx264",
            "-preset", "veryfast",
            "-pix_fmt", "yuv420p",
            "-movflags", "+faststart",
            clip_path,
        ]
        ok, detail = await run_ffmpeg_command(cmd, timeout=FRAME_VIDEO_RENDER_TIMEOUT_SECONDS)
        if not ok or not os.path.exists(clip_path):
            return False, f"clip_{idx}:{detail}"
        clips.append(clip_path)
    concat_path = os.path.join(directory, "frame_video_concat.txt")
    with open(concat_path, "w", encoding="utf-8") as f:
        for clip in clips:
            f.write(f"file '{frame_video_concat_path(clip)}'\n")
    concat_cmd = [
        ffmpeg, "-y",
        "-f", "concat",
        "-safe", "0",
        "-i", concat_path,
        "-c", "copy",
        "-movflags", "+faststart",
        output_path,
    ]
    ok, detail = await run_ffmpeg_command(concat_cmd, timeout=FRAME_VIDEO_RENDER_TIMEOUT_SECONDS)
    if not ok or not os.path.exists(output_path):
        return False, f"concat:{detail}"
    return True, "ok"

async def render_frame_video_from_state(context: ContextTypes.DEFAULT_TYPE, state: dict, output_path: str, tmpdir: str) -> tuple[bool, str]:
    result = await render_frame_video_canonical_from_state(context, state, output_path, tmpdir)
    return bool(result.get("ok")), str(result.get("reason") or result.get("blocker") or "ok")


async def frame_video_materialize_file(context: ContextTypes.DEFAULT_TYPE, file_id: str, path: str) -> str:
    if not str(file_id or "").strip():
        return ""
    await telegram_file_to_path(context, str(file_id), path)
    return path if os.path.exists(path) and os.path.getsize(path) > 0 else ""


async def render_frame_video_legacy_from_materialized_paths(
    image_paths: list[str],
    output_path: str,
    state: dict,
    *,
    music_path: str = "",
    voice_path: str = "",
    logo_path: str = "",
) -> dict:
    try:
        command = frame_video_runtime.build_ffmpeg_command(
            image_paths,
            output_path,
            state,
            ffmpeg_path=frame_video_ffmpeg_path(),
            music_path=music_path,
            voice_path=voice_path,
            logo_path=logo_path,
        )
    except Exception as exc:
        return {"ok": False, "reason": f"plan:{sanitize_log_text(str(exc))[:220]}"}
    ok, detail = await run_ffmpeg_command(command.command, timeout=FRAME_VIDEO_RENDER_TIMEOUT_SECONDS)
    if not ok or not os.path.exists(output_path) or os.path.getsize(output_path) <= 0:
        return {"ok": False, "reason": f"ffmpeg:{sanitize_log_text(str(detail))[:300]}", "command": command.command}
    probe = await asyncio.to_thread(
        frame_video_runtime.probe_mp4,
        output_path,
        command.expected_duration,
        command.expects_audio,
    )
    if not probe.get("ok"):
        return {"ok": False, "reason": f"validate:{probe.get('reason')}", "probe": probe, "command": command.command}
    digest = hashlib.sha256()
    with open(output_path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return {
        "ok": True,
        "reason": "ok",
        "probe": probe,
        "expected_duration_seconds": command.expected_duration,
        "expects_audio": command.expects_audio,
        "output_size_bytes": os.path.getsize(output_path),
        "output_sha256": digest.hexdigest(),
        "command": command.command,
    }


async def render_frame_video_canonical_from_state(
    context: ContextTypes.DEFAULT_TYPE,
    state: dict,
    output_path: str,
    tmpdir: str,
    *,
    user_id: int = 0,
    confirmation_id: str = "",
    language: str = "vi",
) -> dict:
    state = dict(state or {})
    state["photos"] = frame_video_runtime.canonical_image_manifest(state.get("photos") or [])
    image_paths: list[str] = []
    for idx, photo in enumerate(state["photos"][:FRAME_VIDEO_MAX_IMAGES], start=1):
        file_id = str(photo.get("file_id") or "")
        path = os.path.join(tmpdir, f"frame_input_{idx:02d}.img")
        if file_id:
            await telegram_file_to_path(context, file_id, path)
            image_paths.append(path)
            continue
        image_url = str(photo.get("image_url") or photo.get("url") or "").strip()
        if image_url:
            await url_to_path(image_url, path, max_bytes=10 * 1024 * 1024)
            image_paths.append(path)
    logo_path = await frame_video_materialize_file(
        context,
        str(state.get("logo_file_id") or ""),
        os.path.join(tmpdir, "frame_logo.img"),
    )
    music_path = await frame_video_materialize_file(
        context,
        str(state.get("music_file_id") or ""),
        os.path.join(tmpdir, "frame_music.audio"),
    )
    voice_path = await frame_video_materialize_file(
        context,
        str(state.get("voice_file_id") or ""),
        os.path.join(tmpdir, "frame_voice.audio"),
    )
    seam_result = await asyncio.to_thread(
        frame_video_public_seam.render_frame_video_public,
        state=state,
        image_paths=image_paths,
        output_path=output_path,
        user_id=int(user_id or 0),
        confirmation_id=str(confirmation_id or state.get("frame_video_job_id") or ""),
        language=str(language or "vi"),
        runtime_sha=str(APP_BUILD_SHA or APP_BUILD or "local"),
        expected_worker_sha=str(APP_BUILD_SHA or APP_BUILD or "local"),
        worker_sha=str(APP_BUILD_SHA or APP_BUILD or "local"),
        worker_instance_id=f"railway-frame-public:{os.getpid()}",
        ffmpeg_path=frame_video_ffmpeg_path(),
        ffprobe_path=ffprobe_path_for_ffmpeg(frame_video_ffmpeg_path()),
        music_path=music_path,
        voice_path=voice_path,
        logo_path=logo_path,
        admin_no_charge=is_admin_user(int(user_id or 0)),
        charge_plan={"policy": "post_delivery", "amount_xu": int(frame_video_planned_charge_xu(state, user_id) or 0)},
        timeout_seconds=frame_video_stage_timeout_for_state(state),
        environ=os.environ,
    )
    if seam_result.get("enabled"):
        return seam_result
    return await render_frame_video_legacy_from_materialized_paths(
        image_paths,
        output_path,
        state,
        music_path=music_path,
        voice_path=voice_path,
        logo_path=logo_path,
    )

async def render_frame_video_preview_from_state(context: ContextTypes.DEFAULT_TYPE, state: dict, output_path: str, tmpdir: str) -> tuple[bool, str]:
    ratio = frame_video_ratio_payload(state.get("ratio") or "9x16")
    effect = frame_video_effect_payload(state.get("effect") or "fade")
    photos = list(state.get("photos") or [])
    preview_count = max(2, min(3, len(photos)))
    preview_seconds = frame_video_paid_preview_seconds(state)
    image_paths: list[str] = []
    for idx, photo in enumerate(photos[:preview_count], start=1):
        file_id = str(photo.get("file_id") or "")
        path = os.path.join(tmpdir, f"frame_preview_input_{idx}.jpg")
        if file_id:
            await telegram_file_to_path(context, file_id, path)
            image_paths.append(path)
            continue
        image_url = str(photo.get("image_url") or photo.get("url") or "").strip()
        if image_url:
            await url_to_path(image_url, path, max_bytes=10 * 1024 * 1024)
            image_paths.append(path)
    return await render_frame_video_paths(
        image_paths,
        output_path,
        max(240, int(ratio["width"]) // 2),
        max(240, int(ratio["height"]) // 2),
        float(preview_seconds / preview_count),
        str(effect["token"]),
    )

