def frame_video_message_media(update: Update) -> tuple[str, object | None]:
    message = getattr(update, "message", None)
    if not message:
        return "", None
    photos = list(getattr(message, "photo", None) or [])
    if photos:
        return "image", photos[-1]
    document = getattr(message, "document", None)
    if document:
        mime = str(getattr(document, "mime_type", "") or "").lower()
        name = str(getattr(document, "file_name", "") or "").lower()
        image_mimes = {"image/jpeg", "image/jpg", "image/png", "image/webp"}
        audio_mimes = {
            "audio/mpeg", "audio/mp3", "audio/wav", "audio/x-wav", "audio/mp4",
            "audio/aac", "audio/ogg", "audio/flac", "audio/x-flac",
        }
        generic_mime = mime in {"", "application/octet-stream"}
        if mime in image_mimes or (generic_mime and name.endswith((".jpg", ".jpeg", ".png", ".webp"))):
            return "image", document
        if mime in audio_mimes or (generic_mime and name.endswith((".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac"))):
            return "audio", document
    audio = getattr(message, "audio", None)
    if audio:
        return "audio", audio
    voice = getattr(message, "voice", None)
    if voice:
        return "audio", voice
    return "", None


def video_edit_recovery_mode(state: dict) -> str:
    """Infer a canonical lane only for a state already owned by Video Edit."""

    mode = video_edit_state_machine.normalize_edit_mode(state.get("edit_mode"))
    if mode:
        return mode
    step = str(state.get("step") or "")
    selected_tool = str(state.get("selected_tool") or "")
    entry_context = str(state.get("entry_context") or "")
    last_section = str(state.get("last_section") or "")
    if entry_context == "quality_enhance" or last_section == "restore":
        return "quality_enhance"
    if selected_tool == "ai_edit" or step in {"await_ai_video", "ai_source_summary", "ai_suggestions"}:
        return "ai_edit"
    if selected_tool in {"manual", "manual_edit"} or step in {
        "await_video", "await_concat", "await_logo", "await_srt", "manual_edit", "options",
    }:
        return "manual_edit"
    return ""


async def recover_product_video_media_failure(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    *,
    handler_name: str,
) -> bool:
    """Contain a media intake failure inside the product that owns the session."""

    message = getattr(update, "message", None)
    user = getattr(update, "effective_user", None)
    if not message or not user:
        return False
    uid = int(user.id)
    lang = get_user_language(uid) or "vi"
    message_id = safe_int(getattr(message, "message_id", 0), 0)

    if handler_name == "handle_video_editor_pending_upload":
        state = dict(get_video_editor_pending(uid) or {})
        if not state:
            return False
        step = str(state.get("step") or "")
        if step == "awaiting_video_tail9_logo":
            if message_id and safe_int(state.get("last_recovery_message_id"), 0) == message_id:
                return True
            update_video_editor_screen(
                uid,
                "logo_input",
                parent_callback="videoedit|overlay",
                state_step="await_logo",
                last_recovery_message_id=message_id,
                awaiting_media=True,
                pending_field="logo",
            )
            await message.reply_text(
                "⚠️ Chưa lưu được logo vừa gửi. Kế hoạch vẫn được giữ; anh/chị hãy gửi lại logo PNG, JPG hoặc WEBP.",
                reply_markup=video_local_input_keyboard(
                    "manual", lang, back_callback="videoedit|overlay"
                ),
            )
            return True

        if step in {"await_logo", "await_srt", "await_concat"}:
            if message_id and safe_int(state.get("last_recovery_message_id"), 0) == message_id:
                return True
            update_video_editor_pending(
                uid,
                step,
                last_recovery_message_id=message_id,
                awaiting_media=True,
            )
            if step == "await_logo":
                logo_parent = video_local_logo_parent_callback(state)
                text = "⚠️ Chưa lưu được logo. Hãy gửi lại PNG, JPG, JPEG hoặc WebP."
                markup = video_local_input_keyboard(
                    "manual", lang, back_callback=logo_parent
                )
            elif step == "await_srt":
                text = "⚠️ Chưa lưu được file SRT. Hãy gửi lại đúng file phụ đề."
                markup = video_local_input_keyboard(
                    "manual", lang, back_callback="videoedit|overlay"
                )
            else:
                text = "⚠️ Chưa lưu được video ghép. Hãy gửi lại video ở đúng bước này."
                markup = video_local_input_keyboard(
                    "manual", lang, back_callback="videoedit|join"
                )
            await message.reply_text(text, reply_markup=markup)
            return True

        mode = video_edit_recovery_mode(state)
        if not mode:
            return False
        if message_id and safe_int(state.get("last_recovery_message_id"), 0) == message_id:
            return True

        if not state.get("source_file_id"):
            waiting = video_edit_state_machine.keep_waiting_after_invalid(
                state,
                "video_edit_intake_runtime_error",
            )
            waiting["last_recovery_message_id"] = message_id
            save_video_edit_canonical_state(uid, waiting)
            await message.reply_text(
                "⚠️ Chưa đọc được video này. Phiên chỉnh sửa vẫn được giữ; anh/chị hãy gửi lại file MP4, MOV, MKV hoặc WebM.",
                reply_markup=video_edit_lane_upload_keyboard(mode, lang),
            )
            return True

        recovered = dict(state)
        recovered.update({
            "step": video_edit_state_machine.ready_screen(mode),
            "edit_mode": mode,
            "current_screen": video_edit_state_machine.ready_screen(mode),
            "return_to": "videoedit|hub",
            "awaiting_media": False,
            "intake_in_progress": False,
            "last_recovery_message_id": message_id,
        })
        if mode == "manual_edit" and not recovered.get("manual_edit_plan"):
            recovered["manual_edit_plan"] = video_local_editing.default_manual_edit_plan("")
        current = save_video_edit_canonical_state(uid, recovered)
        if mode == "manual_edit":
            text = video_local_manual_options_text(current, lang)
            markup = video_local_manual_options_keyboard(lang, current)
        elif mode == "quality_enhance":
            text = video_quality_enhance_source_text(current, lang)
            markup = video_quality_enhance_source_keyboard(lang, current)
        else:
            text = video_ai_edit_source_summary_text(current, lang)
            markup = video_ai_edit_source_summary_keyboard(lang, current)
        await message.reply_text(text, parse_mode="HTML", reply_markup=markup)
        return True

    if handler_name == "handle_frame_video_pending_media":
        raw_state = get_frame_video_state(uid)
        if not raw_state:
            return False
        state = normalize_frame_video_state(raw_state)
        step = str(state.get("step") or "")
        pending = str(state.get("pending_input") or "")
        relevant = {"collect", "replace_image", "logo_upload", "music_upload", "voice_upload"}
        if step not in relevant and pending not in relevant:
            return False
        if message_id and safe_int(state.get("last_media_recovery_message_id"), 0) == message_id:
            return True
        state["last_media_recovery_message_id"] = message_id
        set_frame_video_state(uid, state)
        text, markup, parse_mode = frame_video3_current_screen(state, lang)
        await message.reply_text(
            "⚠️ Chưa mở được tệp vừa gửi. Ảnh và kế hoạch vẫn được giữ nguyên. Anh/chị có thể gửi lại tệp ở đúng màn này.\n\n" + text,
            parse_mode=parse_mode,
            reply_markup=markup,
        )
        return True

    return False


def product_video_media_failure_guard(media_handler):
    """Prevent one Product Video media exception from escaping as generic X."""

    async def guarded(update: Update, context: ContextTypes.DEFAULT_TYPE):
        try:
            return await media_handler(update, context)
        except ApplicationHandlerStop:
            raise
        except Exception as exc:
            if getattr(exc, "_video_editor_state_guard_handled", False):
                return True
            logger.exception("product_video_media_intake_failed handler=%s", getattr(media_handler, "__name__", "unknown"))
            try:
                if await recover_product_video_media_failure(
                    update,
                    context,
                    handler_name=getattr(media_handler, "__name__", ""),
                ):
                    return True
            except Exception:
                logger.exception("product_video_media_intake_recovery_failed handler=%s", getattr(media_handler, "__name__", "unknown"))
                return True
            raise

    guarded.__name__ = getattr(media_handler, "__name__", "product_video_media_handler")
    return guarded


def video_editor_message_state_guard(message_handler):
    """Rollback only this message handler's exact write after reply failure."""

    async def guarded(update: Update, context: ContextTypes.DEFAULT_TYPE):
        user_id = safe_int(
            getattr(getattr(update, "effective_user", None), "id", 0),
            0,
        )
        state_key = video_editor_pending_key(user_id) if user_id else ""
        try:
            restored_state = dict(get_video_editor_pending(user_id) or {}) if user_id else {}
        except VideoEditorStateUnavailableError:
            await notify_video_editor_state_unavailable(
                getattr(update, "message", None)
            )
            return True
        had_state = bool(restored_state)
        snapshot = video_editor_state_snapshot(restored_state)
        guard_snapshot_token = _VIDEO_EDITOR_GUARD_SNAPSHOT.set(snapshot)
        write_token = _VIDEO_EDITOR_STATE_WRITE.set(None)
        try:
            return await message_handler(update, context)
        except VideoEditorStateUnavailableError:
            await notify_video_editor_state_unavailable(
                getattr(update, "message", None)
            )
            return True
        except VideoEditorStateCommitError as exc:
            winner = video_editor_state_snapshot(exc.winner)
            message = getattr(update, "message", None)
            if message is not None and winner:
                await rerender_video_editor_after_stale_commit(
                    message,
                    winner,
                    get_user_language(user_id) or "vi",
                )
            elif message is not None:
                try:
                    await message.reply_text(
                        "⚠️ Không thể lưu phiên Chỉnh sửa video lúc này. Phiên chưa thay đổi; vui lòng thử lại."
                    )
                except Exception:
                    pass
            return True
        except ApplicationHandlerStop:
            raise
        except Exception as exc:
            concurrent_winner_preserved = False
            write_record = _VIDEO_EDITOR_STATE_WRITE.get()
            if state_key and write_record:
                restored, winner = rollback_video_editor_guard_state(
                    user_id,
                    write_record,
                    snapshot,
                    snapshot_exists=had_state,
                )
                concurrent_winner_preserved = not restored
                message = getattr(update, "message", None)
                if not restored and winner and message is not None:
                    try:
                        await rerender_video_editor_after_stale_commit(
                            message,
                            winner,
                            get_user_language(user_id) or "vi",
                        )
                    except Exception:
                        pass
            if concurrent_winner_preserved:
                setattr(exc, "_video_editor_state_guard_handled", True)
            raise
        finally:
            _VIDEO_EDITOR_STATE_WRITE.reset(write_token)
            _VIDEO_EDITOR_GUARD_SNAPSHOT.reset(guard_snapshot_token)

    guarded.__name__ = getattr(message_handler, "__name__", "video_editor_message_handler")
    guarded.__wrapped__ = message_handler
    return guarded


@product_video_media_failure_guard
async def handle_frame_video_pending_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message:
        return False
    uid = update.effective_user.id
    state = normalize_frame_video_state(get_frame_video_state(uid)) if get_frame_video_state(uid) else {}
    if not state:
        return False
    pending = str(state.get("pending_input") or "")
    step = str(state.get("step") or "")
    if step not in {"collect", "replace_image", "logo_upload", "music_upload", "voice_upload"} and pending not in {
        "replace_image", "logo_upload", "music_upload", "voice_upload"
    }:
        return False
    state, fresh = frame_video_flow.mark_media_message_processed(state, getattr(update.message, "message_id", ""))
    if not fresh:
        return True
    kind, media = frame_video_message_media(update)
    expected = "audio" if (pending or step) in {"music_upload", "voice_upload"} else "image"
    if not media or kind != expected:
        set_frame_video_state(uid, state)
        await update.message.reply_text(
            "⚠️ File chưa đúng loại. Hãy gửi ảnh JPG/PNG/WebP." if expected == "image" else "⚠️ File chưa đúng loại. Hãy gửi MP3/WAV/M4A/AAC/OGG/FLAC.",
        )
        return True
    file_id = str(getattr(media, "file_id", "") or "")
    file_size = int(getattr(media, "file_size", 0) or 0)
    if not file_id:
        set_frame_video_state(uid, state)
        await update.message.reply_text("⚠️ Không đọc được file này. Anh/chị gửi lại file khác nhé.")
        return True
    target = pending or step
    if target in {"collect", "replace_image"}:
        item = {
            "file_id": file_id,
            "file_unique_id": str(getattr(media, "file_unique_id", "") or ""),
            "file_size": file_size,
            "mime_type": str(getattr(media, "mime_type", "") or "image/jpeg"),
            "source_message_id": str(getattr(update.message, "message_id", "") or ""),
        }
        if target == "replace_image":
            selected = str(state.get("selected_image_id") or "")
            state["photos"] = frame_video_runtime.manifest_replace(state.get("photos") or [], selected, item)
            state["duration_confirmed"] = False
            state["pending_input"] = ""
            state["step"] = "images"
            state = normalize_frame_video_state(state)
            set_frame_video_state(uid, state)
            await update.message.reply_text(frame_video_images_text(state), parse_mode="HTML", reply_markup=frame_video_images_keyboard(state))
            return True
        selected_count = _safe_int(state.get("image_count"), 0)
        max_allowed = selected_count if selected_count >= 2 else FRAME_VIDEO_MAX_IMAGES
        if len(state.get("photos") or []) >= max_allowed:
            set_frame_video_state(uid, state)
            await update.message.reply_text(
                f"Đã đủ {max_allowed}/{max_allowed} ảnh. Bấm ✅ Xong phần ảnh để tiếp tục.",
                reply_markup=frame_video_collect_keyboard("framevideo|ratio_first_menu" if selected_count >= 2 else "framevideo|hub", state),
            )
            return True
        state = frame_video_flow.add_photo(state, item)
        state["step"] = "collect"
        set_frame_video_state(uid, state)
        await update.message.reply_text(
            frame_video_collect_text(len(state["photos"]), selected_count),
            reply_markup=frame_video_collect_keyboard("framevideo|ratio_first_menu" if selected_count >= 2 else "framevideo|hub", state),
        )
        return True
    if target == "logo_upload":
        return_to = str(state.get("addon_return_to") or "addons")
        if is_frame_video3_state(state):
            state.update({
                "logo_file_id": file_id,
                "logo_file_size": file_size,
                "pending_brand_kind": "logo",
                "pending_brand_position": str(state.get("logo_position") or "top_right"),
                "pending_input": "",
                "step": "logo_position",
            })
            set_frame_video_state(uid, state)
            await update.message.reply_text(
                "✅ Đã nhận ảnh logo. Hãy chọn vị trí rồi xác nhận lưu.",
                reply_markup=frame_video_position_keyboard("logo", "framevideo|branding"),
            )
            return True
        state.update({"logo_enabled": True, "logo_file_id": file_id, "logo_file_size": file_size, "pending_input": "", "step": "addons"})
        set_frame_video_state(uid, state)
        await update.message.reply_text(
            "✅ Đã nhận logo. Chọn vị trí logo.",
            reply_markup=frame_video_position_keyboard(
                "logo",
                "framevideo|audio_menu" if return_to == "audio_menu" else "framevideo|addons",
            ),
        )
        return True
    audio_key = "music" if target == "music_upload" else "voice"
    stored_return_to = state.get("music_return_to") if audio_key == "music" else state.get("addon_return_to")
    return_to = str(
        stored_return_to
        or ("audio_menu" if is_frame_video3_state(state) else ("music_menu" if audio_key == "music" else "addons"))
    )
    state.update({
        f"{audio_key}_enabled": True,
        f"{audio_key}_file_id": file_id,
        f"{audio_key}_file_size": file_size,
        "pending_input": "",
        "step": "music" if audio_key == "music" else ("audio" if return_to == "audio_menu" else "addons"),
    })
    set_frame_video_state(uid, state)
    if audio_key == "music":
        back_callback = {
            "audio_menu": "framevideo|audio_menu",
            "addons": "framevideo|addons",
            "panel": "framevideo|panel",
        }.get(return_to, "framevideo|panel")
        await update.message.reply_text(
            frame_video_music_menu_text(state),
            parse_mode="HTML",
            reply_markup=frame_video_music_menu_keyboard(state, back_callback),
        )
    else:
        await update.message.reply_text(
            f"✅ Đã nhận file lồng tiếng. Âm lượng hiện tại {int(state.get('voice_volume_percent') or 100)}%.",
            reply_markup=frame_video_volume_keyboard(
                "voice",
                "framevideo|audio_menu" if return_to == "audio_menu" else "framevideo|addons",
            ),
        )
    return True

async def handle_frame_video_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message or not update.message.text:
        return False
    uid = update.effective_user.id
    state = get_frame_video_state(uid)
    if not state:
        return False
    state = normalize_frame_video_state(state)
    step = str(state.get("step") or "")
    text = update.message.text.strip()
    if step == "image_count_custom":
        count = _safe_int(text, 0)
        if count < 2 or count > FRAME_VIDEO_MAX_IMAGES:
            await update.message.reply_text(f"⚠️ Số ảnh hợp lệ là 2-{FRAME_VIDEO_MAX_IMAGES}. Hãy nhập lại.")
            return True
        state.update({
            "image_count": count,
            "ai_image_count": count,
            "step": "ratio_first",
            "pending_input": "",
        })
        set_frame_video_state(uid, state)
        await update.message.reply_text(
            ivf.frame_video_ratio_first_text(str(state.get("ratio") or "9x16"), get_user_language(uid) or "vi")
            + f"\n\nĐã chọn <b>{count} ảnh</b>.",
            parse_mode="HTML",
            reply_markup=ivf.frame_video_ratio_first_keyboard(get_user_language(uid) or "vi"),
        )
        return True
    if step == "image_caption_input":
        if is_frame_video3_state(state):
            state.update({"step": "images", "pending_input": ""})
            set_frame_video_state(uid, state)
            await update.message.reply_text(
                frame_video_images_text(state)
                + "\n\nNút ghi chú ảnh cũ đã được bỏ khỏi quy trình.",
                parse_mode="HTML",
                reply_markup=frame_video_images_keyboard(state),
            )
            return True
        content = " ".join(text.split())[:1000]
        if not content:
            await update.message.reply_text("⚠️ Ghi chú đang trống. Anh/chị nhập lại nhé.")
            return True
        try:
            state = frame_video_flow.update_selected_image(state, caption=content)
        except ValueError:
            state.update({"step": "images", "pending_input": ""})
            set_frame_video_state(uid, state)
            await update.message.reply_text(
                "⚠️ Ảnh đang chọn không còn trong kế hoạch.",
                reply_markup=frame_video_images_keyboard(state),
            )
            return True
        state.update({"step": "images", "pending_input": ""})
        set_frame_video_state(uid, state)
        await update.message.reply_text(
            frame_video_images_text(state),
            parse_mode="HTML",
            reply_markup=frame_video_images_keyboard(state),
        )
        return True
    if step == "ratio_first_custom":
        match = re.fullmatch(r"\s*(\d{1,4})\s*[xX:]\s*(\d{1,4})\s*", text)
        if not match:
            await update.message.reply_text("⚠️ Nhập theo dạng 9:16 hoặc 1080x1920.")
            return True
        first, second = int(match.group(1)), int(match.group(2))
        if first <= 0 or second <= 0 or first > 4096 or second > 4096:
            await update.message.reply_text("⚠️ Tỉ lệ hoặc kích thước chưa hợp lệ. Hãy nhập lại.")
            return True
        known = {(9, 16): "9x16", (16, 9): "16x9", (1, 1): "1x1", (4, 5): "4x5"}
        ratio = known.get((first, second), "custom")
        if ratio == "custom":
            width, height = first, second
            if width < 100 or height < 100:
                width, height = width * 100, height * 100
            state.update({"ratio": "custom", "custom_width": width, "custom_height": height})
        else:
            state.update({"ratio": ratio, "custom_width": 0, "custom_height": 0})
        text_next, markup_next, next_step = frame_video3_after_ratio(state, get_user_language(uid) or "vi")
        state.update({"step": next_step, "pending_input": ""})
        set_frame_video_state(uid, state)
        await update.message.reply_text(text_next, parse_mode="HTML", reply_markup=markup_next)
        return True
    if step in {"duration_custom", "image_duration_custom", "transition_time_custom", "volume_custom"}:
        if step == "image_duration_custom" and is_frame_video3_state(state):
            state.update({"step": "duration", "pending_input": ""})
            set_frame_video_state(uid, state)
            await update.message.reply_text(
                frame_video_duration_menu_text(state),
                parse_mode="HTML",
                reply_markup=frame_video_duration_menu_keyboard(False, state),
            )
            return True
        raw = text.replace(",", ".").replace("%", "").strip()
        try:
            value = float(raw)
        except Exception:
            value = -1
        if step == "volume_custom":
            if value < 0 or value > 200:
                await update.message.reply_text("⚠️ Nhập âm lượng từ 0 đến 200%.")
                return True
            kind = str(state.get("pending_volume_kind") or "music")
            state = frame_video_flow.set_volume(state, kind, int(value))
            return_to = str(
                state.get("pending_return_to")
                or ("audio_menu" if is_frame_video3_state(state) else ("music_menu" if kind == "music" else "addons"))
            )
            state.update({"step": "audio" if return_to == "audio_menu" else ("music" if return_to == "music_menu" else "addons"), "pending_volume_kind": "", "pending_return_to": ""})
            set_frame_video_state(uid, state)
            if return_to == "audio_menu":
                await update.message.reply_text(
                    f"✅ Đã đặt âm lượng {int(value)}%.",
                    reply_markup=frame_video_audio_menu_keyboard(state),
                )
                return True
            await update.message.reply_text(
                f"✅ Đã đặt âm lượng {int(value)}%.",
                reply_markup=frame_video_music_menu_keyboard(state) if kind == "music" else frame_video_addons_keyboard(state),
            )
            return True
        if step == "transition_time_custom":
            if value < 0.1 or value > 1.5:
                await update.message.reply_text("⚠️ Nhập thời gian nối cảnh từ 0,1 đến 1,5 giây.")
                return True
            state.update({"transition_seconds": round(value, 2), "step": "transition"})
            set_frame_video_state(uid, state)
            await update.message.reply_text("✅ Đã cập nhật độ dài điểm nối.", reply_markup=frame_video_transition_keyboard(state))
            return True
        if value < 0.5 or value > 30:
            await update.message.reply_text("⚠️ Nhập thời lượng từ 0,5 đến 30 giây.")
            return True
        state = frame_video_flow.set_selected_duration(state, value) if step == "image_duration_custom" else frame_video_flow.set_global_duration(state, value)
        is_framevideo3 = is_frame_video3_state(state)
        state["step"] = "images" if step == "image_duration_custom" else ("duration" if is_framevideo3 else "panel")
        set_frame_video_state(uid, state)
        if step != "image_duration_custom" and is_framevideo3:
            await update.message.reply_text(
                frame_video_duration_menu_text(state),
                parse_mode="HTML",
                reply_markup=frame_video_duration_menu_keyboard(False, state),
            )
            return True
        await update.message.reply_text(
            frame_video_images_text(state) if step == "image_duration_custom" else frame_video_panel_text(state),
            parse_mode="HTML",
            reply_markup=frame_video_images_keyboard(state) if step == "image_duration_custom" else frame_video_panel_keyboard(),
        )
        return True
    if step == "ratio_custom":
        match = re.fullmatch(r"\s*(\d{2,4})\s*[xX:]\s*(\d{2,4})\s*", text)
        if not match:
            await update.message.reply_text("⚠️ Nhập theo dạng 1080x1920 hoặc 9:16.")
            return True
        width, height = int(match.group(1)), int(match.group(2))
        if width < 100 or height < 100:
            width, height = width * 100, height * 100
        state.update({"ratio": "custom", "custom_width": width, "custom_height": height, "step": "panel"})
        set_frame_video_state(uid, state)
        await update.message.reply_text(frame_video_panel_text(state), parse_mode="HTML", reply_markup=frame_video_panel_keyboard())
        return True
    if step == "text_timing_input":
        match = re.fullmatch(r"\s*(\d+(?:[.,]\d+)?)\s*-\s*(\d+(?:[.,]\d+)?)\s*", text)
        total = frame_video_runtime.expected_duration_seconds(state)
        if not match:
            await update.message.reply_text("⚠️ Nhập theo dạng bắt đầu-kết thúc, ví dụ 1.5-4.")
            return True
        start = float(match.group(1).replace(",", "."))
        end = float(match.group(2).replace(",", "."))
        if start < 0 or end <= start or end > total + 0.001:
            await update.message.reply_text(f"⚠️ Thời điểm phải nằm trong 0-{total:g} giây và kết thúc phải sau bắt đầu.")
            return True
        try:
            state = frame_video_flow.update_selected_text(state, image_id="", start_seconds=start, end_seconds=end)
        except ValueError:
            await update.message.reply_text("⚠️ Mục chữ không còn tồn tại. Hãy chọn lại.", reply_markup=frame_video_text_list_keyboard(state))
            return True
        state.update({"step": "text_editor", "pending_input": ""})
        set_frame_video_state(uid, state)
        await update.message.reply_text(frame_video_text_editor_text(state), parse_mode="HTML", reply_markup=frame_video_text_editor_keyboard())
        return True
    if step in {"watermark_input", "subtitle_input", "text_input", "text_edit_input"}:
        # All four land in an FFmpeg drawtext/subtitles filter later.
        content = ffmpeg_text.sanitize_overlay_text(text, 500)
        if not content:
            await update.message.reply_text("⚠️ Nội dung đang trống. Anh/chị nhập lại nhé.")
            return True
        if step == "watermark_input":
            if is_frame_video3_state(state):
                state.update({
                    "watermark_text": content,
                    "pending_brand_kind": "watermark",
                    "pending_brand_position": str(state.get("watermark_position") or "top_right"),
                    "pending_input": "",
                    "step": "watermark_position",
                })
                set_frame_video_state(uid, state)
                await update.message.reply_text(
                    "✅ Đã nhận watermark chữ. Hãy chọn vị trí rồi xác nhận lưu.",
                    reply_markup=frame_video_position_keyboard("watermark", "framevideo|branding"),
                )
                return True
            state.update({"watermark_enabled": True, "watermark_text": content, "step": "addons"})
            set_frame_video_state(uid, state)
            await update.message.reply_text("✅ Đã lưu watermark. Chọn vị trí hiển thị.", reply_markup=frame_video_position_keyboard("watermark"))
            return True
        if step == "subtitle_input":
            return_to = str(state.get("addon_return_to") or "addons")
            state.update({
                "subtitle_enabled": True,
                "subtitle_text": content,
                "subtitle_position": "bottom_center",
                "step": "audio" if return_to == "audio_menu" else "addons",
                "pending_input": "",
            })
            state = frame_video_flow.sync_render_overlays(state)
            set_frame_video_state(uid, state)
            await update.message.reply_text(
                frame_video_audio_menu_text(state) if return_to == "audio_menu" else frame_video_addons_text(state),
                parse_mode="HTML",
                reply_markup=frame_video_audio_menu_keyboard(state) if return_to == "audio_menu" else frame_video_addons_keyboard(state),
            )
            return True
        if step == "text_edit_input":
            try:
                state = frame_video_flow.update_selected_text(state, content=content)
            except ValueError:
                await update.message.reply_text("⚠️ Mục chữ không còn tồn tại. Hãy chọn lại.", reply_markup=frame_video_text_list_keyboard(state))
                return True
            state.update({"step": "text_editor", "pending_input": ""})
            set_frame_video_state(uid, state)
            await update.message.reply_text(frame_video_text_editor_text(state), parse_mode="HTML", reply_markup=frame_video_text_editor_keyboard())
            return True
        state = frame_video_flow.add_text_overlay(state, content)
        state.update({"step": "text_editor", "pending_input": ""})
        set_frame_video_state(uid, state)
        await update.message.reply_text("✅ Đã thêm chữ. Chọn vị trí hiển thị.", reply_markup=frame_video_position_keyboard("text"))
        return True
    if step == "ai_prompt":
        prompt = " ".join(text.split())
        if len(prompt) < 3:
            await update.message.reply_text("⚠️ Prompt hơi ngắn. Anh/chị nhập rõ chủ đề ảnh muốn tạo nhé.")
            return True
        state["ai_prompt"] = img2vid_ai_prompt_from_topic(prompt)
        state["ai_prompt_source"] = "custom"
        state["step"] = "ai_prepared"
        state = frame_video_sync_ai_image_prompts(state, force=True)
        set_frame_video_state(uid, state)
        await update.message.reply_text(
            ivf.frame_video_ai_prompt_text(state.get("ai_prompt") or "", get_user_language(uid) or "vi"),
            parse_mode="HTML",
            reply_markup=img2vid_ai_prompt_review_keyboard(state, get_user_language(uid) or "vi"),
        )
        return True
    if step == "ai_prompt_image_input":
        index = _safe_int(state.get("selected_ai_prompt_index"), 0)
        if index <= 0 or len(text) < 3:
            await update.message.reply_text("⚠️ Prompt hơi ngắn hoặc ảnh không hợp lệ. Anh/chị nhập lại nhé.")
            return True
        try:
            state = frame_video_flow.update_ai_image_prompt(state, index, text)
        except ValueError:
            await update.message.reply_text(
                "⚠️ Không tìm thấy prompt ảnh đang sửa. Hãy mở lại danh sách prompt.",
                reply_markup=img2vid_ai_prompt_set_keyboard(state),
            )
            return True
        state.update({"step": "ai_prompt_image", "pending_input": ""})
        set_frame_video_state(uid, state)
        await update.message.reply_text(
            img2vid_ai_prompt_image_text(state),
            parse_mode="HTML",
            reply_markup=img2vid_ai_prompt_image_keyboard(state),
        )
        return True
    if step == "ai_count_custom":
        count = _safe_int(text, 0)
        if count < 2 or count > IMG2VID_AI_IMAGE_MAX_COUNT:
            await update.message.reply_text(f"⚠️ Số ảnh hợp lệ là 2-{IMG2VID_AI_IMAGE_MAX_COUNT}.")
            return True
        state["ai_image_count"] = count
        if str(state.get("commercial_flow_version") or "") == "framevideo3":
            state["image_count"] = count
        state["ai_image_tier"] = ""
        state["ai_image_prompts"] = []
        state["selected_ai_prompt_index"] = 1
        state["image_generation_price"] = 0
        state["step"] = "ai_entry"
        set_frame_video_state(uid, state)
        await update.message.reply_text(
            ivf.frame_video_ai_first_guard_text(get_user_language(uid) or "vi")
            + f"\n\nĐã chọn: <b>{count} ảnh</b>. Bây giờ chọn gợi ý hoặc tự nhập prompt.",
            parse_mode="HTML",
            reply_markup=ivf.frame_video_ai_first_keyboard(get_user_language(uid) or "vi"),
        )
        return True
    if step == "seconds_custom":
        raw = text.replace(",", ".")
        try:
            seconds = float(raw)
        except Exception:
            seconds = 0.0
        if seconds <= 0 or seconds > 30:
            await update.message.reply_text("⚠️ Nhập số giây mỗi ảnh từ 1 đến 30.")
            return True
        state = invalidate_frame_video_paid_preview(state)
        state["seconds_per_image"] = round(seconds, 2)
        state["duration"] = "custom"
        state["ratio"] = state.get("ratio") or "9x16"
        state["effect"] = state.get("effect") or "fade"
        state["music_choice"] = "skip"
        state["music_merge_enabled"] = False
        state["voice_choice"] = "skip"
        state["voice_merge_enabled"] = False
        state["step"] = "confirm"
        set_frame_video_state(uid, state)
        await update.message.reply_text(img2vid_slideshow_confirm_text(state, uid), parse_mode="HTML", reply_markup=img2vid_slideshow_confirm_keyboard())
        return True
    return False

async def render_video_with_audio(update: Update, context: ContextTypes.DEFAULT_TYPE, video_info: dict, audio_info: dict, mode: str):
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return await update.message.reply_text("⚠️ Hệ thống chưa sẵn sàng để ghép nhạc hoặc giọng đọc vào video. TOAN AAS chưa trừ Xu.")
    if not video_info:
        return await update.message.reply_text("⚠️ Chưa có video. Hãy gửi video hoặc reply video rồi dùng lệnh này. Bot chưa trừ Xu.")
    if not audio_info:
        return await update.message.reply_text("⚠️ Chưa có audio/nhạc. Hãy chọn nhạc bằng /select_music hoặc gửi audio rồi dùng lại lệnh. Bot chưa trừ Xu.")
    with tempfile.TemporaryDirectory() as tmpdir:
        video_path = await materialize_media_source(context, video_info, tmpdir, ".mp4")
        audio_path = await materialize_media_source(context, audio_info, tmpdir, ".mp3")
        out_path = os.path.join(tmpdir, f"toan_aas_{mode}.mp4")
        cmd = [
            ffmpeg, "-y",
            "-i", video_path,
            "-i", audio_path,
            "-map", "0:v:0",
            "-map", "1:a:0",
            "-c:v", "copy",
            "-c:a", "aac",
            "-shortest",
            out_path,
        ]
        ok, detail = await run_ffmpeg_command(cmd)
        if not ok or not os.path.exists(out_path):
            safe_detail = html.escape(str(detail or "ffmpeg_failed")[:300])
            return await update.message.reply_text(
                "❌ Render video chưa thành công trong admin test.\n"
                f"Admin detail: <code>{safe_detail}</code>\n\n"
                "Bot chưa trừ Xu.",
                parse_mode="HTML",
            )
        caption = "✅ Đã ghép nhạc vào video." if mode == "add_music" else "✅ Đã ghép voice/audio vào video."
        with open(out_path, "rb") as f:
            await context.bot.send_video(chat_id=update.effective_chat.id, video=f, caption=f"{caption}\nBot chưa trừ Xu trong admin test.")

async def render_image_music_video(update: Update, context: ContextTypes.DEFAULT_TYPE, image_info: dict, audio_info: dict):
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return await update.message.reply_text("⚠️ Server chưa có ffmpeg. Admin cần cài ffmpeg để tạo video từ ảnh + nhạc. Bot chưa trừ Xu.")
    if not image_info:
        return await update.message.reply_text("⚠️ Chưa có ảnh. Hãy gửi ảnh hoặc reply ảnh rồi dùng /image_to_music_video. Bot chưa trừ Xu.")
    with tempfile.TemporaryDirectory() as tmpdir:
        image_path = await materialize_media_source(context, image_info, tmpdir, ".jpg")
        out_path = os.path.join(tmpdir, "toan_aas_image_music.mp4")
        if audio_info:
            audio_path = await materialize_media_source(context, audio_info, tmpdir, ".mp3")
            cmd = [
                ffmpeg, "-y",
                "-loop", "1",
                "-i", image_path,
                "-i", audio_path,
                "-t", "30",
                "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p",
                "-c:v", "libx264",
                "-c:a", "aac",
                "-shortest",
                out_path,
            ]
        else:
            cmd = [
                ffmpeg, "-y",
                "-loop", "1",
                "-t", "10",
                "-i", image_path,
                "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p",
                "-c:v", "libx264",
                out_path,
            ]
        ok, detail = await run_ffmpeg_command(cmd)
        if not ok or not os.path.exists(out_path):
            safe_detail = html.escape(str(detail or "ffmpeg_failed")[:300])
            return await update.message.reply_text(
                "❌ Tạo video từ ảnh + nhạc chưa thành công trong admin test.\n"
                f"Admin detail: <code>{safe_detail}</code>\n\n"
                "Bot chưa trừ Xu.",
                parse_mode="HTML",
            )
        with open(out_path, "rb") as f:
            await context.bot.send_video(chat_id=update.effective_chat.id, video=f, caption="✅ Đã tạo video từ ảnh và nhạc.\nBot chưa trừ Xu trong admin test.")

