def format_admin_report(payload: dict) -> str:
    users = payload["users"]
    money = payload["money"]
    credits = payload["credits"]
    tools = payload["tools"]
    providers = payload["providers"]
    growth = payload["growth"]
    success_rate = 0
    if int(tools["success"] or 0) + int(tools["fail"] or 0) > 0:
        success_rate = round((int(tools["success"] or 0) / (int(tools["success"] or 0) + int(tools["fail"] or 0))) * 100, 1)
    top_tool_lines = [f"• {html.escape(str(name or 'unknown'))}: <b>{int(count or 0)}</b>" for name, count in tools["top_tools"]]
    top_command_lines = [f"• <code>{html.escape(str(cmd or '-'))}</code>: <b>{int(count or 0)}</b>" for cmd, count in tools["top_commands"]]
    provider_lines = [
        f"• {html.escape(str(provider or 'unknown'))}/{html.escape(str(status or '-'))}: <b>{int(count or 0)}</b>"
        for provider, status, count in providers["rows"]
    ]
    lines = [
        f"📊 <b>TOAN AAS — BÁO CÁO {html.escape(payload['label']).upper()}</b>",
        f"<code>{html.escape(payload['start_at'])}</code> → <code>{html.escape(payload['end_at'])}</code>",
        "",
        "<b>Users</b>",
        f"• Tổng user: <b>{users['total']}</b>",
        f"• User mới: <b>{users['new']}</b>",
        f"• User active: <b>{users['active']}</b>",
        f"• User quay lại: <b>{users['returning']}</b>",
        "",
        "<b>Doanh thu / Xu</b>",
        f"• Tổng thu: <b>{vnd_text(money['total_amount'])}</b> ({money['total_count']} giao dịch)",
        f"• PayOS: <b>{vnd_text(money['payos_amount'])}</b> ({money['payos_count']} giao dịch)",
        f"• Manual QR: <b>{vnd_text(money['manual_amount'])}</b> ({money['manual_count']} giao dịch)",
        f"• Xu đã bán theo đơn: <b>{xu_text(money['xu_sold'])}</b>",
        f"• Bill chờ duyệt: <b>{money['pending_deposits']}</b>",
        f"• Xu cộng trong kỳ: <b>{xu_text(credits['added'])}</b>",
        f"• Xu trừ trong kỳ: <b>{xu_text(credits['spent'])}</b>",
        f"• Xu đang lưu hành: <b>{xu_text(credits['circulating'])}</b>",
        "",
        "<b>Công cụ</b>",
        f"• Lượt gọi tool: <b>{tools['requested']}</b>",
        f"• Thành công: <b>{tools['success']}</b>",
        f"• Lỗi: <b>{tools['fail']}</b>",
        f"• Tỷ lệ thành công: <b>{success_rate}%</b>",
        f"• AI chat lượt: <b>{tools.get('ai_chat_total', 0)}</b>",
        f"• AI chat success: <b>{tools.get('ai_chat_success', 0)}</b>",
        f"• AI chat fail: <b>{tools.get('ai_chat_fail', 0)}</b>",
        f"• Xu chat đã trừ: <b>{xu_text(tools.get('ai_chat_xu_spent', 0))}</b>",
        "",
        "<b>Trial / Promo</b>",
        f"• Trial đã cấp: <b>{growth['trial_grants']}</b>",
        f"• Promo/Gift/Launch events: <b>{growth['promo_events']}</b>",
        "",
        "<b>Referral</b>",
        f"• Ref starts: <b>{growth.get('ref_starts', 0)}</b>",
        f"• Qualified first deposits: <b>{growth.get('ref_qualified', 0)}</b>",
        f"• Referral rewards paid: <b>{growth.get('ref_rewards_paid', 0)}</b>",
        f"• Referral Xu rewarded: <b>{xu_text(growth.get('ref_xu_rewarded', 0))}</b>",
        "",
        "<b>Member / Birthday</b>",
        f"• Tier ups: <b>{growth.get('tier_ups', 0)}</b>",
        f"• Tier promo created/used: <b>{growth.get('tier_promos_created', 0)}</b>/<b>{growth.get('tier_promos_used', 0)}</b>",
        f"• Tier promo Xu bonus: <b>{xu_text(growth.get('tier_promo_xu', 0))}</b>",
        f"• Birthday pending review: <b>{growth.get('birthday_pending', 0)}</b>",
        f"• Birthday gifts: <b>{growth.get('birthday_gifts', 0)}</b>",
        f"• Birthday Xu gifted: <b>{xu_text(growth.get('birthday_xu', 0))}</b>",
        "",
        "<b>Provider</b>",
        f"• Provider error/debug fail: <b>{providers['errors']}</b>",
    ]
    if provider_lines:
        lines.extend(provider_lines[:5])
    if top_tool_lines:
        lines.extend(["", "<b>Top tools</b>", *top_tool_lines[:6]])
    if top_command_lines:
        lines.extend(["", "<b>Top commands</b>", *top_command_lines[:6]])
    lines.append("")
    lines.append("Lệnh AI insight: <code>/report_ai_today</code> | chart: <code>/report_chart_week</code>")
    return "\n".join(lines[:120])

def admin_report_plain(payload: dict) -> str:
    text = format_admin_report(payload)
    text = re.sub(r"<[^>]+>", "", text)
    return html.unescape(text)

def offline_admin_insight(payload: dict, ai_error: str = "") -> str:
    users = payload.get("users") or {}
    money = payload.get("money") or {}
    tools = payload.get("tools") or {}
    providers = payload.get("providers") or {}
    growth = payload.get("growth") or {}
    requested = int(tools.get("requested") or 0)
    success = int(tools.get("success") or 0)
    fail = int(tools.get("fail") or 0)
    provider_errors = int(providers.get("errors") or 0)
    revenue = int(money.get("total_amount") or 0)
    active = int(users.get("active") or 0)
    new_users = int(users.get("new") or 0)
    success_rate = 0.0
    if success + fail > 0:
        success_rate = round(success / (success + fail) * 100, 1)
    good_points = []
    if active > 0:
        good_points.append("Bot có hoạt động thực tế trong kỳ.")
    if success_rate >= 80:
        good_points.append(f"Tỷ lệ tool thành công đang khá ổn ({success_rate}%).")
    if revenue > 0:
        good_points.append(f"Đã có doanh thu: {vnd_text(revenue)}.")
    if int(growth.get("trial_grants") or 0) > 0 or new_users > 0:
        good_points.append("Có user mới/trial mới, onboarding vẫn có tín hiệu.")
    if not good_points:
        good_points.append("Chưa có tín hiệu mạnh; cần test thực tế và kéo user dùng lại.")
    risks = []
    if provider_errors > 0 or fail > 0:
        risks.append("Có lỗi provider/tool, cần ưu tiên kiểm tra tool lỗi nhiều nhất.")
    if revenue <= 0:
        risks.append("Doanh thu bằng 0, cần thúc đẩy nạp Xu/manual QR hoặc ưu đãi hợp lệ.")
    if active <= 1:
        risks.append("Active user thấp, cần cải thiện onboarding và nhắc user dùng thử.")
    if int(money.get("pending_deposits") or 0) > 0:
        risks.append("Có bill chờ duyệt, cần xử lý để không mất niềm tin khách.")
    if not risks:
        risks.append("Chưa thấy rủi ro lớn từ số liệu hiện có; tiếp tục theo dõi provider và thanh toán.")
    actions = [
        "Fix hoặc khóa provider đang lỗi nhiều nhất trước khi mở cho khách.",
        "Test lại flow nạp Xu: manual QR trước, PayOS debug sau.",
        "Theo dõi user mới/active ngày mai và nhắc dùng /film hoặc công cụ đã PASS.",
    ]
    if revenue <= 0:
        actions.insert(0, "Đăng/tư vấn gói dùng thử và hướng khách nạp 50k/100k nếu tool đã ổn.")
    return "\n".join([
        "⚠️ AI provider đang hết quota/tạm lỗi, hệ thống dùng đánh giá nội bộ tạm thời.",
        (f"<i>Lỗi AI: {html.escape(str(ai_error)[:180])}</i>" if ai_error else ""),
        "",
        "<b>1. Tổng quan</b>",
        f"• Users: <b>{int(users.get('total') or 0)}</b>",
        f"• Active users: <b>{active}</b>",
        f"• User mới: <b>{new_users}</b>",
        f"• Doanh thu: <b>{vnd_text(revenue)}</b>",
        f"• Tool calls: <b>{requested}</b> | success <b>{success}</b> | fail <b>{fail}</b>",
        f"• Provider errors: <b>{provider_errors}</b>",
        "",
        "<b>2. Điểm tốt</b>",
        *[f"• {item}" for item in good_points],
        "",
        "<b>3. Rủi ro</b>",
        *[f"• {item}" for item in risks],
        "",
        "<b>4. Hành động ưu tiên</b>",
        *[f"{idx}. {item}" for idx, item in enumerate(actions[:4], 1)],
    ])

def report_chart_payload(start_at: str, end_at: str, label: str) -> str:
    conn = db_connect()
    try:
        start_dt = datetime.strptime(start_at[:10], "%Y-%m-%d")
        end_dt = datetime.strptime(end_at[:10], "%Y-%m-%d")
        days = []
        cursor = start_dt
        while cursor <= end_dt and len(days) < 370:
            days.append(cursor.strftime("%Y-%m-%d"))
            cursor += timedelta(days=1)
        revenue_rows = dict(sql_rows(
            conn,
            """SELECT substr(paid_at,1,10), COALESCE(SUM(amount),0)
            FROM payos_orders WHERE status=? AND paid_at BETWEEN ? AND ?
            GROUP BY substr(paid_at,1,10)""",
            (PAYOS_STATUS_PAID, start_at, end_at),
        ))
        manual_rows = dict(sql_rows(
            conn,
            """SELECT substr(created_at,1,10), COALESCE(SUM(amount_vnd),0)
            FROM usage_events WHERE event_type='payment_manual_approved' AND created_at BETWEEN ? AND ?
            GROUP BY substr(created_at,1,10)""",
            (start_at, end_at),
        ))
        user_rows = dict(sql_rows(
            conn,
            """SELECT substr(created_at,1,10), COUNT(DISTINCT user_id)
            FROM usage_events WHERE created_at BETWEEN ? AND ?
            GROUP BY substr(created_at,1,10)""",
            (start_at, end_at),
        ))
        tool_rows = dict(sql_rows(
            conn,
            """SELECT substr(created_at,1,10), COUNT(*)
            FROM usage_events WHERE event_type IN ('tool_use','tool_success','tool_fail') AND created_at BETWEEN ? AND ?
            GROUP BY substr(created_at,1,10)""",
            (start_at, end_at),
        ))
        values = {
            day: int(revenue_rows.get(day, 0) or 0) + int(manual_rows.get(day, 0) or 0)
            for day in days
        }
        max_revenue = max(values.values()) if values else 0
        max_active = max([int(user_rows.get(day, 0) or 0) for day in days] or [0])
        max_tools = max([int(tool_rows.get(day, 0) or 0) for day in days] or [0])
        def bar(value, max_value, width=12):
            value = int(value or 0)
            max_value = int(max_value or 0)
            if max_value <= 0 or value <= 0:
                return "·"
            filled = max(1, min(width, round((value / max_value) * width)))
            return "█" * filled
        lines = [
            f"📈 <b>TOAN AAS Chart — {html.escape(label)}</b>",
            "<code>Ngày | Doanh thu | Active | Tool</code>",
            "",
        ]
        for day in days[-31:]:
            revenue = values.get(day, 0)
            active = int(user_rows.get(day, 0) or 0)
            tool_count = int(tool_rows.get(day, 0) or 0)
            lines.append(
                f"<code>{day}</code> {bar(revenue, max_revenue)} {vnd_text(revenue)} | "
                f"{bar(active, max_active, 8)} {active} | {bar(tool_count, max_tools, 8)} {tool_count}"
            )
        if len(days) > 31:
            lines.append("")
            lines.append("<i>Chart text fallback chỉ hiển thị 31 ngày cuối để không vượt giới hạn Telegram.</i>")
        return "\n".join(lines)
    finally:
        conn.close()

def month_report_bounds(month_arg: str = "") -> tuple[str, str, str]:
    raw = (month_arg or "").strip()
    if raw:
        dt = datetime.strptime(raw, "%Y-%m")
    else:
        now = datetime.now()
        dt = datetime(now.year, now.month, 1)
    if dt.month == 12:
        next_month = datetime(dt.year + 1, 1, 1)
    else:
        next_month = datetime(dt.year, dt.month + 1, 1)
    end = next_month - timedelta(seconds=1)
    return _report_dt_text(dt), _report_dt_text(end), f"Tháng {dt.strftime('%Y-%m')}"

def year_report_bounds(year_arg: str = "") -> tuple[str, str, str]:
    raw = (year_arg or "").strip()
    year = int(raw) if raw else datetime.now().year
    start = datetime(year, 1, 1)
    end = datetime(year, 12, 31, 23, 59, 59)
    return _report_dt_text(start), _report_dt_text(end), f"Năm {year}"

def accounting_export_csv(start_at: str, end_at: str, label: str, ledger_only: bool = False) -> str:
    buffer = io.StringIO()
    writer = csv.writer(buffer)
    writer.writerow(["TOAN AAS Accounting/Internal Export", label, start_at, end_at])
    writer.writerow(["Note", "Sổ quản trị nội bộ, không thay thế hóa đơn/chứng từ hợp pháp hoặc tư vấn kế toán/thuế."])
    writer.writerow([])
    conn = db_connect()
    try:
        payos_amount = int(sql_scalar(conn, "SELECT COALESCE(SUM(amount),0) FROM payos_orders WHERE status=? AND paid_at BETWEEN ? AND ?", (PAYOS_STATUS_PAID, start_at, end_at), 0) or 0)
        payos_count = int(sql_scalar(conn, "SELECT COUNT(*) FROM payos_orders WHERE status=? AND paid_at BETWEEN ? AND ?", (PAYOS_STATUS_PAID, start_at, end_at), 0) or 0)
        manual_amount = int(sql_scalar(conn, "SELECT COALESCE(SUM(amount),0) FROM pending_deposits WHERE status='approved' AND submitted_at BETWEEN ? AND ?", (start_at, end_at), 0) or 0)
        manual_count = int(sql_scalar(conn, "SELECT COUNT(*) FROM pending_deposits WHERE status='approved' AND submitted_at BETWEEN ? AND ?", (start_at, end_at), 0) or 0)
        xu_sold = int(sql_scalar(conn, "SELECT COALESCE(SUM(xu),0) FROM payos_orders WHERE status=? AND paid_at BETWEEN ? AND ?", (PAYOS_STATUS_PAID, start_at, end_at), 0) or 0)
        xu_manual = int(sql_scalar(conn, "SELECT COALESCE(SUM(xu),0) FROM pending_deposits WHERE status='approved' AND submitted_at BETWEEN ? AND ?", (start_at, end_at), 0) or 0)
        xu_spent = abs(int(sql_scalar(conn, "SELECT COALESCE(SUM(delta),0) FROM credit_events WHERE delta<0 AND created_at BETWEEN ? AND ?", (start_at, end_at), 0) or 0))
        xu_refunded = int(sql_scalar(conn, "SELECT COALESCE(SUM(delta),0) FROM credit_events WHERE delta>0 AND lower(event_type) LIKE '%refund%' AND created_at BETWEEN ? AND ?", (start_at, end_at), 0) or 0)
        writer.writerow(["SUMMARY"])
        writer.writerow(["total_cash_received_vnd", payos_amount + manual_amount])
        writer.writerow(["payos_paid_orders", payos_count])
        writer.writerow(["manual_approved_orders", manual_count])
        writer.writerow(["payos_amount_vnd", payos_amount])
        writer.writerow(["manual_amount_vnd", manual_amount])
        writer.writerow(["xu_sold_payos", xu_sold])
        writer.writerow(["xu_sold_manual", xu_manual])
        writer.writerow(["xu_spent", xu_spent])
        writer.writerow(["xu_refunded", xu_refunded])
        writer.writerow([])

        if not ledger_only:
            writer.writerow(["PAYOS_ORDERS"])
            writer.writerow(["order_code", "user_id", "amount_vnd", "package_amount_vnd", "base_xu", "launch_bonus_xu", "total_xu", "payment_method", "status", "created_at", "paid_at", "payment_link_id"])
            for row in sql_rows(
                conn,
                """SELECT order_code,user_id,amount,package_amount_vnd,base_xu,launch_bonus_xu,xu,status,created_at,paid_at,payment_link_id
                FROM payos_orders
                WHERE created_at BETWEEN ? AND ? OR paid_at BETWEEN ? AND ?
                ORDER BY COALESCE(paid_at,created_at)""",
                (start_at, end_at, start_at, end_at),
            ):
                writer.writerow([row[0], row[1], row[2], row[3], row[4], row[5], row[6], "payos", row[7], row[8], row[9], row[10]])
            writer.writerow([])

            writer.writerow(["MANUAL_DEPOSITS"])
            writer.writerow(["deposit_id", "order_code", "user_id", "username", "amount_vnd", "total_xu", "payment_method", "status", "submitted_at"])
            for row in sql_rows(
                conn,
                """SELECT id,order_code,user_id,username,amount,xu,status,submitted_at
                FROM pending_deposits
                WHERE submitted_at BETWEEN ? AND ?
                ORDER BY submitted_at""",
                (start_at, end_at),
            ):
                writer.writerow([row[0], row[1], row[2], row[3], row[4], row[5], "manual_qr", row[6], row[7]])
            writer.writerow([])

            writer.writerow(["TRANSACTIONS_SPEND"])
            writer.writerow(["user_id", "action", "base_cost", "discount_rate", "discount_xu", "final_cost", "created_at"])
            for row in sql_rows(
                conn,
                "SELECT user_id,action,cost,discount_rate,created_at FROM transactions WHERE created_at BETWEEN ? AND ? ORDER BY created_at",
                (start_at, end_at),
            ):
                final_cost = int(row[2] or 0)
                writer.writerow([row[0], row[1], "", row[3], "", final_cost, row[4]])
            writer.writerow([])

        writer.writerow(["CREDIT_EVENTS_LEDGER"])
        writer.writerow(["user_id", "delta", "balance_after", "event_type", "ref_id", "note", "created_at"])
        for row in sql_rows(
            conn,
            "SELECT user_id,delta,balance_after,event_type,ref_id,note,created_at FROM credit_events WHERE created_at BETWEEN ? AND ? ORDER BY created_at",
            (start_at, end_at),
        ):
            writer.writerow(list(row))
        writer.writerow([])

        writer.writerow(["REFUNDS"])
        writer.writerow(["user_id", "xu_refunded", "event_type", "ref_id", "reason", "created_at"])
        for row in sql_rows(
            conn,
            "SELECT user_id,delta,event_type,ref_id,note,created_at FROM credit_events WHERE delta>0 AND lower(event_type) LIKE '%refund%' AND created_at BETWEEN ? AND ? ORDER BY created_at",
            (start_at, end_at),
        ):
            writer.writerow([row[0], row[1], row[2], row[3], row[4], row[5]])
    finally:
        conn.close()
    return buffer.getvalue()

