def memory_note_count(user_id) -> int:
    conn = db_connect()
    try:
        row = conn.execute(
            "SELECT COUNT(*) FROM memory_notes WHERE user_id=? AND status='active' AND is_archived=0",
            (str(user_id),),
        ).fetchone()
        return int(row[0] or 0) if row else 0
    finally:
        conn.close()

def memory_storage_used_breakdown(user_id) -> dict:
    conn = db_connect()
    try:
        row = conn.execute(
            """SELECT
                   COALESCE(SUM(LENGTH(CAST(COALESCE(content,'') AS BLOB)) + LENGTH(CAST(COALESCE(summary,'') AS BLOB))),0),
                   COALESCE(SUM(COALESCE(file_size,0)),0)
            FROM memory_notes WHERE user_id=? AND is_archived=0""",
            (str(user_id),),
        ).fetchone()
        text_bytes = int(row[0] or 0) if row else 0
        personal_file_bytes = int(row[1] or 0) if row else 0
        archive_file_bytes = int(sql_scalar(
            conn,
            "SELECT COALESCE(SUM(COALESCE(size_bytes,0)),0) FROM internal_documents WHERE owner_admin_id=? AND status='active'",
            (str(user_id),),
            0,
        ) or 0)
        file_bytes = personal_file_bytes + archive_file_bytes
        return {
            "text_bytes": text_bytes,
            "file_bytes": file_bytes,
            "archive_file_bytes": archive_file_bytes,
            "total_bytes": text_bytes + file_bytes,
            "text_mb": text_bytes / (1024 * 1024),
            "file_mb": file_bytes / (1024 * 1024),
            "total_mb": (text_bytes + file_bytes) / (1024 * 1024),
        }
    finally:
        conn.close()

def memory_storage_used_bytes(user_id) -> int:
    return int(memory_storage_used_breakdown(user_id).get("total_bytes") or 0)

def memory_active_reminder_count(user_id) -> int:
    conn = db_connect()
    try:
        row = conn.execute(
            "SELECT COUNT(*) FROM memory_reminders WHERE user_id=? AND status='active'",
            (str(user_id),),
        ).fetchone()
        return int(row[0] or 0) if row else 0
    finally:
        conn.close()

def memory_status_payload(user_id) -> dict:
    plan = ensure_memory_plan(user_id)
    notes = memory_note_count(user_id)
    storage = memory_storage_used_breakdown(user_id)
    storage_bytes = int(storage["total_bytes"])
    ai_limit = int(plan["ai_classify_monthly_limit"])
    ai_used = int(plan["ai_classify_used"])
    active_storage_addon_mb = memory_active_storage_addon_mb(user_id)
    base_limit_mb = max(TOTAL_FREE_STORAGE_MB, int(plan["storage_limit_mb"]))
    total_limit_mb = base_limit_mb + active_storage_addon_mb
    total_limit_bytes = total_limit_mb * 1024 * 1024
    used_percent = (storage_bytes / total_limit_bytes * 100) if total_limit_bytes > 0 else 0
    addon_mb = max(0, total_limit_mb - TOTAL_FREE_STORAGE_MB)
    return {
        "plan": plan,
        "notes": notes,
        "text_bytes": int(storage["text_bytes"]),
        "file_bytes": int(storage["file_bytes"]),
        "storage_bytes": storage_bytes,
        "text_mb": storage["text_mb"],
        "file_mb": storage["file_mb"],
        "storage_mb": storage["total_mb"],
        "total_limit_mb": total_limit_mb,
        "total_limit_bytes": total_limit_bytes,
        "used_percent": used_percent,
        "addon_mb": addon_mb,
        "active_storage_addon_mb": active_storage_addon_mb,
        "base_limit_mb": base_limit_mb,
        "near_quota": used_percent >= STORAGE_NEAR_QUOTA_PERCENT,
        "ai_remaining": max(0, ai_limit - ai_used),
        "active_reminders": memory_active_reminder_count(user_id),
    }

def memory_quota_error(user_id, extra_bytes: int = 0, extra_kind: str = "text") -> str:
    if is_admin_user(user_id):
        return ""
    status = memory_status_payload(user_id)
    plan = status["plan"]
    if status["notes"] >= int(plan["note_limit"]):
        return (
            "⚠️ Bạn đã dùng hết số lượng ghi chú của gói hiện tại.\n\n"
            f"• Gói: {plan['plan']}\n"
            f"• Giới hạn: {plan['note_limit']} ghi chú\n\n"
            "Bạn có thể dọn ghi chú cũ hoặc liên hệ admin nếu cần tăng hạn mức."
        )
    extra = max(0, int(extra_bytes or 0))
    kind = str(extra_kind or "text").lower()
    if kind in {"text", "note", "reminder", "checklist"} and status["addon_mb"] <= 0 and status["text_bytes"] + extra > NOTES_TEXT_FREE_BYTES:
        return (
            "⚠️ Dung lượng ghi chú/text miễn phí đã đầy.\n\n"
            f"• Text/ghi chú hiện có: {storage_bytes_to_mb_text(status['text_bytes'])} / {NOTES_TEXT_FREE_MB}MB\n"
            f"• Nội dung mới: {storage_bytes_to_mb_text(extra)}\n\n"
            "TOAN AAS chưa lưu nội dung này và chưa trừ Xu.\n"
            "Bạn có thể dọn ghi chú cũ hoặc mua thêm dung lượng."
        )
    if kind in {"file", "image", "audio", "document"} and status["addon_mb"] <= 0 and status["file_bytes"] + extra > FILES_AUDIO_FREE_BYTES:
        return (
            "⚠️ Dung lượng tệp/ảnh/âm thanh miễn phí đã đầy.\n\n"
            f"• Tệp/ảnh/âm thanh hiện có: {storage_bytes_to_mb_text(status['file_bytes'])} / {FILES_AUDIO_FREE_MB}MB\n"
            f"• File mới: {storage_bytes_to_mb_text(extra)}\n\n"
            "TOAN AAS chưa lưu file này để tránh vượt dung lượng.\n"
            "Bạn có thể xóa bớt file cũ hoặc mua thêm dung lượng."
        )
    if status["storage_bytes"] + extra > status["total_limit_bytes"]:
        return (
            "⚠️ Dung lượng lưu trữ của bạn đã đầy.\n\n"
            f"• Đã dùng: {storage_bytes_to_mb_text(status['storage_bytes'])} / {status['total_limit_mb']}MB\n"
            f"• Dữ liệu mới: {storage_bytes_to_mb_text(extra)}\n\n"
            "TOAN AAS chưa lưu dữ liệu này để tránh vượt dung lượng.\n"
            "Bạn có thể xóa bớt file cũ hoặc mua thêm dung lượng."
        )
    return ""

def memory_clean_title(text: str) -> str:
    text = re.sub(r"\s+", " ", str(text or "")).strip()
    if not text:
        return "Ghi chú TOAN AAS"
    return text[:80] + ("..." if len(text) > 80 else "")

def memory_default_category(text: str) -> str:
    lower = str(text or "").lower()
    if any(x in lower for x in ("khách", "lead", "báo giá", "đơn hàng")):
        return "Khách hàng/Lead"
    if any(x in lower for x in ("video", "content", "caption", "tiktok", "facebook", "youtube")):
        return "Ý tưởng content"
    if any(x in lower for x in ("tiền", "doanh thu", "chi phí", "thanh toán")):
        return "Tài chính"
    if any(x in lower for x in ("học", "khóa", "bài học")):
        return "Học tập"
    if any(x in lower for x in ("việc", "todo", "cần làm", "nhắc")):
        return "Việc cần làm"
    return "Khác"

def memory_extract_json(text: str) -> dict:
    raw = str(text or "").strip()
    if not raw or raw.startswith("❌"):
        return {}
    candidates = []
    fence = re.search(r"```(?:json)?\s*(.*?)```", raw, re.I | re.S)
    if fence:
        candidates.append(fence.group(1).strip())
    candidates.append(raw)
    for candidate in candidates:
        if not candidate:
            continue
        try:
            parsed = json.loads(candidate)
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            pass
        match = re.search(r"\{.*\}", candidate, re.S)
        if match:
            try:
                parsed = json.loads(match.group(0))
                return parsed if isinstance(parsed, dict) else {}
            except Exception:
                pass
    return {}

def memory_ai_classify(content: str, user_id) -> tuple[bool, dict, str]:
    prompt = (
        "Bạn là TOAN AAS Memory classifier. Chỉ trả về đúng 1 object JSON hợp lệ, không markdown, không giải thích.\n"
        "Schema: title, summary, tags, category, priority.\n"
        "priority chỉ dùng một trong: low, normal, important, urgent.\n"
        "category chọn ngắn gọn theo nội dung. tags là list 3-8 tag.\n"
        "Nếu thiếu dữ liệu, tự đặt default ngắn gọn nhưng JSON vẫn phải hợp lệ."
    )
    try:
        output = AgentGemini.chat(prompt, str(content or "")[:6000], f"memory:{user_id}", is_json=False)
        data = memory_extract_json(output)
        if not data:
            return False, {}, "AI trả về không đúng JSON"
        tags = data.get("tags") or []
        if isinstance(tags, str):
            tags = [x.strip() for x in re.split(r"[,;#]", tags) if x.strip()]
        priority = str(data.get("priority") or "normal").lower()
        if priority not in MEMORY_PRIORITIES:
            priority = "normal"
        result = {
            "title": memory_clean_title(data.get("title") or content),
            "summary": str(data.get("summary") or "")[:1000],
            "tags": ", ".join(str(x).strip() for x in tags[:8] if str(x).strip()),
            "category": str(data.get("category") or memory_default_category(content))[:80],
            "priority": priority,
        }
        return True, result, ""
    except Exception as e:
        return False, {}, str(e)[:220]

def memory_create_note(user_id, content: str, ai_data: dict | None = None, source_type: str = "text", file_id="", file_name="", file_size=0) -> int:
    content = str(content or "").strip()
    data = ai_data or {}
    title = memory_clean_title(data.get("title") or content)
    summary = str(data.get("summary") or content[:500]).strip()
    tags = str(data.get("tags") or "").strip()
    category = str(data.get("category") or memory_default_category(content)).strip()[:80]
    priority = str(data.get("priority") or "normal").lower()
    if priority not in MEMORY_PRIORITIES:
        priority = "normal"
    conn = db_connect()
    try:
        cur = conn.cursor()
        cur.execute(
            """INSERT INTO memory_notes
            (user_id, title, content, summary, tags, category, priority, status, source_type,
             file_id, file_name, file_size, is_archived, created_at, updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                str(user_id), title, content, summary, tags, category, priority, "active", source_type,
                str(file_id or ""), str(file_name or ""), int(file_size or 0), 0, now_text(), now_text(),
            ),
        )
        note_id = int(cur.lastrowid)
        conn.commit()
        return note_id
    finally:
        conn.close()

def memory_fetch_note(user_id, note_id: int, include_archived: bool = False) -> dict:
    conn = db_connect()
    try:
        query = """SELECT id, user_id, title, content, summary, tags, category, priority, status, source_type,
                          file_id, file_name, file_size, is_archived, created_at, updated_at
                   FROM memory_notes WHERE id=? AND user_id=?"""
        row = conn.execute(query, (int(note_id), str(user_id))).fetchone()
        if not row:
            return {}
        keys = ["id", "user_id", "title", "content", "summary", "tags", "category", "priority", "status", "source_type", "file_id", "file_name", "file_size", "is_archived", "created_at", "updated_at"]
        data = dict(zip(keys, row))
        if not include_archived and (int(data.get("is_archived") or 0) or data.get("status") != "active"):
            return {}
        return data
    finally:
        conn.close()

def memory_format_note_item(note: dict) -> str:
    tags = f" | #{html.escape(str(note.get('tags') or '').replace(', ', ' #'))}" if note.get("tags") else ""
    return (
        f"#{note.get('id')} — <b>{html.escape(note.get('title') or 'Ghi chú')}</b>\n"
        f"  <code>{html.escape(note.get('priority') or 'normal')}</code> | {html.escape(note.get('category') or 'Khác')}{tags}\n"
        f"  {html.escape((note.get('summary') or '')[:180])}"
    )

def memory_format_note_item_with_time(note: dict) -> str:
    created_at = html.escape(str(note.get("created_at") or "-"))
    source = html.escape(str(note.get("source_type") or "manual"))
    return (
        f"#{note.get('id')} — <b>{html.escape(note.get('title') or 'Ghi chú')}</b>\n"
        f"  Tạo lúc: <code>{created_at}</code> | Nguồn: <code>{source}</code>\n"
        f"  {html.escape((note.get('summary') or note.get('content') or '')[:180])}"
    )

def memory_guided_pending_key(user_id) -> str:
    return f"memory_guided:{user_id}"

def set_memory_guided_pending(user_id, action: str, **fields) -> dict:
    payload = {
        "pending_action": str(action or "").strip(),
        "created_at_ts": time.time(),
    }
    for key, value in fields.items():
        payload[str(key)] = _short_pending_text(value, 900)
    USER_PENDING[memory_guided_pending_key(user_id)] = payload
    return payload

def get_memory_guided_pending(user_id) -> dict | None:
    payload = USER_PENDING.get(memory_guided_pending_key(user_id)) or {}
    if not payload.get("pending_action"):
        return None
    if time.time() - float(payload.get("created_at_ts") or 0) > QUICK_MEDIA_PENDING_TTL_SECONDS:
        USER_PENDING.pop(memory_guided_pending_key(user_id), None)
        return None
    return payload

def clear_memory_guided_pending(user_id) -> bool:
    return USER_PENDING.pop(memory_guided_pending_key(user_id), None) is not None

