    memory_record_event(uid, "note_priority_updated", note_id=note_id, detail=priority)
    await update.message.reply_text(f"✅ Đã đổi mức độ ghi chú <code>#{note_id}</code> thành <code>{priority}</code>.", parse_mode="HTML")

