async def send_or_confirm_trend_video_flow_from_callback(query, uid: int, topic: str) -> None:
    lang = user_ui_lang(uid)
    if not TREND_VIDEO_WORKFLOW_ENABLED:
        if normalize_user_language(lang) == "zh":
            await safe_edit_or_send(query, "🛠 Trend → Video Workflow 暂时维护中。本次未扣除 Xu。")
        elif normalize_user_language(lang) != "vi":
            await safe_edit_or_send(query, "🛠 Trend → Video Workflow is temporarily under maintenance. The bot has not charged Xu.")
        else:
            await safe_edit_or_send(query, "🛠 Trend → Video Workflow đang tạm tắt để bảo trì. Bot chưa trừ Xu.")
        return
    if not trend_video_workflow_can_access(uid):
        if normalize_user_language(lang) == "zh":
            await safe_edit_or_send(query, "🧪 Trend video workflow 仍在内部测试，尚未公开。\n本次未扣除 Xu。")
        elif normalize_user_language(lang) != "vi":
            await safe_edit_or_send(query, "🧪 Trend video workflow is in internal testing and is not public yet.\nThe bot has not charged Xu.")
        else:
            await safe_edit_or_send(query, f"{TREND_VIDEO_WORKFLOW_PUBLIC_OFF_MESSAGE}\nBot chưa trừ Xu.")
        return
    topic = re.sub(r"\s+", " ", str(topic or "").strip())[:800]
    if not topic:
        await safe_edit_or_send(query, cinematic_ad_missing_latest_text(lang))
        return
    if is_admin_user(uid):
        if normalize_user_language(lang) == "zh":
            await safe_edit_or_send(query, "🎬 正在根据当前 concept 生成 Trend → Video Workflow...\nAdmin preview / no Xu deducted.")
        elif normalize_user_language(lang) != "vi":
            await safe_edit_or_send(query, "🎬 Creating Trend → Video Workflow from the current concept...\nAdmin preview / no Xu deducted.")
        else:
            await safe_edit_or_send(query, "🎬 Đang tạo Trend → Video Workflow từ concept hiện tại...\nAdmin preview / no Xu deducted.")
        await send_trend_video_flow_for_topic_message(query.message, uid, topic, billing_note=trend_workflow_admin_preview_note(), lang=lang)
        return
    if not TREND_WORKFLOW_BILLING_ENABLED:
        if normalize_user_language(lang) == "zh":
            await safe_edit_or_send(query, "🎬 正在根据当前 concept 生成 Trend → Video Workflow...\nBilling workflow OFF，本次未扣除 Xu。")
        elif normalize_user_language(lang) != "vi":
            await safe_edit_or_send(query, "🎬 Creating Trend → Video Workflow from the current concept...\nBilling workflow is OFF, the bot has not charged Xu.")
        else:
            await safe_edit_or_send(query, "🎬 Đang tạo Trend → Video Workflow từ concept hiện tại...\nBilling workflow OFF, bot chưa trừ Xu.")
        await send_trend_video_flow_for_topic_message(query.message, uid, topic, billing_note=trend_workflow_billing_off_note(lang), lang=lang)
        return
    total_cost = int(trend_workflow_content_cost_breakdown().get("total") or 0)
    workflow = trend_workflow_id(uid)
    credits, _, _ = get_user(uid, query.from_user.first_name or query.from_user.username or "Trend workflow user")
    if int(credits or 0) < total_cost:
        await edit_trend_workflow_insufficient_credits(query, int(credits or 0), total_cost, uid, workflow)
        return
    if TREND_WORKFLOW_REQUIRE_CONFIRM:
        set_trend_workflow_confirm_pending(uid, topic, workflow)
        await safe_edit_or_send(
            query,
            trend_workflow_content_confirm_text(topic, int(credits or 0), lang),
            parse_mode="HTML",
            reply_markup=trend_workflow_content_confirm_keyboard(lang, bool(active_package_item_for_user(uid, "trend_workflow"))),
        )
        return
    if normalize_user_language(lang) == "zh":
        await safe_edit_or_send(query, "🎬 正在根据当前 concept 生成 Trend → Video Workflow...")
    elif normalize_user_language(lang) != "vi":
        await safe_edit_or_send(query, "🎬 Creating Trend → Video Workflow from the current concept...")
    else:
        await safe_edit_or_send(query, "🎬 Đang tạo Trend → Video Workflow từ concept hiện tại...")
    await execute_confirmed_trend_workflow_content(query.message, uid, topic, workflow)

@video_public_callback_failure_guard
async def handle_cinematic_ad_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    await query.answer()
    uid = query.from_user.id
    data = query.data or ""
    parts = data.split("|")
    action = parts[1] if len(parts) >= 2 else "start"
    value = parts[2] if len(parts) >= 3 else ""
    extra = parts[3] if len(parts) >= 4 else ""
    lang = user_ui_lang(uid)
    if action.startswith("concept_style_"):
        value = normalize_cinematic_ad_style_code(action.replace("concept_style_", "", 1))
        action = "style"
    elif action == "style" and str(value or "").strip().lower() == "skip":
        value = "direct_sales"
    elif action == "style":
        value = normalize_cinematic_ad_style_code(value)

    if action == "cancel":
        clear_cinematic_ad_pending(uid)
        return await safe_edit_query_message(
            query,
            ui_text(lang, "concept_ad.cancelled"),
            reply_markup=main_video_keyboard(lang),
        )
    if action == "main":
        clear_cinematic_ad_pending(uid)
        clear_media_creator_pending_states(uid)
        return await safe_edit_query_message(
            query,
            ui_text(lang, "common.open_main_menu"),
            reply_markup=localized_main_menu_keyboard(is_admin_user(uid), lang),
        )
    if action in {"start", "new", "guided_start"}:
        clear_media_creator_pending_states(uid)
        if action == "new":
            LAST_CINEMATIC_AD_CONCEPTS.pop(cinematic_ad_latest_key(uid), None)
        set_cinematic_ad_pending(uid, "product")
        return await safe_edit_query_message(query, cinematic_ad_product_text(lang), reply_markup=cinematic_ad_product_keyboard(lang))
    if action in {
        "continue", "lock", "back_locked", "concept_choice", "image_menu", "video_menu", "music_menu",
        "motion_current", "motion_choice", "use_motion_current", "save_motion_current",
        "image_prompt_current", "image_prompt_from_motion", "image_prompt_choice", "video_prompt_current", "video_prompt_from_motion", "video_prompt_choice",
        "save_image_prompt_current", "save_video_prompt_current",
        "create_image_current", "create_video_current", "video_current", "trend_current", "workflow_current",
        "music_current", "music_suggest", "music_library", "music_genre", "music_choice", "music_ai", "music_ai_save", "music_none", "music_save",
        "finalize_video_music", "finalize_video_no_music", "save_video_package", "finalize",
        "admin_video_smoke", "edit_current", "image_ai", "image_ai_tier",
    }:
        concept = get_latest_cinematic_ad_concept(uid)
        if not concept:
            return await safe_edit_query_message(
                query,
                ui_text(lang, "concept.current_missing"),
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton(ui_text(lang, "concept_ad.new"), callback_data="adconcept|start")],
                    [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="adconcept|main")],
                ]),
            )
        if action in {"continue", "lock", "back_locked"}:
            concept = lock_latest_cinematic_ad_concept(uid) or concept
            return await safe_edit_query_message(query, cinematic_ad_continue_text(concept, lang), reply_markup=cinematic_ad_locked_keyboard(lang))
        if action == "concept_choice":
            idx = max(1, min(3, safe_int(value, 1)))
            concept["idea_choice"] = idx
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(
                query,
                cinematic_ad_concept_choice_detail(concept, idx, lang),
                reply_markup=cinematic_ad_selected_concept_keyboard(lang),
            )
        if action == "image_menu":
            concept = lock_latest_cinematic_ad_concept(uid) or concept
            return await safe_edit_query_message(query, cinematic_ad_image_menu_text(concept, lang), reply_markup=cinematic_ad_image_menu_keyboard(lang))
        if action == "video_menu":
            concept = lock_latest_cinematic_ad_concept(uid) or concept
            return await safe_edit_query_message(query, cinematic_ad_video_menu_text(concept, lang), reply_markup=cinematic_ad_video_menu_keyboard(lang))
        if action == "music_menu":
            concept = lock_latest_cinematic_ad_concept(uid) or concept
            return await safe_edit_query_message(query, cinematic_ad_music_menu_text(concept, lang), reply_markup=cinematic_ad_music_menu_keyboard(lang))
        if action == "motion_current":
            return await safe_edit_query_message(
                query,
                cinematic_ad_motion_choices_text(concept, lang),
                reply_markup=cinematic_ad_motion_choices_keyboard(lang),
            )
        if action == "motion_choice":
            idx = max(1, min(3, safe_int(value, 1)))
            concept["motion_choice"] = idx
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(
                query,
                cinematic_ad_motion_from_concept_text(concept, lang, idx),
                reply_markup=cinematic_ad_motion_keyboard(lang),
            )
        if action in {"use_motion_current", "save_motion_current"}:
            concept["motion_saved"] = True
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(
                query,
                ui_text(lang, "concept.motion_saved_next"),
                reply_markup=cinematic_ad_motion_saved_keyboard(lang, is_admin_user(uid)),
            )
        if action in {"image_prompt_current", "image_prompt_from_motion", "create_image_current"}:
            return await safe_edit_query_message(
                query,
                cinematic_ad_image_prompts_from_concept_text(concept, lang),
                reply_markup=cinematic_ad_image_prompt_choices_keyboard(lang),
            )
        if action == "image_prompt_choice":
            idx = max(1, min(3, safe_int(value, 1)))
            concept["image_prompt_choice"] = idx
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(
                query,
                cinematic_ad_selected_image_prompt_text(concept, idx, lang),
                reply_markup=cinematic_ad_image_prompt_selected_keyboard(idx, lang),
            )
        if action == "save_image_prompt_current":
            idx = max(1, min(3, safe_int(value or concept.get("image_prompt_choice") or 1, 1)))
            concept["image_prompt_saved"] = True
            concept["image_prompt_choice"] = idx
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(
                query,
                ui_text(lang, "concept.saved_image_prompt"),
                reply_markup=cinematic_ad_image_prompt_selected_keyboard(idx, lang),
            )
        if action in {"video_prompt_current", "video_prompt_from_motion"}:
            return await safe_edit_query_message(
                query,
                cinematic_ad_video_prompt_from_concept_text(concept, lang),
                reply_markup=cinematic_ad_video_prompt_choices_keyboard(lang),
            )
        if action == "video_prompt_choice":
            idx = max(1, min(3, safe_int(value, 1)))
            concept["video_prompt_choice"] = idx
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(
                query,
                cinematic_ad_selected_video_prompt_text(concept, idx, lang),
                reply_markup=cinematic_ad_video_prompt_selected_keyboard(idx, lang, is_admin_user(uid)),
            )
        if action == "save_video_prompt_current":
            idx = max(1, min(3, safe_int(value or concept.get("video_prompt_choice") or 1, 1)))
            concept["video_prompt_saved"] = True
            concept["video_prompt_choice"] = idx
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(
                query,
                ui_text(lang, "concept.video_prompt_saved_next"),
                reply_markup=cinematic_ad_video_saved_keyboard(lang, is_admin_user(uid)),
            )
        if action == "finalization":
            concept = lock_latest_cinematic_ad_concept(uid) or concept
            package = build_cinematic_ad_video_package(uid, concept, lang, source="cinematic_ad_finalization")
            source_state = dict(concept)
            source_state["script"] = str(concept.get("brand_story") or concept.get("message") or "")
            source_state["video_prompt"] = package.get("video_prompt") or ""
            generated_url = str(concept.get("generated_image_url") or concept.get("image_url") or "")
            if generated_url:
                source_state["photos"] = [{"image_url": generated_url}]
            return await open_video_finalization(query, uid, "cinematic_ad", source_state, lang, "adconcept|back_locked", package)
        if action in {"trend_current", "workflow_current"}:
            _product, _message, _style, topic = cinematic_ad_concept_input(concept, lang)
            return await send_or_confirm_trend_video_flow_from_callback(query, uid, topic)
        if action in {"video_current", "create_video_current"}:
            if not str(value or "").strip():
                concept = lock_latest_cinematic_ad_concept(uid) or concept
                return await safe_edit_query_message(
                    query,
                    cinematic_ad_video_prompt_from_concept_text(concept, lang),
                    reply_markup=cinematic_ad_video_prompt_choices_keyboard(lang),
                )
            idx = max(1, min(3, safe_int(value or concept.get("video_prompt_choice") or 1, 1)))
            concept["video_prompt_choice"] = idx
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            package = build_cinematic_ad_video_package(uid, concept, lang, source="cinematic_ad_prompt")
            source_state = dict(concept)
            source_state["script"] = str(concept.get("brand_story") or concept.get("message") or "")
            source_state["video_prompt"] = package.get("video_prompt") or ""
            return await open_video_finalization(query, uid, "cinematic_ad", source_state, lang, "adconcept|back_locked", package)
        if action in {"music_current", "music_suggest"}:
            return await safe_edit_query_message(query, cinematic_ad_music_from_concept_text(concept, lang), reply_markup=cinematic_ad_music_suggestion_keyboard(lang))
        if action == "music_library":
            return await safe_edit_query_message(query, cinematic_ad_music_library_text(concept, lang), reply_markup=cinematic_ad_music_library_keyboard(lang))
        if action == "music_genre":
            search_query = cinematic_ad_music_genre_query(value, concept, lang)
            set_video_music_context(uid, "cinematic_ad")
            await safe_edit_query_message(query, ui_text(lang, "concept.music_searching"))
            return await send_music_library_results(query.message, uid, search_query)
        if action == "music_choice":
            idx = max(1, min(3, safe_int(value, 1)))
            concept["music_choice"] = idx
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(query, cinematic_ad_music_choice_text(concept, idx, lang), reply_markup=cinematic_ad_music_selected_keyboard(lang))
        if action == "music_ai":
            concept["music_choice"] = "ai_prompt"
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(query, cinematic_ad_music_ai_text(concept, lang), reply_markup=cinematic_ad_music_ai_selected_keyboard(lang))
        if action == "music_ai_save":
            concept["music_choice"] = "ai_prompt"
            concept["music_saved"] = True
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(query, cinematic_ad_music_ai_text(concept, lang) + "\n\n" + ("Bot đã lưu prompt nhạc AI. Tạo nhạc AI thật sẽ mở sau." if normalize_user_language(lang) == "vi" else "The bot saved this AI music prompt. Real AI music generation will open later."), reply_markup=cinematic_ad_music_ai_selected_keyboard(lang))
        if action == "music_none":
            concept["music_choice"] = "none"
            concept["no_music"] = True
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(query, cinematic_ad_no_music_selected_text(concept, lang), parse_mode="HTML", reply_markup=cinematic_ad_no_music_keyboard(lang))
        if action == "music_save":
            concept["music_saved"] = True
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(query, ui_text(lang, "concept.music_saved_next"), reply_markup=cinematic_ad_music_selected_keyboard(lang))
        if action in {"finalize_video_music", "finalize_video_no_music"}:
            no_music = action == "finalize_video_no_music"
            if no_music:
                concept["music_choice"] = "none"
                concept["no_music"] = True
            else:
                concept.setdefault("music_choice", concept.get("music_choice") or "not_selected")
            concept["video_prompt_choice"] = safe_int(value or concept.get("video_prompt_choice") or 1, 1)
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            package = build_cinematic_ad_video_package(uid, concept, lang, no_music=no_music, source="cinematic_ad_music")
            source_state = dict(concept)
            source_state["script"] = str(concept.get("brand_story") or concept.get("message") or "")
            source_state["video_prompt"] = package.get("video_prompt") or ""
            result = await open_video_finalization(query, uid, "cinematic_ad", source_state, lang, "adconcept|back_locked", package)
            if not no_music:
                update_video_finalization(uid, music_enabled=True, music_mode="suggested", music_prompt=str(concept.get("music_choice") or "cinematic suggestion"))
            return result
        if action == "save_video_package":
            package = get_latest_video_package(uid)
            if not package:
                package = save_latest_video_package(uid, build_cinematic_ad_video_package(uid, concept, lang, source="cinematic_ad_saved"))
            return await safe_edit_query_message(
                query,
                cinematic_ad_video_package_saved_text(package, lang),
                parse_mode="HTML",
                reply_markup=cinematic_ad_video_package_saved_keyboard(lang, is_admin_user(uid)),
            )
        if action == "finalize":
            concept["finalized"] = True
            LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(uid)] = concept
            return await safe_edit_query_message(
                query,
                cinematic_ad_finalize_text(concept, lang),
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton(ui_text(lang, "concept.review_video_prompt"), callback_data="adconcept|video_prompt_current")],
                    [InlineKeyboardButton(ui_text(lang, "concept.review_image_prompt"), callback_data="adconcept|image_prompt_current")],
                    [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="adconcept|main")],
                ]),
            )
        if action == "admin_video_smoke":
            if not is_admin_user(uid):
                return await safe_edit_query_message(query, ui_text(lang, "media.public_off"))
            idx = max(1, min(3, safe_int(value or concept.get("video_prompt_choice") or 1, 1)))
            await safe_edit_query_message(query, ui_text(lang, "video.admin_smoke_warning"))
            fake_update = SimpleNamespace(effective_user=query.from_user, effective_chat=SimpleNamespace(id=query.message.chat_id), message=query.message)
            return await run_quick_video_admin_smoke(fake_update, context, cinematic_ad_video_smoke_prompt(concept, idx, lang))
        if action == "edit_current":
            product, message, style, _topic = cinematic_ad_concept_input(concept, lang)
            set_cinematic_ad_pending(uid, "edit", product, message, style)
            return await safe_edit_query_message(
                query,
                ui_text(lang, "concept.edit_prompt"),
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton(ui_text(lang, "concept.back_locked"), callback_data="adconcept|back_locked")],
                    [InlineKeyboardButton(ui_text(lang, "common.cancel"), callback_data="adconcept|cancel"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="adconcept|main")],
                ]),
            )
        if action == "image_ai":
            prompt_index = safe_int(value, 1)
            if not SHOPAIKEY_PUBLIC_IMAGE_ENABLED:
                return await safe_edit_query_message(query, ui_text(lang, "media.public_off"))
            if shopaikey_active_job_for_user(uid, "image"):
                return await safe_edit_query_message(query, ui_text(lang, "media.job_lock"))
            return await safe_edit_query_message(
                query,
                public_image_tier_selection_text(lang),
                parse_mode="HTML",
                reply_markup=cinematic_ad_image_tier_keyboard(prompt_index, lang),
            )
        if action == "image_ai_tier":
            prompt_index = safe_int(value, 1)
            tier = normalize_image_tier(extra or SHOPAIKEY_IMAGE_DEFAULT_TIER)
            payload = canonical_image_tier_payload(tier)
            if not payload.get("enabled"):
                return await safe_edit_query_message(query, ui_text(lang, "image.tier_disabled_message"))
            if not SHOPAIKEY_PUBLIC_IMAGE_ENABLED:
                return await safe_edit_query_message(query, ui_text(lang, "media.public_off"))
            if shopaikey_active_job_for_user(uid, "image"):
                return await safe_edit_query_message(query, ui_text(lang, "media.job_lock"))
            prompt = cinematic_ad_image_prompt_for_index(concept, prompt_index, lang)
            credits, _, _ = get_user(uid, query.from_user.first_name or query.from_user.username or "Concept image user")
            base_cost = int(payload.get("cost") or 0)
            final_preview_cost = shopaikey_preview_final_cost(uid, base_cost, "shopaikey_image")
            if int(credits or 0) < final_preview_cost and not is_admin_user(uid):
                return await edit_insufficient_credits(query, int(credits or 0), final_preview_cost, uid)
            token = set_shopaikey_pending_confirmation(uid, {
                "job_type": "image",
                "prompt": image_tier_prompt_for_generation(prompt, tier),
                "original_prompt": prompt,
                "base_cost": base_cost,
                "from_image": False,
                "image_tier": tier,
                "tier_label": payload.get("label") or tier,
                "model": payload.get("model") or SHOPAIKEY_IMAGE_MODEL or "nano-banana",
                "retry_warranty_count": int(payload.get("retry_warranty_count") or 0),
                "source": "cinematic_ad_concept",
            })
            return await safe_edit_query_message(
                query,
                public_image_confirm_text(tier, prompt, int(credits or 0), lang),
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton(ui_text(lang, "common.confirm"), callback_data=f"shopai|confirm|{token}")],
                    [InlineKeyboardButton(ui_text(lang, "common.cancel"), callback_data=f"shopai|cancel|{token}")],
                    [InlineKeyboardButton(ui_text(lang, "concept.back_locked"), callback_data="adconcept|back_locked")],
                ]),
            )
    if action == "back":
        pending = get_cinematic_ad_pending(uid) or {}
        if value == "product":
            set_cinematic_ad_pending(uid, "product")
            return await safe_edit_query_message(query, cinematic_ad_product_text(lang), reply_markup=cinematic_ad_product_keyboard(lang))
        product = pending.get("product") or ("你的产品/服务" if normalize_user_language(lang) == "zh" else ("your product/service" if normalize_user_language(lang) != "vi" else "sản phẩm/dịch vụ của bạn"))
        set_cinematic_ad_pending(uid, "message", product)
        return await safe_edit_query_message(query, cinematic_ad_message_text(product, lang), reply_markup=cinematic_ad_message_keyboard(lang))
    if action == "message":
        pending = get_cinematic_ad_pending(uid) or {}
        product = pending.get("product") or ("你的产品/服务" if normalize_user_language(lang) == "zh" else ("your product/service" if normalize_user_language(lang) != "vi" else "sản phẩm/dịch vụ của bạn"))
        if value == "custom":
            set_cinematic_ad_pending(uid, "message", product)
            return await safe_edit_query_message(
                query,
                ui_text(lang, "concept_ad.custom_message_prompt"),
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="adconcept|back|message")],
                    [InlineKeyboardButton(ui_text(lang, "common.cancel"), callback_data="adconcept|cancel"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="adconcept|main")],
                ]),
            )
        if value == "skip":
            message = cinematic_ad_default_message(lang)
            set_cinematic_ad_pending(uid, "style", product, message)
            return await safe_edit_query_message(query, cinematic_ad_style_text(product, message, lang), reply_markup=cinematic_ad_style_keyboard(lang))
        message = cinematic_ad_message_label(value, lang)
        set_cinematic_ad_pending(uid, "style", product, message)
        return await safe_edit_query_message(query, cinematic_ad_style_text(product, message, lang), reply_markup=cinematic_ad_style_keyboard(lang))
    if action == "style":
        pending = get_cinematic_ad_pending(uid) or {}
        if not pending or str(pending.get("step") or "") not in {"style", "edit"} or not (pending.get("product") and pending.get("message")):
            return await safe_edit_query_message(
                query,
                cinematic_ad_expired_session_text(lang),
                reply_markup=cinematic_ad_expired_session_keyboard(lang),
            )
        product = pending.get("product")
        message = pending.get("message")
        save_cinematic_ad_concept(uid, product, message, value, lang)
        clear_cinematic_ad_pending(uid)
        return await safe_edit_or_send_long_html(
            query,
            cinematic_ad_concept_text(product, message, value, lang),
            reply_markup=cinematic_ad_continuation_keyboard(lang),
        )
    return await safe_edit_query_message(query, cinematic_ad_product_text(lang), reply_markup=cinematic_ad_product_keyboard(lang))

async def handle_cinematic_ad_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_cinematic_ad_pending(uid)
    if not pending:
        return False
    lang = user_ui_lang(uid)
    text = re.sub(r"\s+", " ", update.message.text.strip())[:500]
    if not text:
        return False
    step = pending.get("step") or "product"
    if step == "product":
        set_cinematic_ad_pending(uid, "message", text)
        await update.message.reply_text(cinematic_ad_message_text(text, lang), parse_mode="HTML", reply_markup=cinematic_ad_message_keyboard(lang))
        return True
    if step == "message":
        product = pending.get("product") or ("你的产品/服务" if normalize_user_language(lang) == "zh" else ("your product/service" if normalize_user_language(lang) != "vi" else "sản phẩm/dịch vụ của bạn"))
        set_cinematic_ad_pending(uid, "style", product, text)
        await update.message.reply_text(cinematic_ad_style_text(product, text, lang), parse_mode="HTML", reply_markup=cinematic_ad_style_keyboard(lang))
        return True
    product = pending.get("product") or ("你的产品/服务" if normalize_user_language(lang) == "zh" else ("your product/service" if normalize_user_language(lang) != "vi" else "sản phẩm/dịch vụ của bạn"))
    message = pending.get("message") or ("品牌信息" if normalize_user_language(lang) == "zh" else ("brand message" if normalize_user_language(lang) != "vi" else "thông điệp thương hiệu"))
    if step == "edit":
        style = str(pending.get("style") or "cinematic").strip() or "cinematic"
        if normalize_user_language(lang) == "zh":
            revised_message = f"{message}; 修改方向: {text}"
        elif normalize_user_language(lang) != "vi":
            revised_message = f"{message}; edit direction: {text}"
        else:
            revised_message = f"{message}; chỉnh theo yêu cầu: {text}"
        save_cinematic_ad_concept(uid, product, revised_message, style, lang)
        clear_cinematic_ad_pending(uid)
        await safe_reply_long_html(
            update.message,
            cinematic_ad_concept_text(product, revised_message, style, lang),
            reply_markup=cinematic_ad_continuation_keyboard(lang),
        )
        return True
    save_cinematic_ad_concept(uid, product, message, text, lang)
    clear_cinematic_ad_pending(uid)
    await safe_reply_long_html(
        update.message,
        cinematic_ad_concept_text(product, message, text, lang),
        reply_markup=cinematic_ad_continuation_keyboard(lang),
    )
    return True

