async def execute_image_warranty_retry(context: ContextTypes.DEFAULT_TYPE, chat_id, uid, parent_job_id: int, lang: str = "vi", edit_note: str = "") -> bool:
    parent = shopaikey_image_job_for_user(parent_job_id, uid)
    if not parent or image_job_retry_warranty_remaining(parent_job_id) <= 0:
        await context.bot.send_message(chat_id=chat_id, text=image_warranty_retry_exhausted_text(lang), reply_markup=image_warranty_retry_exhausted_keyboard(lang))
        return True
    if shopaikey_active_job_for_user(uid, "image"):
        await context.bot.send_message(chat_id=chat_id, text=ui_text(lang, "media.job_lock"))
        return True
    if not SHOPAIKEY_PUBLIC_IMAGE_ENABLED and not is_admin_user(uid):
        await context.bot.send_message(chat_id=chat_id, text=ui_text(lang, "media.public_off"))
        return True
    original = str(parent.get("prompt_preview") or "").strip()
    retry_aspect_ratio = infer_image_aspect_ratio_from_prompt(original, "9:16")
    adjustment = str(edit_note or "").strip()
    retry_prompt = (
        f"{original}\n\n"
        + (f"Warranty retry adjustment: {adjustment}\n" if adjustment else "Warranty retry: regenerate once with a cleaner result while keeping the same request.\n")
        + "Keep the same product/topic and make only a small revision. No watermark, no extra text."
    )[:1400]
    await context.bot.send_message(
        chat_id=chat_id,
        text=(
            "🔁 Đang tạo lại ảnh bảo hành. Bot không trừ thêm Xu.\nProvider có thể vẫn tốn credit thật."
            if normalize_user_language(lang) == "vi" else
            "🔁 Creating the warranty retry image. The bot will not charge extra Xu.\nThe provider may still consume real credit."
        ),
    )
    model = str(parent.get("model") or SHOPAIKEY_IMAGE_MODEL or "nano-banana")
    job_id = create_shopaikey_job(
        uid,
        chat_id,
        "image",
        model=model,
        prompt=retry_prompt,
        status="IN_PROGRESS",
        admin_only=is_admin_user(uid),
        xu_cost_planned=0,
        source_job_id=str(parent_job_id),
        retry_warranty_count=0,
        retry_warranty_parent_job_id=parent_job_id,
    )
    update_shopaikey_job(job_id=job_id, billing_status="warranty_retry", confirm_required=0, confirmed_at=now_text())
    result = await shopaikey_image_generate(retry_prompt, model, aspect_ratio=retry_aspect_ratio)
    status = str(result.get("status") or "FAIL")
    image_url = str(result.get("image_url") or "")
    b64_json = str(result.get("b64_json") or "")
    if status == "PASS" and (image_url or b64_json):
        update_shopaikey_job(job_id=job_id, status="SUCCESS", result_url=image_url, result_sent=0, model=result.get("model") or model, attempts=1, finished_at=now_text())
        caption = ui_text(
            lang,
            "image.success",
            label=html.escape(localized_image_tier_label("standard", lang)),
            job_id=int(job_id or 0),
            billing_note=html.escape("Đã dùng 1 lần tạo lại bảo hành. Bot không trừ thêm Xu." if normalize_user_language(lang) == "vi" else "Used 1 warranty retry. The bot did not charge extra Xu."),
        )
        caption = f"{caption}\n{image_aspect_result_line(result.get('aspect_ratio') or retry_aspect_ratio, lang)}"
        output_sent, output_file_id = await send_generated_image_result(
            context,
            chat_id,
            image_url,
            caption,
            public_image_success_keyboard(job_id, "standard", lang),
            lang,
            b64_json=b64_json,
        )
        if output_sent:
            parent_used = max(0, int(parent.get("retry_warranty_used") or 0)) + 1
            update_shopaikey_job(job_id=parent_job_id, retry_warranty_used=parent_used)
            update_shopaikey_job(job_id=job_id, result_sent=1, output_file_id=output_file_id)
            return True
        status = "FAIL_SEND_IMAGE"
        result["status"] = status
        result["error_class"] = "FAIL_SEND_IMAGE"
        result["detail"] = "telegram_image_output_send_failed"
    provider_error_text = result.get("detail") or result.get("provider_error_code") or result.get("error_class") or status
    update_shopaikey_job(
        job_id=job_id,
        status="FAILED",
        error_class=result.get("error_class") or status,
        provider_error_code=result.get("provider_error_code") or "",
        provider_message=provider_error_text,
        attempts=1,
        finished_at=now_text(),
        refund_status="not_charged",
        refund_reason="warranty_retry_provider_fail",
    )
    await context.bot.send_message(
        chat_id=chat_id,
        text=(
            "⚙️ Tạo lại ảnh bảo hành bị lỗi provider. Bot chưa trừ thêm Xu và chưa tính là đã dùng lượt bảo hành. Vui lòng thử lại sau."
            if normalize_user_language(lang) == "vi" else
            "⚙️ The warranty retry failed due to provider error. The bot did not charge extra Xu and did not consume the warranty retry. Please try again later."
        ),
    )
    return True

def canonical_image_quality_catalog_lines(lang: str = "vi") -> list[str]:
    if (normalize_user_language(lang) or "") not in {"vi"}:
        return [ui_text(lang, "image.choose_tier.title")]
    rows = ["🖼 <b>Chọn chất lượng ảnh</b>", ""]
    for tier in CANONICAL_IMAGE_TIER_ORDER:
        payload = canonical_image_tier_payload(tier)
        if not payload.get("enabled"):
            continue
        icon = str(payload.get("public_icon") or IMAGE_TIER_ICONS.get(tier) or "🖼")
        warranty = int(payload.get("retry_warranty_count") or 0)
        rows.extend([
            f"{icon} <b>{html.escape(str(payload.get('label') or 'Chất lượng ảnh'))} — {int(payload.get('cost') or 0)} Xu/ảnh</b>",
            f"• Mức chất lượng: {html.escape(str(payload.get('public_level') or payload.get('quality') or 'Rõ nét'))}.",
            f"• Phù hợp: {html.escape(str(payload.get('use_case') or payload.get('description') or 'Ảnh theo nội dung đã duyệt.'))}",
            (
                "• Bảo hành: kèm 1 lần tạo lại trong cùng yêu cầu."
                if warranty
                else "• Bảo hành: không kèm lần tạo lại miễn phí."
            ),
            "",
        ])
    rows.append("Xu chỉ được trừ sau khi bạn xem báo giá và xác nhận tạo ảnh.")
    return rows


def public_image_tier_selection_text(lang: str = "vi") -> str:
    return "\n".join(canonical_image_quality_catalog_lines(lang))

QUICK_IMAGE_FLOW_TTL_SECONDS = 10 * 60
QUICK_IMAGE_FLOW_STEPS = {
    "entry",
    "suggestions",
    "prepared_prompt",
    "custom_prompt",
    "logo_choice",
    "logo_input",
    "logo_position",
    "logo_confirm",
    "ratio",
    "tier",
    "confirm",
    "generating",
}

def quick_image_flow_pending_key(user_id) -> str:
    return f"quick_image_flow:{user_id}"

def set_quick_image_flow(user_id, step: str = "entry", **fields) -> dict:
    normalized_step = str(step or "entry").strip().lower()
    if normalized_step not in QUICK_IMAGE_FLOW_STEPS:
        normalized_step = "entry"
    current = USER_PENDING.get(quick_image_flow_pending_key(user_id)) or {}
    payload = {
        "pending_action": "quick_image_flow",
        "step": normalized_step,
        "created_at_ts": time.time(),
    }
    if current.get("pending_action") == "quick_image_flow":
        payload.update({key: value for key, value in current.items() if key not in {"step", "created_at_ts"}})
        payload["step"] = normalized_step
        payload["created_at_ts"] = time.time()
    for key, value in fields.items():
        if key in {
            "prompt", "prompt_source", "selected_topic", "negative_prompt", "original_request",
            "image_purpose", "purpose_label", "style", "suggested_ratio", "text_logo_caution",
            "logo_watermark_text", "ratio_back_target", "return_to", "return_label", "source_flow",
            "storyboard_scene_id", "storyboard_slot", "flow", "product", "owner", "session_id", "return_step",
            "generation_state", "idea_id", "material_type", "uiflow3_draft_id",
            "uiflow3_parent_product", "uiflow3_target_kind", "uiflow3_target_id",
            "uiflow3_return_step", "uiflow3_return_view", "uiflow3_active_character_id",
            "uiflow3_active_location_id",
        }:
            limit = 300 if key == "logo_watermark_text" else 1400
            payload[key] = re.sub(r"\s+", " ", str(value or "").strip())[:limit]
        elif key in {"aspect_ratio", "tier", "confirm_token"}:
            payload[key] = str(value or "").strip()[:120]
        elif key == "logo_watermark_position":
            payload[key] = logo_watermark_normalize_position(value) if str(value or "").strip() else ""
        elif key in {
            "suggest_offset", "prompt_variant", "storyboard_scene_index", "storyboard_prompt_version",
            "storyboard_target_index", "storyboard_target_count", "revision",
            "uiflow3_owner_user_id", "uiflow3_owner_chat_id", "uiflow3_ui_revision",
        }:
            payload[key] = max(0, _safe_int(value, 0))
        elif key in {"logo_watermark_enabled", "logo_watermark_decided"}:
            payload[key] = bool(value)
        elif key == "logo_watermark_source":
            payload[key] = str(value or "").strip()[:40]
    USER_PENDING[quick_image_flow_pending_key(user_id)] = payload
    return payload

def get_quick_image_flow(user_id) -> dict | None:
    key = quick_image_flow_pending_key(user_id)
    pending = USER_PENDING.get(key) or {}
    if pending.get("pending_action") != "quick_image_flow":
        return None
    if time.time() - float(pending.get("created_at_ts") or 0) > QUICK_IMAGE_FLOW_TTL_SECONDS:
        USER_PENDING.pop(key, None)
        return None
    return pending


