def quick_image_entry_keyboard(
    lang: str = "vi",
    *,
    state: dict | None = None,
    back_callback: str = "menu|main_image",
    back_label: str | None = None,
) -> InlineKeyboardMarkup:
    vi = normalize_user_language(lang) == "vi"
    state_data = dict(state or {})
    callback_prefix = (
        "vstoryimg"
        if str(state_data.get("owner") or "") == "storyboard_image"
        and str(state_data.get("flow") or "") == "storyboard"
        and str(state_data.get("product") or "") == "storyboard_prompt"
        else "create_media"
    )
    back_text = back_label or ("⬅️ Quay lại" if vi else "⬅️ Back")
    back_button = (
        InlineKeyboardButton(back_text, callback_data="menu|main_image")
        if back_callback == "menu|main_image"
        else InlineKeyboardButton(back_text, callback_data=back_callback)
    )
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("💡 Chọn từ 5 gợi ý" if vi else "💡 Choose from 5 ideas", callback_data=f"{callback_prefix}|qi_suggest"),
            InlineKeyboardButton("✍️ Tự nhập prompt" if vi else "✍️ Custom prompt", callback_data=f"{callback_prefix}|qi_custom"),
        ],
        [
            back_button,
            InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"),
        ],
    ])

def quick_image_suggestions_text(state: dict | None = None, lang: str = "vi") -> str:
    state = state or {}
    suggestions = quick_image_suggestions(_safe_int(state.get("suggest_offset"), 0), lang)
    if normalize_user_language(lang) != "vi":
        lines = ["✨ <b>Five image ideas</b>", "", "Choose an idea. TOAN AAS will prepare the full prompt before ratio and pricing.", ""]
    else:
        lines = ["✨ <b>5 ý tưởng gợi ý tạo ảnh</b>", "", "Chọn một ý tưởng. TOAN AAS sẽ soạn prompt hoàn chỉnh trước khi chọn tỉ lệ và giá.", ""]
    lines.extend(f"{idx}. {html.escape(item)}" for idx, item in enumerate(suggestions, 1))
    lines.extend(["", ui_text(lang, "common.no_api_no_charge")])
    return "\n".join(lines)

