def _engine_missing_values(values) -> list[str]:
    if values is None:
        return []
    if isinstance(values, str):
        raw_values = [values]
    else:
        raw_values = list(values or [])
    result = []
    seen = set()
    for item in raw_values:
        text = str(item or "").strip()
        if not text:
            continue
        marker = text.lower()
        if marker in seen:
            continue
        seen.add(marker)
        result.append(text)
    return result

def _engine_is_public_blocker(value: str) -> bool:
    marker = str(value or "").strip().lower()
    if not marker:
        return False
    if marker in ENGINE_PUBLIC_BLOCKER_TOKENS:
        return True
    return marker.endswith("_public_enabled") or marker.startswith("public_")

def engine_public_blockers(readiness: dict | None = None) -> list[str]:
    readiness = dict(readiness or {})
    blockers = _engine_missing_values(readiness.get("public_blockers"))
    blockers.extend(item for item in _engine_missing_values(readiness.get("missing")) if _engine_is_public_blocker(item))
    return _engine_missing_values(blockers)

def engine_technical_missing(readiness: dict | None = None) -> list[str]:
    readiness = dict(readiness or {})
    if "technical_missing" in readiness:
        return _engine_missing_values(readiness.get("technical_missing"))
    return [item for item in _engine_missing_values(readiness.get("missing")) if not _engine_is_public_blocker(item)]

def engine_readiness_payload(
    *,
    configured: bool,
    public_ready: bool,
    technical_missing: list[str] | None = None,
    public_blockers: list[str] | None = None,
    reason: str = "",
    **extra,
) -> dict:
    technical = _engine_missing_values(technical_missing)
    blockers = _engine_missing_values(public_blockers)
    payload = {
        **extra,
        "configured": bool(configured),
        "public_ready": bool(public_ready),
        "missing": technical,
        "technical_missing": technical,
        "public_blockers": blockers,
        "reason": reason or ",".join(technical or blockers) or "ready",
    }
    return payload

def admin_product_engine_missing_text(feature: str, readiness: dict | None = None) -> str:
    label = html.escape(engine_adapter_label(feature))
    if normalize_engine_feature(feature) == "music_song":
        missing = ", ".join(engine_technical_missing(readiness))
        detail = f" Thiếu: <code>{html.escape(missing[:220])}</code>." if missing else ""
        return f"⚙️ Admin test chưa chạy được: music_song thiếu component thật.{detail} Không gọi provider mới và không trừ Xu."
    missing = ", ".join(engine_technical_missing(readiness))
    detail = f" Thiếu: <code>{html.escape(missing[:220])}</code>." if missing else ""
    return f"⚙️ Admin test chưa chạy được: {label} thiếu component kỹ thuật hoặc cấu hình thật.{detail} Không gọi provider và không trừ Xu."

def _product_engine_readiness(product_area: str, action: str = "", state: dict | None = None) -> dict:
    area = str(product_area or "").strip().lower().replace("-", "_")
    state = dict(state or {})
    if area in {"voice", "voice_tts", "minimax", "minimax_tts"}:
        item = get_minimax_voice_readiness()
        tts_readiness = get_tts_provider_readiness(public=False)
        synth_adapter = globals().get("synthesize_standalone_tts_audio")
        adapter_overridden = callable(synth_adapter) and getattr(synth_adapter, "__name__", "") != "synthesize_standalone_tts_audio"
        fallback_public_ready = bool(
            voice_tts_product_public_enabled()
            and (
                adapter_overridden
                or tts_readiness.get("public_ready")
            )
        )
        configured = bool(
            tts_readiness.get("configured")
            or item.get("ready")
            or fallback_public_ready
        )
        tts_smoke_pass = provider_status_is_pass(str(item.get("last_tts_smoke") or preferred_tool_test_status_text("minimax_tts", "minimax_tts_key4u", "minimax_tts_shopaikey", "minimax_voice_job")))
        public_ready = bool(
            voice_tts_product_public_enabled()
            and configured
            and (
                item.get("product_public_enabled")
                or fallback_public_ready
                or item.get("public_enabled")
                or tts_smoke_pass
                or not MINIMAX_REQUIRE_SMOKE_PASS
            )
        )
        technical_missing = [] if tts_readiness.get("configured") else list(item.get("missing_env") or [])
        if not configured and "tts_provider_missing" not in technical_missing:
            technical_missing.append("tts_provider_missing")
        return engine_readiness_payload(
            configured=configured,
            public_ready=public_ready,
            technical_missing=technical_missing,
            public_blockers=[] if public_ready else ["public_flag"],
            reason=tts_readiness.get("reason") or item.get("reason") or item.get("admin_debug_reason") or "",
            provider=tts_readiness.get("provider") or item.get("provider") or "",
            model=tts_readiness.get("model") or item.get("model") or "",
            supported_voices=tts_readiness.get("supported_voices") or [],
            default_female_voice_id=tts_readiness.get("default_female_voice_id") or "",
            default_male_voice_id=tts_readiness.get("default_male_voice_id") or "",
            configured_providers=tts_readiness.get("configured_providers") or [],
            public_providers=tts_readiness.get("public_providers") or [],
        )
    if area in {"voice_clone", "minimax_clone", "minimax_voice_clone"}:
        item = get_minimax_voice_clone_readiness()
        configured = bool(item.get("ready"))
        public_ready = bool(item.get("public_enabled"))
        technical_missing = list(item.get("missing_env") or [])
        if item.get("provider_permission_blocked"):
            technical_missing.append("clone_permission_forbidden")
        return engine_readiness_payload(
            configured=configured,
            public_ready=public_ready,
            technical_missing=technical_missing,
            public_blockers=[] if public_ready else ["public_flag"],
            reason=item.get("reason") or "",
            admin_test_ready=bool(configured and not technical_missing),
            provider_permission_blocked=bool(item.get("provider_permission_blocked")),
            upload_adapter_missing=list(item.get("upload_adapter_missing") or []),
        )
    if area in {"music", "music_ai", "music_background", "music_song", "suno", "suno_music", "suno_song"}:
        item = get_suno_music_readiness()
        public_ready = bool(music_product_submit_public_ready(item, area))
        admin_real_test = _state_requests_admin_real_test(state)
        technical_missing = list(item.get("missing_env") or [])
        status_endpoint_ready = item.get("status_endpoint_ready", item.get("fetch_ready", True))
        if not status_endpoint_ready:
            technical_missing.append("music_status_route_missing")
        legacy_full_result_guard = "product_public_enabled" not in item
        public_blockers = [] if public_ready else ["public_flag"]
        if legacy_full_result_guard:
            if not item.get("download_ready", True):
                public_blockers.append("music_download_not_ready")
            if not item.get("full_result_ok", True):
                public_blockers.append("music_full_result_not_ready")
        return engine_readiness_payload(
            configured=bool(item.get("ready")),
            public_ready=public_ready and not bool(technical_missing),
            technical_missing=technical_missing,
            public_blockers=public_blockers,
            reason=item.get("reason") or item.get("admin_debug_reason") or "",
            admin_test_ready=bool(item.get("ready") and not technical_missing),
            admin_submit_ready=bool(item.get("ready")),
            admin_fetch_ready=bool(item.get("fetch_ready")),
            admin_download_ready=bool(item.get("download_ready")),
            partial_result_possible=bool(item.get("ready") and item.get("fetch_ready")),
        )
    subtitle_modes = {
        "subtitle": VIDEO_SUBTITLE_MODE_CREATE,
        "subtitle_auto": VIDEO_SUBTITLE_MODE_CREATE,
        "subtitle_create": VIDEO_SUBTITLE_MODE_CREATE,
        "translate": VIDEO_SUBTITLE_MODE_TRANSLATE,
        "translation": VIDEO_SUBTITLE_MODE_TRANSLATE,
        "subtitle_translate": VIDEO_SUBTITLE_MODE_TRANSLATE,
        "dub": VIDEO_SUBTITLE_MODE_DUB,
        "dubbing": VIDEO_SUBTITLE_MODE_DUB,
        "video_dub": VIDEO_SUBTITLE_MODE_DUB,
        "subtitle_plus_dub": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
    }
    if area in subtitle_modes:
        mode = normalize_video_translate_mode(action) or subtitle_modes[area]
        admin_cap = video_dubbing_capability(mode, state, public=False)
        public_cap = video_dubbing_capability(mode, state, public=True)
        admin_real_test = _state_requests_admin_real_test(state)
        technical_missing = [
            {
                "asr": "asr_adapter_missing",
                "translation": "subtitle_translate_adapter_missing",
                "tts": "video_dub_tts_adapter_missing",
            }.get(item, item)
            for item in _engine_missing_values(admin_cap.get("missing"))
            if not _engine_is_public_blocker(item)
        ]
        if (
            admin_real_test
            and getattr(video_dubbing_capability, "__name__", "") == "video_dubbing_capability"
            and not video_dubbing_state_has_subtitle_or_transcript(state)
            and not subdub_public_flag_with_override("VIDEO_ASR_ENABLED", VIDEO_ASR_ENABLED)
            and "asr_adapter_missing" not in technical_missing
        ):
            technical_missing.append("asr_adapter_missing")
        if admin_cap.get("reason") == "mode_disabled" and not admin_real_test:
            technical_missing = ["mode_disabled"]
        elif not admin_cap.get("ok") and not technical_missing:
            if not mode:
                technical_missing.append("mode_missing")
            else:
                needs_translation = mode == VIDEO_SUBTITLE_MODE_TRANSLATE or (
                    mode in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}
                    and bool(state.get("target_language") or str(state.get("translate_requested") or "") == "1")
                )
                if (
                    not video_dubbing_asr_ready_for_state(mode, state, public=False)
                    or (
                        not video_dubbing_state_has_subtitle_or_transcript(state)
                        and not video_asr_provider_available_for(public=False)
                    )
                ):
                    technical_missing.append("asr_adapter_missing")
                if needs_translation and not video_translation_provider_available():
                    technical_missing.append("subtitle_translate_adapter_missing")
                if mode in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB} and (not VIDEO_DUB_TTS_ENABLED or not video_tts_provider_available_for(public=False)):
                    technical_missing.append("video_dub_tts_adapter_missing")
        public_blockers = [
            item for item in _engine_missing_values(public_cap.get("missing"))
            if _engine_is_public_blocker(item)
        ]
        if public_cap.get("reason") in {"mode_disabled", "public_disabled"}:
            public_blockers.append("feature_flag" if public_cap.get("reason") == "mode_disabled" else "public_flag")
        return engine_readiness_payload(
            configured=not bool(technical_missing),
            public_ready=bool(public_cap.get("ok")) and not bool(technical_missing),
            technical_missing=technical_missing,
            public_blockers=public_blockers,
            reason=admin_cap.get("reason") or public_cap.get("reason") or "",
            admin_test_ready=bool(not technical_missing),
            partial_result_possible=bool(mode in {VIDEO_SUBTITLE_MODE_CREATE, VIDEO_SUBTITLE_MODE_TRANSLATE} or video_tts_provider_available_for(public=False)),
            mode_enabled=bool(video_dubbing_mode_flag(mode)),
            public_mode_enabled=bool(video_dubbing_public_flag(mode)),
        )
    if area in {"video", "video_export", "video_ai"}:
        admin_item = get_video_prompt_export_readiness(user_is_admin=True)
        public_item = get_video_prompt_export_readiness(user_is_admin=False)
        return engine_readiness_payload(
            configured=bool(admin_item.get("admin_ready")),
            public_ready=bool(public_item.get("public_ready")),
            technical_missing=list(admin_item.get("missing_admin") or []),
            public_blockers=[] if public_item.get("public_ready") else ["public_flag"],
            reason=admin_item.get("reason") or "",
        )
    if area in {"multiscene", "multi_scene", "video_multiscene"}:
        scene_count = safe_int(action, safe_int(state.get("scene_count"), 3))
        admin_real_test = _state_requests_admin_real_test(state)
        technical_missing = video_multiscene_missing_components(
            scene_count,
            include_smoke=not admin_real_test,
            require_stitch_verified=not admin_real_test,
        )
        public_ready = bool(video_multiscene_public_ready(scene_count))
        return engine_readiness_payload(
            configured=not bool(technical_missing),
            public_ready=public_ready and not bool(technical_missing),
            technical_missing=technical_missing,
            public_blockers=[] if public_ready else ["public_flag"],
            reason="ready" if not technical_missing else ",".join(technical_missing),
            admin_test_ready=bool(not technical_missing),
            stitch_verified=bool(video_multiscene_stitching_ready()),
        )
    if area in {"long_video", "longvideo", "video_long"}:
        public_ready = bool(VIDEO_LONG_RENDER_ENABLED and VIDEO_LONG_AI_PUBLIC_ENABLED)
        return engine_readiness_payload(
            configured=True,
            public_ready=public_ready,
            technical_missing=[],
            public_blockers=[] if public_ready else ["public_flag"],
            reason="ready" if VIDEO_LONG_RENDER_ENABLED else "long video render guarded; planning remains open",
        )
    return engine_readiness_payload(configured=True, public_ready=True, technical_missing=[], public_blockers=[], reason="unknown_area_allowed")

def can_user_access_product_engine(
    user_id,
    product_area,
    action,
    *,
    is_provider_call: bool = False,
    is_paid_job: bool = False,
    confirm_paid: bool = False,
    admin_interactive_confirm: bool = False,
    state: dict | None = None,
    confirmed_product: bool = False,
) -> dict:
    admin = is_admin_user(user_id)
    effective_confirm_paid = bool(confirm_paid or (admin and admin_interactive_confirm and is_provider_call))
    state_for_readiness = dict(state or {})
    if confirmed_product:
        state_for_readiness[SUBDUB_FINAL_CONFIRM_STATE_KEY] = True
    if admin and is_provider_call and effective_confirm_paid:
        state_for_readiness.update({
            "admin_real_test": True,
            "admin_interactive_confirm": bool(admin_interactive_confirm),
        })
    readiness = _product_engine_readiness(product_area, action, state_for_readiness)
    technical_missing = engine_technical_missing(readiness)
    if admin:
        if is_paid_job and not effective_confirm_paid:
            return {
                "allowed": False,
                "status": "blocked_admin_requires_confirm",
                "reason": f"missing {ADMIN_PAID_CONFIRM_FLAG}",
                "message": admin_paid_confirm_required_text(),
                "readiness": readiness,
            }
        if is_provider_call and (not readiness.get("configured") or technical_missing):
            readiness_reason = str(readiness.get("reason") or "").strip()
            blocked_reason = (
                ",".join(technical_missing)
                or (readiness_reason if readiness_reason and readiness_reason != "ready" else "")
                or "provider_not_configured"
            )
            return {
                "allowed": False,
                "status": "blocked_admin_missing_provider_config",
                "reason": blocked_reason,
                "message": admin_product_engine_missing_text(product_area, readiness),
                "readiness": readiness,
            }
        reason = "admin interactive product confirmation" if admin_interactive_confirm else "admin bypasses public gate"
        return {"allowed": True, "status": "allowed_admin", "reason": reason, "message": "", "readiness": readiness}
    if not is_provider_call:
        return {"allowed": True, "status": "allowed_public_draft", "reason": "draft/menu flow stays open", "message": "", "readiness": readiness}
    if not readiness.get("public_ready"):
        return {
            "allowed": False,
            "status": "blocked_public_maintenance",
            "reason": readiness.get("reason") or ",".join(readiness.get("missing") or []),
            "message": PUBLIC_PRODUCT_MAINTENANCE_VI,
            "readiness": readiness,
        }
    if is_paid_job and not confirm_paid:
        return {
            "allowed": False,
            "status": "blocked_public_requires_final_confirm",
            "reason": "missing final confirmation",
            "message": PUBLIC_PRODUCT_MAINTENANCE_VI,
            "readiness": readiness,
        }
    if not readiness.get("configured"):
        return {
            "allowed": False,
            "status": "blocked_public_maintenance",
            "reason": readiness.get("reason") or ",".join(readiness.get("missing") or []),
            "message": PUBLIC_PRODUCT_MAINTENANCE_VI,
            "readiness": readiness,
        }
    return {"allowed": True, "status": "allowed_public", "reason": "public ready", "message": "", "readiness": readiness}

def engine_action_for_feature(feature: str, params: dict | None = None) -> str:
    feature_key = normalize_engine_feature(feature)
    params = dict(params or {})
    if feature_key in {"subtitle_asr", "subtitle_auto", "subtitle_translate", "video_dub", "subtitle_plus_dub"}:
        state = dict(params.get("state") or {})
        return normalize_video_translate_mode(
            params.get("mode") or state.get("video_processing_mode") or state.get("mode") or state.get("process_type")
        )
    if feature_key in {"video_multiscene", "multiscene"}:
        order = dict(params.get("order") or params.get("order_or_session") or params.get("session") or {})
        session = dict(order.get("session") or order)
        scene_count = params.get("scene_count") or order.get("scene_count") or session.get("scene_count") or session.get("selected_scene_count")
        return str(safe_int(scene_count, 3))
    if feature_key in {"music", "music_background", "music_song"}:
        return "preview" if params.get("preview") else "confirm"
    if feature_key in {"voice_tts", "voice_saved_tts"}:
        return "tts"
    return str(params.get("action") or feature_key)

def evaluate_engine_gate(feature: str, params: dict | None = None, context: dict | None = None) -> dict:
    params = dict(params or {})
    context = dict(context or {})
    uid = context.get("user_id", params.get("user_id", 0))
    entry_source = str(context.get("entry_source") or ENGINE_ENTRY_SOURCE_PRODUCT)
    admin_interactive_confirm = bool(
        context.get("admin_interactive_confirm")
        or (entry_source == ENGINE_ENTRY_SOURCE_PRODUCT and context.get("confirm_paid"))
    )
    is_paid_job = bool(context.get("is_paid_job", is_admin_user(uid)))
    confirmed_product = bool(
        context.get("confirmed_product")
        or (
            entry_source == ENGINE_ENTRY_SOURCE_PRODUCT
            and context.get("confirm_paid")
            and normalize_engine_feature(feature) in {
                "subtitle_asr",
                "subtitle_auto",
                "subtitle_translate",
                "video_dub",
                "subtitle_plus_dub",
            }
        )
    )
    decision = can_user_access_product_engine(
        uid,
        engine_feature_product_area(feature),
        engine_action_for_feature(feature, params),
        is_provider_call=True,
        is_paid_job=is_paid_job,
        confirm_paid=bool(context.get("confirm_paid")),
        admin_interactive_confirm=admin_interactive_confirm,
        state=dict(params.get("state") or context.get("state") or {}),
        confirmed_product=confirmed_product,
    )
    decision["engine_feature"] = normalize_engine_feature(feature)
    decision["entry_source"] = entry_source
    decision["product_path_executor"] = ENGINE_PRODUCT_PATH_EXECUTOR
    if decision.get("status") == "blocked_admin_missing_provider_config":
        decision["message"] = admin_product_engine_missing_text(feature, decision.get("readiness"))
    return decision

def engine_output_bytes(payload) -> bytes:
    if isinstance(payload, (bytes, bytearray)):
        return bytes(payload)
    if isinstance(payload, io.BytesIO):
        return payload.getvalue()
    if isinstance(payload, dict):
        for key in ("output_bytes", "audio_bytes", "video_bytes", "subtitle_bytes", "bytes"):
            data = payload.get(key)
            if isinstance(data, (bytes, bytearray)):
                return bytes(data)
    return b""

def engine_provider_task_id(payload) -> str:
    if not isinstance(payload, dict):
        return ""
    for key in ("task_id", "provider_task_id", "parent_task_id", "job_id"):
        value = str(payload.get(key) or "").strip()
        if value:
            return value
    return ""

def engine_result_base(feature: str, status: str, *, ok: bool, detail: str = "", **extra) -> dict:
    return {
        "ok": bool(ok),
        "status": str(status or ("PASS" if ok else "FAIL")),
        "detail": sanitize_log_text(str(detail or ""))[:300],
        "engine_feature": normalize_engine_feature(feature),
        "adapter": engine_adapter_label(feature),
        "product_path_executor": ENGINE_PRODUCT_PATH_EXECUTOR,
        **extra,
    }

def engine_fail(feature: str, status: str, detail: str = "", **extra) -> dict:
    return engine_result_base(feature, status, ok=False, detail=detail, **extra)

def engine_success(feature: str, status: str = "PASS", detail: str = "", **extra) -> dict:
    return engine_result_base(feature, status, ok=True, detail=detail, **extra)

def music_engine_feature_for_result(result: dict | None = None) -> str:
    product_kind = music_result_product_kind(result)
    return "music_song" if product_kind in {"song_half", "song_full", "song_seconds"} else "music_background"

def music_confirm_product_label(result: dict | None = None, lang: str = "vi") -> str:
    result = dict(result or {})
    kind = music_result_product_kind(result)
    is_vi = music_ui_lang(lang=lang) == "vi"
    if kind == "song_half" and music_short_mode_verified():
        return "một bài hát hoàn chỉnh" if is_vi else "a complete song"
    if kind == "song_full":
        return "một bài hát hoàn chỉnh" if is_vi else "a complete song"
    if kind == "song_seconds":
        seconds = music_result_duration_seconds(result)
        return f"bài hát có lời {seconds} giây" if is_vi else f"a {seconds}s song with lyrics"
    seconds = music_result_duration_seconds(result)
    return f"bản đầy đủ {seconds} giây" if is_vi else f"a full {seconds}s background track"

def engine_readiness_registry() -> dict:
    features = [
        "voice_tts",
        "voice_clone",
        "music_background",
        "music_song",
        "subtitle_asr",
        "subtitle_translate",
        "video_dub",
        "subtitle_plus_dub",
        "video_single",
        "video_multiscene",
    ]
    payload = {}
    for feature in features:
        payload[feature] = {
            **_product_engine_readiness(engine_feature_product_area(feature), engine_action_for_feature(feature)),
            "adapter": engine_adapter_label(feature),
            "product_path_executor": ENGINE_PRODUCT_PATH_EXECUTOR,
        }
    return payload

# Only this object proves a gate decision came from inside the process.
# A caller cannot forge it by setting a key in a dict, which a bare
# "gate_prechecked": True could be. See engine_gate_precheck below.
_ENGINE_GATE_PRECHECK_TOKEN = object()
_ENGINE_GATE_PRECHECK_TTL_SECONDS = 10.0
# Keep the authoritative binding outside the caller-visible dict: the dict is
# mutable, while this private ticket registry is what execute_engine checks.
_ENGINE_GATE_PRECHECK_TICKETS: dict[object, tuple[str, str, str, float]] = {}


def _engine_gate_precheck_binding(
    feature: str,
    params: dict | None = None,
    context: dict | None = None,
) -> tuple[str, str, str]:
    params = dict(params or {})
    context = dict(context or {})
    feature_key = normalize_engine_feature(feature)
    user_id = context.get("user_id", params.get("user_id", 0))
    action = engine_action_for_feature(feature_key, params)
    return (
        feature_key,
        str(user_id if user_id is not None else "").strip(),
        str(action or "").strip().lower(),
    )


def _engine_gate_precheck_metadata(
    feature: str,
    params: dict | None = None,
    context: dict | None = None,
) -> dict:
    feature_key, user_id, action = _engine_gate_precheck_binding(feature, params, context)
    issued_at = time.monotonic()
    for ticket, binding in list(_ENGINE_GATE_PRECHECK_TICKETS.items()):
        ticket_age = issued_at - binding[3]
        if ticket_age > _ENGINE_GATE_PRECHECK_TTL_SECONDS:
            _ENGINE_GATE_PRECHECK_TICKETS.pop(ticket, None)
    ticket = object()
    _ENGINE_GATE_PRECHECK_TICKETS[ticket] = (feature_key, user_id, action, issued_at)
    return {
        "_precheck_token": _ENGINE_GATE_PRECHECK_TOKEN,
        "_precheck_ticket": ticket,
        "_precheck_feature": feature_key,
        "_precheck_user_id": user_id,
        "_precheck_action": action,
        "_precheck_issued_at": issued_at,
    }


def _engine_gate_precheck_ticket(candidate: dict) -> tuple[str, str, str, float] | None:
    if candidate.get("_precheck_token") is not _ENGINE_GATE_PRECHECK_TOKEN:
        return None
    try:
        return _ENGINE_GATE_PRECHECK_TICKETS.get(candidate.get("_precheck_ticket"))
    except TypeError:
        return None


def _engine_gate_precheck_is_live(issued_at: float) -> bool:
    try:
        issued_at = float(issued_at)
    except (TypeError, ValueError):
        return False
    if not math.isfinite(issued_at):
        return False
    age = time.monotonic() - issued_at
    return 0 <= age <= _ENGINE_GATE_PRECHECK_TTL_SECONDS


def engine_gate_precheck(feature: str, params: dict | None = None, context: dict | None = None) -> dict:
    """Run the product gate now and return a result execute_engine will accept.

    A caller that has already decided access — because it ran its own product
    export guard — uses this instead of asserting `gate_prechecked` and hoping
    the engine believes it. The returned object carries a token that only this
    module can produce, so the engine can tell a real decision from a claim.
    """
    decision = dict(evaluate_engine_gate(feature, params, context) or {})
    decision.update(_engine_gate_precheck_metadata(feature, params, context))
    return decision


def engine_gate_precheck_allow(feature: str, params: dict | None = None, context: dict | None = None, *, reason: str = "") -> dict:
    """Record an allow decision the caller has already made for itself.

    Same tamper-proof token, but the caller states plainly that it owns the
    decision. Kept separate from engine_gate_precheck so the two cases are
    distinguishable in code review and in the returned status.
    """
    params = dict(params or {})
    context = dict(context or {})
    feature_key = normalize_engine_feature(feature)
    decision = {
        "allowed": True,
        "status": "allowed_prechecked",
        "reason": reason or "caller already passed product export guard",
        "message": "",
        "readiness": _product_engine_readiness(
            engine_feature_product_area(feature_key),
            engine_action_for_feature(feature_key, params),
            dict(params.get("state") or {}),
        ),
        "engine_feature": feature_key,
        "entry_source": str(context.get("entry_source") or ENGINE_ENTRY_SOURCE_PRODUCT),
        "product_path_executor": ENGINE_PRODUCT_PATH_EXECUTOR,
    }
    decision.update(_engine_gate_precheck_metadata(feature_key, params, context))
    return decision


def engine_gate_precheck_result(
    context: dict | None,
    feature: str | None = None,
    params: dict | None = None,
) -> dict | None:
    """Return a live decision bound to the current engine invocation."""
    candidate = (context or {}).get("gate_precheck_result")
    if not isinstance(candidate, dict):
        return None
    binding = _engine_gate_precheck_ticket(candidate)
    if binding is None or not _engine_gate_precheck_is_live(binding[3]):
        return None
    # Preserve the old inspection-only call shape, while the execution path
    # below always supplies the invocation binding and therefore fails closed.
    if feature is None:
        return candidate
    expected_feature, expected_user_id, expected_action = _engine_gate_precheck_binding(feature, params, context)
    if (
        binding[0] != expected_feature
        or binding[1] != expected_user_id
        or binding[2] != expected_action
    ):
        return None
    return candidate


async def execute_engine(feature: str, params: dict | None = None, context: dict | None = None) -> dict:
    feature_key = normalize_engine_feature(feature)
    params = dict(params or {})
    context = dict(context or {})
    uid = context.get("user_id", params.get("user_id", 0))
    subdub_features = {"subtitle_asr", "subtitle_auto", "subtitle_translate", "video_dub", "subtitle_plus_dub"}
    prechecked = engine_gate_precheck_result(context, feature_key, params)
    if prechecked is not None and feature_key not in subdub_features:
        # A real decision object from inside the process. A bare
        # "gate_prechecked": True no longer skips the gate on its own: without
        # this token the engine evaluates the gate itself, below.
        gate = {key: value for key, value in prechecked.items() if not str(key).startswith("_precheck_")}
    else:
        gate = evaluate_engine_gate(feature_key, params, context)
    if not gate.get("allowed"):
        return engine_fail(
            feature_key,
            "GATE_BLOCKED",
            gate.get("reason") or gate.get("status") or "",
            gate=gate,
            message=gate.get("message") or "",
        )

    runner = params.get("runner")
    if callable(runner):
        runner_result = runner()
        if asyncio.iscoroutine(runner_result) or hasattr(runner_result, "__await__"):
            runner_result = await runner_result
        if isinstance(runner_result, dict) and runner_result.get("ok") is False:
            return engine_fail(
                feature_key,
                str(runner_result.get("status") or "RUNNER_FAILED"),
                runner_result.get("detail") or runner_result.get("text") or "",
                gate=gate,
                runner_result=runner_result,
                message=str(runner_result.get("text") or ""),
            )
        output_bytes = engine_output_bytes(runner_result)
        task_id = engine_provider_task_id(runner_result)
        runner_output_ready = bool(
            output_bytes
            or (
                isinstance(runner_result, dict)
                and (
                    runner_result.get("has_subtitle")
                    or runner_result.get("has_audio")
                    or runner_result.get("has_video")
                    or runner_result.get("preview_text")
                )
            )
        )
        runner_has_output = bool(runner_output_ready or task_id)
        status = "PASS" if runner_output_ready else ("PASS_SUBMITTED" if task_id else "RUNNER_DISPATCHED")
        return engine_success(
            feature_key,
            status,
            "runner completed",
            gate=gate,
            runner_result=runner_result,
            output_bytes=output_bytes,
            provider_task_id=task_id,
            job_created=bool(task_id),
            has_output_bytes=bool(output_bytes),
            runner_has_output=runner_has_output,
        )

    if feature_key in {"voice_tts", "voice_saved_tts", "voice"}:
        try:
            ok, audio_bytes, detail = await synthesize_standalone_tts_audio(
                str(params.get("text") or ""),
                voice_id=str(params.get("voice_id") or ""),
                voice_style=str(params.get("voice_style") or ""),
                speed=str(params.get("speed") or "normal"),
                provider_hint=str(params.get("provider_hint") or ""),
                allow_admin=bool(context.get("allow_admin") or is_admin_user(uid)),
            )
        except TypeError:
            ok, audio_bytes, detail = await synthesize_standalone_tts_audio(
                str(params.get("text") or ""),
                voice_id=str(params.get("voice_id") or ""),
                voice_style=str(params.get("voice_style") or ""),
                speed=str(params.get("speed") or "normal"),
            )
        if not ok or not audio_bytes:
            return engine_fail(feature_key, "NO_OUTPUT_BYTES", detail or "tts_empty", gate=gate)
        return engine_success(
            feature_key,
            "PASS",
            detail,
            gate=gate,
            output_bytes=bytes(audio_bytes),
            has_output_bytes=True,
            output_size=len(audio_bytes or b""),
        )

    if feature_key in {"music", "music_background", "music_song"}:
        result = dict(params.get("result") or {})
        try:
            submitted = await submit_music_generation_job(
                result,
                preview=bool(params.get("preview")),
                admin_smoke=bool(context.get("admin_smoke", is_admin_user(uid))),
                updated_by=context.get("updated_by", uid),
            )
        except TypeError:
            submitted = await submit_music_generation_job(result, preview=bool(params.get("preview")))
        task_id = str(submitted.get("task_id") or "").strip()
        output_bytes = engine_output_bytes(submitted)
        if not submitted.get("ok") or (not task_id and not output_bytes):
            return engine_fail(
                feature_key,
                "NO_PROVIDER_JOB",
                submitted.get("detail") or submitted.get("status") or "music_provider_no_task",
                gate=gate,
                provider_result=submitted,
            )
        return engine_success(
            feature_key,
            "PASS" if output_bytes else str(submitted.get("status") or "PASS_SUBMITTED"),
            submitted.get("detail") or "",
            gate=gate,
            provider_result=submitted,
            provider_task_id=task_id,
            job_created=bool(task_id),
            output_bytes=output_bytes,
            has_output_bytes=bool(output_bytes),
        )

    if feature_key in {"video_multiscene", "multiscene"}:
        order = dict(params.get("order") or params.get("order_or_session") or {})
        if params.get("blackbox"):
            started = await run_multiscene_blackbox_job(
                order,
                wait_for_completion=bool(params.get("wait_for_completion", False)),
                render_video_func=params.get("render_video_func"),
                sender=params.get("sender"),
            )
            task_id = str(started.get("parent_task_id") or "").strip() if isinstance(started, dict) else ""
            final_output = str((started or {}).get("final_output") or "") if isinstance(started, dict) else ""
            final_output_ok = bool(final_output and os.path.exists(final_output) and os.path.getsize(final_output) > 0)
            async_submission = bool(not params.get("wait_for_completion", False) and task_id and (started or {}).get("background_started"))
            if not final_output_ok and not async_submission:
                return engine_fail(
                    feature_key,
                    str((started or {}).get("status") or "BLACKBOX_NO_OUTPUT"),
                    str((started or {}).get("message") or ""),
                    gate=gate,
                    provider_result=started,
                    message=str((started or {}).get("message") or ""),
                )
            return engine_success(
                feature_key,
                "PASS" if final_output_ok else "PASS_SUBMITTED",
                "multiscene blackbox output ready" if final_output_ok else "multiscene blackbox job submitted",
                gate=gate,
                provider_result=started,
                provider_task_id=task_id,
                job_created=bool(task_id),
                final_output=final_output,
                has_output_bytes=final_output_ok,
            )
        if is_admin_user(uid) and bool(context.get("admin_interactive_confirm") or context.get("confirm_paid")):
            order["admin_test"] = True
            order["confirm_paid"] = True
        started = await run_multiscene_video_job(order, wait_for_completion=bool(params.get("wait_for_completion", True)))
        task_id = str(started.get("parent_task_id") or "").strip() if isinstance(started, dict) else ""
        final_output = str((started or {}).get("final_output") or "") if isinstance(started, dict) else ""
        final_output_ok = bool(final_output and os.path.exists(final_output) and os.path.getsize(final_output) > 0)
        async_submission = bool(not params.get("wait_for_completion", True) and task_id)
        if not final_output_ok and not async_submission:
            return engine_fail(
                feature_key,
                "NO_OUTPUT_BYTES",
                str((started or {}).get("status") if isinstance(started, dict) else "multiscene_no_output"),
                gate=gate,
                provider_result=started,
            )
        return engine_success(
            feature_key,
            "PASS" if final_output_ok else "PASS_SUBMITTED",
            "multiscene output ready" if final_output_ok else "multiscene provider job submitted",
            gate=gate,
            provider_result=started,
            provider_task_id=task_id,
            job_created=bool(task_id),
            final_output=final_output,
            has_output_bytes=final_output_ok,
        )

    if feature_key in {"subtitle_asr", "subtitle_auto", "subtitle_translate", "video_dub", "subtitle_plus_dub", "video_single", "video"}:
        return engine_fail(feature_key, "ADAPTER_MISSING", "runner adapter required", gate=gate)

    return engine_fail(feature_key, "ADAPTER_MISSING", "unknown engine feature", gate=gate)

