def video_finalization_selected_aspect(state: dict | None = None) -> str:
    state = dict(state or {})
    payload = dict(state.get("source_payload") or {})
    project = dict(state.get("video_project") or {})
    for value in (
        state.get("selected_video_aspect_ratio"),
        state.get("aspect_ratio"),
        payload.get("aspect_ratio"),
        payload.get("ratio"),
        project.get("aspect_ratio"),
    ):
        text = str(value or "").strip()
        if text:
            return normalize_media_aspect_ratio(text, "9:16", "video")
    return "9:16"

VIDEO_FINALIZATION_ASPECT_CHOICES = ("9:16", "16:9", "1:1", "4:5")

def _video_finalization_valid_aspect(value) -> str:
    raw = str(value or "").strip().lower().replace("x", ":").replace(" ", "")
    if raw in set(media_aspect_ratio_options("video")):
        return raw
    return ""

def _video_finalization_aspect_sources(state: dict | None = None) -> list[dict]:
    state = dict(state or {})
    source_payload = dict(state.get("source_payload") or {})
    pending_payload = dict(state.get("pending_payload") or {})
    # build_video_project may inject a default aspect ratio. For the aspect gate
    # we only treat values carried by the flow state/payload as an actual choice.
    return [
        state,
        source_payload,
        pending_payload,
        dict(state.get("session_context") or {}),
    ]

def video_finalization_explicit_aspect(state: dict | None = None) -> str:
    state = dict(state or {})
    skip_selected = bool(state.get("source_media_aspect_defaulted"))
    for source in _video_finalization_aspect_sources(state):
        for key in (
            "selected_video_aspect_ratio",
            "aspect_ratio",
            "ratio",
            "preferred_aspect_ratio",
            "source_aspect_ratio",
            "media_aspect_ratio",
            "original_aspect_ratio",
        ):
            if skip_selected and key == "selected_video_aspect_ratio" and source is state:
                continue
            aspect = _video_finalization_valid_aspect(source.get(key))
            if aspect:
                return normalize_media_aspect_ratio(aspect, "9:16", "video")
    return ""

def video_finalization_has_source_media(state: dict | None = None) -> bool:
    state = dict(state or {})
    payload = dict(state.get("source_payload") or {})
    project = dict(state.get("video_project") or {})
    source_tokens = {
        str(state.get("source") or "").strip().lower(),
        str(payload.get("source") or "").strip().lower(),
        str(payload.get("source_flow") or "").strip().lower(),
        str(payload.get("product_id") or "").strip().lower(),
        str(project.get("source") or "").strip().lower(),
    }
    media_sources = {
        "imagevideo",
        "videoref",
        "image_to_video",
        "reference_video_plan",
        "video_reference",
        "video_ref",
        "selfscene",
        "self_shot_scene_change",
        "image_upload",
        "video_upload",
        "upload_image",
        "upload_video",
    }
    media_keys = (
        "source_media_ref",
        "source_file_id",
        "source_video_file_id",
        "input_video_file_id",
        "telegram_file_id",
        "video_file_id",
        "image_file_id",
        "source_image_file_id",
        "source_image_url",
        "source_video_url",
    )
    sources = [state, payload, project]
    has_media_marker = any(
        bool(source.get(key))
        for source in sources
        for key in media_keys
    )
    has_media_marker = has_media_marker or any(bool(source.get("photos")) for source in sources if any(token in media_sources for token in source_tokens))
    if any(token in media_sources for token in source_tokens) and has_media_marker:
        return True
    return any(bool(source.get("source_media_ref")) for source in sources)

def video_finalization_needs_aspect_choice(state: dict | None = None) -> bool:
    state = dict(state or {})
    if video_finalization_explicit_aspect(state):
        return False
    return not video_finalization_has_source_media(state)

def video_finalization_aspect_display(state: dict | None = None, lang: str = "vi") -> str:
    state = dict(state or {})
    if state.get("source_media_aspect_defaulted") and str(state.get("aspect_source") or "") == "source_media":
        lang = normalize_user_language(lang) or "vi"
        return public_video_deep_copy(lang)["source_aspect"]
    return video_finalization_selected_aspect(state)

def video_finalization_apply_aspect(state: dict | None = None, aspect_ratio: str = "", source: str = "user_selected") -> dict:
    current = dict(state or {})
    aspect = normalize_media_aspect_ratio(aspect_ratio, "9:16", "video")
    current["selected_video_aspect_ratio"] = aspect
    current["aspect_ratio"] = aspect
    current["aspect_source"] = str(source or "user_selected")[:40]
    current["source_media_aspect_defaulted"] = False
    for key in ("source_payload", "pending_payload", "video_project"):
        payload = dict(current.get(key) or {})
        payload["aspect_ratio"] = aspect
        current[key] = payload
    session_context = dict(current.get("session_context") or {})
    session_context["aspect_ratio"] = aspect
    current["session_context"] = session_context
    return current

def video_finalization_prepare_aspect_state(state: dict | None = None) -> dict:
    current = dict(state or {})
    explicit = video_finalization_explicit_aspect(current)
    if explicit:
        return video_finalization_apply_aspect(current, explicit, str(current.get("aspect_source") or "provided"))
    if video_finalization_has_source_media(current):
        aspect = video_finalization_selected_aspect(current)
        current = video_finalization_apply_aspect(current, aspect, "source_media")
        current["source_media_aspect_defaulted"] = True
        return current
    return current

def video_finalization_aspect_text(state: dict | None = None, lang: str = "vi") -> str:
    state = dict(state or {})
    source = state.get("source_label") or video_finalization_source_label(state.get("source"), lang)
    lang = normalize_user_language(lang) or "vi"
    copy = public_video_deep_copy(lang)
    return (
        f"<b>{copy['aspect_title']}</b>\n\n"
        f"{copy['source']}: <b>{html.escape(str(source))}</b>\n\n"
        f"{copy['available_ratios']}: <b>9:16 / 16:9 / 1:1 / 4:5</b>\n\n"
        f"{copy['choose_aspect']}. {copy['common_no_charge']}."
    )

def video_finalization_aspect_keyboard(lang: str = "vi") -> InlineKeyboardMarkup:
    lang = normalize_user_language(lang) or "vi"
    copy = public_video_deep_copy(lang)
    labels = {
        "9:16": "📱 9:16",
        "16:9": "📺 16:9",
        "1:1": "⬛ 1:1",
        "4:5": "🖼 4:5",
    }
    rows = [
        [
            InlineKeyboardButton(labels["9:16"], callback_data="vfinal|aspect|9x16"),
            InlineKeyboardButton(labels["16:9"], callback_data="vfinal|aspect|16x9"),
        ],
        [
            InlineKeyboardButton(labels["1:1"], callback_data="vfinal|aspect|1x1"),
            InlineKeyboardButton(labels["4:5"], callback_data="vfinal|aspect|4x5"),
        ],
        [
            InlineKeyboardButton(copy["back"], callback_data="vfinal|back"),
            InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main"),
        ],
    ]
    return InlineKeyboardMarkup(rows)

async def video_finalization_render_aspect(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = dict(state or get_video_finalization_state(user_id) or {})
    current["step"] = "aspect"
    current["aspect_screen_shown"] = True
    set_video_finalization_state(user_id, current)
    return await safe_edit_or_send(
        query,
        video_finalization_aspect_text(current, lang),
        parse_mode="HTML",
        reply_markup=video_finalization_aspect_keyboard(lang),
    )

async def video_finalization_render_menu(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = video_finalization_prepare_aspect_state(state or get_video_finalization_state(user_id) or {})
    if video_finalization_needs_aspect_choice(current):
        return await video_finalization_render_aspect(query, user_id, current, lang)
    current["step"] = "menu"
    current["return_to_invoice"] = False
    current["addon_return_target"] = "package"
    set_video_finalization_state(user_id, current)
    return await safe_edit_or_send(
        query,
        video_finalization_menu_text(current, lang),
        parse_mode="HTML",
        reply_markup=video_finalization_menu_keyboard(lang),
    )

def video_finalization_package_from_state(state: dict | None = None) -> dict:
    state = dict(state or {})
    package = video_finalization_payload(state)
    package.setdefault("source", str(state.get("source") or "promptvideo")[:80])
    package.setdefault("source_flow", str(state.get("source") or "promptvideo")[:80])
    package.setdefault("video_prompt", video_finalization_prompt_text(state))
    package.setdefault("prompt", video_finalization_prompt_text(state))
    package.setdefault("concept_text", str((state.get("session_context") or {}).get("script") or "")[:1200])
    package.setdefault("video_project", dict(state.get("video_project") or {}))
    for key in (
        "source_file_id",
        "source_video_file_id",
        "input_video_file_id",
        "telegram_file_id",
        "source_file_name",
        "source_mime_type",
        "source_duration",
        "source_file_size",
        "object_prompt",
        "direction_prompt",
        "selected_topic",
        "selected_context",
        "selected_motion",
        "selected_music",
        "invoice_id",
        "add_on_origin",
        "addon_origin",
    ):
        if not package.get(key) and state.get(key):
            package[key] = state.get(key)
    return package

def video_scene_selection_info(state: dict | None = None) -> dict:
    state = dict(state or {})
    sources = [
        state,
        dict(state.get("source_payload") or {}),
        dict(state.get("pending_payload") or {}),
        dict(state.get("video_project") or {}),
        dict((state.get("pending_payload") or {}).get("video_project") or {}),
        dict((state.get("source_payload") or {}).get("video_project") or {}),
    ]
    selected = 0
    for source in sources:
        selected = safe_int(source.get("selected_scene_count") or 0, 0)
        if selected > 0:
            break
    if selected <= 0:
        return {}
    scene_seconds = 0
    duration = 0
    duration_mode = ""
    note = ""
    for source in sources:
        scene_seconds = scene_seconds or safe_int(source.get("estimated_scene_seconds") or source.get("scene_duration_seconds") or 0, 0)
        duration = duration or safe_int(source.get("estimated_duration_seconds") or 0, 0)
        duration_mode = duration_mode or str(source.get("duration_mode") or "").strip()
        note = note or str(source.get("duration_note") or "").strip()
    scene_seconds = max(1, scene_seconds or TASK3D_SCENE_SECONDS)
    duration = duration or selected * scene_seconds
    return {
        "selected_scene_count": selected,
        "estimated_scene_seconds": scene_seconds,
        "estimated_duration_seconds": duration,
        "duration_mode": duration_mode or "scene_based",
        "duration_note": note or f"{selected} cảnh, khoảng {duration} giây",
    }

def video_scene_selection_summary_lines(state: dict | None = None, lang: str = "vi", invoice: bool = False) -> list[str]:
    info = video_scene_selection_info(state)
    if not info:
        return []
    count = int(info["selected_scene_count"])
    duration = int(info["estimated_duration_seconds"])
    scene_seconds = int(info["estimated_scene_seconds"])
    if normalize_user_language(lang) != "vi":
        calc = f"each scene/clip is about {scene_seconds} seconds" if invoice else f"1 scene ≈ {scene_seconds} seconds"
        lines = [
            f"Scene count: <b>{count} scene{'s' if count != 1 else ''}</b>",
            f"Estimated duration: <b>about {duration} seconds</b>",
            f"Calculation: <b>{html.escape(calc)}</b>",
        ]
        if count >= 10 and not invoice:
            lines.append("Longer multi-scene videos may take more time. TOAN AAS will confirm before processing or charging Xu.")
        return lines
    calc = f"mỗi cảnh/clip khoảng {scene_seconds} giây" if invoice else f"1 cảnh ≈ {scene_seconds} giây"
    lines = [
        f"Số cảnh: <b>{count} cảnh</b>",
        f"Thời lượng ước tính: <b>khoảng {duration} giây</b>",
        f"Cách tính: <b>{html.escape(calc)}</b>",
    ]
    if count >= 10 and not invoice:
        lines.append("Video nhiều cảnh có thể mất lâu hơn và có thể cần ghép nhiều clip. TOAN AAS sẽ báo lại trước khi xử lý/trừ Xu.")
    return lines

def video_finalization_invoice_active(user_id, state: dict | None = None) -> bool:
    state = dict(state or {})
    if str(state.get("addon_return_target") or "").strip().lower() == "invoice":
        return True
    addon_state = get_video_addon_state(user_id)
    if addon_state:
        return True
    return str(state.get("step") or "").strip().lower() == "confirm"

def video_finalization_set_origin(state: dict | None, origin_screen: str) -> dict:
    current = dict(state or {})
    origin = str(origin_screen or "video_options").strip().lower()
    stack = [str(item) for item in (current.get("screen_stack") or []) if str(item or "").strip()]
    if not stack or stack[-1] != origin:
        stack.append(origin)
    current["origin_screen"] = origin
    current["return_to_invoice"] = origin == "invoice"
    current["screen_stack"] = stack[-8:]
    current["addon_return_target"] = "invoice" if origin == "invoice" else "hub"
    return current

async def video_finalization_render_invoice(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = dict(state or get_video_finalization_state(user_id) or {})
    addon_state = get_video_addon_state(user_id)
    if addon_state:
        current["step"] = "confirm"
        current["origin_screen"] = "invoice"
        current["return_to_invoice"] = True
        current["addon_return_target"] = "invoice"
        set_video_finalization_state(user_id, current)
        return await render_video_addon_screen(query, user_id, addon_state, "invoice", lang)
    return await video_finalization_continue_to_invoice_or_tier(query, user_id, current, lang)

def video_finalization_addon_return_target(user_id, state: dict | None = None) -> str:
    return "invoice" if video_finalization_invoice_active(user_id, state) else "hub"

def video_finalization_merge_pending_payload(existing: dict | None, new_payload: dict | None) -> dict:
    existing = dict(existing or {})
    merged = {**existing, **dict(new_payload or {})}
    for key in (
        "source_file_id",
        "source_video_file_id",
        "input_video_file_id",
        "telegram_file_id",
        "source_file_name",
        "source_mime_type",
        "source_duration",
        "source_file_size",
        "object_prompt",
        "direction_prompt",
        "selected_topic",
        "selected_context",
        "selected_motion",
        "selected_music",
        "invoice_id",
        "add_on_origin",
        "addon_origin",
    ):
        if not merged.get(key) and existing.get(key):
            merged[key] = existing.get(key)
    return merged

async def video_finalization_return_after_addon(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = dict(state or get_video_finalization_state(user_id) or {})
    if not current:
        return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
    clear_video_addon_state(user_id)
    current = video_finalization_prepare_aspect_state(current)
    current["step"] = "menu"
    current["return_to_invoice"] = False
    current["addon_return_target"] = "hub"
    set_video_finalization_state(user_id, current)
    return await safe_edit_or_send(
        query,
        video_finalization_menu_text(current, lang),
        parse_mode="HTML",
        reply_markup=video_finalization_menu_keyboard(lang),
    )

async def video_finalization_continue_to_invoice_or_tier(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = dict(state or get_video_finalization_state(user_id) or {})
    if not current:
        return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
    tier = normalize_video_tier(current.get("selected_video_tier") or "")
    has_selected_tier = bool(current.get("selected_video_tier"))
    if has_selected_tier and video_finalization_has_prompt(current):
        current["selected_video_tier"] = tier
        current["selected_video_aspect_ratio"] = video_finalization_selected_aspect(current)
        if not video_scene_selection_info(current):
            if current.get("addon_return_target") == "invoice" or current.get("return_to_invoice"):
                current = video_finalization_apply_scene_count_fields(current, 1, user_id)
            else:
                return await video_finalization_render_scene_count(query, user_id, current, lang)
        current["step"] = "confirm"
        set_video_finalization_state(user_id, current)
        status = get_public_video_tier_ui_status(tier, is_admin_user(user_id))
        if not status.get("enabled"):
            return await safe_edit_or_send(
                query,
                video_finalization_tier_guard_text(tier, lang),
                parse_mode="HTML",
                reply_markup=video_finalization_tier_guard_keyboard(lang),
            )
        package = video_finalization_package_from_state(current)
        aspect = video_finalization_selected_aspect(current)
        pending_payload = public_video_pending_payload_from_package(tier, package, aspect)
        pending_payload.update({
            "video_finalization": dict(package.get("video_finalization") or {}),
            "video_finalization_confirmed": True,
            "video_addon_ready_for_invoice": True,
            "source": str(current.get("source") or package.get("source") or "promptvideo")[:80],
            "source_flow": str(current.get("source") or package.get("source_flow") or "promptvideo")[:80],
        })
        set_public_video_package_context(user_id, pending_payload)
        return await start_video_addon_step(query, user_id, pending_payload, tier, lang, source="ai")
    current["step"] = "tier"
    set_video_finalization_state(user_id, current)
    return await safe_edit_or_send(
        query,
        video_finalization_tier_text(current, lang),
        parse_mode="HTML",
        reply_markup=video_finalization_tier_keyboard(lang),
    )

def ensure_video_finalization_from_addon_state(user_id, addon_state: dict | None = None) -> dict:
    addon_state = dict(addon_state or {})
    pending = dict(addon_state.get("pending_payload") or {})
    current = dict(get_video_finalization_state(user_id) or {})
    source_payload = video_finalization_merge_pending_payload(
        current.get("source_payload") or {},
        pending,
    )
    current.update({
        "step": "menu",
        "addon_return_target": "hub",
        "source_payload": source_payload,
        "selected_video_tier": normalize_video_tier(
            current.get("selected_video_tier")
            or addon_state.get("video_tier")
            or pending.get("video_tier")
            or "low"
        ),
        "source": str(current.get("source") or addon_state.get("source") or pending.get("source") or "video_addon")[:80],
        "source_label": current.get("source_label") or addon_state.get("source_label") or "",
        "video_order": dict(addon_state.get("video_order") or current.get("video_order") or {}),
    })
    if pending.get("aspect_ratio") and not current.get("selected_video_aspect_ratio"):
        current["selected_video_aspect_ratio"] = normalize_media_aspect_ratio(
            str(pending.get("aspect_ratio")),
            "9:16",
            "video",
        )
    finalization = video_finalization_defaults()
    finalization.update(dict(current.get("video_finalization") or {}))
    finalization.update(dict(pending.get("video_finalization") or {}))
    finalization.update(video_audio_settings_from_state({**addon_state, **current, "video_finalization": finalization, "pending_payload": pending}))
    current["video_finalization"] = finalization
    current = video_audio_apply_settings_to_state(current, finalization)
    return set_video_finalization_state(user_id, current)

def video_finalization_tier_text(state: dict | None = None, lang: str = "vi") -> str:
    state = dict(state or {})
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or {}))
    source = state.get("source_label") or video_finalization_source_label(state.get("source"), lang)
    has_prompt = video_finalization_has_prompt(state)
    lang = normalize_user_language(lang) or "vi"
    copy = public_video_deep_copy(lang)
    yes, no = copy["yes"], copy["no"]
    return (
        f"<b>{copy['tier_title']}</b>\n\n"
        f"{copy['source']}: <b>{html.escape(str(source))}</b>\n"
        f"{copy['video_prompt']}: <b>{yes if has_prompt else no}</b>\n"
        f"{copy['script']}: <b>{yes if state.get('has_script') else no}</b>\n"
        f"{copy['images_scenes']}: <b>{yes if developing_video_frame_photos(state) else no}</b>\n"
        f"{copy['music']}: <b>{yes if finalization['music_enabled'] else no}</b>\n"
        f"{copy['voice']}: <b>{yes if finalization['voice_enabled'] else no}</b>\n"
        f"{copy['subtitles']}: <b>{yes if finalization['subtitle_enabled'] else no}</b>\n\n"
        f"{copy['select_package']}:\n"
        + "\n".join(video_tier_price_line(tier, lang) for tier in VIDEO_PUBLIC_TIER_UI_ORDER)
        + f"\n\n{copy['choose_scene_next']}.\n\n{copy['common_no_charge']}."
    )

def video_finalization_tier_keyboard(lang: str = "vi") -> InlineKeyboardMarkup:
    lang = normalize_user_language(lang) or "vi"
    copy = public_video_deep_copy(lang)
    def label(tier: str) -> str:
        return video_tier_button_text(tier, lang)
    buttons = [
        InlineKeyboardButton(label(tier), callback_data=f"vfinal|tier|{tier}")
        for tier in VIDEO_PUBLIC_TIER_UI_ORDER
    ]
    buttons.append(InlineKeyboardButton("⚙️ " + copy["extra_options"], callback_data="vfinal|menu"))
    rows = [buttons[index:index + 2] for index in range(0, len(buttons), 2)]
    rows.append([
        InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vfinal|back"),
        InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main"),
    ])
    return InlineKeyboardMarkup(rows)

def video_scene_count_price_line(tier: str, scene_count, lang: str = "vi", html_bold_total: bool = True) -> str:
    count = product_video_r9_scene_count(scene_count)
    price = product_video_r9_scene_pricing(count, tier=tier)
    seconds = int(price["estimated_seconds"])
    effective_each = int(price["unit_charge_xu"])
    subtotal = int(price["list_total_xu"])
    discount_percent = int(price["discount_percent"])
    discount_xu = int(price["discount_xu"])
    total = int(price["charge_total_xu"])
    total_text = f"<b>{xu_number(total)} Xu</b>" if html_bold_total else f"{xu_number(total)} Xu"
    lang = normalize_user_language(lang) or "vi"
    copy = public_video_deep_copy(lang)
    formula = f"{xu_number(effective_each)} × {count} = {xu_number(subtotal)} Xu"
    if discount_percent:
        formula += f"; -{discount_percent}% (-{xu_number(discount_xu)} Xu) = {total_text}"
    scene_label = copy["scene"] if count == 1 else copy["scenes"]
    return f"• {count} {scene_label} ≈ {seconds} {copy['seconds']} — {formula}"

def video_scene_count_option_label(tier: str, scene_count, lang: str = "vi") -> str:
    count = product_video_r9_scene_count(scene_count)
    price = product_video_r9_scene_pricing(count, tier=tier)
    seconds = int(price["estimated_seconds"])
    total = int(price["charge_total_xu"])
    discount = int(price["discount_percent"])
    discount_note = f" · -{discount}%" if discount else ""
    lang = normalize_user_language(lang) or "vi"
