def video_quote_invoice_text(quote: dict, state: dict | None = None, lang: str = "vi") -> str:
    locale = normalize_user_language(lang) or "vi"
    copy = public_video_deep_copy(locale)
    quote = dict(quote or {})
    state = dict(state or {})
    tier = normalize_video_tier(quote.get("tier") or state.get("video_tier") or "low")
    count = max(1, int(quote.get("scene_count") or 1))
    seconds = int(quote.get("estimated_seconds") or count * TASK3D_SCENE_SECONDS)
    unit = int(
        quote.get("scene_unit_price_xu")
        or quote.get("package_base_xu")
        or PRODUCT_VIDEO_R9_PROMO_PRICE_PER_SCENE_XU
    )
    subtotal = int(quote.get("scene_list_total_xu") or unit * count)
    video_xu = int(quote.get("scene_video_xu") or subtotal)
    discount_percent = int(
        quote.get("multiscene_discount_percent")
        or max(0, 100 - int(quote.get("scene_discount_percent") or 100))
    )
    discount_xu = int(quote.get("scene_discount_xu") or max(0, subtotal - video_xu))
    addon_xu = int(quote.get("addon_fee_xu") or 0)
    total_xu = int(quote.get("total_xu") or video_xu + addon_xu)
    equivalent = int(quote.get("estimated_vnd") or total_xu * int(XU_TO_VND or 100))
    package_label = video_tier_short_label(tier, locale)

    def addon_label(item: dict) -> str:
        key = str(item.get("key") or "").strip().lower()
        if "music" in key or "sfx" in key:
            return copy["music"]
        if "voice" in key or "dub" in key:
            return copy["voice"]
        if "subtitle" in key or "translate" in key:
            return copy["subtitles"]
        if "logo" in key or "watermark" in key:
            return copy["logo_watermark"]
        return copy["addons"]

    paid_items = video_order_dedupe_items(quote.get("paid_items") or [])
    addon_lines = "\n".join(
        f"• {addon_label(item)}: <b>+{xu_number(item.get('price_xu'))} Xu</b>"
        for item in paid_items
    ) or f"• {copy['none']}: <b>0 Xu</b>"
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or {}))
    branding_text = logo_watermark_clean_text(
        finalization.get("logo_watermark_text")
        if finalization.get("logo_watermark_enabled")
        else ""
    )
    branding_line = ""
    if branding_text:
        branding_position = logo_watermark_position_label(
            finalization.get("logo_watermark_position") or "",
            locale,
        )
        branding_line = (
            f"• {copy['logo_watermark']}: <b>{html.escape(branding_text)}</b> · "
            f"{html.escape(branding_position)}\n"
        )
    discount_line = (
        f"-{discount_percent}% (-{xu_number(discount_xu)} Xu)"
        if discount_percent
        else "0%"
    )
    scene_label = copy["scene"] if count == 1 else copy["scenes"]
    return (
        f"<b>{copy['invoice_title']}</b>\n\n"
        f"{copy['tier_title']}: <b>{html.escape(package_label)}</b>\n"
        f"{copy['scene_title']}: <b>{count} {scene_label}</b>\n"
        f"{copy['video_duration']}: <b>{seconds} {copy['seconds']}</b>\n"
        f"{copy['per_scene']}: <b>{xu_number(unit)} Xu</b>\n"
        f"{copy['multiscene_discount']}: <b>{discount_line}</b>\n"
        f"{copy['price_by_scene']}: <b>{xu_number(unit)} × {count} = {xu_number(subtotal)} Xu → {xu_number(video_xu)} Xu</b>\n"
        f"{branding_line}"
        f"{copy['addons']}:\n{addon_lines}\n"
        f"{copy['addons']}: <b>{xu_number(addon_xu)} Xu</b>\n\n"
        f"{copy['total']}: <b>{xu_number(total_xu)} Xu</b>\n"
        f"{copy['equivalent']}: <b>{xu_number(equivalent)} VND</b>\n\n"
        f"{copy['charge_after_delivery']}."
    )

def video_price_invoice_text(state: dict, lang: str = "vi") -> str:
    state = dict(state or {})
    preview = dict(state.get("current_video_price_preview") or {})
    if preview and not state.get("video_order") and not state.get("video_tier") and not (state.get("pending_payload") or {}).get("video_tier"):
        base_xu = int(preview.get("base_video_xu") or 0)
        music_xu = int(preview.get("music_xu") or 0)
        subtitle_xu = int(preview.get("subtitle_xu") or 0)
        dubbing_xu = int(preview.get("dubbing_xu") or 0)
        free_items = []
        paid_items = []
        if str(preview.get("music_option") or state.get("current_video_music_option") or "").strip().lower() not in {"", "none", "off", "no"}:
            target = paid_items if music_xu > 0 else free_items
            target.append({"key": "music", "label": "Nhạc/SFX", "price_xu": music_xu})
        addon_mode = str(preview.get("addon_mode") or "").strip()
        addon_label = str(preview.get("addon_label") or "").strip()
        addon_xu = int(preview.get("addon_xu") or subtitle_xu + dubbing_xu)
        if addon_mode == "subtitle_plus_dubbing" and addon_xu > 0:
            paid_items.append({"key": addon_mode, "label": addon_label or "Phụ đề và lồng tiếng", "price_xu": addon_xu})
        else:
            if subtitle_xu > 0:
                label = addon_label if addon_mode in {"subtitle", "translate_subtitle"} else "Phụ đề"
                paid_items.append({"key": addon_mode or "subtitle", "label": label, "price_xu": subtitle_xu})
            if dubbing_xu > 0:
                label = addon_label if addon_mode == "dubbing" else "Lồng tiếng"
                paid_items.append({"key": addon_mode or "dubbing", "label": label, "price_xu": dubbing_xu})
        order = {
            "tier": "legacy_preview",
            "tier_name": "Video AI",
            "base_price_xu": base_xu,
            "requested_seconds": int(preview.get("duration_seconds") or state.get("current_video_duration_seconds") or VIDEO_ORDER_DEFAULT_BASE_SECONDS),
            "free_items": free_items or [{"key": "planning", "label": "Prompt/kịch bản đã chuẩn bị", "price_xu": 0}],
            "paid_items": paid_items,
            "discounts": [],
            "total_xu": int(preview.get("total_xu") or base_xu + music_xu + subtitle_xu + dubbing_xu),
            "estimated_vnd": int(preview.get("estimated_vnd") or 0),
            "billable": True,
        }
        if not order["estimated_vnd"]:
            order["estimated_vnd"] = int(order["total_xu"] or 0) * int(XU_TO_VND or 100)
        pricing = {**preview, "video_order": order}
    else:
        order = video_order_from_state(state)
        pricing = preview or video_order_to_price_preview(order, state)
        return video_quote_invoice_text(calculate_video_quote(state), state, lang)
    order = dict(pricing.get("video_order") or order)
    duration = int(order.get("requested_seconds") or pricing.get("duration_seconds") or VIDEO_ORDER_DEFAULT_BASE_SECONDS)
    raw_tier = str(order.get("tier") or state.get("video_tier") or "").strip()
    tier_norm = normalize_video_tier(raw_tier) if raw_tier in set(VIDEO_TIER_ORDER) else ""
    def lines(items):
        return "\n".join(
            f"• {html.escape(str(item.get('label')))}: <b>{'+' if int(item.get('price_xu') or 0) > 0 else ''}{xu_number(item.get('price_xu'))} Xu</b>"
            for item in (items or [])
        )

    free_lines_vi = lines(order.get("free_items")) or "• Không có mục miễn phí bổ sung."
    paid_lines_vi = lines(order.get("paid_items")) or "• Không có add-on trả phí."
    free_lines_en = lines(order.get("free_items")) or "• No extra free item."
    paid_lines_en = lines(order.get("paid_items")) or "• No paid add-on."
    audio_invoice_block = video_audio_invoice_block(state, lang)
    if audio_invoice_block:
        free_lines_vi = f"{free_lines_vi}\n{audio_invoice_block}"
        free_lines_en = f"{free_lines_en}\n{audio_invoice_block}"
    discount_lines = lines(order.get("discounts")) if order.get("discounts") else ""
    total_xu = int(order.get("total_xu") or pricing.get("total_xu") or 0)
    equivalent = int(order.get("estimated_vnd") or pricing.get("estimated_vnd") or total_xu * int(XU_TO_VND or 100))
    base_price_xu = int(order.get("base_price_xu") or 0)
    if tier_norm:
        package_label_vi = f"{video_tier_short_label(tier_norm, 'vi')} {base_price_xu} Xu"
        package_label_en = f"{video_tier_short_label(tier_norm, 'en')} {base_price_xu} Xu"
    else:
        package_label_vi = str(order.get("tier_name") or "Video AI")
        package_label_en = package_label_vi
    paid_option_labels = [
        str(item.get("label") or item.get("key") or "").strip()
        for item in (order.get("paid_items") or [])
        if str(item.get("label") or item.get("key") or "").strip()
    ]
    option_summary_vi = ", ".join(paid_option_labels[:4]) if paid_option_labels else "mặc định"
    option_summary_en = ", ".join(paid_option_labels[:4]) if paid_option_labels else "default"
    voice_guard = video_voice_mux_export_guard(state)
    voice_invoice_note_en = (
        "\nVoice: <b>default narration saved, not muxed into this video version</b>.\n"
        if voice_guard.get("reason") == "default_voice_saved_not_muxed" else ""
    )
    voice_invoice_note_vi = (
        "\nGiọng đọc mặc định đã được lưu nhưng chưa ghép vào video ở bản hiện tại.\n"
        if voice_guard.get("reason") == "default_voice_saved_not_muxed" else ""
    )
    scene_invoice_lines_en = video_scene_selection_summary_lines(state, "en", invoice=True)
    scene_invoice_lines_vi = video_scene_selection_summary_lines(state, "vi", invoice=True)
    duration_line_en = "\n".join(scene_invoice_lines_en) if scene_invoice_lines_en else f"Duration: <b>{duration} seconds</b>"
    duration_line_vi = "\n".join(scene_invoice_lines_vi) if scene_invoice_lines_vi else f"Thời lượng: <b>{duration} giây</b>"

    if normalize_user_language(lang) != "vi":
        discount_block = f"\nDiscounts:\n{discount_lines}\n" if discount_lines else ""
        return (
            "🎬 <b>Confirm video export</b>\n\n"
            f"Package: <b>{html.escape(package_label_en)}</b>\n"
            "Content: <b>ready</b>\n"
            f"Options: <b>{html.escape(option_summary_en)}</b>\n"
            f"{voice_invoice_note_en}"
            "TOAN AAS has not processed anything and no Xu was charged.\n\n"
            "🧾 <b>Final video invoice</b>\n\n"
            f"Package: <b>{html.escape(str(order.get('tier_name')))}</b>\n"
            f"{duration_line_en}\n\n"
            "Main service:\n"
            f"• Video: <b>{xu_number(order.get('base_price_xu'))} Xu</b>\n\n"
            f"Free items:\n{free_lines_en}\n\n"
            f"Paid add-ons:\n{paid_lines_en}\n"
            f"{discount_block}"
            "\n"
            f"Total: <b>{xu_number(total_xu)} Xu</b>\n"
            f"Equivalent: <b>{xu_number(equivalent)} VND</b>\n\n"
            "Processing starts only after you press the final confirmation button."
        )
    discount_block = f"\nƯu đãi hợp lệ:\n{discount_lines}\n" if discount_lines else ""
    return (
        "🎬 <b>Xác nhận xuất video</b>\n\n"
        f"Gói: <b>{html.escape(package_label_vi)}</b>\n"
        "Nội dung: <b>đã sẵn sàng</b>\n"
        f"Tùy chọn: <b>{html.escape(option_summary_vi)}</b>\n"
        f"{voice_invoice_note_vi}"
        "TOAN AAS chưa xử lý và chưa trừ Xu.\n\n"
        "🧾 <b>Hóa đơn xác nhận video</b>\n\n"
        f"Gói chính: <b>{html.escape(str(order.get('tier_name')))}</b>\n"
        f"{duration_line_vi}\n\n"
        "Dịch vụ chính:\n"
        f"• Video: <b>{xu_number(order.get('base_price_xu'))} Xu</b>\n\n"
        f"Mục miễn phí:\n{free_lines_vi}\n\n"
        f"Công cụ bổ sung có phí:\n{paid_lines_vi}\n"
        f"{discount_block}"
        "\n"
        f"Tổng: <b>{xu_number(total_xu)} Xu</b>\n"
        f"Tương đương: <b>{xu_number(equivalent)}đ</b>\n\n"
        "TOAN AAS chỉ bắt đầu xử lý và trừ Xu sau khi bạn bấm xác nhận cuối."
    )

