    job_id = str(args[0] if args else "").strip()
    job = frame_video_job_for_user(job_id, uid, allow_any=True) if job_id else {}
    state = get_frame_video_state(uid) if not job else {}
    debug = img2vid_state_debug_dict(job_id, state, job)
