def extract_openai_image_payload(result) -> tuple[str, str]:
    data = getattr(result, "data", None)
    if data is None and isinstance(result, dict):
        data = result.get("data")
    if not data:
        return "", ""
    item = data[0]
    if isinstance(item, dict):
        return item.get("b64_json") or "", item.get("url") or ""
    return getattr(item, "b64_json", "") or "", getattr(item, "url", "") or ""

async def send_openai_image_result(update: Update, result, caption: str) -> bool:
    b64_json, url = extract_openai_image_payload(result)
    if b64_json:
        image_bytes = base64.b64decode(b64_json)
        photo = io.BytesIO(image_bytes)
        photo.name = "toan_aas_ai_image.png"
        await update.message.reply_photo(photo=photo, caption=caption[:1000])
        return True
    if url:
        try:
            async with httpx.AsyncClient(timeout=60.0, follow_redirects=True) as client:
                response = await client.get(url)
            if response.status_code < 400 and response.content:
                photo = io.BytesIO(response.content)
                photo.name = "toan_aas_ai_image.png"
                await update.message.reply_photo(photo=photo, caption=caption[:1000])
                return True
        except Exception as e:
            logger.warning(f"OpenAI image URL download failed: {e}")
        await update.message.reply_text(f"✅ Ảnh đã tạo: {url}\n\n{caption}")
        return True
    return False

def openai_image_disabled_text(kind: str = "generation") -> str:
    if kind == "edit":
        return "OpenAI Image Edit đang disabled. Set ENABLE_OPENAI_IMAGE_EDIT=1 để admin test."
    return "OpenAI Image đang disabled. Set ENABLE_OPENAI_IMAGE=1 để admin test."

def image_edit_policy_block_reason(instruction: str) -> str:
    text = str(instruction or "").strip().lower()
    if not text:
        return ""
    identity_markers = (
        "deepfake", "giả mạo danh tính", "mạo danh", "clone mặt", "clone khuôn mặt",
        "fake face", "impersonate", "identity fraud",
    )
    if any(marker in text for marker in identity_markers):
        return "Không hỗ trợ chỉnh ảnh theo hướng giả mạo danh tính/deepfake."
    sensitive_doc_markers = (
        "bill", "biên lai", "chứng từ", "sao kê", "giao dịch", "chuyển khoản",
        "hóa đơn", "hoá đơn", "invoice", "receipt", "bank statement",
        "cccd", "cmnd", "căn cước", "hộ chiếu", "passport", "bằng cấp", "giấy tờ",
    )
    manipulation_markers = (
        "fake", "giả", "làm thật", "trông thật", "sửa", "đổi", "thay", "xóa",
        "xoá", "tăng", "giảm", "che", "ẩn", "remove", "edit", "change",
    )
    if any(marker in text for marker in sensitive_doc_markers) and any(marker in text for marker in manipulation_markers):
        return "Không hỗ trợ chỉnh sửa bill/chứng từ/giấy tờ/sao kê hoặc tài liệu giao dịch."
    return ""

def reply_image_file_id_for_edit(reply) -> tuple[str, str]:
    if not reply:
        return "", ""
    if getattr(reply, "photo", None):
        return reply.photo[-1].file_id, "source.png"
    doc = getattr(reply, "document", None)
    if doc:
        name = doc.file_name or "source_image.png"
        mime = (doc.mime_type or "").lower()
        ext = os.path.splitext(name.lower())[1]
        if mime.startswith("image/") or ext in {".jpg", ".jpeg", ".png", ".webp"}:
            return doc.file_id, name
    return "", ""

async def cmd_tool_test_ai_image(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    prompt = media_factory_topic_from_args(context)
    if not prompt:
        return await update.message.reply_text("⚠️ Cú pháp: /tool_test_ai_image <prompt>")
    if not ENABLE_OPENAI_IMAGE:
        save_tool_test_result("ai_image", "DISABLED", "ENABLE_OPENAI_IMAGE=0", update.effective_user.id)
        return await update.message.reply_text(openai_image_disabled_text("generation"))
    if not openai_client:
        save_tool_test_result("ai_image", "MISSING", "OPENAI_API_KEY missing", update.effective_user.id)
        return await update.message.reply_text("⚠️ OpenAI image provider chưa được cấu hình. Không có Xu nào bị trừ.")
    safe_prompt = (
        f"{prompt}\n\n"
        "Create a safe, realistic, high-quality image. No watermark, no broken text, no illegal or deceptive content."
    )
    try:
        def run_image():
            return openai_client.images.generate(
                model=OPENAI_IMAGE_MODEL,
                prompt=safe_prompt,
                size="1024x1024",
                n=1,
            )
        result = await asyncio.to_thread(run_image)
        sent = await send_openai_image_result(update, result, "✅ OpenAI Image admin smoke test PASS.")
        if not sent:
            raise RuntimeError("OpenAI image response did not contain b64_json or url")
        save_tool_test_result("ai_image", "PASS", f"model={OPENAI_IMAGE_MODEL}; admin_smoke_test", update.effective_user.id)
        record_api_debug("openai_image", "tool_test_ai_image", "PASS", 0, f"model={OPENAI_IMAGE_MODEL}; prompt_len={len(prompt)}")
    except Exception as e:
        detail = provider_error_summary(e)
        save_tool_test_result("ai_image", "FAIL", detail, update.effective_user.id)
        record_api_debug("openai_image", "tool_test_ai_image", "FAIL", 0, detail)
        await update.message.reply_text(
            "❌ OpenAI Image admin smoke test FAIL.\n"
            f"• Error: <code>{html.escape(detail[:300])}</code>\n"
            "Không có Xu nào bị trừ.",
            parse_mode="HTML",
        )

