    keyword = " ".join(context.args or []).strip()
    if not keyword:
        return await update.message.reply_text("Cú pháp: /prompt_vault_search <keyword>")
    matches = TASK3D_PROMPT_VAULT.search(keyword)
    lines = ["🔎 <b>Prompt vault search</b>", ""]
