async def handle_knowledge_vault_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    await query.answer()
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "status"
    admin = bool(query.from_user and is_admin_user(query.from_user.id))
    vault = toan_knowledge_vault()

    if action == "use" and len(parts) >= 3:
        prompt = vault.get_prompt(int(parts[2]), public=not admin)
        if not prompt:
            return await query.message.reply_text("Prompt chưa được duyệt public hoặc không tồn tại.")
        await query.message.reply_text(
            "📋 <b>Prompt sẵn sàng dùng</b>\n\n<pre>" + html.escape(str(prompt.get("prompt_text") or "")) + "</pre>",
            parse_mode="HTML",
        )
        return

    if not admin:
        prompts = vault.search_prompt(public_only=True, limit=10)
        rows = [[InlineKeyboardButton(f"Dùng prompt #{prompt['id']}", callback_data=f"vault|use|{int(prompt['id'])}")] for prompt in prompts[:8]]
        return await query.edit_message_text(vault_prompt_list_text(prompts, title="📚 Kho Prompt TOAN AAS"), parse_mode="HTML", reply_markup=InlineKeyboardMarkup(rows) if rows else None)

    if action == "approve_prompt" and len(parts) >= 3:
        prompt = vault.approve_prompt(int(parts[2]), approved_by=query.from_user.id)
        return await query.edit_message_text(
            "✅ Đã duyệt prompt.\n\n" + vault_json_block(prompt or {"ok": False, "reason": "not_found"}),
            parse_mode="HTML",
            reply_markup=vault_admin_keyboard(),
        )
    if action == "approve_asset" and len(parts) >= 3:
        asset = vault.approve_asset(int(parts[2]), approved_by=query.from_user.id)
        return await query.edit_message_text(
            "✅ Đã duyệt asset.\n\n" + vault_json_block(asset or {"ok": False, "reason": "not_found"}),
            parse_mode="HTML",
            reply_markup=vault_admin_keyboard(),
        )
    if action == "prompts":
        prompts = vault.search_prompt(public_only=False, limit=10)
        rows = [[InlineKeyboardButton(f"Dùng prompt #{prompt['id']}", callback_data=f"vault|use|{int(prompt['id'])}")] for prompt in prompts[:8]]
        return await query.edit_message_text(vault_prompt_list_text(prompts), parse_mode="HTML", reply_markup=InlineKeyboardMarkup(rows) if rows else vault_admin_keyboard())
    if action == "review":
        prompts = [prompt for prompt in vault.search_prompt(public_only=False, limit=20) if prompt.get("status") != "approved"]
        rows = [[InlineKeyboardButton(f"Duyệt #{prompt['id']}", callback_data=f"vault|approve_prompt|{int(prompt['id'])}")] for prompt in prompts[:8]]
        return await query.edit_message_text(vault_prompt_list_text(prompts, title="🧾 Nháp cần duyệt"), parse_mode="HTML", reply_markup=InlineKeyboardMarkup(rows) if rows else vault_admin_keyboard())
    if action == "assets":
        requested = parts[2] if len(parts) > 2 else ""
        if requested == "audio":
            assets = []
            for asset_type in ("music", "sfx", "voice", "audio"):
                assets.extend(vault.list_assets(asset_type=asset_type, public_only=False, limit=8))
        else:
            assets = vault.list_assets(asset_type=requested, public_only=False, limit=12)
        label = VAULT_ASSET_LABELS.get(requested, "Kho Media")
        return await query.edit_message_text(vault_asset_list_text(assets, title=label), parse_mode="HTML", reply_markup=vault_admin_keyboard())
    if action == "search":
        return await query.edit_message_text(
            "🔎 Dùng <code>/kho_prompt &lt;từ khóa&gt;</code> để tìm prompt public/admin, hoặc <code>/vault_prompt_debug &lt;id&gt;</code> để xem chi tiết admin.",
            parse_mode="HTML",
            reply_markup=vault_admin_keyboard(),
        )
    if action == "import":
        return await query.edit_message_text(
            "📥 <b>Import học liệu</b>\n\n"
            "• <code>/vault_import_folder</code> dùng thư mục import mặc định.\n"
            "• <code>/vault_import_video_refs</code> nhập Kho Video tham khảo.\n"
            "• Reply video/ảnh/audio/file rồi gửi <code>/vault_import_file</code>.\n"
            "• Prompt text: <code>/vault_import_file Video prompt: ...</code>\n"
            "• Online refs: <code>/vault_import_online_sources &lt;url1&gt; &lt;url2&gt;</code>\n"
            "• Sync/backup: <code>/vault_sync_index</code>, <code>/vault_backup</code>",
            parse_mode="HTML",
            reply_markup=vault_admin_keyboard(),
        )

    status = toan_vault_importer().debug_status()
    await query.edit_message_text("🧠 <b>Kho học liệu TOAN AAS</b>\n\n" + vault_json_block(status), parse_mode="HTML", reply_markup=vault_admin_keyboard())


async def cmd_trend_source_status(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Lệnh này chỉ dành cho admin.")
    status = video_trend2_db(video_trend_catalog.refresh_status)
    await update.message.reply_text(
        "🔥 <b>Trạng thái kho trend</b>\n\n<pre>" + html.escape(json.dumps(status, ensure_ascii=False, indent=2)) + "</pre>",
        parse_mode="HTML",
    )


async def cmd_trend_source_refresh(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Lệnh này chỉ dành cho admin.")
    result = await asyncio.to_thread(run_video_trend_catalog_refresh_once)
    await update.message.reply_text(
        "✅ Đã làm mới kho trend từ nguồn công khai. Không gọi provider trả phí.\n\n<pre>"
        + html.escape(json.dumps(result, ensure_ascii=False, indent=2))
        + "</pre>",
        parse_mode="HTML",
    )


async def cmd_trend_source_list(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Lệnh này chỉ dành cho admin.")
    rows = video_trend2_db(lambda conn: video_trend_catalog.list_items(conn, limit=10, offset=0, include_stale_cache=True))
    lines = ["🔥 <b>Trend sources</b>", ""]
    for item in rows:
        lines.append(
            f"• <code>{html.escape(str(item.get('trend_id')))}</code> · "
            f"{html.escape(str(item.get('title')))} · {html.escape(str(item.get('source_name')))}"
        )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")


async def cmd_trend_source_add(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Lệnh này chỉ dành cho admin.")
    raw = " ".join(context.args or []).strip()
    if not raw:
        return await update.message.reply_text("Cú pháp: /trend_source_add {JSON object}\nKhông dùng dữ liệu scrape trái phép.")
    try:
        item = json.loads(raw)
    except Exception:
        return await update.message.reply_text("⚠️ JSON không hợp lệ. Trend cache chưa thay đổi.")
    try:
        result = video_trend2_db(
            lambda conn: video_trend_catalog.upsert_items(conn, [item] if isinstance(item, dict) else [])
        )
    except ValueError as exc:
        return await update.message.reply_text(f"⚠️ Nguồn trend chưa hợp lệ: {sanitize_log_text(str(exc))[:160]}")
    await update.message.reply_text("<pre>" + html.escape(json.dumps(result, ensure_ascii=False, indent=2)) + "</pre>", parse_mode="HTML")


def video_provider_status_text(status: dict | None = None, key4u_credit: dict | None = None) -> str:
    status = dict(status or video_provider_router.provider_status_payload())
    key4u_credit = dict(key4u_credit or status.get("key4u_credit_diagnostic") or {}) if isinstance(key4u_credit or status.get("key4u_credit_diagnostic") or {}, dict) else {}
    providers = [dict(item) for item in (status.get("providers") or []) if isinstance(item, dict)]
    missing_env = dict(status.get("missing_env") or {}) if isinstance(status.get("missing_env") or {}, dict) else {}
    invalid_env = dict(status.get("invalid_env") or {}) if isinstance(status.get("invalid_env") or {}, dict) else {}
    provider_chain_raw = status.get("effective_provider_chain") or status.get("provider_chain") or []
    if isinstance(provider_chain_raw, str):
        provider_chain_iter = [item.strip() for item in provider_chain_raw.split(",") if item.strip()]
    else:
        try:
            provider_chain_iter = list(provider_chain_raw)
        except TypeError:
            provider_chain_iter = []
    provider_chain_text = ",".join(str(item) for item in provider_chain_iter) or "-"
    selection_reason = str(status.get("selection_reason") or status.get("summary_reason") or "-")
    fallback_raw = status.get("fallback_order") or []
    if isinstance(fallback_raw, str):
        fallback_order = [item.strip() for item in fallback_raw.split(",") if item.strip()]
    else:
        try:
            fallback_order = list(fallback_raw)
        except TypeError:
            fallback_order = []
    first_fallback = str(fallback_order[0]) if fallback_order else "-"
    lines = [
        "🎬 <b>Trạng thái nhà cung cấp video</b>",
        "",
        f"• Sẵn sàng: <code>{'có' if status.get('ready') or status.get('ok') else 'không'}</code>",
        f"• Lý do: <code>{html.escape(str(status.get('summary_reason') or status.get('reason') or '-'))}</code>",
        f"• Thứ tự provider: <code>{html.escape(provider_chain_text)}</code>",
        f"• Provider đầu tiên: <code>{html.escape(str(status.get('first_ready_provider') or '-'))}</code>",
        f"• Lý do chọn: <code>{html.escape(selection_reason)}</code>",
        f"• Fallback tiếp theo: <code>{html.escape(first_fallback)}</code>",
        f"• Provider đang bật: <code>{int(status.get('enabled_count') or 0)}</code>",
        f"• Provider đủ cấu hình: <code>{int(status.get('configured_count') or 0)}</code>",
        f"• Provider gần đủ cấu hình: <code>{html.escape(', '.join(status.get('near_ready_providers') or []) or '-')}</code>",
        "",
        "Thiếu biến:",
    ]
    if missing_env:
        for provider_name, missing in missing_env.items():
            lines.append(f"• <code>{html.escape(str(provider_name))}</code>: <code>{html.escape(', '.join(str(item) for item in missing) or '-')}</code>")
    else:
        lines.append("• <code>-</code>")
    lines.append("")
    lines.append("Biến sai/placeholder:")
    if invalid_env:
        for provider_name, invalid in invalid_env.items():
            lines.append(f"• <code>{html.escape(str(provider_name))}</code>: <code>{html.escape(', '.join(str(item) for item in invalid) or '-')}</code>")
    else:
        lines.append("• <code>-</code>")
    lines.extend(["", "Providers:"])
    for provider in providers:
        provider_name = str(provider.get("provider") or "-")
        key4u_usage_suffix = ""
        if provider_name == "key4u_video":
            key4u_usage_suffix = (
                f" usage_credit=<code>{html.escape(str(key4u_credit.get('credit') or 'unknown'))}</code> "
                f"usage_reason=<code>{html.escape(str(key4u_credit.get('reason') or 'key4u_usage_url_missing'))}</code> "
                f"usage_auth_source=<code>{html.escape(str(key4u_credit.get('usage_auth_source') or '-'))}</code> "
                f"usage_auth_header=<code>{html.escape(str(key4u_credit.get('usage_auth_header_name') or '-'))}</code> "
                f"usage_auth_scheme=<code>{html.escape(str(key4u_credit.get('usage_auth_scheme_prefix') or '-'))}</code> "
                f"usage_auth_mode=<code>{html.escape(str(key4u_credit.get('usage_auth_mode') or '-'))}</code> "
                f"usage_host=<code>{html.escape(str(key4u_credit.get('usage_endpoint_host') or '-'))}</code> "
                f"usage_path=<code>{html.escape(str(key4u_credit.get('usage_endpoint_path') or '-'))}</code> "
                f"usage_http=<code>{html.escape(str(key4u_credit.get('usage_http_status') or 0))}</code> "
                f"usage_tried=<code>{len(key4u_credit.get('usage_endpoint_candidates_tried') or [])}</code> "
                f"usage_connectivity=<code>{html.escape(str(key4u_credit.get('usage_connectivity_status') or 'UNKNOWN'))}</code> "
                f"usage_balance=<code>{html.escape(str(key4u_credit.get('usage_balance_status') or 'UNKNOWN'))}</code> "
                f"usage_health_http=<code>{html.escape(str(key4u_credit.get('usage_health_http') or 0))}</code> "
                f"usage_balance_http=<code>{html.escape(str(key4u_credit.get('usage_balance_http') or 0))}</code> "
                f"usage_success=<code>{html.escape(str(key4u_credit.get('usage_success_endpoint_host_path') or '-'))}</code> "
                f"usage_success_type=<code>{html.escape(str(key4u_credit.get('usage_success_endpoint_type') or '-'))}</code> "
                f"usage_success_mode=<code>{html.escape(str(key4u_credit.get('usage_success_auth_mode') or '-'))}</code> "
                f"usage_shape=<code>{html.escape(str(key4u_credit.get('usage_response_shape') or '-'))}</code> "
            )
        lines.append(
            "• "
            f"<code>{html.escape(provider_name)}</code> "
            f"enabled=<code>{'yes' if provider.get('enabled') else 'no'}</code> "
            f"configured=<code>{'yes' if provider.get('configured') else 'no'}</code> "
            f"endpoint=<code>{'yes' if provider.get('endpoint_present') else 'no'}</code> "
            f"submit=<code>{'yes' if provider.get('submit_url_present') else 'no'}</code> "
            f"poll=<code>{'yes' if provider.get('poll_url_present') else 'no'}</code> "
            f"auth=<code>{'yes' if provider.get('auth_present') else 'no'}</code> "
            f"model=<code>{'yes' if provider.get('model_present') else 'no'}</code> "
            f"source=<code>{html.escape(str(provider.get('selected_provider_config_source') or provider.get('provider_config_source') or '-'))}</code> "
            f"namespaces=<code>{html.escape(','.join(str(item) for item in (provider.get('provider_config_namespaces_checked') or [])) or '-')}</code> "
            f"alias=<code>{html.escape(','.join(str(item) for item in (provider.get('selected_provider_alias_prefixes_checked') or [])) or '-')}</code> "
            f"submit_host=<code>{html.escape(str(provider.get('provider_submit_url_host') or '-'))}</code> "
            f"namespace_mismatch=<code>{'yes' if provider.get('provider_env_namespace_mismatch') else 'no'}</code> "
            f"credit=<code>{html.escape(str(provider.get('credit_status') or 'unknown'))}</code> "
            f"{key4u_usage_suffix}"
            f"fallback_only=<code>{'yes' if provider.get('fallback_only') else 'no'}</code> "
            f"blocker=<code>{html.escape(str(provider.get('blocker') or provider.get('selection_blocker') or '-'))}</code> "
            f"invalid_fields=<code>{html.escape(','.join(str(item) for item in (provider.get('invalid_fields') or [])) or '-')}</code> "
            f"caps=<code>{html.escape(','.join(str(item) for item in (provider.get('capabilities') or [])) or '-')}</code> "
            f"missing=<code>{html.escape(','.join(str(item) for item in (provider.get('missing') or [])) or '-')}</code>"
        )
    lines.append("")
    lines.append("Nếu không có provider phù hợp, video product phải fail sạch với provider_capability_missing và chưa trừ Xu.")
    text = "\n".join(lines)
    if len(text) > VIDEO_DEBUG_REPLY_LIMIT:
        return video_provider_status_compact_text(status, key4u_credit, reason="message_too_long")
    return text


def video_provider_status_compact_text(status: dict | None = None, key4u_credit: dict | None = None, *, reason: str = "partial") -> str:
    status = dict(status or {})
    key4u_credit = dict(key4u_credit or status.get("key4u_credit_diagnostic") or {}) if isinstance(key4u_credit or status.get("key4u_credit_diagnostic") or {}, dict) else {}
    providers = [dict(item) for item in (status.get("providers") or []) if isinstance(item, dict)]
    provider_chain_raw = status.get("effective_provider_chain") or status.get("provider_chain") or []
    if isinstance(provider_chain_raw, str):
        provider_chain = [item.strip() for item in provider_chain_raw.split(",") if item.strip()]
    else:
        try:
            provider_chain = [str(item) for item in provider_chain_raw]
        except TypeError:
            provider_chain = []
    fallback_raw = status.get("fallback_order") or []
    if isinstance(fallback_raw, str):
        fallback_order = [item.strip() for item in fallback_raw.split(",") if item.strip()]
    else:
        try:
            fallback_order = [str(item) for item in fallback_raw]
        except TypeError:
            fallback_order = []
    missing_env = status.get("missing_env") if isinstance(status.get("missing_env"), dict) else {}
    invalid_env = status.get("invalid_env") if isinstance(status.get("invalid_env"), dict) else {}
    lines = [
        "🎬 <b>Trạng thái nhà cung cấp video</b>",
        "Provider status diagnostic partial",
        "",
        f"• debug_truncated: <code>yes</code>",
        f"• truncate_reason: <code>{_video_debug_safe_value(reason, 80)}</code>",
        f"• Sẵn sàng: <code>{'có' if status.get('ready') or status.get('ok') else 'không'}</code>",
        f"• Lý do: <code>{_video_debug_safe_value(status.get('summary_reason') or status.get('reason'), 160)}</code>",
        f"• Thứ tự provider: <code>{_video_debug_safe_value(','.join(provider_chain) or '-', 220)}</code>",
        f"• Provider đầu tiên: <code>{_video_debug_safe_value(status.get('first_ready_provider'), 80)}</code>",
        f"• Lý do chọn: <code>{_video_debug_safe_value(status.get('selection_reason') or status.get('summary_reason'), 160)}</code>",
        f"• Fallback tiếp theo: <code>{_video_debug_safe_value(fallback_order[0] if fallback_order else '-', 80)}</code>",
        f"• Provider đang bật: <code>{safe_int(status.get('enabled_count'), 0)}</code>",
        f"• Provider đủ cấu hình: <code>{safe_int(status.get('configured_count'), 0)}</code>",
        f"• Missing groups: <code>{safe_int(len(missing_env), 0)}</code>",
        f"• Invalid groups: <code>{safe_int(len(invalid_env), 0)}</code>",
        f"• Key4U credit: <code>{_video_debug_safe_value(key4u_credit.get('credit') or key4u_credit.get('usage_balance_status') or 'unknown', 80)}</code>",
        f"• Key4U reason: <code>{_video_debug_safe_value(key4u_credit.get('reason'), 140)}</code>",
        "",
        "Providers:",
    ]
    for provider in providers[:8]:
        provider_name = str(provider.get("provider") or "-")
        lines.append(
            "• "
            f"<code>{_video_debug_safe_value(provider_name, 80)}</code> "
            f"enabled=<code>{'yes' if provider.get('enabled') else 'no'}</code> "
            f"configured=<code>{'yes' if provider.get('configured') else 'no'}</code> "
            f"submit=<code>{'yes' if provider.get('submit_url_present') else 'no'}</code> "
            f"poll=<code>{'yes' if provider.get('poll_url_present') else 'no'}</code> "
            f"auth=<code>{'yes' if provider.get('auth_present') else 'no'}</code> "
            f"model=<code>{'yes' if provider.get('model_present') else 'no'}</code> "
            f"credit=<code>{_video_debug_safe_value(provider.get('credit_status') or 'unknown', 60)}</code> "
            f"fallback_only=<code>{'yes' if provider.get('fallback_only') else 'no'}</code> "
            f"blocker=<code>{_video_debug_safe_value(provider.get('blocker') or provider.get('selection_blocker'), 120)}</code> "
            f"caps=<code>{_video_debug_safe_value(','.join(str(item) for item in (provider.get('capabilities') or [])), 160)}</code>"
        )
    lines.append("")
    lines.append("Nếu không có provider phù hợp, video product fail sạch với provider_capability_missing và chưa trừ Xu.")
    text = "\n".join(lines)
    return text if len(text) <= VIDEO_DEBUG_REPLY_LIMIT else text[: VIDEO_DEBUG_REPLY_LIMIT - 80] + "\n• debug_truncated=<code>hard_limit</code>"


def video_provider_env_audit_text(audit: dict | None = None) -> str:
    audit = dict(audit or video_provider_router.video_provider_env_audit_payload())
    rows = [item for item in (audit.get("rows") or []) if isinstance(item, dict)]
    lines = [
        "🧪 <b>Video Provider ENV Audit</b>",
        "",
        f"• Audit: <code>{'PASS' if audit.get('ok') else 'FAIL'}</code>",
        f"• Provider được chọn: <code>{html.escape(str(audit.get('selected_provider') or '-'))}</code>",
        f"• Submit config provider được chọn: <code>{'có' if audit.get('selected_provider_submit_config_non_empty') else 'không'}</code>",
        f"• Status ready khớp submit config: <code>{'có' if audit.get('status_ready_implies_submit_config_non_empty') else 'không'}</code>",
        f"• Worker hydrate local: <code>{'có' if audit.get('worker_local_hydration_success') else 'không'}</code>",
        f"• Fallback nếu selected rỗng: <code>{'có' if audit.get('fallback_provider_attempted_if_selected_empty') else 'không'}</code>",
        f"• Chain: <code>{html.escape(','.join(str(item) for item in (audit.get('provider_chain') or [])) or '-')}</code>",
        "",
        "Providers:",
    ]
    for row in rows:
        lines.append(
            "• "
            f"<code>{html.escape(str(row.get('provider') or '-'))}</code> "
            f"status_configured=<code>{'yes' if row.get('status_configured') else 'no'}</code> "
            f"submit_config=<code>{'yes' if row.get('submit_config_non_empty') else 'no'}</code> "
            f"aligned=<code>{'yes' if row.get('status_submit_registry_aligned') else 'no'}</code> "
            f"source=<code>{html.escape(str(row.get('config_source') or '-'))}</code> "
            f"namespaces=<code>{html.escape(','.join(str(item) for item in (row.get('namespaces_checked') or [])) or '-')}</code> "
            f"alias=<code>{html.escape(','.join(str(item) for item in (row.get('alias_prefixes_checked') or [])) or '-')}</code> "
            f"host=<code>{html.escape(str(row.get('submit_url_host') or '-'))}</code> "
            f"path=<code>{html.escape(str(row.get('submit_url_path') or '-'))}</code> "
            f"auth_name=<code>{'yes' if row.get('auth_header_name_present') else 'no'}</code> "
            f"auth_value=<code>{'yes' if row.get('auth_header_value_present') else 'no'}</code> "
            f"model=<code>{'yes' if row.get('model_present') else 'no'}</code> "
            f"no_v1_v1=<code>{'yes' if row.get('no_v1_v1') else 'no'}</code> "
            f"namespace_mismatch=<code>{'yes' if row.get('provider_env_namespace_mismatch') else 'no'}</code>"
        )
    lines.append("")
    lines.append("Lệnh này chỉ hiển thị host/path/header-present/model-present, không hiển thị token hoặc URL ký.")
    return "\n".join(lines)


def video_provider_setup_text(status: dict | None = None) -> str:
    status = dict(status or video_provider_router.provider_status_payload())
    missing_env = dict(status.get("missing_env") or {})
    invalid_env = dict(status.get("invalid_env") or {})
    missing_lines = []
    for provider_name, missing in missing_env.items():
        missing_lines.append(f"- {provider_name}: {', '.join(str(item) for item in missing) or '-'}")
    if not missing_lines:
        missing_lines.append("- -")
    invalid_lines = []
    for provider in status.get("providers") or []:
        provider_name = str(provider.get("provider") or "-")
        invalid_fields = ", ".join(str(item) for item in (provider.get("invalid_fields") or [])) or "-"
        invalid_names = ", ".join(str(item) for item in invalid_env.get(provider_name, [])) or "-"
        blocker = str(provider.get("blocker") or "-")
        if invalid_names != "-" or invalid_fields != "-":
            invalid_lines.append(f"- {provider_name}: fields={invalid_fields}; env={invalid_names}; blocker={blocker}")
    if not invalid_lines:
        invalid_lines.append("- -")
    lines = [
        "🎬 <b>Cấu hình nhà cung cấp dựng video</b>",
        "",
        "Trạng thái:",
        f"- Sẵn sàng: {'có' if status.get('ready') or status.get('ok') else 'không'}",
        f"- Provider đang bật: {int(status.get('enabled_count') or 0)}",
        f"- Provider có endpoint: {int(status.get('configured_count') or 0)}",
        "- Provider thiếu biến:",
        *missing_lines,
        "- Provider sai cấu hình/placeholder:",
        *invalid_lines,
        "",
        "Recommended Railway variables:",
        "",
        "A. TOAN AAS generic backend:",
        "VIDEO_TOANAAS_ENABLED=true",
        "VIDEO_TOANAAS_SUBMIT_URL=&lt;submit_url&gt;",
        "VIDEO_TOANAAS_POLL_URL=&lt;poll_url&gt;",
        "VIDEO_TOANAAS_AUTH_HEADER_NAME=Authorization",
        "VIDEO_TOANAAS_AUTH_HEADER_VALUE=&lt;token&gt;",
        "",
        "B. ShopAIKey video:",
        "SHOPAIKEY_VIDEO_ENABLED=true",
        "SHOPAIKEY_VIDEO_SUBMIT_URL=&lt;submit_url&gt;",
        "SHOPAIKEY_VIDEO_POLL_URL=&lt;poll_url&gt;",
        "SHOPAIKEY_VIDEO_AUTH_HEADER_NAME=Authorization",
        "SHOPAIKEY_VIDEO_AUTH_HEADER_VALUE=&lt;token&gt;",
        "",
        "C. Key4U video:",
        "KEY4U_VIDEO_ENABLED=true",
        "KEY4U_VIDEO_SUBMIT_URL=&lt;submit_url&gt;",
        "KEY4U_VIDEO_POLL_URL=&lt;poll_url&gt;",
        "KEY4U_VIDEO_AUTH_HEADER_NAME=Authorization",
        "KEY4U_VIDEO_AUTH_HEADER_VALUE=&lt;token&gt;",
        "",
        "D. Generic HTTP:",
        "VIDEO_GENERIC_HTTP_ENABLED=true",
        "VIDEO_GENERIC_HTTP_SUBMIT_URL=&lt;submit_url&gt;",
        "VIDEO_GENERIC_HTTP_POLL_URL=&lt;poll_url&gt;",
        "VIDEO_GENERIC_HTTP_AUTH_HEADER_NAME=Authorization",
        "VIDEO_GENERIC_HTTP_AUTH_HEADER_VALUE=&lt;token&gt;",
        "VIDEO_GENERIC_HTTP_RESULT_FIELD=result_url",
        "",
        "Ghi chú: lệnh này không hiện token thật và không gọi provider.",
    ]
    return "\n".join(lines)


