def _parse_remote_worker_canary_job_id(args: list[str] | tuple[str, ...] | None) -> int:
    for arg in args or []:
        text = str(arg or "").strip()
        match = re.search(r"(?:RW-(?:PROD-)?CANARY-)?(\d+)", text, re.IGNORECASE)
        if match:
            return safe_int(match.group(1), 0)
    return 0


def _remote_worker_prod_canary_options(args: list[str] | tuple[str, ...] | None) -> dict:
    values = [str(arg or "").strip() for arg in (args or []) if str(arg or "").strip()]
    options = {
        "profile": "simple",
        "duration_seconds": 3,
        "scene_count": 1,
        "provider_smoke": "--provider-smoke" in values,
        "confirm_provider_cost": "--confirm-provider-cost" in values,
    }
    for index, value in enumerate(values):
        if value == "--profile" and index + 1 < len(values):
            options["profile"] = values[index + 1]
        if value == "--duration" and index + 1 < len(values):
            options["duration_seconds"] = safe_int(values[index + 1], 3)
        if value == "--scenes" and index + 1 < len(values):
            options["scene_count"] = safe_int(values[index + 1], 1)
    return options


def _format_remote_worker_canary_status(status: dict) -> str:
    if not status.get("ok"):
        return "🧪 <b>Remote Worker Canary</b>\n\nChưa tìm thấy job canary an toàn."
    uploaded = "yes" if status.get("result_uploaded") else "no"
    sent = "yes" if status.get("sent_to_admin") else "no"
    failure = status.get("safe_failure_reason") or "-"
    stage = status.get("stage") or status.get("progress_message") or status.get("status") or "-"
    return "\n".join(
        [
            "🧪 <b>Remote Worker Canary Status</b>",
            "",
            f"• Job: <code>{html.escape(status.get('canary_ref') or '-')}</code>",
            f"• Status: <code>{html.escape(status.get('status') or '-')}</code>",
            f"• Stage: <code>{html.escape(stage)}</code>",
            f"• Worker: <code>{html.escape(status.get('worker_id') or '-')}</code>",
            f"• Claimed at: <code>{html.escape(vietnam_time_display(status.get('claimed_at')))}</code>",
            f"• Last heartbeat: <code>{html.escape(vietnam_time_display(status.get('last_heartbeat_at')))}</code>",
            f"• Progress: <code>{safe_int(status.get('progress_percent'), 0)}%</code> {html.escape(status.get('progress_message') or '')}",
            f"• Result uploaded: <code>{uploaded}</code>",
            f"• Result file size: <code>{safe_int(status.get('result_file_size'), 0)}</code>",
            f"• Sent to admin: <code>{sent}</code>",
            f"• Error: <code>{html.escape(status.get('safe_error_type') or '-')}</code>",
            f"• Failure: <code>{html.escape(failure)}</code>",
        ]
    )


def _remote_worker_prod_canary_next_action(status: dict) -> str:
    state = str(status.get("status") or "").strip().lower()
    stage = str(status.get("stage") or "").strip().lower()
    if stage == "not_claimed_timeout":
        return "Chạy admin-canary --once trên VPS để xem idle reason."
    if state == "queued":
        return "Chờ worker claim hoặc kiểm tra service admin-canary."
    if state == "claimed":
        return "Chờ hoàn tất hoặc refresh trạng thái canary."
    if state == "failed":
        return "Đọc reason code rồi kiểm tra journal admin-canary."
    if state == "completed":
        return "Canary hoàn tất; có thể tạo canary mới khi cần."
    return "Refresh trạng thái hoặc kiểm tra service admin-canary."


def _format_remote_worker_prod_canary_status(status: dict) -> str:
    if not status.get("ok"):
        return "🧪 <b>VPS Worker Production Canary</b>\n\nChưa tìm thấy job admin production canary."
    uploaded = "yes" if status.get("result_uploaded") else "no"
    sent = "yes" if status.get("sent_to_admin") else "no"
    provider = "yes" if status.get("provider_call") else "no"
    public = "yes" if status.get("public_user") else "no"
    no_charge = "yes" if status.get("no_charge") else "no"
    reason_code = status.get("reason_code") or status.get("safe_failure_reason_code") or "-"
    failure = status.get("safe_failure_reason") or "-"
    next_action = _remote_worker_prod_canary_next_action(status)
    return "\n".join(
        [
            "🧪 <b>VPS Worker Production Canary Status</b>",
            "",
            f"• Job: <code>{html.escape(status.get('canary_ref') or '-')}</code>",
            f"• Label: <code>{html.escape(status.get('queue_label') or '-')}</code>",
            f"• Status: <code>{html.escape(status.get('status') or '-')}</code>",
            f"• Stage: <code>{html.escape(status.get('stage') or '-')}</code>",
            f"• Worker: <code>{html.escape(status.get('worker_id') or '-')}</code>",
            f"• Claimed at: <code>{html.escape(vietnam_time_display(status.get('claimed_at')))}</code>",
            f"• Last heartbeat: <code>{html.escape(vietnam_time_display(status.get('last_heartbeat_at')))}</code>",
            f"• Progress: <code>{safe_int(status.get('progress_percent'), 0)}%</code> {html.escape(status.get('progress_message') or '')}",
            f"• Result uploaded: <code>{uploaded}</code>",
            f"• Result file exists: <code>{'yes' if status.get('result_file_exists') else 'no'}</code>",
            f"• Result file size: <code>{safe_int(status.get('result_file_size'), 0)}</code>",
            f"• Telegram sent: <code>{sent}</code>",
            f"• No-charge: <code>{no_charge}</code>",
            f"• Public: <code>{public}</code>",
            f"• Provider: <code>{provider}</code>",
            f"• Reason code: <code>{html.escape(reason_code)}</code>",
            f"• Error: <code>{html.escape(status.get('safe_error_type') or '-')}</code>",
            f"• Reason: <code>{html.escape(status.get('safe_reason_code') or '-')}</code>",
            f"• Failure: <code>{html.escape(failure)}</code>",
            f"• Next action: <b>{html.escape(next_action)}</b>",
        ]
    )


async def cmd_remote_worker_canary(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id if update.effective_user else 0
    if not is_admin_user(uid):
        return await update.message.reply_text("⛔ Lệnh này chỉ dành cho Admin.")
    args = set(str(arg or "").strip() for arg in (getattr(context, "args", None) or []))
    if "--no-charge" not in args:
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/remote_worker_canary --no-charge</code>",
            parse_mode="HTML",
        )
    flags = worker_auth.worker_api_runtime_flags(LOCAL_WORKER_TOKEN)
    if not flags.get("worker_api_enabled"):
        return await update.message.reply_text(
            "🧪 <b>Remote Worker Canary</b>\n\nLOCAL_WORKER_TOKEN chưa cấu hình. Chưa tạo job.",
            parse_mode="HTML",
        )
    conn = db_connect()
    try:
        result = remote_worker_api.create_remote_worker_canary_job(conn, admin_user_id=safe_int(uid, 0))
    finally:
        conn.close()
    if not result.get("ok"):
        return await update.message.reply_text(
            f"🧪 <b>Remote Worker Canary</b>\n\nFAIL: <code>{html.escape(result.get('reason') or 'canary_create_failed')}</code>",
            parse_mode="HTML",
        )
    job = result.get("job") or {}
    canary_ref = result.get("canary_ref") or f"RW-CANARY-{job.get('id') or ''}"
    try:
        set_system_setting("remote_worker:last_canary_job_id", str(job.get("id") or ""), "last remote worker canary job", uid)
        set_system_setting("remote_worker:last_canary_status", "canary_queued", "last remote worker canary status", uid)
    except Exception:
        logger.warning("remote worker canary setting skipped")
    lines = [
        "🧪 <b>Remote Worker Canary</b>",
        "",
        "Đã tạo job canary an toàn cho VPS worker.",
        f"• Job: <code>{html.escape(canary_ref)}</code>",
        "• Loại: kiểm tra worker",
        "• Trừ Xu: Không",
        "• Gọi provider: Không",
        "• Job khách thật: Không",
        "",
        "Trên VPS chạy:",
        "<code>python remote_worker.py --canary --once</code>",
        "",
        f"Kiểm tra: <code>/remote_worker_canary_status {html.escape(canary_ref)}</code>",
    ]
    return await update.message.reply_text(
        "\n".join(lines),
        parse_mode="HTML",
        reply_markup=_remote_worker_canary_keyboard(str(canary_ref)),
    )


