def security_fold_text(value) -> str:
    text = str(value or "").replace("đ", "d").replace("Đ", "D")
    text = unicodedata.normalize("NFKD", text)
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    return re.sub(r"\s+", " ", text.lower()).strip()

def is_telegram_group_management_request(raw_text) -> bool:
    lower_raw = str(raw_text or "").lower()
    if any(method in lower_raw for method in TELEGRAM_GROUP_MANAGEMENT_METHODS):
        return True
    folded = security_fold_text(raw_text)
    return any(phrase in folded for phrase in TELEGRAM_GROUP_MANAGEMENT_PHRASES)

def blocked_telegram_group_management_plan(raw_text) -> dict:
    return {
        "intent": "blocked_telegram_group_management",
        "topic": str(raw_text or "")[:300],
        "confidence": 100,
        "execute": 0,
        "safe_mode": 1,
        "blocked_by_security": True,
        "safety_note": TELEGRAM_GROUP_MANAGEMENT_BLOCK_MESSAGE,
    }

def extract_supported_video_url(text):
    urls = re.findall(r"https?://[^\s<>\"]+", text or "", flags=re.I)
    supported_hosts = (
        "tiktok.com", "vt.tiktok.com",
        "youtube.com", "youtu.be", "m.youtube.com",
        "facebook.com", "fb.watch", "m.facebook.com", "web.facebook.com",
        "instagram.com", "threads.net",
    )
    for url in urls:
        cleaned = url.rstrip(").,!?;\"'")
        lower_url = cleaned.lower()
        if any(host in lower_url for host in supported_hosts):
            return cleaned
    return ""

def first_number_near(text, words, default=0):
    for word in words:
        match = re.search(rf"(\d+)\s+(?:\S+\s+){{0,2}}{re.escape(word)}", text, re.IGNORECASE)
        if match:
            return int(match.group(1))
        match = re.search(rf"{re.escape(word)}\s*(?:=|#)?\s*(\d+)", text, re.IGNORECASE)
        if match:
            return int(match.group(1))
    return default

def compact_arg_value(value):
    value = str(value or "").strip()
    if not value:
        return ""
    if any(ch.isspace() for ch in value):
        return value
    return value

def parse_metric_number(raw_text, aliases, default=0):
    text = (raw_text or "").lower()
    alias_group = "|".join(re.escape(alias.lower()) for alias in aliases)
    for alias_match in re.finditer(rf"\b(?:{alias_group})\b", text, re.IGNORECASE):
        prefix = text[:alias_match.start()]
        suffix = text[alias_match.end():]
        before = re.search(r"(\d+(?:[.,]\d+)?)\s*$", prefix)
        before_is_id = bool(re.search(r"\b(job|queue|id)\s*#?\s*\d+(?:[.,]\d+)?\s*$", prefix, re.IGNORECASE))
        if before and not before_is_id:
            try:
                return int(float(before.group(1).replace(",", ".")))
            except ValueError:
                pass
        after = re.search(r"^\s*(?:=|:)?\s*(\d+(?:[.,]\d+)?)", suffix)
        if after:
            try:
                return int(float(after.group(1).replace(",", ".")))
            except ValueError:
                pass
    return default

def parse_money_amount_near(raw_text, aliases, default=0):
    text = (raw_text or "").lower()
    alias_group = "|".join(re.escape(alias.lower()) for alias in aliases)
    number = r"(\d+(?:[.,]\d+)?)\s*(k|nghìn|nghin|tr|triệu|trieu|m|đ|vnd|vnđ)?"
    patterns = [
        rf"(?:{alias_group})\s*(?:=|:)?\s*{number}",
        rf"{number}\s*(?:{alias_group})",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if not match:
            continue
        raw_value = match.group(1).replace(",", ".")
        unit = (match.group(2) or "").lower()
        try:
            value = float(raw_value)
        except ValueError:
            continue
        if unit in {"k", "nghìn", "nghin"}:
            value *= 1000
        elif unit in {"tr", "triệu", "trieu", "m"}:
            value *= 1000000
        return int(value)
    return default

def parse_count_metrics_sequence(raw_text):
    alias_map = {
        "view": "view",
        "views": "view",
        "lượt xem": "view",
        "luot xem": "view",
        "click": "click",
        "clicks": "click",
        "nhấp": "click",
        "nhap": "click",
        "đơn": "order",
        "don": "order",
        "order": "order",
        "orders": "order",
        "lead": "lead",
        "leads": "lead",
        "khách": "lead",
        "khach": "lead",
    }
    text = (raw_text or "").lower()
    text = re.sub(r"lượt\s+xem", "view", text)
    text = re.sub(r"luot\s+xem", "view", text)
    text = re.sub(r"đơn\s+hàng", "đơn", text)
    text = re.sub(r"don\s+hang", "don", text)
    tokens = re.findall(r"\d+(?:[.,]\d+)?|[a-zA-ZÀ-ỹ]+", text, re.IGNORECASE)
    metrics = {}
    pending_metric = None
    last_number = None
    last_number_is_id = False
    previous_word = ""
    for token in tokens:
        normalized = token.lower()
        if re.fullmatch(r"\d+(?:[.,]\d+)?", normalized):
            try:
                number = int(float(normalized.replace(",", ".")))
            except ValueError:
                previous_word = normalized
                continue
            if pending_metric and pending_metric not in metrics:
                metrics[pending_metric] = number
                pending_metric = None
                last_number = None
                last_number_is_id = False
            else:
                last_number = number
                last_number_is_id = previous_word in {"job", "queue", "id"}
            previous_word = normalized
            continue
        metric = alias_map.get(normalized)
        if metric:
            if last_number is not None and not last_number_is_id and metric not in metrics:
                metrics[metric] = last_number
                last_number = None
                last_number_is_id = False
                pending_metric = None
            elif metric not in metrics:
                pending_metric = metric
            previous_word = normalized
            continue
        if normalized not in {"có", "co", "la", "là", "duoc", "được"}:
            pending_metric = None if pending_metric and normalized in {"job", "queue", "id"} else pending_metric
        previous_word = normalized
    return metrics

def parse_brain_performance_metrics(raw_text):
    metrics = {}
    counts = parse_count_metrics_sequence(raw_text)
    views = counts.get("view", 0)
    clicks = counts.get("click", 0)
    orders = counts.get("order", 0)
    leads = counts.get("lead", 0)
    revenue = parse_money_amount_near(raw_text, ["doanh thu", "revenue", "hoa hồng", "hoa hong", "thu về", "thu ve", "tiền về", "tien ve"])
    cost = parse_money_amount_near(raw_text, ["cost", "chi phí", "chi phi", "tốn", "ton", "ads", "quảng cáo", "quang cao"])
    if views:
        metrics["view"] = {"value": views, "amount": 0}
    if clicks:
        metrics["click"] = {"value": clicks, "amount": 0}
    if orders:
        metrics["order"] = {"value": orders, "amount": revenue}
    elif revenue:
        metrics["revenue"] = {"value": 1, "amount": revenue}
    if leads:
        metrics["lead"] = {"value": leads, "amount": 0}
    if cost:
        metrics["cost"] = {"value": 1, "amount": cost}
    return metrics

def clean_operator_topic(text, default="công nghệ AI"):
    source = (text or "").replace("shoppe", "shopee")
    cleaned = re.sub(
        r"\b(tạo|tao|làm|lam|video|clip|short|reel|phim|film|series|storyboard|cảnh|canh|tập|tap|chủ đề|chu de|dài|dai|trend|viral|mới nhất|moi nhat|cho|trên|tren|kênh|kenh|gắn|gan|link|affiliate|aff|campaign|camp|limit|job|build|luôn|luon|đăng|dang|bán hàng|ban hang|kiếm tiền|kiem tien|tìm|tim|rồi|roi|và|va|theo|để|de)\b",
        " ",
        source,
        flags=re.IGNORECASE,
    )
    cleaned = re.sub(r"\b(tiktok|facebook|fb|youtube|shorts|onlyfan|onlyfans|reels|instagram|ig|mxh|social|multi|all)\b", " ", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\b\d+\b", " ", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" :=#-,.")
    return cleaned or default

