async def cmd_operator_daily(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    try:
        days = int(data.get("days") or data.get("ngay") or (context.args[0] if context.args else 1))
    except (TypeError, ValueError):
        days = 1
    days = max(1, min(days, 30))
    (
        since, job_status_counts, job_stage_counts, queue_status_counts,
        performance_counts, recent_jobs, open_queue
    ) = operator_daily_data(update.effective_user.id, days)
    lines = [
        f"📊 <b>AI OPERATOR DAILY — {days} ngày</b>",
        f"• Từ: <code>{html.escape(since)}</code>",
        "",
        "<b>Job mới theo status:</b>",
        "• " + (", ".join(f"{html.escape(status or '-')}={count}" for status, count in job_status_counts) or "0"),
        "<b>Job cập nhật theo stage:</b>",
        "• " + (", ".join(f"{html.escape(stage or '-')}={count}" for stage, count in job_stage_counts) or "0"),
        "<b>Publish queue:</b>",
        "• " + (", ".join(f"{html.escape(status or '-')}={count}" for status, count in queue_status_counts) or "0"),
        "",
        "<b>Performance:</b>",
    ]
    if performance_counts:
        for event_type, value_sum, amount_sum, count in performance_counts:
            lines.append(f"• {html.escape(event_type or '-')}: value=<b>{value_sum}</b> | amount=<b>{amount_sum:,}đ</b> | events={count}")
    else:
        lines.append("• Chưa có dữ liệu mới.")
    lines.append("\n<b>Job vừa cập nhật:</b>")
    if recent_jobs:
        for jid, stage, status, platform, topic, channel_name, product_name, updated_at in recent_jobs:
            lines.append(
                f"• #{jid} | {html.escape(stage or '-')}/{html.escape(status or '-')} | "
                f"<code>{html.escape(platform or '-')}</code> | {html.escape(channel_name or '-')}\n"
                f"  {html.escape(topic or '-')}\n"
                f"  aff={html.escape(product_name or '-')} | {updated_at or '-'}"
            )
    else:
        lines.append("• Không có job cập nhật.")
    lines.append("\n<b>Queue cần xử lý:</b>")
    if open_queue:
        for qid, job_id, platform, channel_name, mode, status, scheduled_at, topic in open_queue:
            lines.append(
                f"• queue #{qid} | job #{job_id} | {html.escape(mode or '-')}/{html.escape(status or '-')} | "
                f"<code>{html.escape(platform or '-')}</code> | {html.escape(channel_name or '-')}\n"
                f"  schedule={html.escape(scheduled_at or '-')} | {html.escape(topic or '-')}"
            )
    else:
        lines.append("• Không có queue mở.")
    lines.append("\nLệnh nhanh: /operator_dashboard | /publish_queue | /performance | /operator_auto")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_operator_daily_pack(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    try:
        days = max(1, min(int(data.get("days") or data.get("ngay") or (context.args[0] if context.args else 1)), 30))
    except (TypeError, ValueError):
        days = 1
    try:
        limit = max(3, min(int(data.get("limit") or 8), 20))
    except (TypeError, ValueError):
        limit = 8
    platform = (data.get("platform") or data.get("nen") or "tiktok").lower()
    topic = data.get("topic") or data.get("niche") or data.get("chu_de") or ""
    pack = operator_daily_execution_pack_data(
        update.effective_user.id,
        days=days,
        platform=platform,
        limit=limit,
        topic=topic,
    )
    state = pack.get("state") or {}
    lines = [
        f"🧭 <b>DAILY EXECUTION PACK — {days} ngày</b>",
        f"• Platform: <code>{html.escape(platform)}</code> | Decision window: <b>{pack.get('decision_days')}</b> ngày",
        f"• Audit: <code>{html.escape(state.get('audit_level') or '-')}</code> score=<b>{state.get('audit_score', 0)}</b>",
        f"• Next: <code>{html.escape(state.get('next_mode') or '-')}</code> — {html.escape(state.get('next_title') or '-')}",
        f"• Queue/task: <b>{state.get('open_queue_count', 0)}</b>/<b>{state.get('worker_task_count', 0)}</b> | "
        f"Affiliate rev/click: <b>{int(state.get('affiliate_revenue') or 0):,}đ</b>/<b>{state.get('affiliate_clicks', 0)}</b>",
        "",
        "<b>Việc hôm nay theo thứ tự:</b>",
    ]
    for item in (pack.get("execution_queue") or [])[:limit]:
        action = item.get("machine_action") or {}
        lines.append(
            f"{item.get('rank')}. <code>{html.escape(item.get('lane') or '-')}</code> — {html.escape(item.get('title') or '-')}\n"
            f"   why: {html.escape(item.get('why') or '-')}\n"
            f"   TG: <code>{html.escape(item.get('telegram') or '-')}</code>\n"
            f"   API: <code>{html.escape(action.get('method') or 'GET')} {html.escape(action.get('url') or item.get('api') or '-')}</code> | "
            f"safe=<b>{'YES' if action.get('safe_to_execute') else 'NO'}</b>"
        )
    top_links = pack.get("top_affiliate_links") or []
    if top_links:
        lines.append("\n<b>Link nên ưu tiên:</b>")
        for item in top_links[:5]:
            lines.append(
                f"• aff #{item.get('affiliate_id')} | {html.escape(item.get('network') or '-')} | "
                f"<b>{html.escape(item.get('product') or '-')}</b> | score={item.get('score')}\n"
                f"  clicks={item.get('clicks')} rev={int(item.get('revenue') or 0):,}đ | <code>{html.escape(item.get('next') or '-')}</code>"
            )
    lines.append(
        "\n<b>API cho Claude/n8n:</b>\n"
        f"<code>GET /api/operator/daily-pack?days={days}&amp;platform={html.escape(platform)}&amp;limit={limit}</code>\n"
        "<b>Rule:</b> xử lý từng rank, không vượt review/publish gate, sau đăng phải ghi performance."
    )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_operator_daily_run(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    days = max(1, min(safe_int(data.get("days") or data.get("ngay") or 1, 1), 30))
    limit = max(3, min(safe_int(data.get("limit") or 8, 8), 20))
    rank = max(1, min(safe_int(data.get("rank") or data.get("r") or (context.args[0] if context.args else 1), 1), 20))
    platform = (data.get("platform") or data.get("nen") or "tiktok").lower()
    topic = data.get("topic") or data.get("niche") or data.get("chu_de") or ""
    execute = truthy_value(data.get("execute") or data.get("run") or data.get("chay"), False)
    safe_mode = truthy_value(data.get("safe") or data.get("safe_mode"), True)
    msg = await update.message.reply_text(
        "▶️ Đang kiểm tra daily machine action..."
        + (" chạy trong safe mode." if execute else " preview trước, chưa đổi dữ liệu.")
    )
    try:
        result = await execute_daily_machine_action(
            update.effective_user.id,
            days=days,
            platform=platform,
            limit=limit,
            topic=topic,
            rank=rank,
            execute=execute,
            safe_mode=safe_mode,
            include_context=True,
            include_prompt=True,
        )
    except Exception as e:
        await alert_admin(context, "Operator Daily Run", str(e))
        return await msg.edit_text("❌ Daily run lỗi. Đã báo admin.")
    item = result.get("item") or {}
    action = result.get("machine_action") or {}
    run_result = result.get("result") or {}
    lines = [
        "▶️ <b>DAILY MACHINE ACTION</b>",
        f"• Rank: <b>{result.get('rank')}</b> | Lane: <code>{html.escape(result.get('lane') or '-')}</code>",
        f"• Title: <b>{html.escape(item.get('title') or '-')}</b>",
        f"• Safe: <b>{'YES' if action.get('safe_to_execute') else 'NO'}</b> | Admin gate: <b>{'YES' if action.get('requires_admin') else 'NO'}</b>",
        f"• Execute: <b>{'YES' if execute else 'NO'}</b> | Executed: <b>{'YES' if result.get('executed') else 'NO'}</b>",
    ]
    if result.get("blocked_by_safe_mode") or result.get("blocked_by_policy"):
        lines.append(f"• Blocked: {html.escape(result.get('message') or 'safe gate')}")
    if result.get("reason"):
        lines.append(f"• Reason: <code>{html.escape(str(result.get('reason')))}</code>")
    if run_result.get("task"):
        task = run_result.get("task") or {}
        lines.append(f"• Claimed task: <code>#{task.get('id')}</code> | job <code>#{task.get('job_id')}</code>")
    created_jobs = run_result.get("created_jobs") or []
    built_jobs = run_result.get("built_jobs") or []
    if created_jobs or built_jobs:
        lines.append(f"• Jobs tạo/build: <b>{len(created_jobs)}</b>/<b>{len(built_jobs)}</b>")
    lines.extend([
        "",
        f"TG action: <code>{html.escape(item.get('telegram') or '-')}</code>",
        f"API action: <code>{html.escape(action.get('method') or 'GET')} {html.escape(action.get('url') or '-')}</code>",
        f"Next: <code>{html.escape(result.get('after_done') or '/operator_daily_pack')}</code>",
        "",
        "Chạy thật: <code>/operator_daily_run rank=%s execute=1</code>" % result.get("rank"),
    ])
    await msg.edit_text("\n".join(lines), parse_mode="HTML")

async def cmd_operator_daily_cycle(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    days = max(1, min(safe_int(data.get("days") or data.get("ngay") or 1, 1), 30))
    limit = max(3, min(safe_int(data.get("limit") or 8, 8), 20))
    max_steps = max(1, min(safe_int(data.get("max") or data.get("max_steps") or data.get("steps") or 3, 3), 10))
    platform = (data.get("platform") or data.get("nen") or "tiktok").lower()
    topic = data.get("topic") or data.get("niche") or data.get("chu_de") or ""
    execute = truthy_value(data.get("execute") or data.get("run") or data.get("chay"), False)
    safe_mode = truthy_value(data.get("safe") or data.get("safe_mode"), True)
    msg = await update.message.reply_text(
        "🔁 Đang chạy daily cycle..."
        + (" safe execute, có gate sẽ dừng." if execute else " preview trước, chưa đổi dữ liệu.")
    )
    try:
        result = await operator_daily_cycle_data(
            update.effective_user.id,
            days=days,
            platform=platform,
            limit=limit,
            topic=topic,
            max_steps=max_steps,
            execute=execute,
            safe_mode=safe_mode,
            include_context=True,
            include_prompt=True,
        )
    except Exception as e:
        await alert_admin(context, "Operator Daily Cycle", str(e))
        return await msg.edit_text("❌ Daily cycle lỗi. Đã báo admin.")

    lines = [
        "🔁 <b>DAILY SAFE CYCLE</b>",
        f"• Platform: <code>{html.escape(platform)}</code> | Days: <b>{days}</b> | Max: <b>{max_steps}</b>",
        f"• Execute: <b>{'YES' if execute else 'NO'}</b> | Safe: <b>{'YES' if safe_mode else 'NO'}</b>",
        f"• Steps: <b>{len(result.get('steps') or [])}</b> | Executed: <b>{result.get('executed_count', 0)}</b>",
        f"• Stop: <code>{html.escape(result.get('stop_reason') or '-')}</code>",
        "",
        "<b>Các bước:</b>",
    ]
    for step in (result.get("steps") or [])[:max_steps]:
        item = step.get("item") or {}
        action = step.get("machine_action") or {}
        gate = step.get("message") or step.get("reason") or ("ok" if step.get("executed") else "preview")
        lines.append(
            f"{step.get('cycle_step')}. <code>{html.escape(step.get('lane') or '-')}</code> — {html.escape(item.get('title') or '-')}\n"
            f"   executed=<b>{'YES' if step.get('executed') else 'NO'}</b> | "
            f"safe=<b>{'YES' if action.get('safe_to_execute') else 'NO'}</b> | "
            f"gate=<code>{html.escape(str(gate))}</code>\n"
            f"   next=<code>{html.escape(step.get('after_done') or action.get('after_success') or '-')}</code>"
        )
    next_action = result.get("next_machine_action") or {}
    lines.extend([
        "",
        f"Next machine: <code>{html.escape(next_action.get('method') or 'GET')} {html.escape(next_action.get('url') or '/api/operator/daily-pack')}</code>",
        "",
        "Lệnh tiếp: <code>/operator_daily_pack</code> | <code>/operator_daily_run rank=1 execute=1</code> | "
        "<code>/operator_daily_cycle execute=1 max=3</code>",
    ])
    await msg.edit_text("\n".join(lines), parse_mode="HTML")

