async def cmd_distribution_pack(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    try:
        job_id = int(data.get("job") or data.get("id") or context.args[0])
    except (IndexError, TypeError, ValueError):
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/distribution_pack job=&lt;JOB_ID&gt;</code>",
            parse_mode="HTML",
        )
    pack = build_distribution_pack(update.effective_user.id, job_id)
    if not pack:
        return await update.message.reply_text("❌ Không tìm thấy production job.")
    job = pack.get("job") or {}
    channel = pack.get("channel") or {}
    affiliate = pack.get("affiliate") or {}
    placement = pack.get("placement_map") or {}
    review = pack.get("review_gate") or {}
    tracking = pack.get("tracking_plan") or {}
    commands = (pack.get("commands") or {}).get("telegram") or {}
    lines = [
        f"🧭 <b>DISTRIBUTION PACK — JOB #{job_id}</b>",
        f"• Topic: {html.escape(job.get('topic') or '-')}",
        f"• Platform: <code>{html.escape(job.get('platform') or '-')}</code>",
        f"• Kênh: <code>#{channel.get('id') or '-'}</code> {html.escape(channel.get('channel_name') or '-')} / {html.escape(channel.get('account_label') or 'main')}",
        f"• Readiness: <b>{html.escape(channel.get('readiness') or 'unknown')}</b> | {html.escape(channel.get('readiness_reason') or '-')}",
        f"• Affiliate: <code>#{affiliate.get('id') or '-'}</code> {html.escape(affiliate.get('product_name') or '-')}",
        "",
        "<b>Đặt link:</b>",
        f"• Caption: <code>{html.escape(placement.get('caption') or '-')}</code>",
        f"• Comment ghim: <code>{html.escape(placement.get('pinned_comment') or '-')}</code>",
        f"• Status/story: <code>{html.escape(placement.get('status_or_story') or '-')}</code>",
        f"• Disclosure: {html.escape(placement.get('disclosure') or '-')}",
        "",
        "<b>Review gate:</b>",
        f"• Decision: <code>{html.escape(review.get('decision') or 'REVIEW_REQUIRED')}</code>",
        f"• Auto publish: <b>{'có' if review.get('can_auto_publish') else 'không'}</b>",
        f"• Next: <code>{html.escape(review.get('next_command') or commands.get('review_video') or '')}</code>",
        "",
        "<b>Tracking source:</b>",
    ]
    for key, src in (tracking.get("sources") or {}).items():
        lines.append(f"• {html.escape(key)}: <code>{html.escape(src)}</code>")
    lines.extend([
        "",
        "<b>Lệnh điều hành:</b>",
        f"• Worker: <code>{html.escape(commands.get('worker_pack') or '')}</code>",
        f"• Approve: <code>{html.escape(commands.get('approve_publish') or '')}</code>",
        f"• Sau đăng: <code>{html.escape(commands.get('mark_published') or '')}</code>",
        f"• Doanh thu: <code>{html.escape(commands.get('performance_revenue') or '')}</code>",
        "",
        f"API: <code>/api/operator/jobs/{job_id}/distribution-pack</code>",
    ])
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_comment_pack(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    job_id = safe_int(data.get("job") or data.get("id") or (context.args[0] if context.args else 0), 0)
    max_comments = max(1, min(safe_int(data.get("max") or data.get("limit") or data.get("comments"), 10), 10))
    delay = max(10, min(safe_int(data.get("delay") or data.get("delay_seconds"), 30), 600))
    if not job_id:
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/comment_pack job=&lt;JOB_ID&gt; max=10 delay=30</code>",
            parse_mode="HTML"
        )
    pack = build_affiliate_comment_pack(update.effective_user.id, job_id, max_comments=max_comments, delay_seconds=delay)
    if not pack:
        return await update.message.reply_text("❌ Không tìm thấy production job.")
    lines = [
        f"💬 <b>AFFILIATE COMMENT PACK — JOB #{job_id}</b>",
        f"• Platform: <code>{html.escape(pack.get('platform') or '-')}</code> | Comments: <b>{len(pack.get('comments') or [])}</b>",
        f"• Delay: <b>{pack.get('delay_seconds_between_comments') or 30}s</b>",
        f"• Rule: {html.escape(pack.get('rule') or '')}\n",
    ]
    if pack.get("primary_comment"):
        lines.append("<b>Comment chính:</b>")
        lines.append(f"<pre>{html_pre(pack.get('primary_comment') or '-', 900)}</pre>")
    lines.append("<b>Comment liên quan:</b>")
    for item in (pack.get("comments") or [])[:max_comments]:
        lines.append(
            f"• #{item.get('order')} | aff=<code>#{item.get('affiliate_id') or '-'}</code> | src=<code>{html.escape(item.get('tracking_source') or '-')}</code>\n"
            f"<pre>{html_pre(item.get('text') or '-', 700)}</pre>"
        )
    commands = pack.get("commands") or {}
    lines.extend([
        "<b>Sau đăng:</b>",
        f"• Post publish: <code>{html.escape(commands.get('post_publish') or '')}</code>",
        f"• Tracking: <code>{html.escape(commands.get('tracking_report') or '')}</code>",
        f"API: <code>/api/operator/jobs/{job_id}/comment-pack?max_comments={max_comments}</code>",
    ])
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_pipeline_pack(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    job_id = safe_int(data.get("job") or data.get("id"), 0)
    try:
        days = max(1, min(int(data.get("days") or data.get("ngay") or 30), 180))
    except (TypeError, ValueError):
        days = 30
    platform = (data.get("platform") or data.get("nen") or "tiktok").lower()
    pack = operator_pipeline_pack_data(update.effective_user.id, job_id=job_id, days=days, platform=platform, limit=8)
    focus_job_id = int(pack.get("focus_job_id") or 0)
    next_action = pack.get("next_action") or {}
    lines = [
        "🧠 <b>PIPELINE COMMAND PACK</b>",
        f"• Focus job: <code>#{focus_job_id or '-'}</code> | source=<code>{html.escape(pack.get('focus_source') or '-')}</code>",
        f"• State: <b>{html.escape(pack.get('pipeline_state') or '-')}</b>",
        f"• Next type: <code>{html.escape(next_action.get('type') or '-')}</code>",
        f"• Next Telegram: <code>{html.escape(next_action.get('telegram') or '-')}</code>",
    ]
    job = pack.get("job") or {}
    if job:
        lines.extend([
            "",
            "<b>Job:</b>",
            f"• {html.escape(job.get('topic') or '-')} | <code>{html.escape(job.get('platform') or '-')}</code>",
            f"• Stage/status: <code>{html.escape(job.get('stage') or '-')}</code>/<code>{html.escape(job.get('status') or '-')}</code>",
            f"• Affiliate: {html.escape(((job.get('affiliate') or {}).get('product')) or '-')}",
        ])
    worker = pack.get("worker_next") or {}
    task = worker.get("next_task") or {}
    if task:
        lines.extend([
            "",
            "<b>Worker:</b>",
            f"• Task <code>#{task.get('id') or '-'}</code> / <code>{html.escape(task.get('task_type') or '-')}</code> / tool=<code>{html.escape(task.get('tool') or '-')}</code>",
            f"• Claim: <code>{html.escape(worker.get('claim_task_url') or '-')}</code>",
        ])
    distribution = pack.get("distribution_pack") or {}
    channel = distribution.get("channel") or {}
    review = distribution.get("review_gate") or {}
    if distribution:
        lines.extend([
            "",
            "<b>Distribution:</b>",
            f"• Kênh: <code>#{channel.get('id') or '-'}</code> {html.escape(channel.get('channel_name') or '-')} / {html.escape(channel.get('account_label') or 'main')}",
            f"• Readiness: <code>{html.escape(channel.get('readiness') or '-')}</code>",
            f"• Review: <code>{html.escape(review.get('decision') or '-')}</code>",
        ])
    lines.append("\n<b>Chuỗi lệnh:</b>")
    for cmd in (pack.get("telegram_sequence") or [])[:8]:
        lines.append(f"• <code>{html.escape(cmd)}</code>")
    lines.append("\nAPI: <code>GET /api/operator/pipeline-pack</code> hoặc <code>GET /api/operator/jobs/&lt;JOB_ID&gt;/pipeline-pack</code>")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_queue_publish(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    try:
        job_id = int(data.get("id") or data.get("job") or context.args[0])
    except (IndexError, TypeError, ValueError):
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/queue_publish job=1 mode=manual schedule=2026-06-01 note=...</code>",
            parse_mode="HTML"
        )
    mode = (data.get("mode") or "manual").lower()
    if mode not in {"manual", "api"}:
        return await update.message.reply_text("⚠️ mode hợp lệ: <code>manual</code> hoặc <code>api</code>", parse_mode="HTML")
    scheduled_at = data.get("schedule") or data.get("time") or ""
    note = data.get("note") or ""
    ok, queue_id = create_publish_queue_item(update.effective_user.id, job_id, mode, scheduled_at, note)
    if not ok:
        reason = str(queue_id or "unknown")
        if reason.startswith("needs_approval"):
            return await update.message.reply_text(
                f"⚠️ Job #{job_id} chưa qua chốt duyệt. Dùng:\n"
                f"<code>/job_ready job={job_id}</code>\n"
                f"<code>/approve_publish job={job_id} queue=1 mode={html.escape(mode)}</code>",
                parse_mode="HTML"
            )
        if reason.startswith("not_ready:"):
            parts = reason.split(":", 2)
            key = parts[1] if len(parts) > 1 else "unknown"
            next_cmd = parts[2] if len(parts) > 2 else f"/job_ready job={job_id}"
            return await update.message.reply_text(
                f"⚠️ Job #{job_id} chưa đủ điều kiện queue publish.\n"
                f"• Thiếu: <code>{html.escape(key)}</code>\n"
                f"• Next: <code>{html.escape(next_cmd)}</code>",
                parse_mode="HTML"
            )
        return await update.message.reply_text(f"❌ Không queue được: <code>{html.escape(reason)}</code>", parse_mode="HTML")
    await update.message.reply_text(
        f"✅ <b>Đã đưa job #{job_id} vào hàng đợi đăng</b>\n"
        f"• Queue ID: <code>{queue_id}</code>\n"
        f"• Mode: <code>{mode}</code>\n"
        f"• Schedule: <code>{html.escape(scheduled_at or 'chưa hẹn')}</code>\n\n"
        f"Khi đăng xong: <code>/mark_published job={job_id} url=https://...</code>",
        parse_mode="HTML"
    )

async def cmd_approve_publish(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    try:
        job_id = int(data.get("job") or data.get("id") or context.args[0])
    except (IndexError, TypeError, ValueError):
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/approve_publish job=1 queue=1 mode=manual note=...</code>",
            parse_mode="HTML"
        )
    queue = str(data.get("queue") or data.get("enqueue") or "1").lower() not in {"0", "false", "no", "khong"}
    mode = (data.get("mode") or "manual").lower()
    if mode not in {"manual", "api"}:
        return await update.message.reply_text("⚠️ mode hợp lệ: <code>manual</code> hoặc <code>api</code>", parse_mode="HTML")
    note = data.get("note") or "admin_approved_publish"
    scheduled_at = data.get("schedule") or data.get("time") or ""
    send_handoff = truthy_value(data.get("handoff") or data.get("send_handoff"), True)
    ok, reason, info = approve_publish_job(update.effective_user.id, job_id, note=note, queue=queue, mode=mode, scheduled_at=scheduled_at)
    if not ok:
        if reason == "not_ready":
            missing = info.get("missing") or []
            lines = [f"⚠️ <b>Job #{job_id} chưa đủ điều kiện duyệt đăng</b>\n"]
            for item in missing[:8]:
                lines.append(f"• <code>{html.escape(item['key'])}</code>: {html.escape(item['detail'])}\n  Next: <code>{html.escape(item['next'])}</code>")
            return await update.message.reply_text("\n".join(lines), parse_mode="HTML")
        return await update.message.reply_text(f"❌ Không duyệt được: <code>{html.escape(reason)}</code>", parse_mode="HTML")
    await update.message.reply_text(
        f"✅ <b>Đã duyệt publish job #{job_id}</b>\n"
        f"• Queue: <b>{'có' if info.get('queued') else 'không'}</b>\n"
        f"• Queue ID: <code>{info.get('queue_id') or '-'}</code>\n"
        f"• Mode: <code>{html.escape(mode)}</code>\n\n"
        f"Xem hàng đợi: <code>/publish_queue</code>\n"
        f"Handoff: <code>/publisher_handoff queue={info.get('queue_id') or '<QUEUE_ID>'}</code>",
        parse_mode="HTML"
    )
    if queue and send_handoff and info.get("queue_id"):
        report = await send_publisher_handoff_packet(
            context,
            update.effective_chat.id,
            update.effective_user.id,
            int(info.get("queue_id")),
            send_media=True,
        )
        if report.get("errors"):
            await update.message.reply_text(
                "⚠️ Handoff đã gửi nhưng video có lỗi gửi file: "
                + html.escape(str(report.get("errors")[:2])),
                parse_mode="HTML",
            )

async def cmd_approve_ready(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    data = parse_key_value_args(" ".join(context.args))
    limit = max(1, min(safe_int(data.get("limit") or data.get("max"), 3), 10))
    mode = (data.get("mode") or "manual").lower()
    scheduled_at = data.get("schedule") or data.get("time") or ""
    send_handoff = truthy_value(data.get("handoff") or data.get("send_handoff"), True)
    ok, reason, result = approve_ready_jobs(
        update.effective_user.id,
        limit=limit,
        mode=mode,
        scheduled_at=scheduled_at,
        note=data.get("note") or "admin_batch_approve_ready",
    )
    if not ok:
        return await update.message.reply_text(f"❌ Approve ready lỗi: <code>{html.escape(reason)}</code>", parse_mode="HTML")
    approved = result.get("approved") or []
    skipped = result.get("skipped") or []
    lines = [
        "✅ <b>BATCH APPROVE READY</b>",
        f"• Approved: <b>{len(approved)}</b> | Skipped: <b>{len(skipped)}</b> | Mode: <code>{html.escape(mode)}</code>",
    ]
    if approved:
        lines.append("\n<b>Đã queue:</b>")
        for item in approved[:10]:
            lines.append(
                f"• job <code>#{item.get('job_id')}</code> → queue <code>#{item.get('queue_id') or '-'}</code> | "
                f"{html.escape(item.get('platform') or '-')}\n"
                f"  Handoff: <code>/publisher_handoff queue={item.get('queue_id') or '<QUEUE_ID>'}</code>"
            )
    if skipped:
        lines.append("\n<b>Bỏ qua:</b>")
        for item in skipped[:8]:
            lines.append(
                f"• job <code>#{item.get('job_id')}</code> | <code>{html.escape(item.get('reason') or '-')}</code>"
                + (f" | Next: <code>{html.escape(item.get('next') or '')}</code>" if item.get("next") else "")
            )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")
    if send_handoff:
        for item in approved[:3]:
            queue_id = safe_int(item.get("queue_id"), 0)
            if not queue_id:
                continue
            report = await send_publisher_handoff_packet(
                context,
                update.effective_chat.id,
                update.effective_user.id,
                queue_id,
                send_media=True,
            )
            if report.get("errors"):
                await update.message.reply_text(
                    f"⚠️ Handoff queue #{queue_id} gửi file lỗi: "
                    + html.escape(str(report.get("errors")[:2])),
                    parse_mode="HTML",
                )

