async def handle_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if await handle_video_ai_edit_pending_media(update, context):
        return
    if await handle_video_editor_pending_upload(update, context):
        return
    if await handle_broadcast_lite_pending_photo(update, context):
        return
    uid = update.effective_user.id
    username = update.effective_user.first_name
    bill_state = get_active_manual_bill_state(uid)
    is_bill = bool(bill_state)

    if is_bill:
        lang = get_user_language(uid) or "vi"
        copy = public_hub_copy(lang)
        USER_BILL_STATE.pop(uid, None)
        photo = update.message.photo[-1]
        deposit = create_manual_pending_deposit(
            update.effective_user,
            bill_state,
            file_id=photo.file_id,
            file_unique_id=str(getattr(photo, "file_unique_id", "") or ""),
        )
        if not deposit.get("ok"):
            if public_copy_locale(lang) == "vi":
                failure_text = "⚠️ Không thể lưu bill này. Vui lòng mở lại Nạp thủ công và thử lại."
            else:
                failure_text = f"⚠️ {copy['common_failed']}\n\n{copy['common_no_charge']}"
            return await update.message.reply_text(failure_text)
        await notify_manual_pending_deposit(context, deposit)
        await update.message.reply_text(
            manual_pending_user_text(deposit, lang),
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(f"📂 {copy['manual_topup']}", callback_data=f"manual|history|{uid}"), InlineKeyboardButton(f"💬 {copy['support']}", callback_data="support|start")],
                [InlineKeyboardButton(f"🏠 {copy['main_menu']}", callback_data="menu|main")],
            ]),
        )
        return

    if await handle_free_hub_pending_upload(update, context):
        return

    if await handle_internal_archive_pending_upload(update, context):
        return

    if await handle_support_ticket_attachment(update, context):
        return

    if await handle_doc_tool_pending_upload(update, context):
        return

    if await handle_video_uiflow3_pending_media(update, context):
        return

    if await handle_storyboard2_pending_media(update, context):
        return

    if await handle_video_scene3_pending_media(update, context):
        return

    if await handle_architecture_profile_pending_media(update, context):
        return

    if await handle_image_menu_pending_photo(update, context):
        return

    frame_state = get_frame_video_state(uid)
    if frame_state and bool(frame_state.get("img2vid_lock1")) and await handle_frame_video_photo(update, context):
        return

    if await handle_video_product_pending_media(update, context):
        return

    if await handle_developing_video_pending_image(update, context):
        return

    if await handle_frame_video_photo(update, context):
        return

    if await handle_public_chat_attachment(update, context):
        return

    remember_last_user_file(update)
    cache_recent_media_state(update)
    await update.message.reply_text(
        image_upload_outside_flow_text(get_user_language(update.effective_user.id) if update.effective_user else "vi"),
        parse_mode="HTML",
        reply_markup=image_upload_outside_flow_keyboard(
            get_user_language(update.effective_user.id) if update.effective_user else "vi",
            admin=is_admin_user(update.effective_user.id) if update.effective_user else False,
        ),
    )

async def handle_translation_media_pending_upload(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message:
        return False
    uid = update.effective_user.id
    pending = get_translation_menu_pending(uid)
    ctx = str((pending or {}).get("translation_context") or "")
    if ctx not in {"translate_file", "translate_audio"}:
        return False
    lang = get_user_language(uid) or "vi"
    message = update.message
    document = getattr(message, "document", None)
    audio = getattr(message, "audio", None)
    voice = getattr(message, "voice", None)
    video = getattr(message, "video", None)
    doc_mime = str(getattr(document, "mime_type", "") or "").lower()
    doc_name = str(getattr(document, "file_name", "") or "").lower()
    doc_is_audio = bool(doc_mime.startswith("audio/") or doc_name.endswith((".mp3", ".wav", ".m4a", ".ogg", ".oga", ".aac", ".flac")))
    doc_is_video = bool(doc_mime.startswith("video/") or doc_name.endswith((".mp4", ".mov", ".mkv", ".webm", ".avi")))

    if ctx == "translate_file":
        if document and not doc_is_audio and not doc_is_video:
            info, _source = doc_input_file_info(update)
            if info:
                save_translation_request(uid, "file", source_ref=info)
                clear_translation_menu_pending(uid)
                await show_translation_picker(update, "file")
                return True
        await message.reply_text(
            public_hub_copy(normalize_user_language(lang) or "vi")["translation_file_only"],
            reply_markup=translation_input_keyboard(lang, parent="media"),
        )
        return True

    if ctx == "translate_audio":
        if video or doc_is_video:
            await message.reply_text(
                public_hub_copy(normalize_user_language(lang) or "vi")["translation_audio_video_redirect"],
                reply_markup=translation_voice_menu_keyboard(lang, parent="media"),
            )
            return True
        if audio or voice or doc_is_audio:
            cache_recent_media_state(update)
            remember_last_media(update)
            save_translation_request(uid, "voice")
            clear_translation_menu_pending(uid)
            await show_translation_picker(update, "voice")
            return True
        await message.reply_text(
            f"{public_hub_copy(normalize_user_language(lang) or 'vi')['translation_audio_only']} "
            f"{public_hub_copy(normalize_user_language(lang) or 'vi')['translation_audio_need_file']}",
            reply_markup=translation_voice_menu_keyboard(lang, parent="media"),
        )
        return True
    return False

