def video_dubbing_pending_key(user_id) -> str:
    return f"video_dubbing:{user_id}"

def video_dubbing_artifact_key(user_id, kind: str) -> str:
    return f"video_dubbing_artifact:{user_id}:{str(kind or '')[:40]}"

def set_video_dubbing_artifact(user_id, kind: str, value: str) -> str:
    ref = video_dubbing_artifact_key(user_id, kind)
    USER_PENDING[ref] = {"value": str(value or ""), "created_at_ts": time.time()}
    return ref

def get_video_dubbing_artifact(user_id, ref_or_kind: str) -> str:
    ref = str(ref_or_kind or "")
    if not ref.startswith("video_dubbing_artifact:"):
        ref = video_dubbing_artifact_key(user_id, ref)
    payload = USER_PENDING.get(ref) or {}
    if time.time() - float(payload.get("created_at_ts") or 0) > VIDEO_DUBBING_TTL_SECONDS:
        USER_PENDING.pop(ref, None)
        return ""
    return str(payload.get("value") or "")

def subdub_translation_cache_language_key(value: str = "") -> str:
    normalized = normalize_translate_target(value)
    if normalized:
        return normalized
    return re.sub(r"\s+", " ", unicodedata.normalize("NFKC", str(value or "")).strip()).casefold()[:80]

def subdub_translation_cache_source_hash(subtitle_text: str = "") -> str:
    body = unicodedata.normalize("NFC", str(subtitle_text or "")).strip()
    return hashlib.sha256(body.encode("utf-8", errors="strict")).hexdigest()[:24] if body else ""

def subdub_translation_cache_matches(state: dict | None, source_subtitle: str, target_language: str) -> bool:
    current = dict(state or {})
    translated_ref = str(current.get("translated_subtitle_ref") or "").strip()
    cached_language = str(current.get("translated_subtitle_target_language") or "").strip()
    cached_source_hash = str(current.get("translated_subtitle_source_hash") or "").strip()
    if translated_ref and not cached_language and not cached_source_hash:
        # Legacy jobs stored an explicit artifact ref without cache metadata.
        # Target changes clear that ref in set_video_dubbing_pending, so an
        # intact legacy ref remains safe to reuse for the current state.
        return True
    return bool(
        translated_ref
        and cached_language == subdub_translation_cache_language_key(target_language)
        and cached_source_hash == subdub_translation_cache_source_hash(source_subtitle)
    )

def normalize_video_translate_mode(value: str) -> str:
    raw_value = str(value or "").strip()
    raw_lower = raw_value.lower()
    aliases = {
        "subtitle": VIDEO_SUBTITLE_MODE_CREATE,
        "auto_subtitle": VIDEO_SUBTITLE_MODE_CREATE,
        "auto_subtitle_video": VIDEO_SUBTITLE_MODE_CREATE,
        "translate_subtitle": VIDEO_SUBTITLE_MODE_TRANSLATE,
        "subtitle_translate_video": VIDEO_SUBTITLE_MODE_TRANSLATE,
        "translated_subtitle_video": VIDEO_SUBTITLE_MODE_TRANSLATE,
        "voice": VIDEO_SUBTITLE_MODE_DUB,
        "video_dub": VIDEO_SUBTITLE_MODE_DUB,
        "dub_video": VIDEO_SUBTITLE_MODE_DUB,
        "dub_only": VIDEO_SUBTITLE_MODE_DUB,
        "video_dubbing": VIDEO_SUBTITLE_MODE_DUB,
        "translate_voice": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        "translate_dub": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        "full_video": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        "subtitle_dub": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        "subtitle_dub_video": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        "subtitle_plus_dub_video": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        "translated_subtitle_plus_dub": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        VIDEO_DUBBING_FLOW_SUBTITLE_FILE_TRANSLATE: VIDEO_SUBTITLE_MODE_TRANSLATE,
        VIDEO_DUBBING_FLOW_TRANSCRIPT: VIDEO_SUBTITLE_MODE_CREATE,
        "transcript": VIDEO_SUBTITLE_MODE_CREATE,
    }
    mode = aliases.get(raw_value, aliases.get(raw_lower, raw_value))
    return mode if mode in VIDEO_TRANSLATE_MODES else ""

def video_dubbing_is_video_only_mode(mode: str) -> bool:
    return normalize_video_translate_mode(mode) in VIDEO_ONLY_TRANSLATE_MODES

def video_dubbing_is_video_upload_info(info: dict | None = None) -> bool:
    info = dict(info or {})
    media_kind = str(info.get("media_kind") or info.get("file_type") or "").strip().lower()
    mime_type = str(info.get("mime_type") or info.get("source_mime_type") or "").strip().lower()
    file_name = str(info.get("file_name") or info.get("source_file_name") or "").strip().lower()
    return bool(
        media_kind == "video"
        or mime_type.startswith("video/")
        or file_name.endswith((".mp4", ".mov", ".mkv", ".webm"))
    )

