def video_only_price_discount_percent(chars: int) -> int:
    return finance_volume_discount_percent(chars)

def calculate_video_only_char_price(chars: int, rate_xu: float, *, minimum: int = 1) -> dict:
    chars = max(0, int(chars or 0))
    rate = float(rate_xu or 0)
    raw = chars * rate
    discount_percent = video_only_price_discount_percent(chars)
    discount_xu = raw * discount_percent / 100.0
    total = raw - discount_xu
    total_xu = int(math.ceil(total)) if chars and rate > 0 else 0
    if chars and rate > 0:
        total_xu = max(int(minimum or 1), total_xu)
    return {
        "chars": chars,
        "rate_xu": rate,
        "raw_xu": raw,
        "discount_percent": discount_percent,
        "discount_xu": discount_xu,
        "total_xu": total_xu,
    }

def video_dubbing_billing_char_count(state: dict | None = None) -> int:
    state = dict(state or {})
    for key in ("billing_chars", "billable_chars", "char_count", "subtitle_chars", "dub_chars", "transcript_chars", "estimated_chars"):
        value = _safe_int(state.get(key), 0)
        if value > 0:
            return value
    user_id = state.get("user_id") or state.get("_user_id") or state.get("uid")
    for key in ("translated_subtitle_ref", "subtitle_ref", "source_subtitle_ref"):
        ref = str(state.get(key) or "")
        if ref and user_id:
            text = get_video_dubbing_artifact(user_id, ref)
            if text:
                return len(text)
    duration = _safe_int(state.get("video_duration") or state.get("source_duration"), 0)
    if duration > 0:
        return max(100, duration * 12)
    return 0

def video_dubbing_flow_label(state: dict | None = None, lang: str = "vi") -> str:
    flow_type = str((state or {}).get("flow_type") or "")
    if normalize_user_language(lang) != "vi":
        return "Video with subtitles" if flow_type == VIDEO_DUBBING_FLOW_HAS_SUBTITLE else "Speech-only video"
    return "Video đã có phụ đề" if flow_type == VIDEO_DUBBING_FLOW_HAS_SUBTITLE else "Video chỉ có tiếng"

def video_only_price_line(price: dict) -> str:
    discount = int((price or {}).get("discount_percent") or 0)
    return f"{discount}%" if discount else "không"

SUBDUB_PRODUCT_TYPE_SUBTITLE_ONLY = "subtitle_only"
SUBDUB_PRODUCT_TYPE_DUB_ONLY = "dub_only"
SUBDUB_PRODUCT_TYPE_SUBTITLE_DUB = "subtitle_dub"
SUBDUB_PRODUCT_TYPES = {
    SUBDUB_PRODUCT_TYPE_SUBTITLE_ONLY,
    SUBDUB_PRODUCT_TYPE_DUB_ONLY,
    SUBDUB_PRODUCT_TYPE_SUBTITLE_DUB,
}

def subdub_expected_product_type_from_state(mode: str = "", state: dict | None = None) -> str:
    state = dict(state or {})
    direct = str(mode or "").strip().lower()
    if direct in SUBDUB_PRODUCT_TYPES:
        return direct
    requested = normalize_video_translate_mode(state.get("requested_mode") or "")
    active_flow = str(state.get("active_flow") or "").strip().lower()
    product = str(state.get("product") or "").strip().lower()
    source_entry = normalize_video_translate_mode(state.get("source_entry") or state.get("entry_surface") or "")
    if (
        requested == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB
        or active_flow == VIDEO_DUBBING_FLOW_SUBTITLE_PLUS_DUB
        or source_entry == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB
        or "subtitle_plus" in product
    ):
        return SUBDUB_PRODUCT_TYPE_SUBTITLE_DUB
    safe_mode = normalize_video_translate_mode(
        mode
        or state.get("video_processing_mode")
        or state.get("mode")
        or state.get("process_type")
    )
    if safe_mode == VIDEO_SUBTITLE_MODE_DUB:
        return SUBDUB_PRODUCT_TYPE_DUB_ONLY
    if safe_mode == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB:
        return SUBDUB_PRODUCT_TYPE_SUBTITLE_DUB
    if safe_mode:
        return SUBDUB_PRODUCT_TYPE_SUBTITLE_ONLY
    existing = str(state.get("product_type") or "").strip().lower()
    return existing if existing in SUBDUB_PRODUCT_TYPES else ""

def subdub_product_type_from_mode(mode: str = "", state: dict | None = None) -> str:
    state = dict(state or {})
    expected = subdub_expected_product_type_from_state(mode, state)
    if expected in SUBDUB_PRODUCT_TYPES:
        return expected
    existing = str(state.get("product_type") or "").strip().lower()
    if existing in SUBDUB_PRODUCT_TYPES:
        return existing
    direct = str(mode or "").strip().lower()
    if direct in SUBDUB_PRODUCT_TYPES:
        return direct
    safe_mode = normalize_video_translate_mode(
        mode
        or state.get("video_processing_mode")
        or state.get("mode")
        or state.get("process_type")
    )
    if safe_mode == VIDEO_SUBTITLE_MODE_DUB:
        return SUBDUB_PRODUCT_TYPE_DUB_ONLY
    if safe_mode == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB:
        return SUBDUB_PRODUCT_TYPE_SUBTITLE_DUB
    return SUBDUB_PRODUCT_TYPE_SUBTITLE_ONLY

def subdub_resolved_route_mode(mode: str = "", state: dict | None = None) -> str:
    state = dict(state or {})
    requested = normalize_video_translate_mode(state.get("requested_mode") or "")
    active_flow = str(state.get("active_flow") or "").strip().lower()
    source_entry = normalize_video_translate_mode(state.get("source_entry") or "")
    if (
        requested == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB
        or active_flow == VIDEO_DUBBING_FLOW_SUBTITLE_PLUS_DUB
        or source_entry == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB
    ):
        return VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB
    return normalize_video_translate_mode(
        mode
        or state.get("video_processing_mode")
        or state.get("mode")
        or state.get("process_type")
    )

def subdub_route_state_debug_fields(mode: str = "", state: dict | None = None, voice_resolution: dict | None = None) -> dict:
    state = dict(state or {})
    voice = dict(voice_resolution or state.get("_subdub_voice_resolution") or {})
    expected_product = subdub_expected_product_type_from_state(mode, state)
    resolved_product = subdub_product_type_from_mode(mode, state)
    existing_product = str(state.get("product_type") or "").strip().lower()
    selected_voice_id = str(
        voice.get("selected_voice_id")
        or state.get("selected_voice_id")
        or state.get("voice_id")
        or state.get("provider_voice_id")
        or state.get("selected_tts_voice_id")
        or ""
    ).strip()
    requested_mode = normalize_video_translate_mode(state.get("requested_mode") or "")
    active_flow = str(state.get("active_flow") or "").strip().lower()
    if requested_mode:
        route_source = "requested_mode"
    elif active_flow:
        route_source = "active_flow"
    elif mode or state.get("mode") or state.get("video_processing_mode"):
        route_source = "mode"
    elif existing_product:
        route_source = "product_type"
    else:
        route_source = "missing"
    return {
        "selected_public_entrypoint": str(state.get("source_entry") or state.get("entry_surface") or mode or "")[:120],
        "selected_subdub_product": str(state.get("product") or existing_product or resolved_product or "")[:120],
        "expected_product_type": expected_product,
        "resolved_product_type": resolved_product,
        "resolved_mode": subdub_resolved_route_mode(mode, state),
        "voice_gender_requested": str(voice.get("requested_voice_gender") or state.get("requested_voice_gender") or state.get("selected_voice_gender") or subdub_voice_gender_from_state(state) or "")[:40],
        "selected_voice_id_present": bool(selected_voice_id),
        "route_state_source": route_source,
        "route_state_stale_detected": bool(existing_product in SUBDUB_PRODUCT_TYPES and expected_product in SUBDUB_PRODUCT_TYPES and existing_product != expected_product),
    }

def subdub_expected_media_for_product(product_type: str = "") -> str:
    return "video" if str(product_type or "").strip().lower() in SUBDUB_PRODUCT_TYPES else ""

def subdub_back_stack_for_entry(mode: str = "", origin: str = "translation") -> str:
    safe_mode = normalize_video_translate_mode(mode)
    safe_origin = str(origin or "translation").strip().lower()
    parent = "videodub|start|video_addon" if safe_origin == "video_addon" else "videodub|start|translation"
    return " > ".join(item for item in (parent, f"videodub|type|{safe_mode}" if safe_mode else "") if item)

def subdub_entry_state_fields(
    mode: str = "",
    *,
    source_entry: str = "",
    origin: str = "translation",
    current_step: str = "source",
) -> dict:
    safe_mode = normalize_video_translate_mode(mode)
    product_type = subdub_product_type_from_mode(safe_mode)
    entry = str(source_entry or safe_mode or product_type).strip()
    return {
        "product_type": product_type,
        "current_step": str(current_step or "source")[:80],
        "expected_media": subdub_expected_media_for_product(product_type),
        "source_entry": entry[:120],
        "back_stack": subdub_back_stack_for_entry(safe_mode, origin),
    }

def set_video_dubbing_pending(user_id, step: str, **fields) -> dict:
    current = USER_PENDING.get(video_dubbing_pending_key(user_id)) or {}
    state = dict(current) if current.get("pending_action") == "video_dubbing" else {}
    next_step = str(step or "")[:80]
    previous_step = str(state.get("current_step") or state.get("step") or "")[:80]
    state.update({
        "pending_action": "video_dubbing",
        "step": next_step,
        "current_step": next_step,
        "previous_step": previous_step if previous_step and previous_step != next_step else str(state.get("previous_step") or "")[:80],
        "created_at_ts": time.time(),
    })
    translation_target_changed = False
    if "target_language" in fields:
        previous_target = subdub_translation_cache_language_key(state.get("target_language") or "")
        next_target = subdub_translation_cache_language_key(fields.get("target_language") or "")
        translation_target_changed = previous_target != next_target
    for key, value in fields.items():
        if key in {
            "mode", "process_type", "video_file_id", "source_file_id", "source_file_name",
            "video_processing_mode", "video_file_unique_id", "source_file_unique_id", "source_mime_type",
            "video_message_id", "video_duration", "source_duration",
            "video_file_size", "source_file_size", "source_language", "target_language",
            "voice_style", "processing", "pending_video_action", "pending_confirm_token",
            "voice_id", "voice_kind", "voice_profile_id", "voice_vault_page",
            "last_video_flow", "translate_requested", "origin", "product_context",
            "return_to", "source_kind", "source_url", "source_platform",
            "source_rights_confirmed", "link_import_job_id", "link_import_status",
            "link_import_charged_xu", "output_type", "output_label",
            "voice_speed", "voice_volume", "source_audio_volume", "smart_voice",
            "subdub_final_confirmed", "subdub_confirmation_source", "subdub_confirmed_at_ts",
            "subtitle_lines", "subtitle_draft", "subtitle_edit_line",
            "subtitle_find_text", "subtitle_replace_text", "subtitle_time_shift_ms",
            "requested_mode", "preview_seen", "preview_guard_acknowledged",
            "translation_session_id", "product", "current_step", "previous_step",
            "source_ref", "subtitle_ref", "source_subtitle_ref", "translated_subtitle_ref",
            "translated_subtitle_target_language", "translated_subtitle_source_hash",
            "source_file_ref", "source_media_type", "source_content_type",
            "active_flow", "output_format", "entry_surface", "media_kind",
            "selected_language", "selected_voice", "speed",
            "preview_seconds", "preview_text", "processing_error", "task2_job_id",
            "dub_source", "segment_count", "subtitle_segment_count",
            "translated_segment_count", "detected_language", "last_ready_step",
            "final_subtitle_available", "final_audio_available",
            "final_video_available", "final_dub_asset_id",
            "final_dub_video_asset_id", "final_subtitle_asset_ids",
            "final_translation_asset_ids", "flow_type",
            "source_has_subtitle", "video_has_subtitle", "has_embedded_subtitle",
            "existing_subtitle_detected", "billing_chars", "billable_chars",
            "char_count", "subtitle_chars", "dub_chars", "transcript_chars",
            "estimated_chars", "combo_subpath", "product_type",
            "expected_media", "source_entry", "back_stack",
            "selected_voice_gender", "selected_voice_id", "selected_voice_label",
            "resolved_voice_id", "resolved_gender", "auto_detected_gender",
            "voice_confidence", "voice_fallback_reason", "voice_fallback_used",
            "provider_voice_id", "tts_payload_voice_id", "selected_tts_voice_id",
            "requested_voice_gender", "dub_voice_gender",
            "hardsub_cover_enabled", "subtitle_style_profile",
            "subtitle_style_preset", "cover_original_subtitle",
            "subtitle_position_slot", "subtitle_position", "subtitle_align",
            "subtitle_position_return_step",
            "cover_opacity", "cover_height_ratio", "cover_y_ratio",
            "advanced_style_enabled",
            "keep_original_audio", "original_audio_volume_percent",
            "dubbed_voice_volume_percent", "audio_mix_mode",
            "volume_config_source", "audio_mix_return_step",
        }:
            state[key] = _short_pending_text(value)
    if translation_target_changed:
        state["translated_subtitle_ref"] = ""
        state["translated_subtitle_target_language"] = ""
        state["translated_subtitle_source_hash"] = ""
    mode = normalize_video_translate_mode(
        state.get("video_processing_mode") or state.get("mode") or state.get("process_type")
    )
    if mode:
        state["mode"] = mode
        state["process_type"] = mode
        state["video_processing_mode"] = mode
        default_product = {
            VIDEO_SUBTITLE_MODE_CREATE: "auto_subtitle",
            VIDEO_SUBTITLE_MODE_TRANSLATE: "subtitle_plus_dubbing" if normalize_video_translate_mode(state.get("requested_mode")) == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB else "subtitle_translation",
            VIDEO_SUBTITLE_MODE_DUB: "auto_dubbing",
            VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB: "subtitle_plus_dubbing",
        }.get(mode, state.get("product") or "")
        default_active_flow = {
            VIDEO_SUBTITLE_MODE_CREATE: "auto_subtitle",
            VIDEO_SUBTITLE_MODE_TRANSLATE: "subtitle_translate",
            VIDEO_SUBTITLE_MODE_DUB: "dub_audio",
            VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB: VIDEO_DUBBING_FLOW_SUBTITLE_PLUS_DUB,
        }.get(mode, state.get("active_flow") or "")
        active_flow = str(state.get("active_flow") or default_active_flow)
        if active_flow == VIDEO_DUBBING_FLOW_TRANSCRIPT:
            state["product"] = "transcript"
            state["output_type"] = str(state.get("output_type") or "txt")
            state["output_format"] = str(state.get("output_format") or "txt")
        elif active_flow == VIDEO_DUBBING_FLOW_SUBTITLE_FILE_TRANSLATE:
            state["product"] = "subtitle_file_translation"
        else:
            state["product"] = default_product
            active_flow = default_active_flow
        state["active_flow"] = active_flow
        product_type = subdub_product_type_from_mode(mode, state)
        state["product_type"] = product_type
        state["expected_media"] = str(state.get("expected_media") or subdub_expected_media_for_product(product_type))
        state["source_entry"] = str(state.get("source_entry") or mode)[:120]
        state["back_stack"] = str(
            state.get("back_stack")
            or subdub_back_stack_for_entry(mode, state.get("origin") or "translation")
        )[:300]
    if not state.get("translation_session_id"):
        state["translation_session_id"] = hashlib.sha256(f"video-task2:{user_id}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20]
    state["source_ref"] = str(state.get("source_ref") or state.get("source_file_id") or state.get("video_file_id") or "")[:300]
    state["selected_language"] = str(state.get("target_language") or state.get("selected_language") or "")[:120]
    state["selected_voice"] = str(state.get("voice_style") or state.get("selected_voice") or "")[:160]
    state["speed"] = str(state.get("voice_speed") or state.get("speed") or "")[:20]
    if state.get("video_file_id") and not state.get("source_file_id"):
        state["source_file_id"] = state["video_file_id"]
    if state.get("source_file_id") and not state.get("video_file_id"):
        state["video_file_id"] = state["source_file_id"]
    if state.get("video_duration") and not state.get("source_duration"):
        state["source_duration"] = state["video_duration"]
    if state.get("source_duration") and not state.get("video_duration"):
        state["video_duration"] = state["source_duration"]
    USER_PENDING[video_dubbing_pending_key(user_id)] = state
    return state

def get_video_dubbing_pending(user_id) -> dict | None:
    state = USER_PENDING.get(video_dubbing_pending_key(user_id)) or {}
    if state.get("pending_action") != "video_dubbing":
        return None
    if time.time() - float(state.get("created_at_ts") or 0) > VIDEO_DUBBING_TTL_SECONDS:
        USER_PENDING.pop(video_dubbing_pending_key(user_id), None)
        return None
    return state

def clear_video_dubbing_pending(user_id) -> bool:
    changed = USER_PENDING.pop(video_dubbing_pending_key(user_id), None) is not None
    prefix = f"video_dubbing_artifact:{user_id}:"
    for key in list(USER_PENDING.keys()):
        if str(key).startswith(prefix):
            USER_PENDING.pop(key, None)
    return changed

