def subdub_duration_validation_allows_success(payload: dict | None = None) -> bool:
    current = dict(payload or {})
    validation = dict(current.get("output_validation") or current.get("_subdub_output_validation") or {})
    blocker = str(current.get("success_blocked_reason") or current.get("artifact_validation_result") or validation.get("detail") or "").strip()
    if blocker == "video_duration_coverage_failed":
        return False
    has_duration_contract = bool(
        "duration_coverage_ok" in current
        or "duration_coverage_ok" in validation
        or float(current.get("expected_duration") or validation.get("expected_duration") or 0.0) > 0
    )
    if not has_duration_contract:
        return True
    if "duration_coverage_ok" in current and not truthy_value(current.get("duration_coverage_ok"), False):
        return False
    if "duration_coverage_ok" in validation and not truthy_value(validation.get("duration_coverage_ok"), False):
        return False
    if validation and "ok" in validation and not truthy_value(validation.get("ok"), False):
        return False
    expected = max(0.0, float(current.get("expected_duration") or current.get("source_duration") or validation.get("expected_duration") or validation.get("source_duration") or 0.0))
    actual = max(0.0, float(current.get("canonical_final_artifact_duration") or current.get("final_mp4_duration") or validation.get("actual_duration") or validation.get("duration") or 0.0))
    if expected > 0:
        if actual <= 0 or actual < expected * 0.97:
            return False
    return True


SUBDUB_VIDEO_DELIVERY_MESSAGE_ID_KEYS = (
    "video_delivery_message_id",
    "final_video_message_id",
    "subdub_final_video_message_id",
)

SUBDUB_SUBTITLE_DELIVERY_MESSAGE_ID_KEYS = (
    "srt_delivery_message_id",
    "subtitle_delivery_message_id",
)


def subdub_payload_requires_final_mp4(payload: dict | None = None) -> bool:
    """Resolve the lane contract before accepting a delivery artifact."""
    current = dict(payload or {})
    candidates = [current]
    nested_state = current.get("state")
    if isinstance(nested_state, dict):
        candidates.append(nested_state)
    for candidate in candidates:
        mode_values = (
            candidate.get("mode"),
            candidate.get("mapped_mode"),
            candidate.get("video_processing_mode"),
            candidate.get("requested_mode"),
        )
        product_values = (
            candidate.get("product_type"),
            candidate.get("mapped_product_type"),
        )
        if any(
            subdub_video_requires_final_mp4(mode, product)
            for mode in mode_values
            for product in product_values
        ):
            return True
        if any(subdub_video_requires_final_mp4(mode) for mode in mode_values):
            return True
        if any(subdub_video_requires_final_mp4("", product) for product in product_values):
            return True
    return False


def subdub_terminal_delivery_evidence(*payloads: dict | None) -> dict:
    """Return lane-specific Telegram evidence, never generic success flags."""
    requires_final_mp4 = any(subdub_payload_requires_final_mp4(payload) for payload in payloads)
    for payload in payloads:
        current = dict(payload or {})
        nested_state = current.get("state")
        candidates = [current]
        if isinstance(nested_state, dict):
            candidates.append(nested_state)
        for candidate in candidates:
            for key in SUBDUB_VIDEO_DELIVERY_MESSAGE_ID_KEYS:
                message_id = str(candidate.get(key) or "").strip()
                if message_id and subdub_duration_validation_allows_success({**current, **candidate}):
                    return {
                        "artifact_type": "video",
                        "is_video": True,
                        "message_id": message_id,
                        "message_id_key": key,
                    }
            if not requires_final_mp4:
                for key in SUBDUB_SUBTITLE_DELIVERY_MESSAGE_ID_KEYS:
                    message_id = str(candidate.get(key) or "").strip()
                    if message_id:
                        return {
                            "artifact_type": "subtitle",
                            "is_video": False,
                            "message_id": message_id,
                            "message_id_key": key,
                        }
    return {}


def subdub_confirmed_video_delivery_message_id(*payloads: dict | None) -> str:
    evidence = subdub_terminal_delivery_evidence(*payloads)
    if not evidence.get("is_video"):
        return ""
    return str(evidence.get("message_id") or "").strip()


def subdub_result_has_delivered_video(result: dict | None = None) -> bool:
    return bool(subdub_confirmed_video_delivery_message_id(result))


def subdub_registry_terminal_state(result: dict | None = None) -> str:
    current = dict(result or {})
    evidence = subdub_terminal_delivery_evidence(current)
    if evidence:
        return "delivered"
    if current.get("partial_audio_delivered") or current.get("delivery_partial_result"):
        return "needs_admin_review"
    return "failed_no_charge"


def subdub_rehydrate_terminal_job(job: dict | None = None) -> tuple[str, dict]:
    """Restore delivered registry state without submitting or reprocessing work."""
    current = dict(job or {})
    identity = str(
        current.get("job_key")
        or current.get("internal_job_id")
        or current.get("job_id")
        or current.get("public_code")
        or ""
    ).strip()
    if not identity:
        return "", current
    key = str(current.get("job_key") or f"persisted_subdub:{identity}")
    existing = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(key) or {})
    nonempty_existing = {
        field: value
        for field, value in existing.items()
        if value not in (None, "", [], {})
    }
    restored = subdub_enrich_job_identity(
        {**current, **nonempty_existing, "job_key": key},
        job_key=key,
        mode=str(current.get("mode") or current.get("mapped_mode") or ""),
        state=current,
    )
    SUBTITLE_DUB_PIPELINE_JOBS[key] = restored
    return key, dict(restored)


def subdub_persisted_job_registry_present(job: dict | None = None) -> bool:
    current = dict(job or {})
    key = str(current.get("job_key") or "").strip()
    if key and key in SUBTITLE_DUB_PIPELINE_JOBS:
        return True
    wanted = subdub_job_identifier_variants(current)
    if not wanted:
        return False
    return any(
        bool(wanted & subdub_job_identifier_variants(candidate))
        for candidate in SUBTITLE_DUB_PIPELINE_JOBS.values()
    )


def subdub_panel_edit_already_terminal(error: Exception | None = None) -> bool:
    """Telegram uses this error when the stored panel is already identical."""
    token = " ".join(
        part
        for part in (
            str(error or ""),
            str(getattr(error, "message", "") or ""),
        )
        if part
    ).strip().lower()
    return "message is not modified" in token or "message_not_modified" in token


def subdub_should_terminalize_interrupted_persisted_job(
    job: dict | None = None,
    *,
    registry_present: bool = False,
) -> bool:
    current = dict(job or {})
    if not current or registry_present:
        return False
    if str(current.get("lookup_store_hit") or "") not in {
        "engine_async_direct",
        "engine_async_feature_index",
        "engine_async_persisted_scan",
    }:
        return False
    if subdub_terminal_delivery_evidence(current) or subdub_existing_mp4_recovery_candidate(current):
        return False
    terminal = str(current.get("terminal_state") or "").strip().lower()
    if terminal in SUBDUB_TERMINAL_STATES:
        return False
    status = str(current.get("status") or "").strip().lower()
    progress = _safe_int(current.get("progress_percent"), 0)
    active = status in {"", "queued", "running", "processing", "submitted"} and 0 < progress < 100
    return bool(active and current.get("pipeline_started"))


def subdub_terminalize_interrupted_persisted_job(
    job_key: str,
    job: dict | None = None,
) -> dict:
    current = dict(job or {})
    stage = subdub_canonical_lifecycle_state(
        current.get("progress_stage")
        or current.get("current_stage")
        or current.get("lifecycle_state")
        or "saved_input"
    )
    if stage in SUBDUB_TERMINAL_STATES:
        stage = "saved_input"
    progress = max(
        5,
        _safe_int(current.get("progress_percent"), 0),
        subdub_progress_percent_for_lifecycle(stage, "failed_no_charge"),
    )
    return update_subtitle_dub_pipeline_job(
        job_key,
        status="failed_no_charge",
        terminal_state="failed_no_charge",
        lifecycle_state=stage,
        current_stage=stage,
        progress_stage=stage,
        progress_percent=progress,
        completed_steps=subdub_completed_steps_for_lifecycle(stage, "failed_no_charge"),
        charge_status="not_charged",
        charged_xu=0,
        no_charge_reason="interrupted_after_restart_no_artifact",
        pipeline_blocker="interrupted_after_restart_no_artifact",
        provider_resubmit_prevented=True,
        provider_replay_count=0,
        status_panel_terminalized=True,
        refresh_stopped_after_terminal=True,
        panel_finalized=True,
        panel_final_percent=progress,
        delivery_success=False,
        delivery_succeeded=False,
        final_mp4_delivered=False,
    )


def subdub_existing_mp4_recovery_candidate(job: dict | None = None) -> str:
    current = dict(job or {})
    if subdub_terminal_delivery_evidence(current):
        return ""
    if (
        truthy_value(current.get("delivery_attempted"), False)
        or truthy_value(current.get("delivery_started"), False)
        or _safe_int(current.get("delivery_attempts"), 0) > 0
    ):
        return ""
    if not bool(
        truthy_value(current.get("final_mp4_validated"), False)
        or truthy_value(current.get("output_validated"), False)
    ):
        return ""
    for key in ("canonical_final_artifact_path", "final_mp4_path", "output_video_path", "final_video_path"):
        path = str(current.get(key) or "").strip()
        if path and os.path.exists(path):
            try:
                if os.path.getsize(path) > 0:
                    return path
            except OSError:
                pass
    return ""


async def subdub_recover_existing_mp4_delivery(
    query,
    context,
    job_key: str,
    job: dict | None = None,
    lang: str = "vi",
) -> dict:
    del context
    current = dict(job or {})
    path = subdub_existing_mp4_recovery_candidate(current)
    if not job_key or not path or not getattr(query, "message", None):
        return {}
    update_subtitle_dub_pipeline_job(
        job_key,
        delivery_attempted=True,
        delivery_started=True,
        delivery_attempts=max(1, _safe_int(current.get("delivery_attempts"), 0) + 1),
        delivery_recovery_started=True,
        delivery_recovery_started_at=time.time(),
    )
    try:
        delivery = await send_public_subtitle_dub_final_outputs(
            query.message,
            mode=str(current.get("mode") or current.get("mapped_mode") or ""),
            active_flow=str(current.get("active_flow") or ""),
            requested_mode=str(current.get("requested_mode") or ""),
            subtitle_items=[],
            srt_text="",
            audio_bytes=b"",
            video_bytes=b"",
            lang=lang,
            include_subtitle_outputs=False,
            strict_validation=True,
            job_key=job_key,
            expected_duration_seconds=float(current.get("expected_duration") or current.get("source_duration") or 0.0),
            canonical_video_path=path,
            require_final_audio=bool(
                truthy_value(current.get("final_audio_required"), False)
                or truthy_value(current.get("source_has_audio"), False)
                or normalize_video_translate_mode(current.get("mode") or current.get("mapped_mode") or "")
                in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}
            ),
        )
    except Exception as exc:
        update_subtitle_dub_pipeline_job(
            job_key,
            status="failed_no_charge",
            terminal_state="failed_no_charge",
            lifecycle_state="failed_no_charge",
            current_stage="failed_no_charge",
            progress_stage="failed_no_charge",
            progress_percent=subdub_progress_percent_for_lifecycle("failed_no_charge", "failed_no_charge"),
            charge_status="not_charged",
            no_charge_reason="existing_mp4_delivery_failed",
            delivery_recovery_failed=True,
            delivery_attempt_uncertain=subdub_receipt_send_is_uncertain(exc),
        )
        return {}
    message_id = subdub_confirmed_video_delivery_message_id(delivery)
    if not message_id:
        update_subtitle_dub_pipeline_job(
            job_key,
            status="failed_no_charge",
            terminal_state="failed_no_charge",
            lifecycle_state="failed_no_charge",
            current_stage="failed_no_charge",
            progress_stage="failed_no_charge",
            progress_percent=subdub_progress_percent_for_lifecycle("failed_no_charge", "failed_no_charge"),
            charge_status="not_charged",
            no_charge_reason="existing_mp4_delivery_unconfirmed",
            delivery_recovery_failed=True,
        )
        return dict(delivery)
    mark_subtitle_dub_pipeline_output_sent(
        job_key,
        terminal_state="delivered",
        delivery_message_id=message_id,
        terminal_artifact_type="video",
        video_delivery_message_id=message_id,
    )
    update_subtitle_dub_pipeline_job(
        job_key,
        delivery_recovery_succeeded=True,
        delivery_recovery_completed_at=time.time(),
        video_delivery_message_id=message_id,
        final_video_message_id=message_id,
        subdub_final_video_message_id=message_id,
        final_mp4_delivered=True,
        delivery_success=True,
        delivery_succeeded=True,
    )
    return {**current, **delivery, "video_delivery_message_id": message_id}


def subdub_video_delivery_message_id(*payloads: dict | None) -> str:
    """Return concrete Telegram video-delivery evidence, never a status flag."""
    return subdub_confirmed_video_delivery_message_id(*payloads)


def subdub_reconcile_delivered_video_result(
    mode: str,
    result: dict | None = None,
    job: dict | None = None,
    state: dict | None = None,
) -> dict:
    """Merge persisted Telegram delivery truth back into a final callback result."""
    current_result = dict(result or {})
    current_job = dict(job or {})
    current_state = dict(state or {})
    normalized_mode = normalize_video_translate_mode(mode)
    if normalized_mode not in {
        VIDEO_SUBTITLE_MODE_CREATE,
        VIDEO_SUBTITLE_MODE_TRANSLATE,
        VIDEO_SUBTITLE_MODE_DUB,
        VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
    }:
        return current_result
    message_id = subdub_video_delivery_message_id(current_result, current_job)
    if not message_id:
        return current_result
    delivery_context = {
        **current_state,
        **current_job,
        **dict(current_result.get("state") or {}),
        **current_result,
        "video_delivery_message_id": message_id,
    }
    if not subdub_duration_validation_allows_success(delivery_context):
        return current_result
    reconciled_state = {
        **current_state,
        **dict(current_job.get("state") or {}),
        **dict(current_result.get("state") or {}),
        "terminal_state": "delivered",
        "status_panel_terminalized": True,
        "panel_finalized": True,
        "panel_final_percent": 100,
    }
    return {
        **current_job,
        **current_result,
        "ok": True,
        "status": "completed",
        "has_video": True,
        "video_delivered": True,
        "final_mp4_delivered": True,
        "delivery_success": True,
        "delivery_succeeded": True,
        "terminal_state": "delivered",
        "terminal_public_outcome_type": "success",
        "terminal_public_outcome_sent": True,
        "telegram_message_id": message_id,
        "delivery_message_id": message_id,
        "video_delivery_message_id": message_id,
        "final_video_message_id": message_id,
        "subdub_final_video_message_id": message_id,
        "public_error_sent": False,
        "public_failure_sent": False,
        "public_error_sent_count": 0,
        "late_fail_suppressed": True,
        "state": reconciled_state,
    }

def subdub_receipt_voice_label(state: dict | None = None, result: dict | None = None, lang: str = "vi") -> str:
    current = {
        **dict(state or {}),
        **dict((result or {}).get("state") or {}),
        **dict(result or {}),
    }
    gender = str(
        current.get("resolved_gender")
        or current.get("selected_voice_gender")
        or current.get("requested_voice_gender")
        or current.get("voice_gender")
        or ""
    ).strip().lower()
    if gender not in {"female", "male"}:
        gender = subdub_voice_gender_from_state(current)
    if normalize_user_language(lang) != "vi":
        if gender == "female":
            return "female voice"
        if gender == "male":
            return "male voice"
    else:
        if gender == "female":
            return "Giọng nữ"
        if gender == "male":
            return "Giọng nam"
    label = str(
        current.get("selected_voice_label")
        or current.get("voice_label")
        or current.get("voice_style")
        or ""
    ).strip()
    if not label:
        return ""
    label_normalized = subdub_voice_text_normalized(label)
    if any(token in label_normalized for token in {"provider", "api", "voice_id", "callback", "handler"}):
        return ""
    if minimax_voice_adapter.validate_provider_voice_id(label):
        return ""
    return label[:80]


def subdub_receipt_financial_snapshot(
    user_id,
    *,
    price_xu: int = 0,
    charged_xu: int = 0,
) -> dict:
    """Read the post-charge balance without performing another wallet mutation."""
    balance_xu = 0
    try:
        balance_xu, _total_spent, _is_vip = get_user(user_id)
    except Exception as exc:
        logger.warning(
            "subdub receipt balance read failed | error=%s",
            type(exc).__name__,
        )
    return {
        "final_price_xu": max(0, _safe_int(price_xu, 0)),
        "charged_xu": max(0, _safe_int(charged_xu, 0)),
        "account_balance_xu": max(0, _safe_int(balance_xu, 0)),
    }


def subdub_receipt_duration_label(duration_seconds, lang: str = "vi") -> str:
    duration = max(0, _safe_int(duration_seconds, 0))
    if not duration:
        return "Đang cập nhật" if normalize_user_language(lang) == "vi" else "Updating"
    minutes, seconds = divmod(duration, 60)
    if normalize_user_language(lang) != "vi":
        return f"{minutes} min {seconds} sec" if minutes else f"{seconds} sec"
    return f"{minutes} phút {seconds} giây" if minutes else f"{seconds} giây"

def video_dubbing_receipt_text(state: dict | None = None, result: dict | None = None, lang: str = "vi") -> str:
    state = state or {}
    result = result or {}
    receipt_context = {**state, **dict(result.get("state") or {}), **result}
    mode = normalize_video_translate_mode(
        receipt_context.get("requested_mode")
        or receipt_context.get("mode")
        or receipt_context.get("video_processing_mode")
    )
    outcome_type = str(result.get("terminal_public_outcome_type") or state.get("terminal_public_outcome_type") or "").strip().lower()
    public_error_already_sent = bool(result.get("public_error_sent") or state.get("public_error_sent") or int(result.get("public_error_sent_count") or state.get("public_error_sent_count") or 0) > 0)
    duration_valid = subdub_duration_validation_allows_success(receipt_context)
    # Keep the historical result-only check for compatibility, then include
    # persisted state fields used by refreshed status/receipt rendering.
    delivered_video = subdub_result_has_delivered_video(result)
    delivered_video = delivered_video or subdub_result_has_delivered_video(receipt_context)
    terminal_delivered = duration_valid and str(result.get("terminal_state") or state.get("terminal_state") or "").strip().lower() == "delivered"
    if outcome_type == "partial_audio_delivered" or result.get("partial_audio_delivered") or state.get("partial_audio_delivered"):
        if SUBDUB_PUBLIC_AUDIO_FALLBACK_ENABLED:
            return subdub_audio_fallback_text(mode, lang)
        return subdub_final_video_failed_text(lang) if subdub_video_requires_final_mp4(mode) else subdub_mode_fail_text(mode, lang)
    if not duration_valid:
        return subdub_duration_invalid_output_text(lang)
    if not (delivered_video or terminal_delivered) and (outcome_type == "failure" or (
        public_error_already_sent
        and not bool(result.get("late_fail_suppressed") or state.get("late_fail_suppressed"))
    )):
        return subdub_mode_fail_text(mode, lang)
    charged_xu = int(result.get("charged") or result.get("charged_xu") or state.get("charged_xu") or 0)
    if delivered_video or terminal_delivered:
        actual_duration = float(
            receipt_context.get("canonical_final_artifact_duration")
            or receipt_context.get("final_mp4_duration")
            or (receipt_context.get("output_validation") or {}).get("actual_duration")
            or (receipt_context.get("output_validation") or {}).get("duration")
            or 0.0
        )
        if actual_duration <= 0:
            actual_duration = float(
                receipt_context.get("source_duration")
                or receipt_context.get("input_duration_seconds")
                or receipt_context.get("input_duration")
                or receipt_context.get("video_duration")
                or 0.0
            )
        duration = subdub_receipt_duration_label(actual_duration, lang)
        product_labels = {
            VIDEO_SUBTITLE_MODE_CREATE: "Video phụ đề",
            VIDEO_SUBTITLE_MODE_TRANSLATE: "Video phụ đề dịch",
            VIDEO_SUBTITLE_MODE_DUB: "Video lồng tiếng",
            VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB: "Video combo phụ đề - lồng tiếng",
        }
        type_labels = {
            VIDEO_SUBTITLE_MODE_CREATE: "Phụ đề",
            VIDEO_SUBTITLE_MODE_TRANSLATE: "Phụ đề dịch",
            VIDEO_SUBTITLE_MODE_DUB: "Lồng tiếng",
            VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB: "Combo phụ đề - lồng tiếng",
        }
        product_label = product_labels.get(mode, "Video đã xử lý")
        type_label = type_labels.get(mode, product_label)
        job_code = (
            result.get("public_job_id")
            or result.get("subdub_public_job_id")
            or result.get("job_id")
            or result.get("internal_job_id")
            or state.get("public_job_id")
            or state.get("subdub_public_job_id")
            or state.get("_pipeline_job_id")
            or state.get("job_id")
            or ""
        )
        support_code = subdub_public_job_code(str(job_code)) if job_code else "-"
        is_vi = normalize_user_language(lang) == "vi"
        target_language = str(receipt_context.get("target_language") or "").strip()
        if not target_language:
            target_language = "Không dịch" if is_vi else "Not translated"
        final_price_xu = max(
            0,
            _safe_int(
                receipt_context.get("final_price_xu"),
                charged_xu,
            ),
        )
        balance_present = "account_balance_xu" in receipt_context
        account_balance_xu = max(0, _safe_int(receipt_context.get("account_balance_xu"), 0))
        if normalize_user_language(lang) != "vi":
            return (
                "✅ <b>Completed</b>\n\n"
                f"• Support code: <code>{html.escape(support_code)}</code>\n"
                f"• Result: <b>{html.escape(product_label)}</b>\n"
                f"• Translation language: <b>{html.escape(target_language)}</b>\n"
                f"• Service type: <b>{html.escape(type_label)}</b>\n"
                f"• Duration: <b>{html.escape(duration)}</b>\n"
                f"• Price: <b>{final_price_xu} Xu</b>\n"
                f"• Charged: <b>{int(charged_xu or 0)} Xu</b>\n"
                f"• Account balance: <b>{account_balance_xu} Xu</b>\n"
                "• Status: <b>Video sent</b>"
            )
        return (
            "✅ <b>Đã hoàn tất</b>\n\n"
            f"• Mã xử lý: <code>{html.escape(support_code)}</code>\n"
            f"• Kết quả: <b>{html.escape(product_label)}</b>\n"
            f"• Ngôn ngữ dịch: <b>{html.escape(target_language)}</b>\n"
            f"• Loại dịch vụ: <b>{html.escape(type_label)}</b>\n"
            f"• Thời lượng: <b>{html.escape(duration)}</b>\n"
            f"• Giá: <b>{final_price_xu} Xu</b>\n"
            f"• Đã trừ: <b>{int(charged_xu or 0)} Xu</b>\n"
            f"• Tài khoản còn: <b>{account_balance_xu if balance_present else 0} Xu</b>\n"
            "• Trạng thái: <b>Đã gửi video</b>"
        )
    if mode == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB:
        return subtitle_plus_dub_completed_text(state, result, lang)
    sent_count = sum(int(result.get(key) or 0) for key in ("sent_documents", "sent_audio", "sent_video", "sent_video_document"))
    if normalize_user_language(lang) != "vi":
        if sent_count > 0:
            return f"The result was sent above.\n\n{cost_line}"
        _filename, caption, _button = video_dubbing_final_video_label(mode, lang)
        if mode in {VIDEO_SUBTITLE_MODE_CREATE, VIDEO_SUBTITLE_MODE_TRANSLATE} and not result.get("has_video") and result.get("has_subtitle"):
            caption = subdub_subtitle_fallback_text(mode, lang)
        if mode == VIDEO_SUBTITLE_MODE_DUB and not result.get("has_video") and result.get("has_audio"):
            caption = subdub_audio_fallback_text(mode, lang) if SUBDUB_PUBLIC_AUDIO_FALLBACK_ENABLED else subdub_final_video_failed_text(lang)
        return f"{caption}\n\n{cost_line}"
    if sent_count > 0:
        return f"Kết quả đã gửi phía trên.\n\n{cost_line}"
    _filename, caption, _button = video_dubbing_final_video_label(mode, lang)
    if mode in {VIDEO_SUBTITLE_MODE_CREATE, VIDEO_SUBTITLE_MODE_TRANSLATE} and not result.get("has_video") and result.get("has_subtitle"):
        caption = subdub_subtitle_fallback_text(mode, lang)
    if mode == VIDEO_SUBTITLE_MODE_DUB and not result.get("has_video") and result.get("has_audio"):
        caption = subdub_audio_fallback_text(mode, lang) if SUBDUB_PUBLIC_AUDIO_FALLBACK_ENABLED else subdub_final_video_failed_text(lang)
    return f"{caption}\n\n{cost_line}"
def video_dubbing_receipt_keyboard(lang: str = "vi", origin: str = "translation", state: dict | None = None) -> InlineKeyboardMarkup:
    is_vi = normalize_user_language(lang) == "vi"
    state = dict(state or {})
    mode = normalize_video_translate_mode(state.get("mode") or state.get("video_processing_mode"))
    active_flow = str(state.get("active_flow") or "")
    rows = []
    if str(origin or "").strip().lower() == "video_addon":
        rows.append([InlineKeyboardButton("⬅️ Quay lại tùy chọn video" if is_vi else "⬅️ Back to video options", callback_data="videodub|return_origin")])
    if active_flow == VIDEO_DUBBING_FLOW_TRANSCRIPT:
        rows.append([InlineKeyboardButton("🧾 Tải TXT" if is_vi else "🧾 Download TXT", callback_data="videodub|download_final_subtitle")])
    elif active_flow == VIDEO_DUBBING_FLOW_SUBTITLE_FILE_TRANSLATE:
        rows.append([InlineKeyboardButton("📄 Tải phụ đề dịch" if is_vi else "📄 Download translated subtitle", callback_data="videodub|download_final_subtitle")])
    elif mode == VIDEO_SUBTITLE_MODE_CREATE:
        _filename, _caption, video_button = video_dubbing_final_video_label(mode, lang)
        rows.extend([
            [
                InlineKeyboardButton(video_button, callback_data="videodub|download_final_video"),
                InlineKeyboardButton("📄 Tải SRT" if is_vi else "📄 Download SRT", callback_data="videodub|download_final_subtitle"),
            ],
            [
                InlineKeyboardButton("🔁 Tạo lại phụ đề" if is_vi else "🔁 Create subtitles again", callback_data="videodub|retry_media"),
                InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"),
            ],
        ])
        return InlineKeyboardMarkup(rows)
    elif mode == VIDEO_SUBTITLE_MODE_TRANSLATE:
        _filename, _caption, video_button = video_dubbing_final_video_label(mode, lang)
        requested = normalize_video_translate_mode(state.get("requested_mode"))
        rows.extend([
            [
                InlineKeyboardButton(video_button, callback_data="videodub|download_final_video"),
                InlineKeyboardButton("📄 Tải SRT dịch" if is_vi else "📄 Download translated SRT", callback_data="videodub|download_final_subtitle"),
            ],
        ])
        if requested == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB:
            rows.append([
                InlineKeyboardButton("🎙 Lồng tiếng bản dịch" if is_vi else "🎙 Dub translated subtitles", callback_data="videodub|result_translate_dub"),
                InlineKeyboardButton("🌐 Dịch ngôn ngữ khác" if is_vi else "🌐 Translate another language", callback_data="videodub|result_translate"),
            ])
            rows.append([InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")])
        else:
            rows.append([
                InlineKeyboardButton("🌐 Dịch ngôn ngữ khác" if is_vi else "🌐 Translate another language", callback_data="videodub|result_translate"),
                InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"),
            ])
        return InlineKeyboardMarkup(rows)
    elif mode == VIDEO_SUBTITLE_MODE_DUB:
        _filename, _caption, video_button = video_dubbing_final_video_label(mode, lang)
        first_row = []
        if str(state.get("final_video_available") or "") == "1":
            first_row.append(InlineKeyboardButton(video_button, callback_data="videodub|download_final_video"))
        if str(state.get("final_audio_available") or "") == "1":
            first_row.append(InlineKeyboardButton("🎧 Tải audio" if is_vi else "🎧 Download audio", callback_data="videodub|download_final_audio"))
        if first_row:
            rows.append(first_row)
        rows.append([
            InlineKeyboardButton("🔁 Lồng tiếng lại" if is_vi else "🔁 Dub again", callback_data="videodub|redub_voice"),
            InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main"),
        ])
        return InlineKeyboardMarkup(rows)
    rows.extend([
        [InlineKeyboardButton("🔁 Làm video khác" if is_vi else "🔁 Another video", callback_data="videodub|back_type")],
        [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
    ])
    return InlineKeyboardMarkup(rows)

def video_dubbing_mode_flag(mode: str) -> bool:
    return {
        VIDEO_SUBTITLE_MODE_CREATE: VIDEO_SUBTITLE_ENABLED,
        VIDEO_SUBTITLE_MODE_TRANSLATE: VIDEO_TRANSLATE_SUBTITLE_ENABLED,
        VIDEO_SUBTITLE_MODE_DUB: VIDEO_DUB_ENABLED,
        VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB: VIDEO_SUBTITLE_PLUS_DUB_ENABLED,
    }.get(normalize_video_translate_mode(mode), False)

SUBDUB_PUBLIC_OVERRIDE_PREFIX = "subdub_public_override"
SUBDUB_FINAL_CONFIRM_STATE_KEY = "subdub_final_confirmed"
SUBDUB_FINAL_CONFIRM_SOURCE = "videodub|final"


def subdub_final_confirmed_state(state: dict | None = None) -> bool:
    """Return whether this state was admitted through the final SubDub edge."""
    value = (state or {}).get(SUBDUB_FINAL_CONFIRM_STATE_KEY)
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "on"}
    return bool(value)


def subdub_public_override_value(name: str) -> str:
    """Persisted runtime override for SubDub public go-live switches.

    Values: "true" / "false" force the switch; "" (absent) falls back to the
    Railway ENV default. Stored in system_settings so it survives restarts
    and needs no redeploy. Scoped to SubDub public readiness only.
    """
    return str(get_system_setting(f"{SUBDUB_PUBLIC_OVERRIDE_PREFIX}:{name}", "") or "").strip().lower()


def subdub_set_public_override(name: str, value: str, updated_by="") -> None:
    set_system_setting(
        f"{SUBDUB_PUBLIC_OVERRIDE_PREFIX}:{name}",
        str(value or "").strip().lower(),
        "subdub_public_open_safe",
        updated_by,
    )


def subdub_public_flag_with_override(env_name: str, env_value) -> bool:
    override = subdub_public_override_value(env_name)
    if override in {"true", "false"}:
        return override == "true"
    return bool(env_value)


def subdub_public_freeze_override_active() -> bool:
    return subdub_public_override_value("PROVIDER_FREEZE") == "false"


def subdub_public_force_override_active() -> bool:
    return subdub_public_override_value("PUBLIC_FORCE") == "true"


def subdub_explicit_provider_selection() -> dict:
    raw_asr = str(ASR_PROVIDER or "").strip().lower()
    raw_translation = str(TRANSLATE_PROVIDER or "").strip().lower()
    raw_tts = str(TTS_PROVIDER or "").strip().lower()
    asr = subdub_asr_provider_name()
    translation = subdub_translation_provider_name()
    tts = subdub_tts_provider_name()
    invalid = []
    if raw_asr in {"", "auto"} or asr not in {"deepgram", "key4u", "shopaikey"}:
        invalid.append("ASR_PROVIDER")
    if raw_translation in {"", "auto"} or translation not in {"deepl", "key4u", "shopaikey"}:
        invalid.append("TRANSLATE_PROVIDER")
    if raw_tts in {"", "auto"} or tts not in {"direct_minimax", "key4u_minimax", "shopaikey_minimax"}:
        invalid.append("TTS_PROVIDER")
    return {
        "asr": asr,
        "translation": translation,
        "tts": tts,
        "invalid": invalid,
        "all_explicit": not invalid,
    }


def subdub_public_state_debug_text() -> str:
    selectors = subdub_explicit_provider_selection()
    labels = {
        "subtitle_create": "subtitle",
        "subtitle_translate": "translation",
        "dub": "dubbing",
        "subtitle_plus_dub": "combo",
    }
    lines = [
        "SUBDUB PUBLIC STATE",
        f"asr_provider={selectors['asr'] or '-'}",
        f"translation_provider={selectors['translation'] or '-'}",
        f"tts_provider={selectors['tts'] or '-'}",
        f"provider_auto_executable={'NO' if selectors['all_explicit'] else 'YES'}",
        f"provider_freeze={'OFF' if subdub_public_freeze_override_active() or not (PROVIDER_FREEZE or PROVIDER_FREEZE_ENABLED) else 'ON'}",
        f"smoke_hard_lock={'OFF' if subdub_public_force_override_active() else 'ON'}",
        f"automatic_paid_fallback={'ON' if PROVIDER_FALLBACK_ENABLED else 'OFF'}",
        "background_product_execution=OFF",
    ]
    for mode, label in labels.items():
        readiness = get_subdub_lane_readiness(mode, {}, public=True)
        lines.append(
            f"{label}={'ON' if readiness.get('public_flag_enabled') else 'OFF'}"
            f" | ready={'YES' if readiness.get('effective_ready') else 'NO'}"
            f" | smoke={readiness.get('asr_smoke_status') or 'NOT_TESTED'}"
            f" | blockers={','.join(readiness.get('blockers') or []) or '-'}"
        )
    return "\n".join(lines)


def video_dubbing_public_flag(mode: str) -> bool:
    mode = normalize_video_translate_mode(mode)
    entry = {
        VIDEO_SUBTITLE_MODE_CREATE: ("VIDEO_SUBTITLE_PUBLIC_ENABLED", VIDEO_SUBTITLE_PUBLIC_ENABLED),
        VIDEO_SUBTITLE_MODE_TRANSLATE: ("VIDEO_TRANSLATE_SUBTITLE_PUBLIC_ENABLED", VIDEO_TRANSLATE_SUBTITLE_PUBLIC_ENABLED),
        VIDEO_SUBTITLE_MODE_DUB: ("VIDEO_DUB_PUBLIC_ENABLED", VIDEO_DUB_PUBLIC_ENABLED),
        VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB: ("VIDEO_SUBTITLE_PLUS_DUB_PUBLIC_ENABLED", VIDEO_SUBTITLE_PLUS_DUB_PUBLIC_ENABLED),
    }.get(mode)
    if not entry:
        return False
    return subdub_public_flag_with_override(entry[0], entry[1])

def video_dubbing_effective_mode_enabled(mode: str, public: bool = True) -> bool:
    mode = normalize_video_translate_mode(mode)
    if TRANSLATION_DUB_MAINTENANCE:
        return False
    if public and mode in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}:
        return bool(video_dubbing_public_flag(mode))
    configured_flag = video_dubbing_public_flag(mode) if public else video_dubbing_mode_flag(mode)
    if configured_flag:
        return True
    return bool(video_dubbing_configured_readiness(mode, {}, public=public).get("ok"))

def video_translation_provider_available() -> bool:
    return bool(
        DEEPL_API_KEY
        or key4u_subtitle_translation_public_ready()
        or gemini_client
        or openai_client
        or shopaikey_subtitle_translation_public_ready()
    )

def video_translation_provider_configured() -> bool:
    return bool(
        DEEPL_API_KEY
        or key4u_subtitle_translation_configured()
        or gemini_client
        or openai_client
        or shopaikey_public_chat_fallback_enabled()
    )

def active_translation_provider_label() -> str:
    if DEEPL_API_KEY:
        return "deepl"
    if key4u_subtitle_translation_public_ready():
        return "key4u_qwen_mt"
    if gemini_client:
        return "gemini"
    if openai_client:
        return "openai"
    if shopaikey_subtitle_translation_public_ready():
        return "shopaikey_chat"
    return "missing"

def video_tts_provider_available_for(public: bool = True) -> bool:
    provider = str(TTS_PROVIDER or "auto").lower()
    if public:
        minimax_ready = bool(
            key4u_minimax_tts_public_ready()
            or shopaikey_minimax_tts_public_ready()
            or direct_minimax_tts_public_ready()
        )
        shopaikey_ready = shopaikey_tts_fallback_public_ready()
    else:
        tts_smoke = preferred_tool_test_status_text("video_dub", "minimax_tts", "minimax_tts_key4u", "minimax_tts_shopaikey", "shopaikey_tts", "tts")
        minimax_ready = bool(
            provider_status_is_pass(tts_smoke)
            and (
                key4u_minimax_tts_configured(require_public=False)
                or shopaikey_minimax_tts_configured()
                or direct_minimax_tts_configured()
            )
        )
        shopaikey_ready = bool(
            provider_status_is_pass(tts_smoke)
            and SHOPAIKEY_ENABLED
            and SHOPAIKEY_TTS_ENABLED
            and SHOPAIKEY_API_KEY
            and (SHOPAIKEY_DUBBING_TTS_ENDPOINT or SHOPAIKEY_TTS_ENDPOINT)
        )
    if provider in {"minimax", "shopaikey_minimax", "minimax_voice"}:
        return minimax_ready
    if provider in {"shopaikey", "shopai"}:
        return shopaikey_ready
    if provider == "elevenlabs":
        return bool(ELEVENLABS_API_KEY)
    if provider in {"fish", "fish_audio"}:
        return bool(FISH_AUDIO_KEY)
    if provider in {"edge", "edge_tts"}:
        return bool(edge_tts)
    return bool(minimax_ready or shopaikey_ready or ELEVENLABS_API_KEY or FISH_AUDIO_KEY or edge_tts)

def video_tts_provider_available() -> bool:
    return video_tts_provider_available_for(public=True)

def video_tts_provider_configured_for_dub() -> bool:
    provider = str(TTS_PROVIDER or "auto").lower()
    minimax_configured = bool(
        key4u_minimax_tts_configured(require_public=False)
        or shopaikey_minimax_tts_configured()
        or direct_minimax_tts_configured()
    )
    shopaikey_configured = bool(
        SHOPAIKEY_ENABLED
        and SHOPAIKEY_TTS_ENABLED
        and SHOPAIKEY_API_KEY
        and (SHOPAIKEY_DUBBING_TTS_ENDPOINT or SHOPAIKEY_TTS_ENDPOINT)
    )
    if provider in {"minimax", "shopaikey_minimax", "minimax_voice"}:
        return minimax_configured
    if provider in {"shopaikey", "shopai"}:
        return shopaikey_configured
    if provider == "elevenlabs":
        return bool(ELEVENLABS_API_KEY)
    if provider in {"fish", "fish_audio"}:
        return bool(FISH_AUDIO_KEY)
    if provider in {"edge", "edge_tts"}:
        return bool(edge_tts)
    return bool(minimax_configured or shopaikey_configured or ELEVENLABS_API_KEY or FISH_AUDIO_KEY or edge_tts)

def video_dubbing_mode_needs_asr_provider(mode: str, state: dict | None = None) -> bool:
    mode = normalize_video_translate_mode(mode)
    state = dict(state or {})
    if video_dubbing_state_has_subtitle_or_transcript(state):
        return False
    return video_dubbing_state_requires_asr(mode, state)

def video_dubbing_needs_translation_provider(mode: str, state: dict | None = None) -> bool:
    mode = normalize_video_translate_mode(mode)
    state = dict(state or {})
    target = str(state.get("target_language") or "").strip().lower()
    keep_original = target in {"", "same", "giữ nguyên ngôn ngữ gốc", "giu nguyen ngon ngu goc"}
    if mode == VIDEO_SUBTITLE_MODE_TRANSLATE:
        return True
    return bool(
        mode in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}
        and str(state.get("translate_requested") or "0") == "1"
        and not keep_original
    )

def subdub_effective_freeze_status(mode: str) -> dict:
    mode = normalize_video_translate_mode(mode)
    global_freeze = bool(PROVIDER_FREEZE or PROVIDER_FREEZE_ENABLED)
    subdub_freeze = bool(TRANSLATION_DUB_MAINTENANCE)
    return {
        "mode": mode,
        "global_provider_freeze": global_freeze,
        "subdub_freeze": subdub_freeze,
        "effective_frozen": bool(global_freeze or subdub_freeze),
        "reason": "provider_freeze" if global_freeze else ("subdub_maintenance" if subdub_freeze else "ready"),
    }

def subdub_provider_smoke_result(kind: str, provider: str) -> dict:
    kind = str(kind or "").strip().lower()
    provider = str(provider or "").strip().lower()
    fallback_keys = {
        ("asr", "deepgram"): ("asr", "stt"),
        ("asr", "key4u"): ("key4u_stt", "asr", "stt"),
        ("asr", "shopaikey"): ("shopaikey_stt", "asr_shopaikey", "asr", "stt"),
        ("translation", "deepl"): ("translation:deepl", "translation"),
        ("translation", "key4u"): ("key4u_translation", "translation"),
        ("translation", "shopaikey"): ("shopaikey_chat", "translation"),
        ("tts", "direct_minimax"): ("minimax_tts_direct", "minimax_tts", "tts"),
        ("tts", "key4u_minimax"): ("minimax_tts_key4u", "minimax_tts", "tts"),
        ("tts", "shopaikey_minimax"): ("minimax_tts_shopaikey", "minimax_tts", "tts"),
    }
    keys = (f"{kind}:{provider}",) + tuple(fallback_keys.get((kind, provider), ()))
    selected = {"status": "NOT_TESTED", "tested_at": "", "detail": ""}
    for key in keys:
        current = dict(get_tool_test_result(key) or {})
        if provider_status_base(current.get("status")) not in {"", "NOT_TESTED"}:
            selected = current
            break
    status = provider_status_base(selected.get("status"))
    detail = str(selected.get("detail") or "")
    runtime_sha = str(APP_BUILD_SHA or APP_BUILD or "").strip().lower()
    if provider_status_is_pass(status):
        match = re.search(r"runtime_sha=([a-z0-9._-]+)", detail.lower())
        smoke_sha = str(match.group(1) if match else "").strip().lower()
        if not runtime_sha or not smoke_sha or not (runtime_sha.startswith(smoke_sha) or smoke_sha.startswith(runtime_sha)):
            status = "STALE"
    return {
        "status": status or "NOT_TESTED",
        "tested_at": str(selected.get("tested_at") or ""),
        "detail": detail,
        "runtime_sha": runtime_sha,
    }

def save_subdub_provider_smoke(kind: str, provider: str, status: str, detail: str = "", updated_by="") -> dict:
    runtime_sha = str(APP_BUILD_SHA or APP_BUILD or "local").strip()
    safe_detail = sanitize_log_text(str(detail or ""))[:760]
    stamped_detail = f"runtime_sha={runtime_sha}; {safe_detail}".rstrip("; ")
    return save_tool_test_result(
        f"{str(kind or '').strip().lower()}:{str(provider or '').strip().lower()}",
        status,
        stamped_detail,
        updated_by,
    )

def subdub_asr_provider_name() -> str:
    provider = str(ASR_PROVIDER or "auto").strip().lower()
    return "shopaikey" if provider == "shopai" else provider

def subdub_tts_provider_name() -> str:
    provider = str(TTS_PROVIDER or "auto").strip().lower()
    aliases = {
        "key4u": "key4u_minimax",
        "shopai": "shopaikey_minimax",
        "shopaikey": "shopaikey_minimax",
    }
    return aliases.get(provider, provider)

def subdub_provider_configured(kind: str, provider: str) -> bool:
    if kind == "asr":
        return {
            "deepgram": bool(DEEPGRAM_API_KEY),
            "key4u": bool(key4u_asr_configured()),
            "shopaikey": bool(SHOPAIKEY_API_KEY and SHOPAIKEY_AUDIO_TRANSCRIPTION_ENDPOINT),
        }.get(provider, False)
    if kind == "translation":
        return {
            "deepl": bool(DEEPL_API_KEY),
            "key4u": bool(key4u_subtitle_translation_configured()),
            "shopaikey": bool(shopaikey_public_chat_fallback_enabled()),
        }.get(provider, False)
    return {
        "direct_minimax": bool(MINIMAX_API_KEY and MINIMAX_GROUP_ID),
        "key4u_minimax": bool(key4u_minimax_tts_configured(require_public=False)),
        "shopaikey_minimax": bool(shopaikey_minimax_tts_configured()),
    }.get(provider, False)

def subdub_provider_public_allowed(kind: str, provider: str) -> bool:
    force_open = subdub_public_force_override_active()
    if kind == "asr":
        route_allowed = {
            "deepgram": True,
            "key4u": bool(KEY4U_PUBLIC_ENABLED or force_open),
            "shopaikey": bool(not SHOPAIKEY_ADMIN_ONLY or force_open),
        }.get(provider, False)
        return bool(subdub_public_flag_with_override("VIDEO_ASR_ENABLED", VIDEO_ASR_ENABLED) and route_allowed)
    if kind == "translation":
        return {
            "deepl": True,
            "key4u": bool(KEY4U_PUBLIC_ENABLED or force_open),
            "shopaikey": bool(not SHOPAIKEY_ADMIN_ONLY or force_open),
        }.get(provider, False)
    route_allowed = {
        "direct_minimax": True,
        "key4u_minimax": bool(KEY4U_PUBLIC_ENABLED or force_open),
        "shopaikey_minimax": bool(not SHOPAIKEY_ADMIN_ONLY or force_open),
    }.get(provider, False)
    return bool(subdub_public_flag_with_override("VIDEO_DUB_TTS_ENABLED", VIDEO_DUB_TTS_ENABLED) and route_allowed)

def get_subdub_lane_readiness(
    mode: str,
    state: dict | None = None,
    *,
    public: bool,
    admin_smoke: bool = False,
    admin_interactive_confirm: bool = False,
    confirmed_product: bool = False,
) -> dict:
    mode = normalize_video_translate_mode(mode)
    state = dict(state or {})
    confirmed_product = bool(confirmed_product or subdub_final_confirmed_state(state))
    force_open = bool(public and subdub_public_force_override_active())
    admin_interactive_confirm = bool(admin_interactive_confirm and not public)
    if admin_interactive_confirm:
        admin_smoke = True
    freeze = subdub_effective_freeze_status(mode)
    runtime = dict(subdub_runtime_status_payload() or {})
    ffmpeg_ready = bool(runtime.get("ffmpeg_ready", runtime.get("ffmpeg_version_probe_ok", runtime.get("media_preprocessing_ready"))))
    ffprobe_ready = bool(runtime.get("ffprobe_ready", runtime.get("ffprobe_version_probe_ok", runtime.get("media_preprocessing_ready"))))
    subtitle_render_ready = bool(runtime.get("subtitle_rendering_ready", runtime.get("subtitle_render_ready", runtime.get("media_preprocessing_ready"))))
    subtitle_output = mode in {
        VIDEO_SUBTITLE_MODE_CREATE,
        VIDEO_SUBTITLE_MODE_TRANSLATE,
        VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
    }
    media_runtime_ready = bool(ffmpeg_ready and ffprobe_ready and (subtitle_render_ready or not subtitle_output))
    asr_state_known = bool(
        video_dubbing_state_has_subtitle_or_transcript(state)
        or any(
            str(state.get(key) or "").strip()
            for key in ("source_file_name", "source_mime_type", "mime_type", "media_kind", "source_media_kind")
        )
    )
    if asr_state_known:
        asr_required = bool(mode and video_dubbing_mode_needs_asr_provider(mode, state))
    else:
        # Lane-level probe (no customer input yet): assume the worst-case job for this
        # lane — raw media with no subtitle/transcript attached — so ASR readiness
        # (explicit provider + configured + smoke PASS on current SHA) cannot be
        # skipped just because the probe state is empty. A lane must not open on an
        # unverified ASR chain.
        asr_required = bool(mode and video_dubbing_state_requires_asr(mode, {"media_kind": "video"}))
    translation_required = bool(mode and video_dubbing_needs_translation_provider(mode, state))
    tts_required = mode in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}
    asr_provider = subdub_asr_provider_name()
    translation_provider = subdub_translation_provider_name()
    tts_provider = subdub_tts_provider_name()
    asr_configured = subdub_provider_configured("asr", asr_provider)
    translation_configured = subdub_provider_configured("translation", translation_provider)
    tts_configured = subdub_provider_configured("tts", tts_provider)
    asr_smoke_status = subdub_provider_smoke_result("asr", asr_provider).get("status") or "NOT_TESTED"
    translation_smoke_status = subdub_provider_smoke_result("translation", translation_provider).get("status") or "NOT_TESTED"
    tts_smoke_status = subdub_provider_smoke_result("tts", tts_provider).get("status") or "NOT_TESTED"
    asr_public_allowed = subdub_provider_public_allowed("asr", asr_provider)
    translation_public_allowed = subdub_provider_public_allowed("translation", translation_provider)
    tts_public_allowed = subdub_provider_public_allowed("tts", tts_provider)
    blockers: list[str] = []
    if not mode:
        blockers.append("mode_missing")
    if public and not video_dubbing_public_flag(mode) and not confirmed_product:
        blockers.append("public_flag_off")
    if (
        freeze.get("global_provider_freeze")
        and not admin_interactive_confirm
        and not confirmed_product
        and not subdub_public_freeze_override_active()
    ):
        blockers.append("provider_freeze")
    if TRANSLATION_DUB_MAINTENANCE:
        blockers.append("maintenance")
    if not media_runtime_ready:
        blockers.append("media_runtime_not_ready")
    if asr_required:
        if asr_provider not in {"deepgram", "key4u", "shopaikey"}:
            blockers.append("asr_provider_policy_required")
        elif not asr_configured:
            blockers.append("asr_not_configured")
        elif public and not asr_public_allowed and not confirmed_product:
            blockers.append("asr_public_not_allowed")
        elif not admin_smoke and not force_open and not confirmed_product and not provider_status_is_pass(asr_smoke_status):
            blockers.append("asr_smoke_not_pass")
    if translation_required:
        if translation_provider not in {"deepl", "key4u", "shopaikey"}:
            blockers.append("translation_provider_policy_required")
        elif not translation_configured:
            blockers.append("translation_not_configured")
        elif public and not translation_public_allowed and not confirmed_product:
            blockers.append("translation_public_not_allowed")
        elif not admin_smoke and not force_open and not confirmed_product and not provider_status_is_pass(translation_smoke_status):
            blockers.append("translation_smoke_not_pass")
    if tts_required:
        if tts_provider not in {"direct_minimax", "key4u_minimax", "shopaikey_minimax"}:
            blockers.append("tts_provider_policy_required")
        elif not tts_configured:
            blockers.append("tts_not_configured")
        elif public and not tts_public_allowed and not confirmed_product:
            blockers.append("tts_public_not_allowed")
        elif not admin_smoke and not force_open and not confirmed_product and not provider_status_is_pass(tts_smoke_status):
            blockers.append("tts_smoke_not_pass")
    blockers = list(dict.fromkeys(blockers))
    return {
        "mode": mode,
        "public_flag_enabled": bool(video_dubbing_public_flag(mode)),
        "maintenance_enabled": bool(TRANSLATION_DUB_MAINTENANCE),
        "global_provider_freeze": bool(freeze.get("global_provider_freeze")),
        "subdub_freeze": bool(freeze.get("subdub_freeze")),
        "media_runtime_ready": media_runtime_ready,
        "asr_required": asr_required,
        "asr_provider": asr_provider,
        "asr_configured": asr_configured,
        "asr_smoke_status": asr_smoke_status,
        "asr_public_allowed": asr_public_allowed,
        "translation_required": translation_required,
        "translation_provider": translation_provider,
        "translation_configured": translation_configured,
        "translation_smoke_status": translation_smoke_status,
        "translation_public_allowed": translation_public_allowed,
        "tts_required": tts_required,
        "tts_provider": tts_provider,
        "tts_configured": tts_configured,
        "tts_smoke_status": tts_smoke_status,
        "public_force_open": force_open,
        "confirmed_product": confirmed_product,
        "smoke_hard_lock": not (force_open or confirmed_product),
        "tts_public_allowed": tts_public_allowed,
        "effective_ready": not blockers,
        "blockers": blockers,
        "public_reason": "ready" if not blockers else "subdub_temporarily_unavailable",
        "admin_reason": "ready" if not blockers else ",".join(blockers),
    }

def video_dubbing_configured_readiness(
    mode: str,
    state: dict | None = None,
    public: bool = True,
    asr_readiness: dict | None = None,
    admin_interactive_confirm: bool = False,
    confirmed_product: bool = False,
) -> dict:
    mode = normalize_video_translate_mode(mode)
    state = dict(state or {})
    confirmed_product = bool(confirmed_product or subdub_final_confirmed_state(state))
    del asr_readiness
    readiness = get_subdub_lane_readiness(
        mode,
        state,
        public=public,
        admin_smoke=bool(state.get("admin_real_test") or state.get("admin_smoke")),
        admin_interactive_confirm=admin_interactive_confirm,
        confirmed_product=confirmed_product,
    )
    blockers = list(readiness.get("blockers") or [])
    missing: list[str] = []
    category_tokens = (
        ("mode", "mode"),
        ("maintenance", "maintenance"),
        ("provider_freeze", "lane_closed"),
        ("public_flag", "lane_closed"),
        ("media_runtime", "ffmpeg"),
        ("smoke_not_pass", "lane_closed"),
        ("public_not_allowed", "lane_closed"),
        ("provider_policy_required", "lane_closed"),
        ("asr_", "asr"),
        ("translation_", "translation"),
        ("tts_", "tts"),
    )
    for blocker in blockers:
        category = next((name for token, name in category_tokens if token in blocker), blocker)
        if category not in missing:
            missing.append(category)
    return {
        "ok": not missing,
        "reason": "ready" if not missing else f"missing_{missing[0]}",
        "missing": missing,
        "maintenance": bool(TRANSLATION_DUB_MAINTENANCE),
        "public": bool(public),
        "canonical_readiness": readiness,
    }

def video_dubbing_capability(mode: str, state: dict | None = None, public: bool = True, *, confirmed_product: bool = False) -> dict:
    mode = normalize_video_translate_mode(mode)
    state = state or {}
    confirmed_product = bool(confirmed_product or subdub_final_confirmed_state(state))
    if not mode:
        return {"ok": False, "reason": "invalid_mode", "missing": ["mode"]}
    readiness = get_subdub_lane_readiness(
        mode,
        state,
        public=public,
        admin_smoke=bool((state or {}).get("admin_real_test") or (state or {}).get("admin_smoke")),
        confirmed_product=confirmed_product,
    )
    missing = list(readiness.get("blockers") or [])
    return {
        "ok": bool(readiness.get("effective_ready")),
        "reason": "ready" if not missing else missing[0],
        "missing": missing,
        "asr": str(readiness.get("asr_provider") or ""),
        "translation": str(readiness.get("translation_provider") or ""),
        "tts": str(readiness.get("tts_provider") or ""),
        "mux": "enabled" if video_dubbing_mux_ready() else "not_enabled_audio_output_only",
        "readiness": readiness,
    }

def video_translation_admin_blockers(mode: str, state: dict | None = None, public: bool = True) -> list[str]:
    mode = normalize_video_translate_mode(mode)
    state = dict(state or {})
    blockers = []
    if TRANSLATION_DUB_MAINTENANCE:
        blockers.append("TRANSLATION_DUB_MAINTENANCE")
    if video_dubbing_mode_needs_asr_provider(mode, state) and not get_asr_adapter_readiness(public=False).get("configured"):
        blockers.append("ASR provider missing")
    if video_dubbing_needs_translation_provider(mode, state) and not video_translation_provider_configured():
        blockers.append("Subtitle translation provider missing")
    if mode in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}:
        if not video_tts_provider_configured_for_dub():
            blockers.append("TTS/default voice missing")
    return list(dict.fromkeys(blockers))

def video_pipeline_status_payload() -> dict:
    worker = local_worker_status_payload()
    mux_worker_ready = bool(worker.get("connected") and worker.get("ffmpeg_path"))
    mux_ready = video_dubbing_mux_ready()
    subtitle_render_ready = video_dubbing_subtitle_render_ready()
    asr_readiness = get_asr_adapter_readiness(public=True)
    selected_asr = subdub_asr_provider_name()
    selected_translation = subdub_translation_provider_name()
    selected_tts = subdub_tts_provider_name()
    return {
        "execution_owner": "railway_local",
        "external_worker_required": False,
        "external_worker_connection": "N/A",
        "asr_provider": selected_asr or "policy_required",
        "asr_test": str(subdub_provider_smoke_result("asr", selected_asr).get("status") or "NOT_TESTED"),
        "asr_readiness": "READY" if asr_readiness.get("public_ready") else ("CONFIGURED" if asr_readiness.get("configured") else "MISSING"),
        "asr_configured": bool(asr_readiness.get("configured")),
        "asr_smoke_ready": bool(asr_readiness.get("smoke_ready")),
        "asr_public_ready": bool(asr_readiness.get("public_ready")),
        "asr_supports_audio": bool(asr_readiness.get("supports_audio")),
        "asr_supports_video": bool(asr_readiness.get("supports_video")),
        "translation_provider": selected_translation or "policy_required",
        "translation_test": str(subdub_provider_smoke_result("translation", selected_translation).get("status") or "NOT_TESTED"),
        "tts_provider": selected_tts or "policy_required",
        "tts_test": str(subdub_provider_smoke_result("tts", selected_tts).get("status") or "NOT_TESTED"),
        "ffmpeg_mux": "ready" if mux_ready else ("worker_ready_no_local_ffmpeg" if mux_worker_ready else "disabled"),
        "subtitle_burn_in": "ready" if subtitle_render_ready else ("worker_ready_no_local_ffmpeg" if mux_worker_ready else "disabled"),
        "local_worker_connected": bool(worker.get("connected")),
        "subtitle_test": preferred_tool_test_status_text("video_subtitle"),
        "dub_test": preferred_tool_test_status_text("video_dub"),
        "subtitle_dub_test": preferred_tool_test_status_text("subtitle_plus_dub"),
    }

