def subdub_canonical_mode(mode: str = "", state: dict | None = None) -> str:
    state = dict(state or {})
    normalized = normalize_video_translate_mode(
        mode
        or state.get("video_processing_mode")
        or state.get("mode")
        or state.get("process_type")
        or state.get("requested_mode")
    )
    if normalized == VIDEO_SUBTITLE_MODE_DUB:
        return SUBDUB_CANONICAL_MODE_DUB
    if normalized == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB:
        return SUBDUB_CANONICAL_MODE_SUBTITLE_DUB
    if normalized == VIDEO_SUBTITLE_MODE_CREATE:
        return SUBDUB_CANONICAL_MODE_AUTO_SUBTITLE
    return SUBDUB_CANONICAL_MODE_SUBTITLE_TRANSLATE

def subdub_mode_expected_steps(mode: str = "", state: dict | None = None) -> list[str]:
    canonical = subdub_canonical_mode(mode, state)
    return [
        str(SUBDUB_PROGRESS_STAGES.get(token, ("", token, ""))[1])
        for token in SUBDUB_CANONICAL_MODE_STAGE_TOKENS.get(canonical, ())
    ]

def subdub_progress_stage_tokens_for_product(product_type_or_mode: str = "", state: dict | None = None) -> tuple[str, ...]:
    token = str(product_type_or_mode or "").strip()
    if token in VIDEO_SUBTITLE_MODES or any(
        str((state or {}).get(key) or "").strip()
        for key in ("mode", "video_processing_mode", "process_type", "requested_mode")
    ):
        canonical = subdub_canonical_mode(token, state)
        return tuple(SUBDUB_CANONICAL_MODE_STAGE_TOKENS.get(canonical) or ())
    product_type = subdub_product_type_from_mode(product_type_or_mode, state)
    return tuple(SUBDUB_PRODUCT_PROGRESS_STAGE_TOKENS.get(product_type) or SUBDUB_PRODUCT_PROGRESS_STAGE_TOKENS[SUBDUB_PRODUCT_TYPE_SUBTITLE_DUB])

def subdub_progress_steps_for_product(product_type_or_mode: str = "", state: dict | None = None) -> list[dict]:
    product_type = subdub_product_type_from_mode(product_type_or_mode, state)
    canonical = subdub_canonical_mode(product_type_or_mode, state) if str(product_type_or_mode or "") in VIDEO_SUBTITLE_MODES or state else ""
    return [
        {**subdub_progress_stage_payload(token), "product_type": product_type, "canonical_mode": canonical}
        for token in subdub_progress_stage_tokens_for_product(product_type_or_mode, state)
    ]

def subdub_public_job_code(job_id: str = "") -> str:
    return product_progress_status.product_progress_public_job_code(job_id)

def subdub_public_code_value(job_id: str = "") -> str:
    return product_progress_status.product_progress_public_job_code(job_id).lstrip("#").upper()

def subdub_existing_public_code(job: dict | None = None) -> str:
    current = dict(job or {})
    for key in ("public_code", "subdub_public_job_id", "progress_public_code", "public_job_id"):
        value = str(current.get(key) or "").strip()
        if value:
            return value.lstrip("#").upper()
    return ""

def subdub_identity_fields(job: dict | None = None, *, job_key: str = "", mode: str = "", state: dict | None = None) -> dict:
    current = dict(job or {})
    state = {**dict(state or {}), **current}
    normalized_mode = normalize_video_translate_mode(
        mode
        or current.get("mode")
        or current.get("video_processing_mode")
        or current.get("process_type")
        or state.get("mode")
        or state.get("video_processing_mode")
        or state.get("process_type")
    )
    internal_job_id = str(
        current.get("internal_job_id")
        or current.get("job_id")
        or current.get("registry_job_id")
        or ""
    ).strip()
    visible_job_id = str(current.get("job_id") or current.get("registry_job_id") or internal_job_id or "").strip()
    public_code = subdub_existing_public_code(current) or subdub_public_code_value(visible_job_id or internal_job_id)
    product_type = subdub_product_type_from_mode(normalized_mode, state)
    mapped_mode = normalized_mode or str(current.get("mode") or state.get("mode") or "").strip()
    return {
        "feature": "subtitle_dub",
        "internal_job_id": internal_job_id,
        "job_id": visible_job_id or internal_job_id,
        "job_key": str(job_key or current.get("job_key") or ""),
        "public_code": public_code,
        "public_job_id": public_code,
        "subdub_public_job_id": public_code,
        "progress_public_code": f"#{public_code}" if public_code else "",
        "product_type": product_type,
        "mapped_product_type": product_type,
        "mapped_mode": mapped_mode,
        "mode": mapped_mode,
    }

def subdub_enrich_job_identity(job: dict | None = None, *, job_key: str = "", mode: str = "", state: dict | None = None) -> dict:
    current = dict(job or {})
    identity = subdub_identity_fields(current, job_key=job_key, mode=mode, state=state)
    for key, value in identity.items():
        if key in {"internal_job_id", "job_id", "mode", "product_type"} and current.get(key):
            continue
        current[key] = value
    for key in ("mapped_product_type", "mapped_mode", "public_code", "public_job_id", "subdub_public_job_id", "progress_public_code", "feature"):
        if identity.get(key):
            current[key] = identity[key]
    checked = list(current.get("lookup_stores_checked") or [])
    current["lookup_stores_checked"] = checked
    return subdub_normalize_input_save_failed_terminal(current)

def subdub_progress_stage_payload(stage: str = "") -> dict:
    token = str(stage or "saved_input").strip().lower()
    percent, label, status = SUBDUB_PROGRESS_STAGES.get(token, SUBDUB_PROGRESS_STAGES["saved_input"])
    return {"stage": token, "percent": percent, "label": label, "status": status}

def subdub_progress_text(stage: str = "saved_input", job_id: str = "", lang: str = "vi") -> str:
    copy = public_subdub_deep_copy(normalize_user_language(lang))
    payload = subdub_progress_stage_payload(stage)
    text = product_progress_status_text(
        "subdub",
        job_id,
        str(payload.get("stage") or stage or "received_file"),
        int(payload.get("percent") or 0),
        "delivered" if str(payload.get("stage") or "") == "delivered" else "",
        lang=lang,
    )
    heading = copy["success"] if str(payload.get("stage") or "").strip().lower() == "delivered" else copy["progress"]
    return f"{heading} · {int(payload.get('percent') or 0)}%\n{copy['job']}: <code>{html.escape(str(job_id or '-'))}</code>"
def subdub_progress_keyboard(job_id: str = "", lang: str = "vi") -> InlineKeyboardMarkup:
    copy = public_subdub_deep_copy(normalize_user_language(lang))
    safe_job = re.sub(r"[^A-Za-z0-9_.:-]+", "", str(job_id or ""))[:40]
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton(copy["update"], callback_data=f"videodub|subdub_status|{safe_job}"),
            InlineKeyboardButton(copy["another"], callback_data="videodub|source_upload"),
        ],
        [
            InlineKeyboardButton(f"⬅️ {copy['combo']}", callback_data="videodub|status_back_type"),
            InlineKeyboardButton(copy["main"], callback_data="menu|main"),
        ],
    ])

