def subdub_success_cost_line(charged_xu: int | float | str = 0, lang: str = "vi") -> str:
    try:
        charged = int(float(charged_xu or 0))
    except Exception:
        charged = 0
    if normalize_user_language(lang) != "vi":
        return f"Cost: <b>{charged} Xu</b>"
    return f"Chi phí: <b>{charged} Xu</b>"

def subdub_public_outcome_allows_success(job: dict | None = None) -> bool:
    current = dict(job or {})
    if not current:
        return True
    if str(current.get("terminal_public_outcome_type") or "").strip().lower() == "partial_audio_delivered":
        return False
    if subdub_job_has_failure_public_outcome(current):
        return False
    return True

def subdub_record_duplicate_terminal(job_key: str, job: dict, *, outcome: str, reason: str = "") -> dict:
    current = dict(job or {})
    if outcome == "success":
        current["duplicate_success_prevented"] = True
        current["duplicate_success_prevented_count"] = int(current.get("duplicate_success_prevented_count") or 0) + 1
    elif outcome == "failure":
        current["duplicate_error_prevented"] = True
        current["duplicate_error_prevented_count"] = int(current.get("duplicate_error_prevented_count") or current.get("duplicate_fail_prevented_count") or 0) + 1
    if reason:
        current["last_duplicate_terminal_reason"] = str(reason or "")[:160]
    current["updated_at"] = time.time()
    if job_key:
        SUBTITLE_DUB_PIPELINE_JOBS[str(job_key)] = current
    return current

def subdub_begin_delivery_once(job_key: str) -> bool:
    key = str(job_key or "")
    if not key:
        return True
    job = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(key) or {})
    if not job:
        return True
    if subdub_terminal_blocks_late_delivery(job):
        job["duplicate_success_prevented_count"] = int(job.get("duplicate_success_prevented_count") or 0) + 1
        job["duplicate_delivery_prevented"] = True
        job["updated_at"] = time.time()
        SUBTITLE_DUB_PIPELINE_JOBS[key] = job
        return False
    if job.get("subdub_delivery_started_at"):
        job["duplicate_delivery_prevented_count"] = int(job.get("duplicate_delivery_prevented_count") or 0) + 1
        job["duplicate_delivery_prevented"] = True
        job["updated_at"] = time.time()
        SUBTITLE_DUB_PIPELINE_JOBS[key] = job
        return False
    job["subdub_delivery_started_at"] = time.time()
    job["delivery_attempt_count"] = int(job.get("delivery_attempt_count") or 0) + 1
    job["delivery_attempted"] = True
    job["lifecycle_state"] = "delivering"
    job["current_stage"] = "delivering"
    job["progress_stage"] = "delivering"
    job["progress_percent"] = subdub_progress_percent_for_lifecycle("delivering")
    job["completed_steps"] = subdub_completed_steps_for_lifecycle("delivering")
    job["updated_at"] = time.time()
    SUBTITLE_DUB_PIPELINE_JOBS[key] = job
    return True

async def send_subdub_fail_once(
    message,
    job_key: str,
    *,
    mode: str = "",
    reason: str = "",
    lang: str = "vi",
    reply_markup=None,
    terminalize_active: bool = False,
) -> dict:
    key = str(job_key or "")
    job = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(key) or {})
    safe_mode = normalize_video_translate_mode(mode)
    reason_token = str(reason or "").strip().lower().replace("-", "_")
    terminalize_active = bool(
        terminalize_active
        or reason_token in {"validation_failed", "delivery_failed"}
    )
    if safe_mode in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}:
        user_from_key = key.split("|", 1)[0] if key else ""
        fallback_user_id = _safe_int(user_from_key, 0)
        if fallback_user_id:
            fallback_job = subtitle_dub_find_latest_dub_job_for_user_mode(fallback_user_id, safe_mode)
            if fallback_job and not job:
                job = dict(fallback_job)
                key = str(job.get("job_key") or key)
    if not terminalize_active and subdub_should_suppress_dub_generic_public_fail(safe_mode, reason, job):
        if key:
            current = dict(job or SUBTITLE_DUB_PIPELINE_JOBS.get(key) or {})
            current["job_key"] = str(current.get("job_key") or key)
            current["late_public_error_suppressed"] = True
            current["late_fail_suppressed"] = True
            current["generic_dub_fail_public_suppressed"] = True
            current["generic_fail_suppressed_while_active_or_delivered"] = True
            current["last_ignored_error_reason"] = str(reason or "")[:180]
            current["ignored_late_error_count"] = int(current.get("ignored_late_error_count") or 0) + 1
            current["public_failure_sent"] = False
            current["public_error_sent"] = False
            current["updated_at"] = time.time()
            SUBTITLE_DUB_PIPELINE_JOBS[key] = current
            persist_subtitle_dub_pipeline_job_snapshot(key, current, reason="generic_dub_video_fail_public_suppressed")
        return {"sent": False, "suppressed": True, "reason": "generic_dub_video_fail_public_suppressed"}
    if not terminalize_active and job and subdub_should_suppress_generic_fail_for_active_job(job, {"detail": reason}):
        job["ignored_late_error_count"] = int(job.get("ignored_late_error_count") or 0) + 1
        job["last_ignored_error_reason"] = str(reason or "")[:180]
        job["late_public_error_suppressed"] = True
        job["late_fail_suppressed"] = True
        job["generic_fail_suppressed_while_active_or_delivered"] = True
        job["delivered_success_wins_over_late_fail"] = bool(subdub_result_has_delivered_video(job) or subdub_job_video_delivery_succeeded(job))
        job["valid_output_wins_over_generic_fail"] = bool(subdub_should_suppress_late_public_failure(job))
        job["public_failure_sent"] = False
        job["public_error_sent"] = False
        job["updated_at"] = time.time()
        SUBTITLE_DUB_PIPELINE_JOBS[key] = job
        persist_subtitle_dub_pipeline_job_snapshot(key, job, reason="generic_fail_suppressed_active_or_delivered")
        return {"sent": False, "suppressed": True, "reason": "active_or_delivered_job"}
    if job and subdub_should_suppress_late_public_failure(job):
        job["ignored_late_error_count"] = int(job.get("ignored_late_error_count") or 0) + 1
        job["last_ignored_error_reason"] = str(reason or "")[:180]
        job["late_public_error_suppressed"] = True
        job["late_fail_suppressed"] = True
        job["duplicate_error_prevented"] = True
        job["error_sent_after_delivery"] = False
        job["delivery_succeeded"] = bool(job.get("delivery_succeeded") or subdub_job_video_delivery_succeeded(job))
        job["public_success_sent"] = bool(job.get("public_success_sent") or job.get("terminal_public_outcome_type") == "success")
        job["public_failure_sent"] = False
        job["public_error_sent"] = False
        job["suppress_reason"] = (
            "video_already_delivered"
            if subdub_job_video_delivery_succeeded(job)
            else "final_delivery_in_progress"
        )
        if job.get("terminal_public_outcome_type") == "success" or job.get("delivery_succeeded"):
            job["terminal_state"] = "delivered"
            job["status"] = "completed"
        job["updated_at"] = time.time()
        SUBTITLE_DUB_PIPELINE_JOBS[key] = job
        persist_subtitle_dub_pipeline_job_snapshot(key, job, reason="late_public_failure_suppressed")
        return {"sent": False, "suppressed": True, "reason": job["suppress_reason"]}
    if job and subdub_job_blocks_public_fail(job):
        job["ignored_late_error_count"] = int(job.get("ignored_late_error_count") or 0) + 1
        job["last_ignored_error_reason"] = str(reason or "")[:180]
        job["late_public_error_suppressed"] = True
        job["late_fail_suppressed"] = True
        job["duplicate_error_prevented"] = True
        job["error_sent_after_delivery"] = False
        job["updated_at"] = time.time()
        SUBTITLE_DUB_PIPELINE_JOBS[key] = job
        persist_subtitle_dub_pipeline_job_snapshot(key, job, reason="terminal_public_failure_suppressed")
        return {"sent": False, "suppressed": True, "reason": "terminal_delivered"}
    if job and subdub_job_has_failure_public_outcome(job):
        subdub_record_duplicate_terminal(key, job, outcome="failure", reason="failure_public_outcome_already_sent")
        return {"sent": False, "suppressed": True, "reason": "already_failed"}
    text = (
        subdub_media_runtime_unavailable_text(lang)
        if reason_token in {"ffmpeg_missing", "ffprobe_missing", "media_runtime_missing"}
        else subdub_mode_fail_text(mode, lang)
    )
    sent_msg = None
    message_id = ""
    terminal_panel_confirmed = False
    terminal_edit_method = ""
    terminal_edit_error = ""
    reply_target = getattr(message, "message", None)
    if reply_target is None and callable(getattr(message, "reply_text", None)):
        reply_target = message

    if callable(getattr(message, "edit_message_text", None)):
        try:
            sent_msg = await message.edit_message_text(
                text,
                parse_mode="HTML",
                reply_markup=reply_markup,
            )
            terminal_panel_confirmed = True
            terminal_edit_method = "status_panel_edit"
        except Exception as exc:
            if subdub_panel_edit_already_terminal(exc):
                terminal_panel_confirmed = True
                terminal_edit_method = "stored_message_already_terminal"
            else:
                terminal_edit_error = sanitize_log_text(type(exc).__name__)[:120]

    if not terminal_panel_confirmed and callable(getattr(reply_target, "reply_text", None)):
        try:
            sent_msg = await reply_target.reply_text(
                text,
                parse_mode="HTML",
                reply_markup=reply_markup,
            )
            terminal_panel_confirmed = True
            terminal_edit_method = "replacement_status_message"
            terminal_edit_error = ""
        except Exception as exc:
            terminal_edit_error = sanitize_log_text(type(exc).__name__)[:120]

    if not terminal_panel_confirmed:
        bot_client = getattr(message, "bot", None)
        if bot_client is None and reply_target is not None and callable(getattr(reply_target, "get_bot", None)):
            try:
                bot_client = reply_target.get_bot()
            except Exception:
                bot_client = None
        chat_id = getattr(reply_target, "chat_id", None) if reply_target is not None else None
        if bot_client is not None and chat_id is not None:
            try:
                sent_msg = await bot_client.send_message(
                    chat_id=chat_id,
                    text=text,
                    parse_mode="HTML",
                    reply_markup=reply_markup,
                )
                terminal_panel_confirmed = True
                terminal_edit_method = "replacement_bot_message"
                terminal_edit_error = ""
            except Exception as exc:
                terminal_edit_error = sanitize_log_text(type(exc).__name__)[:120]

    message_id = str(
        getattr(sent_msg, "message_id", "")
        or (
            getattr(reply_target, "message_id", "")
            if terminal_panel_confirmed and terminal_edit_method != "replacement_status_message"
            else ""
        )
        or (job.get("status_panel_message_id") if terminal_panel_confirmed else "")
        or ""
    )
    if key:
        input_save_fail = subdub_input_save_failure_detected(
            {
                **job,
                "pipeline_blocker": str(reason or ""),
                "input_save_blocker": str(reason or ""),
                "last_error_stage": "input_save" if str(reason or "").strip() in SUBDUB_INPUT_SAVE_FAILURE_BLOCKERS else job.get("last_error_stage"),
            }
        )
        last_truthful_stage = str(
            job.get("progress_stage")
            or job.get("current_stage")
            or job.get("lifecycle_state")
            or "received_file"
        )
        if subdub_canonical_lifecycle_state(last_truthful_stage) in SUBDUB_TERMINAL_STATES:
            last_truthful_stage = "received_file"
        fail_stage = "input_save_failed" if input_save_fail else last_truthful_stage
        fail_percent = subdub_progress_percent_for_lifecycle(fail_stage, "failed_no_charge")
        update_subtitle_dub_pipeline_job(
            key,
            status="failed",
            terminal_state="failed_no_charge",
            lifecycle_state=fail_stage,
            current_stage=fail_stage,
            progress_stage=fail_stage,
            progress_percent=fail_percent,
            completed_steps=subdub_completed_steps_for_lifecycle(fail_stage, "failed_no_charge"),
            public_error_sent=terminal_panel_confirmed,
            public_failure_sent=terminal_panel_confirmed,
            terminal_public_outcome_sent=terminal_panel_confirmed,
            terminal_public_outcome_type="failure" if terminal_panel_confirmed else "",
            terminal_public_outcome_message_id=message_id,
            public_error_sent_count=1 if terminal_panel_confirmed else 0,
            success_sent_count=0,
            duplicate_error_prevented=False,
            duplicate_success_prevented=False,
            late_fail_suppressed=False,
            error_sent_after_delivery=False,
            subdub_fail_message_id=message_id,
            pipeline_blocker=str(reason or "subdub_failed")[:180],
            charge_status="not_charged",
            no_charge_reason=str(reason or "subdub_failed")[:180],
            status_panel_terminalized=terminal_panel_confirmed,
            status_panel_terminal_edit_confirmed=terminal_panel_confirmed,
            status_panel_terminal_edit_failed=not terminal_panel_confirmed,
            status_panel_terminal_edit_error="" if terminal_panel_confirmed else (terminal_edit_error or "terminal_panel_send_failed"),
            status_panel_terminal_edit_method=terminal_edit_method,
            status_panel_replacement_sent=terminal_edit_method in {"replacement_status_message", "replacement_bot_message"},
            refresh_stopped_after_terminal=True,
            panel_finalized=terminal_panel_confirmed,
            panel_final_percent=fail_percent,
            panel_final_message_id=message_id if terminal_panel_confirmed else "",
            validation_started=bool(subdub_canonical_lifecycle_state(job.get("progress_stage") or "") == "validating_output"),
            validation_passed=False,
            delivery_started=bool(job.get("delivery_attempted")),
            delivery_success=False,
            charge_after_delivery=False,
            cost_line_rendered=False,
            success_cost_line="",
            cost_line_reason="failed_no_charge",
        )
    return {
        "sent": terminal_panel_confirmed,
        "suppressed": False,
        "reason": reason,
        "status_panel_terminal_edit_method": terminal_edit_method,
    }

def subtitle_dub_find_pipeline_job_for_user(user_id, job_id: str = "") -> dict:
    wanted = str(job_id or "").strip()
    candidates = []
    for job in SUBTITLE_DUB_PIPELINE_JOBS.values():
        item = dict(job or {})
        if str(item.get("user_id") or "") != str(user_id or "") and not is_admin_user(user_id):
            continue
        if wanted and wanted not in {str(item.get("job_id") or ""), str(item.get("internal_job_id") or "")}:
            continue
        candidates.append(item)
    candidates.sort(key=lambda item: float(item.get("updated_at") or item.get("started_at") or 0), reverse=True)
    return dict(candidates[0]) if candidates else {}

def subtitle_dub_find_latest_dub_job_for_user_mode(user_id, mode: str = "", state: dict | None = None) -> dict:
    safe_mode = normalize_video_translate_mode(mode)
    if safe_mode not in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}:
        return {}
    source_tokens = {
        str((state or {}).get(key) or "").strip()
        for key in ("source_file_unique_id", "video_file_unique_id", "source_file_id", "video_file_id")
    }
    source_tokens.discard("")

    def _visible(item: dict) -> bool:
        owner = str(item.get("user_id") or "").strip()
        if not owner or not user_id:
            return True
        try:
            if is_admin_user(user_id):
                return True
        except Exception:
            pass
        return owner == str(user_id)

    def _mode(item: dict) -> str:
        return normalize_video_translate_mode(
            item.get("mode")
            or item.get("mapped_mode")
            or item.get("video_processing_mode")
            or item.get("process_type")
            or item.get("requested_mode")
            or ""
        )

    def _source_score(item: dict) -> int:
        if not source_tokens:
            return 0
        haystack = " ".join(
            str(item.get(key) or "")
            for key in (
                "job_key",
                "source",
                "input_file_id",
                "source_file_id",
                "video_file_id",
                "source_file_unique_id",
                "video_file_unique_id",
            )
        )
        return 1 if any(token and token in haystack for token in source_tokens) else 0

    def _active_or_delivered_score(item: dict) -> int:
        if subdub_should_suppress_late_public_failure(item) or subdub_job_blocks_public_fail(item):
            return 3
        if subdub_should_suppress_generic_fail_for_active_job(item, {}):
            return 2
        terminal = str(item.get("terminal_state") or "").strip().lower()
        status = str(item.get("status") or "").strip().lower()
        if terminal.startswith("failed") or status.startswith("failed"):
            return 0
        progress = _safe_int(item.get("progress_percent") or item.get("panel_final_percent"), 0)
        return 1 if progress > 0 else 0

    candidates: list[dict] = []
    for raw in SUBTITLE_DUB_PIPELINE_JOBS.values():
        item = dict(raw or {})
        if _visible(item) and _mode(item) == safe_mode:
            candidates.append(item)
    try:
        for raw in list_engine_async_jobs("subtitle_dub", limit=120):
            item = subdub_merge_debug_job(raw or {})
            if _visible(item) and _mode(item) == safe_mode:
                candidates.append(item)
    except Exception:
        pass
    if not candidates:
        return {}
    candidates.sort(
        key=lambda item: (
            _source_score(item),
            _active_or_delivered_score(item),
            subdub_job_timestamp(item.get("updated_at") or item.get("started_at") or item.get("created_at") or 0),
        ),
        reverse=True,
    )
    return dict(candidates[0])

def subdub_job_public_status_text(job: dict | None = None, lang: str = "vi") -> str:
    job = dict(job or {})
    status = str(job.get("status") or "").lower()
    terminal = str(job.get("terminal_state") or "").lower()
    job_id = str(job.get("job_id") or job.get("internal_job_id") or "")
    outcome = str(job.get("terminal_public_outcome_type") or "").strip().lower()
    blocker = str(job.get("pipeline_blocker") or job.get("input_save_blocker") or job.get("no_charge_reason") or "").strip()
    if outcome == "partial_audio_delivered" or job.get("partial_audio_delivered"):
        return subdub_audio_fallback_text(str(job.get("mode") or ""), lang)
    if blocker == "large_telegram_download_unsupported" or "file is too big" in blocker.lower():
        return subdub_large_telegram_media_public_text(lang)
    if blocker.startswith("telegram_download_failed"):
        return subdub_download_failure_public_text(lang)
    if terminal == "delivered" or (status == "completed" and job.get("output_sent")):
        return subdub_progress_text("delivered", job_id, lang)
    if status.startswith("failed") or terminal.startswith("failed"):
        safe = sanitize_log_text(
            str(job.get("last_error_safe") or job.get("public_safe_error") or "")
        ).strip()[:500]
        if safe:
            return safe
        return subdub_clean_failure_text(lang)
    return subdub_progress_text(str(job.get("progress_stage") or job.get("stage") or "saved_input"), job_id, lang)

async def subdub_send_progress_update(
    query,
    job_key: str,
    job_id: str,
    stage: str,
    lang: str = "vi",
    *,
    rendered_text: str = "",
) -> None:
    canonical_stage = subdub_canonical_lifecycle_state(stage)
    lifecycle_debug = subdub_lifecycle_debug_fields(canonical_stage)
    lock = SUBDUB_PROGRESS_EDIT_LOCKS.setdefault(str(job_key or ""), asyncio.Lock())
    async with lock:
        current_job = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(str(job_key or "")) or {})
        current_terminal = str(current_job.get("terminal_state") or "").strip().lower()
        if current_terminal in SUBDUB_TERMINAL_STATES and current_terminal != canonical_stage:
            return
        update_subtitle_dub_pipeline_job(
            job_key,
            lifecycle_state=canonical_stage,
            current_stage=canonical_stage,
            progress_stage=canonical_stage,
            progress_percent=subdub_progress_percent_for_lifecycle(canonical_stage),
            completed_steps=subdub_completed_steps_for_lifecycle(canonical_stage),
            registry_job_id=str(job_id or ""),
            registry_chat_id_present=bool(getattr(getattr(query, "message", None), "chat_id", "")),
            **lifecycle_debug,
        )
        try:
            rendered = await safe_edit_or_send(
                query,
                rendered_text or subdub_progress_text(canonical_stage, job_id, lang),
                parse_mode="HTML",
                reply_markup=subdub_progress_keyboard(job_id, lang),
            )
            message_id = str(getattr(rendered, "message_id", "") or getattr(getattr(query, "message", None), "message_id", "") or "")
            if message_id:
                update_subtitle_dub_pipeline_job(job_key, status_panel_message_id=message_id)
        except Exception as exc:
            update_subtitle_dub_pipeline_job(
                job_key,
                status_panel_edit_failed=True,
                public_panel_update_failed_nonterminal=True,
                status_panel_edit_failed_count=int((SUBTITLE_DUB_PIPELINE_JOBS.get(job_key) or {}).get("status_panel_edit_failed_count") or 0) + 1,
                last_runtime_error_reason=sanitize_log_text(type(exc).__name__)[:120],
            )
            logger.warning("subtitle/dub progress update skipped | %s", sanitize_log_text(str(exc))[:120])


async def subdub_finalize_delivered_panel(
    query,
    context,
    job_key: str,
    job_id: str,
    lang: str,
    result: dict | None = None,
) -> object | None:
    """Render the terminal 100% panel only after artifact-specific delivery."""
    key = str(job_key or "")
    current = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(key) or {})
    evidence = subdub_terminal_delivery_evidence(result, current)
    if not key or not evidence:
        return None

    panel_text = subdub_progress_text("delivered", job_id, lang)
    panel_markup = subdub_progress_keyboard(job_id, lang)
    panel_message_id = str(current.get("status_panel_message_id") or "").strip()
    panel_chat_id = str(
        current.get("status_panel_chat_id")
        or current.get("chat_id")
        or getattr(getattr(query, "message", None), "chat_id", "")
        or ""
    ).strip()
    bot_client = getattr(context, "bot", None)
    if bot_client is None and hasattr(query, "get_bot"):
        try:
            bot_client = query.get_bot()
        except Exception:
            bot_client = None

    rendered = None
    edit_method = ""
    edit_error = ""
    if bot_client is not None and panel_message_id and panel_chat_id:
        try:
            rendered = await bot_client.edit_message_text(
                chat_id=_safe_int(panel_chat_id, panel_chat_id),
                message_id=_safe_int(panel_message_id, panel_message_id),
                text=panel_text,
                parse_mode="HTML",
                reply_markup=panel_markup,
            )
            edit_method = "stored_message_id"
        except Exception as exc:
            if subdub_panel_edit_already_terminal(exc):
                rendered = getattr(query, "message", None) or object()
                edit_method = "stored_message_already_terminal"
            else:
                edit_error = sanitize_log_text(type(exc).__name__)[:120]

    if rendered is None:
        message = getattr(query, "message", None)
        if message is None or not hasattr(message, "reply_text"):
            update_subtitle_dub_pipeline_job(
                key,
                status_panel_terminalized=False,
                status_panel_terminal_edit_confirmed=False,
                status_panel_terminal_edit_failed=True,
                status_panel_terminal_edit_error=edit_error or "panel_message_unavailable",
            )
            return None
        try:
            rendered = await message.reply_text(
                panel_text,
                parse_mode="HTML",
                reply_markup=panel_markup,
            )
            edit_method = "replacement_status_message"
        except Exception as exc:
            update_subtitle_dub_pipeline_job(
                key,
                status_panel_terminalized=False,
                status_panel_terminal_edit_confirmed=False,
                status_panel_terminal_edit_failed=True,
                status_panel_terminal_edit_error=sanitize_log_text(type(exc).__name__)[:120],
            )
            return None

    rendered_message_id = str(getattr(rendered, "message_id", "") or panel_message_id).strip()
    rendered_chat_id = str(
        getattr(rendered, "chat_id", "")
        or getattr(getattr(query, "message", None), "chat_id", "")
        or panel_chat_id
    ).strip()
    artifact_type = str(evidence.get("artifact_type") or "").strip()
    message_id = str(evidence.get("message_id") or "").strip()
    delivery_fields = {
        "terminal_artifact_type": artifact_type,
        "delivery_message_id": message_id,
    }
    if artifact_type == "video":
        delivery_fields.update(
            {
                "video_delivery_message_id": message_id,
                "final_video_message_id": message_id,
                "subdub_final_video_message_id": message_id,
                "final_mp4_delivered": True,
                "delivery_success": True,
                "delivery_succeeded": True,
            }
        )
    elif artifact_type == "subtitle":
        delivery_fields["srt_delivery_message_id"] = message_id

    update_subtitle_dub_pipeline_job(
        key,
        status="completed",
        terminal_state="delivered",
        lifecycle_state="delivered",
        current_stage="delivered",
        progress_stage="delivered",
        progress_percent=100,
        completed_steps=subdub_completed_steps_for_lifecycle("delivered", "delivered"),
        panel_finalized=True,
        panel_final_percent=100,
        panel_final_message_id=rendered_message_id,
        status_panel_message_id=rendered_message_id,
        status_panel_chat_id=rendered_chat_id,
        status_panel_terminalized=True,
        status_panel_terminal_edit_confirmed=True,
        status_panel_terminal_edit_failed=False,
        status_panel_terminal_edit_error="",
        status_panel_terminal_edit_method=edit_method,
        status_panel_replacement_sent=edit_method == "replacement_status_message",
        refresh_stopped_after_terminal=True,
        terminal_public_outcome_type="success",
        terminal_public_outcome_sent=True,
        terminal_public_outcome_message_id=message_id,
        **delivery_fields,
    )
    return rendered


def subdub_mark_delivered_terminal(job_key: str, result: dict | None = None) -> dict:
    """Persist the delivered terminal before nonessential Telegram UI work."""
    current = dict(result or {})
    message_id = subdub_video_delivery_message_id(current, SUBTITLE_DUB_PIPELINE_JOBS.get(job_key))
    if not job_key or not message_id or not subdub_duration_validation_allows_success(current):
        return dict(SUBTITLE_DUB_PIPELINE_JOBS.get(job_key) or {})
    return update_subtitle_dub_pipeline_job(
        job_key,
        status="completed",
        terminal_state="delivered",
        lifecycle_state="delivered",
        current_stage="delivered",
        progress_stage="delivered",
        progress_percent=100,
        completed_steps=subdub_completed_steps_for_lifecycle("delivered", "delivered"),
        panel_finalized=True,
        panel_final_percent=100,
        status_panel_terminalized=True,
        refresh_stopped_after_terminal=True,
        terminal_public_outcome_type="success",
        terminal_public_outcome_sent=True,
        terminal_public_outcome_message_id=message_id,
        public_error_sent=False,
        public_failure_sent=False,
        public_error_sent_count=0,
        delivery_success=True,
        delivery_succeeded=True,
        delivery_confirmed_before_success=True,
        final_mp4_delivered=True,
        output_sent=True,
        public_success_sent=True,
        video_delivery_message_id=message_id,
        final_video_message_id=message_id,
        subdub_final_video_message_id=message_id,
        delivery_message_id=message_id,
        late_fail_suppressed=True,
        error_sent_after_delivery=False,
    )


def subdub_receipt_send_is_uncertain(error: Exception) -> bool:
    token = str(error or "").strip().lower()
    return any(part in token for part in ("timeout", "timed out", "readtimeout", "networkerror"))


async def subdub_send_success_receipt_once(
    message,
    job_key: str,
    receipt_text: str,
    reply_markup=None,
) -> object | None:
    """Send one receipt after real video delivery without risking duplicate timeout retries."""
    job = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(str(job_key or "")) or {})
    evidence = subdub_terminal_delivery_evidence(job)
    delivery_message_id = str(evidence.get("message_id") or "").strip()
    existing_receipt_id = str(job.get("subdub_success_message_id") or job.get("receipt_message_id") or "").strip()
    if not message or not job_key or not delivery_message_id:
        return None
    panel_confirmed = bool(job.get("status_panel_terminal_edit_confirmed"))
    legacy_without_stored_panel = bool(
        not str(job.get("status_panel_message_id") or "").strip()
        and not str(job.get("status_panel_chat_id") or "").strip()
    )
    if not panel_confirmed and not legacy_without_stored_panel:
        update_subtitle_dub_pipeline_job(
            job_key,
            receipt_sent_once=False,
            receipt_send_state="blocked_until_terminal_panel",
            receipt_blocked_reason="terminal_panel_not_confirmed",
        )
        return None
    if existing_receipt_id or truthy_value(job.get("receipt_sent_once"), False):
        update_subtitle_dub_pipeline_job(
            job_key,
            receipt_sent_once=True,
            duplicate_receipt_prevented=True,
            receipt_message_id=existing_receipt_id,
        )
        return None
    receipt_send_state = str(job.get("receipt_send_state") or "").strip().lower()
    if receipt_send_state == "unknown" or truthy_value(job.get("receipt_send_uncertain"), False):
        update_subtitle_dub_pipeline_job(
            job_key,
            duplicate_receipt_prevented=True,
            receipt_send_state="unknown",
            receipt_send_uncertain=True,
        )
        return None
    update_subtitle_dub_pipeline_job(
        job_key,
        receipt_send_attempted=True,
        receipt_send_attempted_at=time.time(),
        receipt_send_state="sending",
    )
    sent_receipt = None
    try:
        sent_receipt = await message.reply_text(
            receipt_text,
            parse_mode="HTML",
            reply_markup=reply_markup,
        )
    except Exception as exc:
        uncertain = subdub_receipt_send_is_uncertain(exc)
        if not uncertain:
            sent_receipt = await safe_reply_text(
                message,
                html_message_to_plain_text(receipt_text),
                parse_mode=None,
                reply_markup=reply_markup,
            )
        if sent_receipt is None:
            update_subtitle_dub_pipeline_job(
                job_key,
                receipt_send_state="unknown" if uncertain else "failed",
                receipt_send_uncertain=uncertain,
                receipt_send_failed=not uncertain,
                receipt_send_error=sanitize_log_text(type(exc).__name__)[:120],
            )
            return None
    receipt_message_id = str(getattr(sent_receipt, "message_id", "") or "").strip()
    if not receipt_message_id:
        update_subtitle_dub_pipeline_job(
            job_key,
            receipt_send_state="failed",
            receipt_send_failed=True,
            receipt_send_error="missing_receipt_message_id",
        )
        return None
    update_subtitle_dub_pipeline_job(
        job_key,
        subdub_success_message_id=receipt_message_id,
        receipt_message_id=receipt_message_id,
        receipt_sent_once=True,
        receipt_send_state="sent",
        receipt_send_failed=False,
        receipt_send_uncertain=False,
        success_sent_count=max(1, int((SUBTITLE_DUB_PIPELINE_JOBS.get(job_key) or {}).get("success_sent_count") or 0)),
    )
    return sent_receipt

def video_dubbing_job_status_text(job: dict | None = None, lang: str = "vi") -> str:
    job = dict(job or {})
    copy = public_subdub_deep_copy(normalize_user_language(lang))
    status = str(job.get("status") or "").lower()
    if status in {"queued", "running", "processing"}:
        return f"{copy['progress']}\n{copy['job']}"
    if status == "succeeded":
        return f"{copy['success']}\n{copy['output']}"
    return f"{copy['fail']}\n{copy['failure']}"

def video_dubbing_job_result_keyboard(lang: str = "vi") -> InlineKeyboardMarkup:
    is_vi = normalize_user_language(lang) == "vi"
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("📥 Tải file" if is_vi else "📥 Download file", callback_data="videodub|job_download"),
            InlineKeyboardButton("🔁 Làm video khác" if is_vi else "🔁 Another video", callback_data="videodub|back_type"),
        ],
        [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
    ])

def pipeline_input_limit_mb(is_admin: bool = False) -> int:
    return PIPELINE_MAX_INPUT_MB_ADMIN if is_admin else PIPELINE_MAX_INPUT_MB_PUBLIC

def subdub_input_limit_mb(
    is_admin: bool = False,
    *,
    intake_method: str = "",
    local_api: bool | None = None,
) -> int:
    del is_admin
    method = str(intake_method or "").strip().lower()
    if not method:
        return min(int(SUBDUB_MAX_INPUT_MB), int(SUBDUB_TELEGRAM_DOWNLOAD_LIMIT_MB))
    processing_limit = int(SUBDUB_PROCESSING_MAX_INPUT_MB)
    if method in {"local_path_override", "source_bytes_override", "legal_fixture"}:
        return processing_limit
    if method == "cloud_bot_api":
        return min(processing_limit, int(SUBDUB_TELEGRAM_CLOUD_DOWNLOAD_LIMIT_MB))
    if method == "bot_api_direct":
        uses_local_api = telegram_local_api_enabled() if local_api is None else bool(local_api)
        transport_limit = (
            int(SUBDUB_TELEGRAM_DOWNLOAD_LIMIT_MB)
            if uses_local_api
            else int(SUBDUB_TELEGRAM_CLOUD_DOWNLOAD_LIMIT_MB)
        )
        return min(processing_limit, transport_limit)
    return min(processing_limit, int(SUBDUB_TELEGRAM_DOWNLOAD_LIMIT_MB))


def subdub_output_delivery_limit_mb(kind: str = "document", *, local_api: bool | None = None) -> int:
    """Resolve output size by Telegram transport instead of a global 49 MB gate."""
    output_kind = str(kind or "document").strip().lower()
    configured = int(
        SUBDUB_TELEGRAM_SEND_VIDEO_MAX_MB
        if output_kind == "video"
        else SUBDUB_TELEGRAM_DOCUMENT_MAX_MB
    )
    uses_local_api = telegram_local_api_enabled() if local_api is None else bool(local_api)
    if uses_local_api:
        return min(
            int(SUBDUB_TELEGRAM_LOCAL_DOWNLOAD_LIMIT_MAX_MB),
            max(configured, int(SUBDUB_PROCESSING_MAX_INPUT_MB)),
        )
    return min(configured, 50)

def pipeline_duration_limit_seconds(is_admin: bool = False) -> int:
    return PIPELINE_MAX_DURATION_SECONDS_ADMIN if is_admin else PIPELINE_MAX_DURATION_SECONDS_PUBLIC

def subdub_full_duration_limit_seconds(is_admin: bool = False) -> int:
    """Return zero: public media duration is unbounded by application policy.

    Telegram transport and measured resource timeouts remain independent
    capability concerns; this helper must never reject a video by seconds.
    """
    del is_admin
    return 0

def subdub_preview_duration_seconds() -> int:
    return int(SUBDUB_PREVIEW_DURATION_SECONDS)

def subdub_long_video_chunk_plan(
    duration_seconds: float | int = 0,
    chunk_seconds: int | None = None,
    *,
    source_hash: str = "",
    overlap_ms: int = 1500,
    direct_threshold_seconds: int | None = None,
) -> dict:
    duration_value = max(0.0, float(duration_seconds or 0.0))
    duration = max(0, int(math.ceil(duration_value)))
    chunk_size = max(10, min(30, int(chunk_seconds or SUBDUB_LONG_CHUNK_SECONDS or 30)))
    direct_threshold = (
        int(SUBDUB_DIRECT_ASR_MAX_SECONDS)
        if direct_threshold_seconds is None
        else max(1, int(direct_threshold_seconds))
    )
    if duration <= direct_threshold:
        return {
            "chunking_enabled": False,
            "chunk_count": 1 if duration > 0 else 0,
            "chunk_seconds": chunk_size,
            "chunk_ranges": [],
            "concat_required": False,
            "global_timing_preserved": True,
        }
    chunk_count = max(1, int(math.ceil(duration / float(chunk_size))))
    ranges = [
        {
            "index": position + 1,
            "start": position * chunk_size,
            "end": min(duration, (position + 1) * chunk_size),
        }
        for position in range(chunk_count)
    ]
    # Preserve the established 30-second chunk contract. Only rebalance when
    # it would leave an unusably short tail (for example 31s -> 30s + 1s).
    if len(ranges) > 1 and ranges[-1]["end"] - ranges[-1]["start"] < 10:
        ranges = []
        for position in range(chunk_count):
            start = int(round((duration * position) / chunk_count))
            end = int(round((duration * (position + 1)) / chunk_count))
            if end <= start:
                end = min(duration, start + 1)
            ranges.append({"index": position + 1, "start": start, "end": end})
    bounded_overlap_ms = max(0, min(5000, int(overlap_ms or 0)))
    duration_ms = int(round(duration_value * 1000)) or duration * 1000
    fingerprint = str(source_hash or "source_hash_unavailable")
    chunk_metadata = []
    for index, item in enumerate(ranges, start=1):
        ownership_start_ms = int(item.get("start") or 0) * 1000
        ownership_end_ms = min(duration_ms, int(item.get("end") or 0) * 1000)
        extract_start_ms = max(0, ownership_start_ms - bounded_overlap_ms)
        extract_end_ms = min(duration_ms, ownership_end_ms + bounded_overlap_ms)
        identity = f"{fingerprint}:{ownership_start_ms}:{ownership_end_ms}:{chunk_size}"
        chunk_metadata.append({
            **item,
            "chunk_index": int(item.get("index") or index),
            "chunk_id": hashlib.sha256(identity.encode("utf-8")).hexdigest()[:24],
            "source_hash": fingerprint,
            "source_start_ms": ownership_start_ms,
            "source_end_ms": ownership_end_ms,
            "ownership_start_ms": ownership_start_ms,
            "ownership_end_ms": ownership_end_ms,
            "extract_start_ms": extract_start_ms,
            "extract_end_ms": extract_end_ms,
            "duration_ms": max(0, ownership_end_ms - ownership_start_ms),
            "overlap_left_ms": max(0, ownership_start_ms - extract_start_ms),
            "overlap_right_ms": max(0, extract_end_ms - ownership_end_ms),
            "local_audio_path": "",
        })
    return {
        "chunking_enabled": True,
        "chunk_count": len(ranges),
        "chunk_seconds": chunk_size,
        "chunk_ranges": ranges,
        "chunk_metadata": chunk_metadata,
        "concat_required": len(ranges) > 1,
        "global_timing_preserved": True,
    }

def subdub_duration_over_limit_text(lang: str = "vi") -> str:
    if normalize_user_language(lang) != "vi":
        return (
            "This video is longer than the current processing limit. TOAN AAS has not charged Xu. "
            "Please send a shorter video or try again later."
        )
    return "Video này dài hơn giới hạn xử lý hiện tại. TOAN AAS chưa trừ Xu. Anh/chị có thể gửi video ngắn hơn hoặc thử lại sau."

def subdub_duration_gate_payload(
    input_save: dict | None = None,
    state: dict | None = None,
    *,
    is_admin: bool = False,
    ffprobe_duration: float | int = 0,
) -> dict:
    current = dict(input_save or {})
    state = dict(state or {})
    telegram_duration = _safe_int(
        current.get("telegram_duration")
        or state.get("telegram_duration")
        or state.get("video_duration")
        or state.get("source_duration"),
        0,
    )
    ffprobe_seconds = max(
        0,
        int(math.ceil(_safe_float(ffprobe_duration or current.get("ffprobe_duration"), 0.0))),
    )
    input_duration = ffprobe_seconds or telegram_duration or _safe_int(current.get("duration"), 0)
    input_size = _safe_int(
        current.get("telegram_file_size")
        or current.get("size")
        or state.get("video_file_size")
        or state.get("source_file_size"),
        0,
    )
    duration_source = "ffprobe" if ffprobe_seconds else ("telegram" if telegram_duration else ("saved_input" if input_duration else "missing"))
    limit = subdub_full_duration_limit_seconds(is_admin)
    preview = subdub_preview_duration_seconds()
    direct_asr_limit = int(SUBDUB_DIRECT_ASR_MAX_SECONDS)
    over_limit = bool(limit > 0 and input_duration and input_duration > limit)
    input_download_limit_bytes = int(SUBDUB_TELEGRAM_DOWNLOAD_LIMIT_MB) * 1024 * 1024
    output_delivery_limit_bytes = max(
        subdub_output_delivery_limit_mb("video"),
        subdub_output_delivery_limit_mb("document"),
    ) * 1024 * 1024
    is_long = bool(input_duration and input_duration > direct_asr_limit)
    long_allowed = bool(is_long and not over_limit)
    gate_result = "fail_over_limit" if over_limit else ("pass_long" if long_allowed else ("pass_unknown_duration" if not input_duration else "pass"))
    over_30_supported = bool(is_long and long_allowed)
    chunk_plan = (
        subdub_long_video_chunk_plan(
            input_duration,
            direct_threshold_seconds=direct_asr_limit,
        )
        if over_30_supported
        else subdub_long_video_chunk_plan(0, direct_threshold_seconds=direct_asr_limit)
    )
    return {
        "input_duration": int(input_duration or 0),
        "input_duration_seconds": int(input_duration or 0),
        "duration_seconds": int(input_duration or 0),
        "detected_duration_source": duration_source,
        "telegram_duration": int(telegram_duration or 0),
        "ffprobe_duration": int(ffprobe_seconds or 0),
        "duration_limit": int(limit),
        "duration_limit_seconds": int(limit),
        "duration_policy_limit_seconds": int(limit),
        "duration_limit_blocker": "duration_over_limit" if over_limit else "",
        "input_size_bytes": int(input_size or 0),
        "input_download_limit_bytes": input_download_limit_bytes,
        "output_delivery_limit_bytes": output_delivery_limit_bytes,
        "size_limit_blocker": (
            "telegram_direct_download_over_limit"
            if input_size > input_download_limit_bytes
            and str(current.get("telegram_download_method") or "bot_api_direct") == "bot_api_direct"
            else ""
        ),
        "duration_limit_source": (
            "SUBDUB_MAX_DURATION_SECONDS" if limit > 0 else "capability_config_unbounded"
        ),
        "duration_gate_result": gate_result,
        "duration_guard_stage": "after_input_save",
        "is_long_media": is_long,
        "long_media_allowed": long_allowed,
        "over_30_supported": over_30_supported,
        "over_30_route": "async" if over_30_supported else ("blocked_clean" if over_limit else "normal"),
        "duration_preflight_done": True,
        "preview_duration_seconds": int(preview),
        "direct_asr_max_seconds": direct_asr_limit,
        "chunking_enabled": bool(chunk_plan.get("chunking_enabled")),
        "chunk_count": int(chunk_plan.get("chunk_count") or 0),
        "chunk_seconds": int(chunk_plan.get("chunk_seconds") or SUBDUB_LONG_CHUNK_SECONDS),
        "chunk_ranges": list(chunk_plan.get("chunk_ranges") or []),
        "chunk_metadata": list(chunk_plan.get("chunk_metadata") or []),
        "chunk_strategy": "checkpointed_audio_chunks" if chunk_plan.get("chunking_enabled") else "whole_file",
        "concat_required": bool(chunk_plan.get("concat_required")),
        "global_timing_preserved": bool(chunk_plan.get("global_timing_preserved")),
    }
async def subdub_duration_gate_payload_for_saved_input(
    input_save: dict | None = None,
    state: dict | None = None,
    *,
    is_admin: bool = False,
) -> dict:
    current = dict(input_save or {})
    content_type = str(current.get("content_type") or (state or {}).get("source_mime_type") or "").lower()
    ffprobe_duration = 0.0
    source_bytes = current.get("source_bytes")
    if content_type.startswith("video/") and isinstance(source_bytes, (bytes, bytearray)) and source_bytes:
        try:
            probe = await subdub_probe_video_bytes(bytes(source_bytes))
            if probe.get("ok") or float(probe.get("duration") or 0) > 0:
                ffprobe_duration = float(probe.get("duration") or 0.0)
        except Exception:
            ffprobe_duration = 0.0
    return subdub_duration_gate_payload(current, state, is_admin=is_admin, ffprobe_duration=ffprobe_duration)

def subdub_lifecycle_debug_fields(stage: str = "", terminal_state: str = "") -> dict:
    terminal = str(terminal_state or "").strip().lower()
    canonical = subdub_canonical_lifecycle_state(stage or terminal or "received_file")
    order = [
        "received_file",
        "received_video",
        "extracting_audio",
        "transcribing",
        "translating",
        "generating_voice",
        "muxing_video",
        "validating_output",
        "delivering",
        "delivered",
    ]
    try:
        index = order.index(canonical)
    except ValueError:
        index = 0
    completed = subdub_completed_steps_for_lifecycle(canonical, terminal)
    return {
        "pipeline_started": bool(canonical in order or terminal),
        "asr_started": bool(index >= order.index("transcribing") or terminal == "delivered"),
        "translation_started": bool(index >= order.index("translating") or terminal == "delivered"),
        "tts_started": bool(index >= order.index("generating_voice") or terminal == "delivered"),
        "mux_started": bool(index >= order.index("muxing_video") or terminal == "delivered"),
        "artifact_started": bool(index >= order.index("validating_output") or terminal == "delivered"),
        "last_completed_step": str(completed[-1] if completed else ""),
    }

def subtitle_dub_pipeline_job_key(user_id, chat_id, state: dict | None = None) -> str:
    state = dict(state or {})
    source = str(
        state.get("source_file_unique_id")
        or state.get("video_file_unique_id")
        or state.get("source_file_id")
        or state.get("video_file_id")
        or "no_source"
    )
    mode = normalize_video_translate_mode(
        state.get("video_processing_mode") or state.get("mode") or state.get("process_type")
    )
    active_flow = str(state.get("active_flow") or mode or "pipeline")
    return "|".join((str(user_id or 0), str(chat_id or user_id or 0), source[:160], active_flow[:80]))

def subdub_job_timestamp(value, default: float = 0.0) -> float:
    try:
        return float(value or default)
    except (TypeError, ValueError):
        try:
            return datetime.fromisoformat(str(value or "").replace("Z", "+00:00")).timestamp()
        except (TypeError, ValueError):
            return float(default or 0.0)

SUBDUB_WORKSPACE_ACTIVE_STATUSES = frozenset({
    "queued", "accepted", "preparing", "processing", "running", "rendering",
    "muxing", "delivering", "retrying_delivery", "waiting_retry",
    "waiting_provider", "waiting_scene", "finalizing",
})
SUBDUB_WORKSPACE_TERMINAL_STATUSES = frozenset({
    "completed", "delivered", "failed", "failed_no_charge", "failed_refunded",
    "cancelled", "expired", "abandoned",
})

def normalize_workspace_job_status(value) -> str:
    return re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")

def is_workspace_active_status(status) -> bool:
    return normalize_workspace_job_status(status) in SUBDUB_WORKSPACE_ACTIVE_STATUSES

def _workspace_path_is_descendant(path_value: str, root_value: str) -> bool:
    try:
        path_norm = os.path.normcase(os.path.abspath(str(path_value or "")))
        root_norm = os.path.normcase(os.path.abspath(str(root_value or "")))
        return bool(path_norm and root_norm and path_norm != root_norm and os.path.commonpath([path_norm, root_norm]) == root_norm)
    except (OSError, ValueError):
        return False

def subtitle_dub_workspace_path_safety(workspace: str) -> dict:
    original_value = str(workspace or "").strip()
    allowed_root_original = Path(os.path.abspath(PIPELINE_TEMP_ROOT))
    original_path = Path(os.path.abspath(original_value)) if original_value else Path("")
    try:
        allowed_root_resolved = allowed_root_original.resolve(strict=False)
        resolved_path = original_path.resolve(strict=False) if original_value else Path("")
    except (OSError, RuntimeError) as exc:
        return {
            "allowed": False,
            "original_path": original_value,
            "resolved_path": "",
            "allowed_root": str(allowed_root_original),
            "blocked_reason": "path_resolution_failed",
            "error_type": type(exc).__name__,
            "error_message": sanitize_log_text(str(exc))[:300],
            "is_symlink": False,
            "is_junction": False,
        }
    result = {
        "allowed": False,
        "original_path": str(original_path) if original_value else "",
        "resolved_path": str(resolved_path) if original_value else "",
        "allowed_root": str(allowed_root_resolved),
        "blocked_reason": "",
        "error_type": "",
        "error_message": "",
        "is_symlink": bool(original_value and os.path.islink(str(original_path))),
        "is_junction": bool(original_value and callable(getattr(os.path, "isjunction", None)) and os.path.isjunction(str(original_path))),
    }
    if not original_value:
        result["blocked_reason"] = "workspace_path_missing"
        return result
    filesystem_root = Path(resolved_path.anchor).resolve(strict=False) if resolved_path.anchor else Path(os.path.sep).resolve(strict=False)
    if os.path.normcase(str(resolved_path)) == os.path.normcase(str(filesystem_root)):
        result["blocked_reason"] = "filesystem_root_blocked"
        return result
    if os.path.normcase(str(original_path)) == os.path.normcase(str(allowed_root_original)) or os.path.normcase(str(resolved_path)) == os.path.normcase(str(allowed_root_resolved)):
        result["blocked_reason"] = "allowed_root_blocked"
        return result
    if not _workspace_path_is_descendant(str(original_path), str(allowed_root_original)):
        result["blocked_reason"] = "external_or_parent_path_blocked"
        return result
    if not _workspace_path_is_descendant(str(resolved_path), str(allowed_root_resolved)):
        if result["is_symlink"]:
            result["blocked_reason"] = "symlink_escape_blocked"
        elif result["is_junction"]:
            result["blocked_reason"] = "junction_escape_blocked"
        else:
            result["blocked_reason"] = "resolved_path_escape_blocked"
        return result
    result["allowed"] = True
    return result

def _workspace_truthy(value) -> bool:
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "on", "active", "pending"}

def _workspace_job_active_lock(job: dict, now_ts: float) -> tuple[bool, str]:
    for key in ("active_lock", "lock_active", "workspace_lock_active", "delivery_lock_active"):
        if _workspace_truthy(job.get(key)):
            return True, key
    for key in ("lease_until", "lease_expires_at", "lock_until", "lock_expires_at", "workspace_lease_until"):
        if subdub_job_timestamp(job.get(key), 0) > now_ts:
            return True, key
    heartbeat_values = [
        subdub_job_timestamp(job.get(key), 0)
        for key in ("heartbeat_at", "last_heartbeat_at", "worker_heartbeat_at")
        if job.get(key)
    ]
    if heartbeat_values and now_ts - max(heartbeat_values) <= PIPELINE_JOB_LOCK_TTL_SECONDS:
        return True, "recent_heartbeat"
    return False, ""

def _workspace_active_reference_count(job: dict) -> int:
    count = 0
    for key in ("active_reference_count", "delivery_reference_count", "dedupe_reference_count", "retry_reference_count"):
        count += max(0, _safe_int(job.get(key), 0))
    for key in ("active_references", "delivery_references", "dedupe_references", "retry_references"):
        value = job.get(key)
        if isinstance(value, (list, tuple, set, dict)):
            count += len(value)
    for key in ("dedupe_reference_active", "delivery_reference_active", "retry_reference_active"):
        count += int(_workspace_truthy(job.get(key)))
    return count

def _workspace_recorded_paths(job: dict) -> list[str]:
    paths = []
    for key in (
        "final_mp4", "final_mp4_path", "final_output_path", "workspace_final_output_path",
        "canonical_output_path", "canonical_final_output_path", "canonical_mp4_path",
        "final_asset_path", "dub_video_path", "output_path",
    ):
        value = str(job.get(key) or "").strip()
        if value:
            paths.append(value)
    artifacts = job.get("workspace_artifacts") or {}
    if isinstance(artifacts, dict):
        for key in ("final_mp4", "final_video", "output"):
            value = str(artifacts.get(key) or "").strip()
            if value:
                paths.append(value)
    return list(dict.fromkeys(paths))

def can_cleanup_workspace(job_record: dict | None, workspace_path: str, *, now_ts: float | None = None) -> dict:
    job = dict(job_record or {})
    current_ts = float(now_ts or time.time())
    statuses = [
        normalize_workspace_job_status(job.get(key))
        for key in ("status", "terminal_state", "lifecycle_state", "current_stage", "progress_stage")
        if job.get(key)
    ]
    effective_status = next((item for item in statuses if item in SUBDUB_WORKSPACE_TERMINAL_STATUSES), statuses[0] if statuses else "")
    delivery_state = normalize_workspace_job_status(
        job.get("delivery_state") or job.get("delivery_status") or job.get("current_stage") or effective_status
    )
    retry_pending = bool(
        any(_workspace_truthy(job.get(key)) for key in (
            "delivery_retry_pending", "retry_pending", "delivery_retry_scheduled",
            "delivery_pending", "delivery_in_progress", "retry_delivery",
        ))
        or any(item in {"delivering", "retrying_delivery", "waiting_retry", "finalizing"} for item in statuses)
    )
    active_reference_count = _workspace_active_reference_count(job)
    result = {
        "allowed": False,
        "reason": "",
        "final_output_location": "none",
        "delivery_state": delivery_state,
        "retry_pending": retry_pending,
        "active_reference_count": active_reference_count,
        "status": effective_status,
    }
    active_status = next((item for item in statuses if is_workspace_active_status(item)), "")
    if active_status:
        result["reason"] = "cleanup_skipped_active"
        result["status"] = active_status
        return result
    lock_active, lock_reason = _workspace_job_active_lock(job, current_ts)
    if lock_active:
        result["reason"] = "cleanup_skipped_active_lock"
        result["lock_reason"] = lock_reason
        return result
    workspace_resolved = ""
    if str(workspace_path or "").strip():
        safety = subtitle_dub_workspace_path_safety(workspace_path)
        result["path_safety"] = safety
        if not safety.get("allowed"):
            result["reason"] = "cleanup_blocked_unsafe_path"
            return result
        workspace_resolved = str(safety.get("resolved_path") or "")
    if retry_pending:
        result["reason"] = "cleanup_skipped_delivery_pending"
        return result
    if active_reference_count > 0:
        result["reason"] = "cleanup_skipped_active_reference"
        return result
    if effective_status not in SUBDUB_WORKSPACE_TERMINAL_STATUSES:
        result["reason"] = "cleanup_skipped_unknown_status"
        return result
    if not str(workspace_path or "").strip():
        result.update({"allowed": True, "reason": "workspace_missing", "final_output_location": "none"})
        return result
    recorded_paths = _workspace_recorded_paths(job)
    workspace_outputs = []
    canonical_outputs = []
    for item in recorded_paths:
        try:
            resolved = str(Path(item).resolve(strict=False))
        except (OSError, RuntimeError):
            resolved = os.path.abspath(item)
        if _workspace_path_is_descendant(resolved, workspace_resolved):
            workspace_outputs.append(resolved)
        else:
            canonical_outputs.append(resolved)
    canonical_existing = [item for item in canonical_outputs if os.path.isfile(item) and os.path.getsize(item) > 0]
    workspace_existing = [item for item in workspace_outputs if os.path.isfile(item) and os.path.getsize(item) > 0]
    delivered = bool(
        normalize_workspace_job_status(job.get("terminal_state")) == "delivered"
        or _workspace_truthy(job.get("final_mp4_delivered"))
        or (_workspace_truthy(job.get("output_sent")) and _workspace_truthy(job.get("delivery_succeeded")))
    )
    requires_final_mp4 = subdub_video_requires_final_mp4(
        str(job.get("mode") or job.get("mapped_mode") or ""),
        str(job.get("product_type") or job.get("mapped_product_type") or ""),
    )
    if workspace_existing:
        result["final_output_location"] = "workspace"
        if not delivered:
            result["reason"] = "cleanup_skipped_delivery_pending"
            return result
        if not canonical_existing:
            result["reason"] = "cleanup_skipped_final_output_not_canonical"
            return result
    elif canonical_existing:
        result["final_output_location"] = "canonical"
    elif recorded_paths:
        result["final_output_location"] = "missing"
    if requires_final_mp4 and delivered and not canonical_existing:
        result["reason"] = "cleanup_skipped_delivered_output_inconsistent"
        return result
    result.update({"allowed": True, "reason": "cleanup_allowed"})
    return result

def _workspace_cleanup_audit_fields(job: dict, cleanup_result: dict, decision: dict, cleanup_status: str) -> dict:
    error_message = sanitize_log_text(str(cleanup_result.get("error_message") or ""))[:300]
    return {
        "cleanup_status": str(cleanup_status or ""),
        "cleanup_error": error_message,
        "cleanup_error_type": str(cleanup_result.get("error_type") or "")[:120],
        "cleanup_last_attempt_at": time.time(),
        "cleanup_attempt_count": int(job.get("cleanup_attempt_count") or 0) + 1,
        "cleanup_result": dict(cleanup_result or {}),
        "cleanup_decision": dict(decision or {}),
        "cleanup_original_path": str(cleanup_result.get("original_path") or ""),
        "cleanup_resolved_path": str(cleanup_result.get("resolved_path") or ""),
        "cleanup_allowed_root": str(cleanup_result.get("allowed_root") or ""),
        "cleanup_blocked_reason": str(cleanup_result.get("blocked_reason") or decision.get("reason") or ""),
    }

def _persist_workspace_cleanup_audit(job_key: str, job: dict, cleanup_result: dict, decision: dict, cleanup_status: str) -> dict:
    current = dict(job or {})
    current.update(_workspace_cleanup_audit_fields(current, cleanup_result, decision, cleanup_status))
    SUBTITLE_DUB_PIPELINE_JOBS[str(job_key or "")] = current
    persisted = bool(
        persist_subtitle_dub_pipeline_job_snapshot(
            str(job_key or ""),
            current,
            reason=str(cleanup_status or "workspace_cleanup"),
        )
    )
    current["cleanup_audit_persisted"] = persisted
    current["cleanup_record_removal_pending"] = not persisted
    SUBTITLE_DUB_PIPELINE_JOBS[str(job_key or "")] = current
    return current

def _prune_subtitle_dub_pipeline_jobs(now_ts: float | None = None) -> None:
    now_ts = float(now_ts or time.time())
    for key, job in list(SUBTITLE_DUB_PIPELINE_JOBS.items()):
        age = now_ts - subdub_job_timestamp(job.get("updated_at") or job.get("started_at") or 0)
        if age <= PIPELINE_JOB_LOCK_TTL_SECONDS:
            continue
        workspace = str(job.get("workspace") or "")
        decision = can_cleanup_workspace(job, workspace, now_ts=now_ts)
        if not decision.get("allowed"):
            status = str(decision.get("reason") or "cleanup_skipped_active")
            cleanup_result = {
                "attempted": False,
                "deleted": False,
                "already_missing": False,
                "skipped": True,
                "blocked": status == "cleanup_blocked_unsafe_path",
                "error_type": "",
                "error_message": "",
                **dict(decision.get("path_safety") or {}),
            }
            _persist_workspace_cleanup_audit(key, job, cleanup_result, decision, status)
            continue
        cleanup_result = (
            cleanup_subtitle_dub_pipeline_workspace_result(workspace)
            if workspace
            else {
                "attempted": False,
                "deleted": False,
                "already_missing": True,
                "skipped": False,
                "blocked": False,
                "error_type": "",
                "error_message": "",
                "original_path": "",
                "resolved_path": "",
                "allowed_root": str(Path(PIPELINE_TEMP_ROOT).resolve(strict=False)),
                "blocked_reason": "",
            }
        )
        succeeded = bool(cleanup_result.get("deleted") or cleanup_result.get("already_missing"))
        if succeeded:
            previous_attempts = int(job.get("cleanup_attempt_count") or 0)
            status = (
                "workspace_missing_after_previous_attempt"
                if cleanup_result.get("already_missing") and previous_attempts > 0
                else ("workspace_missing" if cleanup_result.get("already_missing") else "cleanup_succeeded")
            )
            audited = _persist_workspace_cleanup_audit(key, job, cleanup_result, decision, status)
            if audited.get("cleanup_audit_persisted"):
                SUBTITLE_DUB_PIPELINE_JOBS.pop(key, None)
        else:
            status = "cleanup_blocked_unsafe_path" if cleanup_result.get("blocked") else "cleanup_failed"
            _persist_workspace_cleanup_audit(key, job, cleanup_result, decision, status)
    cleanup_stale_subtitle_dub_pipeline_workspaces(now_ts=now_ts)

def acquire_subtitle_dub_pipeline_job(job_key: str, **fields) -> tuple[bool, dict]:
    _prune_subtitle_dub_pipeline_jobs()
    key = str(job_key or "")
    existing = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(key) or {})
    if existing and (
        existing.get("status") == "running"
        or (existing.get("status") == "completed" and existing.get("output_sent"))
        or bool(existing.get("output_sent"))
        or str(existing.get("terminal_state") or "").strip().lower() in SUBDUB_TERMINAL_STATES
    ):
        existing["duplicate_count"] = int(existing.get("duplicate_count") or 0) + 1
        existing["updated_at"] = time.time()
        SUBTITLE_DUB_PIPELINE_JOBS[key] = existing
        return False, existing
    now_ts = time.time()
    lifecycle_debug = subdub_lifecycle_debug_fields("received_file")
    job = {
        "job_key": key,
        "job_id": hashlib.sha256(f"{key}:{now_ts}".encode("utf-8")).hexdigest()[:20],
        "status": "running",
        "terminal_state": "",
        "lifecycle_state": "received_file",
        "current_stage": "received_file",
        "progress_stage": "received_file",
        "progress_percent": subdub_progress_percent_for_lifecycle("received_file"),
        "completed_steps": [],
        "input_duration": 0,
        "duration_seconds": 0,
        "detected_duration_source": "missing",
        "telegram_duration": 0,
        "ffprobe_duration": 0,
        "duration_limit": int(subdub_full_duration_limit_seconds(bool(fields.get("is_admin")))),
        "duration_limit_seconds": int(subdub_full_duration_limit_seconds(bool(fields.get("is_admin")))),
        "duration_gate_result": "pending",
        "duration_guard_stage": "created",
        "is_long_media": False,
        "long_media_allowed": False,
        "worker_claim_required": False,
        "worker_claimed": False,
        "registry_job_id": hashlib.sha256(f"{key}:{now_ts}".encode("utf-8")).hexdigest()[:20],
        "registry_chat_id_present": bool(fields.get("chat_id")),
        "status_panel_message_id": "",
        "last_error_stage": "",
        "last_error_safe": "",
        "charge_status": "not_charged",
        **lifecycle_debug,
        "chunking_enabled": False,
        "chunk_count": 0,
        "delivery_attempted": False,
        "delivery_message_id": "",
        "duplicate_delivery_prevented": False,
        "public_error_sent": False,
        "error_sent_after_delivery": False,
        "output_validated": False,
        "output_sent": False,
        **subdub_terminal_outcome_debug_defaults(),
        "started_at": now_ts,
        "updated_at": now_ts,
        "duplicate_count": 0,
        **fields,
    }
    job = subdub_enrich_job_identity(job, job_key=key, mode=str(fields.get("mode") or ""), state=fields)
    SUBTITLE_DUB_PIPELINE_JOBS[key] = job
    persist_subtitle_dub_pipeline_job_snapshot(key, job, reason="pipeline_job_acquired")
    return True, dict(job)

def update_subtitle_dub_pipeline_job(job_key: str, **fields) -> dict:
    job = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(str(job_key or "")) or {})
    if "terminal_state_history" in fields and not fields.get("terminal_state_history") and job.get("terminal_state_history"):
        fields.pop("terminal_state_history", None)
    current_terminal = str(job.get("terminal_state") or "")
    desired_terminal = str(fields.get("terminal_state") or "")
    incoming_stage = str(
        fields.get("progress_stage")
        or fields.get("current_stage")
        or fields.get("lifecycle_state")
        or ""
    )
    current_percent = _safe_int(job.get("progress_percent"), 0)
    incoming_percent = (
        _safe_int(fields.get("progress_percent"), 0)
        if "progress_percent" in fields
        else subdub_progress_percent_for_lifecycle(incoming_stage)
        if incoming_stage
        else current_percent
    )
    if not desired_terminal and incoming_stage and incoming_percent < current_percent:
        for key in (
            "lifecycle_state",
            "current_stage",
            "progress_stage",
            "progress_percent",
            "completed_steps",
        ):
            fields.pop(key, None)
    if current_terminal and desired_terminal and current_terminal != desired_terminal:
        if current_terminal in SUBDUB_TERMINAL_STATES or not subdub_terminal_state_allows_transition(current_terminal, desired_terminal):
            fields = {
                key: value
                for key, value in fields.items()
                if key not in {"terminal_state", "status", "lifecycle_state", "current_stage", "progress_stage", "progress_percent", "completed_steps"}
            }
            desired_terminal = ""
        else:
            history = list(job.get("terminal_state_history") or [])
            history.append({"from": current_terminal, "to": desired_terminal, "at": time.time()})
            fields["terminal_state_history"] = history[-12:]
    elif desired_terminal and not current_terminal:
        history = list(job.get("terminal_state_history") or [])
        history.append({"from": "", "to": desired_terminal, "at": time.time()})
        fields["terminal_state_history"] = history[-12:]
    if desired_terminal:
        fields.setdefault("lifecycle_state", desired_terminal)
        fields.setdefault("current_stage", "delivered" if desired_terminal == "delivered" else desired_terminal)
        fields.setdefault("progress_stage", "delivered" if desired_terminal == "delivered" else desired_terminal)
        fields.setdefault("progress_percent", subdub_progress_percent_for_lifecycle(fields.get("progress_stage") or desired_terminal, desired_terminal))
        fields.setdefault("completed_steps", subdub_completed_steps_for_lifecycle(fields.get("progress_stage") or desired_terminal, desired_terminal))
        if desired_terminal == "delivered":
            fields.update({
                "status": "completed",
                "lifecycle_state": "delivered",
                "current_stage": "delivered",
                "progress_stage": "delivered",
                "progress_percent": 100,
                "completed_steps": subdub_completed_steps_for_lifecycle("delivered", "delivered"),
            })
        elif desired_terminal in {"failed_no_charge", "failed_refunded", "needs_admin_review"}:
            fields["status"] = desired_terminal
    job.update(fields)
    job = subdub_normalize_input_save_failed_terminal(job)
    job = subdub_enrich_job_identity(job, job_key=str(job_key or ""), mode=str(job.get("mode") or fields.get("mode") or ""), state=job)
    job["updated_at"] = time.time()
    SUBTITLE_DUB_PIPELINE_JOBS[str(job_key or "")] = job
    persist_subtitle_dub_pipeline_job_snapshot(str(job_key or ""), job, reason="pipeline_job_update")
    return dict(job)

def persist_subtitle_dub_pipeline_job_snapshot(job_key: str, job: dict | None = None, *, reason: str = "") -> bool:
    current = subdub_normalize_input_save_failed_terminal(
        subdub_enrich_job_identity(job or {}, job_key=str(job_key or ""))
    )
    if not current:
        return False
    job_id = str(current.get("internal_job_id") or current.get("job_id") or current.get("registry_job_id") or "").strip()
    if not job_id:
        return False
    terminal_state = str(current.get("terminal_state") or "").strip().lower()
    status = str(current.get("status") or "").strip().lower() or "running"
    if terminal_state in {"failed_no_charge", "failed_refunded", "delivered", "needs_admin_review"}:
        status = terminal_state
    output_bytes = _safe_int(
        current.get("output_bytes")
        or current.get("final_mp4_size")
        or current.get("video_bytes")
        or current.get("audio_bytes")
        or 0,
        0,
    )
    provider_task_id = str(current.get("provider_task_id") or current.get("provider_job_id") or f"subdub:{job_id}").strip()
    public_code = str(current.get("public_code") or subdub_public_code_value(current.get("job_id") or job_id))
    progress_public_code = str(current.get("progress_public_code") or (f"#{public_code}" if public_code else ""))
    payload = {
        **current,
        "feature": "subtitle_dub",
        "internal_job_id": job_id,
        "job_id": str(current.get("job_id") or job_id),
        "public_code": public_code,
        "public_job_id": str(current.get("public_job_id") or public_code),
        "subdub_public_job_id": str(current.get("subdub_public_job_id") or public_code),
        "progress_public_code": progress_public_code,
        "mapped_product_type": str(current.get("mapped_product_type") or current.get("product_type") or ""),
        "mapped_mode": str(current.get("mapped_mode") or current.get("mode") or ""),
        "provider": str(current.get("provider") or "subtitle_dub_product_pipeline"),
        "provider_task_id": provider_task_id,
        "status": status,
        "output_bytes": output_bytes,
        "progress_text": str(current.get("progress_text") or current.get("progress_stage") or current.get("current_stage") or status),
        "last_provider_status": str(current.get("last_provider_status") or current.get("pipeline_blocker") or reason or status),
        "error_category": str(current.get("error_category") or current.get("pipeline_blocker") or ""),
    }
    if job_key:
        payload["job_key"] = str(job_key)
    try:
        save_engine_async_job(payload)
        return True
    except Exception as exc:
        logger.warning("subtitle/dub pipeline snapshot persist failed | %s", sanitize_log_text(str(exc))[:180])
        return False

def mark_subtitle_dub_pipeline_output_sent(
    job_key: str,
    *,
    terminal_state: str = "delivered",
    delivery_message_id: str = "",
    success_message_id: str = "",
    terminal_artifact_type: str = "",
    video_delivery_message_id: str = "",
    audio_delivery_message_id: str = "",
    srt_delivery_message_id: str = "",
) -> bool:
    job = dict(SUBTITLE_DUB_PIPELINE_JOBS.get(str(job_key or "")) or {})
    if not job or job.get("output_sent"):
        if job:
            job["duplicate_delivery_prevented"] = True
            subdub_record_duplicate_terminal(str(job_key or ""), job, outcome="success", reason="output_already_sent")
            persist_subtitle_dub_pipeline_job_snapshot(str(job_key or ""), job, reason="duplicate_delivery_prevented")
        return False
    desired_terminal = str(terminal_state or "delivered").strip().lower()
    if desired_terminal not in SUBDUB_TERMINAL_STATES:
        desired_terminal = "delivered"
    current_terminal = str(job.get("terminal_state") or "")
    artifact_type = str(terminal_artifact_type or ("video" if video_delivery_message_id else "")).strip().lower()
    partial_audio_terminal = bool(
        artifact_type == "audio_fallback"
        or (
            audio_delivery_message_id
            and not video_delivery_message_id
            and desired_terminal != "delivered"
        )
    )
    requires_final_mp4 = subdub_video_requires_final_mp4(
        str(job.get("mode") or job.get("mapped_mode") or ""),
        str(job.get("product_type") or job.get("mapped_product_type") or ""),
    )
    if partial_audio_terminal and requires_final_mp4 and not SUBDUB_PUBLIC_AUDIO_FALLBACK_ENABLED:
        job["success_blocked_reason"] = "missing_valid_delivered_mp4"
        job["audio_fallback_public_enabled"] = False
        job["audio_fallback_suppressed"] = True
        job["audio_artifact_internal_only"] = True
        job["partial_audio_available"] = True
        job["partial_audio_delivered"] = False
        job["full_video_failed"] = True
        job["terminal_public_outcome_type"] = "failure"
        job["terminal_state"] = "failed_no_charge"
        job["status"] = "failed_no_charge"
        job["lifecycle_state"] = "failed_no_charge"
        job["current_stage"] = "failed_no_charge"
        job["progress_stage"] = "failed_no_charge"
        job["progress_percent"] = subdub_progress_percent_for_lifecycle("failed_no_charge", "failed_no_charge")
        job["completed_steps"] = subdub_completed_steps_for_lifecycle("failed_no_charge", "failed_no_charge")
        job["charge_status"] = "not_charged"
        job["charged_xu"] = 0
        subdub_record_duplicate_terminal(str(job_key or ""), job, outcome="success", reason="audio_fallback_public_disabled")
        persist_subtitle_dub_pipeline_job_snapshot(str(job_key or ""), job, reason="audio_fallback_public_disabled")
        return False
    if partial_audio_terminal:
        desired_terminal = "needs_admin_review"
        if subdub_job_has_failure_public_outcome(job):
            job["partial_audio_after_failure_prevented"] = True
            job["duplicate_delivery_prevented"] = True
            subdub_record_duplicate_terminal(str(job_key or ""), job, outcome="success", reason="partial_audio_after_failure_public_outcome")
            persist_subtitle_dub_pipeline_job_snapshot(str(job_key or ""), job, reason="partial_audio_after_failure_prevented")
            return False
    existing_video_delivery = str(job.get("video_delivery_message_id") or "").strip()
    if desired_terminal == "delivered" and requires_final_mp4 and not (video_delivery_message_id or existing_video_delivery):
        job["success_blocked_reason"] = "missing_valid_delivered_mp4"
        job["duplicate_delivery_prevented"] = True
        job["output_validated_before_success"] = False
        job["delivery_confirmed_before_success"] = False
        job["final_mp4_delivered"] = False
        job["terminal_public_outcome_type"] = "failure"
        job["terminal_state"] = "failed_no_charge"
        job["status"] = "failed_no_charge"
        job["lifecycle_state"] = "failed_no_charge"
        job["current_stage"] = "failed_no_charge"
        job["progress_stage"] = "failed_no_charge"
        job["progress_percent"] = subdub_progress_percent_for_lifecycle("failed_no_charge", "failed_no_charge")
        job["completed_steps"] = subdub_completed_steps_for_lifecycle("failed_no_charge", "failed_no_charge")
        job["charge_status"] = "not_charged"
        job["charged_xu"] = 0
        subdub_record_duplicate_terminal(str(job_key or ""), job, outcome="success", reason="missing_valid_delivered_mp4")
        persist_subtitle_dub_pipeline_job_snapshot(str(job_key or ""), job, reason="success_blocked_missing_valid_delivered_mp4")
        return False
    if desired_terminal == "delivered" and not subdub_public_outcome_allows_success(job):
        job["success_after_error_prevented"] = True
        job["duplicate_delivery_prevented"] = True
        subdub_record_duplicate_terminal(str(job_key or ""), job, outcome="success", reason="failure_public_outcome_already_sent")
        persist_subtitle_dub_pipeline_job_snapshot(str(job_key or ""), job, reason="success_after_error_prevented")
        return False
    if current_terminal and not subdub_terminal_state_allows_transition(current_terminal, desired_terminal):
        job["duplicate_delivery_prevented"] = True
        subdub_record_duplicate_terminal(str(job_key or ""), job, outcome="success", reason="terminal_transition_blocked")
        persist_subtitle_dub_pipeline_job_snapshot(str(job_key or ""), job, reason="terminal_transition_blocked")
        return False
    job["output_sent"] = True
    job["output_validated"] = True
    job["delivery_attempted"] = True
    job["delivery_started"] = True
    job["delivery_attempt_count"] = int(job.get("delivery_attempt_count") or 0) + 1
    job["subdub_delivery_started_at"] = job.get("subdub_delivery_started_at") or time.time()
    if delivery_message_id:
        job["subdub_delivery_message_id"] = str(delivery_message_id)
    if video_delivery_message_id:
        job["video_delivery_message_id"] = str(video_delivery_message_id)
    if audio_delivery_message_id:
        job["audio_delivery_message_id"] = str(audio_delivery_message_id)
    if srt_delivery_message_id:
        job["srt_delivery_message_id"] = str(srt_delivery_message_id)
    if success_message_id:
        job["subdub_success_message_id"] = str(success_message_id)
    if artifact_type:
        job["terminal_artifact_type"] = artifact_type[:80]
    if desired_terminal == "delivered":
        delivered_at = time.time()
        job["subdub_delivered_at"] = delivered_at
        job["delivered_at"] = delivered_at
    locked_at = time.time()
    job["subdub_terminal_locked_at"] = locked_at
    job["terminal_locked_at"] = locked_at
    history = list(job.get("terminal_state_history") or [])
    if current_terminal != desired_terminal:
        history.append({"from": current_terminal, "to": desired_terminal, "at": time.time()})
    job["terminal_state_history"] = history[-12:]
    job["terminal_state"] = desired_terminal
    job["lifecycle_state"] = "delivered" if desired_terminal == "delivered" else desired_terminal
    job["current_stage"] = "delivered" if desired_terminal == "delivered" else desired_terminal
    job["progress_stage"] = job["current_stage"]
    job["progress_percent"] = subdub_progress_percent_for_lifecycle(job["current_stage"], desired_terminal)
    job["completed_steps"] = subdub_completed_steps_for_lifecycle(job["current_stage"], desired_terminal)
    job["status"] = "completed" if desired_terminal == "delivered" else str(job.get("status") or "")
    job["delivery_message_id"] = str(delivery_message_id or video_delivery_message_id or audio_delivery_message_id or srt_delivery_message_id or job.get("delivery_message_id") or "")
    job["delivery_success"] = bool(job.get("delivery_message_id"))
    job["delivery_succeeded"] = bool(job.get("delivery_succeeded") and not partial_audio_terminal)
    job["validation_started"] = True
    job["validation_passed"] = True
    job["output_validated_before_success"] = True
    job["delivery_confirmed_before_success"] = bool(job.get("delivery_message_id"))
    job["terminal_public_outcome_sent"] = True
    job["terminal_public_outcome_type"] = "partial_audio_delivered" if partial_audio_terminal else ("success" if desired_terminal == "delivered" else desired_terminal)
    job["terminal_public_outcome_message_id"] = str(success_message_id or job.get("delivery_message_id") or "")
    video_success_terminal = bool(
        not partial_audio_terminal
        and desired_terminal == "delivered"
        and (artifact_type == "video" or video_delivery_message_id or requires_final_mp4)
    )
    if video_success_terminal:
        final_video_message_id = str(video_delivery_message_id or delivery_message_id or job.get("video_delivery_message_id") or job.get("delivery_message_id") or "")
        job["delivery_succeeded"] = True
        job["public_success_sent"] = True
        job["public_failure_sent"] = False
        job["public_error_sent"] = False
        job["final_video_message_id"] = final_video_message_id
        job["subdub_final_video_message_id"] = final_video_message_id
        job["final_mp4_exists"] = True
        job["final_mp4_validated"] = True
        job["final_mp4_delivered"] = True
        job["full_video_failed"] = False
        job["success_blocked_reason"] = ""
    job["success_sent_count"] = 0 if partial_audio_terminal else max(1, int(job.get("success_sent_count") or 0))
    job["partial_audio_available"] = bool(partial_audio_terminal)
    job["partial_audio_delivered"] = bool(partial_audio_terminal and audio_delivery_message_id)
    job["partial_audio_message_id"] = str(audio_delivery_message_id or "") if partial_audio_terminal else str(job.get("partial_audio_message_id") or "")
    job["full_video_failed"] = bool(partial_audio_terminal)
    if partial_audio_terminal:
        job["charge_status"] = "not_charged_partial_audio"
        job["charged_xu"] = 0
    job["late_fail_suppressed"] = desired_terminal == "delivered" or partial_audio_terminal
    job["error_sent_after_delivery"] = False
    job["panel_finalized"] = True
    job["panel_final_percent"] = int(job.get("progress_percent") or 0)
    job["panel_final_message_id"] = str(job.get("status_panel_message_id") or "")
    job["status_panel_terminalized"] = True
    job["refresh_stopped_after_terminal"] = True
    job["charge_after_delivery"] = bool(int(job.get("charged_xu") or 0) > 0 and job.get("delivery_message_id") and not partial_audio_terminal)
    job["cost_line_rendered"] = False if partial_audio_terminal else bool(int(job.get("charged_xu") or 0) >= 0)
    job["success_cost_line"] = "" if partial_audio_terminal else subdub_success_cost_line(job.get("charged_xu") or 0)
    job["cost_line_reason"] = "partial_audio_no_full_video_charge" if partial_audio_terminal else ("after_delivery" if job.get("delivery_message_id") else "delivery_message_missing")
    job["updated_at"] = time.time()
    SUBTITLE_DUB_PIPELINE_JOBS[str(job_key or "")] = job
    persist_subtitle_dub_pipeline_job_snapshot(str(job_key or ""), job, reason="pipeline_output_sent")
    return True

def create_subtitle_dub_pipeline_workspace(job_id: str) -> str:
    root = os.path.abspath(PIPELINE_TEMP_ROOT)
    safe_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(job_id or "job")).strip("._") or "job"
    workspace = os.path.abspath(os.path.join(root, safe_id))
    if not workspace.startswith(root + os.sep):
        raise RuntimeError("unsafe_pipeline_workspace")
    os.makedirs(workspace, exist_ok=True)
    return workspace

def cleanup_subtitle_dub_pipeline_workspace(workspace: str) -> bool:
    result = cleanup_subtitle_dub_pipeline_workspace_result(workspace)
    return bool(result.get("deleted") or result.get("already_missing"))

def cleanup_subtitle_dub_pipeline_workspace_result(workspace: str) -> dict:
    safety = subtitle_dub_workspace_path_safety(workspace)
    result = {
        "attempted": False,
        "deleted": False,
        "already_missing": False,
        "skipped": False,
        "blocked": not bool(safety.get("allowed")),
        "error_type": str(safety.get("error_type") or ""),
        "error_message": str(safety.get("error_message") or ""),
        "original_path": str(safety.get("original_path") or ""),
        "resolved_path": str(safety.get("resolved_path") or ""),
        "allowed_root": str(safety.get("allowed_root") or ""),
        "blocked_reason": str(safety.get("blocked_reason") or ""),
    }
    if not safety.get("allowed"):
        result["skipped"] = True
        return result
    original_path = str(safety.get("original_path") or "")
    if not os.path.lexists(original_path):
        result["already_missing"] = True
        return result
    result["attempted"] = True
    try:
        if safety.get("is_symlink"):
            os.unlink(original_path)
        elif safety.get("is_junction"):
            os.rmdir(original_path)
        else:
            shutil.rmtree(original_path)
    except FileNotFoundError:
        result["already_missing"] = True
    except PermissionError as exc:
        result["error_type"] = "PermissionError"
        result["error_message"] = sanitize_log_text(str(exc))[:300]
    except OSError as exc:
        result["error_type"] = type(exc).__name__
        result["error_message"] = sanitize_log_text(str(exc))[:300]
    if not result.get("error_type") and not os.path.lexists(original_path):
        result["deleted"] = not result.get("already_missing")
    elif not result.get("error_type") and os.path.lexists(original_path):
        result["error_type"] = "WorkspaceStillExists"
        result["error_message"] = "workspace still exists after cleanup attempt"
    return result

def cleanup_stale_subtitle_dub_pipeline_workspaces(now_ts: float | None = None) -> int:
    root_safety = Path(PIPELINE_TEMP_ROOT).resolve(strict=False)
    if not root_safety.is_dir():
        return 0
    owned_workspaces = {
        str(Path(str(job.get("workspace") or "")).resolve(strict=False))
        for job in SUBTITLE_DUB_PIPELINE_JOBS.values()
        if job.get("workspace")
    }
    current_ts = float(now_ts or time.time())
    cleaned = 0
    try:
        entries = list(root_safety.iterdir())
    except OSError as exc:
        logger.warning("subtitle/dub orphan workspace scan failed | %s", sanitize_log_text(str(exc))[:180])
        return 0
    for entry in entries:
        path = str(entry)
        try:
            resolved = str(entry.resolve(strict=False))
        except (OSError, RuntimeError):
            resolved = path
        if resolved in owned_workspaces or not (entry.is_dir() or entry.is_symlink()):
            continue
        try:
            stale = current_ts - os.path.getmtime(path) > PIPELINE_JOB_LOCK_TTL_SECONDS
        except OSError:
            continue
        if not stale:
            continue
        result = cleanup_subtitle_dub_pipeline_workspace_result(path)
        if result.get("deleted") or result.get("already_missing"):
            cleaned += 1
        elif result.get("blocked") or result.get("error_type"):
            logger.warning(
                "subtitle/dub orphan workspace cleanup blocked | reason=%s | error=%s",
                sanitize_log_text(str(result.get("blocked_reason") or ""))[:120],
                sanitize_log_text(str(result.get("error_type") or ""))[:120],
            )
    return cleaned

def write_subtitle_dub_pipeline_manifest(workspace: str, payload: dict) -> str:
    path = os.path.abspath(os.path.join(workspace, "manifest.json"))
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, ensure_ascii=False, indent=2)
    return path

def write_subtitle_dub_pipeline_artifact(workspace: str, filename: str, data: bytes) -> str:
    if not data:
        return ""
    root = os.path.abspath(str(workspace or ""))
    safe_name = re.sub(r"[^A-Za-z0-9_.-]+", "_", os.path.basename(str(filename or "artifact.bin")))
    safe_name = safe_name.strip("._") or "artifact.bin"
    path = os.path.abspath(os.path.join(root, safe_name))
    if not root or not path.startswith(root + os.sep):
        raise RuntimeError("unsafe_pipeline_artifact")
    with open(path, "wb") as handle:
        handle.write(bytes(data))
    return path

def video_dubbing_sync_state_fields(state: dict | None = None, *, exclude: set[str] | None = None) -> dict:
    skipped = {
        "step",
        "current_step",
        "previous_step",
        "pending_action",
        "created_at_ts",
        *(exclude or set()),
    }
    return {
        key: value for key, value in dict(state or {}).items()
        if key not in skipped
        and not str(key).startswith("_pipeline_")
        and not isinstance(value, (bytes, bytearray))
    }

def subdub_telegram_file_too_big(detail: str = "") -> bool:
    normalized = str(detail or "").strip().lower()
    if not normalized:
        return False
    markers = (
        "file is too big",
        "file too big",
        "request entity too large",
        "telegram_download_failed:file is too big",
        "bad request: file is too big",
    )
    return any(marker in normalized for marker in markers)

def subdub_telegram_api_base_unreachable(detail: str = "") -> bool:
    """INFRA.LOCALBOTAPI: the configured Bot API base could not be reached.

    Only meaningful when a local Bot API server is configured; on the cloud
    endpoint these same markers are ordinary transient network errors.
    """
    normalized = str(detail or "").strip().lower()
    if not normalized:
        return False
    markers = (
        "telegram_download_failed:network",
        "telegram_download_failed:timeout",
        "connecterror",
        "connect error",
        "connection refused",
        "name or service not known",
        "temporary failure in name resolution",
        "ssl",
        "bad gateway",
        "502",
        "503",
        "504",
    )
    return any(marker in normalized for marker in markers)

def subdub_download_failure_public_text(lang: str = "vi") -> str:
    if normalize_user_language(lang) != "vi":
        return (
            "⚠️ TOAN AAS could not fetch the video from Telegram right now.\n"
            "No Xu was charged. Please send the video again."
        )
    return (
        "⚠️ TOAN AAS chưa tải được video từ Telegram lúc này.\n"
        "Hệ thống chưa trừ Xu. Anh/chị vui lòng gửi lại giúp em."
    )


def subdub_large_telegram_media_public_text(lang: str = "vi") -> str:
    limit_mb = int(SUBDUB_TELEGRAM_DOWNLOAD_LIMIT_MB)
    if normalize_user_language(lang) != "vi":
        return (
            f"Telegram direct download currently supports files up to {limit_mb} MB for this workflow.\n"
            "No Xu was charged.\n"
            "Please send a smaller file or use a supported upload source."
        )
    return (
        "TOAN AAS chưa tải trực tiếp được file này từ Telegram; chưa tải được video này vì file quá lớn hoặc Telegram chưa cho hệ thống tải trực tiếp.\n"
        f"Giới hạn tải trực tiếp hiện tại cho luồng này là {limit_mb} MB.\n"
        "Hệ thống chưa trừ Xu.\n"
        "Anh/chị vui lòng gửi file nhỏ hơn hoặc dùng nguồn tải được hỗ trợ."
    )

def subdub_input_save_failure_public_text(input_save: dict | None = None, lang: str = "vi") -> str:
    item = dict(input_save or {})
    detail = str(item.get("detail") or item.get("input_save_blocker") or item.get("error") or "")
    if (
        item.get("telegram_download_limit_hit")
        or str(item.get("input_save_blocker") or "") == "large_telegram_download_unsupported"
        or subdub_telegram_file_too_big(detail)
    ):
        return subdub_large_telegram_media_public_text(lang)
    # INFRA.LOCALBOTAPI degraded mode: the configured Bot API base is down.
    # Never leak the endpoint; never charge; never silently retry the cloud.
    if str(item.get("input_save_blocker") or "") == "telegram_api_base_unreachable":
        return subdub_download_failure_public_text(lang)
    return ""

def subdub_input_save_debug_fields(input_save: dict | None = None, state: dict | None = None) -> dict:
    item = dict(input_save or {})
    state = dict(state or {})
    detail = str(item.get("detail") or item.get("error") or "")
    file_size = _safe_int(
        item.get("telegram_file_size")
        or state.get("video_file_size")
        or state.get("source_file_size")
        or item.get("size"),
        0,
    )
    method = str(item.get("telegram_download_method") or ("source_bytes_override" if item.get("source_bytes") else "bot_api_direct"))
    limit_hit = bool(item.get("telegram_download_limit_hit") or subdub_telegram_file_too_big(detail))
    supported_source = str(item.get("large_media_intake_source") or "")
    # INFRA.LOCALBOTAPI: a configured local Bot API server is itself a large
    # media intake source, so report it truthfully even for plain bot_api_direct.
    if not supported_source and telegram_local_api_enabled() and method == "bot_api_direct":
        supported_source = "local_bot_api"
    supported = bool(
        item.get("large_media_intake_supported")
        or supported_source in {"source_bytes_override", "local_path_override", "local_bot_api"}
    )
    blocker = str(item.get("input_save_blocker") or "")
    if not blocker:
        if limit_hit and not supported:
            blocker = "large_telegram_download_unsupported"
        elif not item.get("file_saved"):
            blocker = str(item.get("detail") or "file_not_saved")
    action = str(item.get("input_save_public_action") or "")
    if not action and blocker == "large_telegram_download_unsupported":
        action = "send_smaller_or_supported_upload"
    no_charge_reason = str(item.get("no_charge_reason") or "")
    if not no_charge_reason and not item.get("ok"):
        no_charge_reason = blocker or "input_save_failed"
    return {
        "input_save_attempted": True,
        "input_save_success": bool(item.get("ok") and item.get("file_saved") and item.get("exists") and int(item.get("size") or 0) > 0),
        "telegram_file_size": file_size,
        "input_size_bytes": file_size,
        "input_download_limit_bytes": int(SUBDUB_TELEGRAM_DOWNLOAD_LIMIT_MB) * 1024 * 1024,
        "output_delivery_limit_bytes": max(
            subdub_output_delivery_limit_mb("video"),
            subdub_output_delivery_limit_mb("document"),
        ) * 1024 * 1024,
        "duration_policy_limit_seconds": subdub_full_duration_limit_seconds(bool(state.get("_pipeline_is_admin"))),
        "duration_limit_blocker": "",
        "size_limit_blocker": "telegram_direct_download_over_limit" if limit_hit and not supported else "",
        "telegram_download_method": method,
        "telegram_api_source": str(item.get("telegram_api_source") or telegram_api_source_label()),
        "telegram_download_limit_hit": limit_hit,
        "large_telegram_media_detected": bool(
            limit_hit
            or item.get("large_telegram_media_detected")
            or file_size > SUBDUB_LARGE_MEDIA_DETECTED_THRESHOLD_BYTES
        ),
        "large_media_intake_supported": supported,
        "large_media_intake_source": supported_source or ("source_bytes_override" if method == "source_bytes_override" else ""),
        "input_save_blocker": blocker,
        "input_save_public_action": action,
        "no_charge_reason": no_charge_reason,
    }

async def video_dubbing_save_input_for_pipeline(
    context: ContextTypes.DEFAULT_TYPE,
    state: dict,
    workspace: str = "",
) -> dict:
    state = dict(state or {})
    result = {
        "ok": False,
        "file_id": str(state.get("video_file_id") or state.get("source_file_id") or ""),
        "path": "",
        "exists": False,
        "size": 0,
        "transport_input_size": 0,
        "duration": _safe_int(state.get("video_duration") or state.get("source_duration"), 0),
        "content_type": str(state.get("source_mime_type") or "video/mp4"),
        "original_filename": str(state.get("source_file_name") or "source.mp4"),
        "file_saved": False,
        "error": "",
        "detail": "",
        "source_bytes": b"",
        "input_save_attempted": True,
        "input_save_success": False,
        "telegram_file_size": _safe_int(state.get("video_file_size") or state.get("source_file_size"), 0),
        "telegram_download_method": "",
        "telegram_api_source": telegram_api_source_label(),
        "telegram_download_limit_hit": False,
        "large_telegram_media_detected": False,
        "large_media_intake_supported": False,
        "large_media_intake_source": "",
        "input_save_blocker": "",
        "input_save_public_action": "",
        "no_charge_reason": "",
    }
    source_bytes = state.get("_pipeline_source_bytes_override")
    if isinstance(source_bytes, bytearray):
        source_bytes = bytes(source_bytes)
    if not isinstance(source_bytes, bytes):
        source_bytes = b""
    content_type = str(state.get("_pipeline_source_content_type_override") or result["content_type"])
    if source_bytes:
        max_input_bytes = subdub_input_limit_mb(
            bool(state.get("_pipeline_is_admin")),
            intake_method="source_bytes_override",
        ) * 1024 * 1024
        if len(source_bytes) > max_input_bytes:
            result.update({
                "error": "RuntimeError",
                "detail": "video_too_large",
                "content_type": content_type,
                "telegram_download_method": "source_bytes_override",
                "large_media_intake_supported": True,
                "large_media_intake_source": "source_bytes_override",
                "input_save_blocker": "video_too_large",
                "no_charge_reason": "video_too_large",
            })
            return result
        result.update({
            "telegram_download_method": "source_bytes_override",
            "large_media_intake_supported": True,
            "large_media_intake_source": "source_bytes_override",
        })
    if not source_bytes:
        source_path_override = str(
            state.get("_pipeline_source_path_override")
            or state.get("_pipeline_large_media_local_path")
            or state.get("input_file_path")
            or state.get("saved_input_path")
            or state.get("source_local_path")
            or ""
        ).strip()
        if source_path_override and os.path.exists(source_path_override) and os.path.isfile(source_path_override):
            source_size = os.path.getsize(source_path_override)
            max_input_mb = subdub_input_limit_mb(
                bool(state.get("_pipeline_is_admin")),
                intake_method="local_path_override",
            )
            if source_size > max_input_mb * 1024 * 1024:
                result.update({
                    "error": "RuntimeError",
                    "detail": "video_too_large",
                    "content_type": content_type,
                    "telegram_download_method": "local_path_override",
                    "large_media_intake_supported": True,
                    "large_media_intake_source": "local_path_override",
                    "input_save_blocker": "video_too_large",
                    "no_charge_reason": "video_too_large",
                })
                return result
            with open(source_path_override, "rb") as handle:
                source_bytes = handle.read()
            result.update({
                "telegram_download_method": "local_path_override",
                "large_media_intake_supported": True,
                "large_media_intake_source": "local_path_override",
                "original_filename": str(state.get("source_file_name") or os.path.basename(source_path_override) or "source.mp4"),
            })
    if not source_bytes:
        if not result["file_id"]:
            result.update({
                "error": "RuntimeError",
                "detail": "missing_video_file_id",
                "content_type": content_type,
                "telegram_download_method": "missing_file_id",
                "input_save_blocker": "missing_video_file_id",
                "no_charge_reason": "missing_video_file_id",
            })
            return result
        local_api = telegram_local_api_enabled()
        try:
            source_bytes, content_type = await video_dubbing_download_source(context, state)
        except Exception as exc:
            safe_detail = sanitize_log_text(str(exc))[:140]
            limit_hit = subdub_telegram_file_too_big(safe_detail)
            # INFRA.LOCALBOTAPI: with a local Bot API server the large-media
            # intake path DOES exist, so an oversize file is an honest
            # "video_too_large", not "the bot cannot fetch large media at all".
            # A dead local server must never silently fall back to the cloud
            # endpoint (the token is logged out of it) - it degrades instead.
            if limit_hit:
                blocker = "video_too_large" if local_api else "large_telegram_download_unsupported"
            elif local_api and subdub_telegram_api_base_unreachable(safe_detail):
                blocker = "telegram_api_base_unreachable"
            else:
                blocker = "telegram_download_failed"
            result.update({
                "error": type(exc).__name__,
                "detail": "telegram_download_failed:" + safe_detail,
                "content_type": content_type,
                "telegram_download_method": "bot_api_direct",
                "telegram_api_source": telegram_api_source_label(),
                "telegram_download_limit_hit": limit_hit,
                "large_telegram_media_detected": limit_hit,
                "large_media_intake_supported": local_api,
                "large_media_intake_source": "local_bot_api" if local_api else "",
                "input_save_blocker": blocker,
                "input_save_public_action": "send_smaller_or_supported_upload" if limit_hit else "",
                "no_charge_reason": blocker,
            })
            return result
        else:
            result.update({
                "telegram_download_method": "bot_api_direct",
                "telegram_api_source": telegram_api_source_label(),
                "large_media_intake_supported": local_api,
                "large_media_intake_source": "local_bot_api" if local_api else "",
            })
    if not source_bytes:
        result.update({
            "error": "RuntimeError",
            "detail": "file_not_saved",
            "content_type": content_type,
            "input_save_blocker": "file_not_saved",
            "no_charge_reason": "file_not_saved",
        })
        return result
    result.update({
        "ok": True,
        "source_bytes": bytes(source_bytes),
        "content_type": str(content_type or result["content_type"]),
        "size": len(source_bytes),
        "transport_input_size": len(source_bytes),
        "input_save_success": True,
    })
    if workspace and source_bytes:
        source_name = os.path.basename(str(state.get("source_file_name") or "source.mp4")) or "source.mp4"
        try:
            source_path = write_subtitle_dub_pipeline_artifact(workspace, source_name, source_bytes)
        except Exception as exc:
            result.update({
                "ok": False,
                "error": type(exc).__name__,
                "detail": sanitize_log_text(str(exc))[:180],
                "input_save_success": False,
                "input_save_blocker": "file_not_saved",
                "no_charge_reason": "file_not_saved",
            })
            return result
        result.update({
            "path": source_path,
            "exists": bool(source_path and os.path.exists(source_path)),
            "file_saved": bool(source_path and os.path.exists(source_path) and os.path.getsize(source_path) > 0),
        })
    if not result.get("file_saved"):
        result.update({
            "ok": False,
            "error": "RuntimeError",
            "detail": "file_not_saved",
            "input_save_success": False,
            "input_save_blocker": "file_not_saved",
            "no_charge_reason": "file_not_saved",
        })
    else:
        result.update(subdub_input_save_debug_fields(result, state))
    return result

def video_dubbing_product_gate_matrix(
    user_id,
    mode: str,
    state: dict | None = None,
    *,
    access: dict | None = None,
    input_save: dict | None = None,
) -> dict:
    state = dict(state or {})
    mode = normalize_video_translate_mode(mode)
    access = dict(access or {})
    confirmed_product = bool(
        subdub_final_confirmed_state(state)
        or access.get("confirmed_product")
        or dict(access.get("readiness") or {}).get("confirmed_product")
    )
    wants_video_output = mode in {
        VIDEO_SUBTITLE_MODE_CREATE,
        VIDEO_SUBTITLE_MODE_TRANSLATE,
        VIDEO_SUBTITLE_MODE_DUB,
        VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
    } and str(state.get("source_mime_type") or "video/mp4").lower().startswith("video/")
    ffmpeg_status = resolve_media_binary("ffmpeg") if wants_video_output else {}
    ffprobe_status = resolve_media_binary("ffprobe") if wants_video_output else {}
    ffmpeg_path = str(ffmpeg_status.get("resolved_path") or "")
    ffprobe_path = str(ffprobe_status.get("resolved_path") or "")
    ffmpeg_available = bool(ffmpeg_path and ffmpeg_status.get("version_probe_ok"))
    ffprobe_available = bool(ffprobe_path and ffprobe_status.get("version_probe_ok"))
    media_prerequisites_ready = bool(not wants_video_output or (ffmpeg_available and ffprobe_available))
    try:
        asr_readiness = get_asr_adapter_readiness(
            public=False,
            audio_extract_ready=ffmpeg_available if wants_video_output else True,
        )
    except TypeError:
        asr_readiness = get_asr_adapter_readiness(public=False)
    product_is_admin = bool(is_admin_user(user_id))
    configured = video_dubbing_configured_readiness(
        mode,
        state,
        public=not product_is_admin,
        asr_readiness=asr_readiness,
        admin_interactive_confirm=bool(product_is_admin and access.get("allowed")),
        confirmed_product=confirmed_product,
    )
    readiness = dict(
        access.get("readiness")
        or {"reason": configured.get("reason") or "ready", "public_blockers": []}
    )
    configured_missing = list(dict.fromkeys(str(item) for item in (configured.get("missing") or []) if str(item or "").strip()))
    asr_enabled = bool(
        not video_dubbing_mode_needs_asr_provider(mode, state)
        or asr_readiness.get("configured")
    )
    translation_enabled = bool(
        not video_dubbing_needs_translation_provider(mode, state)
        or video_translation_provider_configured()
    )
    tts_enabled = bool(
        mode not in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}
        or video_tts_provider_configured_for_dub()
    )
    technical_missing = list(configured_missing)
    if not asr_enabled and "asr" not in technical_missing:
        technical_missing.append("asr")
    if not translation_enabled and "translation" not in technical_missing:
        technical_missing.append("translation")
    if not tts_enabled and "tts" not in technical_missing:
        technical_missing.append("tts")
    if wants_video_output and not ffmpeg_available and "ffmpeg" not in technical_missing:
        technical_missing.append("ffmpeg")
    if wants_video_output and not ffprobe_available and "ffprobe" not in technical_missing:
        technical_missing.append("ffprobe")
    product_config_ready = not bool(technical_missing)
    access_status = str(access.get("status") or "")
    access_reason = str(access.get("reason") or "").strip()
    if not access_reason or (access_status.startswith("blocked") and access_reason == "ready"):
        blocked_fallback = ",".join(technical_missing) if access_status.startswith("blocked") else ""
        access_reason = blocked_fallback or str(readiness.get("reason") or configured.get("reason") or "")
        if access_status.startswith("blocked") and (not access_reason or access_reason == "ready"):
            access_reason = "provider_not_configured"
    gate_reason = ":".join(
        item for item in (access_status, access_reason) if item
    )
    input_save = dict(input_save or {})
    input_ready = bool(
        input_save.get("file_saved")
        and input_save.get("exists")
        and int(input_save.get("size") or 0) > 0
    )
    session_present = bool(
        mode in {
            VIDEO_SUBTITLE_MODE_CREATE,
            VIDEO_SUBTITLE_MODE_TRANSLATE,
            VIDEO_SUBTITLE_MODE_DUB,
            VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        }
        and (
            state.get("active_flow")
            or state.get("video_processing_mode")
            or state.get("process_type")
            or state.get("mode")
        )
    )
    product_route_allowed = bool(session_present and input_ready)
    blocker_names = {
        "asr": "asr_missing",
        "translation": "translation_missing",
        "tts": "tts_missing",
        "ffmpeg": "ffmpeg_missing",
        "ffprobe": "ffprobe_missing",
        "mode": "unsupported_input",
        "maintenance": "product_route_not_allowed",
        "lane_closed": "product_route_not_allowed",
    }
    gate_blockers = list(dict.fromkeys(
        blocker_names.get(item, "provider_key_missing") for item in technical_missing
    ))
    if not input_ready:
        gate_blockers.insert(0, "file_not_saved")
    if not session_present:
        gate_blockers.insert(0, "product_route_not_allowed")
    return {
        "product_route_allowed": product_route_allowed,
        "product_config_ready": bool(product_config_ready),
        "blackbox_enabled": bool(product_route_allowed and product_config_ready),
        "asr_enabled": bool(asr_enabled),
        "translation_enabled": bool(translation_enabled),
        "tts_enabled": bool(tts_enabled),
        "ffmpeg_available": ffmpeg_available,
        "ffmpeg_path": ffmpeg_path,
        "ffmpeg_version_probe_ok": bool(ffmpeg_status.get("version_probe_ok")),
        "ffmpeg_resolution_source": str(ffmpeg_status.get("source") or "not_required"),
        "ffprobe_available": ffprobe_available,
        "ffprobe_path": ffprobe_path,
        "ffprobe_version_probe_ok": bool(ffprobe_status.get("version_probe_ok")),
        "ffprobe_resolution_source": str(ffprobe_status.get("source") or "not_required"),
        "media_prerequisites_required": bool(wants_video_output),
        "media_prerequisites_ready": media_prerequisites_ready,
        "mux_enabled": bool(ffmpeg_available and ffprobe_available),
        "provider_gate_reason": gate_reason or "ready",
        "technical_missing": technical_missing,
        "gate_blockers": gate_blockers,
        "public_blockers": list(readiness.get("public_blockers") or []),
        "access_status": str(access.get("status") or ""),
        "access_allowed": bool(access.get("allowed")),
        "confirmed_product": confirmed_product,
        "gate_overridden_for_product": bool(not access.get("allowed") and product_route_allowed),
        "input_file_id": str(input_save.get("file_id") or state.get("source_file_id") or state.get("video_file_id") or ""),
        "input_file_saved": bool(input_save.get("file_saved")),
        "input_file_exists": bool(input_save.get("exists")),
        "input_file_size": int(input_save.get("size") or 0),
        "duration_seconds": int(input_save.get("duration") or _safe_int(state.get("video_duration") or state.get("source_duration"), 0)),
    }

def video_dubbing_product_gate_allows_pipeline(access: dict | None, gate_matrix: dict | None) -> bool:
    access = dict(access or {})
    gate_matrix = dict(gate_matrix or {})
    return bool(
        access.get("allowed")
        and gate_matrix.get("access_allowed", access.get("allowed"))
        and gate_matrix.get("product_route_allowed")
        and gate_matrix.get("product_config_ready")
        and gate_matrix.get("media_prerequisites_ready", True)
        and gate_matrix.get("input_file_saved")
        and gate_matrix.get("input_file_exists")
        and int(gate_matrix.get("input_file_size") or 0) > 0
    )

def video_dubbing_pipeline_blocker(
    *,
    input_save: dict | None = None,
    gate_matrix: dict | None = None,
    detail: str = "",
    pipeline_attempted: bool = False,
) -> str:
    input_save = dict(input_save or {})
    matrix = dict(gate_matrix or {})
    normalized = str(detail or "").strip().lower()
    if (
        str(input_save.get("input_save_blocker") or "") == "large_telegram_download_unsupported"
        or input_save.get("telegram_download_limit_hit")
        or subdub_telegram_file_too_big(normalized)
    ):
        return "large_telegram_download_unsupported"
    if "telegram_download_failed" in normalized:
        return "telegram_download_failed"
    if normalized.startswith("audio_extract_failed") or normalized.startswith("audio_chunk_extract_failed"):
        return "audio_extract_failed"
    if normalized in {"audio_extract_unavailable", "audio_chunk_extract_unavailable"}:
        return "ffmpeg_missing"
    if not (
        input_save.get("file_saved")
        and input_save.get("exists")
        and int(input_save.get("size") or 0) > 0
        and str(input_save.get("path") or "")
    ):
        return "file_not_saved"
    if not matrix.get("product_route_allowed"):
        return "product_route_not_allowed"
    keyword_blockers = (
        ("duplicate", "duplicate_lock"),
        ("unsupported", "unsupported_input"),
        ("long_media_no_speech", "long_media_no_speech"),
        ("empty_transcript", "no_speech_detected"),
        ("no_speech", "no_speech_detected"),
        ("source_audio_missing", "source_audio_missing"),
        ("audio_stream_missing", "final_audio_missing"),
        ("ffmpeg", "ffmpeg_missing"),
        ("asr", "asr_missing"),
        ("transcri", "asr_missing"),
        ("translation", "translation_missing"),
        ("tts", "tts_missing"),
        ("voice", "tts_missing"),
        ("provider", "provider_key_missing"),
        ("api_key", "provider_key_missing"),
    )
    for keyword, blocker in keyword_blockers:
        if keyword in normalized:
            return blocker
    blockers = list(matrix.get("gate_blockers") or [])
    if blockers:
        return str(blockers[0])
    if not pipeline_attempted:
        return "product_route_not_allowed"
    return ""

def video_dubbing_product_public_failure_text(mode: str, state: dict | None = None, gate_matrix: dict | None = None, lang: str = "vi") -> str:
    mode = normalize_video_translate_mode(mode)
    state = dict(state or {})
    technical_missing = set(str(item) for item in (dict(gate_matrix or {}).get("technical_missing") or []))
    if technical_missing & {"ffmpeg", "ffprobe"}:
        return subdub_media_runtime_unavailable_text(lang)
    if "asr" in technical_missing and video_dubbing_mode_needs_asr_provider(mode, state):
        return video_dubbing_asr_missing_guard_text(lang)
    if mode == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB:
        return subtitle_plus_dub_clean_failure_text(lang)
    return video_dubbing_flow_failure_text(mode, lang)

