def video_editor_source_from_update(update: Update) -> dict:
    message = update.message
    if not message:
        return {}
    telegram_video = getattr(message, "video", None)
    media = telegram_video or getattr(message, "document", None)
    if not media:
        return {}
    mime_type = str(getattr(media, "mime_type", "") or "video/mp4")
    file_name = str(getattr(media, "file_name", "") or "video.mp4")
    if getattr(message, "document", None) and not (mime_type.startswith("video/") or file_name.lower().endswith((".mp4", ".mov", ".mkv", ".webm"))):
        return {}
    source_file_id = str(getattr(media, "file_id", "") or "")[:240]
    source_file_unique_id = str(getattr(media, "file_unique_id", "") or "")[:240]
    return {
        "source_file_id": source_file_id,
        "source_video_id": source_file_id,
        # Telegram file_unique_id is opaque; it is not a content digest.
        "source_file_unique_id": source_file_unique_id,
        "source_video_hash": "",
        "source_file_name": file_name[:180],
        "source_mime_type": mime_type[:120],
        "source_file_size": safe_int(getattr(media, "file_size", 0), 0),
        "source_duration": safe_int(getattr(media, "duration", 0), 0),
        "source_origin": "telegram_video" if telegram_video else "telegram_document",
        "source_width": safe_int(getattr(media, "width", 0), 0),
        "source_height": safe_int(getattr(media, "height", 0), 0),
    }


def video_editor_aux_source_from_update(update: Update, kind: str) -> dict:
    message = update.message
    if not message:
        return {}
    document = getattr(message, "document", None)
    if kind == "logo":
        media = (message.photo[-1] if getattr(message, "photo", None) else document)
        if not media:
            return {}
        mime_type = str(getattr(media, "mime_type", "") or ("image/jpeg" if getattr(message, "photo", None) else ""))
        file_name = str(getattr(media, "file_name", "") or "logo.jpg")
        if not file_name.lower().endswith((".png", ".jpg", ".jpeg", ".webp")):
            return {}
    elif kind == "audio":
        media = getattr(message, "audio", None) or getattr(message, "voice", None) or document
        if not media:
            return {}
        mime_type = str(getattr(media, "mime_type", "") or "audio/mpeg")
        file_name = str(getattr(media, "file_name", "") or "audio.mp3")
        if not file_name.lower().endswith((".mp3", ".m4a", ".aac", ".wav", ".ogg", ".flac", ".opus")):
            return {}
    elif kind == "srt":
        media = document
        if not media:
            return {}
        mime_type = str(getattr(media, "mime_type", "") or "application/x-subrip")
        file_name = str(getattr(media, "file_name", "") or "subtitle.srt")
        if not file_name.lower().endswith(".srt"):
            return {}
    else:
        return {}
    return {
        "file_id": str(getattr(media, "file_id", "") or "")[:240],
        "file_name": video_local_validation.safe_display_filename(file_name, "asset"),
        "mime_type": mime_type[:120],
        "file_size": safe_int(getattr(media, "file_size", 0), 0),
    }


