async def shopaikey_usage_monitor_loop(bot_client):
    await asyncio.sleep(20)
    interval_seconds = max(300, int(SHOPAIKEY_USAGE_CHECK_INTERVAL_MINUTES or 60) * 60)
    while True:
        try:
            if SHOPAIKEY_USAGE_CHECK_ENABLED and SHOPAIKEY_API_KEY:
                result = await get_shopaikey_usage()
                usage = result.get("usage") or {}
                detail = (
                    f"http={result.get('http_status')}; latency_ms={result.get('latency_ms')}; "
                    f"remaining_percent={usage.get('remaining_percent', '-')}; error_class={result.get('error_class') or '-'}"
                )
                save_tool_test_result("shopaikey_usage", result.get("status") or "FAIL", detail, "monitor")
                if result.get("status") == "PASS":
                    save_shopaikey_usage_snapshot(usage, "monitor")
                    await maybe_alert_shopaikey_low_quota(bot_client, usage, "monitor")
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.warning(f"ShopAIKey usage monitor skipped: {type(e).__name__}")
        await asyncio.sleep(interval_seconds)
TELEGRAM_STARTUP_ERROR = ""


def _resolve_optional_telegram_startup_hook(name: str):
    hook = globals().get(str(name or "").strip())
    return hook if callable(hook) else None

async def run_polling_guarded():
    try:
        await tg_app.updater.start_polling(
            allowed_updates=Update.ALL_TYPES,
            drop_pending_updates=True,
        )
    except Exception as e:
        logger.error(f"Telegram polling không chạy được: {e}")
        if ADMIN_ID:
            try:
                await tg_app.bot.send_message(
                    chat_id=ADMIN_ID,
                    text=(
                        "🚨 <b>TOAN AAS POLLING BỊ CHẶN</b>\n\n"
                        "Có thể đang có process/deployment khác dùng cùng <code>TELEGRAM_TOKEN</code> "
                        "hoặc Railway chưa cấu hình <code>PUBLIC_BASE_URL</code> để bật webhook takeover.\n\n"
                        f"• Build: <code>{APP_BUILD}</code>\n"
                        f"• Mode: <code>{html.escape(TELEGRAM_UPDATE_MODE)}</code>\n"
                        "• Cách xử lý: set <code>PUBLIC_BASE_URL</code> đúng domain Railway rồi redeploy."
                    ),
                    parse_mode="HTML",
                )
            except Exception:
                pass

@asynccontextmanager
async def lifespan(app: FastAPI):
    global tg_app, tg_polling_task, tg_webhook_watchdog_task, tg_auto_backup_task, tg_memory_reminder_task, tg_shopaikey_usage_task, tg_payos_expiry_task, tg_broadcast_lite_worker_task, tg_product_video_watchdog_task, tg_frame_video_watchdog_task, tg_video_trend_catalog_task, ACTIVE_TELEGRAM_UPDATE_MODE, ACTIVE_TELEGRAM_WEBHOOK_URL, TELEGRAM_STARTUP_ERROR, ACTIVE_TELEGRAM_BOT_ID, ACTIVE_TELEGRAM_BOT_USERNAME, TELEGRAM_HANDLERS_REGISTERED, PRODUCT_VIDEO_CONFIRM_HANDLER_DIAGNOSTICS
    init_db()
    try:
        run_storage_cleanup_auto_once()
    except Exception as exc:
        logger.warning("storage cleanup auto skipped: %s", type(exc).__name__)
    storage_weekly_task: asyncio.Task | None = None
    token_summary = telegram_token_runtime_summary()
    db_summary = runtime_db_status()
    data_summary = data_persistence_status_payload(include_counts=False)
    logger.info(
        "TOAN AAS STARTUP | build=%s | deploy=%s | public_base_url=%s | public_base_url_source=%s | telegram_update_mode=%s | force_polling=%s | token=%s len=%s masked=%s | db=%s | data_mode=%s | data_path=%s | data_exists=%s | data_loss_risk=%s | startup_backup=%s",
        APP_BUILD,
        APP_DEPLOY_ID or "-",
        PUBLIC_BASE_URL or "missing",
        PUBLIC_BASE_URL_SOURCE or "missing",
        TELEGRAM_UPDATE_MODE,
        str(TELEGRAM_FORCE_POLLING).lower(),
        "configured" if token_summary["configured"] else "missing",
        token_summary["len"],
        token_summary["masked"] or "-",
        db_summary.get("status") or "FAIL",
        data_summary.get("mode") or "-",
        data_summary.get("db_path") or "-",
        "yes" if data_summary.get("db_exists") else "no",
        "yes" if data_summary.get("data_loss_risk") else "no",
        data_summary.get("backup_last_status") or "-",
    )
    subdub_runtime = subdub_runtime_status_payload()
    logger.info(
        "SUBDUB_RUNTIME_READY | build=%s | ffmpeg=%s | ffprobe=%s | ass=%s | unicode_font=%s | ready=%s",
        APP_BUILD,
        "pass" if subdub_runtime.get("ffmpeg_version_probe_ok") else "fail",
        "pass" if subdub_runtime.get("ffprobe_version_probe_ok") else "fail",
        "pass" if subdub_runtime.get("ass_filter_ready") else "fail",
        "pass" if subdub_runtime.get("unicode_font_ready") else "fail",
        "yes" if subdub_runtime.get("media_preprocessing_ready") else "no",
    )
    if not TELEGRAM_TOKEN:
        TELEGRAM_STARTUP_ERROR = "TELEGRAM_TOKEN chưa được set"
        logger.error("TELEGRAM_TOKEN: missing")
        yield
        return
    TELEGRAM_STARTUP_ERROR = ""

    try:
        tg_app = build_telegram_application()
    except Exception as e:
        TELEGRAM_STARTUP_ERROR = str(e)
        ACTIVE_TELEGRAM_UPDATE_MODE = "telegram_startup_error"
        ACTIVE_TELEGRAM_WEBHOOK_URL = ""
        logger.exception(f"Telegram builder lỗi nhưng FastAPI vẫn chạy để /runtime chẩn đoán: {e}")
        yield
        return

    # Group -11 runs before every other handler, including the safe-mode
    # guards, so a flood is dropped before it can reach job creation.
    tg_app.add_handler(MessageHandler(filters.ALL, dispatch_throttle_message_guard), group=-11)
    tg_app.add_handler(CallbackQueryHandler(dispatch_throttle_callback_guard), group=-11)
    tg_app.add_handler(MessageHandler(filters.ALL, safe_mode_message_guard), group=-10)
    tg_app.add_handler(CallbackQueryHandler(safe_mode_callback_guard), group=-10)
    tg_app.add_handler(CallbackQueryHandler(video_public_callback_dedupe_guard), group=-9)
    tg_app.add_handler(
        MessageHandler(
            filters.PHOTO | filters.VOICE | filters.AUDIO | filters.VIDEO | filters.Document.ALL,
            video_public_media_dedupe_guard,
        ),
        group=-9,
    )
    tg_app.add_handler(BusinessConnectionHandler(handle_cskh_business_connection))
    tg_app.add_handler(BusinessMessagesDeletedHandler(handle_cskh_deleted_business_messages))
    tg_app.add_handler(MessageHandler(filters.UpdateType.BUSINESS_MESSAGE, handle_cskh_business_message))
    tg_app.add_handler(MessageHandler(filters.UpdateType.EDITED_BUSINESS_MESSAGE, handle_cskh_edited_business_message))
    tg_app.add_handler(CommandHandler("ping",        cmd_ping))
    tg_app.add_handler(CommandHandler("status",      cmd_status))
    tg_app.add_handler(CommandHandler("support",     cmd_support))
    tg_app.add_handler(CommandHandler("cskh",        cmd_cskh))
