@fastapi_app.get("/api/v1/worker/assets/{asset_id}")
async def api_worker_asset_download(asset_id: str, request: Request):
    verify_remote_worker_api_access(request)
    safe_asset_id = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(asset_id or ""))[:120]
    if not safe_asset_id:
        raise HTTPException(status_code=400, detail="asset_id required")
    asset_root = os.path.join(os.path.dirname(__file__), "files", "worker_assets")
    candidate = os.path.abspath(os.path.join(asset_root, safe_asset_id))
    if not candidate.startswith(os.path.abspath(asset_root)) or not os.path.exists(candidate) or not os.path.isfile(candidate):
        raise HTTPException(status_code=404, detail="asset_not_found")
    return FileResponse(candidate, filename=os.path.basename(candidate))


PRODUCT_VIDEO_SCENE_IMAGE_INPUT_TYPES = frozenset({
    "storyboard_prompt",
    "storyboard_to_video",
    "video_ai_image",
    "image_to_video",
})


@fastapi_app.get("/api/v1/worker/jobs/{job_id}/storyboard-image/{scene_index}/{slot}")
async def api_worker_storyboard_scene_image(job_id: int, scene_index: int, slot: str, request: Request):
    """Transfer one confirmed storyboard image to its authenticated worker."""

    verify_remote_worker_api_access(request)
    image_slot = str(slot or "start").strip().lower()
    if image_slot not in {"start", "end"}:
        raise HTTPException(status_code=400, detail="storyboard_image_slot_invalid")
    wanted_scene = safe_int(scene_index, 0)
    if wanted_scene <= 0:
        raise HTTPException(status_code=400, detail="storyboard_scene_index_invalid")
    conn = db_connect()
    try:
        job = video_project_queue.get_video_render_job(conn, safe_int(job_id, 0))
        hydrated = video_project_queue.hydrate_video_job_payload(conn, job)
    finally:
        conn.close()
    if not hydrated:
        raise HTTPException(status_code=404, detail="job_not_found")
    if str(hydrated.get("status") or "").strip().lower() not in {"queued", "processing", "in_progress", "running", "claimed"}:
        raise HTTPException(status_code=409, detail="storyboard_transfer_requires_active_job")
    project = dict(hydrated.get("project") or {})
    try:
        asset_pack = json.loads(str(project.get("asset_pack_json") or "{}"))
    except Exception:
        asset_pack = {}
    if not isinstance(asset_pack, dict):
        asset_pack = {}
    product_type = str(
        asset_pack.get("product_type")
        or asset_pack.get("video_product_type")
        or project.get("profile_id")
        or ""
    ).strip()
    if product_type not in PRODUCT_VIDEO_SCENE_IMAGE_INPUT_TYPES:
        raise HTTPException(status_code=404, detail="storyboard_image_not_found")
    try:
        scene_cards = json.loads(str(project.get("scene_cards_json") or "[]"))
    except Exception:
        scene_cards = []
    if not isinstance(scene_cards, list):
        scene_cards = []
    if not scene_cards:
        scene_cards = [dict(item) for item in hydrated.get("scenes") or [] if isinstance(item, dict)]
    selected = next(
        (
            dict(card)
            for fallback_index, card in enumerate(scene_cards, start=1)
            if isinstance(card, dict)
            and safe_int(card.get("scene_index") or card.get("scene_id"), fallback_index) == wanted_scene
        ),
        {},
    )
    slot_record = selected.get(f"{image_slot}_image")
    if not isinstance(slot_record, dict):
        slot_record = {}
    start_image_file_id = selected.get("start_image_file_id") if image_slot == "start" else ""
    end_image_file_id = selected.get("end_image_file_id") if image_slot == "end" else ""
    file_id = str(
        start_image_file_id
        or end_image_file_id
        or slot_record.get("file_id")
        or (selected.get("image_file_id") if image_slot == "start" else "")
        or ""
    ).strip()
    if not file_id:
        raise HTTPException(status_code=404, detail=f"storyboard_{image_slot}_image_file_id_missing")
    if tg_app is None or getattr(tg_app, "bot", None) is None:
        raise HTTPException(status_code=503, detail="telegram_storyboard_transfer_unavailable")
    max_bytes = max(1, safe_int(os.getenv("STORYBOARD_IMAGE_MAX_BYTES"), 10 * 1024 * 1024))
    try:
        telegram_file = await tg_app.bot.get_file(file_id)
        declared_size = safe_int(getattr(telegram_file, "file_size", 0), 0)
        if declared_size and declared_size > max_bytes:
            raise HTTPException(status_code=413, detail="storyboard_image_too_large")
        content = bytes(await telegram_file.download_as_bytearray())
    except HTTPException:
        raise
    except Exception as exc:
        logger.warning(
            "storyboard_image_transfer_failed | job_id=%s | scene=%s | slot=%s | error=%s",
            job_id,
            wanted_scene,
            image_slot,
            type(exc).__name__,
        )
        raise HTTPException(status_code=502, detail="storyboard_image_download_failed") from exc
    if not content:
        raise HTTPException(status_code=502, detail="storyboard_image_empty")
    if len(content) > max_bytes:
        raise HTTPException(status_code=413, detail="storyboard_image_too_large")
    filename = f"storyboard-scene-{wanted_scene}-{image_slot}.png"
    return Response(
        content=content,
        media_type="image/png",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@fastapi_app.get("/api/v1/worker/jobs/{job_id}/logo-material")
async def api_worker_product_video_logo_material(job_id: int, request: Request):
    """Transfer one confirmed logo image to its authenticated product worker."""

    verify_remote_worker_api_access(request)
    conn = db_connect()
    try:
        job = video_project_queue.get_video_render_job(conn, safe_int(job_id, 0))
        hydrated = video_project_queue.hydrate_video_job_payload(conn, job)
    finally:
        conn.close()
    if not hydrated:
        raise HTTPException(status_code=404, detail="job_not_found")
    if str(hydrated.get("status") or "").strip().lower() not in {
        "queued", "processing", "in_progress", "running", "claimed",
    }:
        raise HTTPException(status_code=409, detail="logo_transfer_requires_active_job")
    project = dict(hydrated.get("project") or {})
    try:
        asset_pack = json.loads(str(project.get("asset_pack_json") or "{}"))
    except Exception:
        asset_pack = {}
    if not isinstance(asset_pack, dict) or str(asset_pack.get("source") or "") != "product_video":
        raise HTTPException(status_code=404, detail="product_video_logo_not_found")
    material = dict(asset_pack.get("logo_material") or {})
    file_id = str(material.get("logo_file_id") or "").strip()
    if not material.get("logo_enabled") or not file_id:
        raise HTTPException(status_code=404, detail="product_video_logo_file_id_missing")
    if tg_app is None or getattr(tg_app, "bot", None) is None:
        raise HTTPException(status_code=503, detail="telegram_logo_transfer_unavailable")
    max_bytes = max(1, safe_int(os.getenv("PRODUCT_VIDEO_LOGO_MAX_BYTES"), 10 * 1024 * 1024))
    try:
        telegram_file = await tg_app.bot.get_file(file_id)
        declared_size = safe_int(getattr(telegram_file, "file_size", 0), 0)
        if declared_size and declared_size > max_bytes:
            raise HTTPException(status_code=413, detail="product_video_logo_too_large")
        content = bytes(await telegram_file.download_as_bytearray())
    except HTTPException:
        raise
    except Exception as exc:
        logger.warning(
            "product_video_logo_transfer_failed | job_id=%s | error=%s",
            job_id,
            type(exc).__name__,
        )
        raise HTTPException(status_code=502, detail="product_video_logo_download_failed") from exc
    if not content:
        raise HTTPException(status_code=502, detail="product_video_logo_empty")
    if len(content) > max_bytes:
        raise HTTPException(status_code=413, detail="product_video_logo_too_large")
    return Response(
        content=content,
        media_type="image/png",
        headers={"Content-Disposition": 'attachment; filename="product-video-logo.png"'},
    )


@fastapi_app.get("/api/v1/worker/jobs/{job_id}/source-video")
async def api_worker_selfshot3_source_video(job_id: int, request: Request):
    """Transfer a confirmed self-shot source to its authenticated worker only."""

    verify_remote_worker_api_access(request)
    conn = db_connect()
    try:
        job = video_project_queue.get_video_render_job(conn, safe_int(job_id, 0))
        hydrated = video_project_queue.hydrate_video_job_payload(conn, job)
    finally:
        conn.close()
    if not hydrated:
        raise HTTPException(status_code=404, detail="job_not_found")
    job_status = str(hydrated.get("status") or "").strip().lower()
    if job_status not in {"queued", "processing", "in_progress", "running", "claimed"}:
        raise HTTPException(status_code=409, detail="source_transfer_requires_active_job")
    project = dict(hydrated.get("project") or {})
    try:
        asset_pack = json.loads(str(project.get("asset_pack_json") or "{}"))
    except Exception:
        asset_pack = {}
    if not isinstance(asset_pack, dict):
        asset_pack = {}
    product_type = str(
        asset_pack.get("product_type")
        or asset_pack.get("job_type")
        or project.get("profile_id")
        or ""
    ).strip()
    allowed_selfshot_products = {
        video_selfshot2.JOB_TYPE,
        video_selfshot3.JOB_TYPE,
    }
    if product_type not in allowed_selfshot_products:
        raise HTTPException(status_code=404, detail="selfshot_source_not_found")
    source_video = dict(asset_pack.get("source_video") or asset_pack.get("source_asset") or {})
    file_id = str(
        asset_pack.get("source_file_id")
        or asset_pack.get("source_video_id")
        or source_video.get("file_id")
        or ""
    ).strip()
    if not file_id:
        raise HTTPException(status_code=404, detail="source_file_id_missing")
    if tg_app is None or getattr(tg_app, "bot", None) is None:
        raise HTTPException(status_code=503, detail="telegram_source_transfer_unavailable")
    default_source_max = (
        video_local_validation.MAX_UPLOAD_BYTES
        if product_type == video_selfshot2.JOB_TYPE
        else 20 * 1024 * 1024
    )
    max_bytes = max(
        1,
        safe_int(
            os.getenv("SELFSHOT_SOURCE_MAX_BYTES")
            or (
                os.getenv("SELFSHOT2_SOURCE_MAX_BYTES")
                if product_type == video_selfshot2.JOB_TYPE
                else os.getenv("SELFSHOT3_SOURCE_MAX_BYTES")
            ),
            default_source_max,
        ),
    )
    try:
        telegram_file = await tg_app.bot.get_file(file_id)
        declared_size = safe_int(getattr(telegram_file, "file_size", 0), 0)
        if declared_size and declared_size > max_bytes:
            raise HTTPException(status_code=413, detail="source_video_too_large")
        content = bytes(await telegram_file.download_as_bytearray())
    except HTTPException:
        raise
    except Exception as exc:
        logger.warning(
            "selfshot_source_transfer_failed | job_id=%s | product=%s | error=%s",
            job_id,
            product_type,
            type(exc).__name__,
        )
        raise HTTPException(status_code=502, detail="source_video_download_failed") from exc
    if not content:
        raise HTTPException(status_code=502, detail="source_video_empty")
    if len(content) > max_bytes:
        raise HTTPException(status_code=413, detail="source_video_too_large")
    default_filename = "selfshot2-source.mp4" if product_type == video_selfshot2.JOB_TYPE else "selfshot3-source.mp4"
    filename = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(source_video.get("file_name") or default_filename))[:120]
    if not filename.lower().endswith((".mp4", ".mov", ".mkv", ".webm")):
        filename += ".mp4"
    return Response(
        content=content,
        media_type=str(source_video.get("mime_type") or "video/mp4"),
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )

